    return s;

}

static int send_sub_rect(VncState *vs, int x, int y, int w, int h)

{

    VncPalette *palette = &color_count_palette;

    uint32_t bg = 0, fg = 0;

    int colors;

    int ret = 0;

#ifdef CONFIG_VNC_JPEG

    bool force_jpeg = false;

    bool allow_jpeg = true;

#endif



    vnc_framebuffer_update(vs, x, y, w, h, vs->tight.type);



    vnc_tight_start(vs);

    vnc_raw_send_framebuffer_update(vs, x, y, w, h);

    vnc_tight_stop(vs);



#ifdef CONFIG_VNC_JPEG

    if (!vs->vd->non_adaptive && vs->tight.quality != (uint8_t)-1) {

        double freq = vnc_update_freq(vs, x, y, w, h);



        if (freq < tight_jpeg_conf[vs->tight.quality].jpeg_freq_min) {

            allow_jpeg = false;

        }

        if (freq >= tight_jpeg_conf[vs->tight.quality].jpeg_freq_threshold) {

            force_jpeg = true;

            vnc_sent_lossy_rect(vs, x, y, w, h);

        }

    }

#endif



    colors = tight_fill_palette(vs, x, y, w * h, &bg, &fg, palette);



#ifdef CONFIG_VNC_JPEG

    if (allow_jpeg && vs->tight.quality != (uint8_t)-1) {

        ret = send_sub_rect_jpeg(vs, x, y, w, h, bg, fg, colors, palette,

                                 force_jpeg);

    } else {

        ret = send_sub_rect_nojpeg(vs, x, y, w, h, bg, fg, colors, palette);

    }

#else

    ret = send_sub_rect_nojpeg(vs, x, y, w, h, bg, fg, colors, palette);

#endif



    return ret;

}

static ExitStatus translate_one(DisasContext *ctx, uint32_t insn)

{

    uint32_t palcode;

    int32_t disp21, disp16;

#ifndef CONFIG_USER_ONLY

    int32_t disp12;

#endif

    uint16_t fn11;

    uint8_t opc, ra, rb, rc, fpfn, fn7, islit, real_islit;

    uint8_t lit;

    ExitStatus ret;



    /* Decode all instruction fields */

    opc = insn >> 26;

    ra = (insn >> 21) & 0x1F;

    rb = (insn >> 16) & 0x1F;

    rc = insn & 0x1F;

    real_islit = islit = (insn >> 12) & 1;

    if (rb == 31 && !islit) {

        islit = 1;

        lit = 0;

    } else

        lit = (insn >> 13) & 0xFF;

    palcode = insn & 0x03FFFFFF;

    disp21 = ((int32_t)((insn & 0x001FFFFF) << 11)) >> 11;

    disp16 = (int16_t)(insn & 0x0000FFFF);

#ifndef CONFIG_USER_ONLY

    disp12 = (int32_t)((insn & 0x00000FFF) << 20) >> 20;

#endif

    fn11 = (insn >> 5) & 0x000007FF;

    fpfn = fn11 & 0x3F;

    fn7 = (insn >> 5) & 0x0000007F;

    LOG_DISAS("opc %02x ra %2d rb %2d rc %2d disp16 %6d\n",

              opc, ra, rb, rc, disp16);



    ret = NO_EXIT;

    switch (opc) {

    case 0x00:

        /* CALL_PAL */

        ret = gen_call_pal(ctx, palcode);

        break;

    case 0x01:

        /* OPC01 */

        goto invalid_opc;

    case 0x02:

        /* OPC02 */

        goto invalid_opc;

    case 0x03:

        /* OPC03 */

        goto invalid_opc;

    case 0x04:

        /* OPC04 */

        goto invalid_opc;

    case 0x05:

        /* OPC05 */

        goto invalid_opc;

    case 0x06:

        /* OPC06 */

        goto invalid_opc;

    case 0x07:

        /* OPC07 */

        goto invalid_opc;

    case 0x08:

        /* LDA */

        if (likely(ra != 31)) {

            if (rb != 31) {

                tcg_gen_addi_i64(cpu_ir[ra], cpu_ir[rb], disp16);

            } else {

                tcg_gen_movi_i64(cpu_ir[ra], disp16);

            }

        }

        break;

    case 0x09:

        /* LDAH */

        if (likely(ra != 31)) {

            if (rb != 31) {

                tcg_gen_addi_i64(cpu_ir[ra], cpu_ir[rb], disp16 << 16);

            } else {

                tcg_gen_movi_i64(cpu_ir[ra], disp16 << 16);

            }

        }

        break;

    case 0x0A:

        /* LDBU */

        if (ctx->tb->flags & TB_FLAGS_AMASK_BWX) {

            gen_load_mem(ctx, &tcg_gen_qemu_ld8u, ra, rb, disp16, 0, 0);

            break;

        }

        goto invalid_opc;

    case 0x0B:

        /* LDQ_U */

        gen_load_mem(ctx, &tcg_gen_qemu_ld64, ra, rb, disp16, 0, 1);

        break;

    case 0x0C:

        /* LDWU */

        if (ctx->tb->flags & TB_FLAGS_AMASK_BWX) {

            gen_load_mem(ctx, &tcg_gen_qemu_ld16u, ra, rb, disp16, 0, 0);

            break;

        }

        goto invalid_opc;

    case 0x0D:

        /* STW */

        gen_store_mem(ctx, &tcg_gen_qemu_st16, ra, rb, disp16, 0, 0);

        break;

    case 0x0E:

        /* STB */

        gen_store_mem(ctx, &tcg_gen_qemu_st8, ra, rb, disp16, 0, 0);

        break;

    case 0x0F:

        /* STQ_U */

        gen_store_mem(ctx, &tcg_gen_qemu_st64, ra, rb, disp16, 0, 1);

        break;

    case 0x10:

        switch (fn7) {

        case 0x00:

            /* ADDL */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    if (islit) {

                        tcg_gen_addi_i64(cpu_ir[rc], cpu_ir[ra], lit);

                        tcg_gen_ext32s_i64(cpu_ir[rc], cpu_ir[rc]);

                    } else {

                        tcg_gen_add_i64(cpu_ir[rc], cpu_ir[ra], cpu_ir[rb]);

                        tcg_gen_ext32s_i64(cpu_ir[rc], cpu_ir[rc]);

                    }

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], lit);

                    } else {

                        tcg_gen_ext32s_i64(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

            }

            break;

        case 0x02:

            /* S4ADDL */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    TCGv tmp = tcg_temp_new();

                    tcg_gen_shli_i64(tmp, cpu_ir[ra], 2);

                    if (islit) {

                        tcg_gen_addi_i64(tmp, tmp, lit);

                    } else {

                        tcg_gen_add_i64(tmp, tmp, cpu_ir[rb]);

                    }

                    tcg_gen_ext32s_i64(cpu_ir[rc], tmp);

                    tcg_temp_free(tmp);

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], lit);

                    } else {

                        tcg_gen_ext32s_i64(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

            }

            break;

        case 0x09:

            /* SUBL */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    if (islit) {

                        tcg_gen_subi_i64(cpu_ir[rc], cpu_ir[ra], lit);

                    } else {

                        tcg_gen_sub_i64(cpu_ir[rc], cpu_ir[ra], cpu_ir[rb]);

                    }

                    tcg_gen_ext32s_i64(cpu_ir[rc], cpu_ir[rc]);

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], -lit);

                    } else {

                        tcg_gen_neg_i64(cpu_ir[rc], cpu_ir[rb]);

                        tcg_gen_ext32s_i64(cpu_ir[rc], cpu_ir[rc]);

                    }

                }

            }

            break;

        case 0x0B:

            /* S4SUBL */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    TCGv tmp = tcg_temp_new();

                    tcg_gen_shli_i64(tmp, cpu_ir[ra], 2);

                    if (islit) {

                        tcg_gen_subi_i64(tmp, tmp, lit);

                    } else {

                        tcg_gen_sub_i64(tmp, tmp, cpu_ir[rb]);

                    }

                    tcg_gen_ext32s_i64(cpu_ir[rc], tmp);

                    tcg_temp_free(tmp);

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], -lit);

                    } else {

                        tcg_gen_neg_i64(cpu_ir[rc], cpu_ir[rb]);

                        tcg_gen_ext32s_i64(cpu_ir[rc], cpu_ir[rc]);

                    }

                }

            }

            break;

        case 0x0F:

            /* CMPBGE */

            gen_cmpbge(ra, rb, rc, islit, lit);

            break;

        case 0x12:

            /* S8ADDL */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    TCGv tmp = tcg_temp_new();

                    tcg_gen_shli_i64(tmp, cpu_ir[ra], 3);

                    if (islit) {

                        tcg_gen_addi_i64(tmp, tmp, lit);

                    } else {

                        tcg_gen_add_i64(tmp, tmp, cpu_ir[rb]);

                    }

                    tcg_gen_ext32s_i64(cpu_ir[rc], tmp);

                    tcg_temp_free(tmp);

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], lit);

                    } else {

                        tcg_gen_ext32s_i64(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

            }

            break;

        case 0x1B:

            /* S8SUBL */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    TCGv tmp = tcg_temp_new();

                    tcg_gen_shli_i64(tmp, cpu_ir[ra], 3);

                    if (islit) {

                        tcg_gen_subi_i64(tmp, tmp, lit);

                    } else {

                       tcg_gen_sub_i64(tmp, tmp, cpu_ir[rb]);

                    }

                    tcg_gen_ext32s_i64(cpu_ir[rc], tmp);

                    tcg_temp_free(tmp);

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], -lit);

                    } else {

                        tcg_gen_neg_i64(cpu_ir[rc], cpu_ir[rb]);

                        tcg_gen_ext32s_i64(cpu_ir[rc], cpu_ir[rc]);

                    }

                }

            }

            break;

        case 0x1D:

            /* CMPULT */

            gen_cmp(TCG_COND_LTU, ra, rb, rc, islit, lit);

            break;

        case 0x20:

            /* ADDQ */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    if (islit) {

                        tcg_gen_addi_i64(cpu_ir[rc], cpu_ir[ra], lit);

                    } else {

                        tcg_gen_add_i64(cpu_ir[rc], cpu_ir[ra], cpu_ir[rb]);

                    }

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], lit);

                    } else {

                        tcg_gen_mov_i64(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

            }

            break;

        case 0x22:

            /* S4ADDQ */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    TCGv tmp = tcg_temp_new();

                    tcg_gen_shli_i64(tmp, cpu_ir[ra], 2);

                    if (islit) {

                        tcg_gen_addi_i64(cpu_ir[rc], tmp, lit);

                    } else {

                        tcg_gen_add_i64(cpu_ir[rc], tmp, cpu_ir[rb]);

                    }

                    tcg_temp_free(tmp);

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], lit);

                    } else {

                        tcg_gen_mov_i64(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

            }

            break;

        case 0x29:

            /* SUBQ */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    if (islit) {

                        tcg_gen_subi_i64(cpu_ir[rc], cpu_ir[ra], lit);

                    } else {

                        tcg_gen_sub_i64(cpu_ir[rc], cpu_ir[ra], cpu_ir[rb]);

                    }

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], -lit);

                    } else {

                        tcg_gen_neg_i64(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

            }

            break;

        case 0x2B:

            /* S4SUBQ */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    TCGv tmp = tcg_temp_new();

                    tcg_gen_shli_i64(tmp, cpu_ir[ra], 2);

                    if (islit) {

                        tcg_gen_subi_i64(cpu_ir[rc], tmp, lit);

                    } else {

                        tcg_gen_sub_i64(cpu_ir[rc], tmp, cpu_ir[rb]);

                    }

                    tcg_temp_free(tmp);

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], -lit);

                    } else {

                        tcg_gen_neg_i64(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

            }

            break;

        case 0x2D:

            /* CMPEQ */

            gen_cmp(TCG_COND_EQ, ra, rb, rc, islit, lit);

            break;

        case 0x32:

            /* S8ADDQ */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    TCGv tmp = tcg_temp_new();

                    tcg_gen_shli_i64(tmp, cpu_ir[ra], 3);

                    if (islit) {

                        tcg_gen_addi_i64(cpu_ir[rc], tmp, lit);

                    } else {

                        tcg_gen_add_i64(cpu_ir[rc], tmp, cpu_ir[rb]);

                    }

                    tcg_temp_free(tmp);

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], lit);

                    } else {

                        tcg_gen_mov_i64(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

            }

            break;

        case 0x3B:

            /* S8SUBQ */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    TCGv tmp = tcg_temp_new();

                    tcg_gen_shli_i64(tmp, cpu_ir[ra], 3);

                    if (islit) {

                        tcg_gen_subi_i64(cpu_ir[rc], tmp, lit);

                    } else {

                        tcg_gen_sub_i64(cpu_ir[rc], tmp, cpu_ir[rb]);

                    }

                    tcg_temp_free(tmp);

                } else {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], -lit);

                    } else {

                        tcg_gen_neg_i64(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

            }

            break;

        case 0x3D:

            /* CMPULE */

            gen_cmp(TCG_COND_LEU, ra, rb, rc, islit, lit);

            break;

        case 0x40:

            /* ADDL/V */

            gen_addlv(ra, rb, rc, islit, lit);

            break;

        case 0x49:

            /* SUBL/V */

            gen_sublv(ra, rb, rc, islit, lit);

            break;

        case 0x4D:

            /* CMPLT */

            gen_cmp(TCG_COND_LT, ra, rb, rc, islit, lit);

            break;

        case 0x60:

            /* ADDQ/V */

            gen_addqv(ra, rb, rc, islit, lit);

            break;

        case 0x69:

            /* SUBQ/V */

            gen_subqv(ra, rb, rc, islit, lit);

            break;

        case 0x6D:

            /* CMPLE */

            gen_cmp(TCG_COND_LE, ra, rb, rc, islit, lit);

            break;

        default:

            goto invalid_opc;

        }

        break;

    case 0x11:

        switch (fn7) {

        case 0x00:

            /* AND */

            if (likely(rc != 31)) {

                if (ra == 31) {

                    tcg_gen_movi_i64(cpu_ir[rc], 0);

                } else if (islit) {

                    tcg_gen_andi_i64(cpu_ir[rc], cpu_ir[ra], lit);

                } else {

                    tcg_gen_and_i64(cpu_ir[rc], cpu_ir[ra], cpu_ir[rb]);

                }

            }

            break;

        case 0x08:

            /* BIC */

            if (likely(rc != 31)) {

                if (ra != 31) {

                    if (islit) {

