                /* Longword physical access with lock (hw_ldl_l/p) */

                gen_helper_ldl_l_phys(cpu_ir[ra], cpu_env, addr);

                break;

            case 0x3:

                /* Quadword physical access with lock (hw_ldq_l/p) */

                gen_helper_ldq_l_phys(cpu_ir[ra], cpu_env, addr);

                break;

            case 0x4:

                /* Longword virtual PTE fetch (hw_ldl/v) */

                goto invalid_opc;

            case 0x5:

                /* Quadword virtual PTE fetch (hw_ldq/v) */

                goto invalid_opc;

                break;

            case 0x6:

                /* Incpu_ir[ra]id */

                goto invalid_opc;

            case 0x7:

                /* Incpu_ir[ra]id */

                goto invalid_opc;

            case 0x8:

                /* Longword virtual access (hw_ldl) */

                goto invalid_opc;

            case 0x9:

                /* Quadword virtual access (hw_ldq) */

                goto invalid_opc;

            case 0xA:

                /* Longword virtual access with protection check (hw_ldl/w) */

                tcg_gen_qemu_ld_i64(cpu_ir[ra], addr, MMU_KERNEL_IDX, MO_LESL);

                break;

            case 0xB:

                /* Quadword virtual access with protection check (hw_ldq/w) */

                tcg_gen_qemu_ld_i64(cpu_ir[ra], addr, MMU_KERNEL_IDX, MO_LEQ);

                break;

            case 0xC:

                /* Longword virtual access with alt access mode (hw_ldl/a)*/

                goto invalid_opc;

            case 0xD:

                /* Quadword virtual access with alt access mode (hw_ldq/a) */

                goto invalid_opc;

            case 0xE:

                /* Longword virtual access with alternate access mode and

                   protection checks (hw_ldl/wa) */

                tcg_gen_qemu_ld_i64(cpu_ir[ra], addr, MMU_USER_IDX, MO_LESL);

                break;

            case 0xF:

                /* Quadword virtual access with alternate access mode and

                   protection checks (hw_ldq/wa) */

                tcg_gen_qemu_ld_i64(cpu_ir[ra], addr, MMU_USER_IDX, MO_LEQ);

                break;

            }

            tcg_temp_free(addr);

            break;

        }

#endif

        goto invalid_opc;

    case 0x1C:

        switch (fn7) {

        case 0x00:

            /* SEXTB */

            if ((ctx->tb->flags & TB_FLAGS_AMASK_BWX) == 0) {

                goto invalid_opc;

            }

            if (likely(rc != 31)) {

                if (islit) {

                    tcg_gen_movi_i64(cpu_ir[rc], (int64_t)((int8_t)lit));

                } else {

                    tcg_gen_ext8s_i64(cpu_ir[rc], cpu_ir[rb]);

                }

            }

            break;

        case 0x01:

            /* SEXTW */

            if (ctx->tb->flags & TB_FLAGS_AMASK_BWX) {

                if (likely(rc != 31)) {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], (int64_t)((int16_t)lit));

                    } else {

                        tcg_gen_ext16s_i64(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

                break;

            }

            goto invalid_opc;

        case 0x30:

            /* CTPOP */

            if (ctx->tb->flags & TB_FLAGS_AMASK_CIX) {

                if (likely(rc != 31)) {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], ctpop64(lit));

                    } else {

                        gen_helper_ctpop(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

                break;

            }

            goto invalid_opc;

        case 0x31:

            /* PERR */

            if (ctx->tb->flags & TB_FLAGS_AMASK_MVI) {

                gen_perr(ra, rb, rc, islit, lit);

                break;

            }

            goto invalid_opc;

        case 0x32:

            /* CTLZ */

            if (ctx->tb->flags & TB_FLAGS_AMASK_CIX) {

                if (likely(rc != 31)) {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], clz64(lit));

                    } else {

                        gen_helper_ctlz(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

                break;

            }

            goto invalid_opc;

        case 0x33:

            /* CTTZ */

            if (ctx->tb->flags & TB_FLAGS_AMASK_CIX) {

                if (likely(rc != 31)) {

                    if (islit) {

                        tcg_gen_movi_i64(cpu_ir[rc], ctz64(lit));

                    } else {

                        gen_helper_cttz(cpu_ir[rc], cpu_ir[rb]);

                    }

                }

                break;

            }

            goto invalid_opc;

        case 0x34:

            /* UNPKBW */

            if (ctx->tb->flags & TB_FLAGS_AMASK_MVI) {

                if (real_islit || ra != 31) {

                    goto invalid_opc;

                }

                gen_unpkbw(rb, rc);

                break;

            }

            goto invalid_opc;

        case 0x35:

            /* UNPKBL */

            if (ctx->tb->flags & TB_FLAGS_AMASK_MVI) {

                if (real_islit || ra != 31) {

                    goto invalid_opc;

                }

                gen_unpkbl(rb, rc);

                break;

            }

            goto invalid_opc;

        case 0x36:

            /* PKWB */

            if (ctx->tb->flags & TB_FLAGS_AMASK_MVI) {

                if (real_islit || ra != 31) {

                    goto invalid_opc;

                }

                gen_pkwb(rb, rc);

                break;

            }

            goto invalid_opc;

        case 0x37:

            /* PKLB */

            if (ctx->tb->flags & TB_FLAGS_AMASK_MVI) {

                if (real_islit || ra != 31) {

                    goto invalid_opc;

                }

                gen_pklb(rb, rc);

                break;

            }

            goto invalid_opc;

        case 0x38:

            /* MINSB8 */

            if (ctx->tb->flags & TB_FLAGS_AMASK_MVI) {

                gen_minsb8(ra, rb, rc, islit, lit);

                break;

            }

            goto invalid_opc;

        case 0x39:

            /* MINSW4 */

            if (ctx->tb->flags & TB_FLAGS_AMASK_MVI) {

                gen_minsw4(ra, rb, rc, islit, lit);

                break;

            }

            goto invalid_opc;

        case 0x3A:

            /* MINUB8 */

            if (ctx->tb->flags & TB_FLAGS_AMASK_MVI) {

                gen_minub8(ra, rb, rc, islit, lit);

                break;

            }

            goto invalid_opc;

        case 0x3B:

            /* MINUW4 */

            if (ctx->tb->flags & TB_FLAGS_AMASK_MVI) {

                gen_minuw4(ra, rb, rc, islit, lit);

                break;

            }

            goto invalid_opc;

        case 0x3C:

            /* MAXUB8 */

            if (ctx->tb->flags & TB_FLAGS_AMASK_MVI) {

                gen_maxub8(ra, rb, rc, islit, lit);

