#endif

        goto invalid_opc;

    case 0x1F:

        /* HW_ST (PALcode) */

#ifndef CONFIG_USER_ONLY

        if (ctx->tb->flags & TB_FLAGS_PAL_MODE) {

            TCGv addr, val;

            addr = tcg_temp_new();

            if (rb != 31) {

                tcg_gen_addi_i64(addr, cpu_ir[rb], disp12);

