{

    if (!likely(((T1 ^ T2) >> 31) || !((T0 ^ T2) >> 31))) {

        /* Saturate result */

        if (T2 >> 31) {

            T0 = INT32_MIN;

        } else {

            T0 = INT32_MAX;

        }

    }

}

