static void to_json(const QObject *obj, QString *str, int pretty, int indent)

{

    switch (qobject_type(obj)) {

    case QTYPE_QINT: {

        QInt *val = qobject_to_qint(obj);

        char buffer[1024];



        snprintf(buffer, sizeof(buffer), "%" PRId64, qint_get_int(val));

        qstring_append(str, buffer);

        break;

    }

    case QTYPE_QSTRING: {

        QString *val = qobject_to_qstring(obj);

        const char *ptr;



        ptr = qstring_get_str(val);

        qstring_append(str, "\"");

        while (*ptr) {

            if ((ptr[0] & 0xE0) == 0xE0 &&

                (ptr[1] & 0x80) && (ptr[2] & 0x80)) {

                uint16_t wchar;

                char escape[7];



                wchar  = (ptr[0] & 0x0F) << 12;

                wchar |= (ptr[1] & 0x3F) << 6;

                wchar |= (ptr[2] & 0x3F);

                ptr += 2;



                snprintf(escape, sizeof(escape), "\\u%04X", wchar);

                qstring_append(str, escape);

            } else if ((ptr[0] & 0xE0) == 0xC0 && (ptr[1] & 0x80)) {

                uint16_t wchar;

                char escape[7];



                wchar  = (ptr[0] & 0x1F) << 6;

                wchar |= (ptr[1] & 0x3F);

                ptr++;



                snprintf(escape, sizeof(escape), "\\u%04X", wchar);

                qstring_append(str, escape);

            } else switch (ptr[0]) {

                case '\"':

                    qstring_append(str, "\\\"");

                    break;

                case '\\':

                    qstring_append(str, "\\\\");

                    break;

                case '\b':

                    qstring_append(str, "\\b");

                    break;

                case '\f':

                    qstring_append(str, "\\f");

                    break;

                case '\n':

                    qstring_append(str, "\\n");

                    break;

                case '\r':

                    qstring_append(str, "\\r");

                    break;

                case '\t':

                    qstring_append(str, "\\t");

                    break;

                default: {

                    if (ptr[0] <= 0x1F) {

                        char escape[7];

                        snprintf(escape, sizeof(escape), "\\u%04X", ptr[0]);

                        qstring_append(str, escape);

                    } else {

                        char buf[2] = { ptr[0], 0 };

                        qstring_append(str, buf);

                    }

                    break;

                }

                }

            ptr++;

        }

        qstring_append(str, "\"");

        break;

    }

    case QTYPE_QDICT: {

        ToJsonIterState s;

        QDict *val = qobject_to_qdict(obj);



        s.count = 0;

        s.str = str;

        s.indent = indent + 1;

        s.pretty = pretty;

        qstring_append(str, "{");

        qdict_iter(val, to_json_dict_iter, &s);

        if (pretty) {

            int j;

            qstring_append(str, "\n");

            for (j = 0 ; j < indent ; j++)

                qstring_append(str, "    ");

        }

        qstring_append(str, "}");

        break;

    }

    case QTYPE_QLIST: {

        ToJsonIterState s;

        QList *val = qobject_to_qlist(obj);



        s.count = 0;

        s.str = str;

        s.indent = indent + 1;

        s.pretty = pretty;

        qstring_append(str, "[");

        qlist_iter(val, (void *)to_json_list_iter, &s);

        if (pretty) {

            int j;

            qstring_append(str, "\n");

            for (j = 0 ; j < indent ; j++)

                qstring_append(str, "    ");

        }

        qstring_append(str, "]");

        break;

    }

    case QTYPE_QFLOAT: {

        QFloat *val = qobject_to_qfloat(obj);

        char buffer[1024];

        int len;



        len = snprintf(buffer, sizeof(buffer), "%f", qfloat_get_double(val));

        while (len > 0 && buffer[len - 1] == '0') {

            len--;

        }



        if (len && buffer[len - 1] == '.') {

            buffer[len - 1] = 0;

        } else {

            buffer[len] = 0;

        }



        qstring_append(str, buffer);

        break;

    }

    case QTYPE_QBOOL: {

        QBool *val = qobject_to_qbool(obj);



        if (qbool_get_int(val)) {

            qstring_append(str, "true");

        } else {

            qstring_append(str, "false");

        }

        break;

    }

    case QTYPE_QERROR:

        /* XXX: should QError be emitted? */

    case QTYPE_NONE:

        break;

    }

}

static int mux_proc_byte(CharDriverState *chr, MuxDriver *d, int ch)

{

    if (d->term_got_escape) {

        d->term_got_escape = 0;

        if (ch == term_escape_char)

            goto send_char;

        switch(ch) {

        case '?':

        case 'h':

            mux_print_help(chr);

            break;

        case 'x':

            {

                 const char *term =  "QEMU: Terminated\n\r";

                 qemu_chr_fe_write(chr, (uint8_t *)term, strlen(term));

                 exit(0);

                 break;

            }

        case 's':

            blk_commit_all();

            break;

        case 'b':

            qemu_chr_be_event(chr, CHR_EVENT_BREAK);

            break;

        case 'c':

            /* Switch to the next registered device */

            mux_chr_send_event(d, d->focus, CHR_EVENT_MUX_OUT);

            d->focus++;

            if (d->focus >= d->mux_cnt)

                d->focus = 0;

            mux_chr_send_event(d, d->focus, CHR_EVENT_MUX_IN);

            break;

        case 't':

            d->timestamps = !d->timestamps;

            d->timestamps_start = -1;

            d->linestart = 0;

            break;

        }

    } else if (ch == term_escape_char) {

        d->term_got_escape = 1;

    } else {

    send_char:

        return 1;

    }

    return 0;

}

static void win_chr_readfile(CharDriverState *chr)

{

    WinCharState *s = chr->opaque;

    int ret, err;

    uint8_t buf[1024];

    DWORD size;



    ZeroMemory(&s->orecv, sizeof(s->orecv));

    s->orecv.hEvent = s->hrecv;

    ret = ReadFile(s->hcom, buf, s->len, &size, &s->orecv);

    if (!ret) {

        err = GetLastError();

        if (err == ERROR_IO_PENDING) {

            ret = GetOverlappedResult(s->hcom, &s->orecv, &size, TRUE);

        }

    }



    if (size > 0) {

        qemu_chr_read(chr, buf, size);

    }

}

void mips_r4k_init(MachineState *machine)

{

    ram_addr_t ram_size = machine->ram_size;

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = machine->kernel_filename;

    const char *kernel_cmdline = machine->kernel_cmdline;

    const char *initrd_filename = machine->initrd_filename;

    char *filename;

    MemoryRegion *address_space_mem = get_system_memory();

    MemoryRegion *ram = g_new(MemoryRegion, 1);

    MemoryRegion *bios;

    MemoryRegion *iomem = g_new(MemoryRegion, 1);

    MemoryRegion *isa_io = g_new(MemoryRegion, 1);

    MemoryRegion *isa_mem = g_new(MemoryRegion, 1);

    int bios_size;

    MIPSCPU *cpu;

    CPUMIPSState *env;

    ResetData *reset_info;

    int i;

    qemu_irq *i8259;

    ISABus *isa_bus;

    DriveInfo *hd[MAX_IDE_BUS * MAX_IDE_DEVS];

    DriveInfo *dinfo;

    int be;



    /* init CPUs */

    if (cpu_model == NULL) {

#ifdef TARGET_MIPS64

        cpu_model = "R4000";

#else

        cpu_model = "24Kf";

#endif

    }

    cpu = cpu_mips_init(cpu_model);

    if (cpu == NULL) {

        fprintf(stderr, "Unable to find CPU definition\n");

        exit(1);

    }

    env = &cpu->env;



    reset_info = g_malloc0(sizeof(ResetData));

    reset_info->cpu = cpu;

    reset_info->vector = env->active_tc.PC;

    qemu_register_reset(main_cpu_reset, reset_info);



    /* allocate RAM */

    if (ram_size > (256 << 20)) {

        fprintf(stderr,

                "qemu: Too much memory for this machine: %d MB, maximum 256 MB\n",

                ((unsigned int)ram_size / (1 << 20)));

        exit(1);

    }

    memory_region_allocate_system_memory(ram, NULL, "mips_r4k.ram", ram_size);



    memory_region_add_subregion(address_space_mem, 0, ram);



    memory_region_init_io(iomem, NULL, &mips_qemu_ops, NULL, "mips-qemu", 0x10000);

    memory_region_add_subregion(address_space_mem, 0x1fbf0000, iomem);



    /* Try to load a BIOS image. If this fails, we continue regardless,

       but initialize the hardware ourselves. When a kernel gets

       preloaded we also initialize the hardware, since the BIOS wasn't

       run. */

    if (bios_name == NULL)

        bios_name = BIOS_FILENAME;

    filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);

    if (filename) {

        bios_size = get_image_size(filename);

    } else {

        bios_size = -1;

    }

#ifdef TARGET_WORDS_BIGENDIAN

    be = 1;

#else

    be = 0;

#endif

    if ((bios_size > 0) && (bios_size <= BIOS_SIZE)) {

        bios = g_new(MemoryRegion, 1);

        memory_region_init_ram(bios, NULL, "mips_r4k.bios", BIOS_SIZE,

                               &error_fatal);

        memory_region_set_readonly(bios, true);

        memory_region_add_subregion(get_system_memory(), 0x1fc00000, bios);



        load_image_targphys(filename, 0x1fc00000, BIOS_SIZE);

    } else if ((dinfo = drive_get(IF_PFLASH, 0, 0)) != NULL) {

        uint32_t mips_rom = 0x00400000;

        if (!pflash_cfi01_register(0x1fc00000, NULL, "mips_r4k.bios", mips_rom,

                                   blk_by_legacy_dinfo(dinfo),

                                   sector_len, mips_rom / sector_len,

                                   4, 0, 0, 0, 0, be)) {

            fprintf(stderr, "qemu: Error registering flash memory.\n");

	}

    } else if (!qtest_enabled()) {

	/* not fatal */

        fprintf(stderr, "qemu: Warning, could not load MIPS bios '%s'\n",

		bios_name);

    }

    g_free(filename);



    if (kernel_filename) {

        loaderparams.ram_size = ram_size;

        loaderparams.kernel_filename = kernel_filename;

        loaderparams.kernel_cmdline = kernel_cmdline;

        loaderparams.initrd_filename = initrd_filename;

        reset_info->vector = load_kernel();

    }



    /* Init CPU internal devices */

    cpu_mips_irq_init_cpu(cpu);

    cpu_mips_clock_init(cpu);



    /* ISA bus: IO space at 0x14000000, mem space at 0x10000000 */

    memory_region_init_alias(isa_io, NULL, "isa-io",

                             get_system_io(), 0, 0x00010000);

    memory_region_init(isa_mem, NULL, "isa-mem", 0x01000000);

    memory_region_add_subregion(get_system_memory(), 0x14000000, isa_io);

    memory_region_add_subregion(get_system_memory(), 0x10000000, isa_mem);

    isa_bus = isa_bus_new(NULL, isa_mem, get_system_io(), &error_abort);



    /* The PIC is attached to the MIPS CPU INT0 pin */

    i8259 = i8259_init(isa_bus, env->irq[2]);

    isa_bus_irqs(isa_bus, i8259);



    rtc_init(isa_bus, 2000, NULL);



    pit = pit_init(isa_bus, 0x40, 0, NULL);



    serial_hds_isa_init(isa_bus, 0, MAX_SERIAL_PORTS);



    isa_vga_init(isa_bus);



    if (nd_table[0].used)

        isa_ne2000_init(isa_bus, 0x300, 9, &nd_table[0]);



    ide_drive_get(hd, ARRAY_SIZE(hd));

    for(i = 0; i < MAX_IDE_BUS; i++)

        isa_ide_init(isa_bus, ide_iobase[i], ide_iobase2[i], ide_irq[i],

                     hd[MAX_IDE_DEVS * i],

		     hd[MAX_IDE_DEVS * i + 1]);



    isa_create_simple(isa_bus, "i8042");

}

static int write_note(struct memelfnote *men, int fd)

{

    struct elf_note en;



    en.n_namesz = men->namesz;

    en.n_type = men->type;

    en.n_descsz = men->datasz;



    bswap_note(&en);



    if (dump_write(fd, &en, sizeof(en)) != 0)

        return (-1);

    if (dump_write(fd, men->name, men->namesz_rounded) != 0)

        return (-1);

    if (dump_write(fd, men->data, men->datasz) != 0)

        return (-1);



    return (0);

}

static int vhost_virtqueue_start(struct vhost_dev *dev,

                                struct VirtIODevice *vdev,

                                struct vhost_virtqueue *vq,

                                unsigned idx)

{

    hwaddr s, l, a;

    int r;

    int vhost_vq_index = idx - dev->vq_index;

    struct vhost_vring_file file = {

        .index = vhost_vq_index

    };

    struct vhost_vring_state state = {

        .index = vhost_vq_index

    };

    struct VirtQueue *vvq = virtio_get_queue(vdev, idx);



    assert(idx >= dev->vq_index && idx < dev->vq_index + dev->nvqs);



    vq->num = state.num = virtio_queue_get_num(vdev, idx);

    r = dev->vhost_ops->vhost_call(dev, VHOST_SET_VRING_NUM, &state);

    if (r) {

        return -errno;

    }



    state.num = virtio_queue_get_last_avail_idx(vdev, idx);

    r = dev->vhost_ops->vhost_call(dev, VHOST_SET_VRING_BASE, &state);

    if (r) {

        return -errno;

    }



    if (!virtio_has_feature(vdev, VIRTIO_F_VERSION_1) &&

        virtio_legacy_is_cross_endian(vdev)) {

        r = vhost_virtqueue_set_vring_endian_legacy(dev,

                                                    virtio_is_big_endian(vdev),

                                                    vhost_vq_index);

        if (r) {

            return -errno;

        }

    }



    s = l = virtio_queue_get_desc_size(vdev, idx);

    a = virtio_queue_get_desc_addr(vdev, idx);

    vq->desc = cpu_physical_memory_map(a, &l, 0);

    if (!vq->desc || l != s) {

        r = -ENOMEM;

        goto fail_alloc_desc;

    }

    s = l = virtio_queue_get_avail_size(vdev, idx);

    a = virtio_queue_get_avail_addr(vdev, idx);

    vq->avail = cpu_physical_memory_map(a, &l, 0);

    if (!vq->avail || l != s) {

        r = -ENOMEM;

        goto fail_alloc_avail;

    }

    vq->used_size = s = l = virtio_queue_get_used_size(vdev, idx);

    vq->used_phys = a = virtio_queue_get_used_addr(vdev, idx);

    vq->used = cpu_physical_memory_map(a, &l, 1);

    if (!vq->used || l != s) {

        r = -ENOMEM;

        goto fail_alloc_used;

    }



    vq->ring_size = s = l = virtio_queue_get_ring_size(vdev, idx);

    vq->ring_phys = a = virtio_queue_get_ring_addr(vdev, idx);

    vq->ring = cpu_physical_memory_map(a, &l, 1);

    if (!vq->ring || l != s) {

        r = -ENOMEM;

        goto fail_alloc_ring;

    }



    r = vhost_virtqueue_set_addr(dev, vq, vhost_vq_index, dev->log_enabled);

    if (r < 0) {

        r = -errno;

        goto fail_alloc;

    }



    file.fd = event_notifier_get_fd(virtio_queue_get_host_notifier(vvq));

    r = dev->vhost_ops->vhost_call(dev, VHOST_SET_VRING_KICK, &file);

    if (r) {

        r = -errno;

        goto fail_kick;

    }



    /* Clear and discard previous events if any. */

    event_notifier_test_and_clear(&vq->masked_notifier);



    return 0;



fail_kick:

fail_alloc:

    cpu_physical_memory_unmap(vq->ring, virtio_queue_get_ring_size(vdev, idx),

                              0, 0);

fail_alloc_ring:

    cpu_physical_memory_unmap(vq->used, virtio_queue_get_used_size(vdev, idx),

                              0, 0);

fail_alloc_used:

    cpu_physical_memory_unmap(vq->avail, virtio_queue_get_avail_size(vdev, idx),

                              0, 0);

fail_alloc_avail:

    cpu_physical_memory_unmap(vq->desc, virtio_queue_get_desc_size(vdev, idx),

                              0, 0);

fail_alloc_desc:

    return r;

}

void vnc_client_read(void *opaque)

{

    VncState *vs = opaque;

    long ret;



#ifdef CONFIG_VNC_SASL

    if (vs->sasl.conn && vs->sasl.runSSF)

        ret = vnc_client_read_sasl(vs);

    else

#endif /* CONFIG_VNC_SASL */

#ifdef CONFIG_VNC_WS

        if (vs->encode_ws) {

            ret = vnc_client_read_ws(vs);

            if (ret == -1) {

                vnc_disconnect_start(vs);

                return;

            } else if (ret == -2) {

                vnc_client_error(vs);

                return;

            }

        } else

#endif /* CONFIG_VNC_WS */

        {

        ret = vnc_client_read_plain(vs);

        }

    if (!ret) {

        if (vs->csock == -1)

            vnc_disconnect_finish(vs);

        return;

    }



    while (vs->read_handler && vs->input.offset >= vs->read_handler_expect) {

        size_t len = vs->read_handler_expect;

        int ret;



        ret = vs->read_handler(vs, vs->input.buffer, len);

        if (vs->csock == -1) {

            vnc_disconnect_finish(vs);

            return;

        }



        if (!ret) {

            buffer_advance(&vs->input, len);

        } else {

            vs->read_handler_expect = ret;

        }

    }

}

static int find_pte32(CPUPPCState *env, struct mmu_ctx_hash32 *ctx,

                      target_ulong sr, target_ulong eaddr, int rwx)

{

    hwaddr pteg_off, pte_offset;

    ppc_hash_pte32_t pte;

    hwaddr hash;

    uint32_t vsid, pgidx, ptem;

    int ret;



    ret = -1; /* No entry found */

    vsid = sr & SR32_VSID;

    ctx->key = (((sr & SR32_KP) && (msr_pr != 0)) ||

                ((sr & SR32_KS) && (msr_pr == 0))) ? 1 : 0;

    pgidx = (eaddr & ~SEGMENT_MASK_256M) >> TARGET_PAGE_BITS;

    hash = vsid ^ pgidx;

    ptem = (vsid << 7) | (pgidx >> 10);



    /* Page address translation */

    LOG_MMU("htab_base " TARGET_FMT_plx " htab_mask " TARGET_FMT_plx

            " hash " TARGET_FMT_plx "\n",

            env->htab_base, env->htab_mask, hash);



    /* Primary PTEG lookup */

    LOG_MMU("0 htab=" TARGET_FMT_plx "/" TARGET_FMT_plx

            " vsid=%" PRIx32 " ptem=%" PRIx32

            " hash=" TARGET_FMT_plx "\n",

            env->htab_base, env->htab_mask, vsid, ptem, hash);

    pteg_off = get_pteg_offset32(env, hash);

    pte_offset = ppc_hash32_pteg_search(env, pteg_off, 0, ptem, &pte);

    if (pte_offset == -1) {

        /* Secondary PTEG lookup */

        LOG_MMU("1 htab=" TARGET_FMT_plx "/" TARGET_FMT_plx

                " vsid=%" PRIx32 " api=%" PRIx32

                " hash=" TARGET_FMT_plx "\n", env->htab_base,

                env->htab_mask, vsid, ptem, ~hash);

        pteg_off = get_pteg_offset32(env, ~hash);

        pte_offset = ppc_hash32_pteg_search(env, pteg_off, 1, ptem, &pte);

    }



    if (pte_offset != -1) {

        ret = pte_check_hash32(ctx, pte.pte0, pte.pte1, rwx);

        LOG_MMU("found PTE at addr %08" HWADDR_PRIx " prot=%01x ret=%d\n",

                ctx->raddr, ctx->prot, ret);

        /* Update page flags */

        if (ppc_hash32_pte_update_flags(ctx, &pte.pte1, ret, rwx) == 1) {

            ppc_hash32_store_hpte1(env, pte_offset, pte.pte1);

        }

    }



    return ret;

}

static void csrhci_in_packet_vendor(struct csrhci_s *s, int ocf,

                uint8_t *data, int len)

{

    int offset;

    uint8_t *rpkt;



    switch (ocf) {

    case OCF_CSR_SEND_FIRMWARE:

        /* Check if this is the bd_address packet */

        if (len >= 18 + 8 && data[12] == 0x01 && data[13] == 0x00) {

            offset = 18;

            s->bd_addr.b[0] = data[offset + 7];	/* Beyond cmd packet end(!?) */

            s->bd_addr.b[1] = data[offset + 6];

            s->bd_addr.b[2] = data[offset + 4];

            s->bd_addr.b[3] = data[offset + 0];

            s->bd_addr.b[4] = data[offset + 3];

            s->bd_addr.b[5] = data[offset + 2];



            s->hci->bdaddr_set(s->hci, s->bd_addr.b);

            fprintf(stderr, "%s: bd_address loaded from firmware: "

                            "%02x:%02x:%02x:%02x:%02x:%02x\n", __FUNCTION__,

                            s->bd_addr.b[0], s->bd_addr.b[1], s->bd_addr.b[2],

                            s->bd_addr.b[3], s->bd_addr.b[4], s->bd_addr.b[5]);

        }



        rpkt = csrhci_out_packet_event(s, EVT_VENDOR, 11);

        /* Status bytes: no error */

        rpkt[9] = 0x00;

        rpkt[10] = 0x00;

        break;



    default:

        fprintf(stderr, "%s: got a bad CMD packet\n", __FUNCTION__);

        return;

    }



    csrhci_fifo_wake(s);

}

