                gen_op_shiftd_T0_T1_ECX_cc[ot][op]();

            else

                gen_op_shiftd_mem_T0_T1_ECX_cc[ot + s->mem_index][op]();

            s->cc_op = CC_OP_DYNAMIC; /* cannot predict flags after */

        }

