static void ac97_write(void *opaque, target_phys_addr_t addr, uint64_t value,

                       unsigned size)

{

    MilkymistAC97State *s = opaque;



    trace_milkymist_ac97_memory_write(addr, value);



    addr >>= 2;

    switch (addr) {

    case R_AC97_CTRL:

        /* always raise an IRQ according to the direction */

        if (value & AC97_CTRL_RQEN) {

            if (value & AC97_CTRL_WRITE) {

                trace_milkymist_ac97_pulse_irq_crrequest();

                qemu_irq_pulse(s->crrequest_irq);

            } else {

                trace_milkymist_ac97_pulse_irq_crreply();

                qemu_irq_pulse(s->crreply_irq);

            }

        }



        /* RQEN is self clearing */

        s->regs[addr] = value & ~AC97_CTRL_RQEN;

        break;

    case R_D_CTRL:

    case R_U_CTRL:

        s->regs[addr] = value;

        update_voices(s);

        break;

    case R_AC97_ADDR:

    case R_AC97_DATAOUT:

    case R_AC97_DATAIN:

    case R_D_ADDR:

    case R_D_REMAINING:

    case R_U_ADDR:

    case R_U_REMAINING:

        s->regs[addr] = value;

        break;



    default:

        error_report("milkymist_ac97: write access to unknown register 0x"

                TARGET_FMT_plx, addr);

        break;

    }



}

static void mch_realize(PCIDevice *d, Error **errp)

{

    int i;

    MCHPCIState *mch = MCH_PCI_DEVICE(d);



    /* setup pci memory mapping */

    pc_pci_as_mapping_init(OBJECT(mch), mch->system_memory,

                           mch->pci_address_space);



    /* if *disabled* show SMRAM to all CPUs */

    memory_region_init_alias(&mch->smram_region, OBJECT(mch), "smram-region",

                             mch->pci_address_space, 0xa0000, 0x20000);

    memory_region_add_subregion_overlap(mch->system_memory, 0xa0000,

                                        &mch->smram_region, 1);

    memory_region_set_enabled(&mch->smram_region, true);



    memory_region_init_alias(&mch->open_high_smram, OBJECT(mch), "smram-open-high",

                             mch->ram_memory, 0xa0000, 0x20000);

    memory_region_add_subregion_overlap(mch->system_memory, 0xfeda0000,

                                        &mch->open_high_smram, 1);

    memory_region_set_enabled(&mch->open_high_smram, false);



    /* smram, as seen by SMM CPUs */

    memory_region_init(&mch->smram, OBJECT(mch), "smram", 1ull << 32);

    memory_region_set_enabled(&mch->smram, true);

    memory_region_init_alias(&mch->low_smram, OBJECT(mch), "smram-low",

                             mch->ram_memory, 0xa0000, 0x20000);

    memory_region_set_enabled(&mch->low_smram, true);

    memory_region_add_subregion(&mch->smram, 0xa0000, &mch->low_smram);

    memory_region_init_alias(&mch->high_smram, OBJECT(mch), "smram-high",

                             mch->ram_memory, 0xa0000, 0x20000);

    memory_region_set_enabled(&mch->high_smram, true);

    memory_region_add_subregion(&mch->smram, 0xfeda0000, &mch->high_smram);



    memory_region_init_io(&mch->tseg_blackhole, OBJECT(mch),

                          &tseg_blackhole_ops, NULL,

                          "tseg-blackhole", 0);

    memory_region_set_enabled(&mch->tseg_blackhole, false);

    memory_region_add_subregion_overlap(mch->system_memory,

                                        mch->below_4g_mem_size,

                                        &mch->tseg_blackhole, 1);



    memory_region_init_alias(&mch->tseg_window, OBJECT(mch), "tseg-window",

                             mch->ram_memory, mch->below_4g_mem_size, 0);

    memory_region_set_enabled(&mch->tseg_window, false);

    memory_region_add_subregion(&mch->smram, mch->below_4g_mem_size,

                                &mch->tseg_window);

    object_property_add_const_link(qdev_get_machine(), "smram",

                                   OBJECT(&mch->smram), &error_abort);



    init_pam(DEVICE(mch), mch->ram_memory, mch->system_memory,

             mch->pci_address_space, &mch->pam_regions[0],

             PAM_BIOS_BASE, PAM_BIOS_SIZE);

    for (i = 0; i < 12; ++i) {

        init_pam(DEVICE(mch), mch->ram_memory, mch->system_memory,

                 mch->pci_address_space, &mch->pam_regions[i+1],

                 PAM_EXPAN_BASE + i * PAM_EXPAN_SIZE, PAM_EXPAN_SIZE);

    }

    /* Intel IOMMU (VT-d) */

    if (machine_iommu(current_machine)) {

        mch_init_dmar(mch);

    }

}

static void arm_tr_translate_insn(DisasContextBase *dcbase, CPUState *cpu)

{

    DisasContext *dc = container_of(dcbase, DisasContext, base);

    CPUARMState *env = cpu->env_ptr;



#ifdef CONFIG_USER_ONLY

    /* Intercept jump to the magic kernel page.  */

    if (dc->pc >= 0xffff0000) {

        /* We always get here via a jump, so know we are not in a

           conditional execution block.  */

        gen_exception_internal(EXCP_KERNEL_TRAP);

        dc->base.is_jmp = DISAS_NORETURN;

        return;

    }

#endif



    if (dc->ss_active && !dc->pstate_ss) {

        /* Singlestep state is Active-pending.

         * If we're in this state at the start of a TB then either

         *  a) we just took an exception to an EL which is being debugged

         *     and this is the first insn in the exception handler

         *  b) debug exceptions were masked and we just unmasked them

         *     without changing EL (eg by clearing PSTATE.D)

         * In either case we're going to take a swstep exception in the

         * "did not step an insn" case, and so the syndrome ISV and EX

         * bits should be zero.

         */

        assert(dc->base.num_insns == 1);

        gen_exception(EXCP_UDEF, syn_swstep(dc->ss_same_el, 0, 0),

                      default_exception_el(dc));

        dc->base.is_jmp = DISAS_NORETURN;

        return;

    }



    if (dc->thumb) {

        disas_thumb_insn(env, dc);

        if (dc->condexec_mask) {

            dc->condexec_cond = (dc->condexec_cond & 0xe)

                | ((dc->condexec_mask >> 4) & 1);

            dc->condexec_mask = (dc->condexec_mask << 1) & 0x1f;

            if (dc->condexec_mask == 0) {

                dc->condexec_cond = 0;

            }

        }

    } else {

        unsigned int insn = arm_ldl_code(env, dc->pc, dc->sctlr_b);

        dc->pc += 4;

        disas_arm_insn(dc, insn);

    }



    if (dc->condjmp && !dc->base.is_jmp) {

        gen_set_label(dc->condlabel);

        dc->condjmp = 0;

    }



    if (dc->base.is_jmp == DISAS_NEXT) {

        /* Translation stops when a conditional branch is encountered.

         * Otherwise the subsequent code could get translated several times.

         * Also stop translation when a page boundary is reached.  This

         * ensures prefetch aborts occur at the right place.  */



        if (dc->pc >= dc->next_page_start ||

            (dc->pc >= dc->next_page_start - 3 &&

             insn_crosses_page(env, dc))) {

            /* We want to stop the TB if the next insn starts in a new page,

             * or if it spans between this page and the next. This means that

             * if we're looking at the last halfword in the page we need to

             * see if it's a 16-bit Thumb insn (which will fit in this TB)

             * or a 32-bit Thumb insn (which won't).

             * This is to avoid generating a silly TB with a single 16-bit insn

             * in it at the end of this page (which would execute correctly

             * but isn't very efficient).

             */

            dc->base.is_jmp = DISAS_TOO_MANY;

        }

    }



    dc->base.pc_next = dc->pc;

    translator_loop_temp_check(&dc->base);

}

void ppc_tlb_invalidate_one(CPUPPCState *env, target_ulong addr)

{

#if !defined(FLUSH_ALL_TLBS)

    PowerPCCPU *cpu = ppc_env_get_cpu(env);

    CPUState *cs;



    addr &= TARGET_PAGE_MASK;

    switch (env->mmu_model) {

    case POWERPC_MMU_SOFT_6xx:

    case POWERPC_MMU_SOFT_74xx:

        ppc6xx_tlb_invalidate_virt(env, addr, 0);

        if (env->id_tlbs == 1) {

            ppc6xx_tlb_invalidate_virt(env, addr, 1);

        }

        break;

    case POWERPC_MMU_SOFT_4xx:

    case POWERPC_MMU_SOFT_4xx_Z:

        ppc4xx_tlb_invalidate_virt(env, addr, env->spr[SPR_40x_PID]);

        break;

    case POWERPC_MMU_REAL:

        cpu_abort(CPU(cpu), "No TLB for PowerPC 4xx in real mode\n");

        break;

    case POWERPC_MMU_MPC8xx:

        /* XXX: TODO */

        cpu_abort(CPU(cpu), "MPC8xx MMU model is not implemented\n");

        break;

    case POWERPC_MMU_BOOKE:

        /* XXX: TODO */

        cpu_abort(CPU(cpu), "BookE MMU model is not implemented\n");

        break;

    case POWERPC_MMU_BOOKE206:

        /* XXX: TODO */

        cpu_abort(CPU(cpu), "BookE 2.06 MMU model is not implemented\n");

        break;

    case POWERPC_MMU_32B:

    case POWERPC_MMU_601:

        /* tlbie invalidate TLBs for all segments */

        addr &= ~((target_ulong)-1ULL << 28);

        cs = CPU(cpu);

        /* XXX: this case should be optimized,

         * giving a mask to tlb_flush_page

         */

        tlb_flush_page(cs, addr | (0x0 << 28));

        tlb_flush_page(cs, addr | (0x1 << 28));

        tlb_flush_page(cs, addr | (0x2 << 28));

        tlb_flush_page(cs, addr | (0x3 << 28));

        tlb_flush_page(cs, addr | (0x4 << 28));

        tlb_flush_page(cs, addr | (0x5 << 28));

        tlb_flush_page(cs, addr | (0x6 << 28));

        tlb_flush_page(cs, addr | (0x7 << 28));

        tlb_flush_page(cs, addr | (0x8 << 28));

        tlb_flush_page(cs, addr | (0x9 << 28));

        tlb_flush_page(cs, addr | (0xA << 28));

        tlb_flush_page(cs, addr | (0xB << 28));

        tlb_flush_page(cs, addr | (0xC << 28));

        tlb_flush_page(cs, addr | (0xD << 28));

        tlb_flush_page(cs, addr | (0xE << 28));

        tlb_flush_page(cs, addr | (0xF << 28));

        break;

#if defined(TARGET_PPC64)

    case POWERPC_MMU_64B:

    case POWERPC_MMU_2_03:

    case POWERPC_MMU_2_06:

    case POWERPC_MMU_2_06a:

    case POWERPC_MMU_2_07:

    case POWERPC_MMU_2_07a:

        /* tlbie invalidate TLBs for all segments */

        /* XXX: given the fact that there are too many segments to invalidate,

         *      and we still don't have a tlb_flush_mask(env, n, mask) in QEMU,

         *      we just invalidate all TLBs

         */

        tlb_flush(CPU(cpu), 1);

        break;

#endif /* defined(TARGET_PPC64) */

    default:

        /* XXX: TODO */

        cpu_abort(CPU(cpu), "Unknown MMU model\n");

        break;

    }

#else

    ppc_tlb_invalidate_all(env);

#endif

}

static int scsi_qdev_init(DeviceState *qdev)

{

    SCSIDevice *dev = SCSI_DEVICE(qdev);

    SCSIBus *bus = DO_UPCAST(SCSIBus, qbus, dev->qdev.parent_bus);

    SCSIDevice *d;

    int rc = -1;



    if (dev->channel > bus->info->max_channel) {

        error_report("bad scsi channel id: %d", dev->channel);

        goto err;

    }

    if (dev->id != -1 && dev->id > bus->info->max_target) {

        error_report("bad scsi device id: %d", dev->id);

        goto err;

    }

    if (dev->lun != -1 && dev->lun > bus->info->max_lun) {

        error_report("bad scsi device lun: %d", dev->lun);

        goto err;

    }



    if (dev->id == -1) {

        int id = -1;

        if (dev->lun == -1) {

            dev->lun = 0;

        }

        do {

            d = scsi_device_find(bus, dev->channel, ++id, dev->lun);

        } while (d && d->lun == dev->lun && id < bus->info->max_target);

        if (d && d->lun == dev->lun) {

            error_report("no free target");

            goto err;

        }

        dev->id = id;

    } else if (dev->lun == -1) {

        int lun = -1;

        do {

            d = scsi_device_find(bus, dev->channel, dev->id, ++lun);

        } while (d && d->lun == lun && lun < bus->info->max_lun);

        if (d && d->lun == lun) {

            error_report("no free lun");

            goto err;

        }

        dev->lun = lun;

    } else {

        d = scsi_device_find(bus, dev->channel, dev->id, dev->lun);

        assert(d);

        if (d->lun == dev->lun && dev != d) {

            error_report("lun already used by '%s'", d->qdev.id);

            goto err;

        }

    }



    QTAILQ_INIT(&dev->requests);

    rc = scsi_device_init(dev);

    if (rc == 0) {

        dev->vmsentry = qemu_add_vm_change_state_handler(scsi_dma_restart_cb,

                                                         dev);

    }



    if (bus->info->hotplug) {

        bus->info->hotplug(bus, dev);

    }



err:

    return rc;

}

static BusState *qbus_find_recursive(BusState *bus, const char *name,

                                     const BusInfo *info)

{

    DeviceState *dev;

    BusState *child, *ret;

    int match = 1;



    if (name && (strcmp(bus->name, name) != 0)) {

        match = 0;

    }

    if (info && (bus->info != info)) {

        match = 0;

    }

    if (match) {

        return bus;

    }



    LIST_FOREACH(dev, &bus->children, sibling) {

        LIST_FOREACH(child, &dev->child_bus, sibling) {

            ret = qbus_find_recursive(child, name, info);

            if (ret) {

                return ret;

            }

        }

    }

    return NULL;

}

X86CPU *cpu_x86_create(const char *cpu_model, Error **errp)

{

    X86CPU *cpu = NULL;

    ObjectClass *oc;

    CPUClass *cc;

    gchar **model_pieces;

    char *name, *features;

    Error *error = NULL;

    const char *typename;



    model_pieces = g_strsplit(cpu_model, ",", 2);

    if (!model_pieces[0]) {

        error_setg(&error, "Invalid/empty CPU model name");

        goto out;

    }

    name = model_pieces[0];

    features = model_pieces[1];



    oc = x86_cpu_class_by_name(name);

    if (oc == NULL) {

        error_setg(&error, "Unable to find CPU definition: %s", name);

        goto out;

    }

    cc = CPU_CLASS(oc);

    typename = object_class_get_name(oc);



    cc->parse_features(typename, features, &error);

    cpu = X86_CPU(object_new(typename));

    if (error) {

        goto out;

    }



out:

    if (error != NULL) {

        error_propagate(errp, error);

        if (cpu) {

            object_unref(OBJECT(cpu));

            cpu = NULL;

        }

    }

    g_strfreev(model_pieces);

    return cpu;

}

