static void assign_storage(SCLPDevice *sclp, SCCB *sccb)

{

    MemoryRegion *mr = NULL;

    uint64_t this_subregion_size;

    AssignStorage *assign_info = (AssignStorage *) sccb;

    sclpMemoryHotplugDev *mhd = get_sclp_memory_hotplug_dev();

    ram_addr_t assign_addr;

    MemoryRegion *sysmem = get_system_memory();



    if (!mhd) {

        sccb->h.response_code = cpu_to_be16(SCLP_RC_INVALID_SCLP_COMMAND);

        return;

    }

    assign_addr = (assign_info->rn - 1) * mhd->rzm;



    if ((assign_addr % MEM_SECTION_SIZE == 0) &&

        (assign_addr >= mhd->padded_ram_size)) {

        /* Re-use existing memory region if found */

        mr = memory_region_find(sysmem, assign_addr, 1).mr;

        memory_region_unref(mr);

        if (!mr) {



            MemoryRegion *standby_ram = g_new(MemoryRegion, 1);



            /* offset to align to standby_subregion_size for allocation */

            ram_addr_t offset = assign_addr -

                                (assign_addr - mhd->padded_ram_size)

                                % mhd->standby_subregion_size;



            /* strlen("standby.ram") + 4 (Max of KVM_MEMORY_SLOTS) +  NULL */

            char id[16];

            snprintf(id, 16, "standby.ram%d",

                     (int)((offset - mhd->padded_ram_size) /

                     mhd->standby_subregion_size) + 1);



            /* Allocate a subregion of the calculated standby_subregion_size */

            if (offset + mhd->standby_subregion_size >

                mhd->padded_ram_size + mhd->standby_mem_size) {

                this_subregion_size = mhd->padded_ram_size +

                  mhd->standby_mem_size - offset;

            } else {

                this_subregion_size = mhd->standby_subregion_size;

            }



            memory_region_init_ram(standby_ram, NULL, id, this_subregion_size, &error_abort);

            /* This is a hack to make memory hotunplug work again. Once we have

             * subdevices, we have to unparent them when unassigning memory,

             * instead of doing it via the ref count of the MemoryRegion. */

            object_ref(OBJECT(standby_ram));

            object_unparent(OBJECT(standby_ram));

            vmstate_register_ram_global(standby_ram);

            memory_region_add_subregion(sysmem, offset, standby_ram);

        }

        /* The specified subregion is no longer in standby */

        mhd->standby_state_map[(assign_addr - mhd->padded_ram_size)

                               / MEM_SECTION_SIZE] = 1;

    }

    sccb->h.response_code = cpu_to_be16(SCLP_RC_NORMAL_COMPLETION);

}

static int curl_open(BlockDriverState *bs, QDict *options, int flags,

                     Error **errp)

{

    BDRVCURLState *s = bs->opaque;

    CURLState *state = NULL;

    QemuOpts *opts;

    Error *local_err = NULL;

    const char *file;

    const char *cookie;

    const char *cookie_secret;

    double d;

    const char *secretid;

    const char *protocol_delimiter;



    static int inited = 0;



    if (flags & BDRV_O_RDWR) {

        error_setg(errp, "curl block device does not support writes");

        return -EROFS;

    }



    qemu_mutex_init(&s->mutex);

    opts = qemu_opts_create(&runtime_opts, NULL, 0, &error_abort);

    qemu_opts_absorb_qdict(opts, options, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        goto out_noclean;

    }



    s->readahead_size = qemu_opt_get_size(opts, CURL_BLOCK_OPT_READAHEAD,

                                          READ_AHEAD_DEFAULT);

    if ((s->readahead_size & 0x1ff) != 0) {

        error_setg(errp, "HTTP_READAHEAD_SIZE %zd is not a multiple of 512",

                   s->readahead_size);

        goto out_noclean;

    }



    s->timeout = qemu_opt_get_number(opts, CURL_BLOCK_OPT_TIMEOUT,

                                     CURL_TIMEOUT_DEFAULT);

    if (s->timeout > CURL_TIMEOUT_MAX) {

        error_setg(errp, "timeout parameter is too large or negative");

        goto out_noclean;

    }



    s->sslverify = qemu_opt_get_bool(opts, CURL_BLOCK_OPT_SSLVERIFY, true);



    cookie = qemu_opt_get(opts, CURL_BLOCK_OPT_COOKIE);

    cookie_secret = qemu_opt_get(opts, CURL_BLOCK_OPT_COOKIE_SECRET);



    if (cookie && cookie_secret) {

        error_setg(errp,

                   "curl driver cannot handle both cookie and cookie secret");

        goto out_noclean;

    }



    if (cookie_secret) {

        s->cookie = qcrypto_secret_lookup_as_utf8(cookie_secret, errp);

        if (!s->cookie) {

            goto out_noclean;

        }

    } else {

        s->cookie = g_strdup(cookie);

    }



    file = qemu_opt_get(opts, CURL_BLOCK_OPT_URL);

    if (file == NULL) {

        error_setg(errp, "curl block driver requires an 'url' option");

        goto out_noclean;

    }



    if (!strstart(file, bs->drv->protocol_name, &protocol_delimiter) ||

        !strstart(protocol_delimiter, "://", NULL))

    {

        error_setg(errp, "%s curl driver cannot handle the URL '%s' (does not "

                   "start with '%s://')", bs->drv->protocol_name, file,

                   bs->drv->protocol_name);

        goto out_noclean;

    }



    s->username = g_strdup(qemu_opt_get(opts, CURL_BLOCK_OPT_USERNAME));

    secretid = qemu_opt_get(opts, CURL_BLOCK_OPT_PASSWORD_SECRET);



    if (secretid) {

        s->password = qcrypto_secret_lookup_as_utf8(secretid, errp);

        if (!s->password) {

            goto out_noclean;

        }

    }



    s->proxyusername = g_strdup(

        qemu_opt_get(opts, CURL_BLOCK_OPT_PROXY_USERNAME));

    secretid = qemu_opt_get(opts, CURL_BLOCK_OPT_PROXY_PASSWORD_SECRET);

    if (secretid) {

        s->proxypassword = qcrypto_secret_lookup_as_utf8(secretid, errp);

        if (!s->proxypassword) {

            goto out_noclean;

        }

    }



    if (!inited) {

        curl_global_init(CURL_GLOBAL_ALL);

        inited = 1;

    }



    DPRINTF("CURL: Opening %s\n", file);

    QSIMPLEQ_INIT(&s->free_state_waitq);

    s->aio_context = bdrv_get_aio_context(bs);

    s->url = g_strdup(file);

    qemu_mutex_lock(&s->mutex);

    state = curl_find_state(s);

    qemu_mutex_unlock(&s->mutex);

    if (!state) {

        goto out_noclean;

    }



    // Get file size



    if (curl_init_state(s, state) < 0) {

        goto out;

    }



    s->accept_range = false;

    curl_easy_setopt(state->curl, CURLOPT_NOBODY, 1);

    curl_easy_setopt(state->curl, CURLOPT_HEADERFUNCTION,

                     curl_header_cb);

    curl_easy_setopt(state->curl, CURLOPT_HEADERDATA, s);

    if (curl_easy_perform(state->curl))

        goto out;

    if (curl_easy_getinfo(state->curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD, &d)) {

        goto out;

    }

    /* Prior CURL 7.19.4 return value of 0 could mean that the file size is not

     * know or the size is zero. From 7.19.4 CURL returns -1 if size is not

     * known and zero if it is realy zero-length file. */

#if LIBCURL_VERSION_NUM >= 0x071304

    if (d < 0) {

        pstrcpy(state->errmsg, CURL_ERROR_SIZE,

                "Server didn't report file size.");

        goto out;

    }

#else

    if (d <= 0) {

        pstrcpy(state->errmsg, CURL_ERROR_SIZE,

                "Unknown file size or zero-length file.");

        goto out;

    }

#endif



    s->len = d;



    if ((!strncasecmp(s->url, "http://", strlen("http://"))

        || !strncasecmp(s->url, "https://", strlen("https://")))

        && !s->accept_range) {

        pstrcpy(state->errmsg, CURL_ERROR_SIZE,

                "Server does not support 'range' (byte ranges).");

        goto out;

    }

    DPRINTF("CURL: Size = %" PRIu64 "\n", s->len);



    qemu_mutex_lock(&s->mutex);

    curl_clean_state(state);

    qemu_mutex_unlock(&s->mutex);

    curl_easy_cleanup(state->curl);

    state->curl = NULL;



    curl_attach_aio_context(bs, bdrv_get_aio_context(bs));



    qemu_opts_del(opts);

    return 0;



out:

    error_setg(errp, "CURL: Error opening file: %s", state->errmsg);

    curl_easy_cleanup(state->curl);

    state->curl = NULL;

out_noclean:

    qemu_mutex_destroy(&s->mutex);

    g_free(s->cookie);

    g_free(s->url);

    qemu_opts_del(opts);

    return -EINVAL;

}

static void set_kernel_args_old(const struct arm_boot_info *info)

{

    target_phys_addr_t p;

    const char *s;

    int initrd_size = info->initrd_size;

    target_phys_addr_t base = info->loader_start;



    /* see linux/include/asm-arm/setup.h */

    p = base + KERNEL_ARGS_ADDR;

    /* page_size */

    WRITE_WORD(p, 4096);

    /* nr_pages */

    WRITE_WORD(p, info->ram_size / 4096);

    /* ramdisk_size */

    WRITE_WORD(p, 0);

#define FLAG_READONLY	1

#define FLAG_RDLOAD	4

#define FLAG_RDPROMPT	8

    /* flags */

    WRITE_WORD(p, FLAG_READONLY | FLAG_RDLOAD | FLAG_RDPROMPT);

    /* rootdev */

    WRITE_WORD(p, (31 << 8) | 0);	/* /dev/mtdblock0 */

    /* video_num_cols */

    WRITE_WORD(p, 0);

    /* video_num_rows */

    WRITE_WORD(p, 0);

    /* video_x */

    WRITE_WORD(p, 0);

    /* video_y */

    WRITE_WORD(p, 0);

    /* memc_control_reg */

    WRITE_WORD(p, 0);

    /* unsigned char sounddefault */

    /* unsigned char adfsdrives */

    /* unsigned char bytes_per_char_h */

    /* unsigned char bytes_per_char_v */

    WRITE_WORD(p, 0);

    /* pages_in_bank[4] */

    WRITE_WORD(p, 0);

    WRITE_WORD(p, 0);

    WRITE_WORD(p, 0);

    WRITE_WORD(p, 0);

    /* pages_in_vram */

    WRITE_WORD(p, 0);

    /* initrd_start */

    if (initrd_size)

        WRITE_WORD(p, info->loader_start + INITRD_LOAD_ADDR);

    else

        WRITE_WORD(p, 0);

    /* initrd_size */

    WRITE_WORD(p, initrd_size);

    /* rd_start */

    WRITE_WORD(p, 0);

    /* system_rev */

    WRITE_WORD(p, 0);

    /* system_serial_low */

    WRITE_WORD(p, 0);

    /* system_serial_high */

    WRITE_WORD(p, 0);

    /* mem_fclk_21285 */

    WRITE_WORD(p, 0);

    /* zero unused fields */

    while (p < base + KERNEL_ARGS_ADDR + 256 + 1024) {

        WRITE_WORD(p, 0);

    }

    s = info->kernel_cmdline;

    if (s) {

        cpu_physical_memory_write(p, (void *)s, strlen(s) + 1);

    } else {

        WRITE_WORD(p, 0);

    }

}

static void virtio_ccw_net_realize(VirtioCcwDevice *ccw_dev, Error **errp)

{

    DeviceState *qdev = DEVICE(ccw_dev);

    VirtIONetCcw *dev = VIRTIO_NET_CCW(ccw_dev);

    DeviceState *vdev = DEVICE(&dev->vdev);

    Error *err = NULL;



    virtio_net_set_netclient_name(&dev->vdev, qdev->id,

                                  object_get_typename(OBJECT(qdev)));

    qdev_set_parent_bus(vdev, BUS(&ccw_dev->bus));

    object_property_set_bool(OBJECT(vdev), true, "realized", &err);

    if (err) {

        error_propagate(errp, err);

    }

}

