static void init_ppc_proc(PowerPCCPU *cpu)

{

    PowerPCCPUClass *pcc = POWERPC_CPU_GET_CLASS(cpu);

    CPUPPCState *env = &cpu->env;

#if !defined(CONFIG_USER_ONLY)

    int i;



    env->irq_inputs = NULL;

    /* Set all exception vectors to an invalid address */

    for (i = 0; i < POWERPC_EXCP_NB; i++)

        env->excp_vectors[i] = (target_ulong)(-1ULL);

    env->ivor_mask = 0x00000000;

    env->ivpr_mask = 0x00000000;

    /* Default MMU definitions */

    env->nb_BATs = 0;

    env->nb_tlb = 0;

    env->nb_ways = 0;

    env->tlb_type = TLB_NONE;

#endif

    /* Register SPR common to all PowerPC implementations */

    gen_spr_generic(env);

    spr_register(env, SPR_PVR, "PVR",

                 /* Linux permits userspace to read PVR */

#if defined(CONFIG_LINUX_USER)

                 &spr_read_generic,

#else

                 SPR_NOACCESS,

#endif

                 SPR_NOACCESS,

                 &spr_read_generic, SPR_NOACCESS,

                 pcc->pvr);

    /* Register SVR if it's defined to anything else than POWERPC_SVR_NONE */

    if (pcc->svr != POWERPC_SVR_NONE) {

        if (pcc->svr & POWERPC_SVR_E500) {

            spr_register(env, SPR_E500_SVR, "SVR",

                         SPR_NOACCESS, SPR_NOACCESS,

                         &spr_read_generic, SPR_NOACCESS,

                         pcc->svr & ~POWERPC_SVR_E500);

        } else {

            spr_register(env, SPR_SVR, "SVR",

                         SPR_NOACCESS, SPR_NOACCESS,

                         &spr_read_generic, SPR_NOACCESS,

                         pcc->svr);

        }

    }

    /* PowerPC implementation specific initialisations (SPRs, timers, ...) */

    (*pcc->init_proc)(env);



    /* MSR bits & flags consistency checks */

    if (env->msr_mask & (1 << 25)) {

        switch (env->flags & (POWERPC_FLAG_SPE | POWERPC_FLAG_VRE)) {

        case POWERPC_FLAG_SPE:

        case POWERPC_FLAG_VRE:

            break;

        default:

            fprintf(stderr, "PowerPC MSR definition inconsistency\n"

                    "Should define POWERPC_FLAG_SPE or POWERPC_FLAG_VRE\n");

            exit(1);

        }

    } else if (env->flags & (POWERPC_FLAG_SPE | POWERPC_FLAG_VRE)) {

        fprintf(stderr, "PowerPC MSR definition inconsistency\n"

                "Should not define POWERPC_FLAG_SPE nor POWERPC_FLAG_VRE\n");

        exit(1);

    }

    if (env->msr_mask & (1 << 17)) {

        switch (env->flags & (POWERPC_FLAG_TGPR | POWERPC_FLAG_CE)) {

        case POWERPC_FLAG_TGPR:

        case POWERPC_FLAG_CE:

            break;

        default:

            fprintf(stderr, "PowerPC MSR definition inconsistency\n"

                    "Should define POWERPC_FLAG_TGPR or POWERPC_FLAG_CE\n");

            exit(1);

        }

    } else if (env->flags & (POWERPC_FLAG_TGPR | POWERPC_FLAG_CE)) {

        fprintf(stderr, "PowerPC MSR definition inconsistency\n"

                "Should not define POWERPC_FLAG_TGPR nor POWERPC_FLAG_CE\n");

        exit(1);

    }

    if (env->msr_mask & (1 << 10)) {

        switch (env->flags & (POWERPC_FLAG_SE | POWERPC_FLAG_DWE |

                              POWERPC_FLAG_UBLE)) {

        case POWERPC_FLAG_SE:

        case POWERPC_FLAG_DWE:

        case POWERPC_FLAG_UBLE:

            break;

        default:

            fprintf(stderr, "PowerPC MSR definition inconsistency\n"

                    "Should define POWERPC_FLAG_SE or POWERPC_FLAG_DWE or "

                    "POWERPC_FLAG_UBLE\n");

            exit(1);

        }

    } else if (env->flags & (POWERPC_FLAG_SE | POWERPC_FLAG_DWE |

                             POWERPC_FLAG_UBLE)) {

        fprintf(stderr, "PowerPC MSR definition inconsistency\n"

                "Should not define POWERPC_FLAG_SE nor POWERPC_FLAG_DWE nor "

                "POWERPC_FLAG_UBLE\n");

            exit(1);

    }

    if (env->msr_mask & (1 << 9)) {

        switch (env->flags & (POWERPC_FLAG_BE | POWERPC_FLAG_DE)) {

        case POWERPC_FLAG_BE:

        case POWERPC_FLAG_DE:

            break;

        default:

            fprintf(stderr, "PowerPC MSR definition inconsistency\n"

                    "Should define POWERPC_FLAG_BE or POWERPC_FLAG_DE\n");

            exit(1);

        }

    } else if (env->flags & (POWERPC_FLAG_BE | POWERPC_FLAG_DE)) {

        fprintf(stderr, "PowerPC MSR definition inconsistency\n"

                "Should not define POWERPC_FLAG_BE nor POWERPC_FLAG_DE\n");

        exit(1);

    }

    if (env->msr_mask & (1 << 2)) {

        switch (env->flags & (POWERPC_FLAG_PX | POWERPC_FLAG_PMM)) {

        case POWERPC_FLAG_PX:

        case POWERPC_FLAG_PMM:

            break;

        default:

            fprintf(stderr, "PowerPC MSR definition inconsistency\n"

                    "Should define POWERPC_FLAG_PX or POWERPC_FLAG_PMM\n");

            exit(1);

        }

    } else if (env->flags & (POWERPC_FLAG_PX | POWERPC_FLAG_PMM)) {

        fprintf(stderr, "PowerPC MSR definition inconsistency\n"

                "Should not define POWERPC_FLAG_PX nor POWERPC_FLAG_PMM\n");

        exit(1);

    }

    if ((env->flags & (POWERPC_FLAG_RTC_CLK | POWERPC_FLAG_BUS_CLK)) == 0) {

        fprintf(stderr, "PowerPC flags inconsistency\n"

                "Should define the time-base and decrementer clock source\n");

        exit(1);

    }

    /* Allocate TLBs buffer when needed */

#if !defined(CONFIG_USER_ONLY)

    if (env->nb_tlb != 0) {

        int nb_tlb = env->nb_tlb;

        if (env->id_tlbs != 0)

            nb_tlb *= 2;

        switch (env->tlb_type) {

        case TLB_6XX:

            env->tlb.tlb6 = g_malloc0(nb_tlb * sizeof(ppc6xx_tlb_t));

            break;

        case TLB_EMB:

            env->tlb.tlbe = g_malloc0(nb_tlb * sizeof(ppcemb_tlb_t));

            break;

        case TLB_MAS:

            env->tlb.tlbm = g_malloc0(nb_tlb * sizeof(ppcmas_tlb_t));

            break;

        }

        /* Pre-compute some useful values */

        env->tlb_per_way = env->nb_tlb / env->nb_ways;

    }

    if (env->irq_inputs == NULL) {

        fprintf(stderr, "WARNING: no internal IRQ controller registered.\n"

                " Attempt QEMU to crash very soon !\n");

    }

#endif

    if (env->check_pow == NULL) {

        fprintf(stderr, "WARNING: no power management check handler "

                "registered.\n"

                " Attempt QEMU to crash very soon !\n");

    }

}

static int set_boot_dev(ISADevice *s, const char *boot_device)

{

#define PC_MAX_BOOT_DEVICES 3

    int nbds, bds[3] = { 0, };

    int i;



    nbds = strlen(boot_device);

    if (nbds > PC_MAX_BOOT_DEVICES) {

        error_report("Too many boot devices for PC");

        return(1);

    }

    for (i = 0; i < nbds; i++) {

        bds[i] = boot_device2nibble(boot_device[i]);

        if (bds[i] == 0) {

            error_report("Invalid boot device for PC: '%c'",

                         boot_device[i]);

            return(1);

        }

    }

    rtc_set_memory(s, 0x3d, (bds[1] << 4) | bds[0]);

    rtc_set_memory(s, 0x38, (bds[2] << 4) | (fd_bootchk ? 0x0 : 0x1));

    return(0);

}

static int64_t load_kernel (void)

{

    int64_t kernel_entry, kernel_high;

    long initrd_size;

    ram_addr_t initrd_offset;

    int big_endian;

    uint32_t *prom_buf;

    long prom_size;

    int prom_index = 0;



#ifdef TARGET_WORDS_BIGENDIAN

    big_endian = 1;

#else

    big_endian = 0;

#endif



    if (load_elf(loaderparams.kernel_filename, cpu_mips_kseg0_to_phys, NULL,

                 (uint64_t *)&kernel_entry, NULL, (uint64_t *)&kernel_high,

                 big_endian, ELF_MACHINE, 1) < 0) {

        fprintf(stderr, "qemu: could not load kernel '%s'\n",

                loaderparams.kernel_filename);

        exit(1);

    }



    /* load initrd */

    initrd_size = 0;

    initrd_offset = 0;

    if (loaderparams.initrd_filename) {

        initrd_size = get_image_size (loaderparams.initrd_filename);

        if (initrd_size > 0) {

            initrd_offset = (kernel_high + ~INITRD_PAGE_MASK) & INITRD_PAGE_MASK;

            if (initrd_offset + initrd_size > ram_size) {

                fprintf(stderr,

                        "qemu: memory too small for initial ram disk '%s'\n",

                        loaderparams.initrd_filename);

                exit(1);

            }

            initrd_size = load_image_targphys(loaderparams.initrd_filename,

                                              initrd_offset,

                                              ram_size - initrd_offset);

        }

        if (initrd_size == (target_ulong) -1) {

            fprintf(stderr, "qemu: could not load initial ram disk '%s'\n",

                    loaderparams.initrd_filename);

            exit(1);

        }

    }



    /* Setup prom parameters. */

    prom_size = ENVP_NB_ENTRIES * (sizeof(int32_t) + ENVP_ENTRY_SIZE);

    prom_buf = g_malloc(prom_size);



    prom_set(prom_buf, prom_index++, "%s", loaderparams.kernel_filename);

    if (initrd_size > 0) {

        prom_set(prom_buf, prom_index++, "rd_start=0x%" PRIx64 " rd_size=%li %s",

                 cpu_mips_phys_to_kseg0(NULL, initrd_offset), initrd_size,

                 loaderparams.kernel_cmdline);

    } else {

        prom_set(prom_buf, prom_index++, "%s", loaderparams.kernel_cmdline);

    }



    prom_set(prom_buf, prom_index++, "memsize");

    prom_set(prom_buf, prom_index++, "%i", loaderparams.ram_size);

    prom_set(prom_buf, prom_index++, "modetty0");

    prom_set(prom_buf, prom_index++, "38400n8r");

    prom_set(prom_buf, prom_index++, NULL);



    rom_add_blob_fixed("prom", prom_buf, prom_size,

                       cpu_mips_kseg0_to_phys(NULL, ENVP_ADDR));



    return kernel_entry;

}

static int nbd_co_receive_reply(NBDClientSession *s,

                                NBDRequest *request,

                                QEMUIOVector *qiov)

{

    int ret;

    int i = HANDLE_TO_INDEX(s, request->handle);



    /* Wait until we're woken up by nbd_read_reply_entry.  */

    s->requests[i].receiving = true;

    qemu_coroutine_yield();

    s->requests[i].receiving = false;

    if (s->reply.handle != request->handle || !s->ioc || s->quit) {

        ret = -EIO;

    } else {

        ret = -s->reply.error;

        if (qiov && s->reply.error == 0) {

            assert(request->len == iov_size(qiov->iov, qiov->niov));

            if (qio_channel_readv_all(s->ioc, qiov->iov, qiov->niov,

                                      NULL) < 0) {

                ret = -EIO;

                s->quit = true;

            }

        }



        /* Tell the read handler to read another header.  */

        s->reply.handle = 0;

    }



    s->requests[i].coroutine = NULL;



    /* Kick the read_reply_co to get the next reply.  */

    if (s->read_reply_co) {

        aio_co_wake(s->read_reply_co);

    }



    qemu_co_mutex_lock(&s->send_mutex);

    s->in_flight--;

    qemu_co_queue_next(&s->free_sema);

    qemu_co_mutex_unlock(&s->send_mutex);



    return ret;

}

static int usb_host_auto_scan(void *opaque, int bus_num, int addr, char *port,

                              int class_id, int vendor_id, int product_id,

                              const char *product_name, int speed)

{

    struct USBAutoFilter *f;

    struct USBHostDevice *s;



    /* Ignore hubs */

    if (class_id == 9)

        return 0;



    QTAILQ_FOREACH(s, &hostdevs, next) {

        f = &s->match;



        if (f->bus_num > 0 && f->bus_num != bus_num) {

            continue;

        }

        if (f->addr > 0 && f->addr != addr) {

            continue;

        }

        if (f->port != NULL && (port == NULL || strcmp(f->port, port) != 0)) {

            continue;

        }



        if (f->vendor_id > 0 && f->vendor_id != vendor_id) {

            continue;

        }



        if (f->product_id > 0 && f->product_id != product_id) {

            continue;

        }

        /* We got a match */



        /* Already attached ? */

        if (s->fd != -1) {

            return 0;

        }

        DPRINTF("husb: auto open: bus_num %d addr %d\n", bus_num, addr);



        usb_host_open(s, bus_num, addr, port, product_name, speed);

        break;

    }



    return 0;

}

static int disas_coproc_insn(DisasContext *s, uint32_t insn)

{

    int cpnum, is64, crn, crm, opc1, opc2, isread, rt, rt2;

    const ARMCPRegInfo *ri;



    cpnum = (insn >> 8) & 0xf;



    /* First check for coprocessor space used for XScale/iwMMXt insns */

    if (arm_dc_feature(s, ARM_FEATURE_XSCALE) && (cpnum < 2)) {

        if (extract32(s->c15_cpar, cpnum, 1) == 0) {

            return 1;

        }

        if (arm_dc_feature(s, ARM_FEATURE_IWMMXT)) {

            return disas_iwmmxt_insn(s, insn);

        } else if (arm_dc_feature(s, ARM_FEATURE_XSCALE)) {

            return disas_dsp_insn(s, insn);

        }

        return 1;

    }



    /* Otherwise treat as a generic register access */

    is64 = (insn & (1 << 25)) == 0;

    if (!is64 && ((insn & (1 << 4)) == 0)) {

        /* cdp */

        return 1;

    }



    crm = insn & 0xf;

    if (is64) {

        crn = 0;

        opc1 = (insn >> 4) & 0xf;

        opc2 = 0;

        rt2 = (insn >> 16) & 0xf;

    } else {

        crn = (insn >> 16) & 0xf;

        opc1 = (insn >> 21) & 7;

        opc2 = (insn >> 5) & 7;

        rt2 = 0;

    }

    isread = (insn >> 20) & 1;

    rt = (insn >> 12) & 0xf;



    ri = get_arm_cp_reginfo(s->cp_regs,

            ENCODE_CP_REG(cpnum, is64, s->ns, crn, crm, opc1, opc2));

    if (ri) {

        /* Check access permissions */

        if (!cp_access_ok(s->current_el, ri, isread)) {

            return 1;

        }



        if (ri->accessfn ||

            (arm_dc_feature(s, ARM_FEATURE_XSCALE) && cpnum < 14)) {

            /* Emit code to perform further access permissions checks at

             * runtime; this may result in an exception.

             * Note that on XScale all cp0..c13 registers do an access check

             * call in order to handle c15_cpar.

             */

            TCGv_ptr tmpptr;

            TCGv_i32 tcg_syn;

            uint32_t syndrome;



            /* Note that since we are an implementation which takes an

             * exception on a trapped conditional instruction only if the

             * instruction passes its condition code check, we can take

             * advantage of the clause in the ARM ARM that allows us to set

             * the COND field in the instruction to 0xE in all cases.

             * We could fish the actual condition out of the insn (ARM)

             * or the condexec bits (Thumb) but it isn't necessary.

             */

            switch (cpnum) {

            case 14:

                if (is64) {

                    syndrome = syn_cp14_rrt_trap(1, 0xe, opc1, crm, rt, rt2,

                                                 isread, s->thumb);

                } else {

                    syndrome = syn_cp14_rt_trap(1, 0xe, opc1, opc2, crn, crm,

                                                rt, isread, s->thumb);

                }

                break;

            case 15:

                if (is64) {

                    syndrome = syn_cp15_rrt_trap(1, 0xe, opc1, crm, rt, rt2,

                                                 isread, s->thumb);

                } else {

                    syndrome = syn_cp15_rt_trap(1, 0xe, opc1, opc2, crn, crm,

                                                rt, isread, s->thumb);

                }

                break;

            default:

                /* ARMv8 defines that only coprocessors 14 and 15 exist,

                 * so this can only happen if this is an ARMv7 or earlier CPU,

                 * in which case the syndrome information won't actually be

                 * guest visible.

                 */

                assert(!arm_dc_feature(s, ARM_FEATURE_V8));

                syndrome = syn_uncategorized();

                break;

            }



            gen_set_pc_im(s, s->pc);

            tmpptr = tcg_const_ptr(ri);

            tcg_syn = tcg_const_i32(syndrome);

            gen_helper_access_check_cp_reg(cpu_env, tmpptr, tcg_syn);

            tcg_temp_free_ptr(tmpptr);

            tcg_temp_free_i32(tcg_syn);

        }



        /* Handle special cases first */

        switch (ri->type & ~(ARM_CP_FLAG_MASK & ~ARM_CP_SPECIAL)) {

        case ARM_CP_NOP:

            return 0;

        case ARM_CP_WFI:

            if (isread) {

                return 1;

            }

            gen_set_pc_im(s, s->pc);

            s->is_jmp = DISAS_WFI;

            return 0;

        default:

            break;

        }



        if (use_icount && (ri->type & ARM_CP_IO)) {

            gen_io_start();

        }



        if (isread) {

            /* Read */

            if (is64) {

                TCGv_i64 tmp64;

                TCGv_i32 tmp;

                if (ri->type & ARM_CP_CONST) {

                    tmp64 = tcg_const_i64(ri->resetvalue);

                } else if (ri->readfn) {

                    TCGv_ptr tmpptr;

                    tmp64 = tcg_temp_new_i64();

                    tmpptr = tcg_const_ptr(ri);

                    gen_helper_get_cp_reg64(tmp64, cpu_env, tmpptr);

                    tcg_temp_free_ptr(tmpptr);

                } else {

                    tmp64 = tcg_temp_new_i64();

                    tcg_gen_ld_i64(tmp64, cpu_env, ri->fieldoffset);

                }

                tmp = tcg_temp_new_i32();

                tcg_gen_trunc_i64_i32(tmp, tmp64);

                store_reg(s, rt, tmp);

                tcg_gen_shri_i64(tmp64, tmp64, 32);

                tmp = tcg_temp_new_i32();

                tcg_gen_trunc_i64_i32(tmp, tmp64);

                tcg_temp_free_i64(tmp64);

                store_reg(s, rt2, tmp);

            } else {

                TCGv_i32 tmp;

                if (ri->type & ARM_CP_CONST) {

                    tmp = tcg_const_i32(ri->resetvalue);

                } else if (ri->readfn) {

                    TCGv_ptr tmpptr;

                    tmp = tcg_temp_new_i32();

                    tmpptr = tcg_const_ptr(ri);

                    gen_helper_get_cp_reg(tmp, cpu_env, tmpptr);

                    tcg_temp_free_ptr(tmpptr);

                } else {

                    tmp = load_cpu_offset(ri->fieldoffset);

                }

                if (rt == 15) {

                    /* Destination register of r15 for 32 bit loads sets

                     * the condition codes from the high 4 bits of the value

                     */

                    gen_set_nzcv(tmp);

                    tcg_temp_free_i32(tmp);

                } else {

                    store_reg(s, rt, tmp);

                }

            }

        } else {

            /* Write */

            if (ri->type & ARM_CP_CONST) {

                /* If not forbidden by access permissions, treat as WI */

                return 0;

            }



            if (is64) {

                TCGv_i32 tmplo, tmphi;

                TCGv_i64 tmp64 = tcg_temp_new_i64();

                tmplo = load_reg(s, rt);

                tmphi = load_reg(s, rt2);

                tcg_gen_concat_i32_i64(tmp64, tmplo, tmphi);

                tcg_temp_free_i32(tmplo);

                tcg_temp_free_i32(tmphi);

                if (ri->writefn) {

                    TCGv_ptr tmpptr = tcg_const_ptr(ri);

                    gen_helper_set_cp_reg64(cpu_env, tmpptr, tmp64);

                    tcg_temp_free_ptr(tmpptr);

                } else {

                    tcg_gen_st_i64(tmp64, cpu_env, ri->fieldoffset);

                }

                tcg_temp_free_i64(tmp64);

            } else {

                if (ri->writefn) {

                    TCGv_i32 tmp;

                    TCGv_ptr tmpptr;

                    tmp = load_reg(s, rt);

                    tmpptr = tcg_const_ptr(ri);

                    gen_helper_set_cp_reg(cpu_env, tmpptr, tmp);

                    tcg_temp_free_ptr(tmpptr);

                    tcg_temp_free_i32(tmp);

                } else {

                    TCGv_i32 tmp = load_reg(s, rt);

                    store_cpu_offset(tmp, ri->fieldoffset);

                }

            }

        }



        if (use_icount && (ri->type & ARM_CP_IO)) {

            /* I/O operations must end the TB here (whether read or write) */

            gen_io_end();

            gen_lookup_tb(s);

        } else if (!isread && !(ri->type & ARM_CP_SUPPRESS_TB_END)) {

            /* We default to ending the TB on a coprocessor register write,

             * but allow this to be suppressed by the register definition

             * (usually only necessary to work around guest bugs).

             */

            gen_lookup_tb(s);

        }



        return 0;

    }



    /* Unknown register; this might be a guest error or a QEMU

     * unimplemented feature.

     */

    if (is64) {

        qemu_log_mask(LOG_UNIMP, "%s access to unsupported AArch32 "

                      "64 bit system register cp:%d opc1: %d crm:%d "

                      "(%s)\n",

                      isread ? "read" : "write", cpnum, opc1, crm,

                      s->ns ? "non-secure" : "secure");

    } else {

        qemu_log_mask(LOG_UNIMP, "%s access to unsupported AArch32 "

                      "system register cp:%d opc1:%d crn:%d crm:%d opc2:%d "

                      "(%s)\n",

                      isread ? "read" : "write", cpnum, opc1, crn, crm, opc2,

                      s->ns ? "non-secure" : "secure");

    }



    return 1;

}

e1000_mmio_write(void *opaque, target_phys_addr_t addr, uint64_t val,

                 unsigned size)

{

    E1000State *s = opaque;

    unsigned int index = (addr & 0x1ffff) >> 2;



    if (index < NWRITEOPS && macreg_writeops[index]) {

        macreg_writeops[index](s, index, val);

    } else if (index < NREADOPS && macreg_readops[index]) {

        DBGOUT(MMIO, "e1000_mmio_writel RO %x: 0x%04"PRIx64"\n", index<<2, val);

    } else {

        DBGOUT(UNKNOWN, "MMIO unknown write addr=0x%08x,val=0x%08"PRIx64"\n",

               index<<2, val);

    }

}

socket_sockaddr_to_address_unix(struct sockaddr_storage *sa,

                                socklen_t salen,

                                Error **errp)

{

    SocketAddress *addr;

    struct sockaddr_un *su = (struct sockaddr_un *)sa;



    addr = g_new0(SocketAddress, 1);

    addr->type = SOCKET_ADDRESS_KIND_UNIX;

    addr->u.q_unix = g_new0(UnixSocketAddress, 1);

    if (su->sun_path[0]) {

        addr->u.q_unix->path = g_strndup(su->sun_path,

                                         sizeof(su->sun_path));

    }



    return addr;

}

static int fetch_active_ports_list(QEMUFile *f, int version_id,

                                   VirtIOSerial *s, uint32_t nr_active_ports)

{

    uint32_t i;



    s->post_load = g_malloc0(sizeof(*s->post_load));

    s->post_load->nr_active_ports = nr_active_ports;

    s->post_load->connected =

        g_malloc0(sizeof(*s->post_load->connected) * nr_active_ports);



    s->post_load->timer = timer_new_ns(QEMU_CLOCK_VIRTUAL,

                                            virtio_serial_post_load_timer_cb,

                                            s);



    /* Items in struct VirtIOSerialPort */

    for (i = 0; i < nr_active_ports; i++) {

        VirtIOSerialPort *port;

        uint32_t id;



        id = qemu_get_be32(f);

        port = find_port_by_id(s, id);

        if (!port) {

            return -EINVAL;

        }



        port->guest_connected = qemu_get_byte(f);

        s->post_load->connected[i].port = port;

        s->post_load->connected[i].host_connected = qemu_get_byte(f);



        if (version_id > 2) {

            uint32_t elem_popped;



            qemu_get_be32s(f, &elem_popped);

            if (elem_popped) {

                qemu_get_be32s(f, &port->iov_idx);

                qemu_get_be64s(f, &port->iov_offset);



                qemu_get_buffer(f, (unsigned char *)&port->elem,

                                sizeof(port->elem));

                virtqueue_map(&port->elem);



                /*

                 *  Port was throttled on source machine.  Let's

                 *  unthrottle it here so data starts flowing again.

                 */

                virtio_serial_throttle_port(port, false);

            }

        }

    }

    timer_mod(s->post_load->timer, 1);

    return 0;

}

void qdev_prop_set_globals_for_type(DeviceState *dev, const char *typename,

                                    Error **errp)

{

    GlobalProperty *prop;



    QTAILQ_FOREACH(prop, &global_props, next) {

        Error *err = NULL;



        if (strcmp(typename, prop->driver) != 0) {

            continue;

        }

        prop->not_used = false;

        object_property_parse(OBJECT(dev), prop->value, prop->property, &err);

        if (err != NULL) {

            error_propagate(errp, err);

            return;

        }

    }

}

