static void *source_return_path_thread(void *opaque)

{

    MigrationState *ms = opaque;

    QEMUFile *rp = ms->rp_state.from_dst_file;

    uint16_t header_len, header_type;

    const int max_len = 512;

    uint8_t buf[max_len];

    uint32_t tmp32, sibling_error;

    ram_addr_t start = 0; /* =0 to silence warning */

    size_t  len = 0, expected_len;

    int res;



    trace_source_return_path_thread_entry();

    while (!ms->rp_state.error && !qemu_file_get_error(rp) &&

           migration_is_setup_or_active(ms->state)) {

        trace_source_return_path_thread_loop_top();

        header_type = qemu_get_be16(rp);

        header_len = qemu_get_be16(rp);



        if (header_type >= MIG_RP_MSG_MAX ||

            header_type == MIG_RP_MSG_INVALID) {

            error_report("RP: Received invalid message 0x%04x length 0x%04x",

                    header_type, header_len);

            mark_source_rp_bad(ms);

            goto out;

        }



        if ((rp_cmd_args[header_type].len != -1 &&

            header_len != rp_cmd_args[header_type].len) ||

            header_len > max_len) {

            error_report("RP: Received '%s' message (0x%04x) with"

                    "incorrect length %d expecting %zu",

                    rp_cmd_args[header_type].name, header_type, header_len,

                    (size_t)rp_cmd_args[header_type].len);

            mark_source_rp_bad(ms);

            goto out;

        }



        /* We know we've got a valid header by this point */

        res = qemu_get_buffer(rp, buf, header_len);

        if (res != header_len) {

            error_report("RP: Failed reading data for message 0x%04x"

                         " read %d expected %d",

                         header_type, res, header_len);

            mark_source_rp_bad(ms);

            goto out;

        }



        /* OK, we have the message and the data */

        switch (header_type) {

        case MIG_RP_MSG_SHUT:

            sibling_error = be32_to_cpup((uint32_t *)buf);

            trace_source_return_path_thread_shut(sibling_error);

            if (sibling_error) {

                error_report("RP: Sibling indicated error %d", sibling_error);

                mark_source_rp_bad(ms);

            }

            /*

             * We'll let the main thread deal with closing the RP

             * we could do a shutdown(2) on it, but we're the only user

             * anyway, so there's nothing gained.

             */

            goto out;



        case MIG_RP_MSG_PONG:

            tmp32 = be32_to_cpup((uint32_t *)buf);

            trace_source_return_path_thread_pong(tmp32);

            break;



        case MIG_RP_MSG_REQ_PAGES:

            start = be64_to_cpup((uint64_t *)buf);

            len = be32_to_cpup((uint32_t *)(buf + 8));

            migrate_handle_rp_req_pages(ms, NULL, start, len);

            break;



        case MIG_RP_MSG_REQ_PAGES_ID:

            expected_len = 12 + 1; /* header + termination */



            if (header_len >= expected_len) {

                start = be64_to_cpup((uint64_t *)buf);

                len = be32_to_cpup((uint32_t *)(buf + 8));

                /* Now we expect an idstr */

                tmp32 = buf[12]; /* Length of the following idstr */

                buf[13 + tmp32] = '\0';

                expected_len += tmp32;

            }

            if (header_len != expected_len) {

                error_report("RP: Req_Page_id with length %d expecting %zd",

                        header_len, expected_len);

                mark_source_rp_bad(ms);

                goto out;

            }

            migrate_handle_rp_req_pages(ms, (char *)&buf[13], start, len);

            break;



        default:

            break;

        }

    }

    if (rp && qemu_file_get_error(rp)) {

        trace_source_return_path_thread_bad_end();

        mark_source_rp_bad(ms);

    }



    trace_source_return_path_thread_end();

out:

    ms->rp_state.from_dst_file = NULL;

    qemu_fclose(rp);

    return NULL;

}

static int bdrv_qed_do_open(BlockDriverState *bs, QDict *options, int flags,

                            Error **errp)

{

    BDRVQEDState *s = bs->opaque;

    QEDHeader le_header;

    int64_t file_size;

    int ret;



    s->bs = bs;

    qemu_co_queue_init(&s->allocating_write_reqs);



    ret = bdrv_pread(bs->file, 0, &le_header, sizeof(le_header));

    if (ret < 0) {

        return ret;

    }

    qed_header_le_to_cpu(&le_header, &s->header);



    if (s->header.magic != QED_MAGIC) {

        error_setg(errp, "Image not in QED format");

        return -EINVAL;

    }

    if (s->header.features & ~QED_FEATURE_MASK) {

        /* image uses unsupported feature bits */

        error_setg(errp, "Unsupported QED features: %" PRIx64,

                   s->header.features & ~QED_FEATURE_MASK);

        return -ENOTSUP;

    }

    if (!qed_is_cluster_size_valid(s->header.cluster_size)) {

        return -EINVAL;

    }



    /* Round down file size to the last cluster */

    file_size = bdrv_getlength(bs->file->bs);

    if (file_size < 0) {

        return file_size;

    }

    s->file_size = qed_start_of_cluster(s, file_size);



    if (!qed_is_table_size_valid(s->header.table_size)) {

        return -EINVAL;

    }

    if (!qed_is_image_size_valid(s->header.image_size,

                                 s->header.cluster_size,

                                 s->header.table_size)) {

        return -EINVAL;

    }

    if (!qed_check_table_offset(s, s->header.l1_table_offset)) {

        return -EINVAL;

    }



    s->table_nelems = (s->header.cluster_size * s->header.table_size) /

                      sizeof(uint64_t);

    s->l2_shift = ctz32(s->header.cluster_size);

    s->l2_mask = s->table_nelems - 1;

    s->l1_shift = s->l2_shift + ctz32(s->table_nelems);



    /* Header size calculation must not overflow uint32_t */

    if (s->header.header_size > UINT32_MAX / s->header.cluster_size) {

        return -EINVAL;

    }



    if ((s->header.features & QED_F_BACKING_FILE)) {

        if ((uint64_t)s->header.backing_filename_offset +

            s->header.backing_filename_size >

            s->header.cluster_size * s->header.header_size) {

            return -EINVAL;

        }



        ret = qed_read_string(bs->file, s->header.backing_filename_offset,

                              s->header.backing_filename_size, bs->backing_file,

                              sizeof(bs->backing_file));

        if (ret < 0) {

            return ret;

        }



        if (s->header.features & QED_F_BACKING_FORMAT_NO_PROBE) {

            pstrcpy(bs->backing_format, sizeof(bs->backing_format), "raw");

        }

    }



    /* Reset unknown autoclear feature bits.  This is a backwards

     * compatibility mechanism that allows images to be opened by older

     * programs, which "knock out" unknown feature bits.  When an image is

     * opened by a newer program again it can detect that the autoclear

     * feature is no longer valid.

     */

    if ((s->header.autoclear_features & ~QED_AUTOCLEAR_FEATURE_MASK) != 0 &&

        !bdrv_is_read_only(bs->file->bs) && !(flags & BDRV_O_INACTIVE)) {

        s->header.autoclear_features &= QED_AUTOCLEAR_FEATURE_MASK;



        ret = qed_write_header_sync(s);

        if (ret) {

            return ret;

        }



        /* From here on only known autoclear feature bits are valid */

        bdrv_flush(bs->file->bs);

    }



    s->l1_table = qed_alloc_table(s);

    qed_init_l2_cache(&s->l2_cache);



    ret = qed_read_l1_table_sync(s);

    if (ret) {

        goto out;

    }



    /* If image was not closed cleanly, check consistency */

    if (!(flags & BDRV_O_CHECK) && (s->header.features & QED_F_NEED_CHECK)) {

        /* Read-only images cannot be fixed.  There is no risk of corruption

         * since write operations are not possible.  Therefore, allow

         * potentially inconsistent images to be opened read-only.  This can

         * aid data recovery from an otherwise inconsistent image.

         */

        if (!bdrv_is_read_only(bs->file->bs) &&

            !(flags & BDRV_O_INACTIVE)) {

            BdrvCheckResult result = {0};



            ret = qed_check(s, &result, true);

            if (ret) {

                goto out;

            }

        }

    }



    bdrv_qed_attach_aio_context(bs, bdrv_get_aio_context(bs));



out:

    if (ret) {

        qed_free_l2_cache(&s->l2_cache);

        qemu_vfree(s->l1_table);

    }

    return ret;

}

