static void virtio_pci_config_write(void *opaque, hwaddr addr,

                                    uint64_t val, unsigned size)

{

    VirtIOPCIProxy *proxy = opaque;

    uint32_t config = VIRTIO_PCI_CONFIG(&proxy->pci_dev);

    VirtIODevice *vdev = virtio_bus_get_device(&proxy->bus);

    if (addr < config) {

        virtio_ioport_write(proxy, addr, val);

        return;

    }

    addr -= config;

    /*

     * Virtio-PCI is odd. Ioports are LE but config space is target native

     * endian.

     */

    switch (size) {

    case 1:

        virtio_config_writeb(vdev, addr, val);

        break;

    case 2:

        if (virtio_is_big_endian()) {

            val = bswap16(val);

        }

        virtio_config_writew(vdev, addr, val);

        break;

    case 4:

        if (virtio_is_big_endian()) {

            val = bswap32(val);

        }

        virtio_config_writel(vdev, addr, val);

        break;

    }

}

void *qpci_iomap(QPCIDevice *dev, int barno, uint64_t *sizeptr)

{

    QPCIBus *bus = dev->bus;

    static const int bar_reg_map[] = {

        PCI_BASE_ADDRESS_0, PCI_BASE_ADDRESS_1, PCI_BASE_ADDRESS_2,

        PCI_BASE_ADDRESS_3, PCI_BASE_ADDRESS_4, PCI_BASE_ADDRESS_5,

    };

    int bar_reg;

    uint32_t addr, size;

    uint32_t io_type;

    uint64_t loc;



    g_assert(barno >= 0 && barno <= 5);

    bar_reg = bar_reg_map[barno];



    qpci_config_writel(dev, bar_reg, 0xFFFFFFFF);

    addr = qpci_config_readl(dev, bar_reg);



    io_type = addr & PCI_BASE_ADDRESS_SPACE;

    if (io_type == PCI_BASE_ADDRESS_SPACE_IO) {

        addr &= PCI_BASE_ADDRESS_IO_MASK;

    } else {

        addr &= PCI_BASE_ADDRESS_MEM_MASK;

    }



    g_assert(addr); /* Must have *some* size bits */



    size = 1U << ctz32(addr);

    if (sizeptr) {

        *sizeptr = size;

    }



    if (io_type == PCI_BASE_ADDRESS_SPACE_IO) {

        loc = QEMU_ALIGN_UP(bus->pio_alloc_ptr, size);



        g_assert(loc >= bus->pio_alloc_ptr);

        g_assert(loc + size <= QPCI_PIO_LIMIT); /* Keep PIO below 64kiB */



        bus->pio_alloc_ptr = loc + size;



        qpci_config_writel(dev, bar_reg, loc | PCI_BASE_ADDRESS_SPACE_IO);

    } else {

        loc = QEMU_ALIGN_UP(bus->mmio_alloc_ptr, size);



        /* Check for space */

        g_assert(loc >= bus->mmio_alloc_ptr);

        g_assert(loc + size <= bus->mmio_limit);



        bus->mmio_alloc_ptr = loc + size;



        qpci_config_writel(dev, bar_reg, loc);

    }



    return (void *)(uintptr_t)loc;

}

static int vhdx_log_flush(BlockDriverState *bs, BDRVVHDXState *s,

                          VHDXLogSequence *logs)

{

    int ret = 0;

    int i;

    uint32_t cnt, sectors_read;

    uint64_t new_file_size;

    void *data = NULL;

    VHDXLogDescEntries *desc_entries = NULL;

    VHDXLogEntryHeader hdr_tmp = { 0 };



    cnt = logs->count;



    data = qemu_blockalign(bs, VHDX_LOG_SECTOR_SIZE);



    ret = vhdx_user_visible_write(bs, s);

    if (ret < 0) {

        goto exit;

    }



    /* each iteration represents one log sequence, which may span multiple

     * sectors */

    while (cnt--) {

        ret = vhdx_log_peek_hdr(bs, &logs->log, &hdr_tmp);

        if (ret < 0) {

            goto exit;

        }

        /* if the log shows a FlushedFileOffset larger than our current file

         * size, then that means the file has been truncated / corrupted, and

         * we must refused to open it / use it */

        if (hdr_tmp.flushed_file_offset > bdrv_getlength(bs->file->bs)) {

            ret = -EINVAL;

            goto exit;

        }



        ret = vhdx_log_read_desc(bs, s, &logs->log, &desc_entries, true);

        if (ret < 0) {

            goto exit;

        }



        for (i = 0; i < desc_entries->hdr.descriptor_count; i++) {

            if (desc_entries->desc[i].signature == VHDX_LOG_DESC_SIGNATURE) {

                /* data sector, so read a sector to flush */

                ret = vhdx_log_read_sectors(bs, &logs->log, &sectors_read,

                                            data, 1, false);

                if (ret < 0) {

                    goto exit;

                }

                if (sectors_read != 1) {

                    ret = -EINVAL;

                    goto exit;

                }

                vhdx_log_data_le_import(data);

            }



            ret = vhdx_log_flush_desc(bs, &desc_entries->desc[i], data);

            if (ret < 0) {

                goto exit;

            }

        }

        if (bdrv_getlength(bs->file->bs) < desc_entries->hdr.last_file_offset) {

            new_file_size = desc_entries->hdr.last_file_offset;

            if (new_file_size % (1024*1024)) {

                /* round up to nearest 1MB boundary */

                new_file_size = ((new_file_size >> 20) + 1) << 20;

                bdrv_truncate(bs->file, new_file_size, PREALLOC_MODE_OFF, NULL);

            }

        }

        qemu_vfree(desc_entries);

        desc_entries = NULL;

    }



    bdrv_flush(bs);

    /* once the log is fully flushed, indicate that we have an empty log

     * now.  This also sets the log guid to 0, to indicate an empty log */

    vhdx_log_reset(bs, s);



exit:

    qemu_vfree(data);

    qemu_vfree(desc_entries);

    return ret;

}

