static void t_gen_cris_dstep(TCGv d, TCGv a, TCGv b)

{

    int l1;



    l1 = gen_new_label();



    /*

     * d <<= 1

     * if (d >= s)

     *    d -= s;

     */

    tcg_gen_shli_tl(d, a, 1);

    tcg_gen_brcond_tl(TCG_COND_LTU, d, b, l1);

    tcg_gen_sub_tl(d, d, b);

    gen_set_label(l1);

}

static always_inline void gen_arith3 (void *helper,

                                      int ra, int rb, int rc,

                                      int islit, uint8_t lit)

{

    if (unlikely(rc == 31))

        return;



    if (ra != 31) {

        if (islit) {

            TCGv tmp = tcg_const_i64(lit);

            tcg_gen_helper_1_2(helper, cpu_ir[rc], cpu_ir[ra], tmp);

            tcg_temp_free(tmp);

        } else

            tcg_gen_helper_1_2(helper, cpu_ir[rc], cpu_ir[ra], cpu_ir[rb]);

    } else {

        TCGv tmp1 = tcg_const_i64(0);

        if (islit) {

            TCGv tmp2 = tcg_const_i64(lit);

            tcg_gen_helper_1_2(helper, cpu_ir[rc], tmp1, tmp2);

            tcg_temp_free(tmp2);

        } else

            tcg_gen_helper_1_2(helper, cpu_ir[rc], tmp1, cpu_ir[rb]);

        tcg_temp_free(tmp1);

    }

}

int cpu_get_dump_info(ArchDumpInfo *info,

                      const struct GuestPhysBlockList *guest_phys_blocks)

{

    PowerPCCPU *cpu = POWERPC_CPU(first_cpu);

    PowerPCCPUClass *pcc = POWERPC_CPU_GET_CLASS(cpu);



    info->d_machine = PPC_ELF_MACHINE;

    info->d_class = ELFCLASS;



    if ((*pcc->interrupts_big_endian)(cpu)) {

        info->d_endian = ELFDATA2MSB;

    } else {

        info->d_endian = ELFDATA2LSB;

    }

    /* 64KB is the max page size for pseries kernel */

    if (strncmp(object_get_typename(qdev_get_machine()),

                "pseries-", 8) == 0) {

        info->page_size = (1U << 16);

    }



    return 0;

}

static CharDriverState *qemu_chr_open_pty(QemuOpts *opts)

{

    CharDriverState *chr;

    PtyCharDriver *s;

    struct termios tty;

    const char *label;

    int master_fd, slave_fd, len;

#if defined(__OpenBSD__) || defined(__DragonFly__)

    char pty_name[PATH_MAX];

#define q_ptsname(x) pty_name

#else

    char *pty_name = NULL;

#define q_ptsname(x) ptsname(x)

#endif



    if (openpty(&master_fd, &slave_fd, pty_name, NULL, NULL) < 0) {

        return NULL;

    }



    /* Set raw attributes on the pty. */

    tcgetattr(slave_fd, &tty);

    cfmakeraw(&tty);

    tcsetattr(slave_fd, TCSAFLUSH, &tty);

    close(slave_fd);



    chr = g_malloc0(sizeof(CharDriverState));



    len = strlen(q_ptsname(master_fd)) + 5;

    chr->filename = g_malloc(len);

    snprintf(chr->filename, len, "pty:%s", q_ptsname(master_fd));

    qemu_opt_set(opts, "path", q_ptsname(master_fd));



    label = qemu_opts_id(opts);

    fprintf(stderr, "char device redirected to %s%s%s%s\n",

            q_ptsname(master_fd),

            label ? " (label " : "",

            label ? label      : "",

            label ? ")"        : "");



    s = g_malloc0(sizeof(PtyCharDriver));

    chr->opaque = s;

    chr->chr_write = pty_chr_write;

    chr->chr_update_read_handler = pty_chr_update_read_handler;

    chr->chr_close = pty_chr_close;

    chr->chr_add_watch = pty_chr_add_watch;



    s->fd = io_channel_from_fd(master_fd);

    s->timer_tag = 0;



    return chr;

}

