    bs->buffer_alignment = 512;



    pstrcpy(bs->filename, sizeof(bs->filename), filename);



    if (use_bdrv_whitelist && !bdrv_is_whitelisted(drv)) {

        return -ENOTSUP;

    }



    bs->drv = drv;

    bs->opaque = qemu_mallocz(drv->instance_size);



    /*

     * Yes, BDRV_O_NOCACHE aka O_DIRECT means we have to present a

     * write cache to the guest.  We do need the fdatasync to flush

     * out transactions for block allocations, and we maybe have a

     * volatile write cache in our backing device to deal with.

     */

    if (flags & (BDRV_O_CACHE_WB|BDRV_O_NOCACHE))

        bs->enable_write_cache = 1;



    /*

     * Clear flags that are internal to the block layer before opening the

     * image.

     */

    open_flags = flags & ~(BDRV_O_SNAPSHOT | BDRV_O_NO_BACKING);



    /*

     * Snapshots should be writeable.

     */

    if (bs->is_temporary) {

        open_flags |= BDRV_O_RDWR;

    }



    /* Open the image, either directly or using a protocol */

    if (drv->bdrv_file_open) {

        ret = drv->bdrv_file_open(bs, filename, open_flags);

    } else {

        ret = bdrv_file_open(&bs->file, filename, open_flags);

        if (ret >= 0) {

            ret = drv->bdrv_open(bs, open_flags);

        }

    }



    if (ret < 0) {

        goto free_and_fail;

    }



    bs->keep_read_only = bs->read_only = !(open_flags & BDRV_O_RDWR);



    ret = refresh_total_sectors(bs, bs->total_sectors);

    if (ret < 0) {

        goto free_and_fail;

    }



#ifndef _WIN32

    if (bs->is_temporary) {

        unlink(filename);

    }

#endif

    return 0;



free_and_fail:

    if (bs->file) {

        bdrv_delete(bs->file);

        bs->file = NULL;

    }

    qemu_free(bs->opaque);

    bs->opaque = NULL;

    bs->drv = NULL;

    return ret;

}

static int qemu_dup_flags(int fd, int flags)

{

    int ret;

    int serrno;

    int dup_flags;

    int setfl_flags;



#ifdef F_DUPFD_CLOEXEC

    ret = fcntl(fd, F_DUPFD_CLOEXEC, 0);

#else

    ret = dup(fd);

    if (ret != -1) {

        qemu_set_cloexec(ret);

    }

#endif

    if (ret == -1) {

        goto fail;

    }



    dup_flags = fcntl(ret, F_GETFL);

    if (dup_flags == -1) {

        goto fail;

    }



    if ((flags & O_SYNC) != (dup_flags & O_SYNC)) {

        errno = EINVAL;

        goto fail;

    }



    /* Set/unset flags that we can with fcntl */

    setfl_flags = O_APPEND | O_ASYNC | O_NONBLOCK;

#ifdef O_NOATIME

    setfl_flags |= O_NOATIME;

#endif

#ifdef O_DIRECT

    setfl_flags |= O_DIRECT;

#endif

    dup_flags &= ~setfl_flags;

    dup_flags |= (flags & setfl_flags);

    if (fcntl(ret, F_SETFL, dup_flags) == -1) {

        goto fail;

    }



    /* Truncate the file in the cases that open() would truncate it */

    if (flags & O_TRUNC ||

            ((flags & (O_CREAT | O_EXCL)) == (O_CREAT | O_EXCL))) {

        if (ftruncate(ret, 0) == -1) {

            goto fail;

        }

    }



    return ret;



fail:

    serrno = errno;

    if (ret != -1) {

        close(ret);

    }

    errno = serrno;

    return -1;

}

void bdrv_query_image_info(BlockDriverState *bs,

                           ImageInfo **p_info,

                           Error **errp)

{

    int64_t size;

    const char *backing_filename;

    BlockDriverInfo bdi;

    int ret;

    Error *err = NULL;

    ImageInfo *info;



    size = bdrv_getlength(bs);

    if (size < 0) {

        error_setg_errno(errp, -size, "Can't get size of device '%s'",

                         bdrv_get_device_name(bs));

        return;

    }



    info = g_new0(ImageInfo, 1);

    info->filename        = g_strdup(bs->filename);

    info->format          = g_strdup(bdrv_get_format_name(bs));

    info->virtual_size    = size;

    info->actual_size     = bdrv_get_allocated_file_size(bs);

    info->has_actual_size = info->actual_size >= 0;

    if (bdrv_is_encrypted(bs)) {

        info->encrypted = true;

        info->has_encrypted = true;

    }

    if (bdrv_get_info(bs, &bdi) >= 0) {

        if (bdi.cluster_size != 0) {

            info->cluster_size = bdi.cluster_size;

            info->has_cluster_size = true;

        }

        info->dirty_flag = bdi.is_dirty;

        info->has_dirty_flag = true;

    }

    info->format_specific     = bdrv_get_specific_info(bs);

    info->has_format_specific = info->format_specific != NULL;



    backing_filename = bs->backing_file;

    if (backing_filename[0] != '\0') {

        char *backing_filename2 = g_malloc0(1024);

        info->backing_filename = g_strdup(backing_filename);

        info->has_backing_filename = true;

        bdrv_get_full_backing_filename(bs, backing_filename2, 1024, &err);

        if (err) {

            error_propagate(errp, err);

            qapi_free_ImageInfo(info);

            g_free(backing_filename2);

            return;

        }



        if (strcmp(backing_filename, backing_filename2) != 0) {

            info->full_backing_filename =

                        g_strdup(backing_filename2);

            info->has_full_backing_filename = true;

        }



        if (bs->backing_format[0]) {

            info->backing_filename_format = g_strdup(bs->backing_format);

            info->has_backing_filename_format = true;

        }

        g_free(backing_filename2);

    }



    ret = bdrv_query_snapshot_info_list(bs, &info->snapshots, &err);

    switch (ret) {

    case 0:

        if (info->snapshots) {

            info->has_snapshots = true;

        }

        break;

    /* recoverable error */

    case -ENOMEDIUM:

    case -ENOTSUP:

        error_free(err);

        break;

    default:

        error_propagate(errp, err);

        qapi_free_ImageInfo(info);

        return;

    }



    *p_info = info;

}

static int vnc_set_x509_credential(VncDisplay *vs,

