        /**************************/

        /* push/pop */

    case 0x50 ... 0x57: /* push */

        gen_op_mov_TN_reg(OT_LONG, 0, (b & 7) | REX_B(s));

        gen_push_T0(s);

        break;

    case 0x58 ... 0x5f: /* pop */

        if (CODE64(s)) {

            ot = dflag ? OT_QUAD : OT_WORD;

        } else {

            ot = dflag + OT_WORD;

