            if ((modrm & 0xc0) != 0xc0)

                goto illegal_op;

            rm = (modrm & 7) | REX_B(s);

            reg = ((modrm >> 3) & 7) | rex_r;

            if (CODE64(s))

                ot = OT_QUAD;

            else

                ot = OT_LONG;

            switch(reg) {

            case 0:

            case 2:

            case 3:

            case 4:

            case 8:

                if (s->cc_op != CC_OP_DYNAMIC)

                    gen_op_set_cc_op(s->cc_op);

                gen_jmp_im(pc_start - s->cs_base);

                if (b & 2) {

                    gen_op_mov_TN_reg(ot, 0, rm);

                    gen_helper_write_crN(tcg_const_i32(reg), cpu_T[0]);

                    gen_jmp_im(s->pc - s->cs_base);

                    gen_eob(s);

                } else {

                    gen_helper_read_crN(cpu_T[0], tcg_const_i32(reg));

                    gen_op_mov_reg_T0(ot, rm);

                }

                break;

            default:

                goto illegal_op;

            }

        }

        break;

    case 0x121: /* mov reg, drN */

    case 0x123: /* mov drN, reg */

        if (s->cpl != 0) {

            gen_exception(s, EXCP0D_GPF, pc_start - s->cs_base);

        } else {

            modrm = ldub_code(s->pc++);

            if ((modrm & 0xc0) != 0xc0)

                goto illegal_op;

            rm = (modrm & 7) | REX_B(s);

            reg = ((modrm >> 3) & 7) | rex_r;

            if (CODE64(s))

                ot = OT_QUAD;

            else

                ot = OT_LONG;

            /* XXX: do it dynamically with CR4.DE bit */

            if (reg == 4 || reg == 5 || reg >= 8)

                goto illegal_op;

            if (b & 2) {

                gen_svm_check_intercept(s, pc_start, SVM_EXIT_WRITE_DR0 + reg);

                gen_op_mov_TN_reg(ot, 0, rm);

                gen_helper_movl_drN_T0(tcg_const_i32(reg), cpu_T[0]);

                gen_jmp_im(s->pc - s->cs_base);

                gen_eob(s);

            } else {

                gen_svm_check_intercept(s, pc_start, SVM_EXIT_READ_DR0 + reg);

                tcg_gen_ld_tl(cpu_T[0], cpu_env, offsetof(CPUX86State,dr[reg]));

                gen_op_mov_reg_T0(ot, rm);

            }

        }

        break;

    case 0x106: /* clts */

        if (s->cpl != 0) {

            gen_exception(s, EXCP0D_GPF, pc_start - s->cs_base);

        } else {

            gen_svm_check_intercept(s, pc_start, SVM_EXIT_WRITE_CR0);

            gen_helper_clts();

            /* abort block because static cpu state changed */

            gen_jmp_im(s->pc - s->cs_base);

            gen_eob(s);

        }

        break;

    /* MMX/3DNow!/SSE/SSE2/SSE3/SSSE3/SSE4 support */

    case 0x1c3: /* MOVNTI reg, mem */

        if (!(s->cpuid_features & CPUID_SSE2))

            goto illegal_op;

        ot = s->dflag == 2 ? OT_QUAD : OT_LONG;

        modrm = ldub_code(s->pc++);

        mod = (modrm >> 6) & 3;

        if (mod == 3)

            goto illegal_op;

        reg = ((modrm >> 3) & 7) | rex_r;

        /* generate a generic store */

        gen_ldst_modrm(s, modrm, ot, reg, 1);

        break;

    case 0x1ae:

        modrm = ldub_code(s->pc++);

        mod = (modrm >> 6) & 3;

        op = (modrm >> 3) & 7;

        switch(op) {

        case 0: /* fxsave */

            if (mod == 3 || !(s->cpuid_features & CPUID_FXSR) ||

                (s->flags & HF_EM_MASK))

                goto illegal_op;

            if (s->flags & HF_TS_MASK) {

                gen_exception(s, EXCP07_PREX, pc_start - s->cs_base);

                break;

            }

            gen_lea_modrm(s, modrm, &reg_addr, &offset_addr);

            if (s->cc_op != CC_OP_DYNAMIC)

                gen_op_set_cc_op(s->cc_op);

            gen_jmp_im(pc_start - s->cs_base);

            gen_helper_fxsave(cpu_A0, tcg_const_i32((s->dflag == 2)));

            break;

        case 1: /* fxrstor */

            if (mod == 3 || !(s->cpuid_features & CPUID_FXSR) ||

                (s->flags & HF_EM_MASK))

                goto illegal_op;

            if (s->flags & HF_TS_MASK) {

                gen_exception(s, EXCP07_PREX, pc_start - s->cs_base);

                break;

            }

            gen_lea_modrm(s, modrm, &reg_addr, &offset_addr);

            if (s->cc_op != CC_OP_DYNAMIC)

                gen_op_set_cc_op(s->cc_op);

            gen_jmp_im(pc_start - s->cs_base);

            gen_helper_fxrstor(cpu_A0, tcg_const_i32((s->dflag == 2)));

            break;

        case 2: /* ldmxcsr */

        case 3: /* stmxcsr */

            if (s->flags & HF_TS_MASK) {

                gen_exception(s, EXCP07_PREX, pc_start - s->cs_base);

                break;

            }

            if ((s->flags & HF_EM_MASK) || !(s->flags & HF_OSFXSR_MASK) ||

                mod == 3)

                goto illegal_op;

            gen_lea_modrm(s, modrm, &reg_addr, &offset_addr);

            if (op == 2) {

                gen_op_ld_T0_A0(OT_LONG + s->mem_index);

                tcg_gen_st32_tl(cpu_T[0], cpu_env, offsetof(CPUX86State, mxcsr));

            } else {

                tcg_gen_ld32u_tl(cpu_T[0], cpu_env, offsetof(CPUX86State, mxcsr));

                gen_op_st_T0_A0(OT_LONG + s->mem_index);

            }

            break;

        case 5: /* lfence */

        case 6: /* mfence */

            if ((modrm & 0xc7) != 0xc0 || !(s->cpuid_features & CPUID_SSE))

                goto illegal_op;

            break;

        case 7: /* sfence / clflush */

            if ((modrm & 0xc7) == 0xc0) {

                /* sfence */

                /* XXX: also check for cpuid_ext2_features & CPUID_EXT2_EMMX */

                if (!(s->cpuid_features & CPUID_SSE))

                    goto illegal_op;

            } else {

                /* clflush */

                if (!(s->cpuid_features & CPUID_CLFLUSH))

                    goto illegal_op;

                gen_lea_modrm(s, modrm, &reg_addr, &offset_addr);

            }

            break;

        default:

            goto illegal_op;

        }

        break;

    case 0x10d: /* 3DNow! prefetch(w) */

        modrm = ldub_code(s->pc++);

        mod = (modrm >> 6) & 3;

        if (mod == 3)

            goto illegal_op;

        gen_lea_modrm(s, modrm, &reg_addr, &offset_addr);

        /* ignore for now */

        break;

    case 0x1aa: /* rsm */

        gen_svm_check_intercept(s, pc_start, SVM_EXIT_RSM);

        if (!(s->flags & HF_SMM_MASK))

            goto illegal_op;

        if (s->cc_op != CC_OP_DYNAMIC) {

            gen_op_set_cc_op(s->cc_op);

            s->cc_op = CC_OP_DYNAMIC;

        }

        gen_jmp_im(s->pc - s->cs_base);

        gen_helper_rsm();

        gen_eob(s);

        break;

    case 0x1b8: /* SSE4.2 popcnt */

        if ((prefixes & (PREFIX_REPZ | PREFIX_LOCK | PREFIX_REPNZ)) !=

             PREFIX_REPZ)

            goto illegal_op;

        if (!(s->cpuid_ext_features & CPUID_EXT_POPCNT))

            goto illegal_op;



        modrm = ldub_code(s->pc++);

        reg = ((modrm >> 3) & 7);



        if (s->prefix & PREFIX_DATA)

            ot = OT_WORD;

        else if (s->dflag != 2)

            ot = OT_LONG;

        else

            ot = OT_QUAD;



        gen_ldst_modrm(s, modrm, ot, OR_TMP0, 0);

        gen_helper_popcnt(cpu_T[0], cpu_T[0], tcg_const_i32(ot));

        gen_op_mov_reg_T0(ot, reg);



        s->cc_op = CC_OP_EFLAGS;

        break;

    case 0x10e ... 0x10f:

        /* 3DNow! instructions, ignore prefixes */

        s->prefix &= ~(PREFIX_REPZ | PREFIX_REPNZ | PREFIX_DATA);

    case 0x110 ... 0x117:

    case 0x128 ... 0x12f:

    case 0x138 ... 0x13a:

    case 0x150 ... 0x177:

    case 0x17c ... 0x17f:

    case 0x1c2:

    case 0x1c4 ... 0x1c6:

    case 0x1d0 ... 0x1fe:

        gen_sse(s, b, pc_start, rex_r);

        break;

    default:

        goto illegal_op;

    }

    /* lock generation */

    if (s->prefix & PREFIX_LOCK)

        gen_helper_unlock();

    return s->pc;

 illegal_op:

    if (s->prefix & PREFIX_LOCK)

        gen_helper_unlock();

    /* XXX: ensure that no lock was generated */

    gen_exception(s, EXCP06_ILLOP, pc_start - s->cs_base);

    return s->pc;

}

static int usb_serial_handle_data(USBDevice *dev, USBPacket *p)

{

    USBSerialState *s = (USBSerialState *)dev;

    int ret = 0;

    uint8_t devep = p->devep;

    uint8_t *data = p->data;

    int len = p->len;

    int first_len;



    switch (p->pid) {

    case USB_TOKEN_OUT:

        if (devep != 2)

            goto fail;

        qemu_chr_write(s->cs, data, len);

        break;



    case USB_TOKEN_IN:

        if (devep != 1)

            goto fail;

        first_len = RECV_BUF - s->recv_ptr;

        if (len <= 2) {

            ret = USB_RET_NAK;

            break;

        }

        *data++ = usb_get_modem_lines(s) | 1;

        /* We do not have the uart details */

        /* handle serial break */

        if (s->event_trigger && s->event_trigger & FTDI_BI) {

            s->event_trigger &= ~FTDI_BI;

            *data = FTDI_BI;

            ret = 2;

            break;

        } else {

            *data++ = 0;

        }

        len -= 2;

        if (len > s->recv_used)

            len = s->recv_used;

        if (!len) {

            ret = USB_RET_NAK;

            break;

        }

        if (first_len > len)

            first_len = len;

        memcpy(data, s->recv_buf + s->recv_ptr, first_len);

        if (len > first_len)

            memcpy(data + first_len, s->recv_buf, len - first_len);

        s->recv_used -= len;

        s->recv_ptr = (s->recv_ptr + len) % RECV_BUF;

        ret = len + 2;

        break;



    default:

        DPRINTF("Bad token\n");

    fail:

        ret = USB_RET_STALL;

        break;

    }



    return ret;

}

void isa_register_portio_list(ISADevice *dev, uint16_t start,

                              const MemoryRegionPortio *pio_start,

                              void *opaque, const char *name)

{

