static int kvm_ppc_register_host_cpu_type(void)

{

    TypeInfo type_info = {

        .name = TYPE_HOST_POWERPC_CPU,

        .instance_init = kvmppc_host_cpu_initfn,

        .class_init = kvmppc_host_cpu_class_init,

    };

    PowerPCCPUClass *pvr_pcc;

    DeviceClass *dc;



    pvr_pcc = kvm_ppc_get_host_cpu_class();

    if (pvr_pcc == NULL) {

        return -1;

    }

    type_info.parent = object_class_get_name(OBJECT_CLASS(pvr_pcc));

    type_register(&type_info);



    /* Register generic family CPU class for a family */

    pvr_pcc = ppc_cpu_get_family_class(pvr_pcc);

    dc = DEVICE_CLASS(pvr_pcc);

    type_info.parent = object_class_get_name(OBJECT_CLASS(pvr_pcc));

    type_info.name = g_strdup_printf("%s-"TYPE_POWERPC_CPU, dc->desc);

    type_register(&type_info);



#if defined(TARGET_PPC64)

    type_info.name = g_strdup_printf("%s-"TYPE_SPAPR_CPU_CORE, "host");

    type_info.parent = TYPE_SPAPR_CPU_CORE,

    type_info.instance_size = sizeof(sPAPRCPUCore),

    type_info.instance_init = spapr_cpu_core_host_initfn,

    type_info.class_init = NULL;

    type_register(&type_info);

    g_free((void *)type_info.name);



    /* Register generic spapr CPU family class for current host CPU type */

    type_info.name = g_strdup_printf("%s-"TYPE_SPAPR_CPU_CORE, dc->desc);

    type_register(&type_info);

    g_free((void *)type_info.name);

#endif



    return 0;

}

static inline int tcg_gen_code_common(TCGContext *s,

                                      tcg_insn_unit *gen_code_buf,

                                      long search_pc)

{

    int oi, oi_next;



#ifdef DEBUG_DISAS

    if (unlikely(qemu_loglevel_mask(CPU_LOG_TB_OP))) {

        qemu_log("OP:\n");

        tcg_dump_ops(s);

        qemu_log("\n");

    }

#endif



#ifdef CONFIG_PROFILER

    s->opt_time -= profile_getclock();

#endif



#ifdef USE_TCG_OPTIMIZATIONS

    tcg_optimize(s);

#endif



#ifdef CONFIG_PROFILER

    s->opt_time += profile_getclock();

    s->la_time -= profile_getclock();

#endif



    tcg_liveness_analysis(s);



#ifdef CONFIG_PROFILER

    s->la_time += profile_getclock();

#endif



#ifdef DEBUG_DISAS

    if (unlikely(qemu_loglevel_mask(CPU_LOG_TB_OP_OPT))) {

        qemu_log("OP after optimization and liveness analysis:\n");

        tcg_dump_ops(s);

        qemu_log("\n");

    }

#endif



    tcg_reg_alloc_start(s);



    s->code_buf = gen_code_buf;

    s->code_ptr = gen_code_buf;



    tcg_out_tb_init(s);



    for (oi = s->gen_first_op_idx; oi >= 0; oi = oi_next) {

        TCGOp * const op = &s->gen_op_buf[oi];

        TCGArg * const args = &s->gen_opparam_buf[op->args];

        TCGOpcode opc = op->opc;

        const TCGOpDef *def = &tcg_op_defs[opc];

        uint16_t dead_args = s->op_dead_args[oi];

        uint8_t sync_args = s->op_sync_args[oi];



        oi_next = op->next;

#ifdef CONFIG_PROFILER

        tcg_table_op_count[opc]++;

#endif



        switch (opc) {

        case INDEX_op_mov_i32:

        case INDEX_op_mov_i64:

            tcg_reg_alloc_mov(s, def, args, dead_args, sync_args);

            break;

        case INDEX_op_movi_i32:

        case INDEX_op_movi_i64:

            tcg_reg_alloc_movi(s, args, dead_args, sync_args);

            break;

        case INDEX_op_debug_insn_start:

            break;

        case INDEX_op_discard:

            temp_dead(s, args[0]);

            break;

        case INDEX_op_set_label:

            tcg_reg_alloc_bb_end(s, s->reserved_regs);

            tcg_out_label(s, args[0], s->code_ptr);

            break;

        case INDEX_op_call:

            tcg_reg_alloc_call(s, op->callo, op->calli, args,

                               dead_args, sync_args);

            break;

        default:

            /* Sanity check that we've not introduced any unhandled opcodes. */

            if (def->flags & TCG_OPF_NOT_PRESENT) {

                tcg_abort();

            }

            /* Note: in order to speed up the code, it would be much

               faster to have specialized register allocator functions for

               some common argument patterns */

            tcg_reg_alloc_op(s, def, opc, args, dead_args, sync_args);

            break;

        }

        if (search_pc >= 0 && search_pc < tcg_current_code_size(s)) {

            return oi;

        }

#ifndef NDEBUG

        check_regs(s);

#endif

    }



    /* Generate TB finalization at the end of block */

    tcg_out_tb_finalize(s);

    return -1;

}

void timer_mod_anticipate_ns(QEMUTimer *ts, int64_t expire_time)

{

    QEMUTimerList *timer_list = ts->timer_list;

    bool rearm;



    qemu_mutex_lock(&timer_list->active_timers_lock);

    if (ts->expire_time == -1 || ts->expire_time > expire_time) {

        if (ts->expire_time != -1) {

            timer_del_locked(timer_list, ts);

        }

        rearm = timer_mod_ns_locked(timer_list, ts, expire_time);

    } else {

        rearm = false;

    }

    qemu_mutex_unlock(&timer_list->active_timers_lock);



    if (rearm) {

        timerlist_rearm(timer_list);

    }

}

static void pxa2xx_rtc_write(void *opaque, hwaddr addr,

                             uint64_t value64, unsigned size)

{

    PXA2xxRTCState *s = (PXA2xxRTCState *) opaque;

    uint32_t value = value64;



    switch (addr) {

    case RTTR:

        if (!(s->rttr & (1U << 31))) {

            pxa2xx_rtc_hzupdate(s);

            s->rttr = value;

            pxa2xx_rtc_alarm_update(s, s->rtsr);

        }

        break;



    case RTSR:

        if ((s->rtsr ^ value) & (1 << 15))

            pxa2xx_rtc_piupdate(s);



        if ((s->rtsr ^ value) & (1 << 12))

            pxa2xx_rtc_swupdate(s);



        if (((s->rtsr ^ value) & 0x4aac) | (value & ~0xdaac))

            pxa2xx_rtc_alarm_update(s, value);



        s->rtsr = (value & 0xdaac) | (s->rtsr & ~(value & ~0xdaac));

        pxa2xx_rtc_int_update(s);

        break;



    case RTAR:

        s->rtar = value;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    case RDAR1:

        s->rdar1 = value;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    case RDAR2:

        s->rdar2 = value;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    case RYAR1:

        s->ryar1 = value;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    case RYAR2:

        s->ryar2 = value;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    case SWAR1:

        pxa2xx_rtc_swupdate(s);

        s->swar1 = value;

        s->last_swcr = 0;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    case SWAR2:

        s->swar2 = value;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    case PIAR:

        s->piar = value;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    case RCNR:

        pxa2xx_rtc_hzupdate(s);

        s->last_rcnr = value;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    case RDCR:

        pxa2xx_rtc_hzupdate(s);

        s->last_rdcr = value;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    case RYCR:

        s->last_rycr = value;

        break;



    case SWCR:

        pxa2xx_rtc_swupdate(s);

        s->last_swcr = value;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    case RTCPICR:

        pxa2xx_rtc_piupdate(s);

        s->last_rtcpicr = value & 0xffff;

        pxa2xx_rtc_alarm_update(s, s->rtsr);

        break;



    default:

        printf("%s: Bad register " REG_FMT "\n", __FUNCTION__, addr);

    }

}

static void omap_disc_write(void *opaque, hwaddr addr,

                            uint64_t value, unsigned size)

{

    struct omap_dss_s *s = (struct omap_dss_s *) opaque;



    if (size != 4) {

        omap_badwidth_write32(opaque, addr, value);

        return;

    }



    switch (addr) {

    case 0x010:	/* DISPC_SYSCONFIG */

        if (value & 2)						/* SOFTRESET */

            omap_dss_reset(s);

        s->dispc.idlemode = value & 0x301b;

        break;



    case 0x018:	/* DISPC_IRQSTATUS */

        s->dispc.irqst &= ~value;

        omap_dispc_interrupt_update(s);

        break;



    case 0x01c:	/* DISPC_IRQENABLE */

        s->dispc.irqen = value & 0xffff;

        omap_dispc_interrupt_update(s);

        break;



    case 0x040:	/* DISPC_CONTROL */

        s->dispc.control = value & 0x07ff9fff;

        s->dig.enable = (value >> 1) & 1;

        s->lcd.enable = (value >> 0) & 1;

        if (value & (1 << 12))			/* OVERLAY_OPTIMIZATION */

            if (!((s->dispc.l[1].attr | s->dispc.l[2].attr) & 1)) {

                fprintf(stderr, "%s: Overlay Optimization when no overlay "

                        "region effectively exists leads to "

                        "unpredictable behaviour!\n", __func__);

            }

        if (value & (1 << 6)) {				/* GODIGITAL */

            /* XXX: Shadowed fields are:

             * s->dispc.config

             * s->dispc.capable

             * s->dispc.bg[0]

             * s->dispc.bg[1]

             * s->dispc.trans[0]

             * s->dispc.trans[1]

             * s->dispc.line

             * s->dispc.timing[0]

             * s->dispc.timing[1]

             * s->dispc.timing[2]

             * s->dispc.timing[3]

             * s->lcd.nx

             * s->lcd.ny

             * s->dig.nx

             * s->dig.ny

             * s->dispc.l[0].addr[0]

             * s->dispc.l[0].addr[1]

             * s->dispc.l[0].addr[2]

             * s->dispc.l[0].posx

             * s->dispc.l[0].posy

             * s->dispc.l[0].nx

             * s->dispc.l[0].ny

             * s->dispc.l[0].tresh

             * s->dispc.l[0].rowinc

             * s->dispc.l[0].colinc

             * s->dispc.l[0].wininc

             * All they need to be loaded here from their shadow registers.

             */

        }

        if (value & (1 << 5)) {				/* GOLCD */

             /* XXX: Likewise for LCD here.  */

        }

        s->dispc.invalidate = 1;

        break;



    case 0x044:	/* DISPC_CONFIG */

        s->dispc.config = value & 0x3fff;

        /* XXX:

         * bits 2:1 (LOADMODE) reset to 0 after set to 1 and palette loaded

         * bits 2:1 (LOADMODE) reset to 2 after set to 3 and palette loaded

         */

        s->dispc.invalidate = 1;

        break;



    case 0x048:	/* DISPC_CAPABLE */

        s->dispc.capable = value & 0x3ff;

        break;



    case 0x04c:	/* DISPC_DEFAULT_COLOR0 */

        s->dispc.bg[0] = value & 0xffffff;

        s->dispc.invalidate = 1;

        break;

    case 0x050:	/* DISPC_DEFAULT_COLOR1 */

        s->dispc.bg[1] = value & 0xffffff;

        s->dispc.invalidate = 1;

        break;

    case 0x054:	/* DISPC_TRANS_COLOR0 */

        s->dispc.trans[0] = value & 0xffffff;

        s->dispc.invalidate = 1;

        break;

    case 0x058:	/* DISPC_TRANS_COLOR1 */

        s->dispc.trans[1] = value & 0xffffff;

        s->dispc.invalidate = 1;

        break;



    case 0x060:	/* DISPC_LINE_NUMBER */

        s->dispc.line = value & 0x7ff;

        break;



    case 0x064:	/* DISPC_TIMING_H */

        s->dispc.timing[0] = value & 0x0ff0ff3f;

        break;

    case 0x068:	/* DISPC_TIMING_V */

        s->dispc.timing[1] = value & 0x0ff0ff3f;

        break;

    case 0x06c:	/* DISPC_POL_FREQ */

        s->dispc.timing[2] = value & 0x0003ffff;

        break;

    case 0x070:	/* DISPC_DIVISOR */

        s->dispc.timing[3] = value & 0x00ff00ff;

        break;



    case 0x078:	/* DISPC_SIZE_DIG */

        s->dig.nx = ((value >>  0) & 0x7ff) + 1;		/* PPL */

        s->dig.ny = ((value >> 16) & 0x7ff) + 1;		/* LPP */

        s->dispc.invalidate = 1;

        break;

    case 0x07c:	/* DISPC_SIZE_LCD */

        s->lcd.nx = ((value >>  0) & 0x7ff) + 1;		/* PPL */

        s->lcd.ny = ((value >> 16) & 0x7ff) + 1;		/* LPP */

        s->dispc.invalidate = 1;

        break;

    case 0x080:	/* DISPC_GFX_BA0 */

        s->dispc.l[0].addr[0] = (hwaddr) value;

        s->dispc.invalidate = 1;

        break;

    case 0x084:	/* DISPC_GFX_BA1 */

        s->dispc.l[0].addr[1] = (hwaddr) value;

        s->dispc.invalidate = 1;

        break;

    case 0x088:	/* DISPC_GFX_POSITION */

        s->dispc.l[0].posx = ((value >>  0) & 0x7ff);		/* GFXPOSX */

        s->dispc.l[0].posy = ((value >> 16) & 0x7ff);		/* GFXPOSY */

        s->dispc.invalidate = 1;

        break;

    case 0x08c:	/* DISPC_GFX_SIZE */

        s->dispc.l[0].nx = ((value >>  0) & 0x7ff) + 1;		/* GFXSIZEX */

        s->dispc.l[0].ny = ((value >> 16) & 0x7ff) + 1;		/* GFXSIZEY */

        s->dispc.invalidate = 1;

        break;

    case 0x0a0:	/* DISPC_GFX_ATTRIBUTES */

        s->dispc.l[0].attr = value & 0x7ff;

        if (value & (3 << 9))

            fprintf(stderr, "%s: Big-endian pixel format not supported\n",

                            __FUNCTION__);

        s->dispc.l[0].enable = value & 1;

        s->dispc.l[0].bpp = (value >> 1) & 0xf;

        s->dispc.invalidate = 1;

        break;

    case 0x0a4:	/* DISPC_GFX_FIFO_TRESHOLD */

        s->dispc.l[0].tresh = value & 0x01ff01ff;

        break;

    case 0x0ac:	/* DISPC_GFX_ROW_INC */

        s->dispc.l[0].rowinc = value;

        s->dispc.invalidate = 1;

        break;

    case 0x0b0:	/* DISPC_GFX_PIXEL_INC */

        s->dispc.l[0].colinc = value;

        s->dispc.invalidate = 1;

        break;

    case 0x0b4:	/* DISPC_GFX_WINDOW_SKIP */

        s->dispc.l[0].wininc = value;

        break;

    case 0x0b8:	/* DISPC_GFX_TABLE_BA */

        s->dispc.l[0].addr[2] = (hwaddr) value;

        s->dispc.invalidate = 1;

        break;



    case 0x0bc:	/* DISPC_VID1_BA0 */

    case 0x0c0:	/* DISPC_VID1_BA1 */

    case 0x0c4:	/* DISPC_VID1_POSITION */

    case 0x0c8:	/* DISPC_VID1_SIZE */

    case 0x0cc:	/* DISPC_VID1_ATTRIBUTES */

    case 0x0d0:	/* DISPC_VID1_FIFO_TRESHOLD */

    case 0x0d8:	/* DISPC_VID1_ROW_INC */

    case 0x0dc:	/* DISPC_VID1_PIXEL_INC */

    case 0x0e0:	/* DISPC_VID1_FIR */

    case 0x0e4:	/* DISPC_VID1_PICTURE_SIZE */

    case 0x0e8:	/* DISPC_VID1_ACCU0 */

    case 0x0ec:	/* DISPC_VID1_ACCU1 */

    case 0x0f0 ... 0x140:	/* DISPC_VID1_FIR_COEF, DISPC_VID1_CONV_COEF */

    case 0x14c:	/* DISPC_VID2_BA0 */

    case 0x150:	/* DISPC_VID2_BA1 */

    case 0x154:	/* DISPC_VID2_POSITION */

    case 0x158:	/* DISPC_VID2_SIZE */

    case 0x15c:	/* DISPC_VID2_ATTRIBUTES */

    case 0x160:	/* DISPC_VID2_FIFO_TRESHOLD */

    case 0x168:	/* DISPC_VID2_ROW_INC */

    case 0x16c:	/* DISPC_VID2_PIXEL_INC */

    case 0x170:	/* DISPC_VID2_FIR */

    case 0x174:	/* DISPC_VID2_PICTURE_SIZE */

    case 0x178:	/* DISPC_VID2_ACCU0 */

    case 0x17c:	/* DISPC_VID2_ACCU1 */

    case 0x180 ... 0x1d0:	/* DISPC_VID2_FIR_COEF, DISPC_VID2_CONV_COEF */

    case 0x1d4:	/* DISPC_DATA_CYCLE1 */

    case 0x1d8:	/* DISPC_DATA_CYCLE2 */

    case 0x1dc:	/* DISPC_DATA_CYCLE3 */

        break;



    default:

        OMAP_BAD_REG(addr);

    }

}

static void bdrv_replace_child(BdrvChild *child, BlockDriverState *new_bs,

                               bool check_new_perm)

{

    BlockDriverState *old_bs = child->bs;

    uint64_t perm, shared_perm;



    if (old_bs) {

        /* Update permissions for old node. This is guaranteed to succeed

         * because we're just taking a parent away, so we're loosening

         * restrictions. */

        bdrv_get_cumulative_perm(old_bs, &perm, &shared_perm);

        bdrv_check_perm(old_bs, perm, shared_perm, NULL, &error_abort);

        bdrv_set_perm(old_bs, perm, shared_perm);

    }



    bdrv_replace_child_noperm(child, new_bs);



    if (new_bs) {

        bdrv_get_cumulative_perm(new_bs, &perm, &shared_perm);

        if (check_new_perm) {

            bdrv_check_perm(new_bs, perm, shared_perm, NULL, &error_abort);

        }

        bdrv_set_perm(new_bs, perm, shared_perm);

    }

}

void cpu_exec_init(CPUState *cpu, Error **errp)

{

    CPUClass *cc = CPU_GET_CLASS(cpu);

