static void cirrus_invalidate_region(CirrusVGAState * s, int off_begin,

				     int off_pitch, int bytesperline,

				     int lines)

{

    int y;

    int off_cur;

    int off_cur_end;



    for (y = 0; y < lines; y++) {

	off_cur = off_begin;

	off_cur_end = off_cur + bytesperline;

	off_cur &= TARGET_PAGE_MASK;

	while (off_cur < off_cur_end) {

	    cpu_physical_memory_set_dirty(s->vram_offset + off_cur);

	    off_cur += TARGET_PAGE_SIZE;

	}

	off_begin += off_pitch;

    }

}

void error_set_win32(Error **errp, int win32_err, ErrorClass err_class,

                     const char *fmt, ...)

{

    va_list ap;

    char *msg1, *msg2;



    if (errp == NULL) {

        return;

    }



    va_start(ap, fmt);

    error_setv(errp, err_class, fmt, ap);

    va_end(ap);



    if (win32_err != 0) {

        msg1 = (*errp)->msg;

        msg2 = g_win32_error_message(win32_err);

        (*errp)->msg = g_strdup_printf("%s: %s (error: %x)", msg1, msg2,

                                       (unsigned)win32_err);

        g_free(msg2);

        g_free(msg1);

    }

}

static int qio_channel_socket_dgram_worker(QIOTask *task,

                                           Error **errp,

                                           gpointer opaque)

{

    QIOChannelSocket *ioc = QIO_CHANNEL_SOCKET(qio_task_get_source(task));

    struct QIOChannelSocketDGramWorkerData *data = opaque;

    int ret;



    /* socket_dgram() blocks in DNS lookups, so we must use a thread */

    ret = qio_channel_socket_dgram_sync(ioc,

                                        data->localAddr,

                                        data->remoteAddr,

                                        errp);



    object_unref(OBJECT(ioc));

    return ret;

}

