    return phys_sections[index & ~TARGET_PAGE_MASK].mr;

}

static void *do_data_compress(void *opaque)

{

    CompressParam *param = opaque;



    while (!quit_comp_thread) {

        qemu_mutex_lock(&param->mutex);

        /* Re-check the quit_comp_thread in case of

         * terminate_compression_threads is called just before

         * qemu_mutex_lock(&param->mutex) and after

         * while(!quit_comp_thread), re-check it here can make

         * sure the compression thread terminate as expected.

         */

        while (!param->start && !quit_comp_thread) {

            qemu_cond_wait(&param->cond, &param->mutex);

        }

        if (!quit_comp_thread) {

            do_compress_ram_page(param);

        }

        param->start = false;

        qemu_mutex_unlock(&param->mutex);



        qemu_mutex_lock(comp_done_lock);

        param->done = true;

        qemu_cond_signal(comp_done_cond);

        qemu_mutex_unlock(comp_done_lock);

    }



    return NULL;

}

int nbd_client_session_co_readv(NbdClientSession *client, int64_t sector_num,

    int nb_sectors, QEMUIOVector *qiov)

{

    int offset = 0;

    int ret;

    while (nb_sectors > NBD_MAX_SECTORS) {

        ret = nbd_co_readv_1(client, sector_num,

                             NBD_MAX_SECTORS, qiov, offset);

        if (ret < 0) {

            return ret;

        }

        offset += NBD_MAX_SECTORS * 512;

        sector_num += NBD_MAX_SECTORS;

        nb_sectors -= NBD_MAX_SECTORS;

    }

    return nbd_co_readv_1(client, sector_num, nb_sectors, qiov, offset);

}

static int find_pte64(CPUPPCState *env, struct mmu_ctx_hash64 *ctx,

                      ppc_slb_t *slb, target_ulong eaddr, int rwx)

{

    hwaddr pteg_off, pte_offset;

    ppc_hash_pte64_t pte;

    uint64_t vsid, pageaddr, ptem;

    hwaddr hash;

    int segment_bits, target_page_bits;

    int ret;



    ret = -1; /* No entry found */



    if (slb->vsid & SLB_VSID_B) {

        vsid = (slb->vsid & SLB_VSID_VSID) >> SLB_VSID_SHIFT_1T;

        segment_bits = 40;

    } else {

        vsid = (slb->vsid & SLB_VSID_VSID) >> SLB_VSID_SHIFT;

        segment_bits = 28;

    }



    target_page_bits = (slb->vsid & SLB_VSID_L)

        ? TARGET_PAGE_BITS_16M : TARGET_PAGE_BITS;

    ctx->key = !!(msr_pr ? (slb->vsid & SLB_VSID_KP)

                  : (slb->vsid & SLB_VSID_KS));



    pageaddr = eaddr & ((1ULL << segment_bits)

                            - (1ULL << target_page_bits));

    if (slb->vsid & SLB_VSID_B) {

        hash = vsid ^ (vsid << 25) ^ (pageaddr >> target_page_bits);

    } else {

        hash = vsid ^ (pageaddr >> target_page_bits);

    }

    /* Only 5 bits of the page index are used in the AVPN */

    ptem = (slb->vsid & SLB_VSID_PTEM) |

        ((pageaddr >> 16) & ((1ULL << segment_bits) - 0x80));



    ret = -1;



    /* Page address translation */

    LOG_MMU("htab_base " TARGET_FMT_plx " htab_mask " TARGET_FMT_plx

            " hash " TARGET_FMT_plx "\n",

            env->htab_base, env->htab_mask, hash);





    /* Primary PTEG lookup */

    LOG_MMU("0 htab=" TARGET_FMT_plx "/" TARGET_FMT_plx

            " vsid=" TARGET_FMT_lx " ptem=" TARGET_FMT_lx

            " hash=" TARGET_FMT_plx "\n",

            env->htab_base, env->htab_mask, vsid, ptem,  hash);

    pteg_off = (hash * HASH_PTEG_SIZE_64) & env->htab_mask;

    pte_offset = ppc_hash64_pteg_search(env, pteg_off, 0, ptem, &pte);

    if (pte_offset == -1) {

        /* Secondary PTEG lookup */

        LOG_MMU("1 htab=" TARGET_FMT_plx "/" TARGET_FMT_plx

                " vsid=" TARGET_FMT_lx " api=" TARGET_FMT_lx

                " hash=" TARGET_FMT_plx "\n", env->htab_base,

                env->htab_mask, vsid, ptem, ~hash);



        pteg_off = (~hash * HASH_PTEG_SIZE_64) & env->htab_mask;

        pte_offset = ppc_hash64_pteg_search(env, pteg_off, 1, ptem, &pte);

    }



    if (pte_offset != -1) {

        ret = pte64_check(ctx, pte.pte0, pte.pte1, rwx);

        LOG_MMU("found PTE at addr %08" HWADDR_PRIx " prot=%01x ret=%d\n",

                ctx->raddr, ctx->prot, ret);

        /* Update page flags */

        if (ppc_hash64_pte_update_flags(ctx, &pte.pte1, ret, rwx) == 1) {

            ppc_hash64_store_hpte1(env, pte_offset, pte.pte1);

        }

    }



    /* We have a TLB that saves 4K pages, so let's

     * split a huge page to 4k chunks */

    if (target_page_bits != TARGET_PAGE_BITS) {

        ctx->raddr |= (eaddr & ((1 << target_page_bits) - 1))

                      & TARGET_PAGE_MASK;

    }

    return ret;

}

static int monitor_check_qmp_args(const mon_cmd_t *cmd, QDict *args)

{

    int err;

    const char *p;

    CmdArgs cmd_args;

    QemuOptsList *opts_list;



    if (cmd->args_type == NULL) {

        return (qdict_size(args) == 0 ? 0 : -1);

    }



    err = 0;

    cmd_args_init(&cmd_args);

    opts_list = NULL;



    for (p = cmd->args_type;; p++) {

        if (*p == ':') {

            cmd_args.type = *++p;

            p++;

            if (cmd_args.type == '-') {

                cmd_args.flag = *p++;

                cmd_args.optional = 1;

            } else if (cmd_args.type == 'O') {

                opts_list = qemu_find_opts(qstring_get_str(cmd_args.name));

                assert(opts_list);

            } else if (*p == '?') {

                cmd_args.optional = 1;

                p++;

            }



            assert(*p == ',' || *p == '\0');

            if (opts_list) {

                err = check_opts(opts_list, args);

                opts_list = NULL;

            } else {

                err = check_arg(&cmd_args, args);

                QDECREF(cmd_args.name);

                cmd_args_init(&cmd_args);

            }



            if (err < 0) {

                break;

            }

        } else {

            qstring_append_chr(cmd_args.name, *p);

        }



        if (*p == '\0') {

            break;

        }

    }



    QDECREF(cmd_args.name);

    return err;

}

static void dec_bcc(DisasContext *dc)

{

    unsigned int cc;

    unsigned int dslot;



    cc = EXTRACT_FIELD(dc->ir, 21, 23);

    dslot = dc->ir & (1 << 25);

    LOG_DIS("bcc%s r%d %x\n", dslot ? "d" : "", dc->ra, dc->imm);



    dc->delayed_branch = 1;

    if (dslot) {

        dc->delayed_branch = 2;

        dc->tb_flags |= D_FLAG;

        tcg_gen_st_tl(tcg_const_tl(dc->type_b && (dc->tb_flags & IMM_FLAG)),

                      cpu_env, offsetof(CPUState, bimm));

    }



    if (dec_alu_op_b_is_small_imm(dc)) {

        int32_t offset = (int32_t)((int16_t)dc->imm); /* sign-extend.  */



        tcg_gen_movi_tl(env_btarget, dc->pc + offset);

    } else {

        tcg_gen_movi_tl(env_btarget, dc->pc);

        tcg_gen_add_tl(env_btarget, env_btarget, *(dec_alu_op_b(dc)));

    }

    dc->jmp = JMP_INDIRECT;

    eval_cc(dc, cc, env_btaken, cpu_R[dc->ra], tcg_const_tl(0));

}

static int buffered_put_buffer(void *opaque, const uint8_t *buf, int64_t pos, int size)

{

    QEMUFileBuffered *s = opaque;

    ssize_t error;



    DPRINTF("putting %d bytes at %" PRId64 "\n", size, pos);



    error = qemu_file_get_error(s->file);

    if (error) {

        DPRINTF("flush when error, bailing: %s\n", strerror(-error));

        return error;

    }



    if (size <= 0) {

        return size;

    }



    if (size > (s->buffer_capacity - s->buffer_size)) {

        DPRINTF("increasing buffer capacity from %zu by %zu\n",

                s->buffer_capacity, size + 1024);



        s->buffer_capacity += size + 1024;



        s->buffer = g_realloc(s->buffer, s->buffer_capacity);

    }



    memcpy(s->buffer + s->buffer_size, buf, size);

    s->buffer_size += size;



    return size;

}

