static coroutine_fn void do_co_req(void *opaque)

{

    int ret;

    Coroutine *co;

    SheepdogReqCo *srco = opaque;

    int sockfd = srco->sockfd;

    SheepdogReq *hdr = srco->hdr;

    void *data = srco->data;

    unsigned int *wlen = srco->wlen;

    unsigned int *rlen = srco->rlen;



    co = qemu_coroutine_self();

    qemu_aio_set_fd_handler(sockfd, NULL, restart_co_req, co);



    ret = send_co_req(sockfd, hdr, data, wlen);

    if (ret < 0) {

        goto out;

    }



    qemu_aio_set_fd_handler(sockfd, restart_co_req, NULL, co);



    ret = qemu_co_recv(sockfd, hdr, sizeof(*hdr));

    if (ret < sizeof(*hdr)) {

        error_report("failed to get a rsp, %s", strerror(errno));

        ret = -errno;

        goto out;

    }



    if (*rlen > hdr->data_length) {

        *rlen = hdr->data_length;

    }



    if (*rlen) {

        ret = qemu_co_recv(sockfd, data, *rlen);

        if (ret < *rlen) {

            error_report("failed to get the data, %s", strerror(errno));

            ret = -errno;

            goto out;

        }

    }

    ret = 0;

out:

    /* there is at most one request for this sockfd, so it is safe to

     * set each handler to NULL. */

    qemu_aio_set_fd_handler(sockfd, NULL, NULL, NULL);



    srco->ret = ret;

    srco->finished = true;

}

void commit_start(const char *job_id, BlockDriverState *bs,

                  BlockDriverState *base, BlockDriverState *top, int64_t speed,

                  BlockdevOnError on_error, BlockCompletionFunc *cb,

                  void *opaque, const char *backing_file_str, Error **errp)

{

    CommitBlockJob *s;

    BlockReopenQueue *reopen_queue = NULL;

    int orig_overlay_flags;

    int orig_base_flags;

    BlockDriverState *overlay_bs;

    Error *local_err = NULL;



    assert(top != bs);

    if (top == base) {

        error_setg(errp, "Invalid files for merge: top and base are the same");

        return;

    }



    overlay_bs = bdrv_find_overlay(bs, top);



    if (overlay_bs == NULL) {

        error_setg(errp, "Could not find overlay image for %s:", top->filename);

        return;

    }



    s = block_job_create(job_id, &commit_job_driver, bs, speed,

                         cb, opaque, errp);

    if (!s) {

        return;

    }



    orig_base_flags    = bdrv_get_flags(base);

    orig_overlay_flags = bdrv_get_flags(overlay_bs);



    /* convert base & overlay_bs to r/w, if necessary */

    if (!(orig_overlay_flags & BDRV_O_RDWR)) {

        reopen_queue = bdrv_reopen_queue(reopen_queue, overlay_bs, NULL,

                                         orig_overlay_flags | BDRV_O_RDWR);

    }

    if (!(orig_base_flags & BDRV_O_RDWR)) {

        reopen_queue = bdrv_reopen_queue(reopen_queue, base, NULL,

                                         orig_base_flags | BDRV_O_RDWR);

    }

    if (reopen_queue) {

        bdrv_reopen_multiple(reopen_queue, &local_err);

        if (local_err != NULL) {

            error_propagate(errp, local_err);

            block_job_unref(&s->common);

            return;

        }

    }





    s->base = blk_new();

    blk_insert_bs(s->base, base);



    s->top = blk_new();

    blk_insert_bs(s->top, top);



    s->active = bs;



    s->base_flags          = orig_base_flags;

    s->orig_overlay_flags  = orig_overlay_flags;



    s->backing_file_str = g_strdup(backing_file_str);



    s->on_error = on_error;

    s->common.co = qemu_coroutine_create(commit_run);



    trace_commit_start(bs, base, top, s, s->common.co, opaque);

    qemu_coroutine_enter(s->common.co, s);

}

static void virtio_balloon_set_config(VirtIODevice *vdev,

                                      const uint8_t *config_data)

{

    VirtIOBalloon *dev = VIRTIO_BALLOON(vdev);

    struct virtio_balloon_config config;

    uint32_t oldactual = dev->actual;

    memcpy(&config, config_data, 8);

    dev->actual = le32_to_cpu(config.actual);

    if (dev->actual != oldactual) {

        qemu_balloon_changed(ram_size -

                             (dev->actual << VIRTIO_BALLOON_PFN_SHIFT));

    }

}

static ssize_t qio_channel_websock_read_wire(QIOChannelWebsock *ioc,

                                             Error **errp)

{

    ssize_t ret;



    if (ioc->encinput.offset < 4096) {

        size_t want = 4096 - ioc->encinput.offset;



        buffer_reserve(&ioc->encinput, want);

        ret = qio_channel_read(ioc->master,

                               (char *)ioc->encinput.buffer +

                               ioc->encinput.offset,

                               want,

                               errp);

        if (ret < 0) {

            return ret;

        }

        if (ret == 0 &&

            ioc->encinput.offset == 0) {

            return 0;

        }

        ioc->encinput.offset += ret;

    }



    while (ioc->encinput.offset != 0) {

        if (ioc->payload_remain == 0) {

            ret = qio_channel_websock_decode_header(ioc, errp);

            if (ret < 0) {

                return ret;

            }

            if (ret == 0) {

                ioc->io_eof = TRUE;

                break;

            }

        }



        ret = qio_channel_websock_decode_payload(ioc, errp);

        if (ret < 0) {

            return ret;

        }

    }

    return 1;

}

int qcow2_snapshot_delete(BlockDriverState *bs, const char *snapshot_id)

{

    BDRVQcowState *s = bs->opaque;

    QCowSnapshot sn;

    int snapshot_index, ret;



    /* Search the snapshot */

    snapshot_index = find_snapshot_by_id_or_name(bs, snapshot_id);

    if (snapshot_index < 0) {

        return -ENOENT;

    }

    sn = s->snapshots[snapshot_index];



    /* Remove it from the snapshot list */

    memmove(s->snapshots + snapshot_index,

            s->snapshots + snapshot_index + 1,

            (s->nb_snapshots - snapshot_index - 1) * sizeof(sn));

    s->nb_snapshots--;

    ret = qcow2_write_snapshots(bs);

    if (ret < 0) {

        return ret;

    }



    /*

     * The snapshot is now unused, clean up. If we fail after this point, we

     * won't recover but just leak clusters.

     */

    g_free(sn.id_str);

    g_free(sn.name);



    /*

     * Now decrease the refcounts of clusters referenced by the snapshot and

     * free the L1 table.

     */

    ret = qcow2_update_snapshot_refcount(bs, sn.l1_table_offset,

                                         sn.l1_size, -1);

    if (ret < 0) {

        return ret;

    }

    qcow2_free_clusters(bs, sn.l1_table_offset, sn.l1_size * sizeof(uint64_t));



    /* must update the copied flag on the current cluster offsets */

    ret = qcow2_update_snapshot_refcount(bs, s->l1_table_offset, s->l1_size, 0);

    if (ret < 0) {

        return ret;

    }



#ifdef DEBUG_ALLOC

    {

        BdrvCheckResult result = {0};

        qcow2_check_refcounts(bs, &result);

    }

#endif

    return 0;

}

static void rtas_ibm_read_pci_config(sPAPREnvironment *spapr,

                                     uint32_t token, uint32_t nargs,

                                     target_ulong args,

                                     uint32_t nret, target_ulong rets)

{

    uint32_t val, size, addr;

    uint64_t buid = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 2);

    PCIDevice *dev = find_dev(spapr, buid, rtas_ld(args, 0));



    if (!dev) {

        rtas_st(rets, 0, -1);

        return;

    }

    size = rtas_ld(args, 3);

    addr = rtas_pci_cfgaddr(rtas_ld(args, 0));

    val = pci_default_read_config(dev, addr, size);

    rtas_st(rets, 0, 0);

    rtas_st(rets, 1, val);

}

static int64_t get_remaining_dirty(void)

{

    BlkMigDevState *bmds;

    int64_t dirty = 0;



    QSIMPLEQ_FOREACH(bmds, &block_mig_state.bmds_list, entry) {

        dirty += bdrv_get_dirty_count(bmds->bs, bmds->dirty_bitmap);

    }



    return dirty << BDRV_SECTOR_BITS;

}

int arm_set_cpu_on(uint64_t cpuid, uint64_t entry, uint64_t context_id,

                   uint32_t target_el, bool target_aa64)

{

    CPUState *target_cpu_state;

    ARMCPU *target_cpu;



    DPRINTF("cpu %" PRId64 " (EL %d, %s) @ 0x%" PRIx64 " with R0 = 0x%" PRIx64

            "\n", cpuid, target_el, target_aa64 ? "aarch64" : "aarch32", entry,

            context_id);



    /* requested EL level need to be in the 1 to 3 range */

    assert((target_el > 0) && (target_el < 4));



    if (target_aa64 && (entry & 3)) {

        /*

         * if we are booting in AArch64 mode then "entry" needs to be 4 bytes

         * aligned.

         */

        return QEMU_ARM_POWERCTL_INVALID_PARAM;

    }



    /* Retrieve the cpu we are powering up */

    target_cpu_state = arm_get_cpu_by_id(cpuid);

    if (!target_cpu_state) {

        /* The cpu was not found */

        return QEMU_ARM_POWERCTL_INVALID_PARAM;

    }



    target_cpu = ARM_CPU(target_cpu_state);

    if (!target_cpu->powered_off) {

        qemu_log_mask(LOG_GUEST_ERROR,

                      "[ARM]%s: CPU %" PRId64 " is already on\n",

                      __func__, cpuid);

        return QEMU_ARM_POWERCTL_ALREADY_ON;

    }



    /*

     * The newly brought CPU is requested to enter the exception level

     * "target_el" and be in the requested mode (AArch64 or AArch32).

     */



    if (((target_el == 3) && !arm_feature(&target_cpu->env, ARM_FEATURE_EL3)) ||

        ((target_el == 2) && !arm_feature(&target_cpu->env, ARM_FEATURE_EL2))) {

        /*

         * The CPU does not support requested level

         */

        return QEMU_ARM_POWERCTL_INVALID_PARAM;

    }



    if (!target_aa64 && arm_feature(&target_cpu->env, ARM_FEATURE_AARCH64)) {

        /*

         * For now we don't support booting an AArch64 CPU in AArch32 mode

         * TODO: We should add this support later

         */

        qemu_log_mask(LOG_UNIMP,

                      "[ARM]%s: Starting AArch64 CPU %" PRId64

                      " in AArch32 mode is not supported yet\n",

                      __func__, cpuid);

        return QEMU_ARM_POWERCTL_INVALID_PARAM;

    }



    /* Initialize the cpu we are turning on */

    cpu_reset(target_cpu_state);

    target_cpu->powered_off = false;

    target_cpu_state->halted = 0;



    if (target_aa64) {

        if ((target_el < 3) && arm_feature(&target_cpu->env, ARM_FEATURE_EL3)) {

            /*

             * As target mode is AArch64, we need to set lower

             * exception level (the requested level 2) to AArch64

             */

            target_cpu->env.cp15.scr_el3 |= SCR_RW;

        }



        if ((target_el < 2) && arm_feature(&target_cpu->env, ARM_FEATURE_EL2)) {

            /*

             * As target mode is AArch64, we need to set lower

             * exception level (the requested level 1) to AArch64

             */

            target_cpu->env.cp15.hcr_el2 |= HCR_RW;

        }



        target_cpu->env.pstate = aarch64_pstate_mode(target_el, true);

    } else {

        /* We are requested to boot in AArch32 mode */

        static uint32_t mode_for_el[] = { 0,

                                          ARM_CPU_MODE_SVC,

                                          ARM_CPU_MODE_HYP,

                                          ARM_CPU_MODE_SVC };



        cpsr_write(&target_cpu->env, mode_for_el[target_el], CPSR_M,

                   CPSRWriteRaw);

    }



    if (target_el == 3) {

        /* Processor is in secure mode */

        target_cpu->env.cp15.scr_el3 &= ~SCR_NS;

    } else {

        /* Processor is not in secure mode */

        target_cpu->env.cp15.scr_el3 |= SCR_NS;

    }



    /* We check if the started CPU is now at the correct level */

    assert(target_el == arm_current_el(&target_cpu->env));



    if (target_aa64) {

        target_cpu->env.xregs[0] = context_id;

        target_cpu->env.thumb = false;

    } else {

        target_cpu->env.regs[0] = context_id;

        target_cpu->env.thumb = entry & 1;

        entry &= 0xfffffffe;

    }



    /* Start the new CPU at the requested address */

    cpu_set_pc(target_cpu_state, entry);



    qemu_cpu_kick(target_cpu_state);



    /* We are good to go */

    return QEMU_ARM_POWERCTL_RET_SUCCESS;

}

