static void iommu_mem_writew(void *opaque, target_phys_addr_t addr,

                             uint32_t val)

{

    IOMMUState *s = opaque;

    target_phys_addr_t saddr;



    saddr = (addr - s->addr) >> 2;

    DPRINTF("write reg[%d] = %x\n", (int)saddr, val);

    switch (saddr) {

    case IOMMU_CTRL:

        switch (val & IOMMU_CTRL_RNGE) {

        case IOMMU_RNGE_16MB:

            s->iostart = 0xffffffffff000000ULL;

            break;

        case IOMMU_RNGE_32MB:

            s->iostart = 0xfffffffffe000000ULL;

            break;

        case IOMMU_RNGE_64MB:

            s->iostart = 0xfffffffffc000000ULL;

            break;

        case IOMMU_RNGE_128MB:

            s->iostart = 0xfffffffff8000000ULL;

            break;

        case IOMMU_RNGE_256MB:

            s->iostart = 0xfffffffff0000000ULL;

            break;

        case IOMMU_RNGE_512MB:

            s->iostart = 0xffffffffe0000000ULL;

            break;

        case IOMMU_RNGE_1GB:

            s->iostart = 0xffffffffc0000000ULL;

            break;

        default:

        case IOMMU_RNGE_2GB:

            s->iostart = 0xffffffff80000000ULL;

            break;

        }

        DPRINTF("iostart = " TARGET_FMT_plx "\n", s->iostart);

        s->regs[saddr] = ((val & IOMMU_CTRL_MASK) | s->version);

        break;

    case IOMMU_BASE:

        s->regs[saddr] = val & IOMMU_BASE_MASK;

        break;

    case IOMMU_TLBFLUSH:

        DPRINTF("tlb flush %x\n", val);

        s->regs[saddr] = val & IOMMU_TLBFLUSH_MASK;

        break;

    case IOMMU_PGFLUSH:

        DPRINTF("page flush %x\n", val);

        s->regs[saddr] = val & IOMMU_PGFLUSH_MASK;

        break;

    case IOMMU_AFAR:

        s->regs[saddr] = val;

        qemu_irq_lower(s->irq);

        break;

    case IOMMU_AFSR:

        s->regs[saddr] = (val & IOMMU_AFSR_MASK) | IOMMU_AFSR_RESV;

        qemu_irq_lower(s->irq);

        break;

    case IOMMU_SBCFG0:

    case IOMMU_SBCFG1:

    case IOMMU_SBCFG2:

    case IOMMU_SBCFG3:

        s->regs[saddr] = val & IOMMU_SBCFG_MASK;

        break;

    case IOMMU_ARBEN:

        // XXX implement SBus probing: fault when reading unmapped

        // addresses, fault cause and address stored to MMU/IOMMU

        s->regs[saddr] = (val & IOMMU_ARBEN_MASK) | IOMMU_MID;

        break;

    default:

        s->regs[saddr] = val;

        break;

    }

}

static void pci_reset(EEPRO100State * s)

{

    uint32_t device = s->device;

    uint8_t *pci_conf = s->pci_dev->config;



    logout("%p\n", s);



    /* PCI Vendor ID */

    pci_config_set_vendor_id(pci_conf, PCI_VENDOR_ID_INTEL);

    /* PCI Device ID */

    pci_config_set_device_id(pci_conf, PCI_DEVICE_ID_INTEL_82551IT);

    /* PCI Command */

    PCI_CONFIG_16(PCI_COMMAND, 0x0000);

    /* PCI Status */

    PCI_CONFIG_16(PCI_STATUS, 0x2800);

    /* PCI Revision ID */

    PCI_CONFIG_8(PCI_REVISION_ID, 0x08);

    /* PCI Class Code */

    PCI_CONFIG_8(0x09, 0x00);

    pci_config_set_class(pci_conf, PCI_CLASS_NETWORK_ETHERNET);

    /* PCI Cache Line Size */

    /* check cache line size!!! */

    //~ PCI_CONFIG_8(0x0c, 0x00);

    /* PCI Latency Timer */

    PCI_CONFIG_8(0x0d, 0x20);   // latency timer = 32 clocks

    /* PCI Header Type */

    /* BIST (built-in self test) */

#if defined(TARGET_I386)

// !!! workaround for buggy bios

//~ #define PCI_ADDRESS_SPACE_MEM_PREFETCH 0

#endif

#if 0

    /* PCI Base Address Registers */

    /* CSR Memory Mapped Base Address */

    PCI_CONFIG_32(PCI_BASE_ADDRESS_0,

                  PCI_ADDRESS_SPACE_MEM | PCI_ADDRESS_SPACE_MEM_PREFETCH);

    /* CSR I/O Mapped Base Address */

    PCI_CONFIG_32(PCI_BASE_ADDRESS_1, PCI_ADDRESS_SPACE_IO);

#if 0

    /* Flash Memory Mapped Base Address */

    PCI_CONFIG_32(PCI_BASE_ADDRESS_2, 0xfffe0000 | PCI_ADDRESS_SPACE_MEM);

#endif

#endif

    /* Expansion ROM Base Address (depends on boot disable!!!) */

    PCI_CONFIG_32(0x30, 0x00000000);

    /* Capability Pointer */

    PCI_CONFIG_8(0x34, 0xdc);

    /* Interrupt Pin */

    PCI_CONFIG_8(0x3d, 1);      // interrupt pin 0

    /* Minimum Grant */

    PCI_CONFIG_8(0x3e, 0x08);

    /* Maximum Latency */

    PCI_CONFIG_8(0x3f, 0x18);

    /* Power Management Capabilities / Next Item Pointer / Capability ID */

    PCI_CONFIG_32(0xdc, 0x7e210001);



    switch (device) {

    case i82551:

        //~ PCI_CONFIG_16(PCI_DEVICE_ID, 0x1209);

        PCI_CONFIG_8(PCI_REVISION_ID, 0x0f);

        break;

    case i82557B:

        PCI_CONFIG_16(PCI_DEVICE_ID, 0x1229);

        PCI_CONFIG_8(PCI_REVISION_ID, 0x02);

        break;

    case i82557C:

        PCI_CONFIG_16(PCI_DEVICE_ID, 0x1229);

        PCI_CONFIG_8(PCI_REVISION_ID, 0x03);

        break;

    case i82558B:

        PCI_CONFIG_16(PCI_DEVICE_ID, 0x1229);

        PCI_CONFIG_16(PCI_STATUS, 0x2810);

        PCI_CONFIG_8(PCI_REVISION_ID, 0x05);

        break;

    case i82559C:

        PCI_CONFIG_16(PCI_DEVICE_ID, 0x1229);

        PCI_CONFIG_16(PCI_STATUS, 0x2810);

        //~ PCI_CONFIG_8(PCI_REVISION_ID, 0x08);

        break;

    case i82559ER:

        //~ PCI_CONFIG_16(PCI_DEVICE_ID, 0x1209);

        PCI_CONFIG_16(PCI_STATUS, 0x2810);

        PCI_CONFIG_8(PCI_REVISION_ID, 0x09);

        break;

    //~ PCI_CONFIG_16(PCI_DEVICE_ID, 0x1029);

    //~ PCI_CONFIG_16(PCI_DEVICE_ID, 0x1030);       /* 82559 InBusiness 10/100 */

    default:

        logout("Device %X is undefined!\n", device);

    }



    if (device == i82557C || device == i82558B || device == i82559C) {

        logout("Get device id and revision from EEPROM!!!\n");

    }

}

static void gen_arith_imm (CPUState *env, DisasContext *ctx, uint32_t opc,

                           int rt, int rs, int16_t imm)

{

    target_ulong uimm;

    const char *opn = "imm arith";

    TCGv t0 = tcg_temp_local_new(TCG_TYPE_TL);



    if (rt == 0 && opc != OPC_ADDI && opc != OPC_DADDI) {

        /* If no destination, treat it as a NOP.

           For addi, we must generate the overflow exception when needed. */

        MIPS_DEBUG("NOP");

        goto out;

    }

    uimm = (uint16_t)imm;

    switch (opc) {

    case OPC_ADDI:

    case OPC_ADDIU:

#if defined(TARGET_MIPS64)

    case OPC_DADDI:

    case OPC_DADDIU:

#endif

    case OPC_SLTI:

    case OPC_SLTIU:

        uimm = (target_long)imm; /* Sign extend to 32/64 bits */

        /* Fall through. */

    case OPC_ANDI:

    case OPC_ORI:

    case OPC_XORI:

        gen_load_gpr(t0, rs);

        break;

    case OPC_LUI:

        tcg_gen_movi_tl(t0, imm << 16);

        break;

    case OPC_SLL:

    case OPC_SRA:

    case OPC_SRL:

#if defined(TARGET_MIPS64)

    case OPC_DSLL:

    case OPC_DSRA:

    case OPC_DSRL:

    case OPC_DSLL32:

    case OPC_DSRA32:

    case OPC_DSRL32:

#endif

        uimm &= 0x1f;

        gen_load_gpr(t0, rs);

        break;

    }

    switch (opc) {

    case OPC_ADDI:

        {

            TCGv r_tmp1 = tcg_temp_local_new(TCG_TYPE_TL);

            TCGv r_tmp2 = tcg_temp_new(TCG_TYPE_TL);

            int l1 = gen_new_label();



            save_cpu_state(ctx, 1);

            tcg_gen_ext32s_tl(r_tmp1, t0);

            tcg_gen_addi_tl(t0, r_tmp1, uimm);



            tcg_gen_xori_tl(r_tmp1, r_tmp1, uimm);

            tcg_gen_xori_tl(r_tmp1, r_tmp1, -1);

            tcg_gen_xori_tl(r_tmp2, t0, uimm);

            tcg_gen_and_tl(r_tmp1, r_tmp1, r_tmp2);

            tcg_temp_free(r_tmp2);

            tcg_gen_shri_tl(r_tmp1, r_tmp1, 31);

            tcg_gen_brcondi_tl(TCG_COND_EQ, r_tmp1, 0, l1);

            tcg_temp_free(r_tmp1);

            /* operands of same sign, result different sign */

            generate_exception(ctx, EXCP_OVERFLOW);

            gen_set_label(l1);



            tcg_gen_ext32s_tl(t0, t0);

        }

        opn = "addi";

        break;

    case OPC_ADDIU:

        tcg_gen_ext32s_tl(t0, t0);

        tcg_gen_addi_tl(t0, t0, uimm);

        tcg_gen_ext32s_tl(t0, t0);

        opn = "addiu";

        break;

#if defined(TARGET_MIPS64)

    case OPC_DADDI:

        {

            TCGv r_tmp1 = tcg_temp_local_new(TCG_TYPE_TL);

            TCGv r_tmp2 = tcg_temp_new(TCG_TYPE_TL);

            int l1 = gen_new_label();



            save_cpu_state(ctx, 1);

            tcg_gen_mov_tl(r_tmp1, t0);

            tcg_gen_addi_tl(t0, t0, uimm);



            tcg_gen_xori_tl(r_tmp1, r_tmp1, uimm);

            tcg_gen_xori_tl(r_tmp1, r_tmp1, -1);

            tcg_gen_xori_tl(r_tmp2, t0, uimm);

            tcg_gen_and_tl(r_tmp1, r_tmp1, r_tmp2);

            tcg_temp_free(r_tmp2);

            tcg_gen_shri_tl(r_tmp1, r_tmp1, 63);

            tcg_gen_brcondi_tl(TCG_COND_EQ, r_tmp1, 0, l1);

            tcg_temp_free(r_tmp1);

            /* operands of same sign, result different sign */

            generate_exception(ctx, EXCP_OVERFLOW);

            gen_set_label(l1);

        }

        opn = "daddi";

        break;

    case OPC_DADDIU:

        tcg_gen_addi_tl(t0, t0, uimm);

        opn = "daddiu";

        break;

#endif

    case OPC_SLTI:

        gen_op_lti(t0, uimm);

        opn = "slti";

        break;

    case OPC_SLTIU:

        gen_op_ltiu(t0, uimm);

        opn = "sltiu";

        break;

    case OPC_ANDI:

        tcg_gen_andi_tl(t0, t0, uimm);

        opn = "andi";

        break;

    case OPC_ORI:

        tcg_gen_ori_tl(t0, t0, uimm);

        opn = "ori";

        break;

    case OPC_XORI:

        tcg_gen_xori_tl(t0, t0, uimm);

        opn = "xori";

        break;

    case OPC_LUI:

        opn = "lui";

        break;

    case OPC_SLL:

        tcg_gen_ext32u_tl(t0, t0);

        tcg_gen_shli_tl(t0, t0, uimm);

        tcg_gen_ext32s_tl(t0, t0);

        opn = "sll";

        break;

    case OPC_SRA:

        tcg_gen_ext32s_tl(t0, t0);

        tcg_gen_sari_tl(t0, t0, uimm);

        tcg_gen_ext32s_tl(t0, t0);

        opn = "sra";

        break;

    case OPC_SRL:

        switch ((ctx->opcode >> 21) & 0x1f) {

        case 0:

            tcg_gen_ext32u_tl(t0, t0);

            tcg_gen_shri_tl(t0, t0, uimm);

            tcg_gen_ext32s_tl(t0, t0);

            opn = "srl";

            break;

        case 1:

            /* rotr is decoded as srl on non-R2 CPUs */

            if (env->insn_flags & ISA_MIPS32R2) {

                if (uimm != 0) {

                    TCGv r_tmp1 = tcg_temp_new(TCG_TYPE_I32);



                    tcg_gen_trunc_tl_i32(r_tmp1, t0);

                    tcg_gen_rotri_i32(r_tmp1, r_tmp1, uimm);

                    tcg_gen_ext_i32_tl(t0, r_tmp1);

                    tcg_temp_free(r_tmp1);

                }

                opn = "rotr";

            } else {

                tcg_gen_ext32u_tl(t0, t0);

                tcg_gen_shri_tl(t0, t0, uimm);

                tcg_gen_ext32s_tl(t0, t0);

                opn = "srl";

            }

            break;

        default:

            MIPS_INVAL("invalid srl flag");

            generate_exception(ctx, EXCP_RI);

            break;

        }

        break;

#if defined(TARGET_MIPS64)

    case OPC_DSLL:

        tcg_gen_shli_tl(t0, t0, uimm);

        opn = "dsll";

        break;

    case OPC_DSRA:

        tcg_gen_sari_tl(t0, t0, uimm);

        opn = "dsra";

        break;

    case OPC_DSRL:

        switch ((ctx->opcode >> 21) & 0x1f) {

        case 0:

            tcg_gen_shri_tl(t0, t0, uimm);

            opn = "dsrl";

            break;

        case 1:

            /* drotr is decoded as dsrl on non-R2 CPUs */

            if (env->insn_flags & ISA_MIPS32R2) {

                if (uimm != 0) {

                    tcg_gen_rotri_tl(t0, t0, uimm);

                }

                opn = "drotr";

            } else {

                tcg_gen_shri_tl(t0, t0, uimm);

                opn = "dsrl";

            }

            break;

        default:

            MIPS_INVAL("invalid dsrl flag");

            generate_exception(ctx, EXCP_RI);

            break;

        }

        break;

    case OPC_DSLL32:

        tcg_gen_shli_tl(t0, t0, uimm + 32);

        opn = "dsll32";

        break;

    case OPC_DSRA32:

        tcg_gen_sari_tl(t0, t0, uimm + 32);

        opn = "dsra32";

        break;

    case OPC_DSRL32:

        switch ((ctx->opcode >> 21) & 0x1f) {

        case 0:

            tcg_gen_shri_tl(t0, t0, uimm + 32);

            opn = "dsrl32";

            break;

        case 1:

            /* drotr32 is decoded as dsrl32 on non-R2 CPUs */

            if (env->insn_flags & ISA_MIPS32R2) {

                tcg_gen_rotri_tl(t0, t0, uimm + 32);

                opn = "drotr32";

            } else {

                tcg_gen_shri_tl(t0, t0, uimm + 32);

                opn = "dsrl32";

            }

            break;

        default:

            MIPS_INVAL("invalid dsrl32 flag");

            generate_exception(ctx, EXCP_RI);

            break;

        }

        break;

#endif

    default:

        MIPS_INVAL(opn);

        generate_exception(ctx, EXCP_RI);

        goto out;

    }

    gen_store_gpr(t0, rt);

    MIPS_DEBUG("%s %s, %s, " TARGET_FMT_lx, opn, regnames[rt], regnames[rs], uimm);

 out:

    tcg_temp_free(t0);

}

static ImageInfoSpecific *vmdk_get_specific_info(BlockDriverState *bs)

{

    int i;

    BDRVVmdkState *s = bs->opaque;

    ImageInfoSpecific *spec_info = g_new0(ImageInfoSpecific, 1);

    ImageInfoList **next;



    *spec_info = (ImageInfoSpecific){

        .type = IMAGE_INFO_SPECIFIC_KIND_VMDK,

        {

            .vmdk = g_new0(ImageInfoSpecificVmdk, 1),

        },

    };



    *spec_info->u.vmdk = (ImageInfoSpecificVmdk) {

        .create_type = g_strdup(s->create_type),

        .cid = s->cid,

        .parent_cid = s->parent_cid,

    };



    next = &spec_info->u.vmdk->extents;

    for (i = 0; i < s->num_extents; i++) {

        *next = g_new0(ImageInfoList, 1);

        (*next)->value = vmdk_get_extent_info(&s->extents[i]);

        (*next)->next = NULL;

        next = &(*next)->next;

    }



    return spec_info;

}

