static target_ulong h_protect(CPUPPCState *env, sPAPREnvironment *spapr,

                              target_ulong opcode, target_ulong *args)

{

    target_ulong flags = args[0];

    target_ulong pte_index = args[1];

    target_ulong avpn = args[2];

    uint8_t *hpte;

    target_ulong v, r, rb;



    if ((pte_index * HASH_PTE_SIZE_64) & ~env->htab_mask) {

        return H_PARAMETER;

    }



    hpte = env->external_htab + (pte_index * HASH_PTE_SIZE_64);

    while (!lock_hpte(hpte, HPTE_V_HVLOCK)) {

        /* We have no real concurrency in qemu soft-emulation, so we

         * will never actually have a contested lock */

        assert(0);

    }



    v = ldq_p(hpte);

    r = ldq_p(hpte + (HASH_PTE_SIZE_64/2));



    if ((v & HPTE_V_VALID) == 0 ||

        ((flags & H_AVPN) && (v & ~0x7fULL) != avpn)) {

        stq_p(hpte, v & ~HPTE_V_HVLOCK);

        assert(!(ldq_p(hpte) & HPTE_V_HVLOCK));

        return H_NOT_FOUND;

    }



    r &= ~(HPTE_R_PP0 | HPTE_R_PP | HPTE_R_N |

           HPTE_R_KEY_HI | HPTE_R_KEY_LO);

    r |= (flags << 55) & HPTE_R_PP0;

    r |= (flags << 48) & HPTE_R_KEY_HI;

    r |= flags & (HPTE_R_PP | HPTE_R_N | HPTE_R_KEY_LO);

    rb = compute_tlbie_rb(v, r, pte_index);

    stq_p(hpte, v & ~HPTE_V_VALID);

    ppc_tlb_invalidate_one(env, rb);

    stq_p(hpte + (HASH_PTE_SIZE_64/2), r);

    /* Don't need a memory barrier, due to qemu's global lock */

    stq_p(hpte, v & ~HPTE_V_HVLOCK);

    assert(!(ldq_p(hpte) & HPTE_V_HVLOCK));

    return H_SUCCESS;

}

static ExitStatus op_ex(DisasContext *s, DisasOps *o)

{

    /* ??? Perhaps a better way to implement EXECUTE is to set a bit in

       tb->flags, (ab)use the tb->cs_base field as the address of

       the template in memory, and grab 8 bits of tb->flags/cflags for

       the contents of the register.  We would then recognize all this

       in gen_intermediate_code_internal, generating code for exactly

       one instruction.  This new TB then gets executed normally.



       On the other hand, this seems to be mostly used for modifying

       MVC inside of memcpy, which needs a helper call anyway.  So

       perhaps this doesn't bear thinking about any further.  */



    TCGv_i64 tmp;



    update_psw_addr(s);

    update_cc_op(s);



    tmp = tcg_const_i64(s->next_pc);

    gen_helper_ex(cc_op, cpu_env, cc_op, o->in1, o->in2, tmp);

    tcg_temp_free_i64(tmp);



    set_cc_static(s);

    return NO_EXIT;

}

int32 float32_to_int32_round_to_zero( float32 a STATUS_PARAM )

{

    flag aSign;

    int16 aExp, shiftCount;

    uint32_t aSig;

    int32 z;

    a = float32_squash_input_denormal(a STATUS_VAR);



    aSig = extractFloat32Frac( a );

    aExp = extractFloat32Exp( a );

    aSign = extractFloat32Sign( a );

    shiftCount = aExp - 0x9E;

    if ( 0 <= shiftCount ) {

        if ( float32_val(a) != 0xCF000000 ) {

            float_raise( float_flag_invalid STATUS_VAR);

            if ( ! aSign || ( ( aExp == 0xFF ) && aSig ) ) return 0x7FFFFFFF;

        }

        return (int32_t) 0x80000000;

    }

    else if ( aExp <= 0x7E ) {

        if ( aExp | aSig ) STATUS(float_exception_flags) |= float_flag_inexact;

        return 0;

    }

    aSig = ( aSig | 0x00800000 )<<8;

    z = aSig>>( - shiftCount );

    if ( (uint32_t) ( aSig<<( shiftCount & 31 ) ) ) {

        STATUS(float_exception_flags) |= float_flag_inexact;

    }

    if ( aSign ) z = - z;

    return z;



}

int usb_desc_handle_control(USBDevice *dev, USBPacket *p,

        int request, int value, int index, int length, uint8_t *data)

{

    const USBDesc *desc = usb_device_get_usb_desc(dev);

    int ret = -1;



    assert(desc != NULL);

    switch(request) {

    case DeviceOutRequest | USB_REQ_SET_ADDRESS:

        dev->addr = value;

        trace_usb_set_addr(dev->addr);

        ret = 0;

        break;



    case DeviceRequest | USB_REQ_GET_DESCRIPTOR:

        ret = usb_desc_get_descriptor(dev, value, data, length);

        break;



    case DeviceRequest | USB_REQ_GET_CONFIGURATION:

        data[0] = dev->config->bConfigurationValue;

        ret = 1;

        break;

    case DeviceOutRequest | USB_REQ_SET_CONFIGURATION:

        ret = usb_desc_set_config(dev, value);

        trace_usb_set_config(dev->addr, value, ret);

        break;



    case DeviceRequest | USB_REQ_GET_STATUS:

        data[0] = 0;

        if (dev->config->bmAttributes & 0x40) {

            data[0] |= 1 << USB_DEVICE_SELF_POWERED;

        }

        if (dev->remote_wakeup) {

            data[0] |= 1 << USB_DEVICE_REMOTE_WAKEUP;

        }

        data[1] = 0x00;

        ret = 2;

        break;

    case DeviceOutRequest | USB_REQ_CLEAR_FEATURE:

        if (value == USB_DEVICE_REMOTE_WAKEUP) {

            dev->remote_wakeup = 0;

            ret = 0;

        }

        trace_usb_clear_device_feature(dev->addr, value, ret);

        break;

    case DeviceOutRequest | USB_REQ_SET_FEATURE:

        if (value == USB_DEVICE_REMOTE_WAKEUP) {

            dev->remote_wakeup = 1;

            ret = 0;

        }

        trace_usb_set_device_feature(dev->addr, value, ret);

        break;



    case InterfaceRequest | USB_REQ_GET_INTERFACE:

        if (index < 0 || index >= dev->ninterfaces) {

            break;

        }

        data[0] = dev->altsetting[index];

        ret = 1;

        break;

    case InterfaceOutRequest | USB_REQ_SET_INTERFACE:

        ret = usb_desc_set_interface(dev, index, value);

        trace_usb_set_interface(dev->addr, index, value, ret);

        break;



    }

    return ret;

}

static void imx_eth_write(void *opaque, hwaddr offset, uint64_t value,

                           unsigned size)

{

    IMXFECState *s = IMX_FEC(opaque);

    uint32_t index = offset >> 2;



    FEC_PRINTF("reg[%s] <= 0x%" PRIx32 "\n", imx_eth_reg_name(s, index),

                (uint32_t)value);



    switch (index) {

    case ENET_EIR:

        s->regs[index] &= ~value;

        break;

    case ENET_EIMR:

        s->regs[index] = value;

        break;

    case ENET_RDAR:

        if (s->regs[ENET_ECR] & ENET_ECR_ETHEREN) {

            if (!s->regs[index]) {

                s->regs[index] = ENET_RDAR_RDAR;

                imx_eth_enable_rx(s);

            }

        } else {

            s->regs[index] = 0;

        }

        break;

    case ENET_TDAR:

        if (s->regs[ENET_ECR] & ENET_ECR_ETHEREN) {

            s->regs[index] = ENET_TDAR_TDAR;

            imx_eth_do_tx(s);

        }

        s->regs[index] = 0;

        break;

    case ENET_ECR:

        if (value & ENET_ECR_RESET) {

            return imx_eth_reset(DEVICE(s));

        }

        s->regs[index] = value;

        if ((s->regs[index] & ENET_ECR_ETHEREN) == 0) {

            s->regs[ENET_RDAR] = 0;

            s->rx_descriptor = s->regs[ENET_RDSR];

            s->regs[ENET_TDAR] = 0;

            s->tx_descriptor = s->regs[ENET_TDSR];

        }

        break;

    case ENET_MMFR:

        s->regs[index] = value;

        if (extract32(value, 29, 1)) {

            /* This is a read operation */

            s->regs[ENET_MMFR] = deposit32(s->regs[ENET_MMFR], 0, 16,

                                           do_phy_read(s,

                                                       extract32(value,

                                                                 18, 10)));

        } else {

            /* This a write operation */

            do_phy_write(s, extract32(value, 18, 10), extract32(value, 0, 16));

        }

        /* raise the interrupt as the PHY operation is done */

        s->regs[ENET_EIR] |= ENET_INT_MII;

        break;

    case ENET_MSCR:

        s->regs[index] = value & 0xfe;

        break;

    case ENET_MIBC:

        /* TODO: Implement MIB.  */

        s->regs[index] = (value & 0x80000000) ? 0xc0000000 : 0;

        break;

    case ENET_RCR:

        s->regs[index] = value & 0x07ff003f;

        /* TODO: Implement LOOP mode.  */

        break;

    case ENET_TCR:

        /* We transmit immediately, so raise GRA immediately.  */

        s->regs[index] = value;

        if (value & 1) {

            s->regs[ENET_EIR] |= ENET_INT_GRA;

        }

        break;

    case ENET_PALR:

        s->regs[index] = value;

        s->conf.macaddr.a[0] = value >> 24;

        s->conf.macaddr.a[1] = value >> 16;

        s->conf.macaddr.a[2] = value >> 8;

        s->conf.macaddr.a[3] = value;

        break;

    case ENET_PAUR:

        s->regs[index] = (value | 0x0000ffff) & 0xffff8808;

        s->conf.macaddr.a[4] = value >> 24;

        s->conf.macaddr.a[5] = value >> 16;

        break;

    case ENET_OPD:

        s->regs[index] = (value & 0x0000ffff) | 0x00010000;

        break;

    case ENET_IAUR:

    case ENET_IALR:

    case ENET_GAUR:

    case ENET_GALR:

        /* TODO: implement MAC hash filtering.  */

        break;

    case ENET_TFWR:

        if (s->is_fec) {

            s->regs[index] = value & 0x3;

        } else {

            s->regs[index] = value & 0x13f;

        }

        break;

    case ENET_RDSR:

        if (s->is_fec) {

            s->regs[index] = value & ~3;

        } else {

            s->regs[index] = value & ~7;

        }

        s->rx_descriptor = s->regs[index];

        break;

    case ENET_TDSR:

        if (s->is_fec) {

            s->regs[index] = value & ~3;

        } else {

            s->regs[index] = value & ~7;

        }

        s->tx_descriptor = s->regs[index];

        break;

    case ENET_MRBR:

        s->regs[index] = value & 0x00003ff0;

        break;

    default:

        if (s->is_fec) {

            imx_fec_write(s, index, value);

        } else {

            imx_enet_write(s, index, value);

        }

        return;

    }



    imx_eth_update(s);

}

int qemu_chr_open_spice(QemuOpts *opts, CharDriverState **_chr)

{

    CharDriverState *chr;

    SpiceCharDriver *s;

    const char* name = qemu_opt_get(opts, "name");

    uint32_t debug = qemu_opt_get_number(opts, "debug", 0);

    const char** psubtype = spice_server_char_device_recognized_subtypes();

    const char *subtype = NULL;



    if (name == NULL) {

        fprintf(stderr, "spice-qemu-char: missing name parameter\n");

        print_allowed_subtypes();

        return -EINVAL;

    }

    for(;*psubtype != NULL; ++psubtype) {

        if (strcmp(name, *psubtype) == 0) {

            subtype = *psubtype;

            break;

        }

    }

    if (subtype == NULL) {

        fprintf(stderr, "spice-qemu-char: unsupported name\n");

        print_allowed_subtypes();

        return -EINVAL;

    }



    chr = g_malloc0(sizeof(CharDriverState));

    s = g_malloc0(sizeof(SpiceCharDriver));

    s->chr = chr;

    s->debug = debug;

    s->active = false;

    s->sin.subtype = subtype;

    chr->opaque = s;

    chr->chr_write = spice_chr_write;

    chr->chr_close = spice_chr_close;

    chr->chr_guest_open = spice_chr_guest_open;

    chr->chr_guest_close = spice_chr_guest_close;



#if SPICE_SERVER_VERSION < 0x000901

    /* See comment in vmc_state() */

    if (strcmp(subtype, "vdagent") == 0) {

        qemu_chr_generic_open(chr);

    }

#endif



    *_chr = chr;

    return 0;

}

