static int coroutine_fn iscsi_co_readv(BlockDriverState *bs,

                                       int64_t sector_num, int nb_sectors,

                                       QEMUIOVector *iov)

{

    IscsiLun *iscsilun = bs->opaque;

    struct IscsiTask iTask;

    uint64_t lba;

    uint32_t num_sectors;



    if (!is_sector_request_lun_aligned(sector_num, nb_sectors, iscsilun)) {

        return -EINVAL;

    }



    if (bs->bl.max_transfer &&

        nb_sectors << BDRV_SECTOR_BITS > bs->bl.max_transfer) {

        error_report("iSCSI Error: Read of %d sectors exceeds max_xfer_len "

                     "of %" PRIu32 " bytes", nb_sectors, bs->bl.max_transfer);

        return -EINVAL;

    }



    if (iscsilun->lbprz && nb_sectors >= ISCSI_CHECKALLOC_THRES &&

        !iscsi_allocationmap_is_allocated(iscsilun, sector_num, nb_sectors)) {

        int64_t ret;

        int pnum;

        BlockDriverState *file;

        ret = iscsi_co_get_block_status(bs, sector_num,

                                        BDRV_REQUEST_MAX_SECTORS, &pnum, &file);

        if (ret < 0) {

            return ret;

        }

        if (ret & BDRV_BLOCK_ZERO && pnum >= nb_sectors) {

            qemu_iovec_memset(iov, 0, 0x00, iov->size);

            return 0;

        }

    }



    lba = sector_qemu2lun(sector_num, iscsilun);

    num_sectors = sector_qemu2lun(nb_sectors, iscsilun);



    iscsi_co_init_iscsitask(iscsilun, &iTask);

retry:

    if (iscsilun->use_16_for_rw) {

        iTask.task = iscsi_read16_task(iscsilun->iscsi, iscsilun->lun, lba,

                                       num_sectors * iscsilun->block_size,

                                       iscsilun->block_size, 0, 0, 0, 0, 0,

                                       iscsi_co_generic_cb, &iTask);

    } else {

        iTask.task = iscsi_read10_task(iscsilun->iscsi, iscsilun->lun, lba,

                                       num_sectors * iscsilun->block_size,

                                       iscsilun->block_size,

                                       0, 0, 0, 0, 0,

                                       iscsi_co_generic_cb, &iTask);

    }

    if (iTask.task == NULL) {

        return -ENOMEM;

    }

    scsi_task_set_iov_in(iTask.task, (struct scsi_iovec *) iov->iov, iov->niov);



    while (!iTask.complete) {

        iscsi_set_events(iscsilun);

        qemu_coroutine_yield();

    }



    if (iTask.task != NULL) {

        scsi_free_scsi_task(iTask.task);

        iTask.task = NULL;

    }



    if (iTask.do_retry) {

        iTask.complete = 0;

        goto retry;

    }



    if (iTask.status != SCSI_STATUS_GOOD) {

        return iTask.err_code;

    }



    return 0;

}

static DeviceClass *qdev_get_device_class(const char **driver, Error **errp)

{

    ObjectClass *oc;

    DeviceClass *dc;



    oc = object_class_by_name(*driver);

    if (!oc) {

        const char *typename = find_typename_by_alias(*driver);



        if (typename) {

            *driver = typename;

            oc = object_class_by_name(*driver);

        }

    }



    if (!object_class_dynamic_cast(oc, TYPE_DEVICE)) {

        error_setg(errp, "'%s' is not a valid device model name", *driver);

        return NULL;

    }



    if (object_class_is_abstract(oc)) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE, "driver",

                   "non-abstract device type");

        return NULL;

    }



    dc = DEVICE_CLASS(oc);

    if (dc->cannot_instantiate_with_device_add_yet ||

        (qdev_hotplug && !dc->hotpluggable)) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE, "driver",

                   "pluggable device type");

        return NULL;

    }



    return dc;

}

static int usb_net_handle_control(USBDevice *dev, int request, int value,

                int index, int length, uint8_t *data)

{

    USBNetState *s = (USBNetState *) dev;

    int ret = 0;



    switch(request) {

    case DeviceRequest | USB_REQ_GET_STATUS:

        data[0] = (1 << USB_DEVICE_SELF_POWERED) |

                (dev->remote_wakeup << USB_DEVICE_REMOTE_WAKEUP);

        data[1] = 0x00;

        ret = 2;

        break;



    case DeviceOutRequest | USB_REQ_CLEAR_FEATURE:

        if (value == USB_DEVICE_REMOTE_WAKEUP) {

            dev->remote_wakeup = 0;

        } else {

            goto fail;

        }

        ret = 0;

        break;



    case DeviceOutRequest | USB_REQ_SET_FEATURE:

        if (value == USB_DEVICE_REMOTE_WAKEUP) {

            dev->remote_wakeup = 1;

        } else {

            goto fail;

        }

        ret = 0;

        break;



    case DeviceOutRequest | USB_REQ_SET_ADDRESS:

        dev->addr = value;

        ret = 0;

        break;



    case ClassInterfaceOutRequest | USB_CDC_SEND_ENCAPSULATED_COMMAND:

        if (!s->rndis || value || index != 0)

            goto fail;

#ifdef TRAFFIC_DEBUG

        {

            unsigned int i;

            fprintf(stderr, "SEND_ENCAPSULATED_COMMAND:");

            for (i = 0; i < length; i++) {

                if (!(i & 15))

                    fprintf(stderr, "\n%04x:", i);

                fprintf(stderr, " %02x", data[i]);

            }

            fprintf(stderr, "\n\n");

        }

#endif

        ret = rndis_parse(s, data, length);

        break;



    case ClassInterfaceRequest | USB_CDC_GET_ENCAPSULATED_RESPONSE:

        if (!s->rndis || value || index != 0)

            goto fail;

        ret = rndis_get_response(s, data);

        if (!ret) {

            data[0] = 0;

            ret = 1;

        }

#ifdef TRAFFIC_DEBUG

        {

            unsigned int i;

            fprintf(stderr, "GET_ENCAPSULATED_RESPONSE:");

            for (i = 0; i < ret; i++) {

                if (!(i & 15))

                    fprintf(stderr, "\n%04x:", i);

                fprintf(stderr, " %02x", data[i]);

            }

            fprintf(stderr, "\n\n");

        }

#endif

        break;



    case DeviceRequest | USB_REQ_GET_DESCRIPTOR:

        switch(value >> 8) {

        case USB_DT_DEVICE:

            ret = sizeof(qemu_net_dev_descriptor);

            memcpy(data, qemu_net_dev_descriptor, ret);

            break;



        case USB_DT_CONFIG:

            switch (value & 0xff) {

            case 0:

                ret = sizeof(qemu_net_rndis_config_descriptor);

                memcpy(data, qemu_net_rndis_config_descriptor, ret);

                break;



            case 1:

                ret = sizeof(qemu_net_cdc_config_descriptor);

                memcpy(data, qemu_net_cdc_config_descriptor, ret);

                break;



            default:

                goto fail;

            }



            data[2] = ret & 0xff;

            data[3] = ret >> 8;

            break;



        case USB_DT_STRING:

            switch (value & 0xff) {

            case 0:

                /* language ids */

                data[0] = 4;

                data[1] = 3;

                data[2] = 0x09;

                data[3] = 0x04;

                ret = 4;

                break;



            case STRING_ETHADDR:

                ret = set_usb_string(data, s->usbstring_mac);

                break;



            default:

                if (usb_net_stringtable[value & 0xff]) {

                    ret = set_usb_string(data,

                                    usb_net_stringtable[value & 0xff]);

                    break;

                }



                goto fail;

            }

            break;



        default:

            goto fail;

        }

        break;



    case DeviceRequest | USB_REQ_GET_CONFIGURATION:

        data[0] = s->rndis ? DEV_RNDIS_CONFIG_VALUE : DEV_CONFIG_VALUE;

        ret = 1;

        break;



    case DeviceOutRequest | USB_REQ_SET_CONFIGURATION:

        switch (value & 0xff) {

        case DEV_CONFIG_VALUE:

            s->rndis = 0;

            break;



        case DEV_RNDIS_CONFIG_VALUE:

            s->rndis = 1;

            break;



        default:

            goto fail;

        }

        ret = 0;

        break;



    case DeviceRequest | USB_REQ_GET_INTERFACE:

    case InterfaceRequest | USB_REQ_GET_INTERFACE:

        data[0] = 0;

        ret = 1;

        break;



    case DeviceOutRequest | USB_REQ_SET_INTERFACE:

    case InterfaceOutRequest | USB_REQ_SET_INTERFACE:

        ret = 0;

        break;



    default:

    fail:

        fprintf(stderr, "usbnet: failed control transaction: "

                        "request 0x%x value 0x%x index 0x%x length 0x%x\n",

                        request, value, index, length);

        ret = USB_RET_STALL;

        break;

    }

    return ret;

}

