    if (!replay_file || replay_mode == REPLAY_MODE_NONE

        || !events_enabled) {

        Event e;

        e.event_kind = event_kind;

        e.opaque = opaque;

        e.opaque2 = opaque2;

        e.id = id;

        replay_run_event(&e);

