static void vfio_unmap_bars(VFIOPCIDevice *vdev)

{

    int i;



    for (i = 0; i < PCI_ROM_SLOT; i++) {

        vfio_unmap_bar(vdev, i);

    }



    if (vdev->has_vga) {

        vfio_vga_quirk_teardown(vdev);

        pci_unregister_vga(&vdev->pdev);

    }

}

static void pcibus_dev_print(Monitor *mon, DeviceState *dev, int indent)

{

    PCIDevice *d = (PCIDevice *)dev;

    const pci_class_desc *desc;

    char ctxt[64];

    PCIIORegion *r;

    int i, class;



    class = pci_get_word(d->config + PCI_CLASS_DEVICE);

    desc = pci_class_descriptions;

    while (desc->desc && class != desc->class)

        desc++;

    if (desc->desc) {

        snprintf(ctxt, sizeof(ctxt), "%s", desc->desc);

    } else {

        snprintf(ctxt, sizeof(ctxt), "Class %04x", class);

    }



    monitor_printf(mon, "%*sclass %s, addr %02x:%02x.%x, "

                   "pci id %04x:%04x (sub %04x:%04x)\n",

                   indent, "", ctxt, pci_bus_num(d->bus),

                   PCI_SLOT(d->devfn), PCI_FUNC(d->devfn),

                   pci_get_word(d->config + PCI_VENDOR_ID),

                   pci_get_word(d->config + PCI_DEVICE_ID),

                   pci_get_word(d->config + PCI_SUBSYSTEM_VENDOR_ID),

                   pci_get_word(d->config + PCI_SUBSYSTEM_ID));

    for (i = 0; i < PCI_NUM_REGIONS; i++) {

        r = &d->io_regions[i];

        if (!r->size)

            continue;

        monitor_printf(mon, "%*sbar %d: %s at 0x%"FMT_PCIBUS

                       " [0x%"FMT_PCIBUS"]\n",

                       indent, "",

                       i, r->type & PCI_BASE_ADDRESS_SPACE_IO ? "i/o" : "mem",

                       r->addr, r->addr + r->size - 1);

    }

}

ObjectClass *object_class_dynamic_cast_assert(ObjectClass *class,

                                              const char *typename,

                                              const char *file, int line,

                                              const char *func)

{

    ObjectClass *ret;



    trace_object_class_dynamic_cast_assert(class ? class->type->name : "(null)",

                                           typename, file, line, func);



#ifdef CONFIG_QOM_CAST_DEBUG

    int i;



    for (i = 0; i < OBJECT_CLASS_CAST_CACHE; i++) {

        if (class->cast_cache[i] == typename) {

            ret = class;

            goto out;

        }

    }

#else

    if (!class->interfaces) {

        return class;

    }

#endif



    ret = object_class_dynamic_cast(class, typename);

    if (!ret && class) {

        fprintf(stderr, "%s:%d:%s: Object %p is not an instance of type %s\n",

                file, line, func, class, typename);

        abort();

    }



#ifdef CONFIG_QOM_CAST_DEBUG

    if (ret == class) {

        for (i = 1; i < OBJECT_CLASS_CAST_CACHE; i++) {

            class->cast_cache[i - 1] = class->cast_cache[i];

        }

        class->cast_cache[i - 1] = typename;

    }

out:

#endif

    return ret;

}

void msix_load(PCIDevice *dev, QEMUFile *f)

{

    unsigned n = dev->msix_entries_nr;

    unsigned int vector;



    if (!(dev->cap_present & QEMU_PCI_CAP_MSIX)) {

        return;

    }



    msix_free_irq_entries(dev);

    qemu_get_buffer(f, dev->msix_table_page, n * PCI_MSIX_ENTRY_SIZE);

    qemu_get_buffer(f, dev->msix_table_page + MSIX_PAGE_PENDING, (n + 7) / 8);

    msix_update_function_masked(dev);



    for (vector = 0; vector < n; vector++) {

        msix_handle_mask_update(dev, vector, true);

    }

}

static void vga_update_display(void *opaque)

{

    VGACommonState *s = opaque;

    int full_update, graphic_mode;



    qemu_flush_coalesced_mmio_buffer();



    if (ds_get_bits_per_pixel(s->ds) == 0) {

        /* nothing to do */

    } else {

        full_update = 0;

        if (!(s->ar_index & 0x20) &&

            /* extra CGA compatibility hacks (not in standard VGA */

            (!(vga_cga_hacks & VGA_CGA_HACK_PALETTE_BLANKING) ||

             (s->ar_index != 0 && s->ar_flip_flop))) {

            graphic_mode = GMODE_BLANK;

        } else {

            graphic_mode = s->gr[VGA_GFX_MISC] & VGA_GR06_GRAPHICS_MODE;

        }

        if (graphic_mode != s->graphic_mode) {

            s->graphic_mode = graphic_mode;

            s->cursor_blink_time = qemu_get_clock_ms(vm_clock);

            full_update = 1;

        }

        switch(graphic_mode) {

        case GMODE_TEXT:

            vga_draw_text(s, full_update);

            break;

        case GMODE_GRAPH:

            vga_draw_graphic(s, full_update);

            break;

        case GMODE_BLANK:

        default:

            vga_draw_blank(s, full_update);

            break;

        }

    }

}

static bool eckd_valid_address(BootMapPointer *p)

{

    const uint64_t cylinder = p->eckd.cylinder

                            + ((p->eckd.head & 0xfff0) << 12);

    const uint64_t head = p->eckd.head & 0x000f;



    if (head >= virtio_get_heads()

        ||  p->eckd.sector > virtio_get_sectors()

        ||  p->eckd.sector <= 0) {

        return false;

    }



    if (!virtio_guessed_disk_nature() && cylinder >= virtio_get_cylinders()) {

        return false;

    }



    return true;

}

