static int local_set_mapped_file_attrat(int dirfd, const char *name,

                                        FsCred *credp)

{

    FILE *fp;

    int ret;

    char buf[ATTR_MAX];

    int uid = -1, gid = -1, mode = -1, rdev = -1;

    int map_dirfd;



    ret = mkdirat(dirfd, VIRTFS_META_DIR, 0700);

    if (ret < 0 && errno != EEXIST) {

        return -1;

    }



    map_dirfd = openat_dir(dirfd, VIRTFS_META_DIR);

    if (map_dirfd == -1) {

        return -1;

    }



    fp = local_fopenat(map_dirfd, name, "r");

    if (!fp) {

        if (errno == ENOENT) {

            goto update_map_file;

        } else {

            close_preserve_errno(map_dirfd);

            return -1;

        }

    }

    memset(buf, 0, ATTR_MAX);

    while (fgets(buf, ATTR_MAX, fp)) {

        if (!strncmp(buf, "virtfs.uid", 10)) {

            uid = atoi(buf + 11);

        } else if (!strncmp(buf, "virtfs.gid", 10)) {

            gid = atoi(buf + 11);

        } else if (!strncmp(buf, "virtfs.mode", 11)) {

            mode = atoi(buf + 12);

        } else if (!strncmp(buf, "virtfs.rdev", 11)) {

            rdev = atoi(buf + 12);

        }

        memset(buf, 0, ATTR_MAX);

    }

    fclose(fp);



update_map_file:

    fp = local_fopenat(map_dirfd, name, "w");

    close_preserve_errno(map_dirfd);

    if (!fp) {

        return -1;

    }



    if (credp->fc_uid != -1) {

        uid = credp->fc_uid;

    }

    if (credp->fc_gid != -1) {

        gid = credp->fc_gid;

    }

    if (credp->fc_mode != -1) {

        mode = credp->fc_mode;

    }

    if (credp->fc_rdev != -1) {

        rdev = credp->fc_rdev;

    }



    if (uid != -1) {

        fprintf(fp, "virtfs.uid=%d\n", uid);

    }

    if (gid != -1) {

        fprintf(fp, "virtfs.gid=%d\n", gid);

    }

    if (mode != -1) {

        fprintf(fp, "virtfs.mode=%d\n", mode);

    }

    if (rdev != -1) {

        fprintf(fp, "virtfs.rdev=%d\n", rdev);

    }

    fclose(fp);



    return 0;

}

static void check_ieee_exceptions(CPUSPARCState *env)

{

    target_ulong status;



    status = get_float_exception_flags(&env->fp_status);

    if (status) {

        /* Copy IEEE 754 flags into FSR */

        if (status & float_flag_invalid) {

            env->fsr |= FSR_NVC;

        }

        if (status & float_flag_overflow) {

            env->fsr |= FSR_OFC;

        }

        if (status & float_flag_underflow) {

            env->fsr |= FSR_UFC;

        }

        if (status & float_flag_divbyzero) {

            env->fsr |= FSR_DZC;

        }

        if (status & float_flag_inexact) {

            env->fsr |= FSR_NXC;

        }



        if ((env->fsr & FSR_CEXC_MASK) & ((env->fsr & FSR_TEM_MASK) >> 23)) {

            /* Unmasked exception, generate a trap */

            env->fsr |= FSR_FTT_IEEE_EXCP;

            helper_raise_exception(env, TT_FP_EXCP);

        } else {

            /* Accumulate exceptions */

            env->fsr |= (env->fsr & FSR_CEXC_MASK) << 5;

        }

    }

}

static hwaddr ppc_hash64_htab_lookup(PowerPCCPU *cpu,

                                     ppc_slb_t *slb, target_ulong eaddr,

                                     ppc_hash_pte64_t *pte, unsigned *pshift)

{

    CPUPPCState *env = &cpu->env;

    hwaddr hash, ptex;

    uint64_t vsid, epnmask, epn, ptem;

    const struct ppc_one_seg_page_size *sps = slb->sps;



    /* The SLB store path should prevent any bad page size encodings

     * getting in there, so: */

    assert(sps);



    /* If ISL is set in LPCR we need to clamp the page size to 4K */

    if (env->spr[SPR_LPCR] & LPCR_ISL) {

        /* We assume that when using TCG, 4k is first entry of SPS */

        sps = &env->sps.sps[0];

        assert(sps->page_shift == 12);

    }



    epnmask = ~((1ULL << sps->page_shift) - 1);



    if (slb->vsid & SLB_VSID_B) {

        /* 1TB segment */

        vsid = (slb->vsid & SLB_VSID_VSID) >> SLB_VSID_SHIFT_1T;

        epn = (eaddr & ~SEGMENT_MASK_1T) & epnmask;

        hash = vsid ^ (vsid << 25) ^ (epn >> sps->page_shift);

    } else {

        /* 256M segment */

        vsid = (slb->vsid & SLB_VSID_VSID) >> SLB_VSID_SHIFT;

        epn = (eaddr & ~SEGMENT_MASK_256M) & epnmask;

        hash = vsid ^ (epn >> sps->page_shift);

    }

    ptem = (slb->vsid & SLB_VSID_PTEM) | ((epn >> 16) & HPTE64_V_AVPN);

    ptem |= HPTE64_V_VALID;



    /* Page address translation */

    qemu_log_mask(CPU_LOG_MMU,

            "htab_base " TARGET_FMT_plx " htab_mask " TARGET_FMT_plx

            " hash " TARGET_FMT_plx "\n",

            env->htab_base, env->htab_mask, hash);



    /* Primary PTEG lookup */

    qemu_log_mask(CPU_LOG_MMU,

            "0 htab=" TARGET_FMT_plx "/" TARGET_FMT_plx

            " vsid=" TARGET_FMT_lx " ptem=" TARGET_FMT_lx

            " hash=" TARGET_FMT_plx "\n",

            env->htab_base, env->htab_mask, vsid, ptem,  hash);

    ptex = ppc_hash64_pteg_search(cpu, hash, sps, ptem, pte, pshift);



    if (ptex == -1) {

        /* Secondary PTEG lookup */

        ptem |= HPTE64_V_SECONDARY;

        qemu_log_mask(CPU_LOG_MMU,

                "1 htab=" TARGET_FMT_plx "/" TARGET_FMT_plx

                " vsid=" TARGET_FMT_lx " api=" TARGET_FMT_lx

                " hash=" TARGET_FMT_plx "\n", env->htab_base,

                env->htab_mask, vsid, ptem, ~hash);



        ptex = ppc_hash64_pteg_search(cpu, ~hash, sps, ptem, pte, pshift);

    }



    return ptex;

}

QemuOpts *qemu_opts_create(QemuOptsList *list, const char *id,

                           int fail_if_exists, Error **errp)

{

    QemuOpts *opts = NULL;



    if (id) {

        if (!id_wellformed(id)) {

            error_set(errp,QERR_INVALID_PARAMETER_VALUE, "id", "an identifier");

#if 0 /* conversion from qerror_report() to error_set() broke this: */

            error_printf_unless_qmp("Identifiers consist of letters, digits, '-', '.', '_', starting with a letter.\n");

#endif

            return NULL;

        }

        opts = qemu_opts_find(list, id);

        if (opts != NULL) {

            if (fail_if_exists && !list->merge_lists) {

                error_setg(errp, "Duplicate ID '%s' for %s", id, list->name);

                return NULL;

            } else {

                return opts;

            }

        }

    } else if (list->merge_lists) {

        opts = qemu_opts_find(list, NULL);

        if (opts) {

            return opts;

        }

    }

    opts = g_malloc0(sizeof(*opts));

    opts->id = g_strdup(id);

    opts->list = list;

    loc_save(&opts->loc);

    QTAILQ_INIT(&opts->head);

    QTAILQ_INSERT_TAIL(&list->head, opts, next);

    return opts;

}

static int coroutine_fn backup_run_incremental(BackupBlockJob *job)

{

    bool error_is_read;

    int ret = 0;

    int clusters_per_iter;

    uint32_t granularity;

    int64_t sector;

    int64_t cluster;

    int64_t end;

    int64_t last_cluster = -1;

    int64_t sectors_per_cluster = cluster_size_sectors(job);

    BdrvDirtyBitmapIter *dbi;



    granularity = bdrv_dirty_bitmap_granularity(job->sync_bitmap);

    clusters_per_iter = MAX((granularity / job->cluster_size), 1);

    dbi = bdrv_dirty_iter_new(job->sync_bitmap, 0);



    /* Find the next dirty sector(s) */

    while ((sector = bdrv_dirty_iter_next(dbi)) != -1) {

        cluster = sector / sectors_per_cluster;



        /* Fake progress updates for any clusters we skipped */

        if (cluster != last_cluster + 1) {

            job->common.offset += ((cluster - last_cluster - 1) *

                                   job->cluster_size);

        }



        for (end = cluster + clusters_per_iter; cluster < end; cluster++) {

            do {

                if (yield_and_check(job)) {

                    goto out;

                }

                ret = backup_do_cow(job, cluster * job->cluster_size,

                                    job->cluster_size, &error_is_read,

                                    false);

                if ((ret < 0) &&

                    backup_error_action(job, error_is_read, -ret) ==

                    BLOCK_ERROR_ACTION_REPORT) {

                    goto out;

                }

            } while (ret < 0);

        }



        /* If the bitmap granularity is smaller than the backup granularity,

         * we need to advance the iterator pointer to the next cluster. */

        if (granularity < job->cluster_size) {

            bdrv_set_dirty_iter(dbi, cluster * sectors_per_cluster);

        }



        last_cluster = cluster - 1;

    }



    /* Play some final catchup with the progress meter */

    end = DIV_ROUND_UP(job->common.len, job->cluster_size);

    if (last_cluster + 1 < end) {

        job->common.offset += ((end - last_cluster - 1) * job->cluster_size);

    }



out:

    bdrv_dirty_iter_free(dbi);

    return ret;

}

static uint64_t omap_eac_read(void *opaque, target_phys_addr_t addr,

                              unsigned size)

{

    struct omap_eac_s *s = (struct omap_eac_s *) opaque;

    uint32_t ret;



    if (size != 2) {

        return omap_badwidth_read16(opaque, addr);

    }



    switch (addr) {

    case 0x000:	/* CPCFR1 */

        return s->config[0];

    case 0x004:	/* CPCFR2 */

        return s->config[1];

    case 0x008:	/* CPCFR3 */

        return s->config[2];

    case 0x00c:	/* CPCFR4 */

        return s->config[3];



    case 0x010:	/* CPTCTL */

        return s->control | ((s->codec.rxavail + s->codec.rxlen > 0) << 7) |

                ((s->codec.txlen < s->codec.txavail) << 5);



    case 0x014:	/* CPTTADR */

        return s->address;

    case 0x018:	/* CPTDATL */

        return s->data & 0xff;

    case 0x01c:	/* CPTDATH */

        return s->data >> 8;

    case 0x020:	/* CPTVSLL */

        return s->vtol;

    case 0x024:	/* CPTVSLH */

        return s->vtsl | (3 << 5);	/* CRDY1 | CRDY2 */

    case 0x040:	/* MPCTR */

        return s->modem.control;

    case 0x044:	/* MPMCCFR */

        return s->modem.config;

    case 0x060:	/* BPCTR */

        return s->bt.control;

    case 0x064:	/* BPMCCFR */

        return s->bt.config;

    case 0x080:	/* AMSCFR */

        return s->mixer;

    case 0x084:	/* AMVCTR */

        return s->gain[0];

    case 0x088:	/* AM1VCTR */

        return s->gain[1];

    case 0x08c:	/* AM2VCTR */

        return s->gain[2];

    case 0x090:	/* AM3VCTR */

        return s->gain[3];

    case 0x094:	/* ASTCTR */

        return s->att;

    case 0x098:	/* APD1LCR */

        return s->max[0];

    case 0x09c:	/* APD1RCR */

        return s->max[1];

    case 0x0a0:	/* APD2LCR */

        return s->max[2];

    case 0x0a4:	/* APD2RCR */

        return s->max[3];

    case 0x0a8:	/* APD3LCR */

        return s->max[4];

    case 0x0ac:	/* APD3RCR */

        return s->max[5];

    case 0x0b0:	/* APD4R */

        return s->max[6];

    case 0x0b4:	/* ADWR */

        /* This should be write-only?  Docs list it as read-only.  */

        return 0x0000;

    case 0x0b8:	/* ADRDR */

        if (likely(s->codec.rxlen > 1)) {

            ret = s->codec.rxbuf[s->codec.rxoff ++];

            s->codec.rxlen --;

            s->codec.rxoff &= EAC_BUF_LEN - 1;

            return ret;

        } else if (s->codec.rxlen) {

            ret = s->codec.rxbuf[s->codec.rxoff ++];

            s->codec.rxlen --;

            s->codec.rxoff &= EAC_BUF_LEN - 1;

            if (s->codec.rxavail)

                omap_eac_in_refill(s);

            omap_eac_in_dmarequest_update(s);

            return ret;

        }

        return 0x0000;

    case 0x0bc:	/* AGCFR */

        return s->codec.config[0];

    case 0x0c0:	/* AGCTR */

        return s->codec.config[1] | ((s->codec.config[1] & 2) << 14);

    case 0x0c4:	/* AGCFR2 */

        return s->codec.config[2];

    case 0x0c8:	/* AGCFR3 */

        return s->codec.config[3];

    case 0x0cc:	/* MBPDMACTR */

    case 0x0d0:	/* MPDDMARR */

    case 0x0d8:	/* MPUDMARR */

    case 0x0e4:	/* BPDDMARR */

    case 0x0ec:	/* BPUDMARR */

        return 0x0000;



    case 0x100:	/* VERSION_NUMBER */

        return 0x0010;



    case 0x104:	/* SYSCONFIG */

        return s->sysconfig;



    case 0x108:	/* SYSSTATUS */

        return 1 | 0xe;					/* RESETDONE | stuff */

    }



    OMAP_BAD_REG(addr);

    return 0;

}

