    if (strstr(devname, "auto:")) {

        if (parse_filter(devname, &filter) < 0) {

            goto fail;

        }

    } else {

        p = strchr(devname, '.');

        if (p) {

            filter.bus_num    = strtoul(devname, NULL, 0);

            filter.addr       = strtoul(p + 1, NULL, 0);

            filter.vendor_id  = 0;

            filter.product_id = 0;

