            p = strchr(devname, ':');

            if (p) {

                filter.bus_num    = 0;

                filter.addr       = 0;

                filter.vendor_id  = strtoul(devname, NULL, 16);

                filter.product_id = strtoul(p + 1, NULL, 16);

            } else {

                goto fail;

            }

        }

