        };



        s->gpt[i].ccm = IMX_CCM(&s->ccm);



        object_property_set_bool(OBJECT(&s->gpt[i]), true, "realized", &err);

        if (err) {

            error_propagate(errp, err);

            return;

        }

        sysbus_mmio_map(SYS_BUS_DEVICE(&s->gpt[i]), 0, gpt_table[i].addr);

