static coroutine_fn void nbd_trip(void *opaque)

{

    NBDClient *client = opaque;

    NBDExport *exp = client->exp;

    NBDRequestData *req;

    NBDRequest request = { 0 };    /* GCC thinks it can be used uninitialized */

    int ret;

    int flags;

    int reply_data_len = 0;

    Error *local_err = NULL;

    char *msg = NULL;



    trace_nbd_trip();

    if (client->closing) {

        nbd_client_put(client);

        return;

    }



    req = nbd_request_get(client);

    ret = nbd_co_receive_request(req, &request, &local_err);

    client->recv_coroutine = NULL;

    nbd_client_receive_next_request(client);

    if (ret == -EIO) {

        goto disconnect;

    }



    if (ret < 0) {

        goto reply;

    }



    if (client->closing) {

        /*

         * The client may be closed when we are blocked in

         * nbd_co_receive_request()

         */

        goto done;

    }



    switch (request.type) {

    case NBD_CMD_READ:

        /* XXX: NBD Protocol only documents use of FUA with WRITE */

        if (request.flags & NBD_CMD_FLAG_FUA) {

            ret = blk_co_flush(exp->blk);

            if (ret < 0) {

                error_setg_errno(&local_err, -ret, "flush failed");

                break;

            }

        }



        ret = blk_pread(exp->blk, request.from + exp->dev_offset,

                        req->data, request.len);

        if (ret < 0) {

            error_setg_errno(&local_err, -ret, "reading from file failed");

            break;

        }



        reply_data_len = request.len;



        break;

    case NBD_CMD_WRITE:

        if (exp->nbdflags & NBD_FLAG_READ_ONLY) {

            error_setg(&local_err, "Export is read-only");

            ret = -EROFS;

            break;

        }



        flags = 0;

        if (request.flags & NBD_CMD_FLAG_FUA) {

            flags |= BDRV_REQ_FUA;

        }

        ret = blk_pwrite(exp->blk, request.from + exp->dev_offset,

                         req->data, request.len, flags);

        if (ret < 0) {

            error_setg_errno(&local_err, -ret, "writing to file failed");

        }



        break;

    case NBD_CMD_WRITE_ZEROES:

        if (exp->nbdflags & NBD_FLAG_READ_ONLY) {

            error_setg(&local_err, "Export is read-only");

            ret = -EROFS;

            break;

        }



        flags = 0;

        if (request.flags & NBD_CMD_FLAG_FUA) {

            flags |= BDRV_REQ_FUA;

        }

        if (!(request.flags & NBD_CMD_FLAG_NO_HOLE)) {

            flags |= BDRV_REQ_MAY_UNMAP;

        }

        ret = blk_pwrite_zeroes(exp->blk, request.from + exp->dev_offset,

                                request.len, flags);

        if (ret < 0) {

            error_setg_errno(&local_err, -ret, "writing to file failed");

        }



        break;

    case NBD_CMD_DISC:

        /* unreachable, thanks to special case in nbd_co_receive_request() */

        abort();



    case NBD_CMD_FLUSH:

        ret = blk_co_flush(exp->blk);

        if (ret < 0) {

            error_setg_errno(&local_err, -ret, "flush failed");

        }



        break;

    case NBD_CMD_TRIM:

        ret = blk_co_pdiscard(exp->blk, request.from + exp->dev_offset,

                              request.len);

        if (ret < 0) {

            error_setg_errno(&local_err, -ret, "discard failed");

        }



        break;

    default:

        error_setg(&local_err, "invalid request type (%" PRIu32 ") received",

                   request.type);

        ret = -EINVAL;

    }



reply:

    if (local_err) {

        /* If we get here, local_err was not a fatal error, and should be sent

         * to the client. */

        assert(ret < 0);

        msg = g_strdup(error_get_pretty(local_err));

        error_report_err(local_err);

        local_err = NULL;

    }



    if (client->structured_reply &&

        (ret < 0 || request.type == NBD_CMD_READ)) {

        if (ret < 0) {

            ret = nbd_co_send_structured_error(req->client, request.handle,

                                               -ret, msg, &local_err);

        } else {

            ret = nbd_co_send_structured_read(req->client, request.handle,

                                              request.from, req->data,

                                              reply_data_len, &local_err);

        }

    } else {

        ret = nbd_co_send_simple_reply(req->client, request.handle,

                                       ret < 0 ? -ret : 0,

                                       req->data, reply_data_len, &local_err);

    }

    g_free(msg);

    if (ret < 0) {

        error_prepend(&local_err, "Failed to send reply: ");

        goto disconnect;

    }



    /* We must disconnect after NBD_CMD_WRITE if we did not

     * read the payload.

     */

    if (!req->complete) {

        error_setg(&local_err, "Request handling failed in intermediate state");

        goto disconnect;

    }



done:

    nbd_request_put(req);

    nbd_client_put(client);

    return;



disconnect:

    if (local_err) {

        error_reportf_err(local_err, "Disconnect client, due to: ");

    }

    nbd_request_put(req);

    client_close(client, true);

    nbd_client_put(client);

}

static inline void tb_alloc_page(TranslationBlock *tb,

                                 unsigned int n, tb_page_addr_t page_addr)

{

    PageDesc *p;

#ifndef CONFIG_USER_ONLY

    bool page_already_protected;

#endif



    assert_memory_lock();



    tb->page_addr[n] = page_addr;

    p = page_find_alloc(page_addr >> TARGET_PAGE_BITS, 1);

    tb->page_next[n] = p->first_tb;

#ifndef CONFIG_USER_ONLY

    page_already_protected = p->first_tb != NULL;

#endif

    p->first_tb = (TranslationBlock *)((uintptr_t)tb | n);

    invalidate_page_bitmap(p);



#if defined(CONFIG_USER_ONLY)

    if (p->flags & PAGE_WRITE) {

        target_ulong addr;

        PageDesc *p2;

        int prot;



        /* force the host page as non writable (writes will have a

           page fault + mprotect overhead) */

        page_addr &= qemu_host_page_mask;

        prot = 0;

        for (addr = page_addr; addr < page_addr + qemu_host_page_size;

            addr += TARGET_PAGE_SIZE) {



            p2 = page_find(addr >> TARGET_PAGE_BITS);

            if (!p2) {

                continue;

            }

            prot |= p2->flags;

            p2->flags &= ~PAGE_WRITE;

          }

        mprotect(g2h(page_addr), qemu_host_page_size,

                 (prot & PAGE_BITS) & ~PAGE_WRITE);

#ifdef DEBUG_TB_INVALIDATE

        printf("protecting code page: 0x" TARGET_FMT_lx "\n",

               page_addr);

#endif

    }

#else

    /* if some code is already present, then the pages are already

       protected. So we handle the case where only the first TB is

       allocated in a physical page */

    if (!page_already_protected) {

        tlb_protect_code(page_addr);

    }

#endif

}

void address_space_destroy(AddressSpace *as)

{

    /* Flush out anything from MemoryListeners listening in on this */

    memory_region_transaction_begin();

    as->root = NULL;

    memory_region_transaction_commit();

    QTAILQ_REMOVE(&address_spaces, as, address_spaces_link);

    address_space_destroy_dispatch(as);

    flatview_destroy(as->current_map);

    g_free(as->current_map);


}

