    int i;

    QObject *obj;

    QString *str;

    const char *json_in, *utf8_out, *utf8_in, *json_out;



    for (i = 0; test_cases[i].json_in; i++) {

        json_in = test_cases[i].json_in;

        utf8_out = test_cases[i].utf8_out;

        utf8_in = test_cases[i].utf8_in ?: test_cases[i].utf8_out;

        json_out = test_cases[i].json_out ?: test_cases[i].json_in;



        obj = qobject_from_json(json_in, NULL);

        if (utf8_out) {

            str = qobject_to_qstring(obj);

            g_assert(str);

            g_assert_cmpstr(qstring_get_str(str), ==, utf8_out);

        } else {

            g_assert(!obj);

        }

        qobject_decref(obj);



        obj = QOBJECT(qstring_from_str(utf8_in));

        str = qobject_to_json(obj);

        if (json_out) {

            g_assert(str);

            g_assert_cmpstr(qstring_get_str(str), ==, json_out);

        } else {

            g_assert(!str);

        }

        QDECREF(str);

        qobject_decref(obj);



        /*

         * Disabled, because qobject_from_json() is buggy, and I can't

         * be bothered to add the expected incorrect results.

         * FIXME Enable once these bugs have been fixed.

         */

        if (0 && json_out != json_in) {

            obj = qobject_from_json(json_out, NULL);

            str = qobject_to_qstring(obj);

            g_assert(str);

            g_assert_cmpstr(qstring_get_str(str), ==, utf8_out);

        }

    }

}

SubchDev *css_create_sch(CssDevId bus_id, bool is_virtual, bool squash_mcss,

                         Error **errp)

{

    uint16_t schid = 0;

    SubchDev *sch;



    if (bus_id.valid) {

        if (is_virtual != (bus_id.cssid == VIRTUAL_CSSID)) {

            error_setg(errp, "cssid %hhx not valid for %s devices",

                       bus_id.cssid,

                       (is_virtual ? "virtual" : "non-virtual"));

            return NULL;

        }

    }



    if (bus_id.valid) {

        if (squash_mcss) {

            bus_id.cssid = channel_subsys.default_cssid;

        } else if (!channel_subsys.css[bus_id.cssid]) {

            css_create_css_image(bus_id.cssid, false);

        }



        if (!css_find_free_subch_for_devno(bus_id.cssid, bus_id.ssid,

                                           bus_id.devid, &schid, errp)) {

            return NULL;

        }

    } else if (squash_mcss || is_virtual) {

        bus_id.cssid = channel_subsys.default_cssid;



        if (!css_find_free_subch_and_devno(bus_id.cssid, &bus_id.ssid,

                                           &bus_id.devid, &schid, errp)) {

            return NULL;

        }

    } else {

        for (bus_id.cssid = 0; bus_id.cssid < MAX_CSSID; ++bus_id.cssid) {

            if (bus_id.cssid == VIRTUAL_CSSID) {

                continue;

            }



            if (!channel_subsys.css[bus_id.cssid]) {

                css_create_css_image(bus_id.cssid, false);

            }



            if   (css_find_free_subch_and_devno(bus_id.cssid, &bus_id.ssid,

                                                &bus_id.devid, &schid,

                                                NULL)) {

                break;

            }

            if (bus_id.cssid == MAX_CSSID) {

                error_setg(errp, "Virtual channel subsystem is full!");

                return NULL;

            }

        }

    }



    sch = g_new0(SubchDev, 1);

    sch->cssid = bus_id.cssid;

    sch->ssid = bus_id.ssid;

    sch->devno = bus_id.devid;

    sch->schid = schid;

    css_subch_assign(sch->cssid, sch->ssid, schid, sch->devno, sch);

    return sch;

}

static int vdi_create(const char *filename, QemuOpts *opts, Error **errp)

{

    int ret = 0;

    uint64_t bytes = 0;

    uint32_t blocks;

    size_t block_size = DEFAULT_CLUSTER_SIZE;

    uint32_t image_type = VDI_TYPE_DYNAMIC;

    VdiHeader header;

    size_t i;

    size_t bmap_size;

    int64_t offset = 0;

    Error *local_err = NULL;

    BlockDriverState *bs = NULL;

    uint32_t *bmap = NULL;



    logout("\n");



    /* Read out options. */

    bytes = qemu_opt_get_size_del(opts, BLOCK_OPT_SIZE, 0);

#if defined(CONFIG_VDI_BLOCK_SIZE)

    /* TODO: Additional checks (SECTOR_SIZE * 2^n, ...). */

    block_size = qemu_opt_get_size_del(opts,

                                       BLOCK_OPT_CLUSTER_SIZE,

                                       DEFAULT_CLUSTER_SIZE);

#endif

#if defined(CONFIG_VDI_STATIC_IMAGE)

    if (qemu_opt_get_bool_del(opts, BLOCK_OPT_STATIC, false)) {

        image_type = VDI_TYPE_STATIC;

    }

#endif



    if (bytes > VDI_DISK_SIZE_MAX) {

        ret = -ENOTSUP;

        error_setg(errp, "Unsupported VDI image size (size is 0x%" PRIx64

                          ", max supported is 0x%" PRIx64 ")",

                          bytes, VDI_DISK_SIZE_MAX);

        goto exit;

    }



    ret = bdrv_create_file(filename, opts, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto exit;

    }

    ret = bdrv_open(&bs, filename, NULL, NULL, BDRV_O_RDWR | BDRV_O_PROTOCOL,

                    NULL, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto exit;

    }



    /* We need enough blocks to store the given disk size,

       so always round up. */

    blocks = (bytes + block_size - 1) / block_size;



    bmap_size = blocks * sizeof(uint32_t);

    bmap_size = ((bmap_size + SECTOR_SIZE - 1) & ~(SECTOR_SIZE -1));



    memset(&header, 0, sizeof(header));

    pstrcpy(header.text, sizeof(header.text), VDI_TEXT);

    header.signature = VDI_SIGNATURE;

    header.version = VDI_VERSION_1_1;

    header.header_size = 0x180;

    header.image_type = image_type;

    header.offset_bmap = 0x200;

    header.offset_data = 0x200 + bmap_size;

    header.sector_size = SECTOR_SIZE;

    header.disk_size = bytes;

    header.block_size = block_size;

    header.blocks_in_image = blocks;

    if (image_type == VDI_TYPE_STATIC) {

        header.blocks_allocated = blocks;

    }

    uuid_generate(header.uuid_image);

    uuid_generate(header.uuid_last_snap);

    /* There is no need to set header.uuid_link or header.uuid_parent here. */

#if defined(CONFIG_VDI_DEBUG)

    vdi_header_print(&header);

#endif

    vdi_header_to_le(&header);

    ret = bdrv_pwrite_sync(bs, offset, &header, sizeof(header));

    if (ret < 0) {

        error_setg(errp, "Error writing header to %s", filename);

        goto exit;

    }

    offset += sizeof(header);



    if (bmap_size > 0) {

        bmap = g_malloc0(bmap_size);

        for (i = 0; i < blocks; i++) {

            if (image_type == VDI_TYPE_STATIC) {

                bmap[i] = i;

            } else {

                bmap[i] = VDI_UNALLOCATED;

            }

        }

        ret = bdrv_pwrite_sync(bs, offset, bmap, bmap_size);

        if (ret < 0) {

            error_setg(errp, "Error writing bmap to %s", filename);

            goto exit;

        }

        offset += bmap_size;

    }



    if (image_type == VDI_TYPE_STATIC) {

        ret = bdrv_truncate(bs, offset + blocks * block_size);

        if (ret < 0) {

            error_setg(errp, "Failed to statically allocate %s", filename);

            goto exit;

        }

    }



exit:

    bdrv_unref(bs);

    g_free(bmap);

    return ret;

}

int usb_handle_packet(USBDevice *dev, USBPacket *p)

{

    int ret;



    if (dev == NULL) {

        return USB_RET_NODEV;

    }

    assert(dev->addr == p->devaddr);

    assert(dev->state == USB_STATE_DEFAULT);

    assert(p->owner == NULL);



    if (p->devep == 0) {

        /* control pipe */

        switch (p->pid) {

        case USB_TOKEN_SETUP:

            ret = do_token_setup(dev, p);

            break;

        case USB_TOKEN_IN:

            ret = do_token_in(dev, p);

            break;

        case USB_TOKEN_OUT:

            ret = do_token_out(dev, p);

            break;

        default:

            ret = USB_RET_STALL;

            break;

        }

    } else {

        /* data pipe */

        ret = usb_device_handle_data(dev, p);

    }



    if (ret == USB_RET_ASYNC) {

        p->owner = usb_ep_get(dev, p->pid, p->devep);

    }

    return ret;

}

static void old_pc_system_rom_init(MemoryRegion *rom_memory, bool isapc_ram_fw)

{

    char *filename;

    MemoryRegion *bios, *isa_bios;

    int bios_size, isa_bios_size;

    int ret;



    /* BIOS load */

    if (bios_name == NULL) {

        bios_name = BIOS_FILENAME;

    }

    filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);

    if (filename) {

        bios_size = get_image_size(filename);

    } else {

        bios_size = -1;

    }

    if (bios_size <= 0 ||

        (bios_size % 65536) != 0) {

        goto bios_error;

    }

    bios = g_malloc(sizeof(*bios));

    memory_region_init_ram(bios, NULL, "pc.bios", bios_size, &error_abort);

    vmstate_register_ram_global(bios);

    if (!isapc_ram_fw) {

        memory_region_set_readonly(bios, true);

    }

    ret = rom_add_file_fixed(bios_name, (uint32_t)(-bios_size), -1);

    if (ret != 0) {

    bios_error:

        fprintf(stderr, "qemu: could not load PC BIOS '%s'\n", bios_name);

        exit(1);

    }

    g_free(filename);



    /* map the last 128KB of the BIOS in ISA space */

    isa_bios_size = bios_size;

    if (isa_bios_size > (128 * 1024)) {

        isa_bios_size = 128 * 1024;

    }

    isa_bios = g_malloc(sizeof(*isa_bios));

    memory_region_init_alias(isa_bios, NULL, "isa-bios", bios,

                             bios_size - isa_bios_size, isa_bios_size);

    memory_region_add_subregion_overlap(rom_memory,

                                        0x100000 - isa_bios_size,

                                        isa_bios,

                                        1);

    if (!isapc_ram_fw) {

        memory_region_set_readonly(isa_bios, true);

    }



    /* map all the bios at the top of memory */

    memory_region_add_subregion(rom_memory,

                                (uint32_t)(-bios_size),

                                bios);

}

static int kvm_handle_debug(PowerPCCPU *cpu, struct kvm_run *run)

{

    CPUState *cs = CPU(cpu);

    CPUPPCState *env = &cpu->env;

    struct kvm_debug_exit_arch *arch_info = &run->debug.arch;

    int handle = 0;



    if (kvm_find_sw_breakpoint(cs, arch_info->address)) {

        handle = 1;

    } else {

        /* QEMU is not able to handle debug exception, so inject

         * program exception to guest;

         * Yes program exception NOT debug exception !!

         * For software breakpoint QEMU uses a privileged instruction;

         * So there cannot be any reason that we are here for guest

         * set debug exception, only possibility is guest executed a

         * privileged / illegal instruction and that's why we are

         * injecting a program interrupt.

         */



        cpu_synchronize_state(cs);

        /* env->nip is PC, so increment this by 4 to use

         * ppc_cpu_do_interrupt(), which set srr0 = env->nip - 4.

         */

        env->nip += 4;

        cs->exception_index = POWERPC_EXCP_PROGRAM;

        env->error_code = POWERPC_EXCP_INVAL;

        ppc_cpu_do_interrupt(cs);

    }



    return handle;

}

void helper_ldda_asi(target_ulong addr, int asi, int rd)

{

    if ((asi < 0x80 && (env->pstate & PS_PRIV) == 0)

        || ((env->def->features & CPU_FEATURE_HYPV)

            && asi >= 0x30 && asi < 0x80

            && !(env->hpstate & HS_PRIV)))

        raise_exception(TT_PRIV_ACT);



    switch (asi) {

    case 0x24: // Nucleus quad LDD 128 bit atomic

    case 0x2c: // Nucleus quad LDD 128 bit atomic LE

        helper_check_align(addr, 0xf);

        if (rd == 0) {

            env->gregs[1] = ldq_kernel(addr + 8);

            if (asi == 0x2c)

                bswap64s(&env->gregs[1]);

        } else if (rd < 8) {

            env->gregs[rd] = ldq_kernel(addr);

            env->gregs[rd + 1] = ldq_kernel(addr + 8);

            if (asi == 0x2c) {

                bswap64s(&env->gregs[rd]);

                bswap64s(&env->gregs[rd + 1]);

            }

        } else {

            env->regwptr[rd] = ldq_kernel(addr);

            env->regwptr[rd + 1] = ldq_kernel(addr + 8);

            if (asi == 0x2c) {

                bswap64s(&env->regwptr[rd]);

                bswap64s(&env->regwptr[rd + 1]);

            }

        }

        break;

    default:

        helper_check_align(addr, 0x3);

        if (rd == 0)

            env->gregs[1] = helper_ld_asi(addr + 4, asi, 4, 0);

        else if (rd < 8) {

            env->gregs[rd] = helper_ld_asi(addr, asi, 4, 0);

            env->gregs[rd + 1] = helper_ld_asi(addr + 4, asi, 4, 0);

        } else {

            env->regwptr[rd] = helper_ld_asi(addr, asi, 4, 0);

            env->regwptr[rd + 1] = helper_ld_asi(addr + 4, asi, 4, 0);

        }

        break;

    }

}

static void gen_read_xer(TCGv dst)

{

    TCGv t0 = tcg_temp_new();

    TCGv t1 = tcg_temp_new();

    TCGv t2 = tcg_temp_new();

    tcg_gen_mov_tl(dst, cpu_xer);

    tcg_gen_shli_tl(t0, cpu_so, XER_SO);

    tcg_gen_shli_tl(t1, cpu_ov, XER_OV);

    tcg_gen_shli_tl(t2, cpu_ca, XER_CA);

    tcg_gen_or_tl(t0, t0, t1);

    tcg_gen_or_tl(dst, dst, t2);

    tcg_gen_or_tl(dst, dst, t0);

    tcg_temp_free(t0);

    tcg_temp_free(t1);

    tcg_temp_free(t2);

}

