                                                naddrs,

                                                addrs,

                                                errp);



    default:

        abort();

    }

}

int fw_cfg_add_file(FWCfgState *s,  const char *dir, const char *filename,

                    uint8_t *data, uint32_t len)

{

    const char *basename;

    int index;



    if (!s->files) {

        int dsize = sizeof(uint32_t) + sizeof(FWCfgFile) * FW_CFG_FILE_SLOTS;

        s->files = qemu_mallocz(dsize);

        fw_cfg_add_bytes(s, FW_CFG_FILE_DIR, (uint8_t*)s->files, dsize);

    }



    index = be32_to_cpu(s->files->count);

    if (index == FW_CFG_FILE_SLOTS) {

        fprintf(stderr, "fw_cfg: out of file slots\n");

        return 0;

    }



    fw_cfg_add_bytes(s, FW_CFG_FILE_FIRST + index, data, len);



    basename = strrchr(filename, '/');

    if (basename) {

        basename++;

    } else {

        basename = filename;

    }

    if (dir) {

        snprintf(s->files->f[index].name, sizeof(s->files->f[index].name),

                 "%s/%s", dir, basename);

    } else {

        snprintf(s->files->f[index].name, sizeof(s->files->f[index].name),

                 "%s", basename);

    }

    s->files->f[index].size   = cpu_to_be32(len);

    s->files->f[index].select = cpu_to_be16(FW_CFG_FILE_FIRST + index);

    FW_CFG_DPRINTF("%s: #%d: %s (%d bytes)\n", __FUNCTION__,

                   index, s->files->f[index].name, len);



    s->files->count = cpu_to_be32(index+1);

    return 1;

}

void qmp_balloon(int64_t value, Error **errp)

{

    if (kvm_enabled() && !kvm_has_sync_mmu()) {

        error_set(errp, QERR_KVM_MISSING_CAP, "synchronous MMU", "balloon");

        return;

    }



    if (value <= 0) {

        error_set(errp, QERR_INVALID_PARAMETER_VALUE, "target", "a size");

        return;

    }



    if (qemu_balloon(value) == 0) {

        error_set(errp, QERR_DEVICE_NOT_ACTIVE, "balloon");

    }

}

struct GuestFileSeek *qmp_guest_file_seek(int64_t handle, int64_t offset,

                                          int64_t whence, Error **errp)

{

    GuestFileHandle *gfh = guest_file_handle_find(handle, errp);

    GuestFileSeek *seek_data = NULL;

    FILE *fh;

    int ret;



    if (!gfh) {

        return NULL;

    }



    fh = gfh->fh;

    ret = fseek(fh, offset, whence);

    if (ret == -1) {

        error_setg_errno(errp, errno, "failed to seek file");

        if (errno == ESPIPE) {

            /* file is non-seekable, stdio shouldn't be buffering anyways */

            gfh->state = RW_STATE_NEW;

        }

    } else {

        seek_data = g_new0(GuestFileSeek, 1);

        seek_data->position = ftell(fh);

        seek_data->eof = feof(fh);

        gfh->state = RW_STATE_NEW;

    }

    clearerr(fh);



    return seek_data;

}

static bool virtio_device_endian_needed(void *opaque)

{

    VirtIODevice *vdev = opaque;



    assert(vdev->device_endian != VIRTIO_DEVICE_ENDIAN_UNKNOWN);

    if (!virtio_has_feature(vdev, VIRTIO_F_VERSION_1)) {

        return vdev->device_endian != virtio_default_endian();

    }

    /* Devices conforming to VIRTIO 1.0 or later are always LE. */

    return vdev->device_endian != VIRTIO_DEVICE_ENDIAN_LITTLE;

}

static int uhci_handle_td(UHCIState *s, uint32_t addr, UHCI_TD *td, uint32_t *int_mask)

{

    UHCIAsync *async;

    int len = 0, max_len;

    uint8_t pid;



    /* Is active ? */

    if (!(td->ctrl & TD_CTRL_ACTIVE))

        return 1;



    async = uhci_async_find_td(s, addr, td->token);

    if (async) {

        /* Already submitted */

        async->valid = 32;



        if (!async->done)

            return 1;



        uhci_async_unlink(s, async);

        goto done;

    }



    /* Allocate new packet */

    async = uhci_async_alloc(s);

    if (!async)

        return 1;



    async->valid = 10;

    async->td    = addr;

    async->token = td->token;



    max_len = ((td->token >> 21) + 1) & 0x7ff;

    pid = td->token & 0xff;



    async->packet.pid     = pid;

    async->packet.devaddr = (td->token >> 8) & 0x7f;

    async->packet.devep   = (td->token >> 15) & 0xf;

    async->packet.data    = async->buffer;

    async->packet.len     = max_len;

    async->packet.complete_cb     = uhci_async_complete;

    async->packet.complete_opaque = s;



    switch(pid) {

    case USB_TOKEN_OUT:

    case USB_TOKEN_SETUP:

        cpu_physical_memory_read(td->buffer, async->buffer, max_len);

        len = uhci_broadcast_packet(s, &async->packet);

        if (len >= 0)

            len = max_len;

        break;



    case USB_TOKEN_IN:

        len = uhci_broadcast_packet(s, &async->packet);

        break;



    default:

        /* invalid pid : frame interrupted */

        uhci_async_free(s, async);

        s->status |= UHCI_STS_HCPERR;

        uhci_update_irq(s);

        return -1;

    }



    if (len == USB_RET_ASYNC) {

        uhci_async_link(s, async);

        return 2;

    }



    async->packet.len = len;



done:

    len = uhci_complete_td(s, td, async, int_mask);

    uhci_async_free(s, async);

    return len;

}

static void omap_pwt_write(void *opaque, hwaddr addr,

                           uint64_t value, unsigned size)

{

    struct omap_pwt_s *s = (struct omap_pwt_s *) opaque;

    int offset = addr & OMAP_MPUI_REG_MASK;



    if (size != 1) {

        omap_badwidth_write8(opaque, addr, value);

        return;

    }



    switch (offset) {

    case 0x00:	/* FRC */

        s->frc = value & 0x3f;

        break;

    case 0x04:	/* VRC */

        if ((value ^ s->vrc) & 1) {

            if (value & 1)

                printf("%s: %iHz buzz on\n", __FUNCTION__, (int)

                                /* 1.5 MHz from a 12-MHz or 13-MHz PWT_CLK */

                                ((omap_clk_getrate(s->clk) >> 3) /

                                 /* Pre-multiplexer divider */

                                 ((s->gcr & 2) ? 1 : 154) /

                                 /* Octave multiplexer */

                                 (2 << (value & 3)) *

                                 /* 101/107 divider */

                                 ((value & (1 << 2)) ? 101 : 107) *

                                 /*  49/55 divider */

                                 ((value & (1 << 3)) ?  49 : 55) *

                                 /*  50/63 divider */

                                 ((value & (1 << 4)) ?  50 : 63) *

                                 /*  80/127 divider */

                                 ((value & (1 << 5)) ?  80 : 127) /

                                 (107 * 55 * 63 * 127)));

            else

                printf("%s: silence!\n", __FUNCTION__);

        }

        s->vrc = value & 0x7f;

        break;

    case 0x08:	/* GCR */

        s->gcr = value & 3;

        break;

    default:

        OMAP_BAD_REG(addr);

        return;

    }

}

