static int ram_save_block(QEMUFile *f, bool last_stage)

{

    RAMBlock *block = last_seen_block;

    ram_addr_t offset = last_offset;

    bool complete_round = false;

    int bytes_sent = 0;

    MemoryRegion *mr;

    ram_addr_t current_addr;



    if (!block)

        block = QTAILQ_FIRST(&ram_list.blocks);



    while (true) {

        mr = block->mr;

        offset = migration_bitmap_find_and_reset_dirty(mr, offset);

        if (complete_round && block == last_seen_block &&

            offset >= last_offset) {

            break;

        }

        if (offset >= block->length) {

            offset = 0;

            block = QTAILQ_NEXT(block, next);

            if (!block) {

                block = QTAILQ_FIRST(&ram_list.blocks);

                complete_round = true;

                ram_bulk_stage = false;

            }

        } else {

            int ret;

            uint8_t *p;

            int cont = (block == last_sent_block) ?

                RAM_SAVE_FLAG_CONTINUE : 0;



            p = memory_region_get_ram_ptr(mr) + offset;



            /* In doubt sent page as normal */

            bytes_sent = -1;

            ret = ram_control_save_page(f, block->offset,

                               offset, TARGET_PAGE_SIZE, &bytes_sent);



            if (ret != RAM_SAVE_CONTROL_NOT_SUPP) {

                if (ret != RAM_SAVE_CONTROL_DELAYED) {

                    if (bytes_sent > 0) {

                        acct_info.norm_pages++;

                    } else if (bytes_sent == 0) {

                        acct_info.dup_pages++;

                    }

                }

            } else if (is_zero_range(p, TARGET_PAGE_SIZE)) {

                acct_info.dup_pages++;

                bytes_sent = save_block_hdr(f, block, offset, cont,

                                            RAM_SAVE_FLAG_COMPRESS);

                qemu_put_byte(f, 0);

                bytes_sent++;

            } else if (!ram_bulk_stage && migrate_use_xbzrle()) {

                current_addr = block->offset + offset;

                bytes_sent = save_xbzrle_page(f, p, current_addr, block,

                                              offset, cont, last_stage);

                if (!last_stage) {

                    p = get_cached_data(XBZRLE.cache, current_addr);

                }

            }



            /* XBZRLE overflow or normal page */

            if (bytes_sent == -1) {

                bytes_sent = save_block_hdr(f, block, offset, cont, RAM_SAVE_FLAG_PAGE);

                qemu_put_buffer_async(f, p, TARGET_PAGE_SIZE);

                bytes_sent += TARGET_PAGE_SIZE;

                acct_info.norm_pages++;

            }



            /* if page is unmodified, continue to the next */

            if (bytes_sent > 0) {

                last_sent_block = block;

                break;

            }

        }

    }

    last_seen_block = block;

    last_offset = offset;



    return bytes_sent;

}

static int ccid_handle_bulk_out(USBCCIDState *s, USBPacket *p)

{

    CCID_Header *ccid_header;



    if (p->len + s->bulk_out_pos > BULK_OUT_DATA_SIZE) {

        return USB_RET_STALL;

    }

    ccid_header = (CCID_Header *)s->bulk_out_data;

    memcpy(s->bulk_out_data + s->bulk_out_pos, p->data, p->len);

    s->bulk_out_pos += p->len;

    if (p->len == CCID_MAX_PACKET_SIZE) {

        DPRINTF(s, D_VERBOSE,

            "usb-ccid: bulk_in: expecting more packets (%d/%d)\n",

            p->len, ccid_header->dwLength);

        return 0;

    }

    if (s->bulk_out_pos < 10) {

        DPRINTF(s, 1,

                "%s: bad USB_TOKEN_OUT length, should be at least 10 bytes\n",

                __func__);

    } else {

        DPRINTF(s, D_MORE_INFO, "%s %x\n", __func__, ccid_header->bMessageType);

        switch (ccid_header->bMessageType) {

        case CCID_MESSAGE_TYPE_PC_to_RDR_GetSlotStatus:

            ccid_write_slot_status(s, ccid_header);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_IccPowerOn:

            DPRINTF(s, 1, "PowerOn: %d\n",

                ((CCID_IccPowerOn *)(ccid_header))->bPowerSelect);

            s->powered = true;

            if (!ccid_card_inserted(s)) {

                ccid_report_error_failed(s, ERROR_ICC_MUTE);

            }

            /* atr is written regardless of error. */

            ccid_write_data_block_atr(s, ccid_header);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_IccPowerOff:

            DPRINTF(s, 1, "PowerOff\n");

            ccid_reset_error_status(s);

            s->powered = false;

            ccid_write_slot_status(s, ccid_header);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_XfrBlock:

            ccid_on_apdu_from_guest(s, (CCID_XferBlock *)s->bulk_out_data);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_SetParameters:

            ccid_reset_error_status(s);

            ccid_set_parameters(s, ccid_header);

            ccid_write_parameters(s, ccid_header);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_ResetParameters:

            ccid_reset_error_status(s);

            ccid_reset_parameters(s);

            ccid_write_parameters(s, ccid_header);

            break;

        case CCID_MESSAGE_TYPE_PC_to_RDR_GetParameters:

            ccid_reset_error_status(s);

            ccid_write_parameters(s, ccid_header);

            break;

        default:

            DPRINTF(s, 1,

                "handle_data: ERROR: unhandled message type %Xh\n",

                ccid_header->bMessageType);

            /*

             * The caller is expecting the device to respond, tell it we

             * don't support the operation.

             */

            ccid_report_error_failed(s, ERROR_CMD_NOT_SUPPORTED);

            ccid_write_slot_status(s, ccid_header);

            break;

        }

    }

    s->bulk_out_pos = 0;

    return 0;

}

static int usbredir_handle_bulk_data(USBRedirDevice *dev, USBPacket *p,

                                      uint8_t ep)

{

    AsyncURB *aurb = async_alloc(dev, p);

    struct usb_redir_bulk_packet_header bulk_packet;



    DPRINTF("bulk-out ep %02X len %d id %u\n", ep, p->len, aurb->packet_id);



    bulk_packet.endpoint  = ep;

    bulk_packet.length    = p->len;

    bulk_packet.stream_id = 0;

    aurb->bulk_packet = bulk_packet;



    if (ep & USB_DIR_IN) {

        usbredirparser_send_bulk_packet(dev->parser, aurb->packet_id,

                                        &bulk_packet, NULL, 0);

    } else {

        usbredir_log_data(dev, "bulk data out:", p->data, p->len);

        usbredirparser_send_bulk_packet(dev->parser, aurb->packet_id,

                                        &bulk_packet, p->data, p->len);

    }

    usbredirparser_do_write(dev->parser);

    return USB_RET_ASYNC;

}

