static void add_pc_test_cases(void)

{

    QDict *response, *minfo;

    QList *list;

    const QListEntry *p;

    QObject *qobj;

    QString *qstr;

    const char *mname, *path;

    PCTestData *data;



    qtest_start("-machine none");

    response = qmp("{ 'execute': 'query-machines' }");

    g_assert(response);

    list = qdict_get_qlist(response, "return");

    g_assert(list);



    for (p = qlist_first(list); p; p = qlist_next(p)) {

        minfo = qobject_to_qdict(qlist_entry_obj(p));

        g_assert(minfo);

        qobj = qdict_get(minfo, "name");

        g_assert(qobj);

        qstr = qobject_to_qstring(qobj);

        g_assert(qstr);

        mname = qstring_get_str(qstr);

        if (!g_str_has_prefix(mname, "pc-")) {

            continue;

        }

        data = g_malloc(sizeof(PCTestData));

        data->machine = mname;

        data->cpu_model = "Haswell"; /* 1.3+ theoretically */

        data->sockets = 1;

        data->cores = 3;

        data->threads = 2;

        data->maxcpus = data->sockets * data->cores * data->threads * 2;

        if (g_str_has_suffix(mname, "-1.4") ||

            (strcmp(mname, "pc-1.3") == 0) ||

            (strcmp(mname, "pc-1.2") == 0) ||

            (strcmp(mname, "pc-1.1") == 0) ||

            (strcmp(mname, "pc-1.0") == 0) ||

            (strcmp(mname, "pc-0.15") == 0) ||

            (strcmp(mname, "pc-0.14") == 0) ||

            (strcmp(mname, "pc-0.13") == 0) ||

            (strcmp(mname, "pc-0.12") == 0) ||

            (strcmp(mname, "pc-0.11") == 0) ||

            (strcmp(mname, "pc-0.10") == 0)) {

            path = g_strdup_printf("cpu/%s/init/%ux%ux%u&maxcpus=%u",

                                   mname, data->sockets, data->cores,

                                   data->threads, data->maxcpus);

            qtest_add_data_func(path, data, test_pc_without_cpu_add);

        } else {

            path = g_strdup_printf("cpu/%s/add/%ux%ux%u&maxcpus=%u",

                                   mname, data->sockets, data->cores,

                                   data->threads, data->maxcpus);

            qtest_add_data_func(path, data, test_pc_with_cpu_add);

        }

    }

    qtest_end();

}

static void test_qga_set_time(gconstpointer fix)

{

    const TestFixture *fixture = fix;

    QDict *ret;

    int64_t current, time;

    gchar *cmd;



    /* get current time */

    ret = qmp_fd(fixture->fd, "{'execute': 'guest-get-time'}");

    g_assert_nonnull(ret);

    qmp_assert_no_error(ret);

    current = qdict_get_int(ret, "return");

    g_assert_cmpint(current, >, 0);

    QDECREF(ret);



    /* set some old time */

    ret = qmp_fd(fixture->fd, "{'execute': 'guest-set-time',"

                 " 'arguments': { 'time': 1000 } }");

    g_assert_nonnull(ret);

    qmp_assert_no_error(ret);

    QDECREF(ret);



    /* check old time */

    ret = qmp_fd(fixture->fd, "{'execute': 'guest-get-time'}");

    g_assert_nonnull(ret);

    qmp_assert_no_error(ret);

    time = qdict_get_int(ret, "return");

    g_assert_cmpint(time / 1000, <, G_USEC_PER_SEC * 10);

    QDECREF(ret);



    /* set back current time */

    cmd = g_strdup_printf("{'execute': 'guest-set-time',"

                          " 'arguments': { 'time': %" PRId64 " } }",

                          current + time * 1000);

    ret = qmp_fd(fixture->fd, cmd);

    g_free(cmd);

    g_assert_nonnull(ret);

    qmp_assert_no_error(ret);

    QDECREF(ret);

}

static void bus_set_realized(Object *obj, bool value, Error **errp)

{

    BusState *bus = BUS(obj);

    BusClass *bc = BUS_GET_CLASS(bus);

    Error *local_err = NULL;



    if (value && !bus->realized) {

        if (bc->realize) {

            bc->realize(bus, &local_err);

        }

    } else if (!value && bus->realized) {

        if (bc->unrealize) {

            bc->unrealize(bus, &local_err);

        }

    }



    if (local_err != NULL) {

        error_propagate(errp, local_err);

        return;

    }



    bus->realized = value;

}

static void gen_tlbilx_booke206(DisasContext *ctx)

{

#if defined(CONFIG_USER_ONLY)

    gen_inval_exception(ctx, POWERPC_EXCP_PRIV_OPC);

#else

    TCGv t0;

    if (unlikely(ctx->pr)) {

        gen_inval_exception(ctx, POWERPC_EXCP_PRIV_OPC);

        return;

    }



    t0 = tcg_temp_new();

    gen_addr_reg_index(ctx, t0);



    switch((ctx->opcode >> 21) & 0x3) {

    case 0:

        gen_helper_booke206_tlbilx0(cpu_env, t0);

        break;

    case 1:

        gen_helper_booke206_tlbilx1(cpu_env, t0);

        break;

    case 3:

        gen_helper_booke206_tlbilx3(cpu_env, t0);

        break;

    default:

        gen_inval_exception(ctx, POWERPC_EXCP_INVAL_INVAL);

        break;

    }



    tcg_temp_free(t0);

#endif

}

static void pci_basic(void)

{

    QVirtioPCIDevice *dev;

    QPCIBus *bus;

    QVirtQueuePCI *vqpci;

    QGuestAllocator *alloc;

    void *addr;



    bus = pci_test_start();

