static void get_cpuid_vendor(CPUX86State *env, uint32_t *ebx,

                             uint32_t *ecx, uint32_t *edx)

{

    *ebx = env->cpuid_vendor1;

    *edx = env->cpuid_vendor2;

    *ecx = env->cpuid_vendor3;



    /* sysenter isn't supported on compatibility mode on AMD, syscall

     * isn't supported in compatibility mode on Intel.

     * Normally we advertise the actual cpu vendor, but you can override

     * this if you want to use KVM's sysenter/syscall emulation

     * in compatibility mode and when doing cross vendor migration

     */

    if (kvm_enabled() && env->cpuid_vendor_override) {

        host_cpuid(0, 0, NULL, ebx, ecx, edx);

    }

}

void qmp_blockdev_change_medium(const char *device, const char *filename,

                                bool has_format, const char *format,

                                bool has_read_only,

                                BlockdevChangeReadOnlyMode read_only,

                                Error **errp)

{

    BlockBackend *blk;

    BlockDriverState *medium_bs = NULL;

    int bdrv_flags, ret;

    QDict *options = NULL;

    Error *err = NULL;



    blk = blk_by_name(device);

    if (!blk) {

        error_set(errp, ERROR_CLASS_DEVICE_NOT_FOUND,

                  "Device '%s' not found", device);

        goto fail;

    }



    if (blk_bs(blk)) {

        blk_update_root_state(blk);

    }



    bdrv_flags = blk_get_open_flags_from_root_state(blk);

    bdrv_flags &= ~(BDRV_O_TEMPORARY | BDRV_O_SNAPSHOT | BDRV_O_NO_BACKING |

        BDRV_O_PROTOCOL);



    if (!has_read_only) {

        read_only = BLOCKDEV_CHANGE_READ_ONLY_MODE_RETAIN;

    }



    switch (read_only) {

    case BLOCKDEV_CHANGE_READ_ONLY_MODE_RETAIN:

        break;



    case BLOCKDEV_CHANGE_READ_ONLY_MODE_READ_ONLY:

        bdrv_flags &= ~BDRV_O_RDWR;

        break;



    case BLOCKDEV_CHANGE_READ_ONLY_MODE_READ_WRITE:

        bdrv_flags |= BDRV_O_RDWR;

        break;



    default:

        abort();

    }



    if (has_format) {

        options = qdict_new();

        qdict_put(options, "driver", qstring_from_str(format));

    }



    assert(!medium_bs);

    ret = bdrv_open(&medium_bs, filename, NULL, options, bdrv_flags, errp);

    if (ret < 0) {

        goto fail;

    }



    blk_apply_root_state(blk, medium_bs);



    bdrv_add_key(medium_bs, NULL, &err);

    if (err) {

        error_propagate(errp, err);

        goto fail;

    }



    qmp_blockdev_open_tray(device, false, false, &err);

    if (err) {

        error_propagate(errp, err);

        goto fail;

    }



    qmp_x_blockdev_remove_medium(device, &err);

    if (err) {

        error_propagate(errp, err);

        goto fail;

    }



    qmp_blockdev_insert_anon_medium(device, medium_bs, &err);

    if (err) {

        error_propagate(errp, err);

        goto fail;

    }



    qmp_blockdev_close_tray(device, errp);



fail:

    /* If the medium has been inserted, the device has its own reference, so

     * ours must be relinquished; and if it has not been inserted successfully,

     * the reference must be relinquished anyway */

    bdrv_unref(medium_bs);

}

static inline int ppcemb_tlb_check(CPUState *env, ppcemb_tlb_t *tlb,

                                   target_phys_addr_t *raddrp,

                                   target_ulong address, uint32_t pid, int ext,

                                   int i)

{

    target_ulong mask;



    /* Check valid flag */

    if (!(tlb->prot & PAGE_VALID)) {

        qemu_log("%s: TLB %d not valid\n", __func__, i);

        return -1;

    }

    mask = ~(tlb->size - 1);

    LOG_SWTLB("%s: TLB %d address " TARGET_FMT_lx " PID %u <=> " TARGET_FMT_lx

              " " TARGET_FMT_lx " %u\n", __func__, i, address, pid, tlb->EPN,

              mask, (uint32_t)tlb->PID);

    /* Check PID */

    if (tlb->PID != 0 && tlb->PID != pid)

        return -1;

    /* Check effective address */

    if ((address & mask) != tlb->EPN)

        return -1;

    *raddrp = (tlb->RPN & mask) | (address & ~mask);

#if (TARGET_PHYS_ADDR_BITS >= 36)

    if (ext) {

        /* Extend the physical address to 36 bits */

        *raddrp |= (target_phys_addr_t)(tlb->RPN & 0xF) << 32;

    }

#endif



    return 0;

}

