static void gen_rac(DisasContext *ctx)

{

#if defined(CONFIG_USER_ONLY)

    gen_inval_exception(ctx, POWERPC_EXCP_PRIV_OPC);

#else

    TCGv t0;

    if (unlikely(ctx->pr)) {

        gen_inval_exception(ctx, POWERPC_EXCP_PRIV_OPC);

        return;

    }

    t0 = tcg_temp_new();

    gen_addr_reg_index(ctx, t0);

    gen_helper_rac(cpu_gpr[rD(ctx->opcode)], cpu_env, t0);

    tcg_temp_free(t0);

#endif

}

static void kvm_s390_stattrib_synchronize(S390StAttribState *sa)

{

    KVMS390StAttribState *sas = KVM_S390_STATTRIB(sa);

    MachineState *machine = MACHINE(qdev_get_machine());

    unsigned long max = machine->maxram_size / TARGET_PAGE_SIZE;

    unsigned long cx, len = 1 << 19;

    int r;

    struct kvm_s390_cmma_log clog = {

        .flags = 0,

        .mask = ~0ULL,

    };



    if (sas->incoming_buffer) {

        for (cx = 0; cx + len <= max; cx += len) {

            clog.start_gfn = cx;

            clog.count = len;

            clog.values = (uint64_t)(sas->incoming_buffer + cx * len);

            r = kvm_vm_ioctl(kvm_state, KVM_S390_SET_CMMA_BITS, &clog);

            if (r) {

                error_report("KVM_S390_SET_CMMA_BITS failed: %s", strerror(-r));

                return;

            }

        }

        if (cx < max) {

            clog.start_gfn = cx;

            clog.count = max - cx;

            clog.values = (uint64_t)(sas->incoming_buffer + cx * len);

            r = kvm_vm_ioctl(kvm_state, KVM_S390_SET_CMMA_BITS, &clog);

            if (r) {

                error_report("KVM_S390_SET_CMMA_BITS failed: %s", strerror(-r));

            }

        }

        g_free(sas->incoming_buffer);

        sas->incoming_buffer = NULL;

    }

}

static void handle_qmp_command(JSONMessageParser *parser, GQueue *tokens)

{

    QObject *req, *rsp = NULL, *id = NULL;

    QDict *qdict = NULL;

    const char *cmd_name;

    Monitor *mon = cur_mon;

    Error *err = NULL;



    req = json_parser_parse_err(tokens, NULL, &err);

    if (!req && !err) {

        /* json_parser_parse_err() sucks: can fail without setting @err */

        error_setg(&err, QERR_JSON_PARSING);

    }

    if (err) {

        goto err_out;

    }



    qdict = qmp_check_input_obj(req, &err);

    if (!qdict) {

        goto err_out;

    }



    id = qdict_get(qdict, "id");

    qobject_incref(id);

    qdict_del(qdict, "id");



    cmd_name = qdict_get_str(qdict, "execute");

    trace_handle_qmp_command(mon, cmd_name);



    rsp = qmp_dispatch(cur_mon->qmp.commands, req);



    if (mon->qmp.commands == &qmp_cap_negotiation_commands) {

        qdict = qdict_get_qdict(qobject_to_qdict(rsp), "error");

        if (qdict

            && !g_strcmp0(qdict_get_try_str(qdict, "class"),

                    QapiErrorClass_lookup[ERROR_CLASS_COMMAND_NOT_FOUND])) {

            /* Provide a more useful error message */

            qdict_del(qdict, "desc");

            qdict_put(qdict, "desc",

                      qstring_from_str("Expecting capabilities negotiation"

                                       " with 'qmp_capabilities'"));

        }

    }



err_out:

    if (err) {

        qdict = qdict_new();

        qdict_put_obj(qdict, "error", qmp_build_error_object(err));

        error_free(err);

        rsp = QOBJECT(qdict);

    }



    if (rsp) {

        if (id) {

            qdict_put_obj(qobject_to_qdict(rsp), "id", id);

            id = NULL;

        }



        monitor_json_emitter(mon, rsp);

    }



    qobject_decref(id);

    qobject_decref(rsp);

    qobject_decref(req);

}

static void test_blk_read(BlockBackend *blk, long pattern,

                          int64_t pattern_offset, int64_t pattern_count,

                          int64_t offset, int64_t count,

                          bool expect_failed)

{

    void *pattern_buf = NULL;

    QEMUIOVector qiov;

    void *cmp_buf = NULL;

    int async_ret = NOT_DONE;



    if (pattern) {

        cmp_buf = g_malloc(pattern_count);

        memset(cmp_buf, pattern, pattern_count);

    }



    pattern_buf = g_malloc(count);

    if (pattern) {

        memset(pattern_buf, pattern, count);

    } else {

        memset(pattern_buf, 0x00, count);

    }



    qemu_iovec_init(&qiov, 1);

    qemu_iovec_add(&qiov, pattern_buf, count);



    blk_aio_preadv(blk, offset, &qiov, 0, blk_rw_done, &async_ret);

    while (async_ret == NOT_DONE) {

        main_loop_wait(false);

    }



    if (expect_failed) {

        g_assert(async_ret != 0);

    } else {

        g_assert(async_ret == 0);

        if (pattern) {

            g_assert(memcmp(pattern_buf + pattern_offset,

                            cmp_buf, pattern_count) <= 0);

        }

    }



    g_free(pattern_buf);



}

static int vhost_user_start(VhostUserState *s)

{

    VhostNetOptions options;



    if (vhost_user_running(s)) {

        return 0;

    }



    options.backend_type = VHOST_BACKEND_TYPE_USER;

    options.net_backend = &s->nc;

    options.opaque = s->chr;

    options.force = true;



    s->vhost_net = vhost_net_init(&options);



    return vhost_user_running(s) ? 0 : -1;

}

FWCfgState *fw_cfg_init_mem_wide(hwaddr ctl_addr,

                                 hwaddr data_addr, uint32_t data_width,

                                 hwaddr dma_addr, AddressSpace *dma_as)

{

    DeviceState *dev;

    SysBusDevice *sbd;

    FWCfgState *s;

    bool dma_requested = dma_addr && dma_as;



    dev = qdev_create(NULL, TYPE_FW_CFG_MEM);

    qdev_prop_set_uint32(dev, "data_width", data_width);

    if (!dma_requested) {

        qdev_prop_set_bit(dev, "dma_enabled", false);

    }



    fw_cfg_init1(dev);



    sbd = SYS_BUS_DEVICE(dev);

    sysbus_mmio_map(sbd, 0, ctl_addr);

    sysbus_mmio_map(sbd, 1, data_addr);



    s = FW_CFG(dev);



    if (s->dma_enabled) {

        s->dma_as = dma_as;

        s->dma_addr = 0;

        sysbus_mmio_map(sbd, 2, dma_addr);

    }



    return s;

}

static int protocol_client_auth_sasl_step(VncState *vs, uint8_t *data, size_t len)

{

    uint32_t datalen = len;

    const char *serverout;

    unsigned int serveroutlen;

    int err;

    char *clientdata = NULL;



    /* NB, distinction of NULL vs "" is *critical* in SASL */

    if (datalen) {

        clientdata = (char*)data;

        clientdata[datalen-1] = '\0'; /* Wire includes '\0', but make sure */

        datalen--; /* Don't count NULL byte when passing to _start() */

    }



    VNC_DEBUG("Step using SASL Data %p (%d bytes)\n",

              clientdata, datalen);

    err = sasl_server_step(vs->sasl.conn,

                           clientdata,

                           datalen,

                           &serverout,

                           &serveroutlen);

    if (err != SASL_OK &&

        err != SASL_CONTINUE) {

        VNC_DEBUG("sasl step failed %d (%s)\n",

                  err, sasl_errdetail(vs->sasl.conn));

        sasl_dispose(&vs->sasl.conn);

        vs->sasl.conn = NULL;

        goto authabort;

    }



    if (serveroutlen > SASL_DATA_MAX_LEN) {

        VNC_DEBUG("sasl step reply data too long %d\n",

                  serveroutlen);

        sasl_dispose(&vs->sasl.conn);

        vs->sasl.conn = NULL;

        goto authabort;

    }



    VNC_DEBUG("SASL return data %d bytes, nil; %d\n",

              serveroutlen, serverout ? 0 : 1);



    if (serveroutlen) {

        vnc_write_u32(vs, serveroutlen + 1);

        vnc_write(vs, serverout, serveroutlen + 1);

    } else {

        vnc_write_u32(vs, 0);

    }



    /* Whether auth is complete */

    vnc_write_u8(vs, err == SASL_CONTINUE ? 0 : 1);



    if (err == SASL_CONTINUE) {

        VNC_DEBUG("%s", "Authentication must continue\n");

        /* Wait for step length */

        vnc_read_when(vs, protocol_client_auth_sasl_step_len, 4);

    } else {

        if (!vnc_auth_sasl_check_ssf(vs)) {

            VNC_DEBUG("Authentication rejected for weak SSF %p\n", vs->ioc);

            goto authreject;

        }



        /* Check username whitelist ACL */

        if (vnc_auth_sasl_check_access(vs) < 0) {

            VNC_DEBUG("Authentication rejected for ACL %p\n", vs->ioc);

            goto authreject;

        }



        VNC_DEBUG("Authentication successful %p\n", vs->ioc);

        vnc_write_u32(vs, 0); /* Accept auth */

        /*

         * Delay writing in SSF encoded mode until pending output

         * buffer is written

         */

        if (vs->sasl.runSSF)

            vs->sasl.waitWriteSSF = vs->output.offset;

        start_client_init(vs);

    }



    return 0;



 authreject:

    vnc_write_u32(vs, 1); /* Reject auth */

    vnc_write_u32(vs, sizeof("Authentication failed"));

    vnc_write(vs, "Authentication failed", sizeof("Authentication failed"));

    vnc_flush(vs);

    vnc_client_error(vs);

    return -1;



 authabort:

    vnc_client_error(vs);

    return -1;

}

static void sdl_switch(DisplayChangeListener *dcl,

                       DisplaySurface *new_surface)

{

    PixelFormat pf = qemu_pixelformat_from_pixman(new_surface->format);



    /* temporary hack: allows to call sdl_switch to handle scaling changes */

    if (new_surface) {

        surface = new_surface;

    }



    if (!scaling_active) {

        do_sdl_resize(surface_width(surface), surface_height(surface), 0);

    } else if (real_screen->format->BitsPerPixel !=

               surface_bits_per_pixel(surface)) {

        do_sdl_resize(real_screen->w, real_screen->h,

                      surface_bits_per_pixel(surface));

    }



    if (guest_screen != NULL) {

        SDL_FreeSurface(guest_screen);

    }



#ifdef DEBUG_SDL

    printf("SDL: Creating surface with masks: %08x %08x %08x %08x\n",

           pf.rmask, pf.gmask, pf.bmask, pf.amask);

#endif



    guest_screen = SDL_CreateRGBSurfaceFrom

        (surface_data(surface),

         surface_width(surface), surface_height(surface),

         surface_bits_per_pixel(surface), surface_stride(surface),

         pf.rmask, pf.gmask,

         pf.bmask, pf.amask);

}

static inline uint16_t mipsdsp_sat16_sub(int16_t a, int16_t b,

                                         CPUMIPSState *env)

{

    int16_t  temp;



    temp = a - b;

    if (MIPSDSP_OVERFLOW(a, -b, temp, 0x8000)) {

        if (a > 0) {

            temp = 0x7FFF;

        } else {

            temp = 0x8000;

        }

        set_DSPControl_overflow_flag(1, 20, env);

    }



    return temp;

}

