static int net_bridge_run_helper(const char *helper, const char *bridge)

{

    sigset_t oldmask, mask;

    int pid, status;

    char *args[5];

    char **parg;

    int sv[2];



    sigemptyset(&mask);

    sigaddset(&mask, SIGCHLD);

    sigprocmask(SIG_BLOCK, &mask, &oldmask);



    if (socketpair(PF_UNIX, SOCK_STREAM, 0, sv) == -1) {

        return -1;

    }



    /* try to launch bridge helper */

    pid = fork();

    if (pid == 0) {

        int open_max = sysconf(_SC_OPEN_MAX), i;

        char fd_buf[6+10];

        char br_buf[6+IFNAMSIZ] = {0};

        char helper_cmd[PATH_MAX + sizeof(fd_buf) + sizeof(br_buf) + 15];



        for (i = 3; i < open_max; i++) {

            if (i != sv[1]) {

                close(i);

            }

        }



        snprintf(fd_buf, sizeof(fd_buf), "%s%d", "--fd=", sv[1]);



        if (strrchr(helper, ' ') || strrchr(helper, '\t')) {

            /* assume helper is a command */



            if (strstr(helper, "--br=") == NULL) {

                snprintf(br_buf, sizeof(br_buf), "%s%s", "--br=", bridge);

            }



            snprintf(helper_cmd, sizeof(helper_cmd), "%s %s %s %s",

                     helper, "--use-vnet", fd_buf, br_buf);



            parg = args;

            *parg++ = (char *)"sh";

            *parg++ = (char *)"-c";

            *parg++ = helper_cmd;

            *parg++ = NULL;



            execv("/bin/sh", args);

        } else {

            /* assume helper is just the executable path name */



            snprintf(br_buf, sizeof(br_buf), "%s%s", "--br=", bridge);



            parg = args;

            *parg++ = (char *)helper;

            *parg++ = (char *)"--use-vnet";

            *parg++ = fd_buf;

            *parg++ = br_buf;

            *parg++ = NULL;



            execv(helper, args);

        }

        _exit(1);



    } else if (pid > 0) {

        int fd;



        close(sv[1]);



        do {

            fd = recv_fd(sv[0]);

        } while (fd == -1 && errno == EINTR);



        close(sv[0]);



        while (waitpid(pid, &status, 0) != pid) {

            /* loop */

        }

        sigprocmask(SIG_SETMASK, &oldmask, NULL);

        if (fd < 0) {

            fprintf(stderr, "failed to recv file descriptor\n");

            return -1;

        }



        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {

            return fd;

        }

    }

    fprintf(stderr, "failed to launch bridge helper\n");

    return -1;

}

static BlockDriverAIOCB *curl_aio_readv(BlockDriverState *bs,

        int64_t sector_num, QEMUIOVector *qiov, int nb_sectors,

        BlockDriverCompletionFunc *cb, void *opaque)

{

    BDRVCURLState *s = bs->opaque;

    CURLAIOCB *acb;

    size_t start = sector_num * SECTOR_SIZE;

    size_t end;

    CURLState *state;



    acb = qemu_aio_get(&curl_aio_pool, bs, cb, opaque);

    if (!acb)

        return NULL;



    acb->qiov = qiov;



    // In case we have the requested data already (e.g. read-ahead),

    // we can just call the callback and be done.



    switch (curl_find_buf(s, start, nb_sectors * SECTOR_SIZE, acb)) {

        case FIND_RET_OK:

            qemu_aio_release(acb);

            // fall through

        case FIND_RET_WAIT:

            return &acb->common;

        default:

            break;

    }



    // No cache found, so let's start a new request



    state = curl_init_state(s);

    if (!state)

        return NULL;



    acb->start = 0;

    acb->end = (nb_sectors * SECTOR_SIZE);



    state->buf_off = 0;

    if (state->orig_buf)

        qemu_free(state->orig_buf);

    state->buf_start = start;

    state->buf_len = acb->end + READ_AHEAD_SIZE;

    end = MIN(start + state->buf_len, s->len) - 1;

    state->orig_buf = qemu_malloc(state->buf_len);

    state->acb[0] = acb;



    snprintf(state->range, 127, "%lld-%lld", (long long)start, (long long)end);

    dprintf("CURL (AIO): Reading %d at %lld (%s)\n", (nb_sectors * SECTOR_SIZE), start, state->range);

    curl_easy_setopt(state->curl, CURLOPT_RANGE, state->range);



    curl_multi_add_handle(s->multi, state->curl);

    curl_multi_do(s);



    return &acb->common;

}

static int alloc_f(BlockDriverState *bs, int argc, char **argv)

{

    int64_t offset, sector_num;

    int nb_sectors, remaining;

    char s1[64];

    int num, sum_alloc;

    int ret;



    offset = cvtnum(argv[1]);

    if (offset < 0) {

        printf("non-numeric offset argument -- %s\n", argv[1]);


    } else if (offset & 0x1ff) {

        printf("offset %" PRId64 " is not sector aligned\n",

               offset);





    if (argc == 3) {

        nb_sectors = cvtnum(argv[2]);

        if (nb_sectors < 0) {

            printf("non-numeric length argument -- %s\n", argv[2]);



    } else {

        nb_sectors = 1;




    remaining = nb_sectors;

    sum_alloc = 0;

    sector_num = offset >> 9;

    while (remaining) {

        ret = bdrv_is_allocated(bs, sector_num, remaining, &num);





        sector_num += num;

        remaining -= num;

        if (ret) {

            sum_alloc += num;


        if (num == 0) {

            nb_sectors -= remaining;

            remaining = 0;





    cvtstr(offset, s1, sizeof(s1));



    printf("%d/%d sectors allocated at offset %s\n",

           sum_alloc, nb_sectors, s1);

