static inline uint16_t mipsdsp_lshift16(uint16_t a, uint8_t s,

                                        CPUMIPSState *env)

{

    uint8_t  sign;

    uint16_t discard;



    if (s == 0) {

        return a;

    } else {

        sign = (a >> 15) & 0x01;

        if (sign != 0) {

            discard = (((0x01 << (16 - s)) - 1) << s) |

                      ((a >> (14 - (s - 1))) & ((0x01 << s) - 1));

        } else {

            discard = a >> (14 - (s - 1));

        }



        if ((discard != 0x0000) && (discard != 0xFFFF)) {

            set_DSPControl_overflow_flag(1, 22, env);

        }

        return a << s;

    }

}

static ssize_t dump_receive(VLANClientState *vc, const uint8_t *buf, size_t size)

{

    DumpState *s = vc->opaque;

    struct pcap_sf_pkthdr hdr;

    int64_t ts;

    int caplen;



    /* Early return in case of previous error. */

    if (s->fd < 0) {

        return size;

    }



    ts = muldiv64(qemu_get_clock(vm_clock), 1000000, get_ticks_per_sec());

    caplen = size > s->pcap_caplen ? s->pcap_caplen : size;



    hdr.ts.tv_sec = ts / 1000000;

    hdr.ts.tv_usec = ts % 1000000;

    hdr.caplen = caplen;

    hdr.len = size;

    if (write(s->fd, &hdr, sizeof(hdr)) != sizeof(hdr) ||

        write(s->fd, buf, caplen) != caplen) {

        qemu_log("-net dump write error - stop dump\n");

        close(s->fd);

        s->fd = -1;

    }



    return size;

}

static int openpic_load(QEMUFile* f, void *opaque, int version_id)

{

    OpenPICState *opp = (OpenPICState *)opaque;

    unsigned int i;



    if (version_id != 1) {

        return -EINVAL;

    }



    qemu_get_be32s(f, &opp->gcr);

    qemu_get_be32s(f, &opp->vir);

    qemu_get_be32s(f, &opp->pir);

    qemu_get_be32s(f, &opp->spve);

    qemu_get_be32s(f, &opp->tfrr);



    qemu_get_be32s(f, &opp->nb_cpus);



    for (i = 0; i < opp->nb_cpus; i++) {

        qemu_get_sbe32s(f, &opp->dst[i].ctpr);

        openpic_load_IRQ_queue(f, &opp->dst[i].raised);

        openpic_load_IRQ_queue(f, &opp->dst[i].servicing);

        qemu_get_buffer(f, (uint8_t *)&opp->dst[i].outputs_active,

                        sizeof(opp->dst[i].outputs_active));

    }



    for (i = 0; i < OPENPIC_MAX_TMR; i++) {

        qemu_get_be32s(f, &opp->timers[i].tccr);

        qemu_get_be32s(f, &opp->timers[i].tbcr);

    }



    for (i = 0; i < opp->max_irq; i++) {

        uint32_t val;



        val = qemu_get_be32(f);

        write_IRQreg_idr(opp, i, val);

        val = qemu_get_be32(f);

        write_IRQreg_ivpr(opp, i, val);



        qemu_get_be32s(f, &opp->src[i].ivpr);

        qemu_get_be32s(f, &opp->src[i].idr);

        qemu_get_be32s(f, &opp->src[i].destmask);

        qemu_get_sbe32s(f, &opp->src[i].last_cpu);

        qemu_get_sbe32s(f, &opp->src[i].pending);

    }



    return 0;

}

int vnc_tight_send_framebuffer_update(VncState *vs, int x, int y,

                                      int w, int h)

{

    int max_rows;



    if (vs->clientds.pf.bytes_per_pixel == 4 && vs->clientds.pf.rmax == 0xFF &&

        vs->clientds.pf.bmax == 0xFF && vs->clientds.pf.gmax == 0xFF) {

        vs->tight_pixel24 = true;

    } else {

        vs->tight_pixel24 = false;

    }



    if (w * h < VNC_TIGHT_MIN_SPLIT_RECT_SIZE)

        return send_rect_simple(vs, x, y, w, h);



