void qxl_render_update(PCIQXLDevice *qxl)

{

    VGACommonState *vga = &qxl->vga;

    QXLRect dirty[32], update;

    void *ptr;

    int i;



    if (qxl->guest_primary.resized) {

        qxl->guest_primary.resized = 0;



        if (qxl->guest_primary.flipped) {

            g_free(qxl->guest_primary.flipped);

            qxl->guest_primary.flipped = NULL;

        }

        qemu_free_displaysurface(vga->ds);



        qxl->guest_primary.data = memory_region_get_ram_ptr(&qxl->vga.vram);

        if (qxl->guest_primary.stride < 0) {

            /* spice surface is upside down -> need extra buffer to flip */

            qxl->guest_primary.stride = -qxl->guest_primary.stride;

            qxl->guest_primary.flipped = g_malloc(qxl->guest_primary.surface.width *

                                                     qxl->guest_primary.stride);

            ptr = qxl->guest_primary.flipped;

        } else {

            ptr = qxl->guest_primary.data;

        }

        dprint(qxl, 1, "%s: %dx%d, stride %d, bpp %d, depth %d, flip %s\n",

               __FUNCTION__,

               qxl->guest_primary.surface.width,

               qxl->guest_primary.surface.height,

               qxl->guest_primary.stride,

               qxl->guest_primary.bytes_pp,

               qxl->guest_primary.bits_pp,

               qxl->guest_primary.flipped ? "yes" : "no");

        vga->ds->surface =

            qemu_create_displaysurface_from(qxl->guest_primary.surface.width,

                                            qxl->guest_primary.surface.height,

                                            qxl->guest_primary.bits_pp,

                                            qxl->guest_primary.stride,

                                            ptr);

        dpy_resize(vga->ds);

    }



    if (!qxl->guest_primary.commands) {

        return;

    }

    qxl->guest_primary.commands = 0;



    update.left   = 0;

    update.right  = qxl->guest_primary.surface.width;

    update.top    = 0;

    update.bottom = qxl->guest_primary.surface.height;



    memset(dirty, 0, sizeof(dirty));

    qxl_spice_update_area(qxl, 0, &update,

                          dirty, ARRAY_SIZE(dirty), 1, QXL_SYNC);



    for (i = 0; i < ARRAY_SIZE(dirty); i++) {

        if (qemu_spice_rect_is_empty(dirty+i)) {

            break;

        }

        if (qxl->guest_primary.flipped) {

            qxl_flip(qxl, dirty+i);

        }

        dpy_update(vga->ds,

                   dirty[i].left, dirty[i].top,

                   dirty[i].right - dirty[i].left,

                   dirty[i].bottom - dirty[i].top);

    }

}

static int local_fstat(FsContext *fs_ctx, int fid_type,

                       V9fsFidOpenState *fs, struct stat *stbuf)

{

    int err, fd;



    if (fid_type == P9_FID_DIR) {

        fd = dirfd(fs->dir);

    } else {

        fd = fs->fd;

    }



    err = fstat(fd, stbuf);

    if (err) {

        return err;

    }

    if (fs_ctx->export_flags & V9FS_SM_MAPPED) {

        /* Actual credentials are part of extended attrs */

        uid_t tmp_uid;

        gid_t tmp_gid;

        mode_t tmp_mode;

        dev_t tmp_dev;



        if (fgetxattr(fd, "user.virtfs.uid",

                      &tmp_uid, sizeof(uid_t)) > 0) {

            stbuf->st_uid = tmp_uid;

        }

        if (fgetxattr(fd, "user.virtfs.gid",

                      &tmp_gid, sizeof(gid_t)) > 0) {

            stbuf->st_gid = tmp_gid;

        }

        if (fgetxattr(fd, "user.virtfs.mode",

                      &tmp_mode, sizeof(mode_t)) > 0) {

            stbuf->st_mode = tmp_mode;

        }

        if (fgetxattr(fd, "user.virtfs.rdev",

                      &tmp_dev, sizeof(dev_t)) > 0) {

                stbuf->st_rdev = tmp_dev;

        }

    } else if (fs_ctx->export_flags & V9FS_SM_MAPPED_FILE) {

        errno = EOPNOTSUPP;

        return -1;

    }

    return err;

}

static uint64_t malta_fpga_read(void *opaque, target_phys_addr_t addr,

                                unsigned size)

{

    MaltaFPGAState *s = opaque;

    uint32_t val = 0;

    uint32_t saddr;



    saddr = (addr & 0xfffff);



    switch (saddr) {



    /* SWITCH Register */

    case 0x00200:

        val = 0x00000000;		/* All switches closed */

        break;



    /* STATUS Register */

    case 0x00208:

#ifdef TARGET_WORDS_BIGENDIAN

        val = 0x00000012;

#else

        val = 0x00000010;

#endif

        break;



    /* JMPRS Register */

    case 0x00210:

        val = 0x00;

        break;



    /* LEDBAR Register */

    case 0x00408:

        val = s->leds;

        break;



    /* BRKRES Register */

    case 0x00508:

        val = s->brk;

        break;



    /* UART Registers are handled directly by the serial device */



    /* GPOUT Register */

    case 0x00a00:

        val = s->gpout;

        break;



    /* XXX: implement a real I2C controller */



    /* GPINP Register */

    case 0x00a08:

        /* IN = OUT until a real I2C control is implemented */

        if (s->i2csel)

            val = s->i2cout;

        else

            val = 0x00;

        break;



    /* I2CINP Register */

    case 0x00b00:

        val = ((s->i2cin & ~1) | eeprom24c0x_read());

        break;



    /* I2COE Register */

    case 0x00b08:

        val = s->i2coe;

        break;



    /* I2COUT Register */

    case 0x00b10:

        val = s->i2cout;

        break;



    /* I2CSEL Register */

    case 0x00b18:

        val = s->i2csel;

        break;



    default:

#if 0

        printf ("malta_fpga_read: Bad register offset 0x" TARGET_FMT_lx "\n",

                addr);

#endif

        break;

    }

    return val;

}

