                goto out;

            }

            fd = net_handle_fd_param(mon, buf);

            if (fd == -1) {

                goto out;

            }

            if (!net_socket_fd_init(vlan, device, name, fd, 1)) {

                close(fd);

                goto out;

            }

            ret = 0;

        } else if (get_param_value(buf, sizeof(buf), "listen", p) > 0) {

            static const char * const listen_params[] = {

                "vlan", "name", "listen", NULL

            };

            if (check_params(chkbuf, sizeof(chkbuf), listen_params, p) < 0) {

                config_error(mon, "invalid parameter '%s' in '%s'\n", chkbuf, p);

                ret = -1;

                goto out;

            }

            ret = net_socket_listen_init(vlan, device, name, buf);

        } else if (get_param_value(buf, sizeof(buf), "connect", p) > 0) {

            static const char * const connect_params[] = {

                "vlan", "name", "connect", NULL

            };

            if (check_params(chkbuf, sizeof(chkbuf), connect_params, p) < 0) {

                config_error(mon, "invalid parameter '%s' in '%s'\n", chkbuf, p);

                ret = -1;

                goto out;

            }

            ret = net_socket_connect_init(vlan, device, name, buf);

        } else if (get_param_value(buf, sizeof(buf), "mcast", p) > 0) {

            static const char * const mcast_params[] = {

                "vlan", "name", "mcast", NULL

            };

            if (check_params(chkbuf, sizeof(chkbuf), mcast_params, p) < 0) {

                config_error(mon, "invalid parameter '%s' in '%s'\n", chkbuf, p);

                ret = -1;

                goto out;

            }

            ret = net_socket_mcast_init(vlan, device, name, buf);

        } else {

            config_error(mon, "Unknown socket options: %s\n", p);

            ret = -1;

            goto out;

        }

        vlan->nb_host_devs++;

    } else

#ifdef CONFIG_VDE

    if (!strcmp(device, "vde")) {

        static const char * const vde_params[] = {

            "vlan", "name", "sock", "port", "group", "mode", NULL

        };

        char vde_sock[1024], vde_group[512];

	int vde_port, vde_mode;



        if (check_params(buf, sizeof(buf), vde_params, p) < 0) {

            config_error(mon, "invalid parameter '%s' in '%s'\n", buf, p);

            ret = -1;

            goto out;

        }

        vlan->nb_host_devs++;

        if (get_param_value(vde_sock, sizeof(vde_sock), "sock", p) <= 0) {

	    vde_sock[0] = '\0';

	}

	if (get_param_value(buf, sizeof(buf), "port", p) > 0) {

	    vde_port = strtol(buf, NULL, 10);

	} else {

	    vde_port = 0;

	}

	if (get_param_value(vde_group, sizeof(vde_group), "group", p) <= 0) {

	    vde_group[0] = '\0';

	}

	if (get_param_value(buf, sizeof(buf), "mode", p) > 0) {

	    vde_mode = strtol(buf, NULL, 8);

	} else {

	    vde_mode = 0700;

	}

	ret = net_vde_init(vlan, device, name, vde_sock, vde_port, vde_group, vde_mode);

    } else

#endif

    if (!strcmp(device, "dump")) {

        int len = 65536;



        if (get_param_value(buf, sizeof(buf), "len", p) > 0) {

            len = strtol(buf, NULL, 0);

        }

        if (!get_param_value(buf, sizeof(buf), "file", p)) {

            snprintf(buf, sizeof(buf), "qemu-vlan%d.pcap", vlan_id);

        }

        ret = net_dump_init(mon, vlan, device, name, buf, len);

    } else {

        config_error(mon, "Unknown network device: %s\n", device);

        ret = -1;

        goto out;

    }

    if (ret < 0) {

        config_error(mon, "Could not initialize device '%s'\n", device);

    }

out:

    qemu_free(name);

    return ret;

}

static int dump_iterate(DumpState *s)

{

    RAMBlock *block;

    int64_t size;

    int ret;



    while (1) {

        block = s->block;



        size = block->length;

        if (s->has_filter) {

            size -= s->start;

            if (s->begin + s->length < block->offset + block->length) {

                size -= block->offset + block->length - (s->begin + s->length);

            }

        }

        ret = write_memory(s, block, s->start, size);

        if (ret == -1) {

            return ret;

        }



        ret = get_next_block(s, block);

        if (ret == 1) {

            dump_completed(s);

            return 0;

        }

    }

}

static void lsi_reg_writeb(LSIState *s, int offset, uint8_t val)

{

#define CASE_SET_REG24(name, addr) \

    case addr    : s->name &= 0xffffff00; s->name |= val;       break; \

    case addr + 1: s->name &= 0xffff00ff; s->name |= val << 8;  break; \

    case addr + 2: s->name &= 0xff00ffff; s->name |= val << 16; break;



#define CASE_SET_REG32(name, addr) \

    case addr    : s->name &= 0xffffff00; s->name |= val;       break; \

    case addr + 1: s->name &= 0xffff00ff; s->name |= val << 8;  break; \

    case addr + 2: s->name &= 0xff00ffff; s->name |= val << 16; break; \

    case addr + 3: s->name &= 0x00ffffff; s->name |= val << 24; break;



#ifdef DEBUG_LSI_REG

    DPRINTF("Write reg %x = %02x\n", offset, val);

#endif

    switch (offset) {

    case 0x00: /* SCNTL0 */

        s->scntl0 = val;

        if (val & LSI_SCNTL0_START) {

            BADF("Start sequence not implemented\n");

        }

        break;

    case 0x01: /* SCNTL1 */

        s->scntl1 = val & ~LSI_SCNTL1_SST;

        if (val & LSI_SCNTL1_IARB) {

            BADF("Immediate Arbritration not implemented\n");

        }

        if (val & LSI_SCNTL1_RST) {

            if (!(s->sstat0 & LSI_SSTAT0_RST)) {

                BusChild *kid;



                QTAILQ_FOREACH(kid, &s->bus.qbus.children, sibling) {

                    DeviceState *dev = kid->child;

                    device_reset(dev);

                }

                s->sstat0 |= LSI_SSTAT0_RST;

                lsi_script_scsi_interrupt(s, LSI_SIST0_RST, 0);

            }

        } else {

            s->sstat0 &= ~LSI_SSTAT0_RST;

        }

        break;

    case 0x02: /* SCNTL2 */

        val &= ~(LSI_SCNTL2_WSR | LSI_SCNTL2_WSS);

        s->scntl2 = val;

        break;

    case 0x03: /* SCNTL3 */

        s->scntl3 = val;

        break;

    case 0x04: /* SCID */

        s->scid = val;

        break;

    case 0x05: /* SXFER */

        s->sxfer = val;

        break;

    case 0x06: /* SDID */

        if ((val & 0xf) != (s->ssid & 0xf))

            BADF("Destination ID does not match SSID\n");

        s->sdid = val & 0xf;

        break;

    case 0x07: /* GPREG0 */

        break;

    case 0x08: /* SFBR */

        /* The CPU is not allowed to write to this register.  However the

           SCRIPTS register move instructions are.  */

        s->sfbr = val;

        break;

    case 0x0a: case 0x0b:

        /* Openserver writes to these readonly registers on startup */

	return;

    case 0x0c: case 0x0d: case 0x0e: case 0x0f:

        /* Linux writes to these readonly registers on startup.  */

        return;

    CASE_SET_REG32(dsa, 0x10)

    case 0x14: /* ISTAT0 */

        s->istat0 = (s->istat0 & 0x0f) | (val & 0xf0);

        if (val & LSI_ISTAT0_ABRT) {

            lsi_script_dma_interrupt(s, LSI_DSTAT_ABRT);

        }

        if (val & LSI_ISTAT0_INTF) {

            s->istat0 &= ~LSI_ISTAT0_INTF;

            lsi_update_irq(s);

        }

        if (s->waiting == 1 && val & LSI_ISTAT0_SIGP) {

            DPRINTF("Woken by SIGP\n");

            s->waiting = 0;

            s->dsp = s->dnad;

            lsi_execute_script(s);

        }

        if (val & LSI_ISTAT0_SRST) {

            lsi_soft_reset(s);

        }

        break;

    case 0x16: /* MBOX0 */

        s->mbox0 = val;

        break;

    case 0x17: /* MBOX1 */

        s->mbox1 = val;

        break;

    case 0x1a: /* CTEST2 */

	s->ctest2 = val & LSI_CTEST2_PCICIE;

	break;

    case 0x1b: /* CTEST3 */

        s->ctest3 = val & 0x0f;

        break;

    CASE_SET_REG32(temp, 0x1c)

    case 0x21: /* CTEST4 */

        if (val & 7) {

           BADF("Unimplemented CTEST4-FBL 0x%x\n", val);

        }

        s->ctest4 = val;

        break;

    case 0x22: /* CTEST5 */

        if (val & (LSI_CTEST5_ADCK | LSI_CTEST5_BBCK)) {

            BADF("CTEST5 DMA increment not implemented\n");

        }

        s->ctest5 = val;

        break;

    CASE_SET_REG24(dbc, 0x24)

    CASE_SET_REG32(dnad, 0x28)

    case 0x2c: /* DSP[0:7] */

        s->dsp &= 0xffffff00;

        s->dsp |= val;

        break;

    case 0x2d: /* DSP[8:15] */

        s->dsp &= 0xffff00ff;

        s->dsp |= val << 8;

        break;

    case 0x2e: /* DSP[16:23] */

        s->dsp &= 0xff00ffff;

        s->dsp |= val << 16;

        break;

    case 0x2f: /* DSP[24:31] */

        s->dsp &= 0x00ffffff;

        s->dsp |= val << 24;

        if ((s->dmode & LSI_DMODE_MAN) == 0

            && (s->istat1 & LSI_ISTAT1_SRUN) == 0)

            lsi_execute_script(s);

        break;

    CASE_SET_REG32(dsps, 0x30)

    CASE_SET_REG32(scratch[0], 0x34)

    case 0x38: /* DMODE */

        if (val & (LSI_DMODE_SIOM | LSI_DMODE_DIOM)) {

            BADF("IO mappings not implemented\n");

        }

        s->dmode = val;

        break;

    case 0x39: /* DIEN */

        s->dien = val;

        lsi_update_irq(s);

        break;

    case 0x3a: /* SBR */

        s->sbr = val;

        break;

    case 0x3b: /* DCNTL */

        s->dcntl = val & ~(LSI_DCNTL_PFF | LSI_DCNTL_STD);

        if ((val & LSI_DCNTL_STD) && (s->istat1 & LSI_ISTAT1_SRUN) == 0)

            lsi_execute_script(s);

        break;

    case 0x40: /* SIEN0 */

        s->sien0 = val;

        lsi_update_irq(s);

        break;

    case 0x41: /* SIEN1 */

        s->sien1 = val;

        lsi_update_irq(s);

        break;

    case 0x47: /* GPCNTL0 */

        break;

    case 0x48: /* STIME0 */

        s->stime0 = val;

        break;

    case 0x49: /* STIME1 */

        if (val & 0xf) {

            DPRINTF("General purpose timer not implemented\n");

            /* ??? Raising the interrupt immediately seems to be sufficient

               to keep the FreeBSD driver happy.  */

            lsi_script_scsi_interrupt(s, 0, LSI_SIST1_GEN);

        }

        break;

    case 0x4a: /* RESPID0 */

        s->respid0 = val;

        break;

    case 0x4b: /* RESPID1 */

        s->respid1 = val;

        break;

    case 0x4d: /* STEST1 */

        s->stest1 = val;

        break;

    case 0x4e: /* STEST2 */

        if (val & 1) {

            BADF("Low level mode not implemented\n");

        }

        s->stest2 = val;

        break;

    case 0x4f: /* STEST3 */

        if (val & 0x41) {

            BADF("SCSI FIFO test mode not implemented\n");

        }

        s->stest3 = val;

        break;

    case 0x56: /* CCNTL0 */

        s->ccntl0 = val;

        break;

    case 0x57: /* CCNTL1 */

        s->ccntl1 = val;

        break;

    CASE_SET_REG32(mmrs, 0xa0)

    CASE_SET_REG32(mmws, 0xa4)

    CASE_SET_REG32(sfs, 0xa8)

    CASE_SET_REG32(drs, 0xac)

    CASE_SET_REG32(sbms, 0xb0)

    CASE_SET_REG32(dbms, 0xb4)

    CASE_SET_REG32(dnad64, 0xb8)

    CASE_SET_REG32(pmjad1, 0xc0)

    CASE_SET_REG32(pmjad2, 0xc4)

    CASE_SET_REG32(rbc, 0xc8)

    CASE_SET_REG32(ua, 0xcc)

    CASE_SET_REG32(ia, 0xd4)

    CASE_SET_REG32(sbc, 0xd8)

    CASE_SET_REG32(csbc, 0xdc)

    default:

        if (offset >= 0x5c && offset < 0xa0) {

            int n;

            int shift;

            n = (offset - 0x58) >> 2;

            shift = (offset & 3) * 8;

            s->scratch[n] &= ~(0xff << shift);

            s->scratch[n] |= (val & 0xff) << shift;

        } else {

            BADF("Unhandled writeb 0x%x = 0x%x\n", offset, val);

        }

    }

#undef CASE_SET_REG24

#undef CASE_SET_REG32

}

static inline void tcg_out_op(TCGContext *s, int opc, const TCGArg *args,

                              const int *const_args)

{

    int c;



    switch (opc) {

    case INDEX_op_exit_tb:

        tcg_out_movi(s, TCG_TYPE_PTR, TCG_REG_I0, args[0]);

        tcg_out32(s, JMPL | INSN_RD(TCG_REG_G0) | INSN_RS1(TCG_REG_I7) |

                  INSN_IMM13(8));

        tcg_out32(s, RESTORE | INSN_RD(TCG_REG_G0) | INSN_RS1(TCG_REG_G0) |

                      INSN_RS2(TCG_REG_G0));

        break;

    case INDEX_op_goto_tb:

        if (s->tb_jmp_offset) {

            /* direct jump method */

            if (ABS(args[0] - (unsigned long)s->code_ptr) ==

                (ABS(args[0] - (unsigned long)s->code_ptr) & 0x1fffff)) {

                tcg_out32(s, BA |

                          INSN_OFF22(args[0] - (unsigned long)s->code_ptr));

            } else {

                tcg_out_movi(s, TCG_TYPE_PTR, TCG_REG_I5, args[0]);

                tcg_out32(s, JMPL | INSN_RD(TCG_REG_G0) | INSN_RS1(TCG_REG_I5) |

                          INSN_RS2(TCG_REG_G0));

            }

            s->tb_jmp_offset[args[0]] = s->code_ptr - s->code_buf;

        } else {

            /* indirect jump method */

            tcg_out_ld_ptr(s, TCG_REG_I5, (tcg_target_long)(s->tb_next + args[0]));

            tcg_out32(s, JMPL | INSN_RD(TCG_REG_G0) | INSN_RS1(TCG_REG_I5) |

                      INSN_RS2(TCG_REG_G0));

        }

        tcg_out_nop(s);

        s->tb_next_offset[args[0]] = s->code_ptr - s->code_buf;

        break;

    case INDEX_op_call:

        if (const_args[0]) {

            tcg_out32(s, CALL | ((((tcg_target_ulong)args[0]

                                  - (tcg_target_ulong)s->code_ptr) >> 2)

                                 & 0x3fffffff));

            tcg_out_nop(s);

        } else {

            tcg_out_ld_ptr(s, TCG_REG_O7, (tcg_target_long)(s->tb_next + args[0]));

            tcg_out32(s, JMPL | INSN_RD(TCG_REG_O7) | INSN_RS1(TCG_REG_O7) |

                      INSN_RS2(TCG_REG_G0));

            tcg_out_nop(s);

        }

        break;

    case INDEX_op_jmp:

        fprintf(stderr, "unimplemented jmp\n");

        break;

    case INDEX_op_br:

        fprintf(stderr, "unimplemented br\n");

        break;

    case INDEX_op_movi_i32:

        tcg_out_movi(s, TCG_TYPE_I32, args[0], (uint32_t)args[1]);

        break;



#if defined(__sparc_v9__) && !defined(__sparc_v8plus__)

#define OP_32_64(x)                             \

        glue(glue(case INDEX_op_, x), _i32:)    \

        glue(glue(case INDEX_op_, x), _i64:)

#else

#define OP_32_64(x)                             \

        glue(glue(case INDEX_op_, x), _i32:)

#endif

        OP_32_64(ld8u);

        tcg_out_ldst(s, args[0], args[1], args[2], LDUB);

        break;

        OP_32_64(ld8s);

        tcg_out_ldst(s, args[0], args[1], args[2], LDSB);

        break;

        OP_32_64(ld16u);

        tcg_out_ldst(s, args[0], args[1], args[2], LDUH);

        break;

        OP_32_64(ld16s);

        tcg_out_ldst(s, args[0], args[1], args[2], LDSH);

        break;

    case INDEX_op_ld_i32:

#if defined(__sparc_v9__) && !defined(__sparc_v8plus__)

    case INDEX_op_ld32u_i64:

#endif

        tcg_out_ldst(s, args[0], args[1], args[2], LDUW);

        break;

        OP_32_64(st8);

        tcg_out_ldst(s, args[0], args[1], args[2], STB);

        break;

        OP_32_64(st16);

        tcg_out_ldst(s, args[0], args[1], args[2], STH);

        break;

    case INDEX_op_st_i32:

#if defined(__sparc_v9__) && !defined(__sparc_v8plus__)

    case INDEX_op_st32_i64:

#endif

        tcg_out_ldst(s, args[0], args[1], args[2], STW);

        break;

        OP_32_64(add);

        c = ARITH_ADD;

        goto gen_arith32;

        OP_32_64(sub);

        c = ARITH_SUB;

        goto gen_arith32;

        OP_32_64(and);

        c = ARITH_AND;

        goto gen_arith32;

        OP_32_64(or);

        c = ARITH_OR;

        goto gen_arith32;

        OP_32_64(xor);

        c = ARITH_XOR;

        goto gen_arith32;

    case INDEX_op_shl_i32:

        c = SHIFT_SLL;

        goto gen_arith32;

    case INDEX_op_shr_i32:

        c = SHIFT_SRL;

        goto gen_arith32;

    case INDEX_op_sar_i32:

        c = SHIFT_SRA;

        goto gen_arith32;

    case INDEX_op_mul_i32:

        c = ARITH_UMUL;

        goto gen_arith32;

    case INDEX_op_div2_i32:

#if defined(__sparc_v9__) || defined(__sparc_v8plus__)

        c = ARITH_SDIVX;

        goto gen_arith32;

#else

        tcg_out_sety(s, 0);

        c = ARITH_SDIV;

        goto gen_arith32;

#endif

    case INDEX_op_divu2_i32:

#if defined(__sparc_v9__) || defined(__sparc_v8plus__)

        c = ARITH_UDIVX;

        goto gen_arith32;

#else

        tcg_out_sety(s, 0);

        c = ARITH_UDIV;

        goto gen_arith32;

#endif



    case INDEX_op_brcond_i32:

        fprintf(stderr, "unimplemented brcond\n");

        break;



    case INDEX_op_qemu_ld8u:

        fprintf(stderr, "unimplemented qld\n");

        break;

    case INDEX_op_qemu_ld8s:

        fprintf(stderr, "unimplemented qld\n");

        break;

    case INDEX_op_qemu_ld16u:

        fprintf(stderr, "unimplemented qld\n");

        break;

    case INDEX_op_qemu_ld16s:

        fprintf(stderr, "unimplemented qld\n");

        break;

    case INDEX_op_qemu_ld32u:

        fprintf(stderr, "unimplemented qld\n");

        break;

    case INDEX_op_qemu_ld32s:

        fprintf(stderr, "unimplemented qld\n");

        break;

    case INDEX_op_qemu_st8:

        fprintf(stderr, "unimplemented qst\n");

        break;

    case INDEX_op_qemu_st16:

        fprintf(stderr, "unimplemented qst\n");

        break;

    case INDEX_op_qemu_st32:

        fprintf(stderr, "unimplemented qst\n");

        break;



#if defined(__sparc_v9__) && !defined(__sparc_v8plus__)

    case INDEX_op_movi_i64:

        tcg_out_movi(s, TCG_TYPE_I64, args[0], args[1]);

        break;

    case INDEX_op_ld32s_i64:

        tcg_out_ldst(s, args[0], args[1], args[2], LDSW);

        break;

    case INDEX_op_ld_i64:

        tcg_out_ldst(s, args[0], args[1], args[2], LDX);

        break;

    case INDEX_op_st_i64:

        tcg_out_ldst(s, args[0], args[1], args[2], STX);

        break;

    case INDEX_op_shl_i64:

        c = SHIFT_SLLX;

        goto gen_arith32;

    case INDEX_op_shr_i64:

        c = SHIFT_SRLX;

        goto gen_arith32;

    case INDEX_op_sar_i64:

        c = SHIFT_SRAX;

        goto gen_arith32;

    case INDEX_op_mul_i64:

        c = ARITH_MULX;

        goto gen_arith32;

    case INDEX_op_div2_i64:

        c = ARITH_SDIVX;

        goto gen_arith32;

    case INDEX_op_divu2_i64:

        c = ARITH_UDIVX;

        goto gen_arith32;



    case INDEX_op_brcond_i64:

        fprintf(stderr, "unimplemented brcond\n");

        break;

    case INDEX_op_qemu_ld64:

        fprintf(stderr, "unimplemented qld\n");

        break;

    case INDEX_op_qemu_st64:

        fprintf(stderr, "unimplemented qst\n");

        break;



#endif

    gen_arith32:

        if (const_args[2]) {

            tcg_out_arithi(s, args[0], args[1], args[2], c);

        } else {

            tcg_out_arith(s, args[0], args[1], args[2], c);

        }

        break;



    default:

        fprintf(stderr, "unknown opcode 0x%x\n", opc);

        tcg_abort();

    }

}

void os_mem_prealloc(int fd, char *area, size_t memory)

{

    int ret;

    struct sigaction act, oldact;

    sigset_t set, oldset;



    memset(&act, 0, sizeof(act));

    act.sa_handler = &sigbus_handler;

    act.sa_flags = 0;



    ret = sigaction(SIGBUS, &act, &oldact);

    if (ret) {

        perror("os_mem_prealloc: failed to install signal handler");

        exit(1);

    }



    /* unblock SIGBUS */

    sigemptyset(&set);

    sigaddset(&set, SIGBUS);

    pthread_sigmask(SIG_UNBLOCK, &set, &oldset);



    if (sigsetjmp(sigjump, 1)) {

        fprintf(stderr, "os_mem_prealloc: Insufficient free host memory "

                        "pages available to allocate guest RAM\n");

        exit(1);

    } else {

        int i;

        size_t hpagesize = fd_getpagesize(fd);

        size_t numpages = DIV_ROUND_UP(memory, hpagesize);



        /* MAP_POPULATE silently ignores failures */

        for (i = 0; i < numpages; i++) {

            memset(area + (hpagesize * i), 0, 1);

        }



        ret = sigaction(SIGBUS, &oldact, NULL);

        if (ret) {

            perror("os_mem_prealloc: failed to reinstall signal handler");

            exit(1);

        }



        pthread_sigmask(SIG_SETMASK, &oldset, NULL);

    }

}

int usb_handle_packet(USBDevice *dev, USBPacket *p)

{

    int ret;



    if (dev == NULL) {

        return USB_RET_NODEV;

    }

    assert(dev->addr == p->devaddr);

    assert(dev->state == USB_STATE_DEFAULT);

    assert(p->state == USB_PACKET_SETUP);



    if (p->devep == 0) {

        /* control pipe */

        switch (p->pid) {

        case USB_TOKEN_SETUP:

            ret = do_token_setup(dev, p);

            break;

        case USB_TOKEN_IN:

            ret = do_token_in(dev, p);

            break;

        case USB_TOKEN_OUT:

            ret = do_token_out(dev, p);

            break;

        default:

            ret = USB_RET_STALL;

            break;

        }

    } else {

        /* data pipe */

        ret = usb_device_handle_data(dev, p);

    }



    if (ret == USB_RET_ASYNC) {

        p->ep = usb_ep_get(dev, p->pid, p->devep);

        p->state = USB_PACKET_ASYNC;

    }

    return ret;

}

build_rsdp(GArray *rsdp_table, BIOSLinker *linker, unsigned rsdt_tbl_offset)

{

    AcpiRsdpDescriptor *rsdp = acpi_data_push(rsdp_table, sizeof *rsdp);

    unsigned rsdt_pa_size = sizeof(rsdp->rsdt_physical_address);

    unsigned rsdt_pa_offset =

        (char *)&rsdp->rsdt_physical_address - rsdp_table->data;



    bios_linker_loader_alloc(linker, ACPI_BUILD_RSDP_FILE, rsdp_table, 16,

                             true /* fseg memory */);



    memcpy(&rsdp->signature, "RSD PTR ", sizeof(rsdp->signature));

    memcpy(rsdp->oem_id, ACPI_BUILD_APPNAME6, sizeof(rsdp->oem_id));

    rsdp->length = cpu_to_le32(sizeof(*rsdp));

    rsdp->revision = 0x02;



    /* Address to be filled by Guest linker */

    bios_linker_loader_add_pointer(linker,

        ACPI_BUILD_RSDP_FILE, rsdt_pa_offset, rsdt_pa_size,

        ACPI_BUILD_TABLE_FILE, rsdt_tbl_offset);



    rsdp->checksum = 0;

    /* Checksum to be filled by Guest linker */

    bios_linker_loader_add_checksum(linker, ACPI_BUILD_RSDP_FILE,

                                    rsdp, sizeof *rsdp,

                                    &rsdp->checksum);



    return rsdp_table;

}

static inline uint32_t vmsvga_fifo_read_raw(struct vmsvga_state_s *s)

{

    uint32_t cmd = s->fifo[CMD(stop) >> 2];

    s->cmd->stop = cpu_to_le32(CMD(stop) + 4);

    if (CMD(stop) >= CMD(max))

        s->cmd->stop = s->cmd->min;

    return cmd;

}

static void bdrv_replace_child(BdrvChild *child, BlockDriverState *new_bs)

{

    BlockDriverState *old_bs = child->bs;



    if (old_bs) {

        if (old_bs->quiesce_counter && child->role->drained_end) {

            child->role->drained_end(child);

        }

        QLIST_REMOVE(child, next_parent);

    }



    child->bs = new_bs;



    if (new_bs) {

        QLIST_INSERT_HEAD(&new_bs->parents, child, next_parent);

        if (new_bs->quiesce_counter && child->role->drained_begin) {

            child->role->drained_begin(child);

        }

    }

}

void qemu_ram_free(ram_addr_t addr)

{

    RAMBlock *block;



    /* This assumes the iothread lock is taken here too.  */

    qemu_mutex_lock_ramlist();

    QTAILQ_FOREACH(block, &ram_list.blocks, next) {

        if (addr == block->offset) {

            QTAILQ_REMOVE(&ram_list.blocks, block, next);

            ram_list.mru_block = NULL;

            ram_list.version++;

            if (block->flags & RAM_PREALLOC_MASK) {

                ;

            } else if (xen_enabled()) {

                xen_invalidate_map_cache_entry(block->host);

            } else if (mem_path) {

#if defined (__linux__) && !defined(TARGET_S390X)

                if (block->fd) {

                    munmap(block->host, block->length);

                    close(block->fd);

                } else {

                    qemu_anon_ram_free(block->host, block->length);

                }

#else

                abort();

#endif

            } else {

                qemu_anon_ram_free(block->host, block->length);

            }

            g_free(block);

            break;

        }

    }

    qemu_mutex_unlock_ramlist();



}

static int block_job_finish_sync(BlockJob *job,

                                 void (*finish)(BlockJob *, Error **errp),

                                 Error **errp)

{

    BlockDriverState *bs = job->bs;

    Error *local_err = NULL;

    int ret;



    assert(bs->job == job);



    block_job_ref(job);

    finish(job, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        block_job_unref(job);

        return -EBUSY;

    }

    while (!job->completed) {

        aio_poll(bdrv_get_aio_context(bs), true);

    }

    ret = (job->cancelled && job->ret == 0) ? -ECANCELED : job->ret;

    block_job_unref(job);

    return ret;

}

static uint32_t vmdk_read_cid(BlockDriverState *bs, int parent)

{

    char desc[DESC_SIZE];

    uint32_t cid;

    const char *p_name, *cid_str;

    size_t cid_str_size;

    BDRVVmdkState *s = bs->opaque;



    if (bdrv_pread(bs->file, s->desc_offset, desc, DESC_SIZE) != DESC_SIZE) {

        return 0;

    }



    if (parent) {

        cid_str = "parentCID";

        cid_str_size = sizeof("parentCID");

    } else {

        cid_str = "CID";

        cid_str_size = sizeof("CID");

    }



    if ((p_name = strstr(desc,cid_str)) != NULL) {

        p_name += cid_str_size;

        sscanf(p_name,"%x",&cid);

    }



    return cid;

}

