    VMW_CBPRN("vmxnet3_net_init called...");



    qemu_macaddr_default_if_unset(&s->conf.macaddr);



    /* Windows guest will query the address that was set on init */

    memcpy(&s->perm_mac.a, &s->conf.macaddr.a, sizeof(s->perm_mac.a));



    s->mcast_list = NULL;

    s->mcast_list_len = 0;



