}

static inline void tcg_out_op(TCGContext *s, TCGOpcode opc,

                const TCGArg *args, const int *const_args)

{

    int c;



    switch (opc) {

    case INDEX_op_exit_tb:

        {

            uint8_t *ld_ptr = s->code_ptr;

            if (args[0] >> 8)

                tcg_out_ld32_12(s, COND_AL, TCG_REG_R0, TCG_REG_PC, 0);

            else

                tcg_out_dat_imm(s, COND_AL, ARITH_MOV, TCG_REG_R0, 0, args[0]);

            tcg_out_goto(s, COND_AL, (tcg_target_ulong) tb_ret_addr);

            if (args[0] >> 8) {

                *ld_ptr = (uint8_t) (s->code_ptr - ld_ptr) - 8;

                tcg_out32(s, args[0]);

            }

        }

        break;

    case INDEX_op_goto_tb:

        if (s->tb_jmp_offset) {

            /* Direct jump method */

#if defined(USE_DIRECT_JUMP)

            s->tb_jmp_offset[args[0]] = s->code_ptr - s->code_buf;

            tcg_out_b_noaddr(s, COND_AL);

#else

            tcg_out_ld32_12(s, COND_AL, TCG_REG_PC, TCG_REG_PC, -4);

            s->tb_jmp_offset[args[0]] = s->code_ptr - s->code_buf;

            tcg_out32(s, 0);

#endif

        } else {

            /* Indirect jump method */

#if 1

            c = (int) (s->tb_next + args[0]) - ((int) s->code_ptr + 8);

            if (c > 0xfff || c < -0xfff) {

                tcg_out_movi32(s, COND_AL, TCG_REG_R0,

                                (tcg_target_long) (s->tb_next + args[0]));

                tcg_out_ld32_12(s, COND_AL, TCG_REG_PC, TCG_REG_R0, 0);

            } else

                tcg_out_ld32_12(s, COND_AL, TCG_REG_PC, TCG_REG_PC, c);

#else

            tcg_out_ld32_12(s, COND_AL, TCG_REG_R0, TCG_REG_PC, 0);

            tcg_out_ld32_12(s, COND_AL, TCG_REG_PC, TCG_REG_R0, 0);

            tcg_out32(s, (tcg_target_long) (s->tb_next + args[0]));

#endif

        }

        s->tb_next_offset[args[0]] = s->code_ptr - s->code_buf;

        break;

    case INDEX_op_call:

        if (const_args[0])

            tcg_out_call(s, args[0]);

        else

            tcg_out_callr(s, COND_AL, args[0]);

        break;

    case INDEX_op_br:

        tcg_out_goto_label(s, COND_AL, args[0]);

        break;



    case INDEX_op_ld8u_i32:

        tcg_out_ld8u(s, COND_AL, args[0], args[1], args[2]);

        break;

    case INDEX_op_ld8s_i32:

        tcg_out_ld8s(s, COND_AL, args[0], args[1], args[2]);

        break;

    case INDEX_op_ld16u_i32:

        tcg_out_ld16u(s, COND_AL, args[0], args[1], args[2]);

        break;

    case INDEX_op_ld16s_i32:

        tcg_out_ld16s(s, COND_AL, args[0], args[1], args[2]);

        break;

    case INDEX_op_ld_i32:

        tcg_out_ld32u(s, COND_AL, args[0], args[1], args[2]);

        break;

    case INDEX_op_st8_i32:

        tcg_out_st8(s, COND_AL, args[0], args[1], args[2]);

        break;

    case INDEX_op_st16_i32:

        tcg_out_st16(s, COND_AL, args[0], args[1], args[2]);

        break;

    case INDEX_op_st_i32:

        tcg_out_st32(s, COND_AL, args[0], args[1], args[2]);

        break;



    case INDEX_op_mov_i32:

        tcg_out_dat_reg(s, COND_AL, ARITH_MOV,

                        args[0], 0, args[1], SHIFT_IMM_LSL(0));

        break;

    case INDEX_op_movi_i32:

        tcg_out_movi32(s, COND_AL, args[0], args[1]);

        break;

    case INDEX_op_movcond_i32:

        /* Constraints mean that v2 is always in the same register as dest,

         * so we only need to do "if condition passed, move v1 to dest".

         */

        tcg_out_dat_rI(s, COND_AL, ARITH_CMP, 0,

                       args[1], args[2], const_args[2]);

        tcg_out_dat_rI(s, tcg_cond_to_arm_cond[args[5]],

                       ARITH_MOV, args[0], 0, args[3], const_args[3]);

        break;

    case INDEX_op_add_i32:

        c = ARITH_ADD;

        goto gen_arith;

    case INDEX_op_sub_i32:

        c = ARITH_SUB;

        goto gen_arith;

    case INDEX_op_and_i32:

        tcg_out_dat_rIK(s, COND_AL, ARITH_AND, ARITH_BIC,

                        args[0], args[1], args[2], const_args[2]);

        break;

    case INDEX_op_andc_i32:

        tcg_out_dat_rIK(s, COND_AL, ARITH_BIC, ARITH_AND,

                        args[0], args[1], args[2], const_args[2]);

        break;

    case INDEX_op_or_i32:

        c = ARITH_ORR;

        goto gen_arith;

    case INDEX_op_xor_i32:

        c = ARITH_EOR;

        /* Fall through.  */

    gen_arith:

        tcg_out_dat_rI(s, COND_AL, c, args[0], args[1], args[2], const_args[2]);

        break;

    case INDEX_op_add2_i32:

        tcg_out_dat_reg2(s, COND_AL, ARITH_ADD, ARITH_ADC,

                        args[0], args[1], args[2], args[3],

                        args[4], args[5], SHIFT_IMM_LSL(0));

        break;

    case INDEX_op_sub2_i32:

        tcg_out_dat_reg2(s, COND_AL, ARITH_SUB, ARITH_SBC,

                        args[0], args[1], args[2], args[3],

                        args[4], args[5], SHIFT_IMM_LSL(0));

        break;

    case INDEX_op_neg_i32:

        tcg_out_dat_imm(s, COND_AL, ARITH_RSB, args[0], args[1], 0);

        break;

    case INDEX_op_not_i32:

        tcg_out_dat_reg(s, COND_AL,

                        ARITH_MVN, args[0], 0, args[1], SHIFT_IMM_LSL(0));

        break;

    case INDEX_op_mul_i32:

        tcg_out_mul32(s, COND_AL, args[0], args[1], args[2]);

        break;

    case INDEX_op_mulu2_i32:

        tcg_out_umull32(s, COND_AL, args[0], args[1], args[2], args[3]);

        break;

    case INDEX_op_muls2_i32:

        tcg_out_smull32(s, COND_AL, args[0], args[1], args[2], args[3]);

        break;

    /* XXX: Perhaps args[2] & 0x1f is wrong */

    case INDEX_op_shl_i32:

        c = const_args[2] ?

                SHIFT_IMM_LSL(args[2] & 0x1f) : SHIFT_REG_LSL(args[2]);

        goto gen_shift32;

    case INDEX_op_shr_i32:

        c = const_args[2] ? (args[2] & 0x1f) ? SHIFT_IMM_LSR(args[2] & 0x1f) :

                SHIFT_IMM_LSL(0) : SHIFT_REG_LSR(args[2]);

        goto gen_shift32;

    case INDEX_op_sar_i32:

        c = const_args[2] ? (args[2] & 0x1f) ? SHIFT_IMM_ASR(args[2] & 0x1f) :

                SHIFT_IMM_LSL(0) : SHIFT_REG_ASR(args[2]);

        goto gen_shift32;

    case INDEX_op_rotr_i32:

        c = const_args[2] ? (args[2] & 0x1f) ? SHIFT_IMM_ROR(args[2] & 0x1f) :

                SHIFT_IMM_LSL(0) : SHIFT_REG_ROR(args[2]);

        /* Fall through.  */

    gen_shift32:

        tcg_out_dat_reg(s, COND_AL, ARITH_MOV, args[0], 0, args[1], c);

        break;



    case INDEX_op_rotl_i32:

        if (const_args[2]) {

            tcg_out_dat_reg(s, COND_AL, ARITH_MOV, args[0], 0, args[1],

                            ((0x20 - args[2]) & 0x1f) ?

                            SHIFT_IMM_ROR((0x20 - args[2]) & 0x1f) :

                            SHIFT_IMM_LSL(0));

        } else {

            tcg_out_dat_imm(s, COND_AL, ARITH_RSB, TCG_REG_R8, args[1], 0x20);

            tcg_out_dat_reg(s, COND_AL, ARITH_MOV, args[0], 0, args[1],

                            SHIFT_REG_ROR(TCG_REG_R8));

        }

        break;



    case INDEX_op_brcond_i32:

        tcg_out_dat_rI(s, COND_AL, ARITH_CMP, 0,

                       args[0], args[1], const_args[1]);

        tcg_out_goto_label(s, tcg_cond_to_arm_cond[args[2]], args[3]);

        break;

    case INDEX_op_brcond2_i32:

        /* The resulting conditions are:

         * TCG_COND_EQ    -->  a0 == a2 && a1 == a3,

         * TCG_COND_NE    --> (a0 != a2 && a1 == a3) ||  a1 != a3,

         * TCG_COND_LT(U) --> (a0 <  a2 && a1 == a3) ||  a1 <  a3,

         * TCG_COND_GE(U) --> (a0 >= a2 && a1 == a3) || (a1 >= a3 && a1 != a3),

         * TCG_COND_LE(U) --> (a0 <= a2 && a1 == a3) || (a1 <= a3 && a1 != a3),

         * TCG_COND_GT(U) --> (a0 >  a2 && a1 == a3) ||  a1 >  a3,

         */

        tcg_out_dat_reg(s, COND_AL, ARITH_CMP, 0,

                        args[1], args[3], SHIFT_IMM_LSL(0));

        tcg_out_dat_reg(s, COND_EQ, ARITH_CMP, 0,

                        args[0], args[2], SHIFT_IMM_LSL(0));

        tcg_out_goto_label(s, tcg_cond_to_arm_cond[args[4]], args[5]);

        break;

    case INDEX_op_setcond_i32:

        tcg_out_dat_rI(s, COND_AL, ARITH_CMP, 0,

                       args[1], args[2], const_args[2]);

        tcg_out_dat_imm(s, tcg_cond_to_arm_cond[args[3]],

                        ARITH_MOV, args[0], 0, 1);

        tcg_out_dat_imm(s, tcg_cond_to_arm_cond[tcg_invert_cond(args[3])],

                        ARITH_MOV, args[0], 0, 0);

        break;

    case INDEX_op_setcond2_i32:

        /* See brcond2_i32 comment */

        tcg_out_dat_reg(s, COND_AL, ARITH_CMP, 0,

                        args[2], args[4], SHIFT_IMM_LSL(0));

        tcg_out_dat_reg(s, COND_EQ, ARITH_CMP, 0,

                        args[1], args[3], SHIFT_IMM_LSL(0));

        tcg_out_dat_imm(s, tcg_cond_to_arm_cond[args[5]],

                        ARITH_MOV, args[0], 0, 1);

        tcg_out_dat_imm(s, tcg_cond_to_arm_cond[tcg_invert_cond(args[5])],

                        ARITH_MOV, args[0], 0, 0);

        break;



    case INDEX_op_qemu_ld8u:

        tcg_out_qemu_ld(s, args, 0);

        break;

    case INDEX_op_qemu_ld8s:

        tcg_out_qemu_ld(s, args, 0 | 4);

        break;

    case INDEX_op_qemu_ld16u:

        tcg_out_qemu_ld(s, args, 1);

        break;

    case INDEX_op_qemu_ld16s:

        tcg_out_qemu_ld(s, args, 1 | 4);

        break;

    case INDEX_op_qemu_ld32:

        tcg_out_qemu_ld(s, args, 2);

        break;

    case INDEX_op_qemu_ld64:

        tcg_out_qemu_ld(s, args, 3);

        break;



    case INDEX_op_qemu_st8:

        tcg_out_qemu_st(s, args, 0);

        break;

    case INDEX_op_qemu_st16:

        tcg_out_qemu_st(s, args, 1);

        break;

    case INDEX_op_qemu_st32:

        tcg_out_qemu_st(s, args, 2);

        break;

    case INDEX_op_qemu_st64:

        tcg_out_qemu_st(s, args, 3);

        break;



    case INDEX_op_bswap16_i32:

        tcg_out_bswap16(s, COND_AL, args[0], args[1]);

        break;

    case INDEX_op_bswap32_i32:

        tcg_out_bswap32(s, COND_AL, args[0], args[1]);

        break;



    case INDEX_op_ext8s_i32:

        tcg_out_ext8s(s, COND_AL, args[0], args[1]);

        break;

    case INDEX_op_ext16s_i32:

        tcg_out_ext16s(s, COND_AL, args[0], args[1]);

        break;

    case INDEX_op_ext16u_i32:

        tcg_out_ext16u(s, COND_AL, args[0], args[1]);

        break;



    default:

        tcg_abort();

    }

}

void hmp_info_vnc(Monitor *mon, const QDict *qdict)

{

    VncInfo *info;

    Error *err = NULL;

    VncClientInfoList *client;



    info = qmp_query_vnc(&err);

    if (err) {

        monitor_printf(mon, "%s\n", error_get_pretty(err));

        error_free(err);

        return;

    }



    if (!info->enabled) {

        monitor_printf(mon, "Server: disabled\n");

        goto out;

    }



    monitor_printf(mon, "Server:\n");

    if (info->has_host && info->has_service) {

        monitor_printf(mon, "     address: %s:%s\n", info->host, info->service);

    }

    if (info->has_auth) {

        monitor_printf(mon, "        auth: %s\n", info->auth);

    }



    if (!info->has_clients || info->clients == NULL) {

        monitor_printf(mon, "Client: none\n");

    } else {

        for (client = info->clients; client; client = client->next) {

            monitor_printf(mon, "Client:\n");

            monitor_printf(mon, "     address: %s:%s\n",

                           client->value->base->host,

                           client->value->base->service);

            monitor_printf(mon, "  x509_dname: %s\n",

                           client->value->x509_dname ?

                           client->value->x509_dname : "none");

            monitor_printf(mon, "    username: %s\n",

                           client->value->has_sasl_username ?

                           client->value->sasl_username : "none");

        }

    }



out:

    qapi_free_VncInfo(info);

}

static void cmos_init(int ram_size, const char *boot_device, BlockDriverState **hd_table)

{

    RTCState *s = rtc_state;

    int val;

    int fd0, fd1, nb;

    int i;



    /* various important CMOS locations needed by PC/Bochs bios */



    /* memory size */

    val = 640; /* base memory in K */

    rtc_set_memory(s, 0x15, val);

    rtc_set_memory(s, 0x16, val >> 8);



    val = (ram_size / 1024) - 1024;

    if (val > 65535)

        val = 65535;

    rtc_set_memory(s, 0x17, val);

    rtc_set_memory(s, 0x18, val >> 8);

    rtc_set_memory(s, 0x30, val);

    rtc_set_memory(s, 0x31, val >> 8);



    if (ram_size > (16 * 1024 * 1024))

        val = (ram_size / 65536) - ((16 * 1024 * 1024) / 65536);

    else

        val = 0;

    if (val > 65535)

        val = 65535;

    rtc_set_memory(s, 0x34, val);

    rtc_set_memory(s, 0x35, val >> 8);



    /* set boot devices, and disable floppy signature check if requested */

    rtc_set_memory(s, 0x3d,

            boot_device2nibble(boot_device[1]) << 4 |

            boot_device2nibble(boot_device[0]) );

    rtc_set_memory(s, 0x38,

            boot_device2nibble(boot_device[2]) << 4 | (fd_bootchk ?  0x0 : 0x1));



    /* floppy type */



    fd0 = fdctrl_get_drive_type(floppy_controller, 0);

    fd1 = fdctrl_get_drive_type(floppy_controller, 1);



    val = (cmos_get_fd_drive_type(fd0) << 4) | cmos_get_fd_drive_type(fd1);

    rtc_set_memory(s, 0x10, val);



    val = 0;

    nb = 0;

    if (fd0 < 3)

        nb++;

    if (fd1 < 3)

        nb++;

    switch (nb) {

    case 0:

        break;

    case 1:

        val |= 0x01; /* 1 drive, ready for boot */

        break;

    case 2:

        val |= 0x41; /* 2 drives, ready for boot */

        break;

    }

    val |= 0x02; /* FPU is there */

    val |= 0x04; /* PS/2 mouse installed */

    rtc_set_memory(s, REG_EQUIPMENT_BYTE, val);



    /* hard drives */



    rtc_set_memory(s, 0x12, (hd_table[0] ? 0xf0 : 0) | (hd_table[1] ? 0x0f : 0));

    if (hd_table[0])

        cmos_init_hd(0x19, 0x1b, hd_table[0]);

    if (hd_table[1])

        cmos_init_hd(0x1a, 0x24, hd_table[1]);



    val = 0;

    for (i = 0; i < 4; i++) {

        if (hd_table[i]) {

            int cylinders, heads, sectors, translation;

            /* NOTE: bdrv_get_geometry_hint() returns the physical

                geometry.  It is always such that: 1 <= sects <= 63, 1

                <= heads <= 16, 1 <= cylinders <= 16383. The BIOS

                geometry can be different if a translation is done. */

            translation = bdrv_get_translation_hint(hd_table[i]);

            if (translation == BIOS_ATA_TRANSLATION_AUTO) {

                bdrv_get_geometry_hint(hd_table[i], &cylinders, &heads, &sectors);

                if (cylinders <= 1024 && heads <= 16 && sectors <= 63) {

                    /* No translation. */

                    translation = 0;

                } else {

                    /* LBA translation. */

                    translation = 1;

                }

            } else {

                translation--;

            }

            val |= translation << (i * 2);

        }

    }

    rtc_set_memory(s, 0x39, val);

}

static int nbd_parse_uri(const char *filename, QDict *options)

{

    URI *uri;

    const char *p;

    QueryParams *qp = NULL;

    int ret = 0;

    bool is_unix;



    uri = uri_parse(filename);

    if (!uri) {

        return -EINVAL;

    }



    /* transport */

    if (!strcmp(uri->scheme, "nbd")) {

        is_unix = false;

    } else if (!strcmp(uri->scheme, "nbd+tcp")) {

        is_unix = false;

    } else if (!strcmp(uri->scheme, "nbd+unix")) {

        is_unix = true;

    } else {

        ret = -EINVAL;

        goto out;

    }



    p = uri->path ? uri->path : "/";

    p += strspn(p, "/");

    if (p[0]) {

        qdict_put(options, "export", qstring_from_str(p));

    }



    qp = query_params_parse(uri->query);

    if (qp->n > 1 || (is_unix && !qp->n) || (!is_unix && qp->n)) {

        ret = -EINVAL;

        goto out;

    }



    if (is_unix) {

        /* nbd+unix:///export?socket=path */

        if (uri->server || uri->port || strcmp(qp->p[0].name, "socket")) {

            ret = -EINVAL;

            goto out;

        }

        qdict_put(options, "server.type", qstring_from_str("unix"));

        qdict_put(options, "server.data.path",

                  qstring_from_str(qp->p[0].value));

    } else {

        QString *host;

        char *port_str;



        /* nbd[+tcp]://host[:port]/export */

        if (!uri->server) {

            ret = -EINVAL;

            goto out;

        }



        /* strip braces from literal IPv6 address */

        if (uri->server[0] == '[') {

            host = qstring_from_substr(uri->server, 1,

                                       strlen(uri->server) - 2);

        } else {

            host = qstring_from_str(uri->server);

        }



        qdict_put(options, "server.type", qstring_from_str("inet"));

        qdict_put(options, "server.data.host", host);



        port_str = g_strdup_printf("%d", uri->port ?: NBD_DEFAULT_PORT);

        qdict_put(options, "server.data.port", qstring_from_str(port_str));

        g_free(port_str);

    }



out:

    if (qp) {

        query_params_free(qp);

    }

    uri_free(uri);

    return ret;

}

static void disas_ldst_excl(DisasContext *s, uint32_t insn)

{

    int rt = extract32(insn, 0, 5);

    int rn = extract32(insn, 5, 5);

    int rt2 = extract32(insn, 10, 5);

    int is_lasr = extract32(insn, 15, 1);

    int rs = extract32(insn, 16, 5);

    int is_pair = extract32(insn, 21, 1);

    int is_store = !extract32(insn, 22, 1);

    int is_excl = !extract32(insn, 23, 1);

    int size = extract32(insn, 30, 2);

    TCGv_i64 tcg_addr;



    if ((!is_excl && !is_lasr) ||

        (is_pair && size < 2)) {

        unallocated_encoding(s);

        return;

    }



    if (rn == 31) {

        gen_check_sp_alignment(s);

    }

    tcg_addr = read_cpu_reg_sp(s, rn, 1);



    /* Note that since TCG is single threaded load-acquire/store-release

     * semantics require no extra if (is_lasr) { ... } handling.

     */



    if (is_excl) {

        if (!is_store) {

            s->is_ldex = true;

            gen_load_exclusive(s, rt, rt2, tcg_addr, size, is_pair);

        } else {

            gen_store_exclusive(s, rs, rt, rt2, tcg_addr, size, is_pair);

        }

    } else {

        TCGv_i64 tcg_rt = cpu_reg(s, rt);

        if (is_store) {

            do_gpr_st(s, tcg_rt, tcg_addr, size);

        } else {

            do_gpr_ld(s, tcg_rt, tcg_addr, size, false, false);

        }

        if (is_pair) {

            TCGv_i64 tcg_rt2 = cpu_reg(s, rt);

            tcg_gen_addi_i64(tcg_addr, tcg_addr, 1 << size);

            if (is_store) {

                do_gpr_st(s, tcg_rt2, tcg_addr, size);

            } else {

                do_gpr_ld(s, tcg_rt2, tcg_addr, size, false, false);

            }

        }

    }

}

