static void tcg_out_insn_3405(TCGContext *s, AArch64Insn insn, TCGType ext,

                              TCGReg rd, uint16_t half, unsigned shift)

{

    assert((shift & ~0x30) == 0);

    tcg_out32(s, insn | ext << 31 | shift << (21 - 4) | half << 5 | rd);

}

static inline int handle_cpu_signal(unsigned long pc, unsigned long address,

                                    int is_write, sigset_t *old_set, 

                                    void *puc)

{

    TranslationBlock *tb;

    int ret;



    if (cpu_single_env)

        env = cpu_single_env; /* XXX: find a correct solution for multithread */

#if defined(DEBUG_SIGNAL)

    qemu_printf("qemu: SIGSEGV pc=0x%08lx address=%08lx w=%d oldset=0x%08lx\n", 

                pc, address, is_write, *(unsigned long *)old_set);

#endif

    /* XXX: locking issue */

    if (is_write && page_unprotect(address, pc, puc)) {

        return 1;

    }



    /* see if it is an MMU fault */

    ret = cpu_x86_handle_mmu_fault(env, address, is_write, 

                                   ((env->hflags & HF_CPL_MASK) == 3), 0);

    if (ret < 0)

        return 0; /* not an MMU fault */

    if (ret == 0)

        return 1; /* the MMU fault was handled without causing real CPU fault */

    /* now we have a real cpu fault */

    tb = tb_find_pc(pc);

    if (tb) {

        /* the PC is inside the translated code. It means that we have

           a virtual CPU fault */

        cpu_restore_state(tb, env, pc, puc);

    }

    if (ret == 1) {

#if 0

        printf("PF exception: EIP=0x%08x CR2=0x%08x error=0x%x\n", 

               env->eip, env->cr[2], env->error_code);

#endif

        /* we restore the process signal mask as the sigreturn should

           do it (XXX: use sigsetjmp) */

        sigprocmask(SIG_SETMASK, old_set, NULL);

        raise_exception_err(EXCP0E_PAGE, env->error_code);

    } else {

        /* activate soft MMU for this block */

        env->hflags |= HF_SOFTMMU_MASK;

        cpu_resume_from_signal(env, puc);

    }

    /* never comes here */

    return 1;

}

static void coroutine_fn v9fs_xattrcreate(void *opaque)

{

    int flags;

    int32_t fid;

    int64_t size;

    ssize_t err = 0;

    V9fsString name;

    size_t offset = 7;

    V9fsFidState *file_fidp;

    V9fsFidState *xattr_fidp;

    V9fsPDU *pdu = opaque;



    v9fs_string_init(&name);

    err = pdu_unmarshal(pdu, offset, "dsqd", &fid, &name, &size, &flags);

    if (err < 0) {

        goto out_nofid;

    }

    trace_v9fs_xattrcreate(pdu->tag, pdu->id, fid, name.data, size, flags);



    file_fidp = get_fid(pdu, fid);

    if (file_fidp == NULL) {

        err = -EINVAL;

        goto out_nofid;

    }

    /* Make the file fid point to xattr */

    xattr_fidp = file_fidp;

    xattr_fidp->fid_type = P9_FID_XATTR;

    xattr_fidp->fs.xattr.copied_len = 0;

    xattr_fidp->fs.xattr.xattrwalk_fid = false;

    xattr_fidp->fs.xattr.len = size;

    xattr_fidp->fs.xattr.flags = flags;

    v9fs_string_init(&xattr_fidp->fs.xattr.name);

    v9fs_string_copy(&xattr_fidp->fs.xattr.name, &name);

    g_free(xattr_fidp->fs.xattr.value);

    xattr_fidp->fs.xattr.value = g_malloc0(size);

    err = offset;

    put_fid(pdu, file_fidp);

out_nofid:

    pdu_complete(pdu, err);

    v9fs_string_free(&name);

}

static void omap_sysctl_write(void *opaque, target_phys_addr_t addr,

                uint32_t value)

{

    struct omap_sysctl_s *s = (struct omap_sysctl_s *) opaque;



    switch (addr) {

    case 0x000:	/* CONTROL_REVISION */

    case 0x2a4:	/* CONTROL_MSUSPENDMUX_5 */

    case 0x2c0:	/* CONTROL_PSA_VALUE */

    case 0x2f8:	/* CONTROL_STATUS */

    case 0x2fc:	/* CONTROL_GENERAL_PURPOSE_STATUS */

    case 0x300:	/* CONTROL_RPUB_KEY_H_0 */

    case 0x304:	/* CONTROL_RPUB_KEY_H_1 */

    case 0x308:	/* CONTROL_RPUB_KEY_H_2 */

    case 0x30c:	/* CONTROL_RPUB_KEY_H_3 */

    case 0x310:	/* CONTROL_RAND_KEY_0 */

    case 0x314:	/* CONTROL_RAND_KEY_1 */

    case 0x318:	/* CONTROL_RAND_KEY_2 */

    case 0x31c:	/* CONTROL_RAND_KEY_3 */

    case 0x320:	/* CONTROL_CUST_KEY_0 */

    case 0x324:	/* CONTROL_CUST_KEY_1 */

    case 0x330:	/* CONTROL_TEST_KEY_0 */

    case 0x334:	/* CONTROL_TEST_KEY_1 */

    case 0x338:	/* CONTROL_TEST_KEY_2 */

    case 0x33c:	/* CONTROL_TEST_KEY_3 */

    case 0x340:	/* CONTROL_TEST_KEY_4 */

    case 0x344:	/* CONTROL_TEST_KEY_5 */

    case 0x348:	/* CONTROL_TEST_KEY_6 */

    case 0x34c:	/* CONTROL_TEST_KEY_7 */

    case 0x350:	/* CONTROL_TEST_KEY_8 */

    case 0x354:	/* CONTROL_TEST_KEY_9 */

        OMAP_RO_REG(addr);

        return;



    case 0x010:	/* CONTROL_SYSCONFIG */

        s->sysconfig = value & 0x1e;

        break;



    case 0x030 ... 0x140:	/* CONTROL_PADCONF - only used in the POP */

        /* XXX: should check constant bits */

        s->padconf[(addr - 0x30) >> 2] = value & 0x1f1f1f1f;

        break;



    case 0x270:	/* CONTROL_DEBOBS */

        s->obs = value & 0xff;

        break;



    case 0x274:	/* CONTROL_DEVCONF */

        s->devconfig = value & 0xffffc7ff;

        break;



    case 0x28c:	/* CONTROL_EMU_SUPPORT */

        break;



    case 0x290:	/* CONTROL_MSUSPENDMUX_0 */

        s->msuspendmux[0] = value & 0x3fffffff;

        break;

    case 0x294:	/* CONTROL_MSUSPENDMUX_1 */

        s->msuspendmux[1] = value & 0x3fffffff;

        break;

    case 0x298:	/* CONTROL_MSUSPENDMUX_2 */

        s->msuspendmux[2] = value & 0x3fffffff;

        break;

    case 0x29c:	/* CONTROL_MSUSPENDMUX_3 */

        s->msuspendmux[3] = value & 0x3fffffff;

        break;

    case 0x2a0:	/* CONTROL_MSUSPENDMUX_4 */

        s->msuspendmux[4] = value & 0x3fffffff;

        break;



    case 0x2b8:	/* CONTROL_PSA_CTRL */

        s->psaconfig = value & 0x1c;

        s->psaconfig |= (value & 0x20) ? 2 : 1;

        break;

    case 0x2bc:	/* CONTROL_PSA_CMD */

        break;



    case 0x2b0:	/* CONTROL_SEC_CTRL */

    case 0x2b4:	/* CONTROL_SEC_TEST */

    case 0x2d0:	/* CONTROL_SEC_EMU */

    case 0x2d4:	/* CONTROL_SEC_TAP */

    case 0x2d8:	/* CONTROL_OCM_RAM_PERM */

    case 0x2dc:	/* CONTROL_OCM_PUB_RAM_ADD */

    case 0x2e0:	/* CONTROL_EXT_SEC_RAM_START_ADD */

    case 0x2e4:	/* CONTROL_EXT_SEC_RAM_STOP_ADD */

    case 0x2f0:	/* CONTROL_SEC_STATUS */

    case 0x2f4:	/* CONTROL_SEC_ERR_STATUS */

        break;



    default:

        OMAP_BAD_REG(addr);

        return;

    }

}

ssize_t qemu_paio_return(struct qemu_paiocb *aiocb)

{

    ssize_t ret;



    pthread_mutex_lock(&lock);

