static char *read_splashfile(char *filename, int *file_sizep, int *file_typep)

{

    GError *err = NULL;

    gboolean res;

    gchar *content;

    int file_type = -1;

    unsigned int filehead = 0;

    int bmp_bpp;



    res = g_file_get_contents(filename, &content, (gsize *)file_sizep, &err);

    if (res == FALSE) {

        error_report("failed to read splash file '%s'", filename);

        g_error_free(err);

        return NULL;

    }



    /* check file size */

    if (*file_sizep < 30) {

        goto error;

    }



    /* check magic ID */

    filehead = ((content[0] & 0xff) + (content[1] << 8)) & 0xffff;

    if (filehead == 0xd8ff) {

        file_type = JPG_FILE;

    } else if (filehead == 0x4d42) {

        file_type = BMP_FILE;

    } else {

        goto error;

    }



    /* check BMP bpp */

    if (file_type == BMP_FILE) {

        bmp_bpp = (content[28] + (content[29] << 8)) & 0xffff;

        if (bmp_bpp != 24) {

            goto error;

        }

    }



    /* return values */

    *file_typep = file_type;



    return content;



error:

    error_report("splash file '%s' format not recognized; must be JPEG "

                 "or 24 bit BMP", filename);

    g_free(content);

    return NULL;

}

struct pxa2xx_lcdc_s *pxa2xx_lcdc_init(target_phys_addr_t base, qemu_irq irq,

                DisplayState *ds)

{

    int iomemtype;

    struct pxa2xx_lcdc_s *s;



    s = (struct pxa2xx_lcdc_s *) qemu_mallocz(sizeof(struct pxa2xx_lcdc_s));

    s->base = base;

    s->invalidated = 1;

    s->irq = irq;

    s->ds = ds;



    pxa2xx_lcdc_orientation(s, graphic_rotate);



    iomemtype = cpu_register_io_memory(0, pxa2xx_lcdc_readfn,

                    pxa2xx_lcdc_writefn, s);

    cpu_register_physical_memory(base, 0x000fffff, iomemtype);



    graphic_console_init(ds, pxa2xx_update_display,

                    pxa2xx_invalidate_display, pxa2xx_screen_dump, s);



    switch (s->ds->depth) {

    case 0:

        s->dest_width = 0;

        break;

    case 8:

        s->line_fn[0] = pxa2xx_draw_fn_8;

        s->line_fn[1] = pxa2xx_draw_fn_8t;

        s->dest_width = 1;

        break;

    case 15:

        s->line_fn[0] = pxa2xx_draw_fn_15;

        s->line_fn[1] = pxa2xx_draw_fn_15t;

        s->dest_width = 2;

        break;

    case 16:

        s->line_fn[0] = pxa2xx_draw_fn_16;

        s->line_fn[1] = pxa2xx_draw_fn_16t;

        s->dest_width = 2;

        break;

    case 24:

        s->line_fn[0] = pxa2xx_draw_fn_24;

        s->line_fn[1] = pxa2xx_draw_fn_24t;

        s->dest_width = 3;

        break;

    case 32:

        s->line_fn[0] = pxa2xx_draw_fn_32;

        s->line_fn[1] = pxa2xx_draw_fn_32t;

        s->dest_width = 4;

        break;

    default:

        fprintf(stderr, "%s: Bad color depth\n", __FUNCTION__);

        exit(1);

    }



    register_savevm("pxa2xx_lcdc", 0, 0,

                    pxa2xx_lcdc_save, pxa2xx_lcdc_load, s);



    return s;

}

