                                          NET_CLIENT_OPTIONS_KIND_NIC,
                                          MAX_QUEUE_NUM);
    if (queues == 0) {
        ret = -ENOENT;
    if (queues > MAX_QUEUE_NUM) {
        ret = -E2BIG;
    for (i = 0; i < queues; i++) {
        if (peers[i] == NULL) {
            ret = -ENOENT;
        if (peers[i]->peer) {
            ret = -EEXIST;
        ncs[i] = peers[i];
        ncs[i]->queue_index = i;
    conf->queues = queues;
    return 0;
err:
