static void ps2_mouse_event(DeviceState *dev, QemuConsole *src,

                            InputEvent *evt)

{

    static const int bmap[INPUT_BUTTON__MAX] = {

        [INPUT_BUTTON_LEFT]   = MOUSE_EVENT_LBUTTON,

        [INPUT_BUTTON_MIDDLE] = MOUSE_EVENT_MBUTTON,

        [INPUT_BUTTON_RIGHT]  = MOUSE_EVENT_RBUTTON,

    };

    PS2MouseState *s = (PS2MouseState *)dev;

    InputMoveEvent *move;

    InputBtnEvent *btn;



    /* check if deltas are recorded when disabled */

    if (!(s->mouse_status & MOUSE_STATUS_ENABLED))

        return;



    switch (evt->type) {

    case INPUT_EVENT_KIND_REL:

        move = evt->u.rel;

        if (move->axis == INPUT_AXIS_X) {

            s->mouse_dx += move->value;

        } else if (move->axis == INPUT_AXIS_Y) {

            s->mouse_dy -= move->value;

        }

        break;



    case INPUT_EVENT_KIND_BTN:

        btn = evt->u.btn;

        if (btn->down) {

            s->mouse_buttons |= bmap[btn->button];

            if (btn->button == INPUT_BUTTON_WHEEL_UP) {

                s->mouse_dz--;

            } else if (btn->button == INPUT_BUTTON_WHEEL_DOWN) {

                s->mouse_dz++;

            }

        } else {

            s->mouse_buttons &= ~bmap[btn->button];

        }

        break;



    default:

        /* keep gcc happy */

        break;

    }

}

static void gdb_accept(void *opaque)

{

    GDBState *s;

    struct sockaddr_in sockaddr;

    socklen_t len;

    int val, fd;



    for(;;) {

        len = sizeof(sockaddr);

        fd = accept(gdbserver_fd, (struct sockaddr *)&sockaddr, &len);

        if (fd < 0 && errno != EINTR) {

            perror("accept");

            return;

        } else if (fd >= 0) {

            break;

        }

    }



    /* set short latency */

    val = 1;

    setsockopt(fd, IPPROTO_TCP, TCP_NODELAY, (char *)&val, sizeof(val));



    s = &gdbserver_state;

    memset (s, 0, sizeof (GDBState));

    s->env = first_cpu; /* XXX: allow to change CPU */

    s->fd = fd;

    gdb_has_xml = 0;



    gdb_syscall_state = s;



    fcntl(fd, F_SETFL, O_NONBLOCK);

}

bool desc_ring_set_size(DescRing *ring, uint32_t size)

{

    int i;



    if (size < 2 || size > 0x10000 || (size & (size - 1))) {

        DPRINTF("ERROR: ring[%d] size (%d) not a power of 2 "

                "or in range [2, 64K]\n", ring->index, size);

        return false;

    }



    for (i = 0; i < ring->size; i++) {

        if (ring->info[i].buf) {

            g_free(ring->info[i].buf);

        }

    }



    ring->size = size;

    ring->head = ring->tail = 0;



    ring->info = g_realloc(ring->info, size * sizeof(DescInfo));

    if (!ring->info) {

        return false;

    }



    memset(ring->info, 0, size * sizeof(DescInfo));



    for (i = 0; i < size; i++) {

        ring->info[i].ring = ring;

    }



    return true;

}

