qcrypto_tls_session_check_certificate(QCryptoTLSSession *session,

                                      Error **errp)

{

    int ret;

    unsigned int status;

    const gnutls_datum_t *certs;

    unsigned int nCerts, i;

    time_t now;

    gnutls_x509_crt_t cert = NULL;



    now = time(NULL);

    if (now == ((time_t)-1)) {

        error_setg_errno(errp, errno, "Cannot get current time");

        return -1;

    }



    ret = gnutls_certificate_verify_peers2(session->handle, &status);

    if (ret < 0) {

        error_setg(errp, "Verify failed: %s", gnutls_strerror(ret));

        return -1;

    }



    if (status != 0) {

        const char *reason = "Invalid certificate";



        if (status & GNUTLS_CERT_INVALID) {

            reason = "The certificate is not trusted";

        }



        if (status & GNUTLS_CERT_SIGNER_NOT_FOUND) {

            reason = "The certificate hasn't got a known issuer";

        }



        if (status & GNUTLS_CERT_REVOKED) {

            reason = "The certificate has been revoked";

        }



        if (status & GNUTLS_CERT_INSECURE_ALGORITHM) {

            reason = "The certificate uses an insecure algorithm";

        }



        error_setg(errp, "%s", reason);

        return -1;

    }



    certs = gnutls_certificate_get_peers(session->handle, &nCerts);

    if (!certs) {

        error_setg(errp, "No certificate peers");

        return -1;

    }



    for (i = 0; i < nCerts; i++) {

        ret = gnutls_x509_crt_init(&cert);

        if (ret < 0) {

            error_setg(errp, "Cannot initialize certificate: %s",

                       gnutls_strerror(ret));

            return -1;

        }



        ret = gnutls_x509_crt_import(cert, &certs[i], GNUTLS_X509_FMT_DER);

        if (ret < 0) {

            error_setg(errp, "Cannot import certificate: %s",

                       gnutls_strerror(ret));

            goto error;

        }



        if (gnutls_x509_crt_get_expiration_time(cert) < now) {

            error_setg(errp, "The certificate has expired");

            goto error;

        }



        if (gnutls_x509_crt_get_activation_time(cert) > now) {

            error_setg(errp, "The certificate is not yet activated");

            goto error;

        }



        if (gnutls_x509_crt_get_activation_time(cert) > now) {

            error_setg(errp, "The certificate is not yet activated");

            goto error;

        }



        if (i == 0) {

            size_t dnameSize = 1024;

            session->peername = g_malloc(dnameSize);

        requery:

            ret = gnutls_x509_crt_get_dn(cert, session->peername, &dnameSize);

            if (ret < 0) {

                if (ret == GNUTLS_E_SHORT_MEMORY_BUFFER) {

                    session->peername = g_realloc(session->peername,

                                                  dnameSize);

                    goto requery;

                }

                error_setg(errp, "Cannot get client distinguished name: %s",

                           gnutls_strerror(ret));

                goto error;

            }

            if (session->aclname) {

                qemu_acl *acl = qemu_acl_find(session->aclname);

                int allow;

                if (!acl) {

                    error_setg(errp, "Cannot find ACL %s",

                               session->aclname);

                    goto error;

                }



                allow = qemu_acl_party_is_allowed(acl, session->peername);



                error_setg(errp, "TLS x509 ACL check for %s is %s",

                           session->peername, allow ? "allowed" : "denied");

                if (!allow) {

                    goto error;

                }

            }

            if (session->hostname) {

                if (!gnutls_x509_crt_check_hostname(cert, session->hostname)) {

                    error_setg(errp,

                               "Certificate does not match the hostname %s",

                               session->hostname);

                    goto error;

                }

            }

        }



        gnutls_x509_crt_deinit(cert);

    }



    return 0;



 error:

    gnutls_x509_crt_deinit(cert);

    return -1;

}

static inline int32_t mipsdsp_add_i32(int32_t a, int32_t b, CPUMIPSState *env)

{

    int32_t temp;



    temp = a + b;



    if (MIPSDSP_OVERFLOW(a, b, temp, 0x80000000)) {

        set_DSPControl_overflow_flag(1, 20, env);

    }



    return temp;

}

static void nand_command(NANDFlashState *s)

{

    unsigned int offset;

    switch (s->cmd) {

    case NAND_CMD_READ0:

        s->iolen = 0;

        break;



    case NAND_CMD_READID:

        s->ioaddr = s->io;

        s->iolen = 0;

        nand_pushio_byte(s, s->manf_id);

        nand_pushio_byte(s, s->chip_id);

        nand_pushio_byte(s, 'Q'); /* Don't-care byte (often 0xa5) */

        if (nand_flash_ids[s->chip_id].options & NAND_SAMSUNG_LP) {

            /* Page Size, Block Size, Spare Size; bit 6 indicates

             * 8 vs 16 bit width NAND.

             */

            nand_pushio_byte(s, (s->buswidth == 2) ? 0x55 : 0x15);

        } else {

            nand_pushio_byte(s, 0xc0); /* Multi-plane */

        }

        break;



    case NAND_CMD_RANDOMREAD2:

    case NAND_CMD_NOSERIALREAD2:

        if (!(nand_flash_ids[s->chip_id].options & NAND_SAMSUNG_LP))

            break;

        offset = s->addr & ((1 << s->addr_shift) - 1);

        s->blk_load(s, s->addr, offset);

        if (s->gnd)

            s->iolen = (1 << s->page_shift) - offset;

        else

            s->iolen = (1 << s->page_shift) + (1 << s->oob_shift) - offset;

        break;



    case NAND_CMD_RESET:

        nand_reset(&s->busdev.qdev);

        break;



    case NAND_CMD_PAGEPROGRAM1:

        s->ioaddr = s->io;

        s->iolen = 0;

        break;



    case NAND_CMD_PAGEPROGRAM2:

        if (s->wp) {

            s->blk_write(s);

        }

        break;



    case NAND_CMD_BLOCKERASE1:

        break;



    case NAND_CMD_BLOCKERASE2:

        s->addr &= (1ull << s->addrlen * 8) - 1;

        if (nand_flash_ids[s->chip_id].options & NAND_SAMSUNG_LP)

            s->addr <<= 16;

        else

            s->addr <<= 8;



        if (s->wp) {

            s->blk_erase(s);

        }

        break;



    case NAND_CMD_READSTATUS:

        s->ioaddr = s->io;

        s->iolen = 0;

        nand_pushio_byte(s, s->status);

        break;



    default:

        printf("%s: Unknown NAND command 0x%02x\n", __FUNCTION__, s->cmd);

    }

}

static void readline_hist_add(ReadLineState *rs, const char *cmdline)

{

    char *hist_entry, *new_entry;

    int idx;



    if (cmdline[0] == '\0')

	return;

    new_entry = NULL;

    if (rs->hist_entry != -1) {

	/* We were editing an existing history entry: replace it */

	hist_entry = rs->history[rs->hist_entry];

	idx = rs->hist_entry;

	if (strcmp(hist_entry, cmdline) == 0) {

	    goto same_entry;

	}

    }

    /* Search cmdline in history buffers */

    for (idx = 0; idx < READLINE_MAX_CMDS; idx++) {

	hist_entry = rs->history[idx];

	if (hist_entry == NULL)

	    break;

	if (strcmp(hist_entry, cmdline) == 0) {

	same_entry:

	    new_entry = hist_entry;

	    /* Put this entry at the end of history */

	    memmove(&rs->history[idx], &rs->history[idx + 1],

		    (READLINE_MAX_CMDS - idx + 1) * sizeof(char *));

	    rs->history[READLINE_MAX_CMDS - 1] = NULL;

	    for (; idx < READLINE_MAX_CMDS; idx++) {

		if (rs->history[idx] == NULL)

		    break;

	    }

	    break;

	}

    }

    if (idx == READLINE_MAX_CMDS) {

	/* Need to get one free slot */

	free(rs->history[0]);

	memcpy(rs->history, &rs->history[1],

	       (READLINE_MAX_CMDS - 1) * sizeof(char *));

	rs->history[READLINE_MAX_CMDS - 1] = NULL;

	idx = READLINE_MAX_CMDS - 1;

    }

    if (new_entry == NULL)

	new_entry = strdup(cmdline);

    rs->history[idx] = new_entry;

    rs->hist_entry = -1;

}

static int flush_blks(QEMUFile *f)

{

    BlkMigBlock *blk;

    int ret = 0;



    DPRINTF("%s Enter submitted %d read_done %d transferred %d\n",

            __FUNCTION__, block_mig_state.submitted, block_mig_state.read_done,

            block_mig_state.transferred);



    blk_mig_lock();

    while ((blk = QSIMPLEQ_FIRST(&block_mig_state.blk_list)) != NULL) {

        if (qemu_file_rate_limit(f)) {

            break;

        }

        if (blk->ret < 0) {

            ret = blk->ret;

            break;

        }



        QSIMPLEQ_REMOVE_HEAD(&block_mig_state.blk_list, entry);

        blk_mig_unlock();

        blk_send(f, blk);

        blk_mig_lock();



        g_free(blk->buf);

        g_free(blk);



        block_mig_state.read_done--;

        block_mig_state.transferred++;

        assert(block_mig_state.read_done >= 0);

    }

    blk_mig_unlock();



    DPRINTF("%s Exit submitted %d read_done %d transferred %d\n", __FUNCTION__,

            block_mig_state.submitted, block_mig_state.read_done,

            block_mig_state.transferred);

    return ret;

}

static void sx1_init(MachineState *machine, const int version)

{

    struct omap_mpu_state_s *mpu;

    MemoryRegion *address_space = get_system_memory();

    MemoryRegion *flash = g_new(MemoryRegion, 1);

    MemoryRegion *flash_1 = g_new(MemoryRegion, 1);

    MemoryRegion *cs = g_new(MemoryRegion, 4);

    static uint32_t cs0val = 0x00213090;

    static uint32_t cs1val = 0x00215070;

    static uint32_t cs2val = 0x00001139;

    static uint32_t cs3val = 0x00001139;

    DriveInfo *dinfo;

    int fl_idx;

    uint32_t flash_size = flash0_size;

    int be;



    if (version == 2) {

        flash_size = flash2_size;

    }



    mpu = omap310_mpu_init(address_space, sx1_binfo.ram_size,

                           machine->cpu_model);



    /* External Flash (EMIFS) */

    memory_region_init_ram(flash, NULL, "omap_sx1.flash0-0", flash_size,

                           &error_abort);

    vmstate_register_ram_global(flash);

    memory_region_set_readonly(flash, true);

    memory_region_add_subregion(address_space, OMAP_CS0_BASE, flash);



    memory_region_init_io(&cs[0], NULL, &static_ops, &cs0val,

                          "sx1.cs0", OMAP_CS0_SIZE - flash_size);

    memory_region_add_subregion(address_space,

                                OMAP_CS0_BASE + flash_size, &cs[0]);





    memory_region_init_io(&cs[2], NULL, &static_ops, &cs2val,

                          "sx1.cs2", OMAP_CS2_SIZE);

    memory_region_add_subregion(address_space,

                                OMAP_CS2_BASE, &cs[2]);



    memory_region_init_io(&cs[3], NULL, &static_ops, &cs3val,

                          "sx1.cs3", OMAP_CS3_SIZE);

    memory_region_add_subregion(address_space,

                                OMAP_CS2_BASE, &cs[3]);



    fl_idx = 0;

#ifdef TARGET_WORDS_BIGENDIAN

    be = 1;

#else

    be = 0;

#endif



    if ((dinfo = drive_get(IF_PFLASH, 0, fl_idx)) != NULL) {

        if (!pflash_cfi01_register(OMAP_CS0_BASE, NULL,

                                   "omap_sx1.flash0-1", flash_size,

                                   blk_by_legacy_dinfo(dinfo),

                                   sector_size, flash_size / sector_size,

                                   4, 0, 0, 0, 0, be)) {

            fprintf(stderr, "qemu: Error registering flash memory %d.\n",

                           fl_idx);

        }

        fl_idx++;

    }



    if ((version == 1) &&

            (dinfo = drive_get(IF_PFLASH, 0, fl_idx)) != NULL) {

        memory_region_init_ram(flash_1, NULL, "omap_sx1.flash1-0", flash1_size,

                               &error_abort);

        vmstate_register_ram_global(flash_1);

        memory_region_set_readonly(flash_1, true);

        memory_region_add_subregion(address_space, OMAP_CS1_BASE, flash_1);



        memory_region_init_io(&cs[1], NULL, &static_ops, &cs1val,

                              "sx1.cs1", OMAP_CS1_SIZE - flash1_size);

        memory_region_add_subregion(address_space,

                                OMAP_CS1_BASE + flash1_size, &cs[1]);



        if (!pflash_cfi01_register(OMAP_CS1_BASE, NULL,

                                   "omap_sx1.flash1-1", flash1_size,

                                   blk_by_legacy_dinfo(dinfo),

                                   sector_size, flash1_size / sector_size,

                                   4, 0, 0, 0, 0, be)) {

            fprintf(stderr, "qemu: Error registering flash memory %d.\n",

                           fl_idx);

        }

        fl_idx++;

    } else {

        memory_region_init_io(&cs[1], NULL, &static_ops, &cs1val,

                              "sx1.cs1", OMAP_CS1_SIZE);

        memory_region_add_subregion(address_space,

                                OMAP_CS1_BASE, &cs[1]);

    }



    if (!machine->kernel_filename && !fl_idx && !qtest_enabled()) {

        fprintf(stderr, "Kernel or Flash image must be specified\n");

        exit(1);

    }



    /* Load the kernel.  */

    sx1_binfo.kernel_filename = machine->kernel_filename;

    sx1_binfo.kernel_cmdline = machine->kernel_cmdline;

    sx1_binfo.initrd_filename = machine->initrd_filename;

    arm_load_kernel(mpu->cpu, &sx1_binfo);



    /* TODO: fix next line */

    //~ qemu_console_resize(ds, 640, 480);

}

