static int block_save_live(Monitor *mon, QEMUFile *f, int stage, void *opaque)

{

    int ret;



    DPRINTF("Enter save live stage %d submitted %d transferred %d\n",

            stage, block_mig_state.submitted, block_mig_state.transferred);



    if (stage < 0) {

        blk_mig_cleanup(mon);

        return 0;

    }



    if (block_mig_state.blk_enable != 1) {

        /* no need to migrate storage */

        qemu_put_be64(f, BLK_MIG_FLAG_EOS);

        return 1;

    }



    if (stage == 1) {

        init_blk_migration(mon, f);



        /* start track dirty blocks */

        set_dirty_tracking(1);

    }



    flush_blks(f);



    ret = qemu_file_get_error(f);

    if (ret) {

        blk_mig_cleanup(mon);

        return ret;

    }



    blk_mig_reset_dirty_cursor();



    if (stage == 2) {

        /* control the rate of transfer */

        while ((block_mig_state.submitted +

                block_mig_state.read_done) * BLOCK_SIZE <

               qemu_file_get_rate_limit(f)) {

            if (block_mig_state.bulk_completed == 0) {

                /* first finish the bulk phase */

                if (blk_mig_save_bulked_block(mon, f) == 0) {

                    /* finished saving bulk on all devices */

                    block_mig_state.bulk_completed = 1;

                }

            } else {

                if (blk_mig_save_dirty_block(mon, f, 1) == 0) {

                    /* no more dirty blocks */

                    break;

                }

            }

        }



        flush_blks(f);



        ret = qemu_file_get_error(f);

        if (ret) {

            blk_mig_cleanup(mon);

            return ret;

        }

    }



    if (stage == 3) {

        /* we know for sure that save bulk is completed and

           all async read completed */

        assert(block_mig_state.submitted == 0);



        while (blk_mig_save_dirty_block(mon, f, 0) != 0);

        blk_mig_cleanup(mon);



        /* report completion */

        qemu_put_be64(f, (100 << BDRV_SECTOR_BITS) | BLK_MIG_FLAG_PROGRESS);



        ret = qemu_file_get_error(f);

        if (ret) {

            return ret;

        }



        monitor_printf(mon, "Block migration completed\n");

    }



    qemu_put_be64(f, BLK_MIG_FLAG_EOS);



    return ((stage == 2) && is_stage2_completed());

}

int qemu_config_parse(FILE *fp, QemuOptsList **lists, const char *fname)

{

    char line[1024], group[64], id[64], arg[64], value[1024];

    Location loc;

    QemuOptsList *list = NULL;

    Error *local_err = NULL;

    QemuOpts *opts = NULL;

    int res = -1, lno = 0;



    loc_push_none(&loc);

    while (fgets(line, sizeof(line), fp) != NULL) {

        loc_set_file(fname, ++lno);

        if (line[0] == '\n') {

            /* skip empty lines */

            continue;

        }

        if (line[0] == '#') {

            /* comment */

            continue;

        }

        if (sscanf(line, "[%63s \"%63[^\"]\"]", group, id) == 2) {

            /* group with id */

            list = find_list(lists, group, &local_err);

            if (local_err) {

                error_report_err(local_err);

                goto out;

            }

            opts = qemu_opts_create(list, id, 1, NULL);

            continue;

        }

        if (sscanf(line, "[%63[^]]]", group) == 1) {

            /* group without id */

            list = find_list(lists, group, &local_err);

            if (local_err) {

                error_report_err(local_err);

                goto out;

            }

            opts = qemu_opts_create(list, NULL, 0, &error_abort);

            continue;

        }

        value[0] = '\0';

        if (sscanf(line, " %63s = \"%1023[^\"]\"", arg, value) == 2 ||

            sscanf(line, " %63s = \"\"", arg) == 1) {

            /* arg = value */

            if (opts == NULL) {

                error_report("no group defined");

                goto out;

            }

            qemu_opt_set(opts, arg, value, &local_err);

            if (local_err) {

                error_report_err(local_err);

                goto out;

            }

            continue;

        }

        error_report("parse error");

        goto out;

    }

    if (ferror(fp)) {

        error_report("error reading file");

        goto out;

    }

    res = 0;

out:

    loc_pop(&loc);

    return res;

}

static void qmp_input_check_struct(Visitor *v, Error **errp)

{

    QmpInputVisitor *qiv = to_qiv(v);

    StackObject *tos = &qiv->stack[qiv->nb_stack - 1];



    assert(qiv->nb_stack > 0);



    if (qiv->strict) {

        GHashTable *const top_ht = tos->h;

        if (top_ht) {

            GHashTableIter iter;

            const char *key;



            g_hash_table_iter_init(&iter, top_ht);

            if (g_hash_table_iter_next(&iter, (void **)&key, NULL)) {

                error_setg(errp, QERR_QMP_EXTRA_MEMBER, key);

            }

        }

    }

}

e1000e_intrmgr_delay_tx_causes(E1000ECore *core, uint32_t *causes)

{

    static const uint32_t delayable_causes = E1000_ICR_TXQ0 |

                                             E1000_ICR_TXQ1 |

                                             E1000_ICR_TXQE |

                                             E1000_ICR_TXDW;



    if (msix_enabled(core->owner)) {

        return false;

    }



    /* Clean up all causes that may be delayed */

    core->delayed_causes |= *causes & delayable_causes;

    *causes &= ~delayable_causes;



    /* If there are causes that cannot be delayed */

    if (causes != 0) {

        return false;

    }



    /* All causes delayed */

    e1000e_intrmgr_rearm_timer(&core->tidv);



    if (!core->tadv.running && (core->mac[TADV] != 0)) {

        e1000e_intrmgr_rearm_timer(&core->tadv);

    }



    return true;

}

static int qcow2_make_empty(BlockDriverState *bs)

{

    BDRVQcow2State *s = bs->opaque;

    uint64_t start_sector;

    int sector_step = INT_MAX / BDRV_SECTOR_SIZE;

    int l1_clusters, ret = 0;



    l1_clusters = DIV_ROUND_UP(s->l1_size, s->cluster_size / sizeof(uint64_t));



    if (s->qcow_version >= 3 && !s->snapshots &&

        3 + l1_clusters <= s->refcount_block_size) {

        /* The following function only works for qcow2 v3 images (it requires

         * the dirty flag) and only as long as there are no snapshots (because

         * it completely empties the image). Furthermore, the L1 table and three

         * additional clusters (image header, refcount table, one refcount

         * block) have to fit inside one refcount block. */

        return make_completely_empty(bs);

    }



    /* This fallback code simply discards every active cluster; this is slow,

     * but works in all cases */

    for (start_sector = 0; start_sector < bs->total_sectors;

         start_sector += sector_step)

    {

        /* As this function is generally used after committing an external

         * snapshot, QCOW2_DISCARD_SNAPSHOT seems appropriate. Also, the

         * default action for this kind of discard is to pass the discard,

         * which will ideally result in an actually smaller image file, as

         * is probably desired. */

        ret = qcow2_discard_clusters(bs, start_sector * BDRV_SECTOR_SIZE,

                                     MIN(sector_step,

                                         bs->total_sectors - start_sector),

                                     QCOW2_DISCARD_SNAPSHOT, true);

        if (ret < 0) {

            break;

        }

    }



    return ret;

}

static void s390_cpu_full_reset(CPUState *s)

{

    S390CPU *cpu = S390_CPU(s);

    S390CPUClass *scc = S390_CPU_GET_CLASS(cpu);

    CPUS390XState *env = &cpu->env;

    int i;



    scc->parent_reset(s);

    cpu->env.sigp_order = 0;

    s390_cpu_set_state(CPU_STATE_STOPPED, cpu);



    memset(env, 0, offsetof(CPUS390XState, end_reset_fields));



    /* architectured initial values for CR 0 and 14 */

    env->cregs[0] = CR0_RESET;

    env->cregs[14] = CR14_RESET;



    /* architectured initial value for Breaking-Event-Address register */

    env->gbea = 1;



    env->pfault_token = -1UL;

    env->ext_index = -1;

    for (i = 0; i < ARRAY_SIZE(env->io_index); i++) {

        env->io_index[i] = -1;

    }

    env->mchk_index = -1;



    /* tininess for underflow is detected before rounding */

    set_float_detect_tininess(float_tininess_before_rounding,

                              &env->fpu_status);



    /* Reset state inside the kernel that we cannot access yet from QEMU. */

    if (kvm_enabled()) {

        kvm_s390_reset_vcpu(cpu);

    }

}

static bool ufd_version_check(int ufd)

{

    struct uffdio_api api_struct;

    uint64_t ioctl_mask;



    api_struct.api = UFFD_API;

    api_struct.features = 0;

    if (ioctl(ufd, UFFDIO_API, &api_struct)) {

        error_report("postcopy_ram_supported_by_host: UFFDIO_API failed: %s",

                     strerror(errno));

        return false;

    }



    ioctl_mask = (__u64)1 << _UFFDIO_REGISTER |

                 (__u64)1 << _UFFDIO_UNREGISTER;

    if ((api_struct.ioctls & ioctl_mask) != ioctl_mask) {

        error_report("Missing userfault features: %" PRIx64,

                     (uint64_t)(~api_struct.ioctls & ioctl_mask));

        return false;

    }



    if (getpagesize() != ram_pagesize_summary()) {

        bool have_hp = false;

        /* We've got a huge page */

#ifdef UFFD_FEATURE_MISSING_HUGETLBFS

        have_hp = api_struct.features & UFFD_FEATURE_MISSING_HUGETLBFS;

#endif

        if (!have_hp) {

            error_report("Userfault on this host does not support huge pages");

            return false;

        }

    }

    return true;

}

