static void invalidate_tlb (int idx, int use_extra)

{

    tlb_t *tlb;

    target_ulong addr;

    uint8_t ASID;



    ASID = env->CP0_EntryHi & 0xFF;



    tlb = &env->tlb[idx];

    /* The qemu TLB is flushed then the ASID changes, so no need to

       flush these entries again.  */

    if (tlb->G == 0 && tlb->ASID != ASID) {

        return;

    }



    if (use_extra && env->tlb_in_use < MIPS_TLB_MAX) {

        /* For tlbwr, we can shadow the discarded entry into

	   a new (fake) TLB entry, as long as the guest can not

	   tell that it's there.  */

        env->tlb[env->tlb_in_use] = *tlb;

        env->tlb_in_use++;

        return;

    }



    if (tlb->V0) {

        tb_invalidate_page_range(tlb->PFN[0], tlb->end - tlb->VPN);

        addr = tlb->VPN;

        while (addr < tlb->end) {

            tlb_flush_page (env, addr);

            addr += TARGET_PAGE_SIZE;

        }

    }

    if (tlb->V1) {

        tb_invalidate_page_range(tlb->PFN[1], tlb->end2 - tlb->end);

        addr = tlb->end;

        while (addr < tlb->end2) {

            tlb_flush_page (env, addr);

            addr += TARGET_PAGE_SIZE;

        }

    }

}

static int parse_uri(const char *filename, QDict *options, Error **errp)

{

    URI *uri = NULL;

    QueryParams *qp = NULL;

    int i;



    uri = uri_parse(filename);

    if (!uri) {

        return -EINVAL;

    }



    if (strcmp(uri->scheme, "ssh") != 0) {

        error_setg(errp, "URI scheme must be 'ssh'");

        goto err;

    }



    if (!uri->server || strcmp(uri->server, "") == 0) {

        error_setg(errp, "missing hostname in URI");

        goto err;

    }



    if (!uri->path || strcmp(uri->path, "") == 0) {

        error_setg(errp, "missing remote path in URI");

        goto err;

    }



    qp = query_params_parse(uri->query);

    if (!qp) {

        error_setg(errp, "could not parse query parameters");

        goto err;

    }



    if(uri->user && strcmp(uri->user, "") != 0) {

        qdict_put(options, "user", qstring_from_str(uri->user));

    }



    qdict_put(options, "host", qstring_from_str(uri->server));



    if (uri->port) {

        qdict_put(options, "port", qint_from_int(uri->port));

    }



    qdict_put(options, "path", qstring_from_str(uri->path));



    /* Pick out any query parameters that we understand, and ignore

     * the rest.

     */

    for (i = 0; i < qp->n; ++i) {

        if (strcmp(qp->p[i].name, "host_key_check") == 0) {

            qdict_put(options, "host_key_check",

                      qstring_from_str(qp->p[i].value));

        }

    }



    query_params_free(qp);

    uri_free(uri);

    return 0;



 err:

    if (qp) {

      query_params_free(qp);

    }

    if (uri) {

      uri_free(uri);

    }

    return -EINVAL;

}

