int net_init_dump(const NetClientOptions *opts, const char *name,

                  NetClientState *peer, Error **errp)

{

    int len, rc;

    const char *file;

    char def_file[128];

    const NetdevDumpOptions *dump;

    NetClientState *nc;

    DumpNetClient *dnc;



    assert(opts->type == NET_CLIENT_OPTIONS_KIND_DUMP);

    dump = opts->u.dump;



    assert(peer);



    if (dump->has_file) {

        file = dump->file;

    } else {

        int id;

        int ret;



        ret = net_hub_id_for_client(peer, &id);

        assert(ret == 0); /* peer must be on a hub */



        snprintf(def_file, sizeof(def_file), "qemu-vlan%d.pcap", id);

        file = def_file;

    }



    if (dump->has_len) {

        if (dump->len > INT_MAX) {

            error_setg(errp, "invalid length: %"PRIu64, dump->len);

            return -1;

        }

        len = dump->len;

    } else {

        len = 65536;

    }



    nc = qemu_new_net_client(&net_dump_info, peer, "dump", name);

    snprintf(nc->info_str, sizeof(nc->info_str),

             "dump to %s (len=%d)", file, len);



    dnc = DO_UPCAST(DumpNetClient, nc, nc);

    rc = net_dump_state_init(&dnc->ds, file, len, errp);

    if (rc) {

        qemu_del_net_client(nc);

    }

    return rc;

}

static int handle_secondary_tcp_pkt(NetFilterState *nf,

                                    Connection *conn,

                                    Packet *pkt)

{

    struct tcphdr *tcp_pkt;



    tcp_pkt = (struct tcphdr *)pkt->transport_header;



    if (trace_event_get_state(TRACE_COLO_FILTER_REWRITER_DEBUG)) {

        trace_colo_filter_rewriter_pkt_info(__func__,

                    inet_ntoa(pkt->ip->ip_src), inet_ntoa(pkt->ip->ip_dst),

                    ntohl(tcp_pkt->th_seq), ntohl(tcp_pkt->th_ack),

                    tcp_pkt->th_flags);

        trace_colo_filter_rewriter_conn_offset(conn->offset);

    }



    if (((tcp_pkt->th_flags & (TH_ACK | TH_SYN)) == (TH_ACK | TH_SYN))) {

        /*

         * save offset = secondary_seq and then

         * in handle_primary_tcp_pkt make offset

         * = secondary_seq - primary_seq

         */

        conn->offset = ntohl(tcp_pkt->th_seq);

    }



    if ((tcp_pkt->th_flags & (TH_ACK | TH_SYN)) == TH_ACK) {

        /* handle packets to the primary from the secondary*/

        tcp_pkt->th_seq = htonl(ntohl(tcp_pkt->th_seq) - conn->offset);



        net_checksum_calculate((uint8_t *)pkt->data, pkt->size);

    }



    return 0;

}

static void nvdimm_dsm_reserved_root(AcpiNVDIMMState *state, NvdimmDsmIn *in,

                                     hwaddr dsm_mem_addr)

{

    switch (in->function) {

    case 0x0:

        nvdimm_dsm_function0(0x1 | 1 << 1 /* Read FIT */, dsm_mem_addr);

        return;

    case 0x1 /* Read FIT */:

        nvdimm_dsm_func_read_fit(state, in, dsm_mem_addr);

        return;

    }



    nvdimm_dsm_no_payload(NVDIMM_DSM_RET_STATUS_UNSUPPORT, dsm_mem_addr);

}

static void omap_prcm_dpll_update(struct omap_prcm_s *s)

{

    omap_clk dpll = omap_findclk(s->mpu, "dpll");

    omap_clk dpll_x2 = omap_findclk(s->mpu, "dpll");

    omap_clk core = omap_findclk(s->mpu, "core_clk");

    int mode = (s->clken[9] >> 0) & 3;

    int mult, div;



    mult = (s->clksel[5] >> 12) & 0x3ff;

    div = (s->clksel[5] >> 8) & 0xf;

    if (mult == 0 || mult == 1)

        mode = 1;	/* Bypass */



    s->dpll_lock = 0;

    switch (mode) {

    case 0:

        fprintf(stderr, "%s: bad EN_DPLL\n", __FUNCTION__);

        break;

    case 1:	/* Low-power bypass mode (Default) */

    case 2:	/* Fast-relock bypass mode */

        omap_clk_setrate(dpll, 1, 1);

        omap_clk_setrate(dpll_x2, 1, 1);

        break;

    case 3:	/* Lock mode */

        s->dpll_lock = 1; /* After 20 FINT cycles (ref_clk / (div + 1)).  */



        omap_clk_setrate(dpll, div + 1, mult);

        omap_clk_setrate(dpll_x2, div + 1, mult * 2);

        break;

    }



    switch ((s->clksel[6] >> 0) & 3) {

    case 0:

        omap_clk_reparent(core, omap_findclk(s->mpu, "clk32-kHz"));

        break;

    case 1:

        omap_clk_reparent(core, dpll);

        break;

    case 2:

        /* Default */

        omap_clk_reparent(core, dpll_x2);

        break;

    case 3:

        fprintf(stderr, "%s: bad CORE_CLK_SRC\n", __FUNCTION__);

        break;

    }

}

void HELPER(dc_zva)(CPUARMState *env, uint64_t vaddr_in)

{

    /* Implement DC ZVA, which zeroes a fixed-length block of memory.

     * Note that we do not implement the (architecturally mandated)

     * alignment fault for attempts to use this on Device memory

     * (which matches the usual QEMU behaviour of not implementing either

     * alignment faults or any memory attribute handling).

     */



    ARMCPU *cpu = arm_env_get_cpu(env);

    uint64_t blocklen = 4 << cpu->dcz_blocksize;

    uint64_t vaddr = vaddr_in & ~(blocklen - 1);



#ifndef CONFIG_USER_ONLY

    {

        /* Slightly awkwardly, QEMU's TARGET_PAGE_SIZE may be less than

         * the block size so we might have to do more than one TLB lookup.

         * We know that in fact for any v8 CPU the page size is at least 4K

         * and the block size must be 2K or less, but TARGET_PAGE_SIZE is only

         * 1K as an artefact of legacy v5 subpage support being present in the

         * same QEMU executable.

         */

        int maxidx = DIV_ROUND_UP(blocklen, TARGET_PAGE_SIZE);

        void *hostaddr[maxidx];

        int try, i;

        unsigned mmu_idx = cpu_mmu_index(env, false);

        TCGMemOpIdx oi = make_memop_idx(MO_UB, mmu_idx);



        for (try = 0; try < 2; try++) {



            for (i = 0; i < maxidx; i++) {

                hostaddr[i] = tlb_vaddr_to_host(env,

                                                vaddr + TARGET_PAGE_SIZE * i,

                                                1, mmu_idx);

                if (!hostaddr[i]) {

                    break;

                }

            }

            if (i == maxidx) {

                /* If it's all in the TLB it's fair game for just writing to;

                 * we know we don't need to update dirty status, etc.

                 */

                for (i = 0; i < maxidx - 1; i++) {

                    memset(hostaddr[i], 0, TARGET_PAGE_SIZE);

                }

                memset(hostaddr[i], 0, blocklen - (i * TARGET_PAGE_SIZE));

                return;

            }

            /* OK, try a store and see if we can populate the tlb. This

             * might cause an exception if the memory isn't writable,

             * in which case we will longjmp out of here. We must for

             * this purpose use the actual register value passed to us

             * so that we get the fault address right.

             */

            helper_ret_stb_mmu(env, vaddr_in, 0, oi, GETRA());

            /* Now we can populate the other TLB entries, if any */

            for (i = 0; i < maxidx; i++) {

                uint64_t va = vaddr + TARGET_PAGE_SIZE * i;

                if (va != (vaddr_in & TARGET_PAGE_MASK)) {

                    helper_ret_stb_mmu(env, va, 0, oi, GETRA());

                }

            }

        }



        /* Slow path (probably attempt to do this to an I/O device or

         * similar, or clearing of a block of code we have translations

         * cached for). Just do a series of byte writes as the architecture

         * demands. It's not worth trying to use a cpu_physical_memory_map(),

         * memset(), unmap() sequence here because:

         *  + we'd need to account for the blocksize being larger than a page

         *  + the direct-RAM access case is almost always going to be dealt

         *    with in the fastpath code above, so there's no speed benefit

         *  + we would have to deal with the map returning NULL because the

         *    bounce buffer was in use

         */

        for (i = 0; i < blocklen; i++) {

            helper_ret_stb_mmu(env, vaddr + i, 0, oi, GETRA());

        }

    }

#else

    memset(g2h(vaddr), 0, blocklen);

#endif

}

static void slirp_bootp_load(QEMUFile *f, Slirp *slirp)

{

    int i;



    for (i = 0; i < NB_BOOTP_CLIENTS; i++) {

        slirp->bootp_clients[i].allocated = qemu_get_be16(f);

        qemu_get_buffer(f, slirp->bootp_clients[i].macaddr, 6);

    }

}

static int scsi_handle_rw_error(SCSIDiskReq *r, int error)

{

    bool is_read = (r->req.cmd.xfer == SCSI_XFER_FROM_DEV);

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);

    BlockErrorAction action = bdrv_get_error_action(s->qdev.conf.bs, is_read, error);



    if (action == BLOCK_ERROR_ACTION_REPORT) {

        switch (error) {

        case ENOMEDIUM:

            scsi_check_condition(r, SENSE_CODE(NO_MEDIUM));

            break;

        case ENOMEM:

            scsi_check_condition(r, SENSE_CODE(TARGET_FAILURE));

            break;

        case EINVAL:

            scsi_check_condition(r, SENSE_CODE(INVALID_FIELD));

            break;

        case ENOSPC:

            scsi_check_condition(r, SENSE_CODE(SPACE_ALLOC_FAILED));

            break;

        default:

            scsi_check_condition(r, SENSE_CODE(IO_ERROR));

            break;

        }

    }

    bdrv_error_action(s->qdev.conf.bs, action, is_read, error);

    if (action == BLOCK_ERROR_ACTION_STOP) {

        scsi_req_retry(&r->req);

    }

    return action != BLOCK_ERROR_ACTION_IGNORE;

}

void migrate_fd_connect(MigrationState *s)

{

    s->state = MIG_STATE_ACTIVE;

    trace_migrate_set_state(MIG_STATE_ACTIVE);



    s->bytes_xfer = 0;

    /* This is a best 1st approximation. ns to ms */

    s->expected_downtime = max_downtime/1000000;



    s->cleanup_bh = qemu_bh_new(migrate_fd_cleanup, s);

    s->file = qemu_fopen_ops(s, &migration_file_ops);



    qemu_file_set_rate_limit(s->file,

                             s->bandwidth_limit / XFER_LIMIT_RATIO);



    qemu_thread_create(&s->thread, migration_thread, s,

                       QEMU_THREAD_JOINABLE);

    notifier_list_notify(&migration_state_notifiers, s);

}

void *iommu_dma_memory_map(DMAContext *dma, dma_addr_t addr, dma_addr_t *len,

                           DMADirection dir)

{

    int err;

    target_phys_addr_t paddr, plen;

    void *buf;



    if (dma->map) {

        return dma->map(dma, addr, len, dir);

    }



    plen = *len;

    err = dma->translate(dma, addr, &paddr, &plen, dir);

    if (err) {

        return NULL;

    }



    /*

     * If this is true, the virtual region is contiguous,

     * but the translated physical region isn't. We just

     * clamp *len, much like address_space_map() does.

     */

    if (plen < *len) {

        *len = plen;

    }



    buf = address_space_map(dma->as, paddr, &plen, dir == DMA_DIRECTION_FROM_DEVICE);

    *len = plen;



    return buf;

}

static void lx_init(const LxBoardDesc *board, MachineState *machine)

{

#ifdef TARGET_WORDS_BIGENDIAN

    int be = 1;

#else

    int be = 0;

#endif

    MemoryRegion *system_memory = get_system_memory();

    XtensaCPU *cpu = NULL;

    CPUXtensaState *env = NULL;

    MemoryRegion *ram, *rom, *system_io;

    DriveInfo *dinfo;

    pflash_t *flash = NULL;

    QemuOpts *machine_opts = qemu_get_machine_opts();

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = qemu_opt_get(machine_opts, "kernel");

    const char *kernel_cmdline = qemu_opt_get(machine_opts, "append");

    const char *dtb_filename = qemu_opt_get(machine_opts, "dtb");

    const char *initrd_filename = qemu_opt_get(machine_opts, "initrd");

    int n;



    if (!cpu_model) {

        cpu_model = XTENSA_DEFAULT_CPU_MODEL;

    }



    for (n = 0; n < smp_cpus; n++) {

        cpu = cpu_xtensa_init(cpu_model);

        if (cpu == NULL) {

            error_report("unable to find CPU definition '%s'\n",

                         cpu_model);

            exit(EXIT_FAILURE);

        }

        env = &cpu->env;



        env->sregs[PRID] = n;

        qemu_register_reset(lx60_reset, cpu);

        /* Need MMU initialized prior to ELF loading,

         * so that ELF gets loaded into virtual addresses

         */

        cpu_reset(CPU(cpu));

    }



    ram = g_malloc(sizeof(*ram));

    memory_region_init_ram(ram, NULL, "lx60.dram", machine->ram_size,

                           &error_abort);

    vmstate_register_ram_global(ram);

    memory_region_add_subregion(system_memory, 0, ram);



    system_io = g_malloc(sizeof(*system_io));

    memory_region_init(system_io, NULL, "lx60.io", 224 * 1024 * 1024);

    memory_region_add_subregion(system_memory, 0xf0000000, system_io);

    lx60_fpga_init(system_io, 0x0d020000);

    if (nd_table[0].used) {

        lx60_net_init(system_io, 0x0d030000, 0x0d030400, 0x0d800000,

                xtensa_get_extint(env, 1), nd_table);

    }



    if (!serial_hds[0]) {

        serial_hds[0] = qemu_chr_new("serial0", "null", NULL);

    }



    serial_mm_init(system_io, 0x0d050020, 2, xtensa_get_extint(env, 0),

            115200, serial_hds[0], DEVICE_NATIVE_ENDIAN);



    dinfo = drive_get(IF_PFLASH, 0, 0);

    if (dinfo) {

        flash = pflash_cfi01_register(board->flash_base,

                NULL, "lx60.io.flash", board->flash_size,

                blk_bs(blk_by_legacy_dinfo(dinfo)),

                board->flash_sector_size,

                board->flash_size / board->flash_sector_size,

                4, 0x0000, 0x0000, 0x0000, 0x0000, be);

        if (flash == NULL) {

            error_report("unable to mount pflash\n");

            exit(EXIT_FAILURE);

        }

    }



    /* Use presence of kernel file name as 'boot from SRAM' switch. */

    if (kernel_filename) {

        uint32_t entry_point = env->pc;

        size_t bp_size = 3 * get_tag_size(0); /* first/last and memory tags */

        uint32_t tagptr = 0xfe000000 + board->sram_size;

        uint32_t cur_tagptr;

        BpMemInfo memory_location = {

            .type = tswap32(MEMORY_TYPE_CONVENTIONAL),

            .start = tswap32(0),

            .end = tswap32(machine->ram_size),

        };

        uint32_t lowmem_end = machine->ram_size < 0x08000000 ?

            machine->ram_size : 0x08000000;

        uint32_t cur_lowmem = QEMU_ALIGN_UP(lowmem_end / 2, 4096);



        rom = g_malloc(sizeof(*rom));

        memory_region_init_ram(rom, NULL, "lx60.sram", board->sram_size,

                               &error_abort);

        vmstate_register_ram_global(rom);

        memory_region_add_subregion(system_memory, 0xfe000000, rom);



        if (kernel_cmdline) {

            bp_size += get_tag_size(strlen(kernel_cmdline) + 1);

        }

        if (dtb_filename) {

            bp_size += get_tag_size(sizeof(uint32_t));

        }

        if (initrd_filename) {

            bp_size += get_tag_size(sizeof(BpMemInfo));

        }



        /* Put kernel bootparameters to the end of that SRAM */

        tagptr = (tagptr - bp_size) & ~0xff;

        cur_tagptr = put_tag(tagptr, BP_TAG_FIRST, 0, NULL);

        cur_tagptr = put_tag(cur_tagptr, BP_TAG_MEMORY,

                             sizeof(memory_location), &memory_location);



        if (kernel_cmdline) {

            cur_tagptr = put_tag(cur_tagptr, BP_TAG_COMMAND_LINE,

                                 strlen(kernel_cmdline) + 1, kernel_cmdline);

        }

        if (dtb_filename) {

            int fdt_size;

            void *fdt = load_device_tree(dtb_filename, &fdt_size);

            uint32_t dtb_addr = tswap32(cur_lowmem);



            if (!fdt) {

                error_report("could not load DTB '%s'\n", dtb_filename);

                exit(EXIT_FAILURE);

            }



            cpu_physical_memory_write(cur_lowmem, fdt, fdt_size);

            cur_tagptr = put_tag(cur_tagptr, BP_TAG_FDT,

                                 sizeof(dtb_addr), &dtb_addr);

            cur_lowmem = QEMU_ALIGN_UP(cur_lowmem + fdt_size, 4096);

        }

        if (initrd_filename) {

            BpMemInfo initrd_location = { 0 };

            int initrd_size = load_ramdisk(initrd_filename, cur_lowmem,

                                           lowmem_end - cur_lowmem);



            if (initrd_size < 0) {

                initrd_size = load_image_targphys(initrd_filename,

                                                  cur_lowmem,

                                                  lowmem_end - cur_lowmem);

            }

            if (initrd_size < 0) {

                error_report("could not load initrd '%s'\n", initrd_filename);

                exit(EXIT_FAILURE);

            }

            initrd_location.start = tswap32(cur_lowmem);

            initrd_location.end = tswap32(cur_lowmem + initrd_size);

            cur_tagptr = put_tag(cur_tagptr, BP_TAG_INITRD,

                                 sizeof(initrd_location), &initrd_location);

            cur_lowmem = QEMU_ALIGN_UP(cur_lowmem + initrd_size, 4096);

        }

        cur_tagptr = put_tag(cur_tagptr, BP_TAG_LAST, 0, NULL);

        env->regs[2] = tagptr;



        uint64_t elf_entry;

        uint64_t elf_lowaddr;

        int success = load_elf(kernel_filename, translate_phys_addr, cpu,

                &elf_entry, &elf_lowaddr, NULL, be, ELF_MACHINE, 0);

        if (success > 0) {

            entry_point = elf_entry;

        } else {

            hwaddr ep;

            int is_linux;

            success = load_uimage(kernel_filename, &ep, NULL, &is_linux);

            if (success > 0 && is_linux) {

                entry_point = ep;

            } else {

                error_report("could not load kernel '%s'\n",

                             kernel_filename);

                exit(EXIT_FAILURE);

            }

        }

        if (entry_point != env->pc) {

            static const uint8_t jx_a0[] = {

#ifdef TARGET_WORDS_BIGENDIAN

                0x0a, 0, 0,

#else

                0xa0, 0, 0,

#endif

            };

            env->regs[0] = entry_point;

            cpu_physical_memory_write(env->pc, jx_a0, sizeof(jx_a0));

        }

    } else {

        if (flash) {

            MemoryRegion *flash_mr = pflash_cfi01_get_memory(flash);

            MemoryRegion *flash_io = g_malloc(sizeof(*flash_io));



            memory_region_init_alias(flash_io, NULL, "lx60.flash",

                    flash_mr, board->flash_boot_base,

                    board->flash_size - board->flash_boot_base < 0x02000000 ?

                    board->flash_size - board->flash_boot_base : 0x02000000);

            memory_region_add_subregion(system_memory, 0xfe000000,

                    flash_io);

        }

    }

}

void kvm_arch_reset_vcpu(X86CPU *cpu)

{

    CPUX86State *env = &cpu->env;



    env->exception_injected = -1;

    env->interrupt_injected = -1;

    env->xcr0 = 1;

    if (kvm_irqchip_in_kernel()) {

        env->mp_state = cpu_is_bsp(cpu) ? KVM_MP_STATE_RUNNABLE :

                                          KVM_MP_STATE_UNINITIALIZED;

    } else {

        env->mp_state = KVM_MP_STATE_RUNNABLE;

    }



    if (cpu->hyperv_synic) {

        int i;

        for (i = 0; i < ARRAY_SIZE(env->msr_hv_synic_sint); i++) {

            env->msr_hv_synic_sint[i] = HV_SINT_MASKED;

        }

    }

}

