void muls64(int64_t *phigh, int64_t *plow, int64_t a, int64_t b)

{

#if defined(__x86_64__)

    __asm__ ("imul %0\n\t"

             : "=d" (*phigh), "=a" (*plow)

             : "a" (a), "0" (b)

             );

#else

    int64_t ph;

    uint64_t pm1, pm2, pl;



    pl = (uint64_t)((uint32_t)a) * (uint64_t)((uint32_t)b);

    pm1 = (a >> 32) * (uint32_t)b;

    pm2 = (uint32_t)a * (b >> 32);

    ph = (a >> 32) * (b >> 32);



    ph += (int64_t)pm1 >> 32;

    pm1 = (uint64_t)((uint32_t)pm1) + pm2 + (pl >> 32);



    *phigh = ph + ((int64_t)pm1 >> 32);

    *plow = (pm1 << 32) + (uint32_t)pl;

#endif

}

static int32_t scsi_disk_emulate_command(SCSIRequest *req, uint8_t *buf)

{

    SCSIDiskReq *r = DO_UPCAST(SCSIDiskReq, req, req);

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, req->dev);

    uint64_t nb_sectors;

    uint8_t *outbuf;

    int buflen;



    switch (req->cmd.buf[0]) {

    case INQUIRY:

    case MODE_SENSE:

    case MODE_SENSE_10:

    case RESERVE:

    case RESERVE_10:

    case RELEASE:

    case RELEASE_10:

    case START_STOP:

    case ALLOW_MEDIUM_REMOVAL:

    case GET_CONFIGURATION:

    case GET_EVENT_STATUS_NOTIFICATION:

    case MECHANISM_STATUS:

    case REQUEST_SENSE:

        break;



    default:

        if (s->tray_open || !bdrv_is_inserted(s->qdev.conf.bs)) {

            scsi_check_condition(r, SENSE_CODE(NO_MEDIUM));

            return 0;

        }

        break;

    }



    /*

     * FIXME: we shouldn't return anything bigger than 4k, but the code

     * requires the buffer to be as big as req->cmd.xfer in several

     * places.  So, do not allow CDBs with a very large ALLOCATION

     * LENGTH.  The real fix would be to modify scsi_read_data and

     * dma_buf_read, so that they return data beyond the buflen

     * as all zeros.

     */

    if (req->cmd.xfer > 65536) {

        goto illegal_request;

    }

    r->buflen = MAX(4096, req->cmd.xfer);



    if (!r->iov.iov_base) {

        r->iov.iov_base = qemu_blockalign(s->qdev.conf.bs, r->buflen);

    }



    buflen = req->cmd.xfer;

    outbuf = r->iov.iov_base;

    memset(outbuf, 0, r->buflen);

    switch (req->cmd.buf[0]) {

    case TEST_UNIT_READY:

        assert(!s->tray_open && bdrv_is_inserted(s->qdev.conf.bs));

        break;

    case INQUIRY:

        buflen = scsi_disk_emulate_inquiry(req, outbuf);

        if (buflen < 0) {

            goto illegal_request;

        }

        break;

    case MODE_SENSE:

    case MODE_SENSE_10:

        buflen = scsi_disk_emulate_mode_sense(r, outbuf);

        if (buflen < 0) {

            goto illegal_request;

        }

        break;

    case READ_TOC:

        buflen = scsi_disk_emulate_read_toc(req, outbuf);

        if (buflen < 0) {

            goto illegal_request;

        }

        break;

    case RESERVE:

        if (req->cmd.buf[1] & 1) {

            goto illegal_request;

        }

        break;

    case RESERVE_10:

        if (req->cmd.buf[1] & 3) {

            goto illegal_request;

        }

        break;

    case RELEASE:

        if (req->cmd.buf[1] & 1) {

            goto illegal_request;

        }

        break;

    case RELEASE_10:

        if (req->cmd.buf[1] & 3) {

            goto illegal_request;

        }

        break;

    case START_STOP:

        if (scsi_disk_emulate_start_stop(r) < 0) {

            return 0;

        }

        break;

    case ALLOW_MEDIUM_REMOVAL:

        s->tray_locked = req->cmd.buf[4] & 1;

        bdrv_lock_medium(s->qdev.conf.bs, req->cmd.buf[4] & 1);

        break;

    case READ_CAPACITY_10:

        /* The normal LEN field for this command is zero.  */

        memset(outbuf, 0, 8);

        bdrv_get_geometry(s->qdev.conf.bs, &nb_sectors);

        if (!nb_sectors) {

            scsi_check_condition(r, SENSE_CODE(LUN_NOT_READY));

            return 0;

        }

        if ((req->cmd.buf[8] & 1) == 0 && req->cmd.lba) {

            goto illegal_request;

        }

        nb_sectors /= s->qdev.blocksize / 512;

        /* Returned value is the address of the last sector.  */

        nb_sectors--;

        /* Remember the new size for read/write sanity checking. */

        s->qdev.max_lba = nb_sectors;

        /* Clip to 2TB, instead of returning capacity modulo 2TB. */

        if (nb_sectors > UINT32_MAX) {

            nb_sectors = UINT32_MAX;

        }

        outbuf[0] = (nb_sectors >> 24) & 0xff;

        outbuf[1] = (nb_sectors >> 16) & 0xff;

        outbuf[2] = (nb_sectors >> 8) & 0xff;

        outbuf[3] = nb_sectors & 0xff;

        outbuf[4] = 0;

        outbuf[5] = 0;

        outbuf[6] = s->qdev.blocksize >> 8;

        outbuf[7] = 0;

        break;

    case REQUEST_SENSE:

        /* Just return "NO SENSE".  */

        buflen = scsi_build_sense(NULL, 0, outbuf, r->buflen,

                                  (req->cmd.buf[1] & 1) == 0);

        if (buflen < 0) {

            goto illegal_request;

        }

        break;

    case MECHANISM_STATUS:

        buflen = scsi_emulate_mechanism_status(s, outbuf);

        if (buflen < 0) {

            goto illegal_request;

        }

        break;

    case GET_CONFIGURATION:

        buflen = scsi_get_configuration(s, outbuf);

        if (buflen < 0) {

            goto illegal_request;

        }

        break;

    case GET_EVENT_STATUS_NOTIFICATION:

        buflen = scsi_get_event_status_notification(s, r, outbuf);

        if (buflen < 0) {

            goto illegal_request;

        }

        break;

    case READ_DISC_INFORMATION:

        buflen = scsi_read_disc_information(s, r, outbuf);

        if (buflen < 0) {

            goto illegal_request;

        }

        break;

    case READ_DVD_STRUCTURE:

        buflen = scsi_read_dvd_structure(s, r, outbuf);

        if (buflen < 0) {

            goto illegal_request;

        }

        break;

    case SERVICE_ACTION_IN_16:

        /* Service Action In subcommands. */

        if ((req->cmd.buf[1] & 31) == SAI_READ_CAPACITY_16) {

            DPRINTF("SAI READ CAPACITY(16)\n");

            memset(outbuf, 0, req->cmd.xfer);

            bdrv_get_geometry(s->qdev.conf.bs, &nb_sectors);

            if (!nb_sectors) {

                scsi_check_condition(r, SENSE_CODE(LUN_NOT_READY));

                return 0;

            }

            if ((req->cmd.buf[14] & 1) == 0 && req->cmd.lba) {

                goto illegal_request;

            }

            nb_sectors /= s->qdev.blocksize / 512;

            /* Returned value is the address of the last sector.  */

            nb_sectors--;

            /* Remember the new size for read/write sanity checking. */

            s->qdev.max_lba = nb_sectors;

            outbuf[0] = (nb_sectors >> 56) & 0xff;

            outbuf[1] = (nb_sectors >> 48) & 0xff;

            outbuf[2] = (nb_sectors >> 40) & 0xff;

            outbuf[3] = (nb_sectors >> 32) & 0xff;

            outbuf[4] = (nb_sectors >> 24) & 0xff;

            outbuf[5] = (nb_sectors >> 16) & 0xff;

            outbuf[6] = (nb_sectors >> 8) & 0xff;

            outbuf[7] = nb_sectors & 0xff;

            outbuf[8] = 0;

            outbuf[9] = 0;

            outbuf[10] = s->qdev.blocksize >> 8;

            outbuf[11] = 0;

            outbuf[12] = 0;

            outbuf[13] = get_physical_block_exp(&s->qdev.conf);



            /* set TPE bit if the format supports discard */

            if (s->qdev.conf.discard_granularity) {

                outbuf[14] = 0x80;

            }



            /* Protection, exponent and lowest lba field left blank. */

            break;

        }

        DPRINTF("Unsupported Service Action In\n");

        goto illegal_request;

    case SYNCHRONIZE_CACHE:

        /* The request is used as the AIO opaque value, so add a ref.  */

        scsi_req_ref(&r->req);

        bdrv_acct_start(s->qdev.conf.bs, &r->acct, 0, BDRV_ACCT_FLUSH);

        r->req.aiocb = bdrv_aio_flush(s->qdev.conf.bs, scsi_aio_complete, r);

        return 0;

    case SEEK_10:

        DPRINTF("Seek(10) (sector %" PRId64 ")\n", r->req.cmd.lba);

        if (r->req.cmd.lba > s->qdev.max_lba) {

            goto illegal_lba;

        }

        break;

    case MODE_SELECT:

        DPRINTF("Mode Select(6) (len %lu)\n", (long)r->req.cmd.xfer);

        break;

    case MODE_SELECT_10:

        DPRINTF("Mode Select(10) (len %lu)\n", (long)r->req.cmd.xfer);

        break;

    case UNMAP:

        DPRINTF("Unmap (len %lu)\n", (long)r->req.cmd.xfer);

        break;

    case WRITE_SAME_10:

    case WRITE_SAME_16:

        nb_sectors = scsi_data_cdb_length(r->req.cmd.buf);

        if (bdrv_is_read_only(s->qdev.conf.bs)) {

            scsi_check_condition(r, SENSE_CODE(WRITE_PROTECTED));

            return 0;

        }

        if (!check_lba_range(s, r->req.cmd.lba, nb_sectors)) {

            goto illegal_lba;

        }



        /*

         * We only support WRITE SAME with the unmap bit set for now.

         */

        if (!(req->cmd.buf[1] & 0x8)) {

            goto illegal_request;

        }



        /* The request is used as the AIO opaque value, so add a ref.  */

        scsi_req_ref(&r->req);

        r->req.aiocb = bdrv_aio_discard(s->qdev.conf.bs,

                                        r->req.cmd.lba * (s->qdev.blocksize / 512),

                                        nb_sectors * (s->qdev.blocksize / 512),

                                        scsi_aio_complete, r);

        return 0;

    default:

        DPRINTF("Unknown SCSI command (%2.2x)\n", buf[0]);

        scsi_check_condition(r, SENSE_CODE(INVALID_OPCODE));

        return 0;

    }

    assert(!r->req.aiocb);

    r->iov.iov_len = MIN(r->buflen, req->cmd.xfer);

    if (r->iov.iov_len == 0) {

        scsi_req_complete(&r->req, GOOD);

    }

    if (r->req.cmd.mode == SCSI_XFER_TO_DEV) {

        assert(r->iov.iov_len == req->cmd.xfer);

        return -r->iov.iov_len;

    } else {

        return r->iov.iov_len;

    }



illegal_request:

    if (r->req.status == -1) {

        scsi_check_condition(r, SENSE_CODE(INVALID_FIELD));

    }

    return 0;



illegal_lba:

    scsi_check_condition(r, SENSE_CODE(LBA_OUT_OF_RANGE));

    return 0;

}

static void mips_jazz_init(MachineState *machine,

                           enum jazz_model_e jazz_model)

{

    MemoryRegion *address_space = get_system_memory();

    const char *cpu_model = machine->cpu_model;

    char *filename;

    int bios_size, n;

    MIPSCPU *cpu;

    CPUClass *cc;

    CPUMIPSState *env;

    qemu_irq *i8259;

    rc4030_dma *dmas;

    MemoryRegion *rc4030_dma_mr;

    MemoryRegion *isa_mem = g_new(MemoryRegion, 1);

    MemoryRegion *isa_io = g_new(MemoryRegion, 1);

    MemoryRegion *rtc = g_new(MemoryRegion, 1);

    MemoryRegion *i8042 = g_new(MemoryRegion, 1);

    MemoryRegion *dma_dummy = g_new(MemoryRegion, 1);

    NICInfo *nd;

    DeviceState *dev, *rc4030;

    SysBusDevice *sysbus;

    ISABus *isa_bus;

    ISADevice *pit;

    DriveInfo *fds[MAX_FD];

    qemu_irq esp_reset, dma_enable;

    MemoryRegion *ram = g_new(MemoryRegion, 1);

    MemoryRegion *bios = g_new(MemoryRegion, 1);

    MemoryRegion *bios2 = g_new(MemoryRegion, 1);



    /* init CPUs */

    if (cpu_model == NULL) {

        cpu_model = "R4000";

    }

    cpu = cpu_mips_init(cpu_model);

    if (cpu == NULL) {

        fprintf(stderr, "Unable to find CPU definition\n");

        exit(1);

    }

    env = &cpu->env;

    qemu_register_reset(main_cpu_reset, cpu);



    /* Chipset returns 0 in invalid reads and do not raise data exceptions.

     * However, we can't simply add a global memory region to catch

     * everything, as memory core directly call unassigned_mem_read/write

     * on some invalid accesses, which call do_unassigned_access on the

     * CPU, which raise an exception.

     * Handle that case by hijacking the do_unassigned_access method on

     * the CPU, and do not raise exceptions for data access. */

    cc = CPU_GET_CLASS(cpu);

    real_do_unassigned_access = cc->do_unassigned_access;

    cc->do_unassigned_access = mips_jazz_do_unassigned_access;



    /* allocate RAM */

    memory_region_allocate_system_memory(ram, NULL, "mips_jazz.ram",

                                         machine->ram_size);

    memory_region_add_subregion(address_space, 0, ram);



    memory_region_init_ram(bios, NULL, "mips_jazz.bios", MAGNUM_BIOS_SIZE,

                           &error_abort);

    vmstate_register_ram_global(bios);

    memory_region_set_readonly(bios, true);

    memory_region_init_alias(bios2, NULL, "mips_jazz.bios", bios,

                             0, MAGNUM_BIOS_SIZE);

    memory_region_add_subregion(address_space, 0x1fc00000LL, bios);

    memory_region_add_subregion(address_space, 0xfff00000LL, bios2);



    /* load the BIOS image. */

    if (bios_name == NULL)

        bios_name = BIOS_FILENAME;

    filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);

    if (filename) {

        bios_size = load_image_targphys(filename, 0xfff00000LL,

                                        MAGNUM_BIOS_SIZE);

        g_free(filename);

    } else {

        bios_size = -1;

    }

    if ((bios_size < 0 || bios_size > MAGNUM_BIOS_SIZE) && !qtest_enabled()) {

        error_report("Could not load MIPS bios '%s'", bios_name);

        exit(1);

    }



    /* Init CPU internal devices */

    cpu_mips_irq_init_cpu(env);

    cpu_mips_clock_init(env);



    /* Chipset */

    rc4030 = rc4030_init(&dmas, &rc4030_dma_mr);

    sysbus = SYS_BUS_DEVICE(rc4030);

    sysbus_connect_irq(sysbus, 0, env->irq[6]);

    sysbus_connect_irq(sysbus, 1, env->irq[3]);

    memory_region_add_subregion(address_space, 0x80000000,

                                sysbus_mmio_get_region(sysbus, 0));

    memory_region_add_subregion(address_space, 0xf0000000,

                                sysbus_mmio_get_region(sysbus, 1));

    memory_region_init_io(dma_dummy, NULL, &dma_dummy_ops, NULL, "dummy_dma", 0x1000);

    memory_region_add_subregion(address_space, 0x8000d000, dma_dummy);



    /* ISA bus: IO space at 0x90000000, mem space at 0x91000000 */

    memory_region_init(isa_io, NULL, "isa-io", 0x00010000);

    memory_region_init(isa_mem, NULL, "isa-mem", 0x01000000);

    memory_region_add_subregion(address_space, 0x90000000, isa_io);

    memory_region_add_subregion(address_space, 0x91000000, isa_mem);

    isa_bus = isa_bus_new(NULL, isa_mem, isa_io);



    /* ISA devices */

    i8259 = i8259_init(isa_bus, env->irq[4]);

    isa_bus_irqs(isa_bus, i8259);

    DMA_init(0);

    pit = pit_init(isa_bus, 0x40, 0, NULL);

    pcspk_init(isa_bus, pit);



    /* Video card */

    switch (jazz_model) {

    case JAZZ_MAGNUM:

        dev = qdev_create(NULL, "sysbus-g364");

        qdev_init_nofail(dev);

        sysbus = SYS_BUS_DEVICE(dev);

        sysbus_mmio_map(sysbus, 0, 0x60080000);

        sysbus_mmio_map(sysbus, 1, 0x40000000);

        sysbus_connect_irq(sysbus, 0, qdev_get_gpio_in(rc4030, 3));

        {

            /* Simple ROM, so user doesn't have to provide one */

            MemoryRegion *rom_mr = g_new(MemoryRegion, 1);

            memory_region_init_ram(rom_mr, NULL, "g364fb.rom", 0x80000,

                                   &error_abort);

            vmstate_register_ram_global(rom_mr);

            memory_region_set_readonly(rom_mr, true);

            uint8_t *rom = memory_region_get_ram_ptr(rom_mr);

            memory_region_add_subregion(address_space, 0x60000000, rom_mr);

            rom[0] = 0x10; /* Mips G364 */

        }

        break;

    case JAZZ_PICA61:

        isa_vga_mm_init(0x40000000, 0x60000000, 0, get_system_memory());

        break;

    default:

        break;

    }



    /* Network controller */

    for (n = 0; n < nb_nics; n++) {

        nd = &nd_table[n];

        if (!nd->model)

            nd->model = g_strdup("dp83932");

        if (strcmp(nd->model, "dp83932") == 0) {

            qemu_check_nic_model(nd, "dp83932");



            dev = qdev_create(NULL, "dp8393x");

            qdev_set_nic_properties(dev, nd);

            qdev_prop_set_uint8(dev, "it_shift", 2);

            qdev_prop_set_ptr(dev, "dma_mr", rc4030_dma_mr);

            qdev_init_nofail(dev);

            sysbus = SYS_BUS_DEVICE(dev);

            sysbus_mmio_map(sysbus, 0, 0x80001000);

            sysbus_mmio_map(sysbus, 1, 0x8000b000);

            sysbus_connect_irq(sysbus, 0, qdev_get_gpio_in(rc4030, 4));

            break;

        } else if (is_help_option(nd->model)) {

            fprintf(stderr, "qemu: Supported NICs: dp83932\n");

            exit(1);

        } else {

            fprintf(stderr, "qemu: Unsupported NIC: %s\n", nd->model);

            exit(1);

        }

    }



    /* SCSI adapter */

    esp_init(0x80002000, 0,

             rc4030_dma_read, rc4030_dma_write, dmas[0],

             qdev_get_gpio_in(rc4030, 5), &esp_reset, &dma_enable);



    /* Floppy */

    if (drive_get_max_bus(IF_FLOPPY) >= MAX_FD) {

        fprintf(stderr, "qemu: too many floppy drives\n");

        exit(1);

    }

    for (n = 0; n < MAX_FD; n++) {

        fds[n] = drive_get(IF_FLOPPY, 0, n);

    }

    fdctrl_init_sysbus(qdev_get_gpio_in(rc4030, 1), 0, 0x80003000, fds);



    /* Real time clock */

    rtc_init(isa_bus, 1980, NULL);

    memory_region_init_io(rtc, NULL, &rtc_ops, NULL, "rtc", 0x1000);

    memory_region_add_subregion(address_space, 0x80004000, rtc);



    /* Keyboard (i8042) */

    i8042_mm_init(qdev_get_gpio_in(rc4030, 6), qdev_get_gpio_in(rc4030, 7),

                  i8042, 0x1000, 0x1);

    memory_region_add_subregion(address_space, 0x80005000, i8042);



    /* Serial ports */

    if (serial_hds[0]) {

        serial_mm_init(address_space, 0x80006000, 0,

                       qdev_get_gpio_in(rc4030, 8), 8000000/16,

                       serial_hds[0], DEVICE_NATIVE_ENDIAN);

    }

    if (serial_hds[1]) {

        serial_mm_init(address_space, 0x80007000, 0,

                       qdev_get_gpio_in(rc4030, 9), 8000000/16,

                       serial_hds[1], DEVICE_NATIVE_ENDIAN);

    }



    /* Parallel port */

    if (parallel_hds[0])

        parallel_mm_init(address_space, 0x80008000, 0,

                         qdev_get_gpio_in(rc4030, 0), parallel_hds[0]);



    /* FIXME: missing Jazz sound at 0x8000c000, rc4030[2] */



    /* NVRAM */

    dev = qdev_create(NULL, "ds1225y");

    qdev_init_nofail(dev);

    sysbus = SYS_BUS_DEVICE(dev);

    sysbus_mmio_map(sysbus, 0, 0x80009000);



    /* LED indicator */

    sysbus_create_simple("jazz-led", 0x8000f000, NULL);

}

int bdrv_truncate(BlockDriverState *bs, int64_t offset)

{

    BlockDriver *drv = bs->drv;

    int ret;

    if (!drv)

        return -ENOMEDIUM;

    if (!drv->bdrv_truncate)

        return -ENOTSUP;

    if (bs->read_only)

        return -EACCES;



    ret = drv->bdrv_truncate(bs, offset);

    if (ret == 0) {

        ret = refresh_total_sectors(bs, offset >> BDRV_SECTOR_BITS);

        bdrv_dirty_bitmap_truncate(bs);

        bdrv_parent_cb_resize(bs);


    }

    return ret;

}

static void gen_sub(DisasContext *dc, TCGv dest, TCGv srca, TCGv srcb)

{

    TCGv res = tcg_temp_new();

    TCGv sr_cy = tcg_temp_new();

    TCGv sr_ov = tcg_temp_new();



    tcg_gen_sub_tl(res, srca, srcb);

    tcg_gen_xor_tl(sr_cy, srca, srcb);

    tcg_gen_xor_tl(sr_ov, res, srcb);

    tcg_gen_and_tl(sr_ov, sr_ov, sr_cy);

    tcg_gen_setcond_tl(TCG_COND_LTU, sr_cy, srca, srcb);



    tcg_gen_mov_tl(dest, res);

    tcg_temp_free(res);



    tcg_gen_shri_tl(sr_ov, sr_ov, TARGET_LONG_BITS - 1);

    tcg_gen_deposit_tl(cpu_sr, cpu_sr, sr_cy, ctz32(SR_CY), 1);

    tcg_gen_deposit_tl(cpu_sr, cpu_sr, sr_ov, ctz32(SR_OV), 1);



    gen_ove_cyov(dc, sr_ov, sr_cy);

    tcg_temp_free(sr_ov);

    tcg_temp_free(sr_cy);

}

static void ecc_mem_writel(void *opaque, target_phys_addr_t addr, uint32_t val)

{

    ECCState *s = opaque;



    switch (addr & ECC_ADDR_MASK) {

    case ECC_MER:

        s->regs[0] = (s->regs[0] & (ECC_MER_VER | ECC_MER_IMPL)) |

                     (val & ~(ECC_MER_VER | ECC_MER_IMPL));

        DPRINTF("Write memory enable %08x\n", val);

        break;

    case ECC_MDR:

        s->regs[1] =  val & ECC_MDR_MASK;

        DPRINTF("Write memory delay %08x\n", val);

        break;

    case ECC_MFSR:

        s->regs[2] =  val;

        DPRINTF("Write memory fault status %08x\n", val);

        break;

    case ECC_VCR:

        s->regs[3] =  val;

        DPRINTF("Write slot configuration %08x\n", val);

        break;

    case ECC_DR:

        s->regs[6] =  val;

        DPRINTF("Write diagnosiic %08x\n", val);

        break;

    case ECC_ECR0:

        s->regs[7] =  val;

        DPRINTF("Write event count 1 %08x\n", val);

        break;

    case ECC_ECR1:

        s->regs[7] =  val;

        DPRINTF("Write event count 2 %08x\n", val);

        break;

    }

}

