static int tap_alloc(char *dev, size_t dev_size)

{

    int tap_fd, if_fd, ppa = -1;

    static int ip_fd = 0;

    char *ptr;



    static int arp_fd = 0;

    int ip_muxid, arp_muxid;

    struct strioctl  strioc_if, strioc_ppa;

    int link_type = I_PLINK;

    struct lifreq ifr;

    char actual_name[32] = "";



    memset(&ifr, 0x0, sizeof(ifr));



    if( *dev ){

       ptr = dev;

       while( *ptr && !qemu_isdigit((int)*ptr) ) ptr++;

       ppa = atoi(ptr);

    }



    /* Check if IP device was opened */

    if( ip_fd )

       close(ip_fd);



    TFR(ip_fd = open("/dev/udp", O_RDWR, 0));

    if (ip_fd < 0) {

       syslog(LOG_ERR, "Can't open /dev/ip (actually /dev/udp)");

       return -1;

    }



    TFR(tap_fd = open("/dev/tap", O_RDWR, 0));

    if (tap_fd < 0) {

       syslog(LOG_ERR, "Can't open /dev/tap");

       return -1;

    }



    /* Assign a new PPA and get its unit number. */

    strioc_ppa.ic_cmd = TUNNEWPPA;

    strioc_ppa.ic_timout = 0;

    strioc_ppa.ic_len = sizeof(ppa);

    strioc_ppa.ic_dp = (char *)&ppa;

    if ((ppa = ioctl (tap_fd, I_STR, &strioc_ppa)) < 0)

       syslog (LOG_ERR, "Can't assign new interface");



    TFR(if_fd = open("/dev/tap", O_RDWR, 0));

    if (if_fd < 0) {

       syslog(LOG_ERR, "Can't open /dev/tap (2)");

       return -1;

    }

    if(ioctl(if_fd, I_PUSH, "ip") < 0){

       syslog(LOG_ERR, "Can't push IP module");

       return -1;

    }



    if (ioctl(if_fd, SIOCGLIFFLAGS, &ifr) < 0)

	syslog(LOG_ERR, "Can't get flags\n");



    snprintf (actual_name, 32, "tap%d", ppa);

    pstrcpy(ifr.lifr_name, sizeof(ifr.lifr_name), actual_name);



    ifr.lifr_ppa = ppa;

    /* Assign ppa according to the unit number returned by tun device */



    if (ioctl (if_fd, SIOCSLIFNAME, &ifr) < 0)

        syslog (LOG_ERR, "Can't set PPA %d", ppa);

    if (ioctl(if_fd, SIOCGLIFFLAGS, &ifr) <0)

        syslog (LOG_ERR, "Can't get flags\n");

    /* Push arp module to if_fd */

    if (ioctl (if_fd, I_PUSH, "arp") < 0)

        syslog (LOG_ERR, "Can't push ARP module (2)");



    /* Push arp module to ip_fd */

    if (ioctl (ip_fd, I_POP, NULL) < 0)

        syslog (LOG_ERR, "I_POP failed\n");

    if (ioctl (ip_fd, I_PUSH, "arp") < 0)

        syslog (LOG_ERR, "Can't push ARP module (3)\n");

    /* Open arp_fd */

    TFR(arp_fd = open ("/dev/tap", O_RDWR, 0));

    if (arp_fd < 0)

       syslog (LOG_ERR, "Can't open %s\n", "/dev/tap");



    /* Set ifname to arp */

    strioc_if.ic_cmd = SIOCSLIFNAME;

    strioc_if.ic_timout = 0;

    strioc_if.ic_len = sizeof(ifr);

    strioc_if.ic_dp = (char *)&ifr;

    if (ioctl(arp_fd, I_STR, &strioc_if) < 0){

        syslog (LOG_ERR, "Can't set ifname to arp\n");

    }



    if((ip_muxid = ioctl(ip_fd, I_LINK, if_fd)) < 0){

       syslog(LOG_ERR, "Can't link TAP device to IP");

       return -1;

    }



    if ((arp_muxid = ioctl (ip_fd, link_type, arp_fd)) < 0)

        syslog (LOG_ERR, "Can't link TAP device to ARP");



    close (if_fd);



    memset(&ifr, 0x0, sizeof(ifr));

    pstrcpy(ifr.lifr_name, sizeof(ifr.lifr_name), actual_name);

    ifr.lifr_ip_muxid  = ip_muxid;

    ifr.lifr_arp_muxid = arp_muxid;



    if (ioctl (ip_fd, SIOCSLIFMUXID, &ifr) < 0)

    {

      ioctl (ip_fd, I_PUNLINK , arp_muxid);

      ioctl (ip_fd, I_PUNLINK, ip_muxid);

      syslog (LOG_ERR, "Can't set multiplexor id");

    }



    snprintf(dev, dev_size, "tap%d", ppa);

    return tap_fd;

}

void helper_do_semihosting(CPUMIPSState *env)

{

    target_ulong *gpr = env->active_tc.gpr;

    const UHIOp op = gpr[25];

    char *p, *p2;



    switch (op) {

    case UHI_exit:

        qemu_log("UHI(%d): exit(%d)\n", op, (int)gpr[4]);

        exit(gpr[4]);

    case UHI_open:

        GET_TARGET_STRING(p, gpr[4]);

        if (!strcmp("/dev/stdin", p)) {

            gpr[2] = 0;

        } else if (!strcmp("/dev/stdout", p)) {

            gpr[2] = 1;

        } else if (!strcmp("/dev/stderr", p)) {

            gpr[2] = 2;

        } else {

            gpr[2] = open(p, get_open_flags(gpr[5]), gpr[6]);

            gpr[3] = errno_mips(errno);

        }

        FREE_TARGET_STRING(p, gpr[4]);

        break;

    case UHI_close:

        if (gpr[4] < 3) {

            /* ignore closing stdin/stdout/stderr */

            gpr[2] = 0;

            goto uhi_done;

        }

        gpr[2] = close(gpr[4]);

        gpr[3] = errno_mips(errno);

        break;

    case UHI_read:

        gpr[2] = read_from_file(env, gpr[4], gpr[5], gpr[6], 0);

        gpr[3] = errno_mips(errno);

        break;

    case UHI_write:

        gpr[2] = write_to_file(env, gpr[4], gpr[5], gpr[6], 0);

        gpr[3] = errno_mips(errno);

        break;

    case UHI_lseek:

        gpr[2] = lseek(gpr[4], gpr[5], gpr[6]);

        gpr[3] = errno_mips(errno);

        break;

    case UHI_unlink:

        GET_TARGET_STRING(p, gpr[4]);

        gpr[2] = remove(p);

        gpr[3] = errno_mips(errno);

        FREE_TARGET_STRING(p, gpr[4]);

        break;

    case UHI_fstat:

        {

            struct stat sbuf;

            memset(&sbuf, 0, sizeof(sbuf));

            gpr[2] = fstat(gpr[4], &sbuf);

            gpr[3] = errno_mips(errno);

            if (gpr[2]) {

                goto uhi_done;

            }

            gpr[2] = copy_stat_to_target(env, &sbuf, gpr[5]);

            gpr[3] = errno_mips(errno);

        }

        break;

    case UHI_argc:

        gpr[2] = semihosting_get_argc();

        break;

    case UHI_argnlen:

        if (gpr[4] >= semihosting_get_argc()) {

            gpr[2] = -1;

            goto uhi_done;

        }

        gpr[2] = strlen(semihosting_get_arg(gpr[4]));

        break;

    case UHI_argn:

        if (gpr[4] >= semihosting_get_argc()) {

            gpr[2] = -1;

            goto uhi_done;

        }

        gpr[2] = copy_argn_to_target(env, gpr[4], gpr[5]);

        break;

    case UHI_plog:

        GET_TARGET_STRING(p, gpr[4]);

        p2 = strstr(p, "%d");

        if (p2) {

            int char_num = p2 - p;

            char *buf = g_malloc(char_num + 1);

            strncpy(buf, p, char_num);

            buf[char_num] = '\0';

            gpr[2] = printf("%s%d%s", buf, (int)gpr[5], p2 + 2);

            g_free(buf);

        } else {

            gpr[2] = printf("%s", p);

        }

        FREE_TARGET_STRING(p, gpr[4]);

        break;

    case UHI_assert:

        GET_TARGET_STRING(p, gpr[4]);

        GET_TARGET_STRING(p2, gpr[5]);

        printf("assertion '");

        printf("\"%s\"", p);

        printf("': file \"%s\", line %d\n", p2, (int)gpr[6]);

        FREE_TARGET_STRING(p2, gpr[5]);

        FREE_TARGET_STRING(p, gpr[4]);

        abort();

        break;

    case UHI_pread:

        gpr[2] = read_from_file(env, gpr[4], gpr[5], gpr[6], gpr[7]);

        gpr[3] = errno_mips(errno);

        break;

    case UHI_pwrite:

        gpr[2] = write_to_file(env, gpr[4], gpr[5], gpr[6], gpr[7]);

        gpr[3] = errno_mips(errno);

        break;

#ifndef _WIN32

    case UHI_link:

        GET_TARGET_STRING(p, gpr[4]);

        GET_TARGET_STRING(p2, gpr[5]);

        gpr[2] = link(p, p2);

        gpr[3] = errno_mips(errno);

        FREE_TARGET_STRING(p2, gpr[5]);

        FREE_TARGET_STRING(p, gpr[4]);

        break;

#endif

    default:

        fprintf(stderr, "Unknown UHI operation %d\n", op);

        abort();

    }

uhi_done:

    return;

}

