{

    pid_t pid = -1;

    int stdinfd[2] = { -1, -1 };

    int stdoutfd[2] = { -1, -1 };

    int devnull = -1;

    bool stdinnull = false, stdoutnull = false;

    QIOChannelCommand *ioc;



    flags = flags & O_ACCMODE;



    if (flags == O_RDONLY) {

        stdinnull = true;

    }

    if (flags == O_WRONLY) {

        stdoutnull = true;

    }



    if (stdinnull || stdoutnull) {

        devnull = open("/dev/null", O_RDWR);

        if (!devnull) {

            error_setg_errno(errp, errno,

                             "Unable to open /dev/null");

            goto error;

        }

    }



    if ((!stdinnull && pipe(stdinfd) < 0) ||

        (!stdoutnull && pipe(stdoutfd) < 0)) {

        error_setg_errno(errp, errno,

                         "Unable to open pipe");

        goto error;

    }



    pid = qemu_fork(errp);

    if (pid < 0) {

        goto error;

    }



    if (pid == 0) { /* child */

        dup2(stdinnull ? devnull : stdinfd[0], STDIN_FILENO);

        dup2(stdoutnull ? devnull : stdoutfd[1], STDOUT_FILENO);

        /* Leave stderr connected to qemu's stderr */



        if (!stdinnull) {

            close(stdinfd[0]);

            close(stdinfd[1]);

        }

        if (!stdoutnull) {

            close(stdoutfd[0]);

            close(stdoutfd[1]);

        }



        execv(argv[0], (char * const *)argv);

        _exit(1);

    }



    if (!stdinnull) {

        close(stdinfd[0]);

    }

    if (!stdoutnull) {

        close(stdoutfd[1]);

    }



    ioc = qio_channel_command_new_pid(stdinnull ? devnull : stdinfd[1],

                                      stdoutnull ? devnull : stdoutfd[0],

                                      pid);

    trace_qio_channel_command_new_spawn(ioc, argv[0], flags);

    return ioc;



 error:

    if (stdinfd[0] != -1) {

        close(stdinfd[0]);

    }

    if (stdinfd[1] != -1) {

        close(stdinfd[1]);

    }

    if (stdoutfd[0] != -1) {

        close(stdoutfd[0]);

    }

    if (stdoutfd[1] != -1) {

        close(stdoutfd[1]);

    }

    return NULL;

}

long do_sigreturn(CPUX86State *env)

{

    struct sigframe *frame;

    abi_ulong frame_addr = env->regs[R_ESP] - 8;

    target_sigset_t target_set;

    sigset_t set;

    int eax, i;



#if defined(DEBUG_SIGNAL)

    fprintf(stderr, "do_sigreturn\n");

#endif

    if (!lock_user_struct(VERIFY_READ, frame, frame_addr, 1))

        goto badframe;

    /* set blocked signals */

    if (__get_user(target_set.sig[0], &frame->sc.oldmask))

        goto badframe;

    for(i = 1; i < TARGET_NSIG_WORDS; i++) {

        if (__get_user(target_set.sig[i], &frame->extramask[i - 1]))

            goto badframe;

    }



    target_to_host_sigset_internal(&set, &target_set);

    do_sigprocmask(SIG_SETMASK, &set, NULL);



    /* restore registers */

    if (restore_sigcontext(env, &frame->sc, &eax))

        goto badframe;

    unlock_user_struct(frame, frame_addr, 0);

    return eax;



badframe:

    unlock_user_struct(frame, frame_addr, 0);

    force_sig(TARGET_SIGSEGV);

    return 0;

}

void cpu_dump_state(CPUXtensaState *env, FILE *f, fprintf_function cpu_fprintf,

        int flags)

{

    int i, j;



    cpu_fprintf(f, "PC=%08x\n\n", env->pc);



    for (i = j = 0; i < 256; ++i) {

        if (sregnames[i]) {

            cpu_fprintf(f, "%s=%08x%c", sregnames[i], env->sregs[i],

                    (j++ % 4) == 3 ? '\n' : ' ');

        }

    }



    cpu_fprintf(f, (j % 4) == 0 ? "\n" : "\n\n");



    for (i = j = 0; i < 256; ++i) {

        if (uregnames[i]) {

            cpu_fprintf(f, "%s=%08x%c", uregnames[i], env->uregs[i],

                    (j++ % 4) == 3 ? '\n' : ' ');

        }

    }



    cpu_fprintf(f, (j % 4) == 0 ? "\n" : "\n\n");



    for (i = 0; i < 16; ++i) {

        cpu_fprintf(f, "A%02d=%08x%c", i, env->regs[i],

                (i % 4) == 3 ? '\n' : ' ');

    }



    cpu_fprintf(f, "\n");



    for (i = 0; i < env->config->nareg; ++i) {

        cpu_fprintf(f, "AR%02d=%08x%c", i, env->phys_regs[i],

                (i % 4) == 3 ? '\n' : ' ');

    }



    if (xtensa_option_enabled(env->config, XTENSA_OPTION_FP_COPROCESSOR)) {

        cpu_fprintf(f, "\n");



        for (i = 0; i < 16; ++i) {

            cpu_fprintf(f, "F%02d=%08x (%+10.8e)%c", i,

                    float32_val(env->fregs[i]),

                    *(float *)&env->fregs[i], (i % 2) == 1 ? '\n' : ' ');

        }

    }

}

int kvm_arch_init(KVMState *s)

{

    uint64_t identity_base = 0xfffbc000;

    int ret;

    struct utsname utsname;



    ret = kvm_get_supported_msrs(s);

    if (ret < 0) {

        return ret;

    }



    uname(&utsname);

    lm_capable_kernel = strcmp(utsname.machine, "x86_64") == 0;



    /*

     * On older Intel CPUs, KVM uses vm86 mode to emulate 16-bit code directly.

     * In order to use vm86 mode, an EPT identity map and a TSS  are needed.

     * Since these must be part of guest physical memory, we need to allocate

     * them, both by setting their start addresses in the kernel and by

     * creating a corresponding e820 entry. We need 4 pages before the BIOS.

     *

     * Older KVM versions may not support setting the identity map base. In

     * that case we need to stick with the default, i.e. a 256K maximum BIOS

     * size.

     */

#ifdef KVM_CAP_SET_IDENTITY_MAP_ADDR

    if (kvm_check_extension(s, KVM_CAP_SET_IDENTITY_MAP_ADDR)) {

        /* Allows up to 16M BIOSes. */

        identity_base = 0xfeffc000;



        ret = kvm_vm_ioctl(s, KVM_SET_IDENTITY_MAP_ADDR, &identity_base);

        if (ret < 0) {

            return ret;

        }

    }

#endif

    /* Set TSS base one page after EPT identity map. */

    ret = kvm_vm_ioctl(s, KVM_SET_TSS_ADDR, identity_base + 0x1000);

    if (ret < 0) {

        return ret;

    }



    /* Tell fw_cfg to notify the BIOS to reserve the range. */

    ret = e820_add_entry(identity_base, 0x4000, E820_RESERVED);

    if (ret < 0) {

        fprintf(stderr, "e820_add_entry() table is full\n");

        return ret;

    }




    return 0;

}

