static void slirp_guestfwd(SlirpState *s, Monitor *mon, const char *config_str,

                           int legacy_format)

{

    struct in_addr server = { .s_addr = 0 };

    struct GuestFwd *fwd;

    const char *p;

    char buf[128];

    char *end;

    int port;



    p = config_str;

    if (legacy_format) {

        if (get_str_sep(buf, sizeof(buf), &p, ':') < 0) {

            goto fail_syntax;

        }

    } else {

        if (get_str_sep(buf, sizeof(buf), &p, ':') < 0) {

            goto fail_syntax;

        }

        if (strcmp(buf, "tcp") && buf[0] != '\0') {

            goto fail_syntax;

        }

        if (get_str_sep(buf, sizeof(buf), &p, ':') < 0) {

            goto fail_syntax;

        }

        if (buf[0] != '\0' && !inet_aton(buf, &server)) {

            goto fail_syntax;

        }

        if (get_str_sep(buf, sizeof(buf), &p, '-') < 0) {

            goto fail_syntax;

        }

    }

    port = strtol(buf, &end, 10);

    if (*end != '\0' || port < 1 || port > 65535) {

        goto fail_syntax;

    }



    fwd = qemu_malloc(sizeof(struct GuestFwd));

    snprintf(buf, sizeof(buf), "guestfwd.tcp:%d", port);

    fwd->hd = qemu_chr_open(buf, p, NULL);

    if (!fwd->hd) {

        config_error(mon, "could not open guest forwarding device '%s'\n",

                     buf);

        qemu_free(fwd);

        return;

    }



    if (slirp_add_exec(s->slirp, 3, fwd->hd, &server, port) < 0) {

        config_error(mon, "conflicting/invalid host:port in guest forwarding "

                     "rule '%s'\n", config_str);

        qemu_free(fwd);

        return;

    }

    fwd->server = server;

    fwd->port = port;

    fwd->slirp = s->slirp;



    qemu_chr_add_handlers(fwd->hd, guestfwd_can_read, guestfwd_read,

                          NULL, fwd);

    return;



 fail_syntax:

    config_error(mon, "invalid guest forwarding rule '%s'\n", config_str);

}

int s390_virtio_hypercall(CPUState *env, uint64_t mem, uint64_t hypercall)

{

    int r = 0, i;



    dprintf("KVM hypercall: %ld\n", hypercall);

    switch (hypercall) {

    case KVM_S390_VIRTIO_NOTIFY:

        if (mem > ram_size) {

            VirtIOS390Device *dev = s390_virtio_bus_find_vring(s390_bus,

                                                               mem, &i);

            if (dev) {

                virtio_queue_notify(dev->vdev, i);

            } else {

                r = -EINVAL;

            }

        } else {

            /* Early printk */

        }

        break;

    case KVM_S390_VIRTIO_RESET:

    {

        VirtIOS390Device *dev;



        dev = s390_virtio_bus_find_mem(s390_bus, mem);

        virtio_reset(dev->vdev);


        s390_virtio_device_sync(dev);

        break;

    }

    case KVM_S390_VIRTIO_SET_STATUS:

    {

        VirtIOS390Device *dev;



        dev = s390_virtio_bus_find_mem(s390_bus, mem);

        if (dev) {

            s390_virtio_device_update_status(dev);

        } else {

            r = -EINVAL;

        }

        break;

    }

    default:

        r = -EINVAL;

        break;

    }



    return r;

}

