static void exynos4210_rtc_write(void *opaque, target_phys_addr_t offset,

        uint64_t value, unsigned size)

{

    Exynos4210RTCState *s = (Exynos4210RTCState *)opaque;



    switch (offset) {

    case INTP:

        if (value & INTP_ALM_ENABLE) {

            qemu_irq_lower(s->alm_irq);

            s->reg_intp &= (~INTP_ALM_ENABLE);

        }

        if (value & INTP_TICK_ENABLE) {

            qemu_irq_lower(s->tick_irq);

            s->reg_intp &= (~INTP_TICK_ENABLE);

        }

        break;

    case RTCCON:

        if (value & RTC_ENABLE) {

            exynos4210_rtc_update_freq(s, value);

        }

        if ((value & RTC_ENABLE) > (s->reg_rtccon & RTC_ENABLE)) {

            /* clock timer */

            ptimer_set_count(s->ptimer_1Hz, RTC_BASE_FREQ);

            ptimer_run(s->ptimer_1Hz, 1);

            DPRINTF("run clock timer\n");

        }

        if ((value & RTC_ENABLE) < (s->reg_rtccon & RTC_ENABLE)) {

            /* tick timer */

            ptimer_stop(s->ptimer);

            /* clock timer */

            ptimer_stop(s->ptimer_1Hz);

            DPRINTF("stop all timers\n");

        }

        if (value & RTC_ENABLE) {

            if ((value & TICK_TIMER_ENABLE) >

                (s->reg_rtccon & TICK_TIMER_ENABLE) &&

                (s->reg_ticcnt)) {

                ptimer_set_count(s->ptimer, s->reg_ticcnt);

                ptimer_run(s->ptimer, 1);

                DPRINTF("run tick timer\n");

            }

            if ((value & TICK_TIMER_ENABLE) <

                (s->reg_rtccon & TICK_TIMER_ENABLE)) {

                ptimer_stop(s->ptimer);

            }

        }

        s->reg_rtccon = value;

        break;

    case TICCNT:

        if (value > TICNT_THRESHHOLD) {

            s->reg_ticcnt = value;

        } else {

            fprintf(stderr,

                    "[exynos4210.rtc: bad TICNT value %u ]\n",

                    (uint32_t)value);

        }

        break;



    case RTCALM:

        s->reg_rtcalm = value;

        break;

    case ALMSEC:

        s->reg_almsec = (value & 0x7f);

        break;

    case ALMMIN:

        s->reg_almmin = (value & 0x7f);

        break;

    case ALMHOUR:

        s->reg_almhour = (value & 0x3f);

        break;

    case ALMDAY:

        s->reg_almday = (value & 0x3f);

        break;

    case ALMMON:

        s->reg_almmon = (value & 0x1f);

        break;

    case ALMYEAR:

        s->reg_almyear = (value & 0x0fff);

        break;



    case BCDSEC:

        if (s->reg_rtccon & RTC_ENABLE) {

            s->current_tm.tm_sec = (int)from_bcd((uint8_t)value);

        }

        break;

    case BCDMIN:

        if (s->reg_rtccon & RTC_ENABLE) {

            s->current_tm.tm_min = (int)from_bcd((uint8_t)value);

        }

        break;

    case BCDHOUR:

        if (s->reg_rtccon & RTC_ENABLE) {

            s->current_tm.tm_hour = (int)from_bcd((uint8_t)value);

        }

        break;

    case BCDDAYWEEK:

        if (s->reg_rtccon & RTC_ENABLE) {

            s->current_tm.tm_wday = (int)from_bcd((uint8_t)value);

        }

        break;

    case BCDDAY:

        if (s->reg_rtccon & RTC_ENABLE) {

            s->current_tm.tm_mday = (int)from_bcd((uint8_t)value);

        }

        break;

    case BCDMON:

        if (s->reg_rtccon & RTC_ENABLE) {

            s->current_tm.tm_mon = (int)from_bcd((uint8_t)value) - 1;

        }

        break;

    case BCDYEAR:

        if (s->reg_rtccon & RTC_ENABLE) {

            /* 3 digits */

            s->current_tm.tm_year = (int)from_bcd((uint8_t)value) +

                    (int)from_bcd((uint8_t)((value >> 8) & 0x0f)) * 100;

        }

        break;



    default:

        fprintf(stderr,

                "[exynos4210.rtc: bad write offset " TARGET_FMT_plx "]\n",

                offset);

        break;



    }

}

static void dummy_m68k_init(QEMUMachineInitArgs *args)

{

    ram_addr_t ram_size = args->ram_size;

    const char *cpu_model = args->cpu_model;

    const char *kernel_filename = args->kernel_filename;

    CPUM68KState *env;

    MemoryRegion *address_space_mem =  get_system_memory();

    MemoryRegion *ram = g_new(MemoryRegion, 1);

    int kernel_size;

    uint64_t elf_entry;

    target_phys_addr_t entry;



    if (!cpu_model)

        cpu_model = "cfv4e";

    env = cpu_init(cpu_model);

    if (!env) {

        fprintf(stderr, "Unable to find m68k CPU definition\n");

        exit(1);

    }



    /* Initialize CPU registers.  */

    env->vbr = 0;



    /* RAM at address zero */

    memory_region_init_ram(ram, "dummy_m68k.ram", ram_size);

    vmstate_register_ram_global(ram);

    memory_region_add_subregion(address_space_mem, 0, ram);



    /* Load kernel.  */

    if (kernel_filename) {

        kernel_size = load_elf(kernel_filename, NULL, NULL, &elf_entry,

                               NULL, NULL, 1, ELF_MACHINE, 0);

        entry = elf_entry;

        if (kernel_size < 0) {

            kernel_size = load_uimage(kernel_filename, &entry, NULL, NULL);

        }

        if (kernel_size < 0) {

            kernel_size = load_image_targphys(kernel_filename,

                                              KERNEL_LOAD_ADDR,

                                              ram_size - KERNEL_LOAD_ADDR);

            entry = KERNEL_LOAD_ADDR;

        }

        if (kernel_size < 0) {

            fprintf(stderr, "qemu: could not load kernel '%s'\n",

                    kernel_filename);

            exit(1);

        }

    } else {

        entry = 0;

    }

    env->pc = entry;

}

static void memory_dump(int count, int format, int wsize,

                        target_phys_addr_t addr, int is_physical)

{

    CPUState *env;

    int nb_per_line, l, line_size, i, max_digits, len;

    uint8_t buf[16];

    uint64_t v;



    if (format == 'i') {

        int flags;

        flags = 0;

        env = mon_get_cpu();

        if (!env && !is_physical)

            return;

#ifdef TARGET_I386

        if (wsize == 2) {

            flags = 1;

        } else if (wsize == 4) {

            flags = 0;

        } else {

            /* as default we use the current CS size */

            flags = 0;

            if (env) {

#ifdef TARGET_X86_64

                if ((env->efer & MSR_EFER_LMA) &&

                    (env->segs[R_CS].flags & DESC_L_MASK))

                    flags = 2;

                else

#endif

                if (!(env->segs[R_CS].flags & DESC_B_MASK))

                    flags = 1;

            }

        }

#endif

        monitor_disas(env, addr, count, is_physical, flags);

        return;

    }



    len = wsize * count;

    if (wsize == 1)

        line_size = 8;

    else

        line_size = 16;

    nb_per_line = line_size / wsize;

    max_digits = 0;



    switch(format) {

    case 'o':

        max_digits = (wsize * 8 + 2) / 3;

        break;

    default:

    case 'x':

        max_digits = (wsize * 8) / 4;

        break;

    case 'u':

    case 'd':

        max_digits = (wsize * 8 * 10 + 32) / 33;

        break;

    case 'c':

        wsize = 1;

        break;

    }



    while (len > 0) {

        if (is_physical)

            term_printf(TARGET_FMT_plx ":", addr);

        else

            term_printf(TARGET_FMT_lx ":", (target_ulong)addr);

        l = len;

        if (l > line_size)

            l = line_size;

        if (is_physical) {

            cpu_physical_memory_rw(addr, buf, l, 0);

        } else {

            env = mon_get_cpu();

            if (!env)

                break;

            cpu_memory_rw_debug(env, addr, buf, l, 0);

        }

        i = 0;

        while (i < l) {

            switch(wsize) {

            default:

            case 1:

                v = ldub_raw(buf + i);

                break;

            case 2:

                v = lduw_raw(buf + i);

                break;

            case 4:

                v = (uint32_t)ldl_raw(buf + i);

                break;

            case 8:

                v = ldq_raw(buf + i);

                break;

            }

            term_printf(" ");

            switch(format) {

            case 'o':

                term_printf("%#*" PRIo64, max_digits, v);

                break;

            case 'x':

                term_printf("0x%0*" PRIx64, max_digits, v);

                break;

            case 'u':

                term_printf("%*" PRIu64, max_digits, v);

                break;

            case 'd':

                term_printf("%*" PRId64, max_digits, v);

                break;

            case 'c':

                term_printc(v);

                break;

            }

            i += wsize;

        }

        term_printf("\n");

        addr += l;

        len -= l;

    }

}

void ide_sector_write(IDEState *s)

{

    int64_t sector_num;

    int n;



    s->status = READY_STAT | SEEK_STAT | BUSY_STAT;

