    if (!qobj || qobject_type(qobj) != QTYPE_QBOOL) {

        error_setg(errp, QERR_INVALID_PARAMETER_TYPE, name ? name : "null",

                   "boolean");

        return;

    }



    *obj = qbool_get_bool(qobject_to_qbool(qobj));

}

