GuestLogicalProcessorList *qmp_guest_get_vcpus(Error **errp)

{

    PSYSTEM_LOGICAL_PROCESSOR_INFORMATION pslpi, ptr;

    DWORD length;

    GuestLogicalProcessorList *head, **link;

    Error *local_err = NULL;

    int64_t current;



    ptr = pslpi = NULL;

    length = 0;

    current = 0;

    head = NULL;

    link = &head;



    if ((GetLogicalProcessorInformation(pslpi, &length) == FALSE) &&

        (GetLastError() == ERROR_INSUFFICIENT_BUFFER) &&

        (length > sizeof(SYSTEM_LOGICAL_PROCESSOR_INFORMATION))) {

        ptr = pslpi = g_malloc0(length);

        if (GetLogicalProcessorInformation(pslpi, &length) == FALSE) {

            error_setg(&local_err, "Failed to get processor information: %d",

                       (int)GetLastError());

        }

    } else {

        error_setg(&local_err,

                   "Failed to get processor information buffer length: %d",

                   (int)GetLastError());

    }



    while ((local_err == NULL) && (length > 0)) {

        if (pslpi->Relationship == RelationProcessorCore) {

            ULONG_PTR cpu_bits = pslpi->ProcessorMask;



            while (cpu_bits > 0) {

                if (!!(cpu_bits & 1)) {

                    GuestLogicalProcessor *vcpu;

                    GuestLogicalProcessorList *entry;



                    vcpu = g_malloc0(sizeof *vcpu);

                    vcpu->logical_id = current++;

                    vcpu->online = true;

                    vcpu->has_can_offline = false;



                    entry = g_malloc0(sizeof *entry);

                    entry->value = vcpu;



                    *link = entry;

                    link = &entry->next;

                }

                cpu_bits >>= 1;

            }

        }

        length -= sizeof(SYSTEM_LOGICAL_PROCESSOR_INFORMATION);

        pslpi++; /* next entry */

    }



    g_free(ptr);



    if (local_err == NULL) {

        if (head != NULL) {

            return head;

        }

        /* there's no guest with zero VCPUs */

        error_setg(&local_err, "Guest reported zero VCPUs");

    }



    qapi_free_GuestLogicalProcessorList(head);

    error_propagate(errp, local_err);

    return NULL;

}

static bool bdrv_drain_poll(BlockDriverState *bs)

{

    bool waited = false;



    while (atomic_read(&bs->in_flight) > 0) {

        aio_poll(bdrv_get_aio_context(bs), true);

        waited = true;

    }

    return waited;

}

static void cpu_exec_step(CPUState *cpu)

{

    CPUClass *cc = CPU_GET_CLASS(cpu);

    TranslationBlock *tb;

    target_ulong cs_base, pc;

    uint32_t flags;

    uint32_t cflags = 1 | CF_IGNORE_ICOUNT;



    if (sigsetjmp(cpu->jmp_env, 0) == 0) {

        tb = tb_lookup__cpu_state(cpu, &pc, &cs_base, &flags,

                                  cflags & CF_HASH_MASK);

        if (tb == NULL) {

            mmap_lock();

            tb_lock();

            tb = tb_gen_code(cpu, pc, cs_base, flags, cflags);

            tb_unlock();

            mmap_unlock();

        }



        cc->cpu_exec_enter(cpu);

        /* execute the generated code */

        trace_exec_tb(tb, pc);

        cpu_tb_exec(cpu, tb);

        cc->cpu_exec_exit(cpu);

    } else {

        /* We may have exited due to another problem here, so we need

         * to reset any tb_locks we may have taken but didn't release.

         * The mmap_lock is dropped by tb_gen_code if it runs out of

         * memory.

         */

#ifndef CONFIG_SOFTMMU

        tcg_debug_assert(!have_mmap_lock());

#endif

        tb_lock_reset();

    }

}

static bool intel_hda_xfer(HDACodecDevice *dev, uint32_t stnr, bool output,

                           uint8_t *buf, uint32_t len)

{

    HDACodecBus *bus = DO_UPCAST(HDACodecBus, qbus, dev->qdev.parent_bus);

    IntelHDAState *d = container_of(bus, IntelHDAState, codecs);

    target_phys_addr_t addr;

    uint32_t s, copy, left;

    IntelHDAStream *st;

    bool irq = false;



    st = output ? d->st + 4 : d->st;

    for (s = 0; s < 4; s++) {

        if (stnr == ((st[s].ctl >> 20) & 0x0f)) {

            st = st + s;

            break;

        }

    }

    if (s == 4) {

        return false;

    }

    if (st->bpl == NULL) {

        return false;

    }

    if (st->ctl & (1 << 26)) {

        /*

         * Wait with the next DMA xfer until the guest

         * has acked the buffer completion interrupt

         */

        return false;

    }



    left = len;

    while (left > 0) {

        copy = left;

        if (copy > st->bsize - st->lpib)

            copy = st->bsize - st->lpib;

        if (copy > st->bpl[st->be].len - st->bp)

            copy = st->bpl[st->be].len - st->bp;



        dprint(d, 3, "dma: entry %d, pos %d/%d, copy %d\n",

               st->be, st->bp, st->bpl[st->be].len, copy);



        pci_dma_rw(&d->pci, st->bpl[st->be].addr + st->bp, buf, copy, !output);

        st->lpib += copy;

        st->bp += copy;

        buf += copy;

        left -= copy;



        if (st->bpl[st->be].len == st->bp) {

            /* bpl entry filled */

            if (st->bpl[st->be].flags & 0x01) {

                irq = true;

            }

            st->bp = 0;

            st->be++;

            if (st->be == st->bentries) {

                /* bpl wrap around */

                st->be = 0;

                st->lpib = 0;

            }

        }

    }

    if (d->dp_lbase & 0x01) {

        addr = intel_hda_addr(d->dp_lbase & ~0x01, d->dp_ubase);

        stl_le_pci_dma(&d->pci, addr + 8*s, st->lpib);

    }

    dprint(d, 3, "dma: --\n");



    if (irq) {

        st->ctl |= (1 << 26); /* buffer completion interrupt */

        intel_hda_update_irq(d);

    }

    return true;

}

int64_t qmp_guest_get_time(Error **errp)

{

   int ret;

   qemu_timeval tq;

   int64_t time_ns;



   ret = qemu_gettimeofday(&tq);

   if (ret < 0) {

       error_setg_errno(errp, errno, "Failed to get time");

       return -1;

   }



   time_ns = tq.tv_sec * 1000000000LL + tq.tv_usec * 1000;

   return time_ns;

}

static int check_strtox_error(const char *nptr, char *ep,

                              const char **endptr, int libc_errno)

{

    if (libc_errno == 0 && ep == nptr) {

        libc_errno = EINVAL;

    }

    if (!endptr && *ep) {

        return -EINVAL;

    }

    if (endptr) {

        *endptr = ep;

    }

    return -libc_errno;

}

static void ncq_cb(void *opaque, int ret)

{

    NCQTransferState *ncq_tfs = (NCQTransferState *)opaque;

    IDEState *ide_state = &ncq_tfs->drive->port.ifs[0];



    if (ret == -ECANCELED) {

        return;

    }

    /* Clear bit for this tag in SActive */

    ncq_tfs->drive->port_regs.scr_act &= ~(1 << ncq_tfs->tag);



    if (ret < 0) {

        /* error */

        ide_state->error = ABRT_ERR;

        ide_state->status = READY_STAT | ERR_STAT;

        ncq_tfs->drive->port_regs.scr_err |= (1 << ncq_tfs->tag);

    } else {

        ide_state->status = READY_STAT | SEEK_STAT;

    }



    ahci_write_fis_sdb(ncq_tfs->drive->hba, ncq_tfs->drive->port_no,

                       (1 << ncq_tfs->tag));



    DPRINTF(ncq_tfs->drive->port_no, "NCQ transfer tag %d finished\n",

            ncq_tfs->tag);



    block_acct_done(bdrv_get_stats(ncq_tfs->drive->port.ifs[0].bs),

                    &ncq_tfs->acct);

    qemu_sglist_destroy(&ncq_tfs->sglist);

    ncq_tfs->used = 0;

}

static bool aio_dispatch_handlers(AioContext *ctx)

{

    AioHandler *node, *tmp;

    bool progress = false;



    /*

     * We have to walk very carefully in case aio_set_fd_handler is

     * called while we're walking.

     */

    qemu_lockcnt_inc(&ctx->list_lock);



    QLIST_FOREACH_SAFE_RCU(node, &ctx->aio_handlers, node, tmp) {

        int revents;



        revents = node->pfd.revents & node->pfd.events;

        node->pfd.revents = 0;



        if (!node->deleted &&

            (revents & (G_IO_IN | G_IO_HUP | G_IO_ERR)) &&

            aio_node_check(ctx, node->is_external) &&

            node->io_read) {

            node->io_read(node->opaque);



            /* aio_notify() does not count as progress */

            if (node->opaque != &ctx->notifier) {

                progress = true;

            }

        }

        if (!node->deleted &&

            (revents & (G_IO_OUT | G_IO_ERR)) &&

            aio_node_check(ctx, node->is_external) &&

            node->io_write) {

            node->io_write(node->opaque);

            progress = true;

        }



        if (node->deleted) {

            if (qemu_lockcnt_dec_if_lock(&ctx->list_lock)) {

                QLIST_REMOVE(node, node);

                g_free(node);

                qemu_lockcnt_inc_and_unlock(&ctx->list_lock);

            }

        }

    }



    qemu_lockcnt_dec(&ctx->list_lock);

    return progress;

}

static void decode_opc_special3(CPUMIPSState *env, DisasContext *ctx)

{

    int rs, rt, rd, sa;

    uint32_t op1, op2;



    rs = (ctx->opcode >> 21) & 0x1f;

    rt = (ctx->opcode >> 16) & 0x1f;

    rd = (ctx->opcode >> 11) & 0x1f;

    sa = (ctx->opcode >> 6) & 0x1f;



    op1 = MASK_SPECIAL3(ctx->opcode);

    switch (op1) {

    case OPC_EXT:

    case OPC_INS:

        check_insn(ctx, ISA_MIPS32R2);

        gen_bitops(ctx, op1, rt, rs, sa, rd);

        break;

    case OPC_BSHFL:

        op2 = MASK_BSHFL(ctx->opcode);

        switch (op2) {

        case OPC_ALIGN ... OPC_ALIGN_END:

        case OPC_BITSWAP:

            check_insn(ctx, ISA_MIPS32R6);

            decode_opc_special3_r6(env, ctx);

            break;

        default:

            check_insn(ctx, ISA_MIPS32R2);

            gen_bshfl(ctx, op2, rt, rd);

            break;

        }

        break;

#if defined(TARGET_MIPS64)

    case OPC_DEXTM ... OPC_DEXT:

    case OPC_DINSM ... OPC_DINS:

        check_insn(ctx, ISA_MIPS64R2);

        check_mips_64(ctx);

        gen_bitops(ctx, op1, rt, rs, sa, rd);

        break;

    case OPC_DBSHFL:

        op2 = MASK_DBSHFL(ctx->opcode);

        switch (op2) {

        case OPC_DALIGN ... OPC_DALIGN_END:

        case OPC_DBITSWAP:

            check_insn(ctx, ISA_MIPS32R6);

            decode_opc_special3_r6(env, ctx);

            break;

        default:

            check_insn(ctx, ISA_MIPS64R2);

            check_mips_64(ctx);

            op2 = MASK_DBSHFL(ctx->opcode);

            gen_bshfl(ctx, op2, rt, rd);

            break;

        }

        break;

#endif

    case OPC_RDHWR:

        gen_rdhwr(ctx, rt, rd);

        break;

    case OPC_FORK:

        check_insn(ctx, ASE_MT);

        {

            TCGv t0 = tcg_temp_new();

            TCGv t1 = tcg_temp_new();



            gen_load_gpr(t0, rt);

            gen_load_gpr(t1, rs);

            gen_helper_fork(t0, t1);

            tcg_temp_free(t0);

            tcg_temp_free(t1);

        }

        break;

    case OPC_YIELD:

        check_insn(ctx, ASE_MT);

        {

            TCGv t0 = tcg_temp_new();



            gen_load_gpr(t0, rs);

            gen_helper_yield(t0, cpu_env, t0);

            gen_store_gpr(t0, rd);

            tcg_temp_free(t0);

        }

        break;

    default:

        if (ctx->insn_flags & ISA_MIPS32R6) {

            decode_opc_special3_r6(env, ctx);

        } else {

            decode_opc_special3_legacy(env, ctx);

        }

    }

}

static void scsi_dma_complete(void *opaque, int ret)

{

    SCSIDiskReq *r = (SCSIDiskReq *)opaque;

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);



    bdrv_acct_done(s->qdev.conf.bs, &r->acct);



    if (ret) {

        if (scsi_handle_rw_error(r, -ret)) {

            goto done;

        }

    }



    r->sector += r->sector_count;

    r->sector_count = 0;

    scsi_req_complete(&r->req, GOOD);



done:

    if (!r->req.io_canceled) {

        scsi_req_unref(&r->req);

    }

}

static void dump_sprs (CPUPPCState *env)

{

    ppc_spr_t *spr;

    uint32_t pvr = env->spr[SPR_PVR];

    uint32_t sr, sw, ur, uw;

    int i, j, n;



    printf("* SPRs for PVR=%08x\n", pvr);

    for (i = 0; i < 32; i++) {

        for (j = 0; j < 32; j++) {

            n = (i << 5) | j;

            spr = &env->spr_cb[n];

#if !defined(CONFIG_USER_ONLY)

            sw = spr->oea_write != NULL && spr->oea_write != SPR_NOACCESS;

            sr = spr->oea_read != NULL && spr->oea_read != SPR_NOACCESS;

#else

            sw = 0;

            sr = 0;

#endif

            uw = spr->uea_write != NULL && spr->uea_write != SPR_NOACCESS;

            ur = spr->uea_read != NULL && spr->uea_read != SPR_NOACCESS;

            if (sw || sr || uw || ur) {

                printf("%4d (%03x) %8s s%c%c u%c%c\n",

                       (i << 5) | j, (i << 5) | j, spr->name,

                       sw ? 'w' : '-', sr ? 'r' : '-',

                       uw ? 'w' : '-', ur ? 'r' : '-');

            }

        }

    }

    fflush(stdout);

    fflush(stderr);

}

void pc_cpus_init(PCMachineState *pcms)

{

    int i;

    CPUClass *cc;

    ObjectClass *oc;

    const char *typename;

    gchar **model_pieces;

    X86CPU *cpu = NULL;

    MachineState *machine = MACHINE(pcms);



    /* init CPUs */

    if (machine->cpu_model == NULL) {

#ifdef TARGET_X86_64

        machine->cpu_model = "qemu64";

#else

        machine->cpu_model = "qemu32";

#endif

    }



    model_pieces = g_strsplit(machine->cpu_model, ",", 2);

    if (!model_pieces[0]) {

        error_report("Invalid/empty CPU model name");

        exit(1);

    }



    oc = cpu_class_by_name(TYPE_X86_CPU, model_pieces[0]);

    if (oc == NULL) {

        error_report("Unable to find CPU definition: %s", model_pieces[0]);

        exit(1);

    }

    typename = object_class_get_name(oc);

    cc = CPU_CLASS(oc);

    cc->parse_features(typename, model_pieces[1], &error_fatal);

    g_strfreev(model_pieces);



    /* Calculates the limit to CPU APIC ID values

     *

     * Limit for the APIC ID value, so that all

     * CPU APIC IDs are < pcms->apic_id_limit.

     *

     * This is used for FW_CFG_MAX_CPUS. See comments on bochs_bios_init().

     */

    pcms->apic_id_limit = x86_cpu_apic_id_from_index(max_cpus - 1) + 1;

    if (pcms->apic_id_limit > ACPI_CPU_HOTPLUG_ID_LIMIT) {

        error_report("max_cpus is too large. APIC ID of last CPU is %u",

                     pcms->apic_id_limit - 1);

        exit(1);

    }



    pcms->possible_cpus = g_malloc0(sizeof(CPUArchIdList) +

                                    sizeof(CPUArchId) * max_cpus);

    for (i = 0; i < max_cpus; i++) {

        pcms->possible_cpus->cpus[i].arch_id = x86_cpu_apic_id_from_index(i);

        pcms->possible_cpus->len++;

        if (i < smp_cpus) {

            cpu = pc_new_cpu(typename, x86_cpu_apic_id_from_index(i),

                             &error_fatal);

            object_unref(OBJECT(cpu));

        }

    }



    /* tell smbios about cpuid version and features */

    smbios_set_cpuid(cpu->env.cpuid_version, cpu->env.features[FEAT_1_EDX]);

}

