            QDict *bs_dict = qobject_to_qdict(bs_obj);



            obj = qobject_from_jsonf("{ 'file': %s, 'ro': %i, 'drv': %s, "

                                     "'encrypted': %i }",

                                     bs->filename, bs->read_only,

                                     bs->drv->format_name,

