static int coroutine_fn bdrv_driver_pwritev(BlockDriverState *bs,
                                            uint64_t offset, uint64_t bytes,
                                            QEMUIOVector *qiov, int flags)
{
    BlockDriver *drv = bs->drv;
    int64_t sector_num;
    unsigned int nb_sectors;
    int ret;
    if (drv->bdrv_co_pwritev) {
        ret = drv->bdrv_co_pwritev(bs, offset, bytes, qiov,
                                   flags & bs->supported_write_flags);
        flags &= ~bs->supported_write_flags;
        goto emulate_flags;
    }
    sector_num = offset >> BDRV_SECTOR_BITS;
    nb_sectors = bytes >> BDRV_SECTOR_BITS;
    assert((offset & (BDRV_SECTOR_SIZE - 1)) == 0);
    assert((bytes & (BDRV_SECTOR_SIZE - 1)) == 0);
    assert((bytes >> BDRV_SECTOR_BITS) <= BDRV_REQUEST_MAX_SECTORS);
    if (drv->bdrv_co_writev_flags) {
        ret = drv->bdrv_co_writev_flags(bs, sector_num, nb_sectors, qiov,
                                        flags & bs->supported_write_flags);
        flags &= ~bs->supported_write_flags;
    } else if (drv->bdrv_co_writev) {
        assert(!bs->supported_write_flags);
        ret = drv->bdrv_co_writev(bs, sector_num, nb_sectors, qiov);
    } else {
        BlockAIOCB *acb;
        CoroutineIOCompletion co = {
            .coroutine = qemu_coroutine_self(),
        };
        acb = bs->drv->bdrv_aio_writev(bs, sector_num, qiov, nb_sectors,
                                       bdrv_co_io_em_complete, &co);
        if (acb == NULL) {
            ret = -EIO;
        } else {
            qemu_coroutine_yield();
            ret = co.ret;
        }
    }
emulate_flags:
    if (ret == 0 && (flags & BDRV_REQ_FUA)) {
        ret = bdrv_co_flush(bs);
    }
    return ret;
}

static void host_signal_handler(int host_signum, siginfo_t *info,

                                void *puc)

{

    CPUArchState *env = thread_cpu->env_ptr;

    CPUState *cpu = ENV_GET_CPU(env);

    TaskState *ts = cpu->opaque;



    int sig;

    target_siginfo_t tinfo;

    ucontext_t *uc = puc;

    struct emulated_sigtable *k;



    /* the CPU emulator uses some host signals to detect exceptions,

       we forward to it some signals */

    if ((host_signum == SIGSEGV || host_signum == SIGBUS)

        && info->si_code > 0) {

        if (cpu_signal_handler(host_signum, info, puc))

            return;

    }



    /* get target signal number */

    sig = host_to_target_signal(host_signum);

    if (sig < 1 || sig > TARGET_NSIG)

        return;

    trace_user_host_signal(env, host_signum, sig);



    rewind_if_in_safe_syscall(puc);



    host_to_target_siginfo_noswap(&tinfo, info);

    k = &ts->sigtab[sig - 1];

    k->info = tinfo;

    k->pending = sig;

    ts->signal_pending = 1;



    /* Block host signals until target signal handler entered. We

     * can't block SIGSEGV or SIGBUS while we're executing guest

     * code in case the guest code provokes one in the window between

     * now and it getting out to the main loop. Signals will be

     * unblocked again in process_pending_signals().

     */

    sigfillset(&uc->uc_sigmask);

    sigdelset(&uc->uc_sigmask, SIGSEGV);

    sigdelset(&uc->uc_sigmask, SIGBUS);



    /* interrupt the virtual CPU as soon as possible */

    cpu_exit(thread_cpu);

}

static int nbd_co_send_request(BlockDriverState *bs,

                               struct nbd_request *request,

                               QEMUIOVector *qiov, int offset)

{

    NbdClientSession *s = nbd_get_client_session(bs);

    AioContext *aio_context;

    int rc, ret;



    qemu_co_mutex_lock(&s->send_mutex);

    s->send_coroutine = qemu_coroutine_self();

    aio_context = bdrv_get_aio_context(bs);

    aio_set_fd_handler(aio_context, s->sock,

                       nbd_reply_ready, nbd_restart_write, bs);

    if (qiov) {

        if (!s->is_unix) {

            socket_set_cork(s->sock, 1);

        }

        rc = nbd_send_request(s->sock, request);

        if (rc >= 0) {

            ret = qemu_co_sendv(s->sock, qiov->iov, qiov->niov,

                                offset, request->len);

            if (ret != request->len) {

                rc = -EIO;

            }

        }

        if (!s->is_unix) {

            socket_set_cork(s->sock, 0);

        }

    } else {

        rc = nbd_send_request(s->sock, request);

    }

    aio_set_fd_handler(aio_context, s->sock, nbd_reply_ready, NULL, bs);

    s->send_coroutine = NULL;

    qemu_co_mutex_unlock(&s->send_mutex);

    return rc;

}

qio_channel_socket_accept(QIOChannelSocket *ioc,

                          Error **errp)

{

    QIOChannelSocket *cioc;



    cioc = qio_channel_socket_new();

    cioc->remoteAddrLen = sizeof(ioc->remoteAddr);

    cioc->localAddrLen = sizeof(ioc->localAddr);



 retry:

    trace_qio_channel_socket_accept(ioc);

    cioc->fd = qemu_accept(ioc->fd, (struct sockaddr *)&cioc->remoteAddr,

                           &cioc->remoteAddrLen);

    if (cioc->fd < 0) {

        trace_qio_channel_socket_accept_fail(ioc);

        if (errno == EINTR) {

            goto retry;

        }

        goto error;

    }



    if (getsockname(cioc->fd, (struct sockaddr *)&cioc->localAddr,

                    &cioc->localAddrLen) < 0) {

        error_setg_errno(errp, errno,

                         "Unable to query local socket address");

        goto error;

    }



#ifndef WIN32

    if (cioc->localAddr.ss_family == AF_UNIX) {

        QIOChannel *ioc_local = QIO_CHANNEL(cioc);

        qio_channel_set_feature(ioc_local, QIO_CHANNEL_FEATURE_FD_PASS);

    }

#endif /* WIN32 */



    trace_qio_channel_socket_accept_complete(ioc, cioc, cioc->fd);

    return cioc;



 error:

    object_unref(OBJECT(cioc));

    return NULL;

}

static void io_write(IPackDevice *ip, uint8_t addr, uint16_t val)

{

    IPOctalState *dev = IPOCTAL(ip);

    unsigned reg = val & 0xFF;

    /* addr[7:6]: block   (A-D)

       addr[7:5]: channel (a-h)

       addr[5:0]: register */

    unsigned block = addr >> 5;

    unsigned channel = addr >> 4;

    /* Big endian, accessed using 8-bit bytes at odd locations */

    unsigned offset = (addr & 0x1F) ^ 1;

    SCC2698Channel *ch = &dev->ch[channel];

    SCC2698Block *blk = &dev->blk[block];

    uint8_t old_isr = blk->isr;

    uint8_t old_imr = blk->imr;



    switch (offset) {



    case REG_MRa:

    case REG_MRb:

        ch->mr[ch->mr_idx] = reg;

        DPRINTF("Write MR%u%c 0x%x\n", ch->mr_idx + 1, channel + 'a', reg);

        ch->mr_idx = 1;

        break;



    /* Not implemented */

    case REG_CSRa:

    case REG_CSRb:

        DPRINTF("Write CSR%c: 0x%x\n", channel + 'a', reg);

        break;



    case REG_CRa:

    case REG_CRb:

        write_cr(dev, channel, reg);

        break;



    case REG_THRa:

    case REG_THRb:

        if (ch->sr & SR_TXRDY) {

            DPRINTF("Write THR%c (0x%x)\n", channel + 'a', reg);

            if (ch->dev) {

                uint8_t thr = reg;

                qemu_chr_fe_write(ch->dev, &thr, 1);

            }

        } else {

            DPRINTF("Write THR%c (0x%x), Tx disabled\n", channel + 'a', reg);

        }

        break;



    /* Not implemented */

    case REG_ACR:

        DPRINTF("Write ACR%c 0x%x\n", block + 'A', val);

        break;



    case REG_IMR:

        DPRINTF("Write IMR%c 0x%x\n", block + 'A', val);

        blk->imr = reg;

        break;



    /* Not implemented */

    case REG_OPCR:

        DPRINTF("Write OPCR%c 0x%x\n", block + 'A', val);

        break;



    default:

        DPRINTF("Write unknown/unsupported register 0x%02x %u\n", offset, val);

    }



    if (old_isr != blk->isr || old_imr != blk->imr) {

        update_irq(dev, block);

    }

}

