static void arm_cache_flush(abi_ulong start, abi_ulong last)

{

    abi_ulong addr, last1;



    if (last < start)

        return;

    addr = start;

    for(;;) {

        last1 = ((addr + TARGET_PAGE_SIZE) & TARGET_PAGE_MASK) - 1;

        if (last1 > last)

            last1 = last;

        tb_invalidate_page_range(addr, last1 + 1);

        if (last1 == last)

            break;

        addr = last1 + 1;

    }

}

Object *object_dynamic_cast(Object *obj, const char *typename)

{

    GSList *i;



    /* Check if typename is a direct ancestor */

    if (object_is_type(obj, typename)) {

        return obj;

    }



    /* Check if obj has an interface of typename */

    for (i = obj->interfaces; i; i = i->next) {

        Interface *iface = i->data;



        if (object_is_type(OBJECT(iface), typename)) {

            return OBJECT(iface);

        }

    }



    /* Check if obj is an interface and its containing object is a direct

     * ancestor of typename */

    if (object_is_type(obj, TYPE_INTERFACE)) {

        Interface *iface = INTERFACE(obj);



        if (object_is_type(iface->obj, typename)) {

            return iface->obj;

        }

    }



    return NULL;

}

void ioinst_handle_rchp(S390CPU *cpu, uint64_t reg1)

{

    int cc;

    uint8_t cssid;

    uint8_t chpid;

    int ret;

    CPUS390XState *env = &cpu->env;



    if (RCHP_REG1_RES(reg1)) {

        program_interrupt(env, PGM_OPERAND, 2);

        return;

    }



    cssid = RCHP_REG1_CSSID(reg1);

    chpid = RCHP_REG1_CHPID(reg1);



    trace_ioinst_chp_id("rchp", cssid, chpid);



    ret = css_do_rchp(cssid, chpid);



    switch (ret) {

    case -ENODEV:

        cc = 3;

        break;

    case -EBUSY:

        cc = 2;

        break;

    case 0:

        cc = 0;

        break;

    default:

        /* Invalid channel subsystem. */

        program_interrupt(env, PGM_OPERAND, 2);

        return;

    }

    setcc(cpu, cc);

}

