void disas(FILE *out, void *code, unsigned long size)

{

    unsigned long pc;

    int count;

    struct disassemble_info disasm_info;

    int (*print_insn)(bfd_vma pc, disassemble_info *info);



    INIT_DISASSEMBLE_INFO(disasm_info, out, fprintf);



    disasm_info.buffer = code;

    disasm_info.buffer_vma = (unsigned long)code;

    disasm_info.buffer_length = size;



#ifdef HOST_WORDS_BIGENDIAN

    disasm_info.endian = BFD_ENDIAN_BIG;

#else

    disasm_info.endian = BFD_ENDIAN_LITTLE;

#endif

#if defined(__i386__)

    disasm_info.mach = bfd_mach_i386_i386;

    print_insn = print_insn_i386;

#elif defined(__x86_64__)

    disasm_info.mach = bfd_mach_x86_64;

    print_insn = print_insn_i386;

#elif defined(_ARCH_PPC)

    print_insn = print_insn_ppc;

#elif defined(__alpha__)

    print_insn = print_insn_alpha;

#elif defined(__sparc__)

    print_insn = print_insn_sparc;

#if defined(__sparc_v8plus__) || defined(__sparc_v8plusa__) || defined(__sparc_v9__)

    disasm_info.mach = bfd_mach_sparc_v9b;

#endif

#elif defined(__arm__)

    print_insn = print_insn_arm;

#elif defined(__MIPSEB__)

    print_insn = print_insn_big_mips;

#elif defined(__MIPSEL__)

    print_insn = print_insn_little_mips;

#elif defined(__m68k__)

    print_insn = print_insn_m68k;

#elif defined(__s390__)

    print_insn = print_insn_s390;

#elif defined(__hppa__)

    print_insn = print_insn_hppa;

#elif defined(__ia64__)

    print_insn = print_insn_ia64;

#else

    fprintf(out, "0x%lx: Asm output not supported on this arch\n",

	    (long) code);

    return;

#endif

    for (pc = (unsigned long)code; size > 0; pc += count, size -= count) {

	fprintf(out, "0x%08lx:  ", pc);

#ifdef __arm__

        /* since data is included in the code, it is better to

           display code data too */

        fprintf(out, "%08x  ", (int)bfd_getl32((const bfd_byte *)pc));

#endif

	count = print_insn(pc, &disasm_info);

	fprintf(out, "\n");

	if (count < 0)

	    break;

    }

}

void bdrv_add_key(BlockDriverState *bs, const char *key, Error **errp)

{

    if (key) {

        if (!bdrv_is_encrypted(bs)) {

            error_setg(errp, "Node '%s' is not encrypted",

                      bdrv_get_device_or_node_name(bs));

        } else if (bdrv_set_key(bs, key) < 0) {

            error_set(errp, QERR_INVALID_PASSWORD);

        }

    } else {

        if (bdrv_key_required(bs)) {

            error_set(errp, ERROR_CLASS_DEVICE_ENCRYPTED,

                      "'%s' (%s) is encrypted",

                      bdrv_get_device_or_node_name(bs),

                      bdrv_get_encrypted_filename(bs));

        }

    }

}

static void armv7m_nvic_reset(DeviceState *dev)

{

    nvic_state *s = NVIC(dev);

    NVICClass *nc = NVIC_GET_CLASS(s);

    nc->parent_reset(dev);

    /* Common GIC reset resets to disabled; the NVIC doesn't have

     * per-CPU interfaces so mark our non-existent CPU interface

     * as enabled by default, and with a priority mask which allows

     * all interrupts through.

     */

    s->gic.cpu_enabled[0] = true;

    s->gic.priority_mask[0] = 0x100;

    /* The NVIC as a whole is always enabled. */

    s->gic.enabled = true;

    systick_reset(s);

}

static int migration_rate_limit(void *opaque)

{

    MigrationState *s = opaque;

    int ret;



    ret = qemu_file_get_error(s->file);

    if (ret) {

        return ret;

    }



    if (s->bytes_xfer >= s->xfer_limit) {

        return 1;

    }



    return 0;

}

void cpu_interrupt(CPUState *env, int mask)

{

    int old_mask;



    old_mask = env->interrupt_request;

    env->interrupt_request |= mask;



#ifndef CONFIG_USER_ONLY

    /*

     * If called from iothread context, wake the target cpu in

     * case its halted.

     */

    if (!qemu_cpu_self(env)) {

        qemu_cpu_kick(env);

        return;

    }

#endif



    if (use_icount) {

        env->icount_decr.u16.high = 0xffff;

#ifndef CONFIG_USER_ONLY

        if (!can_do_io(env)

            && (mask & ~old_mask) != 0) {

            cpu_abort(env, "Raised interrupt while not in I/O function");

        }

#endif

    } else {

        cpu_unlink_tb(env);

    }

}

static inline void tcg_out_tlb_load(TCGContext *s, TCGReg addrlo, TCGReg addrhi,

                                    int mem_index, TCGMemOp s_bits,

                                    tcg_insn_unit **label_ptr, int which)

{

    const TCGReg r0 = TCG_REG_L0;

    const TCGReg r1 = TCG_REG_L1;

    TCGType ttype = TCG_TYPE_I32;

    TCGType htype = TCG_TYPE_I32;

    int trexw = 0, hrexw = 0;



    if (TCG_TARGET_REG_BITS == 64) {

        if (TARGET_LONG_BITS == 64) {

            ttype = TCG_TYPE_I64;

            trexw = P_REXW;

        }

        if (TCG_TYPE_PTR == TCG_TYPE_I64) {

            htype = TCG_TYPE_I64;

            hrexw = P_REXW;

        }

    }



    tcg_out_mov(s, htype, r0, addrlo);

    tcg_out_mov(s, ttype, r1, addrlo);



    tcg_out_shifti(s, SHIFT_SHR + hrexw, r0,

                   TARGET_PAGE_BITS - CPU_TLB_ENTRY_BITS);



    tgen_arithi(s, ARITH_AND + trexw, r1,

                TARGET_PAGE_MASK | ((1 << s_bits) - 1), 0);

    tgen_arithi(s, ARITH_AND + hrexw, r0,

                (CPU_TLB_SIZE - 1) << CPU_TLB_ENTRY_BITS, 0);



    tcg_out_modrm_sib_offset(s, OPC_LEA + hrexw, r0, TCG_AREG0, r0, 0,

                             offsetof(CPUArchState, tlb_table[mem_index][0])

                             + which);



    /* cmp 0(r0), r1 */

    tcg_out_modrm_offset(s, OPC_CMP_GvEv + trexw, r1, r0, 0);



    /* Prepare for both the fast path add of the tlb addend, and the slow

       path function argument setup.  There are two cases worth note:

       For 32-bit guest and x86_64 host, MOVL zero-extends the guest address

       before the fastpath ADDQ below.  For 64-bit guest and x32 host, MOVQ

       copies the entire guest address for the slow path, while truncation

       for the 32-bit host happens with the fastpath ADDL below.  */

    tcg_out_mov(s, ttype, r1, addrlo);



    /* jne slow_path */

    tcg_out_opc(s, OPC_JCC_long + JCC_JNE, 0, 0, 0);

    label_ptr[0] = s->code_ptr;

    s->code_ptr += 4;



    if (TARGET_LONG_BITS > TCG_TARGET_REG_BITS) {

        /* cmp 4(r0), addrhi */

        tcg_out_modrm_offset(s, OPC_CMP_GvEv, addrhi, r0, 4);



        /* jne slow_path */

        tcg_out_opc(s, OPC_JCC_long + JCC_JNE, 0, 0, 0);

        label_ptr[1] = s->code_ptr;

        s->code_ptr += 4;

    }



    /* TLB Hit.  */



    /* add addend(r0), r1 */

    tcg_out_modrm_offset(s, OPC_ADD_GvEv + hrexw, r1, r0,

                         offsetof(CPUTLBEntry, addend) - which);

}

static inline void t_gen_sext(TCGv d, TCGv s, int size)

{

	if (size == 1)

		tcg_gen_ext8s_i32(d, s);

	else if (size == 2)

		tcg_gen_ext16s_i32(d, s);

	else if(GET_TCGV(d) != GET_TCGV(s))

		tcg_gen_mov_tl(d, s);

}

static int vio_make_devnode(VIOsPAPRDevice *dev,

                            void *fdt)

{

    VIOsPAPRDeviceInfo *info = (VIOsPAPRDeviceInfo *)qdev_get_info(&dev->qdev);

    int vdevice_off, node_off, ret;

    char *dt_name;



    vdevice_off = fdt_path_offset(fdt, "/vdevice");

    if (vdevice_off < 0) {

        return vdevice_off;

    }



    dt_name = vio_format_dev_name(dev);

    if (!dt_name) {

        return -ENOMEM;

    }



    node_off = fdt_add_subnode(fdt, vdevice_off, dt_name);

    free(dt_name);

    if (node_off < 0) {

        return node_off;

    }



    ret = fdt_setprop_cell(fdt, node_off, "reg", dev->reg);

    if (ret < 0) {

        return ret;

    }



    if (info->dt_type) {

        ret = fdt_setprop_string(fdt, node_off, "device_type",

                                 info->dt_type);

        if (ret < 0) {

            return ret;

        }

    }



    if (info->dt_compatible) {

        ret = fdt_setprop_string(fdt, node_off, "compatible",

                                 info->dt_compatible);

        if (ret < 0) {

            return ret;

        }

    }



    if (dev->qirq) {

        uint32_t ints_prop[] = {cpu_to_be32(dev->vio_irq_num), 0};



        ret = fdt_setprop(fdt, node_off, "interrupts", ints_prop,

                          sizeof(ints_prop));

        if (ret < 0) {

            return ret;

        }

    }



    if (dev->rtce_window_size) {

        uint32_t dma_prop[] = {cpu_to_be32(dev->reg),

                               0, 0,

                               0, cpu_to_be32(dev->rtce_window_size)};



        ret = fdt_setprop_cell(fdt, node_off, "ibm,#dma-address-cells", 2);

        if (ret < 0) {

            return ret;

        }



        ret = fdt_setprop_cell(fdt, node_off, "ibm,#dma-size-cells", 2);

        if (ret < 0) {

            return ret;

        }



        ret = fdt_setprop(fdt, node_off, "ibm,my-dma-window", dma_prop,

                          sizeof(dma_prop));

        if (ret < 0) {

            return ret;

        }

    }



    if (info->devnode) {

        ret = (info->devnode)(dev, fdt, node_off);

        if (ret < 0) {

            return ret;

        }

    }



    return node_off;

}

void mkimg(const char *file, const char *fmt, unsigned size_mb)

{

    gchar *cli;

    bool ret;

    int rc;

    GError *err = NULL;

    char *qemu_img_path;

    gchar *out, *out2;

    char *abs_path;



    qemu_img_path = getenv("QTEST_QEMU_IMG");

    abs_path = realpath(qemu_img_path, NULL);

    assert(qemu_img_path);



    cli = g_strdup_printf("%s create -f %s %s %uM", abs_path,

                          fmt, file, size_mb);

    ret = g_spawn_command_line_sync(cli, &out, &out2, &rc, &err);

    if (err) {

        fprintf(stderr, "%s\n", err->message);

        g_error_free(err);

    }

    g_assert(ret && !err);



    /* In glib 2.34, we have g_spawn_check_exit_status. in 2.12, we don't.

     * glib 2.43.91 implementation assumes that any non-zero is an error for

     * windows, but uses extra precautions for Linux. However,

     * 0 is only possible if the program exited normally, so that should be

     * sufficient for our purposes on all platforms, here. */

    if (rc) {

        fprintf(stderr, "qemu-img returned status code %d\n", rc);

    }

    g_assert(!rc);



    g_free(out);

    g_free(out2);

    g_free(cli);

    free(abs_path);

}

static void cris_alu_op_exec(DisasContext *dc, int op, 

                   TCGv dst, TCGv a, TCGv b, int size)

{

    /* Emit the ALU insns.  */

    switch (op) {

    case CC_OP_ADD:

        tcg_gen_add_tl(dst, a, b);

        /* Extended arithmetics.  */

        t_gen_addx_carry(dc, dst);

        break;

    case CC_OP_ADDC:

        tcg_gen_add_tl(dst, a, b);

        t_gen_add_flag(dst, 0); /* C_FLAG.  */

        break;

    case CC_OP_MCP:

        tcg_gen_add_tl(dst, a, b);

        t_gen_add_flag(dst, 8); /* R_FLAG.  */

        break;

    case CC_OP_SUB:

        tcg_gen_sub_tl(dst, a, b);

        /* Extended arithmetics.  */

        t_gen_subx_carry(dc, dst);

        break;

    case CC_OP_MOVE:

        tcg_gen_mov_tl(dst, b);

        break;

    case CC_OP_OR:

        tcg_gen_or_tl(dst, a, b);

        break;

    case CC_OP_AND:

        tcg_gen_and_tl(dst, a, b);

        break;

    case CC_OP_XOR:

        tcg_gen_xor_tl(dst, a, b);

        break;

    case CC_OP_LSL:

        t_gen_lsl(dst, a, b);

        break;

    case CC_OP_LSR:

        t_gen_lsr(dst, a, b);

        break;

    case CC_OP_ASR:

        t_gen_asr(dst, a, b);

        break;

    case CC_OP_NEG:

        tcg_gen_neg_tl(dst, b);

        /* Extended arithmetics.  */

        t_gen_subx_carry(dc, dst);

        break;

    case CC_OP_LZ:

        gen_helper_lz(dst, b);

        break;

    case CC_OP_MULS:

        tcg_gen_muls2_tl(dst, cpu_PR[PR_MOF], a, b);

        break;

    case CC_OP_MULU:

        tcg_gen_mulu2_tl(dst, cpu_PR[PR_MOF], a, b);

        break;

    case CC_OP_DSTEP:

        t_gen_cris_dstep(dst, a, b);

        break;

    case CC_OP_MSTEP:

        t_gen_cris_mstep(dst, a, b, cpu_PR[PR_CCS]);

        break;

    case CC_OP_BOUND:

    {

        int l1;

        l1 = gen_new_label();

        tcg_gen_mov_tl(dst, a);

        tcg_gen_brcond_tl(TCG_COND_LEU, a, b, l1);

        tcg_gen_mov_tl(dst, b);

        gen_set_label(l1);

    }

        break;

    case CC_OP_CMP:

        tcg_gen_sub_tl(dst, a, b);

        /* Extended arithmetics.  */

        t_gen_subx_carry(dc, dst);

        break;

    default:

        qemu_log("illegal ALU op.\n");

        BUG();

        break;

    }



    if (size == 1) {

        tcg_gen_andi_tl(dst, dst, 0xff);

    } else if (size == 2) {

        tcg_gen_andi_tl(dst, dst, 0xffff);

    }

}

static void blockdev_backup_prepare(BlkTransactionState *common, Error **errp)

{

    BlockdevBackupState *state = DO_UPCAST(BlockdevBackupState, common, common);

    BlockdevBackup *backup;

    BlockBackend *blk, *target;

    Error *local_err = NULL;



    assert(common->action->kind == TRANSACTION_ACTION_KIND_BLOCKDEV_BACKUP);

    backup = common->action->blockdev_backup;



    blk = blk_by_name(backup->device);

    if (!blk) {

        error_setg(errp, "Device '%s' not found", backup->device);

        return;

    }



    if (!blk_is_available(blk)) {

        error_setg(errp, QERR_DEVICE_HAS_NO_MEDIUM, backup->device);

        return;

    }



    target = blk_by_name(backup->target);

    if (!target) {

        error_setg(errp, "Device '%s' not found", backup->target);

        return;

    }



    /* AioContext is released in .clean() */

    state->aio_context = blk_get_aio_context(blk);

    if (state->aio_context != blk_get_aio_context(target)) {

        state->aio_context = NULL;

        error_setg(errp, "Backup between two IO threads is not implemented");

        return;

    }

    aio_context_acquire(state->aio_context);

    state->bs = blk_bs(blk);

    bdrv_drained_begin(state->bs);



    qmp_blockdev_backup(backup->device, backup->target,

                        backup->sync,

                        backup->has_speed, backup->speed,

                        backup->has_on_source_error, backup->on_source_error,

                        backup->has_on_target_error, backup->on_target_error,

                        &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }



    state->job = state->bs->job;

}

static int zipl_magic(uint8_t *ptr)

{

    uint32_t *p = (void*)ptr;

    uint32_t *z = (void*)ZIPL_MAGIC;



    if (*p != *z) {

        debug_print_int("invalid magic", *p);

        virtio_panic("invalid magic");

    }



    return 1;

}

static void bt_hid_interrupt_sdu(void *opaque, const uint8_t *data, int len)

{

    struct bt_hid_device_s *hid = opaque;



    if (len > BT_HID_MTU || len < 1)

        goto bad;

    if ((data[0] & 3) != BT_DATA_OUTPUT)

        goto bad;

    if ((data[0] >> 4) == BT_DATA) {

        if (hid->intr_state)

            goto bad;



        hid->data_type = BT_DATA_OUTPUT;

        hid->intrdataout.len = 0;

    } else if ((data[0] >> 4) == BT_DATC) {

        if (!hid->intr_state)

            goto bad;

    } else

        goto bad;



    memcpy(hid->intrdataout.buffer + hid->intrdataout.len, data + 1, len - 1);

    hid->intrdataout.len += len - 1;

    hid->intr_state = (len == BT_HID_MTU);

    if (!hid->intr_state) {

        memcpy(hid->dataout.buffer, hid->intrdataout.buffer,

                        hid->dataout.len = hid->intrdataout.len);

        bt_hid_out(hid);

    }



    return;

bad:

    fprintf(stderr, "%s: bad transaction on Interrupt channel.\n",

                    __func__);

}

static void decode_opc (CPUState *env, DisasContext *ctx)

{

    int32_t offset;

    int rs, rt, rd, sa;

    uint32_t op, op1, op2;

    int16_t imm;



    /* make sure instructions are on a word boundary */

    if (ctx->pc & 0x3) {

        env->CP0_BadVAddr = ctx->pc;

        generate_exception(ctx, EXCP_AdEL);

        return;

    }



    if ((ctx->hflags & MIPS_HFLAG_BMASK) == MIPS_HFLAG_BL) {

        int l1;

        /* Handle blikely not taken case */

        MIPS_DEBUG("blikely condition (" TARGET_FMT_lx ")", ctx->pc + 4);

        l1 = gen_new_label();

        gen_op_jnz_T2(l1);

        gen_op_save_state(ctx->hflags & ~MIPS_HFLAG_BMASK);

        gen_goto_tb(ctx, 1, ctx->pc + 4);

        gen_set_label(l1);

    }

    op = MASK_OP_MAJOR(ctx->opcode);

    rs = (ctx->opcode >> 21) & 0x1f;

    rt = (ctx->opcode >> 16) & 0x1f;

    rd = (ctx->opcode >> 11) & 0x1f;

    sa = (ctx->opcode >> 6) & 0x1f;

    imm = (int16_t)ctx->opcode;

    switch (op) {

    case OPC_SPECIAL:

        op1 = MASK_SPECIAL(ctx->opcode);

        switch (op1) {

        case OPC_SLL:          /* Arithmetic with immediate */

        case OPC_SRL ... OPC_SRA:

            gen_arith_imm(env, ctx, op1, rd, rt, sa);

            break;

        case OPC_MOVZ ... OPC_MOVN:

            check_insn(env, ctx, ISA_MIPS4 | ISA_MIPS32);

        case OPC_SLLV:         /* Arithmetic */

        case OPC_SRLV ... OPC_SRAV:

        case OPC_ADD ... OPC_NOR:

        case OPC_SLT ... OPC_SLTU:

            gen_arith(env, ctx, op1, rd, rs, rt);

            break;

        case OPC_MULT ... OPC_DIVU:

            gen_muldiv(ctx, op1, rs, rt);

            break;

        case OPC_JR ... OPC_JALR:

            gen_compute_branch(ctx, op1, rs, rd, sa);

            return;

        case OPC_TGE ... OPC_TEQ: /* Traps */

        case OPC_TNE:

            gen_trap(ctx, op1, rs, rt, -1);

            break;

        case OPC_MFHI:          /* Move from HI/LO */

        case OPC_MFLO:

            gen_HILO(ctx, op1, rd);

            break;

        case OPC_MTHI:

        case OPC_MTLO:          /* Move to HI/LO */

            gen_HILO(ctx, op1, rs);

            break;

        case OPC_PMON:          /* Pmon entry point, also R4010 selsl */

#ifdef MIPS_STRICT_STANDARD

            MIPS_INVAL("PMON / selsl");

            generate_exception(ctx, EXCP_RI);

#else

            gen_op_pmon(sa);

#endif

            break;

        case OPC_SYSCALL:

            generate_exception(ctx, EXCP_SYSCALL);

            break;

        case OPC_BREAK:

            generate_exception(ctx, EXCP_BREAK);

            break;

        case OPC_SPIM:

#ifdef MIPS_STRICT_STANDARD

            MIPS_INVAL("SPIM");

            generate_exception(ctx, EXCP_RI);

#else

           /* Implemented as RI exception for now. */

            MIPS_INVAL("spim (unofficial)");

            generate_exception(ctx, EXCP_RI);

#endif

            break;

        case OPC_SYNC:

            /* Treat as NOP. */

            break;



        case OPC_MOVCI:

            check_insn(env, ctx, ISA_MIPS4 | ISA_MIPS32);

            if (env->CP0_Config1 & (1 << CP0C1_FP)) {

                save_cpu_state(ctx, 1);

                check_cp1_enabled(ctx);

                gen_movci(ctx, rd, rs, (ctx->opcode >> 18) & 0x7,

                          (ctx->opcode >> 16) & 1);

            } else {

                generate_exception_err(ctx, EXCP_CpU, 1);

            }

            break;



#if defined(TARGET_MIPSN32) || defined(TARGET_MIPS64)

       /* MIPS64 specific opcodes */

        case OPC_DSLL:

        case OPC_DSRL ... OPC_DSRA:

        case OPC_DSLL32:

        case OPC_DSRL32 ... OPC_DSRA32:

            check_insn(env, ctx, ISA_MIPS3);

            check_mips_64(ctx);

            gen_arith_imm(env, ctx, op1, rd, rt, sa);

            break;

        case OPC_DSLLV:

        case OPC_DSRLV ... OPC_DSRAV:

        case OPC_DADD ... OPC_DSUBU:

            check_insn(env, ctx, ISA_MIPS3);

            check_mips_64(ctx);

            gen_arith(env, ctx, op1, rd, rs, rt);

            break;

        case OPC_DMULT ... OPC_DDIVU:

            check_insn(env, ctx, ISA_MIPS3);

            check_mips_64(ctx);

            gen_muldiv(ctx, op1, rs, rt);

            break;

#endif

        default:            /* Invalid */

            MIPS_INVAL("special");

            generate_exception(ctx, EXCP_RI);

            break;

        }

        break;

    case OPC_SPECIAL2:

        op1 = MASK_SPECIAL2(ctx->opcode);

        switch (op1) {

        case OPC_MADD ... OPC_MADDU: /* Multiply and add/sub */

        case OPC_MSUB ... OPC_MSUBU:

            check_insn(env, ctx, ISA_MIPS32);

            gen_muldiv(ctx, op1, rs, rt);

            break;

        case OPC_MUL:

            gen_arith(env, ctx, op1, rd, rs, rt);

            break;

        case OPC_CLZ ... OPC_CLO:

            check_insn(env, ctx, ISA_MIPS32);

            gen_cl(ctx, op1, rd, rs);

            break;

        case OPC_SDBBP:

            /* XXX: not clear which exception should be raised

             *      when in debug mode...

             */

            check_insn(env, ctx, ISA_MIPS32);

            if (!(ctx->hflags & MIPS_HFLAG_DM)) {

                generate_exception(ctx, EXCP_DBp);

            } else {

                generate_exception(ctx, EXCP_DBp);

            }

            /* Treat as NOP. */

            break;

#if defined(TARGET_MIPSN32) || defined(TARGET_MIPS64)

        case OPC_DCLZ ... OPC_DCLO:

            check_insn(env, ctx, ISA_MIPS64);

            check_mips_64(ctx);

            gen_cl(ctx, op1, rd, rs);

            break;

#endif

        default:            /* Invalid */

            MIPS_INVAL("special2");

            generate_exception(ctx, EXCP_RI);

            break;

        }

        break;

    case OPC_SPECIAL3:

         op1 = MASK_SPECIAL3(ctx->opcode);

         switch (op1) {

         case OPC_EXT:

         case OPC_INS:

             check_insn(env, ctx, ISA_MIPS32R2);

             gen_bitops(ctx, op1, rt, rs, sa, rd);

             break;

         case OPC_BSHFL:

             check_insn(env, ctx, ISA_MIPS32R2);

             op2 = MASK_BSHFL(ctx->opcode);

             switch (op2) {

             case OPC_WSBH:

                 GEN_LOAD_REG_TN(T1, rt);

                 gen_op_wsbh();

                 break;

             case OPC_SEB:

                 GEN_LOAD_REG_TN(T1, rt);

                 gen_op_seb();

                 break;

             case OPC_SEH:

                 GEN_LOAD_REG_TN(T1, rt);

                 gen_op_seh();

                 break;

             default:            /* Invalid */

                 MIPS_INVAL("bshfl");

                 generate_exception(ctx, EXCP_RI);

                 break;

            }

            GEN_STORE_TN_REG(rd, T0);

            break;

        case OPC_RDHWR:

            check_insn(env, ctx, ISA_MIPS32R2);

            switch (rd) {

            case 0:

                save_cpu_state(ctx, 1);

                gen_op_rdhwr_cpunum();

                break;

            case 1:

                save_cpu_state(ctx, 1);

                gen_op_rdhwr_synci_step();

                break;

            case 2:

                save_cpu_state(ctx, 1);

                gen_op_rdhwr_cc();

                break;

            case 3:

                save_cpu_state(ctx, 1);

                gen_op_rdhwr_ccres();

                break;

            case 29:

#if defined (CONFIG_USER_ONLY)

                gen_op_tls_value();

                break;

#endif

            default:            /* Invalid */

                MIPS_INVAL("rdhwr");

                generate_exception(ctx, EXCP_RI);

                break;

            }

            GEN_STORE_TN_REG(rt, T0);

            break;

        case OPC_FORK:

            check_mips_mt(env, ctx);

            GEN_LOAD_REG_TN(T0, rt);

            GEN_LOAD_REG_TN(T1, rs);

            gen_op_fork();

            break;

        case OPC_YIELD:

            check_mips_mt(env, ctx);

            GEN_LOAD_REG_TN(T0, rs);

            gen_op_yield();

            GEN_STORE_TN_REG(rd, T0);

            break;

#if defined(TARGET_MIPSN32) || defined(TARGET_MIPS64)

        case OPC_DEXTM ... OPC_DEXT:

        case OPC_DINSM ... OPC_DINS:

            check_insn(env, ctx, ISA_MIPS64R2);

            check_mips_64(ctx);

            gen_bitops(ctx, op1, rt, rs, sa, rd);

            break;

        case OPC_DBSHFL:

            check_insn(env, ctx, ISA_MIPS64R2);

            check_mips_64(ctx);

            op2 = MASK_DBSHFL(ctx->opcode);

            switch (op2) {

            case OPC_DSBH:

                GEN_LOAD_REG_TN(T1, rt);

                gen_op_dsbh();

                break;

            case OPC_DSHD:

                GEN_LOAD_REG_TN(T1, rt);

                gen_op_dshd();

                break;

            default:            /* Invalid */

                MIPS_INVAL("dbshfl");

                generate_exception(ctx, EXCP_RI);

                break;

            }

            GEN_STORE_TN_REG(rd, T0);

#endif

        default:            /* Invalid */

            MIPS_INVAL("special3");

            generate_exception(ctx, EXCP_RI);

            break;

        }

        break;

    case OPC_REGIMM:

        op1 = MASK_REGIMM(ctx->opcode);

        switch (op1) {

        case OPC_BLTZ ... OPC_BGEZL: /* REGIMM branches */

        case OPC_BLTZAL ... OPC_BGEZALL:

            gen_compute_branch(ctx, op1, rs, -1, imm << 2);

            return;

        case OPC_TGEI ... OPC_TEQI: /* REGIMM traps */

        case OPC_TNEI:

            gen_trap(ctx, op1, rs, -1, imm);

            break;

        case OPC_SYNCI:

            check_insn(env, ctx, ISA_MIPS32R2);

            /* Treat as NOP. */

            break;

        default:            /* Invalid */

            MIPS_INVAL("regimm");

            generate_exception(ctx, EXCP_RI);

            break;

        }

        break;

    case OPC_CP0:

        check_cp0_enabled(ctx);

        op1 = MASK_CP0(ctx->opcode);

        switch (op1) {

        case OPC_MFC0:

        case OPC_MTC0:

        case OPC_MFTR:

        case OPC_MTTR:

#if defined(TARGET_MIPSN32) || defined(TARGET_MIPS64)

        case OPC_DMFC0:

        case OPC_DMTC0:

#endif

            gen_cp0(env, ctx, op1, rt, rd);

            break;

        case OPC_C0_FIRST ... OPC_C0_LAST:

            gen_cp0(env, ctx, MASK_C0(ctx->opcode), rt, rd);

            break;

        case OPC_MFMC0:

            op2 = MASK_MFMC0(ctx->opcode);

            switch (op2) {

            case OPC_DMT:

                check_mips_mt(env, ctx);

                gen_op_dmt();

                break;

            case OPC_EMT:

                check_mips_mt(env, ctx);

                gen_op_emt();

                break;

            case OPC_DVPE:

                check_mips_mt(env, ctx);

                gen_op_dvpe();

                break;

            case OPC_EVPE:

                check_mips_mt(env, ctx);

                gen_op_evpe();

                break;

            case OPC_DI:

                check_insn(env, ctx, ISA_MIPS32R2);

                save_cpu_state(ctx, 1);

                gen_op_di();

                /* Stop translation as we may have switched the execution mode */

                ctx->bstate = BS_STOP;

                break;

            case OPC_EI:

                check_insn(env, ctx, ISA_MIPS32R2);

                save_cpu_state(ctx, 1);

                gen_op_ei();

                /* Stop translation as we may have switched the execution mode */

                ctx->bstate = BS_STOP;

                break;

            default:            /* Invalid */

                MIPS_INVAL("mfmc0");

                generate_exception(ctx, EXCP_RI);

                break;

            }

            GEN_STORE_TN_REG(rt, T0);

            break;

        case OPC_RDPGPR:

            check_insn(env, ctx, ISA_MIPS32R2);

            GEN_LOAD_SRSREG_TN(T0, rt);

            GEN_STORE_TN_REG(rd, T0);

            break;

        case OPC_WRPGPR:

            check_insn(env, ctx, ISA_MIPS32R2);

            GEN_LOAD_REG_TN(T0, rt);

            GEN_STORE_TN_SRSREG(rd, T0);

            break;

        default:

            MIPS_INVAL("cp0");

            generate_exception(ctx, EXCP_RI);

            break;

        }

        break;

    case OPC_ADDI ... OPC_LUI: /* Arithmetic with immediate opcode */

         gen_arith_imm(env, ctx, op, rt, rs, imm);

         break;

    case OPC_J ... OPC_JAL: /* Jump */

         offset = (int32_t)(ctx->opcode & 0x3FFFFFF) << 2;

         gen_compute_branch(ctx, op, rs, rt, offset);

         return;

    case OPC_BEQ ... OPC_BGTZ: /* Branch */

    case OPC_BEQL ... OPC_BGTZL:

         gen_compute_branch(ctx, op, rs, rt, imm << 2);

         return;

    case OPC_LB ... OPC_LWR: /* Load and stores */

    case OPC_SB ... OPC_SW:

    case OPC_SWR:

    case OPC_LL:

    case OPC_SC:

         gen_ldst(ctx, op, rt, rs, imm);

         break;

    case OPC_CACHE:

        check_insn(env, ctx, ISA_MIPS3 | ISA_MIPS32);

        /* Treat as NOP. */

        break;

    case OPC_PREF:

        check_insn(env, ctx, ISA_MIPS4 | ISA_MIPS32);

        /* Treat as NOP. */

        break;



    /* Floating point (COP1). */

    case OPC_LWC1:

    case OPC_LDC1:

    case OPC_SWC1:

    case OPC_SDC1:

        if (env->CP0_Config1 & (1 << CP0C1_FP)) {

            save_cpu_state(ctx, 1);

            check_cp1_enabled(ctx);

            gen_flt_ldst(ctx, op, rt, rs, imm);

        } else {

            generate_exception_err(ctx, EXCP_CpU, 1);

        }

        break;



    case OPC_CP1:

        if (env->CP0_Config1 & (1 << CP0C1_FP)) {

            save_cpu_state(ctx, 1);

            check_cp1_enabled(ctx);

            op1 = MASK_CP1(ctx->opcode);

            switch (op1) {

            case OPC_MFHC1:

            case OPC_MTHC1:

                check_insn(env, ctx, ISA_MIPS32R2);

            case OPC_MFC1:

            case OPC_CFC1:

            case OPC_MTC1:

            case OPC_CTC1:

                gen_cp1(ctx, op1, rt, rd);

                break;

#if defined(TARGET_MIPSN32) || defined(TARGET_MIPS64)

            case OPC_DMFC1:

            case OPC_DMTC1:

                check_insn(env, ctx, ISA_MIPS3);

                gen_cp1(ctx, op1, rt, rd);

                break;

#endif

            case OPC_BC1ANY2:

            case OPC_BC1ANY4:

                check_cp1_3d(env, ctx);

                /* fall through */

            case OPC_BC1:

                gen_compute_branch1(env, ctx, MASK_BC1(ctx->opcode),

                                    (rt >> 2) & 0x7, imm << 2);

                return;

            case OPC_S_FMT:

            case OPC_D_FMT:

            case OPC_W_FMT:

            case OPC_L_FMT:

            case OPC_PS_FMT:

                gen_farith(ctx, MASK_CP1_FUNC(ctx->opcode), rt, rd, sa,

                           (imm >> 8) & 0x7);

                break;

            default:

                MIPS_INVAL("cp1");

                generate_exception (ctx, EXCP_RI);

                break;

            }

        } else {

            generate_exception_err(ctx, EXCP_CpU, 1);

        }

        break;



    /* COP2.  */

    case OPC_LWC2:

    case OPC_LDC2:

    case OPC_SWC2:

    case OPC_SDC2:

    case OPC_CP2:

        /* COP2: Not implemented. */

        generate_exception_err(ctx, EXCP_CpU, 2);

        break;



    case OPC_CP3:

        if (env->CP0_Config1 & (1 << CP0C1_FP)) {

            save_cpu_state(ctx, 1);

            check_cp1_enabled(ctx);

            op1 = MASK_CP3(ctx->opcode);

            switch (op1) {

            case OPC_LWXC1:

            case OPC_LDXC1:

            case OPC_LUXC1:

            case OPC_SWXC1:

            case OPC_SDXC1:

            case OPC_SUXC1:

                gen_flt3_ldst(ctx, op1, sa, rd, rs, rt);

                break;

            case OPC_PREFX:

                /* Treat as NOP. */

                break;

            case OPC_ALNV_PS:

            case OPC_MADD_S:

            case OPC_MADD_D:

            case OPC_MADD_PS:

            case OPC_MSUB_S:

            case OPC_MSUB_D:

            case OPC_MSUB_PS:

            case OPC_NMADD_S:

            case OPC_NMADD_D:

            case OPC_NMADD_PS:

            case OPC_NMSUB_S:

            case OPC_NMSUB_D:

            case OPC_NMSUB_PS:

                gen_flt3_arith(ctx, op1, sa, rs, rd, rt);

                break;

            default:

                MIPS_INVAL("cp3");

                generate_exception (ctx, EXCP_RI);

                break;

            }

        } else {

            generate_exception_err(ctx, EXCP_CpU, 1);

        }

        break;



#if defined(TARGET_MIPSN32) || defined(TARGET_MIPS64)

    /* MIPS64 opcodes */

    case OPC_LWU:

    case OPC_LDL ... OPC_LDR:

    case OPC_SDL ... OPC_SDR:

    case OPC_LLD:

    case OPC_LD:

    case OPC_SCD:

    case OPC_SD:

        check_insn(env, ctx, ISA_MIPS3);

        check_mips_64(ctx);

        gen_ldst(ctx, op, rt, rs, imm);

        break;

    case OPC_DADDI ... OPC_DADDIU:

        check_insn(env, ctx, ISA_MIPS3);

        check_mips_64(ctx);

        gen_arith_imm(env, ctx, op, rt, rs, imm);

        break;

#endif

    case OPC_JALX:

        check_insn(env, ctx, ASE_MIPS16);

        /* MIPS16: Not implemented. */

    case OPC_MDMX:

        check_insn(env, ctx, ASE_MDMX);

        /* MDMX: Not implemented. */

    default:            /* Invalid */

        MIPS_INVAL("major opcode");

        generate_exception(ctx, EXCP_RI);

        break;

    }

    if (ctx->hflags & MIPS_HFLAG_BMASK) {

        int hflags = ctx->hflags & MIPS_HFLAG_BMASK;

        /* Branches completion */

        ctx->hflags &= ~MIPS_HFLAG_BMASK;

        ctx->bstate = BS_BRANCH;

        save_cpu_state(ctx, 0);

        switch (hflags) {

        case MIPS_HFLAG_B:

            /* unconditional branch */

            MIPS_DEBUG("unconditional branch");

            gen_goto_tb(ctx, 0, ctx->btarget);

            break;

        case MIPS_HFLAG_BL:

            /* blikely taken case */

            MIPS_DEBUG("blikely branch taken");

            gen_goto_tb(ctx, 0, ctx->btarget);

            break;

        case MIPS_HFLAG_BC:

            /* Conditional branch */

            MIPS_DEBUG("conditional branch");

            {

              int l1;

              l1 = gen_new_label();

              gen_op_jnz_T2(l1);

              gen_goto_tb(ctx, 1, ctx->pc + 4);

              gen_set_label(l1);

              gen_goto_tb(ctx, 0, ctx->btarget);

            }

            break;

        case MIPS_HFLAG_BR:

            /* unconditional branch to register */

            MIPS_DEBUG("branch to register");

            gen_op_breg();

            gen_op_reset_T0();

            gen_op_exit_tb();

            break;

        default:

            MIPS_DEBUG("unknown branch");

            break;

        }

    }

}

static void port92_write(void *opaque, hwaddr addr, uint64_t val,

                         unsigned size)

{

    Port92State *s = opaque;

    int oldval = s->outport;



    DPRINTF("port92: write 0x%02" PRIx64 "\n", val);

    s->outport = val;

    qemu_set_irq(*s->a20_out, (val >> 1) & 1);

    if ((val & 1) && !(oldval & 1)) {

        qemu_system_reset_request();

    }

}

static uint64_t coroutine_fn mirror_iteration(MirrorBlockJob *s)

{

    BlockDriverState *source = blk_bs(s->common.blk);

    int64_t sector_num, first_chunk;

    uint64_t delay_ns = 0;

    /* At least the first dirty chunk is mirrored in one iteration. */

    int nb_chunks = 1;

    int64_t end = s->bdev_length / BDRV_SECTOR_SIZE;

    int sectors_per_chunk = s->granularity >> BDRV_SECTOR_BITS;

    bool write_zeroes_ok = bdrv_can_write_zeroes_with_unmap(blk_bs(s->target));



    sector_num = hbitmap_iter_next(&s->hbi);

    if (sector_num < 0) {

        bdrv_dirty_iter_init(s->dirty_bitmap, &s->hbi);

        sector_num = hbitmap_iter_next(&s->hbi);

        trace_mirror_restart_iter(s, bdrv_get_dirty_count(s->dirty_bitmap));

        assert(sector_num >= 0);

    }



    first_chunk = sector_num / sectors_per_chunk;

    while (test_bit(first_chunk, s->in_flight_bitmap)) {

        trace_mirror_yield_in_flight(s, sector_num, s->in_flight);

        mirror_wait_for_io(s);

    }



    block_job_pause_point(&s->common);



    /* Find the number of consective dirty chunks following the first dirty

     * one, and wait for in flight requests in them. */

    while (nb_chunks * sectors_per_chunk < (s->buf_size >> BDRV_SECTOR_BITS)) {

        int64_t hbitmap_next;

        int64_t next_sector = sector_num + nb_chunks * sectors_per_chunk;

        int64_t next_chunk = next_sector / sectors_per_chunk;

        if (next_sector >= end ||

            !bdrv_get_dirty(source, s->dirty_bitmap, next_sector)) {

            break;

        }

        if (test_bit(next_chunk, s->in_flight_bitmap)) {

            break;

        }



        hbitmap_next = hbitmap_iter_next(&s->hbi);

        if (hbitmap_next > next_sector || hbitmap_next < 0) {

            /* The bitmap iterator's cache is stale, refresh it */

            bdrv_set_dirty_iter(&s->hbi, next_sector);

            hbitmap_next = hbitmap_iter_next(&s->hbi);

        }

        assert(hbitmap_next == next_sector);

        nb_chunks++;

    }



    /* Clear dirty bits before querying the block status, because

     * calling bdrv_get_block_status_above could yield - if some blocks are

     * marked dirty in this window, we need to know.

     */

    bdrv_reset_dirty_bitmap(s->dirty_bitmap, sector_num,

                            nb_chunks * sectors_per_chunk);

    bitmap_set(s->in_flight_bitmap, sector_num / sectors_per_chunk, nb_chunks);

    while (nb_chunks > 0 && sector_num < end) {

        int ret;

        int io_sectors, io_sectors_acct;

        BlockDriverState *file;

        enum MirrorMethod {

            MIRROR_METHOD_COPY,

            MIRROR_METHOD_ZERO,

            MIRROR_METHOD_DISCARD

        } mirror_method = MIRROR_METHOD_COPY;



        assert(!(sector_num % sectors_per_chunk));

        ret = bdrv_get_block_status_above(source, NULL, sector_num,

                                          nb_chunks * sectors_per_chunk,

                                          &io_sectors, &file);

        if (ret < 0) {

            io_sectors = nb_chunks * sectors_per_chunk;

        }



        io_sectors -= io_sectors % sectors_per_chunk;

        if (io_sectors < sectors_per_chunk) {

            io_sectors = sectors_per_chunk;

        } else if (ret >= 0 && !(ret & BDRV_BLOCK_DATA)) {

            int64_t target_sector_num;

            int target_nb_sectors;

            bdrv_round_sectors_to_clusters(blk_bs(s->target), sector_num,

                                           io_sectors,  &target_sector_num,

                                           &target_nb_sectors);

            if (target_sector_num == sector_num &&

                target_nb_sectors == io_sectors) {

                mirror_method = ret & BDRV_BLOCK_ZERO ?

                                    MIRROR_METHOD_ZERO :

                                    MIRROR_METHOD_DISCARD;

            }

        }



        while (s->in_flight >= MAX_IN_FLIGHT) {

            trace_mirror_yield_in_flight(s, sector_num, s->in_flight);

            mirror_wait_for_io(s);

        }



        mirror_clip_sectors(s, sector_num, &io_sectors);

        switch (mirror_method) {

        case MIRROR_METHOD_COPY:

            io_sectors = mirror_do_read(s, sector_num, io_sectors);

            io_sectors_acct = io_sectors;

            break;

        case MIRROR_METHOD_ZERO:

        case MIRROR_METHOD_DISCARD:

            mirror_do_zero_or_discard(s, sector_num, io_sectors,

                                      mirror_method == MIRROR_METHOD_DISCARD);

            if (write_zeroes_ok) {

                io_sectors_acct = 0;

            } else {

                io_sectors_acct = io_sectors;

            }

            break;

        default:

            abort();

        }

        assert(io_sectors);

        sector_num += io_sectors;

        nb_chunks -= DIV_ROUND_UP(io_sectors, sectors_per_chunk);

        if (s->common.speed) {

            delay_ns = ratelimit_calculate_delay(&s->limit, io_sectors_acct);

        }

    }

    return delay_ns;

}

void pcie_port_init_reg(PCIDevice *d)

{

    /* Unlike pci bridge,

       66MHz and fast back to back don't apply to pci express port. */

    pci_set_word(d->config + PCI_STATUS, 0);

    pci_set_word(d->config + PCI_SEC_STATUS, 0);



    /* Unlike conventional pci bridge, some bits are hardwired to 0. */

#define  PCI_BRIDGE_CTL_VGA_16BIT       0x10    /* VGA 16-bit decode */

    pci_set_word(d->wmask + PCI_BRIDGE_CONTROL,

                 PCI_BRIDGE_CTL_PARITY |

                 PCI_BRIDGE_CTL_ISA |

                 PCI_BRIDGE_CTL_VGA |

                 PCI_BRIDGE_CTL_VGA_16BIT | /* Req, but no alias support yet */

                 PCI_BRIDGE_CTL_SERR |

                 PCI_BRIDGE_CTL_BUS_RESET);

}

static always_inline void gen_farith3 (void *helper,

                                       int ra, int rb, int rc)

{

    if (unlikely(rc == 31))

        return;



    if (ra != 31) {

        if (rb != 31)

            tcg_gen_helper_1_2(helper, cpu_fir[rc], cpu_fir[ra], cpu_fir[rb]);

        else {

            TCGv tmp = tcg_const_i64(0);

            tcg_gen_helper_1_2(helper, cpu_fir[rc], cpu_fir[ra], tmp);

            tcg_temp_free(tmp);

        }

    } else {

        TCGv tmp = tcg_const_i64(0);

        if (rb != 31)

            tcg_gen_helper_1_2(helper, cpu_fir[rc], tmp, cpu_fir[rb]);

        else

            tcg_gen_helper_1_2(helper, cpu_fir[rc], tmp, tmp);

        tcg_temp_free(tmp);

    }

}

static bool vfio_prereg_listener_skipped_section(MemoryRegionSection *section)

{

    if (memory_region_is_iommu(section->mr)) {

        hw_error("Cannot possibly preregister IOMMU memory");

    }



    return !memory_region_is_ram(section->mr) ||

            memory_region_is_skip_dump(section->mr);

}

