static int local_set_mapped_file_attr(FsContext *ctx,

                                      const char *path, FsCred *credp)

{

    FILE *fp;

    int ret = 0;

    char buf[ATTR_MAX];

    char attr_path[PATH_MAX];

    int uid = -1, gid = -1, mode = -1, rdev = -1;



    fp = local_fopen(local_mapped_attr_path(ctx, path, attr_path), "r");

    if (!fp) {

        goto create_map_file;

    }

    memset(buf, 0, ATTR_MAX);

    while (fgets(buf, ATTR_MAX, fp)) {

        if (!strncmp(buf, "virtfs.uid", 10)) {

            uid = atoi(buf+11);

        } else if (!strncmp(buf, "virtfs.gid", 10)) {

            gid = atoi(buf+11);

        } else if (!strncmp(buf, "virtfs.mode", 11)) {

            mode = atoi(buf+12);

        } else if (!strncmp(buf, "virtfs.rdev", 11)) {

            rdev = atoi(buf+12);

        }

        memset(buf, 0, ATTR_MAX);

    }

    fclose(fp);

    goto update_map_file;



create_map_file:

    ret = local_create_mapped_attr_dir(ctx, path);

    if (ret < 0) {

        goto err_out;

    }



update_map_file:

    fp = local_fopen(attr_path, "w");

    if (!fp) {

        ret = -1;

        goto err_out;

    }



    if (credp->fc_uid != -1) {

        uid = credp->fc_uid;

    }

    if (credp->fc_gid != -1) {

        gid = credp->fc_gid;

    }

    if (credp->fc_mode != -1) {

        mode = credp->fc_mode;

    }

    if (credp->fc_rdev != -1) {

        rdev = credp->fc_rdev;

    }





    if (uid != -1) {

        fprintf(fp, "virtfs.uid=%d\n", uid);

    }

    if (gid != -1) {

        fprintf(fp, "virtfs.gid=%d\n", gid);

    }

    if (mode != -1) {

        fprintf(fp, "virtfs.mode=%d\n", mode);

    }

    if (rdev != -1) {

        fprintf(fp, "virtfs.rdev=%d\n", rdev);

    }

    fclose(fp);



err_out:

    return ret;

}

static int64_t qemu_next_alarm_deadline(void)

{

    int64_t delta;

    int64_t rtdelta;



    if (!use_icount && vm_clock->active_timers) {

        delta = vm_clock->active_timers->expire_time -

                     qemu_get_clock_ns(vm_clock);

    } else {

        delta = INT32_MAX;

    }

    if (host_clock->active_timers) {

        int64_t hdelta = host_clock->active_timers->expire_time -

                 qemu_get_clock_ns(host_clock);

        if (hdelta < delta) {

            delta = hdelta;

        }

    }

    if (rt_clock->active_timers) {

        rtdelta = (rt_clock->active_timers->expire_time -

                 qemu_get_clock_ns(rt_clock));

        if (rtdelta < delta) {

            delta = rtdelta;

        }

    }



    return delta;

}

static void drive_backup_prepare(BlkActionState *common, Error **errp)

{

    DriveBackupState *state = DO_UPCAST(DriveBackupState, common, common);

    BlockBackend *blk;

    DriveBackup *backup;

    Error *local_err = NULL;



    assert(common->action->type == TRANSACTION_ACTION_KIND_DRIVE_BACKUP);

    backup = common->action->u.drive_backup.data;



    blk = blk_by_name(backup->device);

    if (!blk) {

        error_set(errp, ERROR_CLASS_DEVICE_NOT_FOUND,

                  "Device '%s' not found", backup->device);

        return;

    }



    if (!blk_is_available(blk)) {

        error_setg(errp, QERR_DEVICE_HAS_NO_MEDIUM, backup->device);

        return;

    }



    /* AioContext is released in .clean() */

    state->aio_context = blk_get_aio_context(blk);

    aio_context_acquire(state->aio_context);

    bdrv_drained_begin(blk_bs(blk));

    state->bs = blk_bs(blk);



    do_drive_backup(backup->has_job_id ? backup->job_id : NULL,

                    backup->device, backup->target,

                    backup->has_format, backup->format,

                    backup->sync,

                    backup->has_mode, backup->mode,

                    backup->has_speed, backup->speed,

                    backup->has_bitmap, backup->bitmap,

                    backup->has_on_source_error, backup->on_source_error,

                    backup->has_on_target_error, backup->on_target_error,

                    common->block_job_txn, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }



    state->job = state->bs->job;

}

