static int get_next_block(DumpState *s, RAMBlock *block)

{

    while (1) {

        block = QTAILQ_NEXT(block, next);

        if (!block) {

            /* no more block */

            return 1;

        }



        s->start = 0;

        s->block = block;

        if (s->has_filter) {

            if (block->offset >= s->begin + s->length ||

                block->offset + block->length <= s->begin) {

                /* This block is out of the range */

                continue;

            }



            if (s->begin > block->offset) {

                s->start = s->begin - block->offset;

            }

        }



        return 0;

    }

}

void do_interrupt(CPUState *env)

{

    int intno = env->exception_index;



#ifdef DEBUG_PCALL

    if (qemu_loglevel_mask(CPU_LOG_INT)) {

        static int count;

        const char *name;



        if (intno < 0 || intno >= 0x180)

            name = "Unknown";

        else if (intno >= 0x100)

            name = "Trap Instruction";

        else if (intno >= 0xc0)

            name = "Window Fill";

        else if (intno >= 0x80)

            name = "Window Spill";

        else {

            name = excp_names[intno];

            if (!name)

                name = "Unknown";

        }



        qemu_log("%6d: %s (v=%04x) pc=%016" PRIx64 " npc=%016" PRIx64

                " SP=%016" PRIx64 "\n",

                count, name, intno,

                env->pc,

                env->npc, env->regwptr[6]);

        log_cpu_state(env, 0);

#if 0

        {

            int i;

            uint8_t *ptr;



            qemu_log("       code=");

            ptr = (uint8_t *)env->pc;

            for(i = 0; i < 16; i++) {

                qemu_log(" %02x", ldub(ptr + i));

            }

            qemu_log("\n");

        }

#endif

        count++;

    }

#endif

#if !defined(CONFIG_USER_ONLY)

    if (env->tl >= env->maxtl) {

        cpu_abort(env, "Trap 0x%04x while trap level (%d) >= MAXTL (%d),"

                  " Error state", env->exception_index, env->tl, env->maxtl);

        return;

    }

#endif

    if (env->tl < env->maxtl - 1) {

        env->tl++;

    } else {

        env->pstate |= PS_RED;

        if (env->tl < env->maxtl)

            env->tl++;

    }

    env->tsptr = &env->ts[env->tl & MAXTL_MASK];

    env->tsptr->tstate = ((uint64_t)GET_CCR(env) << 32) |

        ((env->asi & 0xff) << 24) | ((env->pstate & 0xf3f) << 8) |

        GET_CWP64(env);

    env->tsptr->tpc = env->pc;

    env->tsptr->tnpc = env->npc;

    env->tsptr->tt = intno;

    if (!(env->def->features & CPU_FEATURE_GL)) {

        switch (intno) {

        case TT_IVEC:

            change_pstate(PS_PEF | PS_PRIV | PS_IG);

            break;

        case TT_TFAULT:

        case TT_TMISS:

        case TT_DFAULT:

        case TT_DMISS:

        case TT_DPROT:

            change_pstate(PS_PEF | PS_PRIV | PS_MG);

            break;

        default:

            change_pstate(PS_PEF | PS_PRIV | PS_AG);

            break;

        }

    }

    if (intno == TT_CLRWIN)

        cpu_set_cwp(env, cpu_cwp_dec(env, env->cwp - 1));

    else if ((intno & 0x1c0) == TT_SPILL)

        cpu_set_cwp(env, cpu_cwp_dec(env, env->cwp - env->cansave - 2));

    else if ((intno & 0x1c0) == TT_FILL)

        cpu_set_cwp(env, cpu_cwp_inc(env, env->cwp + 1));

    env->tbr &= ~0x7fffULL;

    env->tbr |= ((env->tl > 1) ? 1 << 14 : 0) | (intno << 5);

    env->pc = env->tbr;

    env->npc = env->pc + 4;

    env->exception_index = 0;

}

int bdrv_open2(BlockDriverState *bs, const char *filename, int flags,

               BlockDriver *drv)

{

    int ret, open_flags;

    char tmp_filename[PATH_MAX];

    char backing_filename[PATH_MAX];



    bs->read_only = 0;

    bs->is_temporary = 0;

    bs->encrypted = 0;

    bs->autogrow = 0;



    if (flags & BDRV_O_AUTOGROW)

        bs->autogrow = 1;



    if (flags & BDRV_O_SNAPSHOT) {

        BlockDriverState *bs1;

        int64_t total_size;



        /* if snapshot, we create a temporary backing file and open it

           instead of opening 'filename' directly */



        /* if there is a backing file, use it */

        bs1 = bdrv_new("");

        if (!bs1) {

            return -ENOMEM;

        }

        if (bdrv_open(bs1, filename, 0) < 0) {

            bdrv_delete(bs1);

            return -1;

        }

        total_size = bdrv_getlength(bs1) >> SECTOR_BITS;

        bdrv_delete(bs1);



        get_tmp_filename(tmp_filename, sizeof(tmp_filename));

        realpath(filename, backing_filename);

        if (bdrv_create(&bdrv_qcow2, tmp_filename,

                        total_size, backing_filename, 0) < 0) {

            return -1;

        }

        filename = tmp_filename;

        bs->is_temporary = 1;

    }



    pstrcpy(bs->filename, sizeof(bs->filename), filename);

    if (flags & BDRV_O_FILE) {

        drv = find_protocol(filename);

        if (!drv)

            return -ENOENT;

    } else {

        if (!drv) {

            drv = find_image_format(filename);

            if (!drv)

                return -1;

        }

    }

    bs->drv = drv;

    bs->opaque = qemu_mallocz(drv->instance_size);

    bs->total_sectors = 0; /* driver will set if it does not do getlength */

    if (bs->opaque == NULL && drv->instance_size > 0)

        return -1;

    /* Note: for compatibility, we open disk image files as RDWR, and

       RDONLY as fallback */

    if (!(flags & BDRV_O_FILE))

        open_flags = BDRV_O_RDWR | (flags & BDRV_O_DIRECT);

    else

        open_flags = flags & ~(BDRV_O_FILE | BDRV_O_SNAPSHOT);

    ret = drv->bdrv_open(bs, filename, open_flags);

    if (ret == -EACCES && !(flags & BDRV_O_FILE)) {

        ret = drv->bdrv_open(bs, filename, BDRV_O_RDONLY);

        bs->read_only = 1;

    }

    if (ret < 0) {

        qemu_free(bs->opaque);

        bs->opaque = NULL;

        bs->drv = NULL;

        return ret;

    }

    if (drv->bdrv_getlength) {

        bs->total_sectors = bdrv_getlength(bs) >> SECTOR_BITS;

    }

#ifndef _WIN32

    if (bs->is_temporary) {

        unlink(filename);

    }

#endif

    if (bs->backing_file[0] != '\0') {

        /* if there is a backing file, use it */

        bs->backing_hd = bdrv_new("");

        if (!bs->backing_hd) {

        fail:

            bdrv_close(bs);

            return -ENOMEM;

        }

        path_combine(backing_filename, sizeof(backing_filename),

                     filename, bs->backing_file);

        if (bdrv_open(bs->backing_hd, backing_filename, 0) < 0)

            goto fail;

    }



    /* call the change callback */

    bs->media_changed = 1;

    if (bs->change_cb)

        bs->change_cb(bs->change_opaque);



    return 0;

}

static void drive_backup_abort(BlkActionState *common)

{

    DriveBackupState *state = DO_UPCAST(DriveBackupState, common, common);

    BlockDriverState *bs = state->bs;



    /* Only cancel if it's the job we started */

    if (bs && bs->job && bs->job == state->job) {

        block_job_cancel_sync(bs->job);

    }

}

static void ivshmem_check_version(void *opaque, const uint8_t * buf, int size)

{

    IVShmemState *s = opaque;

    int tmp;

    int64_t version;



    if (!fifo_update_and_get_i64(s, buf, size, &version)) {

        return;

    }



    tmp = qemu_chr_fe_get_msgfd(s->server_chr);

    if (tmp != -1 || version != IVSHMEM_PROTOCOL_VERSION) {

        fprintf(stderr, "incompatible version, you are connecting to a ivshmem-"

                "server using a different protocol please check your setup\n");

        qemu_chr_add_handlers(s->server_chr, NULL, NULL, NULL, s);

        return;

    }



    IVSHMEM_DPRINTF("version check ok, switch to real chardev handler\n");

    qemu_chr_add_handlers(s->server_chr, ivshmem_can_receive, ivshmem_read,

                          NULL, s);

}

