static void dec10_reg_scc(DisasContext *dc)

{

    int cond = dc->dst;



    LOG_DIS("s%s $r%u\n", cc_name(cond), dc->src);



    if (cond != CC_A)

    {

        int l1;



        gen_tst_cc (dc, cpu_R[dc->src], cond);

        l1 = gen_new_label();

        tcg_gen_brcondi_tl(TCG_COND_EQ, cpu_R[dc->src], 0, l1);

        tcg_gen_movi_tl(cpu_R[dc->src], 1);

        gen_set_label(l1);

    } else {

        tcg_gen_movi_tl(cpu_R[dc->src], 1);

    }



    cris_cc_mask(dc, 0);

}

void armv7m_nvic_acknowledge_irq(void *opaque)

{

    NVICState *s = (NVICState *)opaque;

    CPUARMState *env = &s->cpu->env;

    const int pending = s->vectpending;

    const int running = nvic_exec_prio(s);

    int pendgroupprio;

    VecInfo *vec;



    assert(pending > ARMV7M_EXCP_RESET && pending < s->num_irq);



    vec = &s->vectors[pending];



    assert(vec->enabled);

    assert(vec->pending);



    pendgroupprio = vec->prio;

    if (pendgroupprio > 0) {

        pendgroupprio &= nvic_gprio_mask(s);

    }

    assert(pendgroupprio < running);



    trace_nvic_acknowledge_irq(pending, vec->prio);



    vec->active = 1;

    vec->pending = 0;



    env->v7m.exception = s->vectpending;



    nvic_irq_update(s);

}

static CharDriverState *text_console_init(ChardevVC *vc)

{

    CharDriverState *chr;

    QemuConsole *s;

    unsigned width = 0;

    unsigned height = 0;



    chr = g_malloc0(sizeof(CharDriverState));



    if (vc->has_width) {

