    }



    trace_console_txt_new(width, height);

    if (width == 0 || height == 0) {

        s = new_console(NULL, TEXT_CONSOLE, 0);

    } else {

        s = new_console(NULL, TEXT_CONSOLE_FIXED_SIZE, 0);

        s->surface = qemu_create_displaysurface(width, height);

