void sdl_display_init(DisplayState *ds, int full_screen, int no_frame)

{

    int flags;

    uint8_t data = 0;



#if defined(__APPLE__)

    /* always use generic keymaps */

    if (!keyboard_layout)

        keyboard_layout = "en-us";

#endif

    if(keyboard_layout) {

        kbd_layout = init_keyboard_layout(keyboard_layout);

        if (!kbd_layout)

            exit(1);

    }



    if (no_frame)

        gui_noframe = 1;



    flags = SDL_INIT_VIDEO | SDL_INIT_NOPARACHUTE;

    if (SDL_Init (flags)) {

        fprintf(stderr, "Could not initialize SDL - exiting\n");

        exit(1);

    }

#ifndef _WIN32

    /* NOTE: we still want Ctrl-C to work, so we undo the SDL redirections */

    signal(SIGINT, SIG_DFL);

    signal(SIGQUIT, SIG_DFL);

#endif



    ds->dpy_update = sdl_update;

    ds->dpy_resize = sdl_resize;

    ds->dpy_refresh = sdl_refresh;

    ds->dpy_fill = sdl_fill;

    ds->mouse_set = sdl_mouse_warp;

    ds->cursor_define = sdl_mouse_define;



    sdl_resize(ds, 640, 400);

    sdl_update_caption();

    SDL_EnableKeyRepeat(250, 50);

    gui_grab = 0;



    sdl_cursor_hidden = SDL_CreateCursor(&data, &data, 8, 1, 0, 0);

    sdl_cursor_normal = SDL_GetCursor();



    atexit(sdl_cleanup);

    if (full_screen) {

        gui_fullscreen = 1;

        gui_fullscreen_initial_grab = 1;

        sdl_grab_start();

    }

}

int nbd_trip(BlockDriverState *bs, int csock, off_t size, uint64_t dev_offset,

             off_t *offset, uint32_t nbdflags, uint8_t *data, int data_size)

{

    struct nbd_request request;

    struct nbd_reply reply;



    TRACE("Reading request.");



    if (nbd_receive_request(csock, &request) == -1)

        return -1;



    if (request.len + NBD_REPLY_SIZE > data_size) {

        LOG("len (%u) is larger than max len (%u)",

            request.len + NBD_REPLY_SIZE, data_size);

        errno = EINVAL;

        return -1;

    }



    if ((request.from + request.len) < request.from) {

        LOG("integer overflow detected! "

            "you're probably being attacked");

        errno = EINVAL;

        return -1;

    }



    if ((request.from + request.len) > size) {

            LOG("From: %" PRIu64 ", Len: %u, Size: %" PRIu64

            ", Offset: %" PRIu64 "\n",

                    request.from, request.len, (uint64_t)size, dev_offset);

        LOG("requested operation past EOF--bad client?");

        errno = EINVAL;

        return -1;

    }



    TRACE("Decoding type");



    reply.handle = request.handle;

    reply.error = 0;



    switch (request.type) {

    case NBD_CMD_READ:

        TRACE("Request type is READ");



        if (bdrv_read(bs, (request.from + dev_offset) / 512,

                  data + NBD_REPLY_SIZE,

                  request.len / 512) == -1) {

            LOG("reading from file failed");

            errno = EINVAL;

            return -1;

        }

        *offset += request.len;



        TRACE("Read %u byte(s)", request.len);



        /* Reply

           [ 0 ..  3]    magic   (NBD_REPLY_MAGIC)

           [ 4 ..  7]    error   (0 == no error)

           [ 7 .. 15]    handle

         */



        cpu_to_be32w((uint32_t*)data, NBD_REPLY_MAGIC);

        cpu_to_be32w((uint32_t*)(data + 4), reply.error);

        cpu_to_be64w((uint64_t*)(data + 8), reply.handle);



        TRACE("Sending data to client");



        if (write_sync(csock, data,

                   request.len + NBD_REPLY_SIZE) !=

                   request.len + NBD_REPLY_SIZE) {

            LOG("writing to socket failed");

            errno = EINVAL;

            return -1;

        }

        break;

    case NBD_CMD_WRITE:

        TRACE("Request type is WRITE");



        TRACE("Reading %u byte(s)", request.len);



        if (read_sync(csock, data, request.len) != request.len) {

            LOG("reading from socket failed");

            errno = EINVAL;

            return -1;

        }



        if (nbdflags & NBD_FLAG_READ_ONLY) {

            TRACE("Server is read-only, return error");

            reply.error = 1;

        } else {

            TRACE("Writing to device");



            if (bdrv_write(bs, (request.from + dev_offset) / 512,

                       data, request.len / 512) == -1) {

                LOG("writing to file failed");

                errno = EINVAL;

                return -1;

            }



            *offset += request.len;

        }



        if (nbd_send_reply(csock, &reply) == -1)

            return -1;

        break;

    case NBD_CMD_DISC:

        TRACE("Request type is DISCONNECT");

        errno = 0;

        return 1;

    default:

        LOG("invalid request type (%u) received", request.type);

        errno = EINVAL;

        return -1;

    }



    TRACE("Request/Reply complete");



    return 0;

}

