static void ide_sector_write_cb(void *opaque, int ret)

{

    IDEState *s = opaque;

    int n;



    if (ret == -ECANCELED) {

        return;

    }

    block_acct_done(blk_get_stats(s->blk), &s->acct);



    s->pio_aiocb = NULL;

    s->status &= ~BUSY_STAT;



    if (ret != 0) {

        if (ide_handle_rw_error(s, -ret, IDE_RETRY_PIO)) {

            return;

        }

    }



    n = s->nsector;

    if (n > s->req_nb_sectors) {

        n = s->req_nb_sectors;

    }

    s->nsector -= n;



    ide_set_sector(s, ide_get_sector(s) + n);

    if (s->nsector == 0) {

        /* no more sectors to write */

        ide_transfer_stop(s);

    } else {

        int n1 = s->nsector;

        if (n1 > s->req_nb_sectors) {

            n1 = s->req_nb_sectors;

        }

        ide_transfer_start(s, s->io_buffer, n1 * BDRV_SECTOR_SIZE,

                           ide_sector_write);

    }



    if (win2k_install_hack && ((++s->irq_count % 16) == 0)) {

        /* It seems there is a bug in the Windows 2000 installer HDD

           IDE driver which fills the disk with empty logs when the

           IDE write IRQ comes too early. This hack tries to correct

           that at the expense of slower write performances. Use this

           option _only_ to install Windows 2000. You must disable it

           for normal use. */

        timer_mod(s->sector_write_timer,

                       qemu_clock_get_ns(QEMU_CLOCK_VIRTUAL) + (get_ticks_per_sec() / 1000));

    } else {

        ide_set_irq(s->bus);

    }

}

static int ioreq_runio_qemu_sync(struct ioreq *ioreq)

{

    struct XenBlkDev *blkdev = ioreq->blkdev;

    int i, rc, len = 0;

    off_t pos;



    if (ioreq->req.nr_segments && ioreq_map(ioreq) == -1)

	goto err;

    if (ioreq->presync)

	bdrv_flush(blkdev->bs);



    switch (ioreq->req.operation) {

    case BLKIF_OP_READ:

	pos = ioreq->start;

	for (i = 0; i < ioreq->v.niov; i++) {

	    rc = bdrv_read(blkdev->bs, pos / BLOCK_SIZE,

			   ioreq->v.iov[i].iov_base,

			   ioreq->v.iov[i].iov_len / BLOCK_SIZE);

	    if (rc != 0) {

		xen_be_printf(&blkdev->xendev, 0, "rd I/O error (%p, len %zd)\n",

			      ioreq->v.iov[i].iov_base,

			      ioreq->v.iov[i].iov_len);

		goto err;

	    }

	    len += ioreq->v.iov[i].iov_len;

	    pos += ioreq->v.iov[i].iov_len;

	}

	break;

    case BLKIF_OP_WRITE:

    case BLKIF_OP_WRITE_BARRIER:

        if (!ioreq->req.nr_segments)

            break;

	pos = ioreq->start;

	for (i = 0; i < ioreq->v.niov; i++) {

	    rc = bdrv_write(blkdev->bs, pos / BLOCK_SIZE,

			    ioreq->v.iov[i].iov_base,

			    ioreq->v.iov[i].iov_len / BLOCK_SIZE);

	    if (rc != 0) {

		xen_be_printf(&blkdev->xendev, 0, "wr I/O error (%p, len %zd)\n",

			      ioreq->v.iov[i].iov_base,

			      ioreq->v.iov[i].iov_len);

		goto err;

	    }

	    len += ioreq->v.iov[i].iov_len;

	    pos += ioreq->v.iov[i].iov_len;

	}

	break;

    default:

	/* unknown operation (shouldn't happen -- parse catches this) */

	goto err;

    }



    if (ioreq->postsync)

	bdrv_flush(blkdev->bs);

    ioreq->status = BLKIF_RSP_OKAY;



    ioreq_unmap(ioreq);

    ioreq_finish(ioreq);

    return 0;



err:

    ioreq->status = BLKIF_RSP_ERROR;

    return -1;

}

