static void gen_spr_amr (CPUPPCState *env)

{

#ifndef CONFIG_USER_ONLY

    /* Virtual Page Class Key protection */

    /* The AMR is accessible either via SPR 13 or SPR 29.  13 is

     * userspace accessible, 29 is privileged.  So we only need to set

     * the kvm ONE_REG id on one of them, we use 29 */

    spr_register(env, SPR_UAMR, "UAMR",

                 &spr_read_uamr, &spr_write_uamr_pr,

                 &spr_read_uamr, &spr_write_uamr,

                 0);

    spr_register_kvm(env, SPR_AMR, "AMR",

                     SPR_NOACCESS, SPR_NOACCESS,

                     &spr_read_generic, &spr_write_generic,

                     KVM_REG_PPC_AMR, 0xffffffffffffffffULL);

    spr_register_kvm(env, SPR_UAMOR, "UAMOR",

                     SPR_NOACCESS, SPR_NOACCESS,

                     &spr_read_generic, &spr_write_generic,

                     KVM_REG_PPC_UAMOR, 0);

#endif /* !CONFIG_USER_ONLY */

}

static void set_kernel_args(const struct arm_boot_info *info)

{

    int initrd_size = info->initrd_size;

    target_phys_addr_t base = info->loader_start;

    target_phys_addr_t p;



    p = base + KERNEL_ARGS_ADDR;

    /* ATAG_CORE */

    WRITE_WORD(p, 5);

    WRITE_WORD(p, 0x54410001);

    WRITE_WORD(p, 1);

    WRITE_WORD(p, 0x1000);

    WRITE_WORD(p, 0);

    /* ATAG_MEM */

    /* TODO: handle multiple chips on one ATAG list */

    WRITE_WORD(p, 4);

    WRITE_WORD(p, 0x54410002);

    WRITE_WORD(p, info->ram_size);

    WRITE_WORD(p, info->loader_start);

    if (initrd_size) {

        /* ATAG_INITRD2 */

        WRITE_WORD(p, 4);

        WRITE_WORD(p, 0x54420005);

        WRITE_WORD(p, info->loader_start + INITRD_LOAD_ADDR);

        WRITE_WORD(p, initrd_size);

    }

    if (info->kernel_cmdline && *info->kernel_cmdline) {

        /* ATAG_CMDLINE */

        int cmdline_size;



        cmdline_size = strlen(info->kernel_cmdline);

        cpu_physical_memory_write(p + 8, (void *)info->kernel_cmdline,

                                  cmdline_size + 1);

        cmdline_size = (cmdline_size >> 2) + 1;

        WRITE_WORD(p, cmdline_size + 2);

        WRITE_WORD(p, 0x54410009);

        p += cmdline_size * 4;

    }

    if (info->atag_board) {

        /* ATAG_BOARD */

        int atag_board_len;

        uint8_t atag_board_buf[0x1000];



        atag_board_len = (info->atag_board(info, atag_board_buf) + 3) & ~3;

        WRITE_WORD(p, (atag_board_len + 8) >> 2);

        WRITE_WORD(p, 0x414f4d50);

        cpu_physical_memory_write(p, atag_board_buf, atag_board_len);

        p += atag_board_len;

    }

    /* ATAG_END */

    WRITE_WORD(p, 0);

    WRITE_WORD(p, 0);

}

static void ppc_powernv_init(MachineState *machine)

{

    PnvMachineState *pnv = POWERNV_MACHINE(machine);

    MemoryRegion *ram;

    char *fw_filename;

    long fw_size;

    int i;

    char *chip_typename;



    /* allocate RAM */

    if (machine->ram_size < (1 * G_BYTE)) {

        error_report("Warning: skiboot may not work with < 1GB of RAM");

    }



    ram = g_new(MemoryRegion, 1);

    memory_region_allocate_system_memory(ram, NULL, "ppc_powernv.ram",

                                         machine->ram_size);

    memory_region_add_subregion(get_system_memory(), 0, ram);



    /* load skiboot firmware  */

    if (bios_name == NULL) {

        bios_name = FW_FILE_NAME;

    }



    fw_filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);



    fw_size = load_image_targphys(fw_filename, FW_LOAD_ADDR, FW_MAX_SIZE);

    if (fw_size < 0) {

        error_report("Could not load OPAL '%s'", fw_filename);

        exit(1);

    }

    g_free(fw_filename);



    /* load kernel */

    if (machine->kernel_filename) {

        long kernel_size;



        kernel_size = load_image_targphys(machine->kernel_filename,

                                          KERNEL_LOAD_ADDR, 0x2000000);

        if (kernel_size < 0) {

            error_report("Could not load kernel '%s'",

                         machine->kernel_filename);

            exit(1);

        }

    }



    /* load initrd */

    if (machine->initrd_filename) {

        pnv->initrd_base = INITRD_LOAD_ADDR;

        pnv->initrd_size = load_image_targphys(machine->initrd_filename,

                                  pnv->initrd_base, 0x10000000); /* 128MB max */

        if (pnv->initrd_size < 0) {

            error_report("Could not load initial ram disk '%s'",

                         machine->initrd_filename);

            exit(1);

        }

    }



    /* We need some cpu model to instantiate the PnvChip class */

    if (machine->cpu_model == NULL) {

        machine->cpu_model = "POWER8";

    }



    /* Create the processor chips */

    chip_typename = g_strdup_printf(TYPE_PNV_CHIP "-%s", machine->cpu_model);

    if (!object_class_by_name(chip_typename)) {

        error_report("invalid CPU model '%s' for %s machine",

                     machine->cpu_model, MACHINE_GET_CLASS(machine)->name);

        exit(1);

    }



    pnv->chips = g_new0(PnvChip *, pnv->num_chips);

    for (i = 0; i < pnv->num_chips; i++) {

        char chip_name[32];

        Object *chip = object_new(chip_typename);



        pnv->chips[i] = PNV_CHIP(chip);



        /* TODO: put all the memory in one node on chip 0 until we find a

         * way to specify different ranges for each chip

         */

        if (i == 0) {

            object_property_set_int(chip, machine->ram_size, "ram-size",

                                    &error_fatal);

        }



        snprintf(chip_name, sizeof(chip_name), "chip[%d]", PNV_CHIP_HWID(i));

        object_property_add_child(OBJECT(pnv), chip_name, chip, &error_fatal);

        object_property_set_int(chip, PNV_CHIP_HWID(i), "chip-id",

                                &error_fatal);

        object_property_set_int(chip, smp_cores, "nr-cores", &error_fatal);

        object_property_set_bool(chip, true, "realized", &error_fatal);

    }

    g_free(chip_typename);



    /* Instantiate ISA bus on chip 0 */

    pnv->isa_bus = pnv_isa_create(pnv->chips[0]);



    /* Create serial port */

    serial_hds_isa_init(pnv->isa_bus, 0, MAX_SERIAL_PORTS);



    /* Create an RTC ISA device too */

    rtc_init(pnv->isa_bus, 2000, NULL);



    /* OpenPOWER systems use a IPMI SEL Event message to notify the

     * host to powerdown */

    pnv->powerdown_notifier.notify = pnv_powerdown_notify;

    qemu_register_powerdown_notifier(&pnv->powerdown_notifier);

}

static int proxy_remove(FsContext *ctx, const char *path)

{

    int retval;

    V9fsString name;

    v9fs_string_init(&name);

    v9fs_string_sprintf(&name, "%s", path);

    retval = v9fs_request(ctx->private, T_REMOVE, NULL, "s", &name);

    v9fs_string_free(&name);

    if (retval < 0) {

        errno = -retval;

    }

    return retval;

}

static uint64_t pxa2xx_ssp_read(void *opaque, hwaddr addr,

                                unsigned size)

{

    PXA2xxSSPState *s = (PXA2xxSSPState *) opaque;

    uint32_t retval;



    switch (addr) {

    case SSCR0:

        return s->sscr[0];

    case SSCR1:

        return s->sscr[1];

    case SSPSP:

        return s->sspsp;

    case SSTO:

        return s->ssto;

    case SSITR:

        return s->ssitr;

    case SSSR:

        return s->sssr | s->ssitr;

    case SSDR:

        if (!s->enable)

            return 0xffffffff;

        if (s->rx_level < 1) {

            printf("%s: SSP Rx Underrun\n", __FUNCTION__);

            return 0xffffffff;

        }

        s->rx_level --;

        retval = s->rx_fifo[s->rx_start ++];

        s->rx_start &= 0xf;

        pxa2xx_ssp_fifo_update(s);

        return retval;

    case SSTSA:

        return s->sstsa;

    case SSRSA:

        return s->ssrsa;

    case SSTSS:

        return 0;

    case SSACD:

        return s->ssacd;

    default:

        printf("%s: Bad register " REG_FMT "\n", __FUNCTION__, addr);

        break;

    }

    return 0;

}

static inline void tcg_out_op(TCGContext *s, TCGOpcode opc,

                              const TCGArg *args, const int *const_args)

{

    int c, vexop, rexw = 0;



#if TCG_TARGET_REG_BITS == 64

# define OP_32_64(x) \

        case glue(glue(INDEX_op_, x), _i64): \

            rexw = P_REXW; /* FALLTHRU */    \

        case glue(glue(INDEX_op_, x), _i32)

#else

# define OP_32_64(x) \

        case glue(glue(INDEX_op_, x), _i32)

#endif



    switch(opc) {

    case INDEX_op_exit_tb:

        tcg_out_movi(s, TCG_TYPE_PTR, TCG_REG_EAX, args[0]);

        tcg_out_jmp(s, tb_ret_addr);

        break;

    case INDEX_op_goto_tb:

        if (s->tb_jmp_offset) {

            /* direct jump method */

            tcg_out8(s, OPC_JMP_long); /* jmp im */

            s->tb_jmp_offset[args[0]] = tcg_current_code_size(s);

            tcg_out32(s, 0);

        } else {

            /* indirect jump method */

            tcg_out_modrm_offset(s, OPC_GRP5, EXT5_JMPN_Ev, -1,

                                 (intptr_t)(s->tb_next + args[0]));

        }

        s->tb_next_offset[args[0]] = tcg_current_code_size(s);

        break;

    case INDEX_op_br:

        tcg_out_jxx(s, JCC_JMP, args[0], 0);

        break;

    OP_32_64(ld8u):

        /* Note that we can ignore REXW for the zero-extend to 64-bit.  */

        tcg_out_modrm_offset(s, OPC_MOVZBL, args[0], args[1], args[2]);

        break;

    OP_32_64(ld8s):

        tcg_out_modrm_offset(s, OPC_MOVSBL + rexw, args[0], args[1], args[2]);

        break;

    OP_32_64(ld16u):

        /* Note that we can ignore REXW for the zero-extend to 64-bit.  */

        tcg_out_modrm_offset(s, OPC_MOVZWL, args[0], args[1], args[2]);

        break;

    OP_32_64(ld16s):

        tcg_out_modrm_offset(s, OPC_MOVSWL + rexw, args[0], args[1], args[2]);

        break;

#if TCG_TARGET_REG_BITS == 64

    case INDEX_op_ld32u_i64:

#endif

    case INDEX_op_ld_i32:

        tcg_out_ld(s, TCG_TYPE_I32, args[0], args[1], args[2]);

        break;



    OP_32_64(st8):

        if (const_args[0]) {

            tcg_out_modrm_offset(s, OPC_MOVB_EvIz,

                                 0, args[1], args[2]);

            tcg_out8(s, args[0]);

        } else {

            tcg_out_modrm_offset(s, OPC_MOVB_EvGv | P_REXB_R,

                                 args[0], args[1], args[2]);

        }

        break;

    OP_32_64(st16):

        if (const_args[0]) {

            tcg_out_modrm_offset(s, OPC_MOVL_EvIz | P_DATA16,

                                 0, args[1], args[2]);

            tcg_out16(s, args[0]);

        } else {

            tcg_out_modrm_offset(s, OPC_MOVL_EvGv | P_DATA16,

                                 args[0], args[1], args[2]);

        }

        break;

#if TCG_TARGET_REG_BITS == 64

    case INDEX_op_st32_i64:

#endif

    case INDEX_op_st_i32:

        if (const_args[0]) {

            tcg_out_modrm_offset(s, OPC_MOVL_EvIz, 0, args[1], args[2]);

            tcg_out32(s, args[0]);

        } else {

            tcg_out_st(s, TCG_TYPE_I32, args[0], args[1], args[2]);

        }

        break;



    OP_32_64(add):

        /* For 3-operand addition, use LEA.  */

        if (args[0] != args[1]) {

            TCGArg a0 = args[0], a1 = args[1], a2 = args[2], c3 = 0;



            if (const_args[2]) {

                c3 = a2, a2 = -1;

            } else if (a0 == a2) {

                /* Watch out for dest = src + dest, since we've removed

                   the matching constraint on the add.  */

                tgen_arithr(s, ARITH_ADD + rexw, a0, a1);

                break;

            }



            tcg_out_modrm_sib_offset(s, OPC_LEA + rexw, a0, a1, a2, 0, c3);

            break;

        }

        c = ARITH_ADD;

        goto gen_arith;

    OP_32_64(sub):

        c = ARITH_SUB;

        goto gen_arith;

    OP_32_64(and):

        c = ARITH_AND;

        goto gen_arith;

    OP_32_64(or):

        c = ARITH_OR;

        goto gen_arith;

    OP_32_64(xor):

        c = ARITH_XOR;

        goto gen_arith;

    gen_arith:

        if (const_args[2]) {

            tgen_arithi(s, c + rexw, args[0], args[2], 0);

        } else {

            tgen_arithr(s, c + rexw, args[0], args[2]);

        }

        break;



    OP_32_64(andc):

        if (const_args[2]) {

            tcg_out_mov(s, rexw ? TCG_TYPE_I64 : TCG_TYPE_I32,

                        args[0], args[1]);

            tgen_arithi(s, ARITH_AND + rexw, args[0], ~args[2], 0);

        } else {

            tcg_out_vex_modrm(s, OPC_ANDN + rexw, args[0], args[2], args[1]);

        }

        break;



    OP_32_64(mul):

        if (const_args[2]) {

            int32_t val;

            val = args[2];

            if (val == (int8_t)val) {

                tcg_out_modrm(s, OPC_IMUL_GvEvIb + rexw, args[0], args[0]);

                tcg_out8(s, val);

            } else {

                tcg_out_modrm(s, OPC_IMUL_GvEvIz + rexw, args[0], args[0]);

                tcg_out32(s, val);

            }

        } else {

            tcg_out_modrm(s, OPC_IMUL_GvEv + rexw, args[0], args[2]);

        }

        break;



    OP_32_64(div2):

        tcg_out_modrm(s, OPC_GRP3_Ev + rexw, EXT3_IDIV, args[4]);

        break;

    OP_32_64(divu2):

        tcg_out_modrm(s, OPC_GRP3_Ev + rexw, EXT3_DIV, args[4]);

        break;



    OP_32_64(shl):

        c = SHIFT_SHL;

        vexop = OPC_SHLX;

        goto gen_shift_maybe_vex;

    OP_32_64(shr):

        c = SHIFT_SHR;

        vexop = OPC_SHRX;

        goto gen_shift_maybe_vex;

    OP_32_64(sar):

        c = SHIFT_SAR;

        vexop = OPC_SARX;

        goto gen_shift_maybe_vex;

    OP_32_64(rotl):

        c = SHIFT_ROL;

        goto gen_shift;

    OP_32_64(rotr):

        c = SHIFT_ROR;

        goto gen_shift;

    gen_shift_maybe_vex:

        if (have_bmi2 && !const_args[2]) {

            tcg_out_vex_modrm(s, vexop + rexw, args[0], args[2], args[1]);

            break;

        }

        /* FALLTHRU */

    gen_shift:

        if (const_args[2]) {

            tcg_out_shifti(s, c + rexw, args[0], args[2]);

        } else {

            tcg_out_modrm(s, OPC_SHIFT_cl + rexw, c, args[0]);

        }

        break;



    case INDEX_op_brcond_i32:

        tcg_out_brcond32(s, args[2], args[0], args[1], const_args[1],

                         args[3], 0);

        break;

    case INDEX_op_setcond_i32:

        tcg_out_setcond32(s, args[3], args[0], args[1],

                          args[2], const_args[2]);

        break;

    case INDEX_op_movcond_i32:

        tcg_out_movcond32(s, args[5], args[0], args[1],

                          args[2], const_args[2], args[3]);

        break;



    OP_32_64(bswap16):

        tcg_out_rolw_8(s, args[0]);

        break;

    OP_32_64(bswap32):

        tcg_out_bswap32(s, args[0]);

        break;



    OP_32_64(neg):

        tcg_out_modrm(s, OPC_GRP3_Ev + rexw, EXT3_NEG, args[0]);

        break;

    OP_32_64(not):

        tcg_out_modrm(s, OPC_GRP3_Ev + rexw, EXT3_NOT, args[0]);

        break;



    OP_32_64(ext8s):

        tcg_out_ext8s(s, args[0], args[1], rexw);

        break;

    OP_32_64(ext16s):

        tcg_out_ext16s(s, args[0], args[1], rexw);

        break;

    OP_32_64(ext8u):

        tcg_out_ext8u(s, args[0], args[1]);

        break;

    OP_32_64(ext16u):

        tcg_out_ext16u(s, args[0], args[1]);

        break;



    case INDEX_op_qemu_ld_i32:

        tcg_out_qemu_ld(s, args, 0);

        break;

    case INDEX_op_qemu_ld_i64:

        tcg_out_qemu_ld(s, args, 1);

        break;

    case INDEX_op_qemu_st_i32:

        tcg_out_qemu_st(s, args, 0);

        break;

    case INDEX_op_qemu_st_i64:

        tcg_out_qemu_st(s, args, 1);

        break;



    OP_32_64(mulu2):

        tcg_out_modrm(s, OPC_GRP3_Ev + rexw, EXT3_MUL, args[3]);

        break;

    OP_32_64(muls2):

        tcg_out_modrm(s, OPC_GRP3_Ev + rexw, EXT3_IMUL, args[3]);

        break;

    OP_32_64(add2):

        if (const_args[4]) {

            tgen_arithi(s, ARITH_ADD + rexw, args[0], args[4], 1);

        } else {

            tgen_arithr(s, ARITH_ADD + rexw, args[0], args[4]);

        }

        if (const_args[5]) {

            tgen_arithi(s, ARITH_ADC + rexw, args[1], args[5], 1);

        } else {

            tgen_arithr(s, ARITH_ADC + rexw, args[1], args[5]);

        }

        break;

    OP_32_64(sub2):

        if (const_args[4]) {

            tgen_arithi(s, ARITH_SUB + rexw, args[0], args[4], 1);

        } else {

            tgen_arithr(s, ARITH_SUB + rexw, args[0], args[4]);

        }

        if (const_args[5]) {

            tgen_arithi(s, ARITH_SBB + rexw, args[1], args[5], 1);

        } else {

            tgen_arithr(s, ARITH_SBB + rexw, args[1], args[5]);

        }

        break;



#if TCG_TARGET_REG_BITS == 32

    case INDEX_op_brcond2_i32:

        tcg_out_brcond2(s, args, const_args, 0);

        break;

    case INDEX_op_setcond2_i32:

        tcg_out_setcond2(s, args, const_args);

        break;

#else /* TCG_TARGET_REG_BITS == 64 */

    case INDEX_op_ld32s_i64:

        tcg_out_modrm_offset(s, OPC_MOVSLQ, args[0], args[1], args[2]);

        break;

    case INDEX_op_ld_i64:

        tcg_out_ld(s, TCG_TYPE_I64, args[0], args[1], args[2]);

        break;

    case INDEX_op_st_i64:

        if (const_args[0]) {

            tcg_out_modrm_offset(s, OPC_MOVL_EvIz | P_REXW,

                                 0, args[1], args[2]);

            tcg_out32(s, args[0]);

        } else {

            tcg_out_st(s, TCG_TYPE_I64, args[0], args[1], args[2]);

        }

        break;



    case INDEX_op_brcond_i64:

        tcg_out_brcond64(s, args[2], args[0], args[1], const_args[1],

                         args[3], 0);

        break;

    case INDEX_op_setcond_i64:

        tcg_out_setcond64(s, args[3], args[0], args[1],

                          args[2], const_args[2]);

        break;

    case INDEX_op_movcond_i64:

        tcg_out_movcond64(s, args[5], args[0], args[1],

                          args[2], const_args[2], args[3]);

        break;



    case INDEX_op_bswap64_i64:

        tcg_out_bswap64(s, args[0]);

        break;

    case INDEX_op_ext32u_i64:

        tcg_out_ext32u(s, args[0], args[1]);

        break;

    case INDEX_op_ext32s_i64:

        tcg_out_ext32s(s, args[0], args[1]);

        break;

#endif



    OP_32_64(deposit):

        if (args[3] == 0 && args[4] == 8) {

            /* load bits 0..7 */

            tcg_out_modrm(s, OPC_MOVB_EvGv | P_REXB_R | P_REXB_RM,

                          args[2], args[0]);

        } else if (args[3] == 8 && args[4] == 8) {

            /* load bits 8..15 */

            tcg_out_modrm(s, OPC_MOVB_EvGv, args[2], args[0] + 4);

        } else if (args[3] == 0 && args[4] == 16) {

            /* load bits 0..15 */

            tcg_out_modrm(s, OPC_MOVL_EvGv | P_DATA16, args[2], args[0]);

        } else {

            tcg_abort();

        }

        break;



    case INDEX_op_mov_i32:  /* Always emitted via tcg_out_mov.  */

    case INDEX_op_mov_i64:

    case INDEX_op_movi_i32: /* Always emitted via tcg_out_movi.  */

    case INDEX_op_movi_i64:

    case INDEX_op_call:     /* Always emitted via tcg_out_call.  */

    default:

        tcg_abort();

    }



#undef OP_32_64

}

static int coroutine_fn bdrv_co_do_write_zeroes(BlockDriverState *bs,

    int64_t sector_num, int nb_sectors, BdrvRequestFlags flags)

{

    BlockDriver *drv = bs->drv;

    QEMUIOVector qiov;

    struct iovec iov = {0};

    int ret = 0;



    int max_write_zeroes = bs->bl.max_write_zeroes ?

                           bs->bl.max_write_zeroes : INT_MAX;



    while (nb_sectors > 0 && !ret) {

        int num = nb_sectors;



        /* Align request.  Block drivers can expect the "bulk" of the request

         * to be aligned.

         */

        if (bs->bl.write_zeroes_alignment

            && num > bs->bl.write_zeroes_alignment) {

            if (sector_num % bs->bl.write_zeroes_alignment != 0) {

                /* Make a small request up to the first aligned sector.  */

                num = bs->bl.write_zeroes_alignment;

                num -= sector_num % bs->bl.write_zeroes_alignment;

            } else if ((sector_num + num) % bs->bl.write_zeroes_alignment != 0) {

                /* Shorten the request to the last aligned sector.  num cannot

                 * underflow because num > bs->bl.write_zeroes_alignment.

                 */

                num -= (sector_num + num) % bs->bl.write_zeroes_alignment;

            }

        }



        /* limit request size */

        if (num > max_write_zeroes) {

            num = max_write_zeroes;

        }



        ret = -ENOTSUP;

        /* First try the efficient write zeroes operation */

        if (drv->bdrv_co_write_zeroes) {

            ret = drv->bdrv_co_write_zeroes(bs, sector_num, num, flags);

        }



        if (ret == -ENOTSUP) {

            /* Fall back to bounce buffer if write zeroes is unsupported */

            int max_xfer_len = MIN_NON_ZERO(bs->bl.max_transfer_length,

                                            MAX_WRITE_ZEROES_BOUNCE_BUFFER);

            num = MIN(num, max_xfer_len);

            iov.iov_len = num * BDRV_SECTOR_SIZE;

            if (iov.iov_base == NULL) {

                iov.iov_base = qemu_try_blockalign(bs, num * BDRV_SECTOR_SIZE);

                if (iov.iov_base == NULL) {

                    ret = -ENOMEM;

                    goto fail;

                }

                memset(iov.iov_base, 0, num * BDRV_SECTOR_SIZE);

            }

            qemu_iovec_init_external(&qiov, &iov, 1);



            ret = drv->bdrv_co_writev(bs, sector_num, num, &qiov);



            /* Keep bounce buffer around if it is big enough for all

             * all future requests.

             */

            if (num < max_xfer_len) {

                qemu_vfree(iov.iov_base);

                iov.iov_base = NULL;

            }

        }



        sector_num += num;

        nb_sectors -= num;

    }



fail:

    qemu_vfree(iov.iov_base);

    return ret;

}

