static void term_up_char(void)

{

    int idx;



    if (term_hist_entry == 0)

	return;

    if (term_hist_entry == -1) {

	/* Find latest entry */

	for (idx = 0; idx < TERM_MAX_CMDS; idx++) {

	    if (term_history[idx] == NULL)

		break;

	}

	term_hist_entry = idx;

    }

    term_hist_entry--;

    if (term_hist_entry >= 0) {

	strcpy(term_cmd_buf, term_history[term_hist_entry]);

	term_printf("\n");

	term_print_cmdline(term_cmd_buf);

	term_cmd_buf_index = term_cmd_buf_size = strlen(term_cmd_buf);

    }

}

static void coroutine_fn v9fs_link(void *opaque)

{

    V9fsPDU *pdu = opaque;

    int32_t dfid, oldfid;

    V9fsFidState *dfidp, *oldfidp;

    V9fsString name;

    size_t offset = 7;

    int err = 0;



    v9fs_string_init(&name);

    err = pdu_unmarshal(pdu, offset, "dds", &dfid, &oldfid, &name);

    if (err < 0) {

        goto out_nofid;

    }

    trace_v9fs_link(pdu->tag, pdu->id, dfid, oldfid, name.data);



    if (name_is_illegal(name.data)) {

        err = -ENOENT;

        goto out_nofid;

    }



    if (!strcmp(".", name.data) || !strcmp("..", name.data)) {

        err = -EEXIST;

        goto out_nofid;

    }



    dfidp = get_fid(pdu, dfid);

    if (dfidp == NULL) {

        err = -ENOENT;

        goto out_nofid;

    }



    oldfidp = get_fid(pdu, oldfid);

    if (oldfidp == NULL) {

        err = -ENOENT;

        goto out;

    }

    err = v9fs_co_link(pdu, oldfidp, dfidp, &name);

    if (!err) {

        err = offset;

    }


out:

    put_fid(pdu, dfidp);

out_nofid:

    v9fs_string_free(&name);

    pdu_complete(pdu, err);

