static void pxa2xx_rtc_piupdate(PXA2xxRTCState *s)

{

    int64_t rt = qemu_get_clock(rt_clock);

    if (s->rtsr & (1 << 15))

        s->last_swcr += rt - s->last_pi;

    s->last_pi = rt;

}

int ioinst_handle_ssch(CPUS390XState *env, uint64_t reg1, uint32_t ipb)

{

    int cssid, ssid, schid, m;

    SubchDev *sch;

    ORB *orig_orb, orb;

    uint64_t addr;

    int ret = -ENODEV;

    int cc;

    hwaddr len = sizeof(*orig_orb);



    if (ioinst_disassemble_sch_ident(reg1, &m, &cssid, &ssid, &schid)) {

        program_interrupt(env, PGM_OPERAND, 2);

        return -EIO;

    }

    trace_ioinst_sch_id("ssch", cssid, ssid, schid);

    addr = decode_basedisp_s(env, ipb);

    if (addr & 3) {

        program_interrupt(env, PGM_SPECIFICATION, 2);

        return -EIO;

    }

    orig_orb = s390_cpu_physical_memory_map(env, addr, &len, 0);

    if (!orig_orb || len != sizeof(*orig_orb)) {

        program_interrupt(env, PGM_ADDRESSING, 2);

        cc = -EIO;

        goto out;

    }

    copy_orb_from_guest(&orb, orig_orb);

    if (!ioinst_orb_valid(&orb)) {

        program_interrupt(env, PGM_OPERAND, 2);

        cc = -EIO;

        goto out;

    }

    sch = css_find_subch(m, cssid, ssid, schid);

    if (sch && css_subch_visible(sch)) {

        ret = css_do_ssch(sch, &orb);

    }

    switch (ret) {

    case -ENODEV:

        cc = 3;

        break;

    case -EBUSY:

        cc = 2;

        break;

    case 0:

        cc = 0;

        break;

    default:

        cc = 1;

        break;

    }



out:

    s390_cpu_physical_memory_unmap(env, orig_orb, len, 0);

    return cc;

}

int ioinst_handle_tpi(S390CPU *cpu, uint32_t ipb)

{

    CPUS390XState *env = &cpu->env;

    uint64_t addr;

    int lowcore;

    IOIntCode int_code;

    hwaddr len;

    int ret;

    uint8_t ar;



    trace_ioinst("tpi");

    addr = decode_basedisp_s(env, ipb, &ar);

    if (addr & 3) {

        program_interrupt(env, PGM_SPECIFICATION, 2);

        return -EIO;

    }



    lowcore = addr ? 0 : 1;

    len = lowcore ? 8 /* two words */ : 12 /* three words */;

    ret = css_do_tpi(&int_code, lowcore);

    if (ret == 1) {

        s390_cpu_virt_mem_write(cpu, lowcore ? 184 : addr, ar, &int_code, len);

    }

    return ret;

}

