int virtio_load(VirtIODevice *vdev, QEMUFile *f, int version_id)

{

    int i, ret;

    int32_t config_len;

    uint32_t num;

    uint32_t features;

    BusState *qbus = qdev_get_parent_bus(DEVICE(vdev));

    VirtioBusClass *k = VIRTIO_BUS_GET_CLASS(qbus);

    VirtioDeviceClass *vdc = VIRTIO_DEVICE_GET_CLASS(vdev);



    /*

     * We poison the endianness to ensure it does not get used before

     * subsections have been loaded.

     */

    vdev->device_endian = VIRTIO_DEVICE_ENDIAN_UNKNOWN;



    if (k->load_config) {

        ret = k->load_config(qbus->parent, f);

        if (ret)

            return ret;

    }



    qemu_get_8s(f, &vdev->status);

    qemu_get_8s(f, &vdev->isr);

    qemu_get_be16s(f, &vdev->queue_sel);

    if (vdev->queue_sel >= VIRTIO_QUEUE_MAX) {

        return -1;

    }

    qemu_get_be32s(f, &features);



    /*

     * Temporarily set guest_features low bits - needed by

     * virtio net load code testing for VIRTIO_NET_F_CTRL_GUEST_OFFLOADS

     * VIRTIO_NET_F_GUEST_ANNOUNCE and VIRTIO_NET_F_CTRL_VQ.

     *

     * Note: devices should always test host features in future - don't create

     * new dependencies like this.

     */

    vdev->guest_features = features;



    config_len = qemu_get_be32(f);



    /*

     * There are cases where the incoming config can be bigger or smaller

     * than what we have; so load what we have space for, and skip

     * any excess that's in the stream.

     */

    qemu_get_buffer(f, vdev->config, MIN(config_len, vdev->config_len));



    while (config_len > vdev->config_len) {

        qemu_get_byte(f);

        config_len--;

    }



    num = qemu_get_be32(f);



    if (num > VIRTIO_QUEUE_MAX) {

        error_report("Invalid number of virtqueues: 0x%x", num);

        return -1;

    }



    for (i = 0; i < num; i++) {

        vdev->vq[i].vring.num = qemu_get_be32(f);

        if (k->has_variable_vring_alignment) {

            vdev->vq[i].vring.align = qemu_get_be32(f);

        }

        vdev->vq[i].vring.desc = qemu_get_be64(f);

        qemu_get_be16s(f, &vdev->vq[i].last_avail_idx);

        vdev->vq[i].signalled_used_valid = false;

        vdev->vq[i].notification = true;



        if (vdev->vq[i].vring.desc) {

            /* XXX virtio-1 devices */

            virtio_queue_update_rings(vdev, i);

        } else if (vdev->vq[i].last_avail_idx) {

            error_report("VQ %d address 0x0 "

                         "inconsistent with Host index 0x%x",

                         i, vdev->vq[i].last_avail_idx);

                return -1;

        }

        if (k->load_queue) {

            ret = k->load_queue(qbus->parent, i, f);

            if (ret)

                return ret;

        }

    }



    virtio_notify_vector(vdev, VIRTIO_NO_VECTOR);



    if (vdc->load != NULL) {

        ret = vdc->load(vdev, f, version_id);

        if (ret) {

            return ret;

        }

    }



    if (vdc->vmsd) {

        ret = vmstate_load_state(f, vdc->vmsd, vdev, version_id);

        if (ret) {

            return ret;

        }

    }



    /* Subsections */

    ret = vmstate_load_state(f, &vmstate_virtio, vdev, 1);

    if (ret) {

        return ret;

    }



    if (vdev->device_endian == VIRTIO_DEVICE_ENDIAN_UNKNOWN) {

        vdev->device_endian = virtio_default_endian();

    }



    if (virtio_64bit_features_needed(vdev)) {

        /*

         * Subsection load filled vdev->guest_features.  Run them

         * through virtio_set_features to sanity-check them against

         * host_features.

         */

        uint64_t features64 = vdev->guest_features;

        if (virtio_set_features_nocheck(vdev, features64) < 0) {

            error_report("Features 0x%" PRIx64 " unsupported. "

                         "Allowed features: 0x%" PRIx64,

                         features64, vdev->host_features);

            return -1;

        }

    } else {

        if (virtio_set_features_nocheck(vdev, features) < 0) {

            error_report("Features 0x%x unsupported. "

                         "Allowed features: 0x%" PRIx64,

                         features, vdev->host_features);

            return -1;

        }

    }



    rcu_read_lock();

    for (i = 0; i < num; i++) {

        if (vdev->vq[i].vring.desc) {

            uint16_t nheads;

            nheads = vring_avail_idx(&vdev->vq[i]) - vdev->vq[i].last_avail_idx;

            /* Check it isn't doing strange things with descriptor numbers. */

            if (nheads > vdev->vq[i].vring.num) {

                error_report("VQ %d size 0x%x Guest index 0x%x "

                             "inconsistent with Host index 0x%x: delta 0x%x",

                             i, vdev->vq[i].vring.num,

                             vring_avail_idx(&vdev->vq[i]),

                             vdev->vq[i].last_avail_idx, nheads);

                return -1;

            }

            vdev->vq[i].used_idx = vring_used_idx(&vdev->vq[i]);

            vdev->vq[i].shadow_avail_idx = vring_avail_idx(&vdev->vq[i]);



            /*

             * Some devices migrate VirtQueueElements that have been popped

             * from the avail ring but not yet returned to the used ring.

             * Since max ring size < UINT16_MAX it's safe to use modulo

             * UINT16_MAX + 1 subtraction.

             */

            vdev->vq[i].inuse = (uint16_t)(vdev->vq[i].last_avail_idx -

                                vdev->vq[i].used_idx);

            if (vdev->vq[i].inuse > vdev->vq[i].vring.num) {

                error_report("VQ %d size 0x%x < last_avail_idx 0x%x - "

                             "used_idx 0x%x",

                             i, vdev->vq[i].vring.num,

                             vdev->vq[i].last_avail_idx,

                             vdev->vq[i].used_idx);

                return -1;

            }

        }

    }

    rcu_read_unlock();



    return 0;

}

static void usbredir_iso_packet(void *priv, uint64_t id,

    struct usb_redir_iso_packet_header *iso_packet,

    uint8_t *data, int data_len)

{

    USBRedirDevice *dev = priv;

    uint8_t ep = iso_packet->endpoint;



    DPRINTF2("iso-in status %d ep %02X len %d id %"PRIu64"\n",

             iso_packet->status, ep, data_len, id);



    if (dev->endpoint[EP2I(ep)].type != USB_ENDPOINT_XFER_ISOC) {

        ERROR("received iso packet for non iso endpoint %02X\n", ep);

        free(data);

        return;

    }



    if (dev->endpoint[EP2I(ep)].iso_started == 0) {

        DPRINTF("received iso packet for non started stream ep %02X\n", ep);

        free(data);

        return;

    }



    /* bufp_alloc also adds the packet to the ep queue */

    bufp_alloc(dev, data, data_len, iso_packet->status, ep);

}

static void slavio_serial_mem_writeb(void *opaque, target_phys_addr_t addr, uint32_t val)

{

    SerialState *ser = opaque;

    ChannelState *s;

    uint32_t saddr;

    int newreg, channel;



    val &= 0xff;

    saddr = (addr & 3) >> 1;

    channel = (addr & SERIAL_MAXADDR) >> 2;

    s = &ser->chn[channel];

    switch (saddr) {

    case 0:

	SER_DPRINTF("Write channel %c, reg[%d] = %2.2x\n", CHN_C(s), s->reg, val & 0xff);

	newreg = 0;

	switch (s->reg) {

	case 0:

	    newreg = val & 7;

	    val &= 0x38;

	    switch (val) {

	    case 8:

		newreg |= 0x8;

		break;

	    case 0x28:

                clr_txint(s);

		break;

	    case 0x38:

                if (s->rxint_under_svc)

                    clr_rxint(s);

                else if (s->txint_under_svc)

                    clr_txint(s);

		break;

	    default:

		break;

	    }

	    break;

        case 1 ... 3:

        case 6 ... 8:

        case 10 ... 11:

        case 14 ... 15:

	    s->wregs[s->reg] = val;

	    break;

        case 4:

        case 5:

        case 12:

        case 13:

	    s->wregs[s->reg] = val;

            slavio_serial_update_parameters(s);

	    break;

	case 9:

	    switch (val & 0xc0) {

	    case 0:

	    default:

		break;

	    case 0x40:

		slavio_serial_reset_chn(&ser->chn[1]);

		return;

	    case 0x80:

		slavio_serial_reset_chn(&ser->chn[0]);

		return;

	    case 0xc0:

		slavio_serial_reset(ser);

		return;

	    }

	    break;

	default:

	    break;

	}

	if (s->reg == 0)

	    s->reg = newreg;

	else

	    s->reg = 0;

	break;

    case 1:

	SER_DPRINTF("Write channel %c, ch %d\n", CHN_C(s), val);

	if (s->wregs[5] & 8) { // tx enabled

	    s->tx = val;

	    if (s->chr)

		qemu_chr_write(s->chr, &s->tx, 1);

	    else if (s->type == kbd) {

		handle_kbd_command(s, val);

	    }

	    s->rregs[0] |= 4; // Tx buffer empty

	    s->rregs[1] |= 1; // All sent

            set_txint(s);

	}

	break;

    default:

	break;

    }

}

mst_fpga_writeb(void *opaque, target_phys_addr_t addr, uint64_t value,

		unsigned size)

{

	mst_irq_state *s = (mst_irq_state *) opaque;

	value &= 0xffffffff;



	switch (addr) {

	case MST_LEDDAT1:

		s->leddat1 = value;

		break;

	case MST_LEDDAT2:

		s->leddat2 = value;

		break;

	case MST_LEDCTRL:

		s->ledctrl = value;

		break;

	case MST_GPSWR:

		s->gpswr = value;

		break;

	case MST_MSCWR1:

		s->mscwr1 = value;

		break;

	case MST_MSCWR2:

		s->mscwr2 = value;

		break;

	case MST_MSCWR3:

		s->mscwr3 = value;

		break;

	case MST_MSCRD:

		s->mscrd =  value;

		break;

	case MST_INTMSKENA:	/* Mask interrupt */

		s->intmskena = (value & 0xFEEFF);

		qemu_set_irq(s->parent, s->intsetclr & s->intmskena);

		break;

	case MST_INTSETCLR:	/* clear or set interrupt */

		s->intsetclr = (value & 0xFEEFF);

		qemu_set_irq(s->parent, s->intsetclr & s->intmskena);

		break;

		/* For PCMCIAx allow the to change only power and reset */

	case MST_PCMCIA0:

		s->pcmcia0 = (value & 0x1f) | (s->pcmcia0 & ~0x1f);

		break;

	case MST_PCMCIA1:

		s->pcmcia1 = (value & 0x1f) | (s->pcmcia1 & ~0x1f);

		break;

	default:

		printf("Mainstone - mst_fpga_writeb: Bad register offset "

			"0x" TARGET_FMT_plx "\n", addr);

	}

}

static int sysctl_oldcvt(void *holdp, size_t holdlen, uint32_t kind)

{

    switch (kind & CTLTYPE) {

    case CTLTYPE_INT:

    case CTLTYPE_UINT:

        *(uint32_t *)holdp = tswap32(*(uint32_t *)holdp);

        break;

#ifdef TARGET_ABI32

    case CTLTYPE_LONG:

    case CTLTYPE_ULONG:

        *(uint32_t *)holdp = tswap32(*(long *)holdp);

        break;

#else

    case CTLTYPE_LONG:

        *(uint64_t *)holdp = tswap64(*(long *)holdp);

    case CTLTYPE_ULONG:

        *(uint64_t *)holdp = tswap64(*(unsigned long *)holdp);

        break;

#endif

#if !defined(__FreeBSD_version) || __FreeBSD_version < 900031

    case CTLTYPE_QUAD:

#else

    case CTLTYPE_U64:

#endif

        *(uint64_t *)holdp = tswap64(*(uint64_t *)holdp);

        break;

    case CTLTYPE_STRING:

        break;

    default:

        /* XXX unhandled */

        return -1;

    }

    return 0;

}

