static ssize_t qio_channel_socket_readv(QIOChannel *ioc,

                                        const struct iovec *iov,

                                        size_t niov,

                                        int **fds,

                                        size_t *nfds,

                                        Error **errp)

{

    QIOChannelSocket *sioc = QIO_CHANNEL_SOCKET(ioc);

    ssize_t ret;

    struct msghdr msg = { NULL, };

    char control[CMSG_SPACE(sizeof(int) * SOCKET_MAX_FDS)];

    int sflags = 0;



    memset(control, 0, CMSG_SPACE(sizeof(int) * SOCKET_MAX_FDS));



#ifdef MSG_CMSG_CLOEXEC

    sflags |= MSG_CMSG_CLOEXEC;

#endif



    msg.msg_iov = (struct iovec *)iov;

    msg.msg_iovlen = niov;

    if (fds && nfds) {

        msg.msg_control = control;

        msg.msg_controllen = sizeof(control);

    }



 retry:

    ret = recvmsg(sioc->fd, &msg, sflags);

    if (ret < 0) {

        if (socket_error() == EAGAIN ||

            socket_error() == EWOULDBLOCK) {

            return QIO_CHANNEL_ERR_BLOCK;

        }

        if (socket_error() == EINTR) {

            goto retry;

        }



        error_setg_errno(errp, socket_error(),

                         "Unable to read from socket");

        return -1;

    }



    if (fds && nfds) {

        qio_channel_socket_copy_fds(&msg, fds, nfds);

    }



    return ret;

}

float32 float32_sqrt( float32 a STATUS_PARAM )

{

    flag aSign;

    int16 aExp, zExp;

    bits32 aSig, zSig;

    bits64 rem, term;



    aSig = extractFloat32Frac( a );

    aExp = extractFloat32Exp( a );

    aSign = extractFloat32Sign( a );

    if ( aExp == 0xFF ) {

        if ( aSig ) return propagateFloat32NaN( a, 0 STATUS_VAR );

        if ( ! aSign ) return a;

        float_raise( float_flag_invalid STATUS_VAR);

        return float32_default_nan;

    }

    if ( aSign ) {

        if ( ( aExp | aSig ) == 0 ) return a;

        float_raise( float_flag_invalid STATUS_VAR);

        return float32_default_nan;

    }

    if ( aExp == 0 ) {

        if ( aSig == 0 ) return 0;

        normalizeFloat32Subnormal( aSig, &aExp, &aSig );

    }

    zExp = ( ( aExp - 0x7F )>>1 ) + 0x7E;

    aSig = ( aSig | 0x00800000 )<<8;

    zSig = estimateSqrt32( aExp, aSig ) + 2;

    if ( ( zSig & 0x7F ) <= 5 ) {

        if ( zSig < 2 ) {

            zSig = 0x7FFFFFFF;

            goto roundAndPack;

        }

        aSig >>= aExp & 1;

        term = ( (bits64) zSig ) * zSig;

        rem = ( ( (bits64) aSig )<<32 ) - term;

        while ( (sbits64) rem < 0 ) {

            --zSig;

            rem += ( ( (bits64) zSig )<<1 ) | 1;

        }

        zSig |= ( rem != 0 );

    }

    shift32RightJamming( zSig, 1, &zSig );

 roundAndPack:

    return roundAndPackFloat32( 0, zExp, zSig STATUS_VAR );



}

static void xhci_port_update(XHCIPort *port, int is_detach)

{

    port->portsc = PORTSC_PP;

    if (port->uport->dev && port->uport->dev->attached && !is_detach &&

        (1 << port->uport->dev->speed) & port->speedmask) {

        port->portsc |= PORTSC_CCS;

        switch (port->uport->dev->speed) {

        case USB_SPEED_LOW:

            port->portsc |= PORTSC_SPEED_LOW;

            break;

        case USB_SPEED_FULL:

            port->portsc |= PORTSC_SPEED_FULL;

            break;

        case USB_SPEED_HIGH:

            port->portsc |= PORTSC_SPEED_HIGH;

            break;

        case USB_SPEED_SUPER:

            port->portsc |= PORTSC_SPEED_SUPER;

            break;

        }

    }



    if (xhci_running(port->xhci)) {

        port->portsc |= PORTSC_CSC;

        XHCIEvent ev = { ER_PORT_STATUS_CHANGE, CC_SUCCESS,

                         port->portnr << 24};

        xhci_event(port->xhci, &ev, 0);

        DPRINTF("xhci: port change event for port %d\n", port->portnr);

    }

}

