        goto exit;

    }



    memset(&cow_header, 0, sizeof(cow_header));

    cow_header.magic = cpu_to_be32(COW_MAGIC);

    cow_header.version = cpu_to_be32(COW_VERSION);

    if (image_filename) {

        /* Note: if no file, we put a dummy mtime */

        cow_header.mtime = cpu_to_be32(0);



        if (stat(image_filename, &st) != 0) {

            goto mtime_fail;

        }

        cow_header.mtime = cpu_to_be32(st.st_mtime);

    mtime_fail:

        pstrcpy(cow_header.backing_file, sizeof(cow_header.backing_file),

                image_filename);

    }

    cow_header.sectorsize = cpu_to_be32(512);

    cow_header.size = cpu_to_be64(image_sectors * 512);

    ret = bdrv_pwrite(cow_bs, 0, &cow_header, sizeof(cow_header));

    if (ret < 0) {

        goto exit;

    }



    /* resize to include at least all the bitmap */

    ret = bdrv_truncate(cow_bs,

        sizeof(cow_header) + ((image_sectors + 7) >> 3));

    if (ret < 0) {

        goto exit;

    }



exit:

    g_free(image_filename);

    if (cow_bs) {

        bdrv_unref(cow_bs);

    }

    return ret;

}

socket_sockaddr_to_address_inet(struct sockaddr_storage *sa,

                                socklen_t salen,

                                Error **errp)

{

    char host[NI_MAXHOST];

    char serv[NI_MAXSERV];

    SocketAddressLegacy *addr;

    InetSocketAddress *inet;

    int ret;



    ret = getnameinfo((struct sockaddr *)sa, salen,

                      host, sizeof(host),

                      serv, sizeof(serv),

                      NI_NUMERICHOST | NI_NUMERICSERV);

    if (ret != 0) {

        error_setg(errp, "Cannot format numeric socket address: %s",

                   gai_strerror(ret));

        return NULL;

    }



    addr = g_new0(SocketAddressLegacy, 1);

    addr->type = SOCKET_ADDRESS_LEGACY_KIND_INET;

    inet = addr->u.inet.data = g_new0(InetSocketAddress, 1);

    inet->host = g_strdup(host);

    inet->port = g_strdup(serv);

    if (sa->ss_family == AF_INET) {

        inet->has_ipv4 = inet->ipv4 = true;

    } else {

        inet->has_ipv6 = inet->ipv6 = true;

    }



    return addr;

}

static int kvm_get_fpu(CPUState *env)

{

    struct kvm_fpu fpu;

    int i, ret;



    ret = kvm_vcpu_ioctl(env, KVM_GET_FPU, &fpu);

    if (ret < 0)

        return ret;



    env->fpstt = (fpu.fsw >> 11) & 7;

    env->fpus = fpu.fsw;

    env->fpuc = fpu.fcw;

    for (i = 0; i < 8; ++i)

	env->fptags[i] = !((fpu.ftwx >> i) & 1);

    memcpy(env->fpregs, fpu.fpr, sizeof env->fpregs);

    memcpy(env->xmm_regs, fpu.xmm, sizeof env->xmm_regs);

    env->mxcsr = fpu.mxcsr;



    return 0;

}

static void dump_aml_files(test_data *data, bool rebuild)

{

    AcpiSdtTable *sdt;

    GError *error = NULL;

    gchar *aml_file = NULL;

    gint fd;

    ssize_t ret;

    int i;



    for (i = 0; i < data->tables->len; ++i) {

        const char *ext = data->variant ? data->variant : "";

        sdt = &g_array_index(data->tables, AcpiSdtTable, i);

        g_assert(sdt->aml);



        if (rebuild) {

            uint32_t signature = cpu_to_le32(sdt->header.signature);

            aml_file = g_strdup_printf("%s/%s/%.4s%s", data_dir, data->machine,

                                       (gchar *)&signature, ext);

            fd = g_open(aml_file, O_WRONLY|O_TRUNC|O_CREAT,

                        S_IRUSR|S_IWUSR|S_IRGRP|S_IWGRP|S_IROTH);

        } else {

            fd = g_file_open_tmp("aml-XXXXXX", &sdt->aml_file, &error);

            g_assert_no_error(error);

        }

        g_assert(fd >= 0);



        ret = qemu_write_full(fd, sdt, sizeof(AcpiTableHeader));

        g_assert(ret == sizeof(AcpiTableHeader));

        ret = qemu_write_full(fd, sdt->aml, sdt->aml_len);

        g_assert(ret == sdt->aml_len);



        close(fd);



        if (aml_file) {

            g_free(aml_file);

        }

    }

}

int nbd_init(int fd, QIOChannelSocket *sioc, uint32_t flags, off_t size)

{

    TRACE("Setting NBD socket");



    if (ioctl(fd, NBD_SET_SOCK, sioc->fd) < 0) {

        int serrno = errno;

        LOG("Failed to set NBD socket");

        return -serrno;

    }



    TRACE("Setting block size to %lu", (unsigned long)BDRV_SECTOR_SIZE);



    if (ioctl(fd, NBD_SET_BLKSIZE, (size_t)BDRV_SECTOR_SIZE) < 0) {

        int serrno = errno;

        LOG("Failed setting NBD block size");

        return -serrno;

    }



    TRACE("Setting size to %zd block(s)", (size_t)(size / BDRV_SECTOR_SIZE));



    if (ioctl(fd, NBD_SET_SIZE_BLOCKS, (size_t)(size / BDRV_SECTOR_SIZE)) < 0) {

        int serrno = errno;

        LOG("Failed setting size (in blocks)");

        return -serrno;

    }



    if (ioctl(fd, NBD_SET_FLAGS, flags) < 0) {

        if (errno == ENOTTY) {

            int read_only = (flags & NBD_FLAG_READ_ONLY) != 0;

            TRACE("Setting readonly attribute");



            if (ioctl(fd, BLKROSET, (unsigned long) &read_only) < 0) {

                int serrno = errno;

                LOG("Failed setting read-only attribute");

                return -serrno;

            }

        } else {

            int serrno = errno;

            LOG("Failed setting flags");

            return -serrno;

        }

    }



    TRACE("Negotiation ended");



    return 0;

}

static void smbios_build_type_0_fields(QemuOpts *opts)

{

    const char *val;

    unsigned char major, minor;



    val = qemu_opt_get(opts, "vendor");

    if (val) {

        smbios_add_field(0, offsetof(struct smbios_type_0, vendor_str),

                         val, strlen(val) + 1);

    }

    val = qemu_opt_get(opts, "version");

    if (val) {

        smbios_add_field(0, offsetof(struct smbios_type_0, bios_version_str),

                         val, strlen(val) + 1);

    }

    val = qemu_opt_get(opts, "date");

    if (val) {

        smbios_add_field(0, offsetof(struct smbios_type_0,

                                     bios_release_date_str),

                         val, strlen(val) + 1);

    }

    val = qemu_opt_get(opts, "release");

    if (val) {

        if (sscanf(val, "%hhu.%hhu", &major, &minor) != 2) {

            error_report("Invalid release");

            exit(1);

        }

        smbios_add_field(0, offsetof(struct smbios_type_0,

                                     system_bios_major_release),

                         &major, 1);

        smbios_add_field(0, offsetof(struct smbios_type_0,

                                     system_bios_minor_release),

                         &minor, 1);

    }

}

SimpleSpiceUpdate *qemu_spice_create_update(SimpleSpiceDisplay *ssd)

{

    SimpleSpiceUpdate *update;

    QXLDrawable *drawable;

    QXLImage *image;

    QXLCommand *cmd;

    uint8_t *src, *dst;

    int by, bw, bh;



    if (qemu_spice_rect_is_empty(&ssd->dirty)) {

        return NULL;

    };



    pthread_mutex_lock(&ssd->lock);

    dprint(2, "%s: lr %d -> %d,  tb -> %d -> %d\n", __FUNCTION__,

           ssd->dirty.left, ssd->dirty.right,

           ssd->dirty.top, ssd->dirty.bottom);



    update   = qemu_mallocz(sizeof(*update));

    drawable = &update->drawable;

    image    = &update->image;

    cmd      = &update->ext.cmd;



    bw       = ssd->dirty.right - ssd->dirty.left;

    bh       = ssd->dirty.bottom - ssd->dirty.top;

    update->bitmap = qemu_malloc(bw * bh * 4);



    drawable->bbox            = ssd->dirty;

    drawable->clip.type       = SPICE_CLIP_TYPE_NONE;

    drawable->effect          = QXL_EFFECT_OPAQUE;

    drawable->release_info.id = (intptr_t)update;

    drawable->type            = QXL_DRAW_COPY;

    drawable->surfaces_dest[0] = -1;

    drawable->surfaces_dest[1] = -1;

    drawable->surfaces_dest[2] = -1;



    drawable->u.copy.rop_descriptor  = SPICE_ROPD_OP_PUT;

    drawable->u.copy.src_bitmap      = (intptr_t)image;

    drawable->u.copy.src_area.right  = bw;

    drawable->u.copy.src_area.bottom = bh;



    QXL_SET_IMAGE_ID(image, QXL_IMAGE_GROUP_DEVICE, ssd->unique++);

    image->descriptor.type   = SPICE_IMAGE_TYPE_BITMAP;

    image->bitmap.flags      = QXL_BITMAP_DIRECT | QXL_BITMAP_TOP_DOWN;

    image->bitmap.stride     = bw * 4;

    image->descriptor.width  = image->bitmap.x = bw;

    image->descriptor.height = image->bitmap.y = bh;

    image->bitmap.data = (intptr_t)(update->bitmap);

    image->bitmap.palette = 0;

    image->bitmap.format = SPICE_BITMAP_FMT_32BIT;



    if (ssd->conv == NULL) {

        PixelFormat dst = qemu_default_pixelformat(32);

        ssd->conv = qemu_pf_conv_get(&dst, &ssd->ds->surface->pf);

        assert(ssd->conv);

    }



    src = ds_get_data(ssd->ds) +

        ssd->dirty.top * ds_get_linesize(ssd->ds) +

        ssd->dirty.left * ds_get_bytes_per_pixel(ssd->ds);

    dst = update->bitmap;

    for (by = 0; by < bh; by++) {

        qemu_pf_conv_run(ssd->conv, dst, src, bw);

        src += ds_get_linesize(ssd->ds);

        dst += image->bitmap.stride;

    }



    cmd->type = QXL_CMD_DRAW;

    cmd->data = (intptr_t)drawable;



    memset(&ssd->dirty, 0, sizeof(ssd->dirty));

    pthread_mutex_unlock(&ssd->lock);

    return update;

}

void HELPER(set_cp15)(CPUARMState *env, uint32_t insn, uint32_t val)

{

    int op1;

    int op2;

    int crm;



    op1 = (insn >> 21) & 7;

    op2 = (insn >> 5) & 7;

    crm = insn & 0xf;

    switch ((insn >> 16) & 0xf) {

    case 0:

        /* ID codes.  */

        if (arm_feature(env, ARM_FEATURE_XSCALE))

            break;

        if (arm_feature(env, ARM_FEATURE_OMAPCP))

            break;

        if (arm_feature(env, ARM_FEATURE_V7)

                && op1 == 2 && crm == 0 && op2 == 0) {

            env->cp15.c0_cssel = val & 0xf;

            break;

        }

        goto bad_reg;

    case 1: /* System configuration.  */

        if (arm_feature(env, ARM_FEATURE_V7)

                && op1 == 0 && crm == 1 && op2 == 0) {

            env->cp15.c1_scr = val;

            break;

        }

        if (arm_feature(env, ARM_FEATURE_OMAPCP))

            op2 = 0;

        switch (op2) {

        case 0:

            if (!arm_feature(env, ARM_FEATURE_XSCALE) || crm == 0)

                env->cp15.c1_sys = val;

            /* ??? Lots of these bits are not implemented.  */

            /* This may enable/disable the MMU, so do a TLB flush.  */

            tlb_flush(env, 1);

            break;

        case 1: /* Auxiliary control register.  */

            if (arm_feature(env, ARM_FEATURE_XSCALE)) {

                env->cp15.c1_xscaleauxcr = val;

                break;

            }

            /* Not implemented.  */

            break;

        case 2:

            if (arm_feature(env, ARM_FEATURE_XSCALE))

                goto bad_reg;

            if (env->cp15.c1_coproc != val) {

                env->cp15.c1_coproc = val;

                /* ??? Is this safe when called from within a TB?  */

                tb_flush(env);

            }

            break;

        default:

            goto bad_reg;

        }

        break;

    case 4: /* Reserved.  */

        goto bad_reg;

    case 6: /* MMU Fault address / MPU base/size.  */

        if (arm_feature(env, ARM_FEATURE_MPU)) {

            if (crm >= 8)

                goto bad_reg;

            env->cp15.c6_region[crm] = val;

        } else {

            if (arm_feature(env, ARM_FEATURE_OMAPCP))

                op2 = 0;

            switch (op2) {

            case 0:

                env->cp15.c6_data = val;

                break;

            case 1: /* ??? This is WFAR on armv6 */

            case 2:

                env->cp15.c6_insn = val;

                break;

            default:

                goto bad_reg;

            }

        }

        break;

    case 7: /* Cache control.  */

        env->cp15.c15_i_max = 0x000;

        env->cp15.c15_i_min = 0xff0;

        if (op1 != 0) {

            goto bad_reg;

        }

        break;

    case 9:

        if (arm_feature(env, ARM_FEATURE_OMAPCP))

            break;

        if (arm_feature(env, ARM_FEATURE_STRONGARM))

            break; /* Ignore ReadBuffer access */

        switch (crm) {

        case 0: /* Cache lockdown.  */

	    switch (op1) {

	    case 0: /* L1 cache.  */

		switch (op2) {

		case 0:

		    env->cp15.c9_data = val;

		    break;

		case 1:

		    env->cp15.c9_insn = val;

		    break;

		default:

		    goto bad_reg;

		}

		break;

	    case 1: /* L2 cache.  */

		/* Ignore writes to L2 lockdown/auxiliary registers.  */

		break;

	    default:

		goto bad_reg;

	    }

	    break;

        case 1: /* TCM memory region registers.  */

            /* Not implemented.  */

            goto bad_reg;

        default:

            goto bad_reg;

        }

        break;

    case 12: /* Reserved.  */

        goto bad_reg;

    }

    return;

bad_reg:

    /* ??? For debugging only.  Should raise illegal instruction exception.  */

    cpu_abort(env, "Unimplemented cp15 register write (c%d, c%d, {%d, %d})\n",

              (insn >> 16) & 0xf, crm, op1, op2);

}

static void tcx_init(hwaddr addr, qemu_irq irq, int vram_size, int width,

                     int height, int depth)

{

    DeviceState *dev;

    SysBusDevice *s;



    dev = qdev_create(NULL, "SUNW,tcx");

    qdev_prop_set_uint32(dev, "vram_size", vram_size);

    qdev_prop_set_uint16(dev, "width", width);

    qdev_prop_set_uint16(dev, "height", height);

    qdev_prop_set_uint16(dev, "depth", depth);

    qdev_prop_set_uint64(dev, "prom_addr", addr);

    qdev_init_nofail(dev);

    s = SYS_BUS_DEVICE(dev);



    /* 10/ROM : FCode ROM */

    sysbus_mmio_map(s, 0, addr);

    /* 2/STIP : Stipple */

    sysbus_mmio_map(s, 1, addr + 0x04000000ULL);

    /* 3/BLIT : Blitter */

    sysbus_mmio_map(s, 2, addr + 0x06000000ULL);

    /* 5/RSTIP : Raw Stipple */

    sysbus_mmio_map(s, 3, addr + 0x0c000000ULL);

    /* 6/RBLIT : Raw Blitter */

    sysbus_mmio_map(s, 4, addr + 0x0e000000ULL);

    /* 7/TEC : Transform Engine */

    sysbus_mmio_map(s, 5, addr + 0x00700000ULL);

    /* 8/CMAP  : DAC */

    sysbus_mmio_map(s, 6, addr + 0x00200000ULL);

    /* 9/THC : */

    if (depth == 8) {

        sysbus_mmio_map(s, 7, addr + 0x00300000ULL);

    } else {

        sysbus_mmio_map(s, 7, addr + 0x00301000ULL);

    }

    /* 11/DHC : */

    sysbus_mmio_map(s, 8, addr + 0x00240000ULL);

    /* 12/ALT : */

    sysbus_mmio_map(s, 9, addr + 0x00280000ULL);

    /* 0/DFB8 : 8-bit plane */

    sysbus_mmio_map(s, 10, addr + 0x00800000ULL);

    /* 1/DFB24 : 24bit plane */

    sysbus_mmio_map(s, 11, addr + 0x02000000ULL);

    /* 4/RDFB32: Raw framebuffer. Control plane */

    sysbus_mmio_map(s, 12, addr + 0x0a000000ULL);

    /* 9/THC24bits : NetBSD writes here even with 8-bit display: dummy */

    if (depth == 8) {

        sysbus_mmio_map(s, 13, addr + 0x00301000ULL);

    }



    sysbus_connect_irq(s, 0, irq);

}

static int local_mknod(FsContext *fs_ctx, V9fsPath *dir_path,

                       const char *name, FsCred *credp)

{

    int err = -1;

    int dirfd;



    if (fs_ctx->export_flags & V9FS_SM_MAPPED_FILE &&

        local_is_mapped_file_metadata(fs_ctx, name)) {

        errno = EINVAL;

        return -1;

    }



    dirfd = local_opendir_nofollow(fs_ctx, dir_path->data);

    if (dirfd == -1) {

        return -1;

    }



    if (fs_ctx->export_flags & V9FS_SM_MAPPED ||

        fs_ctx->export_flags & V9FS_SM_MAPPED_FILE) {

        err = mknodat(dirfd, name, SM_LOCAL_MODE_BITS | S_IFREG, 0);

        if (err == -1) {

            goto out;

        }



        if (fs_ctx->export_flags & V9FS_SM_MAPPED) {

            err = local_set_xattrat(dirfd, name, credp);

        } else {

            err = local_set_mapped_file_attrat(dirfd, name, credp);

        }

        if (err == -1) {

            goto err_end;

        }

    } else if (fs_ctx->export_flags & V9FS_SM_PASSTHROUGH ||

               fs_ctx->export_flags & V9FS_SM_NONE) {

        err = mknodat(dirfd, name, credp->fc_mode, credp->fc_rdev);

        if (err == -1) {

            goto out;

        }

        err = local_set_cred_passthrough(fs_ctx, dirfd, name, credp);

        if (err == -1) {

            goto err_end;

        }

    }

    goto out;



err_end:

    unlinkat_preserve_errno(dirfd, name, 0);

out:

    close_preserve_errno(dirfd);

    return err;

}

static void tpm_passthrough_worker_thread(gpointer data,

                                          gpointer user_data)

{

    TPMPassthruThreadParams *thr_parms = user_data;

    TPMPassthruState *tpm_pt = thr_parms->tb->s.tpm_pt;

    TPMBackendCmd cmd = (TPMBackendCmd)data;



    DPRINTF("tpm_passthrough: processing command type %d\n", cmd);



    switch (cmd) {

    case TPM_BACKEND_CMD_PROCESS_CMD:

        tpm_passthrough_unix_transfer(tpm_pt->tpm_fd,

                                      thr_parms->tpm_state->locty_data);



        thr_parms->recv_data_callback(thr_parms->tpm_state,

                                      thr_parms->tpm_state->locty_number);

        break;

    case TPM_BACKEND_CMD_INIT:

    case TPM_BACKEND_CMD_END:

    case TPM_BACKEND_CMD_TPM_RESET:

        /* nothing to do */

        break;

    }

}

