int clp_service_call(S390CPU *cpu, uint8_t r2)

{

    ClpReqHdr *reqh;

    ClpRspHdr *resh;

    S390PCIBusDevice *pbdev;

    uint32_t req_len;

    uint32_t res_len;

    uint8_t buffer[4096 * 2];

    uint8_t cc = 0;

    CPUS390XState *env = &cpu->env;

    int i;



    cpu_synchronize_state(CPU(cpu));



    if (env->psw.mask & PSW_MASK_PSTATE) {

        program_interrupt(env, PGM_PRIVILEGED, 4);

        return 0;

    }



    if (s390_cpu_virt_mem_read(cpu, env->regs[r2], r2, buffer, sizeof(*reqh))) {

        return 0;

    }

    reqh = (ClpReqHdr *)buffer;

    req_len = lduw_p(&reqh->len);

    if (req_len < 16 || req_len > 8184 || (req_len % 8 != 0)) {

        program_interrupt(env, PGM_OPERAND, 4);

        return 0;

    }



    if (s390_cpu_virt_mem_read(cpu, env->regs[r2], r2, buffer,

                               req_len + sizeof(*resh))) {

        return 0;

    }

    resh = (ClpRspHdr *)(buffer + req_len);

    res_len = lduw_p(&resh->len);

    if (res_len < 8 || res_len > 8176 || (res_len % 8 != 0)) {

        program_interrupt(env, PGM_OPERAND, 4);

        return 0;

    }

    if ((req_len + res_len) > 8192) {

        program_interrupt(env, PGM_OPERAND, 4);

        return 0;

    }



    if (s390_cpu_virt_mem_read(cpu, env->regs[r2], r2, buffer,

                               req_len + res_len)) {

        return 0;

    }



    if (req_len != 32) {

        stw_p(&resh->rsp, CLP_RC_LEN);

        goto out;

    }



    switch (lduw_p(&reqh->cmd)) {

    case CLP_LIST_PCI: {

        ClpReqRspListPci *rrb = (ClpReqRspListPci *)buffer;

        list_pci(rrb, &cc);

        break;

    }

    case CLP_SET_PCI_FN: {

        ClpReqSetPci *reqsetpci = (ClpReqSetPci *)reqh;

        ClpRspSetPci *ressetpci = (ClpRspSetPci *)resh;



        pbdev = s390_pci_find_dev_by_fh(ldl_p(&reqsetpci->fh));

        if (!pbdev) {

                stw_p(&ressetpci->hdr.rsp, CLP_RC_SETPCIFN_FH);

                goto out;

        }



        switch (reqsetpci->oc) {

        case CLP_SET_ENABLE_PCI_FN:

            pbdev->fh |= FH_MASK_ENABLE;

            pbdev->state = ZPCI_FS_ENABLED;

            stl_p(&ressetpci->fh, pbdev->fh);

            stw_p(&ressetpci->hdr.rsp, CLP_RC_OK);

            break;

        case CLP_SET_DISABLE_PCI_FN:

            pbdev->fh &= ~FH_MASK_ENABLE;

            pbdev->state = ZPCI_FS_DISABLED;

            stl_p(&ressetpci->fh, pbdev->fh);

            stw_p(&ressetpci->hdr.rsp, CLP_RC_OK);

            break;

        default:

            DPRINTF("unknown set pci command\n");

            stw_p(&ressetpci->hdr.rsp, CLP_RC_SETPCIFN_FHOP);

            break;

        }

        break;

    }

    case CLP_QUERY_PCI_FN: {

        ClpReqQueryPci *reqquery = (ClpReqQueryPci *)reqh;

        ClpRspQueryPci *resquery = (ClpRspQueryPci *)resh;



        pbdev = s390_pci_find_dev_by_fh(ldl_p(&reqquery->fh));

        if (!pbdev) {

            DPRINTF("query pci no pci dev\n");

            stw_p(&resquery->hdr.rsp, CLP_RC_SETPCIFN_FH);

            goto out;

        }



        for (i = 0; i < PCI_BAR_COUNT; i++) {

            uint32_t data = pci_get_long(pbdev->pdev->config +

                PCI_BASE_ADDRESS_0 + (i * 4));



            stl_p(&resquery->bar[i], data);

            resquery->bar_size[i] = pbdev->pdev->io_regions[i].size ?

                                    ctz64(pbdev->pdev->io_regions[i].size) : 0;

            DPRINTF("bar %d addr 0x%x size 0x%" PRIx64 "barsize 0x%x\n", i,

                    ldl_p(&resquery->bar[i]),

                    pbdev->pdev->io_regions[i].size,

                    resquery->bar_size[i]);

        }



        stq_p(&resquery->sdma, ZPCI_SDMA_ADDR);

        stq_p(&resquery->edma, ZPCI_EDMA_ADDR);

        stl_p(&resquery->fid, pbdev->fid);

        stw_p(&resquery->pchid, 0);

        stw_p(&resquery->ug, 1);

        stl_p(&resquery->uid, pbdev->fid);

        stw_p(&resquery->hdr.rsp, CLP_RC_OK);

        break;

    }

    case CLP_QUERY_PCI_FNGRP: {

        ClpRspQueryPciGrp *resgrp = (ClpRspQueryPciGrp *)resh;

        resgrp->fr = 1;

        stq_p(&resgrp->dasm, 0);

        stq_p(&resgrp->msia, ZPCI_MSI_ADDR);

        stw_p(&resgrp->mui, 0);

        stw_p(&resgrp->i, 128);

        resgrp->version = 0;



        stw_p(&resgrp->hdr.rsp, CLP_RC_OK);

        break;

    }

    default:

        DPRINTF("unknown clp command\n");

        stw_p(&resh->rsp, CLP_RC_CMD);

        break;

    }



out:

    if (s390_cpu_virt_mem_write(cpu, env->regs[r2], r2, buffer,

                                req_len + res_len)) {

        return 0;

    }

    setcc(cpu, cc);

    return 0;

}

static void usbredir_interrupt_packet(void *priv, uint32_t id,

    struct usb_redir_interrupt_packet_header *interrupt_packet,

    uint8_t *data, int data_len)

{

    USBRedirDevice *dev = priv;

    uint8_t ep = interrupt_packet->endpoint;



    DPRINTF("interrupt-in status %d ep %02X len %d id %u\n",

            interrupt_packet->status, ep, data_len, id);



    if (dev->endpoint[EP2I(ep)].type != USB_ENDPOINT_XFER_INT) {

        ERROR("received int packet for non interrupt endpoint %02X\n", ep);

        free(data);

        return;

    }



    if (ep & USB_DIR_IN) {

        if (dev->endpoint[EP2I(ep)].interrupt_started == 0) {

            DPRINTF("received int packet while not started ep %02X\n", ep);

            free(data);

            return;

        }



        /* bufp_alloc also adds the packet to the ep queue */

        bufp_alloc(dev, data, data_len, interrupt_packet->status, ep);

    } else {

        int len = interrupt_packet->length;



        AsyncURB *aurb = async_find(dev, id);

        if (!aurb) {

            return;

        }



        if (aurb->interrupt_packet.endpoint != interrupt_packet->endpoint) {

            ERROR("return int packet mismatch, please report this!\n");

            len = USB_RET_NAK;

        }



        if (aurb->packet) {

            aurb->packet->result = usbredir_handle_status(dev,

                                               interrupt_packet->status, len);

            usb_packet_complete(&dev->dev, aurb->packet);

        }

        async_free(dev, aurb);

    }

}

static int coroutine_fn nfs_co_readv(BlockDriverState *bs,

                                     int64_t sector_num, int nb_sectors,

                                     QEMUIOVector *iov)

{

    NFSClient *client = bs->opaque;

    NFSRPC task;



    nfs_co_init_task(client, &task);

    task.iov = iov;



    if (nfs_pread_async(client->context, client->fh,

                        sector_num * BDRV_SECTOR_SIZE,

                        nb_sectors * BDRV_SECTOR_SIZE,

                        nfs_co_generic_cb, &task) != 0) {

        return -ENOMEM;

    }



    while (!task.complete) {

        nfs_set_events(client);

        qemu_coroutine_yield();

    }



    if (task.ret < 0) {

        return task.ret;

    }



    /* zero pad short reads */

    if (task.ret < iov->size) {

        qemu_iovec_memset(iov, task.ret, 0, iov->size - task.ret);

    }



    return 0;

}

int scsi_req_parse(SCSIRequest *req, uint8_t *buf)

{

    int rc;



    if (req->dev->type == TYPE_TAPE) {

        rc = scsi_req_stream_length(&req->cmd, req->dev, buf);

    } else {

        rc = scsi_req_length(&req->cmd, req->dev, buf);

    }

    if (rc != 0)

        return rc;



    assert(buf == req->cmd.buf);

    scsi_cmd_xfer_mode(&req->cmd);

    req->cmd.lba = scsi_cmd_lba(&req->cmd);

    trace_scsi_req_parsed(req->dev->id, req->lun, req->tag, buf[0],

                          req->cmd.mode, req->cmd.xfer);

    if (req->cmd.lba != -1) {

        trace_scsi_req_parsed_lba(req->dev->id, req->lun, req->tag, buf[0],

                              req->cmd.lba);

    }

    return 0;

}

void virtqueue_map_sg(struct iovec *sg, hwaddr *addr,

    size_t num_sg, int is_write)

{

    unsigned int i;

    hwaddr len;



    if (num_sg >= VIRTQUEUE_MAX_SIZE) {

        error_report("virtio: map attempt out of bounds: %zd > %d",

                     num_sg, VIRTQUEUE_MAX_SIZE);

        exit(1);

    }



    for (i = 0; i < num_sg; i++) {

        len = sg[i].iov_len;

        sg[i].iov_base = cpu_physical_memory_map(addr[i], &len, is_write);

        if (sg[i].iov_base == NULL || len != sg[i].iov_len) {

            error_report("virtio: trying to map MMIO memory");

            exit(1);

        }

    }

}

