qcrypto_tls_session_new(QCryptoTLSCreds *creds,

                        const char *hostname,

                        const char *aclname,

                        QCryptoTLSCredsEndpoint endpoint,

                        Error **errp)

{

    QCryptoTLSSession *session;

    int ret;



    session = g_new0(QCryptoTLSSession, 1);

    trace_qcrypto_tls_session_new(

        session, creds, hostname ? hostname : "<none>",

        aclname ? aclname : "<none>", endpoint);



    if (hostname) {

        session->hostname = g_strdup(hostname);

    }

    if (aclname) {

        session->aclname = g_strdup(aclname);

    }

    session->creds = creds;

    object_ref(OBJECT(creds));



    if (creds->endpoint != endpoint) {

        error_setg(errp, "Credentials endpoint doesn't match session");

        goto error;

    }



    if (endpoint == QCRYPTO_TLS_CREDS_ENDPOINT_SERVER) {

        ret = gnutls_init(&session->handle, GNUTLS_SERVER);

    } else {

        ret = gnutls_init(&session->handle, GNUTLS_CLIENT);

    }

    if (ret < 0) {

        error_setg(errp, "Cannot initialize TLS session: %s",

                   gnutls_strerror(ret));

        goto error;

    }



    if (object_dynamic_cast(OBJECT(creds),

                            TYPE_QCRYPTO_TLS_CREDS_ANON)) {

        QCryptoTLSCredsAnon *acreds = QCRYPTO_TLS_CREDS_ANON(creds);



        ret = gnutls_priority_set_direct(session->handle,

                                         "NORMAL:+ANON-DH", NULL);

        if (ret < 0) {

            error_setg(errp, "Unable to set TLS session priority: %s",

                       gnutls_strerror(ret));

            goto error;

        }

        if (creds->endpoint == QCRYPTO_TLS_CREDS_ENDPOINT_SERVER) {

            ret = gnutls_credentials_set(session->handle,

                                         GNUTLS_CRD_ANON,

                                         acreds->data.server);

        } else {

            ret = gnutls_credentials_set(session->handle,

                                         GNUTLS_CRD_ANON,

                                         acreds->data.client);

        }

        if (ret < 0) {

            error_setg(errp, "Cannot set session credentials: %s",

                       gnutls_strerror(ret));

            goto error;

        }

    } else if (object_dynamic_cast(OBJECT(creds),

                                   TYPE_QCRYPTO_TLS_CREDS_X509)) {

        QCryptoTLSCredsX509 *tcreds = QCRYPTO_TLS_CREDS_X509(creds);



        ret = gnutls_set_default_priority(session->handle);

        if (ret < 0) {

            error_setg(errp, "Cannot set default TLS session priority: %s",

                       gnutls_strerror(ret));

            goto error;

        }

        ret = gnutls_credentials_set(session->handle,

                                     GNUTLS_CRD_CERTIFICATE,

                                     tcreds->data);

        if (ret < 0) {

            error_setg(errp, "Cannot set session credentials: %s",

                       gnutls_strerror(ret));

            goto error;

        }



        if (creds->endpoint == QCRYPTO_TLS_CREDS_ENDPOINT_SERVER) {

            /* This requests, but does not enforce a client cert.

             * The cert checking code later does enforcement */

            gnutls_certificate_server_set_request(session->handle,

                                                  GNUTLS_CERT_REQUEST);

        }

    } else {

        error_setg(errp, "Unsupported TLS credentials type %s",

                   object_get_typename(OBJECT(creds)));

        goto error;

    }



    gnutls_transport_set_ptr(session->handle, session);

    gnutls_transport_set_push_function(session->handle,

                                       qcrypto_tls_session_push);

    gnutls_transport_set_pull_function(session->handle,

                                       qcrypto_tls_session_pull);



    return session;



 error:

    qcrypto_tls_session_free(session);

    return NULL;

}

static void tcg_cpu_exec(void)

{

    int ret = 0;



    if (next_cpu == NULL)

        next_cpu = first_cpu;

    for (; next_cpu != NULL; next_cpu = next_cpu->next_cpu) {

        CPUState *env = cur_cpu = next_cpu;



        if (timer_alarm_pending) {

            timer_alarm_pending = 0;

            break;

        }

        if (cpu_can_run(env))

            ret = qemu_cpu_exec(env);

        else if (env->stop)

            break;



        if (ret == EXCP_DEBUG) {

            gdb_set_stop_cpu(env);

            debug_requested = 1;

            break;

        }

    }

}

static int vfio_base_device_init(VFIODevice *vbasedev)

{

    VFIOGroup *group;

    VFIODevice *vbasedev_iter;

    char path[PATH_MAX], iommu_group_path[PATH_MAX], *group_name;

    ssize_t len;

    struct stat st;

    int groupid;

    int ret;



    /* name must be set prior to the call */

    if (!vbasedev->name || strchr(vbasedev->name, '/')) {

        return -EINVAL;

    }



    /* Check that the host device exists */

    g_snprintf(path, sizeof(path), "/sys/bus/platform/devices/%s/",

               vbasedev->name);



    if (stat(path, &st) < 0) {

        error_report("vfio: error: no such host device: %s", path);

        return -errno;

    }



    g_strlcat(path, "iommu_group", sizeof(path));

    len = readlink(path, iommu_group_path, sizeof(iommu_group_path));

    if (len < 0 || len >= sizeof(iommu_group_path)) {

        error_report("vfio: error no iommu_group for device");

        return len < 0 ? -errno : -ENAMETOOLONG;

    }



    iommu_group_path[len] = 0;

    group_name = basename(iommu_group_path);



    if (sscanf(group_name, "%d", &groupid) != 1) {

        error_report("vfio: error reading %s: %m", path);

        return -errno;

    }



    trace_vfio_platform_base_device_init(vbasedev->name, groupid);



    group = vfio_get_group(groupid, &address_space_memory);

    if (!group) {

        error_report("vfio: failed to get group %d", groupid);

        return -ENOENT;

    }



    g_snprintf(path, sizeof(path), "%s", vbasedev->name);



    QLIST_FOREACH(vbasedev_iter, &group->device_list, next) {

        if (strcmp(vbasedev_iter->name, vbasedev->name) == 0) {

            error_report("vfio: error: device %s is already attached", path);

            vfio_put_group(group);

            return -EBUSY;

        }

    }

    ret = vfio_get_device(group, path, vbasedev);

    if (ret) {

        error_report("vfio: failed to get device %s", path);

        vfio_put_group(group);

        return ret;

    }



    ret = vfio_populate_device(vbasedev);

    if (ret) {

        error_report("vfio: failed to populate device %s", path);

        vfio_put_group(group);

    }



    return ret;

}

void Y8950UpdateOne(FM_OPL *OPL, INT16 *buffer, int length)

{

    int i;

	int data;

	OPLSAMPLE *buf = buffer;

	UINT32 amsCnt  = OPL->amsCnt;

	UINT32 vibCnt  = OPL->vibCnt;

	UINT8 rythm = OPL->rythm&0x20;

	OPL_CH *CH,*R_CH;

	YM_DELTAT *DELTAT = OPL->deltat;



	/* setup DELTA-T unit */

	YM_DELTAT_DECODE_PRESET(DELTAT);



	if( (void *)OPL != cur_chip ){

		cur_chip = (void *)OPL;

		/* channel pointers */

		S_CH = OPL->P_CH;

		E_CH = &S_CH[9];

		/* rythm slot */

		SLOT7_1 = &S_CH[7].SLOT[SLOT1];

		SLOT7_2 = &S_CH[7].SLOT[SLOT2];

		SLOT8_1 = &S_CH[8].SLOT[SLOT1];

		SLOT8_2 = &S_CH[8].SLOT[SLOT2];

		/* LFO state */

		amsIncr = OPL->amsIncr;

		vibIncr = OPL->vibIncr;

		ams_table = OPL->ams_table;

		vib_table = OPL->vib_table;

	}

	R_CH = rythm ? &S_CH[6] : E_CH;

    for( i=0; i < length ; i++ )

	{

		/*            channel A         channel B         channel C      */

		/* LFO */

		ams = ams_table[(amsCnt+=amsIncr)>>AMS_SHIFT];

		vib = vib_table[(vibCnt+=vibIncr)>>VIB_SHIFT];

		outd[0] = 0;

		/* deltaT ADPCM */

		if( DELTAT->portstate )

			YM_DELTAT_ADPCM_CALC(DELTAT);

		/* FM part */

		for(CH=S_CH ; CH < R_CH ; CH++)

			OPL_CALC_CH(CH);

		/* Rythn part */

		if(rythm)

			OPL_CALC_RH(S_CH);

		/* limit check */

		data = Limit( outd[0] , OPL_MAXOUT, OPL_MINOUT );

		/* store to sound buffer */

		buf[i] = data >> OPL_OUTSB;

	}

	OPL->amsCnt = amsCnt;

	OPL->vibCnt = vibCnt;

	/* deltaT START flag */

	if( !DELTAT->portstate )

		OPL->status &= 0xfe;

}

