static uint32_t nabm_readl (void *opaque, uint32_t addr)

{

    PCIAC97LinkState *d = opaque;

    AC97LinkState *s = &d->ac97;

    AC97BusMasterRegs *r = NULL;

    uint32_t index = addr - s->base[1];

    uint32_t val = ~0U;



    switch (index) {

    case PI_BDBAR:

    case PO_BDBAR:

    case MC_BDBAR:

        r = &s->bm_regs[GET_BM (index)];

        val = r->bdbar;

        dolog ("BMADDR[%d] -> %#x\n", GET_BM (index), val);

        break;

    case PI_CIV:

    case PO_CIV:

    case MC_CIV:

        r = &s->bm_regs[GET_BM (index)];

        val = r->civ | (r->lvi << 8) | (r->sr << 16);

        dolog ("CIV LVI SR[%d] -> %#x, %#x, %#x\n", GET_BM (index),

               r->civ, r->lvi, r->sr);

        break;

    case PI_PICB:

    case PO_PICB:

    case MC_PICB:

        r = &s->bm_regs[GET_BM (index)];

        val = r->picb | (r->piv << 16) | (r->cr << 24);

        dolog ("PICB PIV CR[%d] -> %#x %#x %#x %#x\n", GET_BM (index),

               val, r->picb, r->piv, r->cr);

        break;

    case GLOB_CNT:

        val = s->glob_cnt;

        dolog ("glob_cnt -> %#x\n", val);

        break;

    case GLOB_STA:

        val = s->glob_sta | GS_S0CR;

        dolog ("glob_sta -> %#x\n", val);

        break;

    default:

        dolog ("U nabm readl %#x -> %#x\n", addr, val);

        break;

    }

    return val;

}

static uint32_t dp8393x_readl(void *opaque, target_phys_addr_t addr)

{

    uint32_t v;

    v = dp8393x_readw(opaque, addr);

    v |= dp8393x_readw(opaque, addr + 2) << 16;

    return v;

}

qcrypto_tls_creds_x509_sanity_check(QCryptoTLSCredsX509 *creds,

                                    bool isServer,

                                    const char *cacertFile,

                                    const char *certFile,

                                    Error **errp)

{

    gnutls_x509_crt_t cert = NULL;

    gnutls_x509_crt_t cacerts[MAX_CERTS];

    size_t ncacerts = 0;

    size_t i;

    int ret = -1;



    memset(cacerts, 0, sizeof(cacerts));

    if (access(certFile, R_OK) == 0) {

        cert = qcrypto_tls_creds_load_cert(creds,

                                           certFile, isServer,

                                           errp);

        if (!cert) {

            goto cleanup;

        }

    }

    if (access(cacertFile, R_OK) == 0) {

        if (qcrypto_tls_creds_load_ca_cert_list(creds,

                                                cacertFile, cacerts,

                                                MAX_CERTS, &ncacerts,

                                                errp) < 0) {

            goto cleanup;

        }

    }



    if (cert &&

        qcrypto_tls_creds_check_cert(creds,

                                     cert, certFile, isServer,

                                     false, errp) < 0) {

        goto cleanup;

    }



    for (i = 0; i < ncacerts; i++) {

        if (qcrypto_tls_creds_check_cert(creds,

                                         cacerts[i], cacertFile,

                                         isServer, true, errp) < 0) {

            goto cleanup;

        }

    }



    if (cert && ncacerts &&

        qcrypto_tls_creds_check_cert_pair(cert, certFile, cacerts,

                                          ncacerts, cacertFile,

                                          isServer, errp) < 0) {

        goto cleanup;

    }



    ret = 0;



 cleanup:

    if (cert) {

        gnutls_x509_crt_deinit(cert);

    }

    for (i = 0; i < ncacerts; i++) {

        gnutls_x509_crt_deinit(cacerts[i]);

    }

    return ret;

}

