    segoff.offset = 0xabcdef12;

    asm volatile("lfs %2, %0\n\t"

                 "movl %%fs, %1\n\t"

                 : "=r" (res), "=g" (res2)

                 : "m" (segoff));

    printf("FS:reg = %04x:%08x\n", res2, res);



