static uint32_t sdhci_read_dataport(SDHCIState *s, unsigned size)

{

    uint32_t value = 0;

    int i;



    /* first check that a valid data exists in host controller input buffer */

    if ((s->prnsts & SDHC_DATA_AVAILABLE) == 0) {

        ERRPRINT("Trying to read from empty buffer\n");

        return 0;

    }



    for (i = 0; i < size; i++) {

        value |= s->fifo_buffer[s->data_count] << i * 8;

        s->data_count++;

        /* check if we've read all valid data (blksize bytes) from buffer */

        if ((s->data_count) >= (s->blksize & 0x0fff)) {

            DPRINT_L2("All %u bytes of data have been read from input buffer\n",

                    s->data_count);

            s->prnsts &= ~SDHC_DATA_AVAILABLE; /* no more data in a buffer */

            s->data_count = 0;  /* next buff read must start at position [0] */



            if (s->trnmod & SDHC_TRNS_BLK_CNT_EN) {

                s->blkcnt--;

            }



            /* if that was the last block of data */

            if ((s->trnmod & SDHC_TRNS_MULTI) == 0 ||

                ((s->trnmod & SDHC_TRNS_BLK_CNT_EN) && (s->blkcnt == 0)) ||

                 /* stop at gap request */

                (s->stopped_state == sdhc_gap_read &&

                 !(s->prnsts & SDHC_DAT_LINE_ACTIVE))) {

                sdhci_end_transfer(s);

            } else { /* if there are more data, read next block from card */

                sdhci_read_block_from_card(s);

            }

            break;

        }

    }



    return value;

}

static int archipelago_aio_segmented_rw(BDRVArchipelagoState *s,

                                        size_t count,

                                        off_t offset,

                                        ArchipelagoAIOCB *aio_cb,

                                        int op)

{

    int i, ret, segments_nr, last_segment_size;

    ArchipelagoSegmentedRequest *segreq;



    segreq = g_malloc(sizeof(ArchipelagoSegmentedRequest));



    if (op == ARCHIP_OP_FLUSH) {

        segments_nr = 1;

        segreq->ref = segments_nr;

        segreq->total = count;

        segreq->count = 0;

        segreq->failed = 0;

        ret = archipelago_submit_request(s, 0, count, offset, aio_cb,

                                           segreq, ARCHIP_OP_FLUSH);

        if (ret < 0) {

            goto err_exit;

        }

        return 0;

    }



    segments_nr = (int)(count / MAX_REQUEST_SIZE) + \

                  ((count % MAX_REQUEST_SIZE) ? 1 : 0);

    last_segment_size = (int)(count % MAX_REQUEST_SIZE);



    segreq->ref = segments_nr;

    segreq->total = count;

    segreq->count = 0;

    segreq->failed = 0;



    for (i = 0; i < segments_nr - 1; i++) {

        ret = archipelago_submit_request(s, i * MAX_REQUEST_SIZE,

                                           MAX_REQUEST_SIZE,

                                           offset + i * MAX_REQUEST_SIZE,

                                           aio_cb, segreq, op);



        if (ret < 0) {

            goto err_exit;

        }

    }



    if ((segments_nr > 1) && last_segment_size) {

        ret = archipelago_submit_request(s, i * MAX_REQUEST_SIZE,

                                           last_segment_size,

                                           offset + i * MAX_REQUEST_SIZE,

                                           aio_cb, segreq, op);

    } else if ((segments_nr > 1) && !last_segment_size) {

        ret = archipelago_submit_request(s, i * MAX_REQUEST_SIZE,

                                           MAX_REQUEST_SIZE,

                                           offset + i * MAX_REQUEST_SIZE,

                                           aio_cb, segreq, op);

    } else if (segments_nr == 1) {

            ret = archipelago_submit_request(s, 0, count, offset, aio_cb,

                                               segreq, op);

    }



    if (ret < 0) {

        goto err_exit;

    }



    return 0;



err_exit:

    __sync_add_and_fetch(&segreq->failed, 1);

    if (segments_nr == 1) {

        if (__sync_add_and_fetch(&segreq->ref, -1) == 0) {

            g_free(segreq);

        }

    } else {

        if ((__sync_add_and_fetch(&segreq->ref, -segments_nr + i)) == 0) {

            g_free(segreq);

        }

    }



    return ret;

}

static int ram_load_dead(QEMUFile *f, void *opaque)

{

    RamDecompressState s1, *s = &s1;

    uint8_t buf[10];

    ram_addr_t i;



    if (ram_decompress_open(s, f) < 0)

        return -EINVAL;

    for(i = 0; i < last_ram_offset; i+= BDRV_HASH_BLOCK_SIZE) {

        if (ram_decompress_buf(s, buf, 1) < 0) {

            fprintf(stderr, "Error while reading ram block header\n");

            goto error;

        }

        if (buf[0] == 0) {

            if (ram_decompress_buf(s, qemu_get_ram_ptr(i),

                                   BDRV_HASH_BLOCK_SIZE) < 0) {

                fprintf(stderr, "Error while reading ram block address=0x%08" PRIx64, (uint64_t)i);

                goto error;

            }

        } else {

        error:

            printf("Error block header\n");

            return -EINVAL;

        }

    }

    ram_decompress_close(s);



    return 0;

}

static void v9fs_attach(void *opaque)

{

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;

    int32_t fid, afid, n_uname;

    V9fsString uname, aname;

    V9fsFidState *fidp;

    size_t offset = 7;

    V9fsQID qid;

    ssize_t err;



    pdu_unmarshal(pdu, offset, "ddssd", &fid, &afid, &uname, &aname, &n_uname);

    trace_v9fs_attach(pdu->tag, pdu->id, fid, afid, uname.data, aname.data);



    fidp = alloc_fid(s, fid);

    if (fidp == NULL) {

        err = -EINVAL;

        goto out_nofid;

    }

    fidp->uid = n_uname;

    err = v9fs_co_name_to_path(pdu, NULL, "/", &fidp->path);

    if (err < 0) {

        err = -EINVAL;

        clunk_fid(s, fid);

        goto out;

    }

    err = fid_to_qid(pdu, fidp, &qid);

    if (err < 0) {

        err = -EINVAL;

        clunk_fid(s, fid);

        goto out;

    }

    offset += pdu_marshal(pdu, offset, "Q", &qid);

    err = offset;

out:

    put_fid(pdu, fidp);

out_nofid:



    complete_pdu(s, pdu, err);

    v9fs_string_free(&uname);

    v9fs_string_free(&aname);

}

