static void mem_add(MemoryListener *listener, MemoryRegionSection *section)

{

    AddressSpaceDispatch *d = container_of(listener, AddressSpaceDispatch, listener);

    MemoryRegionSection now = limit(*section), remain = limit(*section);



    if ((now.offset_within_address_space & ~TARGET_PAGE_MASK)

        || (now.size < TARGET_PAGE_SIZE)) {

        now.size = MIN(TARGET_PAGE_ALIGN(now.offset_within_address_space)

                       - now.offset_within_address_space,

                       now.size);

        register_subpage(d, &now);

        remain.size -= now.size;

        remain.offset_within_address_space += now.size;

        remain.offset_within_region += now.size;

    }

    while (remain.size >= TARGET_PAGE_SIZE) {

        now = remain;

        if (remain.offset_within_region & ~TARGET_PAGE_MASK) {

            now.size = TARGET_PAGE_SIZE;

            register_subpage(d, &now);

        } else {

            now.size &= TARGET_PAGE_MASK;

            register_multipage(d, &now);

        }

        remain.size -= now.size;

        remain.offset_within_address_space += now.size;

        remain.offset_within_region += now.size;

    }

    now = remain;

    if (now.size) {

        register_subpage(d, &now);

    }

}

static void acpi_set_cpu_present_bit(AcpiCpuHotplug *g, CPUState *cpu,

                                     Error **errp)

{

    CPUClass *k = CPU_GET_CLASS(cpu);

    int64_t cpu_id;



    cpu_id = k->get_arch_id(cpu);

    if ((cpu_id / 8) >= ACPI_GPE_PROC_LEN) {

        error_setg(errp, "acpi: invalid cpu id: %" PRIi64, cpu_id);

        return;

    }



    g->sts[cpu_id / 8] |= (1 << (cpu_id % 8));

}

uint32_t HELPER(get_cp15)(CPUARMState *env, uint32_t insn)

{

    int op1;

    int op2;

    int crm;



    op1 = (insn >> 21) & 7;

    op2 = (insn >> 5) & 7;

    crm = insn & 0xf;

    switch ((insn >> 16) & 0xf) {

    case 0: /* ID codes.  */

        switch (op1) {

        case 0:

            switch (crm) {

            case 0:

                switch (op2) {

                case 0: /* Device ID.  */

                    return env->cp15.c0_cpuid;

                case 1: /* Cache Type.  */

		    return env->cp15.c0_cachetype;

                case 2: /* TCM status.  */

                    return 0;

                case 3: /* TLB type register.  */

                    return 0; /* No lockable TLB entries.  */

                case 5: /* MPIDR */

                    /* The MPIDR was standardised in v7; prior to

                     * this it was implemented only in the 11MPCore.

                     * For all other pre-v7 cores it does not exist.

                     */

                    if (arm_feature(env, ARM_FEATURE_V7) ||

                        ARM_CPUID(env) == ARM_CPUID_ARM11MPCORE) {

                        int mpidr = env->cpu_index;

                        /* We don't support setting cluster ID ([8..11])

                         * so these bits always RAZ.

                         */

                        if (arm_feature(env, ARM_FEATURE_V7MP)) {

                            mpidr |= (1 << 31);

                            /* Cores which are uniprocessor (non-coherent)

                             * but still implement the MP extensions set

                             * bit 30. (For instance, A9UP.) However we do

                             * not currently model any of those cores.

                             */

                        }

                        return mpidr;

                    }

                    /* otherwise fall through to the unimplemented-reg case */

                default:

                    goto bad_reg;

                }

            case 3: case 4: case 5: case 6: case 7:

                return 0;

            default:

                goto bad_reg;

            }

        default:

            goto bad_reg;

        }

    case 4: /* Reserved.  */

        goto bad_reg;

    case 11: /* TCM DMA control.  */

    case 12: /* Reserved.  */

        goto bad_reg;

    }

bad_reg:

    /* ??? For debugging only.  Should raise illegal instruction exception.  */

    cpu_abort(env, "Unimplemented cp15 register read (c%d, c%d, {%d, %d})\n",

              (insn >> 16) & 0xf, crm, op1, op2);

    return 0;

}

static void hpet_ram_writel(void *opaque, target_phys_addr_t addr,

                            uint32_t value)

{

    int i;

    HPETState *s = opaque;

    uint64_t old_val, new_val, val, index;



    DPRINTF("qemu: Enter hpet_ram_writel at %" PRIx64 " = %#x\n", addr, value);

    index = addr;

    old_val = hpet_ram_readl(opaque, addr);

    new_val = value;



    /*address range of all TN regs*/

    if (index >= 0x100 && index <= 0x3ff) {

        uint8_t timer_id = (addr - 0x100) / 0x20;

        HPETTimer *timer = &s->timer[timer_id];



        DPRINTF("qemu: hpet_ram_writel timer_id = %#x \n", timer_id);

        if (timer_id > s->num_timers) {

            DPRINTF("qemu: timer id out of range\n");

            return;

        }

        switch ((addr - 0x100) % 0x20) {

        case HPET_TN_CFG:

            DPRINTF("qemu: hpet_ram_writel HPET_TN_CFG\n");

            if (activating_bit(old_val, new_val, HPET_TN_FSB_ENABLE)) {

                update_irq(timer, 0);

            }

            val = hpet_fixup_reg(new_val, old_val, HPET_TN_CFG_WRITE_MASK);

            timer->config = (timer->config & 0xffffffff00000000ULL) | val;

            if (new_val & HPET_TN_32BIT) {

                timer->cmp = (uint32_t)timer->cmp;

                timer->period = (uint32_t)timer->period;

            }

            if (activating_bit(old_val, new_val, HPET_TN_ENABLE)) {

                hpet_set_timer(timer);

            } else if (deactivating_bit(old_val, new_val, HPET_TN_ENABLE)) {

                hpet_del_timer(timer);

            }

            break;

        case HPET_TN_CFG + 4: // Interrupt capabilities

            DPRINTF("qemu: invalid HPET_TN_CFG+4 write\n");

            break;

        case HPET_TN_CMP: // comparator register

            DPRINTF("qemu: hpet_ram_writel HPET_TN_CMP \n");

            if (timer->config & HPET_TN_32BIT) {

                new_val = (uint32_t)new_val;

            }

            if (!timer_is_periodic(timer)

                || (timer->config & HPET_TN_SETVAL)) {

                timer->cmp = (timer->cmp & 0xffffffff00000000ULL) | new_val;

            }

            if (timer_is_periodic(timer)) {

                /*

                 * FIXME: Clamp period to reasonable min value?

                 * Clamp period to reasonable max value

                 */

                new_val &= (timer->config & HPET_TN_32BIT ? ~0u : ~0ull) >> 1;

                timer->period =

                    (timer->period & 0xffffffff00000000ULL) | new_val;

            }

            timer->config &= ~HPET_TN_SETVAL;

            if (hpet_enabled(s)) {

                hpet_set_timer(timer);

            }

            break;

        case HPET_TN_CMP + 4: // comparator register high order

            DPRINTF("qemu: hpet_ram_writel HPET_TN_CMP + 4\n");

            if (!timer_is_periodic(timer)

                || (timer->config & HPET_TN_SETVAL)) {

                timer->cmp = (timer->cmp & 0xffffffffULL) | new_val << 32;

            } else {

                /*

                 * FIXME: Clamp period to reasonable min value?

                 * Clamp period to reasonable max value

                 */

                new_val &= (timer->config & HPET_TN_32BIT ? ~0u : ~0ull) >> 1;

                timer->period =

                    (timer->period & 0xffffffffULL) | new_val << 32;

                }

                timer->config &= ~HPET_TN_SETVAL;

                if (hpet_enabled(s)) {

                    hpet_set_timer(timer);

                }

                break;

        case HPET_TN_ROUTE:

            timer->fsb = (timer->fsb & 0xffffffff00000000ULL) | new_val;

            break;

        case HPET_TN_ROUTE + 4:

            timer->fsb = (new_val << 32) | (timer->fsb & 0xffffffff);

            break;

        default:

            DPRINTF("qemu: invalid hpet_ram_writel\n");

            break;

        }

        return;

    } else {

        switch (index) {

        case HPET_ID:

            return;

        case HPET_CFG:

            val = hpet_fixup_reg(new_val, old_val, HPET_CFG_WRITE_MASK);

            s->config = (s->config & 0xffffffff00000000ULL) | val;

            if (activating_bit(old_val, new_val, HPET_CFG_ENABLE)) {

                /* Enable main counter and interrupt generation. */

                s->hpet_offset =

                    ticks_to_ns(s->hpet_counter) - qemu_get_clock_ns(vm_clock);

                for (i = 0; i < s->num_timers; i++) {

                    if ((&s->timer[i])->cmp != ~0ULL) {

                        hpet_set_timer(&s->timer[i]);

                    }

                }

            } else if (deactivating_bit(old_val, new_val, HPET_CFG_ENABLE)) {

                /* Halt main counter and disable interrupt generation. */

                s->hpet_counter = hpet_get_ticks(s);

                for (i = 0; i < s->num_timers; i++) {

                    hpet_del_timer(&s->timer[i]);

                }

            }

            /* i8254 and RTC are disabled when HPET is in legacy mode */

            if (activating_bit(old_val, new_val, HPET_CFG_LEGACY)) {

                hpet_pit_disable();

                qemu_irq_lower(s->irqs[RTC_ISA_IRQ]);

            } else if (deactivating_bit(old_val, new_val, HPET_CFG_LEGACY)) {

                hpet_pit_enable();

                qemu_set_irq(s->irqs[RTC_ISA_IRQ], s->rtc_irq_level);

            }

            break;

        case HPET_CFG + 4:

            DPRINTF("qemu: invalid HPET_CFG+4 write \n");

            break;

        case HPET_STATUS:

            val = new_val & s->isr;

            for (i = 0; i < s->num_timers; i++) {

                if (val & (1 << i)) {

                    update_irq(&s->timer[i], 0);

                }

            }

            break;

        case HPET_COUNTER:

            if (hpet_enabled(s)) {

                DPRINTF("qemu: Writing counter while HPET enabled!\n");

            }

            s->hpet_counter =

                (s->hpet_counter & 0xffffffff00000000ULL) | value;

            DPRINTF("qemu: HPET counter written. ctr = %#x -> %" PRIx64 "\n",

                    value, s->hpet_counter);

            break;

        case HPET_COUNTER + 4:

            if (hpet_enabled(s)) {

                DPRINTF("qemu: Writing counter while HPET enabled!\n");

            }

            s->hpet_counter =

                (s->hpet_counter & 0xffffffffULL) | (((uint64_t)value) << 32);

            DPRINTF("qemu: HPET counter + 4 written. ctr = %#x -> %" PRIx64 "\n",

                    value, s->hpet_counter);

            break;

        default:

            DPRINTF("qemu: invalid hpet_ram_writel\n");

            break;

        }

    }

}

static void create_pcie(const VirtBoardInfo *vbi, qemu_irq *pic,

                        bool use_highmem)

{

    hwaddr base_mmio = vbi->memmap[VIRT_PCIE_MMIO].base;

    hwaddr size_mmio = vbi->memmap[VIRT_PCIE_MMIO].size;

    hwaddr base_mmio_high = vbi->memmap[VIRT_PCIE_MMIO_HIGH].base;

    hwaddr size_mmio_high = vbi->memmap[VIRT_PCIE_MMIO_HIGH].size;

    hwaddr base_pio = vbi->memmap[VIRT_PCIE_PIO].base;

    hwaddr size_pio = vbi->memmap[VIRT_PCIE_PIO].size;

    hwaddr base_ecam = vbi->memmap[VIRT_PCIE_ECAM].base;

    hwaddr size_ecam = vbi->memmap[VIRT_PCIE_ECAM].size;

    hwaddr base = base_mmio;

    int nr_pcie_buses = size_ecam / PCIE_MMCFG_SIZE_MIN;

    int irq = vbi->irqmap[VIRT_PCIE];

    MemoryRegion *mmio_alias;

    MemoryRegion *mmio_reg;

    MemoryRegion *ecam_alias;

    MemoryRegion *ecam_reg;

    DeviceState *dev;

    char *nodename;

    int i;



    dev = qdev_create(NULL, TYPE_GPEX_HOST);

    qdev_init_nofail(dev);



    /* Map only the first size_ecam bytes of ECAM space */

    ecam_alias = g_new0(MemoryRegion, 1);

    ecam_reg = sysbus_mmio_get_region(SYS_BUS_DEVICE(dev), 0);

    memory_region_init_alias(ecam_alias, OBJECT(dev), "pcie-ecam",

                             ecam_reg, 0, size_ecam);

    memory_region_add_subregion(get_system_memory(), base_ecam, ecam_alias);



    /* Map the MMIO window into system address space so as to expose

     * the section of PCI MMIO space which starts at the same base address

     * (ie 1:1 mapping for that part of PCI MMIO space visible through

     * the window).

     */

    mmio_alias = g_new0(MemoryRegion, 1);

    mmio_reg = sysbus_mmio_get_region(SYS_BUS_DEVICE(dev), 1);

    memory_region_init_alias(mmio_alias, OBJECT(dev), "pcie-mmio",

                             mmio_reg, base_mmio, size_mmio);

    memory_region_add_subregion(get_system_memory(), base_mmio, mmio_alias);



    if (use_highmem) {

        /* Map high MMIO space */

        MemoryRegion *high_mmio_alias = g_new0(MemoryRegion, 1);



        memory_region_init_alias(high_mmio_alias, OBJECT(dev), "pcie-mmio-high",

                                 mmio_reg, base_mmio_high, size_mmio_high);

        memory_region_add_subregion(get_system_memory(), base_mmio_high,

                                    high_mmio_alias);

    }



    /* Map IO port space */

    sysbus_mmio_map(SYS_BUS_DEVICE(dev), 2, base_pio);



    for (i = 0; i < GPEX_NUM_IRQS; i++) {

        sysbus_connect_irq(SYS_BUS_DEVICE(dev), i, pic[irq + i]);

    }



    nodename = g_strdup_printf("/pcie@%" PRIx64, base);

    qemu_fdt_add_subnode(vbi->fdt, nodename);

    qemu_fdt_setprop_string(vbi->fdt, nodename,

                            "compatible", "pci-host-ecam-generic");

    qemu_fdt_setprop_string(vbi->fdt, nodename, "device_type", "pci");

    qemu_fdt_setprop_cell(vbi->fdt, nodename, "#address-cells", 3);

    qemu_fdt_setprop_cell(vbi->fdt, nodename, "#size-cells", 2);

    qemu_fdt_setprop_cells(vbi->fdt, nodename, "bus-range", 0,

                           nr_pcie_buses - 1);



    qemu_fdt_setprop_cells(vbi->fdt, nodename, "msi-parent", vbi->v2m_phandle);



    qemu_fdt_setprop_sized_cells(vbi->fdt, nodename, "reg",

                                 2, base_ecam, 2, size_ecam);



    if (use_highmem) {

        qemu_fdt_setprop_sized_cells(vbi->fdt, nodename, "ranges",

                                     1, FDT_PCI_RANGE_IOPORT, 2, 0,

                                     2, base_pio, 2, size_pio,

                                     1, FDT_PCI_RANGE_MMIO, 2, base_mmio,

                                     2, base_mmio, 2, size_mmio,

                                     1, FDT_PCI_RANGE_MMIO_64BIT,

                                     2, base_mmio_high,

                                     2, base_mmio_high, 2, size_mmio_high);

    } else {

        qemu_fdt_setprop_sized_cells(vbi->fdt, nodename, "ranges",

                                     1, FDT_PCI_RANGE_IOPORT, 2, 0,

                                     2, base_pio, 2, size_pio,

                                     1, FDT_PCI_RANGE_MMIO, 2, base_mmio,

                                     2, base_mmio, 2, size_mmio);

    }



    qemu_fdt_setprop_cell(vbi->fdt, nodename, "#interrupt-cells", 1);

    create_pcie_irq_map(vbi, vbi->gic_phandle, irq, nodename);



    g_free(nodename);

}

int omap_validate_emifs_addr(struct omap_mpu_state_s *s,

                target_phys_addr_t addr)

