            if (!pmsav7_use_background_region(cpu, mmu_idx, is_user)) {

                /* background fault */

                fi->type = ARMFault_Background;

                return true;


            get_phys_addr_pmsav7_default(env, mmu_idx, address, prot);

        } else { /* a MPU hit! */

