                    qemu_log_mask(LOG_GUEST_ERROR,

                                  "DRACR[%d]: Bad value for AP bits: 0x%"

                                  PRIx32 "\n", n, ap);


            } else { /* Priv. mode AP bits decoding */

                switch (ap) {

                case 0:

                    break; /* no access */

                case 1:

                case 2:

                case 3:

                    *prot |= PAGE_WRITE;


                case 5:

                case 6:










                default:

                    qemu_log_mask(LOG_GUEST_ERROR,

                                  "DRACR[%d]: Bad value for AP bits: 0x%"

                                  PRIx32 "\n", n, ap);





