static uint64_t cchip_read(void *opaque, hwaddr addr, unsigned size)

{

    CPUState *cpu = current_cpu;

    TyphoonState *s = opaque;

    uint64_t ret = 0;



    if (addr & 4) {

        return s->latch_tmp;

    }



    switch (addr) {

    case 0x0000:

        /* CSC: Cchip System Configuration Register.  */

        /* All sorts of data here; probably the only thing relevant is

           PIP<14> Pchip 1 Present = 0.  */

        break;



    case 0x0040:

        /* MTR: Memory Timing Register.  */

        /* All sorts of stuff related to real DRAM.  */

        break;



    case 0x0080:

        /* MISC: Miscellaneous Register.  */

        ret = s->cchip.misc | (cpu->cpu_index & 3);

        break;



    case 0x00c0:

        /* MPD: Memory Presence Detect Register.  */

        break;



    case 0x0100: /* AAR0 */

    case 0x0140: /* AAR1 */

    case 0x0180: /* AAR2 */

    case 0x01c0: /* AAR3 */

        /* AAR: Array Address Register.  */

        /* All sorts of information about DRAM.  */

        break;



    case 0x0200:

        /* DIM0: Device Interrupt Mask Register, CPU0.  */

        ret = s->cchip.dim[0];

        break;

    case 0x0240:

        /* DIM1: Device Interrupt Mask Register, CPU1.  */

        ret = s->cchip.dim[1];

        break;

    case 0x0280:

        /* DIR0: Device Interrupt Request Register, CPU0.  */

        ret = s->cchip.dim[0] & s->cchip.drir;

        break;

    case 0x02c0:

        /* DIR1: Device Interrupt Request Register, CPU1.  */

        ret = s->cchip.dim[1] & s->cchip.drir;

        break;

    case 0x0300:

        /* DRIR: Device Raw Interrupt Request Register.  */

        ret = s->cchip.drir;

        break;



    case 0x0340:

        /* PRBEN: Probe Enable Register.  */

        break;



    case 0x0380:

        /* IIC0: Interval Ignore Count Register, CPU0.  */

        ret = s->cchip.iic[0];

        break;

    case 0x03c0:

        /* IIC1: Interval Ignore Count Register, CPU1.  */

        ret = s->cchip.iic[1];

        break;



    case 0x0400: /* MPR0 */

    case 0x0440: /* MPR1 */

    case 0x0480: /* MPR2 */

    case 0x04c0: /* MPR3 */

        /* MPR: Memory Programming Register.  */

        break;



    case 0x0580:

        /* TTR: TIGbus Timing Register.  */

        /* All sorts of stuff related to interrupt delivery timings.  */

        break;

    case 0x05c0:

        /* TDR: TIGbug Device Timing Register.  */

        break;



    case 0x0600:

        /* DIM2: Device Interrupt Mask Register, CPU2.  */

        ret = s->cchip.dim[2];

        break;

    case 0x0640:

        /* DIM3: Device Interrupt Mask Register, CPU3.  */

        ret = s->cchip.dim[3];

        break;

    case 0x0680:

        /* DIR2: Device Interrupt Request Register, CPU2.  */

        ret = s->cchip.dim[2] & s->cchip.drir;

        break;

    case 0x06c0:

        /* DIR3: Device Interrupt Request Register, CPU3.  */

        ret = s->cchip.dim[3] & s->cchip.drir;

        break;



    case 0x0700:

        /* IIC2: Interval Ignore Count Register, CPU2.  */

        ret = s->cchip.iic[2];

        break;

    case 0x0740:

        /* IIC3: Interval Ignore Count Register, CPU3.  */

        ret = s->cchip.iic[3];

        break;



    case 0x0780:

        /* PWR: Power Management Control.   */

        break;



    case 0x0c00: /* CMONCTLA */

    case 0x0c40: /* CMONCTLB */

    case 0x0c80: /* CMONCNT01 */

    case 0x0cc0: /* CMONCNT23 */

        break;



    default:

        cpu_unassigned_access(cpu, addr, false, false, 0, size);

        return -1;

    }



    s->latch_tmp = ret >> 32;

    return ret;

}

static int blk_init(struct XenDevice *xendev)

{

    struct XenBlkDev *blkdev = container_of(xendev, struct XenBlkDev, xendev);

    int index, qflags, have_barriers, info = 0;

    char *h;



    /* read xenstore entries */

    if (blkdev->params == NULL) {

	blkdev->params = xenstore_read_be_str(&blkdev->xendev, "params");

        h = strchr(blkdev->params, ':');

	if (h != NULL) {

	    blkdev->fileproto = blkdev->params;

	    blkdev->filename  = h+1;

	    *h = 0;

	} else {

	    blkdev->fileproto = "<unset>";

	    blkdev->filename  = blkdev->params;

	}

    }

    if (blkdev->mode == NULL)

	blkdev->mode = xenstore_read_be_str(&blkdev->xendev, "mode");

    if (blkdev->type == NULL)

	blkdev->type = xenstore_read_be_str(&blkdev->xendev, "type");

    if (blkdev->dev == NULL)

	blkdev->dev = xenstore_read_be_str(&blkdev->xendev, "dev");

    if (blkdev->devtype == NULL)

	blkdev->devtype = xenstore_read_be_str(&blkdev->xendev, "device-type");



    /* do we have all we need? */

    if (blkdev->params == NULL ||

	blkdev->mode == NULL   ||

	blkdev->type == NULL   ||

	blkdev->dev == NULL)

	return -1;



    /* read-only ? */

    if (strcmp(blkdev->mode, "w") == 0) {

	qflags = BDRV_O_RDWR;

    } else {

	qflags = 0;

	info  |= VDISK_READONLY;

    }



    /* cdrom ? */

    if (blkdev->devtype && !strcmp(blkdev->devtype, "cdrom"))

	info  |= VDISK_CDROM;



    /* init qemu block driver */

    index = (blkdev->xendev.dev - 202 * 256) / 16;

    blkdev->dinfo = drive_get(IF_XEN, 0, index);

    if (!blkdev->dinfo) {

        /* setup via xenbus -> create new block driver instance */

        xen_be_printf(&blkdev->xendev, 2, "create new bdrv (xenbus setup)\n");

	blkdev->bs = bdrv_new(blkdev->dev);

	if (blkdev->bs) {

	    if (bdrv_open(blkdev->bs, blkdev->filename, qflags,

                           bdrv_find_whitelisted_format(blkdev->fileproto))

                != 0) {

		bdrv_delete(blkdev->bs);

		blkdev->bs = NULL;

	    }

	}

	if (!blkdev->bs)

	    return -1;

    } else {

        /* setup via qemu cmdline -> already setup for us */

        xen_be_printf(&blkdev->xendev, 2, "get configured bdrv (cmdline setup)\n");

	blkdev->bs = blkdev->dinfo->bdrv;

    }

    blkdev->file_blk  = BLOCK_SIZE;

    blkdev->file_size = bdrv_getlength(blkdev->bs);

    if (blkdev->file_size < 0) {

        xen_be_printf(&blkdev->xendev, 1, "bdrv_getlength: %d (%s) | drv %s\n",

                      (int)blkdev->file_size, strerror(-blkdev->file_size),

                      blkdev->bs->drv ? blkdev->bs->drv->format_name : "-");

	blkdev->file_size = 0;

    }

    have_barriers = blkdev->bs->drv && blkdev->bs->drv->bdrv_flush ? 1 : 0;



    xen_be_printf(xendev, 1, "type \"%s\", fileproto \"%s\", filename \"%s\","

		  " size %" PRId64 " (%" PRId64 " MB)\n",

		  blkdev->type, blkdev->fileproto, blkdev->filename,

		  blkdev->file_size, blkdev->file_size >> 20);



    /* fill info */

    xenstore_write_be_int(&blkdev->xendev, "feature-barrier", have_barriers);

    xenstore_write_be_int(&blkdev->xendev, "info",            info);

    xenstore_write_be_int(&blkdev->xendev, "sector-size",     blkdev->file_blk);

    xenstore_write_be_int(&blkdev->xendev, "sectors",

			  blkdev->file_size / blkdev->file_blk);

    return 0;

}

static void register_subpage(AddressSpaceDispatch *d, MemoryRegionSection *section)

{

    subpage_t *subpage;

    hwaddr base = section->offset_within_address_space

        & TARGET_PAGE_MASK;

    MemoryRegionSection *existing = phys_page_find(d->phys_map, base,

                                                   next_map.nodes, next_map.sections);

    MemoryRegionSection subsection = {

        .offset_within_address_space = base,

        .size = int128_make64(TARGET_PAGE_SIZE),

    };

    hwaddr start, end;



    assert(existing->mr->subpage || existing->mr == &io_mem_unassigned);



    if (!(existing->mr->subpage)) {

        subpage = subpage_init(d->as, base);

        subsection.mr = &subpage->iomem;

        phys_page_set(d, base >> TARGET_PAGE_BITS, 1,

                      phys_section_add(&subsection));

    } else {

        subpage = container_of(existing->mr, subpage_t, iomem);

    }

    start = section->offset_within_address_space & ~TARGET_PAGE_MASK;

    end = start + int128_get64(section->size) - 1;

    subpage_register(subpage, start, end, phys_section_add(section));

}

