static void virtio_net_handle_ctrl(VirtIODevice *vdev, VirtQueue *vq)

{

    VirtIONet *n = VIRTIO_NET(vdev);

    struct virtio_net_ctrl_hdr ctrl;

    virtio_net_ctrl_ack status = VIRTIO_NET_ERR;

    VirtQueueElement elem;

    size_t s;

    struct iovec *iov, *iov2;

    unsigned int iov_cnt;



    while (virtqueue_pop(vq, &elem)) {

        if (iov_size(elem.in_sg, elem.in_num) < sizeof(status) ||

            iov_size(elem.out_sg, elem.out_num) < sizeof(ctrl)) {

            error_report("virtio-net ctrl missing headers");

            exit(1);

        }



        iov_cnt = elem.out_num;

        iov2 = iov = g_memdup(elem.out_sg, sizeof(struct iovec) * elem.out_num);

        s = iov_to_buf(iov, iov_cnt, 0, &ctrl, sizeof(ctrl));

        iov_discard_front(&iov, &iov_cnt, sizeof(ctrl));

        if (s != sizeof(ctrl)) {

            status = VIRTIO_NET_ERR;

        } else if (ctrl.class == VIRTIO_NET_CTRL_RX) {

            status = virtio_net_handle_rx_mode(n, ctrl.cmd, iov, iov_cnt);

        } else if (ctrl.class == VIRTIO_NET_CTRL_MAC) {

            status = virtio_net_handle_mac(n, ctrl.cmd, iov, iov_cnt);

        } else if (ctrl.class == VIRTIO_NET_CTRL_VLAN) {

            status = virtio_net_handle_vlan_table(n, ctrl.cmd, iov, iov_cnt);

        } else if (ctrl.class == VIRTIO_NET_CTRL_ANNOUNCE) {

            status = virtio_net_handle_announce(n, ctrl.cmd, iov, iov_cnt);

        } else if (ctrl.class == VIRTIO_NET_CTRL_MQ) {

            status = virtio_net_handle_mq(n, ctrl.cmd, iov, iov_cnt);

        } else if (ctrl.class == VIRTIO_NET_CTRL_GUEST_OFFLOADS) {

            status = virtio_net_handle_offloads(n, ctrl.cmd, iov, iov_cnt);

        }



        s = iov_from_buf(elem.in_sg, elem.in_num, 0, &status, sizeof(status));

        assert(s == sizeof(status));



        virtqueue_push(vq, &elem, sizeof(status));

        virtio_notify(vdev, vq);

        g_free(iov2);

    }

}

void cpu_exec_realizefn(CPUState *cpu, Error **errp)

{

    CPUClass *cc = CPU_GET_CLASS(cpu);



    cpu_list_add(cpu);



    if (tcg_enabled() && !cc->tcg_initialized) {

        cc->tcg_initialized = true;

        cc->tcg_initialize();

    }



#ifndef CONFIG_USER_ONLY

    if (qdev_get_vmsd(DEVICE(cpu)) == NULL) {

        vmstate_register(NULL, cpu->cpu_index, &vmstate_cpu_common, cpu);

    }

    if (cc->vmsd != NULL) {

        vmstate_register(NULL, cpu->cpu_index, cc->vmsd, cpu);

    }

#endif

}

float32 helper_fitos(CPUSPARCState *env, int32_t src)

{

    /* Inexact error possible converting int to float.  */

    float32 ret;

    clear_float_exceptions(env);

    ret = int32_to_float32(src, &env->fp_status);

    check_ieee_exceptions(env);

    return ret;

}

static void test_wait_event_notifier(void)

{

    EventNotifierTestData data = { .n = 0, .active = 1 };

    event_notifier_init(&data.e, false);

    aio_set_event_notifier(ctx, &data.e, event_ready_cb);

    g_assert(!aio_poll(ctx, false));

    g_assert_cmpint(data.n, ==, 0);

    g_assert_cmpint(data.active, ==, 1);



    event_notifier_set(&data.e);

    g_assert(aio_poll(ctx, false));

    g_assert_cmpint(data.n, ==, 1);

    g_assert_cmpint(data.active, ==, 0);



    g_assert(!aio_poll(ctx, false));

    g_assert_cmpint(data.n, ==, 1);

    g_assert_cmpint(data.active, ==, 0);



    aio_set_event_notifier(ctx, &data.e, NULL);

    g_assert(!aio_poll(ctx, false));

    g_assert_cmpint(data.n, ==, 1);



    event_notifier_cleanup(&data.e);

}

static void bswap_shdr(struct elf_shdr *shdr)

{

    bswap32s(&shdr->sh_name);

    bswap32s(&shdr->sh_type);

    bswaptls(&shdr->sh_flags);

    bswaptls(&shdr->sh_addr);

    bswaptls(&shdr->sh_offset);

    bswaptls(&shdr->sh_size);

    bswap32s(&shdr->sh_link);

    bswap32s(&shdr->sh_info);

    bswaptls(&shdr->sh_addralign);

    bswaptls(&shdr->sh_entsize);

}

void fdt_build_clock_node(void *host_fdt, void *guest_fdt,

                         uint32_t host_phandle,

                         uint32_t guest_phandle)

{

    char *node_path = NULL;

    char *nodename;

    const void *r;

    int ret, node_offset, prop_len, path_len = 16;



    node_offset = fdt_node_offset_by_phandle(host_fdt, host_phandle);

    if (node_offset <= 0) {

        error_setg(&error_fatal,

                   "not able to locate clock handle %d in host device tree",

                   host_phandle);

    }

    node_path = g_malloc(path_len);

    while ((ret = fdt_get_path(host_fdt, node_offset, node_path, path_len))

            == -FDT_ERR_NOSPACE) {

        path_len += 16;

        node_path = g_realloc(node_path, path_len);

    }

    if (ret < 0) {

        error_setg(&error_fatal,

                   "not able to retrieve node path for clock handle %d",

                   host_phandle);

    }



    r = qemu_fdt_getprop(host_fdt, node_path, "compatible", &prop_len,

                         &error_fatal);

    if (strcmp(r, "fixed-clock")) {

        error_setg(&error_fatal,

                   "clock handle %d is not a fixed clock", host_phandle);

    }



    nodename = strrchr(node_path, '/');

    qemu_fdt_add_subnode(guest_fdt, nodename);



    copy_properties_from_host(clock_copied_properties,

                              ARRAY_SIZE(clock_copied_properties),

                              host_fdt, guest_fdt,

                              node_path, nodename);



    qemu_fdt_setprop_cell(guest_fdt, nodename, "phandle", guest_phandle);



    g_free(node_path);

}

static always_inline int _find_pte (mmu_ctx_t *ctx, int is_64b, int h, int rw)

{

    target_ulong base, pte0, pte1;

    int i, good = -1;

    int ret, r;



    ret = -1; /* No entry found */

    base = ctx->pg_addr[h];

    for (i = 0; i < 8; i++) {

#if defined(TARGET_PPC64)

        if (is_64b) {

            pte0 = ldq_phys(base + (i * 16));

            pte1 =  ldq_phys(base + (i * 16) + 8);

            r = pte64_check(ctx, pte0, pte1, h, rw);

#if defined (DEBUG_MMU)

            if (loglevel != 0) {

                fprintf(logfile, "Load pte from 0x" ADDRX " => 0x" ADDRX

                        " 0x" ADDRX " %d %d %d 0x" ADDRX "\n",

                        base + (i * 16), pte0, pte1,

                        (int)(pte0 & 1), h, (int)((pte0 >> 1) & 1),

                        ctx->ptem);

            }

#endif

        } else

#endif

        {

            pte0 = ldl_phys(base + (i * 8));

            pte1 =  ldl_phys(base + (i * 8) + 4);

            r = pte32_check(ctx, pte0, pte1, h, rw);

#if defined (DEBUG_MMU)

            if (loglevel != 0) {

                fprintf(logfile, "Load pte from 0x" ADDRX " => 0x" ADDRX

                        " 0x" ADDRX " %d %d %d 0x" ADDRX "\n",

                        base + (i * 8), pte0, pte1,

                        (int)(pte0 >> 31), h, (int)((pte0 >> 6) & 1),

                        ctx->ptem);

            }

#endif

        }

        switch (r) {

        case -3:

            /* PTE inconsistency */

            return -1;

        case -2:

            /* Access violation */

            ret = -2;

            good = i;

            break;

        case -1:

        default:

            /* No PTE match */

            break;

        case 0:

            /* access granted */

            /* XXX: we should go on looping to check all PTEs consistency

             *      but if we can speed-up the whole thing as the

             *      result would be undefined if PTEs are not consistent.

             */

            ret = 0;

            good = i;

            goto done;

        }

    }

    if (good != -1) {

    done:

#if defined (DEBUG_MMU)

        if (loglevel != 0) {

            fprintf(logfile, "found PTE at addr 0x" PADDRX " prot=0x%01x "

                    "ret=%d\n",

                    ctx->raddr, ctx->prot, ret);

        }

#endif

        /* Update page flags */

        pte1 = ctx->raddr;

        if (pte_update_flags(ctx, &pte1, ret, rw) == 1) {

#if defined(TARGET_PPC64)

            if (is_64b) {

                stq_phys_notdirty(base + (good * 16) + 8, pte1);

            } else

#endif

            {

                stl_phys_notdirty(base + (good * 8) + 4, pte1);

            }

        }

    }



    return ret;

}

static void x86_cpu_register_feature_bit_props(X86CPU *cpu,

                                               FeatureWord w,

                                               int bitnr)

{

    Object *obj = OBJECT(cpu);

    int i;

    char **names;

    FeatureWordInfo *fi = &feature_word_info[w];



    if (!fi->feat_names[bitnr]) {

        return;

    }



    names = g_strsplit(fi->feat_names[bitnr], "|", 0);



    feat2prop(names[0]);

    x86_cpu_register_bit_prop(cpu, names[0], &cpu->env.features[w], bitnr);



    for (i = 1; names[i]; i++) {

        feat2prop(names[i]);

        object_property_add_alias(obj, names[i], obj, names[0],

                                  &error_abort);

    }



    g_strfreev(names);

}

