static void aio_write_done(void *opaque, int ret)

{

    struct aio_ctx *ctx = opaque;

    struct timeval t2;



    gettimeofday(&t2, NULL);





    if (ret < 0) {

        printf("aio_write failed: %s\n", strerror(-ret));

        goto out;

    }



    if (ctx->qflag) {

        goto out;

    }



    /* Finally, report back -- -C gives a parsable format */

    t2 = tsub(t2, ctx->t1);

    print_report("wrote", &t2, ctx->offset, ctx->qiov.size,

                 ctx->qiov.size, 1, ctx->Cflag);

out:

    qemu_io_free(ctx->buf);


    g_free(ctx);

}

static void ehci_reset(void *opaque)

{

    EHCIState *s = opaque;

    int i;

    USBDevice *devs[NB_PORTS];



    trace_usb_ehci_reset();



    /*

     * Do the detach before touching portsc, so that it correctly gets send to

     * us or to our companion based on PORTSC_POWNER before the reset.

     */

    for(i = 0; i < NB_PORTS; i++) {

        devs[i] = s->ports[i].dev;

        if (devs[i] && devs[i]->attached) {

            usb_detach(&s->ports[i]);

        }

    }



    memset(&s->mmio[OPREGBASE], 0x00, MMIO_SIZE - OPREGBASE);



    s->usbcmd = NB_MAXINTRATE << USBCMD_ITC_SH;

    s->usbsts = USBSTS_HALT;

    s->usbsts_pending = 0;

    s->usbsts_frindex = 0;



    s->astate = EST_INACTIVE;

    s->pstate = EST_INACTIVE;



    for(i = 0; i < NB_PORTS; i++) {

        if (s->companion_ports[i]) {

            s->portsc[i] = PORTSC_POWNER | PORTSC_PPOWER;

        } else {

            s->portsc[i] = PORTSC_PPOWER;

        }

        if (devs[i] && devs[i]->attached) {

            usb_attach(&s->ports[i]);

            usb_device_reset(devs[i]);

        }

    }

    ehci_queues_rip_all(s, 0);

    ehci_queues_rip_all(s, 1);

    qemu_del_timer(s->frame_timer);

    qemu_bh_cancel(s->async_bh);

}

void OPPROTO op_POWER_slq (void)

{

    uint32_t msk = -1, tmp;



    msk = msk << (T1 & 0x1FUL);

    if (T1 & 0x20UL)

        msk = ~msk;

    T1 &= 0x1FUL;

    tmp = rotl32(T0, T1);

    T0 = tmp & msk;

    env->spr[SPR_MQ] = tmp;

    RETURN();

}

static int qio_channel_command_close(QIOChannel *ioc,

                                     Error **errp)

{

    QIOChannelCommand *cioc = QIO_CHANNEL_COMMAND(ioc);

    int rv = 0;



    /* We close FDs before killing, because that

     * gives a better chance of clean shutdown

     */

    if (close(cioc->writefd) < 0) {

        rv = -1;

    }

    if (close(cioc->readfd) < 0) {

        rv = -1;

    }

#ifndef WIN32

    if (qio_channel_command_abort(cioc, errp) < 0) {

        return -1;

    }

#endif

    if (rv < 0) {

        error_setg_errno(errp, errno, "%s",

                         "Unable to close command");

    }

    return rv;

}

void sh_intc_register_sources(struct intc_desc *desc,

			      struct intc_vect *vectors,

			      int nr_vectors,

			      struct intc_group *groups,

			      int nr_groups)

{

    unsigned int i, k;

    struct intc_source *s;



    for (i = 0; i < nr_vectors; i++) {

	struct intc_vect *vect = vectors + i;



	sh_intc_register_source(desc, vect->enum_id, groups, nr_groups);

	s = sh_intc_source(desc, vect->enum_id);

	if (s)

	    s->vect = vect->vect;



#ifdef DEBUG_INTC_SOURCES

	printf("sh_intc: registered source %d -> 0x%04x (%d/%d)\n",

	       vect->enum_id, s->vect, s->enable_count, s->enable_max);

#endif

    }



    if (groups) {

        for (i = 0; i < nr_groups; i++) {

	    struct intc_group *gr = groups + i;



	    s = sh_intc_source(desc, gr->enum_id);

	    s->next_enum_id = gr->enum_ids[0];



	    for (k = 1; k < ARRAY_SIZE(gr->enum_ids); k++) {

                if (!gr->enum_ids[k])

                    continue;



		s = sh_intc_source(desc, gr->enum_ids[k - 1]);

		s->next_enum_id = gr->enum_ids[k];

	    }



#ifdef DEBUG_INTC_SOURCES

	    printf("sh_intc: registered group %d (%d/%d)\n",

		   gr->enum_id, s->enable_count, s->enable_max);

#endif

	}

    }

}

void sparc64_get_context(CPUSPARCState *env)

{

    abi_ulong ucp_addr;

    struct target_ucontext *ucp;

    target_mc_gregset_t *grp;

    target_mcontext_t *mcp;

    abi_ulong fp, i7, w_addr;

    int err;

    unsigned int i;

    target_sigset_t target_set;

    sigset_t set;



    ucp_addr = env->regwptr[UREG_I0];

    if (!lock_user_struct(VERIFY_WRITE, ucp, ucp_addr, 0)) {

        goto do_sigsegv;

    }



    mcp = &ucp->tuc_mcontext;

    grp = &mcp->mc_gregs;



    /* Skip over the trap instruction, first. */

    env->pc = env->npc;

    env->npc += 4;



    err = 0;



    do_sigprocmask(0, NULL, &set);

    host_to_target_sigset_internal(&target_set, &set);

    if (TARGET_NSIG_WORDS == 1) {

        __put_user(target_set.sig[0],

                   (abi_ulong *)&ucp->tuc_sigmask);

    } else {

        abi_ulong *src, *dst;

        src = target_set.sig;

        dst = ucp->tuc_sigmask.sig;

        for (i = 0; i < TARGET_NSIG_WORDS; i++, dst++, src++) {

            __put_user(*src, dst);

        }

        if (err)

            goto do_sigsegv;

    }



    /* XXX: tstate must be saved properly */

    //    __put_user(env->tstate, &((*grp)[MC_TSTATE]));

    __put_user(env->pc, &((*grp)[MC_PC]));

    __put_user(env->npc, &((*grp)[MC_NPC]));

    __put_user(env->y, &((*grp)[MC_Y]));

    __put_user(env->gregs[1], &((*grp)[MC_G1]));

    __put_user(env->gregs[2], &((*grp)[MC_G2]));

    __put_user(env->gregs[3], &((*grp)[MC_G3]));

    __put_user(env->gregs[4], &((*grp)[MC_G4]));

    __put_user(env->gregs[5], &((*grp)[MC_G5]));

    __put_user(env->gregs[6], &((*grp)[MC_G6]));

    __put_user(env->gregs[7], &((*grp)[MC_G7]));

    __put_user(env->regwptr[UREG_I0], &((*grp)[MC_O0]));

    __put_user(env->regwptr[UREG_I1], &((*grp)[MC_O1]));

    __put_user(env->regwptr[UREG_I2], &((*grp)[MC_O2]));

    __put_user(env->regwptr[UREG_I3], &((*grp)[MC_O3]));

    __put_user(env->regwptr[UREG_I4], &((*grp)[MC_O4]));

    __put_user(env->regwptr[UREG_I5], &((*grp)[MC_O5]));

    __put_user(env->regwptr[UREG_I6], &((*grp)[MC_O6]));

    __put_user(env->regwptr[UREG_I7], &((*grp)[MC_O7]));



    w_addr = TARGET_STACK_BIAS+env->regwptr[UREG_I6];

    fp = i7 = 0;

    if (get_user(fp, w_addr + offsetof(struct target_reg_window, ins[6]),

                 abi_ulong) != 0) {

        goto do_sigsegv;

    }

    if (get_user(i7, w_addr + offsetof(struct target_reg_window, ins[7]),

                 abi_ulong) != 0) {

        goto do_sigsegv;

    }

    __put_user(fp, &(mcp->mc_fp));

    __put_user(i7, &(mcp->mc_i7));



    {

        uint32_t *dst = ucp->tuc_mcontext.mc_fpregs.mcfpu_fregs.sregs;

        for (i = 0; i < 64; i++, dst++) {

            if (i & 1) {

                __put_user(env->fpr[i/2].l.lower, dst);

            } else {

                __put_user(env->fpr[i/2].l.upper, dst);

            }

        }

    }

    __put_user(env->fsr, &(mcp->mc_fpregs.mcfpu_fsr));

    __put_user(env->gsr, &(mcp->mc_fpregs.mcfpu_gsr));

    __put_user(env->fprs, &(mcp->mc_fpregs.mcfpu_fprs));



    if (err)

        goto do_sigsegv;

    unlock_user_struct(ucp, ucp_addr, 1);

    return;

do_sigsegv:

    unlock_user_struct(ucp, ucp_addr, 1);

    force_sig(TARGET_SIGSEGV);

}

