                        goto graphic_error;

                    if (*p == 'x') {

                        p++;

                        depth = strtol(p, (char **)&p, 10);

                        if (depth != 8 && depth != 15 && depth != 16 &&

                            depth != 24 && depth != 32)

                            goto graphic_error;

                    } else if (*p == '\0') {

                        depth = graphic_depth;

                    } else {

                        goto graphic_error;

                    }



                    graphic_width = w;

                    graphic_height = h;

                    graphic_depth = depth;

                }

                break;

            case QEMU_OPTION_echr:

