                    exit(1);

                }

                opts = qemu_opts_parse(olist, optarg, 0);

                if (!opts) {

                    fprintf(stderr, "parse error: %s\n", optarg);

                    exit(1);

                }

                break;

            case QEMU_OPTION_writeconfig:

                {

                    FILE *fp;

                    if (strcmp(optarg, "-") == 0) {

                        fp = stdout;

