int qemu_sem_timedwait(QemuSemaphore *sem, int ms)

{

    int rc = WaitForSingleObject(sem->sema, ms);

    if (rc == WAIT_OBJECT_0) {

        return 0;

    }

    if (rc != WAIT_TIMEOUT) {

        error_exit(GetLastError(), __func__);

    }

    return -1;

}

static void disas_simd_3same_int(DisasContext *s, uint32_t insn)

{

    int is_q = extract32(insn, 30, 1);

    int u = extract32(insn, 29, 1);

    int size = extract32(insn, 22, 2);

    int opcode = extract32(insn, 11, 5);

    int rm = extract32(insn, 16, 5);

    int rn = extract32(insn, 5, 5);

    int rd = extract32(insn, 0, 5);

    int pass;



    switch (opcode) {

    case 0x13: /* MUL, PMUL */

        if (u && size != 0) {

            unallocated_encoding(s);

            return;

        }

        /* fall through */

    case 0x0: /* SHADD, UHADD */

    case 0x2: /* SRHADD, URHADD */

    case 0x4: /* SHSUB, UHSUB */

    case 0xc: /* SMAX, UMAX */

    case 0xd: /* SMIN, UMIN */

    case 0xe: /* SABD, UABD */

    case 0xf: /* SABA, UABA */

    case 0x12: /* MLA, MLS */

        if (size == 3) {

            unallocated_encoding(s);

            return;

        }

        break;

    case 0x16: /* SQDMULH, SQRDMULH */

        if (size == 0 || size == 3) {

            unallocated_encoding(s);

            return;

        }

        break;

    default:

        if (size == 3 && !is_q) {

            unallocated_encoding(s);

            return;

        }

        break;

    }



    if (!fp_access_check(s)) {

        return;

    }



    if (size == 3) {

        for (pass = 0; pass < (is_q ? 2 : 1); pass++) {

            TCGv_i64 tcg_op1 = tcg_temp_new_i64();

            TCGv_i64 tcg_op2 = tcg_temp_new_i64();

            TCGv_i64 tcg_res = tcg_temp_new_i64();



            read_vec_element(s, tcg_op1, rn, pass, MO_64);

            read_vec_element(s, tcg_op2, rm, pass, MO_64);



            handle_3same_64(s, opcode, u, tcg_res, tcg_op1, tcg_op2);



            write_vec_element(s, tcg_res, rd, pass, MO_64);



            tcg_temp_free_i64(tcg_res);

            tcg_temp_free_i64(tcg_op1);

            tcg_temp_free_i64(tcg_op2);

        }

    } else {

        for (pass = 0; pass < (is_q ? 4 : 2); pass++) {

            TCGv_i32 tcg_op1 = tcg_temp_new_i32();

            TCGv_i32 tcg_op2 = tcg_temp_new_i32();

            TCGv_i32 tcg_res = tcg_temp_new_i32();

            NeonGenTwoOpFn *genfn = NULL;

            NeonGenTwoOpEnvFn *genenvfn = NULL;



            read_vec_element_i32(s, tcg_op1, rn, pass, MO_32);

            read_vec_element_i32(s, tcg_op2, rm, pass, MO_32);



            switch (opcode) {

            case 0x0: /* SHADD, UHADD */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_hadd_s8, gen_helper_neon_hadd_u8 },

                    { gen_helper_neon_hadd_s16, gen_helper_neon_hadd_u16 },

                    { gen_helper_neon_hadd_s32, gen_helper_neon_hadd_u32 },

                };

                genfn = fns[size][u];

                break;

            }

            case 0x1: /* SQADD, UQADD */

            {

                static NeonGenTwoOpEnvFn * const fns[3][2] = {

                    { gen_helper_neon_qadd_s8, gen_helper_neon_qadd_u8 },

                    { gen_helper_neon_qadd_s16, gen_helper_neon_qadd_u16 },

                    { gen_helper_neon_qadd_s32, gen_helper_neon_qadd_u32 },

                };

                genenvfn = fns[size][u];

                break;

            }

            case 0x2: /* SRHADD, URHADD */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_rhadd_s8, gen_helper_neon_rhadd_u8 },

                    { gen_helper_neon_rhadd_s16, gen_helper_neon_rhadd_u16 },

                    { gen_helper_neon_rhadd_s32, gen_helper_neon_rhadd_u32 },

                };

                genfn = fns[size][u];

                break;

            }

            case 0x4: /* SHSUB, UHSUB */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_hsub_s8, gen_helper_neon_hsub_u8 },

                    { gen_helper_neon_hsub_s16, gen_helper_neon_hsub_u16 },

                    { gen_helper_neon_hsub_s32, gen_helper_neon_hsub_u32 },

                };

                genfn = fns[size][u];

                break;

            }

            case 0x5: /* SQSUB, UQSUB */

            {

                static NeonGenTwoOpEnvFn * const fns[3][2] = {

                    { gen_helper_neon_qsub_s8, gen_helper_neon_qsub_u8 },

                    { gen_helper_neon_qsub_s16, gen_helper_neon_qsub_u16 },

                    { gen_helper_neon_qsub_s32, gen_helper_neon_qsub_u32 },

                };

                genenvfn = fns[size][u];

                break;

            }

            case 0x6: /* CMGT, CMHI */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_cgt_s8, gen_helper_neon_cgt_u8 },

                    { gen_helper_neon_cgt_s16, gen_helper_neon_cgt_u16 },

                    { gen_helper_neon_cgt_s32, gen_helper_neon_cgt_u32 },

                };

                genfn = fns[size][u];

                break;

            }

            case 0x7: /* CMGE, CMHS */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_cge_s8, gen_helper_neon_cge_u8 },

                    { gen_helper_neon_cge_s16, gen_helper_neon_cge_u16 },

                    { gen_helper_neon_cge_s32, gen_helper_neon_cge_u32 },

                };

                genfn = fns[size][u];

                break;

            }

            case 0x8: /* SSHL, USHL */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_shl_s8, gen_helper_neon_shl_u8 },

                    { gen_helper_neon_shl_s16, gen_helper_neon_shl_u16 },

                    { gen_helper_neon_shl_s32, gen_helper_neon_shl_u32 },

                };

                genfn = fns[size][u];

                break;

            }

            case 0x9: /* SQSHL, UQSHL */

            {

                static NeonGenTwoOpEnvFn * const fns[3][2] = {

                    { gen_helper_neon_qshl_s8, gen_helper_neon_qshl_u8 },

                    { gen_helper_neon_qshl_s16, gen_helper_neon_qshl_u16 },

                    { gen_helper_neon_qshl_s32, gen_helper_neon_qshl_u32 },

                };

                genenvfn = fns[size][u];

                break;

            }

            case 0xa: /* SRSHL, URSHL */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_rshl_s8, gen_helper_neon_rshl_u8 },

                    { gen_helper_neon_rshl_s16, gen_helper_neon_rshl_u16 },

                    { gen_helper_neon_rshl_s32, gen_helper_neon_rshl_u32 },

                };

                genfn = fns[size][u];

                break;

            }

            case 0xb: /* SQRSHL, UQRSHL */

            {

                static NeonGenTwoOpEnvFn * const fns[3][2] = {

                    { gen_helper_neon_qrshl_s8, gen_helper_neon_qrshl_u8 },

                    { gen_helper_neon_qrshl_s16, gen_helper_neon_qrshl_u16 },

                    { gen_helper_neon_qrshl_s32, gen_helper_neon_qrshl_u32 },

                };

                genenvfn = fns[size][u];

                break;

            }

            case 0xc: /* SMAX, UMAX */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_max_s8, gen_helper_neon_max_u8 },

                    { gen_helper_neon_max_s16, gen_helper_neon_max_u16 },

                    { gen_max_s32, gen_max_u32 },

                };

                genfn = fns[size][u];

                break;

            }



            case 0xd: /* SMIN, UMIN */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_min_s8, gen_helper_neon_min_u8 },

                    { gen_helper_neon_min_s16, gen_helper_neon_min_u16 },

                    { gen_min_s32, gen_min_u32 },

                };

                genfn = fns[size][u];

                break;

            }

            case 0xe: /* SABD, UABD */

            case 0xf: /* SABA, UABA */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_abd_s8, gen_helper_neon_abd_u8 },

                    { gen_helper_neon_abd_s16, gen_helper_neon_abd_u16 },

                    { gen_helper_neon_abd_s32, gen_helper_neon_abd_u32 },

                };

                genfn = fns[size][u];

                break;

            }

            case 0x10: /* ADD, SUB */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_add_u8, gen_helper_neon_sub_u8 },

                    { gen_helper_neon_add_u16, gen_helper_neon_sub_u16 },

                    { tcg_gen_add_i32, tcg_gen_sub_i32 },

                };

                genfn = fns[size][u];

                break;

            }

            case 0x11: /* CMTST, CMEQ */

            {

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_tst_u8, gen_helper_neon_ceq_u8 },

                    { gen_helper_neon_tst_u16, gen_helper_neon_ceq_u16 },

                    { gen_helper_neon_tst_u32, gen_helper_neon_ceq_u32 },

                };

                genfn = fns[size][u];

                break;

            }

            case 0x13: /* MUL, PMUL */

                if (u) {

                    /* PMUL */

                    assert(size == 0);

                    genfn = gen_helper_neon_mul_p8;

                    break;

                }

                /* fall through : MUL */

            case 0x12: /* MLA, MLS */

            {

                static NeonGenTwoOpFn * const fns[3] = {

                    gen_helper_neon_mul_u8,

                    gen_helper_neon_mul_u16,

                    tcg_gen_mul_i32,

                };

                genfn = fns[size];

                break;

            }

            case 0x16: /* SQDMULH, SQRDMULH */

            {

                static NeonGenTwoOpEnvFn * const fns[2][2] = {

                    { gen_helper_neon_qdmulh_s16, gen_helper_neon_qrdmulh_s16 },

                    { gen_helper_neon_qdmulh_s32, gen_helper_neon_qrdmulh_s32 },

                };

                assert(size == 1 || size == 2);

                genenvfn = fns[size - 1][u];

                break;

            }

            default:

                g_assert_not_reached();

            }



            if (genenvfn) {

                genenvfn(tcg_res, cpu_env, tcg_op1, tcg_op2);

            } else {

                genfn(tcg_res, tcg_op1, tcg_op2);

            }



            if (opcode == 0xf || opcode == 0x12) {

                /* SABA, UABA, MLA, MLS: accumulating ops */

                static NeonGenTwoOpFn * const fns[3][2] = {

                    { gen_helper_neon_add_u8, gen_helper_neon_sub_u8 },

                    { gen_helper_neon_add_u16, gen_helper_neon_sub_u16 },

                    { tcg_gen_add_i32, tcg_gen_sub_i32 },

                };

                bool is_sub = (opcode == 0x12 && u); /* MLS */



                genfn = fns[size][is_sub];

                read_vec_element_i32(s, tcg_op1, rd, pass, MO_32);

                genfn(tcg_res, tcg_op1, tcg_res);

            }



            write_vec_element_i32(s, tcg_res, rd, pass, MO_32);



            tcg_temp_free_i32(tcg_res);

            tcg_temp_free_i32(tcg_op1);

            tcg_temp_free_i32(tcg_op2);

        }

    }



    if (!is_q) {

        clear_vec_high(s, rd);

    }

}

static ssize_t proxy_preadv(FsContext *ctx, V9fsFidOpenState *fs,

                            const struct iovec *iov,

                            int iovcnt, off_t offset)

{

    ssize_t ret;

#ifdef CONFIG_PREADV

    ret = preadv(fs->fd, iov, iovcnt, offset);

#else

    ret = lseek(fs->fd, offset, SEEK_SET);

    if (ret >= 0) {

        ret = readv(fs->fd, iov, iovcnt);

    }

#endif

    return ret;

}

MemoryRegion *address_space_translate(AddressSpace *as, hwaddr addr,

                                      hwaddr *xlat, hwaddr *plen,

                                      bool is_write)

{

    IOMMUTLBEntry iotlb;

    MemoryRegionSection *section;

    MemoryRegion *mr;

    hwaddr len = *plen;



    for (;;) {

        section = address_space_translate_internal(as->dispatch, addr, &addr, &len, true);

        mr = section->mr;



        if (!mr->iommu_ops) {

            break;

        }



        iotlb = mr->iommu_ops->translate(mr, addr);

        addr = ((iotlb.translated_addr & ~iotlb.addr_mask)

                | (addr & iotlb.addr_mask));

        len = MIN(len, (addr | iotlb.addr_mask) - addr + 1);

        if (!(iotlb.perm & (1 << is_write))) {

            mr = &io_mem_unassigned;

            break;

        }



        as = iotlb.target_as;

    }



    *plen = len;

    *xlat = addr;

    return mr;

}

static void shpc_set_status(SHPCDevice *shpc,

                            int slot, uint8_t value, uint16_t msk)

{

    uint8_t *status = shpc->config + SHPC_SLOT_STATUS(slot);

    pci_word_test_and_clear_mask(status, msk);

    pci_word_test_and_set_mask(status, value << (ffs(msk) - 1));

}

static void prom_set(uint32_t* prom_buf, int index, const char *string, ...)

{

    va_list ap;

    int32_t table_addr;



    if (index >= ENVP_NB_ENTRIES)

        return;



    if (string == NULL) {

        prom_buf[index] = 0;

        return;

    }



    table_addr = sizeof(int32_t) * ENVP_NB_ENTRIES + index * ENVP_ENTRY_SIZE;

    prom_buf[index] = tswap32(ENVP_ADDR + table_addr);



    va_start(ap, string);

    vsnprintf((char *)prom_buf + table_addr, ENVP_ENTRY_SIZE, string, ap);

    va_end(ap);

}

DriveInfo *drive_get(BlockInterfaceType type, int bus, int unit)

{

    DriveInfo *dinfo;



    /* seek interface, bus and unit */



    TAILQ_FOREACH(dinfo, &drives, next) {

        if (dinfo->type == type &&

	    dinfo->bus == bus &&

	    dinfo->unit == unit)

            return dinfo;

    }



    return NULL;

}

static void acpi_table_install(const char unsigned *blob, size_t bloblen,

                               bool has_header,

                               const struct AcpiTableOptions *hdrs,

                               Error **errp)

{

    size_t body_start;

    const char unsigned *hdr_src;

    size_t body_size, acpi_payload_size;

    struct acpi_table_header *ext_hdr;

    unsigned changed_fields;



    /* Calculate where the ACPI table body starts within the blob, plus where

     * to copy the ACPI table header from.

     */

    if (has_header) {

        /*   _length             | ACPI header in blob | blob body

         *   ^^^^^^^^^^^^^^^^^^^   ^^^^^^^^^^^^^^^^^^^   ^^^^^^^^^

         *   ACPI_TABLE_PFX_SIZE     sizeof dfl_hdr      body_size

         *                           == body_start

         *

         *                         ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^

         *                           acpi_payload_size == bloblen

         */

        body_start = sizeof dfl_hdr;



        if (bloblen < body_start) {

            error_setg(errp, "ACPI table claiming to have header is too "

                       "short, available: %zu, expected: %zu", bloblen,

                       body_start);

            return;

        }

        hdr_src = blob;

    } else {

        /*   _length             | ACPI header in template | blob body

         *   ^^^^^^^^^^^^^^^^^^^   ^^^^^^^^^^^^^^^^^^^^^^^   ^^^^^^^^^^

         *   ACPI_TABLE_PFX_SIZE       sizeof dfl_hdr        body_size

         *                                                   == bloblen

         *

         *                         ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^

         *                                  acpi_payload_size

         */

        body_start = 0;

        hdr_src = dfl_hdr;

    }

    body_size = bloblen - body_start;

    acpi_payload_size = sizeof dfl_hdr + body_size;



    if (acpi_payload_size > UINT16_MAX) {

        error_setg(errp, "ACPI table too big, requested: %zu, max: %u",

                   acpi_payload_size, (unsigned)UINT16_MAX);

        return;

    }



    /* We won't fail from here on. Initialize / extend the globals. */

    if (acpi_tables == NULL) {

        acpi_tables_len = sizeof(uint16_t);

        acpi_tables = g_malloc0(acpi_tables_len);

    }



    acpi_tables = g_realloc(acpi_tables, acpi_tables_len +

                                         ACPI_TABLE_PFX_SIZE +

                                         sizeof dfl_hdr + body_size);



    ext_hdr = (struct acpi_table_header *)(acpi_tables + acpi_tables_len);

    acpi_tables_len += ACPI_TABLE_PFX_SIZE;



    memcpy(acpi_tables + acpi_tables_len, hdr_src, sizeof dfl_hdr);

    acpi_tables_len += sizeof dfl_hdr;



    if (blob != NULL) {

        memcpy(acpi_tables + acpi_tables_len, blob + body_start, body_size);

        acpi_tables_len += body_size;

    }



    /* increase number of tables */

    stw_le_p(acpi_tables, lduw_le_p(acpi_tables) + 1u);



    /* Update the header fields. The strings need not be NUL-terminated. */

    changed_fields = 0;

    ext_hdr->_length = cpu_to_le16(acpi_payload_size);



    if (hdrs->has_sig) {

        strncpy(ext_hdr->sig, hdrs->sig, sizeof ext_hdr->sig);

        ++changed_fields;

    }



    if (has_header && le32_to_cpu(ext_hdr->length) != acpi_payload_size) {

        fprintf(stderr,

                "warning: ACPI table has wrong length, header says "

                "%" PRIu32 ", actual size %zu bytes\n",

                le32_to_cpu(ext_hdr->length), acpi_payload_size);

    }

    ext_hdr->length = cpu_to_le32(acpi_payload_size);



    if (hdrs->has_rev) {

        ext_hdr->revision = hdrs->rev;

        ++changed_fields;

    }



    ext_hdr->checksum = 0;



    if (hdrs->has_oem_id) {

        strncpy(ext_hdr->oem_id, hdrs->oem_id, sizeof ext_hdr->oem_id);

        ++changed_fields;

    }

    if (hdrs->has_oem_table_id) {

        strncpy(ext_hdr->oem_table_id, hdrs->oem_table_id,

                sizeof ext_hdr->oem_table_id);

        ++changed_fields;

    }

    if (hdrs->has_oem_rev) {

        ext_hdr->oem_revision = cpu_to_le32(hdrs->oem_rev);

        ++changed_fields;

    }

    if (hdrs->has_asl_compiler_id) {

        strncpy(ext_hdr->asl_compiler_id, hdrs->asl_compiler_id,

                sizeof ext_hdr->asl_compiler_id);

        ++changed_fields;

    }

    if (hdrs->has_asl_compiler_rev) {

        ext_hdr->asl_compiler_revision = cpu_to_le32(hdrs->asl_compiler_rev);

        ++changed_fields;

    }



    if (!has_header && changed_fields == 0) {

        warn_report("ACPI table: no headers are specified");

    }



    /* recalculate checksum */

    ext_hdr->checksum = acpi_checksum((const char unsigned *)ext_hdr +

                                      ACPI_TABLE_PFX_SIZE, acpi_payload_size);

}

static void spapr_hotplug_req_event(uint8_t hp_id, uint8_t hp_action,

                                    sPAPRDRConnectorType drc_type,

                                    union drc_identifier *drc_id)

{

    sPAPRMachineState *spapr = SPAPR_MACHINE(qdev_get_machine());

    struct hp_log_full *new_hp;

    struct rtas_error_log *hdr;

    struct rtas_event_log_v6 *v6hdr;

    struct rtas_event_log_v6_maina *maina;

    struct rtas_event_log_v6_mainb *mainb;

    struct rtas_event_log_v6_hp *hp;



    new_hp = g_malloc0(sizeof(struct hp_log_full));

    hdr = &new_hp->hdr;

    v6hdr = &new_hp->v6hdr;

    maina = &new_hp->maina;

    mainb = &new_hp->mainb;

    hp = &new_hp->hp;



    hdr->summary = cpu_to_be32(RTAS_LOG_VERSION_6

                               | RTAS_LOG_SEVERITY_EVENT

                               | RTAS_LOG_DISPOSITION_NOT_RECOVERED

                               | RTAS_LOG_OPTIONAL_PART_PRESENT

                               | RTAS_LOG_INITIATOR_HOTPLUG

                               | RTAS_LOG_TYPE_HOTPLUG);

    hdr->extended_length = cpu_to_be32(sizeof(*new_hp)

                                       - sizeof(new_hp->hdr));



    spapr_init_v6hdr(v6hdr);

    spapr_init_maina(maina, 3 /* Main-A, Main-B, HP */);



    mainb->hdr.section_id = cpu_to_be16(RTAS_LOG_V6_SECTION_ID_MAINB);

    mainb->hdr.section_length = cpu_to_be16(sizeof(*mainb));

    mainb->subsystem_id = 0x80; /* External environment */

    mainb->event_severity = 0x00; /* Informational / non-error */

    mainb->event_subtype = 0x00; /* Normal shutdown */



    hp->hdr.section_id = cpu_to_be16(RTAS_LOG_V6_SECTION_ID_HOTPLUG);

    hp->hdr.section_length = cpu_to_be16(sizeof(*hp));

    hp->hdr.section_version = 1; /* includes extended modifier */

    hp->hotplug_action = hp_action;

    hp->hotplug_identifier = hp_id;



    switch (drc_type) {

    case SPAPR_DR_CONNECTOR_TYPE_PCI:

        hp->hotplug_type = RTAS_LOG_V6_HP_TYPE_PCI;

        if (hp->hotplug_action == RTAS_LOG_V6_HP_ACTION_ADD) {

            spapr_hotplug_set_signalled(drc_id->index);

        }

        break;

    case SPAPR_DR_CONNECTOR_TYPE_LMB:

        hp->hotplug_type = RTAS_LOG_V6_HP_TYPE_MEMORY;

        break;

    case SPAPR_DR_CONNECTOR_TYPE_CPU:

        hp->hotplug_type = RTAS_LOG_V6_HP_TYPE_CPU;

        break;

    default:

        /* we shouldn't be signaling hotplug events for resources

         * that don't support them

         */

        g_assert(false);

        return;

    }



    if (hp_id == RTAS_LOG_V6_HP_ID_DRC_COUNT) {

        hp->drc_id.count = cpu_to_be32(drc_id->count);

    } else if (hp_id == RTAS_LOG_V6_HP_ID_DRC_INDEX) {

        hp->drc_id.index = cpu_to_be32(drc_id->index);

    } else if (hp_id == RTAS_LOG_V6_HP_ID_DRC_COUNT_INDEXED) {

        /* we should not be using count_indexed value unless the guest

         * supports dedicated hotplug event source

         */

        g_assert(spapr_ovec_test(spapr->ov5_cas, OV5_HP_EVT));

        hp->drc_id.count_indexed.count =

            cpu_to_be32(drc_id->count_indexed.count);

        hp->drc_id.count_indexed.index =

            cpu_to_be32(drc_id->count_indexed.index);

    }



    rtas_event_log_queue(RTAS_LOG_TYPE_HOTPLUG, new_hp, true);



    qemu_irq_pulse(xics_get_qirq(XICS_FABRIC(spapr),

                                 rtas_event_log_to_irq(spapr,

                                                       RTAS_LOG_TYPE_HOTPLUG)));

}

void qemu_aio_flush(void)

{

    AioHandler *node;

    int ret;



    do {

        ret = 0;



	/*

	 * If there are pending emulated aio start them now so flush

	 * will be able to return 1.

	 */

        qemu_aio_wait();



        QLIST_FOREACH(node, &aio_handlers, node) {

            if (node->io_flush) {

                ret |= node->io_flush(node->opaque);

            }

        }

    } while (qemu_bh_poll() || ret > 0);

}

static void gen_srs(DisasContext *s,

                    uint32_t mode, uint32_t amode, bool writeback)

{

    int32_t offset;

    TCGv_i32 addr = tcg_temp_new_i32();

    TCGv_i32 tmp = tcg_const_i32(mode);

    gen_helper_get_r13_banked(addr, cpu_env, tmp);

    tcg_temp_free_i32(tmp);

    switch (amode) {

    case 0: /* DA */

        offset = -4;

        break;

    case 1: /* IA */

        offset = 0;

        break;

    case 2: /* DB */

        offset = -8;

        break;

    case 3: /* IB */

        offset = 4;

        break;

    default:

        abort();

    }

    tcg_gen_addi_i32(addr, addr, offset);

    tmp = load_reg(s, 14);

    gen_aa32_st32(tmp, addr, get_mem_index(s));

    tcg_temp_free_i32(tmp);

    tmp = load_cpu_field(spsr);

    tcg_gen_addi_i32(addr, addr, 4);

    gen_aa32_st32(tmp, addr, get_mem_index(s));

    tcg_temp_free_i32(tmp);

    if (writeback) {

        switch (amode) {

        case 0:

            offset = -8;

            break;

        case 1:

            offset = 4;

            break;

        case 2:

            offset = -4;

            break;

        case 3:

            offset = 0;

            break;

        default:

            abort();

        }

        tcg_gen_addi_i32(addr, addr, offset);

        tmp = tcg_const_i32(mode);

        gen_helper_set_r13_banked(cpu_env, tmp, addr);

        tcg_temp_free_i32(tmp);

    }

    tcg_temp_free_i32(addr);

}

