    /* 3.2.25 */

    g_assert_cmpint(qpci_config_readb(dev, 0x91), ==, 0x00); /* ERRSTS */

    /* 3.2.26 */

    g_assert_cmpint(qpci_config_readb(dev, 0x93), ==, 0x00); /* TRC */





    qtest_end();

