static void nvdimm_realize(PCDIMMDevice *dimm, Error **errp)

{

    MemoryRegion *mr = host_memory_backend_get_memory(dimm->hostmem, errp);

    NVDIMMDevice *nvdimm = NVDIMM(dimm);

    uint64_t align, pmem_size, size = memory_region_size(mr);



    align = memory_region_get_alignment(mr);



    pmem_size = size - nvdimm->label_size;

    nvdimm->label_data = memory_region_get_ram_ptr(mr) + pmem_size;

    pmem_size = QEMU_ALIGN_DOWN(pmem_size, align);



    if (size <= nvdimm->label_size || !pmem_size) {

        HostMemoryBackend *hostmem = dimm->hostmem;

        char *path = object_get_canonical_path_component(OBJECT(hostmem));



        error_setg(errp, "the size of memdev %s (0x%" PRIx64 ") is too "

                   "small to contain nvdimm label (0x%" PRIx64 ") and "

                   "aligned PMEM (0x%" PRIx64 ")",

                   path, memory_region_size(mr), nvdimm->label_size, align);


        return;

    }



    memory_region_init_alias(&nvdimm->nvdimm_mr, OBJECT(dimm),

                             "nvdimm-memory", mr, 0, pmem_size);

    nvdimm->nvdimm_mr.align = align;

}

static void gen_sync(DisasContext *ctx)

{

    uint32_t l = (ctx->opcode >> 21) & 3;



    /*

     * We may need to check for a pending TLB flush.

     *

     * We do this on ptesync (l == 2) on ppc64 and any sync pn ppc32.

     *

     * Additionally, this can only happen in kernel mode however so

     * check MSR_PR as well.

     */

    if (((l == 2) || !(ctx->insns_flags & PPC_64B)) && !ctx->pr) {

        gen_check_tlb_flush(ctx);

    }

}

static int qcrypto_ivgen_essiv_calculate(QCryptoIVGen *ivgen,

                                         uint64_t sector,

                                         uint8_t *iv, size_t niv,

                                         Error **errp)

{

    QCryptoIVGenESSIV *essiv = ivgen->private;

    size_t ndata = qcrypto_cipher_get_block_len(ivgen->cipher);

    uint8_t *data = g_new(uint8_t, ndata);



    sector = cpu_to_le64(sector);

    memcpy(data, (uint8_t *)&sector, ndata);

    if (sizeof(sector) < ndata) {

        memset(data + sizeof(sector), 0, ndata - sizeof(sector));

    }



    if (qcrypto_cipher_encrypt(essiv->cipher,

                               data,

                               data,

                               ndata,

                               errp) < 0) {

        g_free(data);

        return -1;

    }



    if (ndata > niv) {

        ndata = niv;

    }

    memcpy(iv, data, ndata);

    if (ndata < niv) {

        memset(iv + ndata, 0, niv - ndata);

    }

    g_free(data);

    return 0;

}

