static UHCIQueue *uhci_queue_get(UHCIState *s, UHCI_TD *td, USBEndpoint *ep)

{

    uint32_t token = uhci_queue_token(td);

    UHCIQueue *queue;



    QTAILQ_FOREACH(queue, &s->queues, next) {

