static CharDriverState *qemu_chr_open_tcp(const char *host_str,

                                          int is_telnet,

					  int is_unix)

{

    CharDriverState *chr = NULL;

    TCPCharDriver *s = NULL;

    int fd = -1, ret, err, val;

    int is_listen = 0;

    int is_waitconnect = 1;

    int do_nodelay = 0;

    const char *ptr;

    struct sockaddr_in saddr;

#ifndef _WIN32

    struct sockaddr_un uaddr;

#endif

    struct sockaddr *addr;

    socklen_t addrlen;



#ifndef _WIN32

    if (is_unix) {

	addr = (struct sockaddr *)&uaddr;

	addrlen = sizeof(uaddr);

	if (parse_unix_path(&uaddr, host_str) < 0)

	    goto fail;

    } else

#endif

    {

	addr = (struct sockaddr *)&saddr;

	addrlen = sizeof(saddr);

	if (parse_host_port(&saddr, host_str) < 0)

	    goto fail;

    }



    ptr = host_str;

    while((ptr = strchr(ptr,','))) {

        ptr++;

        if (!strncmp(ptr,"server",6)) {

            is_listen = 1;

        } else if (!strncmp(ptr,"nowait",6)) {

            is_waitconnect = 0;

        } else if (!strncmp(ptr,"nodelay",6)) {

            do_nodelay = 1;

        } else {

            printf("Unknown option: %s\n", ptr);

            goto fail;

        }

    }

    if (!is_listen)

        is_waitconnect = 0;



    chr = qemu_mallocz(sizeof(CharDriverState));

    if (!chr)

        goto fail;

    s = qemu_mallocz(sizeof(TCPCharDriver));

    if (!s)

        goto fail;



#ifndef _WIN32

    if (is_unix)

	fd = socket(PF_UNIX, SOCK_STREAM, 0);

    else

#endif

	fd = socket(PF_INET, SOCK_STREAM, 0);



    if (fd < 0)

        goto fail;



    if (!is_waitconnect)

        socket_set_nonblock(fd);



    s->connected = 0;

    s->fd = -1;

    s->listen_fd = -1;

    s->is_unix = is_unix;

    s->do_nodelay = do_nodelay && !is_unix;



    chr->opaque = s;

    chr->chr_write = tcp_chr_write;

    chr->chr_close = tcp_chr_close;



    if (is_listen) {

        /* allow fast reuse */

#ifndef _WIN32

	if (is_unix) {

	    char path[109];

	    pstrcpy(path, sizeof(path), uaddr.sun_path);

	    unlink(path);

	} else

#endif

	{

	    val = 1;

	    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, (const char *)&val, sizeof(val));

	}



        ret = bind(fd, addr, addrlen);

        if (ret < 0)

            goto fail;



        ret = listen(fd, 0);

        if (ret < 0)

            goto fail;



        s->listen_fd = fd;

        qemu_set_fd_handler(s->listen_fd, tcp_chr_accept, NULL, chr);

        if (is_telnet)

            s->do_telnetopt = 1;

    } else {

        for(;;) {

            ret = connect(fd, addr, addrlen);

            if (ret < 0) {

                err = socket_error();

                if (err == EINTR || err == EWOULDBLOCK) {

                } else if (err == EINPROGRESS) {

                    break;

#ifdef _WIN32

                } else if (err == WSAEALREADY) {

                    break;

#endif

                } else {

                    goto fail;

                }

            } else {

                s->connected = 1;

                break;

            }

        }

        s->fd = fd;

        socket_set_nodelay(fd);

        if (s->connected)

            tcp_chr_connect(chr);

        else

            qemu_set_fd_handler(s->fd, NULL, tcp_chr_connect, chr);

    }



    if (is_listen && is_waitconnect) {

        printf("QEMU waiting for connection on: %s\n", host_str);

        tcp_chr_accept(chr);

        socket_set_nonblock(s->listen_fd);

    }



    return chr;

 fail:

    if (fd >= 0)

        closesocket(fd);

    qemu_free(s);

    qemu_free(chr);

    return NULL;

}

void define_one_arm_cp_reg_with_opaque(ARMCPU *cpu,

                                       const ARMCPRegInfo *r, void *opaque)

{

    /* Define implementations of coprocessor registers.

     * We store these in a hashtable because typically

     * there are less than 150 registers in a space which

     * is 16*16*16*8*8 = 262144 in size.

     * Wildcarding is supported for the crm, opc1 and opc2 fields.

     * If a register is defined twice then the second definition is

     * used, so this can be used to define some generic registers and

     * then override them with implementation specific variations.

     * At least one of the original and the second definition should

     * include ARM_CP_OVERRIDE in its type bits -- this is just a guard

     * against accidental use.

     */

    int crm, opc1, opc2;

    int crmmin = (r->crm == CP_ANY) ? 0 : r->crm;

    int crmmax = (r->crm == CP_ANY) ? 15 : r->crm;

    int opc1min = (r->opc1 == CP_ANY) ? 0 : r->opc1;

    int opc1max = (r->opc1 == CP_ANY) ? 7 : r->opc1;

    int opc2min = (r->opc2 == CP_ANY) ? 0 : r->opc2;

    int opc2max = (r->opc2 == CP_ANY) ? 7 : r->opc2;

    /* 64 bit registers have only CRm and Opc1 fields */

    assert(!((r->type & ARM_CP_64BIT) && (r->opc2 || r->crn)));

    /* Check that the register definition has enough info to handle

     * reads and writes if they are permitted.

     */

    if (!(r->type & (ARM_CP_SPECIAL|ARM_CP_CONST))) {

        if (r->access & PL3_R) {

            assert(r->fieldoffset || r->readfn);

        }

        if (r->access & PL3_W) {

            assert(r->fieldoffset || r->writefn);

        }

    }

    /* Bad type field probably means missing sentinel at end of reg list */

    assert(cptype_valid(r->type));

    for (crm = crmmin; crm <= crmmax; crm++) {

        for (opc1 = opc1min; opc1 <= opc1max; opc1++) {

            for (opc2 = opc2min; opc2 <= opc2max; opc2++) {

                uint32_t *key = g_new(uint32_t, 1);

                ARMCPRegInfo *r2 = g_memdup(r, sizeof(ARMCPRegInfo));

                int is64 = (r->type & ARM_CP_64BIT) ? 1 : 0;

                *key = ENCODE_CP_REG(r->cp, is64, r->crn, crm, opc1, opc2);

                if (opaque) {

                    r2->opaque = opaque;

                }

                /* Make sure reginfo passed to helpers for wildcarded regs

                 * has the correct crm/opc1/opc2 for this reg, not CP_ANY:

                 */

                r2->crm = crm;

                r2->opc1 = opc1;

                r2->opc2 = opc2;

                /* By convention, for wildcarded registers only the first

                 * entry is used for migration; the others are marked as

                 * NO_MIGRATE so we don't try to transfer the register

                 * multiple times. Special registers (ie NOP/WFI) are

                 * never migratable.

                 */

                if ((r->type & ARM_CP_SPECIAL) ||

                    ((r->crm == CP_ANY) && crm != 0) ||

                    ((r->opc1 == CP_ANY) && opc1 != 0) ||

                    ((r->opc2 == CP_ANY) && opc2 != 0)) {

                    r2->type |= ARM_CP_NO_MIGRATE;

                }



                /* Overriding of an existing definition must be explicitly

                 * requested.

                 */

                if (!(r->type & ARM_CP_OVERRIDE)) {

                    ARMCPRegInfo *oldreg;

                    oldreg = g_hash_table_lookup(cpu->cp_regs, key);

                    if (oldreg && !(oldreg->type & ARM_CP_OVERRIDE)) {

                        fprintf(stderr, "Register redefined: cp=%d %d bit "

                                "crn=%d crm=%d opc1=%d opc2=%d, "

                                "was %s, now %s\n", r2->cp, 32 + 32 * is64,

                                r2->crn, r2->crm, r2->opc1, r2->opc2,

                                oldreg->name, r2->name);

                        g_assert_not_reached();

                    }

                }

                g_hash_table_insert(cpu->cp_regs, key, r2);

            }

        }

    }

}

static void sdhci_sdma_transfer_single_block(SDHCIState *s)

{

    int n;

    uint32_t datacnt = s->blksize & 0x0fff;



    if (s->trnmod & SDHC_TRNS_READ) {

        for (n = 0; n < datacnt; n++) {

            s->fifo_buffer[n] = sdbus_read_data(&s->sdbus);

        }

        dma_memory_write(&address_space_memory, s->sdmasysad, s->fifo_buffer,

                         datacnt);

    } else {

        dma_memory_read(&address_space_memory, s->sdmasysad, s->fifo_buffer,

                        datacnt);

        for (n = 0; n < datacnt; n++) {

            sdbus_write_data(&s->sdbus, s->fifo_buffer[n]);

        }

    }



    if (s->trnmod & SDHC_TRNS_BLK_CNT_EN) {

        s->blkcnt--;

    }



    sdhci_end_transfer(s);

}

static int tight_compress_data(VncState *vs, int stream_id, size_t bytes,

                               int level, int strategy)

{

    z_streamp zstream = &vs->tight_stream[stream_id];

    int previous_out;



    if (bytes < VNC_TIGHT_MIN_TO_COMPRESS) {

        vnc_write(vs, vs->tight.buffer, vs->tight.offset);

        return bytes;

    }



    if (tight_init_stream(vs, stream_id, level, strategy)) {

        return -1;

    }



    /* reserve memory in output buffer */

    buffer_reserve(&vs->tight_zlib, bytes + 64);



    /* set pointers */

    zstream->next_in = vs->tight.buffer;

    zstream->avail_in = vs->tight.offset;

    zstream->next_out = vs->tight_zlib.buffer + vs->tight_zlib.offset;

    zstream->avail_out = vs->tight_zlib.capacity - vs->tight_zlib.offset;

    zstream->data_type = Z_BINARY;

    previous_out = zstream->total_out;



    /* start encoding */

    if (deflate(zstream, Z_SYNC_FLUSH) != Z_OK) {

        fprintf(stderr, "VNC: error during tight compression\n");

        return -1;

    }



    vs->tight_zlib.offset = vs->tight_zlib.capacity - zstream->avail_out;

    bytes = zstream->total_out - previous_out;



    tight_send_compact_size(vs, bytes);

    vnc_write(vs, vs->tight_zlib.buffer, bytes);



    buffer_reset(&vs->tight_zlib);



    return bytes;

}

