static int restore_user_regs(CPUPPCState *env,

                             struct target_mcontext *frame, int sig)

{

    target_ulong save_r2 = 0;

    target_ulong msr;

    target_ulong ccr;



    int i;



    if (!sig) {

        save_r2 = env->gpr[2];

    }



    /* Restore general registers.  */

    for (i = 0; i < ARRAY_SIZE(env->gpr); i++) {

        if (__get_user(env->gpr[i], &frame->mc_gregs[i])) {

            return 1;

        }

    }

    if (__get_user(env->nip, &frame->mc_gregs[TARGET_PT_NIP])

        || __get_user(env->ctr, &frame->mc_gregs[TARGET_PT_CTR])

        || __get_user(env->lr, &frame->mc_gregs[TARGET_PT_LNK])

        || __get_user(env->xer, &frame->mc_gregs[TARGET_PT_XER]))

        return 1;

    if (__get_user(ccr, &frame->mc_gregs[TARGET_PT_CCR]))

        return 1;



    for (i = 0; i < ARRAY_SIZE(env->crf); i++) {

        env->crf[i] = (ccr >> (32 - ((i + 1) * 4))) & 0xf;

    }



    if (!sig) {

        env->gpr[2] = save_r2;

    }

    /* Restore MSR.  */

    if (__get_user(msr, &frame->mc_gregs[TARGET_PT_MSR]))

        return 1;



    /* If doing signal return, restore the previous little-endian mode.  */

    if (sig)

        env->msr = (env->msr & ~MSR_LE) | (msr & MSR_LE);



    /* Restore Altivec registers if necessary.  */

    if (env->insns_flags & PPC_ALTIVEC) {

        for (i = 0; i < ARRAY_SIZE(env->avr); i++) {

            ppc_avr_t *avr = &env->avr[i];

            ppc_avr_t *vreg = &frame->mc_vregs.altivec[i];



            if (__get_user(avr->u64[0], &vreg->u64[0]) ||

                __get_user(avr->u64[1], &vreg->u64[1])) {

                return 1;

            }

        }

        /* Set MSR_VEC in the saved MSR value to indicate that

           frame->mc_vregs contains valid data.  */

        if (__get_user(env->spr[SPR_VRSAVE],

                       (target_ulong *)(&frame->mc_vregs.altivec[32].u32[3])))

            return 1;

    }



    /* Restore floating point registers.  */

    if (env->insns_flags & PPC_FLOAT) {

        uint64_t fpscr;

        for (i = 0; i < ARRAY_SIZE(env->fpr); i++) {

            if (__get_user(env->fpr[i], &frame->mc_fregs[i])) {

                return 1;

            }

        }

        if (__get_user(fpscr, &frame->mc_fregs[32]))

            return 1;

        env->fpscr = (uint32_t) fpscr;

    }



    /* Save SPE registers.  The kernel only saves the high half.  */

    if (env->insns_flags & PPC_SPE) {

#if defined(TARGET_PPC64)

        for (i = 0; i < ARRAY_SIZE(env->gpr); i++) {

            uint32_t hi;



            if (__get_user(hi, &frame->mc_vregs.spe[i])) {

                return 1;

            }

            env->gpr[i] = ((uint64_t)hi << 32) | ((uint32_t) env->gpr[i]);

        }

#else

        for (i = 0; i < ARRAY_SIZE(env->gprh); i++) {

            if (__get_user(env->gprh[i], &frame->mc_vregs.spe[i])) {

                return 1;

            }

        }

#endif

        if (__get_user(env->spe_fscr, &frame->mc_vregs.spe[32]))

            return 1;

    }



    return 0;

}

static void virtio_pci_config_write(void *opaque, hwaddr addr,

                                    uint64_t val, unsigned size)

{

    VirtIOPCIProxy *proxy = opaque;

    uint32_t config = VIRTIO_PCI_CONFIG(&proxy->pci_dev);

    if (addr < config) {

        virtio_ioport_write(proxy, addr, val);

        return;

    }

    addr -= config;

    /*

     * Virtio-PCI is odd. Ioports are LE but config space is target native

     * endian.

     */

    switch (size) {

    case 1:

        virtio_config_writeb(proxy->vdev, addr, val);

        break;

    case 2:

        if (virtio_is_big_endian()) {

            val = bswap16(val);

        }

        virtio_config_writew(proxy->vdev, addr, val);

        break;

    case 4:

        if (virtio_is_big_endian()) {

            val = bswap32(val);

        }

        virtio_config_writel(proxy->vdev, addr, val);

        break;

    }

}

int qcow2_alloc_cluster_link_l2(BlockDriverState *bs, QCowL2Meta *m)

{

    BDRVQcowState *s = bs->opaque;

    int i, j = 0, l2_index, ret;

    uint64_t *old_cluster, start_sect, l2_offset, *l2_table;

    uint64_t cluster_offset = m->cluster_offset;

    bool cow = false;



    trace_qcow2_cluster_link_l2(qemu_coroutine_self(), m->nb_clusters);



    if (m->nb_clusters == 0)

        return 0;



    old_cluster = g_malloc(m->nb_clusters * sizeof(uint64_t));



    /* copy content of unmodified sectors */

    start_sect = (m->offset & ~(s->cluster_size - 1)) >> 9;

    if (m->n_start) {

        cow = true;

        qemu_co_mutex_unlock(&s->lock);

        ret = copy_sectors(bs, start_sect, cluster_offset, 0, m->n_start);

        qemu_co_mutex_lock(&s->lock);

        if (ret < 0)

            goto err;

    }



    if (m->nb_available & (s->cluster_sectors - 1)) {

        uint64_t end = m->nb_available & ~(uint64_t)(s->cluster_sectors - 1);

        cow = true;

        qemu_co_mutex_unlock(&s->lock);

        ret = copy_sectors(bs, start_sect + end, cluster_offset + (end << 9),

                m->nb_available - end, s->cluster_sectors);

        qemu_co_mutex_lock(&s->lock);

        if (ret < 0)

            goto err;

    }



    /*

     * Update L2 table.

     *

     * Before we update the L2 table to actually point to the new cluster, we

     * need to be sure that the refcounts have been increased and COW was

     * handled.

     */

    if (cow) {

        qcow2_cache_depends_on_flush(s->l2_table_cache);

    }



    qcow2_cache_set_dependency(bs, s->l2_table_cache, s->refcount_block_cache);

    ret = get_cluster_table(bs, m->offset, &l2_table, &l2_offset, &l2_index);

    if (ret < 0) {

        goto err;

    }

    qcow2_cache_entry_mark_dirty(s->l2_table_cache, l2_table);



    for (i = 0; i < m->nb_clusters; i++) {

        /* if two concurrent writes happen to the same unallocated cluster

	 * each write allocates separate cluster and writes data concurrently.

	 * The first one to complete updates l2 table with pointer to its

	 * cluster the second one has to do RMW (which is done above by

	 * copy_sectors()), update l2 table with its cluster pointer and free

	 * old cluster. This is what this loop does */

        if(l2_table[l2_index + i] != 0)

            old_cluster[j++] = l2_table[l2_index + i];



        l2_table[l2_index + i] = cpu_to_be64((cluster_offset +

                    (i << s->cluster_bits)) | QCOW_OFLAG_COPIED);

     }





    ret = qcow2_cache_put(bs, s->l2_table_cache, (void**) &l2_table);

    if (ret < 0) {

        goto err;

    }



    /*

     * If this was a COW, we need to decrease the refcount of the old cluster.

     * Also flush bs->file to get the right order for L2 and refcount update.

     */

    if (j != 0) {

        for (i = 0; i < j; i++) {

            qcow2_free_any_clusters(bs,

                be64_to_cpu(old_cluster[i]) & ~QCOW_OFLAG_COPIED, 1);

        }

    }



    ret = 0;

err:

    g_free(old_cluster);

    return ret;

 }

MemTxResult address_space_read_continue(AddressSpace *as, hwaddr addr,

                                        MemTxAttrs attrs, uint8_t *buf,

                                        int len, hwaddr addr1, hwaddr l,

                                        MemoryRegion *mr)

{

    uint8_t *ptr;

    uint64_t val;

    MemTxResult result = MEMTX_OK;

    bool release_lock = false;



    for (;;) {

        if (!memory_access_is_direct(mr, false)) {

            /* I/O case */

            release_lock |= prepare_mmio_access(mr);

            l = memory_access_size(mr, l, addr1);

            switch (l) {

            case 8:

                /* 64 bit read access */

                result |= memory_region_dispatch_read(mr, addr1, &val, 8,

                                                      attrs);

                stq_p(buf, val);

                break;

            case 4:

                /* 32 bit read access */

                result |= memory_region_dispatch_read(mr, addr1, &val, 4,

                                                      attrs);

                stl_p(buf, val);

                break;

            case 2:

                /* 16 bit read access */

                result |= memory_region_dispatch_read(mr, addr1, &val, 2,

                                                      attrs);

                stw_p(buf, val);

                break;

            case 1:

                /* 8 bit read access */

                result |= memory_region_dispatch_read(mr, addr1, &val, 1,

                                                      attrs);

                stb_p(buf, val);

                break;

            default:

                abort();

            }

        } else {

            /* RAM case */

            ptr = qemu_map_ram_ptr(mr->ram_block, addr1);

            memcpy(buf, ptr, l);

        }



        if (release_lock) {

            qemu_mutex_unlock_iothread();

            release_lock = false;

        }



        len -= l;

        buf += l;

        addr += l;



        if (!len) {

            break;

        }



        l = len;

        mr = address_space_translate(as, addr, &addr1, &l, false);

    }



    return result;

}

