static void colo_compare_complete(UserCreatable *uc, Error **errp)

{

    CompareState *s = COLO_COMPARE(uc);

    Chardev *chr;

    char thread_name[64];

    static int compare_id;



    if (!s->pri_indev || !s->sec_indev || !s->outdev) {

        error_setg(errp, "colo compare needs 'primary_in' ,"

                   "'secondary_in','outdev' property set");

        return;

    } else if (!strcmp(s->pri_indev, s->outdev) ||

               !strcmp(s->sec_indev, s->outdev) ||

               !strcmp(s->pri_indev, s->sec_indev)) {

        error_setg(errp, "'indev' and 'outdev' could not be same "

                   "for compare module");

        return;

    }



    if (find_and_check_chardev(&chr, s->pri_indev, errp) ||

        !qemu_chr_fe_init(&s->chr_pri_in, chr, errp)) {

        return;

    }



    if (find_and_check_chardev(&chr, s->sec_indev, errp) ||

        !qemu_chr_fe_init(&s->chr_sec_in, chr, errp)) {

        return;

    }



    if (find_and_check_chardev(&chr, s->outdev, errp) ||

        !qemu_chr_fe_init(&s->chr_out, chr, errp)) {

        return;

    }



    net_socket_rs_init(&s->pri_rs, compare_pri_rs_finalize, s->vnet_hdr);

    net_socket_rs_init(&s->sec_rs, compare_sec_rs_finalize, s->vnet_hdr);



    g_queue_init(&s->conn_list);



    s->connection_track_table = g_hash_table_new_full(connection_key_hash,

                                                      connection_key_equal,

                                                      g_free,

                                                      connection_destroy);



    sprintf(thread_name, "colo-compare %d", compare_id);

    qemu_thread_create(&s->thread, thread_name,

                       colo_compare_thread, s,

                       QEMU_THREAD_JOINABLE);

    compare_id++;



    return;

}

ram_addr_t qemu_ram_alloc_from_ptr(ram_addr_t size, void *host,

                                   MemoryRegion *mr)

{

    RAMBlock *new_block;



    size = TARGET_PAGE_ALIGN(size);

    new_block = g_malloc0(sizeof(*new_block));



    new_block->mr = mr;

    new_block->offset = find_ram_offset(size);

    if (host) {

        new_block->host = host;

        new_block->flags |= RAM_PREALLOC_MASK;

    } else {

        if (mem_path) {

#if defined (__linux__) && !defined(TARGET_S390X)

            new_block->host = file_ram_alloc(new_block, size, mem_path);

            if (!new_block->host) {

                new_block->host = qemu_vmalloc(size);

                qemu_madvise(new_block->host, size, QEMU_MADV_MERGEABLE);

            }

#else

            fprintf(stderr, "-mem-path option unsupported\n");

            exit(1);

#endif

        } else {

#if defined(TARGET_S390X) && defined(CONFIG_KVM)

            /* S390 KVM requires the topmost vma of the RAM to be smaller than

               an system defined value, which is at least 256GB. Larger systems

               have larger values. We put the guest between the end of data

               segment (system break) and this value. We use 32GB as a base to

               have enough room for the system break to grow. */

            new_block->host = mmap((void*)0x800000000, size,

                                   PROT_EXEC|PROT_READ|PROT_WRITE,

                                   MAP_SHARED | MAP_ANONYMOUS | MAP_FIXED, -1, 0);

            if (new_block->host == MAP_FAILED) {

                fprintf(stderr, "Allocating RAM failed\n");

                abort();

            }

#else

            if (xen_enabled()) {

                xen_ram_alloc(new_block->offset, size, mr);

            } else {

                new_block->host = qemu_vmalloc(size);

            }

#endif

            qemu_madvise(new_block->host, size, QEMU_MADV_MERGEABLE);

        }

    }

    new_block->length = size;



    QLIST_INSERT_HEAD(&ram_list.blocks, new_block, next);



    ram_list.phys_dirty = g_realloc(ram_list.phys_dirty,

                                       last_ram_offset() >> TARGET_PAGE_BITS);

    cpu_physical_memory_set_dirty_range(new_block->offset, size, 0xff);



    if (kvm_enabled())

        kvm_setup_guest_memory(new_block->host, size);



    return new_block->offset;

}

static void x86_iommu_realize(DeviceState *dev, Error **errp)

{

    X86IOMMUState *x86_iommu = X86_IOMMU_DEVICE(dev);

    X86IOMMUClass *x86_class = X86_IOMMU_GET_CLASS(dev);

    MachineState *ms = MACHINE(qdev_get_machine());

    MachineClass *mc = MACHINE_GET_CLASS(ms);

    PCMachineState *pcms =

        PC_MACHINE(object_dynamic_cast(OBJECT(ms), TYPE_PC_MACHINE));

    QLIST_INIT(&x86_iommu->iec_notifiers);



    if (!pcms) {

        error_setg(errp, "Machine-type '%s' not supported by IOMMU",

                   mc->name);

        return;

    }



    if (x86_class->realize) {

        x86_class->realize(dev, errp);

    }



    x86_iommu_set_default(X86_IOMMU_DEVICE(dev));

}

static uint64_t cs_read (void *opaque, target_phys_addr_t addr, unsigned size)

{

    CSState *s = opaque;

    uint32_t saddr, iaddr, ret;



    saddr = addr;

    iaddr = ~0U;



    switch (saddr) {

    case Index_Address:

        ret = s->regs[saddr] & ~0x80;

        break;



    case Index_Data:

        if (!(s->dregs[MODE_And_ID] & MODE2))

            iaddr = s->regs[Index_Address] & 0x0f;

        else

            iaddr = s->regs[Index_Address] & 0x1f;



        ret = s->dregs[iaddr];

        if (iaddr == Error_Status_And_Initialization) {

            /* keep SEAL happy */

            if (s->aci_counter) {

                ret |= 1 << 5;

                s->aci_counter -= 1;

            }

        }

        break;



    default:

        ret = s->regs[saddr];

        break;

    }

    dolog ("read %d:%d -> %d\n", saddr, iaddr, ret);

    return ret;

}

static int mmu_translate_region(CPUS390XState *env, target_ulong vaddr,

                                uint64_t asc, uint64_t entry, int level,

                                target_ulong *raddr, int *flags, int rw)

{

    CPUState *cs = CPU(s390_env_get_cpu(env));

    uint64_t origin, offs, new_entry;

    const int pchks[4] = {

        PGM_SEGMENT_TRANS, PGM_REG_THIRD_TRANS,

        PGM_REG_SEC_TRANS, PGM_REG_FIRST_TRANS

    };



    PTE_DPRINTF("%s: 0x%" PRIx64 "\n", __func__, entry);



    origin = entry & _REGION_ENTRY_ORIGIN;

    offs = (vaddr >> (17 + 11 * level / 4)) & 0x3ff8;



    new_entry = ldq_phys(cs->as, origin + offs);

    PTE_DPRINTF("%s: 0x%" PRIx64 " + 0x%" PRIx64 " => 0x%016" PRIx64 "\n",

                __func__, origin, offs, new_entry);



    if ((new_entry & _REGION_ENTRY_INV) != 0) {

        /* XXX different regions have different faults */

        DPRINTF("%s: invalid region\n", __func__);

        trigger_page_fault(env, vaddr, PGM_SEGMENT_TRANS, asc, rw);

        return -1;

    }



    if ((new_entry & _REGION_ENTRY_TYPE_MASK) != level) {

        trigger_page_fault(env, vaddr, PGM_TRANS_SPEC, asc, rw);

        return -1;

    }



    /* XXX region protection flags */

    /* *flags &= ~PAGE_WRITE */



    if (level == _ASCE_TYPE_SEGMENT) {

        return mmu_translate_segment(env, vaddr, asc, new_entry, raddr, flags,

                                     rw);

    }



    /* Check region table offset and length */

    offs = (vaddr >> (28 + 11 * (level - 4) / 4)) & 3;

    if (offs < ((new_entry & _REGION_ENTRY_TF) >> 6)

        || offs > (new_entry & _REGION_ENTRY_LENGTH)) {

        DPRINTF("%s: invalid offset or len (%lx)\n", __func__, new_entry);

        trigger_page_fault(env, vaddr, pchks[level / 4 - 1], asc, rw);

        return -1;

    }



    /* yet another region */

    return mmu_translate_region(env, vaddr, asc, new_entry, level - 4,

                                raddr, flags, rw);

}

static void sunkbd_handle_event(DeviceState *dev, QemuConsole *src,

                                InputEvent *evt)

{

    ChannelState *s = (ChannelState *)dev;

    int qcode, keycode;

    InputKeyEvent *key;



    assert(evt->type == INPUT_EVENT_KIND_KEY);

    key = evt->u.key;

    qcode = qemu_input_key_value_to_qcode(key->key);

    trace_escc_sunkbd_event_in(qcode, QKeyCode_lookup[qcode],

                               key->down);



    if (qcode == Q_KEY_CODE_CAPS_LOCK) {

        if (key->down) {

            s->caps_lock_mode ^= 1;

            if (s->caps_lock_mode == 2) {

                return; /* Drop second press */

            }

        } else {

            s->caps_lock_mode ^= 2;

            if (s->caps_lock_mode == 3) {

                return; /* Drop first release */

            }

        }

    }



    if (qcode == Q_KEY_CODE_NUM_LOCK) {

        if (key->down) {

            s->num_lock_mode ^= 1;

            if (s->num_lock_mode == 2) {

                return; /* Drop second press */

            }

        } else {

            s->num_lock_mode ^= 2;

            if (s->num_lock_mode == 3) {

                return; /* Drop first release */

            }

        }

    }



    keycode = qcode_to_keycode[qcode];

    if (!key->down) {

        keycode |= 0x80;

    }

    trace_escc_sunkbd_event_out(keycode);

    put_queue(s, keycode);

}

static void fmod_write_sample (HWVoiceOut *hw, uint8_t *dst, int dst_len)

{

    int src_len1 = dst_len;

    int src_len2 = 0;

    int pos = hw->rpos + dst_len;

    st_sample_t *src1 = hw->mix_buf + hw->rpos;

    st_sample_t *src2 = NULL;



    if (pos > hw->samples) {

        src_len1 = hw->samples - hw->rpos;

        src2 = hw->mix_buf;

        src_len2 = dst_len - src_len1;

        pos = src_len2;

    }



    if (src_len1) {

        hw->clip (dst, src1, src_len1);

    }



    if (src_len2) {

        dst = advance (dst, src_len1 << hw->info.shift);

        hw->clip (dst, src2, src_len2);

    }



    hw->rpos = pos % hw->samples;

}

