static int compare_litqobj_to_qobj(LiteralQObject *lhs, QObject *rhs)

{

    if (lhs->type != qobject_type(rhs)) {

        return 0;

    }



    switch (lhs->type) {

    case QTYPE_QINT:

        return lhs->value.qint == qint_get_int(qobject_to_qint(rhs));

    case QTYPE_QSTRING:

        return (strcmp(lhs->value.qstr, qstring_get_str(qobject_to_qstring(rhs))) == 0);

    case QTYPE_QDICT: {

        int i;



        for (i = 0; lhs->value.qdict[i].key; i++) {

            QObject *obj = qdict_get(qobject_to_qdict(rhs), lhs->value.qdict[i].key);



            if (!compare_litqobj_to_qobj(&lhs->value.qdict[i].value, obj)) {

                return 0;

            }

        }



        return 1;

    }

    case QTYPE_QLIST: {

        QListCompareHelper helper;



        helper.index = 0;

        helper.objs = lhs->value.qlist;

        helper.result = 1;



        qlist_iter(qobject_to_qlist(rhs), compare_helper, &helper);



        return helper.result;

    }

    default:

        break;

    }



    return 0;

}

static void trigger_prot_fault(CPUS390XState *env, target_ulong vaddr,

                               uint64_t asc, int rw, bool exc)

{

    uint64_t tec;



    tec = vaddr | (rw == MMU_DATA_STORE ? FS_WRITE : FS_READ) | 4 | asc >> 46;



    DPRINTF("%s: trans_exc_code=%016" PRIx64 "\n", __func__, tec);



    if (!exc) {

        return;

    }



    trigger_access_exception(env, PGM_PROTECTION, ILEN_LATER_INC, tec);

}

static int check_oflag_copied(BlockDriverState *bs, BdrvCheckResult *res)

{

    BDRVQcowState *s = bs->opaque;

    uint64_t *l2_table = qemu_blockalign(bs, s->cluster_size);

    int ret;

    int refcount;

    int i, j;



    for (i = 0; i < s->l1_size; i++) {

        uint64_t l1_entry = s->l1_table[i];

        uint64_t l2_offset = l1_entry & L1E_OFFSET_MASK;



        if (!l2_offset) {

            continue;

        }



        refcount = get_refcount(bs, l2_offset >> s->cluster_bits);

        if (refcount < 0) {

            /* don't print message nor increment check_errors */

            continue;

        }

        if ((refcount == 1) != ((l1_entry & QCOW_OFLAG_COPIED) != 0)) {

            fprintf(stderr, "ERROR OFLAG_COPIED L2 cluster: l1_index=%d "

                    "l1_entry=%" PRIx64 " refcount=%d\n",

                    i, l1_entry, refcount);

            res->corruptions++;

        }



        ret = bdrv_pread(bs->file, l2_offset, l2_table,

                         s->l2_size * sizeof(uint64_t));

        if (ret < 0) {

            fprintf(stderr, "ERROR: Could not read L2 table: %s\n",

                    strerror(-ret));

            res->check_errors++;

            goto fail;

        }



        for (j = 0; j < s->l2_size; j++) {

            uint64_t l2_entry = be64_to_cpu(l2_table[j]);

            uint64_t data_offset = l2_entry & L2E_OFFSET_MASK;

            int cluster_type = qcow2_get_cluster_type(l2_entry);



            if ((cluster_type == QCOW2_CLUSTER_NORMAL) ||

                ((cluster_type == QCOW2_CLUSTER_ZERO) && (data_offset != 0))) {

                refcount = get_refcount(bs, data_offset >> s->cluster_bits);

                if (refcount < 0) {

                    /* don't print message nor increment check_errors */

                    continue;

                }

                if ((refcount == 1) != ((l2_entry & QCOW_OFLAG_COPIED) != 0)) {

                    fprintf(stderr, "ERROR OFLAG_COPIED data cluster: "

                            "l2_entry=%" PRIx64 " refcount=%d\n",

                            l2_entry, refcount);

                    res->corruptions++;

                }

            }

        }

    }



    ret = 0;



fail:

    qemu_vfree(l2_table);

    return ret;

}

static int map_f(BlockBackend *blk, int argc, char **argv)

{

    int64_t offset;

    int64_t nb_sectors, total_sectors;

    char s1[64];

    int64_t num;

    int ret;

    const char *retstr;



    offset = 0;

    total_sectors = blk_nb_sectors(blk);

    if (total_sectors < 0) {

        error_report("Failed to query image length: %s",

                     strerror(-total_sectors));

        return 0;

    }



    nb_sectors = total_sectors;



    do {

        ret = map_is_allocated(blk_bs(blk), offset, nb_sectors, &num);

        if (ret < 0) {

            error_report("Failed to get allocation status: %s", strerror(-ret));

            return 0;

        } else if (!num) {

            error_report("Unexpected end of image");

            return 0;

        }



        retstr = ret ? "    allocated" : "not allocated";

        cvtstr(offset << 9ULL, s1, sizeof(s1));

        printf("[% 24" PRId64 "] % 8" PRId64 "/% 8" PRId64 " sectors %s "

               "at offset %s (%d)\n",

               offset << 9ULL, num, nb_sectors, retstr, s1, ret);



        offset += num;

        nb_sectors -= num;

    } while (offset < total_sectors);



    return 0;

}

fdctrl_t *fdctrl_init (qemu_irq irq, int dma_chann, int mem_mapped,

                       target_phys_addr_t io_base,

                       BlockDriverState **fds)

{

    fdctrl_t *fdctrl;

    int io_mem;

    int i;



    FLOPPY_DPRINTF("init controller\n");

    fdctrl = qemu_mallocz(sizeof(fdctrl_t));

    if (!fdctrl)

        return NULL;

    fdctrl->fifo = qemu_memalign(512, FD_SECTOR_LEN);

    if (fdctrl->fifo == NULL) {

        qemu_free(fdctrl);

        return NULL;

    }

    fdctrl->result_timer = qemu_new_timer(vm_clock,

                                          fdctrl_result_timer, fdctrl);



    fdctrl->version = 0x90; /* Intel 82078 controller */

    fdctrl->irq = irq;

    fdctrl->dma_chann = dma_chann;

    fdctrl->io_base = io_base;

    fdctrl->config = 0x60; /* Implicit seek, polling & FIFO enabled */

    fdctrl->sun4m = 0;

    if (fdctrl->dma_chann != -1) {

        fdctrl->dma_en = 1;

        DMA_register_channel(dma_chann, &fdctrl_transfer_handler, fdctrl);

    } else {

        fdctrl->dma_en = 0;

    }

    for (i = 0; i < 2; i++) {

        fd_init(&fdctrl->drives[i], fds[i]);

    }

    fdctrl_reset(fdctrl, 0);

    fdctrl->state = FD_CTRL_ACTIVE;

    if (mem_mapped) {

        io_mem = cpu_register_io_memory(0, fdctrl_mem_read, fdctrl_mem_write,

                                        fdctrl);

        cpu_register_physical_memory(io_base, 0x08, io_mem);

    } else {

        register_ioport_read((uint32_t)io_base + 0x01, 5, 1, &fdctrl_read,

                             fdctrl);

        register_ioport_read((uint32_t)io_base + 0x07, 1, 1, &fdctrl_read,

                             fdctrl);

        register_ioport_write((uint32_t)io_base + 0x01, 5, 1, &fdctrl_write,

                              fdctrl);

        register_ioport_write((uint32_t)io_base + 0x07, 1, 1, &fdctrl_write,

                              fdctrl);

    }

    register_savevm("fdc", io_base, 1, fdc_save, fdc_load, fdctrl);

    qemu_register_reset(fdctrl_external_reset, fdctrl);

    for (i = 0; i < 2; i++) {

        fd_revalidate(&fdctrl->drives[i]);

    }



    return fdctrl;

}

void *block_job_create(const BlockJobDriver *driver, BlockDriverState *bs,

                       int64_t speed, BlockDriverCompletionFunc *cb,

                       void *opaque, Error **errp)

{

    BlockJob *job;



    if (bs->job || bdrv_in_use(bs)) {

        error_set(errp, QERR_DEVICE_IN_USE, bdrv_get_device_name(bs));

        return NULL;

    }

    bdrv_ref(bs);

    bdrv_set_in_use(bs, 1);



    job = g_malloc0(driver->instance_size);

    job->driver        = driver;

    job->bs            = bs;

    job->cb            = cb;

    job->opaque        = opaque;

    job->busy          = true;

    bs->job = job;



    /* Only set speed when necessary to avoid NotSupported error */

    if (speed != 0) {

        Error *local_err = NULL;



        block_job_set_speed(job, speed, &local_err);

        if (local_err) {

            bs->job = NULL;

            g_free(job);

            bdrv_set_in_use(bs, 0);

            error_propagate(errp, local_err);

            return NULL;

        }

    }

    return job;

}

static int apb_pci_bridge_initfn(PCIDevice *dev)

{

    int rc;



    rc = pci_bridge_initfn(dev);

    if (rc < 0) {

        return rc;

    }



    pci_config_set_vendor_id(dev->config, PCI_VENDOR_ID_SUN);

    pci_config_set_device_id(dev->config, PCI_DEVICE_ID_SUN_SIMBA);



    /*

     * command register:

     * According to PCI bridge spec, after reset

     *   bus master bit is off

     *   memory space enable bit is off

     * According to manual (805-1251.pdf).

     *   the reset value should be zero unless the boot pin is tied high

     *   (which is true) and thus it should be PCI_COMMAND_MEMORY.

     */

    pci_set_word(dev->config + PCI_COMMAND,

                 PCI_COMMAND_MEMORY);

    pci_set_word(dev->config + PCI_STATUS,

                 PCI_STATUS_FAST_BACK | PCI_STATUS_66MHZ |

                 PCI_STATUS_DEVSEL_MEDIUM);

    pci_set_byte(dev->config + PCI_REVISION_ID, 0x11);

    return 0;

}

static int proxy_rename(FsContext *ctx, const char *oldpath,

                        const char *newpath)

{

    int retval;

    V9fsString oldname, newname;



    v9fs_string_init(&oldname);

    v9fs_string_init(&newname);



    v9fs_string_sprintf(&oldname, "%s", oldpath);

    v9fs_string_sprintf(&newname, "%s", newpath);

