static void handle_pending_signal(CPUArchState *cpu_env, int sig)

{

    CPUState *cpu = ENV_GET_CPU(cpu_env);

    abi_ulong handler;

    sigset_t set;

    target_sigset_t target_old_set;

    struct target_sigaction *sa;

    TaskState *ts = cpu->opaque;

    struct emulated_sigtable *k = &ts->sigtab[sig - 1];



    trace_user_handle_signal(cpu_env, sig);

    /* dequeue signal */

    k->pending = 0;



    sig = gdb_handlesig(cpu, sig);

    if (!sig) {

        sa = NULL;

        handler = TARGET_SIG_IGN;

    } else {

        sa = &sigact_table[sig - 1];

        handler = sa->_sa_handler;

    }



    if (sig == TARGET_SIGSEGV && sigismember(&ts->signal_mask, SIGSEGV)) {

        /* Guest has blocked SIGSEGV but we got one anyway. Assume this

         * is a forced SIGSEGV (ie one the kernel handles via force_sig_info

         * because it got a real MMU fault), and treat as if default handler.

         */

        handler = TARGET_SIG_DFL;

    }



    if (handler == TARGET_SIG_DFL) {

        /* default handler : ignore some signal. The other are job control or fatal */

        if (sig == TARGET_SIGTSTP || sig == TARGET_SIGTTIN || sig == TARGET_SIGTTOU) {

            kill(getpid(),SIGSTOP);

        } else if (sig != TARGET_SIGCHLD &&

                   sig != TARGET_SIGURG &&

                   sig != TARGET_SIGWINCH &&

                   sig != TARGET_SIGCONT) {

            force_sig(sig);

        }

    } else if (handler == TARGET_SIG_IGN) {

        /* ignore sig */

    } else if (handler == TARGET_SIG_ERR) {

        force_sig(sig);

    } else {

        /* compute the blocked signals during the handler execution */

        sigset_t *blocked_set;



        target_to_host_sigset(&set, &sa->sa_mask);

        /* SA_NODEFER indicates that the current signal should not be

           blocked during the handler */

        if (!(sa->sa_flags & TARGET_SA_NODEFER))

            sigaddset(&set, target_to_host_signal(sig));



        /* save the previous blocked signal state to restore it at the

           end of the signal execution (see do_sigreturn) */

        host_to_target_sigset_internal(&target_old_set, &ts->signal_mask);



        /* block signals in the handler */

        blocked_set = ts->in_sigsuspend ?

            &ts->sigsuspend_mask : &ts->signal_mask;

        sigorset(&ts->signal_mask, blocked_set, &set);

        ts->in_sigsuspend = 0;



        /* if the CPU is in VM86 mode, we restore the 32 bit values */

#if defined(TARGET_I386) && !defined(TARGET_X86_64)

        {

            CPUX86State *env = cpu_env;

            if (env->eflags & VM_MASK)

                save_v86_state(env);

        }

#endif

        /* prepare the stack frame of the virtual CPU */

#if defined(TARGET_ABI_MIPSN32) || defined(TARGET_ABI_MIPSN64) \

    || defined(TARGET_OPENRISC) || defined(TARGET_TILEGX)

        /* These targets do not have traditional signals.  */

        setup_rt_frame(sig, sa, &k->info, &target_old_set, cpu_env);

#else

        if (sa->sa_flags & TARGET_SA_SIGINFO)

            setup_rt_frame(sig, sa, &k->info, &target_old_set, cpu_env);

        else

            setup_frame(sig, sa, &target_old_set, cpu_env);

#endif

        if (sa->sa_flags & TARGET_SA_RESETHAND) {

            sa->_sa_handler = TARGET_SIG_DFL;

        }

    }

}

static void pxa2xx_gpio_handler_update(PXA2xxGPIOInfo *s) {

    uint32_t level, diff;

    int i, bit, line;

    for (i = 0; i < PXA2XX_GPIO_BANKS; i ++) {

        level = s->olevel[i] & s->dir[i];



        for (diff = s->prev_level[i] ^ level; diff; diff ^= 1 << bit) {

            bit = ffs(diff) - 1;

            line = bit + 32 * i;

            qemu_set_irq(s->handler[line], (level >> bit) & 1);

        }



        s->prev_level[i] = level;

    }

}

int kvm_init(int smp_cpus)

{

    static const char upgrade_note[] =

        "Please upgrade to at least kernel 2.6.29 or recent kvm-kmod\n"

        "(see http://sourceforge.net/projects/kvm).\n";

    KVMState *s;

    int ret;

    int i;



    if (smp_cpus > 1) {

        fprintf(stderr, "No SMP KVM support, use '-smp 1'\n");

        return -EINVAL;

    }



    s = qemu_mallocz(sizeof(KVMState));



#ifdef KVM_CAP_SET_GUEST_DEBUG

    TAILQ_INIT(&s->kvm_sw_breakpoints);

#endif

    for (i = 0; i < ARRAY_SIZE(s->slots); i++)

        s->slots[i].slot = i;



    s->vmfd = -1;

    s->fd = open("/dev/kvm", O_RDWR);

    if (s->fd == -1) {

        fprintf(stderr, "Could not access KVM kernel module: %m\n");

        ret = -errno;

        goto err;

    }



    ret = kvm_ioctl(s, KVM_GET_API_VERSION, 0);

    if (ret < KVM_API_VERSION) {

        if (ret > 0)

            ret = -EINVAL;

        fprintf(stderr, "kvm version too old\n");

        goto err;

    }



    if (ret > KVM_API_VERSION) {

        ret = -EINVAL;

        fprintf(stderr, "kvm version not supported\n");

        goto err;

    }



    s->vmfd = kvm_ioctl(s, KVM_CREATE_VM, 0);

    if (s->vmfd < 0)

        goto err;



    /* initially, KVM allocated its own memory and we had to jump through

     * hooks to make phys_ram_base point to this.  Modern versions of KVM

     * just use a user allocated buffer so we can use regular pages

     * unmodified.  Make sure we have a sufficiently modern version of KVM.

     */

    if (!kvm_check_extension(s, KVM_CAP_USER_MEMORY)) {

        ret = -EINVAL;

        fprintf(stderr, "kvm does not support KVM_CAP_USER_MEMORY\n%s",

                upgrade_note);

        goto err;

    }



    /* There was a nasty bug in < kvm-80 that prevents memory slots from being

     * destroyed properly.  Since we rely on this capability, refuse to work

     * with any kernel without this capability. */

    if (!kvm_check_extension(s, KVM_CAP_DESTROY_MEMORY_REGION_WORKS)) {

        ret = -EINVAL;



        fprintf(stderr,

                "KVM kernel module broken (DESTROY_MEMORY_REGION).\n%s",

                upgrade_note);

        goto err;

    }



#ifdef KVM_CAP_COALESCED_MMIO

    s->coalesced_mmio = kvm_check_extension(s, KVM_CAP_COALESCED_MMIO);

#else

    s->coalesced_mmio = 0;

#endif



    s->broken_set_mem_region = 1;

#ifdef KVM_CAP_JOIN_MEMORY_REGIONS_WORKS

    ret = kvm_ioctl(s, KVM_CHECK_EXTENSION, KVM_CAP_JOIN_MEMORY_REGIONS_WORKS);

    if (ret > 0) {

        s->broken_set_mem_region = 0;

    }

#endif



    ret = kvm_arch_init(s, smp_cpus);

    if (ret < 0)

        goto err;



    kvm_state = s;



    return 0;



err:

    if (s) {

        if (s->vmfd != -1)

            close(s->vmfd);

        if (s->fd != -1)

            close(s->fd);

    }

    qemu_free(s);



    return ret;

}

static int virtconsole_initfn(VirtIOSerialPort *port)

{

    VirtConsole *vcon = DO_UPCAST(VirtConsole, port, port);

    VirtIOSerialPortInfo *info = DO_UPCAST(VirtIOSerialPortInfo, qdev,

                                           vcon->port.dev.info);



    if (port->id == 0 && !info->is_console) {

        error_report("Port number 0 on virtio-serial devices reserved for virtconsole devices for backward compatibility.");

        return -1;

    }



    if (vcon->chr) {

        qemu_chr_add_handlers(vcon->chr, chr_can_read, chr_read, chr_event,

                              vcon);

        info->have_data = flush_buf;

        info->guest_open = guest_open;

        info->guest_close = guest_close;

    }



    return 0;

}

static int ppc_hash32_get_physical_address(CPUPPCState *env, struct mmu_ctx_hash32 *ctx,

                                           target_ulong eaddr, int rw,

                                           int access_type)

{

    bool real_mode = (access_type == ACCESS_CODE && msr_ir == 0)

        || (access_type != ACCESS_CODE && msr_dr == 0);



    if (real_mode) {

        ctx->raddr = eaddr;

        ctx->prot = PAGE_READ | PAGE_EXEC | PAGE_WRITE;

        return 0;

    } else {

        int ret = -1;



        /* Try to find a BAT */

        if (env->nb_BATs != 0) {

            ret = ppc_hash32_get_bat(env, ctx, eaddr, rw, access_type);

        }

        if (ret < 0) {

            /* We didn't match any BAT entry or don't have BATs */

            ret = get_segment32(env, ctx, eaddr, rw, access_type);

        }

        return ret;

    }

}

static int vmdk_read(BlockDriverState *bs, int64_t sector_num,

                    uint8_t *buf, int nb_sectors)

{

    BDRVVmdkState *s = bs->opaque;

    int ret;

    uint64_t n, index_in_cluster;

    VmdkExtent *extent = NULL;

    uint64_t cluster_offset;



    while (nb_sectors > 0) {

        extent = find_extent(s, sector_num, extent);

        if (!extent) {

            return -EIO;

        }

        ret = get_cluster_offset(

                            bs, extent, NULL,

                            sector_num << 9, 0, &cluster_offset);

        index_in_cluster = sector_num % extent->cluster_sectors;

        n = extent->cluster_sectors - index_in_cluster;

        if (n > nb_sectors)

            n = nb_sectors;

        if (ret) {

            /* if not allocated, try to read from parent image, if exist */

            if (bs->backing_hd) {

                if (!vmdk_is_cid_valid(bs))

                    return -EINVAL;

                ret = bdrv_read(bs->backing_hd, sector_num, buf, n);

                if (ret < 0)

                    return ret;

            } else {

                memset(buf, 0, 512 * n);

            }

        } else {

            ret = bdrv_pread(extent->file,

                            cluster_offset + index_in_cluster * 512,

                            buf, n * 512);

            if (ret < 0) {

                return ret;

            }

        }

        nb_sectors -= n;

        sector_num += n;

        buf += n * 512;

    }

    return 0;

}

static bool migrate_params_check(MigrationParameters *params, Error **errp)

{

    if (params->has_compress_level &&

        (params->compress_level < 0 || params->compress_level > 9)) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE, "compress_level",

                   "is invalid, it should be in the range of 0 to 9");

        return false;

    }



    if (params->has_compress_threads &&

        (params->compress_threads < 1 || params->compress_threads > 255)) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE,

                   "compress_threads",

                   "is invalid, it should be in the range of 1 to 255");

        return false;

    }



    if (params->has_decompress_threads &&

        (params->decompress_threads < 1 || params->decompress_threads > 255)) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE,

                   "decompress_threads",

                   "is invalid, it should be in the range of 1 to 255");

        return false;

    }



    if (params->has_cpu_throttle_initial &&

        (params->cpu_throttle_initial < 1 ||

         params->cpu_throttle_initial > 99)) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE,

                   "cpu_throttle_initial",

                   "an integer in the range of 1 to 99");

        return false;

    }



    if (params->has_cpu_throttle_increment &&

        (params->cpu_throttle_increment < 1 ||

         params->cpu_throttle_increment > 99)) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE,

                   "cpu_throttle_increment",

                   "an integer in the range of 1 to 99");

        return false;

    }



    if (params->has_max_bandwidth &&

        (params->max_bandwidth < 0 || params->max_bandwidth > SIZE_MAX)) {

        error_setg(errp, "Parameter 'max_bandwidth' expects an integer in the"

                         " range of 0 to %zu bytes/second", SIZE_MAX);

        return false;

    }



    if (params->has_downtime_limit &&

        (params->downtime_limit < 0 ||

         params->downtime_limit > MAX_MIGRATE_DOWNTIME)) {

        error_setg(errp, "Parameter 'downtime_limit' expects an integer in "

                         "the range of 0 to %d milliseconds",

                         MAX_MIGRATE_DOWNTIME);

        return false;

    }



    if (params->has_x_checkpoint_delay && (params->x_checkpoint_delay < 0)) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE,

                    "x_checkpoint_delay",

                    "is invalid, it should be positive");

        return false;

    }

    if (params->has_x_multifd_channels &&

        (params->x_multifd_channels < 1 || params->x_multifd_channels > 255)) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE,

                   "multifd_channels",

                   "is invalid, it should be in the range of 1 to 255");

        return false;

    }

    if (params->has_x_multifd_page_count &&

            (params->x_multifd_page_count < 1 ||

             params->x_multifd_page_count > 10000)) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE,

                   "multifd_page_count",

                   "is invalid, it should be in the range of 1 to 10000");

        return false;

    }



    if (params->has_xbzrle_cache_size &&

        (params->xbzrle_cache_size < qemu_target_page_size() ||

         !is_power_of_2(params->xbzrle_cache_size))) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE,

                   "xbzrle_cache_size",

                   "is invalid, it should be bigger than target page size"

                   " and a power of two");

        return false;

    }



    return true;

}

int add_exec(struct ex_list **ex_ptr, int do_pty, char *exec,

             struct in_addr addr, int port)

{

	struct ex_list *tmp_ptr;



	/* First, check if the port is "bound" */

	for (tmp_ptr = *ex_ptr; tmp_ptr; tmp_ptr = tmp_ptr->ex_next) {

		if (port == tmp_ptr->ex_fport &&

		    addr.s_addr == tmp_ptr->ex_addr.s_addr)

			return -1;

	}



	tmp_ptr = *ex_ptr;

	*ex_ptr = (struct ex_list *)malloc(sizeof(struct ex_list));

	(*ex_ptr)->ex_fport = port;

	(*ex_ptr)->ex_addr = addr;

	(*ex_ptr)->ex_pty = do_pty;

	(*ex_ptr)->ex_exec = (do_pty == 3) ? exec : strdup(exec);

	(*ex_ptr)->ex_next = tmp_ptr;

	return 0;

}

static void dec_sextb(DisasContext *dc)

