static int vfio_add_capabilities(VFIOPCIDevice *vdev)

{

    PCIDevice *pdev = &vdev->pdev;

    int ret;



    if (!(pdev->config[PCI_STATUS] & PCI_STATUS_CAP_LIST) ||

        !pdev->config[PCI_CAPABILITY_LIST]) {

        return 0; /* Nothing to add */

    }



    ret = vfio_add_std_cap(vdev, pdev->config[PCI_CAPABILITY_LIST]);

    if (ret) {

        return ret;

    }



    /* on PCI bus, it doesn't make sense to expose extended capabilities. */

    if (!pci_is_express(pdev) ||

        !pci_bus_is_express(pdev->bus) ||

        !pci_get_long(pdev->config + PCI_CONFIG_SPACE_SIZE)) {

        return 0;

    }



    return vfio_add_ext_cap(vdev);

}

static void test_qemu_strtosz_units(void)

{

    const char *none = "1";

    const char *b = "1B";

    const char *k = "1K";

    const char *m = "1M";

    const char *g = "1G";

    const char *t = "1T";

    const char *p = "1P";

    const char *e = "1E";

    char *endptr = NULL;

    int64_t res;



    /* default is M */

    res = qemu_strtosz_MiB(none, &endptr);

    g_assert_cmpint(res, ==, M_BYTE);

    g_assert(endptr == none + 1);



    res = qemu_strtosz(b, &endptr);

    g_assert_cmpint(res, ==, 1);

    g_assert(endptr == b + 2);



    res = qemu_strtosz(k, &endptr);

    g_assert_cmpint(res, ==, K_BYTE);

    g_assert(endptr == k + 2);



    res = qemu_strtosz(m, &endptr);

    g_assert_cmpint(res, ==, M_BYTE);

    g_assert(endptr == m + 2);



    res = qemu_strtosz(g, &endptr);

    g_assert_cmpint(res, ==, G_BYTE);

    g_assert(endptr == g + 2);



    res = qemu_strtosz(t, &endptr);

    g_assert_cmpint(res, ==, T_BYTE);

    g_assert(endptr == t + 2);



    res = qemu_strtosz(p, &endptr);

    g_assert_cmpint(res, ==, P_BYTE);

    g_assert(endptr == p + 2);



    res = qemu_strtosz(e, &endptr);

    g_assert_cmpint(res, ==, E_BYTE);

    g_assert(endptr == e + 2);

}

static inline void gen_op_arith_divd(DisasContext *ctx, TCGv ret, TCGv arg1,

                                     TCGv arg2, int sign, int compute_ov)

{

    int l1 = gen_new_label();

    int l2 = gen_new_label();



    tcg_gen_brcondi_i64(TCG_COND_EQ, arg2, 0, l1);

    if (sign) {

        int l3 = gen_new_label();

        tcg_gen_brcondi_i64(TCG_COND_NE, arg2, -1, l3);

        tcg_gen_brcondi_i64(TCG_COND_EQ, arg1, INT64_MIN, l1);

        gen_set_label(l3);

        tcg_gen_div_i64(ret, arg1, arg2);

    } else {

        tcg_gen_divu_i64(ret, arg1, arg2);

    }

    if (compute_ov) {

        tcg_gen_movi_tl(cpu_ov, 0);

    }

    tcg_gen_br(l2);

    gen_set_label(l1);

    if (sign) {

        tcg_gen_sari_i64(ret, arg1, 63);

    } else {

        tcg_gen_movi_i64(ret, 0);

    }

    if (compute_ov) {

        tcg_gen_movi_tl(cpu_ov, 1);

        tcg_gen_movi_tl(cpu_so, 1);

    }

    gen_set_label(l2);

    if (unlikely(Rc(ctx->opcode) != 0))

        gen_set_Rc0(ctx, ret);

}

static int os_host_main_loop_wait(int timeout)

{

    int ret, i;

    PollingEntry *pe;

    WaitObjects *w = &wait_objects;

    static struct timeval tv0;



    /* XXX: need to suppress polling by better using win32 events */

    ret = 0;

    for (pe = first_polling_entry; pe != NULL; pe = pe->next) {

        ret |= pe->func(pe->opaque);

    }

    if (ret != 0) {

        return ret;

    }



    if (nfds >= 0) {

        ret = select(nfds + 1, &rfds, &wfds, &xfds, &tv0);

        if (ret != 0) {

            timeout = 0;

        }

    }



    for (i = 0; i < w->num; i++) {

        poll_fds[i].fd = (DWORD) w->events[i];

        poll_fds[i].events = G_IO_IN;

    }



    qemu_mutex_unlock_iothread();

    ret = g_poll(poll_fds, w->num, timeout);

    qemu_mutex_lock_iothread();

    if (ret > 0) {

        for (i = 0; i < w->num; i++) {

            w->revents[i] = poll_fds[i].revents;

        }

        for (i = 0; i < w->num; i++) {

            if (w->revents[i] && w->func[i]) {

                w->func[i](w->opaque[i]);

            }

        }

    }



    /* If an edge-triggered socket event occurred, select will return a

     * positive result on the next iteration.  We do not need to do anything

     * here.

     */



    return ret;

}

static int do_syscall(CPUState *env,

                      struct kqemu_cpu_state *kenv)

{

    int selector;



    selector = (env->star >> 32) & 0xffff;

#ifdef TARGET_X86_64

    if (env->hflags & HF_LMA_MASK) {

        int code64;



        env->regs[R_ECX] = kenv->next_eip;

        env->regs[11] = env->eflags;



        code64 = env->hflags & HF_CS64_MASK;



        cpu_x86_set_cpl(env, 0);

        cpu_x86_load_seg_cache(env, R_CS, selector & 0xfffc,

                               0, 0xffffffff,

                               DESC_G_MASK | DESC_P_MASK |

                               DESC_S_MASK |

                               DESC_CS_MASK | DESC_R_MASK | DESC_A_MASK | DESC_L_MASK);

        cpu_x86_load_seg_cache(env, R_SS, (selector + 8) & 0xfffc,

                               0, 0xffffffff,

                               DESC_G_MASK | DESC_B_MASK | DESC_P_MASK |

                               DESC_S_MASK |

                               DESC_W_MASK | DESC_A_MASK);

        env->eflags &= ~env->fmask;

        if (code64)

            env->eip = env->lstar;

        else

            env->eip = env->cstar;

    } else

#endif

    {

        env->regs[R_ECX] = (uint32_t)kenv->next_eip;



        cpu_x86_set_cpl(env, 0);

        cpu_x86_load_seg_cache(env, R_CS, selector & 0xfffc,

                           0, 0xffffffff,

                               DESC_G_MASK | DESC_B_MASK | DESC_P_MASK |

                               DESC_S_MASK |

                               DESC_CS_MASK | DESC_R_MASK | DESC_A_MASK);

        cpu_x86_load_seg_cache(env, R_SS, (selector + 8) & 0xfffc,

                               0, 0xffffffff,

                               DESC_G_MASK | DESC_B_MASK | DESC_P_MASK |

                               DESC_S_MASK |

                               DESC_W_MASK | DESC_A_MASK);

        env->eflags &= ~(IF_MASK | RF_MASK | VM_MASK);

        env->eip = (uint32_t)env->star;

    }

    return 2;

}

gdb_handlesig(CPUState *cpu, int sig)

{

    GDBState *s;

    char buf[256];

    int n;



    s = gdbserver_state;

    if (gdbserver_fd < 0 || s->fd < 0) {

        return sig;

    }



    /* disable single step if it was enabled */

    cpu_single_step(cpu, 0);

    tb_flush(cpu);



    if (sig != 0) {

        snprintf(buf, sizeof(buf), "S%02x", target_signal_to_gdb(sig));

        put_packet(s, buf);

    }

    /* put_packet() might have detected that the peer terminated the

       connection.  */

    if (s->fd < 0) {

        return sig;

    }



    sig = 0;

    s->state = RS_IDLE;

    s->running_state = 0;

    while (s->running_state == 0) {

        n = read(s->fd, buf, 256);

        if (n > 0) {

            int i;



            for (i = 0; i < n; i++) {

                gdb_read_byte(s, buf[i]);

            }

        } else if (n == 0 || errno != EAGAIN) {

            /* XXX: Connection closed.  Should probably wait for another

               connection before continuing.  */

            return sig;

        }

    }

    sig = s->signal;

    s->signal = 0;

    return sig;

}

void xen_map_cache_init(void)

{

    unsigned long size;

    struct rlimit rlimit_as;



    mapcache = g_malloc0(sizeof (MapCache));



    QTAILQ_INIT(&mapcache->locked_entries);

    mapcache->last_address_index = -1;



    if (geteuid() == 0) {

        rlimit_as.rlim_cur = RLIM_INFINITY;

        rlimit_as.rlim_max = RLIM_INFINITY;

        mapcache->max_mcache_size = MCACHE_MAX_SIZE;

    } else {

        getrlimit(RLIMIT_AS, &rlimit_as);

        rlimit_as.rlim_cur = rlimit_as.rlim_max;



        if (rlimit_as.rlim_max != RLIM_INFINITY) {

            fprintf(stderr, "Warning: QEMU's maximum size of virtual"

                    " memory is not infinity.\n");

        }

        if (rlimit_as.rlim_max < MCACHE_MAX_SIZE + NON_MCACHE_MEMORY_SIZE) {

            mapcache->max_mcache_size = rlimit_as.rlim_max -

                NON_MCACHE_MEMORY_SIZE;

        } else {

            mapcache->max_mcache_size = MCACHE_MAX_SIZE;

        }

    }



    setrlimit(RLIMIT_AS, &rlimit_as);



    mapcache->nr_buckets =

        (((mapcache->max_mcache_size >> XC_PAGE_SHIFT) +

          (1UL << (MCACHE_BUCKET_SHIFT - XC_PAGE_SHIFT)) - 1) >>

         (MCACHE_BUCKET_SHIFT - XC_PAGE_SHIFT));



    size = mapcache->nr_buckets * sizeof (MapCacheEntry);

    size = (size + XC_PAGE_SIZE - 1) & ~(XC_PAGE_SIZE - 1);

    DPRINTF("%s, nr_buckets = %lx size %lu\n", __func__,

            mapcache->nr_buckets, size);

    mapcache->entry = g_malloc0(size);

}

static void nvdimm_build_nfit(AcpiNVDIMMState *state, GArray *table_offsets,

                              GArray *table_data, BIOSLinker *linker)

{

    NvdimmFitBuffer *fit_buf = &state->fit_buf;

    unsigned int header;





    /* NVDIMM device is not plugged? */

    if (!fit_buf->fit->len) {

        return;

    }



    acpi_add_table(table_offsets, table_data);



    /* NFIT header. */

    header = table_data->len;

    acpi_data_push(table_data, sizeof(NvdimmNfitHeader));

    /* NVDIMM device structures. */

    g_array_append_vals(table_data, fit_buf->fit->data, fit_buf->fit->len);



    build_header(linker, table_data,

                 (void *)(table_data->data + header), "NFIT",

                 sizeof(NvdimmNfitHeader) + fit_buf->fit->len, 1, NULL, NULL);

}

static inline uint32_t efsctui(uint32_t val)

{

    CPU_FloatU u;



    u.l = val;

    /* NaN are not treated the same way IEEE 754 does */

    if (unlikely(float32_is_nan(u.f)))

        return 0;



    return float32_to_uint32(u.f, &env->vec_status);

}

