    s->in = qemu_allocate_irqs(omap_mpuio_set, s, 16);

    omap_mpuio_reset(s);



    memory_region_init_io(&s->iomem, NULL, &omap_mpuio_ops, s,

                          "omap-mpuio", 0x800);

    memory_region_add_subregion(memory, base, &s->iomem);



    omap_clk_adduser(clk, qemu_allocate_irq(omap_mpuio_onoff, s, 0));



    return s;

}

static void iscsi_attach_aio_context(BlockDriverState *bs,

                                     AioContext *new_context)

{

    IscsiLun *iscsilun = bs->opaque;



    iscsilun->aio_context = new_context;

    iscsi_set_events(iscsilun);



#if defined(LIBISCSI_FEATURE_NOP_COUNTER)

    /* Set up a timer for sending out iSCSI NOPs */

    iscsilun->nop_timer = aio_timer_new(iscsilun->aio_context,

                                        QEMU_CLOCK_REALTIME, SCALE_MS,

                                        iscsi_nop_timed_event, iscsilun);

    timer_mod(iscsilun->nop_timer,

              qemu_clock_get_ms(QEMU_CLOCK_REALTIME) + NOP_INTERVAL);

#endif

}

static int64_t alloc_block(BlockDriverState* bs, int64_t sector_num)

{

    BDRVVPCState *s = bs->opaque;

    int64_t bat_offset;

    uint32_t index, bat_value;

    int ret;

    uint8_t bitmap[s->bitmap_size];



    // Check if sector_num is valid

    if ((sector_num < 0) || (sector_num > bs->total_sectors))

        return -1;



    // Write entry into in-memory BAT

    index = (sector_num * 512) / s->block_size;

    if (s->pagetable[index] != 0xFFFFFFFF)

        return -1;



    s->pagetable[index] = s->free_data_block_offset / 512;



    // Initialize the block's bitmap

    memset(bitmap, 0xff, s->bitmap_size);

    bdrv_pwrite(bs->file, s->free_data_block_offset, bitmap, s->bitmap_size);



    // Write new footer (the old one will be overwritten)

    s->free_data_block_offset += s->block_size + s->bitmap_size;

    ret = rewrite_footer(bs);

    if (ret < 0)

        goto fail;



    // Write BAT entry to disk

    bat_offset = s->bat_offset + (4 * index);

    bat_value = be32_to_cpu(s->pagetable[index]);

    ret = bdrv_pwrite(bs->file, bat_offset, &bat_value, 4);

    if (ret < 0)

        goto fail;



    return get_sector_offset(bs, sector_num, 0);



fail:

    s->free_data_block_offset -= (s->block_size + s->bitmap_size);

    return -1;

}

static void gen_addq(DisasContext *s, TCGv_i64 val, int rlow, int rhigh)

{

    TCGv_i64 tmp;

    TCGv tmpl;

    TCGv tmph;



    /* Load 64-bit value rd:rn.  */

    tmpl = load_reg(s, rlow);

    tmph = load_reg(s, rhigh);

    tmp = tcg_temp_new_i64();

    tcg_gen_concat_i32_i64(tmp, tmpl, tmph);

    dead_tmp(tmpl);

    dead_tmp(tmph);

    tcg_gen_add_i64(val, val, tmp);

    tcg_temp_free_i64(tmp);

}

static int do_compress_ram_page(QEMUFile *f, RAMBlock *block,

                                ram_addr_t offset)

{

    RAMState *rs = &ram_state;

    int bytes_sent, blen;

    uint8_t *p = block->host + (offset & TARGET_PAGE_MASK);



    bytes_sent = save_page_header(rs, block, offset |

                                  RAM_SAVE_FLAG_COMPRESS_PAGE);

    blen = qemu_put_compression_data(f, p, TARGET_PAGE_SIZE,

                                     migrate_compress_level());

    if (blen < 0) {

        bytes_sent = 0;

        qemu_file_set_error(migrate_get_current()->to_dst_file, blen);

        error_report("compressed data failed!");

    } else {

        bytes_sent += blen;

        ram_release_pages(block->idstr, offset & TARGET_PAGE_MASK, 1);

    }



    return bytes_sent;

}

static void ppc_cpu_unrealizefn(DeviceState *dev, Error **errp)

{

    PowerPCCPU *cpu = POWERPC_CPU(dev);

    CPUPPCState *env = &cpu->env;

    opc_handler_t **table;

    int i, j;



    cpu_exec_exit(CPU(dev));



    for (i = 0; i < PPC_CPU_OPCODES_LEN; i++) {

        if (env->opcodes[i] == &invalid_handler) {

            continue;

        }

        if (is_indirect_opcode(env->opcodes[i])) {

            table = ind_table(env->opcodes[i]);

            for (j = 0; j < PPC_CPU_INDIRECT_OPCODES_LEN; j++) {

                if (table[j] != &invalid_handler &&

                        is_indirect_opcode(table[j])) {

                    g_free((opc_handler_t *)((uintptr_t)table[j] &

                        ~PPC_INDIRECT));

                }

            }

            g_free((opc_handler_t *)((uintptr_t)env->opcodes[i] &

                ~PPC_INDIRECT));

        }

    }

}

