static void monitor_find_completion(Monitor *mon,

                                    const char *cmdline)

{

    char *args[MAX_ARGS];

    int nb_args, len;



    /* 1. parse the cmdline */

    if (parse_cmdline(cmdline, &nb_args, args) < 0) {

        return;

    }

#ifdef DEBUG_COMPLETION

    for (i = 0; i < nb_args; i++) {

        monitor_printf(mon, "arg%d = '%s'\n", i, args[i]);

    }

#endif



    /* if the line ends with a space, it means we want to complete the

       next arg */

    len = strlen(cmdline);

    if (len > 0 && qemu_isspace(cmdline[len - 1])) {

        if (nb_args >= MAX_ARGS) {

            goto cleanup;

        }

        args[nb_args++] = g_strdup("");

    }



    /* 2. auto complete according to args */

    monitor_find_completion_by_table(mon, mon->cmd_table, args, nb_args);



cleanup:

    free_cmdline_args(args, nb_args);

}

static void gdb_set_cpu_pc(GDBState *s, target_ulong pc)

{

#if defined(TARGET_I386)

    cpu_synchronize_state(s->c_cpu);

    s->c_cpu->eip = pc;

#elif defined (TARGET_PPC)

    s->c_cpu->nip = pc;

#elif defined (TARGET_SPARC)

    s->c_cpu->pc = pc;

    s->c_cpu->npc = pc + 4;

#elif defined (TARGET_ARM)

    s->c_cpu->regs[15] = pc;

#elif defined (TARGET_SH4)

    s->c_cpu->pc = pc;

#elif defined (TARGET_MIPS)

    s->c_cpu->active_tc.PC = pc;

#elif defined (TARGET_MICROBLAZE)

    s->c_cpu->sregs[SR_PC] = pc;

#elif defined (TARGET_CRIS)

    s->c_cpu->pc = pc;

#elif defined (TARGET_ALPHA)

    s->c_cpu->pc = pc;

#elif defined (TARGET_S390X)

    cpu_synchronize_state(s->c_cpu);

    s->c_cpu->psw.addr = pc;

#endif

}

bool hvf_inject_interrupts(CPUState *cpu_state)

{

    int allow_nmi = !(rvmcs(cpu_state->hvf_fd, VMCS_GUEST_INTERRUPTIBILITY) &

                VMCS_INTERRUPTIBILITY_NMI_BLOCKING);

    X86CPU *x86cpu = X86_CPU(cpu_state);

    CPUX86State *env = &x86cpu->env;



    uint64_t idt_info = rvmcs(cpu_state->hvf_fd, VMCS_IDT_VECTORING_INFO);

    uint64_t info = 0;



    if (idt_info & VMCS_IDT_VEC_VALID) {

        uint8_t vector = idt_info & 0xff;

        uint64_t intr_type = idt_info & VMCS_INTR_T_MASK;

        info = idt_info;



        uint64_t reason = rvmcs(cpu_state->hvf_fd, VMCS_EXIT_REASON);

        if (intr_type == VMCS_INTR_T_NMI && reason != EXIT_REASON_TASK_SWITCH) {

            allow_nmi = 1;

            vmx_clear_nmi_blocking(cpu_state);

        }



        if ((allow_nmi || intr_type != VMCS_INTR_T_NMI)) {

            info &= ~(1 << 12); /* clear undefined bit */

            if (intr_type == VMCS_INTR_T_SWINTR ||

                intr_type == VMCS_INTR_T_PRIV_SWEXCEPTION ||

                intr_type == VMCS_INTR_T_SWEXCEPTION) {

                uint64_t ins_len = rvmcs(cpu_state->hvf_fd,

                                         VMCS_EXIT_INSTRUCTION_LENGTH);

                wvmcs(cpu_state->hvf_fd, VMCS_ENTRY_INST_LENGTH, ins_len);

            }

            if (vector == EXCEPTION_BP || vector == EXCEPTION_OF) {

                /*

                 * VT-x requires #BP and #OF to be injected as software

                 * exceptions.

                 */

                info &= ~VMCS_INTR_T_MASK;

                info |= VMCS_INTR_T_SWEXCEPTION;

                uint64_t ins_len = rvmcs(cpu_state->hvf_fd,

                                         VMCS_EXIT_INSTRUCTION_LENGTH);

                wvmcs(cpu_state->hvf_fd, VMCS_ENTRY_INST_LENGTH, ins_len);

            }



            uint64_t err = 0;

            if (idt_info & VMCS_INTR_DEL_ERRCODE) {

                err = rvmcs(cpu_state->hvf_fd, VMCS_IDT_VECTORING_ERROR);

                wvmcs(cpu_state->hvf_fd, VMCS_ENTRY_EXCEPTION_ERROR, err);

            }

            /*printf("reinject  %lx err %d\n", info, err);*/

            wvmcs(cpu_state->hvf_fd, VMCS_ENTRY_INTR_INFO, info);

        };

    }



    if (cpu_state->interrupt_request & CPU_INTERRUPT_NMI) {

        if (allow_nmi && !(info & VMCS_INTR_VALID)) {

            cpu_state->interrupt_request &= ~CPU_INTERRUPT_NMI;

            info = VMCS_INTR_VALID | VMCS_INTR_T_NMI | NMI_VEC;

            wvmcs(cpu_state->hvf_fd, VMCS_ENTRY_INTR_INFO, info);

        } else {

            vmx_set_nmi_window_exiting(cpu_state);

        }

    }



    if (env->hvf_emul->interruptable &&

        (cpu_state->interrupt_request & CPU_INTERRUPT_HARD) &&

        (EFLAGS(env) & IF_MASK) && !(info & VMCS_INTR_VALID)) {

        int line = cpu_get_pic_interrupt(&x86cpu->env);

        cpu_state->interrupt_request &= ~CPU_INTERRUPT_HARD;

        if (line >= 0) {

            wvmcs(cpu_state->hvf_fd, VMCS_ENTRY_INTR_INFO, line |

                  VMCS_INTR_VALID | VMCS_INTR_T_HWINTR);

        }

    }

    if (cpu_state->interrupt_request & CPU_INTERRUPT_HARD) {

        vmx_set_int_window_exiting(cpu_state);

    }

}

static void jpeg_prepare_row(VncState *vs, uint8_t *dst, int x, int y,

                                       int count)

{

    if (vs->tight_pixel24)

        jpeg_prepare_row24(vs, dst, x, y, count);

    else if (ds_get_bytes_per_pixel(vs->ds) == 4)

        jpeg_prepare_row32(vs, dst, x, y, count);

    else

        jpeg_prepare_row16(vs, dst, x, y, count);

}

void pc_basic_device_init(qemu_irq *isa_irq,

                          FDCtrl **floppy_controller,

                          ISADevice **rtc_state)

{

    int i;

    DriveInfo *fd[MAX_FD];

    PITState *pit;

    qemu_irq rtc_irq = NULL;

    qemu_irq *a20_line;

    ISADevice *i8042, *port92, *vmmouse;

    qemu_irq *cpu_exit_irq;



    register_ioport_write(0x80, 1, 1, ioport80_write, NULL);



    register_ioport_write(0xf0, 1, 1, ioportF0_write, NULL);



    if (!no_hpet) {

        DeviceState *hpet = sysbus_try_create_simple("hpet", HPET_BASE, NULL);



        if (hpet) {

            for (i = 0; i < 24; i++) {

                sysbus_connect_irq(sysbus_from_qdev(hpet), i, isa_irq[i]);

            }

            rtc_irq = qdev_get_gpio_in(hpet, 0);

        }

    }

    *rtc_state = rtc_init(2000, rtc_irq);



    qemu_register_boot_set(pc_boot_set, *rtc_state);



    pit = pit_init(0x40, isa_reserve_irq(0));

    pcspk_init(pit);



    for(i = 0; i < MAX_SERIAL_PORTS; i++) {

        if (serial_hds[i]) {

            serial_isa_init(i, serial_hds[i]);

        }

    }



    for(i = 0; i < MAX_PARALLEL_PORTS; i++) {

        if (parallel_hds[i]) {

            parallel_init(i, parallel_hds[i]);

        }

    }



    a20_line = qemu_allocate_irqs(handle_a20_line_change, first_cpu, 2);

    i8042 = isa_create_simple("i8042");

    i8042_setup_a20_line(i8042, &a20_line[0]);

    vmport_init();

    vmmouse = isa_try_create("vmmouse");

    if (vmmouse) {

        qdev_prop_set_ptr(&vmmouse->qdev, "ps2_mouse", i8042);

    }

    port92 = isa_create_simple("port92");

    port92_init(port92, &a20_line[1]);



    cpu_exit_irq = qemu_allocate_irqs(cpu_request_exit, NULL, 1);

    DMA_init(0, cpu_exit_irq);



    for(i = 0; i < MAX_FD; i++) {

        fd[i] = drive_get(IF_FLOPPY, 0, i);

    }

    *floppy_controller = fdctrl_init_isa(fd);

}

static void dump_json_image_check(ImageCheck *check, bool quiet)

{

    QString *str;

    QObject *obj;

    Visitor *v = qmp_output_visitor_new(&obj);



    visit_type_ImageCheck(v, NULL, &check, &error_abort);

    visit_complete(v, &obj);

    str = qobject_to_json_pretty(obj);

    assert(str != NULL);

    qprintf(quiet, "%s\n", qstring_get_str(str));

    qobject_decref(obj);

    visit_free(v);

    QDECREF(str);

}

