static coroutine_fn int qcow2_co_readv(BlockDriverState *bs, int64_t sector_num,

                          int remaining_sectors, QEMUIOVector *qiov)

{

    BDRVQcowState *s = bs->opaque;

    int index_in_cluster, n1;

    int ret;

    int cur_nr_sectors; /* number of sectors in current iteration */

    uint64_t cluster_offset = 0;

    uint64_t bytes_done = 0;

    QEMUIOVector hd_qiov;

    uint8_t *cluster_data = NULL;



    qemu_iovec_init(&hd_qiov, qiov->niov);



    qemu_co_mutex_lock(&s->lock);



    while (remaining_sectors != 0) {



        /* prepare next request */

        cur_nr_sectors = remaining_sectors;

        if (s->crypt_method) {

            cur_nr_sectors = MIN(cur_nr_sectors,

                QCOW_MAX_CRYPT_CLUSTERS * s->cluster_sectors);

        }



        ret = qcow2_get_cluster_offset(bs, sector_num << 9,

            &cur_nr_sectors, &cluster_offset);

        if (ret < 0) {

            goto fail;

        }



        index_in_cluster = sector_num & (s->cluster_sectors - 1);



        qemu_iovec_reset(&hd_qiov);

        qemu_iovec_concat(&hd_qiov, qiov, bytes_done,

            cur_nr_sectors * 512);



        switch (ret) {

        case QCOW2_CLUSTER_UNALLOCATED:



            if (bs->backing_hd) {

                /* read from the base image */

                n1 = qcow2_backing_read1(bs->backing_hd, &hd_qiov,

                    sector_num, cur_nr_sectors);

                if (n1 > 0) {

                    BLKDBG_EVENT(bs->file, BLKDBG_READ_BACKING_AIO);

                    qemu_co_mutex_unlock(&s->lock);

                    ret = bdrv_co_readv(bs->backing_hd, sector_num,

                                        n1, &hd_qiov);

                    qemu_co_mutex_lock(&s->lock);

                    if (ret < 0) {

                        goto fail;

                    }

                }

            } else {

                /* Note: in this case, no need to wait */

                qemu_iovec_memset(&hd_qiov, 0, 0, 512 * cur_nr_sectors);

            }

            break;



        case QCOW2_CLUSTER_ZERO:

            if (s->qcow_version < 3) {

                ret = -EIO;

                goto fail;

            }

            qemu_iovec_memset(&hd_qiov, 0, 0, 512 * cur_nr_sectors);

            break;



        case QCOW2_CLUSTER_COMPRESSED:

            /* add AIO support for compressed blocks ? */

            ret = qcow2_decompress_cluster(bs, cluster_offset);

            if (ret < 0) {

                goto fail;

            }



            qemu_iovec_from_buf(&hd_qiov, 0,

                s->cluster_cache + index_in_cluster * 512,

                512 * cur_nr_sectors);

            break;



        case QCOW2_CLUSTER_NORMAL:

            if ((cluster_offset & 511) != 0) {

                ret = -EIO;

                goto fail;

            }



            if (s->crypt_method) {

                /*

                 * For encrypted images, read everything into a temporary

                 * contiguous buffer on which the AES functions can work.

                 */

                if (!cluster_data) {

                    cluster_data =

                        qemu_blockalign(bs, QCOW_MAX_CRYPT_CLUSTERS * s->cluster_size);

                }



                assert(cur_nr_sectors <=

                    QCOW_MAX_CRYPT_CLUSTERS * s->cluster_sectors);

                qemu_iovec_reset(&hd_qiov);

                qemu_iovec_add(&hd_qiov, cluster_data,

                    512 * cur_nr_sectors);

            }



            BLKDBG_EVENT(bs->file, BLKDBG_READ_AIO);

            qemu_co_mutex_unlock(&s->lock);

            ret = bdrv_co_readv(bs->file,

                                (cluster_offset >> 9) + index_in_cluster,

                                cur_nr_sectors, &hd_qiov);

            qemu_co_mutex_lock(&s->lock);

            if (ret < 0) {

                goto fail;

            }

            if (s->crypt_method) {

                qcow2_encrypt_sectors(s, sector_num,  cluster_data,

                    cluster_data, cur_nr_sectors, 0, &s->aes_decrypt_key);

                qemu_iovec_from_buf(qiov, bytes_done,

                    cluster_data, 512 * cur_nr_sectors);

            }

            break;



        default:

            g_assert_not_reached();

            ret = -EIO;

            goto fail;

        }



        remaining_sectors -= cur_nr_sectors;

        sector_num += cur_nr_sectors;

        bytes_done += cur_nr_sectors * 512;

    }

    ret = 0;



fail:

    qemu_co_mutex_unlock(&s->lock);



    qemu_iovec_destroy(&hd_qiov);

    qemu_vfree(cluster_data);



    return ret;

}

static int sh_pci_init_device(SysBusDevice *dev)

{

    SHPCIState *s;

    int i;



    s = FROM_SYSBUS(SHPCIState, dev);

    for (i = 0; i < 4; i++) {

        sysbus_init_irq(dev, &s->irq[i]);

    }

    s->bus = pci_register_bus(&s->busdev.qdev, "pci",

                              sh_pci_set_irq, sh_pci_map_irq,

                              s->irq,

                              get_system_memory(),

                              get_system_io(),

                              PCI_DEVFN(0, 0), 4);

    memory_region_init_io(&s->memconfig_p4, &sh_pci_reg_ops, s,

                          "sh_pci", 0x224);

    memory_region_init_alias(&s->memconfig_a7, "sh_pci.2", &s->memconfig_a7,

                             0, 0x224);

    isa_mmio_setup(&s->isa, 0x40000);

    sysbus_init_mmio_cb2(dev, sh_pci_map, sh_pci_unmap);

    sysbus_init_mmio_region(dev, &s->memconfig_a7);

    sysbus_init_mmio_region(dev, &s->isa);

    s->dev = pci_create_simple(s->bus, PCI_DEVFN(0, 0), "sh_pci_host");

    return 0;

}

static uint64_t pxa2xx_lcdc_read(void *opaque, hwaddr offset,

                                 unsigned size)

{

    PXA2xxLCDState *s = (PXA2xxLCDState *) opaque;

    int ch;



    switch (offset) {

    case LCCR0:

        return s->control[0];

    case LCCR1:

        return s->control[1];

    case LCCR2:

        return s->control[2];

    case LCCR3:

        return s->control[3];

    case LCCR4:

        return s->control[4];

    case LCCR5:

        return s->control[5];



    case OVL1C1:

        return s->ovl1c[0];

    case OVL1C2:

        return s->ovl1c[1];

    case OVL2C1:

        return s->ovl2c[0];

    case OVL2C2:

        return s->ovl2c[1];



    case CCR:

        return s->ccr;



    case CMDCR:

        return s->cmdcr;



    case TRGBR:

        return s->trgbr;

    case TCR:

        return s->tcr;



    case 0x200 ... 0x1000:	/* DMA per-channel registers */

        ch = (offset - 0x200) >> 4;

        if (!(ch >= 0 && ch < PXA_LCDDMA_CHANS))

            goto fail;



        switch (offset & 0xf) {

        case DMA_FDADR:

            return s->dma_ch[ch].descriptor;

        case DMA_FSADR:

            return s->dma_ch[ch].source;

        case DMA_FIDR:

            return s->dma_ch[ch].id;

        case DMA_LDCMD:

            return s->dma_ch[ch].command;

        default:

            goto fail;

        }



    case FBR0:

        return s->dma_ch[0].branch;

    case FBR1:

        return s->dma_ch[1].branch;

    case FBR2:

        return s->dma_ch[2].branch;

    case FBR3:

        return s->dma_ch[3].branch;

    case FBR4:

        return s->dma_ch[4].branch;

    case FBR5:

        return s->dma_ch[5].branch;

    case FBR6:

        return s->dma_ch[6].branch;



    case BSCNTR:

        return s->bscntr;



    case PRSR:

        return 0;



    case LCSR0:

        return s->status[0];

    case LCSR1:

        return s->status[1];

    case LIIDR:

        return s->liidr;



    default:

    fail:

        hw_error("%s: Bad offset " REG_FMT "\n", __FUNCTION__, offset);

    }



    return 0;

}

int main_loop(void)

{

#ifndef _WIN32

    struct pollfd ufds[MAX_IO_HANDLERS + 1], *pf;

    IOHandlerRecord *ioh, *ioh_next;

    uint8_t buf[4096];

    int n, max_size;

#endif

    int ret, timeout;

    CPUState *env = global_env;



    for(;;) {

        if (vm_running) {

            ret = cpu_exec(env);

            if (shutdown_requested) {

                ret = EXCP_INTERRUPT; 

                break;

            }

            if (reset_requested) {

                reset_requested = 0;

                qemu_system_reset();

                ret = EXCP_INTERRUPT; 

            }

            if (ret == EXCP_DEBUG) {

                vm_stop(EXCP_DEBUG);

            }

            /* if hlt instruction, we wait until the next IRQ */

            /* XXX: use timeout computed from timers */

            if (ret == EXCP_HLT) 

                timeout = 10;

            else

                timeout = 0;

        } else {

            timeout = 10;

        }



#ifdef _WIN32

        if (timeout > 0)

            Sleep(timeout);

#else



        /* poll any events */

        /* XXX: separate device handlers from system ones */

        pf = ufds;

        for(ioh = first_io_handler; ioh != NULL; ioh = ioh->next) {

            if (!ioh->fd_can_read) {

                max_size = 0;

                pf->fd = ioh->fd;

                pf->events = POLLIN;

                ioh->ufd = pf;

                pf++;

            } else {

                max_size = ioh->fd_can_read(ioh->opaque);

                if (max_size > 0) {

                    if (max_size > sizeof(buf))

                        max_size = sizeof(buf);

                    pf->fd = ioh->fd;

                    pf->events = POLLIN;

                    ioh->ufd = pf;

                    pf++;

                } else {

                    ioh->ufd = NULL;

                }

            }

            ioh->max_size = max_size;

        }



        ret = poll(ufds, pf - ufds, timeout);

        if (ret > 0) {

            /* XXX: better handling of removal */

            for(ioh = first_io_handler; ioh != NULL; ioh = ioh_next) {

                ioh_next = ioh->next;

                pf = ioh->ufd;

                if (pf) {

                    if (pf->revents & POLLIN) {

                        if (ioh->max_size == 0) {

                            /* just a read event */

                            ioh->fd_read(ioh->opaque, NULL, 0);

                        } else {

                            n = read(ioh->fd, buf, ioh->max_size);

                            if (n >= 0) {

                                ioh->fd_read(ioh->opaque, buf, n);

                            } else if (errno != EAGAIN) {

                                ioh->fd_read(ioh->opaque, NULL, -errno);

                            }

                        }

                    }

                }

            }

        }



#if defined(CONFIG_SLIRP)

        /* XXX: merge with poll() */

        if (slirp_inited) {

            fd_set rfds, wfds, xfds;

            int nfds;

            struct timeval tv;



            nfds = -1;

            FD_ZERO(&rfds);

            FD_ZERO(&wfds);

            FD_ZERO(&xfds);

            slirp_select_fill(&nfds, &rfds, &wfds, &xfds);

            tv.tv_sec = 0;

            tv.tv_usec = 0;

            ret = select(nfds + 1, &rfds, &wfds, &xfds, &tv);

            if (ret >= 0) {

                slirp_select_poll(&rfds, &wfds, &xfds);

            }

        }

#endif



#endif



        if (vm_running) {

            qemu_run_timers(&active_timers[QEMU_TIMER_VIRTUAL], 

                            qemu_get_clock(vm_clock));



            if (audio_enabled) {

                /* XXX: add explicit timer */

                SB16_run();

            }



            /* run dma transfers, if any */

            DMA_run();

        }



        /* real time timers */

        qemu_run_timers(&active_timers[QEMU_TIMER_REALTIME], 

                        qemu_get_clock(rt_clock));

    }

    cpu_disable_ticks();

    return ret;

}

static void intel_hda_corb_run(IntelHDAState *d)

{

    hwaddr addr;

    uint32_t rp, verb;



    if (d->ics & ICH6_IRS_BUSY) {

        dprint(d, 2, "%s: [icw] verb 0x%08x\n", __FUNCTION__, d->icw);

        intel_hda_send_command(d, d->icw);

        return;

    }



    for (;;) {

        if (!(d->corb_ctl & ICH6_CORBCTL_RUN)) {

            dprint(d, 2, "%s: !run\n", __FUNCTION__);

            return;

        }

        if ((d->corb_rp & 0xff) == d->corb_wp) {

            dprint(d, 2, "%s: corb ring empty\n", __FUNCTION__);

            return;

        }

        if (d->rirb_count == d->rirb_cnt) {

            dprint(d, 2, "%s: rirb count reached\n", __FUNCTION__);

            return;

        }



        rp = (d->corb_rp + 1) & 0xff;

        addr = intel_hda_addr(d->corb_lbase, d->corb_ubase);

        verb = ldl_le_pci_dma(&d->pci, addr + 4*rp);

        d->corb_rp = rp;



        dprint(d, 2, "%s: [rp 0x%x] verb 0x%08x\n", __FUNCTION__, rp, verb);

        intel_hda_send_command(d, verb);

    }

}

