void cris_mmu_flush_pid(CPUState *env, uint32_t pid)

{

	target_ulong vaddr;

	unsigned int idx;

	uint32_t lo, hi;

	uint32_t tlb_vpn;

	int tlb_pid, tlb_g, tlb_v, tlb_k;

	unsigned int set;

	unsigned int mmu;



	pid &= 0xff;

	for (mmu = 0; mmu < 2; mmu++) {

		for (set = 0; set < 4; set++)

		{

			for (idx = 0; idx < 16; idx++) {

				lo = env->tlbsets[mmu][set][idx].lo;

				hi = env->tlbsets[mmu][set][idx].hi;



				tlb_vpn = EXTRACT_FIELD(hi, 13, 31);

				tlb_pid = EXTRACT_FIELD(hi, 0, 7);

				tlb_g  = EXTRACT_FIELD(lo, 4, 4);

				tlb_v = EXTRACT_FIELD(lo, 3, 3);

				tlb_k = EXTRACT_FIELD(lo, 2, 2);



				/* Kernel protected areas need to be flushed

				   as well.  */

				if (tlb_v && !tlb_g && (tlb_pid == pid || tlb_k)) {

					vaddr = tlb_vpn << TARGET_PAGE_BITS;

					D(fprintf(logfile,

						  "flush pid=%x vaddr=%x\n", 

						  pid, vaddr));

					tlb_flush_page(env, vaddr);

				}

			}

		}

	}

}

static void vfio_intp_interrupt(VFIOINTp *intp)

{

    int ret;

    VFIOINTp *tmp;

    VFIOPlatformDevice *vdev = intp->vdev;

    bool delay_handling = false;



    qemu_mutex_lock(&vdev->intp_mutex);

    if (intp->state == VFIO_IRQ_INACTIVE) {

        QLIST_FOREACH(tmp, &vdev->intp_list, next) {

            if (tmp->state == VFIO_IRQ_ACTIVE ||

                tmp->state == VFIO_IRQ_PENDING) {

                delay_handling = true;

                break;

            }

        }

    }

    if (delay_handling) {

        /*

         * the new IRQ gets a pending status and is pushed in

         * the pending queue

         */

        intp->state = VFIO_IRQ_PENDING;

        trace_vfio_intp_interrupt_set_pending(intp->pin);

        QSIMPLEQ_INSERT_TAIL(&vdev->pending_intp_queue,

                             intp, pqnext);

        ret = event_notifier_test_and_clear(&intp->interrupt);

        qemu_mutex_unlock(&vdev->intp_mutex);

        return;

    }



    trace_vfio_platform_intp_interrupt(intp->pin,

                              event_notifier_get_fd(&intp->interrupt));



    ret = event_notifier_test_and_clear(&intp->interrupt);

    if (!ret) {

        error_report("Error when clearing fd=%d (ret = %d)",

                     event_notifier_get_fd(&intp->interrupt), ret);

    }



    intp->state = VFIO_IRQ_ACTIVE;



    /* sets slow path */

    vfio_mmap_set_enabled(vdev, false);



    /* trigger the virtual IRQ */

    qemu_set_irq(intp->qemuirq, 1);



    /*

     * Schedule the mmap timer which will restore fastpath when no IRQ

     * is active anymore

     */

    if (vdev->mmap_timeout) {

        timer_mod(vdev->mmap_timer,

                  qemu_clock_get_ms(QEMU_CLOCK_VIRTUAL) +

                      vdev->mmap_timeout);

    }

    qemu_mutex_unlock(&vdev->intp_mutex);

}

void tb_invalidate_phys_addr(hwaddr addr)

{

    ram_addr_t ram_addr;

    MemoryRegionSection *section;



    section = phys_page_find(address_space_memory.dispatch,

                             addr >> TARGET_PAGE_BITS);

    if (!(memory_region_is_ram(section->mr)

          || memory_region_is_romd(section->mr))) {

        return;

    }

    ram_addr = (memory_region_get_ram_addr(section->mr) & TARGET_PAGE_MASK)

        + memory_region_section_addr(section, addr);

    tb_invalidate_phys_page_range(ram_addr, ram_addr + 1, 0);

}

