static void s390_init(QEMUMachineInitArgs *args)

{

    ram_addr_t my_ram_size = args->ram_size;

    const char *cpu_model = args->cpu_model;

    const char *kernel_filename = args->kernel_filename;

    const char *kernel_cmdline = args->kernel_cmdline;

    const char *initrd_filename = args->initrd_filename;

    CPUS390XState *env = NULL;

    MemoryRegion *sysmem = get_system_memory();

    MemoryRegion *ram = g_new(MemoryRegion, 1);

    ram_addr_t kernel_size = 0;

    ram_addr_t initrd_offset;

    ram_addr_t initrd_size = 0;

    int shift = 0;

    uint8_t *storage_keys;

    void *virtio_region;

    hwaddr virtio_region_len;

    hwaddr virtio_region_start;

    int i;



    /* s390x ram size detection needs a 16bit multiplier + an increment. So

       guests > 64GB can be specified in 2MB steps etc. */

    while ((my_ram_size >> (20 + shift)) > 65535) {

        shift++;

    }

    my_ram_size = my_ram_size >> (20 + shift) << (20 + shift);



    /* lets propagate the changed ram size into the global variable. */

    ram_size = my_ram_size;



    /* get a BUS */

    s390_bus = s390_virtio_bus_init(&my_ram_size);

    s390_sclp_init();



    /* allocate RAM */

    memory_region_init_ram(ram, "s390.ram", my_ram_size);

    vmstate_register_ram_global(ram);

    memory_region_add_subregion(sysmem, 0, ram);



    /* clear virtio region */

    virtio_region_len = my_ram_size - ram_size;

    virtio_region_start = ram_size;

    virtio_region = cpu_physical_memory_map(virtio_region_start,

                                            &virtio_region_len, true);

    memset(virtio_region, 0, virtio_region_len);

    cpu_physical_memory_unmap(virtio_region, virtio_region_len, 1,

                              virtio_region_len);



    /* allocate storage keys */

    storage_keys = g_malloc0(my_ram_size / TARGET_PAGE_SIZE);



    /* init CPUs */

    if (cpu_model == NULL) {

        cpu_model = "host";

    }



    ipi_states = g_malloc(sizeof(S390CPU *) * smp_cpus);



    for (i = 0; i < smp_cpus; i++) {

        S390CPU *cpu;

        CPUS390XState *tmp_env;



        cpu = cpu_s390x_init(cpu_model);

        tmp_env = &cpu->env;

        if (!env) {

            env = tmp_env;

        }

        ipi_states[i] = cpu;

        tmp_env->halted = 1;

        tmp_env->exception_index = EXCP_HLT;

        tmp_env->storage_keys = storage_keys;

    }



    /* One CPU has to run */

    s390_add_running_cpu(env);



    if (kernel_filename) {



        kernel_size = load_elf(kernel_filename, NULL, NULL, NULL, NULL,

                               NULL, 1, ELF_MACHINE, 0);

        if (kernel_size == -1UL) {

            kernel_size = load_image_targphys(kernel_filename, 0, ram_size);

        }

        if (kernel_size == -1UL) {

            fprintf(stderr, "qemu: could not load kernel '%s'\n",

                    kernel_filename);

            exit(1);

        }

        /*

         * we can not rely on the ELF entry point, since up to 3.2 this

         * value was 0x800 (the SALIPL loader) and it wont work. For

         * all (Linux) cases 0x10000 (KERN_IMAGE_START) should be fine.

         */

        env->psw.addr = KERN_IMAGE_START;

        env->psw.mask = 0x0000000180000000ULL;

    } else {

        ram_addr_t bios_size = 0;

        char *bios_filename;



        /* Load zipl bootloader */

        if (bios_name == NULL) {

            bios_name = ZIPL_FILENAME;

        }



        bios_filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);

        bios_size = load_image_targphys(bios_filename, ZIPL_LOAD_ADDR, 4096);

        g_free(bios_filename);



        if ((long)bios_size < 0) {

            hw_error("could not load bootloader '%s'\n", bios_name);

        }



        if (bios_size > 4096) {

            hw_error("stage1 bootloader is > 4k\n");

        }



        env->psw.addr = ZIPL_START;

        env->psw.mask = 0x0000000180000000ULL;

    }



    if (initrd_filename) {

        initrd_offset = INITRD_START;

        while (kernel_size + 0x100000 > initrd_offset) {

            initrd_offset += 0x100000;

        }

        initrd_size = load_image_targphys(initrd_filename, initrd_offset,

                                          ram_size - initrd_offset);

        if (initrd_size == -1UL) {

            fprintf(stderr, "qemu: could not load initrd '%s'\n",

                    initrd_filename);

            exit(1);

        }



        /* we have to overwrite values in the kernel image, which are "rom" */

        stq_p(rom_ptr(INITRD_PARM_START), initrd_offset);

        stq_p(rom_ptr(INITRD_PARM_SIZE), initrd_size);

    }



    if (rom_ptr(KERN_PARM_AREA)) {

        /* we have to overwrite values in the kernel image, which are "rom" */

        memcpy(rom_ptr(KERN_PARM_AREA), kernel_cmdline,

               strlen(kernel_cmdline) + 1);

    }



    /* Create VirtIO network adapters */

    for(i = 0; i < nb_nics; i++) {

        NICInfo *nd = &nd_table[i];

        DeviceState *dev;



        if (!nd->model) {

            nd->model = g_strdup("virtio");

        }



        if (strcmp(nd->model, "virtio")) {

            fprintf(stderr, "S390 only supports VirtIO nics\n");

            exit(1);

        }



        dev = qdev_create((BusState *)s390_bus, "virtio-net-s390");

        qdev_set_nic_properties(dev, nd);

        qdev_init_nofail(dev);

    }



    /* Create VirtIO disk drives */

    for(i = 0; i < MAX_BLK_DEVS; i++) {

        DriveInfo *dinfo;

        DeviceState *dev;



        dinfo = drive_get(IF_IDE, 0, i);

        if (!dinfo) {

            continue;

        }



        dev = qdev_create((BusState *)s390_bus, "virtio-blk-s390");

        qdev_prop_set_drive_nofail(dev, "drive", dinfo->bdrv);

        qdev_init_nofail(dev);

    }

}

void sparc64_set_context(CPUSPARCState *env)

{

    abi_ulong ucp_addr;

    struct target_ucontext *ucp;

    target_mc_gregset_t *grp;

    abi_ulong pc, npc, tstate;

    abi_ulong fp, i7, w_addr;

    int err;

    unsigned int i;



    ucp_addr = env->regwptr[UREG_I0];

    if (!lock_user_struct(VERIFY_READ, ucp, ucp_addr, 1))

        goto do_sigsegv;

    grp  = &ucp->tuc_mcontext.mc_gregs;

    err  = __get_user(pc, &((*grp)[MC_PC]));

    err |= __get_user(npc, &((*grp)[MC_NPC]));

    if (err || ((pc | npc) & 3))

        goto do_sigsegv;

    if (env->regwptr[UREG_I1]) {

        target_sigset_t target_set;

        sigset_t set;



        if (TARGET_NSIG_WORDS == 1) {

            if (__get_user(target_set.sig[0], &ucp->tuc_sigmask.sig[0]))

                goto do_sigsegv;

        } else {

            abi_ulong *src, *dst;

            src = ucp->tuc_sigmask.sig;

            dst = target_set.sig;

            for (i = 0; i < TARGET_NSIG_WORDS; i++, dst++, src++) {

                err |= __get_user(*dst, src);

            }

            if (err)

                goto do_sigsegv;

        }

        target_to_host_sigset_internal(&set, &target_set);

        sigprocmask(SIG_SETMASK, &set, NULL);

    }

    env->pc = pc;

    env->npc = npc;

    err |= __get_user(env->y, &((*grp)[MC_Y]));

    err |= __get_user(tstate, &((*grp)[MC_TSTATE]));

    env->asi = (tstate >> 24) & 0xff;

    cpu_put_ccr(env, tstate >> 32);

    cpu_put_cwp64(env, tstate & 0x1f);

    err |= __get_user(env->gregs[1], (&(*grp)[MC_G1]));

    err |= __get_user(env->gregs[2], (&(*grp)[MC_G2]));

    err |= __get_user(env->gregs[3], (&(*grp)[MC_G3]));

    err |= __get_user(env->gregs[4], (&(*grp)[MC_G4]));

    err |= __get_user(env->gregs[5], (&(*grp)[MC_G5]));

    err |= __get_user(env->gregs[6], (&(*grp)[MC_G6]));

    err |= __get_user(env->gregs[7], (&(*grp)[MC_G7]));

    err |= __get_user(env->regwptr[UREG_I0], (&(*grp)[MC_O0]));

    err |= __get_user(env->regwptr[UREG_I1], (&(*grp)[MC_O1]));

    err |= __get_user(env->regwptr[UREG_I2], (&(*grp)[MC_O2]));

    err |= __get_user(env->regwptr[UREG_I3], (&(*grp)[MC_O3]));

    err |= __get_user(env->regwptr[UREG_I4], (&(*grp)[MC_O4]));

    err |= __get_user(env->regwptr[UREG_I5], (&(*grp)[MC_O5]));

    err |= __get_user(env->regwptr[UREG_I6], (&(*grp)[MC_O6]));

    err |= __get_user(env->regwptr[UREG_I7], (&(*grp)[MC_O7]));



    err |= __get_user(fp, &(ucp->tuc_mcontext.mc_fp));

    err |= __get_user(i7, &(ucp->tuc_mcontext.mc_i7));



    w_addr = TARGET_STACK_BIAS+env->regwptr[UREG_I6];

    if (put_user(fp, w_addr + offsetof(struct target_reg_window, ins[6]), 

                 abi_ulong) != 0)

        goto do_sigsegv;

    if (put_user(i7, w_addr + offsetof(struct target_reg_window, ins[7]), 

                 abi_ulong) != 0)

        goto do_sigsegv;

    /* FIXME this does not match how the kernel handles the FPU in

     * its sparc64_set_context implementation. In particular the FPU

     * is only restored if fenab is non-zero in:

     *   __get_user(fenab, &(ucp->tuc_mcontext.mc_fpregs.mcfpu_enab));

     */

    err |= __get_user(env->fprs, &(ucp->tuc_mcontext.mc_fpregs.mcfpu_fprs));

    {

        uint32_t *src = ucp->tuc_mcontext.mc_fpregs.mcfpu_fregs.sregs;

        for (i = 0; i < 64; i++, src++) {

            if (i & 1) {

                err |= __get_user(env->fpr[i/2].l.lower, src);

            } else {

                err |= __get_user(env->fpr[i/2].l.upper, src);

            }

        }

    }

    err |= __get_user(env->fsr,

                      &(ucp->tuc_mcontext.mc_fpregs.mcfpu_fsr));

    err |= __get_user(env->gsr,

                      &(ucp->tuc_mcontext.mc_fpregs.mcfpu_gsr));

    if (err)

        goto do_sigsegv;

    unlock_user_struct(ucp, ucp_addr, 0);

    return;

 do_sigsegv:

    unlock_user_struct(ucp, ucp_addr, 0);

    force_sig(TARGET_SIGSEGV);

}

uint32_t cpu_mips_get_count (CPUState *env)

{

    if (env->CP0_Cause & (1 << CP0Ca_DC)) {

        return env->CP0_Count;

    } else {

        return env->CP0_Count +

            (uint32_t)muldiv64(qemu_get_clock(vm_clock),

                               TIMER_FREQ, get_ticks_per_sec());

    }

}

static int cpu_has_work(CPUState *env)

{

    if (env->stop)

