static abi_ulong load_elf_interp(struct elfhdr * interp_elf_ex,

                                 int interpreter_fd,

                                 abi_ulong *interp_load_addr,

                                 char bprm_buf[BPRM_BUF_SIZE])

{

    struct elf_phdr *elf_phdata  =  NULL;

    abi_ulong load_addr, load_bias, loaddr, hiaddr;

    int retval;

    abi_ulong error;

    int i;



    bswap_ehdr(interp_elf_ex);

    /* First of all, some simple consistency checks */

    if ((interp_elf_ex->e_type != ET_EXEC &&

         interp_elf_ex->e_type != ET_DYN) ||

        !elf_check_arch(interp_elf_ex->e_machine)) {

        return ~((abi_ulong)0UL);

    }



    /* Now read in all of the header information */



    if (sizeof(struct elf_phdr) * interp_elf_ex->e_phnum > TARGET_PAGE_SIZE)

        return ~(abi_ulong)0UL;



    elf_phdata =  (struct elf_phdr *)

        malloc(sizeof(struct elf_phdr) * interp_elf_ex->e_phnum);



    if (!elf_phdata)

        return ~((abi_ulong)0UL);



    /*

     * If the size of this structure has changed, then punt, since

     * we will be doing the wrong thing.

     */

    if (interp_elf_ex->e_phentsize != sizeof(struct elf_phdr)) {

        free(elf_phdata);

        return ~((abi_ulong)0UL);

    }



    i = interp_elf_ex->e_phnum * sizeof(struct elf_phdr);

    if (interp_elf_ex->e_phoff + i <= BPRM_BUF_SIZE) {

        memcpy(elf_phdata, bprm_buf + interp_elf_ex->e_phoff, i);

    } else {

        retval = pread(interpreter_fd, elf_phdata, i, interp_elf_ex->e_phoff);

        if (retval != i) {

            perror("load_elf_interp");

            exit(-1);

        }

    }

    bswap_phdr(elf_phdata, interp_elf_ex->e_phnum);



    /* Find the maximum size of the image and allocate an appropriate

       amount of memory to handle that.  */

    loaddr = -1, hiaddr = 0;

    for (i = 0; i < interp_elf_ex->e_phnum; ++i) {

        if (elf_phdata[i].p_type == PT_LOAD) {

            abi_ulong a = elf_phdata[i].p_vaddr;

            if (a < loaddr) {

                loaddr = a;

            }

            a += elf_phdata[i].p_memsz;

            if (a > hiaddr) {

                hiaddr = a;

            }

        }

    }



    load_addr = loaddr;

    if (interp_elf_ex->e_type == ET_DYN) {

        /* The image indicates that it can be loaded anywhere.  Find a

           location that can hold the memory space required.  If the

           image is pre-linked, LOADDR will be non-zero.  Since we do

           not supply MAP_FIXED here we'll use that address if and

           only if it remains available.  */

        load_addr = target_mmap(loaddr, hiaddr - loaddr, PROT_NONE,

                                MAP_PRIVATE | MAP_ANON | MAP_NORESERVE,

                                -1, 0);

        if (load_addr == -1) {

            perror("mmap");

            exit(-1);

        }

    }

    load_bias = load_addr - loaddr;



    for (i = 0; i < interp_elf_ex->e_phnum; i++) {

        struct elf_phdr *eppnt = elf_phdata + i;

        if (eppnt->p_type == PT_LOAD) {

            abi_ulong vaddr, vaddr_po, vaddr_ps, vaddr_ef, vaddr_em;

            int elf_prot = 0;



            if (eppnt->p_flags & PF_R) elf_prot =  PROT_READ;

            if (eppnt->p_flags & PF_W) elf_prot |= PROT_WRITE;

            if (eppnt->p_flags & PF_X) elf_prot |= PROT_EXEC;



            vaddr = load_bias + eppnt->p_vaddr;

            vaddr_po = TARGET_ELF_PAGEOFFSET(vaddr);

            vaddr_ps = TARGET_ELF_PAGESTART(vaddr);



            error = target_mmap(vaddr_ps, eppnt->p_filesz + vaddr_po,

                                elf_prot, MAP_PRIVATE | MAP_FIXED,

                                interpreter_fd, eppnt->p_offset - vaddr_po);

            if (error == -1) {

                /* Real error */

                close(interpreter_fd);

                free(elf_phdata);

                return ~((abi_ulong)0UL);

            }



            vaddr_ef = vaddr + eppnt->p_filesz;

            vaddr_em = vaddr + eppnt->p_memsz;



            /* If the load segment requests extra zeros (e.g. bss), map it.  */

            if (vaddr_ef < vaddr_em) {

                zero_bss(vaddr_ef, vaddr_em, elf_prot);

            }

        }

    }



    if (qemu_log_enabled()) {

        load_symbols(interp_elf_ex, interpreter_fd, load_bias);

    }



    close(interpreter_fd);

    free(elf_phdata);



    *interp_load_addr = load_addr;

    return ((abi_ulong) interp_elf_ex->e_entry) + load_bias;

}

static int execute_command(BlockDriverState *bdrv,

                           SCSIGenericReq *r, int direction,

                           BlockCompletionFunc *complete)

{

    r->io_header.interface_id = 'S';

    r->io_header.dxfer_direction = direction;

    r->io_header.dxferp = r->buf;

    r->io_header.dxfer_len = r->buflen;

    r->io_header.cmdp = r->req.cmd.buf;

    r->io_header.cmd_len = r->req.cmd.len;

    r->io_header.mx_sb_len = sizeof(r->req.sense);

    r->io_header.sbp = r->req.sense;

    r->io_header.timeout = MAX_UINT;

    r->io_header.usr_ptr = r;

    r->io_header.flags |= SG_FLAG_DIRECT_IO;



    r->req.aiocb = bdrv_aio_ioctl(bdrv, SG_IO, &r->io_header, complete, r);

    if (r->req.aiocb == NULL) {

        return -EIO;

    }



    return 0;

}

void stq_phys_notdirty(target_phys_addr_t addr, uint64_t val)

{

    uint8_t *ptr;

    MemoryRegionSection *section;



    section = phys_page_find(addr >> TARGET_PAGE_BITS);



    if (!memory_region_is_ram(section->mr) || section->readonly) {

        addr = memory_region_section_addr(section, addr);

        if (memory_region_is_ram(section->mr)) {

            section = &phys_sections[phys_section_rom];

        }

#ifdef TARGET_WORDS_BIGENDIAN

        io_mem_write(section->mr, addr, val >> 32, 4);

        io_mem_write(section->mr, addr + 4, (uint32_t)val, 4);

#else

        io_mem_write(section->mr, addr, (uint32_t)val, 4);

        io_mem_write(section->mr, addr + 4, val >> 32, 4);

#endif

    } else {

        ptr = qemu_get_ram_ptr((memory_region_get_ram_addr(section->mr)

                                & TARGET_PAGE_MASK)

                               + memory_region_section_addr(section, addr));

        stq_p(ptr, val);

    }

}

static void kvm_apic_mem_write(void *opaque, target_phys_addr_t addr,

                               uint64_t data, unsigned size)

{

    MSIMessage msg = { .address = addr, .data = data };

    int ret;



    ret = kvm_irqchip_send_msi(kvm_state, msg);

    if (ret < 0) {

        fprintf(stderr, "KVM: injection failed, MSI lost (%s)\n",

                strerror(-ret));

    }

}

void os_daemonize(void)

{

    if (daemonize) {

        pid_t pid;

        int fds[2];



        if (pipe(fds) == -1) {

            exit(1);

        }



        pid = fork();

        if (pid > 0) {

            uint8_t status;

            ssize_t len;



            close(fds[1]);



        again:

            len = read(fds[0], &status, 1);

            if (len == -1 && (errno == EINTR)) {

                goto again;

            }

            if (len != 1) {

                exit(1);

            }

            else if (status == 1) {

                fprintf(stderr, "Could not acquire pidfile\n");

                exit(1);

            } else {

                exit(0);

            }

            } else if (pid < 0) {

                exit(1);

            }



        close(fds[0]);

        daemon_pipe = fds[1];

        qemu_set_cloexec(daemon_pipe);



        setsid();



        pid = fork();

        if (pid > 0) {

            exit(0);

        } else if (pid < 0) {

            exit(1);

        }

        umask(027);



        signal(SIGTSTP, SIG_IGN);

        signal(SIGTTOU, SIG_IGN);

        signal(SIGTTIN, SIG_IGN);

    }

}

int cpu_signal_handler(int host_signum, void *pinfo,

                           void *puc)

{

    siginfo_t *info = pinfo;

    ucontext_t *uc = puc;

    uint32_t *pc = uc->uc_mcontext.sc_pc;

    uint32_t insn = *pc;

    int is_write = 0;



    /* XXX: need kernel patch to get write flag faster */

    switch (insn >> 26) {

    case 0x0d: /* stw */

    case 0x0e: /* stb */

    case 0x0f: /* stq_u */

    case 0x24: /* stf */

    case 0x25: /* stg */

    case 0x26: /* sts */

    case 0x27: /* stt */

    case 0x2c: /* stl */

    case 0x2d: /* stq */

    case 0x2e: /* stl_c */

    case 0x2f: /* stq_c */

        is_write = 1;

    }



    return handle_cpu_signal(pc, (unsigned long)info->si_addr,

                             is_write, &uc->uc_sigmask);

}

static uint32_t bitband_readw(void *opaque, target_phys_addr_t offset)

{

    uint32_t addr;

    uint16_t mask;

    uint16_t v;

    addr = bitband_addr(opaque, offset) & ~1;

    mask = (1 << ((offset >> 2) & 15));

    mask = tswap16(mask);

    cpu_physical_memory_read(addr, (uint8_t *)&v, 2);

    return (v & mask) != 0;

}

static void sd_set_ocr(SDState *sd)

{

    /* All voltages OK, card power-up OK, Standard Capacity SD Memory Card */

    sd->ocr = 0x80ffff00;

}

static uint32_t pxa2xx_rtc_read(void *opaque, target_phys_addr_t addr)

{

    PXA2xxRTCState *s = (PXA2xxRTCState *) opaque;



    switch (addr) {

    case RTTR:

        return s->rttr;

    case RTSR:

        return s->rtsr;

    case RTAR:

        return s->rtar;

    case RDAR1:

        return s->rdar1;

    case RDAR2:

        return s->rdar2;

    case RYAR1:

        return s->ryar1;

    case RYAR2:

        return s->ryar2;

    case SWAR1:

        return s->swar1;

    case SWAR2:

        return s->swar2;

    case PIAR:

        return s->piar;

    case RCNR:

        return s->last_rcnr + ((qemu_get_clock(rt_clock) - s->last_hz) << 15) /

                (1000 * ((s->rttr & 0xffff) + 1));

    case RDCR:

        return s->last_rdcr + ((qemu_get_clock(rt_clock) - s->last_hz) << 15) /

                (1000 * ((s->rttr & 0xffff) + 1));

    case RYCR:

        return s->last_rycr;

    case SWCR:

        if (s->rtsr & (1 << 12))

            return s->last_swcr + (qemu_get_clock(rt_clock) - s->last_sw) / 10;

        else

            return s->last_swcr;

    default:

        printf("%s: Bad register " REG_FMT "\n", __FUNCTION__, addr);

        break;

    }

    return 0;

}

static int check_protocol_support(bool *has_ipv4, bool *has_ipv6)

{

#ifdef HAVE_IFADDRS_H

    struct ifaddrs *ifaddr = NULL, *ifa;

    struct addrinfo hints = { 0 };

    struct addrinfo *ai = NULL;

    int gaierr;



    *has_ipv4 = *has_ipv6 = false;



    if (getifaddrs(&ifaddr) < 0) {

        g_printerr("Failed to lookup interface addresses: %s\n",

                   strerror(errno));

        return -1;

    }



    for (ifa = ifaddr; ifa != NULL; ifa = ifa->ifa_next) {

        if (!ifa->ifa_addr) {

            continue;

        }



        if (ifa->ifa_addr->sa_family == AF_INET) {

            *has_ipv4 = true;

        }

        if (ifa->ifa_addr->sa_family == AF_INET6) {

            *has_ipv6 = true;

        }

    }



    freeifaddrs(ifaddr);



    hints.ai_flags = AI_PASSIVE | AI_ADDRCONFIG;

    hints.ai_family = AF_INET6;

    hints.ai_socktype = SOCK_STREAM;



    gaierr = getaddrinfo("::1", NULL, &hints, &ai);

    if (gaierr != 0) {

        if (gaierr == EAI_ADDRFAMILY ||

            gaierr == EAI_FAMILY ||

            gaierr == EAI_NONAME) {

            *has_ipv6 = false;

        } else {

            g_printerr("Failed to resolve ::1 address: %s\n",

                       gai_strerror(gaierr));

            return -1;

        }

    }



    freeaddrinfo(ai);



    return 0;

#else

    *has_ipv4 = *has_ipv6 = false;



    return -1;

#endif

}

