static gnutls_certificate_credentials_t vnc_tls_initialize_x509_cred(VncState *vs)

{

    gnutls_certificate_credentials_t x509_cred;

    int ret;



    if (!vs->vd->x509cacert) {

	VNC_DEBUG("No CA x509 certificate specified\n");

	return NULL;

    }

    if (!vs->vd->x509cert) {

	VNC_DEBUG("No server x509 certificate specified\n");

	return NULL;

    }

    if (!vs->vd->x509key) {

	VNC_DEBUG("No server private key specified\n");

	return NULL;

    }



    if ((ret = gnutls_certificate_allocate_credentials(&x509_cred)) < 0) {

	VNC_DEBUG("Cannot allocate credentials %s\n", gnutls_strerror(ret));

	return NULL;

    }

    if ((ret = gnutls_certificate_set_x509_trust_file(x509_cred,

						      vs->vd->x509cacert,

						      GNUTLS_X509_FMT_PEM)) < 0) {

	VNC_DEBUG("Cannot load CA certificate %s\n", gnutls_strerror(ret));

	gnutls_certificate_free_credentials(x509_cred);

	return NULL;

    }



    if ((ret = gnutls_certificate_set_x509_key_file (x509_cred,

						     vs->vd->x509cert,

						     vs->vd->x509key,

						     GNUTLS_X509_FMT_PEM)) < 0) {

	VNC_DEBUG("Cannot load certificate & key %s\n", gnutls_strerror(ret));

	gnutls_certificate_free_credentials(x509_cred);

	return NULL;

    }



    if (vs->vd->x509cacrl) {

	if ((ret = gnutls_certificate_set_x509_crl_file(x509_cred,

							vs->vd->x509cacrl,

							GNUTLS_X509_FMT_PEM)) < 0) {

	    VNC_DEBUG("Cannot load CRL %s\n", gnutls_strerror(ret));

	    gnutls_certificate_free_credentials(x509_cred);

	    return NULL;

	}

    }



    gnutls_certificate_set_dh_params (x509_cred, dh_params);



    return x509_cred;

}

CPUState *ppc440ep_init(ram_addr_t *ram_size, PCIBus **pcip,

                        const unsigned int pci_irq_nrs[4], int do_init,

                        const char *cpu_model)

{

    target_phys_addr_t ram_bases[PPC440EP_SDRAM_NR_BANKS];

    target_phys_addr_t ram_sizes[PPC440EP_SDRAM_NR_BANKS];

    CPUState *env;

    qemu_irq *pic;

    qemu_irq *irqs;

    qemu_irq *pci_irqs;



    if (cpu_model == NULL) {

        cpu_model = "440-Xilinx"; // XXX: should be 440EP

    }

    env = cpu_init(cpu_model);

    if (!env) {

        fprintf(stderr, "Unable to initialize CPU!\n");

        exit(1);

    }



    ppc_dcr_init(env, NULL, NULL);



    /* interrupt controller */

    irqs = g_malloc0(sizeof(qemu_irq) * PPCUIC_OUTPUT_NB);

    irqs[PPCUIC_OUTPUT_INT] = ((qemu_irq *)env->irq_inputs)[PPC40x_INPUT_INT];

    irqs[PPCUIC_OUTPUT_CINT] = ((qemu_irq *)env->irq_inputs)[PPC40x_INPUT_CINT];

    pic = ppcuic_init(env, irqs, 0x0C0, 0, 1);



    /* SDRAM controller */

    memset(ram_bases, 0, sizeof(ram_bases));

    memset(ram_sizes, 0, sizeof(ram_sizes));

    *ram_size = ppc4xx_sdram_adjust(*ram_size, PPC440EP_SDRAM_NR_BANKS,

                                    ram_bases, ram_sizes,

                                    ppc440ep_sdram_bank_sizes);

    /* XXX 440EP's ECC interrupts are on UIC1, but we've only created UIC0. */

    ppc4xx_sdram_init(env, pic[14], PPC440EP_SDRAM_NR_BANKS, ram_bases,

                      ram_sizes, do_init);



    /* PCI */

    pci_irqs = g_malloc(sizeof(qemu_irq) * 4);

    pci_irqs[0] = pic[pci_irq_nrs[0]];

    pci_irqs[1] = pic[pci_irq_nrs[1]];

    pci_irqs[2] = pic[pci_irq_nrs[2]];

    pci_irqs[3] = pic[pci_irq_nrs[3]];

    *pcip = ppc4xx_pci_init(env, pci_irqs,

                            PPC440EP_PCI_CONFIG,

                            PPC440EP_PCI_INTACK,

                            PPC440EP_PCI_SPECIAL,

                            PPC440EP_PCI_REGS);

    if (!*pcip)

        printf("couldn't create PCI controller!\n");



    isa_mmio_init(PPC440EP_PCI_IO, PPC440EP_PCI_IOLEN);



    if (serial_hds[0] != NULL) {

        serial_mm_init(0xef600300, 0, pic[0], PPC_SERIAL_MM_BAUDBASE,

                       serial_hds[0], 1, 1);

    }

    if (serial_hds[1] != NULL) {

        serial_mm_init(0xef600400, 0, pic[1], PPC_SERIAL_MM_BAUDBASE,

                       serial_hds[1], 1, 1);

    }



    return env;

}

void *cpu_register_map_client(void *opaque, void (*callback)(void *opaque))

{

    MapClient *client = g_malloc(sizeof(*client));



    qemu_mutex_lock(&map_client_list_lock);

    client->opaque = opaque;

    client->callback = callback;

    QLIST_INSERT_HEAD(&map_client_list, client, link);

    if (!atomic_read(&bounce.in_use)) {

        cpu_notify_map_clients_locked();

    }

    qemu_mutex_unlock(&map_client_list_lock);

    return client;

}

static void test_flush(void)

{

    QPCIDevice *dev;

    QPCIBar bmdma_bar, ide_bar;

    uint8_t data;



    ide_test_start(

        "-drive file=blkdebug::%s,if=ide,cache=writeback,format=raw",

        tmp_path);



    dev = get_pci_device(&bmdma_bar, &ide_bar);



    qtest_irq_intercept_in(global_qtest, "ioapic");



    /* Dirty media so that CMD_FLUSH_CACHE will actually go to disk */

    make_dirty(0);



    /* Delay the completion of the flush request until we explicitly do it */

    g_free(hmp("qemu-io ide0-hd0 \"break flush_to_os A\""));



    /* FLUSH CACHE command on device 0*/

    qpci_io_writeb(dev, ide_bar, reg_device, 0);

    qpci_io_writeb(dev, ide_bar, reg_command, CMD_FLUSH_CACHE);



    /* Check status while request is in flight*/

    data = qpci_io_readb(dev, ide_bar, reg_status);

    assert_bit_set(data, BSY | DRDY);

    assert_bit_clear(data, DF | ERR | DRQ);



    /* Complete the command */

    g_free(hmp("qemu-io ide0-hd0 \"resume A\""));



    /* Check registers */

    data = qpci_io_readb(dev, ide_bar, reg_device);

    g_assert_cmpint(data & DEV, ==, 0);



    do {

        data = qpci_io_readb(dev, ide_bar, reg_status);

    } while (data & BSY);



    assert_bit_set(data, DRDY);

    assert_bit_clear(data, BSY | DF | ERR | DRQ);



    ide_test_quit();


}

static int protocol_client_auth_sasl_start(VncState *vs, uint8_t *data, size_t len)

{

    uint32_t datalen = len;

    const char *serverout;

    unsigned int serveroutlen;

    int err;

    char *clientdata = NULL;



    /* NB, distinction of NULL vs "" is *critical* in SASL */

    if (datalen) {

        clientdata = (char*)data;

        clientdata[datalen-1] = '\0'; /* Should be on wire, but make sure */

        datalen--; /* Don't count NULL byte when passing to _start() */

    }



    VNC_DEBUG("Start SASL auth with mechanism %s. Data %p (%d bytes)\n",

              vs->sasl.mechlist, clientdata, datalen);

    err = sasl_server_start(vs->sasl.conn,

                            vs->sasl.mechlist,

                            clientdata,

                            datalen,

                            &serverout,

                            &serveroutlen);

    if (err != SASL_OK &&

        err != SASL_CONTINUE) {

        VNC_DEBUG("sasl start failed %d (%s)\n",

                  err, sasl_errdetail(vs->sasl.conn));

        sasl_dispose(&vs->sasl.conn);

        vs->sasl.conn = NULL;

        goto authabort;

    }

    if (serveroutlen > SASL_DATA_MAX_LEN) {

        VNC_DEBUG("sasl start reply data too long %d\n",

                  serveroutlen);

        sasl_dispose(&vs->sasl.conn);

        vs->sasl.conn = NULL;

        goto authabort;

    }



    VNC_DEBUG("SASL return data %d bytes, nil; %d\n",

              serveroutlen, serverout ? 0 : 1);



    if (serveroutlen) {

        vnc_write_u32(vs, serveroutlen + 1);

        vnc_write(vs, serverout, serveroutlen + 1);

    } else {

        vnc_write_u32(vs, 0);

    }



    /* Whether auth is complete */

    vnc_write_u8(vs, err == SASL_CONTINUE ? 0 : 1);



    if (err == SASL_CONTINUE) {

        VNC_DEBUG("%s", "Authentication must continue\n");

        /* Wait for step length */

        vnc_read_when(vs, protocol_client_auth_sasl_step_len, 4);

    } else {

        if (!vnc_auth_sasl_check_ssf(vs)) {

            VNC_DEBUG("Authentication rejected for weak SSF %p\n", vs->ioc);

            goto authreject;

        }



        /* Check username whitelist ACL */

        if (vnc_auth_sasl_check_access(vs) < 0) {

            VNC_DEBUG("Authentication rejected for ACL %p\n", vs->ioc);

            goto authreject;

        }



        VNC_DEBUG("Authentication successful %p\n", vs->ioc);

        vnc_write_u32(vs, 0); /* Accept auth */

        start_client_init(vs);

    }



    return 0;



 authreject:

    vnc_write_u32(vs, 1); /* Reject auth */

    vnc_write_u32(vs, sizeof("Authentication failed"));

    vnc_write(vs, "Authentication failed", sizeof("Authentication failed"));

    vnc_flush(vs);

    vnc_client_error(vs);

    return -1;



 authabort:

    vnc_client_error(vs);

    return -1;

}

static void qtest_irq_handler(void *opaque, int n, int level)

{

    qemu_irq old_irq = *(qemu_irq *)opaque;

    qemu_set_irq(old_irq, level);



    if (irq_levels[n] != level) {

        CharDriverState *chr = qtest_chr;

        irq_levels[n] = level;

        qtest_send_prefix(chr);

        qtest_send(chr, "IRQ %s %d\n",

                   level ? "raise" : "lower", n);

    }

}

