BlockAIOCB *bdrv_aio_flush(BlockDriverState *bs,

        BlockCompletionFunc *cb, void *opaque)

{

    trace_bdrv_aio_flush(bs, opaque);



    Coroutine *co;

    BlockAIOCBCoroutine *acb;



    /* Matched by bdrv_co_complete's bdrv_dec_in_flight.  */

    bdrv_inc_in_flight(bs);



    acb = qemu_aio_get(&bdrv_em_co_aiocb_info, bs, cb, opaque);

    acb->need_bh = true;

    acb->req.error = -EINPROGRESS;



    co = qemu_coroutine_create(bdrv_aio_flush_co_entry, acb);

    qemu_coroutine_enter(co);



    bdrv_co_maybe_schedule_bh(acb);

    return &acb->common;

}

VirtIODevice *virtio_net_init(DeviceState *dev, NICConf *conf,

                              virtio_net_conf *net)

{

    VirtIONet *n;



    n = (VirtIONet *)virtio_common_init("virtio-net", VIRTIO_ID_NET,

                                        sizeof(struct virtio_net_config),

                                        sizeof(VirtIONet));



    n->vdev.get_config = virtio_net_get_config;

    n->vdev.set_config = virtio_net_set_config;

    n->vdev.get_features = virtio_net_get_features;

    n->vdev.set_features = virtio_net_set_features;

    n->vdev.bad_features = virtio_net_bad_features;

    n->vdev.reset = virtio_net_reset;

    n->vdev.set_status = virtio_net_set_status;

    n->rx_vq = virtio_add_queue(&n->vdev, 256, virtio_net_handle_rx);

    n->tx_vq = virtio_add_queue(&n->vdev, 256, virtio_net_handle_tx);

    n->ctrl_vq = virtio_add_queue(&n->vdev, 64, virtio_net_handle_ctrl);

    qemu_macaddr_default_if_unset(&conf->macaddr);

    memcpy(&n->mac[0], &conf->macaddr, sizeof(n->mac));

    n->status = VIRTIO_NET_S_LINK_UP;



    n->nic = qemu_new_nic(&net_virtio_info, conf, dev->info->name, dev->id, n);



    qemu_format_nic_info_str(&n->nic->nc, conf->macaddr.a);



    n->tx_timer = qemu_new_timer(vm_clock, virtio_net_tx_timer, n);

    n->tx_waiting = 0;

    n->tx_timeout = net->txtimer;

    n->tx_burst = net->txburst;

    n->mergeable_rx_bufs = 0;

    n->promisc = 1; /* for compatibility */



    n->mac_table.macs = qemu_mallocz(MAC_TABLE_ENTRIES * ETH_ALEN);



    n->vlans = qemu_mallocz(MAX_VLAN >> 3);



    n->qdev = dev;

    register_savevm(dev, "virtio-net", -1, VIRTIO_NET_VM_VERSION,

                    virtio_net_save, virtio_net_load, n);

    n->vmstate = qemu_add_vm_change_state_handler(virtio_net_vmstate_change, n);



    return &n->vdev;

}

int cpu_x86_register(X86CPU *cpu, const char *cpu_model)

{

    CPUX86State *env = &cpu->env;

    x86_def_t def1, *def = &def1;

    Error *error = NULL;

    char *name, *features;

    gchar **model_pieces;



    memset(def, 0, sizeof(*def));



    model_pieces = g_strsplit(cpu_model, ",", 2);

    if (!model_pieces[0]) {

        error_setg(&error, "Invalid/empty CPU model name");

        goto out;

    }

    name = model_pieces[0];

    features = model_pieces[1];



    if (cpu_x86_find_by_name(def, name) < 0) {

        error_setg(&error, "Unable to find CPU definition: %s", name);

        goto out;

    }



    if (kvm_enabled()) {

        def->kvm_features |= kvm_default_features;

    }

    def->ext_features |= CPUID_EXT_HYPERVISOR;



    object_property_set_str(OBJECT(cpu), def->vendor, "vendor", &error);

    object_property_set_int(OBJECT(cpu), def->level, "level", &error);

    object_property_set_int(OBJECT(cpu), def->family, "family", &error);

    object_property_set_int(OBJECT(cpu), def->model, "model", &error);

    object_property_set_int(OBJECT(cpu), def->stepping, "stepping", &error);

    env->cpuid_features = def->features;

    env->cpuid_ext_features = def->ext_features;

    env->cpuid_ext2_features = def->ext2_features;

    env->cpuid_ext3_features = def->ext3_features;

    object_property_set_int(OBJECT(cpu), def->xlevel, "xlevel", &error);

    env->cpuid_kvm_features = def->kvm_features;

    env->cpuid_svm_features = def->svm_features;

    env->cpuid_ext4_features = def->ext4_features;

    env->cpuid_7_0_ebx_features = def->cpuid_7_0_ebx_features;

    env->cpuid_xlevel2 = def->xlevel2;

    object_property_set_int(OBJECT(cpu), (int64_t)def->tsc_khz * 1000,

                            "tsc-frequency", &error);



    object_property_set_str(OBJECT(cpu), def->model_id, "model-id", &error);

    if (error) {

        goto out;

    }



    cpu_x86_parse_featurestr(cpu, features, &error);

out:

    g_strfreev(model_pieces);

    if (error) {

        fprintf(stderr, "%s\n", error_get_pretty(error));

        error_free(error);

        return -1;

    }

    return 0;

}

static int img_info(int argc, char **argv)

{

    int c;

    OutputFormat output_format = OFORMAT_HUMAN;

    bool chain = false;

    const char *filename, *fmt, *output;

    ImageInfoList *list;

    bool image_opts = false;



    fmt = NULL;

    output = NULL;

    for(;;) {

        int option_index = 0;

        static const struct option long_options[] = {

            {"help", no_argument, 0, 'h'},

            {"format", required_argument, 0, 'f'},

            {"output", required_argument, 0, OPTION_OUTPUT},

            {"backing-chain", no_argument, 0, OPTION_BACKING_CHAIN},

            {"object", required_argument, 0, OPTION_OBJECT},

            {"image-opts", no_argument, 0, OPTION_IMAGE_OPTS},

            {0, 0, 0, 0}

        };

        c = getopt_long(argc, argv, "f:h",

                        long_options, &option_index);

        if (c == -1) {

            break;

        }

        switch(c) {

        case '?':

        case 'h':

            help();

            break;

        case 'f':

            fmt = optarg;

            break;

        case OPTION_OUTPUT:

            output = optarg;

            break;

        case OPTION_BACKING_CHAIN:

            chain = true;

            break;

        case OPTION_OBJECT: {

            QemuOpts *opts;

            opts = qemu_opts_parse_noisily(&qemu_object_opts,

                                           optarg, true);

            if (!opts) {

                return 1;

            }

        }   break;

        case OPTION_IMAGE_OPTS:

            image_opts = true;

            break;

        }

    }

    if (optind != argc - 1) {

        error_exit("Expecting one image file name");

    }

    filename = argv[optind++];



    if (output && !strcmp(output, "json")) {

        output_format = OFORMAT_JSON;

    } else if (output && !strcmp(output, "human")) {

        output_format = OFORMAT_HUMAN;

    } else if (output) {

        error_report("--output must be used with human or json as argument.");

        return 1;

    }



    if (qemu_opts_foreach(&qemu_object_opts,

                          user_creatable_add_opts_foreach,

                          NULL, NULL)) {

        return 1;

    }



    list = collect_image_info_list(image_opts, filename, fmt, chain);

    if (!list) {

        return 1;

    }



    switch (output_format) {

    case OFORMAT_HUMAN:

        dump_human_image_info_list(list);

        break;

    case OFORMAT_JSON:

        if (chain) {

            dump_json_image_info_list(list);

        } else {

            dump_json_image_info(list->value);

        }

        break;

    }



    qapi_free_ImageInfoList(list);

    return 0;

}

static int handle_sigp(S390CPU *cpu, uint8_t ipa1, uint32_t ipb)

{

    CPUS390XState *env = &cpu->env;

    const uint8_t r1 = ipa1 >> 4;

    const uint8_t r3 = ipa1 & 0x0f;

    int ret;

    uint8_t order;

    uint64_t *status_reg;

    uint64_t param;

    S390CPU *dst_cpu = NULL;



    cpu_synchronize_state(CPU(cpu));



    /* get order code */

    order = decode_basedisp_rs(env, ipb, NULL)

        & SIGP_ORDER_MASK;

    status_reg = &env->regs[r1];

    param = (r1 % 2) ? env->regs[r1] : env->regs[r1 + 1];



    if (qemu_mutex_trylock(&qemu_sigp_mutex)) {

        ret = SIGP_CC_BUSY;

        goto out;

    }



    switch (order) {

    case SIGP_SET_ARCH:

        ret = sigp_set_architecture(cpu, param, status_reg);

        break;

    default:

        /* all other sigp orders target a single vcpu */

        dst_cpu = s390_cpu_addr2state(env->regs[r3]);

        ret = handle_sigp_single_dst(dst_cpu, order, param, status_reg);

    }

    qemu_mutex_unlock(&qemu_sigp_mutex);



out:

    trace_kvm_sigp_finished(order, CPU(cpu)->cpu_index,

                            dst_cpu ? CPU(dst_cpu)->cpu_index : -1, ret);



    if (ret >= 0) {

        setcc(cpu, ret);

        return 0;

    }



    return ret;

}

static void bt_hci_done(struct HCIInfo *info)

{

    struct bt_hci_s *hci = hci_from_info(info);

    int handle;



    bt_device_done(&hci->device);



    if (hci->device.lmp_name)

        g_free((void *) hci->device.lmp_name);



    /* Be gentle and send DISCONNECT to all connected peers and those

     * currently waiting for us to accept or reject a connection request.

     * This frees the links.  */

    if (hci->conn_req_host) {

        bt_hci_connection_reject(hci,

                                 hci->conn_req_host, HCI_OE_POWER_OFF);

        return;

    }



    for (handle = HCI_HANDLE_OFFSET;

                    handle < (HCI_HANDLE_OFFSET | HCI_HANDLES_MAX); handle ++)

        if (!bt_hci_handle_bad(hci, handle))

            bt_hci_disconnect(hci, handle, HCI_OE_POWER_OFF);



    /* TODO: this is not enough actually, there may be slaves from whom

     * we have requested a connection who will soon (or not) respond with

     * an accept or a reject, so we should also check if hci->lm.connecting

     * is non-zero and if so, avoid freeing the hci but otherwise disappear

     * from all qemu social life (e.g. stop scanning and request to be

     * removed from s->device.net) and arrange for

     * s->device.lmp_connection_complete to free the remaining bits once

     * hci->lm.awaiting_bdaddr[] is empty.  */



    timer_free(hci->lm.inquiry_done);

    timer_free(hci->lm.inquiry_next);

    timer_free(hci->conn_accept_timer);



    g_free(hci);

}

