static void laio_cancel(BlockDriverAIOCB *blockacb)

{

    struct qemu_laiocb *laiocb = (struct qemu_laiocb *)blockacb;

    struct io_event event;

    int ret;



    if (laiocb->ret != -EINPROGRESS)

        return;



    /*

     * Note that as of Linux 2.6.31 neither the block device code nor any

     * filesystem implements cancellation of AIO request.

     * Thus the polling loop below is the normal code path.

     */

    ret = io_cancel(laiocb->ctx->ctx, &laiocb->iocb, &event);

    if (ret == 0) {

        laiocb->ret = -ECANCELED;

        return;

    }



    /*

     * We have to wait for the iocb to finish.

     *

     * The only way to get the iocb status update is by polling the io context.

     * We might be able to do this slightly more optimal by removing the

     * O_NONBLOCK flag.

     */

    while (laiocb->ret == -EINPROGRESS) {

        qemu_laio_completion_cb(&laiocb->ctx->e);

    }

}

static void coroutine_fn stream_run(void *opaque)

{

    StreamBlockJob *s = opaque;

    BlockDriverState *bs = s->common.bs;

    BlockDriverState *base = s->base;

    int64_t sector_num, end;

    int error = 0;

    int ret = 0;

    int n = 0;

    void *buf;



    s->common.len = bdrv_getlength(bs);

    if (s->common.len < 0) {

        block_job_completed(&s->common, s->common.len);

        return;

    }



    end = s->common.len >> BDRV_SECTOR_BITS;

    buf = qemu_blockalign(bs, STREAM_BUFFER_SIZE);



    /* Turn on copy-on-read for the whole block device so that guest read

     * requests help us make progress.  Only do this when copying the entire

     * backing chain since the copy-on-read operation does not take base into

     * account.

     */

    if (!base) {

        bdrv_enable_copy_on_read(bs);

    }



    for (sector_num = 0; sector_num < end; sector_num += n) {

        uint64_t delay_ns = 0;

        bool copy;



wait:

        /* Note that even when no rate limit is applied we need to yield

         * with no pending I/O here so that bdrv_drain_all() returns.

         */

        block_job_sleep_ns(&s->common, QEMU_CLOCK_REALTIME, delay_ns);

        if (block_job_is_cancelled(&s->common)) {

            break;

        }



        ret = bdrv_is_allocated(bs, sector_num,

                                STREAM_BUFFER_SIZE / BDRV_SECTOR_SIZE, &n);

        if (ret == 1) {

            /* Allocated in the top, no need to copy.  */

            copy = false;

        } else if (ret >= 0) {

            /* Copy if allocated in the intermediate images.  Limit to the

             * known-unallocated area [sector_num, sector_num+n).  */

            ret = bdrv_is_allocated_above(bs->backing_hd, base,

                                          sector_num, n, &n);



            /* Finish early if end of backing file has been reached */

            if (ret == 0 && n == 0) {

                n = end - sector_num;

            }



            copy = (ret == 1);

        }

        trace_stream_one_iteration(s, sector_num, n, ret);

        if (ret >= 0 && copy) {

            if (s->common.speed) {

                delay_ns = ratelimit_calculate_delay(&s->limit, n);

                if (delay_ns > 0) {

                    goto wait;

                }

            }

            ret = stream_populate(bs, sector_num, n, buf);

        }

        if (ret < 0) {

            BlockErrorAction action =

                block_job_error_action(&s->common, s->common.bs, s->on_error,

                                       true, -ret);

            if (action == BDRV_ACTION_STOP) {

                n = 0;

                continue;

            }

            if (error == 0) {

                error = ret;

            }

            if (action == BDRV_ACTION_REPORT) {

                break;

            }

        }

        ret = 0;



        /* Publish progress */

        s->common.offset += n * BDRV_SECTOR_SIZE;

    }



    if (!base) {

        bdrv_disable_copy_on_read(bs);

    }



    /* Do not remove the backing file if an error was there but ignored.  */

    ret = error;



    if (!block_job_is_cancelled(&s->common) && sector_num == end && ret == 0) {

        const char *base_id = NULL, *base_fmt = NULL;

        if (base) {

            base_id = s->backing_file_id;

            if (base->drv) {

                base_fmt = base->drv->format_name;

            }

        }

        ret = bdrv_change_backing_file(bs, base_id, base_fmt);

        close_unused_images(bs, base, base_id);

    }



    qemu_vfree(buf);

    block_job_completed(&s->common, ret);

}

PCIBus *pci_apb_init(hwaddr special_base,

                     hwaddr mem_base,

                     qemu_irq *ivec_irqs, PCIBus **busA, PCIBus **busB,

                     qemu_irq **pbm_irqs)

{

    DeviceState *dev;

    SysBusDevice *s;

    PCIHostState *phb;

    APBState *d;

    IOMMUState *is;

    PCIDevice *pci_dev;

    PCIBridge *br;



    /* Ultrasparc PBM main bus */

    dev = qdev_create(NULL, TYPE_APB);

    d = APB_DEVICE(dev);

    phb = PCI_HOST_BRIDGE(dev);

    phb->bus = pci_register_bus(DEVICE(phb), "pci",

                                pci_apb_set_irq, pci_pbm_map_irq, d,

                                &d->pci_mmio,

                                get_system_io(),

                                0, 32, TYPE_PCI_BUS);

    qdev_init_nofail(dev);

    s = SYS_BUS_DEVICE(dev);

    /* apb_config */

    sysbus_mmio_map(s, 0, special_base);

    /* PCI configuration space */

    sysbus_mmio_map(s, 1, special_base + 0x1000000ULL);

    /* pci_ioport */

    sysbus_mmio_map(s, 2, special_base + 0x2000000ULL);



    memory_region_init(&d->pci_mmio, OBJECT(s), "pci-mmio", 0x100000000ULL);

    memory_region_add_subregion(get_system_memory(), mem_base, &d->pci_mmio);



    *pbm_irqs = d->pbm_irqs;

    d->ivec_irqs = ivec_irqs;



    pci_create_simple(phb->bus, 0, "pbm-pci");



    /* APB IOMMU */

    is = &d->iommu;

    memset(is, 0, sizeof(IOMMUState));



    memory_region_init_iommu(&is->iommu, sizeof(is->iommu),

                             TYPE_APB_IOMMU_MEMORY_REGION, OBJECT(dev),

                             "iommu-apb", UINT64_MAX);

    address_space_init(&is->iommu_as, MEMORY_REGION(&is->iommu), "pbm-as");

    pci_setup_iommu(phb->bus, pbm_pci_dma_iommu, is);



    /* APB secondary busses */

    pci_dev = pci_create_multifunction(phb->bus, PCI_DEVFN(1, 0), true,

                                   TYPE_PBM_PCI_BRIDGE);

    br = PCI_BRIDGE(pci_dev);

    pci_bridge_map_irq(br, "pciB", pci_apb_map_irq);

    qdev_init_nofail(&pci_dev->qdev);

    *busB = pci_bridge_get_sec_bus(br);



    pci_dev = pci_create_multifunction(phb->bus, PCI_DEVFN(1, 1), true,

                                   TYPE_PBM_PCI_BRIDGE);

    br = PCI_BRIDGE(pci_dev);

    pci_bridge_map_irq(br, "pciA", pci_apb_map_irq);

    qdev_prop_set_bit(DEVICE(pci_dev), "busA", true);

    qdev_init_nofail(&pci_dev->qdev);

    *busA = pci_bridge_get_sec_bus(br);



    return phb->bus;

}

