static int local_link(FsContext *ctx, V9fsPath *oldpath,

                      V9fsPath *dirpath, const char *name)

{

    int ret;

    V9fsString newpath;

    char buffer[PATH_MAX], buffer1[PATH_MAX];



    v9fs_string_init(&newpath);

    v9fs_string_sprintf(&newpath, "%s/%s", dirpath->data, name);



    ret = link(rpath(ctx, oldpath->data, buffer),

               rpath(ctx, newpath.data, buffer1));



    /* now link the virtfs_metadata files */

    if (!ret && (ctx->export_flags & V9FS_SM_MAPPED_FILE)) {

        /* Link the .virtfs_metadata files. Create the metada directory */

        ret = local_create_mapped_attr_dir(ctx, newpath.data);

        if (ret < 0) {

            goto err_out;

        }

        ret = link(local_mapped_attr_path(ctx, oldpath->data, buffer),

                   local_mapped_attr_path(ctx, newpath.data, buffer1));

        if (ret < 0 && errno != ENOENT) {

            goto err_out;

        }

    }

err_out:

    v9fs_string_free(&newpath);

    return ret;

}

static void commit_complete(BlockJob *job, void *opaque)

{

    CommitBlockJob *s = container_of(job, CommitBlockJob, common);

    CommitCompleteData *data = opaque;

    BlockDriverState *active = s->active;

    BlockDriverState *top = blk_bs(s->top);

    BlockDriverState *base = blk_bs(s->base);

    BlockDriverState *overlay_bs = bdrv_find_overlay(active, top);

    int ret = data->ret;



    if (!block_job_is_cancelled(&s->common) && ret == 0) {

        /* success */

        ret = bdrv_drop_intermediate(active, top, base, s->backing_file_str);

    }



    /* restore base open flags here if appropriate (e.g., change the base back

     * to r/o). These reopens do not need to be atomic, since we won't abort

     * even on failure here */

    if (s->base_flags != bdrv_get_flags(base)) {

        bdrv_reopen(base, s->base_flags, NULL);

    }

    if (overlay_bs && s->orig_overlay_flags != bdrv_get_flags(overlay_bs)) {

        bdrv_reopen(overlay_bs, s->orig_overlay_flags, NULL);

    }

    g_free(s->backing_file_str);

    blk_unref(s->top);

    blk_unref(s->base);

    block_job_completed(&s->common, ret);

    g_free(data);

}

static int ide_drive_post_load(void *opaque, int version_id)

{

    IDEState *s = opaque;



    if (s->identify_set) {

        blk_set_enable_write_cache(s->blk, !!(s->identify_data[85] & (1 << 5)));

    }

    return 0;

}

void do_migrate_set_downtime(Monitor *mon, const QDict *qdict)

{

    char *ptr;

    double d;

    const char *value = qdict_get_str(qdict, "value");



    d = strtod(value, &ptr);

    if (!strcmp(ptr,"ms")) {

        d *= 1000000;

    } else if (!strcmp(ptr,"us")) {

        d *= 1000;

    } else if (!strcmp(ptr,"ns")) {

    } else {

        /* all else considered to be seconds */

        d *= 1000000000;

    }



    max_downtime = (uint64_t)d;

}

int kvm_set_ioeventfd_pio_word(int fd, uint16_t addr, uint16_t val, bool assign)

{

    struct kvm_ioeventfd kick = {

        .datamatch = val,

        .addr = addr,

        .len = 2,

        .flags = KVM_IOEVENTFD_FLAG_DATAMATCH | KVM_IOEVENTFD_FLAG_PIO,

        .fd = fd,

    };

    int r;

    if (!kvm_enabled())

        return -ENOSYS;

    if (!assign)

        kick.flags |= KVM_IOEVENTFD_FLAG_DEASSIGN;

    r = kvm_vm_ioctl(kvm_state, KVM_IOEVENTFD, &kick);

    if (r < 0)

        return r;

    return 0;

}

