void msi_uninit(struct PCIDevice *dev)

{

    uint16_t flags = pci_get_word(dev->config + msi_flags_off(dev));

    uint8_t cap_size = msi_cap_sizeof(flags);

    pci_del_capability(dev, PCI_CAP_ID_MSIX, cap_size);

    MSI_DEV_PRINTF(dev, "uninit\n");

}

Object *user_creatable_add(const QDict *qdict,

                           Visitor *v, Error **errp)

{

    char *type = NULL;

    char *id = NULL;

    Object *obj = NULL;

    Error *local_err = NULL, *end_err = NULL;

    QDict *pdict;



    pdict = qdict_clone_shallow(qdict);



    visit_start_struct(v, NULL, NULL, 0, &local_err);

    if (local_err) {

        goto out;

    }



    qdict_del(pdict, "qom-type");

    visit_type_str(v, "qom-type", &type, &local_err);

    if (local_err) {

        goto out_visit;

    }



    qdict_del(pdict, "id");

    visit_type_str(v, "id", &id, &local_err);

    if (local_err) {

        goto out_visit;

    }



    obj = user_creatable_add_type(type, id, pdict, v, &local_err);

    if (local_err) {

        goto out_visit;

    }



 out_visit:

    visit_end_struct(v, &end_err);

    if (end_err) {

        error_propagate(&local_err, end_err);

        if (obj) {

            user_creatable_del(id, NULL);

        }

        goto out;

    }



out:

    QDECREF(pdict);

    g_free(id);

    g_free(type);

    if (local_err) {

        error_propagate(errp, local_err);

        object_unref(obj);

        return NULL;

    }

    return obj;

}

void do_compute_hflags (CPUPPCState *env)

{

    /* Compute current hflags */

    env->hflags = (msr_pr << MSR_PR) | (msr_le << MSR_LE) |

        (msr_fp << MSR_FP) | (msr_fe0 << MSR_FE0) | (msr_fe1 << MSR_FE1) |

        (msr_vr << MSR_VR) | (msr_ap << MSR_AP) | (msr_sa << MSR_SA) | 

        (msr_se << MSR_SE) | (msr_be << MSR_BE);

#if defined (TARGET_PPC64)

    env->hflags |= (msr_sf << MSR_SF) | (msr_hv << MSR_HV);

#endif

}

