static inline TranslationBlock *tb_find(CPUState *cpu,

                                        TranslationBlock *last_tb,

                                        int tb_exit)

{

    TranslationBlock *tb;

    target_ulong cs_base, pc;

    uint32_t flags;

    bool acquired_tb_lock = false;

    uint32_t cf_mask = curr_cflags();



    tb = tb_lookup__cpu_state(cpu, &pc, &cs_base, &flags, cf_mask);

    if (tb == NULL) {

        /* mmap_lock is needed by tb_gen_code, and mmap_lock must be

         * taken outside tb_lock. As system emulation is currently

         * single threaded the locks are NOPs.

         */

        mmap_lock();

        tb_lock();

        acquired_tb_lock = true;



        /* There's a chance that our desired tb has been translated while

         * taking the locks so we check again inside the lock.

         */

        tb = tb_htable_lookup(cpu, pc, cs_base, flags, cf_mask);

        if (likely(tb == NULL)) {

            /* if no translated code available, then translate it now */

            tb = tb_gen_code(cpu, pc, cs_base, flags, cf_mask);

        }



        mmap_unlock();

        /* We add the TB in the virtual pc hash table for the fast lookup */

        atomic_set(&cpu->tb_jmp_cache[tb_jmp_cache_hash_func(pc)], tb);

    }

#ifndef CONFIG_USER_ONLY

    /* We don't take care of direct jumps when address mapping changes in

     * system emulation. So it's not safe to make a direct jump to a TB

     * spanning two pages because the mapping for the second page can change.

     */

    if (tb->page_addr[1] != -1) {

        last_tb = NULL;

    }

#endif

    /* See if we can patch the calling TB. */

    if (last_tb && !qemu_loglevel_mask(CPU_LOG_TB_NOCHAIN)) {

        if (!acquired_tb_lock) {

            tb_lock();

            acquired_tb_lock = true;

        }

        if (!(tb->cflags & CF_INVALID)) {

            tb_add_jump(last_tb, tb_exit, tb);

        }

    }

    if (acquired_tb_lock) {

        tb_unlock();

    }

    return tb;

}

static VncServerInfo2List *qmp_query_server_entry(QIOChannelSocket *ioc,

                                                  bool websocket,

                                                  int auth,

                                                  int subauth,

                                                  VncServerInfo2List *prev)

{

    VncServerInfo2List *list;

    VncServerInfo2 *info;

    Error *err = NULL;

    SocketAddress *addr;



    addr = qio_channel_socket_get_local_address(ioc, &err);

    if (!addr) {

        error_free(err);

        return prev;

    }



    info = g_new0(VncServerInfo2, 1);

    vnc_init_basic_info(addr, qapi_VncServerInfo2_base(info), &err);

    qapi_free_SocketAddress(addr);

    if (err) {

        qapi_free_VncServerInfo2(info);

        error_free(err);

        return prev;

    }

    info->websocket = websocket;



    qmp_query_auth(auth, subauth, &info->auth,

                   &info->vencrypt, &info->has_vencrypt);



    list = g_new0(VncServerInfo2List, 1);

    list->value = info;

    list->next = prev;

    return list;

}

static void tcx_invalidate_cursor_position(TCXState *s)

{

    int ymin, ymax, start, end;



    /* invalidate only near the cursor */

    ymin = s->cursy;

    if (ymin >= s->height) {

        return;

    }

    ymax = MIN(s->height, ymin + 32);

    start = ymin * 1024;

    end   = ymax * 1024;



    memory_region_set_dirty(&s->vram_mem, start, end-start);

}

static int pxa2xx_timer_init(SysBusDevice *dev)

{

    int i;

    int iomemtype;

    PXA2xxTimerInfo *s;

    qemu_irq irq4;



    s = FROM_SYSBUS(PXA2xxTimerInfo, dev);

    s->irq_enabled = 0;

    s->oldclock = 0;

    s->clock = 0;

    s->lastload = qemu_get_clock(vm_clock);

    s->reset3 = 0;



    for (i = 0; i < 4; i ++) {

        s->timer[i].value = 0;

        sysbus_init_irq(dev, &s->timer[i].irq);

        s->timer[i].info = s;

        s->timer[i].num = i;

        s->timer[i].level = 0;

        s->timer[i].qtimer = qemu_new_timer(vm_clock,

                        pxa2xx_timer_tick, &s->timer[i]);

    }

    if (s->flags & (1 << PXA2XX_TIMER_HAVE_TM4)) {

        sysbus_init_irq(dev, &irq4);



        for (i = 0; i < 8; i ++) {

            s->tm4[i].tm.value = 0;

            s->tm4[i].tm.info = s;

            s->tm4[i].tm.num = i + 4;

            s->tm4[i].tm.level = 0;

            s->tm4[i].freq = 0;

            s->tm4[i].control = 0x0;

            s->tm4[i].tm.qtimer = qemu_new_timer(vm_clock,

                        pxa2xx_timer_tick4, &s->tm4[i]);

            s->tm4[i].tm.irq = irq4;

        }

    }



    iomemtype = cpu_register_io_memory(pxa2xx_timer_readfn,

                    pxa2xx_timer_writefn, s, DEVICE_NATIVE_ENDIAN);

    sysbus_init_mmio(dev, 0x00001000, iomemtype);



    return 0;

}

static void xenfb_mouse_event(void *opaque,

			      int dx, int dy, int dz, int button_state)

{

    struct XenInput *xenfb = opaque;

    DisplaySurface *surface = qemu_console_surface(xenfb->c.con);

    int dw = surface_width(surface);

    int dh = surface_height(surface);

    int i;



    trace_xenfb_mouse_event(opaque, dx, dy, dz, button_state,

                            xenfb->abs_pointer_wanted);

    if (xenfb->abs_pointer_wanted)

	xenfb_send_position(xenfb,

			    dx * (dw - 1) / 0x7fff,

			    dy * (dh - 1) / 0x7fff,

			    dz);

    else

	xenfb_send_motion(xenfb, dx, dy, dz);



    for (i = 0 ; i < 8 ; i++) {

	int lastDown = xenfb->button_state & (1 << i);

	int down = button_state & (1 << i);

	if (down == lastDown)

	    continue;



	if (xenfb_send_key(xenfb, down, BTN_LEFT+i) < 0)

	    return;

    }

    xenfb->button_state = button_state;

}

