static void lsi_do_command(LSIState *s)

{

    SCSIDevice *dev;

    uint8_t buf[16];

    uint32_t id;

    int n;



    DPRINTF("Send command len=%d\n", s->dbc);

    if (s->dbc > 16)

        s->dbc = 16;

    cpu_physical_memory_read(s->dnad, buf, s->dbc);

    s->sfbr = buf[0];

    s->command_complete = 0;



    id = (s->select_tag >> 8) & 0xf;

    dev = s->bus.devs[id];

    if (!dev) {

        lsi_bad_selection(s, id);

        return;

    }



    assert(s->current == NULL);

    s->current = qemu_mallocz(sizeof(lsi_request));

    s->current->tag = s->select_tag;

    s->current->req = scsi_req_new(dev, s->current->tag, s->current_lun,

                                   s->current);



    n = scsi_req_enqueue(s->current->req, buf);

    if (n) {

        if (n > 0) {

            lsi_set_phase(s, PHASE_DI);

        } else if (n < 0) {

            lsi_set_phase(s, PHASE_DO);

        }

        scsi_req_continue(s->current->req);

    }

    if (!s->command_complete) {

        if (n) {

            /* Command did not complete immediately so disconnect.  */

            lsi_add_msg_byte(s, 2); /* SAVE DATA POINTER */

            lsi_add_msg_byte(s, 4); /* DISCONNECT */

            /* wait data */

            lsi_set_phase(s, PHASE_MI);

            s->msg_action = 1;

            lsi_queue_command(s);

        } else {

            /* wait command complete */

            lsi_set_phase(s, PHASE_DI);

        }

    }

}

void ioinst_handle_chsc(S390CPU *cpu, uint32_t ipb)

{

    ChscReq *req;

    ChscResp *res;

    uint64_t addr;

    int reg;

    uint16_t len;

    uint16_t command;

    CPUS390XState *env = &cpu->env;

    uint8_t buf[TARGET_PAGE_SIZE];



    trace_ioinst("chsc");

    reg = (ipb >> 20) & 0x00f;

    addr = env->regs[reg];

    /* Page boundary? */

    if (addr & 0xfff) {

        program_interrupt(env, PGM_SPECIFICATION, 2);

        return;

    }

    /*

     * Reading sizeof(ChscReq) bytes is currently enough for all of our

     * present CHSC sub-handlers ... if we ever need more, we should take

     * care of req->len here first.

     */

    if (s390_cpu_virt_mem_read(cpu, addr, reg, buf, sizeof(ChscReq))) {

        return;

    }

    req = (ChscReq *)buf;

    len = be16_to_cpu(req->len);

    /* Length field valid? */

    if ((len < 16) || (len > 4088) || (len & 7)) {

        program_interrupt(env, PGM_OPERAND, 2);

        return;

    }

    memset((char *)req + len, 0, TARGET_PAGE_SIZE - len);

    res = (void *)((char *)req + len);

    command = be16_to_cpu(req->command);

    trace_ioinst_chsc_cmd(command, len);

    switch (command) {

    case CHSC_SCSC:

        ioinst_handle_chsc_scsc(req, res);

        break;

    case CHSC_SCPD:

        ioinst_handle_chsc_scpd(req, res);

        break;

    case CHSC_SDA:

        ioinst_handle_chsc_sda(req, res);

        break;

    case CHSC_SEI:

        ioinst_handle_chsc_sei(req, res);

        break;

    default:

        ioinst_handle_chsc_unimplemented(res);

        break;

    }



    if (!s390_cpu_virt_mem_write(cpu, addr + len, reg, res,

                                 be16_to_cpu(res->len))) {

        setcc(cpu, 0);    /* Command execution complete */

    }

}

int inet_connect_opts(QemuOpts *opts, Error **errp,

                      NonBlockingConnectHandler *callback, void *opaque)

{

    struct addrinfo *res, *e;

    int sock = -1;

    bool in_progress;

    ConnectState *connect_state = NULL;



    res = inet_parse_connect_opts(opts, errp);

    if (!res) {

        return -1;

    }



    if (callback != NULL) {

        connect_state = g_malloc0(sizeof(*connect_state));

        connect_state->addr_list = res;

        connect_state->callback = callback;

        connect_state->opaque = opaque;

    }



    for (e = res; e != NULL; e = e->ai_next) {

        if (error_is_set(errp)) {

            error_free(*errp);

            *errp = NULL;

        }

        if (connect_state != NULL) {

            connect_state->current_addr = e;

        }

        sock = inet_connect_addr(e, &in_progress, connect_state, errp);

        if (in_progress) {

            return sock;

        } else if (sock >= 0) {

            /* non blocking socket immediate success, call callback */

            if (callback != NULL) {

                callback(sock, opaque);

            }

            break;

        }

    }

    g_free(connect_state);

    freeaddrinfo(res);

    return sock;

}

static void channel_run(DBDMA_channel *ch)

{

    dbdma_cmd *current = &ch->current;

    uint16_t cmd, key;

    uint16_t req_count;

    uint32_t phy_addr;



    DBDMA_DPRINTF("channel_run\n");

    dump_dbdma_cmd(current);



    /* clear WAKE flag at command fetch */



    ch->regs[DBDMA_STATUS] &= cpu_to_be32(~WAKE);



    cmd = le16_to_cpu(current->command) & COMMAND_MASK;



    switch (cmd) {

    case DBDMA_NOP:

        nop(ch);

	return;



    case DBDMA_STOP:

        stop(ch);

	return;

    }



    key = le16_to_cpu(current->command) & 0x0700;

    req_count = le16_to_cpu(current->req_count);

    phy_addr = le32_to_cpu(current->phy_addr);



    if (key == KEY_STREAM4) {

        printf("command %x, invalid key 4\n", cmd);

        kill_channel(ch);

        return;

    }



    switch (cmd) {

    case OUTPUT_MORE:

        start_output(ch, key, phy_addr, req_count, 0);

	return;



    case OUTPUT_LAST:

        start_output(ch, key, phy_addr, req_count, 1);

	return;



    case INPUT_MORE:

        start_input(ch, key, phy_addr, req_count, 0);

	return;



    case INPUT_LAST:

        start_input(ch, key, phy_addr, req_count, 1);

	return;

    }



    if (key < KEY_REGS) {

        printf("command %x, invalid key %x\n", cmd, key);

        key = KEY_SYSTEM;

    }



    /* for LOAD_WORD and STORE_WORD, req_count is on 3 bits

     * and BRANCH is invalid

     */



    req_count = req_count & 0x0007;

    if (req_count & 0x4) {

        req_count = 4;

        phy_addr &= ~3;

    } else if (req_count & 0x2) {

        req_count = 2;

        phy_addr &= ~1;

    } else

        req_count = 1;



    switch (cmd) {

    case LOAD_WORD:

        load_word(ch, key, phy_addr, req_count);

	return;



    case STORE_WORD:

        store_word(ch, key, phy_addr, req_count);

	return;

    }

}

