static void openpic_reset (void *opaque)

{

    openpic_t *opp = (openpic_t *)opaque;

    int i;



    opp->glbc = 0x80000000;

    /* Initialise controller registers */

    opp->frep = ((OPENPIC_EXT_IRQ - 1) << 16) | ((MAX_CPU - 1) << 8) | VID;

    opp->veni = VENI;

    opp->pint = 0x00000000;

    opp->spve = 0x000000FF;

    opp->tifr = 0x003F7A00;

    /* ? */

    opp->micr = 0x00000000;

    /* Initialise IRQ sources */

    for (i = 0; i < opp->max_irq; i++) {

	opp->src[i].ipvp = 0xA0000000;

	opp->src[i].ide  = 0x00000000;

    }

    /* Initialise IRQ destinations */

    for (i = 0; i < MAX_CPU; i++) {

	opp->dst[i].pctp      = 0x0000000F;

	opp->dst[i].pcsr      = 0x00000000;

	memset(&opp->dst[i].raised, 0, sizeof(IRQ_queue_t));


	memset(&opp->dst[i].servicing, 0, sizeof(IRQ_queue_t));


    }

    /* Initialise timers */

    for (i = 0; i < MAX_TMR; i++) {

	opp->timers[i].ticc = 0x00000000;

	opp->timers[i].tibc = 0x80000000;

    }

    /* Initialise doorbells */

#if MAX_DBL > 0

    opp->dar = 0x00000000;

    for (i = 0; i < MAX_DBL; i++) {

	opp->doorbells[i].dmr  = 0x00000000;

    }

#endif

    /* Initialise mailboxes */

#if MAX_MBX > 0

    for (i = 0; i < MAX_MBX; i++) { /* ? */

	opp->mailboxes[i].mbr   = 0x00000000;

    }

#endif

    /* Go out of RESET state */

    opp->glbc = 0x00000000;

}

static XICSState *xics_system_init(MachineState *machine,

                                   int nr_servers, int nr_irqs)

{

    XICSState *icp = NULL;



    if (kvm_enabled()) {

        Error *err = NULL;



        if (machine_kernel_irqchip_allowed(machine)) {

            icp = try_create_xics(TYPE_KVM_XICS, nr_servers, nr_irqs, &err);

        }

        if (machine_kernel_irqchip_required(machine) && !icp) {

            error_report("kernel_irqchip requested but unavailable: %s",

                         error_get_pretty(err));

        }


    }



    if (!icp) {

        icp = try_create_xics(TYPE_XICS, nr_servers, nr_irqs, &error_abort);

    }



    return icp;

}

target_ulong helper_lwr(CPUMIPSState *env, target_ulong arg1,

                        target_ulong arg2, int mem_idx)

{

    target_ulong tmp;



    tmp = do_lbu(env, arg2, mem_idx);

    arg1 = (arg1 & 0xFFFFFF00) | tmp;



    if (GET_LMASK(arg2) >= 1) {

        tmp = do_lbu(env, GET_OFFSET(arg2, -1), mem_idx);

        arg1 = (arg1 & 0xFFFF00FF) | (tmp << 8);

    }



    if (GET_LMASK(arg2) >= 2) {

        tmp = do_lbu(env, GET_OFFSET(arg2, -2), mem_idx);

        arg1 = (arg1 & 0xFF00FFFF) | (tmp << 16);

    }



    if (GET_LMASK(arg2) == 3) {

        tmp = do_lbu(env, GET_OFFSET(arg2, -3), mem_idx);

        arg1 = (arg1 & 0x00FFFFFF) | (tmp << 24);

    }

    return (int32_t)arg1;

}

QEMUSizedBuffer *qsb_clone(const QEMUSizedBuffer *qsb)

{

    QEMUSizedBuffer *out = qsb_create(NULL, qsb_get_length(qsb));

    size_t i;

    ssize_t res;

    off_t pos = 0;



    if (!out) {

        return NULL;

    }



    for (i = 0; i < qsb->n_iov; i++) {

        res =  qsb_write_at(out, qsb->iov[i].iov_base,

                            pos, qsb->iov[i].iov_len);

        if (res < 0) {

            qsb_free(out);

            return NULL;

        }

        pos += res;

    }



    return out;

}

static void device_finalize(Object *obj)

{

    DeviceState *dev = DEVICE(obj);

    BusState *bus;

    DeviceClass *dc = DEVICE_GET_CLASS(dev);



    if (dev->realized) {

        while (dev->num_child_bus) {

            bus = QLIST_FIRST(&dev->child_bus);

            qbus_free(bus);

        }

        if (qdev_get_vmsd(dev)) {

            vmstate_unregister(dev, qdev_get_vmsd(dev), dev);

        }

        if (dc->exit) {

            dc->exit(dev);

        }

        if (dev->opts) {

            qemu_opts_del(dev->opts);

        }

    }

}

static int pte_check_hash32(mmu_ctx_t *ctx, target_ulong pte0,

                            target_ulong pte1, int h, int rw, int type)

{

    target_ulong ptem, mmask;

    int access, ret, pteh, ptev, pp;



    ret = -1;

    /* Check validity and table match */

    ptev = pte_is_valid_hash32(pte0);

    pteh = (pte0 >> 6) & 1;

    if (ptev && h == pteh) {

        /* Check vsid & api */

        ptem = pte0 & PTE_PTEM_MASK;

        mmask = PTE_CHECK_MASK;

        pp = pte1 & 0x00000003;

        if (ptem == ctx->ptem) {

            if (ctx->raddr != (hwaddr)-1ULL) {

                /* all matches should have equal RPN, WIMG & PP */

                if ((ctx->raddr & mmask) != (pte1 & mmask)) {

                    qemu_log("Bad RPN/WIMG/PP\n");

                    return -3;

                }

            }

            /* Compute access rights */

            access = pp_check(ctx->key, pp, ctx->nx);

            /* Keep the matching PTE informations */

            ctx->raddr = pte1;

            ctx->prot = access;

            ret = check_prot(ctx->prot, rw, type);

            if (ret == 0) {

                /* Access granted */

                LOG_MMU("PTE access granted !\n");

            } else {

                /* Access right violation */

                LOG_MMU("PTE access rejected\n");

            }

        }

    }



    return ret;

}

static void gen_lea_modrm(DisasContext *s, int modrm, int *reg_ptr, int *offset_ptr)

{

    int havesib;

    int base, disp;

    int index;

    int scale;

    int opreg;

    int mod, rm, code, override, must_add_seg;



    /* XXX: add a generation time variable to tell if base == 0 in DS/ES/SS */

    override = -1;

    must_add_seg = s->addseg;

    if (s->prefix & (PREFIX_CS | PREFIX_SS | PREFIX_DS | 

                     PREFIX_ES | PREFIX_FS | PREFIX_GS)) {

        if (s->prefix & PREFIX_ES)

            override = R_ES;

        else if (s->prefix & PREFIX_CS)

            override = R_CS;

        else if (s->prefix & PREFIX_SS)

            override = R_SS;

        else if (s->prefix & PREFIX_DS)

            override = R_DS;

        else if (s->prefix & PREFIX_FS)

            override = R_FS;

        else

            override = R_GS;

        must_add_seg = 1;

    }



    mod = (modrm >> 6) & 3;

    rm = modrm & 7;



    if (s->aflag) {



        havesib = 0;

        base = rm;

        index = 0;

        scale = 0;



        if (base == 4) {

            havesib = 1;

            code = ldub(s->pc++);

            scale = (code >> 6) & 3;

            index = (code >> 3) & 7;

            base = code & 7;

        }



        switch (mod) {

        case 0:

            if (base == 5) {

                base = -1;

                disp = ldl(s->pc);

                s->pc += 4;

            } else {

                disp = 0;

            }

            break;

        case 1:

            disp = (int8_t)ldub(s->pc++);

            break;

        default:

        case 2:

            disp = ldl(s->pc);

            s->pc += 4;

            break;

        }



        if (base >= 0) {

            gen_op_movl_A0_reg[base]();

            if (disp != 0)

                gen_op_addl_A0_im(disp);

        } else {

            gen_op_movl_A0_im(disp);

        }

        if (havesib && (index != 4 || scale != 0)) {

            gen_op_addl_A0_reg_sN[scale][index]();

        }

        if (must_add_seg) {

            if (override < 0) {

                if (base == R_EBP || base == R_ESP)

                    override = R_SS;

                else

                    override = R_DS;

            }

            gen_op_addl_A0_seg(offsetof(CPUX86State,seg_cache[override].base));

        }

    } else {

        switch (mod) {

        case 0:

            if (rm == 6) {

                disp = lduw(s->pc);

                s->pc += 2;

                gen_op_movl_A0_im(disp);

                rm = 0; /* avoid SS override */

                goto no_rm;

            } else {

                disp = 0;

            }

            break;

        case 1:

            disp = (int8_t)ldub(s->pc++);

            break;

        default:

        case 2:

            disp = lduw(s->pc);

            s->pc += 2;

            break;

        }

        switch(rm) {

        case 0:

            gen_op_movl_A0_reg[R_EBX]();

            gen_op_addl_A0_reg_sN[0][R_ESI]();

            break;

        case 1:

            gen_op_movl_A0_reg[R_EBX]();

            gen_op_addl_A0_reg_sN[0][R_EDI]();

            break;

        case 2:

            gen_op_movl_A0_reg[R_EBP]();

            gen_op_addl_A0_reg_sN[0][R_ESI]();

            break;

        case 3:

            gen_op_movl_A0_reg[R_EBP]();

            gen_op_addl_A0_reg_sN[0][R_EDI]();

            break;

        case 4:

            gen_op_movl_A0_reg[R_ESI]();

            break;

        case 5:

            gen_op_movl_A0_reg[R_EDI]();

            break;

        case 6:

            gen_op_movl_A0_reg[R_EBP]();

            break;

        default:

        case 7:

            gen_op_movl_A0_reg[R_EBX]();

            break;

        }

        if (disp != 0)

            gen_op_addl_A0_im(disp);

        gen_op_andl_A0_ffff();

    no_rm:

        if (must_add_seg) {

            if (override < 0) {

                if (rm == 2 || rm == 3 || rm == 6)

                    override = R_SS;

                else

                    override = R_DS;

            }

            gen_op_addl_A0_seg(offsetof(CPUX86State,seg_cache[override].base));

        }

    }



    opreg = OR_A0;

    disp = 0;

    *reg_ptr = opreg;

    *offset_ptr = disp;

}

float64 int64_to_float64( int64 a STATUS_PARAM )

{

    flag zSign;



    if ( a == 0 ) return 0;

    if ( a == (sbits64) LIT64( 0x8000000000000000 ) ) {

        return packFloat64( 1, 0x43E, 0 );

    }

    zSign = ( a < 0 );

    return normalizeRoundAndPackFloat64( zSign, 0x43C, zSign ? - a : a STATUS_VAR );



}

static void rtas_ibm_change_msi(sPAPREnvironment *spapr,

                                uint32_t token, uint32_t nargs,

                                target_ulong args, uint32_t nret,

                                target_ulong rets)

{

    uint32_t config_addr = rtas_ld(args, 0);

    uint64_t buid = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 2);

    unsigned int func = rtas_ld(args, 3);

    unsigned int req_num = rtas_ld(args, 4); /* 0 == remove all */

    unsigned int seq_num = rtas_ld(args, 5);

    unsigned int ret_intr_type;

    int ndev, irq;

    sPAPRPHBState *phb = NULL;

    PCIDevice *pdev = NULL;



    switch (func) {

    case RTAS_CHANGE_MSI_FN:

    case RTAS_CHANGE_FN:

        ret_intr_type = RTAS_TYPE_MSI;

        break;

    case RTAS_CHANGE_MSIX_FN:

        ret_intr_type = RTAS_TYPE_MSIX;

        break;

    default:

        fprintf(stderr, "rtas_ibm_change_msi(%u) is not implemented\n", func);

        rtas_st(rets, 0, -3); /* Parameter error */

        return;

    }



    /* Fins sPAPRPHBState */

    phb = find_phb(spapr, buid);

    if (phb) {

        pdev = find_dev(spapr, buid, config_addr);

    }

    if (!phb || !pdev) {

        rtas_st(rets, 0, -3); /* Parameter error */

        return;

    }



    /* Releasing MSIs */

    if (!req_num) {

        ndev = spapr_msicfg_find(phb, config_addr, false);

        if (ndev < 0) {

            trace_spapr_pci_msi("MSI has not been enabled", -1, config_addr);

            rtas_st(rets, 0, -1); /* Hardware error */

            return;

        }

        trace_spapr_pci_msi("Released MSIs", ndev, config_addr);

        rtas_st(rets, 0, 0);

        rtas_st(rets, 1, 0);

        return;

    }



    /* Enabling MSI */



    /* Find a device number in the map to add or reuse the existing one */

    ndev = spapr_msicfg_find(phb, config_addr, true);

    if (ndev >= SPAPR_MSIX_MAX_DEVS || ndev < 0) {

        fprintf(stderr, "No free entry for a new MSI device\n");

        rtas_st(rets, 0, -1); /* Hardware error */

        return;

    }

    trace_spapr_pci_msi("Configuring MSI", ndev, config_addr);



    /* Check if there is an old config and MSI number has not changed */

    if (phb->msi_table[ndev].nvec && (req_num != phb->msi_table[ndev].nvec)) {

        /* Unexpected behaviour */

        fprintf(stderr, "Cannot reuse MSI config for device#%d", ndev);

        rtas_st(rets, 0, -1); /* Hardware error */

        return;

    }



    /* There is no cached config, allocate MSIs */

    if (!phb->msi_table[ndev].nvec) {

        irq = spapr_allocate_irq_block(req_num, false);

        if (irq < 0) {

            fprintf(stderr, "Cannot allocate MSIs for device#%d", ndev);

            rtas_st(rets, 0, -1); /* Hardware error */

            return;

        }

        phb->msi_table[ndev].irq = irq;

        phb->msi_table[ndev].nvec = req_num;

        phb->msi_table[ndev].config_addr = config_addr;

    }



    /* Setup MSI/MSIX vectors in the device (via cfgspace or MSIX BAR) */

    spapr_msi_setmsg(pdev, phb->msi_win_addr | (ndev << 16),

                     ret_intr_type == RTAS_TYPE_MSIX, req_num);



    rtas_st(rets, 0, 0);

    rtas_st(rets, 1, req_num);

    rtas_st(rets, 2, ++seq_num);

    rtas_st(rets, 3, ret_intr_type);



    trace_spapr_pci_rtas_ibm_change_msi(func, req_num);

}

static void gic_dist_writel(void *opaque, target_phys_addr_t offset,

                            uint32_t value)

{

    GICState *s = (GICState *)opaque;

    if (offset == 0xf00) {

        int cpu;

        int irq;

        int mask;



        cpu = gic_get_current_cpu(s);

        irq = value & 0x3ff;

        switch ((value >> 24) & 3) {

        case 0:

            mask = (value >> 16) & ALL_CPU_MASK;

            break;

        case 1:

            mask = ALL_CPU_MASK ^ (1 << cpu);

            break;

        case 2:

            mask = 1 << cpu;

            break;

        default:

            DPRINTF("Bad Soft Int target filter\n");

            mask = ALL_CPU_MASK;

            break;

        }

        GIC_SET_PENDING(irq, mask);

        gic_update(s);

        return;

    }

    gic_dist_writew(opaque, offset, value & 0xffff);

    gic_dist_writew(opaque, offset + 2, value >> 16);

}

void eth_setup_vlan_headers(struct eth_header *ehdr, uint16_t vlan_tag,

    bool *is_new)

{

    struct vlan_header *vhdr = PKT_GET_VLAN_HDR(ehdr);



    switch (be16_to_cpu(ehdr->h_proto)) {

    case ETH_P_VLAN:

    case ETH_P_DVLAN:

        /* vlan hdr exists */

        *is_new = false;

        break;



    default:

        /* No VLAN header, put a new one */

        vhdr->h_proto = ehdr->h_proto;

        ehdr->h_proto = cpu_to_be16(ETH_P_VLAN);

        *is_new = true;

        break;

    }

    vhdr->h_tci = cpu_to_be16(vlan_tag);

}

static void qemu_laio_completion_cb(void *opaque)

{

    struct qemu_laio_state *s = opaque;



    while (1) {

        struct io_event events[MAX_EVENTS];

        uint64_t val;

        ssize_t ret;

        struct timespec ts = { 0 };

        int nevents, i;



        do {

            ret = read(s->efd, &val, sizeof(val));

        } while (ret == 1 && errno == EINTR);



        if (ret == -1 && errno == EAGAIN)

            break;



        if (ret != 8)

            break;



        do {

            nevents = io_getevents(s->ctx, val, MAX_EVENTS, events, &ts);

        } while (nevents == -EINTR);



        for (i = 0; i < nevents; i++) {

            struct iocb *iocb = events[i].obj;

            struct qemu_laiocb *laiocb =

                    container_of(iocb, struct qemu_laiocb, iocb);



            laiocb->ret = io_event_ret(&events[i]);

            qemu_laio_enqueue_completed(s, laiocb);

        }

    }

}

