static int qemu_rdma_accept(RDMAContext *rdma)

{

    RDMACapabilities cap;

    struct rdma_conn_param conn_param = {

                                            .responder_resources = 2,

                                            .private_data = &cap,

                                            .private_data_len = sizeof(cap),

                                         };

    struct rdma_cm_event *cm_event;

    struct ibv_context *verbs;

    int ret = -EINVAL;

    int idx;



    ret = rdma_get_cm_event(rdma->channel, &cm_event);

    if (ret) {

        goto err_rdma_dest_wait;

    }



    if (cm_event->event != RDMA_CM_EVENT_CONNECT_REQUEST) {

        rdma_ack_cm_event(cm_event);

        goto err_rdma_dest_wait;

    }



    memcpy(&cap, cm_event->param.conn.private_data, sizeof(cap));



    network_to_caps(&cap);



    if (cap.version < 1 || cap.version > RDMA_CONTROL_VERSION_CURRENT) {

            fprintf(stderr, "Unknown source RDMA version: %d, bailing...\n",

                            cap.version);

            rdma_ack_cm_event(cm_event);

            goto err_rdma_dest_wait;

    }



    /*

     * Respond with only the capabilities this version of QEMU knows about.

     */

    cap.flags &= known_capabilities;



    /*

     * Enable the ones that we do know about.

     * Add other checks here as new ones are introduced.

     */

    if (cap.flags & RDMA_CAPABILITY_PIN_ALL) {

        rdma->pin_all = true;

    }



    rdma->cm_id = cm_event->id;

    verbs = cm_event->id->verbs;



    rdma_ack_cm_event(cm_event);



    DPRINTF("Memory pin all: %s\n", rdma->pin_all ? "enabled" : "disabled");



    caps_to_network(&cap);



    DPRINTF("verbs context after listen: %p\n", verbs);



    if (!rdma->verbs) {

        rdma->verbs = verbs;

    } else if (rdma->verbs != verbs) {

            fprintf(stderr, "ibv context not matching %p, %p!\n",

                    rdma->verbs, verbs);

            goto err_rdma_dest_wait;

    }



    qemu_rdma_dump_id("dest_init", verbs);



    ret = qemu_rdma_alloc_pd_cq(rdma);

    if (ret) {

        fprintf(stderr, "rdma migration: error allocating pd and cq!\n");

        goto err_rdma_dest_wait;

    }



    ret = qemu_rdma_alloc_qp(rdma);

    if (ret) {

        fprintf(stderr, "rdma migration: error allocating qp!\n");

        goto err_rdma_dest_wait;

    }



    ret = qemu_rdma_init_ram_blocks(rdma);

    if (ret) {

        fprintf(stderr, "rdma migration: error initializing ram blocks!\n");

        goto err_rdma_dest_wait;

    }



    for (idx = 0; idx < RDMA_WRID_MAX; idx++) {

        ret = qemu_rdma_reg_control(rdma, idx);

        if (ret) {

            fprintf(stderr, "rdma: error registering %d control!\n", idx);

            goto err_rdma_dest_wait;

        }

    }



    qemu_set_fd_handler2(rdma->channel->fd, NULL, NULL, NULL, NULL);



    ret = rdma_accept(rdma->cm_id, &conn_param);

    if (ret) {

        fprintf(stderr, "rdma_accept returns %d!\n", ret);

        goto err_rdma_dest_wait;

    }



    ret = rdma_get_cm_event(rdma->channel, &cm_event);

    if (ret) {

        fprintf(stderr, "rdma_accept get_cm_event failed %d!\n", ret);

        goto err_rdma_dest_wait;

    }



    if (cm_event->event != RDMA_CM_EVENT_ESTABLISHED) {

        fprintf(stderr, "rdma_accept not event established!\n");

        rdma_ack_cm_event(cm_event);

        goto err_rdma_dest_wait;

    }



    rdma_ack_cm_event(cm_event);

    rdma->connected = true;



    ret = qemu_rdma_post_recv_control(rdma, RDMA_WRID_READY);

    if (ret) {

        fprintf(stderr, "rdma migration: error posting second control recv!\n");

        goto err_rdma_dest_wait;

    }



    qemu_rdma_dump_gid("dest_connect", rdma->cm_id);



    return 0;



err_rdma_dest_wait:

    rdma->error_state = ret;

    qemu_rdma_cleanup(rdma);

    return ret;

}

int inet_listen(const char *str, char *ostr, int olen,

                int socktype, int port_offset, Error **errp)

{

    QemuOpts *opts;

    char *optstr;

    int sock = -1;



    opts = qemu_opts_create(&dummy_opts, NULL, 0);

    if (inet_parse(opts, str) == 0) {

        sock = inet_listen_opts(opts, port_offset, errp);

        if (sock != -1 && ostr) {

            optstr = strchr(str, ',');

            if (qemu_opt_get_bool(opts, "ipv6", 0)) {

                snprintf(ostr, olen, "[%s]:%s%s",

                         qemu_opt_get(opts, "host"),

                         qemu_opt_get(opts, "port"),

                         optstr ? optstr : "");

            } else {

                snprintf(ostr, olen, "%s:%s%s",

                         qemu_opt_get(opts, "host"),

                         qemu_opt_get(opts, "port"),

                         optstr ? optstr : "");

            }

        }

    } else {

        error_set(errp, QERR_SOCKET_CREATE_FAILED);

    }

    qemu_opts_del(opts);

    return sock;

}

static void r2d_init(MachineState *machine)

{

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = machine->kernel_filename;

    const char *kernel_cmdline = machine->kernel_cmdline;

    const char *initrd_filename = machine->initrd_filename;

    SuperHCPU *cpu;

    CPUSH4State *env;

    ResetData *reset_info;

    struct SH7750State *s;

    MemoryRegion *sdram = g_new(MemoryRegion, 1);

    qemu_irq *irq;

    DriveInfo *dinfo;

    int i;

    DeviceState *dev;

    SysBusDevice *busdev;

    MemoryRegion *address_space_mem = get_system_memory();

    PCIBus *pci_bus;



    if (cpu_model == NULL) {

        cpu_model = "SH7751R";

    }



    cpu = cpu_sh4_init(cpu_model);

    if (cpu == NULL) {

        fprintf(stderr, "Unable to find CPU definition\n");

        exit(1);

    }

    env = &cpu->env;



    reset_info = g_malloc0(sizeof(ResetData));

    reset_info->cpu = cpu;

    reset_info->vector = env->pc;

    qemu_register_reset(main_cpu_reset, reset_info);



    /* Allocate memory space */

    memory_region_init_ram(sdram, NULL, "r2d.sdram", SDRAM_SIZE, &error_abort);

    vmstate_register_ram_global(sdram);

    memory_region_add_subregion(address_space_mem, SDRAM_BASE, sdram);

    /* Register peripherals */

    s = sh7750_init(cpu, address_space_mem);

    irq = r2d_fpga_init(address_space_mem, 0x04000000, sh7750_irl(s));



    dev = qdev_create(NULL, "sh_pci");

    busdev = SYS_BUS_DEVICE(dev);

    qdev_init_nofail(dev);

    pci_bus = PCI_BUS(qdev_get_child_bus(dev, "pci"));

    sysbus_mmio_map(busdev, 0, P4ADDR(0x1e200000));

    sysbus_mmio_map(busdev, 1, A7ADDR(0x1e200000));

    sysbus_connect_irq(busdev, 0, irq[PCI_INTA]);

    sysbus_connect_irq(busdev, 1, irq[PCI_INTB]);

    sysbus_connect_irq(busdev, 2, irq[PCI_INTC]);

    sysbus_connect_irq(busdev, 3, irq[PCI_INTD]);



    sm501_init(address_space_mem, 0x10000000, SM501_VRAM_SIZE,

               irq[SM501], serial_hds[2]);



    /* onboard CF (True IDE mode, Master only). */

    dinfo = drive_get(IF_IDE, 0, 0);

    dev = qdev_create(NULL, "mmio-ide");

    busdev = SYS_BUS_DEVICE(dev);

    sysbus_connect_irq(busdev, 0, irq[CF_IDE]);

    qdev_prop_set_uint32(dev, "shift", 1);

    qdev_init_nofail(dev);

    sysbus_mmio_map(busdev, 0, 0x14001000);

    sysbus_mmio_map(busdev, 1, 0x1400080c);

    mmio_ide_init_drives(dev, dinfo, NULL);



    /* onboard flash memory */

    dinfo = drive_get(IF_PFLASH, 0, 0);

    pflash_cfi02_register(0x0, NULL, "r2d.flash", FLASH_SIZE,

                          dinfo ? blk_by_legacy_dinfo(dinfo) : NULL,

                          (16 * 1024), FLASH_SIZE >> 16,

                          1, 4, 0x0000, 0x0000, 0x0000, 0x0000,

                          0x555, 0x2aa, 0);



    /* NIC: rtl8139 on-board, and 2 slots. */

    for (i = 0; i < nb_nics; i++)

        pci_nic_init_nofail(&nd_table[i], pci_bus,

                            "rtl8139", i==0 ? "2" : NULL);



    /* USB keyboard */

    usb_create_simple(usb_bus_find(-1), "usb-kbd");



    /* Todo: register on board registers */

    memset(&boot_params, 0, sizeof(boot_params));



    if (kernel_filename) {

        int kernel_size;



        kernel_size = load_image_targphys(kernel_filename,

                                          SDRAM_BASE + LINUX_LOAD_OFFSET,

                                          INITRD_LOAD_OFFSET - LINUX_LOAD_OFFSET);

        if (kernel_size < 0) {

          fprintf(stderr, "qemu: could not load kernel '%s'\n", kernel_filename);

          exit(1);

        }



        /* initialization which should be done by firmware */

        address_space_stl(&address_space_memory, SH7750_BCR1, 1 << 3,

                          MEMTXATTRS_UNSPECIFIED, NULL); /* cs3 SDRAM */

        address_space_stw(&address_space_memory, SH7750_BCR2, 3 << (3 * 2),

                          MEMTXATTRS_UNSPECIFIED, NULL); /* cs3 32bit */

        reset_info->vector = (SDRAM_BASE + LINUX_LOAD_OFFSET) | 0xa0000000; /* Start from P2 area */

    }



    if (initrd_filename) {

        int initrd_size;



        initrd_size = load_image_targphys(initrd_filename,

                                          SDRAM_BASE + INITRD_LOAD_OFFSET,

                                          SDRAM_SIZE - INITRD_LOAD_OFFSET);



        if (initrd_size < 0) {

          fprintf(stderr, "qemu: could not load initrd '%s'\n", initrd_filename);

          exit(1);

        }



        /* initialization which should be done by firmware */

        boot_params.loader_type = tswap32(1);

        boot_params.initrd_start = tswap32(INITRD_LOAD_OFFSET);

        boot_params.initrd_size = tswap32(initrd_size);

    }



    if (kernel_cmdline) {

        /* I see no evidence that this .kernel_cmdline buffer requires

           NUL-termination, so using strncpy should be ok. */

        strncpy(boot_params.kernel_cmdline, kernel_cmdline,

                sizeof(boot_params.kernel_cmdline));

    }



    rom_add_blob_fixed("boot_params", &boot_params, sizeof(boot_params),

                       SDRAM_BASE + BOOT_PARAMS_OFFSET);

}

static void menelaus_rtc_hz(void *opaque)

{

    struct menelaus_s *s = (struct menelaus_s *) opaque;



    s->rtc.next_comp --;

    s->rtc.alm_sec --;

    s->rtc.next += 1000;

    qemu_mod_timer(s->rtc.hz, s->rtc.next);

    if ((s->rtc.ctrl >> 3) & 3) {				/* EVERY */

        menelaus_rtc_update(s);

        if (((s->rtc.ctrl >> 3) & 3) == 1 && !s->rtc.tm.tm_sec)

            s->status |= 1 << 8;				/* RTCTMR */

        else if (((s->rtc.ctrl >> 3) & 3) == 2 && !s->rtc.tm.tm_min)

            s->status |= 1 << 8;				/* RTCTMR */

        else if (!s->rtc.tm.tm_hour)

            s->status |= 1 << 8;				/* RTCTMR */

    } else

        s->status |= 1 << 8;					/* RTCTMR */

    if ((s->rtc.ctrl >> 1) & 1) {				/* RTC_AL_EN */

        if (s->rtc.alm_sec == 0)

            s->status |= 1 << 9;				/* RTCALM */

        /* TODO: wake-up */

    }

    if (s->rtc.next_comp <= 0) {

        s->rtc.next -= muldiv64((int16_t) s->rtc.comp, 1000, 0x8000);

        s->rtc.next_comp = 3600;

    }

    menelaus_update(s);

}

