void cpu_loop(CPUMIPSState *env)

{

    CPUState *cs = CPU(mips_env_get_cpu(env));

    target_siginfo_t info;

    int trapnr;

    abi_long ret;

# ifdef TARGET_ABI_MIPSO32

    unsigned int syscall_num;

# endif



    for(;;) {

        cpu_exec_start(cs);

        trapnr = cpu_mips_exec(env);

        cpu_exec_end(cs);

        switch(trapnr) {

        case EXCP_SYSCALL:

            env->active_tc.PC += 4;

# ifdef TARGET_ABI_MIPSO32

            syscall_num = env->active_tc.gpr[2] - 4000;

            if (syscall_num >= sizeof(mips_syscall_args)) {

                ret = -TARGET_ENOSYS;

            } else {

                int nb_args;

                abi_ulong sp_reg;

                abi_ulong arg5 = 0, arg6 = 0, arg7 = 0, arg8 = 0;



                nb_args = mips_syscall_args[syscall_num];

                sp_reg = env->active_tc.gpr[29];

                switch (nb_args) {

                /* these arguments are taken from the stack */

                case 8:

                    if ((ret = get_user_ual(arg8, sp_reg + 28)) != 0) {

                        goto done_syscall;

                    }

                case 7:

                    if ((ret = get_user_ual(arg7, sp_reg + 24)) != 0) {

                        goto done_syscall;

                    }

                case 6:

                    if ((ret = get_user_ual(arg6, sp_reg + 20)) != 0) {

                        goto done_syscall;

                    }

                case 5:

                    if ((ret = get_user_ual(arg5, sp_reg + 16)) != 0) {

                        goto done_syscall;

                    }

                default:

                    break;

                }

                ret = do_syscall(env, env->active_tc.gpr[2],

                                 env->active_tc.gpr[4],

                                 env->active_tc.gpr[5],

                                 env->active_tc.gpr[6],

                                 env->active_tc.gpr[7],

                                 arg5, arg6, arg7, arg8);

            }

done_syscall:

# else

            ret = do_syscall(env, env->active_tc.gpr[2],

                             env->active_tc.gpr[4], env->active_tc.gpr[5],

                             env->active_tc.gpr[6], env->active_tc.gpr[7],

                             env->active_tc.gpr[8], env->active_tc.gpr[9],

                             env->active_tc.gpr[10], env->active_tc.gpr[11]);

# endif /* O32 */

            if (ret == -TARGET_QEMU_ESIGRETURN) {

                /* Returning from a successful sigreturn syscall.

                   Avoid clobbering register state.  */

                break;

            }

            if ((abi_ulong)ret >= (abi_ulong)-1133) {

                env->active_tc.gpr[7] = 1; /* error flag */

                ret = -ret;

            } else {

                env->active_tc.gpr[7] = 0; /* error flag */

            }

            env->active_tc.gpr[2] = ret;

            break;

        case EXCP_TLBL:

        case EXCP_TLBS:

        case EXCP_AdEL:

        case EXCP_AdES:

            info.si_signo = TARGET_SIGSEGV;

            info.si_errno = 0;

            /* XXX: check env->error_code */

            info.si_code = TARGET_SEGV_MAPERR;

            info._sifields._sigfault._addr = env->CP0_BadVAddr;

            queue_signal(env, info.si_signo, &info);

            break;

        case EXCP_CpU:

        case EXCP_RI:

            info.si_signo = TARGET_SIGILL;

            info.si_errno = 0;

            info.si_code = 0;

            queue_signal(env, info.si_signo, &info);

            break;

        case EXCP_INTERRUPT:

            /* just indicate that signals should be handled asap */

            break;

        case EXCP_DEBUG:

            {

                int sig;



                sig = gdb_handlesig(cs, TARGET_SIGTRAP);

                if (sig)

                  {

                    info.si_signo = sig;

                    info.si_errno = 0;

                    info.si_code = TARGET_TRAP_BRKPT;

                    queue_signal(env, info.si_signo, &info);

                  }

            }

            break;

        case EXCP_SC:

            if (do_store_exclusive(env)) {

                info.si_signo = TARGET_SIGSEGV;

                info.si_errno = 0;

                info.si_code = TARGET_SEGV_MAPERR;

                info._sifields._sigfault._addr = env->active_tc.PC;

                queue_signal(env, info.si_signo, &info);

            }

            break;

        case EXCP_DSPDIS:

            info.si_signo = TARGET_SIGILL;

            info.si_errno = 0;

            info.si_code = TARGET_ILL_ILLOPC;

            queue_signal(env, info.si_signo, &info);

            break;

        /* The code below was inspired by the MIPS Linux kernel trap

         * handling code in arch/mips/kernel/traps.c.

         */

        case EXCP_BREAK:

            {

                abi_ulong trap_instr;

                unsigned int code;



                if (env->hflags & MIPS_HFLAG_M16) {

                    if (env->insn_flags & ASE_MICROMIPS) {

                        /* microMIPS mode */

                        abi_ulong instr[2];



                        ret = get_user_u16(instr[0], env->active_tc.PC) ||

                              get_user_u16(instr[1], env->active_tc.PC + 2);



                        trap_instr = (instr[0] << 16) | instr[1];

                    } else {

                        /* MIPS16e mode */

                        ret = get_user_u16(trap_instr, env->active_tc.PC);

                        if (ret != 0) {

                            goto error;

                        }

                        code = (trap_instr >> 6) & 0x3f;

                        if (do_break(env, &info, code) != 0) {

                            goto error;

                        }

                        break;

                    }

                } else {

                    ret = get_user_ual(trap_instr, env->active_tc.PC);

                }



                if (ret != 0) {

                    goto error;

                }



                /* As described in the original Linux kernel code, the

                 * below checks on 'code' are to work around an old

                 * assembly bug.

                 */

                code = ((trap_instr >> 6) & ((1 << 20) - 1));

                if (code >= (1 << 10)) {

                    code >>= 10;

                }



                if (do_break(env, &info, code) != 0) {

                    goto error;

                }

            }

            break;

        case EXCP_TRAP:

            {

                abi_ulong trap_instr;

                unsigned int code = 0;



                if (env->hflags & MIPS_HFLAG_M16) {

                    /* microMIPS mode */

                    abi_ulong instr[2];



                    ret = get_user_u16(instr[0], env->active_tc.PC) ||

                          get_user_u16(instr[1], env->active_tc.PC + 2);



                    trap_instr = (instr[0] << 16) | instr[1];

                } else {

                    ret = get_user_ual(trap_instr, env->active_tc.PC);

                }



                if (ret != 0) {

                    goto error;

                }



                /* The immediate versions don't provide a code.  */

                if (!(trap_instr & 0xFC000000)) {

                    if (env->hflags & MIPS_HFLAG_M16) {

                        /* microMIPS mode */

                        code = ((trap_instr >> 12) & ((1 << 4) - 1));

                    } else {

                        code = ((trap_instr >> 6) & ((1 << 10) - 1));

                    }

                }



                if (do_break(env, &info, code) != 0) {

                    goto error;

                }

            }

            break;

        default:

error:

            fprintf(stderr, "qemu: unhandled CPU exception 0x%x - aborting\n",

                    trapnr);

            cpu_dump_state(cs, stderr, fprintf, 0);

            abort();

        }

        process_pending_signals(env);

    }

}

static void sd_reset(SDState *sd)

{

    uint64_t size;

    uint64_t sect;



    if (sd->blk) {

        blk_get_geometry(sd->blk, &sect);

    } else {

        sect = 0;

    }

    size = sect << 9;



    sect = sd_addr_to_wpnum(size) + 1;



    sd->state = sd_idle_state;

    sd->rca = 0x0000;

    sd_set_ocr(sd);

    sd_set_scr(sd);

    sd_set_cid(sd);

    sd_set_csd(sd, size);

    sd_set_cardstatus(sd);

    sd_set_sdstatus(sd);



    if (sd->wp_groups)

        g_free(sd->wp_groups);

    sd->wp_switch = sd->blk ? blk_is_read_only(sd->blk) : false;

    sd->wpgrps_size = sect;

    sd->wp_groups = bitmap_new(sd->wpgrps_size);

    memset(sd->function_group, 0, sizeof(sd->function_group));

    sd->erase_start = 0;

    sd->erase_end = 0;

    sd->size = size;

    sd->blk_len = 0x200;

    sd->pwd_len = 0;

    sd->expecting_acmd = false;

}

static void test_flush_event_notifier(void)

{

    EventNotifierTestData data = { .n = 0, .active = 10, .auto_set = true };

    event_notifier_init(&data.e, false);

    aio_set_event_notifier(ctx, &data.e, event_ready_cb);

    g_assert(!aio_poll(ctx, false));

    g_assert_cmpint(data.n, ==, 0);

    g_assert_cmpint(data.active, ==, 10);



    event_notifier_set(&data.e);

    g_assert(aio_poll(ctx, false));

    g_assert_cmpint(data.n, ==, 1);

    g_assert_cmpint(data.active, ==, 9);

    g_assert(aio_poll(ctx, false));



    wait_until_inactive(&data);

    g_assert_cmpint(data.n, ==, 10);

    g_assert_cmpint(data.active, ==, 0);

    g_assert(!aio_poll(ctx, false));



    aio_set_event_notifier(ctx, &data.e, NULL);

    g_assert(!aio_poll(ctx, false));

    event_notifier_cleanup(&data.e);

}

static inline void gen_intermediate_code_internal(X86CPU *cpu,

                                                  TranslationBlock *tb,

                                                  bool search_pc)

{

    CPUState *cs = CPU(cpu);

    CPUX86State *env = &cpu->env;

    DisasContext dc1, *dc = &dc1;

    target_ulong pc_ptr;

    uint16_t *gen_opc_end;

    CPUBreakpoint *bp;

    int j, lj;

    uint64_t flags;

    target_ulong pc_start;

    target_ulong cs_base;

    int num_insns;

    int max_insns;



    /* generate intermediate code */

    pc_start = tb->pc;

    cs_base = tb->cs_base;

    flags = tb->flags;



    dc->pe = (flags >> HF_PE_SHIFT) & 1;

    dc->code32 = (flags >> HF_CS32_SHIFT) & 1;

    dc->ss32 = (flags >> HF_SS32_SHIFT) & 1;

    dc->addseg = (flags >> HF_ADDSEG_SHIFT) & 1;

    dc->f_st = 0;

    dc->vm86 = (flags >> VM_SHIFT) & 1;

    dc->cpl = (flags >> HF_CPL_SHIFT) & 3;

    dc->iopl = (flags >> IOPL_SHIFT) & 3;

    dc->tf = (flags >> TF_SHIFT) & 1;

    dc->singlestep_enabled = cs->singlestep_enabled;

    dc->cc_op = CC_OP_DYNAMIC;

    dc->cc_op_dirty = false;

    dc->cs_base = cs_base;

    dc->tb = tb;

    dc->popl_esp_hack = 0;

    /* select memory access functions */

    dc->mem_index = 0;

    if (flags & HF_SOFTMMU_MASK) {

        dc->mem_index = cpu_mmu_index(env);

    }

    dc->cpuid_features = env->features[FEAT_1_EDX];

    dc->cpuid_ext_features = env->features[FEAT_1_ECX];

    dc->cpuid_ext2_features = env->features[FEAT_8000_0001_EDX];

    dc->cpuid_ext3_features = env->features[FEAT_8000_0001_ECX];

    dc->cpuid_7_0_ebx_features = env->features[FEAT_7_0_EBX];

#ifdef TARGET_X86_64

    dc->lma = (flags >> HF_LMA_SHIFT) & 1;

    dc->code64 = (flags >> HF_CS64_SHIFT) & 1;

#endif

    dc->flags = flags;

    dc->jmp_opt = !(dc->tf || cs->singlestep_enabled ||

                    (flags & HF_INHIBIT_IRQ_MASK)

#ifndef CONFIG_SOFTMMU

                    || (flags & HF_SOFTMMU_MASK)

#endif

                    );

    /* Do not optimize repz jumps at all in icount mode, because

       rep movsS instructions are execured with different paths

       in !repz_opt and repz_opt modes. The first one was used

       always except single step mode. And this setting

       disables jumps optimization and control paths become

       equivalent in run and single step modes.

       Now there will be no jump optimization for repz in

       record/replay modes and there will always be an

       additional step for ecx=0 when icount is enabled.

     */

    dc->repz_opt = !dc->jmp_opt && !(tb->cflags & CF_USE_ICOUNT);

#if 0

    /* check addseg logic */

    if (!dc->addseg && (dc->vm86 || !dc->pe || !dc->code32))

        printf("ERROR addseg\n");

#endif



    cpu_T[0] = tcg_temp_new();

    cpu_T[1] = tcg_temp_new();

    cpu_A0 = tcg_temp_new();



    cpu_tmp0 = tcg_temp_new();

    cpu_tmp1_i64 = tcg_temp_new_i64();

    cpu_tmp2_i32 = tcg_temp_new_i32();

    cpu_tmp3_i32 = tcg_temp_new_i32();

    cpu_tmp4 = tcg_temp_new();

    cpu_ptr0 = tcg_temp_new_ptr();

    cpu_ptr1 = tcg_temp_new_ptr();

    cpu_cc_srcT = tcg_temp_local_new();



    gen_opc_end = tcg_ctx.gen_opc_buf + OPC_MAX_SIZE;



    dc->is_jmp = DISAS_NEXT;

    pc_ptr = pc_start;

    lj = -1;

    num_insns = 0;

    max_insns = tb->cflags & CF_COUNT_MASK;

    if (max_insns == 0)

        max_insns = CF_COUNT_MASK;



    gen_tb_start();

    for(;;) {

        if (unlikely(!QTAILQ_EMPTY(&cs->breakpoints))) {

            QTAILQ_FOREACH(bp, &cs->breakpoints, entry) {

                if (bp->pc == pc_ptr &&

                    !((bp->flags & BP_CPU) && (tb->flags & HF_RF_MASK))) {

                    gen_debug(dc, pc_ptr - dc->cs_base);

                    goto done_generating;

                }

            }

        }

        if (search_pc) {

            j = tcg_ctx.gen_opc_ptr - tcg_ctx.gen_opc_buf;

            if (lj < j) {

                lj++;

                while (lj < j)

                    tcg_ctx.gen_opc_instr_start[lj++] = 0;

            }

            tcg_ctx.gen_opc_pc[lj] = pc_ptr;

            gen_opc_cc_op[lj] = dc->cc_op;

            tcg_ctx.gen_opc_instr_start[lj] = 1;

            tcg_ctx.gen_opc_icount[lj] = num_insns;

        }

        if (num_insns + 1 == max_insns && (tb->cflags & CF_LAST_IO))

            gen_io_start();



        pc_ptr = disas_insn(env, dc, pc_ptr);

        num_insns++;

        /* stop translation if indicated */

        if (dc->is_jmp)

            break;

        /* if single step mode, we generate only one instruction and

           generate an exception */

        /* if irq were inhibited with HF_INHIBIT_IRQ_MASK, we clear

           the flag and abort the translation to give the irqs a

           change to be happen */

        if (dc->tf || dc->singlestep_enabled ||

            (flags & HF_INHIBIT_IRQ_MASK)) {

            gen_jmp_im(pc_ptr - dc->cs_base);

            gen_eob(dc);

            break;

        }

        /* Do not cross the boundary of the pages in icount mode,

           it can cause an exception. Do it only when boundary is

           crossed by the first instruction in the block.

           If current instruction already crossed the bound - it's ok,

           because an exception hasn't stopped this code.

         */

        if ((tb->cflags & CF_USE_ICOUNT)

            && ((pc_ptr & TARGET_PAGE_MASK)

                != ((pc_ptr + TARGET_MAX_INSN_SIZE - 1) & TARGET_PAGE_MASK)

                || (pc_ptr & ~TARGET_PAGE_MASK) == 0)) {

            gen_jmp_im(pc_ptr - dc->cs_base);

            gen_eob(dc);

            break;

        }

        /* if too long translation, stop generation too */

        if (tcg_ctx.gen_opc_ptr >= gen_opc_end ||

            (pc_ptr - pc_start) >= (TARGET_PAGE_SIZE - 32) ||

            num_insns >= max_insns) {

            gen_jmp_im(pc_ptr - dc->cs_base);

            gen_eob(dc);

            break;

        }

        if (singlestep) {

            gen_jmp_im(pc_ptr - dc->cs_base);

            gen_eob(dc);

            break;

        }

    }

    if (tb->cflags & CF_LAST_IO)

        gen_io_end();

done_generating:

    gen_tb_end(tb, num_insns);

    *tcg_ctx.gen_opc_ptr = INDEX_op_end;

    /* we don't forget to fill the last values */

    if (search_pc) {

        j = tcg_ctx.gen_opc_ptr - tcg_ctx.gen_opc_buf;

        lj++;

        while (lj <= j)

            tcg_ctx.gen_opc_instr_start[lj++] = 0;

    }



#ifdef DEBUG_DISAS

    if (qemu_loglevel_mask(CPU_LOG_TB_IN_ASM)) {

        int disas_flags;

        qemu_log("----------------\n");

        qemu_log("IN: %s\n", lookup_symbol(pc_start));

#ifdef TARGET_X86_64

        if (dc->code64)

            disas_flags = 2;

        else

#endif

            disas_flags = !dc->code32;

        log_target_disas(env, pc_start, pc_ptr - pc_start, disas_flags);

        qemu_log("\n");

    }

#endif



    if (!search_pc) {

        tb->size = pc_ptr - pc_start;

        tb->icount = num_insns;

    }

}

CPUX86State *cpu_x86_init(const char *cpu_model)

{

    CPUX86State *env;

    static int inited;



    env = qemu_mallocz(sizeof(CPUX86State));

    cpu_exec_init(env);

    env->cpu_model_str = cpu_model;



    /* init various static tables */

    if (!inited) {

        inited = 1;

        optimize_flags_init();

#ifndef CONFIG_USER_ONLY

        prev_debug_excp_handler =

            cpu_set_debug_excp_handler(breakpoint_handler);

#endif

    }

    if (cpu_x86_register(env, cpu_model) < 0) {

        cpu_x86_close(env);

        return NULL;

    }

    mce_init(env);

    cpu_reset(env);

#ifdef CONFIG_KQEMU

    kqemu_init(env);

#endif



    qemu_init_vcpu(env);



    return env;

}

static void x86_cpuid_set_apic_id(Object *obj, Visitor *v, const char *name,

                                  void *opaque, Error **errp)

{

    X86CPU *cpu = X86_CPU(obj);

    DeviceState *dev = DEVICE(obj);

    const int64_t min = 0;

    const int64_t max = UINT32_MAX;

    Error *error = NULL;

    int64_t value;



    if (dev->realized) {

        error_setg(errp, "Attempt to set property '%s' on '%s' after "

                   "it was realized", name, object_get_typename(obj));

        return;

    }



    visit_type_int(v, name, &value, &error);

    if (error) {

        error_propagate(errp, error);

        return;

    }

    if (value < min || value > max) {

        error_setg(errp, "Property %s.%s doesn't take value %" PRId64

                   " (minimum: %" PRId64 ", maximum: %" PRId64 ")" ,

                   object_get_typename(obj), name, value, min, max);

        return;

    }



    if ((value != cpu->apic_id) && cpu_exists(value)) {

        error_setg(errp, "CPU with APIC ID %" PRIi64 " exists", value);

        return;

    }

    cpu->apic_id = value;

}

static bool tcg_out_opc_jmp(TCGContext *s, MIPSInsn opc, void *target)

{

    uintptr_t dest = (uintptr_t)target;

    uintptr_t from = (uintptr_t)s->code_ptr + 4;

    int32_t inst;



    /* The pc-region branch happens within the 256MB region of

       the delay slot (thus the +4).  */

    if ((from ^ dest) & -(1 << 28)) {

        return false;

    }

    assert((dest & 3) == 0);



    inst = opc;

    inst |= (dest >> 2) & 0x3ffffff;

    tcg_out32(s, inst);

    return true;

}

