static uint32_t grlib_gptimer_readl(void *opaque, target_phys_addr_t addr)

{

    GPTimerUnit        *unit  = opaque;

    target_phys_addr_t  timer_addr;

    int                 id;

    uint32_t            value = 0;



    addr &= 0xff;



    /* Unit registers */

    switch (addr) {

    case SCALER_OFFSET:

        trace_grlib_gptimer_readl(-1, "scaler:", unit->scaler);

        return unit->scaler;



    case SCALER_RELOAD_OFFSET:

        trace_grlib_gptimer_readl(-1, "reload:", unit->reload);

        return unit->reload;



    case CONFIG_OFFSET:

        trace_grlib_gptimer_readl(-1, "config:", unit->config);

        return unit->config;



    default:

        break;

    }



    timer_addr = (addr % TIMER_BASE);

    id         = (addr - TIMER_BASE) / TIMER_BASE;



    if (id >= 0 && id < unit->nr_timers) {



        /* GPTimer registers */

        switch (timer_addr) {

        case COUNTER_OFFSET:

            value = ptimer_get_count(unit->timers[id].ptimer);

            trace_grlib_gptimer_readl(id, "counter value:", value);

            return value;



        case COUNTER_RELOAD_OFFSET:

            value = unit->timers[id].reload;

            trace_grlib_gptimer_readl(id, "reload value:", value);

            return value;



        case CONFIG_OFFSET:

            trace_grlib_gptimer_readl(id, "scaler value:",

                                      unit->timers[id].config);

            return unit->timers[id].config;



        default:

            break;

        }



    }



    trace_grlib_gptimer_unknown_register("read", addr);

    return 0;

}

static ram_addr_t find_ram_offset(ram_addr_t size)

{

    RAMBlock *block, *next_block;

    ram_addr_t offset, mingap = ULONG_MAX;



    if (QLIST_EMPTY(&ram_list.blocks))

        return 0;



    QLIST_FOREACH(block, &ram_list.blocks, next) {

        ram_addr_t end, next = ULONG_MAX;



        end = block->offset + block->length;



        QLIST_FOREACH(next_block, &ram_list.blocks, next) {

            if (next_block->offset >= end) {

                next = MIN(next, next_block->offset);

            }

        }

        if (next - end >= size && next - end < mingap) {

            offset =  end;

            mingap = next - end;

        }

    }

    return offset;

}

Coroutine *qemu_coroutine_create(CoroutineEntry *entry)

{

    Coroutine *co = NULL;



    if (CONFIG_COROUTINE_POOL) {

        co = QSLIST_FIRST(&alloc_pool);

        if (!co) {

            if (release_pool_size > POOL_BATCH_SIZE) {

                /* Slow path; a good place to register the destructor, too.  */

                if (!coroutine_pool_cleanup_notifier.notify) {

                    coroutine_pool_cleanup_notifier.notify = coroutine_pool_cleanup;

                    qemu_thread_atexit_add(&coroutine_pool_cleanup_notifier);

                }



                /* This is not exact; there could be a little skew between

                 * release_pool_size and the actual size of release_pool.  But

                 * it is just a heuristic, it does not need to be perfect.

                 */

                alloc_pool_size = atomic_xchg(&release_pool_size, 0);

                QSLIST_MOVE_ATOMIC(&alloc_pool, &release_pool);

                co = QSLIST_FIRST(&alloc_pool);

            }

        }

        if (co) {

            QSLIST_REMOVE_HEAD(&alloc_pool, pool_next);

            alloc_pool_size--;

        }

    }



    if (!co) {

        co = qemu_coroutine_new();

    }



    co->entry = entry;

    QSIMPLEQ_INIT(&co->co_queue_wakeup);

    return co;

}

static void pxa2xx_gpio_write(void *opaque,

                target_phys_addr_t offset, uint32_t value)

{

    struct pxa2xx_gpio_info_s *s = (struct pxa2xx_gpio_info_s *) opaque;

    int bank;

    offset -= s->base;

    if (offset >= 0x200)

        return;



    bank = pxa2xx_gpio_regs[offset].bank;

    switch (pxa2xx_gpio_regs[offset].reg) {

    case GPDR:		/* GPIO Pin-Direction registers */

        s->dir[bank] = value;

        pxa2xx_gpio_handler_update(s);

        break;



    case GPSR:		/* GPIO Pin-Output Set registers */

        s->olevel[bank] |= value;

        pxa2xx_gpio_handler_update(s);


        break;



    case GPCR:		/* GPIO Pin-Output Clear registers */

        s->olevel[bank] &= ~value;

        pxa2xx_gpio_handler_update(s);

        break;



    case GRER:		/* GPIO Rising-Edge Detect Enable registers */

        s->rising[bank] = value;

        break;



    case GFER:		/* GPIO Falling-Edge Detect Enable registers */

        s->falling[bank] = value;

        break;



    case GAFR_L:	/* GPIO Alternate Function registers */

        s->gafr[bank * 2] = value;

        break;



    case GAFR_U:	/* GPIO Alternate Function registers */

        s->gafr[bank * 2 + 1] = value;

        break;



    case GEDR:		/* GPIO Edge Detect Status registers */

        s->status[bank] &= ~value;

        pxa2xx_gpio_irq_update(s);

        break;



    default:

        cpu_abort(cpu_single_env,

                "%s: Bad offset " REG_FMT "\n", __FUNCTION__, offset);

    }

}

static void coroutine_fn v9fs_flush(void *opaque)

{

    ssize_t err;

    int16_t tag;

    size_t offset = 7;

    V9fsPDU *cancel_pdu;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    err = pdu_unmarshal(pdu, offset, "w", &tag);

    if (err < 0) {

        pdu_complete(pdu, err);

        return;

    }

    trace_v9fs_flush(pdu->tag, pdu->id, tag);



    QLIST_FOREACH(cancel_pdu, &s->active_list, next) {

        if (cancel_pdu->tag == tag) {

            break;

        }

    }

    if (cancel_pdu) {

        cancel_pdu->cancelled = 1;

        /*

         * Wait for pdu to complete.

         */

        qemu_co_queue_wait(&cancel_pdu->complete, NULL);

        cancel_pdu->cancelled = 0;

        pdu_free(cancel_pdu);

    }

    pdu_complete(pdu, 7);

}

