static void *rcu_read_stress_test(void *arg)

{

    int i;

    int itercnt = 0;

    struct rcu_stress *p;

    int pc;

    long long n_reads_local = 0;

    volatile int garbage = 0;



    rcu_register_thread();



    *(struct rcu_reader_data **)arg = &rcu_reader;

    while (goflag == GOFLAG_INIT) {

        g_usleep(1000);

    }

    while (goflag == GOFLAG_RUN) {

        rcu_read_lock();

        p = atomic_rcu_read(&rcu_stress_current);

        if (p->mbtest == 0) {

            n_mberror++;

        }

        rcu_read_lock();

        for (i = 0; i < 100; i++) {

            garbage++;

        }

        rcu_read_unlock();

        pc = p->pipe_count;

        rcu_read_unlock();

        if ((pc > RCU_STRESS_PIPE_LEN) || (pc < 0)) {

            pc = RCU_STRESS_PIPE_LEN;

        }

        atomic_inc(&rcu_stress_count[pc]);

        n_reads_local++;

        if ((++itercnt % 0x1000) == 0) {

            synchronize_rcu();

        }

    }

    atomic_add(&n_reads, n_reads_local);



    rcu_unregister_thread();

    return NULL;

}

static void rtc_realizefn(DeviceState *dev, Error **errp)

{

    ISADevice *isadev = ISA_DEVICE(dev);

    RTCState *s = MC146818_RTC(dev);

    int base = 0x70;



    s->cmos_data[RTC_REG_A] = 0x26;

    s->cmos_data[RTC_REG_B] = 0x02;

    s->cmos_data[RTC_REG_C] = 0x00;

    s->cmos_data[RTC_REG_D] = 0x80;



    /* This is for historical reasons.  The default base year qdev property

     * was set to 2000 for most machine types before the century byte was

     * implemented.

     *

     * This if statement means that the century byte will be always 0

     * (at least until 2079...) for base_year = 1980, but will be set

     * correctly for base_year = 2000.

     */

    if (s->base_year == 2000) {

        s->base_year = 0;

    }



    rtc_set_date_from_host(isadev);



#ifdef TARGET_I386

    switch (s->lost_tick_policy) {

    case LOST_TICK_POLICY_SLEW:

        s->coalesced_timer =

            timer_new_ns(rtc_clock, rtc_coalesced_timer, s);

        break;

    case LOST_TICK_POLICY_DISCARD:

        break;

    default:

        error_setg(errp, "Invalid lost tick policy.");

        return;

    }

#endif



    s->periodic_timer = timer_new_ns(rtc_clock, rtc_periodic_timer, s);

    s->update_timer = timer_new_ns(rtc_clock, rtc_update_timer, s);

    check_update_timer(s);



    s->clock_reset_notifier.notify = rtc_notify_clock_reset;

    qemu_clock_register_reset_notifier(rtc_clock,

                                       &s->clock_reset_notifier);



    s->suspend_notifier.notify = rtc_notify_suspend;

    qemu_register_suspend_notifier(&s->suspend_notifier);



    memory_region_init_io(&s->io, OBJECT(s), &cmos_ops, s, "rtc", 2);

    isa_register_ioport(isadev, &s->io, base);



    qdev_set_legacy_instance_id(dev, base, 3);

    qemu_register_reset(rtc_reset, s);



    object_property_add(OBJECT(s), "date", "struct tm",

                        rtc_get_date, NULL, NULL, s, NULL);



    object_property_add_alias(qdev_get_machine(), "rtc-time",

                              OBJECT(s), "date", NULL);

}

static void palmte_init(ram_addr_t ram_size, int vga_ram_size,

                const char *boot_device,

                const char *kernel_filename, const char *kernel_cmdline,

                const char *initrd_filename, const char *cpu_model)

{

    struct omap_mpu_state_s *cpu;

    int flash_size = 0x00800000;

    int sdram_size = palmte_binfo.ram_size;

    int io;

    static uint32_t cs0val = 0xffffffff;

    static uint32_t cs1val = 0x0000e1a0;

    static uint32_t cs2val = 0x0000e1a0;

    static uint32_t cs3val = 0xe1a0e1a0;

    ram_addr_t phys_flash;

    int rom_size, rom_loaded = 0;

    DisplayState *ds = get_displaystate();



    if (ram_size < flash_size + sdram_size + OMAP15XX_SRAM_SIZE) {

        fprintf(stderr, "This architecture uses %i bytes of memory\n",

                        flash_size + sdram_size + OMAP15XX_SRAM_SIZE);

        exit(1);

    }



    cpu = omap310_mpu_init(sdram_size, cpu_model);



    /* External Flash (EMIFS) */

    cpu_register_physical_memory(OMAP_CS0_BASE, flash_size,

                    (phys_flash = qemu_ram_alloc(flash_size)) | IO_MEM_ROM);



    io = cpu_register_io_memory(0, static_readfn, static_writefn, &cs0val);

    cpu_register_physical_memory(OMAP_CS0_BASE + flash_size,

                    OMAP_CS0_SIZE - flash_size, io);

    io = cpu_register_io_memory(0, static_readfn, static_writefn, &cs1val);

    cpu_register_physical_memory(OMAP_CS1_BASE, OMAP_CS1_SIZE, io);

    io = cpu_register_io_memory(0, static_readfn, static_writefn, &cs2val);

    cpu_register_physical_memory(OMAP_CS2_BASE, OMAP_CS2_SIZE, io);

    io = cpu_register_io_memory(0, static_readfn, static_writefn, &cs3val);

    cpu_register_physical_memory(OMAP_CS3_BASE, OMAP_CS3_SIZE, io);



    palmte_microwire_setup(cpu);



    qemu_add_kbd_event_handler(palmte_button_event, cpu);



    palmte_gpio_setup(cpu);



    /* Setup initial (reset) machine state */

    if (nb_option_roms) {

        rom_size = get_image_size(option_rom[0]);

        if (rom_size > flash_size) {

            fprintf(stderr, "%s: ROM image too big (%x > %x)\n",

                            __FUNCTION__, rom_size, flash_size);

            rom_size = 0;

        }

        if (rom_size > 0) {

            rom_size = load_image_targphys(option_rom[0], OMAP_CS0_BASE,

                                           flash_size);

            rom_loaded = 1;

            cpu->env->regs[15] = 0x00000000;

        }

        if (rom_size < 0) {

            fprintf(stderr, "%s: error loading '%s'\n",

                            __FUNCTION__, option_rom[0]);

        }

    }



    if (!rom_loaded && !kernel_filename) {

        fprintf(stderr, "Kernel or ROM image must be specified\n");

        exit(1);

    }



    /* Load the kernel.  */

    if (kernel_filename) {

        /* Start at bootloader.  */

        cpu->env->regs[15] = palmte_binfo.loader_start;



        palmte_binfo.kernel_filename = kernel_filename;

        palmte_binfo.kernel_cmdline = kernel_cmdline;

        palmte_binfo.initrd_filename = initrd_filename;

        arm_load_kernel(cpu->env, &palmte_binfo);

    }



    /* FIXME: We shouldn't really be doing this here.  The LCD controller

       will set the size once configured, so this just sets an initial

       size until the guest activates the display.  */

    ds->surface = qemu_resize_displaysurface(ds, 320, 320);

    dpy_resize(ds);

}

static void menelaus_save(QEMUFile *f, void *opaque)

{

    MenelausState *s = (MenelausState *) opaque;



    qemu_put_be32(f, s->firstbyte);

    qemu_put_8s(f, &s->reg);



    qemu_put_8s(f, &s->vcore[0]);

    qemu_put_8s(f, &s->vcore[1]);

    qemu_put_8s(f, &s->vcore[2]);

    qemu_put_8s(f, &s->vcore[3]);

    qemu_put_8s(f, &s->vcore[4]);

    qemu_put_8s(f, &s->dcdc[0]);

    qemu_put_8s(f, &s->dcdc[1]);

    qemu_put_8s(f, &s->dcdc[2]);

    qemu_put_8s(f, &s->ldo[0]);

    qemu_put_8s(f, &s->ldo[1]);

    qemu_put_8s(f, &s->ldo[2]);

    qemu_put_8s(f, &s->ldo[3]);

    qemu_put_8s(f, &s->ldo[4]);

    qemu_put_8s(f, &s->ldo[5]);

    qemu_put_8s(f, &s->ldo[6]);

    qemu_put_8s(f, &s->ldo[7]);

    qemu_put_8s(f, &s->sleep[0]);

    qemu_put_8s(f, &s->sleep[1]);

    qemu_put_8s(f, &s->osc);

    qemu_put_8s(f, &s->detect);

    qemu_put_be16s(f, &s->mask);

    qemu_put_be16s(f, &s->status);

    qemu_put_8s(f, &s->dir);

    qemu_put_8s(f, &s->inputs);

    qemu_put_8s(f, &s->outputs);

    qemu_put_8s(f, &s->bbsms);

    qemu_put_8s(f, &s->pull[0]);

    qemu_put_8s(f, &s->pull[1]);

    qemu_put_8s(f, &s->pull[2]);

    qemu_put_8s(f, &s->pull[3]);

    qemu_put_8s(f, &s->mmc_ctrl[0]);

    qemu_put_8s(f, &s->mmc_ctrl[1]);

    qemu_put_8s(f, &s->mmc_ctrl[2]);

    qemu_put_8s(f, &s->mmc_debounce);

    qemu_put_8s(f, &s->rtc.ctrl);

    qemu_put_be16s(f, &s->rtc.comp);

    /* Should be <= 1000 */

    qemu_put_be16(f, s->rtc.next - qemu_get_clock(rt_clock));

    tm_put(f, &s->rtc.new);

    tm_put(f, &s->rtc.alm);

    qemu_put_byte(f, s->pwrbtn_state);



    i2c_slave_save(f, &s->i2c);

}

