static void openpic_update_irq(OpenPICState *opp, int n_IRQ)

{

    IRQSource *src;

    bool active, was_active;

    int i;



    src = &opp->src[n_IRQ];

    active = src->pending;



    if ((src->ivpr & IVPR_MASK_MASK) && !src->nomask) {

        /* Interrupt source is disabled */

        DPRINTF("%s: IRQ %d is disabled\n", __func__, n_IRQ);

        active = false;

    }



    was_active = !!(src->ivpr & IVPR_ACTIVITY_MASK);



    /*

     * We don't have a similar check for already-active because

     * ctpr may have changed and we need to withdraw the interrupt.

     */

    if (!active && !was_active) {

        DPRINTF("%s: IRQ %d is already inactive\n", __func__, n_IRQ);

        return;

    }



    if (active) {

        src->ivpr |= IVPR_ACTIVITY_MASK;

    } else {

        src->ivpr &= ~IVPR_ACTIVITY_MASK;

    }



    if (src->idr == 0) {

        /* No target */

        DPRINTF("%s: IRQ %d has no target\n", __func__, n_IRQ);

        return;

    }



    if (src->idr == (1 << src->last_cpu)) {

        /* Only one CPU is allowed to receive this IRQ */

        IRQ_local_pipe(opp, src->last_cpu, n_IRQ, active, was_active);

    } else if (!(src->ivpr & IVPR_MODE_MASK)) {

        /* Directed delivery mode */

        for (i = 0; i < opp->nb_cpus; i++) {

            if (src->destmask & (1 << i)) {

                IRQ_local_pipe(opp, i, n_IRQ, active, was_active);

            }

        }

    } else {

        /* Distributed delivery mode */

        for (i = src->last_cpu + 1; i != src->last_cpu; i++) {

            if (i == opp->nb_cpus) {

                i = 0;

            }

            if (src->destmask & (1 << i)) {

                IRQ_local_pipe(opp, i, n_IRQ, active, was_active);

                src->last_cpu = i;

                break;

            }

        }

    }

}

void dpy_gfx_update_dirty(QemuConsole *con,

                          MemoryRegion *address_space,

                          hwaddr base,

                          bool invalidate)

{

    DisplaySurface *ds = qemu_console_surface(con);

    int width = surface_stride(ds);

    int height = surface_height(ds);

    hwaddr size = width * height;

    MemoryRegionSection mem_section;

    MemoryRegion *mem;

    ram_addr_t addr;

    int first, last, i;

    bool dirty;



    mem_section = memory_region_find(address_space, base, size);

    mem = mem_section.mr;

    if (int128_get64(mem_section.size) != size ||

        !memory_region_is_ram(mem_section.mr)) {

        goto out;

    }

    assert(mem);



    memory_region_sync_dirty_bitmap(mem);

    addr = mem_section.offset_within_region;



    first = -1;

    last = -1;

    for (i = 0; i < height; i++, addr += width) {

        dirty = invalidate ||

            memory_region_get_dirty(mem, addr, width, DIRTY_MEMORY_VGA);

        if (dirty) {

            if (first == -1) {

                first = i;

            }

            last = i;

        }

        if (first != -1 && !dirty) {

            assert(last != -1 && last >= first);

            dpy_gfx_update(con, 0, first, surface_width(ds),

                           last - first + 1);

            first = -1;

        }

    }

    if (first != -1) {

        assert(last != -1 && last >= first);

        dpy_gfx_update(con, 0, first, surface_width(ds),

                       last - first + 1);

    }



    memory_region_reset_dirty(mem, mem_section.offset_within_region, size,

                              DIRTY_MEMORY_VGA);

out:

    memory_region_unref(mem);

}

static void pci_dev_get_w64(PCIBus *b, PCIDevice *dev, void *opaque)

{

    Range *range = opaque;

    PCIDeviceClass *pc = PCI_DEVICE_GET_CLASS(dev);

    uint16_t cmd = pci_get_word(dev->config + PCI_COMMAND);

    int i;



    if (!(cmd & PCI_COMMAND_MEMORY)) {

        return;

    }



    if (pc->is_bridge) {

        pcibus_t base = pci_bridge_get_base(dev, PCI_BASE_ADDRESS_MEM_PREFETCH);

        pcibus_t limit = pci_bridge_get_limit(dev, PCI_BASE_ADDRESS_MEM_PREFETCH);



        base = MAX(base, 0x1ULL << 32);



        if (limit >= base) {

            Range pref_range;

            pref_range.begin = base;

            pref_range.end = limit + 1;

            range_extend(range, &pref_range);

        }

    }

    for (i = 0; i < PCI_NUM_REGIONS; ++i) {

        PCIIORegion *r = &dev->io_regions[i];

        Range region_range;



        if (!r->size ||

            (r->type & PCI_BASE_ADDRESS_SPACE_IO) ||

            !(r->type & PCI_BASE_ADDRESS_MEM_TYPE_64)) {

            continue;

        }

        region_range.begin = pci_bar_address(dev, i, r->type, r->size);

        region_range.end = region_range.begin + r->size;



        if (region_range.begin == PCI_BAR_UNMAPPED) {

            continue;

        }



        region_range.begin = MAX(region_range.begin, 0x1ULL << 32);



        if (region_range.end - 1 >= region_range.begin) {

            range_extend(range, &region_range);

        }

    }

}

cryptodev_builtin_get_aes_algo(uint32_t key_len, Error **errp)

{

    int algo;



    if (key_len == 128 / 8) {

        algo = QCRYPTO_CIPHER_ALG_AES_128;

    } else if (key_len == 192 / 8) {

        algo = QCRYPTO_CIPHER_ALG_AES_192;

    } else if (key_len == 256 / 8) {

        algo = QCRYPTO_CIPHER_ALG_AES_256;

    } else {

        error_setg(errp, "Unsupported key length :%u", key_len);

        return -1;

    }



    return algo;

}

static int sd_snapshot_list(BlockDriverState *bs, QEMUSnapshotInfo **psn_tab)

{

    BDRVSheepdogState *s = bs->opaque;

    SheepdogReq req;

    int fd, nr = 1024, ret, max = BITS_TO_LONGS(SD_NR_VDIS) * sizeof(long);

    QEMUSnapshotInfo *sn_tab = NULL;

    unsigned wlen, rlen;

    int found = 0;

    static SheepdogInode inode;

    unsigned long *vdi_inuse;

    unsigned int start_nr;

    uint64_t hval;

    uint32_t vid;



    vdi_inuse = g_malloc(max);



    fd = connect_to_sdog(s->addr, s->port);

    if (fd < 0) {

        ret = fd;

        goto out;

    }



    rlen = max;

    wlen = 0;



    memset(&req, 0, sizeof(req));



    req.opcode = SD_OP_READ_VDIS;

    req.data_length = max;



    ret = do_req(fd, (SheepdogReq *)&req, vdi_inuse, &wlen, &rlen);



    closesocket(fd);

    if (ret) {

        goto out;

    }



    sn_tab = g_malloc0(nr * sizeof(*sn_tab));



    /* calculate a vdi id with hash function */

    hval = fnv_64a_buf(s->name, strlen(s->name), FNV1A_64_INIT);

    start_nr = hval & (SD_NR_VDIS - 1);



    fd = connect_to_sdog(s->addr, s->port);

    if (fd < 0) {

        error_report("failed to connect");

        ret = fd;

        goto out;

    }



    for (vid = start_nr; found < nr; vid = (vid + 1) % SD_NR_VDIS) {

        if (!test_bit(vid, vdi_inuse)) {

            break;

        }



        /* we don't need to read entire object */

        ret = read_object(fd, (char *)&inode, vid_to_vdi_oid(vid),

                          0, SD_INODE_SIZE - sizeof(inode.data_vdi_id), 0,

                          s->cache_enabled);



        if (ret) {

            continue;

        }



        if (!strcmp(inode.name, s->name) && is_snapshot(&inode)) {

            sn_tab[found].date_sec = inode.snap_ctime >> 32;

            sn_tab[found].date_nsec = inode.snap_ctime & 0xffffffff;

            sn_tab[found].vm_state_size = inode.vm_state_size;

            sn_tab[found].vm_clock_nsec = inode.vm_clock_nsec;



            snprintf(sn_tab[found].id_str, sizeof(sn_tab[found].id_str), "%u",

                     inode.snap_id);

            pstrcpy(sn_tab[found].name,

                    MIN(sizeof(sn_tab[found].name), sizeof(inode.tag)),

                    inode.tag);

            found++;

        }

    }



    closesocket(fd);

out:

    *psn_tab = sn_tab;



    g_free(vdi_inuse);



    if (ret < 0) {

        return ret;

    }



    return found;

}

static void versatile_init(MachineState *machine, int board_id)

{

    ARMCPU *cpu;

    MemoryRegion *sysmem = get_system_memory();

    MemoryRegion *ram = g_new(MemoryRegion, 1);

    qemu_irq pic[32];

    qemu_irq sic[32];

    DeviceState *dev, *sysctl;

    SysBusDevice *busdev;

    DeviceState *pl041;

    PCIBus *pci_bus;

    NICInfo *nd;

    I2CBus *i2c;

    int n;

    int done_smc = 0;

    DriveInfo *dinfo;



    if (!machine->cpu_model) {

        machine->cpu_model = "arm926";

    }

    cpu = cpu_arm_init(machine->cpu_model);

    if (!cpu) {

        fprintf(stderr, "Unable to find CPU definition\n");

        exit(1);

    }

    memory_region_init_ram(ram, NULL, "versatile.ram", machine->ram_size,

                           &error_abort);

    vmstate_register_ram_global(ram);

    /* ??? RAM should repeat to fill physical memory space.  */

    /* SDRAM at address zero.  */

    memory_region_add_subregion(sysmem, 0, ram);



    sysctl = qdev_create(NULL, "realview_sysctl");

    qdev_prop_set_uint32(sysctl, "sys_id", 0x41007004);

    qdev_prop_set_uint32(sysctl, "proc_id", 0x02000000);

    qdev_init_nofail(sysctl);

    sysbus_mmio_map(SYS_BUS_DEVICE(sysctl), 0, 0x10000000);



    dev = sysbus_create_varargs("pl190", 0x10140000,

                                qdev_get_gpio_in(DEVICE(cpu), ARM_CPU_IRQ),

                                qdev_get_gpio_in(DEVICE(cpu), ARM_CPU_FIQ),

                                NULL);

    for (n = 0; n < 32; n++) {

        pic[n] = qdev_get_gpio_in(dev, n);

    }

    dev = sysbus_create_simple(TYPE_VERSATILE_PB_SIC, 0x10003000, NULL);

    for (n = 0; n < 32; n++) {

        sysbus_connect_irq(SYS_BUS_DEVICE(dev), n, pic[n]);

        sic[n] = qdev_get_gpio_in(dev, n);

    }



    sysbus_create_simple("pl050_keyboard", 0x10006000, sic[3]);

    sysbus_create_simple("pl050_mouse", 0x10007000, sic[4]);



    dev = qdev_create(NULL, "versatile_pci");

    busdev = SYS_BUS_DEVICE(dev);

    qdev_init_nofail(dev);

    sysbus_mmio_map(busdev, 0, 0x10001000); /* PCI controller regs */

    sysbus_mmio_map(busdev, 1, 0x41000000); /* PCI self-config */

    sysbus_mmio_map(busdev, 2, 0x42000000); /* PCI config */

    sysbus_mmio_map(busdev, 3, 0x43000000); /* PCI I/O */

    sysbus_mmio_map(busdev, 4, 0x44000000); /* PCI memory window 1 */

    sysbus_mmio_map(busdev, 5, 0x50000000); /* PCI memory window 2 */

    sysbus_mmio_map(busdev, 6, 0x60000000); /* PCI memory window 3 */

    sysbus_connect_irq(busdev, 0, sic[27]);

    sysbus_connect_irq(busdev, 1, sic[28]);

    sysbus_connect_irq(busdev, 2, sic[29]);

    sysbus_connect_irq(busdev, 3, sic[30]);

    pci_bus = (PCIBus *)qdev_get_child_bus(dev, "pci");



    for(n = 0; n < nb_nics; n++) {

        nd = &nd_table[n];



        if (!done_smc && (!nd->model || strcmp(nd->model, "smc91c111") == 0)) {

            smc91c111_init(nd, 0x10010000, sic[25]);

            done_smc = 1;

        } else {

            pci_nic_init_nofail(nd, pci_bus, "rtl8139", NULL);

        }

    }

    if (usb_enabled(false)) {

        pci_create_simple(pci_bus, -1, "pci-ohci");

    }

    n = drive_get_max_bus(IF_SCSI);

    while (n >= 0) {

        pci_create_simple(pci_bus, -1, "lsi53c895a");

        n--;

    }



    sysbus_create_simple("pl011", 0x101f1000, pic[12]);

    sysbus_create_simple("pl011", 0x101f2000, pic[13]);

    sysbus_create_simple("pl011", 0x101f3000, pic[14]);

    sysbus_create_simple("pl011", 0x10009000, sic[6]);



    sysbus_create_simple("pl080", 0x10130000, pic[17]);

    sysbus_create_simple("sp804", 0x101e2000, pic[4]);

    sysbus_create_simple("sp804", 0x101e3000, pic[5]);



    sysbus_create_simple("pl061", 0x101e4000, pic[6]);

    sysbus_create_simple("pl061", 0x101e5000, pic[7]);

    sysbus_create_simple("pl061", 0x101e6000, pic[8]);

    sysbus_create_simple("pl061", 0x101e7000, pic[9]);



    /* The versatile/PB actually has a modified Color LCD controller

       that includes hardware cursor support from the PL111.  */

    dev = sysbus_create_simple("pl110_versatile", 0x10120000, pic[16]);

    /* Wire up the mux control signals from the SYS_CLCD register */

    qdev_connect_gpio_out(sysctl, 0, qdev_get_gpio_in(dev, 0));



    sysbus_create_varargs("pl181", 0x10005000, sic[22], sic[1], NULL);

    sysbus_create_varargs("pl181", 0x1000b000, sic[23], sic[2], NULL);



    /* Add PL031 Real Time Clock. */

    sysbus_create_simple("pl031", 0x101e8000, pic[10]);



    dev = sysbus_create_simple("versatile_i2c", 0x10002000, NULL);

    i2c = (I2CBus *)qdev_get_child_bus(dev, "i2c");

    i2c_create_slave(i2c, "ds1338", 0x68);



    /* Add PL041 AACI Interface to the LM4549 codec */

    pl041 = qdev_create(NULL, "pl041");

    qdev_prop_set_uint32(pl041, "nc_fifo_depth", 512);

    qdev_init_nofail(pl041);

    sysbus_mmio_map(SYS_BUS_DEVICE(pl041), 0, 0x10004000);

    sysbus_connect_irq(SYS_BUS_DEVICE(pl041), 0, sic[24]);



    /* Memory map for Versatile/PB:  */

    /* 0x10000000 System registers.  */

    /* 0x10001000 PCI controller config registers.  */

    /* 0x10002000 Serial bus interface.  */

    /*  0x10003000 Secondary interrupt controller.  */

    /* 0x10004000 AACI (audio).  */

    /*  0x10005000 MMCI0.  */

    /*  0x10006000 KMI0 (keyboard).  */

    /*  0x10007000 KMI1 (mouse).  */

    /* 0x10008000 Character LCD Interface.  */

    /*  0x10009000 UART3.  */

    /* 0x1000a000 Smart card 1.  */

    /*  0x1000b000 MMCI1.  */

    /*  0x10010000 Ethernet.  */

    /* 0x10020000 USB.  */

    /* 0x10100000 SSMC.  */

    /* 0x10110000 MPMC.  */

    /*  0x10120000 CLCD Controller.  */

    /*  0x10130000 DMA Controller.  */

    /*  0x10140000 Vectored interrupt controller.  */

    /* 0x101d0000 AHB Monitor Interface.  */

    /* 0x101e0000 System Controller.  */

    /* 0x101e1000 Watchdog Interface.  */

    /* 0x101e2000 Timer 0/1.  */

    /* 0x101e3000 Timer 2/3.  */

    /* 0x101e4000 GPIO port 0.  */

    /* 0x101e5000 GPIO port 1.  */

    /* 0x101e6000 GPIO port 2.  */

    /* 0x101e7000 GPIO port 3.  */

    /* 0x101e8000 RTC.  */

    /* 0x101f0000 Smart card 0.  */

    /*  0x101f1000 UART0.  */

    /*  0x101f2000 UART1.  */

    /*  0x101f3000 UART2.  */

    /* 0x101f4000 SSPI.  */

    /* 0x34000000 NOR Flash */



    dinfo = drive_get(IF_PFLASH, 0, 0);

    if (!pflash_cfi01_register(VERSATILE_FLASH_ADDR, NULL, "versatile.flash",

                          VERSATILE_FLASH_SIZE,

                          dinfo ? blk_bs(blk_by_legacy_dinfo(dinfo)) : NULL,

                          VERSATILE_FLASH_SECT_SIZE,

                          VERSATILE_FLASH_SIZE / VERSATILE_FLASH_SECT_SIZE,

                          4, 0x0089, 0x0018, 0x0000, 0x0, 0)) {

        fprintf(stderr, "qemu: Error registering flash memory.\n");

    }



    versatile_binfo.ram_size = machine->ram_size;

    versatile_binfo.kernel_filename = machine->kernel_filename;

    versatile_binfo.kernel_cmdline = machine->kernel_cmdline;

    versatile_binfo.initrd_filename = machine->initrd_filename;

    versatile_binfo.board_id = board_id;

    arm_load_kernel(cpu, &versatile_binfo);

}

