static uint64_t apb_config_readl (void *opaque,

                                  target_phys_addr_t addr, unsigned size)

{

    APBState *s = opaque;

    uint32_t val;



    switch (addr & 0xffff) {

    case 0x30 ... 0x4f: /* DMA error registers */

        val = 0;

        /* XXX: not implemented yet */

        break;

    case 0x200 ... 0x20b: /* IOMMU */

        val = s->iommu[(addr & 0xf) >> 2];

        break;

    case 0x20c ... 0x3ff: /* IOMMU flush */

        val = 0;

        break;

    case 0xc00 ... 0xc3f: /* PCI interrupt control */

        if (addr & 4) {

            val = s->pci_irq_map[(addr & 0x3f) >> 3];

        } else {

            val = 0;

        }

        break;

    case 0x1000 ... 0x1080: /* OBIO interrupt control */

        if (addr & 4) {

            val = s->obio_irq_map[(addr & 0xff) >> 3];

        } else {

            val = 0;

        }

        break;

    case 0x2000 ... 0x202f: /* PCI control */

        val = s->pci_control[(addr & 0x3f) >> 2];

        break;

    case 0xf020 ... 0xf027: /* Reset control */

        if (addr & 4) {

            val = s->reset_control;

        } else {

            val = 0;

        }

        break;

    case 0x5000 ... 0x51cf: /* PIO/DMA diagnostics */

    case 0xa400 ... 0xa67f: /* IOMMU diagnostics */

    case 0xa800 ... 0xa80f: /* Interrupt diagnostics */

    case 0xf000 ... 0xf01f: /* FFB config, memory control */

        /* we don't care */

    default:

        val = 0;

        break;

    }

    APB_DPRINTF("%s: addr " TARGET_FMT_lx " -> %x\n", __func__, addr, val);



    return val;

}

write_f(int argc, char **argv)

{

	struct timeval t1, t2;

	int Cflag = 0, pflag = 0, qflag = 0;

	int c, cnt;

	char *buf;

	int64_t offset;

	int count;

        /* Some compilers get confused and warn if this is not initialized.  */

        int total = 0;

	int pattern = 0xcd;



	while ((c = getopt(argc, argv, "CpP:q")) != EOF) {

		switch (c) {

		case 'C':

			Cflag = 1;

			break;

		case 'p':

			pflag = 1;

			break;

		case 'P':

			pattern = atoi(optarg);

			break;

		case 'q':

			qflag = 1;

			break;

		default:

			return command_usage(&write_cmd);

		}

	}



	if (optind != argc - 2)

		return command_usage(&write_cmd);



	offset = cvtnum(argv[optind]);

	if (offset < 0) {

		printf("non-numeric length argument -- %s\n", argv[optind]);

		return 0;

	}



	optind++;

	count = cvtnum(argv[optind]);

	if (count < 0) {

		printf("non-numeric length argument -- %s\n", argv[optind]);

		return 0;

	}



	if (!pflag) {

		if (offset & 0x1ff) {

			printf("offset %lld is not sector aligned\n",

				(long long)offset);

			return 0;

		}



		if (count & 0x1ff) {

			printf("count %d is not sector aligned\n",

				count);

			return 0;

		}

	}



	buf = qemu_io_alloc(count, pattern);



	gettimeofday(&t1, NULL);

	if (pflag)

		cnt = do_pwrite(buf, offset, count, &total);

	else

		cnt = do_write(buf, offset, count, &total);

	gettimeofday(&t2, NULL);



	if (cnt < 0) {

		printf("write failed: %s\n", strerror(-cnt));

		return 0;

	}



	if (qflag)

		return 0;



	/* Finally, report back -- -C gives a parsable format */

	t2 = tsub(t2, t1);

	print_report("wrote", &t2, offset, count, total, cnt, Cflag);



	qemu_io_free(buf);



	return 0;

}

static int cpu_post_load(void *opaque, int version_id)

{

    PowerPCCPU *cpu = opaque;

    CPUPPCState *env = &cpu->env;

    int i;

    target_ulong msr;



    /*

     * If we're operating in compat mode, we should be ok as long as

     * the destination supports the same compatiblity mode.

     *

     * Otherwise, however, we require that the destination has exactly

     * the same CPU model as the source.

     */



#if defined(TARGET_PPC64)

    if (cpu->compat_pvr) {

        Error *local_err = NULL;



        ppc_set_compat(cpu, cpu->compat_pvr, &local_err);

        if (local_err) {

            error_report_err(local_err);

            error_free(local_err);

            return -1;

        }

    } else

#endif

    {

        if (!pvr_match(cpu, env->spr[SPR_PVR])) {

            return -1;

        }

    }



    env->lr = env->spr[SPR_LR];

    env->ctr = env->spr[SPR_CTR];

    cpu_write_xer(env, env->spr[SPR_XER]);

#if defined(TARGET_PPC64)

    env->cfar = env->spr[SPR_CFAR];

#endif

    env->spe_fscr = env->spr[SPR_BOOKE_SPEFSCR];



    for (i = 0; (i < 4) && (i < env->nb_BATs); i++) {

        env->DBAT[0][i] = env->spr[SPR_DBAT0U + 2*i];

        env->DBAT[1][i] = env->spr[SPR_DBAT0U + 2*i + 1];

        env->IBAT[0][i] = env->spr[SPR_IBAT0U + 2*i];

        env->IBAT[1][i] = env->spr[SPR_IBAT0U + 2*i + 1];

    }

    for (i = 0; (i < 4) && ((i+4) < env->nb_BATs); i++) {

        env->DBAT[0][i+4] = env->spr[SPR_DBAT4U + 2*i];

        env->DBAT[1][i+4] = env->spr[SPR_DBAT4U + 2*i + 1];

        env->IBAT[0][i+4] = env->spr[SPR_IBAT4U + 2*i];

        env->IBAT[1][i+4] = env->spr[SPR_IBAT4U + 2*i + 1];

    }



    if (!cpu->vhyp) {

        ppc_store_sdr1(env, env->spr[SPR_SDR1]);

    }



    /* Invalidate all msr bits except MSR_TGPR/MSR_HVB before restoring */

    msr = env->msr;

    env->msr ^= ~((1ULL << MSR_TGPR) | MSR_HVB);

    ppc_store_msr(env, msr);



    hreg_compute_mem_idx(env);



    return 0;

}

static inline void t_gen_mov_TN_preg(TCGv tn, int r)

{

    if (r < 0 || r > 15) {

        fprintf(stderr, "wrong register read $p%d\n", r);

    }

    if (r == PR_BZ || r == PR_WZ || r == PR_DZ) {

        tcg_gen_mov_tl(tn, tcg_const_tl(0));

    } else if (r == PR_VR) {

        tcg_gen_mov_tl(tn, tcg_const_tl(32));

    } else {

        tcg_gen_mov_tl(tn, cpu_PR[r]);

    }

}

