static int loadvm_postcopy_handle_advise(MigrationIncomingState *mis)

{

    PostcopyState ps = postcopy_state_set(POSTCOPY_INCOMING_ADVISE);

    uint64_t remote_pagesize_summary, local_pagesize_summary, remote_tps;



    trace_loadvm_postcopy_handle_advise();

    if (ps != POSTCOPY_INCOMING_NONE) {

        error_report("CMD_POSTCOPY_ADVISE in wrong postcopy state (%d)", ps);

        return -1;

    }



    if (!migrate_postcopy_ram()) {

        return 0;

    }



    if (!postcopy_ram_supported_by_host()) {

        postcopy_state_set(POSTCOPY_INCOMING_NONE);

        return -1;

    }



    remote_pagesize_summary = qemu_get_be64(mis->from_src_file);

    local_pagesize_summary = ram_pagesize_summary();



    if (remote_pagesize_summary != local_pagesize_summary)  {

        /*

         * This detects two potential causes of mismatch:

         *   a) A mismatch in host page sizes

         *      Some combinations of mismatch are probably possible but it gets

         *      a bit more complicated.  In particular we need to place whole

         *      host pages on the dest at once, and we need to ensure that we

         *      handle dirtying to make sure we never end up sending part of

         *      a hostpage on it's own.

         *   b) The use of different huge page sizes on source/destination

         *      a more fine grain test is performed during RAM block migration

         *      but this test here causes a nice early clear failure, and

         *      also fails when passed to an older qemu that doesn't

         *      do huge pages.

         */

        error_report("Postcopy needs matching RAM page sizes (s=%" PRIx64

                                                             " d=%" PRIx64 ")",

                     remote_pagesize_summary, local_pagesize_summary);

        return -1;

    }



    remote_tps = qemu_get_be64(mis->from_src_file);

    if (remote_tps != qemu_target_page_size()) {

        /*

         * Again, some differences could be dealt with, but for now keep it

         * simple.

         */

        error_report("Postcopy needs matching target page sizes (s=%d d=%zd)",

                     (int)remote_tps, qemu_target_page_size());

        return -1;

    }



    if (ram_postcopy_incoming_init(mis)) {

        return -1;

    }



    postcopy_state_set(POSTCOPY_INCOMING_ADVISE);



    return 0;

}

coroutine_fn iscsi_co_discard(BlockDriverState *bs, int64_t sector_num,

                                   int nb_sectors)

{

    IscsiLun *iscsilun = bs->opaque;

    struct IscsiTask iTask;

    struct unmap_list list;

    uint32_t nb_blocks;

    uint32_t max_unmap;



    if (!is_request_lun_aligned(sector_num, nb_sectors, iscsilun)) {

        return -EINVAL;

    }



    if (!iscsilun->lbp.lbpu) {

        /* UNMAP is not supported by the target */

        return 0;

    }



    list.lba = sector_qemu2lun(sector_num, iscsilun);

    nb_blocks = sector_qemu2lun(nb_sectors, iscsilun);



    max_unmap = iscsilun->bl.max_unmap;

    if (max_unmap == 0xffffffff) {

        max_unmap = ISCSI_MAX_UNMAP;

    }



    while (nb_blocks > 0) {

        iscsi_co_init_iscsitask(iscsilun, &iTask);

        list.num = nb_blocks;

        if (list.num > max_unmap) {

            list.num = max_unmap;

        }

retry:

        if (iscsi_unmap_task(iscsilun->iscsi, iscsilun->lun, 0, 0, &list, 1,

                         iscsi_co_generic_cb, &iTask) == NULL) {

            return -EIO;

        }



        while (!iTask.complete) {

            iscsi_set_events(iscsilun);

            qemu_coroutine_yield();

        }



        if (iTask.task != NULL) {

            scsi_free_scsi_task(iTask.task);

            iTask.task = NULL;

        }



        if (iTask.do_retry) {

            goto retry;

        }



        if (iTask.status == SCSI_STATUS_CHECK_CONDITION) {

            /* the target might fail with a check condition if it

               is not happy with the alignment of the UNMAP request

               we silently fail in this case */

            return 0;

        }



        if (iTask.status != SCSI_STATUS_GOOD) {

            return -EIO;

        }



        list.lba += list.num;

        nb_blocks -= list.num;

    }



    return 0;

}

ssize_t qemu_sendv_packet(VLANClientState *sender, const struct iovec *iov,

                          int iovcnt)

{

    VLANState *vlan = sender->vlan;

    VLANClientState *vc;

    VLANPacket *packet;

    ssize_t max_len = 0;

    int i;



    if (sender->link_down)

        return calc_iov_length(iov, iovcnt);



    if (vlan->delivering) {

        max_len = calc_iov_length(iov, iovcnt);



        packet = qemu_malloc(sizeof(VLANPacket) + max_len);

        packet->next = vlan->send_queue;

        packet->sender = sender;

        packet->size = 0;

        for (i = 0; i < iovcnt; i++) {

            size_t len = iov[i].iov_len;



            memcpy(packet->data + packet->size, iov[i].iov_base, len);

            packet->size += len;

        }

        vlan->send_queue = packet;

    } else {

        vlan->delivering = 1;



        for (vc = vlan->first_client; vc != NULL; vc = vc->next) {

            ssize_t len = 0;



            if (vc == sender) {

                continue;

            }

            if (vc->link_down) {

                len = calc_iov_length(iov, iovcnt);

            } else if (vc->receive_iov) {

                len = vc->receive_iov(vc->opaque, iov, iovcnt);

            } else if (vc->receive) {

                len = vc_sendv_compat(vc, iov, iovcnt);

            }

            max_len = MAX(max_len, len);

        }



        while ((packet = vlan->send_queue) != NULL) {

            vlan->send_queue = packet->next;

            qemu_deliver_packet(packet->sender, packet->data, packet->size);

            qemu_free(packet);

        }

        vlan->delivering = 0;

    }



    return max_len;

}

uint64_t float64_to_uint64 (float64 a STATUS_PARAM)

{

    int64_t v;



    v = int64_to_float64(INT64_MIN STATUS_VAR);

    v = float64_to_int64((a + v) STATUS_VAR);



    return v - INT64_MIN;

}

static void xics_realize(DeviceState *dev, Error **errp)

{

    XICSState *icp = XICS(dev);

    ICSState *ics = icp->ics;

    Error *error = NULL;

    int i;



    if (!icp->nr_servers) {

        error_setg(errp, "Number of servers needs to be greater 0");

        return;

    }



    /* Registration of global state belongs into realize */

    spapr_rtas_register("ibm,set-xive", rtas_set_xive);

    spapr_rtas_register("ibm,get-xive", rtas_get_xive);

    spapr_rtas_register("ibm,int-off", rtas_int_off);

    spapr_rtas_register("ibm,int-on", rtas_int_on);



    spapr_register_hypercall(H_CPPR, h_cppr);

    spapr_register_hypercall(H_IPI, h_ipi);

    spapr_register_hypercall(H_XIRR, h_xirr);

    spapr_register_hypercall(H_EOI, h_eoi);



    ics->nr_irqs = icp->nr_irqs;

    ics->offset = XICS_IRQ_BASE;

    ics->icp = icp;

    object_property_set_bool(OBJECT(icp->ics), true, "realized", &error);

    if (error) {

        error_propagate(errp, error);

        return;

    }



    icp->ss = g_malloc0(icp->nr_servers*sizeof(ICPState));

    for (i = 0; i < icp->nr_servers; i++) {

        char buffer[32];

        object_initialize(&icp->ss[i], sizeof(icp->ss[i]), TYPE_ICP);

        snprintf(buffer, sizeof(buffer), "icp[%d]", i);

        object_property_add_child(OBJECT(icp), buffer, OBJECT(&icp->ss[i]), NULL);

        object_property_set_bool(OBJECT(&icp->ss[i]), true, "realized", &error);

        if (error) {

            error_propagate(errp, error);

            return;

        }

    }

}

