static uint32_t virtio_ioport_read(VirtIOPCIProxy *proxy, uint32_t addr)

{

    VirtIODevice *vdev = proxy->vdev;

    uint32_t ret = 0xFFFFFFFF;



    switch (addr) {

    case VIRTIO_PCI_HOST_FEATURES:

        ret = vdev->get_features(vdev);

        ret |= vdev->binding->get_features(proxy);

        break;

    case VIRTIO_PCI_GUEST_FEATURES:

        ret = vdev->guest_features;

        break;

    case VIRTIO_PCI_QUEUE_PFN:

        ret = virtio_queue_get_addr(vdev, vdev->queue_sel)

              >> VIRTIO_PCI_QUEUE_ADDR_SHIFT;

        break;

    case VIRTIO_PCI_QUEUE_NUM:

        ret = virtio_queue_get_num(vdev, vdev->queue_sel);

        break;

    case VIRTIO_PCI_QUEUE_SEL:

        ret = vdev->queue_sel;

        break;

    case VIRTIO_PCI_STATUS:

        ret = vdev->status;

        break;

    case VIRTIO_PCI_ISR:

        /* reading from the ISR also clears it. */

        ret = vdev->isr;

        vdev->isr = 0;

        qemu_set_irq(proxy->pci_dev.irq[0], 0);

        break;

    case VIRTIO_MSI_CONFIG_VECTOR:

        ret = vdev->config_vector;

        break;

    case VIRTIO_MSI_QUEUE_VECTOR:

        ret = virtio_queue_vector(vdev, vdev->queue_sel);

        break;

    default:

        break;

    }



    return ret;

}

static uint64_t onenand_read(void *opaque, hwaddr addr,

                             unsigned size)

{

    OneNANDState *s = (OneNANDState *) opaque;

    int offset = addr >> s->shift;



    switch (offset) {

    case 0x0000 ... 0xc000:

        return lduw_le_p(s->boot[0] + addr);



    case 0xf000:	/* Manufacturer ID */

        return s->id.man;

    case 0xf001:	/* Device ID */

        return s->id.dev;

    case 0xf002:	/* Version ID */

        return s->id.ver;

    /* TODO: get the following values from a real chip!  */

    case 0xf003:	/* Data Buffer size */

        return 1 << PAGE_SHIFT;

    case 0xf004:	/* Boot Buffer size */

        return 0x200;

    case 0xf005:	/* Amount of buffers */

        return 1 | (2 << 8);

    case 0xf006:	/* Technology */

        return 0;



    case 0xf100 ... 0xf107:	/* Start addresses */

        return s->addr[offset - 0xf100];



    case 0xf200:	/* Start buffer */

        return (s->bufaddr << 8) | ((s->count - 1) & (1 << (PAGE_SHIFT - 10)));



    case 0xf220:	/* Command */

        return s->command;

    case 0xf221:	/* System Configuration 1 */

        return s->config[0] & 0xffe0;

    case 0xf222:	/* System Configuration 2 */

        return s->config[1];



    case 0xf240:	/* Controller Status */

        return s->status;

    case 0xf241:	/* Interrupt */

        return s->intstatus;

    case 0xf24c:	/* Unlock Start Block Address */

        return s->unladdr[0];

    case 0xf24d:	/* Unlock End Block Address */

        return s->unladdr[1];

    case 0xf24e:	/* Write Protection Status */

        return s->wpstatus;



    case 0xff00:	/* ECC Status */

        return 0x00;

    case 0xff01:	/* ECC Result of main area data */

    case 0xff02:	/* ECC Result of spare area data */

    case 0xff03:	/* ECC Result of main area data */

    case 0xff04:	/* ECC Result of spare area data */

        hw_error("%s: imeplement ECC\n", __FUNCTION__);

        return 0x0000;

    }



    fprintf(stderr, "%s: unknown OneNAND register %x\n",

                    __FUNCTION__, offset);

    return 0;

}

static int handle_copied(BlockDriverState *bs, uint64_t guest_offset,

    uint64_t *host_offset, uint64_t *bytes, QCowL2Meta **m)

{

    BDRVQcow2State *s = bs->opaque;

    int l2_index;

    uint64_t cluster_offset;

    uint64_t *l2_table;

    unsigned int nb_clusters;

    unsigned int keep_clusters;

    int ret;



    trace_qcow2_handle_copied(qemu_coroutine_self(), guest_offset, *host_offset,

                              *bytes);



    assert(*host_offset == 0 ||    offset_into_cluster(s, guest_offset)

                                == offset_into_cluster(s, *host_offset));



    /*

     * Calculate the number of clusters to look for. We stop at L2 table

     * boundaries to keep things simple.

     */

    nb_clusters =

        size_to_clusters(s, offset_into_cluster(s, guest_offset) + *bytes);



    l2_index = offset_to_l2_index(s, guest_offset);

    nb_clusters = MIN(nb_clusters, s->l2_size - l2_index);



    /* Find L2 entry for the first involved cluster */

    ret = get_cluster_table(bs, guest_offset, &l2_table, &l2_index);

    if (ret < 0) {

        return ret;

    }



    cluster_offset = be64_to_cpu(l2_table[l2_index]);



    /* Check how many clusters are already allocated and don't need COW */

    if (qcow2_get_cluster_type(cluster_offset) == QCOW2_CLUSTER_NORMAL

        && (cluster_offset & QCOW_OFLAG_COPIED))

    {

        /* If a specific host_offset is required, check it */

        bool offset_matches =

            (cluster_offset & L2E_OFFSET_MASK) == *host_offset;



        if (offset_into_cluster(s, cluster_offset & L2E_OFFSET_MASK)) {

            qcow2_signal_corruption(bs, true, -1, -1, "Data cluster offset "

                                    "%#llx unaligned (guest offset: %#" PRIx64

                                    ")", cluster_offset & L2E_OFFSET_MASK,

                                    guest_offset);

            ret = -EIO;

            goto out;

        }



        if (*host_offset != 0 && !offset_matches) {

            *bytes = 0;

            ret = 0;

            goto out;

        }



        /* We keep all QCOW_OFLAG_COPIED clusters */

        keep_clusters =

            count_contiguous_clusters(nb_clusters, s->cluster_size,

                                      &l2_table[l2_index],

                                      QCOW_OFLAG_COPIED | QCOW_OFLAG_ZERO);

        assert(keep_clusters <= nb_clusters);



        *bytes = MIN(*bytes,

                 keep_clusters * s->cluster_size

                 - offset_into_cluster(s, guest_offset));



        ret = 1;

    } else {

        ret = 0;

    }



    /* Cleanup */

out:

    qcow2_cache_put(bs, s->l2_table_cache, (void **) &l2_table);



    /* Only return a host offset if we actually made progress. Otherwise we

     * would make requirements for handle_alloc() that it can't fulfill */

    if (ret > 0) {

        *host_offset = (cluster_offset & L2E_OFFSET_MASK)

                     + offset_into_cluster(s, guest_offset);

    }



    return ret;

}

int css_do_xsch(SubchDev *sch)

{

    SCSW *s = &sch->curr_status.scsw;

    PMCW *p = &sch->curr_status.pmcw;

    int ret;



    if (~(p->flags) & (PMCW_FLAGS_MASK_DNV | PMCW_FLAGS_MASK_ENA)) {

        ret = -ENODEV;

        goto out;

    }



    if (!(s->ctrl & SCSW_CTRL_MASK_FCTL) ||

        ((s->ctrl & SCSW_CTRL_MASK_FCTL) != SCSW_FCTL_START_FUNC) ||

        (!(s->ctrl &

           (SCSW_ACTL_RESUME_PEND | SCSW_ACTL_START_PEND | SCSW_ACTL_SUSP))) ||

        (s->ctrl & SCSW_ACTL_SUBCH_ACTIVE)) {

        ret = -EINPROGRESS;

        goto out;

    }



    if (s->ctrl & SCSW_CTRL_MASK_STCTL) {

        ret = -EBUSY;

        goto out;

    }



    /* Cancel the current operation. */

    s->ctrl &= ~(SCSW_FCTL_START_FUNC |

                 SCSW_ACTL_RESUME_PEND |

                 SCSW_ACTL_START_PEND |

                 SCSW_ACTL_SUSP);

    sch->channel_prog = 0x0;

    sch->last_cmd_valid = false;

    s->dstat = 0;

    s->cstat = 0;

    ret = 0;



out:

    return ret;

}

static int proxy_link(FsContext *ctx, V9fsPath *oldpath,

                      V9fsPath *dirpath, const char *name)

{

    int retval;

    V9fsString newpath;



    v9fs_string_init(&newpath);

    v9fs_string_sprintf(&newpath, "%s/%s", dirpath->data, name);



    retval = v9fs_request(ctx->private, T_LINK, NULL, "ss", oldpath, &newpath);

    v9fs_string_free(&newpath);

    if (retval < 0) {

        errno = -retval;

        retval = -1;

    }

    return retval;

}

void tcg_dump_info(FILE *f,

                   int (*cpu_fprintf)(FILE *f, const char *fmt, ...))

{

    TCGContext *s = &tcg_ctx;

    int64_t tot;



    tot = s->interm_time + s->code_time;

    cpu_fprintf(f, "JIT cycles          %" PRId64 " (%0.3f s at 2.4 GHz)\n",

                tot, tot / 2.4e9);

    cpu_fprintf(f, "translated TBs      %" PRId64 " (aborted=%" PRId64 " %0.1f%%)\n", 

                s->tb_count, 

                s->tb_count1 - s->tb_count,

                s->tb_count1 ? (double)(s->tb_count1 - s->tb_count) / s->tb_count1 * 100.0 : 0);

    cpu_fprintf(f, "avg ops/TB          %0.1f max=%d\n", 

                s->tb_count ? (double)s->op_count / s->tb_count : 0, s->op_count_max);

    cpu_fprintf(f, "deleted ops/TB      %0.2f\n",

                s->tb_count ? 

                (double)s->del_op_count / s->tb_count : 0);

    cpu_fprintf(f, "avg temps/TB        %0.2f max=%d\n",

                s->tb_count ? 

                (double)s->temp_count / s->tb_count : 0,

                s->temp_count_max);



    cpu_fprintf(f, "cycles/op           %0.1f\n", 

                s->op_count ? (double)tot / s->op_count : 0);

    cpu_fprintf(f, "cycles/in byte      %0.1f\n", 

                s->code_in_len ? (double)tot / s->code_in_len : 0);

    cpu_fprintf(f, "cycles/out byte     %0.1f\n", 

                s->code_out_len ? (double)tot / s->code_out_len : 0);

    if (tot == 0)

        tot = 1;

    cpu_fprintf(f, "  gen_interm time   %0.1f%%\n", 

                (double)s->interm_time / tot * 100.0);

    cpu_fprintf(f, "  gen_code time     %0.1f%%\n", 

                (double)s->code_time / tot * 100.0);

    cpu_fprintf(f, "liveness/code time  %0.1f%%\n", 

                (double)s->la_time / (s->code_time ? s->code_time : 1) * 100.0);

    cpu_fprintf(f, "cpu_restore count   %" PRId64 "\n",

                s->restore_count);

    cpu_fprintf(f, "  avg cycles        %0.1f\n",

                s->restore_count ? (double)s->restore_time / s->restore_count : 0);



    dump_op_count();

}

INLINE float32 packFloat32( flag zSign, int16 zExp, bits32 zSig )

{



    return ( ( (bits32) zSign )<<31 ) + ( ( (bits32) zExp )<<23 ) + zSig;



}

static int multiwrite_merge(BlockDriverState *bs, BlockRequest *reqs,

    int num_reqs, MultiwriteCB *mcb)

{

    int i, outidx;



    // Sort requests by start sector

    qsort(reqs, num_reqs, sizeof(*reqs), &multiwrite_req_compare);



    // Check if adjacent requests touch the same clusters. If so, combine them,

    // filling up gaps with zero sectors.

    outidx = 0;

    for (i = 1; i < num_reqs; i++) {

        int merge = 0;

        int64_t oldreq_last = reqs[outidx].sector + reqs[outidx].nb_sectors;



        // This handles the cases that are valid for all block drivers, namely

        // exactly sequential writes and overlapping writes.

        if (reqs[i].sector <= oldreq_last) {

            merge = 1;

        }



        // The block driver may decide that it makes sense to combine requests

        // even if there is a gap of some sectors between them. In this case,

        // the gap is filled with zeros (therefore only applicable for yet

        // unused space in format like qcow2).

        if (!merge && bs->drv->bdrv_merge_requests) {

            merge = bs->drv->bdrv_merge_requests(bs, &reqs[outidx], &reqs[i]);

        }



        if (reqs[outidx].qiov->niov + reqs[i].qiov->niov + 1 > IOV_MAX) {

            merge = 0;

        }



        if (merge) {

            size_t size;

            QEMUIOVector *qiov = qemu_mallocz(sizeof(*qiov));

            qemu_iovec_init(qiov,

                reqs[outidx].qiov->niov + reqs[i].qiov->niov + 1);



            // Add the first request to the merged one. If the requests are

            // overlapping, drop the last sectors of the first request.

            size = (reqs[i].sector - reqs[outidx].sector) << 9;

            qemu_iovec_concat(qiov, reqs[outidx].qiov, size);



            // We might need to add some zeros between the two requests

            if (reqs[i].sector > oldreq_last) {

                size_t zero_bytes = (reqs[i].sector - oldreq_last) << 9;

                uint8_t *buf = qemu_blockalign(bs, zero_bytes);

                memset(buf, 0, zero_bytes);

                qemu_iovec_add(qiov, buf, zero_bytes);

                mcb->callbacks[i].free_buf = buf;

            }



            // Add the second request

            qemu_iovec_concat(qiov, reqs[i].qiov, reqs[i].qiov->size);



            reqs[outidx].nb_sectors += reqs[i].nb_sectors;

            reqs[outidx].qiov = qiov;



            mcb->callbacks[i].free_qiov = reqs[outidx].qiov;

        } else {

            outidx++;

            reqs[outidx].sector     = reqs[i].sector;

            reqs[outidx].nb_sectors = reqs[i].nb_sectors;

            reqs[outidx].qiov       = reqs[i].qiov;

        }

    }



    return outidx + 1;

}

