void configure_icount(QemuOpts *opts, Error **errp)

{

    const char *option;

    char *rem_str = NULL;



    option = qemu_opt_get(opts, "shift");

    if (!option) {

        if (qemu_opt_get(opts, "align") != NULL) {

            error_setg(errp, "Please specify shift option when using align");

        }

        return;

    }



    icount_sleep = qemu_opt_get_bool(opts, "sleep", true);

    if (icount_sleep) {

        icount_warp_timer = timer_new_ns(QEMU_CLOCK_VIRTUAL_RT,

                                         icount_dummy_timer, NULL);

    }



    icount_align_option = qemu_opt_get_bool(opts, "align", false);



    if (icount_align_option && !icount_sleep) {

        error_setg(errp, "align=on and sleep=off are incompatible");

    }

    if (strcmp(option, "auto") != 0) {

        errno = 0;

        icount_time_shift = strtol(option, &rem_str, 0);

        if (errno != 0 || *rem_str != '\0' || !strlen(option)) {

            error_setg(errp, "icount: Invalid shift value");

        }

        use_icount = 1;

        return;

    } else if (icount_align_option) {

        error_setg(errp, "shift=auto and align=on are incompatible");

    } else if (!icount_sleep) {

        error_setg(errp, "shift=auto and sleep=off are incompatible");

    }



    use_icount = 2;



    /* 125MIPS seems a reasonable initial guess at the guest speed.

       It will be corrected fairly quickly anyway.  */

    icount_time_shift = 3;



    /* Have both realtime and virtual time triggers for speed adjustment.

       The realtime trigger catches emulated time passing too slowly,

       the virtual time trigger catches emulated time passing too fast.

       Realtime triggers occur even when idle, so use them less frequently

       than VM triggers.  */

    icount_rt_timer = timer_new_ms(QEMU_CLOCK_VIRTUAL_RT,

                                   icount_adjust_rt, NULL);

    timer_mod(icount_rt_timer,

                   qemu_clock_get_ms(QEMU_CLOCK_VIRTUAL_RT) + 1000);

    icount_vm_timer = timer_new_ns(QEMU_CLOCK_VIRTUAL,

                                        icount_adjust_vm, NULL);

    timer_mod(icount_vm_timer,

                   qemu_clock_get_ns(QEMU_CLOCK_VIRTUAL) +

                   get_ticks_per_sec() / 10);

}

static void handle_port_status_write(EHCIState *s, int port, uint32_t val)

{

    uint32_t *portsc = &s->portsc[port];

    USBDevice *dev = s->ports[port].dev;



    /* Clear rwc bits */

    *portsc &= ~(val & PORTSC_RWC_MASK);

    /* The guest may clear, but not set the PED bit */

    *portsc &= val | ~PORTSC_PED;

    /* POWNER is masked out by RO_MASK as it is RO when we've no companion */

    handle_port_owner_write(s, port, val);

    /* And finally apply RO_MASK */

    val &= PORTSC_RO_MASK;



    if ((val & PORTSC_PRESET) && !(*portsc & PORTSC_PRESET)) {

        trace_usb_ehci_port_reset(port, 1);

    }



    if (!(val & PORTSC_PRESET) &&(*portsc & PORTSC_PRESET)) {

        trace_usb_ehci_port_reset(port, 0);

        if (dev) {

            usb_attach(&s->ports[port], dev);

            usb_send_msg(dev, USB_MSG_RESET);

            *portsc &= ~PORTSC_CSC;

        }



        /*

         *  Table 2.16 Set the enable bit(and enable bit change) to indicate

         *  to SW that this port has a high speed device attached

         */

        if (dev && (dev->speedmask & USB_SPEED_MASK_HIGH)) {

            val |= PORTSC_PED;

        }

    }



    *portsc &= ~PORTSC_RO_MASK;

    *portsc |= val;

}

static uint64_t omap_rtc_read(void *opaque, target_phys_addr_t addr,

                              unsigned size)

{

    struct omap_rtc_s *s = (struct omap_rtc_s *) opaque;

    int offset = addr & OMAP_MPUI_REG_MASK;

    uint8_t i;



    if (size != 1) {

        return omap_badwidth_read8(opaque, addr);

    }



    switch (offset) {

    case 0x00:	/* SECONDS_REG */

        return to_bcd(s->current_tm.tm_sec);



    case 0x04:	/* MINUTES_REG */

        return to_bcd(s->current_tm.tm_min);



    case 0x08:	/* HOURS_REG */

        if (s->pm_am)

            return ((s->current_tm.tm_hour > 11) << 7) |

                    to_bcd(((s->current_tm.tm_hour - 1) % 12) + 1);

        else

            return to_bcd(s->current_tm.tm_hour);



    case 0x0c:	/* DAYS_REG */

        return to_bcd(s->current_tm.tm_mday);



    case 0x10:	/* MONTHS_REG */

        return to_bcd(s->current_tm.tm_mon + 1);



    case 0x14:	/* YEARS_REG */

        return to_bcd(s->current_tm.tm_year % 100);



    case 0x18:	/* WEEK_REG */

        return s->current_tm.tm_wday;



    case 0x20:	/* ALARM_SECONDS_REG */

        return to_bcd(s->alarm_tm.tm_sec);



    case 0x24:	/* ALARM_MINUTES_REG */

        return to_bcd(s->alarm_tm.tm_min);



    case 0x28:	/* ALARM_HOURS_REG */

        if (s->pm_am)

            return ((s->alarm_tm.tm_hour > 11) << 7) |

                    to_bcd(((s->alarm_tm.tm_hour - 1) % 12) + 1);

        else

            return to_bcd(s->alarm_tm.tm_hour);



    case 0x2c:	/* ALARM_DAYS_REG */

        return to_bcd(s->alarm_tm.tm_mday);



    case 0x30:	/* ALARM_MONTHS_REG */

        return to_bcd(s->alarm_tm.tm_mon + 1);



    case 0x34:	/* ALARM_YEARS_REG */

        return to_bcd(s->alarm_tm.tm_year % 100);



    case 0x40:	/* RTC_CTRL_REG */

        return (s->pm_am << 3) | (s->auto_comp << 2) |

                (s->round << 1) | s->running;



    case 0x44:	/* RTC_STATUS_REG */

        i = s->status;

        s->status &= ~0x3d;

        return i;



    case 0x48:	/* RTC_INTERRUPTS_REG */

        return s->interrupts;



    case 0x4c:	/* RTC_COMP_LSB_REG */

        return ((uint16_t) s->comp_reg) & 0xff;



    case 0x50:	/* RTC_COMP_MSB_REG */

        return ((uint16_t) s->comp_reg) >> 8;

    }



    OMAP_BAD_REG(addr);

    return 0;

}

cac_applet_pki_process_apdu(VCard *card, VCardAPDU *apdu,

                            VCardResponse **response)

{

    CACPKIAppletData *pki_applet = NULL;

    VCardAppletPrivate *applet_private = NULL;

    int size, next;

    unsigned char *sign_buffer;

    vcard_7816_status_t status;

    VCardStatus ret = VCARD_FAIL;



    applet_private = vcard_get_current_applet_private(card, apdu->a_channel);

    assert(applet_private);

    pki_applet = &(applet_private->u.pki_data);



    switch (apdu->a_ins) {

    case CAC_UPDATE_BUFFER:

        *response = vcard_make_response(

            VCARD7816_STATUS_ERROR_CONDITION_NOT_SATISFIED);

        ret = VCARD_DONE;

        break;

    case CAC_GET_CERTIFICATE:

        if ((apdu->a_p2 != 0) || (apdu->a_p1 != 0)) {

            *response = vcard_make_response(

                             VCARD7816_STATUS_ERROR_P1_P2_INCORRECT);

            break;

        }

        assert(pki_applet->cert != NULL);

        size = apdu->a_Le;

        if (pki_applet->cert_buffer == NULL) {

            pki_applet->cert_buffer = pki_applet->cert;

            pki_applet->cert_buffer_len = pki_applet->cert_len;

        }

        size = MIN(size, pki_applet->cert_buffer_len);

        next = MIN(255, pki_applet->cert_buffer_len - size);

        *response = vcard_response_new_bytes(

                        card, pki_applet->cert_buffer, size,

                        apdu->a_Le, next ?

                        VCARD7816_SW1_WARNING_CHANGE :

                        VCARD7816_SW1_SUCCESS,

                        next);

        pki_applet->cert_buffer += size;

        pki_applet->cert_buffer_len -= size;

        if ((*response == NULL) || (next == 0)) {

            pki_applet->cert_buffer = NULL;

        }

        if (*response == NULL) {

            *response = vcard_make_response(

                            VCARD7816_STATUS_EXC_ERROR_MEMORY_FAILURE);

        }

        ret = VCARD_DONE;

        break;

    case CAC_SIGN_DECRYPT:

        if (apdu->a_p2 != 0) {

            *response = vcard_make_response(

                             VCARD7816_STATUS_ERROR_P1_P2_INCORRECT);

            break;

        }

        size = apdu->a_Lc;



        sign_buffer = g_realloc(pki_applet->sign_buffer,

                                pki_applet->sign_buffer_len + size);

        memcpy(sign_buffer+pki_applet->sign_buffer_len, apdu->a_body, size);

        size += pki_applet->sign_buffer_len;

        switch (apdu->a_p1) {

        case  0x80:

            /* p1 == 0x80 means we haven't yet sent the whole buffer, wait for

             * the rest */

            pki_applet->sign_buffer = sign_buffer;

            pki_applet->sign_buffer_len = size;

            *response = vcard_make_response(VCARD7816_STATUS_SUCCESS);

            break;

        case 0x00:

            /* we now have the whole buffer, do the operation, result will be

             * in the sign_buffer */

            status = vcard_emul_rsa_op(card, pki_applet->key,

                                       sign_buffer, size);

            if (status != VCARD7816_STATUS_SUCCESS) {

                *response = vcard_make_response(status);

                break;

            }

            *response = vcard_response_new(card, sign_buffer, size, apdu->a_Le,

                                                     VCARD7816_STATUS_SUCCESS);

            if (*response == NULL) {

                *response = vcard_make_response(

                                VCARD7816_STATUS_EXC_ERROR_MEMORY_FAILURE);

            }

            break;

        default:

           *response = vcard_make_response(

                                VCARD7816_STATUS_ERROR_P1_P2_INCORRECT);

            break;

        }

        g_free(sign_buffer);

        pki_applet->sign_buffer = NULL;

        pki_applet->sign_buffer_len = 0;

        ret = VCARD_DONE;

        break;

    case CAC_READ_BUFFER:

        /* new CAC call, go ahead and use the old version for now */

        /* TODO: implement */

        *response = vcard_make_response(

                                VCARD7816_STATUS_ERROR_COMMAND_NOT_SUPPORTED);

        ret = VCARD_DONE;

        break;

    default:

        ret = cac_common_process_apdu(card, apdu, response);

        break;

    }

    return ret;

}

int qcow2_encrypt_sectors(BDRVQcow2State *s, int64_t sector_num,

                          uint8_t *buf, int nb_sectors, bool enc,

                          Error **errp)

{

    union {

        uint64_t ll[2];

        uint8_t b[16];

    } ivec;

    int i;

    int ret;



    for(i = 0; i < nb_sectors; i++) {

        ivec.ll[0] = cpu_to_le64(sector_num);

        ivec.ll[1] = 0;

        if (qcrypto_cipher_setiv(s->cipher,

                                 ivec.b, G_N_ELEMENTS(ivec.b),

                                 errp) < 0) {

            return -1;

        }

        if (enc) {

            ret = qcrypto_cipher_encrypt(s->cipher,

                                         buf, buf,

                                         512,

                                         errp);

        } else {

            ret = qcrypto_cipher_decrypt(s->cipher,

                                         buf, buf,

                                         512,

                                         errp);

        }

        if (ret < 0) {

            return -1;

        }

        sector_num++;

        buf += 512;

    }

    return 0;

}

