static void coroutine_fn v9fs_write(void *opaque)

{

    ssize_t err;

    int32_t fid;

    uint64_t off;

    uint32_t count;

    int32_t len = 0;

    int32_t total = 0;

    size_t offset = 7;

    V9fsFidState *fidp;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;

    QEMUIOVector qiov_full;

    QEMUIOVector qiov;



    err = pdu_unmarshal(pdu, offset, "dqd", &fid, &off, &count);

    if (err < 0) {

        pdu_complete(pdu, err);

        return;

    }

    offset += err;

    v9fs_init_qiov_from_pdu(&qiov_full, pdu, offset, count, true);

    trace_v9fs_write(pdu->tag, pdu->id, fid, off, count, qiov_full.niov);



    fidp = get_fid(pdu, fid);

    if (fidp == NULL) {

        err = -EINVAL;

        goto out_nofid;

    }

    if (fidp->fid_type == P9_FID_FILE) {

        if (fidp->fs.fd == -1) {

            err = -EINVAL;

            goto out;

        }

    } else if (fidp->fid_type == P9_FID_XATTR) {

        /*

         * setxattr operation

         */

        err = v9fs_xattr_write(s, pdu, fidp, off, count,

                               qiov_full.iov, qiov_full.niov);

        goto out;

    } else {

        err = -EINVAL;

        goto out;

    }

    qemu_iovec_init(&qiov, qiov_full.niov);

    do {

        qemu_iovec_reset(&qiov);

        qemu_iovec_concat(&qiov, &qiov_full, total, qiov_full.size - total);

        if (0) {

            print_sg(qiov.iov, qiov.niov);

        }

        /* Loop in case of EINTR */

        do {

            len = v9fs_co_pwritev(pdu, fidp, qiov.iov, qiov.niov, off);

            if (len >= 0) {

                off   += len;

                total += len;

            }

        } while (len == -EINTR && !pdu->cancelled);

        if (len < 0) {

            /* IO error return the error */

            err = len;

            goto out_qiov;

        }

    } while (total < count && len > 0);



    offset = 7;

    err = pdu_marshal(pdu, offset, "d", total);

    if (err < 0) {

        goto out;

    }

    err += offset;

    trace_v9fs_write_return(pdu->tag, pdu->id, total, err);

out_qiov:

    qemu_iovec_destroy(&qiov);

out:

    put_fid(pdu, fidp);

out_nofid:

    qemu_iovec_destroy(&qiov_full);

    pdu_complete(pdu, err);

}

Qcow2Cache *qcow2_cache_create(BlockDriverState *bs, int num_tables)

{

    BDRVQcowState *s = bs->opaque;

    Qcow2Cache *c;

    int i;



    c = g_malloc0(sizeof(*c));

    c->size = num_tables;

    c->entries = g_malloc0(sizeof(*c->entries) * num_tables);



    for (i = 0; i < c->size; i++) {

        c->entries[i].table = qemu_try_blockalign(bs->file, s->cluster_size);

        if (c->entries[i].table == NULL) {

            goto fail;

        }

    }



    return c;



fail:

    for (i = 0; i < c->size; i++) {

        qemu_vfree(c->entries[i].table);

    }

    g_free(c->entries);

    g_free(c);

    return NULL;

}

int bdrv_commit(BlockDriverState *bs)

{

    BlockDriver *drv = bs->drv;

    int64_t sector, total_sectors;

    int n, ro, open_flags;

    int ret = 0;

    uint8_t *buf;

    char filename[1024];



    if (!drv)

        return -ENOMEDIUM;



    if (!bs->backing_hd) {

        return -ENOTSUP;

    }



    if (bdrv_in_use(bs) || bdrv_in_use(bs->backing_hd)) {

        return -EBUSY;

    }



    ro = bs->backing_hd->read_only;

    strncpy(filename, bs->backing_hd->filename, sizeof(filename));

    open_flags =  bs->backing_hd->open_flags;



    if (ro) {

        if (bdrv_reopen(bs->backing_hd, open_flags | BDRV_O_RDWR, NULL)) {

            return -EACCES;

        }

    }



    total_sectors = bdrv_getlength(bs) >> BDRV_SECTOR_BITS;

    buf = g_malloc(COMMIT_BUF_SECTORS * BDRV_SECTOR_SIZE);



    for (sector = 0; sector < total_sectors; sector += n) {

        if (bdrv_is_allocated(bs, sector, COMMIT_BUF_SECTORS, &n)) {



            if (bdrv_read(bs, sector, buf, n) != 0) {

                ret = -EIO;

                goto ro_cleanup;

            }



            if (bdrv_write(bs->backing_hd, sector, buf, n) != 0) {

                ret = -EIO;

                goto ro_cleanup;

            }

        }

    }



    if (drv->bdrv_make_empty) {

        ret = drv->bdrv_make_empty(bs);

        bdrv_flush(bs);

    }



    /*

     * Make sure all data we wrote to the backing device is actually

     * stable on disk.

     */

    if (bs->backing_hd)

        bdrv_flush(bs->backing_hd);



ro_cleanup:

    g_free(buf);



    if (ro) {

        /* ignoring error return here */

        bdrv_reopen(bs->backing_hd, open_flags & ~BDRV_O_RDWR, NULL);

    }



    return ret;

}

static void dec_barrel(DisasContext *dc)

{

    TCGv t0;

    bool s, t;



    if ((dc->tb_flags & MSR_EE_FLAG)

          && (dc->cpu->env.pvr.regs[2] & PVR2_ILL_OPCODE_EXC_MASK)

          && !dc->cpu->cfg.use_barrel) {

        tcg_gen_movi_tl(cpu_SR[SR_ESR], ESR_EC_ILLEGAL_OP);

        t_gen_raise_exception(dc, EXCP_HW_EXCP);

        return;

    }



    s = extract32(dc->imm, 10, 1);

    t = extract32(dc->imm, 9, 1);



    LOG_DIS("bs%s%s r%d r%d r%d\n",

            s ? "l" : "r", t ? "a" : "l", dc->rd, dc->ra, dc->rb);



    t0 = tcg_temp_new();



    tcg_gen_mov_tl(t0, *(dec_alu_op_b(dc)));

    tcg_gen_andi_tl(t0, t0, 31);



    if (s) {

        tcg_gen_shl_tl(cpu_R[dc->rd], cpu_R[dc->ra], t0);

    } else {

        if (t) {

            tcg_gen_sar_tl(cpu_R[dc->rd], cpu_R[dc->ra], t0);

        } else {

            tcg_gen_shr_tl(cpu_R[dc->rd], cpu_R[dc->ra], t0);

        }

    }


}

static int ram_find_and_save_block(RAMState *rs, bool last_stage)

{

    PageSearchStatus pss;

    int pages = 0;

    bool again, found;

    ram_addr_t dirty_ram_abs; /* Address of the start of the dirty page in

                                 ram_addr_t space */



    /* No dirty page as there is zero RAM */

    if (!ram_bytes_total()) {

        return pages;

    }



    pss.block = rs->last_seen_block;

    pss.offset = rs->last_offset;

    pss.complete_round = false;



    if (!pss.block) {

        pss.block = QLIST_FIRST_RCU(&ram_list.blocks);

    }



    do {

        again = true;

        found = get_queued_page(rs, &pss, &dirty_ram_abs);



        if (!found) {

            /* priority queue empty, so just search for something dirty */

            found = find_dirty_block(rs, &pss, &again, &dirty_ram_abs);

        }



        if (found) {

            pages = ram_save_host_page(rs, &pss, last_stage, dirty_ram_abs);

        }

    } while (!pages && again);



    rs->last_seen_block = pss.block;

    rs->last_offset = pss.offset;



    return pages;

}

int msix_init(struct PCIDevice *dev, unsigned short nentries,

              MemoryRegion *table_bar, uint8_t table_bar_nr,

              unsigned table_offset, MemoryRegion *pba_bar,

              uint8_t pba_bar_nr, unsigned pba_offset, uint8_t cap_pos)

{

    int cap;

    unsigned table_size, pba_size;

    uint8_t *config;



    /* Nothing to do if MSI is not supported by interrupt controller */

    if (!msi_nonbroken) {

        return -ENOTSUP;

    }



    if (nentries < 1 || nentries > PCI_MSIX_FLAGS_QSIZE + 1) {

        return -EINVAL;

    }



    table_size = nentries * PCI_MSIX_ENTRY_SIZE;

    pba_size = QEMU_ALIGN_UP(nentries, 64) / 8;



    /* Sanity test: table & pba don't overlap, fit within BARs, min aligned */

    if ((table_bar_nr == pba_bar_nr &&

         ranges_overlap(table_offset, table_size, pba_offset, pba_size)) ||

        table_offset + table_size > memory_region_size(table_bar) ||

        pba_offset + pba_size > memory_region_size(pba_bar) ||

        (table_offset | pba_offset) & PCI_MSIX_FLAGS_BIRMASK) {

        return -EINVAL;

    }



    cap = pci_add_capability(dev, PCI_CAP_ID_MSIX, cap_pos, MSIX_CAP_LENGTH);

    if (cap < 0) {

        return cap;

    }



    dev->msix_cap = cap;

    dev->cap_present |= QEMU_PCI_CAP_MSIX;

    config = dev->config + cap;



    pci_set_word(config + PCI_MSIX_FLAGS, nentries - 1);

    dev->msix_entries_nr = nentries;

    dev->msix_function_masked = true;



    pci_set_long(config + PCI_MSIX_TABLE, table_offset | table_bar_nr);

    pci_set_long(config + PCI_MSIX_PBA, pba_offset | pba_bar_nr);



    /* Make flags bit writable. */

    dev->wmask[cap + MSIX_CONTROL_OFFSET] |= MSIX_ENABLE_MASK |

                                             MSIX_MASKALL_MASK;



    dev->msix_table = g_malloc0(table_size);

    dev->msix_pba = g_malloc0(pba_size);

    dev->msix_entry_used = g_malloc0(nentries * sizeof *dev->msix_entry_used);



    msix_mask_all(dev, nentries);



    memory_region_init_io(&dev->msix_table_mmio, OBJECT(dev), &msix_table_mmio_ops, dev,

                          "msix-table", table_size);

    memory_region_add_subregion(table_bar, table_offset, &dev->msix_table_mmio);

    memory_region_init_io(&dev->msix_pba_mmio, OBJECT(dev), &msix_pba_mmio_ops, dev,

                          "msix-pba", pba_size);

    memory_region_add_subregion(pba_bar, pba_offset, &dev->msix_pba_mmio);



    return 0;

}

