static void test_dealloc_partial(void)

{

    static const char text[] = "don't leak me";



    UserDefTwo *ud2 = NULL;

    Error *err = NULL;



    /* create partial object */

    {

        QDict *ud2_dict;

        QmpInputVisitor *qiv;



        ud2_dict = qdict_new();

        qdict_put_obj(ud2_dict, "string0", QOBJECT(qstring_from_str(text)));



        qiv = qmp_input_visitor_new(QOBJECT(ud2_dict));

        visit_type_UserDefTwo(qmp_input_get_visitor(qiv), &ud2, NULL, &err);

        qmp_input_visitor_cleanup(qiv);

        QDECREF(ud2_dict);

    }



    /* verify partial success */

    assert(ud2 != NULL);

    assert(ud2->string0 != NULL);

    assert(strcmp(ud2->string0, text) == 0);

    assert(ud2->dict1 == NULL);



    /* confirm & release construction error */

    assert(err != NULL);

    error_free(err);



    /* tear down partial object */

    qapi_free_UserDefTwo(ud2);

}

static int bdrv_qed_open(BlockDriverState *bs, QDict *options, int flags,
                         Error **errp)
{
    BDRVQEDState *s = bs->opaque;
    QEDHeader le_header;
    int64_t file_size;
    int ret;
    s->bs = bs;
    QSIMPLEQ_INIT(&s->allocating_write_reqs);
    ret = bdrv_pread(bs->file, 0, &le_header, sizeof(le_header));
    if (ret < 0) {
        return ret;
    qed_header_le_to_cpu(&le_header, &s->header);
    if (s->header.magic != QED_MAGIC) {
        error_setg(errp, "Image not in QED format");
    if (s->header.features & ~QED_FEATURE_MASK) {
        /* image uses unsupported feature bits */
        char buf[64];
        snprintf(buf, sizeof(buf), "%" PRIx64,
            s->header.features & ~QED_FEATURE_MASK);
        error_set(errp, QERR_UNKNOWN_BLOCK_FORMAT_FEATURE,
            bdrv_get_device_name(bs), "QED", buf);
        return -ENOTSUP;
    if (!qed_is_cluster_size_valid(s->header.cluster_size)) {
    /* Round down file size to the last cluster */
    file_size = bdrv_getlength(bs->file);
    if (file_size < 0) {
        return file_size;
    s->file_size = qed_start_of_cluster(s, file_size);
    if (!qed_is_table_size_valid(s->header.table_size)) {
    if (!qed_is_image_size_valid(s->header.image_size,
                                 s->header.cluster_size,
                                 s->header.table_size)) {
    if (!qed_check_table_offset(s, s->header.l1_table_offset)) {
    s->table_nelems = (s->header.cluster_size * s->header.table_size) /
                      sizeof(uint64_t);
    s->l2_shift = ffs(s->header.cluster_size) - 1;
    s->l2_mask = s->table_nelems - 1;
    s->l1_shift = s->l2_shift + ffs(s->table_nelems) - 1;
    if ((s->header.features & QED_F_BACKING_FILE)) {
        if ((uint64_t)s->header.backing_filename_offset +
            s->header.backing_filename_size >
            s->header.cluster_size * s->header.header_size) {
        ret = qed_read_string(bs->file, s->header.backing_filename_offset,
                              s->header.backing_filename_size, bs->backing_file,
                              sizeof(bs->backing_file));
        if (ret < 0) {
            return ret;
        if (s->header.features & QED_F_BACKING_FORMAT_NO_PROBE) {
            pstrcpy(bs->backing_format, sizeof(bs->backing_format), "raw");
    /* Reset unknown autoclear feature bits.  This is a backwards
     * compatibility mechanism that allows images to be opened by older
     * programs, which "knock out" unknown feature bits.  When an image is
     * opened by a newer program again it can detect that the autoclear
     * feature is no longer valid.
     */
    if ((s->header.autoclear_features & ~QED_AUTOCLEAR_FEATURE_MASK) != 0 &&
        !bdrv_is_read_only(bs->file) && !(flags & BDRV_O_INCOMING)) {
        s->header.autoclear_features &= QED_AUTOCLEAR_FEATURE_MASK;
        ret = qed_write_header_sync(s);
        if (ret) {
            return ret;
        /* From here on only known autoclear feature bits are valid */
        bdrv_flush(bs->file);
    s->l1_table = qed_alloc_table(s);
    qed_init_l2_cache(&s->l2_cache);
    ret = qed_read_l1_table_sync(s);
    if (ret) {
        goto out;
    /* If image was not closed cleanly, check consistency */
    if (!(flags & BDRV_O_CHECK) && (s->header.features & QED_F_NEED_CHECK)) {
        /* Read-only images cannot be fixed.  There is no risk of corruption
         * since write operations are not possible.  Therefore, allow
         * potentially inconsistent images to be opened read-only.  This can
         * aid data recovery from an otherwise inconsistent image.
         */
        if (!bdrv_is_read_only(bs->file) &&
            !(flags & BDRV_O_INCOMING)) {
            BdrvCheckResult result = {0};
            ret = qed_check(s, &result, true);
            if (ret) {
                goto out;
    bdrv_qed_attach_aio_context(bs, bdrv_get_aio_context(bs));
out:
    if (ret) {
        qed_free_l2_cache(&s->l2_cache);
        qemu_vfree(s->l1_table);
    return ret;

void gen_intermediate_code(CPUAlphaState *env, struct TranslationBlock *tb)
{
    AlphaCPU *cpu = alpha_env_get_cpu(env);
    CPUState *cs = CPU(cpu);
    DisasContext ctx, *ctxp = &ctx;
    target_ulong pc_start;
    target_ulong pc_mask;
    uint32_t insn;
    ExitStatus ret;
    int num_insns;
    int max_insns;
    pc_start = tb->pc;
    ctx.tb = tb;
    ctx.pc = pc_start;
    ctx.tbflags = tb->flags;
    ctx.mem_idx = cpu_mmu_index(env, false);
    ctx.implver = env->implver;
    ctx.amask = env->amask;
    ctx.singlestep_enabled = cs->singlestep_enabled;
#ifdef CONFIG_USER_ONLY
    ctx.ir = cpu_std_ir;
#else
    ctx.palbr = env->palbr;
    ctx.ir = (ctx.tbflags & ENV_FLAG_PAL_MODE ? cpu_pal_ir : cpu_std_ir);
#endif
    /* ??? Every TB begins with unset rounding mode, to be initialized on
       the first fp insn of the TB.  Alternately we could define a proper
       default for every TB (e.g. QUAL_RM_N or QUAL_RM_D) and make sure
       to reset the FP_STATUS to that default at the end of any TB that
       changes the default.  We could even (gasp) dynamiclly figure out
       what default would be most efficient given the running program.  */
    ctx.tb_rm = -1;
    /* Similarly for flush-to-zero.  */
    ctx.tb_ftz = -1;
    TCGV_UNUSED_I64(ctx.zero);
    TCGV_UNUSED_I64(ctx.sink);
    TCGV_UNUSED_I64(ctx.lit);
    num_insns = 0;
    max_insns = tb->cflags & CF_COUNT_MASK;
    if (max_insns == 0) {
        max_insns = CF_COUNT_MASK;
    if (max_insns > TCG_MAX_INSNS) {
        max_insns = TCG_MAX_INSNS;
    if (in_superpage(&ctx, pc_start)) {
        pc_mask = (1ULL << 41) - 1;
    } else {
        pc_mask = ~TARGET_PAGE_MASK;
    gen_tb_start(tb);
    tcg_clear_temp_count();
    do {
        tcg_gen_insn_start(ctx.pc);
        num_insns++;
        if (unlikely(cpu_breakpoint_test(cs, ctx.pc, BP_ANY))) {
            ret = gen_excp(&ctx, EXCP_DEBUG, 0);
            /* The address covered by the breakpoint must be included in
               [tb->pc, tb->pc + tb->size) in order to for it to be
               properly cleared -- thus we increment the PC here so that
               the logic setting tb->size below does the right thing.  */
            ctx.pc += 4;
            break;
        if (num_insns == max_insns && (tb->cflags & CF_LAST_IO)) {
            gen_io_start();
        insn = cpu_ldl_code(env, ctx.pc);
        ctx.pc += 4;
        ret = translate_one(ctxp, insn);
        free_context_temps(ctxp);
        /* If we reach a page boundary, are single stepping,
           or exhaust instruction count, stop generation.  */
        if (ret == NO_EXIT
            && ((ctx.pc & pc_mask) == 0
                || tcg_op_buf_full()
                || num_insns >= max_insns
                || singlestep
                || ctx.singlestep_enabled)) {
            ret = EXIT_FALLTHRU;
    } while (ret == NO_EXIT);
    if (tb->cflags & CF_LAST_IO) {
        gen_io_end();
    switch (ret) {
    case EXIT_GOTO_TB:
    case EXIT_NORETURN:
        break;
    case EXIT_FALLTHRU:
        if (use_goto_tb(&ctx, ctx.pc)) {
            tcg_gen_goto_tb(0);
            tcg_gen_movi_i64(cpu_pc, ctx.pc);
            tcg_gen_exit_tb((uintptr_t)ctx.tb);
        /* FALLTHRU */
    case EXIT_PC_STALE:
        tcg_gen_movi_i64(cpu_pc, ctx.pc);
        /* FALLTHRU */
    case EXIT_PC_UPDATED:
        if (!use_exit_tb(&ctx)) {
            tcg_gen_lookup_and_goto_ptr(cpu_pc);
            break;
        /* FALLTHRU */
    case EXIT_PC_UPDATED_NOCHAIN:
        if (ctx.singlestep_enabled) {
            gen_excp_1(EXCP_DEBUG, 0);
        } else {
            tcg_gen_exit_tb(0);
        break;
    default:
        g_assert_not_reached();
    gen_tb_end(tb, num_insns);
    tb->size = ctx.pc - pc_start;
    tb->icount = num_insns;
#ifdef DEBUG_DISAS
    if (qemu_loglevel_mask(CPU_LOG_TB_IN_ASM)
        && qemu_log_in_addr_range(pc_start)) {
        qemu_log_lock();
        qemu_log("IN: %s\n", lookup_symbol(pc_start));
        log_target_disas(cs, pc_start, ctx.pc - pc_start, 1);
        qemu_log("\n");
        qemu_log_unlock();
#endif

static int virtio_balloon_device_exit(DeviceState *qdev)

{

    VirtIOBalloon *s = VIRTIO_BALLOON(qdev);

    VirtIODevice *vdev = VIRTIO_DEVICE(qdev);



    balloon_stats_destroy_timer(s);

    qemu_remove_balloon_handler(s);

    unregister_savevm(qdev, "virtio-balloon", s);

    virtio_cleanup(vdev);

    return 0;

}

fdctrl_t *sun4m_fdctrl_init (qemu_irq irq, target_phys_addr_t io_base,

                             DriveInfo **fds, qemu_irq *fdc_tc)

{

    DeviceState *dev;

    fdctrl_sysbus_t *sys;

    fdctrl_t *fdctrl;



    dev = qdev_create(NULL, "SUNW,fdtwo");

    qdev_prop_set_drive(dev, "drive", fds[0]);

    if (qdev_init(dev) != 0)

        return NULL;

    sys = DO_UPCAST(fdctrl_sysbus_t, busdev.qdev, dev);

    fdctrl = &sys->state;

    sysbus_connect_irq(&sys->busdev, 0, irq);

    sysbus_mmio_map(&sys->busdev, 0, io_base);

    *fdc_tc = qdev_get_gpio_in(dev, 0);



    return fdctrl;

}

void dump_mmu(FILE *f, fprintf_function cpu_fprintf, CPUPPCState *env)

{

    switch (env->mmu_model) {

    case POWERPC_MMU_BOOKE:

        mmubooke_dump_mmu(f, cpu_fprintf, env);

        break;

    case POWERPC_MMU_BOOKE206:

        mmubooke206_dump_mmu(f, cpu_fprintf, env);

        break;

    case POWERPC_MMU_SOFT_6xx:

    case POWERPC_MMU_SOFT_74xx:

        mmu6xx_dump_mmu(f, cpu_fprintf, env);

        break;

#if defined(TARGET_PPC64)

    case POWERPC_MMU_64B:

    case POWERPC_MMU_2_03:

    case POWERPC_MMU_2_06:


    case POWERPC_MMU_2_07:


        dump_slb(f, cpu_fprintf, env);

        break;

#endif

    default:

        qemu_log_mask(LOG_UNIMP, "%s: unimplemented\n", __func__);

    }

}

