static int ram_save_target_page(RAMState *rs, PageSearchStatus *pss,

                                bool last_stage, ram_addr_t dirty_ram_abs)

{

    int res = 0;



    /* Check the pages is dirty and if it is send it */

    if (migration_bitmap_clear_dirty(rs, dirty_ram_abs)) {

        unsigned long *unsentmap;

        /*

         * If xbzrle is on, stop using the data compression after first

         * round of migration even if compression is enabled. In theory,

         * xbzrle can do better than compression.

         */



        if (migrate_use_compression()

            && (rs->ram_bulk_stage || !migrate_use_xbzrle())) {

            res = ram_save_compressed_page(rs, pss, last_stage);

        } else {

            res = ram_save_page(rs, pss, last_stage);

        }



        if (res < 0) {

            return res;

        }

        unsentmap = atomic_rcu_read(&rs->ram_bitmap)->unsentmap;

        if (unsentmap) {

            clear_bit(dirty_ram_abs >> TARGET_PAGE_BITS, unsentmap);

        }

    }



    return res;

}

static int vmdk_parent_open(BlockDriverState *bs, const char * filename)

{

    BDRVVmdkState *s = bs->opaque;

    char *p_name; 

    char desc[DESC_SIZE];

    char parent_img_name[1024];



    /* the descriptor offset = 0x200 */

    if (bdrv_pread(s->hd, 0x200, desc, DESC_SIZE) != DESC_SIZE)

        return -1;



    if ((p_name = strstr(desc,"parentFileNameHint")) != 0) {

        char *end_name;

        struct stat file_buf;



        p_name += sizeof("parentFileNameHint") + 1;

        if ((end_name = strchr(p_name,'\"')) == 0)

            return -1;



        strncpy(s->hd->backing_file, p_name, end_name - p_name);

        if (stat(s->hd->backing_file, &file_buf) != 0) {

            path_combine(parent_img_name, sizeof(parent_img_name),

                         filename, s->hd->backing_file);

        } else {

            strcpy(parent_img_name, s->hd->backing_file);

        }



        s->hd->backing_hd = bdrv_new("");

        if (!s->hd->backing_hd) {

            failure:

            bdrv_close(s->hd);

            return -1;

        }

        if (bdrv_open(s->hd->backing_hd, parent_img_name, 0) < 0)

            goto failure;

    }



    return 0;

}

static int sd_snapshot_list(BlockDriverState *bs, QEMUSnapshotInfo **psn_tab)

{

    Error *local_err = NULL;

    BDRVSheepdogState *s = bs->opaque;

    SheepdogReq req;

    int fd, nr = 1024, ret, max = BITS_TO_LONGS(SD_NR_VDIS) * sizeof(long);

    QEMUSnapshotInfo *sn_tab = NULL;

    unsigned wlen, rlen;

    int found = 0;

    static SheepdogInode inode;

    unsigned long *vdi_inuse;

    unsigned int start_nr;

    uint64_t hval;

    uint32_t vid;



    vdi_inuse = g_malloc(max);



    fd = connect_to_sdog(s, &local_err);

    if (fd < 0) {

        error_report("%s", error_get_pretty(local_err));;

        error_free(local_err);

        ret = fd;

        goto out;

    }



    rlen = max;

    wlen = 0;



    memset(&req, 0, sizeof(req));



    req.opcode = SD_OP_READ_VDIS;

    req.data_length = max;



    ret = do_req(fd, s->aio_context, (SheepdogReq *)&req,

                 vdi_inuse, &wlen, &rlen);



    closesocket(fd);

    if (ret) {

        goto out;

    }



    sn_tab = g_malloc0(nr * sizeof(*sn_tab));



    /* calculate a vdi id with hash function */

    hval = fnv_64a_buf(s->name, strlen(s->name), FNV1A_64_INIT);

    start_nr = hval & (SD_NR_VDIS - 1);



    fd = connect_to_sdog(s, &local_err);

    if (fd < 0) {

        error_report("%s", error_get_pretty(local_err));;

        error_free(local_err);

        ret = fd;

        goto out;

    }



    for (vid = start_nr; found < nr; vid = (vid + 1) % SD_NR_VDIS) {

        if (!test_bit(vid, vdi_inuse)) {

            break;

        }



        /* we don't need to read entire object */

        ret = read_object(fd, s->aio_context, (char *)&inode,

                          vid_to_vdi_oid(vid),

                          0, SD_INODE_SIZE - sizeof(inode.data_vdi_id), 0,

                          s->cache_flags);



        if (ret) {

            continue;

        }



        if (!strcmp(inode.name, s->name) && is_snapshot(&inode)) {

            sn_tab[found].date_sec = inode.snap_ctime >> 32;

            sn_tab[found].date_nsec = inode.snap_ctime & 0xffffffff;

            sn_tab[found].vm_state_size = inode.vm_state_size;

            sn_tab[found].vm_clock_nsec = inode.vm_clock_nsec;



            snprintf(sn_tab[found].id_str, sizeof(sn_tab[found].id_str),

                     "%" PRIu32, inode.snap_id);

            pstrcpy(sn_tab[found].name,

                    MIN(sizeof(sn_tab[found].name), sizeof(inode.tag)),

                    inode.tag);

            found++;

        }

    }



    closesocket(fd);

out:

    *psn_tab = sn_tab;



    g_free(vdi_inuse);



    if (ret < 0) {

        return ret;

    }



    return found;

}

static void config_parse(GAConfig *config, int argc, char **argv)

{

    const char *sopt = "hVvdm:p:l:f:F::b:s:t:D";

    int opt_ind = 0, ch;

    const struct option lopt[] = {

        { "help", 0, NULL, 'h' },

        { "version", 0, NULL, 'V' },

        { "dump-conf", 0, NULL, 'D' },

        { "logfile", 1, NULL, 'l' },

        { "pidfile", 1, NULL, 'f' },

#ifdef CONFIG_FSFREEZE

        { "fsfreeze-hook", 2, NULL, 'F' },

#endif

        { "verbose", 0, NULL, 'v' },

        { "method", 1, NULL, 'm' },

        { "path", 1, NULL, 'p' },

        { "daemonize", 0, NULL, 'd' },

        { "blacklist", 1, NULL, 'b' },

#ifdef _WIN32

        { "service", 1, NULL, 's' },

#endif

        { "statedir", 1, NULL, 't' },

        { NULL, 0, NULL, 0 }

    };



    config->log_level = G_LOG_LEVEL_ERROR | G_LOG_LEVEL_CRITICAL;



    while ((ch = getopt_long(argc, argv, sopt, lopt, &opt_ind)) != -1) {

        switch (ch) {

        case 'm':

            g_free(config->method);

            config->method = g_strdup(optarg);

            break;

        case 'p':

            g_free(config->channel_path);

            config->channel_path = g_strdup(optarg);

            break;

        case 'l':

            g_free(config->log_filepath);

            config->log_filepath = g_strdup(optarg);

            break;

        case 'f':

            g_free(config->pid_filepath);

            config->pid_filepath = g_strdup(optarg);

            break;

#ifdef CONFIG_FSFREEZE

        case 'F':

            g_free(config->fsfreeze_hook);

            config->fsfreeze_hook = g_strdup(optarg ?: QGA_FSFREEZE_HOOK_DEFAULT);

            break;

#endif

        case 't':

            g_free(config->state_dir);

            config->state_dir = g_strdup(optarg);

            break;

        case 'v':

            /* enable all log levels */

            config->log_level = G_LOG_LEVEL_MASK;

            break;

        case 'V':

            printf("QEMU Guest Agent %s\n", QEMU_VERSION);

            exit(EXIT_SUCCESS);

        case 'd':

            config->daemonize = 1;

            break;

        case 'D':

            config->dumpconf = 1;

            break;

        case 'b': {

            if (is_help_option(optarg)) {

                qmp_for_each_command(ga_print_cmd, NULL);

                exit(EXIT_SUCCESS);

            }

            config->blacklist = g_list_concat(config->blacklist,

                                             split_list(optarg, ","));

            break;

        }

#ifdef _WIN32

        case 's':

            config->service = optarg;

            if (strcmp(config->service, "install") == 0) {

                if (ga_install_vss_provider()) {

                    exit(EXIT_FAILURE);

                }

                if (ga_install_service(config->channel_path,

                                       config->log_filepath, config->state_dir)) {

                    exit(EXIT_FAILURE);

                }

                exit(EXIT_SUCCESS);

            } else if (strcmp(config->service, "uninstall") == 0) {

                ga_uninstall_vss_provider();

                exit(ga_uninstall_service());

            } else if (strcmp(config->service, "vss-install") == 0) {

                if (ga_install_vss_provider()) {

                    exit(EXIT_FAILURE);

                }

                exit(EXIT_SUCCESS);

            } else if (strcmp(config->service, "vss-uninstall") == 0) {

                ga_uninstall_vss_provider();

                exit(EXIT_SUCCESS);

            } else {

                printf("Unknown service command.\n");

                exit(EXIT_FAILURE);

            }

            break;

#endif

        case 'h':

            usage(argv[0]);

            exit(EXIT_SUCCESS);

        case '?':

            g_print("Unknown option, try '%s --help' for more information.\n",

                    argv[0]);

            exit(EXIT_FAILURE);

        }

    }

}

static void gen_abs(DisasContext *ctx)

{

    int l1 = gen_new_label();

    int l2 = gen_new_label();

    tcg_gen_brcondi_tl(TCG_COND_GE, cpu_gpr[rA(ctx->opcode)], 0, l1);

    tcg_gen_neg_tl(cpu_gpr[rD(ctx->opcode)], cpu_gpr[rA(ctx->opcode)]);

    tcg_gen_br(l2);

    gen_set_label(l1);

    tcg_gen_mov_tl(cpu_gpr[rD(ctx->opcode)], cpu_gpr[rA(ctx->opcode)]);

    gen_set_label(l2);

    if (unlikely(Rc(ctx->opcode) != 0))

        gen_set_Rc0(ctx, cpu_gpr[rD(ctx->opcode)]);

}

