static void t_gen_lz_i32(TCGv d, TCGv x)

{

	TCGv y, m, n;



	y = tcg_temp_new(TCG_TYPE_I32);

	m = tcg_temp_new(TCG_TYPE_I32);

	n = tcg_temp_new(TCG_TYPE_I32);



	/* y = -(x >> 16)  */

	tcg_gen_shri_i32(y, x, 16);

	tcg_gen_neg_i32(y, y);



	/* m = (y >> 16) & 16  */

	tcg_gen_sari_i32(m, y, 16);

	tcg_gen_andi_i32(m, m, 16);



	/* n = 16 - m  */

	tcg_gen_sub_i32(n, tcg_const_i32(16), m);

	/* x = x >> m  */

	tcg_gen_shr_i32(x, x, m);



	/* y = x - 0x100  */

	tcg_gen_subi_i32(y, x, 0x100);

	/* m = (y >> 16) & 8  */

	tcg_gen_sari_i32(m, y, 16);

	tcg_gen_andi_i32(m, m, 8);

	/* n = n + m  */

	tcg_gen_add_i32(n, n, m);

	/* x = x << m  */

	tcg_gen_shl_i32(x, x, m);



	/* y = x - 0x1000  */

	tcg_gen_subi_i32(y, x, 0x1000);

	/* m = (y >> 16) & 4  */

	tcg_gen_sari_i32(m, y, 16);

	tcg_gen_andi_i32(m, m, 4);

	/* n = n + m  */

	tcg_gen_add_i32(n, n, m);

	/* x = x << m  */

	tcg_gen_shl_i32(x, x, m);



	/* y = x - 0x4000  */

	tcg_gen_subi_i32(y, x, 0x4000);

	/* m = (y >> 16) & 2  */

	tcg_gen_sari_i32(m, y, 16);

	tcg_gen_andi_i32(m, m, 2);

	/* n = n + m  */

	tcg_gen_add_i32(n, n, m);

	/* x = x << m  */

	tcg_gen_shl_i32(x, x, m);



	/* y = x >> 14  */

	tcg_gen_shri_i32(y, x, 14);

	/* m = y & ~(y >> 1)  */

	tcg_gen_sari_i32(m, y, 1);

	tcg_gen_not_i32(m, m);

	tcg_gen_and_i32(m, m, y);



	/* d = n + 2 - m  */

	tcg_gen_addi_i32(d, n, 2);

	tcg_gen_sub_i32(d, d, m);



	tcg_temp_free(y);

	tcg_temp_free(m);

	tcg_temp_free(n);

}

static QVirtIOSCSI *qvirtio_scsi_pci_init(int slot)

{

    QVirtIOSCSI *vs;

    QVirtioPCIDevice *dev;

    void *addr;

    int i;



    vs = g_new0(QVirtIOSCSI, 1);

    vs->alloc = pc_alloc_init();

    vs->bus = qpci_init_pc();



    dev = qvirtio_pci_device_find(vs->bus, QVIRTIO_SCSI_DEVICE_ID);

    vs->dev = (QVirtioDevice *)dev;

    g_assert(dev != NULL);

    g_assert_cmphex(vs->dev->device_type, ==, QVIRTIO_SCSI_DEVICE_ID);



    qvirtio_pci_device_enable(dev);

    qvirtio_reset(&qvirtio_pci, vs->dev);

    qvirtio_set_acknowledge(&qvirtio_pci, vs->dev);

    qvirtio_set_driver(&qvirtio_pci, vs->dev);



    addr = dev->addr + QVIRTIO_PCI_DEVICE_SPECIFIC_NO_MSIX;

    vs->num_queues = qvirtio_config_readl(&qvirtio_pci, vs->dev,

                                          (uint64_t)(uintptr_t)addr);



    g_assert_cmpint(vs->num_queues, <, MAX_NUM_QUEUES);



    for (i = 0; i < vs->num_queues + 2; i++) {

        vs->vq[i] = qvirtqueue_setup(&qvirtio_pci, vs->dev, vs->alloc, i);

    }



    return vs;

}

static MachineClass *machine_parse(const char *name)

{

    MachineClass *mc = NULL;

    GSList *el, *machines = object_class_get_list(TYPE_MACHINE, false);



    if (name) {

        mc = find_machine(name);

    }

    if (mc) {

        return mc;

    }

    if (name && !is_help_option(name)) {

        error_report("Unsupported machine type");

        error_printf("Use -machine help to list supported machines!\n");

    } else {

        printf("Supported machines are:\n");

        for (el = machines; el; el = el->next) {

            MachineClass *mc = el->data;

            if (mc->alias) {

                printf("%-20s %s (alias of %s)\n", mc->alias, mc->desc, mc->name);

            }

            printf("%-20s %s%s\n", mc->name, mc->desc,

                   mc->is_default ? " (default)" : "");

        }

    }



    g_slist_free(machines);

    exit(!name || !is_help_option(name));

}

