static void tcg_out_br(TCGContext *s, int label_index)

{

    TCGLabel *l = &s->labels[label_index];

    uint64_t imm;



    /* We pay attention here to not modify the branch target by reading

       the existing value and using it again. This ensure that caches and

       memory are kept coherent during retranslation. */

    if (l->has_value) {

        imm = l->u.value_ptr -  s->code_ptr;

    } else {

        imm = get_reloc_pcrel21b_slot2(s->code_ptr);

        tcg_out_reloc(s, s->code_ptr, R_IA64_PCREL21B, label_index, 0);

    }



    tcg_out_bundle(s, mmB,

                   INSN_NOP_M,

                   INSN_NOP_M,

                   tcg_opc_b1(TCG_REG_P0, OPC_BR_SPTK_MANY_B1, imm));

}

static uint32_t virtio_blk_get_features(VirtIODevice *vdev, uint32_t features)

{

    VirtIOBlock *s = to_virtio_blk(vdev);



    features |= (1 << VIRTIO_BLK_F_SEG_MAX);

    features |= (1 << VIRTIO_BLK_F_GEOMETRY);

    features |= (1 << VIRTIO_BLK_F_TOPOLOGY);

    features |= (1 << VIRTIO_BLK_F_BLK_SIZE);

    features |= (1 << VIRTIO_BLK_F_SCSI);



    features |= (1 << VIRTIO_BLK_F_CONFIG_WCE);

    if (bdrv_enable_write_cache(s->bs))

        features |= (1 << VIRTIO_BLK_F_WCE);



    if (bdrv_is_read_only(s->bs))

        features |= 1 << VIRTIO_BLK_F_RO;



    return features;

}

static void lm32_evr_init(MachineState *machine)

{

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = machine->kernel_filename;

    LM32CPU *cpu;

    CPULM32State *env;

    DriveInfo *dinfo;

    MemoryRegion *address_space_mem =  get_system_memory();

    MemoryRegion *phys_ram = g_new(MemoryRegion, 1);

    qemu_irq *cpu_irq, irq[32];

    ResetInfo *reset_info;

    int i;



    /* memory map */

    hwaddr flash_base  = 0x04000000;

    size_t flash_sector_size       = 256 * 1024;

    size_t flash_size              = 32 * 1024 * 1024;

    hwaddr ram_base    = 0x08000000;

    size_t ram_size                = 64 * 1024 * 1024;

    hwaddr timer0_base = 0x80002000;

    hwaddr uart0_base  = 0x80006000;

    hwaddr timer1_base = 0x8000a000;

    int uart0_irq                  = 0;

    int timer0_irq                 = 1;

    int timer1_irq                 = 3;



    reset_info = g_malloc0(sizeof(ResetInfo));



    if (cpu_model == NULL) {

        cpu_model = "lm32-full";

    }

    cpu = cpu_lm32_init(cpu_model);

    if (cpu == NULL) {

        fprintf(stderr, "qemu: unable to find CPU '%s'\n", cpu_model);

        exit(1);

    }



    env = &cpu->env;

    reset_info->cpu = cpu;



    reset_info->flash_base = flash_base;



    memory_region_init_ram(phys_ram, NULL, "lm32_evr.sdram", ram_size,

                           &error_abort);

    vmstate_register_ram_global(phys_ram);

    memory_region_add_subregion(address_space_mem, ram_base, phys_ram);



    dinfo = drive_get(IF_PFLASH, 0, 0);

    /* Spansion S29NS128P */

    pflash_cfi02_register(flash_base, NULL, "lm32_evr.flash", flash_size,

                          dinfo ? blk_bs(blk_by_legacy_dinfo(dinfo)) : NULL,

                          flash_sector_size, flash_size / flash_sector_size,

                          1, 2, 0x01, 0x7e, 0x43, 0x00, 0x555, 0x2aa, 1);



    /* create irq lines */

    cpu_irq = qemu_allocate_irqs(cpu_irq_handler, cpu, 1);

    env->pic_state = lm32_pic_init(*cpu_irq);

    for (i = 0; i < 32; i++) {

        irq[i] = qdev_get_gpio_in(env->pic_state, i);

    }



    sysbus_create_simple("lm32-uart", uart0_base, irq[uart0_irq]);

    sysbus_create_simple("lm32-timer", timer0_base, irq[timer0_irq]);

    sysbus_create_simple("lm32-timer", timer1_base, irq[timer1_irq]);



    /* make sure juart isn't the first chardev */

    env->juart_state = lm32_juart_init();



    reset_info->bootstrap_pc = flash_base;



    if (kernel_filename) {

        uint64_t entry;

        int kernel_size;



        kernel_size = load_elf(kernel_filename, NULL, NULL, &entry, NULL, NULL,

                               1, ELF_MACHINE, 0);

        reset_info->bootstrap_pc = entry;



        if (kernel_size < 0) {

            kernel_size = load_image_targphys(kernel_filename, ram_base,

                                              ram_size);

            reset_info->bootstrap_pc = ram_base;

        }



        if (kernel_size < 0) {

            fprintf(stderr, "qemu: could not load kernel '%s'\n",

                    kernel_filename);

            exit(1);

        }

    }



    qemu_register_reset(main_cpu_reset, reset_info);

}

static void test_qemu_strtosz_trailing(void)

{

    const char *str;

    char *endptr = NULL;

    int64_t res;



    str = "123xxx";

    res = qemu_strtosz_MiB(str, &endptr);

    g_assert_cmpint(res, ==, 123 * M_BYTE);

    g_assert(endptr == str + 3);



    res = qemu_strtosz(str, NULL);

    g_assert_cmpint(res, ==, -EINVAL);



    str = "1kiB";

    res = qemu_strtosz(str, &endptr);

    g_assert_cmpint(res, ==, 1024);

    g_assert(endptr == str + 2);



    res = qemu_strtosz(str, NULL);

    g_assert_cmpint(res, ==, -EINVAL);

}

build_header(BIOSLinker *linker, GArray *table_data,

             AcpiTableHeader *h, const char *sig, int len, uint8_t rev,

             const char *oem_id, const char *oem_table_id)

{

    memcpy(&h->signature, sig, 4);

    h->length = cpu_to_le32(len);

    h->revision = rev;



    if (oem_id) {

        strncpy((char *)h->oem_id, oem_id, sizeof h->oem_id);

    } else {

        memcpy(h->oem_id, ACPI_BUILD_APPNAME6, 6);

    }



    if (oem_table_id) {

        strncpy((char *)h->oem_table_id, oem_table_id, sizeof(h->oem_table_id));

    } else {

        memcpy(h->oem_table_id, ACPI_BUILD_APPNAME4, 4);

        memcpy(h->oem_table_id + 4, sig, 4);

    }



    h->oem_revision = cpu_to_le32(1);

    memcpy(h->asl_compiler_id, ACPI_BUILD_APPNAME4, 4);

    h->asl_compiler_revision = cpu_to_le32(1);

    h->checksum = 0;

    /* Checksum to be filled in by Guest linker */

    bios_linker_loader_add_checksum(linker, ACPI_BUILD_TABLE_FILE,

                                    h, len, &h->checksum);

}

static void tcg_out_op(TCGContext *s, TCGOpcode opc, const TCGArg *args,

                       const int *const_args)

{

    uint8_t *old_code_ptr = s->code_ptr;



    tcg_out_op_t(s, opc);



    switch (opc) {

    case INDEX_op_exit_tb:

        tcg_out64(s, args[0]);

        break;

    case INDEX_op_goto_tb:

        if (s->tb_jmp_offset) {

            /* Direct jump method. */

            assert(args[0] < ARRAY_SIZE(s->tb_jmp_offset));

            s->tb_jmp_offset[args[0]] = s->code_ptr - s->code_buf;

            tcg_out32(s, 0);

        } else {

            /* Indirect jump method. */

            TODO();

        }

        assert(args[0] < ARRAY_SIZE(s->tb_next_offset));

        s->tb_next_offset[args[0]] = s->code_ptr - s->code_buf;

        break;

    case INDEX_op_br:

        tci_out_label(s, args[0]);

        break;

    case INDEX_op_call:

        tcg_out_ri(s, const_args[0], args[0]);

        break;

    case INDEX_op_setcond_i32:

        tcg_out_r(s, args[0]);

        tcg_out_r(s, args[1]);

        tcg_out_ri32(s, const_args[2], args[2]);

        tcg_out8(s, args[3]);   /* condition */

        break;

#if TCG_TARGET_REG_BITS == 32

    case INDEX_op_setcond2_i32:

        /* setcond2_i32 cond, t0, t1_low, t1_high, t2_low, t2_high */

        tcg_out_r(s, args[0]);

        tcg_out_r(s, args[1]);

        tcg_out_r(s, args[2]);

        tcg_out_ri32(s, const_args[3], args[3]);

        tcg_out_ri32(s, const_args[4], args[4]);

        tcg_out8(s, args[5]);   /* condition */

        break;

#elif TCG_TARGET_REG_BITS == 64

    case INDEX_op_setcond_i64:

        tcg_out_r(s, args[0]);

        tcg_out_r(s, args[1]);

        tcg_out_ri64(s, const_args[2], args[2]);

        tcg_out8(s, args[3]);   /* condition */

        break;

#endif

    case INDEX_op_movi_i32:

        TODO(); /* Handled by tcg_out_movi? */

        break;

    case INDEX_op_ld8u_i32:

    case INDEX_op_ld8s_i32:

    case INDEX_op_ld16u_i32:

    case INDEX_op_ld16s_i32:

    case INDEX_op_ld_i32:

    case INDEX_op_st8_i32:

    case INDEX_op_st16_i32:

    case INDEX_op_st_i32:

    case INDEX_op_ld8u_i64:

    case INDEX_op_ld8s_i64:

    case INDEX_op_ld16u_i64:

    case INDEX_op_ld16s_i64:

    case INDEX_op_ld32u_i64:

    case INDEX_op_ld32s_i64:

    case INDEX_op_ld_i64:

    case INDEX_op_st8_i64:

    case INDEX_op_st16_i64:

    case INDEX_op_st32_i64:

    case INDEX_op_st_i64:

        tcg_out_r(s, args[0]);

        tcg_out_r(s, args[1]);

        assert(args[2] == (uint32_t)args[2]);

        tcg_out32(s, args[2]);

        break;

    case INDEX_op_add_i32:

    case INDEX_op_sub_i32:

    case INDEX_op_mul_i32:

    case INDEX_op_and_i32:

    case INDEX_op_andc_i32:     /* Optional (TCG_TARGET_HAS_andc_i32). */

    case INDEX_op_eqv_i32:      /* Optional (TCG_TARGET_HAS_eqv_i32). */

    case INDEX_op_nand_i32:     /* Optional (TCG_TARGET_HAS_nand_i32). */

    case INDEX_op_nor_i32:      /* Optional (TCG_TARGET_HAS_nor_i32). */

    case INDEX_op_or_i32:

    case INDEX_op_orc_i32:      /* Optional (TCG_TARGET_HAS_orc_i32). */

    case INDEX_op_xor_i32:

    case INDEX_op_shl_i32:

    case INDEX_op_shr_i32:

    case INDEX_op_sar_i32:

    case INDEX_op_rotl_i32:     /* Optional (TCG_TARGET_HAS_rot_i32). */

    case INDEX_op_rotr_i32:     /* Optional (TCG_TARGET_HAS_rot_i32). */

        tcg_out_r(s, args[0]);

        tcg_out_ri32(s, const_args[1], args[1]);

        tcg_out_ri32(s, const_args[2], args[2]);

        break;

    case INDEX_op_deposit_i32:  /* Optional (TCG_TARGET_HAS_deposit_i32). */

        tcg_out_r(s, args[0]);

        tcg_out_r(s, args[1]);

        tcg_out_r(s, args[2]);

        assert(args[3] <= UINT8_MAX);

        tcg_out8(s, args[3]);

        assert(args[4] <= UINT8_MAX);

        tcg_out8(s, args[4]);

        break;



#if TCG_TARGET_REG_BITS == 64

    case INDEX_op_mov_i64:

    case INDEX_op_movi_i64:

        TODO();

        break;

    case INDEX_op_add_i64:

    case INDEX_op_sub_i64:

    case INDEX_op_mul_i64:

    case INDEX_op_and_i64:

    case INDEX_op_andc_i64:     /* Optional (TCG_TARGET_HAS_andc_i64). */

    case INDEX_op_eqv_i64:      /* Optional (TCG_TARGET_HAS_eqv_i64). */

    case INDEX_op_nand_i64:     /* Optional (TCG_TARGET_HAS_nand_i64). */

    case INDEX_op_nor_i64:      /* Optional (TCG_TARGET_HAS_nor_i64). */

    case INDEX_op_or_i64:

    case INDEX_op_orc_i64:      /* Optional (TCG_TARGET_HAS_orc_i64). */

    case INDEX_op_xor_i64:

    case INDEX_op_shl_i64:

    case INDEX_op_shr_i64:

    case INDEX_op_sar_i64:

        /* TODO: Implementation of rotl_i64, rotr_i64 missing in tci.c. */

    case INDEX_op_rotl_i64:     /* Optional (TCG_TARGET_HAS_rot_i64). */

    case INDEX_op_rotr_i64:     /* Optional (TCG_TARGET_HAS_rot_i64). */

        tcg_out_r(s, args[0]);

        tcg_out_ri64(s, const_args[1], args[1]);

        tcg_out_ri64(s, const_args[2], args[2]);

        break;

    case INDEX_op_deposit_i64:  /* Optional (TCG_TARGET_HAS_deposit_i64). */

        tcg_out_r(s, args[0]);

        tcg_out_r(s, args[1]);

        tcg_out_r(s, args[2]);

        assert(args[3] <= UINT8_MAX);

        tcg_out8(s, args[3]);

        assert(args[4] <= UINT8_MAX);

        tcg_out8(s, args[4]);

        break;

    case INDEX_op_div_i64:      /* Optional (TCG_TARGET_HAS_div_i64). */

    case INDEX_op_divu_i64:     /* Optional (TCG_TARGET_HAS_div_i64). */

    case INDEX_op_rem_i64:      /* Optional (TCG_TARGET_HAS_div_i64). */

    case INDEX_op_remu_i64:     /* Optional (TCG_TARGET_HAS_div_i64). */

        TODO();

        break;

    case INDEX_op_div2_i64:     /* Optional (TCG_TARGET_HAS_div2_i64). */

    case INDEX_op_divu2_i64:    /* Optional (TCG_TARGET_HAS_div2_i64). */

        TODO();

        break;

    case INDEX_op_brcond_i64:

        tcg_out_r(s, args[0]);

        tcg_out_ri64(s, const_args[1], args[1]);

        tcg_out8(s, args[2]);           /* condition */

        tci_out_label(s, args[3]);

        break;

    case INDEX_op_bswap16_i64:  /* Optional (TCG_TARGET_HAS_bswap16_i64). */

    case INDEX_op_bswap32_i64:  /* Optional (TCG_TARGET_HAS_bswap32_i64). */

    case INDEX_op_bswap64_i64:  /* Optional (TCG_TARGET_HAS_bswap64_i64). */

    case INDEX_op_not_i64:      /* Optional (TCG_TARGET_HAS_not_i64). */

    case INDEX_op_neg_i64:      /* Optional (TCG_TARGET_HAS_neg_i64). */

    case INDEX_op_ext8s_i64:    /* Optional (TCG_TARGET_HAS_ext8s_i64). */

    case INDEX_op_ext8u_i64:    /* Optional (TCG_TARGET_HAS_ext8u_i64). */

    case INDEX_op_ext16s_i64:   /* Optional (TCG_TARGET_HAS_ext16s_i64). */

    case INDEX_op_ext16u_i64:   /* Optional (TCG_TARGET_HAS_ext16u_i64). */

    case INDEX_op_ext32s_i64:   /* Optional (TCG_TARGET_HAS_ext32s_i64). */

    case INDEX_op_ext32u_i64:   /* Optional (TCG_TARGET_HAS_ext32u_i64). */

#endif /* TCG_TARGET_REG_BITS == 64 */

    case INDEX_op_neg_i32:      /* Optional (TCG_TARGET_HAS_neg_i32). */

    case INDEX_op_not_i32:      /* Optional (TCG_TARGET_HAS_not_i32). */

    case INDEX_op_ext8s_i32:    /* Optional (TCG_TARGET_HAS_ext8s_i32). */

    case INDEX_op_ext16s_i32:   /* Optional (TCG_TARGET_HAS_ext16s_i32). */

    case INDEX_op_ext8u_i32:    /* Optional (TCG_TARGET_HAS_ext8u_i32). */

    case INDEX_op_ext16u_i32:   /* Optional (TCG_TARGET_HAS_ext16u_i32). */

    case INDEX_op_bswap16_i32:  /* Optional (TCG_TARGET_HAS_bswap16_i32). */

    case INDEX_op_bswap32_i32:  /* Optional (TCG_TARGET_HAS_bswap32_i32). */

        tcg_out_r(s, args[0]);

        tcg_out_r(s, args[1]);

        break;

    case INDEX_op_div_i32:      /* Optional (TCG_TARGET_HAS_div_i32). */

    case INDEX_op_divu_i32:     /* Optional (TCG_TARGET_HAS_div_i32). */

    case INDEX_op_rem_i32:      /* Optional (TCG_TARGET_HAS_div_i32). */

    case INDEX_op_remu_i32:     /* Optional (TCG_TARGET_HAS_div_i32). */

        tcg_out_r(s, args[0]);

        tcg_out_ri32(s, const_args[1], args[1]);

        tcg_out_ri32(s, const_args[2], args[2]);

        break;

    case INDEX_op_div2_i32:     /* Optional (TCG_TARGET_HAS_div2_i32). */

    case INDEX_op_divu2_i32:    /* Optional (TCG_TARGET_HAS_div2_i32). */

        TODO();

        break;

#if TCG_TARGET_REG_BITS == 32

    case INDEX_op_add2_i32:

    case INDEX_op_sub2_i32:

        tcg_out_r(s, args[0]);

        tcg_out_r(s, args[1]);

        tcg_out_r(s, args[2]);

        tcg_out_r(s, args[3]);

        tcg_out_r(s, args[4]);

        tcg_out_r(s, args[5]);

        break;

    case INDEX_op_brcond2_i32:

        tcg_out_r(s, args[0]);

        tcg_out_r(s, args[1]);

        tcg_out_ri32(s, const_args[2], args[2]);

        tcg_out_ri32(s, const_args[3], args[3]);

        tcg_out8(s, args[4]);           /* condition */

        tci_out_label(s, args[5]);

        break;

    case INDEX_op_mulu2_i32:

        tcg_out_r(s, args[0]);

        tcg_out_r(s, args[1]);

        tcg_out_r(s, args[2]);

        tcg_out_r(s, args[3]);

        break;

#endif

    case INDEX_op_brcond_i32:

        tcg_out_r(s, args[0]);

        tcg_out_ri32(s, const_args[1], args[1]);

        tcg_out8(s, args[2]);           /* condition */

        tci_out_label(s, args[3]);

        break;

    case INDEX_op_qemu_ld8u:

    case INDEX_op_qemu_ld8s:

    case INDEX_op_qemu_ld16u:

    case INDEX_op_qemu_ld16s:

    case INDEX_op_qemu_ld32:

#if TCG_TARGET_REG_BITS == 64

    case INDEX_op_qemu_ld32s:

    case INDEX_op_qemu_ld32u:

#endif

        tcg_out_r(s, *args++);

        tcg_out_r(s, *args++);

#if TARGET_LONG_BITS > TCG_TARGET_REG_BITS

        tcg_out_r(s, *args++);

#endif

#ifdef CONFIG_SOFTMMU

        tcg_out_i(s, *args);

#endif

        break;

    case INDEX_op_qemu_ld64:

        tcg_out_r(s, *args++);

#if TCG_TARGET_REG_BITS == 32

        tcg_out_r(s, *args++);

#endif

        tcg_out_r(s, *args++);

#if TARGET_LONG_BITS > TCG_TARGET_REG_BITS

        tcg_out_r(s, *args++);

#endif

#ifdef CONFIG_SOFTMMU

        tcg_out_i(s, *args);

#endif

        break;

    case INDEX_op_qemu_st8:

    case INDEX_op_qemu_st16:

    case INDEX_op_qemu_st32:

        tcg_out_r(s, *args++);

        tcg_out_r(s, *args++);

#if TARGET_LONG_BITS > TCG_TARGET_REG_BITS

        tcg_out_r(s, *args++);

#endif

#ifdef CONFIG_SOFTMMU

        tcg_out_i(s, *args);

#endif

        break;

    case INDEX_op_qemu_st64:

        tcg_out_r(s, *args++);

#if TCG_TARGET_REG_BITS == 32

        tcg_out_r(s, *args++);

#endif

        tcg_out_r(s, *args++);

#if TARGET_LONG_BITS > TCG_TARGET_REG_BITS

        tcg_out_r(s, *args++);

#endif

#ifdef CONFIG_SOFTMMU

        tcg_out_i(s, *args);

#endif

        break;

    case INDEX_op_end:

        TODO();

        break;

    default:

        fprintf(stderr, "Missing: %s\n", tcg_op_defs[opc].name);

        tcg_abort();

    }

    old_code_ptr[1] = s->code_ptr - old_code_ptr;

}

static int usbredir_check_filter(USBRedirDevice *dev)

{

    if (dev->interface_info.interface_count == 0) {

        ERROR("No interface info for device\n");

        goto error;

    }



    if (dev->filter_rules) {

        if (!usbredirparser_peer_has_cap(dev->parser,

                                    usb_redir_cap_connect_device_version)) {

            ERROR("Device filter specified and peer does not have the "

                  "connect_device_version capability\n");

            goto error;

        }



        if (usbredirfilter_check(

                dev->filter_rules,

                dev->filter_rules_count,

                dev->device_info.device_class,

                dev->device_info.device_subclass,

                dev->device_info.device_protocol,

                dev->interface_info.interface_class,

                dev->interface_info.interface_subclass,

                dev->interface_info.interface_protocol,

                dev->interface_info.interface_count,

                dev->device_info.vendor_id,

                dev->device_info.product_id,

                dev->device_info.device_version_bcd,

                0) != 0) {

            goto error;

        }

    }



    return 0;



error:

    usbredir_device_disconnect(dev);

    if (usbredirparser_peer_has_cap(dev->parser, usb_redir_cap_filter)) {

        usbredirparser_send_filter_reject(dev->parser);

        usbredirparser_do_write(dev->parser);

    }

    return -1;

}

int spapr_allocate_irq_block(int num, bool lsi)

{

    int first = -1;

    int i;



    for (i = 0; i < num; ++i) {

        int irq;



        irq = spapr_allocate_irq(0, lsi);

        if (!irq) {

            return -1;

        }



        if (0 == i) {

            first = irq;

        }



        /* If the above doesn't create a consecutive block then that's

         * an internal bug */

        assert(irq == (first + i));

    }



    return first;

}

static void vfio_realize(PCIDevice *pdev, Error **errp)

{

    VFIOPCIDevice *vdev = DO_UPCAST(VFIOPCIDevice, pdev, pdev);

    VFIODevice *vbasedev_iter;

    VFIOGroup *group;

    char *tmp, group_path[PATH_MAX], *group_name;

    Error *err = NULL;

    ssize_t len;

    struct stat st;

    int groupid;

    int i, ret;



    if (!vdev->vbasedev.sysfsdev) {

        if (!(~vdev->host.domain || ~vdev->host.bus ||

              ~vdev->host.slot || ~vdev->host.function)) {

            error_setg(errp, "No provided host device");

            error_append_hint(errp, "Use -vfio-pci,host=DDDD:BB:DD.F "

                              "or -vfio-pci,sysfsdev=PATH_TO_DEVICE\n");

            return;

        }

        vdev->vbasedev.sysfsdev =

            g_strdup_printf("/sys/bus/pci/devices/%04x:%02x:%02x.%01x",

                            vdev->host.domain, vdev->host.bus,

                            vdev->host.slot, vdev->host.function);

    }



    if (stat(vdev->vbasedev.sysfsdev, &st) < 0) {

        error_setg_errno(errp, errno, "no such host device");

        error_prepend(errp, ERR_PREFIX, vdev->vbasedev.sysfsdev);

        return;

    }



    vdev->vbasedev.name = g_strdup(basename(vdev->vbasedev.sysfsdev));

    vdev->vbasedev.ops = &vfio_pci_ops;

    vdev->vbasedev.type = VFIO_DEVICE_TYPE_PCI;



    tmp = g_strdup_printf("%s/iommu_group", vdev->vbasedev.sysfsdev);

    len = readlink(tmp, group_path, sizeof(group_path));

    g_free(tmp);



    if (len <= 0 || len >= sizeof(group_path)) {

        error_setg_errno(errp, len < 0 ? errno : ENAMETOOLONG,

                         "no iommu_group found");

        goto error;

    }



    group_path[len] = 0;



    group_name = basename(group_path);

    if (sscanf(group_name, "%d", &groupid) != 1) {

        error_setg_errno(errp, errno, "failed to read %s", group_path);

        goto error;

    }



    trace_vfio_realize(vdev->vbasedev.name, groupid);



    group = vfio_get_group(groupid, pci_device_iommu_address_space(pdev), errp);

    if (!group) {

        goto error;

    }



    QLIST_FOREACH(vbasedev_iter, &group->device_list, next) {

        if (strcmp(vbasedev_iter->name, vdev->vbasedev.name) == 0) {

            error_setg(errp, "device is already attached");

            vfio_put_group(group);

            goto error;

        }

    }



    ret = vfio_get_device(group, vdev->vbasedev.name, &vdev->vbasedev, errp);

    if (ret) {

        vfio_put_group(group);

        goto error;

    }



    vfio_populate_device(vdev, &err);

    if (err) {

        error_propagate(errp, err);

        goto error;

    }



    /* Get a copy of config space */

    ret = pread(vdev->vbasedev.fd, vdev->pdev.config,

                MIN(pci_config_size(&vdev->pdev), vdev->config_size),

                vdev->config_offset);

    if (ret < (int)MIN(pci_config_size(&vdev->pdev), vdev->config_size)) {

        ret = ret < 0 ? -errno : -EFAULT;

        error_setg_errno(errp, -ret, "failed to read device config space");

        goto error;

    }



    /* vfio emulates a lot for us, but some bits need extra love */

    vdev->emulated_config_bits = g_malloc0(vdev->config_size);



    /* QEMU can choose to expose the ROM or not */

    memset(vdev->emulated_config_bits + PCI_ROM_ADDRESS, 0xff, 4);



    /*

     * The PCI spec reserves vendor ID 0xffff as an invalid value.  The

     * device ID is managed by the vendor and need only be a 16-bit value.

     * Allow any 16-bit value for subsystem so they can be hidden or changed.

     */

    if (vdev->vendor_id != PCI_ANY_ID) {

        if (vdev->vendor_id >= 0xffff) {

            error_setg(errp, "invalid PCI vendor ID provided");

            goto error;

        }

        vfio_add_emulated_word(vdev, PCI_VENDOR_ID, vdev->vendor_id, ~0);

        trace_vfio_pci_emulated_vendor_id(vdev->vbasedev.name, vdev->vendor_id);

    } else {

        vdev->vendor_id = pci_get_word(pdev->config + PCI_VENDOR_ID);

    }



    if (vdev->device_id != PCI_ANY_ID) {

        if (vdev->device_id > 0xffff) {

            error_setg(errp, "invalid PCI device ID provided");

            goto error;

        }

        vfio_add_emulated_word(vdev, PCI_DEVICE_ID, vdev->device_id, ~0);

        trace_vfio_pci_emulated_device_id(vdev->vbasedev.name, vdev->device_id);

    } else {

        vdev->device_id = pci_get_word(pdev->config + PCI_DEVICE_ID);

    }



    if (vdev->sub_vendor_id != PCI_ANY_ID) {

        if (vdev->sub_vendor_id > 0xffff) {

            error_setg(errp, "invalid PCI subsystem vendor ID provided");

            goto error;

        }

        vfio_add_emulated_word(vdev, PCI_SUBSYSTEM_VENDOR_ID,

                               vdev->sub_vendor_id, ~0);

        trace_vfio_pci_emulated_sub_vendor_id(vdev->vbasedev.name,

                                              vdev->sub_vendor_id);

    }



    if (vdev->sub_device_id != PCI_ANY_ID) {

        if (vdev->sub_device_id > 0xffff) {

            error_setg(errp, "invalid PCI subsystem device ID provided");

            goto error;

        }

        vfio_add_emulated_word(vdev, PCI_SUBSYSTEM_ID, vdev->sub_device_id, ~0);

        trace_vfio_pci_emulated_sub_device_id(vdev->vbasedev.name,

                                              vdev->sub_device_id);

    }



    /* QEMU can change multi-function devices to single function, or reverse */

    vdev->emulated_config_bits[PCI_HEADER_TYPE] =

                                              PCI_HEADER_TYPE_MULTI_FUNCTION;



    /* Restore or clear multifunction, this is always controlled by QEMU */

    if (vdev->pdev.cap_present & QEMU_PCI_CAP_MULTIFUNCTION) {

        vdev->pdev.config[PCI_HEADER_TYPE] |= PCI_HEADER_TYPE_MULTI_FUNCTION;

    } else {

        vdev->pdev.config[PCI_HEADER_TYPE] &= ~PCI_HEADER_TYPE_MULTI_FUNCTION;

    }



    /*

     * Clear host resource mapping info.  If we choose not to register a

     * BAR, such as might be the case with the option ROM, we can get

     * confusing, unwritable, residual addresses from the host here.

     */

    memset(&vdev->pdev.config[PCI_BASE_ADDRESS_0], 0, 24);

    memset(&vdev->pdev.config[PCI_ROM_ADDRESS], 0, 4);



    vfio_pci_size_rom(vdev);



    vfio_msix_early_setup(vdev, &err);

    if (err) {

        error_propagate(errp, err);

        goto error;

    }



    vfio_bars_setup(vdev);



    ret = vfio_add_capabilities(vdev, errp);

    if (ret) {

        goto out_teardown;

    }



    if (vdev->vga) {

        vfio_vga_quirk_setup(vdev);

    }



    for (i = 0; i < PCI_ROM_SLOT; i++) {

        vfio_bar_quirk_setup(vdev, i);

    }



    if (!vdev->igd_opregion &&

        vdev->features & VFIO_FEATURE_ENABLE_IGD_OPREGION) {

        struct vfio_region_info *opregion;



        if (vdev->pdev.qdev.hotplugged) {

            error_setg(errp,

                       "cannot support IGD OpRegion feature on hotplugged "

                       "device");

            goto out_teardown;

        }



        ret = vfio_get_dev_region_info(&vdev->vbasedev,

                        VFIO_REGION_TYPE_PCI_VENDOR_TYPE | PCI_VENDOR_ID_INTEL,

                        VFIO_REGION_SUBTYPE_INTEL_IGD_OPREGION, &opregion);

        if (ret) {

            error_setg_errno(errp, -ret,

                             "does not support requested IGD OpRegion feature");

            goto out_teardown;

        }



        ret = vfio_pci_igd_opregion_init(vdev, opregion, errp);

        g_free(opregion);

        if (ret) {

            goto out_teardown;

        }

    }



    /* QEMU emulates all of MSI & MSIX */

    if (pdev->cap_present & QEMU_PCI_CAP_MSIX) {

        memset(vdev->emulated_config_bits + pdev->msix_cap, 0xff,

               MSIX_CAP_LENGTH);

    }



    if (pdev->cap_present & QEMU_PCI_CAP_MSI) {

        memset(vdev->emulated_config_bits + pdev->msi_cap, 0xff,

               vdev->msi_cap_size);

    }



    if (vfio_pci_read_config(&vdev->pdev, PCI_INTERRUPT_PIN, 1)) {

        vdev->intx.mmap_timer = timer_new_ms(QEMU_CLOCK_VIRTUAL,

                                                  vfio_intx_mmap_enable, vdev);

        pci_device_set_intx_routing_notifier(&vdev->pdev, vfio_intx_update);

        ret = vfio_intx_enable(vdev, errp);

        if (ret) {

            goto out_teardown;

        }

    }



    vfio_register_err_notifier(vdev);

    vfio_register_req_notifier(vdev);

    vfio_setup_resetfn_quirk(vdev);



    return;



out_teardown:

    pci_device_set_intx_routing_notifier(&vdev->pdev, NULL);

    vfio_teardown_msi(vdev);

    vfio_bars_exit(vdev);

error:

    error_prepend(errp, ERR_PREFIX, vdev->vbasedev.name);

}

static void qmp_input_push(QmpInputVisitor *qiv, QObject *obj, Error **errp)

{

    GHashTable *h;

    StackObject *tos = &qiv->stack[qiv->nb_stack];



    assert(obj);

    if (qiv->nb_stack >= QIV_STACK_SIZE) {

        error_setg(errp, "An internal buffer overran");

        return;

    }



    tos->obj = obj;

    assert(!tos->h);

    assert(!tos->entry);



    if (qiv->strict && qobject_type(obj) == QTYPE_QDICT) {

        h = g_hash_table_new(g_str_hash, g_str_equal);

        qdict_iter(qobject_to_qdict(obj), qdict_add_key, h);

        tos->h = h;

    } else if (qobject_type(obj) == QTYPE_QLIST) {

        tos->entry = qlist_first(qobject_to_qlist(obj));

        tos->first = true;

    }



    qiv->nb_stack++;

}

static int qio_dns_resolver_lookup_sync_inet(QIODNSResolver *resolver,

                                             SocketAddressLegacy *addr,

                                             size_t *naddrs,

                                             SocketAddressLegacy ***addrs,

                                             Error **errp)

{

    struct addrinfo ai, *res, *e;

    InetSocketAddress *iaddr = addr->u.inet.data;

    char port[33];

    char uaddr[INET6_ADDRSTRLEN + 1];

    char uport[33];

    int rc;

    Error *err = NULL;

    size_t i;



    *naddrs = 0;

    *addrs = NULL;



    memset(&ai, 0, sizeof(ai));

    ai.ai_flags = AI_PASSIVE;

    if (iaddr->has_numeric && iaddr->numeric) {

        ai.ai_flags |= AI_NUMERICHOST | AI_NUMERICSERV;

    }

    ai.ai_family = inet_ai_family_from_address(iaddr, &err);

    ai.ai_socktype = SOCK_STREAM;



    if (err) {

        error_propagate(errp, err);

        return -1;

    }



    if (iaddr->host == NULL) {

        error_setg(errp, "host not specified");

        return -1;

    }

    if (iaddr->port != NULL) {

        pstrcpy(port, sizeof(port), iaddr->port);

    } else {

        port[0] = '\0';

    }



    rc = getaddrinfo(strlen(iaddr->host) ? iaddr->host : NULL,

                     strlen(port) ? port : NULL, &ai, &res);

    if (rc != 0) {

        error_setg(errp, "address resolution failed for %s:%s: %s",

                   iaddr->host, port, gai_strerror(rc));

        return -1;

    }



    for (e = res; e != NULL; e = e->ai_next) {

        (*naddrs)++;

    }



    *addrs = g_new0(SocketAddressLegacy *, *naddrs);



    /* create socket + bind */

    for (i = 0, e = res; e != NULL; i++, e = e->ai_next) {

        SocketAddressLegacy *newaddr = g_new0(SocketAddressLegacy, 1);

        InetSocketAddress *newiaddr = g_new0(InetSocketAddress, 1);

        newaddr->u.inet.data = newiaddr;

        newaddr->type = SOCKET_ADDRESS_LEGACY_KIND_INET;



        getnameinfo((struct sockaddr *)e->ai_addr, e->ai_addrlen,

                    uaddr, INET6_ADDRSTRLEN, uport, 32,

                    NI_NUMERICHOST | NI_NUMERICSERV);



        *newiaddr = (InetSocketAddress){

            .host = g_strdup(uaddr),

            .port = g_strdup(uport),

            .has_numeric = true,

            .numeric = true,

            .has_to = iaddr->has_to,

            .to = iaddr->to,

            .has_ipv4 = false,

            .has_ipv6 = false,

        };



        (*addrs)[i] = newaddr;

    }

    freeaddrinfo(res);

    return 0;

}

void helper_vmrun(target_ulong addr)

{

    uint32_t event_inj;

    uint32_t int_ctl;



    if (loglevel & CPU_LOG_TB_IN_ASM)

        fprintf(logfile,"vmrun! " TARGET_FMT_lx "\n", addr);



    env->vm_vmcb = addr;

    regs_to_env();



    /* save the current CPU state in the hsave page */

    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.gdtr.base), env->gdt.base);

    stl_phys(env->vm_hsave + offsetof(struct vmcb, save.gdtr.limit), env->gdt.limit);



    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.idtr.base), env->idt.base);

    stl_phys(env->vm_hsave + offsetof(struct vmcb, save.idtr.limit), env->idt.limit);



    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.cr0), env->cr[0]);

    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.cr2), env->cr[2]);

    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.cr3), env->cr[3]);

    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.cr4), env->cr[4]);

    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.cr8), env->cr[8]);

    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.dr6), env->dr[6]);

    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.dr7), env->dr[7]);



    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.efer), env->efer);

    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.rflags), compute_eflags());



    SVM_SAVE_SEG(env->vm_hsave, segs[R_ES], es);

    SVM_SAVE_SEG(env->vm_hsave, segs[R_CS], cs);

    SVM_SAVE_SEG(env->vm_hsave, segs[R_SS], ss);

    SVM_SAVE_SEG(env->vm_hsave, segs[R_DS], ds);



    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.rip), EIP);

    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.rsp), ESP);

    stq_phys(env->vm_hsave + offsetof(struct vmcb, save.rax), EAX);



    /* load the interception bitmaps so we do not need to access the

       vmcb in svm mode */

    /* We shift all the intercept bits so we can OR them with the TB

       flags later on */

    env->intercept            = (ldq_phys(env->vm_vmcb + offsetof(struct vmcb, control.intercept)) << INTERCEPT_INTR) | INTERCEPT_SVM_MASK;

    env->intercept_cr_read    = lduw_phys(env->vm_vmcb + offsetof(struct vmcb, control.intercept_cr_read));

    env->intercept_cr_write   = lduw_phys(env->vm_vmcb + offsetof(struct vmcb, control.intercept_cr_write));

    env->intercept_dr_read    = lduw_phys(env->vm_vmcb + offsetof(struct vmcb, control.intercept_dr_read));

    env->intercept_dr_write   = lduw_phys(env->vm_vmcb + offsetof(struct vmcb, control.intercept_dr_write));

    env->intercept_exceptions = ldl_phys(env->vm_vmcb + offsetof(struct vmcb, control.intercept_exceptions));



    env->gdt.base  = ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.gdtr.base));

    env->gdt.limit = ldl_phys(env->vm_vmcb + offsetof(struct vmcb, save.gdtr.limit));



    env->idt.base  = ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.idtr.base));

    env->idt.limit = ldl_phys(env->vm_vmcb + offsetof(struct vmcb, save.idtr.limit));



    /* clear exit_info_2 so we behave like the real hardware */

    stq_phys(env->vm_vmcb + offsetof(struct vmcb, control.exit_info_2), 0);



    cpu_x86_update_cr0(env, ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.cr0)));

    cpu_x86_update_cr4(env, ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.cr4)));

    cpu_x86_update_cr3(env, ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.cr3)));

    env->cr[2] = ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.cr2));

    int_ctl = ldl_phys(env->vm_vmcb + offsetof(struct vmcb, control.int_ctl));

    if (int_ctl & V_INTR_MASKING_MASK) {

        env->cr[8] = int_ctl & V_TPR_MASK;

        cpu_set_apic_tpr(env, env->cr[8]);

        if (env->eflags & IF_MASK)

            env->hflags |= HF_HIF_MASK;

    }



#ifdef TARGET_X86_64

    env->efer = ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.efer));

    env->hflags &= ~HF_LMA_MASK;

    if (env->efer & MSR_EFER_LMA)

       env->hflags |= HF_LMA_MASK;

#endif

    env->eflags = 0;

    load_eflags(ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.rflags)),

                ~(CC_O | CC_S | CC_Z | CC_A | CC_P | CC_C | DF_MASK));

    CC_OP = CC_OP_EFLAGS;

    CC_DST = 0xffffffff;



    SVM_LOAD_SEG(env->vm_vmcb, ES, es);

    SVM_LOAD_SEG(env->vm_vmcb, CS, cs);

    SVM_LOAD_SEG(env->vm_vmcb, SS, ss);

    SVM_LOAD_SEG(env->vm_vmcb, DS, ds);



    EIP = ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.rip));

    env->eip = EIP;

    ESP = ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.rsp));

    EAX = ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.rax));

    env->dr[7] = ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.dr7));

    env->dr[6] = ldq_phys(env->vm_vmcb + offsetof(struct vmcb, save.dr6));

    cpu_x86_set_cpl(env, ldub_phys(env->vm_vmcb + offsetof(struct vmcb, save.cpl)));



    /* FIXME: guest state consistency checks */



    switch(ldub_phys(env->vm_vmcb + offsetof(struct vmcb, control.tlb_ctl))) {

        case TLB_CONTROL_DO_NOTHING:

            break;

        case TLB_CONTROL_FLUSH_ALL_ASID:

            /* FIXME: this is not 100% correct but should work for now */

            tlb_flush(env, 1);

        break;

    }



    helper_stgi();



    regs_to_env();



    /* maybe we need to inject an event */

    event_inj = ldl_phys(env->vm_vmcb + offsetof(struct vmcb, control.event_inj));

    if (event_inj & SVM_EVTINJ_VALID) {

        uint8_t vector = event_inj & SVM_EVTINJ_VEC_MASK;

        uint16_t valid_err = event_inj & SVM_EVTINJ_VALID_ERR;

        uint32_t event_inj_err = ldl_phys(env->vm_vmcb + offsetof(struct vmcb, control.event_inj_err));

        stl_phys(env->vm_vmcb + offsetof(struct vmcb, control.event_inj), event_inj & ~SVM_EVTINJ_VALID);



        if (loglevel & CPU_LOG_TB_IN_ASM)

            fprintf(logfile, "Injecting(%#hx): ", valid_err);

        /* FIXME: need to implement valid_err */

        switch (event_inj & SVM_EVTINJ_TYPE_MASK) {

        case SVM_EVTINJ_TYPE_INTR:

                env->exception_index = vector;

                env->error_code = event_inj_err;

                env->exception_is_int = 1;

                env->exception_next_eip = -1;

                if (loglevel & CPU_LOG_TB_IN_ASM)

                    fprintf(logfile, "INTR");

                break;

        case SVM_EVTINJ_TYPE_NMI:

                env->exception_index = vector;

                env->error_code = event_inj_err;

                env->exception_is_int = 1;

                env->exception_next_eip = EIP;

                if (loglevel & CPU_LOG_TB_IN_ASM)

                    fprintf(logfile, "NMI");

                break;

        case SVM_EVTINJ_TYPE_EXEPT:

                env->exception_index = vector;

                env->error_code = event_inj_err;

                env->exception_is_int = 0;

                env->exception_next_eip = -1;

                if (loglevel & CPU_LOG_TB_IN_ASM)

                    fprintf(logfile, "EXEPT");

                break;

        case SVM_EVTINJ_TYPE_SOFT:

                env->exception_index = vector;

                env->error_code = event_inj_err;

                env->exception_is_int = 1;

                env->exception_next_eip = EIP;

                if (loglevel & CPU_LOG_TB_IN_ASM)

                    fprintf(logfile, "SOFT");

                break;

        }

        if (loglevel & CPU_LOG_TB_IN_ASM)

            fprintf(logfile, " %#x %#x\n", env->exception_index, env->error_code);

    }

    if ((int_ctl & V_IRQ_MASK) || (env->intercept & INTERCEPT_VINTR)) {

        env->interrupt_request |= CPU_INTERRUPT_VIRQ;

    }



    cpu_loop_exit();

}

