}

I2CBus *piix4_pm_init(PCIBus *bus, int devfn, uint32_t smb_io_base,

                      qemu_irq sci_irq, qemu_irq smi_irq,

                      int kvm_enabled, FWCfgState *fw_cfg,

                      DeviceState **piix4_pm)

{

    DeviceState *dev;

