    dev = DEVICE(pci_create(bus, devfn, TYPE_PIIX4_PM));

    qdev_prop_set_uint32(dev, "smb_io_base", smb_io_base);

    if (piix4_pm) {

        *piix4_pm = dev;

    }



    s = PIIX4_PM(dev);

    s->irq = sci_irq;

    s->smi_irq = smi_irq;

    s->kvm_enabled = kvm_enabled;

    if (xen_enabled()) {

        s->use_acpi_pci_hotplug = false;

    }



