void HELPER(wsr_lbeg)(uint32_t v)

{

    if (env->sregs[LBEG] != v) {

        tb_invalidate_phys_page_range(

                env->sregs[LEND] - 1, env->sregs[LEND], 0);

        env->sregs[LBEG] = v;

    }

}

void mips_cpu_do_interrupt(CPUState *cs)

{

#if !defined(CONFIG_USER_ONLY)

    MIPSCPU *cpu = MIPS_CPU(cs);

    CPUMIPSState *env = &cpu->env;

    bool update_badinstr = 0;

    target_ulong offset;

    int cause = -1;

    const char *name;



    if (qemu_loglevel_mask(CPU_LOG_INT)

        && cs->exception_index != EXCP_EXT_INTERRUPT) {

        if (cs->exception_index < 0 || cs->exception_index > EXCP_LAST) {

            name = "unknown";

        } else {

            name = excp_names[cs->exception_index];

        }



        qemu_log("%s enter: PC " TARGET_FMT_lx " EPC " TARGET_FMT_lx

                 " %s exception\n",

                 __func__, env->active_tc.PC, env->CP0_EPC, name);

    }

    if (cs->exception_index == EXCP_EXT_INTERRUPT &&

        (env->hflags & MIPS_HFLAG_DM)) {

        cs->exception_index = EXCP_DINT;

    }

    offset = 0x180;

    switch (cs->exception_index) {

    case EXCP_DSS:

        env->CP0_Debug |= 1 << CP0DB_DSS;

        /* Debug single step cannot be raised inside a delay slot and

           resume will always occur on the next instruction

           (but we assume the pc has always been updated during

           code translation). */

        env->CP0_DEPC = env->active_tc.PC | !!(env->hflags & MIPS_HFLAG_M16);

        goto enter_debug_mode;

    case EXCP_DINT:

        env->CP0_Debug |= 1 << CP0DB_DINT;

        goto set_DEPC;

    case EXCP_DIB:

        env->CP0_Debug |= 1 << CP0DB_DIB;

        goto set_DEPC;

    case EXCP_DBp:

        env->CP0_Debug |= 1 << CP0DB_DBp;

        goto set_DEPC;

    case EXCP_DDBS:

        env->CP0_Debug |= 1 << CP0DB_DDBS;

        goto set_DEPC;

    case EXCP_DDBL:

        env->CP0_Debug |= 1 << CP0DB_DDBL;

    set_DEPC:

        env->CP0_DEPC = exception_resume_pc(env);

        env->hflags &= ~MIPS_HFLAG_BMASK;

 enter_debug_mode:

        if (env->insn_flags & ISA_MIPS3) {

            env->hflags |= MIPS_HFLAG_64;

            if (!(env->insn_flags & ISA_MIPS64R6) ||

                env->CP0_Status & (1 << CP0St_KX)) {

                env->hflags &= ~MIPS_HFLAG_AWRAP;

            }

        }

        env->hflags |= MIPS_HFLAG_DM | MIPS_HFLAG_CP0;

        env->hflags &= ~(MIPS_HFLAG_KSU);

        /* EJTAG probe trap enable is not implemented... */

        if (!(env->CP0_Status & (1 << CP0St_EXL)))

            env->CP0_Cause &= ~(1U << CP0Ca_BD);

        env->active_tc.PC = (int32_t)0xBFC00480;

        set_hflags_for_handler(env);

        break;

    case EXCP_RESET:

        cpu_reset(CPU(cpu));

        break;

    case EXCP_SRESET:

        env->CP0_Status |= (1 << CP0St_SR);

        memset(env->CP0_WatchLo, 0, sizeof(env->CP0_WatchLo));

        goto set_error_EPC;

    case EXCP_NMI:

        env->CP0_Status |= (1 << CP0St_NMI);

 set_error_EPC:

        env->CP0_ErrorEPC = exception_resume_pc(env);

        env->hflags &= ~MIPS_HFLAG_BMASK;

        env->CP0_Status |= (1 << CP0St_ERL) | (1 << CP0St_BEV);

        if (env->insn_flags & ISA_MIPS3) {

            env->hflags |= MIPS_HFLAG_64;

            if (!(env->insn_flags & ISA_MIPS64R6) ||

                env->CP0_Status & (1 << CP0St_KX)) {

                env->hflags &= ~MIPS_HFLAG_AWRAP;

            }

        }

        env->hflags |= MIPS_HFLAG_CP0;

        env->hflags &= ~(MIPS_HFLAG_KSU);

        if (!(env->CP0_Status & (1 << CP0St_EXL)))

            env->CP0_Cause &= ~(1U << CP0Ca_BD);

        env->active_tc.PC = (int32_t)0xBFC00000;

        set_hflags_for_handler(env);

        break;

    case EXCP_EXT_INTERRUPT:

        cause = 0;

        if (env->CP0_Cause & (1 << CP0Ca_IV)) {

            uint32_t spacing = (env->CP0_IntCtl >> CP0IntCtl_VS) & 0x1f;



            if ((env->CP0_Status & (1 << CP0St_BEV)) || spacing == 0) {

                offset = 0x200;

            } else {

                uint32_t vector = 0;

                uint32_t pending = (env->CP0_Cause & CP0Ca_IP_mask) >> CP0Ca_IP;



                if (env->CP0_Config3 & (1 << CP0C3_VEIC)) {

                    /* For VEIC mode, the external interrupt controller feeds

                     * the vector through the CP0Cause IP lines.  */

                    vector = pending;

                } else {

                    /* Vectored Interrupts

                     * Mask with Status.IM7-IM0 to get enabled interrupts. */

                    pending &= (env->CP0_Status >> CP0St_IM) & 0xff;

                    /* Find the highest-priority interrupt. */

                    while (pending >>= 1) {

                        vector++;

                    }

                }

                offset = 0x200 + (vector * (spacing << 5));

            }

        }

        goto set_EPC;

    case EXCP_LTLBL:

        cause = 1;

        update_badinstr = !(env->error_code & EXCP_INST_NOTAVAIL);

        goto set_EPC;

    case EXCP_TLBL:

        cause = 2;

        update_badinstr = !(env->error_code & EXCP_INST_NOTAVAIL);

        if ((env->error_code & EXCP_TLB_NOMATCH) &&

            !(env->CP0_Status & (1 << CP0St_EXL))) {

#if defined(TARGET_MIPS64)

            int R = env->CP0_BadVAddr >> 62;

            int UX = (env->CP0_Status & (1 << CP0St_UX)) != 0;

            int SX = (env->CP0_Status & (1 << CP0St_SX)) != 0;

            int KX = (env->CP0_Status & (1 << CP0St_KX)) != 0;



            if (((R == 0 && UX) || (R == 1 && SX) || (R == 3 && KX)) &&

                (!(env->insn_flags & (INSN_LOONGSON2E | INSN_LOONGSON2F))))

                offset = 0x080;

            else

#endif

                offset = 0x000;

        }

        goto set_EPC;

    case EXCP_TLBS:

        cause = 3;

        update_badinstr = 1;

        if ((env->error_code & EXCP_TLB_NOMATCH) &&

            !(env->CP0_Status & (1 << CP0St_EXL))) {

#if defined(TARGET_MIPS64)

            int R = env->CP0_BadVAddr >> 62;

            int UX = (env->CP0_Status & (1 << CP0St_UX)) != 0;

            int SX = (env->CP0_Status & (1 << CP0St_SX)) != 0;

            int KX = (env->CP0_Status & (1 << CP0St_KX)) != 0;



            if (((R == 0 && UX) || (R == 1 && SX) || (R == 3 && KX)) &&

                (!(env->insn_flags & (INSN_LOONGSON2E | INSN_LOONGSON2F))))

                offset = 0x080;

            else

#endif

                offset = 0x000;

        }

        goto set_EPC;

    case EXCP_AdEL:

        cause = 4;

        update_badinstr = !(env->error_code & EXCP_INST_NOTAVAIL);

        goto set_EPC;

    case EXCP_AdES:

        cause = 5;

        update_badinstr = 1;

        goto set_EPC;

    case EXCP_IBE:

        cause = 6;

        goto set_EPC;

    case EXCP_DBE:

        cause = 7;

        goto set_EPC;

    case EXCP_SYSCALL:

        cause = 8;

        update_badinstr = 1;

        goto set_EPC;

    case EXCP_BREAK:

        cause = 9;

        update_badinstr = 1;

        goto set_EPC;

    case EXCP_RI:

        cause = 10;

        update_badinstr = 1;

        goto set_EPC;

    case EXCP_CpU:

        cause = 11;

        update_badinstr = 1;

        env->CP0_Cause = (env->CP0_Cause & ~(0x3 << CP0Ca_CE)) |

                         (env->error_code << CP0Ca_CE);

        goto set_EPC;

    case EXCP_OVERFLOW:

        cause = 12;

        update_badinstr = 1;

        goto set_EPC;

    case EXCP_TRAP:

        cause = 13;

        update_badinstr = 1;

        goto set_EPC;

    case EXCP_MSAFPE:

        cause = 14;

        update_badinstr = 1;

        goto set_EPC;

    case EXCP_FPE:

        cause = 15;

        update_badinstr = 1;

        goto set_EPC;

    case EXCP_C2E:

        cause = 18;

        goto set_EPC;

    case EXCP_TLBRI:

        cause = 19;

        update_badinstr = 1;

        goto set_EPC;

    case EXCP_TLBXI:

        cause = 20;

        goto set_EPC;

    case EXCP_MSADIS:

        cause = 21;

        update_badinstr = 1;

        goto set_EPC;

    case EXCP_MDMX:

        cause = 22;

        goto set_EPC;

    case EXCP_DWATCH:

        cause = 23;

        /* XXX: TODO: manage deferred watch exceptions */

        goto set_EPC;

    case EXCP_MCHECK:

        cause = 24;

        goto set_EPC;

    case EXCP_THREAD:

        cause = 25;

        goto set_EPC;

    case EXCP_DSPDIS:

        cause = 26;

        goto set_EPC;

    case EXCP_CACHE:

        cause = 30;

        if (env->CP0_Status & (1 << CP0St_BEV)) {

            offset = 0x100;

        } else {

            offset = 0x20000100;

        }

 set_EPC:

        if (!(env->CP0_Status & (1 << CP0St_EXL))) {

            env->CP0_EPC = exception_resume_pc(env);

            if (update_badinstr) {

                set_badinstr_registers(env);

            }

            if (env->hflags & MIPS_HFLAG_BMASK) {

                env->CP0_Cause |= (1U << CP0Ca_BD);

            } else {

                env->CP0_Cause &= ~(1U << CP0Ca_BD);

            }

            env->CP0_Status |= (1 << CP0St_EXL);

            if (env->insn_flags & ISA_MIPS3) {

                env->hflags |= MIPS_HFLAG_64;

                if (!(env->insn_flags & ISA_MIPS64R6) ||

                    env->CP0_Status & (1 << CP0St_KX)) {

                    env->hflags &= ~MIPS_HFLAG_AWRAP;

                }

            }

            env->hflags |= MIPS_HFLAG_CP0;

            env->hflags &= ~(MIPS_HFLAG_KSU);

        }

        env->hflags &= ~MIPS_HFLAG_BMASK;

        if (env->CP0_Status & (1 << CP0St_BEV)) {

            env->active_tc.PC = (int32_t)0xBFC00200;

        } else {

            env->active_tc.PC = (int32_t)(env->CP0_EBase & ~0x3ff);

        }

        env->active_tc.PC += offset;

        set_hflags_for_handler(env);

        env->CP0_Cause = (env->CP0_Cause & ~(0x1f << CP0Ca_EC)) | (cause << CP0Ca_EC);

        break;

    default:

        abort();

    }

    if (qemu_loglevel_mask(CPU_LOG_INT)

        && cs->exception_index != EXCP_EXT_INTERRUPT) {

        qemu_log("%s: PC " TARGET_FMT_lx " EPC " TARGET_FMT_lx " cause %d\n"

                 "    S %08x C %08x A " TARGET_FMT_lx " D " TARGET_FMT_lx "\n",

                 __func__, env->active_tc.PC, env->CP0_EPC, cause,

                 env->CP0_Status, env->CP0_Cause, env->CP0_BadVAddr,

                 env->CP0_DEPC);

    }

#endif

    cs->exception_index = EXCP_NONE;

}

uri_resolve_relative (const char *uri, const char * base)

{

    char *val = NULL;

    int ret;

    int ix;

    int pos = 0;

    int nbslash = 0;

    int len;

    URI *ref = NULL;

    URI *bas = NULL;

    char *bptr, *uptr, *vptr;

    int remove_path = 0;



    if ((uri == NULL) || (*uri == 0))

	return NULL;



    /*

     * First parse URI into a standard form

     */

    ref = uri_new ();

    /* If URI not already in "relative" form */

    if (uri[0] != '.') {

	ret = uri_parse_into (ref, uri);

	if (ret != 0)

	    goto done;		/* Error in URI, return NULL */

    } else

	ref->path = g_strdup(uri);



    /*

     * Next parse base into the same standard form

     */

    if ((base == NULL) || (*base == 0)) {

	val = g_strdup (uri);

	goto done;

    }

    bas = uri_new ();

    if (base[0] != '.') {

	ret = uri_parse_into (bas, base);

	if (ret != 0)

	    goto done;		/* Error in base, return NULL */

    } else

	bas->path = g_strdup(base);



    /*

     * If the scheme / server on the URI differs from the base,

     * just return the URI

     */

    if ((ref->scheme != NULL) &&

	((bas->scheme == NULL) ||

	 (strcmp (bas->scheme, ref->scheme)) ||

	 (strcmp (bas->server, ref->server)))) {

	val = g_strdup (uri);

	goto done;

    }

    if (!strcmp(bas->path, ref->path)) {

	val = g_strdup("");

	goto done;

    }

    if (bas->path == NULL) {

	val = g_strdup(ref->path);

	goto done;

    }

    if (ref->path == NULL) {

        ref->path = (char *) "/";

	remove_path = 1;

    }



    /*

     * At this point (at last!) we can compare the two paths

     *

     * First we take care of the special case where either of the

     * two path components may be missing (bug 316224)

     */

    if (bas->path == NULL) {

	if (ref->path != NULL) {

	    uptr = ref->path;

	    if (*uptr == '/')

		uptr++;

	    /* exception characters from uri_to_string */

	    val = uri_string_escape(uptr, "/;&=+$,");

	}

	goto done;

    }

    bptr = bas->path;

    if (ref->path == NULL) {

	for (ix = 0; bptr[ix] != 0; ix++) {

	    if (bptr[ix] == '/')

		nbslash++;

	}

	uptr = NULL;

	len = 1;	/* this is for a string terminator only */

    } else {

    /*

     * Next we compare the two strings and find where they first differ

     */

	if ((ref->path[pos] == '.') && (ref->path[pos+1] == '/'))

            pos += 2;

	if ((*bptr == '.') && (bptr[1] == '/'))

            bptr += 2;

	else if ((*bptr == '/') && (ref->path[pos] != '/'))

	    bptr++;

	while ((bptr[pos] == ref->path[pos]) && (bptr[pos] != 0))

	    pos++;



	if (bptr[pos] == ref->path[pos]) {

	    val = g_strdup("");

	    goto done;		/* (I can't imagine why anyone would do this) */

	}



	/*

	 * In URI, "back up" to the last '/' encountered.  This will be the

	 * beginning of the "unique" suffix of URI

	 */

	ix = pos;

	if ((ref->path[ix] == '/') && (ix > 0))

	    ix--;

	else if ((ref->path[ix] == 0) && (ix > 1) && (ref->path[ix - 1] == '/'))

	    ix -= 2;

	for (; ix > 0; ix--) {

	    if (ref->path[ix] == '/')

		break;

	}

	if (ix == 0) {

	    uptr = ref->path;

	} else {

	    ix++;

	    uptr = &ref->path[ix];

	}



	/*

	 * In base, count the number of '/' from the differing point

	 */

	if (bptr[pos] != ref->path[pos]) {/* check for trivial URI == base */

	    for (; bptr[ix] != 0; ix++) {

		if (bptr[ix] == '/')

		    nbslash++;

	    }

	}

	len = strlen (uptr) + 1;

    }



    if (nbslash == 0) {

	if (uptr != NULL)

	    /* exception characters from uri_to_string */

	    val = uri_string_escape(uptr, "/;&=+$,");

	goto done;

    }



    /*

     * Allocate just enough space for the returned string -

     * length of the remainder of the URI, plus enough space

     * for the "../" groups, plus one for the terminator

     */

    val = g_malloc (len + 3 * nbslash);

    vptr = val;

    /*

     * Put in as many "../" as needed

     */

    for (; nbslash>0; nbslash--) {

	*vptr++ = '.';

	*vptr++ = '.';

	*vptr++ = '/';

    }

    /*

     * Finish up with the end of the URI

     */

    if (uptr != NULL) {

        if ((vptr > val) && (len > 0) &&

	    (uptr[0] == '/') && (vptr[-1] == '/')) {

	    memcpy (vptr, uptr + 1, len - 1);

	    vptr[len - 2] = 0;

	} else {

	    memcpy (vptr, uptr, len);

	    vptr[len - 1] = 0;

	}

    } else {

	vptr[len - 1] = 0;

    }



    /* escape the freshly-built path */

    vptr = val;

	/* exception characters from uri_to_string */

    val = uri_string_escape(vptr, "/;&=+$,");

    g_free(vptr);



done:

    /*

     * Free the working variables

     */

    if (remove_path != 0)

        ref->path = NULL;

    if (ref != NULL)

	uri_free (ref);

    if (bas != NULL)

	uri_free (bas);



    return val;

}

