            slirp_smb(slirp_smb_export);

        }

#endif

    }



    slirp_vc = qemu_new_vlan_client(vlan, model, name, NULL, slirp_receive,

                                    NULL, net_slirp_cleanup, NULL);

    slirp_vc->info_str[0] = '\0';

    slirp_in_use = 1;

    return 0;

}

