int rom_load_all(void)

{

    target_phys_addr_t addr = 0;

    int memtype;

    Rom *rom;



    QTAILQ_FOREACH(rom, &roms, next) {

        if (addr < rom->min)

            addr = rom->min;

        if (rom->max) {

            /* load address range */

            if (rom->align) {

                addr += (rom->align-1);

                addr &= ~(rom->align-1);

            }

            if (addr + rom->romsize > rom->max) {

                fprintf(stderr, "rom: out of memory (rom %s, "

                        "addr 0x" TARGET_FMT_plx

                        ", size 0x%zx, max 0x" TARGET_FMT_plx ")\n",

                        rom->name, addr, rom->romsize, rom->max);

                return -1;

            }

        } else {

            /* fixed address requested */

            if (addr != rom->min) {

                fprintf(stderr, "rom: requested regions overlap "

                        "(rom %s. free=0x" TARGET_FMT_plx

                        ", addr=0x" TARGET_FMT_plx ")\n",

                        rom->name, addr, rom->min);

                return -1;

            }

        }

        rom->addr = addr;

        addr += rom->romsize;

        memtype = cpu_get_physical_page_desc(rom->addr) & (3 << IO_MEM_SHIFT);

        if (memtype == IO_MEM_ROM)

            rom->isrom = 1;

    }

    qemu_register_reset(rom_reset, NULL);

    roms_loaded = 1;

    return 0;

}

static uint32_t vmsvga_value_read(void *opaque, uint32_t address)

{

    uint32_t caps;

    struct vmsvga_state_s *s = opaque;

    DisplaySurface *surface = qemu_console_surface(s->vga.con);

    uint32_t ret;



    switch (s->index) {

    case SVGA_REG_ID:

        ret = s->svgaid;

        break;



    case SVGA_REG_ENABLE:

        ret = s->enable;

        break;



    case SVGA_REG_WIDTH:

        ret = surface_width(surface);

        break;



    case SVGA_REG_HEIGHT:

        ret = surface_height(surface);

        break;



    case SVGA_REG_MAX_WIDTH:

        ret = SVGA_MAX_WIDTH;

        break;



    case SVGA_REG_MAX_HEIGHT:

        ret = SVGA_MAX_HEIGHT;

        break;



    case SVGA_REG_DEPTH:

        ret = s->depth;

        break;



    case SVGA_REG_BITS_PER_PIXEL:

        ret = (s->depth + 7) & ~7;

        break;



    case SVGA_REG_PSEUDOCOLOR:

        ret = 0x0;

        break;



    case SVGA_REG_RED_MASK:

        ret = surface->pf.rmask;

        break;



    case SVGA_REG_GREEN_MASK:

        ret = surface->pf.gmask;

        break;



    case SVGA_REG_BLUE_MASK:

        ret = surface->pf.bmask;

        break;



    case SVGA_REG_BYTES_PER_LINE:

        ret = s->bypp * s->new_width;

        break;



    case SVGA_REG_FB_START: {

        struct pci_vmsvga_state_s *pci_vmsvga

            = container_of(s, struct pci_vmsvga_state_s, chip);

        ret = pci_get_bar_addr(&pci_vmsvga->card, 1);

        break;

    }



    case SVGA_REG_FB_OFFSET:

        ret = 0x0;

        break;



    case SVGA_REG_VRAM_SIZE:

        ret = s->vga.vram_size; /* No physical VRAM besides the framebuffer */

        break;



    case SVGA_REG_FB_SIZE:

        ret = s->vga.vram_size;

        break;



    case SVGA_REG_CAPABILITIES:

        caps = SVGA_CAP_NONE;

#ifdef HW_RECT_ACCEL

        caps |= SVGA_CAP_RECT_COPY;

#endif

#ifdef HW_FILL_ACCEL

        caps |= SVGA_CAP_RECT_FILL;

#endif

#ifdef HW_MOUSE_ACCEL

        if (dpy_cursor_define_supported(s->vga.con)) {

            caps |= SVGA_CAP_CURSOR | SVGA_CAP_CURSOR_BYPASS_2 |

                    SVGA_CAP_CURSOR_BYPASS;

        }

#endif

        ret = caps;

        break;



    case SVGA_REG_MEM_START: {

        struct pci_vmsvga_state_s *pci_vmsvga

            = container_of(s, struct pci_vmsvga_state_s, chip);

        ret = pci_get_bar_addr(&pci_vmsvga->card, 2);

        break;

    }



    case SVGA_REG_MEM_SIZE:

        ret = s->fifo_size;

        break;



    case SVGA_REG_CONFIG_DONE:

        ret = s->config;

        break;



    case SVGA_REG_SYNC:

    case SVGA_REG_BUSY:

        ret = s->syncing;

        break;



    case SVGA_REG_GUEST_ID:

        ret = s->guest;

        break;



    case SVGA_REG_CURSOR_ID:

        ret = s->cursor.id;

        break;



    case SVGA_REG_CURSOR_X:

        ret = s->cursor.x;

        break;



    case SVGA_REG_CURSOR_Y:

        ret = s->cursor.x;

        break;



    case SVGA_REG_CURSOR_ON:

        ret = s->cursor.on;

        break;



    case SVGA_REG_HOST_BITS_PER_PIXEL:

        ret = (s->depth + 7) & ~7;

        break;



    case SVGA_REG_SCRATCH_SIZE:

        ret = s->scratch_size;

        break;



    case SVGA_REG_MEM_REGS:

    case SVGA_REG_NUM_DISPLAYS:

    case SVGA_REG_PITCHLOCK:

    case SVGA_PALETTE_BASE ... SVGA_PALETTE_END:

        ret = 0;

        break;



    default:

        if (s->index >= SVGA_SCRATCH_BASE &&

            s->index < SVGA_SCRATCH_BASE + s->scratch_size) {

            ret = s->scratch[s->index - SVGA_SCRATCH_BASE];

            break;

        }

        printf("%s: Bad register %02x\n", __func__, s->index);

        ret = 0;

        break;

    }



    if (s->index >= SVGA_SCRATCH_BASE) {

        trace_vmware_scratch_read(s->index, ret);

    } else if (s->index >= SVGA_PALETTE_BASE) {

        trace_vmware_palette_read(s->index, ret);

    } else {

        trace_vmware_value_read(s->index, ret);

    }

    return ret;

}

static uint32_t pxa2xx_gpio_read(void *opaque, target_phys_addr_t offset)
{
    struct pxa2xx_gpio_info_s *s = (struct pxa2xx_gpio_info_s *) opaque;
    uint32_t ret;
    int bank;
    offset -= s->base;
    if (offset >= 0x200)
        return 0;
    bank = pxa2xx_gpio_regs[offset].bank;
    switch (pxa2xx_gpio_regs[offset].reg) {
    case GPDR:		/* GPIO Pin-Direction registers */
        return s->dir[bank];
    case GRER:		/* GPIO Rising-Edge Detect Enable registers */
        return s->rising[bank];
    case GFER:		/* GPIO Falling-Edge Detect Enable registers */
        return s->falling[bank];
    case GAFR_L:	/* GPIO Alternate Function registers */
        return s->gafr[bank * 2];
    case GAFR_U:	/* GPIO Alternate Function registers */
        return s->gafr[bank * 2 + 1];
    case GPLR:		/* GPIO Pin-Level registers */
        ret = (s->olevel[bank] & s->dir[bank]) |
                (s->ilevel[bank] & ~s->dir[bank]);
        if (s->read_notify)
            s->read_notify(s->opaque);
        return ret;
    case GEDR:		/* GPIO Edge Detect Status registers */
        return s->status[bank];
    default:
        cpu_abort(cpu_single_env,
                "%s: Bad offset " REG_FMT "\n", __FUNCTION__, offset);
    }
    return 0;
}

