int net_client_init(QemuOpts *opts, int is_netdev, Error **errp)

{

    const char *name;

    const char *type;

    int i;



    type = qemu_opt_get(opts, "type");

    if (!type) {

        error_set(errp, QERR_MISSING_PARAMETER, "type");

        return -1;

    }



    if (is_netdev) {

        if (strcmp(type, "tap") != 0 &&

#ifdef CONFIG_NET_BRIDGE

            strcmp(type, "bridge") != 0 &&

#endif

#ifdef CONFIG_SLIRP

            strcmp(type, "user") != 0 &&

#endif

#ifdef CONFIG_VDE

            strcmp(type, "vde") != 0 &&

#endif

            strcmp(type, "socket") != 0) {

            error_set(errp, QERR_INVALID_PARAMETER_VALUE, "type",

                      "a netdev backend type");

            return -1;

        }



        if (qemu_opt_get(opts, "vlan")) {

            error_set(errp, QERR_INVALID_PARAMETER, "vlan");

            return -1;

        }

        if (qemu_opt_get(opts, "name")) {

            error_set(errp, QERR_INVALID_PARAMETER, "name");

            return -1;

        }

        if (!qemu_opts_id(opts)) {

            error_set(errp, QERR_MISSING_PARAMETER, "id");

            return -1;

        }

    }



    name = qemu_opts_id(opts);

    if (!name) {

        name = qemu_opt_get(opts, "name");

    }



    for (i = 0; i < NET_CLIENT_OPTIONS_KIND_MAX; i++) {

        if (net_client_types[i].type != NULL &&

            !strcmp(net_client_types[i].type, type)) {

            Error *local_err = NULL;

            VLANState *vlan = NULL;

            int ret;



            qemu_opts_validate(opts, &net_client_types[i].desc[0], &local_err);

            if (error_is_set(&local_err)) {

                error_propagate(errp, local_err);

                return -1;

            }



            /* Do not add to a vlan if it's a -netdev or a nic with a

             * netdev= parameter. */

            if (!(is_netdev ||

                  (strcmp(type, "nic") == 0 && qemu_opt_get(opts, "netdev")))) {

                vlan = qemu_find_vlan(qemu_opt_get_number(opts, "vlan", 0), 1);

            }



            ret = 0;

            if (net_client_types[i].init) {

                ret = net_client_types[i].init(opts, name, vlan);

                if (ret < 0) {

                    /* TODO push error reporting into init() methods */

                    error_set(errp, QERR_DEVICE_INIT_FAILED, type);

                    return -1;

                }

            }

            return ret;

        }

    }



    error_set(errp, QERR_INVALID_PARAMETER_VALUE, "type",

              "a network client type");

    return -1;

}

static void usbredir_handle_interrupt_out_data(USBRedirDevice *dev,

                                               USBPacket *p, uint8_t ep)

{

    /* Output interrupt endpoint, normal async operation */

    struct usb_redir_interrupt_packet_header interrupt_packet;

    uint8_t buf[p->iov.size];



    DPRINTF("interrupt-out ep %02X len %zd id %"PRIu64"\n", ep,

            p->iov.size, p->id);



    if (usbredir_already_in_flight(dev, p->id)) {

        p->status = USB_RET_ASYNC;

        return;

    }



    interrupt_packet.endpoint  = ep;

    interrupt_packet.length    = p->iov.size;



    usb_packet_copy(p, buf, p->iov.size);

    usbredir_log_data(dev, "interrupt data out:", buf, p->iov.size);

    usbredirparser_send_interrupt_packet(dev->parser, p->id,

                                    &interrupt_packet, buf, p->iov.size);

    usbredirparser_do_write(dev->parser);

    p->status = USB_RET_ASYNC;

}

void helper_fxtract(void)

{

    CPU86_LDoubleU temp;

