static int xen_pt_exp_rom_bar_reg_write(XenPCIPassthroughState *s,

                                        XenPTReg *cfg_entry, uint32_t *val,

                                        uint32_t dev_value, uint32_t valid_mask)

{

    XenPTRegInfo *reg = cfg_entry->reg;

    XenPTRegion *base = NULL;

    PCIDevice *d = (PCIDevice *)&s->dev;

    uint32_t writable_mask = 0;

    uint32_t throughable_mask = get_throughable_mask(s, reg, valid_mask);

    pcibus_t r_size = 0;

    uint32_t bar_ro_mask = 0;



    r_size = d->io_regions[PCI_ROM_SLOT].size;

    base = &s->bases[PCI_ROM_SLOT];

    /* align memory type resource size */

    r_size = xen_pt_get_emul_size(base->bar_flag, r_size);



    /* set emulate mask and read-only mask */

    bar_ro_mask = (reg->ro_mask | (r_size - 1)) & ~PCI_ROM_ADDRESS_ENABLE;



    /* modify emulate register */

    writable_mask = ~bar_ro_mask & valid_mask;

    cfg_entry->data = XEN_PT_MERGE_VALUE(*val, cfg_entry->data, writable_mask);



    /* create value for writing to I/O device register */

    *val = XEN_PT_MERGE_VALUE(*val, dev_value, throughable_mask);



    return 0;

}

static int tcg_match_xori(TCGType type, tcg_target_long val)

{

    if ((s390_facilities & FACILITY_EXT_IMM) == 0) {

        return 0;

    }



    if (type == TCG_TYPE_I32) {

        /* All 32-bit XORs can be performed with 1 48-bit insn.  */

        return 1;

    }



    /* Look for negative values.  These are best to load with LGHI.  */

    if (val < 0 && val == (int32_t)val) {

        return 0;

    }



    return 1;

}

static int block_crypto_open_generic(QCryptoBlockFormat format,

                                     QemuOptsList *opts_spec,

                                     BlockDriverState *bs,

                                     QDict *options,

                                     int flags,

                                     Error **errp)

{

    BlockCrypto *crypto = bs->opaque;

    QemuOpts *opts = NULL;

    Error *local_err = NULL;

    int ret = -EINVAL;

    QCryptoBlockOpenOptions *open_opts = NULL;

    unsigned int cflags = 0;



    bs->file = bdrv_open_child(NULL, options, "file", bs, &child_file,

                               false, errp);

    if (!bs->file) {

        return -EINVAL;

    }



    opts = qemu_opts_create(opts_spec, NULL, 0, &error_abort);

    qemu_opts_absorb_qdict(opts, options, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        goto cleanup;

    }



    open_opts = block_crypto_open_opts_init(format, opts, errp);

    if (!open_opts) {

        goto cleanup;

    }



    if (flags & BDRV_O_NO_IO) {

        cflags |= QCRYPTO_BLOCK_OPEN_NO_IO;

    }

    crypto->block = qcrypto_block_open(open_opts,

                                       block_crypto_read_func,

                                       bs,

                                       cflags,

                                       errp);



    if (!crypto->block) {

        ret = -EIO;

        goto cleanup;

    }



    bs->encrypted = true;

    bs->valid_key = true;



    ret = 0;

 cleanup:

    qapi_free_QCryptoBlockOpenOptions(open_opts);

    return ret;

}

