        *obj = g_malloc0(size);

    }

}

static int coroutine_fn bdrv_co_io_em(BlockDriverState *bs, int64_t sector_num,

                                      int nb_sectors, QEMUIOVector *iov,

                                      bool is_write)

{

    CoroutineIOCompletion co = {

        .coroutine = qemu_coroutine_self(),

    };

    BlockDriverAIOCB *acb;



    if (is_write) {

        acb = bdrv_aio_writev(bs, sector_num, iov, nb_sectors,

                              bdrv_co_io_em_complete, &co);

    } else {

        acb = bdrv_aio_readv(bs, sector_num, iov, nb_sectors,

                             bdrv_co_io_em_complete, &co);

    }



    trace_bdrv_co_io_em(bs, sector_num, nb_sectors, is_write, acb);

    if (!acb) {

        return -EIO;

    }

    qemu_coroutine_yield();



    return co.ret;

}

static void v9fs_getlock(void *opaque)

{

    size_t offset = 7;

    struct stat stbuf;

    V9fsFidState *fidp;

    V9fsGetlock *glock;

    int32_t fid, err = 0;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    glock = g_malloc(sizeof(*glock));

    pdu_unmarshal(pdu, offset, "dbqqds", &fid, &glock->type,

                  &glock->start, &glock->length, &glock->proc_id,

                  &glock->client_id);



    trace_v9fs_getlock(pdu->tag, pdu->id, fid,

                       glock->type, glock->start, glock->length);



    fidp = get_fid(pdu, fid);

    if (fidp == NULL) {

        err = -ENOENT;

        goto out_nofid;

    }

    err = v9fs_co_fstat(pdu, fidp, &stbuf);

    if (err < 0) {

        goto out;

    }

    glock->type = P9_LOCK_TYPE_UNLCK;

    offset += pdu_marshal(pdu, offset, "bqqds", glock->type,

                          glock->start, glock->length, glock->proc_id,

                          &glock->client_id);

    err = offset;

    trace_v9fs_getlock_return(pdu->tag, pdu->id, glock->type, glock->start,

                              glock->length, glock->proc_id);

out:

    put_fid(pdu, fidp);

out_nofid:

    complete_pdu(s, pdu, err);

    v9fs_string_free(&glock->client_id);

    g_free(glock);

}

