static void test_visitor_out_any(TestOutputVisitorData *data,

                                 const void *unused)

{

    QObject *qobj;

    QInt *qint;

    QBool *qbool;

    QString *qstring;

    QDict *qdict;

    QObject *obj;



    qobj = QOBJECT(qint_from_int(-42));

    visit_type_any(data->ov, NULL, &qobj, &error_abort);

    obj = visitor_get(data);

    g_assert(qobject_type(obj) == QTYPE_QINT);

    g_assert_cmpint(qint_get_int(qobject_to_qint(obj)), ==, -42);

    qobject_decref(qobj);



    visitor_reset(data);

    qdict = qdict_new();

    qdict_put(qdict, "integer", qint_from_int(-42));

    qdict_put(qdict, "boolean", qbool_from_bool(true));

    qdict_put(qdict, "string", qstring_from_str("foo"));

    qobj = QOBJECT(qdict);

    visit_type_any(data->ov, NULL, &qobj, &error_abort);

    qobject_decref(qobj);

    qdict = qobject_to_qdict(visitor_get(data));

    g_assert(qdict);

    qobj = qdict_get(qdict, "integer");

    g_assert(qobj);

    qint = qobject_to_qint(qobj);

    g_assert(qint);

    g_assert_cmpint(qint_get_int(qint), ==, -42);

    qobj = qdict_get(qdict, "boolean");

    g_assert(qobj);

    qbool = qobject_to_qbool(qobj);

    g_assert(qbool);

    g_assert(qbool_get_bool(qbool) == true);

    qstring = qobject_to_qstring(qdict_get(qdict, "string"));

    g_assert(qstring);

    g_assert_cmpstr(qstring_get_str(qstring), ==, "foo");

}

static void handle_user_command(Monitor *mon, const char *cmdline)

{

    QDict *qdict;

    const mon_cmd_t *cmd;



    qdict = qdict_new();



    cmd = monitor_parse_command(mon, cmdline, qdict);

    if (!cmd)

        goto out;



    if (monitor_handler_is_async(cmd)) {

        user_async_cmd_handler(mon, cmd, qdict);

    } else if (monitor_handler_ported(cmd)) {

        monitor_call_handler(mon, cmd, qdict);

    } else {

        cmd->mhandler.cmd(mon, qdict);

    }



    if (monitor_has_error(mon))

        monitor_print_error(mon);



out:

    QDECREF(qdict);

}

static int do_create(struct iovec *iovec)

{

    int ret;

    V9fsString path;

    int flags, mode, uid, gid, cur_uid, cur_gid;



    v9fs_string_init(&path);

    ret = proxy_unmarshal(iovec, PROXY_HDR_SZ, "sdddd",

                          &path, &flags, &mode, &uid, &gid);

    if (ret < 0) {

        goto unmarshal_err_out;

    }

    cur_uid = geteuid();

    cur_gid = getegid();

    ret = setfsugid(uid, gid);

    if (ret < 0) {

        /*

         * On failure reset back to the

         * old uid/gid

         */

        ret = -errno;

        goto err_out;

    }

    ret = open(path.data, flags, mode);

    if (ret < 0) {

        ret = -errno;

    }



err_out:

    setfsugid(cur_uid, cur_gid);

unmarshal_err_out:

    v9fs_string_free(&path);

    return ret;

}

static unsigned int dec_movem_rm(DisasContext *dc)

{

	TCGv tmp;

	TCGv addr;

	int i;



	DIS(fprintf (logfile, "movem $r%u, [$r%u%s\n", dc->op2, dc->op1,

		     dc->postinc ? "+]" : "]"));



	cris_flush_cc_state(dc);



	tmp = tcg_temp_new(TCG_TYPE_TL);

	addr = tcg_temp_new(TCG_TYPE_TL);

	tcg_gen_movi_tl(tmp, 4);

	tcg_gen_mov_tl(addr, cpu_R[dc->op1]);

	for (i = 0; i <= dc->op2; i++) {

		/* Displace addr.  */

		/* Perform the store.  */

		gen_store(dc, addr, cpu_R[i], 4);

		tcg_gen_add_tl(addr, addr, tmp);

	}

	if (dc->postinc)

		tcg_gen_mov_tl(cpu_R[dc->op1], addr);

	cris_cc_mask(dc, 0);

	tcg_temp_free(tmp);

	tcg_temp_free(addr);

	return 2;

}

