int kvm_arch_init_vcpu(CPUState *env)

{

    struct {

        struct kvm_cpuid2 cpuid;

        struct kvm_cpuid_entry2 entries[100];

    } __attribute__((packed)) cpuid_data;

    uint32_t limit, i, j, cpuid_i;

    uint32_t eax, ebx, ecx, edx;



    cpuid_i = 0;



    cpu_x86_cpuid(env, 0, 0, &eax, &ebx, &ecx, &edx);

    limit = eax;



    for (i = 0; i <= limit; i++) {

        struct kvm_cpuid_entry2 *c = &cpuid_data.entries[cpuid_i++];



        switch (i) {

        case 2: {

            /* Keep reading function 2 till all the input is received */

            int times;



            cpu_x86_cpuid(env, i, 0, &eax, &ebx, &ecx, &edx);

            times = eax & 0xff;



            c->function = i;

            c->flags |= KVM_CPUID_FLAG_STATEFUL_FUNC;

            c->flags |= KVM_CPUID_FLAG_STATE_READ_NEXT;

            c->eax = eax;

            c->ebx = ebx;

            c->ecx = ecx;

            c->edx = edx;



            for (j = 1; j < times; ++j) {

                cpu_x86_cpuid(env, i, 0, &eax, &ebx, &ecx, &edx);

                c->function = i;

                c->flags |= KVM_CPUID_FLAG_STATEFUL_FUNC;

                c->eax = eax;

                c->ebx = ebx;

                c->ecx = ecx;

                c->edx = edx;

                c = &cpuid_data.entries[++cpuid_i];

            }

            break;

        }

        case 4:

        case 0xb:

        case 0xd:

            for (j = 0; ; j++) {

                cpu_x86_cpuid(env, i, j, &eax, &ebx, &ecx, &edx);

                c->function = i;

                c->flags = KVM_CPUID_FLAG_SIGNIFCANT_INDEX;

                c->index = j;

                c->eax = eax;

                c->ebx = ebx;

                c->ecx = ecx;

                c->edx = edx;

                c = &cpuid_data.entries[++cpuid_i];



                if (i == 4 && eax == 0)

                    break;

                if (i == 0xb && !(ecx & 0xff00))

                    break;

                if (i == 0xd && eax == 0)

                    break;

            }

            break;

        default:

            cpu_x86_cpuid(env, i, 0, &eax, &ebx, &ecx, &edx);

            c->function = i;

            c->eax = eax;

            c->ebx = ebx;

            c->ecx = ecx;

            c->edx = edx;

            break;

        }

    }

    cpu_x86_cpuid(env, 0x80000000, 0, &eax, &ebx, &ecx, &edx);

    limit = eax;



    for (i = 0x80000000; i <= limit; i++) {

        struct kvm_cpuid_entry2 *c = &cpuid_data.entries[cpuid_i++];



        cpu_x86_cpuid(env, i, 0, &eax, &ebx, &ecx, &edx);

        c->function = i;

        c->eax = eax;

        c->ebx = ebx;

        c->ecx = ecx;

        c->edx = edx;

    }



    cpuid_data.cpuid.nent = cpuid_i;



    return kvm_vcpu_ioctl(env, KVM_SET_CPUID2, &cpuid_data);

}

static int handle_instruction(CPUState *env, struct kvm_run *run)

{

    unsigned int ipa0 = (run->s390_sieic.ipa & 0xff00);

    uint8_t ipa1 = run->s390_sieic.ipa & 0x00ff;

    int ipb_code = (run->s390_sieic.ipb & 0x0fff0000) >> 16;

    int r = -1;



    dprintf("handle_instruction 0x%x 0x%x\n", run->s390_sieic.ipa, run->s390_sieic.ipb);

    switch (ipa0) {

        case IPA0_PRIV:

            r = handle_priv(env, run, ipa1);

            break;

        case IPA0_DIAG:

            r = handle_diag(env, run, ipb_code);

            break;

        case IPA0_SIGP:

            r = handle_sigp(env, run, ipa1);

            break;

    }



    if (r < 0) {

        enter_pgmcheck(env, 0x0001);

    }

    return r;

}

static int coroutine_fn iscsi_co_readv(BlockDriverState *bs,

                                       int64_t sector_num, int nb_sectors,

                                       QEMUIOVector *iov)

{

    IscsiLun *iscsilun = bs->opaque;

    struct IscsiTask iTask;

    uint64_t lba;

    uint32_t num_sectors;



    if (!is_sector_request_lun_aligned(sector_num, nb_sectors, iscsilun)) {

        return -EINVAL;

    }



    if (bs->bl.max_transfer_length && nb_sectors > bs->bl.max_transfer_length) {

        error_report("iSCSI Error: Read of %d sectors exceeds max_xfer_len "

                     "of %d sectors", nb_sectors, bs->bl.max_transfer_length);

        return -EINVAL;

    }



    if (iscsilun->lbprz && nb_sectors >= ISCSI_CHECKALLOC_THRES &&

        !iscsi_allocationmap_is_allocated(iscsilun, sector_num, nb_sectors)) {

        int64_t ret;

        int pnum;

        BlockDriverState *file;

        ret = iscsi_co_get_block_status(bs, sector_num, INT_MAX, &pnum, &file);

        if (ret < 0) {

            return ret;

        }

        if (ret & BDRV_BLOCK_ZERO && pnum >= nb_sectors) {

            qemu_iovec_memset(iov, 0, 0x00, iov->size);

            return 0;

        }

    }



    lba = sector_qemu2lun(sector_num, iscsilun);

    num_sectors = sector_qemu2lun(nb_sectors, iscsilun);



    iscsi_co_init_iscsitask(iscsilun, &iTask);

retry:

    if (iscsilun->use_16_for_rw) {

        iTask.task = iscsi_read16_task(iscsilun->iscsi, iscsilun->lun, lba,

                                       num_sectors * iscsilun->block_size,

                                       iscsilun->block_size, 0, 0, 0, 0, 0,

                                       iscsi_co_generic_cb, &iTask);

    } else {

        iTask.task = iscsi_read10_task(iscsilun->iscsi, iscsilun->lun, lba,

                                       num_sectors * iscsilun->block_size,

                                       iscsilun->block_size,

                                       0, 0, 0, 0, 0,

                                       iscsi_co_generic_cb, &iTask);

    }

    if (iTask.task == NULL) {

        return -ENOMEM;

    }

    scsi_task_set_iov_in(iTask.task, (struct scsi_iovec *) iov->iov, iov->niov);



    while (!iTask.complete) {

        iscsi_set_events(iscsilun);

        qemu_coroutine_yield();

    }



    if (iTask.task != NULL) {

        scsi_free_scsi_task(iTask.task);

        iTask.task = NULL;

    }



    if (iTask.do_retry) {

        iTask.complete = 0;

        goto retry;

    }



    if (iTask.status != SCSI_STATUS_GOOD) {

        return iTask.err_code;

    }



    return 0;

}

static void spapr_numa_cpu(const void *data)

{

    char *cli;

    QDict *resp;

    QList *cpus;

    const QObject *e;



    cli = make_cli(data, "-smp 4,cores=4 "

        "-numa node,nodeid=0 -numa node,nodeid=1 "

        "-numa cpu,node-id=0,core-id=0 "

        "-numa cpu,node-id=0,core-id=1 "

        "-numa cpu,node-id=0,core-id=2 "

        "-numa cpu,node-id=1,core-id=3");

    qtest_start(cli);

    cpus = get_cpus(&resp);

    g_assert(cpus);



    while ((e = qlist_pop(cpus))) {

        QDict *cpu, *props;

        int64_t core, node;



        cpu = qobject_to_qdict(e);

        g_assert(qdict_haskey(cpu, "props"));

        props = qdict_get_qdict(cpu, "props");



        g_assert(qdict_haskey(props, "node-id"));

        node = qdict_get_int(props, "node-id");

        g_assert(qdict_haskey(props, "core-id"));

        core = qdict_get_int(props, "core-id");



        if (core >= 0 && core < 3) {

            g_assert_cmpint(node, ==, 0);

        } else if (core == 3) {

            g_assert_cmpint(node, ==, 1);

        } else {

            g_assert(false);

        }

    }



    QDECREF(resp);

    qtest_end();

    g_free(cli);

}

