static target_ulong h_send_logical_lan(CPUPPCState *env, sPAPREnvironment *spapr,

                                       target_ulong opcode, target_ulong *args)

{

    target_ulong reg = args[0];

    target_ulong *bufs = args + 1;

    target_ulong continue_token = args[7];

    VIOsPAPRDevice *sdev = spapr_vio_find_by_reg(spapr->vio_bus, reg);

    VIOsPAPRVLANDevice *dev = (VIOsPAPRVLANDevice *)sdev;

    unsigned total_len;

    uint8_t *lbuf, *p;

    int i, nbufs;

    int ret;



    dprintf("H_SEND_LOGICAL_LAN(0x" TARGET_FMT_lx ", <bufs>, 0x"

            TARGET_FMT_lx ")\n", reg, continue_token);



    if (!sdev) {

        return H_PARAMETER;

    }



    dprintf("rxbufs = %d\n", dev->rx_bufs);



    if (!dev->isopen) {

        return H_DROPPED;

    }



    if (continue_token) {

        return H_HARDWARE; /* FIXME actually handle this */

    }



    total_len = 0;

    for (i = 0; i < 6; i++) {

        dprintf("   buf desc: 0x" TARGET_FMT_lx "\n", bufs[i]);

        if (!(bufs[i] & VLAN_BD_VALID)) {

            break;

        }

        total_len += VLAN_BD_LEN(bufs[i]);

    }



    nbufs = i;

    dprintf("h_send_logical_lan() %d buffers, total length 0x%x\n",

            nbufs, total_len);



    if (total_len == 0) {

        return H_SUCCESS;

    }



    if (total_len > MAX_PACKET_SIZE) {

        /* Don't let the guest force too large an allocation */

        return H_RESOURCE;

    }



    lbuf = alloca(total_len);

    p = lbuf;

    for (i = 0; i < nbufs; i++) {

        ret = spapr_tce_dma_read(sdev, VLAN_BD_ADDR(bufs[i]),

                                 p, VLAN_BD_LEN(bufs[i]));

        if (ret < 0) {

            return ret;

        }



        p += VLAN_BD_LEN(bufs[i]);

    }



    qemu_send_packet(&dev->nic->nc, lbuf, total_len);



    return H_SUCCESS;

}

static ssize_t virtio_net_receive(NetClientState *nc, const uint8_t *buf, size_t size)

{

    VirtIONet *n = qemu_get_nic_opaque(nc);

    VirtIONetQueue *q = virtio_net_get_subqueue(nc);

    VirtIODevice *vdev = VIRTIO_DEVICE(n);

    struct iovec mhdr_sg[VIRTQUEUE_MAX_SIZE];

    struct virtio_net_hdr_mrg_rxbuf mhdr;

    unsigned mhdr_cnt = 0;

    size_t offset, i, guest_offset;



    if (!virtio_net_can_receive(nc)) {

        return -1;

    }



    /* hdr_len refers to the header we supply to the guest */

    if (!virtio_net_has_buffers(q, size + n->guest_hdr_len - n->host_hdr_len)) {

        return 0;

    }



    if (!receive_filter(n, buf, size))

        return size;



    offset = i = 0;



    while (offset < size) {

        VirtQueueElement elem;

        int len, total;

        const struct iovec *sg = elem.in_sg;



        total = 0;



        if (virtqueue_pop(q->rx_vq, &elem) == 0) {

            if (i == 0)

                return -1;

            error_report("virtio-net unexpected empty queue: "

                         "i %zd mergeable %d offset %zd, size %zd, "

                         "guest hdr len %zd, host hdr len %zd "

                         "guest features 0x%" PRIx64,

                         i, n->mergeable_rx_bufs, offset, size,

                         n->guest_hdr_len, n->host_hdr_len,

                         vdev->guest_features);

            exit(1);

        }



        if (elem.in_num < 1) {

            error_report("virtio-net receive queue contains no in buffers");

            exit(1);

        }



        if (i == 0) {

            assert(offset == 0);

            if (n->mergeable_rx_bufs) {

                mhdr_cnt = iov_copy(mhdr_sg, ARRAY_SIZE(mhdr_sg),

                                    sg, elem.in_num,

                                    offsetof(typeof(mhdr), num_buffers),

                                    sizeof(mhdr.num_buffers));

            }



            receive_header(n, sg, elem.in_num, buf, size);

            offset = n->host_hdr_len;

            total += n->guest_hdr_len;

            guest_offset = n->guest_hdr_len;

        } else {

            guest_offset = 0;

        }



        /* copy in packet.  ugh */

        len = iov_from_buf(sg, elem.in_num, guest_offset,

                           buf + offset, size - offset);

        total += len;

        offset += len;

        /* If buffers can't be merged, at this point we

         * must have consumed the complete packet.

         * Otherwise, drop it. */

        if (!n->mergeable_rx_bufs && offset < size) {

#if 0

            error_report("virtio-net truncated non-mergeable packet: "

                         "i %zd mergeable %d offset %zd, size %zd, "

                         "guest hdr len %zd, host hdr len %zd",

                         i, n->mergeable_rx_bufs,

                         offset, size, n->guest_hdr_len, n->host_hdr_len);

#endif

            return size;

        }



        /* signal other side */

        virtqueue_fill(q->rx_vq, &elem, total, i++);

    }



    if (mhdr_cnt) {

        virtio_stw_p(vdev, &mhdr.num_buffers, i);

        iov_from_buf(mhdr_sg, mhdr_cnt,

                     0,

                     &mhdr.num_buffers, sizeof mhdr.num_buffers);

    }



    virtqueue_flush(q->rx_vq, i);

    virtio_notify(vdev, q->rx_vq);



    return size;

}

static USBDevice *usb_host_device_open_addr(int bus_num, int addr, const char *prod_name)

{

    int fd = -1, ret;

    USBDevice *d = NULL;

    USBHostDevice *dev;

    struct usbdevfs_connectinfo ci;

    char buf[1024];



    printf("husb: open device %d.%d\n", bus_num, addr);



    if (!usb_host_device_path) {

        perror("husb: USB Host Device Path not set");

        goto fail;

    }

    snprintf(buf, sizeof(buf), "%s/%03d/%03d", usb_host_device_path,

             bus_num, addr);

    fd = open(buf, O_RDWR | O_NONBLOCK);

    if (fd < 0) {

        perror(buf);

        goto fail;

    }

    dprintf("husb: opened %s\n", buf);



    d = usb_create(NULL /* FIXME */, "USB Host Device");

    dev = DO_UPCAST(USBHostDevice, dev, d);



    dev->bus_num = bus_num;

    dev->addr = addr;

    dev->fd = fd;



    /* read the device description */

    dev->descr_len = read(fd, dev->descr, sizeof(dev->descr));

    if (dev->descr_len <= 0) {

        perror("husb: reading device data failed");

        goto fail;

    }



#ifdef DEBUG

    {

        int x;

        printf("=== begin dumping device descriptor data ===\n");

        for (x = 0; x < dev->descr_len; x++)

            printf("%02x ", dev->descr[x]);

        printf("\n=== end dumping device descriptor data ===\n");

    }

#endif





    /* 

     * Initial configuration is -1 which makes us claim first 

     * available config. We used to start with 1, which does not

     * always work. I've seen devices where first config starts 

     * with 2.

     */

    if (!usb_host_claim_interfaces(dev, -1))

        goto fail;



    ret = ioctl(fd, USBDEVFS_CONNECTINFO, &ci);

    if (ret < 0) {

        perror("usb_host_device_open: USBDEVFS_CONNECTINFO");

        goto fail;

    }



    printf("husb: grabbed usb device %d.%d\n", bus_num, addr);



    ret = usb_linux_update_endp_table(dev);

    if (ret)

        goto fail;



    if (ci.slow)

        dev->dev.speed = USB_SPEED_LOW;

    else

        dev->dev.speed = USB_SPEED_HIGH;



    if (!prod_name || prod_name[0] == '\0')

        snprintf(dev->dev.devname, sizeof(dev->dev.devname),

                 "host:%d.%d", bus_num, addr);

    else

        pstrcpy(dev->dev.devname, sizeof(dev->dev.devname),

                prod_name);



    /* USB devio uses 'write' flag to check for async completions */

    qemu_set_fd_handler(dev->fd, NULL, async_complete, dev);



    hostdev_link(dev);



    qdev_init(&d->qdev);

    return (USBDevice *) dev;



fail:

    if (d)

        qdev_free(&d->qdev);

    if (fd != -1)

        close(fd);

    return NULL;

}

