static void dec_scall(DisasContext *dc)

{

    TCGv t0;

    int l1;



    if (dc->imm5 == 7) {

        LOG_DIS("scall\n");

    } else if (dc->imm5 == 2) {

        LOG_DIS("break\n");

    } else {

        cpu_abort(dc->env, "invalid opcode\n");

    }



    t0 = tcg_temp_new();

    l1 = gen_new_label();



    if (dc->imm5 == 7) {

        tcg_gen_movi_tl(cpu_pc, dc->pc);

        t_gen_raise_exception(dc, EXCP_SYSTEMCALL);

    } else {

        tcg_gen_movi_tl(cpu_pc, dc->pc);

        t_gen_raise_exception(dc, EXCP_BREAKPOINT);

    }

}

static void slavio_check_interrupts(void *opaque)

{

    CPUState *env;

    SLAVIO_INTCTLState *s = opaque;

    uint32_t pending = s->intregm_pending;

    unsigned int i, j, max = 0;



    pending &= ~s->intregm_disabled;



    if (pending && !(s->intregm_disabled & 0x80000000)) {

	for (i = 0; i < 32; i++) {

	    if (pending & (1 << i)) {

		if (max < s->intbit_to_level[i])

		    max = s->intbit_to_level[i];

	    }

	}

        env = s->cpu_envs[s->target_cpu];

        if (!env) {

	    DPRINTF("No CPU %d, not triggered (pending %x)\n", s->target_cpu, pending);

        }

	else {

            if (env->halted)

                env->halted = 0;

            if (env->interrupt_index == 0) {

                DPRINTF("Triggered CPU %d pil %d\n", s->target_cpu, max);

#ifdef DEBUG_IRQ_COUNT

                s->irq_count[max]++;

#endif

                env->interrupt_index = TT_EXTINT | max;

                cpu_interrupt(env, CPU_INTERRUPT_HARD);

            }

            else

                DPRINTF("Not triggered (pending %x), pending exception %x\n", pending, env->interrupt_index);

	}

    }

    else

	DPRINTF("Not triggered (pending %x), disabled %x\n", pending, s->intregm_disabled);



    for (i = 0; i < MAX_CPUS; i++) {

        max = 0;

        env = s->cpu_envs[i];

        if (!env)

            continue;

        for (j = 17; j < 32; j++) {

            if (s->intreg_pending[i] & (1 << j)) {

                if (max < j - 16)

                    max = j - 16;

            }

        }

	if (max > 0) {

            if (env->halted)

                env->halted = 0;

            if (env->interrupt_index == 0) {

                DPRINTF("Triggered softint %d for cpu %d (pending %x)\n", max, i, pending);

#ifdef DEBUG_IRQ_COUNT

                s->irq_count[max]++;

#endif

                env->interrupt_index = TT_EXTINT | max;

                cpu_interrupt(env, CPU_INTERRUPT_HARD);

            }

        }

    }

}

static int pci_add_option_rom(PCIDevice *pdev, bool is_default_rom)

{

    int size;

    char *path;

    void *ptr;

    char name[32];

    const VMStateDescription *vmsd;



    if (!pdev->romfile)

        return 0;

    if (strlen(pdev->romfile) == 0)

        return 0;



    if (!pdev->rom_bar) {

        /*

         * Load rom via fw_cfg instead of creating a rom bar,

         * for 0.11 compatibility.

         */

        int class = pci_get_word(pdev->config + PCI_CLASS_DEVICE);

        if (class == 0x0300) {

            rom_add_vga(pdev->romfile);

        } else {

            rom_add_option(pdev->romfile, -1);

        }

        return 0;

    }



    path = qemu_find_file(QEMU_FILE_TYPE_BIOS, pdev->romfile);

    if (path == NULL) {

        path = g_strdup(pdev->romfile);

    }



    size = get_image_size(path);

    if (size < 0) {

        error_report("%s: failed to find romfile \"%s\"",

                     __FUNCTION__, pdev->romfile);

        g_free(path);

        return -1;

    }

    if (size & (size - 1)) {

        size = 1 << qemu_fls(size);

    }



    vmsd = qdev_get_vmsd(DEVICE(pdev));



    if (vmsd) {

        snprintf(name, sizeof(name), "%s.rom", vmsd->name);

    } else {

        snprintf(name, sizeof(name), "%s.rom", object_get_typename(OBJECT(pdev)));

    }

    pdev->has_rom = true;

    memory_region_init_ram(&pdev->rom, name, size);

    vmstate_register_ram(&pdev->rom, &pdev->qdev);

    ptr = memory_region_get_ram_ptr(&pdev->rom);

    load_image(path, ptr);

    g_free(path);



    if (is_default_rom) {

        /* Only the default rom images will be patched (if needed). */

        pci_patch_ids(pdev, ptr, size);

    }



    qemu_put_ram_ptr(ptr);



    pci_register_bar(pdev, PCI_ROM_SLOT, 0, &pdev->rom);



    return 0;

}

static char *qemu_rbd_next_tok(int max_len,

                               char *src, char delim,

                               const char *name,

                               char **p, Error **errp)

{

    int l;

    char *end;



    *p = NULL;



    if (delim != '\0') {

        for (end = src; *end; ++end) {

            if (*end == delim) {

                break;

            }

            if (*end == '\\' && end[1] != '\0') {

                end++;

            }

        }

        if (*end == delim) {

            *p = end + 1;

            *end = '\0';

        }

    }

    l = strlen(src);

    if (l >= max_len) {

        error_setg(errp, "%s too long", name);

        return NULL;

    } else if (l == 0) {

        error_setg(errp, "%s too short", name);

        return NULL;

    }



    return src;

}

static int protocol_client_vencrypt_auth(VncState *vs, uint8_t *data, size_t len)

{

    int auth = read_u32(data, 0);



    if (auth != vs->vd->subauth) {

        VNC_DEBUG("Rejecting auth %d\n", auth);

        vnc_write_u8(vs, 0); /* Reject auth */

        vnc_flush(vs);

        vnc_client_error(vs);

    } else {

        VNC_DEBUG("Accepting auth %d, setting up TLS for handshake\n", auth);

        vnc_write_u8(vs, 1); /* Accept auth */

        vnc_flush(vs);



        if (vnc_tls_client_setup(vs, NEED_X509_AUTH(vs)) < 0) {

            VNC_DEBUG("Failed to setup TLS\n");

            return 0;

        }



        VNC_DEBUG("Start TLS VeNCrypt handshake process\n");

        if (vnc_start_vencrypt_handshake(vs) < 0) {

            VNC_DEBUG("Failed to start TLS handshake\n");

            return 0;

        }

    }

    return 0;

}

