static uint32_t drc_unisolate_physical(sPAPRDRConnector *drc)

{

    /* cannot unisolate a non-existent resource, and, or resources

     * which are in an 'UNUSABLE' allocation state. (PAPR 2.7,

     * 13.5.3.5)

     */

    if (!drc->dev) {

