static void max_x86_cpu_initfn(Object *obj)

{

    X86CPU *cpu = X86_CPU(obj);

    CPUX86State *env = &cpu->env;

    KVMState *s = kvm_state;



    /* We can't fill the features array here because we don't know yet if

     * "migratable" is true or false.

     */

    cpu->max_features = true;



    if (kvm_enabled()) {

        X86CPUDefinition host_cpudef = { };

        uint32_t eax = 0, ebx = 0, ecx = 0, edx = 0;



        host_vendor_fms(host_cpudef.vendor, &host_cpudef.family,

                        &host_cpudef.model, &host_cpudef.stepping);



        cpu_x86_fill_model_id(host_cpudef.model_id);



        x86_cpu_load_def(cpu, &host_cpudef, &error_abort);



        env->cpuid_min_level =

            kvm_arch_get_supported_cpuid(s, 0x0, 0, R_EAX);

        env->cpuid_min_xlevel =

            kvm_arch_get_supported_cpuid(s, 0x80000000, 0, R_EAX);

        env->cpuid_min_xlevel2 =

            kvm_arch_get_supported_cpuid(s, 0xC0000000, 0, R_EAX);



        if (lmce_supported()) {

            object_property_set_bool(OBJECT(cpu), true, "lmce", &error_abort);

        }

    } else {

        object_property_set_str(OBJECT(cpu), CPUID_VENDOR_AMD,

                                "vendor", &error_abort);

        object_property_set_int(OBJECT(cpu), 6, "family", &error_abort);

        object_property_set_int(OBJECT(cpu), 6, "model", &error_abort);

        object_property_set_int(OBJECT(cpu), 3, "stepping", &error_abort);

        object_property_set_str(OBJECT(cpu),

                                "QEMU TCG CPU version " QEMU_HW_VERSION,

                                "model-id", &error_abort);

    }



    object_property_set_bool(OBJECT(cpu), true, "pmu", &error_abort);

}

static int vfio_get_device(VFIOGroup *group, const char *name, VFIODevice *vdev)

{

    struct vfio_device_info dev_info = { .argsz = sizeof(dev_info) };

    struct vfio_region_info reg_info = { .argsz = sizeof(reg_info) };

    int ret, i;



    ret = ioctl(group->fd, VFIO_GROUP_GET_DEVICE_FD, name);

    if (ret < 0) {

        error_report("vfio: error getting device %s from group %d: %m\n",

                     name, group->groupid);

        error_report("Verify all devices in group %d are bound to vfio-pci "

                     "or pci-stub and not already in use\n", group->groupid);

        return ret;

    }



    vdev->fd = ret;

    vdev->group = group;

    QLIST_INSERT_HEAD(&group->device_list, vdev, next);



    /* Sanity check device */

    ret = ioctl(vdev->fd, VFIO_DEVICE_GET_INFO, &dev_info);

    if (ret) {

        error_report("vfio: error getting device info: %m\n");

        goto error;

    }



    DPRINTF("Device %s flags: %u, regions: %u, irgs: %u\n", name,

            dev_info.flags, dev_info.num_regions, dev_info.num_irqs);



    if (!(dev_info.flags & VFIO_DEVICE_FLAGS_PCI)) {

        error_report("vfio: Um, this isn't a PCI device\n");

        goto error;

    }



    vdev->reset_works = !!(dev_info.flags & VFIO_DEVICE_FLAGS_RESET);

    if (!vdev->reset_works) {

        error_report("Warning, device %s does not support reset\n", name);

    }



    if (dev_info.num_regions != VFIO_PCI_NUM_REGIONS) {

        error_report("vfio: unexpected number of io regions %u\n",

                     dev_info.num_regions);

        goto error;

    }



    if (dev_info.num_irqs != VFIO_PCI_NUM_IRQS) {

        error_report("vfio: unexpected number of irqs %u\n", dev_info.num_irqs);

        goto error;

    }



    for (i = VFIO_PCI_BAR0_REGION_INDEX; i < VFIO_PCI_ROM_REGION_INDEX; i++) {

        reg_info.index = i;



        ret = ioctl(vdev->fd, VFIO_DEVICE_GET_REGION_INFO, &reg_info);

        if (ret) {

            error_report("vfio: Error getting region %d info: %m\n", i);

            goto error;

        }



        DPRINTF("Device %s region %d:\n", name, i);

        DPRINTF("  size: 0x%lx, offset: 0x%lx, flags: 0x%lx\n",

                (unsigned long)reg_info.size, (unsigned long)reg_info.offset,

                (unsigned long)reg_info.flags);



        vdev->bars[i].flags = reg_info.flags;

        vdev->bars[i].size = reg_info.size;

        vdev->bars[i].fd_offset = reg_info.offset;

        vdev->bars[i].fd = vdev->fd;

        vdev->bars[i].nr = i;

    }



    reg_info.index = VFIO_PCI_ROM_REGION_INDEX;



    ret = ioctl(vdev->fd, VFIO_DEVICE_GET_REGION_INFO, &reg_info);

    if (ret) {

        error_report("vfio: Error getting ROM info: %m\n");

        goto error;

    }



    DPRINTF("Device %s ROM:\n", name);

    DPRINTF("  size: 0x%lx, offset: 0x%lx, flags: 0x%lx\n",

            (unsigned long)reg_info.size, (unsigned long)reg_info.offset,

            (unsigned long)reg_info.flags);



    vdev->rom_size = reg_info.size;

    vdev->rom_offset = reg_info.offset;



    reg_info.index = VFIO_PCI_CONFIG_REGION_INDEX;



    ret = ioctl(vdev->fd, VFIO_DEVICE_GET_REGION_INFO, &reg_info);

    if (ret) {

        error_report("vfio: Error getting config info: %m\n");

        goto error;

    }



    DPRINTF("Device %s config:\n", name);

    DPRINTF("  size: 0x%lx, offset: 0x%lx, flags: 0x%lx\n",

            (unsigned long)reg_info.size, (unsigned long)reg_info.offset,

            (unsigned long)reg_info.flags);



    vdev->config_size = reg_info.size;

    vdev->config_offset = reg_info.offset;



error:

    if (ret) {

        QLIST_REMOVE(vdev, next);

        vdev->group = NULL;

        close(vdev->fd);

    }

    return ret;

}

static BlockBackend *blockdev_init(const char *file, QDict *bs_opts,

                                   Error **errp)

{

    const char *buf;

    int bdrv_flags = 0;

    int on_read_error, on_write_error;


    BlockBackend *blk;

    BlockDriverState *bs;

    ThrottleConfig cfg;

    int snapshot = 0;

    Error *error = NULL;

    QemuOpts *opts;

    const char *id;

    bool has_driver_specific_opts;

    BlockdevDetectZeroesOptions detect_zeroes =

        BLOCKDEV_DETECT_ZEROES_OPTIONS_OFF;

    const char *throttling_group = NULL;



    /* Check common options by copying from bs_opts to opts, all other options

     * stay in bs_opts for processing by bdrv_open(). */

    id = qdict_get_try_str(bs_opts, "id");

    opts = qemu_opts_create(&qemu_common_drive_opts, id, 1, &error);

    if (error) {

        error_propagate(errp, error);

        goto err_no_opts;

    }



    qemu_opts_absorb_qdict(opts, bs_opts, &error);

    if (error) {

        error_propagate(errp, error);

        goto early_err;

    }



    if (id) {

        qdict_del(bs_opts, "id");

    }



    has_driver_specific_opts = !!qdict_size(bs_opts);



    /* extract parameters */

    snapshot = qemu_opt_get_bool(opts, "snapshot", 0);



    account_invalid = qemu_opt_get_bool(opts, "stats-account-invalid", true);

    account_failed = qemu_opt_get_bool(opts, "stats-account-failed", true);



    extract_common_blockdev_options(opts, &bdrv_flags, &throttling_group, &cfg,

                                    &detect_zeroes, &error);

    if (error) {

        error_propagate(errp, error);

        goto early_err;

    }



    if ((buf = qemu_opt_get(opts, "format")) != NULL) {

        if (is_help_option(buf)) {

            error_printf("Supported formats:");

            bdrv_iterate_format(bdrv_format_print, NULL);

            error_printf("\n");

            goto early_err;

        }



        if (qdict_haskey(bs_opts, "driver")) {

            error_setg(errp, "Cannot specify both 'driver' and 'format'");

            goto early_err;

        }

        qdict_put(bs_opts, "driver", qstring_from_str(buf));

    }



    on_write_error = BLOCKDEV_ON_ERROR_ENOSPC;

    if ((buf = qemu_opt_get(opts, "werror")) != NULL) {

        on_write_error = parse_block_error_action(buf, 0, &error);

        if (error) {

            error_propagate(errp, error);

            goto early_err;

        }

    }



    on_read_error = BLOCKDEV_ON_ERROR_REPORT;

    if ((buf = qemu_opt_get(opts, "rerror")) != NULL) {

        on_read_error = parse_block_error_action(buf, 1, &error);

        if (error) {

            error_propagate(errp, error);

            goto early_err;

        }

    }



    if (snapshot) {

        /* always use cache=unsafe with snapshot */

        bdrv_flags &= ~BDRV_O_CACHE_MASK;

        bdrv_flags |= (BDRV_O_SNAPSHOT|BDRV_O_CACHE_WB|BDRV_O_NO_FLUSH);

    }



    /* init */

    if ((!file || !*file) && !has_driver_specific_opts) {

        BlockBackendRootState *blk_rs;



        blk = blk_new(qemu_opts_id(opts), errp);

        if (!blk) {

            goto early_err;

        }



        blk_rs = blk_get_root_state(blk);

        blk_rs->open_flags    = bdrv_flags;

        blk_rs->read_only     = !(bdrv_flags & BDRV_O_RDWR);

        blk_rs->detect_zeroes = detect_zeroes;



        if (throttle_enabled(&cfg)) {

            if (!throttling_group) {

                throttling_group = blk_name(blk);

            }

            blk_rs->throttle_group = g_strdup(throttling_group);

            blk_rs->throttle_state = throttle_group_incref(throttling_group);

            blk_rs->throttle_state->cfg = cfg;

        }



        QDECREF(bs_opts);

    } else {

        if (file && !*file) {

            file = NULL;

        }



        blk = blk_new_open(qemu_opts_id(opts), file, NULL, bs_opts, bdrv_flags,

                           errp);

        if (!blk) {

            goto err_no_bs_opts;

        }

        bs = blk_bs(blk);



        bs->detect_zeroes = detect_zeroes;



        /* disk I/O throttling */

        if (throttle_enabled(&cfg)) {

            if (!throttling_group) {

                throttling_group = blk_name(blk);

            }

            bdrv_io_limits_enable(bs, throttling_group);

            bdrv_set_io_limits(bs, &cfg);

        }



        if (bdrv_key_required(bs)) {

            autostart = 0;

        }



        block_acct_init(blk_get_stats(blk), account_invalid, account_failed);

    }



    blk_set_on_error(blk, on_read_error, on_write_error);



err_no_bs_opts:

    qemu_opts_del(opts);

    return blk;



early_err:

    qemu_opts_del(opts);

err_no_opts:

    QDECREF(bs_opts);

    return NULL;

}

