static int ds1338_send(I2CSlave *i2c, uint8_t data)

{

    DS1338State *s = FROM_I2C_SLAVE(DS1338State, i2c);

    if (s->addr_byte) {

        s->ptr = data;

        s->addr_byte = 0;

        return 0;

    }

    s->nvram[s->ptr - 8] = data;

    if (data < 8) {

        qemu_get_timedate(&s->now, s->offset);

        switch(data) {

        case 0:

            /* TODO: Implement CH (stop) bit.  */

            s->now.tm_sec = from_bcd(data & 0x7f);

            break;

        case 1:

            s->now.tm_min = from_bcd(data & 0x7f);

            break;

        case 2:

            if (data & 0x40) {

                if (data & 0x20) {

                    data = from_bcd(data & 0x4f) + 11;

                } else {

                    data = from_bcd(data & 0x1f) - 1;

                }

            } else {

                data = from_bcd(data);

            }

            s->now.tm_hour = data;

            break;

        case 3:

            s->now.tm_wday = from_bcd(data & 7) - 1;

            break;

        case 4:

            s->now.tm_mday = from_bcd(data & 0x3f);

            break;

        case 5:

            s->now.tm_mon = from_bcd(data & 0x1f) - 1;

            break;

        case 6:

            s->now.tm_year = from_bcd(data) + 100;

            break;

        case 7:

            /* Control register. Currently ignored.  */

            break;

        }

        s->offset = qemu_timedate_diff(&s->now);

    }

    s->ptr = (s->ptr + 1) & 0xff;

    return 0;

}

static int vnc_display_get_address(const char *addrstr,

                                   bool websocket,

                                   bool reverse,

                                   int displaynum,

                                   int to,

                                   bool has_ipv4,

                                   bool has_ipv6,

                                   bool ipv4,

                                   bool ipv6,

                                   SocketAddress **retaddr,

                                   Error **errp)

{

    int ret = -1;

    SocketAddress *addr = NULL;



    addr = g_new0(SocketAddress, 1);



    if (strncmp(addrstr, "unix:", 5) == 0) {

        addr->type = SOCKET_ADDRESS_KIND_UNIX;

        addr->u.q_unix.data = g_new0(UnixSocketAddress, 1);

        addr->u.q_unix.data->path = g_strdup(addrstr + 5);



        if (websocket) {

            error_setg(errp, "UNIX sockets not supported with websock");

            goto cleanup;

        }



        if (to) {

            error_setg(errp, "Port range not support with UNIX socket");

            goto cleanup;

        }

        ret = 0;

    } else {

        const char *port;

        size_t hostlen;

        unsigned long long baseport = 0;

        InetSocketAddress *inet;



        port = strrchr(addrstr, ':');

        if (!port) {

            if (websocket) {

                hostlen = 0;

                port = addrstr;

            } else {

                error_setg(errp, "no vnc port specified");

                goto cleanup;

            }

        } else {

            hostlen = port - addrstr;

            port++;

            if (*port == '\0') {

                error_setg(errp, "vnc port cannot be empty");

                goto cleanup;

            }

        }



        addr->type = SOCKET_ADDRESS_KIND_INET;

        inet = addr->u.inet.data = g_new0(InetSocketAddress, 1);

        if (addrstr[0] == '[' && addrstr[hostlen - 1] == ']') {

            inet->host = g_strndup(addrstr + 1, hostlen - 2);

        } else {

            inet->host = g_strndup(addrstr, hostlen);

        }

        /* plain VNC port is just an offset, for websocket

         * port is absolute */

        if (websocket) {

            if (g_str_equal(addrstr, "") ||

                g_str_equal(addrstr, "on")) {

                if (displaynum == -1) {

                    error_setg(errp, "explicit websocket port is required");

                    goto cleanup;

                }

                inet->port = g_strdup_printf(

                    "%d", displaynum + 5700);

                if (to) {

                    inet->has_to = true;

                    inet->to = to + 5700;

                }

            } else {

                inet->port = g_strdup(port);

            }

        } else {

            int offset = reverse ? 0 : 5900;

            if (parse_uint_full(port, &baseport, 10) < 0) {

                error_setg(errp, "can't convert to a number: %s", port);

                goto cleanup;

            }

            if (baseport > 65535 ||

                baseport + offset > 65535) {

                error_setg(errp, "port %s out of range", port);

                goto cleanup;

            }

            inet->port = g_strdup_printf(

                "%d", (int)baseport + offset);



            if (to) {

                inet->has_to = true;

                inet->to = to + offset;

            }

        }



        inet->ipv4 = ipv4;

        inet->has_ipv4 = has_ipv4;

        inet->ipv6 = ipv6;

        inet->has_ipv6 = has_ipv6;



        ret = baseport;

    }



    *retaddr = addr;



 cleanup:

    if (ret < 0) {

        qapi_free_SocketAddress(addr);

    }

    return ret;

}

