static void pl050_write(void *opaque, hwaddr offset,

                        uint64_t value, unsigned size)

{

    pl050_state *s = (pl050_state *)opaque;

    switch (offset >> 2) {

    case 0: /* KMICR */

        s->cr = value;

        pl050_update(s, s->pending);

        /* ??? Need to implement the enable/disable bit.  */

        break;

    case 2: /* KMIDATA */

        /* ??? This should toggle the TX interrupt line.  */

        /* ??? This means kbd/mouse can block each other.  */

        if (s->is_mouse) {

            ps2_write_mouse(s->dev, value);

        } else {

            ps2_write_keyboard(s->dev, value);

        }

        break;

    case 3: /* KMICLKDIV */

        s->clk = value;

        return;

    default:

        hw_error("pl050_write: Bad offset %x\n", (int)offset);

    }

}

static int eject_device(Monitor *mon, BlockDriverState *bs, int force)

{

    if (!bdrv_is_removable(bs)) {

        qerror_report(QERR_DEVICE_NOT_REMOVABLE, bdrv_get_device_name(bs));

        return -1;

    }

    if (!force && bdrv_dev_is_medium_locked(bs)) {

        qerror_report(QERR_DEVICE_LOCKED, bdrv_get_device_name(bs));

        return -1;

    }

    bdrv_close(bs);

    return 0;

}

static int load_dtb(target_phys_addr_t addr, const struct arm_boot_info *binfo)

{

#ifdef CONFIG_FDT

    uint32_t *mem_reg_property;

    uint32_t mem_reg_propsize;

    void *fdt = NULL;

    char *filename;

    int size, rc;

    uint32_t acells, scells, hival;



    filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, binfo->dtb_filename);

    if (!filename) {

        fprintf(stderr, "Couldn't open dtb file %s\n", binfo->dtb_filename);

        return -1;

    }



    fdt = load_device_tree(filename, &size);

    if (!fdt) {

        fprintf(stderr, "Couldn't open dtb file %s\n", filename);

        g_free(filename);

        return -1;

    }

    g_free(filename);



    acells = qemu_devtree_getprop_cell(fdt, "/", "#address-cells");

    scells = qemu_devtree_getprop_cell(fdt, "/", "#size-cells");

    if (acells == 0 || scells == 0) {

        fprintf(stderr, "dtb file invalid (#address-cells or #size-cells 0)\n");

        return -1;

    }



    mem_reg_propsize = acells + scells;

    mem_reg_property = g_new0(uint32_t, mem_reg_propsize);

    mem_reg_property[acells - 1] = cpu_to_be32(binfo->loader_start);

    hival = cpu_to_be32(binfo->loader_start >> 32);

    if (acells > 1) {

        mem_reg_property[acells - 2] = hival;

    } else if (hival != 0) {

        fprintf(stderr, "qemu: dtb file not compatible with "

                "RAM start address > 4GB\n");

        exit(1);

    }

    mem_reg_property[acells + scells - 1] = cpu_to_be32(binfo->ram_size);

    hival = cpu_to_be32(binfo->ram_size >> 32);

    if (scells > 1) {

        mem_reg_property[acells + scells - 2] = hival;

    } else if (hival != 0) {

        fprintf(stderr, "qemu: dtb file not compatible with "

                "RAM size > 4GB\n");

        exit(1);

    }



    rc = qemu_devtree_setprop(fdt, "/memory", "reg", mem_reg_property,

                              mem_reg_propsize * sizeof(uint32_t));

    if (rc < 0) {

        fprintf(stderr, "couldn't set /memory/reg\n");

    }



    if (binfo->kernel_cmdline && *binfo->kernel_cmdline) {

        rc = qemu_devtree_setprop_string(fdt, "/chosen", "bootargs",

                                          binfo->kernel_cmdline);

        if (rc < 0) {

            fprintf(stderr, "couldn't set /chosen/bootargs\n");

        }

    }



    if (binfo->initrd_size) {

        rc = qemu_devtree_setprop_cell(fdt, "/chosen", "linux,initrd-start",

                binfo->loader_start + INITRD_LOAD_ADDR);

        if (rc < 0) {

            fprintf(stderr, "couldn't set /chosen/linux,initrd-start\n");

        }



        rc = qemu_devtree_setprop_cell(fdt, "/chosen", "linux,initrd-end",

                    binfo->loader_start + INITRD_LOAD_ADDR +

                    binfo->initrd_size);

        if (rc < 0) {

            fprintf(stderr, "couldn't set /chosen/linux,initrd-end\n");

        }

    }



    cpu_physical_memory_write(addr, fdt, size);



    return 0;



#else

    fprintf(stderr, "Device tree requested, "

                "but qemu was compiled without fdt support\n");

    return -1;

#endif

}

static void flush_compressed_data(QEMUFile *f)

{

    int idx, len, thread_count;



    if (!migrate_use_compression()) {

        return;

    }

    thread_count = migrate_compress_threads();

    for (idx = 0; idx < thread_count; idx++) {

        if (!comp_param[idx].done) {

            qemu_mutex_lock(comp_done_lock);

            while (!comp_param[idx].done && !quit_comp_thread) {

                qemu_cond_wait(comp_done_cond, comp_done_lock);

            }

            qemu_mutex_unlock(comp_done_lock);

        }

        if (!quit_comp_thread) {

            len = qemu_put_qemu_file(f, comp_param[idx].file);

            bytes_transferred += len;

        }

    }

}

sPAPRDRConnector *spapr_dr_connector_new(Object *owner,

                                         sPAPRDRConnectorType type,

                                         uint32_t id)

{

    sPAPRDRConnector *drc =

        SPAPR_DR_CONNECTOR(object_new(TYPE_SPAPR_DR_CONNECTOR));



    g_assert(type);



    drc->type = type;

    drc->id = id;

    drc->owner = owner;

    object_property_add_child(owner, "dr-connector[*]", OBJECT(drc), NULL);

    object_property_set_bool(OBJECT(drc), true, "realized", NULL);



    /* human-readable name for a DRC to encode into the DT

     * description. this is mainly only used within a guest in place

     * of the unique DRC index.

     *

     * in the case of VIO/PCI devices, it corresponds to a

     * "location code" that maps a logical device/function (DRC index)

     * to a physical (or virtual in the case of VIO) location in the

     * system by chaining together the "location label" for each

     * encapsulating component.

     *

     * since this is more to do with diagnosing physical hardware

     * issues than guest compatibility, we choose location codes/DRC

     * names that adhere to the documented format, but avoid encoding

     * the entire topology information into the label/code, instead

     * just using the location codes based on the labels for the

     * endpoints (VIO/PCI adaptor connectors), which is basically

     * just "C" followed by an integer ID.

     *

     * DRC names as documented by PAPR+ v2.7, 13.5.2.4

     * location codes as documented by PAPR+ v2.7, 12.3.1.5

     */

    switch (drc->type) {

    case SPAPR_DR_CONNECTOR_TYPE_CPU:

        drc->name = g_strdup_printf("CPU %d", id);

        break;

    case SPAPR_DR_CONNECTOR_TYPE_PHB:

        drc->name = g_strdup_printf("PHB %d", id);

        break;

    case SPAPR_DR_CONNECTOR_TYPE_VIO:

    case SPAPR_DR_CONNECTOR_TYPE_PCI:

        drc->name = g_strdup_printf("C%d", id);

        break;

    case SPAPR_DR_CONNECTOR_TYPE_LMB:

        drc->name = g_strdup_printf("LMB %d", id);

        break;

    default:

        g_assert(false);

    }



    /* PCI slot always start in a USABLE state, and stay there */

    if (drc->type == SPAPR_DR_CONNECTOR_TYPE_PCI) {

        drc->allocation_state = SPAPR_DR_ALLOCATION_STATE_USABLE;

    }



    return drc;

}

