static uint16_t nvme_map_prp(QEMUSGList *qsg, QEMUIOVector *iov, uint64_t prp1,

                             uint64_t prp2, uint32_t len, NvmeCtrl *n)

{

    hwaddr trans_len = n->page_size - (prp1 % n->page_size);

    trans_len = MIN(len, trans_len);

    int num_prps = (len >> n->page_bits) + 1;



    if (!prp1) {

        return NVME_INVALID_FIELD | NVME_DNR;

    } else if (n->cmbsz && prp1 >= n->ctrl_mem.addr &&

               prp1 < n->ctrl_mem.addr + int128_get64(n->ctrl_mem.size)) {

        qsg->nsg = 0;

        qemu_iovec_init(iov, num_prps);

        qemu_iovec_add(iov, (void *)&n->cmbuf[prp1 - n->ctrl_mem.addr], trans_len);

    } else {

        pci_dma_sglist_init(qsg, &n->parent_obj, num_prps);

        qemu_sglist_add(qsg, prp1, trans_len);

    }

    len -= trans_len;

    if (len) {

        if (!prp2) {

            goto unmap;

        }

        if (len > n->page_size) {

            uint64_t prp_list[n->max_prp_ents];

            uint32_t nents, prp_trans;

            int i = 0;



            nents = (len + n->page_size - 1) >> n->page_bits;

            prp_trans = MIN(n->max_prp_ents, nents) * sizeof(uint64_t);

            nvme_addr_read(n, prp2, (void *)prp_list, prp_trans);

            while (len != 0) {

                uint64_t prp_ent = le64_to_cpu(prp_list[i]);



                if (i == n->max_prp_ents - 1 && len > n->page_size) {

                    if (!prp_ent || prp_ent & (n->page_size - 1)) {

                        goto unmap;

                    }



                    i = 0;

                    nents = (len + n->page_size - 1) >> n->page_bits;

                    prp_trans = MIN(n->max_prp_ents, nents) * sizeof(uint64_t);

                    nvme_addr_read(n, prp_ent, (void *)prp_list,

                        prp_trans);

                    prp_ent = le64_to_cpu(prp_list[i]);

                }



                if (!prp_ent || prp_ent & (n->page_size - 1)) {

                    goto unmap;

                }



                trans_len = MIN(len, n->page_size);

                if (qsg->nsg){

                    qemu_sglist_add(qsg, prp_ent, trans_len);

                } else {

                    qemu_iovec_add(iov, (void *)&n->cmbuf[prp_ent - n->ctrl_mem.addr], trans_len);

                }

                len -= trans_len;

                i++;

            }

        } else {

            if (prp2 & (n->page_size - 1)) {

                goto unmap;

            }

            if (qsg->nsg) {

                qemu_sglist_add(qsg, prp2, len);

            } else {

                qemu_iovec_add(iov, (void *)&n->cmbuf[prp2 - n->ctrl_mem.addr], trans_len);

            }

        }

    }

    return NVME_SUCCESS;



 unmap:

    qemu_sglist_destroy(qsg);

    return NVME_INVALID_FIELD | NVME_DNR;

}

static GuestPCIAddress *get_pci_info(char *guid, Error **errp)

{

    HDEVINFO dev_info;

    SP_DEVINFO_DATA dev_info_data;

    DWORD size = 0;

    int i;

    char dev_name[MAX_PATH];

    char *buffer = NULL;

    GuestPCIAddress *pci = NULL;

    char *name = g_strdup(&guid[4]);



    if (!QueryDosDevice(name, dev_name, ARRAY_SIZE(dev_name))) {

        error_setg_win32(errp, GetLastError(), "failed to get dos device name");

        goto out;

    }



    dev_info = SetupDiGetClassDevs(&GUID_DEVINTERFACE_VOLUME, 0, 0,

                                   DIGCF_PRESENT | DIGCF_DEVICEINTERFACE);

    if (dev_info == INVALID_HANDLE_VALUE) {

        error_setg_win32(errp, GetLastError(), "failed to get devices tree");

        goto out;

    }



    dev_info_data.cbSize = sizeof(SP_DEVINFO_DATA);

    for (i = 0; SetupDiEnumDeviceInfo(dev_info, i, &dev_info_data); i++) {

        DWORD addr, bus, slot, func, dev, data, size2;

        while (!SetupDiGetDeviceRegistryProperty(dev_info, &dev_info_data,

                                            SPDRP_PHYSICAL_DEVICE_OBJECT_NAME,

                                            &data, (PBYTE)buffer, size,

                                            &size2)) {

            size = MAX(size, size2);

            if (GetLastError() == ERROR_INSUFFICIENT_BUFFER) {

                g_free(buffer);

                /* Double the size to avoid problems on

                 * W2k MBCS systems per KB 888609.

                 * https://support.microsoft.com/en-us/kb/259695 */

                buffer = g_malloc(size * 2);

            } else {

                error_setg_win32(errp, GetLastError(),

                        "failed to get device name");

                goto out;

            }

        }



        if (g_strcmp0(buffer, dev_name)) {

            continue;

        }



        /* There is no need to allocate buffer in the next functions. The size

         * is known and ULONG according to

         * https://support.microsoft.com/en-us/kb/253232

         * https://msdn.microsoft.com/en-us/library/windows/hardware/ff543095(v=vs.85).aspx

         */

        if (!SetupDiGetDeviceRegistryProperty(dev_info, &dev_info_data,

                   SPDRP_BUSNUMBER, &data, (PBYTE)&bus, size, NULL)) {

            break;

        }



        /* The function retrieves the device's address. This value will be

         * transformed into device function and number */

        if (!SetupDiGetDeviceRegistryProperty(dev_info, &dev_info_data,

                   SPDRP_ADDRESS, &data, (PBYTE)&addr, size, NULL)) {

            break;

        }



        /* This call returns UINumber of DEVICE_CAPABILITIES structure.

         * This number is typically a user-perceived slot number. */

        if (!SetupDiGetDeviceRegistryProperty(dev_info, &dev_info_data,

                   SPDRP_UI_NUMBER, &data, (PBYTE)&slot, size, NULL)) {

            break;

        }



        /* SetupApi gives us the same information as driver with

         * IoGetDeviceProperty. According to Microsoft

         * https://support.microsoft.com/en-us/kb/253232

         * FunctionNumber = (USHORT)((propertyAddress) & 0x0000FFFF);

         * DeviceNumber = (USHORT)(((propertyAddress) >> 16) & 0x0000FFFF);

         * SPDRP_ADDRESS is propertyAddress, so we do the same.*/



        func = addr & 0x0000FFFF;

        dev = (addr >> 16) & 0x0000FFFF;

        pci = g_malloc0(sizeof(*pci));

        pci->domain = dev;

        pci->slot = slot;

        pci->function = func;

        pci->bus = bus;

        break;

    }

out:

    g_free(buffer);

    g_free(name);

    return pci;

}

int target_get_monitor_def(CPUState *cs, const char *name, uint64_t *pval)

{

    int i, regnum;

    PowerPCCPU *cpu = POWERPC_CPU(cs);

    CPUPPCState *env = &cpu->env;



    /* General purpose registers */

    if ((tolower(name[0]) == 'r') &&

        ppc_cpu_get_reg_num(name + 1, ARRAY_SIZE(env->gpr), &regnum)) {

        *pval = env->gpr[regnum];

        return 0;

    }



    /* Floating point registers */

    if ((tolower(name[0]) == 'f') &&

        ppc_cpu_get_reg_num(name + 1, ARRAY_SIZE(env->fpr), &regnum)) {

        *pval = env->fpr[regnum];

        return 0;

    }



    /* Special purpose registers */

    for (i = 0; i < ARRAY_SIZE(env->spr_cb); ++i) {

        ppc_spr_t *spr = &env->spr_cb[i];



        if (spr->name && (strcasecmp(name, spr->name) == 0)) {

            *pval = env->spr[i];

            return 0;

        }

    }



    /* Segment registers */

#if !defined(CONFIG_USER_ONLY)

    if ((strncasecmp(name, "sr", 2) == 0) &&

        ppc_cpu_get_reg_num(name + 2, ARRAY_SIZE(env->sr), &regnum)) {

        *pval = env->sr[regnum];

        return 0;

    }

#endif



    return -EINVAL;

}

