                               NULL, "z2.flash0", Z2_FLASH_SIZE,

                               dinfo ? blk_bs(blk_by_legacy_dinfo(dinfo)) : NULL,

                               sector_len, Z2_FLASH_SIZE / sector_len,

                               4, 0, 0, 0, 0, be)) {

        fprintf(stderr, "qemu: Error registering flash memory.\n");

        exit(1);

    }



    /* setup keypad */

    pxa27x_register_keypad(mpu->kp, map, 0x100);



    /* MMC/SD host */

    pxa2xx_mmci_handlers(mpu->mmc,

        NULL,

        qdev_get_gpio_in(mpu->gpio, Z2_GPIO_SD_DETECT));



    type_register_static(&zipit_lcd_info);

    type_register_static(&aer915_info);

    z2_lcd = ssi_create_slave(mpu->ssp[1], "zipit-lcd");

    bus = pxa2xx_i2c_bus(mpu->i2c[0]);

    i2c_create_slave(bus, TYPE_AER915, 0x55);

    wm = i2c_create_slave(bus, "wm8750", 0x1b);

    mpu->i2s->opaque = wm;

    mpu->i2s->codec_out = wm8750_dac_dat;

    mpu->i2s->codec_in = wm8750_adc_dat;

    wm8750_data_req_set(wm, mpu->i2s->data_req, mpu->i2s);



    qdev_connect_gpio_out(mpu->gpio, Z2_GPIO_LCD_CS,

                          qemu_allocate_irq(z2_lcd_cs, z2_lcd, 0));



    z2_binfo.kernel_filename = kernel_filename;

    z2_binfo.kernel_cmdline = kernel_cmdline;

    z2_binfo.initrd_filename = initrd_filename;

    z2_binfo.board_id = 0x6dd;

    arm_load_kernel(mpu->cpu, &z2_binfo);

}

static int stdio_fclose(void *opaque)

{

    QEMUFileStdio *s = opaque;

    int ret = 0;



    if (s->file->ops->put_buffer || s->file->ops->writev_buffer) {

        int fd = fileno(s->stdio_file);

        struct stat st;



        ret = fstat(fd, &st);

        if (ret == 0 && S_ISREG(st.st_mode)) {

            /*

             * If the file handle is a regular file make sure the

             * data is flushed to disk before signaling success.

             */

            ret = fsync(fd);

            if (ret != 0) {

                ret = -errno;

                return ret;

            }

        }

    }

    if (fclose(s->stdio_file) == EOF) {

        ret = -errno;

    }

    g_free(s);

    return ret;

}

static int vmdk_open_vmdk4(BlockDriverState *bs,

                           BlockDriverState *file,

                           int flags, Error **errp)

{

    int ret;

    uint32_t magic;

    uint32_t l1_size, l1_entry_sectors;

    VMDK4Header header;

    VmdkExtent *extent;

    BDRVVmdkState *s = bs->opaque;

    int64_t l1_backup_offset = 0;



    ret = bdrv_pread(file, sizeof(magic), &header, sizeof(header));

    if (ret < 0) {

        error_setg_errno(errp, -ret,

                         "Could not read header from file '%s'",

                         file->filename);

        return -EINVAL;

    }

    if (header.capacity == 0) {

        uint64_t desc_offset = le64_to_cpu(header.desc_offset);

        if (desc_offset) {

            char *buf = vmdk_read_desc(file, desc_offset << 9, errp);

            if (!buf) {

                return -EINVAL;

            }

            ret = vmdk_open_desc_file(bs, flags, buf, errp);

            g_free(buf);

            return ret;

        }

    }



    if (!s->create_type) {

        s->create_type = g_strdup("monolithicSparse");

    }



    if (le64_to_cpu(header.gd_offset) == VMDK4_GD_AT_END) {

        /*

         * The footer takes precedence over the header, so read it in. The

         * footer starts at offset -1024 from the end: One sector for the

         * footer, and another one for the end-of-stream marker.

         */

        struct {

            struct {

                uint64_t val;

                uint32_t size;

                uint32_t type;

                uint8_t pad[512 - 16];

            } QEMU_PACKED footer_marker;



            uint32_t magic;

            VMDK4Header header;

            uint8_t pad[512 - 4 - sizeof(VMDK4Header)];



            struct {

                uint64_t val;

                uint32_t size;

                uint32_t type;

                uint8_t pad[512 - 16];

            } QEMU_PACKED eos_marker;

        } QEMU_PACKED footer;



        ret = bdrv_pread(file,

            bs->file->total_sectors * 512 - 1536,

            &footer, sizeof(footer));

        if (ret < 0) {

            error_setg_errno(errp, -ret, "Failed to read footer");

            return ret;

        }



        /* Some sanity checks for the footer */

        if (be32_to_cpu(footer.magic) != VMDK4_MAGIC ||

            le32_to_cpu(footer.footer_marker.size) != 0  ||

            le32_to_cpu(footer.footer_marker.type) != MARKER_FOOTER ||

            le64_to_cpu(footer.eos_marker.val) != 0  ||

            le32_to_cpu(footer.eos_marker.size) != 0  ||

            le32_to_cpu(footer.eos_marker.type) != MARKER_END_OF_STREAM)

        {

            error_setg(errp, "Invalid footer");

            return -EINVAL;

        }



        header = footer.header;

    }



    if (le32_to_cpu(header.version) > 3) {

        char buf[64];

        snprintf(buf, sizeof(buf), "VMDK version %" PRId32,

                 le32_to_cpu(header.version));

        error_set(errp, QERR_UNKNOWN_BLOCK_FORMAT_FEATURE,

                  bdrv_get_device_or_node_name(bs), "vmdk", buf);

        return -ENOTSUP;

    } else if (le32_to_cpu(header.version) == 3 && (flags & BDRV_O_RDWR)) {

        /* VMware KB 2064959 explains that version 3 added support for

         * persistent changed block tracking (CBT), and backup software can

         * read it as version=1 if it doesn't care about the changed area

         * information. So we are safe to enable read only. */

        error_setg(errp, "VMDK version 3 must be read only");

        return -EINVAL;

    }



    if (le32_to_cpu(header.num_gtes_per_gt) > 512) {

        error_setg(errp, "L2 table size too big");

        return -EINVAL;

    }



    l1_entry_sectors = le32_to_cpu(header.num_gtes_per_gt)

                        * le64_to_cpu(header.granularity);

    if (l1_entry_sectors == 0) {

        error_setg(errp, "L1 entry size is invalid");

        return -EINVAL;

    }

    l1_size = (le64_to_cpu(header.capacity) + l1_entry_sectors - 1)

                / l1_entry_sectors;

    if (le32_to_cpu(header.flags) & VMDK4_FLAG_RGD) {

        l1_backup_offset = le64_to_cpu(header.rgd_offset) << 9;

    }

    if (bdrv_nb_sectors(file) < le64_to_cpu(header.grain_offset)) {

        error_setg(errp, "File truncated, expecting at least %" PRId64 " bytes",

                   (int64_t)(le64_to_cpu(header.grain_offset)

                             * BDRV_SECTOR_SIZE));

        return -EINVAL;

    }



    ret = vmdk_add_extent(bs, file, false,

                          le64_to_cpu(header.capacity),

                          le64_to_cpu(header.gd_offset) << 9,

                          l1_backup_offset,

                          l1_size,

                          le32_to_cpu(header.num_gtes_per_gt),

                          le64_to_cpu(header.granularity),

                          &extent,

                          errp);

    if (ret < 0) {

        return ret;

    }

    extent->compressed =

        le16_to_cpu(header.compressAlgorithm) == VMDK4_COMPRESSION_DEFLATE;

    if (extent->compressed) {

        g_free(s->create_type);

        s->create_type = g_strdup("streamOptimized");

    }

    extent->has_marker = le32_to_cpu(header.flags) & VMDK4_FLAG_MARKER;

    extent->version = le32_to_cpu(header.version);

    extent->has_zero_grain = le32_to_cpu(header.flags) & VMDK4_FLAG_ZERO_GRAIN;

    ret = vmdk_init_tables(bs, extent, errp);

    if (ret) {

        /* free extent allocated by vmdk_add_extent */

        vmdk_free_last_extent(bs);

    }

    return ret;

}

dma_write(void *opaque, target_phys_addr_t addr,

	  uint64_t val64, unsigned int size)

{

        struct fs_dma_ctrl *ctrl = opaque;

	uint32_t value = val64;

	int c;



	if (size != 4) {

		dma_winvalid(opaque, addr, value);

	}



        /* Make addr relative to this channel and bounded to nr regs.  */

	c = fs_channel(addr);

        addr &= 0xff;

        addr >>= 2;

        switch (addr)

	{

		case RW_DATA:

			ctrl->channels[c].regs[addr] = value;

			break;



		case RW_CFG:

			ctrl->channels[c].regs[addr] = value;

			dma_update_state(ctrl, c);

			break;

		case RW_CMD:

			/* continue.  */

			if (value & ~1)

				printf("Invalid store to ch=%d RW_CMD %x\n",

				       c, value);

			ctrl->channels[c].regs[addr] = value;

			channel_continue(ctrl, c);

			break;



		case RW_SAVED_DATA:

		case RW_SAVED_DATA_BUF:

		case RW_GROUP:

		case RW_GROUP_DOWN:

			ctrl->channels[c].regs[addr] = value;

			break;



		case RW_ACK_INTR:

		case RW_INTR_MASK:

			ctrl->channels[c].regs[addr] = value;

			channel_update_irq(ctrl, c);

			if (addr == RW_ACK_INTR)

				ctrl->channels[c].regs[RW_ACK_INTR] = 0;

			break;



		case RW_STREAM_CMD:

			if (value & ~1023)

				printf("Invalid store to ch=%d "

				       "RW_STREAMCMD %x\n",

				       c, value);

			ctrl->channels[c].regs[addr] = value;

			D(printf("stream_cmd ch=%d\n", c));

			channel_stream_cmd(ctrl, c, value);

			break;



	        default:

			D(printf ("%s c=%d " TARGET_FMT_plx "\n",

				__func__, c, addr));

			break;

        }

}

static int scsi_generic_initfn(SCSIDevice *dev)

{

    SCSIGenericState *s = DO_UPCAST(SCSIGenericState, qdev, dev);

    int sg_version;

    struct sg_scsi_id scsiid;



    if (!s->qdev.conf.dinfo || !s->qdev.conf.dinfo->bdrv) {

        error_report("scsi-generic: drive property not set");

        return -1;

    }

    s->bs = s->qdev.conf.dinfo->bdrv;



    /* check we are really using a /dev/sg* file */

    if (!bdrv_is_sg(s->bs)) {

        error_report("scsi-generic: not /dev/sg*");

        return -1;

    }



    /* check we are using a driver managing SG_IO (version 3 and after */

    if (bdrv_ioctl(s->bs, SG_GET_VERSION_NUM, &sg_version) < 0 ||

        sg_version < 30000) {

        error_report("scsi-generic: scsi generic interface too old");

        return -1;

    }



    /* get LUN of the /dev/sg? */

    if (bdrv_ioctl(s->bs, SG_GET_SCSI_ID, &scsiid)) {

        error_report("scsi-generic: SG_GET_SCSI_ID ioctl failed");

        return -1;

    }



    /* define device state */

    s->lun = scsiid.lun;

    DPRINTF("LUN %d\n", s->lun);

    s->qdev.type = scsiid.scsi_type;

    DPRINTF("device type %d\n", s->qdev.type);

    if (s->qdev.type == TYPE_TAPE) {

        s->qdev.blocksize = get_stream_blocksize(s->bs);

        if (s->qdev.blocksize == -1)

            s->qdev.blocksize = 0;

    } else {

        s->qdev.blocksize = get_blocksize(s->bs);

        /* removable media returns 0 if not present */

        if (s->qdev.blocksize <= 0) {

            if (s->qdev.type == TYPE_ROM || s->qdev.type  == TYPE_WORM)

                s->qdev.blocksize = 2048;

            else

                s->qdev.blocksize = 512;

        }

    }

    DPRINTF("block size %d\n", s->qdev.blocksize);

    s->driver_status = 0;

    memset(s->sensebuf, 0, sizeof(s->sensebuf));

    return 0;

}

