static void tftp_handle_rrq(struct tftp_t *tp, int pktlen)

{

  struct tftp_session *spt;

  int s, k, n;

  u_int8_t *src, *dst;



  s = tftp_session_allocate(tp);



  if (s < 0) {

    return;

  }



  spt = &tftp_sessions[s];



  src = tp->x.tp_buf;

  dst = spt->filename;

  n = pktlen - ((uint8_t *)&tp->x.tp_buf[0] - (uint8_t *)tp);



  /* get name */



  for (k = 0; k < n; k++) {

    if (k < TFTP_FILENAME_MAX) {

      dst[k] = src[k];

    }

    else {

      return;

    }



    if (src[k] == '\0') {

      break;

    }

  }



  if (k >= n) {

    return;

  }



  k++;



  /* check mode */

  if ((n - k) < 6) {

    return;

  }



  if (memcmp(&src[k], "octet\0", 6) != 0) {

      tftp_send_error(spt, 4, "Unsupported transfer mode", tp);

      return;

  }



  k += 6; /* skipping octet */



  /* do sanity checks on the filename */



  if ((spt->filename[0] != '/')

      || (spt->filename[strlen((char *)spt->filename) - 1] == '/')

      ||  strstr((char *)spt->filename, "/../")) {

      tftp_send_error(spt, 2, "Access violation", tp);

      return;

  }



  /* only allow exported prefixes */



  if (!tftp_prefix) {

      tftp_send_error(spt, 2, "Access violation", tp);

      return;

  }



  /* check if the file exists */



  if (tftp_read_data(spt, 0, spt->filename, 0) < 0) {

      tftp_send_error(spt, 1, "File not found", tp);

      return;

  }



  if (src[n - 1] != 0) {

      tftp_send_error(spt, 2, "Access violation", tp);

      return;

  }



  while (k < n) {

      const char *key, *value;



      key = (char *)src + k;

      k += strlen(key) + 1;



      if (k >= n) {

	  tftp_send_error(spt, 2, "Access violation", tp);

	  return;

      }



      value = (char *)src + k;

      k += strlen(value) + 1;



      if (strcmp(key, "tsize") == 0) {

	  int tsize = atoi(value);

	  struct stat stat_p;



	  if (tsize == 0 && tftp_prefix) {

	      char buffer[1024];

	      int len;



	      len = snprintf(buffer, sizeof(buffer), "%s/%s",

			     tftp_prefix, spt->filename);



	      if (stat(buffer, &stat_p) == 0)

		  tsize = stat_p.st_size;

	      else {

		  tftp_send_error(spt, 1, "File not found", tp);

		  return;

	      }

	  }



	  tftp_send_oack(spt, "tsize", tsize, tp);

      }

  }



  tftp_send_data(spt, 1, tp);

}

static int waveformat_to_audio_settings (WAVEFORMATEX *wfx, audsettings_t *as)

{

    if (wfx->wFormatTag != WAVE_FORMAT_PCM) {

        dolog ("Invalid wave format, tag is not PCM, but %d\n",

               wfx->wFormatTag);

        return -1;

    }



    if (!wfx->nSamplesPerSec) {

        dolog ("Invalid wave format, frequency is zero\n");

        return -1;

    }

    as->freq = wfx->nSamplesPerSec;



    switch (wfx->nChannels) {

    case 1:

        as->nchannels = 1;

        break;



    case 2:

        as->nchannels = 2;

        break;



    default:

        dolog (

            "Invalid wave format, number of channels is not 1 or 2, but %d\n",

            wfx->nChannels

            );

        return -1;

    }



    switch (wfx->wBitsPerSample) {

    case 8:

        as->fmt = AUD_FMT_U8;

        break;



    case 16:

        as->fmt = AUD_FMT_S16;

        break;



    case 32:

        as->fmt = AUD_FMT_S32;

        break;



    default:

        dolog ("Invalid wave format, bits per sample is not "

               "8, 16 or 32, but %d\n",

               wfx->wBitsPerSample);

        return -1;

    }



    return 0;

}

void css_queue_crw(uint8_t rsc, uint8_t erc, int chain, uint16_t rsid)

{

    CrwContainer *crw_cont;



    trace_css_crw(rsc, erc, rsid, chain ? "(chained)" : "");

    /* TODO: Maybe use a static crw pool? */

    crw_cont = g_try_malloc0(sizeof(CrwContainer));

    if (!crw_cont) {

        channel_subsys.crws_lost = true;

        return;

    }

    crw_cont->crw.flags = (rsc << 8) | erc;

    if (chain) {

        crw_cont->crw.flags |= CRW_FLAGS_MASK_C;

    }

    crw_cont->crw.rsid = rsid;

    if (channel_subsys.crws_lost) {

        crw_cont->crw.flags |= CRW_FLAGS_MASK_R;

        channel_subsys.crws_lost = false;

    }



    QTAILQ_INSERT_TAIL(&channel_subsys.pending_crws, crw_cont, sibling);



    if (channel_subsys.do_crw_mchk) {

        channel_subsys.do_crw_mchk = false;

        /* Inject crw pending machine check. */

        s390_crw_mchk();

    }

}

