static int sd_snapshot_goto(BlockDriverState *bs, const char *snapshot_id)

{

    BDRVSheepdogState *s = bs->opaque;

    BDRVSheepdogState *old_s;

    char vdi[SD_MAX_VDI_LEN], tag[SD_MAX_VDI_TAG_LEN];

    char *buf = NULL;

    uint32_t vid;

    uint32_t snapid = 0;

    int ret = 0, fd;



    old_s = g_malloc(sizeof(BDRVSheepdogState));



    memcpy(old_s, s, sizeof(BDRVSheepdogState));



    pstrcpy(vdi, sizeof(vdi), s->name);



    snapid = strtoul(snapshot_id, NULL, 10);

    if (snapid) {

        tag[0] = 0;

    } else {

        pstrcpy(tag, sizeof(tag), s->name);

    }



    ret = find_vdi_name(s, vdi, snapid, tag, &vid, 1);

    if (ret) {

        error_report("Failed to find_vdi_name");

        goto out;

    }



    fd = connect_to_sdog(s->addr, s->port);

    if (fd < 0) {

        error_report("failed to connect");

        ret = fd;

        goto out;

    }



    buf = g_malloc(SD_INODE_SIZE);

    ret = read_object(fd, buf, vid_to_vdi_oid(vid), s->inode.nr_copies,

                      SD_INODE_SIZE, 0, s->cache_enabled);



    closesocket(fd);



    if (ret) {

        goto out;

    }



    memcpy(&s->inode, buf, sizeof(s->inode));



    if (!s->inode.vm_state_size) {

        error_report("Invalid snapshot");

        ret = -ENOENT;

        goto out;

    }



    s->is_snapshot = true;



    g_free(buf);

    g_free(old_s);



    return 0;

out:

    /* recover bdrv_sd_state */

    memcpy(s, old_s, sizeof(BDRVSheepdogState));

    g_free(buf);

    g_free(old_s);



    error_report("failed to open. recover old bdrv_sd_state.");



    return ret;

}

static void ehci_advance_state(EHCIState *ehci,

                               int async)

{

    EHCIQueue *q = NULL;

    int again;

    int iter = 0;



    do {

        if (ehci_get_state(ehci, async) == EST_FETCHQH) {

            iter++;

            /* if we are roaming a lot of QH without executing a qTD

             * something is wrong with the linked list. TO-DO: why is

             * this hack needed?

             */

            assert(iter < MAX_ITERATIONS);

#if 0

            if (iter > MAX_ITERATIONS) {

                DPRINTF("\n*** advance_state: bailing on MAX ITERATIONS***\n");

                ehci_set_state(ehci, async, EST_ACTIVE);

                break;

            }

#endif

        }

        switch(ehci_get_state(ehci, async)) {

        case EST_WAITLISTHEAD:

            again = ehci_state_waitlisthead(ehci, async);

            break;



        case EST_FETCHENTRY:

            again = ehci_state_fetchentry(ehci, async);

            break;



        case EST_FETCHQH:

            q = ehci_state_fetchqh(ehci, async);

            again = q ? 1 : 0;

            break;



        case EST_FETCHITD:

            again = ehci_state_fetchitd(ehci, async);

            break;



        case EST_FETCHSITD:

            again = ehci_state_fetchsitd(ehci, async);

            break;



        case EST_ADVANCEQUEUE:

            again = ehci_state_advqueue(q, async);

            break;



        case EST_FETCHQTD:

            again = ehci_state_fetchqtd(q, async);

            break;



        case EST_HORIZONTALQH:

            again = ehci_state_horizqh(q, async);

            break;



        case EST_EXECUTE:

            iter = 0;

            again = ehci_state_execute(q, async);

            break;



        case EST_EXECUTING:

            assert(q != NULL);

            again = ehci_state_executing(q, async);

            break;



        case EST_WRITEBACK:

            assert(q != NULL);

            again = ehci_state_writeback(q, async);

            break;



        default:

            fprintf(stderr, "Bad state!\n");

            again = -1;

            assert(0);

            break;

        }



        if (again < 0) {

            fprintf(stderr, "processing error - resetting ehci HC\n");

            ehci_reset(ehci);

            again = 0;

        }

    }

    while (again);



    ehci_commit_interrupt(ehci);

}

static bool run_poll_handlers_once(AioContext *ctx)

{

    bool progress = false;

    AioHandler *node;



    QLIST_FOREACH_RCU(node, &ctx->aio_handlers, node) {

        if (!node->deleted && node->io_poll &&

            aio_node_check(ctx, node->is_external) &&

            node->io_poll(node->opaque)) {

            progress = true;

        }



        /* Caller handles freeing deleted nodes.  Don't do it here. */

    }



    return progress;

}

print_insn_ppi (int field_b, struct disassemble_info *info)

{

  static const char *sx_tab[] = { "x0", "x1", "a0", "a1" };

  static const char *sy_tab[] = { "y0", "y1", "m0", "m1" };

  fprintf_ftype fprintf_fn = info->fprintf_func;

  void *stream = info->stream;

  unsigned int nib1, nib2, nib3;

  unsigned int altnib1, nib4;

  const char *dc = NULL;

  const sh_opcode_info *op;



  if ((field_b & 0xe800) == 0)

    {

      fprintf_fn (stream, "psh%c\t#%d,",

		  field_b & 0x1000 ? 'a' : 'l',

		  (field_b >> 4) & 127);

      print_dsp_reg (field_b & 0xf, fprintf_fn, stream);

      return;

    }

  if ((field_b & 0xc000) == 0x4000 && (field_b & 0x3000) != 0x1000)

    {

      static const char *du_tab[] = { "x0", "y0", "a0", "a1" };

      static const char *se_tab[] = { "x0", "x1", "y0", "a1" };

      static const char *sf_tab[] = { "y0", "y1", "x0", "a1" };

      static const char *sg_tab[] = { "m0", "m1", "a0", "a1" };



      if (field_b & 0x2000)

	{

	  fprintf_fn (stream, "p%s %s,%s,%s\t",

		      (field_b & 0x1000) ? "add" : "sub",

		      sx_tab[(field_b >> 6) & 3],

		      sy_tab[(field_b >> 4) & 3],

		      du_tab[(field_b >> 0) & 3]);

	}

      else if ((field_b & 0xf0) == 0x10

	       && info->mach != bfd_mach_sh_dsp

	       && info->mach != bfd_mach_sh3_dsp)

	{

	  fprintf_fn (stream, "pclr %s \t", du_tab[(field_b >> 0) & 3]);

	}

      else if ((field_b & 0xf3) != 0)

	{

	  fprintf_fn (stream, ".word 0x%x\t", field_b);

	}

      fprintf_fn (stream, "pmuls%c%s,%s,%s",

		  field_b & 0x2000 ? ' ' : '\t',

		  se_tab[(field_b >> 10) & 3],

		  sf_tab[(field_b >>  8) & 3],

		  sg_tab[(field_b >>  2) & 3]);

      return;

    }



  nib1 = PPIC;

  nib2 = field_b >> 12 & 0xf;

  nib3 = field_b >> 8 & 0xf;

  nib4 = field_b >> 4 & 0xf;

  switch (nib3 & 0x3)

    {

    case 0:

      dc = "";

      nib1 = PPI3;

      break;

    case 1:

      dc = "";

      break;

    case 2:

      dc = "dct ";

      nib3 -= 1;

      break;

    case 3:

      dc = "dcf ";

      nib3 -= 2;

      break;

    }

  if (nib1 == PPI3)

    altnib1 = PPI3NC;

  else

    altnib1 = nib1;

  for (op = sh_table; op->name; op++)

    {

      if ((op->nibbles[1] == nib1 || op->nibbles[1] == altnib1)

	  && op->nibbles[2] == nib2

	  && op->nibbles[3] == nib3)

	{

	  int n;



	  switch (op->nibbles[4])

	    {

	    case HEX_0:

	      break;

	    case HEX_XX00:

	      if ((nib4 & 3) != 0)

		continue;

	      break;

	    case HEX_1:

	      if ((nib4 & 3) != 1)

		continue;

	      break;

	    case HEX_00YY:

	      if ((nib4 & 0xc) != 0)

		continue;

	      break;

	    case HEX_4:

	      if ((nib4 & 0xc) != 4)

		continue;

	      break;

	    default:

	      abort ();

	    }

	  fprintf_fn (stream, "%s%s\t", dc, op->name);

	  for (n = 0; n < 3 && op->arg[n] != A_END; n++)

	    {

	      if (n && op->arg[1] != A_END)

		fprintf_fn (stream, ",");

	      switch (op->arg[n])

		{

		case DSP_REG_N:

		  print_dsp_reg (field_b & 0xf, fprintf_fn, stream);

		  break;

		case DSP_REG_X:

		  fprintf_fn (stream, sx_tab[(field_b >> 6) & 3]);

		  break;

		case DSP_REG_Y:

		  fprintf_fn (stream, sy_tab[(field_b >> 4) & 3]);

		  break;

		case A_MACH:

		  fprintf_fn (stream, "mach");

		  break;

		case A_MACL:

		  fprintf_fn (stream, "macl");

		  break;

		default:

		  abort ();

		}

	    }

	  return;

	}

    }

  /* Not found.  */

  fprintf_fn (stream, ".word 0x%x", field_b);

}

static int monitor_parse(const char *devname)

{

    static int index = 0;

    char label[32];



    if (strcmp(devname, "none") == 0)

        return 0;

    if (index == MAX_MONITOR_DEVICES) {

        fprintf(stderr, "qemu: too many monitor devices\n");

        exit(1);

    }

    if (index == 0) {

        snprintf(label, sizeof(label), "monitor");

    } else {

        snprintf(label, sizeof(label), "monitor%d", index);

    }

    monitor_hds[index] = qemu_chr_open(label, devname, NULL);

    if (!monitor_hds[index]) {

        fprintf(stderr, "qemu: could not open monitor device '%s'\n",

                devname);

        return -1;

    }

    index++;

    return 0;

}

