            ot = OT_BYTE;

        else

            ot = dflag ? OT_LONG : OT_WORD;



        if (prefixes & PREFIX_REPZ) {

            gen_string_es(s, ot, gen_op_stos + 9);

        } else {

            gen_string_es(s, ot, gen_op_stos);

        }

        break;

    case 0xac: /* lodsS */

    case 0xad:

        if ((b & 1) == 0)

            ot = OT_BYTE;

        else

            ot = dflag ? OT_LONG : OT_WORD;

        if (prefixes & PREFIX_REPZ) {

            gen_string_ds(s, ot, gen_op_lods + 9);

        } else {

            gen_string_ds(s, ot, gen_op_lods);

        }

        break;

    case 0xae: /* scasS */

    case 0xaf:

        if ((b & 1) == 0)

            ot = OT_BYTE;

        else

                ot = dflag ? OT_LONG : OT_WORD;

        if (prefixes & PREFIX_REPNZ) {

            if (s->cc_op != CC_OP_DYNAMIC)

                gen_op_set_cc_op(s->cc_op);

            gen_string_es(s, ot, gen_op_scas + 9 * 2);

            s->cc_op = CC_OP_DYNAMIC; /* cannot predict flags after */

        } else if (prefixes & PREFIX_REPZ) {

            if (s->cc_op != CC_OP_DYNAMIC)

                gen_op_set_cc_op(s->cc_op);

            gen_string_es(s, ot, gen_op_scas + 9);

            s->cc_op = CC_OP_DYNAMIC; /* cannot predict flags after */

        } else {

            gen_string_es(s, ot, gen_op_scas);

            s->cc_op = CC_OP_SUBB + ot;

        }

        break;



    case 0xa6: /* cmpsS */

    case 0xa7:

        if ((b & 1) == 0)

            ot = OT_BYTE;

        else

            ot = dflag ? OT_LONG : OT_WORD;

        if (prefixes & PREFIX_REPNZ) {

            if (s->cc_op != CC_OP_DYNAMIC)

                gen_op_set_cc_op(s->cc_op);

            gen_string_ds(s, ot, gen_op_cmps + 9 * 2);

            s->cc_op = CC_OP_DYNAMIC; /* cannot predict flags after */

        } else if (prefixes & PREFIX_REPZ) {

            if (s->cc_op != CC_OP_DYNAMIC)

                gen_op_set_cc_op(s->cc_op);

            gen_string_ds(s, ot, gen_op_cmps + 9);

            s->cc_op = CC_OP_DYNAMIC; /* cannot predict flags after */

        } else {

            gen_string_ds(s, ot, gen_op_cmps);

            s->cc_op = CC_OP_SUBB + ot;

        }

        break;

    case 0x6c: /* insS */

    case 0x6d:

        if (s->cpl > s->iopl || s->vm86) {

            /* NOTE: even for (E)CX = 0 the exception is raised */

            gen_op_gpf(pc_start - s->cs_base);

        } else {

            if ((b & 1) == 0)

                ot = OT_BYTE;

            else

                ot = dflag ? OT_LONG : OT_WORD;

            if (prefixes & PREFIX_REPZ) {

                gen_string_es(s, ot, gen_op_ins + 9);

            } else {

                gen_string_es(s, ot, gen_op_ins);

            }

        }

        break;

    case 0x6e: /* outsS */

    case 0x6f:

        if (s->cpl > s->iopl || s->vm86) {

            /* NOTE: even for (E)CX = 0 the exception is raised */

            gen_op_gpf(pc_start - s->cs_base);

        } else {

            if ((b & 1) == 0)

                ot = OT_BYTE;

            else

                ot = dflag ? OT_LONG : OT_WORD;

            if (prefixes & PREFIX_REPZ) {

                gen_string_ds(s, ot, gen_op_outs + 9);

            } else {

                gen_string_ds(s, ot, gen_op_outs);

            }

        }

        break;



        /************************/

        /* port I/O */

    case 0xe4:

    case 0xe5:

        if (s->cpl > s->iopl || s->vm86) {

            gen_op_gpf(pc_start - s->cs_base);

        } else {

            if ((b & 1) == 0)

                ot = OT_BYTE;

            else

                ot = dflag ? OT_LONG : OT_WORD;

            val = ldub(s->pc++);

            gen_op_movl_T0_im(val);

            gen_op_in[ot]();

            gen_op_mov_reg_T1[ot][R_EAX]();

        }

        break;

    case 0xe6:

    case 0xe7:

        if (s->cpl > s->iopl || s->vm86) {

            gen_op_gpf(pc_start - s->cs_base);

        } else {

            if ((b & 1) == 0)

                ot = OT_BYTE;

            else

                ot = dflag ? OT_LONG : OT_WORD;

            val = ldub(s->pc++);

            gen_op_movl_T0_im(val);

            gen_op_mov_TN_reg[ot][1][R_EAX]();

            gen_op_out[ot]();

        }

        break;

    case 0xec:

    case 0xed:

        if (s->cpl > s->iopl || s->vm86) {

            gen_op_gpf(pc_start - s->cs_base);

        } else {

            if ((b & 1) == 0)

                ot = OT_BYTE;

            else

                ot = dflag ? OT_LONG : OT_WORD;

            gen_op_mov_TN_reg[OT_WORD][0][R_EDX]();

            gen_op_in[ot]();

            gen_op_mov_reg_T1[ot][R_EAX]();

        }

        break;

    case 0xee:

    case 0xef:

        if (s->cpl > s->iopl || s->vm86) {

            gen_op_gpf(pc_start - s->cs_base);

        } else {

            if ((b & 1) == 0)

                ot = OT_BYTE;

            else

                ot = dflag ? OT_LONG : OT_WORD;

            gen_op_mov_TN_reg[OT_WORD][0][R_EDX]();

            gen_op_mov_TN_reg[ot][1][R_EAX]();

            gen_op_out[ot]();

        }

        break;



        /************************/

        /* control */

    case 0xc2: /* ret im */

        val = ldsw(s->pc);

        s->pc += 2;

        gen_pop_T0(s);

        if (s->ss32)

            gen_op_addl_ESP_im(val + (2 << s->dflag));

        else

            gen_op_addw_ESP_im(val + (2 << s->dflag));

        if (s->dflag == 0)

            gen_op_andl_T0_ffff();

        gen_op_jmp_T0();

        s->is_jmp = 1;

        break;

    case 0xc3: /* ret */

        gen_pop_T0(s);

        gen_pop_update(s);

        if (s->dflag == 0)

            gen_op_andl_T0_ffff();

        gen_op_jmp_T0();

        s->is_jmp = 1;

        break;

    case 0xca: /* lret im */

        /* XXX: not restartable */

        val = ldsw(s->pc);

        s->pc += 2;

        /* pop offset */

        gen_pop_T0(s);

        if (s->dflag == 0)

            gen_op_andl_T0_ffff();

        gen_op_jmp_T0();

        gen_pop_update(s);

        /* pop selector */

        gen_pop_T0(s);

        gen_movl_seg_T0(s, R_CS);

        gen_pop_update(s);

        /* add stack offset */

        if (s->ss32)

            gen_op_addl_ESP_im(val + (2 << s->dflag));

        else

            gen_op_addw_ESP_im(val + (2 << s->dflag));

        s->is_jmp = 1;

        break;

    case 0xcb: /* lret */

        /* XXX: not restartable */

        /* pop offset */

        gen_pop_T0(s);

        if (s->dflag == 0)

            gen_op_andl_T0_ffff();

        gen_op_jmp_T0();

        gen_pop_update(s);

        /* pop selector */

        gen_pop_T0(s);

        gen_movl_seg_T0(s, R_CS);

        gen_pop_update(s);

        s->is_jmp = 1;

        break;

    case 0xcf: /* iret */

        /* XXX: not restartable */

        /* pop offset */

        gen_pop_T0(s);

        if (s->dflag == 0)

            gen_op_andl_T0_ffff();

        gen_op_jmp_T0();

        gen_pop_update(s);

        /* pop selector */

        gen_pop_T0(s);

        gen_movl_seg_T0(s, R_CS);

        gen_pop_update(s);

        /* pop eflags */

        gen_pop_T0(s);

        if (s->dflag) {

            if (s->vm86)

                gen_op_movl_eflags_T0_vm(pc_start - s->cs_base);

            else

                gen_op_movl_eflags_T0();

        } else {

            if (s->vm86)

                gen_op_movw_eflags_T0_vm(pc_start - s->cs_base);

            else

                gen_op_movw_eflags_T0();

        }

        gen_pop_update(s);

        s->cc_op = CC_OP_EFLAGS;

        s->is_jmp = 1;

        break;

    case 0xe8: /* call im */

        {

            unsigned int next_eip;

            ot = dflag ? OT_LONG : OT_WORD;

            val = insn_get(s, ot);

            next_eip = s->pc - s->cs_base;

            val += next_eip;

            if (s->dflag == 0)

                val &= 0xffff;

            gen_op_movl_T0_im(next_eip);

            gen_push_T0(s);

            gen_op_jmp_im(val);

            s->is_jmp = 1;

        }

        break;

    case 0x9a: /* lcall im */

        {

            unsigned int selector, offset;



            ot = dflag ? OT_LONG : OT_WORD;

            offset = insn_get(s, ot);

            selector = insn_get(s, OT_WORD);



            /* push return segment + offset */

            gen_op_movl_T0_seg(R_CS);

            gen_push_T0(s);

            next_eip = s->pc - s->cs_base;

            gen_op_movl_T0_im(next_eip);

            gen_push_T0(s);



            /* change cs and pc */

            gen_op_movl_T0_im(selector);

            gen_movl_seg_T0(s, R_CS);

            gen_op_jmp_im((unsigned long)offset);

            s->is_jmp = 1;

        }

        break;

    case 0xe9: /* jmp */

        ot = dflag ? OT_LONG : OT_WORD;

        val = insn_get(s, ot);

        val += s->pc - s->cs_base;

        if (s->dflag == 0)

            val = val & 0xffff;

        gen_op_jmp_im(val);

        s->is_jmp = 1;

        break;

    case 0xea: /* ljmp im */

        {

            unsigned int selector, offset;



            ot = dflag ? OT_LONG : OT_WORD;

            offset = insn_get(s, ot);

            selector = insn_get(s, OT_WORD);



            /* change cs and pc */

            gen_op_movl_T0_im(selector);

            gen_movl_seg_T0(s, R_CS);

            gen_op_jmp_im((unsigned long)offset);

            s->is_jmp = 1;

        }

        break;

    case 0xeb: /* jmp Jb */

        val = (int8_t)insn_get(s, OT_BYTE);

        val += s->pc - s->cs_base;

        if (s->dflag == 0)

            val = val & 0xffff;

        gen_op_jmp_im(val);

        s->is_jmp = 1;

        break;

    case 0x70 ... 0x7f: /* jcc Jb */

        val = (int8_t)insn_get(s, OT_BYTE);

        goto do_jcc;

    case 0x180 ... 0x18f: /* jcc Jv */

        if (dflag) {

            val = insn_get(s, OT_LONG);

        } else {

            val = (int16_t)insn_get(s, OT_WORD); 

        }

    do_jcc:

        next_eip = s->pc - s->cs_base;

        val += next_eip;

        if (s->dflag == 0)

            val &= 0xffff;

        gen_jcc(s, b, val, next_eip);

        s->is_jmp = 1;

        break;



    case 0x190 ... 0x19f: /* setcc Gv */

        modrm = ldub(s->pc++);

        gen_setcc(s, b);

        gen_ldst_modrm(s, modrm, OT_BYTE, OR_TMP0, 1);

        break;

    case 0x140 ... 0x14f: /* cmov Gv, Ev */

        ot = dflag ? OT_LONG : OT_WORD;

        modrm = ldub(s->pc++);

        reg = (modrm >> 3) & 7;

        mod = (modrm >> 6) & 3;

        gen_setcc(s, b);

        if (mod != 3) {

            gen_lea_modrm(s, modrm, &reg_addr, &offset_addr);

            gen_op_ld_T1_A0[ot]();

        } else {

            rm = modrm & 7;

            gen_op_mov_TN_reg[ot][1][rm]();

        }

        gen_op_cmov_reg_T1_T0[ot - OT_WORD][reg]();

        break;



        /************************/

        /* flags */

    case 0x9c: /* pushf */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        if (s->vm86)

            gen_op_movl_T0_eflags_vm();

        else

            gen_op_movl_T0_eflags();

        gen_push_T0(s);

        break;

    case 0x9d: /* popf */

        gen_pop_T0(s);

        if (s->dflag) {

            if (s->vm86)

                gen_op_movl_eflags_T0_vm(pc_start - s->cs_base);

            else

                gen_op_movl_eflags_T0();

        } else {

            if (s->vm86)

                gen_op_movw_eflags_T0_vm(pc_start - s->cs_base);

            else

                gen_op_movw_eflags_T0();

        }

        gen_pop_update(s);

        s->cc_op = CC_OP_EFLAGS;

        break;

    case 0x9e: /* sahf */

        gen_op_mov_TN_reg[OT_BYTE][0][R_AH]();

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        gen_op_movb_eflags_T0();

        s->cc_op = CC_OP_EFLAGS;

        break;

    case 0x9f: /* lahf */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        gen_op_movl_T0_eflags();

        gen_op_mov_reg_T0[OT_BYTE][R_AH]();

        break;

    case 0xf5: /* cmc */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        gen_op_cmc();

        s->cc_op = CC_OP_EFLAGS;

        break;

    case 0xf8: /* clc */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        gen_op_clc();

        s->cc_op = CC_OP_EFLAGS;

        break;

    case 0xf9: /* stc */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        gen_op_stc();

        s->cc_op = CC_OP_EFLAGS;

        break;

    case 0xfc: /* cld */

        gen_op_cld();

        break;

    case 0xfd: /* std */

        gen_op_std();

        break;



        /************************/

        /* bit operations */

    case 0x1ba: /* bt/bts/btr/btc Gv, im */

        ot = dflag ? OT_LONG : OT_WORD;

        modrm = ldub(s->pc++);

        op = (modrm >> 3) & 7;

        mod = (modrm >> 6) & 3;

        rm = modrm & 7;

        if (mod != 3) {

            gen_lea_modrm(s, modrm, &reg_addr, &offset_addr);

            gen_op_ld_T0_A0[ot]();

        } else {

            gen_op_mov_TN_reg[ot][0][rm]();

        }

        /* load shift */

        val = ldub(s->pc++);

        gen_op_movl_T1_im(val);

        if (op < 4)

            goto illegal_op;

        op -= 4;

        gen_op_btx_T0_T1_cc[ot - OT_WORD][op]();

        s->cc_op = CC_OP_SARB + ot;

        if (op != 0) {

            if (mod != 3)

                gen_op_st_T0_A0[ot]();

            else

                gen_op_mov_reg_T0[ot][rm]();

        }

        break;

    case 0x1a3: /* bt Gv, Ev */

        op = 0;

        goto do_btx;

    case 0x1ab: /* bts */

        op = 1;

        goto do_btx;

    case 0x1b3: /* btr */

        op = 2;

        goto do_btx;

    case 0x1bb: /* btc */

        op = 3;

    do_btx:

        ot = dflag ? OT_LONG : OT_WORD;

        modrm = ldub(s->pc++);

        reg = (modrm >> 3) & 7;

        mod = (modrm >> 6) & 3;

        rm = modrm & 7;

        gen_op_mov_TN_reg[OT_LONG][1][reg]();

        if (mod != 3) {

            gen_lea_modrm(s, modrm, &reg_addr, &offset_addr);

            /* specific case: we need to add a displacement */

            if (ot == OT_WORD)

                gen_op_add_bitw_A0_T1();

            else

                gen_op_add_bitl_A0_T1();

            gen_op_ld_T0_A0[ot]();

        } else {

            gen_op_mov_TN_reg[ot][0][rm]();

        }

        gen_op_btx_T0_T1_cc[ot - OT_WORD][op]();

        s->cc_op = CC_OP_SARB + ot;

        if (op != 0) {

            if (mod != 3)

                gen_op_st_T0_A0[ot]();

            else

                gen_op_mov_reg_T0[ot][rm]();

        }

        break;

    case 0x1bc: /* bsf */

    case 0x1bd: /* bsr */

        ot = dflag ? OT_LONG : OT_WORD;

        modrm = ldub(s->pc++);

        reg = (modrm >> 3) & 7;

        gen_ldst_modrm(s, modrm, ot, OR_TMP0, 0);

        gen_op_bsx_T0_cc[ot - OT_WORD][b & 1]();

        /* NOTE: we always write back the result. Intel doc says it is

           undefined if T0 == 0 */

        gen_op_mov_reg_T0[ot][reg]();

        s->cc_op = CC_OP_LOGICB + ot;

        break;

        /************************/

        /* bcd */

    case 0x27: /* daa */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        gen_op_daa();

        s->cc_op = CC_OP_EFLAGS;

        break;

    case 0x2f: /* das */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        gen_op_das();

        s->cc_op = CC_OP_EFLAGS;

        break;

    case 0x37: /* aaa */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        gen_op_aaa();

        s->cc_op = CC_OP_EFLAGS;

        break;

    case 0x3f: /* aas */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        gen_op_aas();

        s->cc_op = CC_OP_EFLAGS;

        break;

    case 0xd4: /* aam */

        val = ldub(s->pc++);

        gen_op_aam(val);

        s->cc_op = CC_OP_LOGICB;

        break;

    case 0xd5: /* aad */

        val = ldub(s->pc++);

        gen_op_aad(val);

        s->cc_op = CC_OP_LOGICB;

        break;

        /************************/

        /* misc */

    case 0x90: /* nop */

        break;

    case 0xcc: /* int3 */

        gen_op_int3((long)pc_start);

        s->is_jmp = 1;

        break;

    case 0xcd: /* int N */

        val = ldub(s->pc++);

        gen_op_int_im(val, pc_start - s->cs_base);

        s->is_jmp = 1;

        break;

    case 0xce: /* into */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        gen_op_into();

        break;

    case 0xfa: /* cli */

        if (!s->vm86) {

            if (s->cpl <= s->iopl)

                gen_op_cli();

            else

                gen_op_gpf(pc_start - s->cs_base);

        } else {

            if (s->iopl == 3)

                gen_op_cli();

            else

                gen_op_cli_vm();

        }

        break;

    case 0xfb: /* sti */

        if (!s->vm86) {

            if (s->cpl <= s->iopl)

                gen_op_sti();

            else

                gen_op_gpf(pc_start - s->cs_base);

        } else {

            if (s->iopl == 3)

                gen_op_sti();

            else

                gen_op_sti_vm(pc_start - s->cs_base);

        }

        break;

    case 0x62: /* bound */

        ot = dflag ? OT_LONG : OT_WORD;

        modrm = ldub(s->pc++);

        reg = (modrm >> 3) & 7;

        mod = (modrm >> 6) & 3;

        if (mod == 3)

            goto illegal_op;

        gen_op_mov_reg_T0[ot][reg]();

        gen_lea_modrm(s, modrm, &reg_addr, &offset_addr);

        if (ot == OT_WORD)

            gen_op_boundw();

        else

            gen_op_boundl();

        break;

    case 0x1c8 ... 0x1cf: /* bswap reg */

        reg = b & 7;

        gen_op_mov_TN_reg[OT_LONG][0][reg]();

        gen_op_bswapl_T0();

        gen_op_mov_reg_T0[OT_LONG][reg]();

        break;

    case 0xd6: /* salc */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        gen_op_salc();

        break;

    case 0xe0: /* loopnz */

    case 0xe1: /* loopz */

        if (s->cc_op != CC_OP_DYNAMIC)

            gen_op_set_cc_op(s->cc_op);

        /* FALL THRU */

    case 0xe2: /* loop */

    case 0xe3: /* jecxz */

        val = (int8_t)insn_get(s, OT_BYTE);

        next_eip = s->pc - s->cs_base;

        val += next_eip;

        if (s->dflag == 0)

            val &= 0xffff;

        gen_op_loop[s->aflag][b & 3](val, next_eip);

        s->is_jmp = 1;

        break;

    case 0x131: /* rdtsc */

        gen_op_rdtsc();

        break;

    case 0x1a2: /* cpuid */

        gen_op_cpuid();

        break;

    case 0xf4: /* hlt */

        if (s->cpl == 0) {

            /* ignored */

        } else {

            gen_op_gpf(pc_start - s->cs_base);

        }

        break;

    default:

        goto illegal_op;

    }

    /* lock generation */

    if (s->prefix & PREFIX_LOCK)

        gen_op_unlock();

    return (long)s->pc;

 illegal_op:

    /* XXX: ensure that no lock was generated */

    return -1;

}

static void xhci_process_commands(XHCIState *xhci)

{

    XHCITRB trb;

    TRBType type;

    XHCIEvent event = {ER_COMMAND_COMPLETE, CC_SUCCESS};

    dma_addr_t addr;

    unsigned int i, slotid = 0;



    DPRINTF("xhci_process_commands()\n");

    if (!xhci_running(xhci)) {

        DPRINTF("xhci_process_commands() called while xHC stopped or paused\n");

        return;

    }



    xhci->crcr_low |= CRCR_CRR;



    while ((type = xhci_ring_fetch(xhci, &xhci->cmd_ring, &trb, &addr))) {

        event.ptr = addr;

        switch (type) {

        case CR_ENABLE_SLOT:

            for (i = 0; i < xhci->numslots; i++) {

                if (!xhci->slots[i].enabled) {

                    break;

                }

            }

            if (i >= xhci->numslots) {

                DPRINTF("xhci: no device slots available\n");

                event.ccode = CC_NO_SLOTS_ERROR;

            } else {

                slotid = i+1;

                event.ccode = xhci_enable_slot(xhci, slotid);

            }

            break;

        case CR_DISABLE_SLOT:

            slotid = xhci_get_slot(xhci, &event, &trb);

            if (slotid) {

                event.ccode = xhci_disable_slot(xhci, slotid);

            }

            break;

        case CR_ADDRESS_DEVICE:

            slotid = xhci_get_slot(xhci, &event, &trb);

            if (slotid) {

                event.ccode = xhci_address_slot(xhci, slotid, trb.parameter,

                                                trb.control & TRB_CR_BSR);

            }

            break;

        case CR_CONFIGURE_ENDPOINT:

            slotid = xhci_get_slot(xhci, &event, &trb);

            if (slotid) {

                event.ccode = xhci_configure_slot(xhci, slotid, trb.parameter,

                                                  trb.control & TRB_CR_DC);

            }

            break;

        case CR_EVALUATE_CONTEXT:

            slotid = xhci_get_slot(xhci, &event, &trb);

            if (slotid) {

                event.ccode = xhci_evaluate_slot(xhci, slotid, trb.parameter);

            }

            break;

        case CR_STOP_ENDPOINT:

            slotid = xhci_get_slot(xhci, &event, &trb);

            if (slotid) {

                unsigned int epid = (trb.control >> TRB_CR_EPID_SHIFT)

                    & TRB_CR_EPID_MASK;

                event.ccode = xhci_stop_ep(xhci, slotid, epid);

            }

            break;

        case CR_RESET_ENDPOINT:

            slotid = xhci_get_slot(xhci, &event, &trb);

            if (slotid) {

                unsigned int epid = (trb.control >> TRB_CR_EPID_SHIFT)

                    & TRB_CR_EPID_MASK;

                event.ccode = xhci_reset_ep(xhci, slotid, epid);

            }

            break;

        case CR_SET_TR_DEQUEUE:

            slotid = xhci_get_slot(xhci, &event, &trb);

            if (slotid) {

                unsigned int epid = (trb.control >> TRB_CR_EPID_SHIFT)

                    & TRB_CR_EPID_MASK;

                unsigned int streamid = (trb.status >> 16) & 0xffff;

                event.ccode = xhci_set_ep_dequeue(xhci, slotid,

                                                  epid, streamid,

                                                  trb.parameter);

            }

            break;

        case CR_RESET_DEVICE:

            slotid = xhci_get_slot(xhci, &event, &trb);

            if (slotid) {

                event.ccode = xhci_reset_slot(xhci, slotid);

            }

            break;

        case CR_GET_PORT_BANDWIDTH:

            event.ccode = xhci_get_port_bandwidth(xhci, trb.parameter);

            break;

        case CR_VENDOR_VIA_CHALLENGE_RESPONSE:

            xhci_via_challenge(xhci, trb.parameter);

            break;

        case CR_VENDOR_NEC_FIRMWARE_REVISION:

            event.type = 48; /* NEC reply */

            event.length = 0x3025;

            break;

        case CR_VENDOR_NEC_CHALLENGE_RESPONSE:

        {

            uint32_t chi = trb.parameter >> 32;

            uint32_t clo = trb.parameter;

            uint32_t val = xhci_nec_challenge(chi, clo);

            event.length = val & 0xFFFF;

            event.epid = val >> 16;

            slotid = val >> 24;

            event.type = 48; /* NEC reply */

        }

        break;

        default:

            trace_usb_xhci_unimplemented("command", type);

            event.ccode = CC_TRB_ERROR;

            break;

        }

        event.slotid = slotid;

        xhci_event(xhci, &event, 0);

    }

}

void cpu_loop(CPUTLGState *env)

{

    CPUState *cs = CPU(tilegx_env_get_cpu(env));

    int trapnr;



    while (1) {

        cpu_exec_start(cs);

        trapnr = cpu_tilegx_exec(cs);

        cpu_exec_end(cs);

        switch (trapnr) {

        case TILEGX_EXCP_SYSCALL:

            env->regs[TILEGX_R_RE] = do_syscall(env, env->regs[TILEGX_R_NR],

                                                env->regs[0], env->regs[1],

                                                env->regs[2], env->regs[3],

                                                env->regs[4], env->regs[5],

                                                env->regs[6], env->regs[7]);

            env->regs[TILEGX_R_ERR] = TILEGX_IS_ERRNO(env->regs[TILEGX_R_RE])

                                                      ? - env->regs[TILEGX_R_RE]

                                                      : 0;

            break;

        case TILEGX_EXCP_OPCODE_EXCH:

            do_exch(env, true, false);

            break;

        case TILEGX_EXCP_OPCODE_EXCH4:

            do_exch(env, false, false);

            break;

        case TILEGX_EXCP_OPCODE_CMPEXCH:

            do_exch(env, true, true);

            break;

        case TILEGX_EXCP_OPCODE_CMPEXCH4:

            do_exch(env, false, true);

            break;

        case TILEGX_EXCP_OPCODE_FETCHADD:

        case TILEGX_EXCP_OPCODE_FETCHADDGEZ:

        case TILEGX_EXCP_OPCODE_FETCHAND:

        case TILEGX_EXCP_OPCODE_FETCHOR:

            do_fetch(env, trapnr, true);

            break;

        case TILEGX_EXCP_OPCODE_FETCHADD4:

        case TILEGX_EXCP_OPCODE_FETCHADDGEZ4:

        case TILEGX_EXCP_OPCODE_FETCHAND4:

        case TILEGX_EXCP_OPCODE_FETCHOR4:

            do_fetch(env, trapnr, false);

            break;

        case TILEGX_EXCP_SIGNAL:

            do_signal(env, env->signo, env->sigcode);

            break;

        case TILEGX_EXCP_REG_IDN_ACCESS:

        case TILEGX_EXCP_REG_UDN_ACCESS:

            gen_sigill_reg(env);

            break;

        default:

            fprintf(stderr, "trapnr is %d[0x%x].\n", trapnr, trapnr);

            g_assert_not_reached();

        }

        process_pending_signals(env);

    }

}

sofree(struct socket *so)

{

  Slirp *slirp = so->slirp;

  struct mbuf *ifm;



  for (ifm = (struct mbuf *) slirp->if_fastq.qh_link;

       (struct quehead *) ifm != &slirp->if_fastq;

       ifm = ifm->ifq_next) {

    if (ifm->ifq_so == so) {

      ifm->ifq_so = NULL;





  for (ifm = (struct mbuf *) slirp->if_batchq.qh_link;

       (struct quehead *) ifm != &slirp->if_batchq;

       ifm = ifm->ifq_next) {

    if (ifm->ifq_so == so) {

      ifm->ifq_so = NULL;





  if (so->so_emu==EMU_RSH && so->extra) {

	sofree(so->extra);

	so->extra=NULL;


  if (so == slirp->tcp_last_so) {

      slirp->tcp_last_so = &slirp->tcb;

  } else if (so == slirp->udp_last_so) {

      slirp->udp_last_so = &slirp->udb;

  } else if (so == slirp->icmp_last_so) {

      slirp->icmp_last_so = &slirp->icmp;


  m_free(so->so_m);



  if(so->so_next && so->so_prev)

    remque(so);  /* crashes if so is not in a queue */






  free(so);

static int check_strtox_error(const char *p, char *endptr, const char **next,

                              int err)

{

    /* If no conversion was performed, prefer BSD behavior over glibc

     * behavior.

     */

    if (err == 0 && endptr == p) {

        err = EINVAL;

    }

    if (!next && *endptr) {

        return -EINVAL;

    }

    if (next) {

        *next = endptr;

    }

    return -err;

}

