int xen_pt_msix_init(XenPCIPassthroughState *s, uint32_t base)

{

    uint8_t id = 0;

    uint16_t control = 0;

    uint32_t table_off = 0;

    int i, total_entries, bar_index;

    XenHostPCIDevice *hd = &s->real_device;

    PCIDevice *d = &s->dev;

    int fd = -1;

    XenPTMSIX *msix = NULL;

    int rc = 0;



    rc = xen_host_pci_get_byte(hd, base + PCI_CAP_LIST_ID, &id);

    if (rc) {

        return rc;

    }



    if (id != PCI_CAP_ID_MSIX) {

        XEN_PT_ERR(d, "Invalid id %#x base %#x\n", id, base);

        return -1;

    }



    xen_host_pci_get_word(hd, base + PCI_MSIX_FLAGS, &control);

    total_entries = control & PCI_MSIX_FLAGS_QSIZE;

    total_entries += 1;



    s->msix = g_malloc0(sizeof (XenPTMSIX)

                        + total_entries * sizeof (XenPTMSIXEntry));

    msix = s->msix;



    msix->total_entries = total_entries;

    for (i = 0; i < total_entries; i++) {

        msix->msix_entry[i].pirq = XEN_PT_UNASSIGNED_PIRQ;

    }



    memory_region_init_io(&msix->mmio, OBJECT(s), &pci_msix_ops,

                          s, "xen-pci-pt-msix",

                          (total_entries * PCI_MSIX_ENTRY_SIZE

                           + XC_PAGE_SIZE - 1)

                          & XC_PAGE_MASK);



    xen_host_pci_get_long(hd, base + PCI_MSIX_TABLE, &table_off);

    bar_index = msix->bar_index = table_off & PCI_MSIX_FLAGS_BIRMASK;

    table_off = table_off & ~PCI_MSIX_FLAGS_BIRMASK;

    msix->table_base = s->real_device.io_regions[bar_index].base_addr;

    XEN_PT_LOG(d, "get MSI-X table BAR base 0x%"PRIx64"\n", msix->table_base);



    fd = open("/dev/mem", O_RDWR);

    if (fd == -1) {

        rc = -errno;

        XEN_PT_ERR(d, "Can't open /dev/mem: %s\n", strerror(errno));

        goto error_out;

    }

    XEN_PT_LOG(d, "table_off = %#x, total_entries = %d\n",

               table_off, total_entries);

    msix->table_offset_adjust = table_off & 0x0fff;

    msix->phys_iomem_base =

        mmap(NULL,

             total_entries * PCI_MSIX_ENTRY_SIZE + msix->table_offset_adjust,

             PROT_READ,

             MAP_SHARED | MAP_LOCKED,

             fd,

             msix->table_base + table_off - msix->table_offset_adjust);

    close(fd);

    if (msix->phys_iomem_base == MAP_FAILED) {

        rc = -errno;

        XEN_PT_ERR(d, "Can't map physical MSI-X table: %s\n", strerror(errno));

        goto error_out;

    }

    msix->phys_iomem_base = (char *)msix->phys_iomem_base

        + msix->table_offset_adjust;



    XEN_PT_LOG(d, "mapping physical MSI-X table to %p\n",

               msix->phys_iomem_base);



    memory_region_add_subregion_overlap(&s->bar[bar_index], table_off,

                                        &msix->mmio,

                                        2); /* Priority: pci default + 1 */



    return 0;



error_out:

    g_free(s->msix);

    s->msix = NULL;

    return rc;

}

static int64_t archipelago_volume_info(BDRVArchipelagoState *s)

{

    uint64_t size;

    int ret, targetlen;

    struct xseg_request *req;

    struct xseg_reply_info *xinfo;

    AIORequestData *reqdata = g_malloc(sizeof(AIORequestData));



    const char *volname = s->volname;

    targetlen = strlen(volname);

    req = xseg_get_request(s->xseg, s->srcport, s->mportno, X_ALLOC);

    if (!req) {

        archipelagolog("Cannot get XSEG request\n");

        goto err_exit2;

    }

    ret = xseg_prep_request(s->xseg, req, targetlen,

                            sizeof(struct xseg_reply_info));

    if (ret < 0) {

        archipelagolog("Cannot prepare XSEG request\n");

        goto err_exit;

    }

    char *target = xseg_get_target(s->xseg, req);

    if (!target) {

        archipelagolog("Cannot get XSEG target\n");

        goto err_exit;

    }

    memcpy(target, volname, targetlen);

    req->size = req->datalen;

    req->offset = 0;

    req->op = X_INFO;



    reqdata->op = ARCHIP_OP_VOLINFO;

    reqdata->volname = volname;

    xseg_set_req_data(s->xseg, req, reqdata);



    xport p = xseg_submit(s->xseg, req, s->srcport, X_ALLOC);

    if (p == NoPort) {

        archipelagolog("Cannot submit XSEG request\n");

        goto err_exit;

    }

    xseg_signal(s->xseg, p);

    qemu_mutex_lock(&s->archip_mutex);

    while (!s->is_signaled) {

        qemu_cond_wait(&s->archip_cond, &s->archip_mutex);

    }

    s->is_signaled = false;

    qemu_mutex_unlock(&s->archip_mutex);



    xinfo = (struct xseg_reply_info *) xseg_get_data(s->xseg, req);

    size = xinfo->size;

    xseg_put_request(s->xseg, req, s->srcport);

    g_free(reqdata);

    s->size = size;

    return size;



err_exit:

    xseg_put_request(s->xseg, req, s->srcport);

err_exit2:

    g_free(reqdata);

    return -EIO;

}

static void openpic_set_irq(void *opaque, int n_IRQ, int level)

{

    OpenPICState *opp = opaque;

    IRQSource *src;



    src = &opp->src[n_IRQ];

    DPRINTF("openpic: set irq %d = %d ipvp=%08x\n",

            n_IRQ, level, src->ipvp);

    if (src->ipvp & IPVP_SENSE_MASK) {

        /* level-sensitive irq */

        src->pending = level;

        if (!level) {

            src->ipvp &= ~IPVP_ACTIVITY_MASK;

        }

    } else {

        /* edge-sensitive irq */

        if (level) {

            src->pending = 1;

        }

    }

    openpic_update_irq(opp, n_IRQ);

}

