static void gt64120_pci_mapping(GT64120State *s)

{

    /* Update IO mapping */

    if ((s->regs[GT_PCI0IOLD] & 0x7f) <= s->regs[GT_PCI0IOHD])

    {

      /* Unmap old IO address */

      if (s->PCI0IO_length)

      {

          memory_region_del_subregion(get_system_memory(), &s->PCI0IO_mem);

          memory_region_destroy(&s->PCI0IO_mem);

      }

      /* Map new IO address */

      s->PCI0IO_start = s->regs[GT_PCI0IOLD] << 21;

      s->PCI0IO_length = ((s->regs[GT_PCI0IOHD] + 1) - (s->regs[GT_PCI0IOLD] & 0x7f)) << 21;

      isa_mem_base = s->PCI0IO_start;

      isa_mmio_init(s->PCI0IO_start, s->PCI0IO_length);

    }

}

static void *qemu_dummy_cpu_thread_fn(void *arg)

{

#ifdef _WIN32

    fprintf(stderr, "qtest is not supported under Windows\n");

    exit(1);

#else

    CPUState *cpu = arg;

    sigset_t waitset;

    int r;



    rcu_register_thread();



    qemu_mutex_lock_iothread();

    qemu_thread_get_self(cpu->thread);

    cpu->thread_id = qemu_get_thread_id();

    cpu->can_do_io = 1;



    sigemptyset(&waitset);

    sigaddset(&waitset, SIG_IPI);



    /* signal CPU creation */

    cpu->created = true;

    qemu_cond_signal(&qemu_cpu_cond);



    current_cpu = cpu;

    while (1) {

        current_cpu = NULL;

        qemu_mutex_unlock_iothread();

        do {

            int sig;

            r = sigwait(&waitset, &sig);

        } while (r == -1 && (errno == EAGAIN || errno == EINTR));

        if (r == -1) {

            perror("sigwait");

            exit(1);

        }

        qemu_mutex_lock_iothread();

        current_cpu = cpu;

        qemu_wait_io_event_common(cpu);

    }



    return NULL;

#endif

}

void target_disas(FILE *out, CPUState *cpu, target_ulong code,

                  target_ulong size, int flags)

{

    CPUClass *cc = CPU_GET_CLASS(cpu);

    target_ulong pc;

    int count;

    CPUDebug s;



    INIT_DISASSEMBLE_INFO(s.info, out, fprintf);



    s.cpu = cpu;

    s.info.read_memory_func = target_read_memory;

    s.info.read_memory_inner_func = NULL;

    s.info.buffer_vma = code;

    s.info.buffer_length = size;

    s.info.print_address_func = generic_print_address;



#ifdef TARGET_WORDS_BIGENDIAN

    s.info.endian = BFD_ENDIAN_BIG;

#else

    s.info.endian = BFD_ENDIAN_LITTLE;

#endif



    if (cc->disas_set_info) {

        cc->disas_set_info(cpu, &s.info);

    }



#if defined(TARGET_I386)

    if (flags == 2) {

        s.info.mach = bfd_mach_x86_64;

    } else if (flags == 1) {

        s.info.mach = bfd_mach_i386_i8086;

    } else {

        s.info.mach = bfd_mach_i386_i386;

    }

    s.info.print_insn = print_insn_i386;

#elif defined(TARGET_PPC)

    if ((flags >> 16) & 1) {

        s.info.endian = BFD_ENDIAN_LITTLE;

    }

    if (flags & 0xFFFF) {

        /* If we have a precise definition of the instruction set, use it. */

        s.info.mach = flags & 0xFFFF;

    } else {

#ifdef TARGET_PPC64

        s.info.mach = bfd_mach_ppc64;

#else

        s.info.mach = bfd_mach_ppc;

#endif

    }

    s.info.disassembler_options = (char *)"any";

    s.info.print_insn = print_insn_ppc;

#endif

    if (s.info.print_insn == NULL) {

        s.info.print_insn = print_insn_od_target;

    }



    for (pc = code; size > 0; pc += count, size -= count) {

	fprintf(out, "0x" TARGET_FMT_lx ":  ", pc);

	count = s.info.print_insn(pc, &s.info);

#if 0

        {

            int i;

            uint8_t b;

            fprintf(out, " {");

            for(i = 0; i < count; i++) {

                target_read_memory(pc + i, &b, 1, &s.info);

                fprintf(out, " %02x", b);

            }

            fprintf(out, " }");

        }

#endif

	fprintf(out, "\n");

	if (count < 0)

	    break;

        if (size < count) {

            fprintf(out,

                    "Disassembler disagrees with translator over instruction "

                    "decoding\n"

                    "Please report this to qemu-devel@nongnu.org\n");

            break;

        }

    }

}

static void coroutine_fn v9fs_fix_fid_paths(V9fsPDU *pdu, V9fsPath *olddir,

                                            V9fsString *old_name,

                                            V9fsPath *newdir,

                                            V9fsString *new_name)

{

    V9fsFidState *tfidp;

    V9fsPath oldpath, newpath;

    V9fsState *s = pdu->s;





    v9fs_path_init(&oldpath);

    v9fs_path_init(&newpath);

    v9fs_co_name_to_path(pdu, olddir, old_name->data, &oldpath);

    v9fs_co_name_to_path(pdu, newdir, new_name->data, &newpath);



    /*

     * Fixup fid's pointing to the old name to

     * start pointing to the new name

     */

    for (tfidp = s->fid_list; tfidp; tfidp = tfidp->next) {

        if (v9fs_path_is_ancestor(&oldpath, &tfidp->path)) {

            /* replace the name */

            v9fs_fix_path(&tfidp->path, &newpath, strlen(oldpath.data));

        }

    }

    v9fs_path_free(&oldpath);

    v9fs_path_free(&newpath);

}

