                    break;

                case NEON_2RM_AESE: case NEON_2RM_AESMC:

                    if (!arm_dc_feature(s, ARM_FEATURE_V8_AES)

                        || ((rm | rd) & 1)) {

                        return 1;

                    }

                    tmp = tcg_const_i32(rd);

                    tmp2 = tcg_const_i32(rm);



                     /* Bit 6 is the lowest opcode bit; it distinguishes between

                      * encryption (AESE/AESMC) and decryption (AESD/AESIMC)

                      */

                    tmp3 = tcg_const_i32(extract32(insn, 6, 1));



                    if (op == NEON_2RM_AESE) {

                        gen_helper_crypto_aese(cpu_env, tmp, tmp2, tmp3);

                    } else {

                        gen_helper_crypto_aesmc(cpu_env, tmp, tmp2, tmp3);

                    }

                    tcg_temp_free_i32(tmp);

                    tcg_temp_free_i32(tmp2);

                    tcg_temp_free_i32(tmp3);

                    break;

                case NEON_2RM_SHA1H:

                    if (!arm_dc_feature(s, ARM_FEATURE_V8_SHA1)

                        || ((rm | rd) & 1)) {

                        return 1;

                    }

                    tmp = tcg_const_i32(rd);

                    tmp2 = tcg_const_i32(rm);



                    gen_helper_crypto_sha1h(cpu_env, tmp, tmp2);



                    tcg_temp_free_i32(tmp);

                    tcg_temp_free_i32(tmp2);

                    break;

                case NEON_2RM_SHA1SU1:

                    if ((rm | rd) & 1) {

                            return 1;

                    }

                    /* bit 6 (q): set -> SHA256SU0, cleared -> SHA1SU1 */

                    if (q) {

                        if (!arm_dc_feature(s, ARM_FEATURE_V8_SHA256)) {

                            return 1;

                        }

                    } else if (!arm_dc_feature(s, ARM_FEATURE_V8_SHA1)) {

                        return 1;

                    }

                    tmp = tcg_const_i32(rd);

                    tmp2 = tcg_const_i32(rm);

                    if (q) {

                        gen_helper_crypto_sha256su0(cpu_env, tmp, tmp2);

                    } else {

                        gen_helper_crypto_sha1su1(cpu_env, tmp, tmp2);

                    }

                    tcg_temp_free_i32(tmp);

                    tcg_temp_free_i32(tmp2);

                    break;

                default:

                elementwise:

                    for (pass = 0; pass < (q ? 4 : 2); pass++) {

                        if (neon_2rm_is_float_op(op)) {

                            tcg_gen_ld_f32(cpu_F0s, cpu_env,

                                           neon_reg_offset(rm, pass));

                            TCGV_UNUSED_I32(tmp);

                        } else {

                            tmp = neon_load_reg(rm, pass);

                        }

                        switch (op) {

                        case NEON_2RM_VREV32:

                            switch (size) {

                            case 0: tcg_gen_bswap32_i32(tmp, tmp); break;

                            case 1: gen_swap_half(tmp); break;

                            default: abort();

                            }

                            break;

                        case NEON_2RM_VREV16:

                            gen_rev16(tmp);

                            break;

                        case NEON_2RM_VCLS:

                            switch (size) {

                            case 0: gen_helper_neon_cls_s8(tmp, tmp); break;

                            case 1: gen_helper_neon_cls_s16(tmp, tmp); break;

                            case 2: gen_helper_neon_cls_s32(tmp, tmp); break;

                            default: abort();

                            }

                            break;

                        case NEON_2RM_VCLZ:

                            switch (size) {

                            case 0: gen_helper_neon_clz_u8(tmp, tmp); break;

                            case 1: gen_helper_neon_clz_u16(tmp, tmp); break;

                            case 2: gen_helper_clz(tmp, tmp); break;

                            default: abort();

                            }

                            break;

                        case NEON_2RM_VCNT:

                            gen_helper_neon_cnt_u8(tmp, tmp);

                            break;

                        case NEON_2RM_VMVN:

                            tcg_gen_not_i32(tmp, tmp);

                            break;

                        case NEON_2RM_VQABS:

                            switch (size) {

                            case 0:

                                gen_helper_neon_qabs_s8(tmp, cpu_env, tmp);

                                break;

                            case 1:

                                gen_helper_neon_qabs_s16(tmp, cpu_env, tmp);

                                break;

                            case 2:

                                gen_helper_neon_qabs_s32(tmp, cpu_env, tmp);

                                break;

                            default: abort();

                            }

                            break;

                        case NEON_2RM_VQNEG:

                            switch (size) {

                            case 0:

                                gen_helper_neon_qneg_s8(tmp, cpu_env, tmp);

                                break;

                            case 1:

                                gen_helper_neon_qneg_s16(tmp, cpu_env, tmp);

                                break;

                            case 2:

                                gen_helper_neon_qneg_s32(tmp, cpu_env, tmp);

                                break;

                            default: abort();

                            }

                            break;

                        case NEON_2RM_VCGT0: case NEON_2RM_VCLE0:

                            tmp2 = tcg_const_i32(0);

                            switch(size) {

                            case 0: gen_helper_neon_cgt_s8(tmp, tmp, tmp2); break;

                            case 1: gen_helper_neon_cgt_s16(tmp, tmp, tmp2); break;

                            case 2: gen_helper_neon_cgt_s32(tmp, tmp, tmp2); break;

                            default: abort();

                            }

                            tcg_temp_free_i32(tmp2);

                            if (op == NEON_2RM_VCLE0) {

                                tcg_gen_not_i32(tmp, tmp);

                            }

                            break;

                        case NEON_2RM_VCGE0: case NEON_2RM_VCLT0:

                            tmp2 = tcg_const_i32(0);

                            switch(size) {

                            case 0: gen_helper_neon_cge_s8(tmp, tmp, tmp2); break;

                            case 1: gen_helper_neon_cge_s16(tmp, tmp, tmp2); break;

                            case 2: gen_helper_neon_cge_s32(tmp, tmp, tmp2); break;

                            default: abort();

                            }

                            tcg_temp_free_i32(tmp2);

                            if (op == NEON_2RM_VCLT0) {

                                tcg_gen_not_i32(tmp, tmp);

                            }

                            break;

                        case NEON_2RM_VCEQ0:

                            tmp2 = tcg_const_i32(0);

                            switch(size) {

                            case 0: gen_helper_neon_ceq_u8(tmp, tmp, tmp2); break;

                            case 1: gen_helper_neon_ceq_u16(tmp, tmp, tmp2); break;

                            case 2: gen_helper_neon_ceq_u32(tmp, tmp, tmp2); break;

                            default: abort();

                            }

                            tcg_temp_free_i32(tmp2);

                            break;

                        case NEON_2RM_VABS:

                            switch(size) {

                            case 0: gen_helper_neon_abs_s8(tmp, tmp); break;

                            case 1: gen_helper_neon_abs_s16(tmp, tmp); break;

                            case 2: tcg_gen_abs_i32(tmp, tmp); break;

                            default: abort();

                            }

                            break;

                        case NEON_2RM_VNEG:

                            tmp2 = tcg_const_i32(0);

                            gen_neon_rsb(size, tmp, tmp2);

                            tcg_temp_free_i32(tmp2);

                            break;

                        case NEON_2RM_VCGT0_F:

                        {

                            TCGv_ptr fpstatus = get_fpstatus_ptr(1);

                            tmp2 = tcg_const_i32(0);

                            gen_helper_neon_cgt_f32(tmp, tmp, tmp2, fpstatus);

                            tcg_temp_free_i32(tmp2);

                            tcg_temp_free_ptr(fpstatus);

                            break;

                        }

                        case NEON_2RM_VCGE0_F:

                        {

                            TCGv_ptr fpstatus = get_fpstatus_ptr(1);

                            tmp2 = tcg_const_i32(0);

                            gen_helper_neon_cge_f32(tmp, tmp, tmp2, fpstatus);

                            tcg_temp_free_i32(tmp2);

                            tcg_temp_free_ptr(fpstatus);

                            break;

                        }

                        case NEON_2RM_VCEQ0_F:

                        {

                            TCGv_ptr fpstatus = get_fpstatus_ptr(1);

                            tmp2 = tcg_const_i32(0);

                            gen_helper_neon_ceq_f32(tmp, tmp, tmp2, fpstatus);

                            tcg_temp_free_i32(tmp2);

                            tcg_temp_free_ptr(fpstatus);

                            break;

                        }

                        case NEON_2RM_VCLE0_F:

                        {

                            TCGv_ptr fpstatus = get_fpstatus_ptr(1);

                            tmp2 = tcg_const_i32(0);

                            gen_helper_neon_cge_f32(tmp, tmp2, tmp, fpstatus);

                            tcg_temp_free_i32(tmp2);

                            tcg_temp_free_ptr(fpstatus);

                            break;

                        }

                        case NEON_2RM_VCLT0_F:

                        {

                            TCGv_ptr fpstatus = get_fpstatus_ptr(1);

                            tmp2 = tcg_const_i32(0);

                            gen_helper_neon_cgt_f32(tmp, tmp2, tmp, fpstatus);

                            tcg_temp_free_i32(tmp2);

                            tcg_temp_free_ptr(fpstatus);

                            break;

                        }

                        case NEON_2RM_VABS_F:

                            gen_vfp_abs(0);

                            break;

                        case NEON_2RM_VNEG_F:

                            gen_vfp_neg(0);

                            break;

                        case NEON_2RM_VSWP:

                            tmp2 = neon_load_reg(rd, pass);

                            neon_store_reg(rm, pass, tmp2);

                            break;

                        case NEON_2RM_VTRN:

                            tmp2 = neon_load_reg(rd, pass);

                            switch (size) {

                            case 0: gen_neon_trn_u8(tmp, tmp2); break;

                            case 1: gen_neon_trn_u16(tmp, tmp2); break;

                            default: abort();

                            }

                            neon_store_reg(rm, pass, tmp2);

                            break;

                        case NEON_2RM_VRINTN:

                        case NEON_2RM_VRINTA:

                        case NEON_2RM_VRINTM:

                        case NEON_2RM_VRINTP:

                        case NEON_2RM_VRINTZ:

                        {

                            TCGv_i32 tcg_rmode;

                            TCGv_ptr fpstatus = get_fpstatus_ptr(1);

                            int rmode;



                            if (op == NEON_2RM_VRINTZ) {

                                rmode = FPROUNDING_ZERO;

                            } else {

                                rmode = fp_decode_rm[((op & 0x6) >> 1) ^ 1];

                            }



                            tcg_rmode = tcg_const_i32(arm_rmode_to_sf(rmode));

                            gen_helper_set_neon_rmode(tcg_rmode, tcg_rmode,

                                                      cpu_env);

                            gen_helper_rints(cpu_F0s, cpu_F0s, fpstatus);

                            gen_helper_set_neon_rmode(tcg_rmode, tcg_rmode,

                                                      cpu_env);

                            tcg_temp_free_ptr(fpstatus);

                            tcg_temp_free_i32(tcg_rmode);

                            break;

                        }

                        case NEON_2RM_VRINTX:

                        {

                            TCGv_ptr fpstatus = get_fpstatus_ptr(1);

                            gen_helper_rints_exact(cpu_F0s, cpu_F0s, fpstatus);

                            tcg_temp_free_ptr(fpstatus);

                            break;

                        }

                        case NEON_2RM_VCVTAU:

                        case NEON_2RM_VCVTAS:

                        case NEON_2RM_VCVTNU:

                        case NEON_2RM_VCVTNS:

                        case NEON_2RM_VCVTPU:

                        case NEON_2RM_VCVTPS:

                        case NEON_2RM_VCVTMU:

                        case NEON_2RM_VCVTMS:

                        {

                            bool is_signed = !extract32(insn, 7, 1);

                            TCGv_ptr fpst = get_fpstatus_ptr(1);

                            TCGv_i32 tcg_rmode, tcg_shift;

                            int rmode = fp_decode_rm[extract32(insn, 8, 2)];



                            tcg_shift = tcg_const_i32(0);

                            tcg_rmode = tcg_const_i32(arm_rmode_to_sf(rmode));

                            gen_helper_set_neon_rmode(tcg_rmode, tcg_rmode,

                                                      cpu_env);



                            if (is_signed) {

                                gen_helper_vfp_tosls(cpu_F0s, cpu_F0s,

                                                     tcg_shift, fpst);

                            } else {

                                gen_helper_vfp_touls(cpu_F0s, cpu_F0s,

                                                     tcg_shift, fpst);

                            }



                            gen_helper_set_neon_rmode(tcg_rmode, tcg_rmode,

                                                      cpu_env);

                            tcg_temp_free_i32(tcg_rmode);

                            tcg_temp_free_i32(tcg_shift);

                            tcg_temp_free_ptr(fpst);

                            break;

                        }

                        case NEON_2RM_VRECPE:

                        {

                            TCGv_ptr fpstatus = get_fpstatus_ptr(1);

                            gen_helper_recpe_u32(tmp, tmp, fpstatus);

                            tcg_temp_free_ptr(fpstatus);

                            break;

                        }

                        case NEON_2RM_VRSQRTE:

                        {

                            TCGv_ptr fpstatus = get_fpstatus_ptr(1);

                            gen_helper_rsqrte_u32(tmp, tmp, fpstatus);

                            tcg_temp_free_ptr(fpstatus);

                            break;

                        }

                        case NEON_2RM_VRECPE_F:

                        {

                            TCGv_ptr fpstatus = get_fpstatus_ptr(1);

                            gen_helper_recpe_f32(cpu_F0s, cpu_F0s, fpstatus);

                            tcg_temp_free_ptr(fpstatus);

                            break;

                        }

                        case NEON_2RM_VRSQRTE_F:

                        {

                            TCGv_ptr fpstatus = get_fpstatus_ptr(1);

                            gen_helper_rsqrte_f32(cpu_F0s, cpu_F0s, fpstatus);

                            tcg_temp_free_ptr(fpstatus);

                            break;

                        }

                        case NEON_2RM_VCVT_FS: /* VCVT.F32.S32 */

                            gen_vfp_sito(0, 1);

                            break;

                        case NEON_2RM_VCVT_FU: /* VCVT.F32.U32 */

                            gen_vfp_uito(0, 1);

                            break;

                        case NEON_2RM_VCVT_SF: /* VCVT.S32.F32 */

                            gen_vfp_tosiz(0, 1);

                            break;

                        case NEON_2RM_VCVT_UF: /* VCVT.U32.F32 */

                            gen_vfp_touiz(0, 1);

                            break;

                        default:

                            /* Reserved op values were caught by the

                             * neon_2rm_sizes[] check earlier.

                             */

                            abort();

                        }

                        if (neon_2rm_is_float_op(op)) {

                            tcg_gen_st_f32(cpu_F0s, cpu_env,

                                           neon_reg_offset(rd, pass));

                        } else {

                            neon_store_reg(rd, pass, tmp);

                        }

                    }

                    break;

                }

            } else if ((insn & (1 << 10)) == 0) {

                /* VTBL, VTBX.  */

                int n = ((insn >> 8) & 3) + 1;

                if ((rn + n) > 32) {

                    /* This is UNPREDICTABLE; we choose to UNDEF to avoid the

                     * helper function running off the end of the register file.

                     */

                    return 1;

                }

                n <<= 3;

                if (insn & (1 << 6)) {

                    tmp = neon_load_reg(rd, 0);

                } else {

                    tmp = tcg_temp_new_i32();

                    tcg_gen_movi_i32(tmp, 0);

                }

                tmp2 = neon_load_reg(rm, 0);

                tmp4 = tcg_const_i32(rn);

                tmp5 = tcg_const_i32(n);

                gen_helper_neon_tbl(tmp2, cpu_env, tmp2, tmp, tmp4, tmp5);

                tcg_temp_free_i32(tmp);

                if (insn & (1 << 6)) {

                    tmp = neon_load_reg(rd, 1);

                } else {

                    tmp = tcg_temp_new_i32();

                    tcg_gen_movi_i32(tmp, 0);

                }

                tmp3 = neon_load_reg(rm, 1);

                gen_helper_neon_tbl(tmp3, cpu_env, tmp3, tmp, tmp4, tmp5);

                tcg_temp_free_i32(tmp5);

                tcg_temp_free_i32(tmp4);

                neon_store_reg(rd, 0, tmp2);

                neon_store_reg(rd, 1, tmp3);

                tcg_temp_free_i32(tmp);

            } else if ((insn & 0x380) == 0) {

                /* VDUP */

                if ((insn & (7 << 16)) == 0 || (q && (rd & 1))) {

                    return 1;

                }

                if (insn & (1 << 19)) {

                    tmp = neon_load_reg(rm, 1);

                } else {

                    tmp = neon_load_reg(rm, 0);

                }

                if (insn & (1 << 16)) {

                    gen_neon_dup_u8(tmp, ((insn >> 17) & 3) * 8);

                } else if (insn & (1 << 17)) {

                    if ((insn >> 18) & 1)

                        gen_neon_dup_high16(tmp);

                    else

                        gen_neon_dup_low16(tmp);

                }

                for (pass = 0; pass < (q ? 4 : 2); pass++) {

                    tmp2 = tcg_temp_new_i32();

                    tcg_gen_mov_i32(tmp2, tmp);

                    neon_store_reg(rd, pass, tmp2);

                }

                tcg_temp_free_i32(tmp);

            } else {

                return 1;

            }

        }

    }

    return 0;

}

static void rtas_int_on(sPAPREnvironment *spapr, uint32_t token,

                        uint32_t nargs, target_ulong args,

                        uint32_t nret, target_ulong rets)

{

    struct ics_state *ics = spapr->icp->ics;

    uint32_t nr;



    if ((nargs != 1) || (nret != 1)) {

        rtas_st(rets, 0, -3);

        return;

    }



    nr = rtas_ld(args, 0);



    if (!ics_valid_irq(ics, nr)) {

        rtas_st(rets, 0, -3);

        return;

    }



    ics_write_xive(ics, nr, ics->irqs[nr - ics->offset].server,

                   ics->irqs[nr - ics->offset].saved_priority,

                   ics->irqs[nr - ics->offset].saved_priority);



    rtas_st(rets, 0, 0); /* Success */

}

static void do_info(Monitor *mon, const QDict *qdict, QObject **ret_data)

{

    const mon_cmd_t *cmd;

    const char *item = qdict_get_try_str(qdict, "item");



    if (!item)

        goto help;



    for (cmd = info_cmds; cmd->name != NULL; cmd++) {

        if (compare_cmd(item, cmd->name))

            break;

    }



    if (cmd->name == NULL)

        goto help;



    if (monitor_handler_ported(cmd)) {

        cmd->mhandler.info_new(mon, ret_data);

        if (*ret_data)

            cmd->user_print(mon, *ret_data);

    } else {

        cmd->mhandler.info(mon);

    }



    return;



help:

    help_cmd(mon, "info");

}

static int ehci_state_fetchsitd(EHCIState *ehci, int async)

{

    uint32_t entry;

    EHCIsitd sitd;



    assert(!async);

    entry = ehci_get_fetch_addr(ehci, async);



    get_dwords(NLPTR_GET(entry), (uint32_t *)&sitd,

               sizeof(EHCIsitd) >> 2);

    ehci_trace_sitd(ehci, entry, &sitd);



    if (!(sitd.results & SITD_RESULTS_ACTIVE)) {

        /* siTD is not active, nothing to do */;

    } else {

        /* TODO: split transfers are not implemented */

        fprintf(stderr, "WARNING: Skipping active siTD\n");

    }



    ehci_set_fetch_addr(ehci, async, sitd.next);

    ehci_set_state(ehci, async, EST_FETCHENTRY);

    return 1;

}

static void test_cdrom_dma(void)

{

    static const size_t len = ATAPI_BLOCK_SIZE;

    char *pattern = g_malloc(ATAPI_BLOCK_SIZE * 16);

    char *rx = g_malloc0(len);

    uintptr_t guest_buf;

    PrdtEntry prdt[1];

    FILE *fh;



    ide_test_start("-drive if=none,file=%s,media=cdrom,format=raw,id=sr0,index=0 "

                   "-device ide-cd,drive=sr0,bus=ide.0", tmp_path);

    qtest_irq_intercept_in(global_qtest, "ioapic");



    guest_buf = guest_alloc(guest_malloc, len);

    prdt[0].addr = cpu_to_le32(guest_buf);

    prdt[0].size = cpu_to_le32(len | PRDT_EOT);



    generate_pattern(pattern, ATAPI_BLOCK_SIZE * 16, ATAPI_BLOCK_SIZE);

    fh = fopen(tmp_path, "w+");

    fwrite(pattern, ATAPI_BLOCK_SIZE, 16, fh);

    fclose(fh);



    send_dma_request(CMD_PACKET, 0, 1, prdt, 1, send_scsi_cdb_read10);



    /* Read back data from guest memory into local qtest memory */

    memread(guest_buf, rx, len);

    g_assert_cmpint(memcmp(pattern, rx, len), ==, 0);



    g_free(pattern);

    g_free(rx);

    test_bmdma_teardown();

}

static void test_abstract_interfaces(void)

{

    QList *all_types;

    QList *obj_types;

    QListEntry *ae;



    qtest_start(common_args);

    /* qom-list-types implements=interface would return any type

     * that implements _any_ interface (not just interface types),

     * so use a trick to find the interface type names:

     * - list all object types

     * - list all types, and look for items that are not

     *   on the first list

     */

    all_types = qom_list_types(NULL, false);

    obj_types = qom_list_types("object", false);



    QLIST_FOREACH_ENTRY(all_types, ae) {

        QDict *at = qobject_to_qdict(qlist_entry_obj(ae));

        const char *aname = qdict_get_str(at, "name");

        QListEntry *oe;

        const char *found = NULL;



        QLIST_FOREACH_ENTRY(obj_types, oe) {

            QDict *ot = qobject_to_qdict(qlist_entry_obj(oe));

            const char *oname = qdict_get_str(ot, "name");

            if (!strcmp(aname, oname)) {

                found = oname;

                break;

            }

        }



        /* Using g_assert_cmpstr() will give more useful failure

         * messages than g_assert(found) */

        g_assert_cmpstr(aname, ==, found);

    }



    QDECREF(all_types);

    QDECREF(obj_types);

    qtest_end();

}

static void mips_fulong2e_init(ram_addr_t ram_size, const char *boot_device,

                        const char *kernel_filename, const char *kernel_cmdline,

                        const char *initrd_filename, const char *cpu_model)

{

    char *filename;

    unsigned long ram_offset, bios_offset;

    long bios_size;

    int64_t kernel_entry;

    qemu_irq *i8259;

    qemu_irq *cpu_exit_irq;

    int via_devfn;

    PCIBus *pci_bus;

    uint8_t *eeprom_buf;

    i2c_bus *smbus;

    int i;

    DriveInfo *hd[MAX_IDE_BUS * MAX_IDE_DEVS];

    DeviceState *eeprom;

    CPUState *env;



    /* init CPUs */

    if (cpu_model == NULL) {

        cpu_model = "Loongson-2E";

    }

    env = cpu_init(cpu_model);

    if (!env) {

        fprintf(stderr, "Unable to find CPU definition\n");

        exit(1);

    }



    register_savevm(NULL, "cpu", 0, 3, cpu_save, cpu_load, env);

    qemu_register_reset(main_cpu_reset, env);



    /* fulong 2e has 256M ram. */

    ram_size = 256 * 1024 * 1024;



    /* fulong 2e has a 1M flash.Winbond W39L040AP70Z */

    bios_size = 1024 * 1024;



    /* allocate RAM */

    ram_offset = qemu_ram_alloc(NULL, "fulong2e.ram", ram_size);

    bios_offset = qemu_ram_alloc(NULL, "fulong2e.bios", bios_size);



    cpu_register_physical_memory(0, ram_size, ram_offset);

    cpu_register_physical_memory(0x1fc00000LL,

					   bios_size, bios_offset | IO_MEM_ROM);



    /* We do not support flash operation, just loading pmon.bin as raw BIOS.

     * Please use -L to set the BIOS path and -bios to set bios name. */



    if (kernel_filename) {

        loaderparams.ram_size = ram_size;

        loaderparams.kernel_filename = kernel_filename;

        loaderparams.kernel_cmdline = kernel_cmdline;

        loaderparams.initrd_filename = initrd_filename;

        kernel_entry = load_kernel (env);

        write_bootloader(env, qemu_get_ram_ptr(bios_offset), kernel_entry);

    } else {

        if (bios_name == NULL) {

                bios_name = FULONG_BIOSNAME;

        }

        filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);

        if (filename) {

            bios_size = load_image_targphys(filename, 0x1fc00000LL,

                                            BIOS_SIZE);

            qemu_free(filename);

        } else {

            bios_size = -1;

        }



        if ((bios_size < 0 || bios_size > BIOS_SIZE) && !kernel_filename) {

            fprintf(stderr, "qemu: Could not load MIPS bios '%s'\n", bios_name);

            exit(1);

        }

    }



    /* Init internal devices */

    cpu_mips_irq_init_cpu(env);

    cpu_mips_clock_init(env);



    /* Interrupt controller */

    /* The 8259 -> IP5  */

    i8259 = i8259_init(env->irq[5]);



    /* North bridge, Bonito --> IP2 */

    pci_bus = bonito_init((qemu_irq *)&(env->irq[2]));



    /* South bridge */

    if (drive_get_max_bus(IF_IDE) >= MAX_IDE_BUS) {

        fprintf(stderr, "qemu: too many IDE bus\n");

        exit(1);

    }



    for(i = 0; i < MAX_IDE_BUS * MAX_IDE_DEVS; i++) {

        hd[i] = drive_get(IF_IDE, i / MAX_IDE_DEVS, i % MAX_IDE_DEVS);

    }



    via_devfn = vt82c686b_init(pci_bus, PCI_DEVFN(FULONG2E_VIA_SLOT, 0));

    if (via_devfn < 0) {

        fprintf(stderr, "vt82c686b_init error \n");

        exit(1);

    }



    isa_bus_irqs(i8259);

    vt82c686b_ide_init(pci_bus, hd, PCI_DEVFN(FULONG2E_VIA_SLOT, 1));

    usb_uhci_vt82c686b_init(pci_bus, PCI_DEVFN(FULONG2E_VIA_SLOT, 2));

    usb_uhci_vt82c686b_init(pci_bus, PCI_DEVFN(FULONG2E_VIA_SLOT, 3));



    smbus = vt82c686b_pm_init(pci_bus, PCI_DEVFN(FULONG2E_VIA_SLOT, 4),

                              0xeee1, NULL);

    eeprom_buf = qemu_mallocz(8 * 256); /* XXX: make this persistent */

    memcpy(eeprom_buf, eeprom_spd, sizeof(eeprom_spd));

    /* TODO: Populate SPD eeprom data.  */

    eeprom = qdev_create((BusState *)smbus, "smbus-eeprom");

    qdev_prop_set_uint8(eeprom, "address", 0x50);

    qdev_prop_set_ptr(eeprom, "data", eeprom_buf);

    qdev_init_nofail(eeprom);



    /* init other devices */

    pit = pit_init(0x40, isa_reserve_irq(0));

    cpu_exit_irq = qemu_allocate_irqs(cpu_request_exit, NULL, 1);

    DMA_init(0, cpu_exit_irq);



    /* Super I/O */

    isa_create_simple("i8042");



    rtc_init(2000, NULL);



    for(i = 0; i < MAX_SERIAL_PORTS; i++) {

        if (serial_hds[i]) {

            serial_isa_init(i, serial_hds[i]);

        }

    }



    if (parallel_hds[0]) {

        parallel_init(0, parallel_hds[0]);

    }



    /* Sound card */

    audio_init(pci_bus);

    /* Network card */

    network_init();

}

static ssize_t nic_receive(NetClientState *nc, const uint8_t * buf, size_t size)

{

    /* TODO:

     * - Magic packets should set bit 30 in power management driver register.

     * - Interesting packets should set bit 29 in power management driver register.

     */

    EEPRO100State *s = DO_UPCAST(NICState, nc, nc)->opaque;

    uint16_t rfd_status = 0xa000;

#if defined(CONFIG_PAD_RECEIVED_FRAMES)

    uint8_t min_buf[60];

#endif

    static const uint8_t broadcast_macaddr[6] =

        { 0xff, 0xff, 0xff, 0xff, 0xff, 0xff };



#if defined(CONFIG_PAD_RECEIVED_FRAMES)

    /* Pad to minimum Ethernet frame length */

    if (size < sizeof(min_buf)) {

        memcpy(min_buf, buf, size);

        memset(&min_buf[size], 0, sizeof(min_buf) - size);

        buf = min_buf;

        size = sizeof(min_buf);

    }

#endif



    if (s->configuration[8] & 0x80) {

        /* CSMA is disabled. */

        logout("%p received while CSMA is disabled\n", s);

        return -1;

#if !defined(CONFIG_PAD_RECEIVED_FRAMES)

    } else if (size < 64 && (s->configuration[7] & BIT(0))) {

        /* Short frame and configuration byte 7/0 (discard short receive) set:

         * Short frame is discarded */

        logout("%p received short frame (%zu byte)\n", s, size);

        s->statistics.rx_short_frame_errors++;

        return -1;

#endif

    } else if ((size > MAX_ETH_FRAME_SIZE + 4) && !(s->configuration[18] & BIT(3))) {

        /* Long frame and configuration byte 18/3 (long receive ok) not set:

         * Long frames are discarded. */

        logout("%p received long frame (%zu byte), ignored\n", s, size);

        return -1;

    } else if (memcmp(buf, s->conf.macaddr.a, 6) == 0) {       /* !!! */

        /* Frame matches individual address. */

        /* TODO: check configuration byte 15/4 (ignore U/L). */

        TRACE(RXTX, logout("%p received frame for me, len=%zu\n", s, size));

    } else if (memcmp(buf, broadcast_macaddr, 6) == 0) {

        /* Broadcast frame. */

        TRACE(RXTX, logout("%p received broadcast, len=%zu\n", s, size));

        rfd_status |= 0x0002;

    } else if (buf[0] & 0x01) {

        /* Multicast frame. */

        TRACE(RXTX, logout("%p received multicast, len=%zu,%s\n", s, size, nic_dump(buf, size)));

        if (s->configuration[21] & BIT(3)) {

          /* Multicast all bit is set, receive all multicast frames. */

        } else {

          unsigned mcast_idx = e100_compute_mcast_idx(buf);

          assert(mcast_idx < 64);

          if (s->mult[mcast_idx >> 3] & (1 << (mcast_idx & 7))) {

            /* Multicast frame is allowed in hash table. */

          } else if (s->configuration[15] & BIT(0)) {

              /* Promiscuous: receive all. */

              rfd_status |= 0x0004;

          } else {

              TRACE(RXTX, logout("%p multicast ignored\n", s));

              return -1;

          }

        }

        /* TODO: Next not for promiscuous mode? */

        rfd_status |= 0x0002;

    } else if (s->configuration[15] & BIT(0)) {

        /* Promiscuous: receive all. */

        TRACE(RXTX, logout("%p received frame in promiscuous mode, len=%zu\n", s, size));

        rfd_status |= 0x0004;

    } else if (s->configuration[20] & BIT(6)) {

        /* Multiple IA bit set. */

        unsigned mcast_idx = compute_mcast_idx(buf);

        assert(mcast_idx < 64);

        if (s->mult[mcast_idx >> 3] & (1 << (mcast_idx & 7))) {

            TRACE(RXTX, logout("%p accepted, multiple IA bit set\n", s));

        } else {

            TRACE(RXTX, logout("%p frame ignored, multiple IA bit set\n", s));

            return -1;

        }

    } else {

        TRACE(RXTX, logout("%p received frame, ignored, len=%zu,%s\n", s, size,

              nic_dump(buf, size)));

        return size;

    }



    if (get_ru_state(s) != ru_ready) {

        /* No resources available. */

        logout("no resources, state=%u\n", get_ru_state(s));

        /* TODO: RNR interrupt only at first failed frame? */

        eepro100_rnr_interrupt(s);

        s->statistics.rx_resource_errors++;

#if 0

        assert(!"no resources");

#endif

        return -1;

    }

    /* !!! */

    eepro100_rx_t rx;

    pci_dma_read(&s->dev, s->ru_base + s->ru_offset,

                 &rx, sizeof(eepro100_rx_t));

    uint16_t rfd_command = le16_to_cpu(rx.command);

    uint16_t rfd_size = le16_to_cpu(rx.size);



    if (size > rfd_size) {

        logout("Receive buffer (%" PRId16 " bytes) too small for data "

            "(%zu bytes); data truncated\n", rfd_size, size);

        size = rfd_size;

    }

#if !defined(CONFIG_PAD_RECEIVED_FRAMES)

    if (size < 64) {

        rfd_status |= 0x0080;

    }

#endif

    TRACE(OTHER, logout("command 0x%04x, link 0x%08x, addr 0x%08x, size %u\n",

          rfd_command, rx.link, rx.rx_buf_addr, rfd_size));

    stw_le_pci_dma(&s->dev, s->ru_base + s->ru_offset +

                offsetof(eepro100_rx_t, status), rfd_status);

    stw_le_pci_dma(&s->dev, s->ru_base + s->ru_offset +

                offsetof(eepro100_rx_t, count), size);

    /* Early receive interrupt not supported. */

#if 0

    eepro100_er_interrupt(s);

#endif

    /* Receive CRC Transfer not supported. */

    if (s->configuration[18] & BIT(2)) {

        missing("Receive CRC Transfer");

        return -1;

    }

    /* TODO: check stripping enable bit. */

#if 0

    assert(!(s->configuration[17] & BIT(0)));

#endif

    pci_dma_write(&s->dev, s->ru_base + s->ru_offset +

                  sizeof(eepro100_rx_t), buf, size);

    s->statistics.rx_good_frames++;

    eepro100_fr_interrupt(s);

    s->ru_offset = le32_to_cpu(rx.link);

    if (rfd_command & COMMAND_EL) {

        /* EL bit is set, so this was the last frame. */

        logout("receive: Running out of frames\n");

        set_ru_state(s, ru_suspended);

    }

    if (rfd_command & COMMAND_S) {

        /* S bit is set. */

        set_ru_state(s, ru_suspended);

    }

    return size;

}

