static void usb_ohci_init(OHCIState *ohci, DeviceState *dev,

                          int num_ports, int devfn,

                          qemu_irq irq, enum ohci_type type,

                          const char *name, uint32_t localmem_base)

{

    int i;



    if (usb_frame_time == 0) {

#ifdef OHCI_TIME_WARP

        usb_frame_time = get_ticks_per_sec();

        usb_bit_time = muldiv64(1, get_ticks_per_sec(), USB_HZ/1000);

#else

        usb_frame_time = muldiv64(1, get_ticks_per_sec(), 1000);

        if (get_ticks_per_sec() >= USB_HZ) {

            usb_bit_time = muldiv64(1, get_ticks_per_sec(), USB_HZ);

        } else {

            usb_bit_time = 1;

        }

#endif

        dprintf("usb-ohci: usb_bit_time=%" PRId64 " usb_frame_time=%" PRId64 "\n",

                usb_frame_time, usb_bit_time);

    }



    ohci->mem = cpu_register_io_memory(ohci_readfn, ohci_writefn, ohci);

    ohci->localmem_base = localmem_base;

    ohci->name = name;



    ohci->irq = irq;

    ohci->type = type;



    usb_bus_new(&ohci->bus, dev);

    ohci->num_ports = num_ports;

    for (i = 0; i < num_ports; i++) {

        usb_register_port(&ohci->bus, &ohci->rhport[i].port, ohci, i, ohci_attach);

    }



    ohci->async_td = 0;

    qemu_register_reset(ohci_reset, ohci);

    ohci_reset(ohci);

}

void helper_float_check_status (void)

{

#ifdef CONFIG_SOFTFLOAT

    if (env->exception_index == POWERPC_EXCP_PROGRAM &&

        (env->error_code & POWERPC_EXCP_FP)) {

        /* Differred floating-point exception after target FPR update */

        if (msr_fe0 != 0 || msr_fe1 != 0)

            helper_raise_exception_err(env->exception_index, env->error_code);

    } else {

        int status = get_float_exception_flags(&env->fp_status);

        if (status & float_flag_overflow) {

            float_overflow_excp();

        } else if (status & float_flag_underflow) {

            float_underflow_excp();

        } else if (status & float_flag_inexact) {

            float_inexact_excp();

        }

    }

#else

    if (env->exception_index == POWERPC_EXCP_PROGRAM &&

        (env->error_code & POWERPC_EXCP_FP)) {

        /* Differred floating-point exception after target FPR update */

        if (msr_fe0 != 0 || msr_fe1 != 0)

            helper_raise_exception_err(env->exception_index, env->error_code);

    }

#endif

}

static void spapr_dt_rtas(sPAPRMachineState *spapr, void *fdt)

{

    int rtas;

    GString *hypertas = g_string_sized_new(256);

    GString *qemu_hypertas = g_string_sized_new(256);

    uint32_t refpoints[] = { cpu_to_be32(0x4), cpu_to_be32(0x4) };

    uint64_t max_hotplug_addr = spapr->hotplug_memory.base +

        memory_region_size(&spapr->hotplug_memory.mr);

    uint32_t lrdr_capacity[] = {

        cpu_to_be32(max_hotplug_addr >> 32),

        cpu_to_be32(max_hotplug_addr & 0xffffffff),

        0, cpu_to_be32(SPAPR_MEMORY_BLOCK_SIZE),

        cpu_to_be32(max_cpus / smp_threads),

    };



    _FDT(rtas = fdt_add_subnode(fdt, 0, "rtas"));



    /* hypertas */

    add_str(hypertas, "hcall-pft");

    add_str(hypertas, "hcall-term");

    add_str(hypertas, "hcall-dabr");

    add_str(hypertas, "hcall-interrupt");

    add_str(hypertas, "hcall-tce");

    add_str(hypertas, "hcall-vio");

    add_str(hypertas, "hcall-splpar");

    add_str(hypertas, "hcall-bulk");

    add_str(hypertas, "hcall-set-mode");

    add_str(hypertas, "hcall-sprg0");

    add_str(hypertas, "hcall-copy");

    add_str(hypertas, "hcall-debug");

    add_str(qemu_hypertas, "hcall-memop1");



    if (!kvm_enabled() || kvmppc_spapr_use_multitce()) {

        add_str(hypertas, "hcall-multi-tce");

    }



    if (spapr->resize_hpt != SPAPR_RESIZE_HPT_DISABLED) {

        add_str(hypertas, "hcall-hpt-resize");

    }



    _FDT(fdt_setprop(fdt, rtas, "ibm,hypertas-functions",

                     hypertas->str, hypertas->len));

    g_string_free(hypertas, TRUE);

    _FDT(fdt_setprop(fdt, rtas, "qemu,hypertas-functions",

                     qemu_hypertas->str, qemu_hypertas->len));

    g_string_free(qemu_hypertas, TRUE);



    _FDT(fdt_setprop(fdt, rtas, "ibm,associativity-reference-points",

                     refpoints, sizeof(refpoints)));



    _FDT(fdt_setprop_cell(fdt, rtas, "rtas-error-log-max",

                          RTAS_ERROR_LOG_MAX));

    _FDT(fdt_setprop_cell(fdt, rtas, "rtas-event-scan-rate",

                          RTAS_EVENT_SCAN_RATE));



    if (msi_nonbroken) {

        _FDT(fdt_setprop(fdt, rtas, "ibm,change-msix-capable", NULL, 0));

    }



    /*

     * According to PAPR, rtas ibm,os-term does not guarantee a return

     * back to the guest cpu.

     *

     * While an additional ibm,extended-os-term property indicates

     * that rtas call return will always occur. Set this property.

     */

    _FDT(fdt_setprop(fdt, rtas, "ibm,extended-os-term", NULL, 0));



    _FDT(fdt_setprop(fdt, rtas, "ibm,lrdr-capacity",

                     lrdr_capacity, sizeof(lrdr_capacity)));



    spapr_dt_rtas_tokens(fdt, rtas);

}

static ssize_t nbd_co_receive_request(NBDRequest *req,

                                      struct nbd_request *request)

{

    NBDClient *client = req->client;

    uint32_t command;

    ssize_t rc;



    g_assert(qemu_in_coroutine());

    client->recv_coroutine = qemu_coroutine_self();

    nbd_update_can_read(client);



    rc = nbd_receive_request(client->ioc, request);

    if (rc < 0) {

        if (rc != -EAGAIN) {

            rc = -EIO;

        }

        goto out;

    }



    TRACE("Decoding type");



    command = request->type & NBD_CMD_MASK_COMMAND;

    if (command != NBD_CMD_WRITE) {

        /* No payload, we are ready to read the next request.  */

        req->complete = true;

    }



    if (command == NBD_CMD_DISC) {

        /* Special case: we're going to disconnect without a reply,

         * whether or not flags, from, or len are bogus */

        TRACE("Request type is DISCONNECT");

        rc = -EIO;

        goto out;

    }



    /* Check for sanity in the parameters, part 1.  Defer as many

     * checks as possible until after reading any NBD_CMD_WRITE

     * payload, so we can try and keep the connection alive.  */

    if ((request->from + request->len) < request->from) {

        LOG("integer overflow detected, you're probably being attacked");

        rc = -EINVAL;

        goto out;

    }



    if (command == NBD_CMD_READ || command == NBD_CMD_WRITE) {

        if (request->len > NBD_MAX_BUFFER_SIZE) {

            LOG("len (%" PRIu32" ) is larger than max len (%u)",

                request->len, NBD_MAX_BUFFER_SIZE);

            rc = -EINVAL;

            goto out;

        }



        req->data = blk_try_blockalign(client->exp->blk, request->len);

        if (req->data == NULL) {

            rc = -ENOMEM;

            goto out;

        }

    }

    if (command == NBD_CMD_WRITE) {

        TRACE("Reading %" PRIu32 " byte(s)", request->len);



        if (read_sync(client->ioc, req->data, request->len) != request->len) {

            LOG("reading from socket failed");

            rc = -EIO;

            goto out;

        }

        req->complete = true;

    }



    /* Sanity checks, part 2. */

    if (request->from + request->len > client->exp->size) {

        LOG("operation past EOF; From: %" PRIu64 ", Len: %" PRIu32

            ", Size: %" PRIu64, request->from, request->len,

            (uint64_t)client->exp->size);

        rc = command == NBD_CMD_WRITE ? -ENOSPC : -EINVAL;

        goto out;

    }

    if (request->type & ~NBD_CMD_MASK_COMMAND & ~NBD_CMD_FLAG_FUA) {

        LOG("unsupported flags (got 0x%x)",

            request->type & ~NBD_CMD_MASK_COMMAND);

        rc = -EINVAL;

        goto out;

    }



    rc = 0;



out:

    client->recv_coroutine = NULL;

    nbd_update_can_read(client);



    return rc;

}

