void HELPER(ucf64_cmpd)(float64 a, float64 b, uint32_t c, CPUUniCore32State *env)

{

    int flag;

    flag = float64_compare_quiet(a, b, &env->ucf64.fp_status);

    env->CF = 0;

    switch (c & 0x7) {

    case 0: /* F */

        break;

    case 1: /* UN */

        if (flag == 2) {

            env->CF = 1;

        }

        break;

    case 2: /* EQ */

        if (flag == 0) {

            env->CF = 1;

        }

        break;

    case 3: /* UEQ */

        if ((flag == 0) || (flag == 2)) {

            env->CF = 1;

        }

        break;

    case 4: /* OLT */

        if (flag == -1) {

            env->CF = 1;

        }

        break;

    case 5: /* ULT */

        if ((flag == -1) || (flag == 2)) {

            env->CF = 1;

        }

        break;

    case 6: /* OLE */

        if ((flag == -1) || (flag == 0)) {

            env->CF = 1;

        }

        break;

    case 7: /* ULE */

        if (flag != 1) {

            env->CF = 1;

        }

        break;

    }

    env->ucf64.xregs[UC32_UCF64_FPSCR] = (env->CF << 29)

                    | (env->ucf64.xregs[UC32_UCF64_FPSCR] & 0x0fffffff);

}

static void acpi_align_size(GArray *blob, unsigned align)

{

    /* Align size to multiple of given size. This reduces the chance

     * we need to change size in the future (breaking cross version migration).

     */

    g_array_set_size(blob, (ROUND_UP(acpi_data_len(blob), align) +

                            g_array_get_element_size(blob) - 1) /

                             g_array_get_element_size(blob));

}

int fd_start_outgoing_migration(MigrationState *s, const char *fdname)

{

    s->fd = monitor_get_fd(s->mon, fdname);

    if (s->fd == -1) {

        DPRINTF("fd_migration: invalid file descriptor identifier\n");

        goto err_after_get_fd;

    }



    if (fcntl(s->fd, F_SETFL, O_NONBLOCK) == -1) {

        DPRINTF("Unable to set nonblocking mode on file descriptor\n");

        goto err_after_open;

    }



    s->get_error = fd_errno;

    s->write = fd_write;

    s->close = fd_close;



    migrate_fd_connect(s);

    return 0;



err_after_open:

    close(s->fd);

err_after_get_fd:

    return -1;

}

static void usbnet_receive(void *opaque, const uint8_t *buf, size_t size)

{

    USBNetState *s = opaque;

    struct rndis_packet_msg_type *msg;



    if (s->rndis) {

        msg = (struct rndis_packet_msg_type *) s->in_buf;

        if (!s->rndis_state == RNDIS_DATA_INITIALIZED)

            return;

        if (size + sizeof(struct rndis_packet_msg_type) > sizeof(s->in_buf))

            return;



        memset(msg, 0, sizeof(struct rndis_packet_msg_type));

        msg->MessageType = cpu_to_le32(RNDIS_PACKET_MSG);

        msg->MessageLength = cpu_to_le32(size + sizeof(struct rndis_packet_msg_type));

        msg->DataOffset = cpu_to_le32(sizeof(struct rndis_packet_msg_type) - 8);

        msg->DataLength = cpu_to_le32(size);

        /* msg->OOBDataOffset;

         * msg->OOBDataLength;

         * msg->NumOOBDataElements;

         * msg->PerPacketInfoOffset;

         * msg->PerPacketInfoLength;

         * msg->VcHandle;

         * msg->Reserved;

         */

        memcpy(msg + 1, buf, size);

        s->in_len = size + sizeof(struct rndis_packet_msg_type);

    } else {

        if (size > sizeof(s->in_buf))

            return;

        memcpy(s->in_buf, buf, size);

        s->in_len = size;

    }

    s->in_ptr = 0;

}

static int v9fs_walk_marshal(V9fsPDU *pdu, uint16_t nwnames, V9fsQID *qids)

{

    int i;

    size_t offset = 7;

    offset += pdu_marshal(pdu, offset, "w", nwnames);

    for (i = 0; i < nwnames; i++) {

        offset += pdu_marshal(pdu, offset, "Q", &qids[i]);

    }

    return offset;

}

static void close_unused_images(BlockDriverState *top, BlockDriverState *base,

                                const char *base_id)

{

    BlockDriverState *intermediate;

    intermediate = top->backing_hd;



    while (intermediate) {

        BlockDriverState *unused;



        /* reached base */

        if (intermediate == base) {

            break;

        }



        unused = intermediate;

        intermediate = intermediate->backing_hd;

        unused->backing_hd = NULL;

        bdrv_delete(unused);

    }

    top->backing_hd = base;

}

