qht_entry_move(struct qht_bucket *to, int i, struct qht_bucket *from, int j)

{

    qht_debug_assert(!(to == from && i == j));

    qht_debug_assert(to->pointers[i]);

    qht_debug_assert(from->pointers[j]);



    to->hashes[i] = from->hashes[j];

    atomic_set(&to->pointers[i], from->pointers[j]);



    from->hashes[j] = 0;

    atomic_set(&from->pointers[j], NULL);

}

static void tswap_siginfo(target_siginfo_t *tinfo,

                          const target_siginfo_t *info)

{

    int sig = info->si_signo;

    tinfo->si_signo = tswap32(sig);

    tinfo->si_errno = tswap32(info->si_errno);

    tinfo->si_code = tswap32(info->si_code);



    if (sig == TARGET_SIGILL || sig == TARGET_SIGFPE || sig == TARGET_SIGSEGV

        || sig == TARGET_SIGBUS || sig == TARGET_SIGTRAP) {

        tinfo->_sifields._sigfault._addr

            = tswapal(info->_sifields._sigfault._addr);

    } else if (sig == TARGET_SIGIO) {

        tinfo->_sifields._sigpoll._band

            = tswap32(info->_sifields._sigpoll._band);

        tinfo->_sifields._sigpoll._fd = tswap32(info->_sifields._sigpoll._fd);

    } else if (sig == TARGET_SIGCHLD) {

        tinfo->_sifields._sigchld._pid

            = tswap32(info->_sifields._sigchld._pid);

        tinfo->_sifields._sigchld._uid

            = tswap32(info->_sifields._sigchld._uid);

        tinfo->_sifields._sigchld._status

            = tswap32(info->_sifields._sigchld._status);

        tinfo->_sifields._sigchld._utime

            = tswapal(info->_sifields._sigchld._utime);

        tinfo->_sifields._sigchld._stime

            = tswapal(info->_sifields._sigchld._stime);

    } else if (sig >= TARGET_SIGRTMIN) {

        tinfo->_sifields._rt._pid = tswap32(info->_sifields._rt._pid);

        tinfo->_sifields._rt._uid = tswap32(info->_sifields._rt._uid);

        tinfo->_sifields._rt._sigval.sival_ptr

            = tswapal(info->_sifields._rt._sigval.sival_ptr);

    }

}

void axisdev88_init (ram_addr_t ram_size,

                     const char *boot_device,

                     const char *kernel_filename, const char *kernel_cmdline,

                     const char *initrd_filename, const char *cpu_model)

{

    CPUState *env;

    DeviceState *dev;

    SysBusDevice *s;

    qemu_irq irq[30], nmi[2], *cpu_irq;

    void *etraxfs_dmac;

    struct etraxfs_dma_client *eth[2] = {NULL, NULL};

    int kernel_size;

    int i;

    int nand_regs;

    int gpio_regs;

    ram_addr_t phys_ram;

    ram_addr_t phys_intmem;



    /* init CPUs */

    if (cpu_model == NULL) {

        cpu_model = "crisv32";

    }

    env = cpu_init(cpu_model);

    qemu_register_reset(main_cpu_reset, env);



    /* allocate RAM */

    phys_ram = qemu_ram_alloc(ram_size);

    cpu_register_physical_memory(0x40000000, ram_size, phys_ram | IO_MEM_RAM);



    /* The ETRAX-FS has 128Kb on chip ram, the docs refer to it as the 

       internal memory.  */

    phys_intmem = qemu_ram_alloc(INTMEM_SIZE);

    cpu_register_physical_memory(0x38000000, INTMEM_SIZE,

                                 phys_intmem | IO_MEM_RAM);





      /* Attach a NAND flash to CS1.  */

    nand_state.nand = nand_init(NAND_MFR_STMICRO, 0x39);

    nand_regs = cpu_register_io_memory(nand_read, nand_write, &nand_state);

    cpu_register_physical_memory(0x10000000, 0x05000000, nand_regs);



    gpio_state.nand = &nand_state;

    gpio_regs = cpu_register_io_memory(gpio_read, gpio_write, &gpio_state);

    cpu_register_physical_memory(0x3001a000, 0x5c, gpio_regs);





    cpu_irq = cris_pic_init_cpu(env);

    dev = qdev_create(NULL, "etraxfs,pic");

    /* FIXME: Is there a proper way to signal vectors to the CPU core?  */

    qdev_prop_set_ptr(dev, "interrupt_vector", &env->interrupt_vector);

    qdev_init(dev);

    s = sysbus_from_qdev(dev);

    sysbus_mmio_map(s, 0, 0x3001c000);

    sysbus_connect_irq(s, 0, cpu_irq[0]);

    sysbus_connect_irq(s, 1, cpu_irq[1]);

    for (i = 0; i < 30; i++) {

        irq[i] = qdev_get_gpio_in(dev, i);

    }

    nmi[0] = qdev_get_gpio_in(dev, 30);

    nmi[1] = qdev_get_gpio_in(dev, 31);



    etraxfs_dmac = etraxfs_dmac_init(0x30000000, 10);

    for (i = 0; i < 10; i++) {

        /* On ETRAX, odd numbered channels are inputs.  */

        etraxfs_dmac_connect(etraxfs_dmac, i, irq + 7 + i, i & 1);

    }



    /* Add the two ethernet blocks.  */

    eth[0] = etraxfs_eth_init(&nd_table[0], 0x30034000, 1);

    if (nb_nics > 1)

        eth[1] = etraxfs_eth_init(&nd_table[1], 0x30036000, 2);



    /* The DMA Connector block is missing, hardwire things for now.  */

    etraxfs_dmac_connect_client(etraxfs_dmac, 0, eth[0]);

    etraxfs_dmac_connect_client(etraxfs_dmac, 1, eth[0] + 1);

    if (eth[1]) {

        etraxfs_dmac_connect_client(etraxfs_dmac, 6, eth[1]);

        etraxfs_dmac_connect_client(etraxfs_dmac, 7, eth[1] + 1);

    }



    /* 2 timers.  */

    sysbus_create_varargs("etraxfs,timer", 0x3001e000, irq[0x1b], nmi[1], NULL);

    sysbus_create_varargs("etraxfs,timer", 0x3005e000, irq[0x1b], nmi[1], NULL);



    for (i = 0; i < 4; i++) {

        sysbus_create_simple("etraxfs,serial", 0x30026000 + i * 0x2000,

                             irq[0x14 + i]);

    }



    if (kernel_filename) {

        uint64_t entry, high;

        int kcmdline_len;



        /* Boots a kernel elf binary, os/linux-2.6/vmlinux from the axis 

           devboard SDK.  */

        kernel_size = load_elf(kernel_filename, -0x80000000LL,

                               &entry, NULL, &high, 0, ELF_MACHINE, 0);

        bootstrap_pc = entry;

        if (kernel_size < 0) {

            /* Takes a kimage from the axis devboard SDK.  */

            kernel_size = load_image_targphys(kernel_filename, 0x40004000,

                                              ram_size);

            bootstrap_pc = 0x40004000;

            env->regs[9] = 0x40004000 + kernel_size;

        }

        env->regs[8] = 0x56902387; /* RAM init magic.  */



        if (kernel_cmdline && (kcmdline_len = strlen(kernel_cmdline))) {

            if (kcmdline_len > 256) {

                fprintf(stderr, "Too long CRIS kernel cmdline (max 256)\n");

                exit(1);

            }

            /* Let the kernel know we are modifying the cmdline.  */

            env->regs[10] = 0x87109563;

            env->regs[11] = 0x40000000;

            pstrcpy_targphys(env->regs[11], 256, kernel_cmdline);

        }

    }

    env->pc = bootstrap_pc;



    printf ("pc =%x\n", env->pc);

    printf ("ram size =%ld\n", ram_size);

}

void bdrv_eject(BlockDriverState *bs, int eject_flag)

{

    BlockDriver *drv = bs->drv;

    int ret;



    if (!drv || !drv->bdrv_eject) {

        ret = -ENOTSUP;

    } else {

        ret = drv->bdrv_eject(bs, eject_flag);

    }

    if (ret == -ENOTSUP) {

        if (eject_flag)

            bdrv_close(bs);

    }

}

static MemTxResult memory_region_write_with_attrs_accessor(MemoryRegion *mr,

                                                           hwaddr addr,

                                                           uint64_t *value,

                                                           unsigned size,

                                                           unsigned shift,

                                                           uint64_t mask,

                                                           MemTxAttrs attrs)

{

    uint64_t tmp;



    tmp = (*value >> shift) & mask;

    if (mr->subpage) {

        trace_memory_region_subpage_write(get_cpu_index(), mr, addr, tmp, size);






    } else if (TRACE_MEMORY_REGION_OPS_WRITE_ENABLED) {

        hwaddr abs_addr = memory_region_to_absolute_addr(mr, addr);

        trace_memory_region_ops_write(get_cpu_index(), mr, abs_addr, tmp, size);

    }

    return mr->ops->write_with_attrs(mr->opaque, addr, tmp, size, attrs);

}

static void usbredir_realize(USBDevice *udev, Error **errp)

{

    USBRedirDevice *dev = USB_REDIRECT(udev);

    int i;



    if (!qemu_chr_fe_get_driver(&dev->cs)) {

        error_setg(errp, QERR_MISSING_PARAMETER, "chardev");

        return;

    }



    if (dev->filter_str) {

        i = usbredirfilter_string_to_rules(dev->filter_str, ":", "|",

                                           &dev->filter_rules,

                                           &dev->filter_rules_count);

        if (i) {

            error_setg(errp, QERR_INVALID_PARAMETER_VALUE, "filter",

                       "a usb device filter string");

            return;

        }

    }



    dev->chardev_close_bh = qemu_bh_new(usbredir_chardev_close_bh, dev);

    dev->device_reject_bh = qemu_bh_new(usbredir_device_reject_bh, dev);

    dev->attach_timer = timer_new_ms(QEMU_CLOCK_VIRTUAL, usbredir_do_attach, dev);



    packet_id_queue_init(&dev->cancelled, dev, "cancelled");

    packet_id_queue_init(&dev->already_in_flight, dev, "already-in-flight");

    usbredir_init_endpoints(dev);



    /* We'll do the attach once we receive the speed from the usb-host */

    udev->auto_attach = 0;



    /* Will be cleared during setup when we find conflicts */

    dev->compatible_speedmask = USB_SPEED_MASK_FULL | USB_SPEED_MASK_HIGH;



    /* Let the backend know we are ready */

    qemu_chr_fe_set_handlers(&dev->cs, usbredir_chardev_can_read,

                             usbredir_chardev_read, usbredir_chardev_event,

                             dev, NULL, true);



    qemu_add_vm_change_state_handler(usbredir_vm_state_change, dev);

}

