        if (env->flags & POWERPC_FLAG_PX)

            printf("                        inclusive protection\n");

        else if (env->flags & POWERPC_FLAG_PMM)

            printf("                        performance monitor mark\n");

        if (env->flags == POWERPC_FLAG_NONE)

            printf("                        none\n");

