static int kvm_s390_store_adtl_status(S390CPU *cpu, hwaddr addr)

{

    void *mem;

    hwaddr len = ADTL_SAVE_AREA_SIZE;



    mem = cpu_physical_memory_map(addr, &len, 1);

    if (!mem) {

        return -EFAULT;

    }

    if (len != ADTL_SAVE_AREA_SIZE) {

        cpu_physical_memory_unmap(mem, len, 1, 0);

        return -EFAULT;

    }



    memcpy(mem, &cpu->env.vregs, 512);



    cpu_physical_memory_unmap(mem, len, 1, len);



    return 0;

}

int page_unprotect(target_ulong address, unsigned long pc, void *puc)

{

    unsigned int page_index, prot, pindex;

    PageDesc *p, *p1;

    target_ulong host_start, host_end, addr;



    /* Technically this isn't safe inside a signal handler.  However we

       know this only ever happens in a synchronous SEGV handler, so in

       practice it seems to be ok.  */

    mmap_lock();



    host_start = address & qemu_host_page_mask;

    page_index = host_start >> TARGET_PAGE_BITS;

    p1 = page_find(page_index);

    if (!p1) {

        mmap_unlock();

        return 0;

    }

    host_end = host_start + qemu_host_page_size;

    p = p1;

    prot = 0;

    for(addr = host_start;addr < host_end; addr += TARGET_PAGE_SIZE) {

        prot |= p->flags;

        p++;

    }

    /* if the page was really writable, then we change its

       protection back to writable */

    if (prot & PAGE_WRITE_ORG) {

        pindex = (address - host_start) >> TARGET_PAGE_BITS;

        if (!(p1[pindex].flags & PAGE_WRITE)) {

            mprotect((void *)g2h(host_start), qemu_host_page_size,

                     (prot & PAGE_BITS) | PAGE_WRITE);

            p1[pindex].flags |= PAGE_WRITE;

            /* and since the content will be modified, we must invalidate

               the corresponding translated code. */

            tb_invalidate_phys_page(address, pc, puc);

#ifdef DEBUG_TB_CHECK

            tb_invalidate_check(address);

#endif

            mmap_unlock();

            return 1;

        }

    }

    mmap_unlock();

    return 0;

}

static inline int array_roll(array_t* array,int index_to,int index_from,int count)

{

    char* buf;

    char* from;

    char* to;

    int is;



    if(!array ||

	    index_to<0 || index_to>=array->next ||

	    index_from<0 || index_from>=array->next)

	return -1;



    if(index_to==index_from)

	return 0;



    is=array->item_size;

    from=array->pointer+index_from*is;

    to=array->pointer+index_to*is;

    buf=g_malloc(is*count);

    memcpy(buf,from,is*count);



    if(index_to<index_from)

	memmove(to+is*count,to,from-to);

    else

	memmove(from,from+is*count,to-from);



    memcpy(to,buf,is*count);



    free(buf);



    return 0;

}

QEMUSizedBuffer *qsb_create(const uint8_t *buffer, size_t len)

{

    QEMUSizedBuffer *qsb;

    size_t alloc_len, num_chunks, i, to_copy;

    size_t chunk_size = (len > QSB_MAX_CHUNK_SIZE)

                        ? QSB_MAX_CHUNK_SIZE

                        : QSB_CHUNK_SIZE;



    num_chunks = DIV_ROUND_UP(len ? len : QSB_CHUNK_SIZE, chunk_size);

    alloc_len = num_chunks * chunk_size;



    qsb = g_try_new0(QEMUSizedBuffer, 1);

    if (!qsb) {

        return NULL;

    }



    qsb->iov = g_try_new0(struct iovec, num_chunks);

    if (!qsb->iov) {

        g_free(qsb);

        return NULL;

    }



    qsb->n_iov = num_chunks;



    for (i = 0; i < num_chunks; i++) {

        qsb->iov[i].iov_base = g_try_malloc0(chunk_size);

        if (!qsb->iov[i].iov_base) {

            /* qsb_free is safe since g_free can cope with NULL */

            qsb_free(qsb);

            return NULL;

        }



        qsb->iov[i].iov_len = chunk_size;

        if (buffer) {

            to_copy = (len - qsb->used) > chunk_size

                      ? chunk_size : (len - qsb->used);

            memcpy(qsb->iov[i].iov_base, &buffer[qsb->used], to_copy);

            qsb->used += to_copy;

        }

    }



    qsb->size = alloc_len;



    return qsb;

}

