bool kvmppc_is_mem_backend_page_size_ok(const char *obj_path)

{

    Object *mem_obj = object_resolve_path(obj_path, NULL);

    char *mempath = object_property_get_str(mem_obj, "mem-path", NULL);

    long pagesize;



    if (mempath) {

        pagesize = qemu_mempath_getpagesize(mempath);


    } else {

        pagesize = getpagesize();

    }



    return pagesize >= max_cpu_page_size;

}

void helper_ldqf(CPUSPARCState *env, target_ulong addr, int mem_idx)

{

    /* XXX add 128 bit load */

    CPU_QuadU u;



    helper_check_align(env, addr, 7);

#if !defined(CONFIG_USER_ONLY)

    switch (mem_idx) {

    case MMU_USER_IDX:

        u.ll.upper = cpu_ldq_user(env, addr);

        u.ll.lower = cpu_ldq_user(env, addr + 8);

        QT0 = u.q;

        break;

    case MMU_KERNEL_IDX:

        u.ll.upper = cpu_ldq_kernel(env, addr);

        u.ll.lower = cpu_ldq_kernel(env, addr + 8);

        QT0 = u.q;

        break;

#ifdef TARGET_SPARC64

    case MMU_HYPV_IDX:

        u.ll.upper = cpu_ldq_hypv(env, addr);

        u.ll.lower = cpu_ldq_hypv(env, addr + 8);

        QT0 = u.q;

        break;

#endif

    default:

        DPRINTF_MMU("helper_ldqf: need to check MMU idx %d\n", mem_idx);

        break;

    }

#else

    u.ll.upper = ldq_raw(address_mask(env, addr));

    u.ll.lower = ldq_raw(address_mask(env, addr + 8));

    QT0 = u.q;

#endif

}

static MemTxResult memory_region_write_accessor(MemoryRegion *mr,

                                                hwaddr addr,

                                                uint64_t *value,

                                                unsigned size,

                                                unsigned shift,

                                                uint64_t mask,

                                                MemTxAttrs attrs)

{

    uint64_t tmp;



    tmp = (*value >> shift) & mask;

    if (mr->subpage) {

        trace_memory_region_subpage_write(get_cpu_index(), mr, addr, tmp, size);






    } else if (TRACE_MEMORY_REGION_OPS_WRITE_ENABLED) {

        hwaddr abs_addr = memory_region_to_absolute_addr(mr, addr);

        trace_memory_region_ops_write(get_cpu_index(), mr, abs_addr, tmp, size);

    }

    mr->ops->write(mr->opaque, addr, tmp, size);

    return MEMTX_OK;

}

