#ifdef TARGET_WORDS_BIGENDIAN

#define GET_LMASK(v) ((v) & 3)

#define GET_OFFSET(addr, offset) (addr + (offset))

#else

#define GET_LMASK(v) (((v) & 3) ^ 3)

#define GET_OFFSET(addr, offset) (addr - (offset))

#endif



target_ulong helper_lwl(CPUMIPSState *env, target_ulong arg1,

                        target_ulong arg2, int mem_idx)

{

    target_ulong tmp;



    tmp = do_lbu(env, arg2, mem_idx);

    arg1 = (arg1 & 0x00FFFFFF) | (tmp << 24);



    if (GET_LMASK(arg2) <= 2) {

        tmp = do_lbu(env, GET_OFFSET(arg2, 1), mem_idx);

        arg1 = (arg1 & 0xFF00FFFF) | (tmp << 16);

    }



    if (GET_LMASK(arg2) <= 1) {

        tmp = do_lbu(env, GET_OFFSET(arg2, 2), mem_idx);

        arg1 = (arg1 & 0xFFFF00FF) | (tmp << 8);

    }



    if (GET_LMASK(arg2) == 0) {

        tmp = do_lbu(env, GET_OFFSET(arg2, 3), mem_idx);

        arg1 = (arg1 & 0xFFFFFF00) | tmp;

    }

    return (int32_t)arg1;

}

static long do_sigreturn_v2(CPUARMState *env)

{

        abi_ulong frame_addr;

	struct sigframe_v2 *frame;



	/*

	 * Since we stacked the signal on a 64-bit boundary,

	 * then 'sp' should be word aligned here.  If it's

	 * not, then the user is trying to mess with us.

	 */

	if (env->regs[13] & 7)

		goto badframe;



        frame_addr = env->regs[13];

	if (!lock_user_struct(VERIFY_READ, frame, frame_addr, 1))

                goto badframe;



        if (do_sigframe_return_v2(env, frame_addr, &frame->uc))

                goto badframe;



	unlock_user_struct(frame, frame_addr, 0);

	return env->regs[0];



badframe:

	unlock_user_struct(frame, frame_addr, 0);

        force_sig(TARGET_SIGSEGV /* , current */);

	return 0;

}

static PCIDevice *find_dev(sPAPREnvironment *spapr,

                           uint64_t buid, uint32_t config_addr)

{

    int devfn = (config_addr >> 8) & 0xFF;

    sPAPRPHBState *phb;



    QLIST_FOREACH(phb, &spapr->phbs, list) {

        BusChild *kid;



        if (phb->buid != buid) {

            continue;

        }



        QTAILQ_FOREACH(kid, &phb->host_state.bus->qbus.children, sibling) {

            PCIDevice *dev = (PCIDevice *)kid->child;

            if (dev->devfn == devfn) {

                return dev;

            }

        }

    }



    return NULL;

}

int xics_alloc(XICSState *icp, int src, int irq_hint, bool lsi)

{

    ICSState *ics = &icp->ics[src];

    int irq;



    if (irq_hint) {

        assert(src == xics_find_source(icp, irq_hint));

        if (!ICS_IRQ_FREE(ics, irq_hint - ics->offset)) {

            trace_xics_alloc_failed_hint(src, irq_hint);

            return -1;

        }

        irq = irq_hint;

    } else {

        irq = ics_find_free_block(ics, 1, 1);

        if (irq < 0) {

            trace_xics_alloc_failed_no_left(src);

            return -1;

        }

        irq += ics->offset;

    }



    ics_set_irq_type(ics, irq - ics->offset, lsi);

    trace_xics_alloc(src, irq);



    return irq;

}

static int archipelago_submit_request(BDRVArchipelagoState *s,

                                        uint64_t bufidx,

                                        size_t count,

                                        off_t offset,

                                        ArchipelagoAIOCB *aio_cb,

                                        ArchipelagoSegmentedRequest *segreq,

                                        int op)

{

    int ret, targetlen;

    char *target;

    void *data = NULL;

    struct xseg_request *req;

    AIORequestData *reqdata = g_malloc(sizeof(AIORequestData));



    targetlen = strlen(s->volname);

    req = xseg_get_request(s->xseg, s->srcport, s->vportno, X_ALLOC);

    if (!req) {

        archipelagolog("Cannot get XSEG request\n");

        goto err_exit2;

    }

    ret = xseg_prep_request(s->xseg, req, targetlen, count);

    if (ret < 0) {

        archipelagolog("Cannot prepare XSEG request\n");

        goto err_exit;

    }

    target = xseg_get_target(s->xseg, req);

    if (!target) {

        archipelagolog("Cannot get XSEG target\n");

        goto err_exit;

    }

    memcpy(target, s->volname, targetlen);

    req->size = count;

    req->offset = offset;



    switch (op) {

    case ARCHIP_OP_READ:

        req->op = X_READ;

        break;

    case ARCHIP_OP_WRITE:

        req->op = X_WRITE;

        break;

    case ARCHIP_OP_FLUSH:

        req->op = X_FLUSH;

        break;

    }

    reqdata->volname = s->volname;

    reqdata->offset = offset;

    reqdata->size = count;

    reqdata->bufidx = bufidx;

    reqdata->aio_cb = aio_cb;

    reqdata->segreq = segreq;

    reqdata->op = op;



    xseg_set_req_data(s->xseg, req, reqdata);

    if (op == ARCHIP_OP_WRITE) {

        data = xseg_get_data(s->xseg, req);

        if (!data) {

            archipelagolog("Cannot get XSEG data\n");

            goto err_exit;

        }

        qemu_iovec_to_buf(aio_cb->qiov, bufidx, data, count);

    }



    xport p = xseg_submit(s->xseg, req, s->srcport, X_ALLOC);

    if (p == NoPort) {

        archipelagolog("Could not submit XSEG request\n");

        goto err_exit;

    }

    xseg_signal(s->xseg, p);

    return 0;



err_exit:

    g_free(reqdata);

    xseg_put_request(s->xseg, req, s->srcport);

    return -EIO;

err_exit2:

    g_free(reqdata);

    return -EIO;

}

int vhost_dev_enable_notifiers(struct vhost_dev *hdev, VirtIODevice *vdev)

{

    BusState *qbus = BUS(qdev_get_parent_bus(DEVICE(vdev)));

    VirtioBusState *vbus = VIRTIO_BUS(qbus);

    VirtioBusClass *k = VIRTIO_BUS_GET_CLASS(vbus);

    int i, r;

    if (!k->set_host_notifier) {

        fprintf(stderr, "binding does not support host notifiers\n");

        r = -ENOSYS;

        goto fail;

    }



    for (i = 0; i < hdev->nvqs; ++i) {

        r = k->set_host_notifier(qbus->parent, hdev->vq_index + i, true);

        if (r < 0) {

            fprintf(stderr, "vhost VQ %d notifier binding failed: %d\n", i, -r);

            goto fail_vq;

        }

    }



    return 0;

fail_vq:

    while (--i >= 0) {

        r = k->set_host_notifier(qbus->parent, hdev->vq_index + i, false);

        if (r < 0) {

            fprintf(stderr, "vhost VQ %d notifier cleanup error: %d\n", i, -r);

            fflush(stderr);

        }

        assert (r >= 0);

    }

fail:

    return r;

}

static int multiwrite_f(BlockDriverState *bs, int argc, char **argv)

{

    struct timeval t1, t2;

    int Cflag = 0, qflag = 0;

    int c, cnt;

    char **buf;

    int64_t offset, first_offset = 0;

    /* Some compilers get confused and warn if this is not initialized.  */

    int total = 0;

    int nr_iov;

    int nr_reqs;

    int pattern = 0xcd;

    QEMUIOVector *qiovs;

    int i;

    BlockRequest *reqs;



    while ((c = getopt(argc, argv, "CqP:")) != EOF) {

        switch (c) {

        case 'C':

            Cflag = 1;

            break;

        case 'q':

            qflag = 1;

            break;

        case 'P':

            pattern = parse_pattern(optarg);

            if (pattern < 0) {

                return 0;

            }

            break;

        default:

            return qemuio_command_usage(&writev_cmd);

        }

    }



    if (optind > argc - 2) {

        return qemuio_command_usage(&writev_cmd);

    }



    nr_reqs = 1;

    for (i = optind; i < argc; i++) {

        if (!strcmp(argv[i], ";")) {

            nr_reqs++;

        }

    }



    reqs = g_malloc0(nr_reqs * sizeof(*reqs));

    buf = g_malloc0(nr_reqs * sizeof(*buf));

    qiovs = g_malloc(nr_reqs * sizeof(*qiovs));



    for (i = 0; i < nr_reqs && optind < argc; i++) {

        int j;



        /* Read the offset of the request */

        offset = cvtnum(argv[optind]);

        if (offset < 0) {

            printf("non-numeric offset argument -- %s\n", argv[optind]);

            goto out;

        }

        optind++;



        if (offset & 0x1ff) {

            printf("offset %lld is not sector aligned\n",

                   (long long)offset);

            goto out;

        }



        if (i == 0) {

            first_offset = offset;

        }



        /* Read lengths for qiov entries */

        for (j = optind; j < argc; j++) {

            if (!strcmp(argv[j], ";")) {

                break;

            }

        }



        nr_iov = j - optind;



        /* Build request */

        buf[i] = create_iovec(bs, &qiovs[i], &argv[optind], nr_iov, pattern);

        if (buf[i] == NULL) {

            goto out;

        }



        reqs[i].qiov = &qiovs[i];

        reqs[i].sector = offset >> 9;

        reqs[i].nb_sectors = reqs[i].qiov->size >> 9;



        optind = j + 1;



        pattern++;

    }



    /* If there were empty requests at the end, ignore them */

    nr_reqs = i;



    gettimeofday(&t1, NULL);

    cnt = do_aio_multiwrite(bs, reqs, nr_reqs, &total);

    gettimeofday(&t2, NULL);



    if (cnt < 0) {

        printf("aio_multiwrite failed: %s\n", strerror(-cnt));

        goto out;

    }



    if (qflag) {

        goto out;

    }



    /* Finally, report back -- -C gives a parsable format */

    t2 = tsub(t2, t1);

    print_report("wrote", &t2, first_offset, total, total, cnt, Cflag);

out:

    for (i = 0; i < nr_reqs; i++) {

        qemu_io_free(buf[i]);

        if (reqs[i].qiov != NULL) {

            qemu_iovec_destroy(&qiovs[i]);

        }

    }

    g_free(buf);

    g_free(reqs);

    g_free(qiovs);

    return 0;

}

static void mips_cps_realize(DeviceState *dev, Error **errp)

{

    MIPSCPSState *s = MIPS_CPS(dev);

    CPUMIPSState *env;

    MIPSCPU *cpu;

    int i;

    Error *err = NULL;

    target_ulong gcr_base;

    bool itu_present = false;



    for (i = 0; i < s->num_vp; i++) {

        cpu = cpu_mips_init(s->cpu_model);

        if (cpu == NULL) {

            error_setg(errp, "%s: CPU initialization failed",  __func__);

            return;

        }



        /* Init internal devices */

        cpu_mips_irq_init_cpu(cpu);

        cpu_mips_clock_init(cpu);



        env = &cpu->env;

        if (cpu_mips_itu_supported(env)) {

            itu_present = true;

            /* Attach ITC Tag to the VP */

            env->itc_tag = mips_itu_get_tag_region(&s->itu);

        }

        qemu_register_reset(main_cpu_reset, cpu);

    }



    cpu = MIPS_CPU(first_cpu);

    env = &cpu->env;



    /* Inter-Thread Communication Unit */

    if (itu_present) {

        object_initialize(&s->itu, sizeof(s->itu), TYPE_MIPS_ITU);

        qdev_set_parent_bus(DEVICE(&s->itu), sysbus_get_default());



        object_property_set_int(OBJECT(&s->itu), 16, "num-fifo", &err);

        object_property_set_int(OBJECT(&s->itu), 16, "num-semaphores", &err);

        object_property_set_bool(OBJECT(&s->itu), true, "realized", &err);

        if (err != NULL) {

            error_propagate(errp, err);

            return;

        }



        memory_region_add_subregion(&s->container, 0,

                           sysbus_mmio_get_region(SYS_BUS_DEVICE(&s->itu), 0));

    }



    /* Cluster Power Controller */

    object_initialize(&s->cpc, sizeof(s->cpc), TYPE_MIPS_CPC);

    qdev_set_parent_bus(DEVICE(&s->cpc), sysbus_get_default());



    object_property_set_int(OBJECT(&s->cpc), s->num_vp, "num-vp", &err);

    object_property_set_int(OBJECT(&s->cpc), 1, "vp-start-running", &err);

    object_property_set_bool(OBJECT(&s->cpc), true, "realized", &err);

    if (err != NULL) {

        error_propagate(errp, err);

        return;

    }



    memory_region_add_subregion(&s->container, 0,

                            sysbus_mmio_get_region(SYS_BUS_DEVICE(&s->cpc), 0));



    /* Global Interrupt Controller */

    object_initialize(&s->gic, sizeof(s->gic), TYPE_MIPS_GIC);

    qdev_set_parent_bus(DEVICE(&s->gic), sysbus_get_default());



    object_property_set_int(OBJECT(&s->gic), s->num_vp, "num-vp", &err);

    object_property_set_int(OBJECT(&s->gic), 128, "num-irq", &err);

    object_property_set_bool(OBJECT(&s->gic), true, "realized", &err);

    if (err != NULL) {

        error_propagate(errp, err);

        return;

    }



    memory_region_add_subregion(&s->container, 0,

                            sysbus_mmio_get_region(SYS_BUS_DEVICE(&s->gic), 0));



    /* Global Configuration Registers */

    gcr_base = env->CP0_CMGCRBase << 4;



    object_initialize(&s->gcr, sizeof(s->gcr), TYPE_MIPS_GCR);

    qdev_set_parent_bus(DEVICE(&s->gcr), sysbus_get_default());



    object_property_set_int(OBJECT(&s->gcr), s->num_vp, "num-vp", &err);

    object_property_set_int(OBJECT(&s->gcr), 0x800, "gcr-rev", &err);

    object_property_set_int(OBJECT(&s->gcr), gcr_base, "gcr-base", &err);

    object_property_set_link(OBJECT(&s->gcr), OBJECT(&s->gic.mr), "gic", &err);

    object_property_set_link(OBJECT(&s->gcr), OBJECT(&s->cpc.mr), "cpc", &err);

    object_property_set_bool(OBJECT(&s->gcr), true, "realized", &err);

    if (err != NULL) {

        error_propagate(errp, err);

        return;

    }



    memory_region_add_subregion(&s->container, gcr_base,

                            sysbus_mmio_get_region(SYS_BUS_DEVICE(&s->gcr), 0));

}

static void load_symbols(struct elfhdr *hdr, int fd, abi_ulong load_bias)

{

    int i, shnum, nsyms, sym_idx = 0, str_idx = 0;

    struct elf_shdr *shdr;

    char *strings = NULL;

    struct syminfo *s = NULL;

    struct elf_sym *new_syms, *syms = NULL;



    shnum = hdr->e_shnum;

    i = shnum * sizeof(struct elf_shdr);

    shdr = (struct elf_shdr *)alloca(i);

    if (pread(fd, shdr, i, hdr->e_shoff) != i) {

        return;

    }



    bswap_shdr(shdr, shnum);

    for (i = 0; i < shnum; ++i) {

        if (shdr[i].sh_type == SHT_SYMTAB) {

            sym_idx = i;

            str_idx = shdr[i].sh_link;

            goto found;

        }

    }



    /* There will be no symbol table if the file was stripped.  */

    return;



 found:

    /* Now know where the strtab and symtab are.  Snarf them.  */

    s = g_try_new(struct syminfo, 1);

    if (!s) {

        goto give_up;

    }



    i = shdr[str_idx].sh_size;

    s->disas_strtab = strings = g_try_malloc(i);

    if (!strings || pread(fd, strings, i, shdr[str_idx].sh_offset) != i) {

        goto give_up;

    }



    i = shdr[sym_idx].sh_size;

    syms = g_try_malloc(i);

    if (!syms || pread(fd, syms, i, shdr[sym_idx].sh_offset) != i) {

        goto give_up;

    }



    nsyms = i / sizeof(struct elf_sym);

    for (i = 0; i < nsyms; ) {

        bswap_sym(syms + i);

        /* Throw away entries which we do not need.  */

        if (syms[i].st_shndx == SHN_UNDEF

            || syms[i].st_shndx >= SHN_LORESERVE

            || ELF_ST_TYPE(syms[i].st_info) != STT_FUNC) {

            if (i < --nsyms) {

                syms[i] = syms[nsyms];

            }

        } else {

#if defined(TARGET_ARM) || defined (TARGET_MIPS)

            /* The bottom address bit marks a Thumb or MIPS16 symbol.  */

            syms[i].st_value &= ~(target_ulong)1;

#endif

            syms[i].st_value += load_bias;

            i++;

        }

    }



    /* No "useful" symbol.  */

    if (nsyms == 0) {

        goto give_up;

    }



    /* Attempt to free the storage associated with the local symbols

       that we threw away.  Whether or not this has any effect on the

       memory allocation depends on the malloc implementation and how

       many symbols we managed to discard.  */

    new_syms = g_try_renew(struct elf_sym, syms, nsyms);

    if (new_syms == NULL) {

        goto give_up;

    }

    syms = new_syms;



    qsort(syms, nsyms, sizeof(*syms), symcmp);



    s->disas_num_syms = nsyms;

#if ELF_CLASS == ELFCLASS32

    s->disas_symtab.elf32 = syms;

#else

    s->disas_symtab.elf64 = syms;

#endif

    s->lookup_symbol = lookup_symbolxx;

    s->next = syminfos;

    syminfos = s;



    return;



give_up:

    g_free(s);

    g_free(strings);

    g_free(syms);

}

static void qvirtio_pci_set_queue_address(QVirtioDevice *d, uint32_t pfn)

{

    QVirtioPCIDevice *dev = (QVirtioPCIDevice *)d;

    qpci_io_writel(dev->pdev, dev->addr + VIRTIO_PCI_QUEUE_PFN, pfn);

