static int64_t realloc_refcount_block(BlockDriverState *bs, int reftable_index,

                                      uint64_t offset)

{

    BDRVQcowState *s = bs->opaque;

    int64_t new_offset = 0;

    void *refcount_block = NULL;

    int ret;



    /* allocate new refcount block */

    new_offset = qcow2_alloc_clusters(bs, s->cluster_size);

    if (new_offset < 0) {

        fprintf(stderr, "Could not allocate new cluster: %s\n",

                strerror(-new_offset));

        ret = new_offset;

        goto fail;

    }



    /* fetch current refcount block content */

    ret = qcow2_cache_get(bs, s->refcount_block_cache, offset, &refcount_block);

    if (ret < 0) {

        fprintf(stderr, "Could not fetch refcount block: %s\n", strerror(-ret));

        goto fail;

    }



    /* new block has not yet been entered into refcount table, therefore it is

     * no refcount block yet (regarding this check) */

    ret = qcow2_pre_write_overlap_check(bs, 0, new_offset, s->cluster_size);

    if (ret < 0) {

        fprintf(stderr, "Could not write refcount block; metadata overlap "

                "check failed: %s\n", strerror(-ret));

        /* the image will be marked corrupt, so don't even attempt on freeing

         * the cluster */

        new_offset = 0;

        goto fail;

    }



    /* write to new block */

    ret = bdrv_write(bs->file, new_offset / BDRV_SECTOR_SIZE, refcount_block,

            s->cluster_sectors);

    if (ret < 0) {

        fprintf(stderr, "Could not write refcount block: %s\n", strerror(-ret));

        goto fail;

    }



    /* update refcount table */

    assert(!offset_into_cluster(s, new_offset));

    s->refcount_table[reftable_index] = new_offset;

    ret = write_reftable_entry(bs, reftable_index);

    if (ret < 0) {

        fprintf(stderr, "Could not update refcount table: %s\n",

                strerror(-ret));

        goto fail;

    }



fail:

    if (new_offset && (ret < 0)) {

        qcow2_free_clusters(bs, new_offset, s->cluster_size,

                QCOW2_DISCARD_ALWAYS);

    }

    if (refcount_block) {

        if (ret < 0) {

            qcow2_cache_put(bs, s->refcount_block_cache, &refcount_block);

        } else {

            ret = qcow2_cache_put(bs, s->refcount_block_cache, &refcount_block);

        }

    }

    if (ret < 0) {

        return ret;

    }

    return new_offset;

}

static ssize_t imx_enet_receive(NetClientState *nc, const uint8_t *buf,

                                size_t len)

{

    IMXFECState *s = IMX_FEC(qemu_get_nic_opaque(nc));

    IMXENETBufDesc bd;

    uint32_t flags = 0;

    uint32_t addr;

    uint32_t crc;

    uint32_t buf_addr;

    uint8_t *crc_ptr;

    unsigned int buf_len;

    size_t size = len;



    FEC_PRINTF("len %d\n", (int)size);



    if (!s->regs[ENET_RDAR]) {

        qemu_log_mask(LOG_GUEST_ERROR, "[%s]%s: Unexpected packet\n",

                      TYPE_IMX_FEC, __func__);

        return 0;

    }



    /* 4 bytes for the CRC.  */

    size += 4;

    crc = cpu_to_be32(crc32(~0, buf, size));

    crc_ptr = (uint8_t *) &crc;



    /* Huge frames are truncted.  */

    if (size > ENET_MAX_FRAME_SIZE) {

        size = ENET_MAX_FRAME_SIZE;

        flags |= ENET_BD_TR | ENET_BD_LG;

    }



    /* Frames larger than the user limit just set error flags.  */

    if (size > (s->regs[ENET_RCR] >> 16)) {

        flags |= ENET_BD_LG;

    }



    addr = s->rx_descriptor;

    while (size > 0) {

        imx_enet_read_bd(&bd, addr);

        if ((bd.flags & ENET_BD_E) == 0) {

            /* No descriptors available.  Bail out.  */

            /*

             * FIXME: This is wrong. We should probably either

             * save the remainder for when more RX buffers are

             * available, or flag an error.

             */

            qemu_log_mask(LOG_GUEST_ERROR, "[%s]%s: Lost end of frame\n",

                          TYPE_IMX_FEC, __func__);

            break;

        }

        buf_len = (size <= s->regs[ENET_MRBR]) ? size : s->regs[ENET_MRBR];

        bd.length = buf_len;

        size -= buf_len;



        FEC_PRINTF("rx_bd 0x%x length %d\n", addr, bd.length);



        /* The last 4 bytes are the CRC.  */

        if (size < 4) {

            buf_len += size - 4;

        }

        buf_addr = bd.data;

        dma_memory_write(&address_space_memory, buf_addr, buf, buf_len);

        buf += buf_len;

        if (size < 4) {

            dma_memory_write(&address_space_memory, buf_addr + buf_len,

                             crc_ptr, 4 - size);

            crc_ptr += 4 - size;

        }

        bd.flags &= ~ENET_BD_E;

        if (size == 0) {

            /* Last buffer in frame.  */

            bd.flags |= flags | ENET_BD_L;

            FEC_PRINTF("rx frame flags %04x\n", bd.flags);

            if (bd.option & ENET_BD_RX_INT) {

                s->regs[ENET_EIR] |= ENET_INT_RXF;

            }

        } else {

            if (bd.option & ENET_BD_RX_INT) {

                s->regs[ENET_EIR] |= ENET_INT_RXB;

            }

        }

        imx_enet_write_bd(&bd, addr);

        /* Advance to the next descriptor.  */

        if ((bd.flags & ENET_BD_W) != 0) {

            addr = s->regs[ENET_RDSR];

        } else {

            addr += sizeof(bd);

        }

    }

    s->rx_descriptor = addr;

    imx_eth_enable_rx(s);

    imx_eth_update(s);

    return len;

}

