void cpu_loop (CPUState *env)

{

    int trapnr;

    target_siginfo_t info;



    while (1) {

        trapnr = cpu_alpha_exec (env);



        switch (trapnr) {

        case EXCP_RESET:

            fprintf(stderr, "Reset requested. Exit\n");

            exit(1);

            break;

        case EXCP_MCHK:

            fprintf(stderr, "Machine check exception. Exit\n");

            exit(1);

            break;

        case EXCP_ARITH:

            fprintf(stderr, "Arithmetic trap.\n");

            exit(1);

            break;

        case EXCP_HW_INTERRUPT:

            fprintf(stderr, "External interrupt. Exit\n");

            exit(1);

            break;

        case EXCP_DFAULT:

            fprintf(stderr, "MMU data fault\n");

            exit(1);

            break;

        case EXCP_DTB_MISS_PAL:

            fprintf(stderr, "MMU data TLB miss in PALcode\n");

            exit(1);

            break;

        case EXCP_ITB_MISS:

            fprintf(stderr, "MMU instruction TLB miss\n");

            exit(1);

            break;

        case EXCP_ITB_ACV:

            fprintf(stderr, "MMU instruction access violation\n");

            exit(1);

            break;

        case EXCP_DTB_MISS_NATIVE:

            fprintf(stderr, "MMU data TLB miss\n");

            exit(1);

            break;

        case EXCP_UNALIGN:

            fprintf(stderr, "Unaligned access\n");

            exit(1);

            break;

        case EXCP_OPCDEC:

            fprintf(stderr, "Invalid instruction\n");

            exit(1);

            break;

        case EXCP_FEN:

            fprintf(stderr, "Floating-point not allowed\n");

            exit(1);

            break;

        case EXCP_CALL_PAL ... (EXCP_CALL_PALP - 1):

            call_pal(env, (trapnr >> 6) | 0x80);

            break;

        case EXCP_CALL_PALP ... (EXCP_CALL_PALE - 1):

            fprintf(stderr, "Privileged call to PALcode\n");

            exit(1);

            break;

        case EXCP_DEBUG:

            {

                int sig;



                sig = gdb_handlesig (env, TARGET_SIGTRAP);

                if (sig)

                  {

                    info.si_signo = sig;

                    info.si_errno = 0;

                    info.si_code = TARGET_TRAP_BRKPT;

                    queue_signal(env, info.si_signo, &info);

                  }

            }

            break;

        default:

            printf ("Unhandled trap: 0x%x\n", trapnr);

            cpu_dump_state(env, stderr, fprintf, 0);

            exit (1);

        }

        process_pending_signals (env);

    }

}

int rom_load_all(void)

{

    target_phys_addr_t addr = 0;

    MemoryRegionSection section;

    Rom *rom;



    QTAILQ_FOREACH(rom, &roms, next) {

        if (rom->fw_file) {

            continue;

        }

        if (addr > rom->addr) {

            fprintf(stderr, "rom: requested regions overlap "

                    "(rom %s. free=0x" TARGET_FMT_plx

                    ", addr=0x" TARGET_FMT_plx ")\n",

                    rom->name, addr, rom->addr);

            return -1;

        }

        addr  = rom->addr;

        addr += rom->romsize;

        section = memory_region_find(get_system_memory(), rom->addr, 1);

        rom->isrom = section.size && memory_region_is_rom(section.mr);

    }

    qemu_register_reset(rom_reset, NULL);

    roms_loaded = 1;

    return 0;

}

static int alsa_init_in (HWVoiceIn *hw, audsettings_t *as)

{

    ALSAVoiceIn *alsa = (ALSAVoiceIn *) hw;

    struct alsa_params_req req;

    struct alsa_params_obt obt;

    snd_pcm_t *handle;

    audsettings_t obt_as;



    req.fmt = aud_to_alsafmt (as->fmt);

    req.freq = as->freq;

    req.nchannels = as->nchannels;

    req.period_size = conf.period_size_in;

    req.buffer_size = conf.buffer_size_in;

    req.size_in_usec = conf.size_in_usec_in;

    req.override_mask = !!conf.period_size_in_overridden

        | (!!conf.buffer_size_in_overridden << 1);



    if (alsa_open (1, &req, &obt, &handle)) {

        return -1;

    }



    obt_as.freq = obt.freq;

    obt_as.nchannels = obt.nchannels;

    obt_as.fmt = obt.fmt;

    obt_as.endianness = obt.endianness;



    audio_pcm_init_info (&hw->info, &obt_as);

    hw->samples = obt.samples;



    alsa->pcm_buf = audio_calloc (AUDIO_FUNC, hw->samples, 1 << hw->info.shift);

    if (!alsa->pcm_buf) {

        dolog ("Could not allocate ADC buffer (%d samples, each %d bytes)\n",

               hw->samples, 1 << hw->info.shift);

        alsa_anal_close (&handle);

        return -1;

    }



    alsa->handle = handle;

    return 0;

}

