static uint64_t omap_id_read(void *opaque, target_phys_addr_t addr,

                             unsigned size)

{

    struct omap_mpu_state_s *s = (struct omap_mpu_state_s *) opaque;



    if (size != 4) {

        return omap_badwidth_read32(opaque, addr);

    }



    switch (addr) {

    case 0xfffe1800:	/* DIE_ID_LSB */

        return 0xc9581f0e;

    case 0xfffe1804:	/* DIE_ID_MSB */

        return 0xa8858bfa;



    case 0xfffe2000:	/* PRODUCT_ID_LSB */

        return 0x00aaaafc;

    case 0xfffe2004:	/* PRODUCT_ID_MSB */

        return 0xcafeb574;



    case 0xfffed400:	/* JTAG_ID_LSB */

        switch (s->mpu_model) {

        case omap310:

            return 0x03310315;

        case omap1510:

            return 0x03310115;

        default:

            hw_error("%s: bad mpu model\n", __FUNCTION__);

        }

        break;



    case 0xfffed404:	/* JTAG_ID_MSB */

        switch (s->mpu_model) {

        case omap310:

            return 0xfb57402f;

        case omap1510:

            return 0xfb47002f;

        default:

            hw_error("%s: bad mpu model\n", __FUNCTION__);

        }

        break;

    }



    OMAP_BAD_REG(addr);

    return 0;

}

ram_addr_t xen_ram_addr_from_mapcache(void *ptr)

{

    MapCacheEntry *entry = NULL;

    MapCacheRev *reventry;

    hwaddr paddr_index;

    hwaddr size;

    int found = 0;



    QTAILQ_FOREACH(reventry, &mapcache->locked_entries, next) {

        if (reventry->vaddr_req == ptr) {

            paddr_index = reventry->paddr_index;

            size = reventry->size;

            found = 1;

            break;

        }

    }

    if (!found) {

        fprintf(stderr, "%s, could not find %p\n", __func__, ptr);

        QTAILQ_FOREACH(reventry, &mapcache->locked_entries, next) {

            DPRINTF("   "TARGET_FMT_plx" -> %p is present\n", reventry->paddr_index,

                    reventry->vaddr_req);

        }

        abort();

        return 0;

    }



    entry = &mapcache->entry[paddr_index % mapcache->nr_buckets];

    while (entry && (entry->paddr_index != paddr_index || entry->size != size)) {

        entry = entry->next;

    }

    if (!entry) {

        DPRINTF("Trying to find address %p that is not in the mapcache!\n", ptr);

        return 0;

    }

    return (reventry->paddr_index << MCACHE_BUCKET_SHIFT) +

        ((unsigned long) ptr - (unsigned long) entry->vaddr_base);

}

static void hpdmc_write(void *opaque, target_phys_addr_t addr, uint64_t value,

                        unsigned size)

{

    MilkymistHpdmcState *s = opaque;



    trace_milkymist_hpdmc_memory_write(addr, value);



    addr >>= 2;

    switch (addr) {

    case R_SYSTEM:

    case R_BYPASS:

    case R_TIMING:

        s->regs[addr] = value;

        break;

    case R_IODELAY:

        /* ignore writes */

        break;



    default:

        error_report("milkymist_hpdmc: write access to unknown register 0x"

                TARGET_FMT_plx, addr << 2);

        break;

    }

}

static int write_elf32_note(DumpState *s)

{

    target_phys_addr_t begin = s->memory_offset - s->note_size;

    Elf32_Phdr phdr;

    int endian = s->dump_info.d_endian;

    int ret;



    memset(&phdr, 0, sizeof(Elf32_Phdr));

    phdr.p_type = cpu_convert_to_target32(PT_NOTE, endian);

    phdr.p_offset = cpu_convert_to_target32(begin, endian);

    phdr.p_paddr = 0;

    phdr.p_filesz = cpu_convert_to_target32(s->note_size, endian);

    phdr.p_memsz = cpu_convert_to_target32(s->note_size, endian);

    phdr.p_vaddr = 0;



