                            "host bridge", sizeof(PCIDevice),

                            0, NULL, NULL);



    pci_config_set_vendor_id(d->config, PCI_VENDOR_ID_FREESCALE);

    pci_config_set_device_id(d->config, PCI_DEVICE_ID_MPC8533E);

