static int load_bitmap_data(BlockDriverState *bs,

                            const uint64_t *bitmap_table,

                            uint32_t bitmap_table_size,

                            BdrvDirtyBitmap *bitmap)

{

    int ret = 0;

    BDRVQcow2State *s = bs->opaque;

    uint64_t sector, sbc;

    uint64_t bm_size = bdrv_dirty_bitmap_size(bitmap);

    uint64_t bm_sectors = DIV_ROUND_UP(bm_size, BDRV_SECTOR_SIZE);

    uint8_t *buf = NULL;

    uint64_t i, tab_size =

            size_to_clusters(s,

                bdrv_dirty_bitmap_serialization_size(bitmap, 0, bm_sectors));



    if (tab_size != bitmap_table_size || tab_size > BME_MAX_TABLE_SIZE) {

        return -EINVAL;

    }



    buf = g_malloc(s->cluster_size);

    sbc = sectors_covered_by_bitmap_cluster(s, bitmap);

    for (i = 0, sector = 0; i < tab_size; ++i, sector += sbc) {

        uint64_t count = MIN(bm_sectors - sector, sbc);

        uint64_t entry = bitmap_table[i];

        uint64_t offset = entry & BME_TABLE_ENTRY_OFFSET_MASK;



        assert(check_table_entry(entry, s->cluster_size) == 0);



        if (offset == 0) {

            if (entry & BME_TABLE_ENTRY_FLAG_ALL_ONES) {

                bdrv_dirty_bitmap_deserialize_ones(bitmap, sector, count,

                                                   false);

            } else {

                /* No need to deserialize zeros because the dirty bitmap is

                 * already cleared */

            }

        } else {

            ret = bdrv_pread(bs->file, offset, buf, s->cluster_size);

            if (ret < 0) {

                goto finish;

            }

            bdrv_dirty_bitmap_deserialize_part(bitmap, buf, sector, count,

                                               false);

        }

    }

    ret = 0;



    bdrv_dirty_bitmap_deserialize_finish(bitmap);



finish:

    g_free(buf);



    return ret;

}

static coroutine_fn int nbd_negotiate(NBDClientNewData *data)

{

    NBDClient *client = data->client;

    char buf[8 + 8 + 8 + 128];

    int rc;

    const int myflags = (NBD_FLAG_HAS_FLAGS | NBD_FLAG_SEND_TRIM |

                         NBD_FLAG_SEND_FLUSH | NBD_FLAG_SEND_FUA);

    bool oldStyle;



    /* Old style negotiation header without options

        [ 0 ..   7]   passwd       ("NBDMAGIC")

        [ 8 ..  15]   magic        (NBD_CLIENT_MAGIC)

        [16 ..  23]   size

        [24 ..  25]   server flags (0)

        [26 ..  27]   export flags

        [28 .. 151]   reserved     (0)



       New style negotiation header with options

        [ 0 ..   7]   passwd       ("NBDMAGIC")

        [ 8 ..  15]   magic        (NBD_OPTS_MAGIC)

        [16 ..  17]   server flags (0)

        ....options sent....

        [18 ..  25]   size

        [26 ..  27]   export flags

        [28 .. 151]   reserved     (0)

     */



    qio_channel_set_blocking(client->ioc, false, NULL);

    rc = -EINVAL;



    TRACE("Beginning negotiation.");

    memset(buf, 0, sizeof(buf));

    memcpy(buf, "NBDMAGIC", 8);



    oldStyle = client->exp != NULL && !client->tlscreds;

    if (oldStyle) {

        assert ((client->exp->nbdflags & ~65535) == 0);

        TRACE("advertising size %" PRIu64 " and flags %x",

              client->exp->size, client->exp->nbdflags | myflags);

        stq_be_p(buf + 8, NBD_CLIENT_MAGIC);

        stq_be_p(buf + 16, client->exp->size);

        stw_be_p(buf + 26, client->exp->nbdflags | myflags);

    } else {

        stq_be_p(buf + 8, NBD_OPTS_MAGIC);

        stw_be_p(buf + 16, NBD_FLAG_FIXED_NEWSTYLE);

    }



    if (oldStyle) {

        if (client->tlscreds) {

            TRACE("TLS cannot be enabled with oldstyle protocol");

            goto fail;

        }

        if (nbd_negotiate_write(client->ioc, buf, sizeof(buf)) != sizeof(buf)) {

            LOG("write failed");

            goto fail;

        }

    } else {

        if (nbd_negotiate_write(client->ioc, buf, 18) != 18) {

            LOG("write failed");

            goto fail;

        }

        rc = nbd_negotiate_options(client);

        if (rc != 0) {

            LOG("option negotiation failed");

            goto fail;

        }



        assert ((client->exp->nbdflags & ~65535) == 0);

        TRACE("advertising size %" PRIu64 " and flags %x",

              client->exp->size, client->exp->nbdflags | myflags);

        stq_be_p(buf + 18, client->exp->size);

        stw_be_p(buf + 26, client->exp->nbdflags | myflags);

        if (nbd_negotiate_write(client->ioc, buf + 18, sizeof(buf) - 18) !=

            sizeof(buf) - 18) {

            LOG("write failed");

            goto fail;

        }

    }



    TRACE("Negotiation succeeded.");

    rc = 0;

fail:

    return rc;

}

