static uint32_t rtl8139_io_readw(void *opaque, uint8_t addr)

{

    RTL8139State *s = opaque;

    uint32_t ret;



    switch (addr)

    {

        case TxAddr0 ... TxAddr0+4*4-1:

            ret = rtl8139_TxStatus_read(s, addr, 2);

            break;

        case IntrMask:

            ret = rtl8139_IntrMask_read(s);

            break;



        case IntrStatus:

            ret = rtl8139_IntrStatus_read(s);

            break;



        case MultiIntr:

            ret = rtl8139_MultiIntr_read(s);

            break;



        case RxBufPtr:

            ret = rtl8139_RxBufPtr_read(s);

            break;



        case RxBufAddr:

            ret = rtl8139_RxBufAddr_read(s);

            break;



        case BasicModeCtrl:

            ret = rtl8139_BasicModeCtrl_read(s);

            break;

        case BasicModeStatus:

            ret = rtl8139_BasicModeStatus_read(s);

            break;

        case NWayAdvert:

            ret = s->NWayAdvert;

            DPRINTF("NWayAdvert read(w) val=0x%04x\n", ret);

            break;

        case NWayLPAR:

            ret = s->NWayLPAR;

            DPRINTF("NWayLPAR read(w) val=0x%04x\n", ret);

            break;

        case NWayExpansion:

            ret = s->NWayExpansion;

            DPRINTF("NWayExpansion read(w) val=0x%04x\n", ret);

            break;



        case CpCmd:

            ret = rtl8139_CpCmd_read(s);

            break;



        case IntrMitigate:

            ret = rtl8139_IntrMitigate_read(s);

            break;



        case TxSummary:

            ret = rtl8139_TSAD_read(s);

            break;



        case CSCR:

            ret = rtl8139_CSCR_read(s);

            break;



        default:

            DPRINTF("ioport read(w) addr=0x%x via read(b)\n", addr);



            ret  = rtl8139_io_readb(opaque, addr);

            ret |= rtl8139_io_readb(opaque, addr + 1) << 8;



            DPRINTF("ioport read(w) addr=0x%x val=0x%04x\n", addr, ret);

            break;

    }



    return ret;

}

static void *colo_compare_thread(void *opaque)

{

    GMainContext *worker_context;

    GMainLoop *compare_loop;

    CompareState *s = opaque;

    GSource *timeout_source;



    worker_context = g_main_context_new();



    qemu_chr_fe_set_handlers(&s->chr_pri_in, compare_chr_can_read,

                             compare_pri_chr_in, NULL, s, worker_context, true);

    qemu_chr_fe_set_handlers(&s->chr_sec_in, compare_chr_can_read,

                             compare_sec_chr_in, NULL, s, worker_context, true);



    compare_loop = g_main_loop_new(worker_context, FALSE);



    /* To kick any packets that the secondary doesn't match */

    timeout_source = g_timeout_source_new(REGULAR_PACKET_CHECK_MS);

    g_source_set_callback(timeout_source,

                          (GSourceFunc)check_old_packet_regular, s, NULL);

    g_source_attach(timeout_source, worker_context);



    g_main_loop_run(compare_loop);



    g_source_unref(timeout_source);

    g_main_loop_unref(compare_loop);

    g_main_context_unref(worker_context);

    return NULL;

}

static void x86_cpu_reset(CPUState *s)
{
    X86CPU *cpu = X86_CPU(s);
    X86CPUClass *xcc = X86_CPU_GET_CLASS(cpu);
    CPUX86State *env = &cpu->env;
    int i;
    xcc->parent_reset(s);
    memset(env, 0, offsetof(CPUX86State, breakpoints));
    tlb_flush(env, 1);
    env->old_exception = -1;
    /* init to reset state */
#ifdef CONFIG_SOFTMMU
    env->hflags |= HF_SOFTMMU_MASK;
#endif
    env->hflags2 |= HF2_GIF_MASK;
    cpu_x86_update_cr0(env, 0x60000010);
    env->a20_mask = ~0x0;
    env->smbase = 0x30000;
    env->idt.limit = 0xffff;
    env->gdt.limit = 0xffff;
    env->ldt.limit = 0xffff;
    env->ldt.flags = DESC_P_MASK | (2 << DESC_TYPE_SHIFT);
    env->tr.limit = 0xffff;
    env->tr.flags = DESC_P_MASK | (11 << DESC_TYPE_SHIFT);
    cpu_x86_load_seg_cache(env, R_CS, 0xf000, 0xffff0000, 0xffff,
                           DESC_P_MASK | DESC_S_MASK | DESC_CS_MASK |
                           DESC_R_MASK | DESC_A_MASK);
    cpu_x86_load_seg_cache(env, R_DS, 0, 0, 0xffff,
                           DESC_P_MASK | DESC_S_MASK | DESC_W_MASK |
                           DESC_A_MASK);
    cpu_x86_load_seg_cache(env, R_ES, 0, 0, 0xffff,
                           DESC_P_MASK | DESC_S_MASK | DESC_W_MASK |
                           DESC_A_MASK);
    cpu_x86_load_seg_cache(env, R_SS, 0, 0, 0xffff,
                           DESC_P_MASK | DESC_S_MASK | DESC_W_MASK |
                           DESC_A_MASK);
    cpu_x86_load_seg_cache(env, R_FS, 0, 0, 0xffff,
                           DESC_P_MASK | DESC_S_MASK | DESC_W_MASK |
                           DESC_A_MASK);
    cpu_x86_load_seg_cache(env, R_GS, 0, 0, 0xffff,
                           DESC_P_MASK | DESC_S_MASK | DESC_W_MASK |
                           DESC_A_MASK);
    env->eip = 0xfff0;
    env->regs[R_EDX] = env->cpuid_version;
    env->eflags = 0x2;
    /* FPU init */
    for (i = 0; i < 8; i++) {
        env->fptags[i] = 1;
    }
    env->fpuc = 0x37f;
    env->mxcsr = 0x1f80;
    env->xstate_bv = XSTATE_FP | XSTATE_SSE;
    env->pat = 0x0007040600070406ULL;
    env->msr_ia32_misc_enable = MSR_IA32_MISC_ENABLE_DEFAULT;
    memset(env->dr, 0, sizeof(env->dr));
    env->dr[6] = DR6_FIXED_1;
    env->dr[7] = DR7_FIXED_1;
    cpu_breakpoint_remove_all(env, BP_CPU);
    cpu_watchpoint_remove_all(env, BP_CPU);
#if !defined(CONFIG_USER_ONLY)
    /* We hard-wire the BSP to the first CPU. */
    if (s->cpu_index == 0) {
        apic_designate_bsp(env->apic_state);
    }
    s->halted = !cpu_is_bsp(cpu);
#endif
}

