    Error *local_err = NULL;



    DPRINTF("Starting RDMA-based incoming migration\n");

    rdma = qemu_rdma_data_init(host_port, &local_err);



    if (rdma == NULL) {

        goto err;

    }



    ret = qemu_rdma_dest_init(rdma, &local_err);



    if (ret) {

        goto err;

    }



    DPRINTF("qemu_rdma_dest_init success\n");



