void arm_v7m_cpu_do_interrupt(CPUState *cs)

{

    ARMCPU *cpu = ARM_CPU(cs);

    CPUARMState *env = &cpu->env;

    uint32_t lr;



    arm_log_exception(cs->exception_index);



    /* For exceptions we just mark as pending on the NVIC, and let that

       handle it.  */

    switch (cs->exception_index) {

    case EXCP_UDEF:

        armv7m_nvic_set_pending(env->nvic, ARMV7M_EXCP_USAGE, env->v7m.secure);

        env->v7m.cfsr[env->v7m.secure] |= R_V7M_CFSR_UNDEFINSTR_MASK;

        break;

    case EXCP_NOCP:

        armv7m_nvic_set_pending(env->nvic, ARMV7M_EXCP_USAGE, env->v7m.secure);

        env->v7m.cfsr[env->v7m.secure] |= R_V7M_CFSR_NOCP_MASK;

        break;

    case EXCP_INVSTATE:

        armv7m_nvic_set_pending(env->nvic, ARMV7M_EXCP_USAGE, env->v7m.secure);

        env->v7m.cfsr[env->v7m.secure] |= R_V7M_CFSR_INVSTATE_MASK;

        break;

    case EXCP_SWI:

        /* The PC already points to the next instruction.  */

        armv7m_nvic_set_pending(env->nvic, ARMV7M_EXCP_SVC, env->v7m.secure);

        break;

    case EXCP_PREFETCH_ABORT:

    case EXCP_DATA_ABORT:

        /* Note that for M profile we don't have a guest facing FSR, but

         * the env->exception.fsr will be populated by the code that

         * raises the fault, in the A profile short-descriptor format.

         */

        switch (env->exception.fsr & 0xf) {

        case 0x8: /* External Abort */

            switch (cs->exception_index) {

            case EXCP_PREFETCH_ABORT:

                env->v7m.cfsr[M_REG_NS] |= R_V7M_CFSR_IBUSERR_MASK;

                qemu_log_mask(CPU_LOG_INT, "...with CFSR.IBUSERR\n");

                break;

            case EXCP_DATA_ABORT:

                env->v7m.cfsr[M_REG_NS] |=

                    (R_V7M_CFSR_PRECISERR_MASK | R_V7M_CFSR_BFARVALID_MASK);

                env->v7m.bfar = env->exception.vaddress;

                qemu_log_mask(CPU_LOG_INT,

                              "...with CFSR.PRECISERR and BFAR 0x%x\n",

                              env->v7m.bfar);

                break;

            }

            armv7m_nvic_set_pending(env->nvic, ARMV7M_EXCP_BUS, false);

            break;

        default:

            /* All other FSR values are either MPU faults or "can't happen

             * for M profile" cases.

             */

            switch (cs->exception_index) {

            case EXCP_PREFETCH_ABORT:

                env->v7m.cfsr[env->v7m.secure] |= R_V7M_CFSR_IACCVIOL_MASK;

                qemu_log_mask(CPU_LOG_INT, "...with CFSR.IACCVIOL\n");

                break;

            case EXCP_DATA_ABORT:

                env->v7m.cfsr[env->v7m.secure] |=

                    (R_V7M_CFSR_DACCVIOL_MASK | R_V7M_CFSR_MMARVALID_MASK);

                env->v7m.mmfar[env->v7m.secure] = env->exception.vaddress;

                qemu_log_mask(CPU_LOG_INT,

                              "...with CFSR.DACCVIOL and MMFAR 0x%x\n",

                              env->v7m.mmfar[env->v7m.secure]);

                break;

            }

            armv7m_nvic_set_pending(env->nvic, ARMV7M_EXCP_MEM,

                                    env->v7m.secure);

            break;

        }

        break;

    case EXCP_BKPT:

        if (semihosting_enabled()) {

            int nr;

            nr = arm_lduw_code(env, env->regs[15], arm_sctlr_b(env)) & 0xff;

            if (nr == 0xab) {

                env->regs[15] += 2;

                qemu_log_mask(CPU_LOG_INT,

                              "...handling as semihosting call 0x%x\n",

                              env->regs[0]);

                env->regs[0] = do_arm_semihosting(env);

                return;

            }

        }

        armv7m_nvic_set_pending(env->nvic, ARMV7M_EXCP_DEBUG, false);

        break;

    case EXCP_IRQ:

        break;

    case EXCP_EXCEPTION_EXIT:

        do_v7m_exception_exit(cpu);

        return;

    default:

        cpu_abort(cs, "Unhandled exception 0x%x\n", cs->exception_index);

        return; /* Never happens.  Keep compiler happy.  */

    }



    lr = R_V7M_EXCRET_RES1_MASK |

        R_V7M_EXCRET_S_MASK |

        R_V7M_EXCRET_DCRS_MASK |

        R_V7M_EXCRET_FTYPE_MASK |

        R_V7M_EXCRET_ES_MASK;

    if (env->v7m.control[env->v7m.secure] & R_V7M_CONTROL_SPSEL_MASK) {

        lr |= R_V7M_EXCRET_SPSEL_MASK;

    }

    if (!arm_v7m_is_handler_mode(env)) {

        lr |= R_V7M_EXCRET_MODE_MASK;

    }



    v7m_push_stack(cpu);

    v7m_exception_taken(cpu, lr);

    qemu_log_mask(CPU_LOG_INT, "... as %d\n", env->v7m.exception);

}

static void socket_sendf(int fd, const char *fmt, va_list ap)

{

    gchar *str;

    size_t size, offset;



    str = g_strdup_vprintf(fmt, ap);

    size = strlen(str);



    offset = 0;

    while (offset < size) {

        ssize_t len;



        len = write(fd, str + offset, size - offset);

        if (len == -1 && errno == EINTR) {

            continue;

        }



        g_assert_no_errno(len);

        g_assert_cmpint(len, >, 0);



        offset += len;

    }

}

int vhost_dev_init(struct vhost_dev *hdev, int devfd, bool force)

{

    uint64_t features;

    int r;

    if (devfd >= 0) {

        hdev->control = devfd;

    } else {

        hdev->control = open("/dev/vhost-net", O_RDWR);

        if (hdev->control < 0) {

            return -errno;

        }

    }

    r = ioctl(hdev->control, VHOST_SET_OWNER, NULL);

    if (r < 0) {

        goto fail;

    }



    r = ioctl(hdev->control, VHOST_GET_FEATURES, &features);

    if (r < 0) {

        goto fail;

    }

    hdev->features = features;



    hdev->client.set_memory = vhost_client_set_memory;

    hdev->client.sync_dirty_bitmap = vhost_client_sync_dirty_bitmap;

    hdev->client.migration_log = vhost_client_migration_log;

    hdev->client.log_start = NULL;

    hdev->client.log_stop = NULL;

    hdev->mem = g_malloc0(offsetof(struct vhost_memory, regions));

    hdev->log = NULL;

    hdev->log_size = 0;

    hdev->log_enabled = false;

    hdev->started = false;

    cpu_register_phys_memory_client(&hdev->client);

    hdev->force = force;

    return 0;

fail:

    r = -errno;

    close(hdev->control);

    return r;

}

static int gdb_get_spe_reg(CPUState *env, uint8_t *mem_buf, int n)

{

    if (n < 32) {

#if defined(TARGET_PPC64)

        stl_p(mem_buf, env->gpr[n] >> 32);

#else

        stl_p(mem_buf, env->gprh[n]);

#endif

        return 4;

    }

    if (n == 33) {

        stq_p(mem_buf, env->spe_acc);

        return 8;

    }

    if (n == 34) {

        /* SPEFSCR not implemented */

        memset(mem_buf, 0, 4);

        return 4;

    }

    return 0;

}

static void virtio_pci_device_unplugged(DeviceState *d)

{

    PCIDevice *pci_dev = PCI_DEVICE(d);

    VirtIOPCIProxy *proxy = VIRTIO_PCI(d);



    virtio_pci_stop_ioeventfd(proxy);

    msix_uninit_exclusive_bar(pci_dev);

}

static int virtio_pci_stop_ioeventfd(VirtIOPCIProxy *proxy)

{

    int n;



    if (!proxy->ioeventfd_started) {

        return 0;

    }



    for (n = 0; n < VIRTIO_PCI_QUEUE_MAX; n++) {

        if (!virtio_queue_get_num(proxy->vdev, n)) {

            continue;

        }



        virtio_pci_set_host_notifier_fd_handler(proxy, n, false);

        virtio_pci_set_host_notifier_internal(proxy, n, false);

    }

    proxy->ioeventfd_started = false;

    return 0;

}

static int ram_decompress_buf(RamDecompressState *s, uint8_t *buf, int len)

{

    int ret, clen;



    s->zstream.avail_out = len;

    s->zstream.next_out = buf;

    while (s->zstream.avail_out > 0) {

        if (s->zstream.avail_in == 0) {

            if (qemu_get_be16(s->f) != RAM_CBLOCK_MAGIC)

                return -1;

            clen = qemu_get_be16(s->f);

            if (clen > IOBUF_SIZE)

                return -1;

            qemu_get_buffer(s->f, s->buf, clen);

            s->zstream.avail_in = clen;

            s->zstream.next_in = s->buf;

        }

        ret = inflate(&s->zstream, Z_PARTIAL_FLUSH);

        if (ret != Z_OK && ret != Z_STREAM_END) {

            return -1;

        }

    }

    return 0;

}

