static void x86_cpu_class_check_missing_features(X86CPUClass *xcc,

                                                 strList **missing_feats)

{

    X86CPU *xc;

    FeatureWord w;

    Error *err = NULL;

    strList **next = missing_feats;



    if (xcc->kvm_required && !kvm_enabled()) {

        strList *new = g_new0(strList, 1);

        new->value = g_strdup("kvm");;

        *missing_feats = new;

        return;

    }



    xc = X86_CPU(object_new(object_class_get_name(OBJECT_CLASS(xcc))));



    x86_cpu_load_features(xc, &err);

    if (err) {

        /* Errors at x86_cpu_load_features should never happen,

         * but in case it does, just report the model as not

         * runnable at all using the "type" property.

         */

        strList *new = g_new0(strList, 1);

        new->value = g_strdup("type");

        *next = new;

        next = &new->next;

    }



    x86_cpu_filter_features(xc);



    for (w = 0; w < FEATURE_WORDS; w++) {

        uint32_t filtered = xc->filtered_features[w];

        int i;

        for (i = 0; i < 32; i++) {

            if (filtered & (1UL << i)) {

                strList *new = g_new0(strList, 1);

                new->value = g_strdup(x86_cpu_feature_name(w, i));

                *next = new;

                next = &new->next;

            }

        }

    }



    object_unref(OBJECT(xc));

}

int bdrv_flush(BlockDriverState *bs)

{

    Coroutine *co;

    RwCo rwco = {

        .bs = bs,

        .ret = NOT_DONE,

    };



    if (qemu_in_coroutine()) {

        /* Fast-path if already in coroutine context */

        bdrv_flush_co_entry(&rwco);

    } else {

        AioContext *aio_context = bdrv_get_aio_context(bs);



        co = qemu_coroutine_create(bdrv_flush_co_entry);

        qemu_coroutine_enter(co, &rwco);

        while (rwco.ret == NOT_DONE) {

            aio_poll(aio_context, true);

        }

    }



    return rwco.ret;

}

void qmp_nbd_server_start(SocketAddressLegacy *addr,

                          bool has_tls_creds, const char *tls_creds,

                          Error **errp)

{

    if (nbd_server) {

        error_setg(errp, "NBD server already running");

        return;

    }



    nbd_server = g_new0(NBDServerData, 1);

    nbd_server->watch = -1;

    nbd_server->listen_ioc = qio_channel_socket_new();

    qio_channel_set_name(QIO_CHANNEL(nbd_server->listen_ioc),

                         "nbd-listener");

    if (qio_channel_socket_listen_sync(

            nbd_server->listen_ioc, addr, errp) < 0) {

        goto error;

    }



    if (has_tls_creds) {

        nbd_server->tlscreds = nbd_get_tls_creds(tls_creds, errp);

        if (!nbd_server->tlscreds) {

            goto error;

        }



        /* TODO SOCKET_ADDRESS_LEGACY_KIND_FD where fd has AF_INET or AF_INET6 */

        if (addr->type != SOCKET_ADDRESS_LEGACY_KIND_INET) {

            error_setg(errp, "TLS is only supported with IPv4/IPv6");

            goto error;

        }

    }



    nbd_server->watch = qio_channel_add_watch(

        QIO_CHANNEL(nbd_server->listen_ioc),

        G_IO_IN,

        nbd_accept,

        NULL,

        NULL);



    return;



 error:

    nbd_server_free(nbd_server);

    nbd_server = NULL;

}

vubr_backend_recv_cb(int sock, void *ctx)

{

    VubrDev *vubr = (VubrDev *) ctx;

    VuDev *dev = &vubr->vudev;

    VuVirtq *vq = vu_get_queue(dev, 0);

    VuVirtqElement *elem = NULL;

    struct iovec mhdr_sg[VIRTQUEUE_MAX_SIZE];

    struct virtio_net_hdr_mrg_rxbuf mhdr;

    unsigned mhdr_cnt = 0;

    int hdrlen = vubr->hdrlen;

    int i = 0;

    struct virtio_net_hdr hdr = {

        .flags = 0,

        .gso_type = VIRTIO_NET_HDR_GSO_NONE

    };



    DPRINT("\n\n   ***   IN UDP RECEIVE CALLBACK    ***\n\n");

    DPRINT("    hdrlen = %d\n", hdrlen);



    if (!vu_queue_enabled(dev, vq) ||

        !vu_queue_started(dev, vq) ||

        !vu_queue_avail_bytes(dev, vq, hdrlen, 0)) {

        DPRINT("Got UDP packet, but no available descriptors on RX virtq.\n");

        return;

    }



    do {

        struct iovec *sg;

        ssize_t ret, total = 0;

        unsigned int num;



        elem = vu_queue_pop(dev, vq, sizeof(VuVirtqElement));

        if (!elem) {

            break;

        }



        if (elem->in_num < 1) {

            fprintf(stderr, "virtio-net contains no in buffers\n");

            break;

        }



        sg = elem->in_sg;

        num = elem->in_num;

        if (i == 0) {

            if (hdrlen == 12) {

                mhdr_cnt = iov_copy(mhdr_sg, ARRAY_SIZE(mhdr_sg),

                                    sg, elem->in_num,

                                    offsetof(typeof(mhdr), num_buffers),

                                    sizeof(mhdr.num_buffers));

            }

            iov_from_buf(sg, elem->in_num, 0, &hdr, sizeof hdr);

            total += hdrlen;

            ret = iov_discard_front(&sg, &num, hdrlen);

            assert(ret == hdrlen);

        }



        struct msghdr msg = {

            .msg_name = (struct sockaddr *) &vubr->backend_udp_dest,

            .msg_namelen = sizeof(struct sockaddr_in),

            .msg_iov = sg,

            .msg_iovlen = elem->in_num,

            .msg_flags = MSG_DONTWAIT,

        };

        do {

            ret = recvmsg(vubr->backend_udp_sock, &msg, 0);

        } while (ret == -1 && (errno == EINTR));



        if (i == 0) {

            iov_restore_front(elem->in_sg, sg, hdrlen);

        }



        if (ret == -1) {

            if (errno == EWOULDBLOCK) {

                vu_queue_rewind(dev, vq, 1);

                break;

            }



            vubr_die("recvmsg()");

        }



        total += ret;

        iov_truncate(elem->in_sg, elem->in_num, total);

        vu_queue_fill(dev, vq, elem, total, i++);



        free(elem);

        elem = NULL;

    } while (false); /* could loop if DONTWAIT worked? */



    if (mhdr_cnt) {

        mhdr.num_buffers = i;

        iov_from_buf(mhdr_sg, mhdr_cnt,

                     0,

                     &mhdr.num_buffers, sizeof mhdr.num_buffers);

    }



    vu_queue_flush(dev, vq, i);

    vu_queue_notify(dev, vq);



    free(elem);

}

static int qemu_rdma_exchange_send(RDMAContext *rdma, RDMAControlHeader *head,

                                   uint8_t *data, RDMAControlHeader *resp,

                                   int *resp_idx,

                                   int (*callback)(RDMAContext *rdma))

{

    int ret = 0;



    /*

     * Wait until the dest is ready before attempting to deliver the message

     * by waiting for a READY message.

     */

    if (rdma->control_ready_expected) {

        RDMAControlHeader resp;

        ret = qemu_rdma_exchange_get_response(rdma,

                                    &resp, RDMA_CONTROL_READY, RDMA_WRID_READY);

        if (ret < 0) {

            return ret;

        }

    }



    /*

     * If the user is expecting a response, post a WR in anticipation of it.

     */

    if (resp) {

        ret = qemu_rdma_post_recv_control(rdma, RDMA_WRID_DATA);

        if (ret) {

            fprintf(stderr, "rdma migration: error posting"

                    " extra control recv for anticipated result!");

            return ret;

        }

    }



    /*

     * Post a WR to replace the one we just consumed for the READY message.

     */

    ret = qemu_rdma_post_recv_control(rdma, RDMA_WRID_READY);

    if (ret) {

        fprintf(stderr, "rdma migration: error posting first control recv!");

        return ret;

    }



    /*

     * Deliver the control message that was requested.

     */

    ret = qemu_rdma_post_send_control(rdma, data, head);



    if (ret < 0) {

        fprintf(stderr, "Failed to send control buffer!\n");

        return ret;

    }



    /*

     * If we're expecting a response, block and wait for it.

     */

    if (resp) {

        if (callback) {

            DDPRINTF("Issuing callback before receiving response...\n");

            ret = callback(rdma);

            if (ret < 0) {

                return ret;

            }

        }



        DDPRINTF("Waiting for response %s\n", control_desc[resp->type]);

        ret = qemu_rdma_exchange_get_response(rdma, resp,

                                              resp->type, RDMA_WRID_DATA);



        if (ret < 0) {

            return ret;

        }



        qemu_rdma_move_header(rdma, RDMA_WRID_DATA, resp);

        if (resp_idx) {

            *resp_idx = RDMA_WRID_DATA;

        }

        DDPRINTF("Response %s received.\n", control_desc[resp->type]);

    }



    rdma->control_ready_expected = 1;



    return 0;

}

static int configure_accelerator(void)

{

    const char *p = NULL;

    char buf[10];

    int i, ret;

    bool accel_initialised = false;

    bool init_failed = false;



    QemuOptsList *list = qemu_find_opts("machine");

    if (!QTAILQ_EMPTY(&list->head)) {

        p = qemu_opt_get(QTAILQ_FIRST(&list->head), "accel");

    }



    if (p == NULL) {

        /* Use the default "accelerator", tcg */

        p = "tcg";

    }



    while (!accel_initialised && *p != '\0') {

        if (*p == ':') {

            p++;

        }

        p = get_opt_name(buf, sizeof (buf), p, ':');

        for (i = 0; i < ARRAY_SIZE(accel_list); i++) {

            if (strcmp(accel_list[i].opt_name, buf) == 0) {

                if (!accel_list[i].available()) {

                    printf("%s not supported for this target\n",

                           accel_list[i].name);

                    continue;

                }

                *(accel_list[i].allowed) = true;

                ret = accel_list[i].init();

                if (ret < 0) {

                    init_failed = true;

                    fprintf(stderr, "failed to initialize %s: %s\n",

                            accel_list[i].name,

                            strerror(-ret));

                    *(accel_list[i].allowed) = false;

                } else {

                    accel_initialised = true;

                }

                break;

            }

        }

        if (i == ARRAY_SIZE(accel_list)) {

            fprintf(stderr, "\"%s\" accelerator does not exist.\n", buf);

        }

    }



    if (!accel_initialised) {

        if (!init_failed) {

            fprintf(stderr, "No accelerator found!\n");

        }

        exit(1);

    }



    if (init_failed) {

        fprintf(stderr, "Back to %s accelerator.\n", accel_list[i].name);

    }



    return !accel_initialised;

}

