void cpu_loop(CPUCRISState *env)

{

    CPUState *cs = CPU(cris_env_get_cpu(env));

    int trapnr, ret;

    target_siginfo_t info;



    while (1) {

        cpu_exec_start(cs);

        trapnr = cpu_cris_exec(cs);

        cpu_exec_end(cs);

        switch (trapnr) {

        case 0xaa:

            {

                info.si_signo = TARGET_SIGSEGV;

                info.si_errno = 0;

                /* XXX: check env->error_code */

                info.si_code = TARGET_SEGV_MAPERR;

                info._sifields._sigfault._addr = env->pregs[PR_EDA];

                queue_signal(env, info.si_signo, &info);

            }

            break;

	case EXCP_INTERRUPT:

	  /* just indicate that signals should be handled asap */

	  break;

        case EXCP_BREAK:

            ret = do_syscall(env, 

                             env->regs[9], 

                             env->regs[10], 

                             env->regs[11], 

                             env->regs[12], 

                             env->regs[13], 

                             env->pregs[7], 

                             env->pregs[11],

                             0, 0);

            env->regs[10] = ret;

            break;

        case EXCP_DEBUG:

            {

                int sig;



                sig = gdb_handlesig(cs, TARGET_SIGTRAP);

                if (sig)

                  {

                    info.si_signo = sig;

                    info.si_errno = 0;

                    info.si_code = TARGET_TRAP_BRKPT;

                    queue_signal(env, info.si_signo, &info);

                  }

            }

            break;

        default:

            printf ("Unhandled trap: 0x%x\n", trapnr);

            cpu_dump_state(cs, stderr, fprintf, 0);

            exit(EXIT_FAILURE);

        }

        process_pending_signals (env);

    }

}

static void tlb_info_32(Monitor *mon, CPUState *env)

{

    int l1, l2;

    uint32_t pgd, pde, pte;



    pgd = env->cr[3] & ~0xfff;

    for(l1 = 0; l1 < 1024; l1++) {

        cpu_physical_memory_read(pgd + l1 * 4, &pde, 4);

        pde = le32_to_cpu(pde);

        if (pde & PG_PRESENT_MASK) {

            if ((pde & PG_PSE_MASK) && (env->cr[4] & CR4_PSE_MASK)) {

                /* 4M pages */

                print_pte(mon, (l1 << 22), pde, ~((1 << 21) - 1));

            } else {

                for(l2 = 0; l2 < 1024; l2++) {

                    cpu_physical_memory_read((pde & ~0xfff) + l2 * 4, &pte, 4);

                    pte = le32_to_cpu(pte);

                    if (pte & PG_PRESENT_MASK) {

                        print_pte(mon, (l1 << 22) + (l2 << 12),

                                  pte & ~PG_PSE_MASK,

                                  ~0xfff);

                    }

                }

            }

        }

    }

}

void parse_option_size(const char *name, const char *value,

                       uint64_t *ret, Error **errp)

{

    uint64_t size;

    int err;



    err = qemu_strtosz(value, NULL, &size);

    if (err == -ERANGE) {

        error_setg(errp, "Value '%s' is too large for parameter '%s'",

                   value, name);

        return;

    }

    if (err) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE, name,

                   "a non-negative number below 2^64");

        error_append_hint(errp, "Optional suffix k, M, G, T, P or E means"

                          " kilo-, mega-, giga-, tera-, peta-\n"

                          "and exabytes, respectively.\n");

        return;

    }

    *ret = size;

}

static int get_physical_addr_mmu(CPUXtensaState *env, bool update_tlb,

        uint32_t vaddr, int is_write, int mmu_idx,

        uint32_t *paddr, uint32_t *page_size, unsigned *access,

        bool may_lookup_pt)

{

    bool dtlb = is_write != 2;

    uint32_t wi;

    uint32_t ei;

    uint8_t ring;

    uint32_t vpn;

    uint32_t pte;

    const xtensa_tlb_entry *entry = NULL;

    xtensa_tlb_entry tmp_entry;

    int ret = xtensa_tlb_lookup(env, vaddr, dtlb, &wi, &ei, &ring);



    if ((ret == INST_TLB_MISS_CAUSE || ret == LOAD_STORE_TLB_MISS_CAUSE) &&

            may_lookup_pt && get_pte(env, vaddr, &pte) == 0) {

        ring = (pte >> 4) & 0x3;

        wi = 0;

        split_tlb_entry_spec_way(env, vaddr, dtlb, &vpn, wi, &ei);



        if (update_tlb) {

            wi = ++env->autorefill_idx & 0x3;

            xtensa_tlb_set_entry(env, dtlb, wi, ei, vpn, pte);

            env->sregs[EXCVADDR] = vaddr;

            qemu_log("%s: autorefill(%08x): %08x -> %08x\n",

                    __func__, vaddr, vpn, pte);

        } else {

            xtensa_tlb_set_entry_mmu(env, &tmp_entry, dtlb, wi, ei, vpn, pte);

            entry = &tmp_entry;

        }

        ret = 0;

    }

    if (ret != 0) {

        return ret;

    }



    if (entry == NULL) {

        entry = xtensa_tlb_get_entry(env, dtlb, wi, ei);

    }



    if (ring < mmu_idx) {

        return dtlb ?

            LOAD_STORE_PRIVILEGE_CAUSE :

            INST_FETCH_PRIVILEGE_CAUSE;

    }



    *access = mmu_attr_to_access(entry->attr);

    if (!is_access_granted(*access, is_write)) {

        return dtlb ?

            (is_write ?

             STORE_PROHIBITED_CAUSE :

             LOAD_PROHIBITED_CAUSE) :

            INST_FETCH_PROHIBITED_CAUSE;

    }



    *paddr = entry->paddr | (vaddr & ~xtensa_tlb_get_addr_mask(env, dtlb, wi));

    *page_size = ~xtensa_tlb_get_addr_mask(env, dtlb, wi) + 1;



    return 0;

}

e1000e_intrmgr_delay_rx_causes(E1000ECore *core, uint32_t *causes)

{

    uint32_t delayable_causes;

    uint32_t rdtr = core->mac[RDTR];

    uint32_t radv = core->mac[RADV];

    uint32_t raid = core->mac[RAID];



    if (msix_enabled(core->owner)) {

        return false;

    }



    delayable_causes = E1000_ICR_RXQ0 |

                       E1000_ICR_RXQ1 |

                       E1000_ICR_RXT0;



    if (!(core->mac[RFCTL] & E1000_RFCTL_ACK_DIS)) {

        delayable_causes |= E1000_ICR_ACK;

    }



    /* Clean up all causes that may be delayed */

    core->delayed_causes |= *causes & delayable_causes;

    *causes &= ~delayable_causes;



    /* Check if delayed RX interrupts disabled by client

       or if there are causes that cannot be delayed */

    if ((rdtr == 0) || (causes != 0)) {

        return false;

    }



    /* Check if delayed RX ACK interrupts disabled by client

       and there is an ACK packet received */

    if ((raid == 0) && (core->delayed_causes & E1000_ICR_ACK)) {

        return false;

    }



    /* All causes delayed */

    e1000e_intrmgr_rearm_timer(&core->rdtr);



    if (!core->radv.running && (radv != 0)) {

        e1000e_intrmgr_rearm_timer(&core->radv);

    }



    if (!core->raid.running && (core->delayed_causes & E1000_ICR_ACK)) {

        e1000e_intrmgr_rearm_timer(&core->raid);

    }



    return true;

}

static int virtio_ccw_cb(SubchDev *sch, CCW1 ccw)

{

    int ret;

    VirtioRevInfo revinfo;

    uint8_t status;

    VirtioFeatDesc features;

    void *config;

    hwaddr indicators;

    VqConfigBlock vq_config;

    VirtioCcwDevice *dev = sch->driver_data;

    VirtIODevice *vdev = virtio_ccw_get_vdev(sch);

    bool check_len;

    int len;

    hwaddr hw_len;

    VirtioThinintInfo *thinint;



    if (!dev) {

        return -EINVAL;

    }



    trace_virtio_ccw_interpret_ccw(sch->cssid, sch->ssid, sch->schid,

                                   ccw.cmd_code);

    check_len = !((ccw.flags & CCW_FLAG_SLI) && !(ccw.flags & CCW_FLAG_DC));



    if (dev->force_revision_1 && dev->revision < 0 &&

        ccw.cmd_code != CCW_CMD_SET_VIRTIO_REV) {

        /*

         * virtio-1 drivers must start with negotiating to a revision >= 1,

         * so post a command reject for all other commands

         */

        return -ENOSYS;

    }



    /* Look at the command. */

    switch (ccw.cmd_code) {

    case CCW_CMD_SET_VQ:

        ret = virtio_ccw_handle_set_vq(sch, ccw, check_len, dev->revision < 1);

        break;

    case CCW_CMD_VDEV_RESET:

        virtio_ccw_reset_virtio(dev, vdev);

        ret = 0;

        break;

    case CCW_CMD_READ_FEAT:

        if (check_len) {

            if (ccw.count != sizeof(features)) {

                ret = -EINVAL;

                break;

            }

        } else if (ccw.count < sizeof(features)) {

            /* Can't execute command. */

            ret = -EINVAL;

            break;

        }

        if (!ccw.cda) {

            ret = -EFAULT;

        } else {

            VirtioDeviceClass *vdc = VIRTIO_DEVICE_GET_CLASS(vdev);



            features.index = address_space_ldub(&address_space_memory,

                                                ccw.cda

                                                + sizeof(features.features),

                                                MEMTXATTRS_UNSPECIFIED,

                                                NULL);

            if (features.index == 0) {

                if (dev->revision >= 1) {

                    /* Don't offer legacy features for modern devices. */

                    features.features = (uint32_t)

                        (vdev->host_features & ~vdc->legacy_features);

                } else {

                    features.features = (uint32_t)vdev->host_features;

                }

            } else if ((features.index == 1) && (dev->revision >= 1)) {

                /*

                 * Only offer feature bits beyond 31 if the guest has

                 * negotiated at least revision 1.

                 */

                features.features = (uint32_t)(vdev->host_features >> 32);

            } else {

                /* Return zeroes if the guest supports more feature bits. */

                features.features = 0;

            }

            address_space_stl_le(&address_space_memory, ccw.cda,

                                 features.features, MEMTXATTRS_UNSPECIFIED,

                                 NULL);

            sch->curr_status.scsw.count = ccw.count - sizeof(features);

            ret = 0;

        }

        break;

    case CCW_CMD_WRITE_FEAT:

        if (check_len) {

            if (ccw.count != sizeof(features)) {

                ret = -EINVAL;

                break;

            }

        } else if (ccw.count < sizeof(features)) {

            /* Can't execute command. */

            ret = -EINVAL;

            break;

        }

        if (!ccw.cda) {

            ret = -EFAULT;

        } else {

            features.index = address_space_ldub(&address_space_memory,

                                                ccw.cda

                                                + sizeof(features.features),

                                                MEMTXATTRS_UNSPECIFIED,

                                                NULL);

            features.features = address_space_ldl_le(&address_space_memory,

                                                     ccw.cda,

                                                     MEMTXATTRS_UNSPECIFIED,

                                                     NULL);

            if (features.index == 0) {

                virtio_set_features(vdev,

                                    (vdev->guest_features & 0xffffffff00000000ULL) |

                                    features.features);

            } else if ((features.index == 1) && (dev->revision >= 1)) {

                /*

                 * If the guest did not negotiate at least revision 1,

                 * we did not offer it any feature bits beyond 31. Such a

                 * guest passing us any bit here is therefore buggy.

                 */

                virtio_set_features(vdev,

                                    (vdev->guest_features & 0x00000000ffffffffULL) |

                                    ((uint64_t)features.features << 32));

            } else {

                /*

                 * If the guest supports more feature bits, assert that it

                 * passes us zeroes for those we don't support.

                 */

                if (features.features) {

                    fprintf(stderr, "Guest bug: features[%i]=%x (expected 0)\n",

                            features.index, features.features);

                    /* XXX: do a unit check here? */

                }

            }

            sch->curr_status.scsw.count = ccw.count - sizeof(features);

            ret = 0;

        }

        break;

    case CCW_CMD_READ_CONF:

        if (check_len) {

            if (ccw.count > vdev->config_len) {

                ret = -EINVAL;

                break;

            }

        }

        len = MIN(ccw.count, vdev->config_len);

        if (!ccw.cda) {

            ret = -EFAULT;

        } else {

            virtio_bus_get_vdev_config(&dev->bus, vdev->config);

            cpu_physical_memory_write(ccw.cda, vdev->config, len);

            sch->curr_status.scsw.count = ccw.count - len;

            ret = 0;

        }

        break;

    case CCW_CMD_WRITE_CONF:

        if (check_len) {

            if (ccw.count > vdev->config_len) {

                ret = -EINVAL;

                break;

            }

        }

        len = MIN(ccw.count, vdev->config_len);

        hw_len = len;

        if (!ccw.cda) {

            ret = -EFAULT;

        } else {

            config = cpu_physical_memory_map(ccw.cda, &hw_len, 0);

            if (!config) {

                ret = -EFAULT;

            } else {

                len = hw_len;

                memcpy(vdev->config, config, len);

                cpu_physical_memory_unmap(config, hw_len, 0, hw_len);

                virtio_bus_set_vdev_config(&dev->bus, vdev->config);

                sch->curr_status.scsw.count = ccw.count - len;

                ret = 0;

            }

        }

        break;

    case CCW_CMD_READ_STATUS:

        if (check_len) {

            if (ccw.count != sizeof(status)) {

                ret = -EINVAL;

                break;

            }

        } else if (ccw.count < sizeof(status)) {

            /* Can't execute command. */

            ret = -EINVAL;

            break;

        }

        if (!ccw.cda) {

            ret = -EFAULT;

        } else {

            address_space_stb(&address_space_memory, ccw.cda, vdev->status,

                                        MEMTXATTRS_UNSPECIFIED, NULL);

            sch->curr_status.scsw.count = ccw.count - sizeof(vdev->status);;

            ret = 0;

        }

        break;

    case CCW_CMD_WRITE_STATUS:

        if (check_len) {

            if (ccw.count != sizeof(status)) {

                ret = -EINVAL;

                break;

            }

        } else if (ccw.count < sizeof(status)) {

            /* Can't execute command. */

            ret = -EINVAL;

            break;

        }

        if (!ccw.cda) {

            ret = -EFAULT;

        } else {

            status = address_space_ldub(&address_space_memory, ccw.cda,

                                        MEMTXATTRS_UNSPECIFIED, NULL);

            if (!(status & VIRTIO_CONFIG_S_DRIVER_OK)) {

                virtio_ccw_stop_ioeventfd(dev);

            }

            if (virtio_set_status(vdev, status) == 0) {

                if (vdev->status == 0) {

                    virtio_ccw_reset_virtio(dev, vdev);

                }

                if (status & VIRTIO_CONFIG_S_DRIVER_OK) {

                    virtio_ccw_start_ioeventfd(dev);

                }

                sch->curr_status.scsw.count = ccw.count - sizeof(status);

                ret = 0;

            } else {

                /* Trigger a command reject. */

                ret = -ENOSYS;

            }

        }

        break;

    case CCW_CMD_SET_IND:

        if (check_len) {

            if (ccw.count != sizeof(indicators)) {

                ret = -EINVAL;

                break;

            }

        } else if (ccw.count < sizeof(indicators)) {

            /* Can't execute command. */

            ret = -EINVAL;

            break;

        }

        if (sch->thinint_active) {

            /* Trigger a command reject. */

            ret = -ENOSYS;

            break;

        }

        if (virtio_get_num_queues(vdev) > NR_CLASSIC_INDICATOR_BITS) {

            /* More queues than indicator bits --> trigger a reject */

            ret = -ENOSYS;

            break;

        }

        if (!ccw.cda) {

            ret = -EFAULT;

        } else {

            indicators = address_space_ldq_be(&address_space_memory, ccw.cda,

                                              MEMTXATTRS_UNSPECIFIED, NULL);

            dev->indicators = get_indicator(indicators, sizeof(uint64_t));

            sch->curr_status.scsw.count = ccw.count - sizeof(indicators);

            ret = 0;

        }

        break;

    case CCW_CMD_SET_CONF_IND:

        if (check_len) {

            if (ccw.count != sizeof(indicators)) {

                ret = -EINVAL;

                break;

            }

        } else if (ccw.count < sizeof(indicators)) {

            /* Can't execute command. */

            ret = -EINVAL;

            break;

        }

        if (!ccw.cda) {

            ret = -EFAULT;

        } else {

            indicators = address_space_ldq_be(&address_space_memory, ccw.cda,

                                              MEMTXATTRS_UNSPECIFIED, NULL);

            dev->indicators2 = get_indicator(indicators, sizeof(uint64_t));

            sch->curr_status.scsw.count = ccw.count - sizeof(indicators);

            ret = 0;

        }

        break;

    case CCW_CMD_READ_VQ_CONF:

        if (check_len) {

            if (ccw.count != sizeof(vq_config)) {

                ret = -EINVAL;

                break;

            }

        } else if (ccw.count < sizeof(vq_config)) {

            /* Can't execute command. */

            ret = -EINVAL;

            break;

        }

        if (!ccw.cda) {

            ret = -EFAULT;

        } else {

            vq_config.index = address_space_lduw_be(&address_space_memory,

                                                    ccw.cda,

                                                    MEMTXATTRS_UNSPECIFIED,

                                                    NULL);

            if (vq_config.index >= VIRTIO_QUEUE_MAX) {

                ret = -EINVAL;

                break;

            }

            vq_config.num_max = virtio_queue_get_num(vdev,

                                                     vq_config.index);

            address_space_stw_be(&address_space_memory,

                                 ccw.cda + sizeof(vq_config.index),

                                 vq_config.num_max,

                                 MEMTXATTRS_UNSPECIFIED,

                                 NULL);

            sch->curr_status.scsw.count = ccw.count - sizeof(vq_config);

            ret = 0;

        }

        break;

    case CCW_CMD_SET_IND_ADAPTER:

        if (check_len) {

            if (ccw.count != sizeof(*thinint)) {

                ret = -EINVAL;

                break;

            }

        } else if (ccw.count < sizeof(*thinint)) {

            /* Can't execute command. */

            ret = -EINVAL;

            break;

        }

        len = sizeof(*thinint);

        hw_len = len;

        if (!ccw.cda) {

            ret = -EFAULT;

        } else if (dev->indicators && !sch->thinint_active) {

            /* Trigger a command reject. */

            ret = -ENOSYS;

        } else {

            thinint = cpu_physical_memory_map(ccw.cda, &hw_len, 0);

            if (!thinint) {

                ret = -EFAULT;

            } else {

                uint64_t ind_bit = ldq_be_p(&thinint->ind_bit);



                len = hw_len;

                dev->summary_indicator =

                    get_indicator(ldq_be_p(&thinint->summary_indicator),

                                  sizeof(uint8_t));

                dev->indicators =

                    get_indicator(ldq_be_p(&thinint->device_indicator),

                                  ind_bit / 8 + 1);

                dev->thinint_isc = thinint->isc;

                dev->routes.adapter.ind_offset = ind_bit;

                dev->routes.adapter.summary_offset = 7;

                cpu_physical_memory_unmap(thinint, hw_len, 0, hw_len);

                dev->routes.adapter.adapter_id = css_get_adapter_id(

                                                 CSS_IO_ADAPTER_VIRTIO,

                                                 dev->thinint_isc);

                sch->thinint_active = ((dev->indicators != NULL) &&

                                       (dev->summary_indicator != NULL));

                sch->curr_status.scsw.count = ccw.count - len;

                ret = 0;

            }

        }

        break;

    case CCW_CMD_SET_VIRTIO_REV:

        len = sizeof(revinfo);

        if (ccw.count < len) {

            ret = -EINVAL;

            break;

        }

        if (!ccw.cda) {

            ret = -EFAULT;

            break;

        }

        revinfo.revision =

            address_space_lduw_be(&address_space_memory, ccw.cda,

                                  MEMTXATTRS_UNSPECIFIED, NULL);

        revinfo.length =

            address_space_lduw_be(&address_space_memory,

                                  ccw.cda + sizeof(revinfo.revision),

                                  MEMTXATTRS_UNSPECIFIED, NULL);

        if (ccw.count < len + revinfo.length ||

            (check_len && ccw.count > len + revinfo.length)) {

            ret = -EINVAL;

            break;

        }

        /*

         * Once we start to support revisions with additional data, we'll

         * need to fetch it here. Nothing to do for now, though.

         */

        if (dev->revision >= 0 ||

            revinfo.revision > virtio_ccw_rev_max(dev) ||

            (dev->force_revision_1 && !revinfo.revision)) {

            ret = -ENOSYS;

            break;

        }

        ret = 0;

        dev->revision = revinfo.revision;

        break;

    default:

        ret = -ENOSYS;

        break;

    }

    return ret;

}

AioContext *aio_context_new(Error **errp)

{

    int ret;

    AioContext *ctx;



    ctx = (AioContext *) g_source_new(&aio_source_funcs, sizeof(AioContext));

    aio_context_setup(ctx);



    ret = event_notifier_init(&ctx->notifier, false);

    if (ret < 0) {

        error_setg_errno(errp, -ret, "Failed to initialize event notifier");

        goto fail;

    }

    g_source_set_can_recurse(&ctx->source, true);

    qemu_lockcnt_init(&ctx->list_lock);

    aio_set_event_notifier(ctx, &ctx->notifier,

                           false,

                           (EventNotifierHandler *)

                           event_notifier_dummy_cb,

                           event_notifier_poll);

#ifdef CONFIG_LINUX_AIO

    ctx->linux_aio = NULL;

#endif

    ctx->thread_pool = NULL;

    qemu_rec_mutex_init(&ctx->lock);

    timerlistgroup_init(&ctx->tlg, aio_timerlist_notify, ctx);



    ctx->poll_ns = 0;

    ctx->poll_max_ns = 0;

    ctx->poll_grow = 0;

    ctx->poll_shrink = 0;



    return ctx;

fail:

    g_source_destroy(&ctx->source);

    return NULL;

}

static int mp_user_setxattr(FsContext *ctx, const char *path, const char *name,

                            void *value, size_t size, int flags)

{

    char buffer[PATH_MAX];

    if (strncmp(name, "user.virtfs.", 12) == 0) {

        /*

         * Don't allow fetch of user.virtfs namesapce

         * in case of mapped security

         */

        errno = EACCES;

        return -1;

    }

    return lsetxattr(rpath(ctx, path, buffer), name, value, size, flags);

}

static int openpic_init(SysBusDevice *dev)

{

    OpenPICState *opp = FROM_SYSBUS(typeof (*opp), dev);

    int i, j;

    MemReg list_le[] = {

        {"glb", &openpic_glb_ops_le, true,

                OPENPIC_GLB_REG_START, OPENPIC_GLB_REG_SIZE},

        {"tmr", &openpic_tmr_ops_le, true,

                OPENPIC_TMR_REG_START, OPENPIC_TMR_REG_SIZE},

        {"msi", &openpic_msi_ops_le, true,

                OPENPIC_MSI_REG_START, OPENPIC_MSI_REG_SIZE},

        {"src", &openpic_src_ops_le, true,

                OPENPIC_SRC_REG_START, OPENPIC_SRC_REG_SIZE},

        {"cpu", &openpic_cpu_ops_le, true,

                OPENPIC_CPU_REG_START, OPENPIC_CPU_REG_SIZE},

    };

    MemReg list_be[] = {

        {"glb", &openpic_glb_ops_be, true,

                OPENPIC_GLB_REG_START, OPENPIC_GLB_REG_SIZE},

        {"tmr", &openpic_tmr_ops_be, true,

                OPENPIC_TMR_REG_START, OPENPIC_TMR_REG_SIZE},

        {"msi", &openpic_msi_ops_be, true,

                OPENPIC_MSI_REG_START, OPENPIC_MSI_REG_SIZE},

        {"src", &openpic_src_ops_be, true,

                OPENPIC_SRC_REG_START, OPENPIC_SRC_REG_SIZE},

        {"cpu", &openpic_cpu_ops_be, true,

                OPENPIC_CPU_REG_START, OPENPIC_CPU_REG_SIZE},

    };

    MemReg *list;



    switch (opp->model) {

    case OPENPIC_MODEL_FSL_MPIC_20:

    default:

        opp->flags |= OPENPIC_FLAG_IDR_CRIT;

        opp->nb_irqs = 80;

        opp->vid = VID_REVISION_1_2;

        opp->vir = VIR_GENERIC;

        opp->vector_mask = 0xFFFF;

        opp->tfrr_reset = 0;

        opp->ivpr_reset = IVPR_MASK_MASK;

        opp->idr_reset = 1 << 0;

        opp->max_irq = FSL_MPIC_20_MAX_IRQ;

        opp->irq_ipi0 = FSL_MPIC_20_IPI_IRQ;

        opp->irq_tim0 = FSL_MPIC_20_TMR_IRQ;

        opp->irq_msi = FSL_MPIC_20_MSI_IRQ;

        opp->brr1 = FSL_BRR1_IPID | FSL_BRR1_IPMJ | FSL_BRR1_IPMN;

        /* XXX really only available as of MPIC 4.0 */

        opp->mpic_mode_mask = GCR_MODE_PROXY;



        msi_supported = true;

        list = list_be;



        for (i = 0; i < FSL_MPIC_20_MAX_EXT; i++) {

            opp->src[i].level = false;

        }



        /* Internal interrupts, including message and MSI */

        for (i = 16; i < MAX_SRC; i++) {

            opp->src[i].type = IRQ_TYPE_FSLINT;

            opp->src[i].level = true;

        }



        /* timers and IPIs */

        for (i = MAX_SRC; i < MAX_IRQ; i++) {

            opp->src[i].type = IRQ_TYPE_FSLSPECIAL;

            opp->src[i].level = false;

        }



        break;



    case OPENPIC_MODEL_RAVEN:

        opp->nb_irqs = RAVEN_MAX_EXT;

        opp->vid = VID_REVISION_1_3;

        opp->vir = VIR_GENERIC;

        opp->vector_mask = 0xFF;

        opp->tfrr_reset = 4160000;

        opp->ivpr_reset = IVPR_MASK_MASK | IVPR_MODE_MASK;

        opp->idr_reset = 0;

        opp->max_irq = RAVEN_MAX_IRQ;

        opp->irq_ipi0 = RAVEN_IPI_IRQ;

        opp->irq_tim0 = RAVEN_TMR_IRQ;

        opp->brr1 = -1;

        opp->mpic_mode_mask = GCR_MODE_MIXED;

        list = list_le;

        /* Don't map MSI region */

        list[2].map = false;



        /* Only UP supported today */

        if (opp->nb_cpus != 1) {

            return -EINVAL;

        }

        break;

    }



    memory_region_init(&opp->mem, "openpic", 0x40000);



    for (i = 0; i < ARRAY_SIZE(list_le); i++) {

        if (!list[i].map) {

            continue;

        }



        memory_region_init_io(&opp->sub_io_mem[i], list[i].ops, opp,

                              list[i].name, list[i].size);



        memory_region_add_subregion(&opp->mem, list[i].start_addr,

                                    &opp->sub_io_mem[i]);

    }



    for (i = 0; i < opp->nb_cpus; i++) {

        opp->dst[i].irqs = g_new(qemu_irq, OPENPIC_OUTPUT_NB);

        for (j = 0; j < OPENPIC_OUTPUT_NB; j++) {

            sysbus_init_irq(dev, &opp->dst[i].irqs[j]);

        }

    }



    register_savevm(&opp->busdev.qdev, "openpic", 0, 2,

                    openpic_save, openpic_load, opp);



    sysbus_init_mmio(dev, &opp->mem);

    qdev_init_gpio_in(&dev->qdev, openpic_set_irq, opp->max_irq);



    return 0;

}

static void do_info_profile(Monitor *mon)

{

    int64_t total;

    total = qemu_time;

    if (total == 0)

        total = 1;

    monitor_printf(mon, "async time  %" PRId64 " (%0.3f)\n",

                   dev_time, dev_time / (double)ticks_per_sec);

    monitor_printf(mon, "qemu time   %" PRId64 " (%0.3f)\n",

                   qemu_time, qemu_time / (double)ticks_per_sec);

