void cpu_dump_state (CPUState *env, FILE *f, fprintf_function cpu_fprintf,

                     int flags)

{

#define RGPL  4

#define RFPL  4



    int i;



    cpu_fprintf(f, "NIP " TARGET_FMT_lx "   LR " TARGET_FMT_lx " CTR "

                TARGET_FMT_lx " XER " TARGET_FMT_lx "\n",

                env->nip, env->lr, env->ctr, env->xer);

    cpu_fprintf(f, "MSR " TARGET_FMT_lx " HID0 " TARGET_FMT_lx "  HF "

                TARGET_FMT_lx " idx %d\n", env->msr, env->spr[SPR_HID0],

                env->hflags, env->mmu_idx);

#if !defined(NO_TIMER_DUMP)

    cpu_fprintf(f, "TB %08" PRIu32 " %08" PRIu64

#if !defined(CONFIG_USER_ONLY)

                " DECR %08" PRIu32

#endif

                "\n",

                cpu_ppc_load_tbu(env), cpu_ppc_load_tbl(env)

#if !defined(CONFIG_USER_ONLY)

                , cpu_ppc_load_decr(env)

#endif

                );

#endif

    for (i = 0; i < 32; i++) {

        if ((i & (RGPL - 1)) == 0)

            cpu_fprintf(f, "GPR%02d", i);

        cpu_fprintf(f, " %016" PRIx64, ppc_dump_gpr(env, i));

        if ((i & (RGPL - 1)) == (RGPL - 1))

            cpu_fprintf(f, "\n");

    }

    cpu_fprintf(f, "CR ");

    for (i = 0; i < 8; i++)

        cpu_fprintf(f, "%01x", env->crf[i]);

    cpu_fprintf(f, "  [");

    for (i = 0; i < 8; i++) {

        char a = '-';

        if (env->crf[i] & 0x08)

            a = 'L';

        else if (env->crf[i] & 0x04)

            a = 'G';

        else if (env->crf[i] & 0x02)

            a = 'E';

        cpu_fprintf(f, " %c%c", a, env->crf[i] & 0x01 ? 'O' : ' ');

    }

    cpu_fprintf(f, " ]             RES " TARGET_FMT_lx "\n",

                env->reserve_addr);

    for (i = 0; i < 32; i++) {

        if ((i & (RFPL - 1)) == 0)

            cpu_fprintf(f, "FPR%02d", i);

        cpu_fprintf(f, " %016" PRIx64, *((uint64_t *)&env->fpr[i]));

        if ((i & (RFPL - 1)) == (RFPL - 1))

            cpu_fprintf(f, "\n");

    }

    cpu_fprintf(f, "FPSCR %08x\n", env->fpscr);

#if !defined(CONFIG_USER_ONLY)

    cpu_fprintf(f, "SRR0 " TARGET_FMT_lx " SRR1 " TARGET_FMT_lx " SDR1 "

                TARGET_FMT_lx "\n", env->spr[SPR_SRR0], env->spr[SPR_SRR1],

                env->sdr1);

#endif



#undef RGPL

#undef RFPL

}

static int sockaddr_to_str(char *dest, int max_len,

                           struct sockaddr_storage *ss, socklen_t ss_len,

                           struct sockaddr_storage *ps, socklen_t ps_len,

                           bool is_listen, bool is_telnet)

{

    char shost[NI_MAXHOST], sserv[NI_MAXSERV];

    char phost[NI_MAXHOST], pserv[NI_MAXSERV];

    const char *left = "", *right = "";



    switch (ss->ss_family) {

#ifndef _WIN32

    case AF_UNIX:

        return snprintf(dest, max_len, "unix:%s%s",

                        ((struct sockaddr_un *)(ss))->sun_path,

                        is_listen ? ",server" : "");

#endif

    case AF_INET6:

        left  = "[";

        right = "]";

        /* fall through */

    case AF_INET:

        getnameinfo((struct sockaddr *) ss, ss_len, shost, sizeof(shost),

                    sserv, sizeof(sserv), NI_NUMERICHOST | NI_NUMERICSERV);

        getnameinfo((struct sockaddr *) ps, ps_len, phost, sizeof(phost),

                    pserv, sizeof(pserv), NI_NUMERICHOST | NI_NUMERICSERV);

        return snprintf(dest, max_len, "%s:%s%s%s:%s%s <-> %s%s%s:%s",

                        is_telnet ? "telnet" : "tcp",

                        left, shost, right, sserv,

                        is_listen ? ",server" : "",

                        left, phost, right, pserv);



    default:

        return snprintf(dest, max_len, "unknown");

    }

}

static inline unsigned int get_seg_limit(uint32_t e1, uint32_t e2)

{

    unsigned int limit;

    limit = (e1 & 0xffff) | (e2 & 0x000f0000);

    if (e2 & DESC_G_MASK)

        limit = (limit << 12) | 0xfff;

    return limit;

}

void hmp_info_block(Monitor *mon, const QDict *qdict)

{

    BlockInfoList *block_list, *info;

    ImageInfo *image_info;

    const char *device = qdict_get_try_str(qdict, "device");

    bool verbose = qdict_get_try_bool(qdict, "verbose", 0);



    block_list = qmp_query_block(NULL);



    for (info = block_list; info; info = info->next) {

        if (device && strcmp(device, info->value->device)) {

            continue;

        }

        monitor_printf(mon, "%s: removable=%d",

                       info->value->device, info->value->removable);



        if (info->value->removable) {

            monitor_printf(mon, " locked=%d", info->value->locked);

            monitor_printf(mon, " tray-open=%d", info->value->tray_open);

        }



        if (info->value->has_io_status) {

            monitor_printf(mon, " io-status=%s",

                           BlockDeviceIoStatus_lookup[info->value->io_status]);

        }



        if (info->value->has_inserted) {

            monitor_printf(mon, " file=");

            monitor_print_filename(mon, info->value->inserted->file);



            if (info->value->inserted->has_backing_file) {

                monitor_printf(mon, " backing_file=");

                monitor_print_filename(mon, info->value->inserted->backing_file);

                monitor_printf(mon, " backing_file_depth=%" PRId64,

                    info->value->inserted->backing_file_depth);

            }

            monitor_printf(mon, " ro=%d drv=%s encrypted=%d",

                           info->value->inserted->ro,

                           info->value->inserted->drv,

                           info->value->inserted->encrypted);



            monitor_printf(mon, " bps=%" PRId64 " bps_rd=%" PRId64

                            " bps_wr=%" PRId64 " iops=%" PRId64

                            " iops_rd=%" PRId64 " iops_wr=%" PRId64,

                            info->value->inserted->bps,

                            info->value->inserted->bps_rd,

                            info->value->inserted->bps_wr,

                            info->value->inserted->iops,

                            info->value->inserted->iops_rd,

                            info->value->inserted->iops_wr);



            if (verbose) {

                monitor_printf(mon, " images:\n");

                image_info = info->value->inserted->image;

                while (1) {

                        bdrv_image_info_dump((fprintf_function)monitor_printf,

                                             mon, image_info);

                    if (image_info->has_backing_image) {

                        image_info = image_info->backing_image;

                    } else {

                        break;

                    }

                }

            }

        } else {

            monitor_printf(mon, " [not inserted]");

        }



        monitor_printf(mon, "\n");

    }



    qapi_free_BlockInfoList(block_list);

}

