static ssize_t rtl8139_do_receive(NetClientState *nc, const uint8_t *buf, size_t size_, int do_interrupt)

{

    RTL8139State *s = qemu_get_nic_opaque(nc);

    PCIDevice *d = PCI_DEVICE(s);

    /* size is the length of the buffer passed to the driver */

    int size = size_;

    const uint8_t *dot1q_buf = NULL;



    uint32_t packet_header = 0;



    uint8_t buf1[MIN_BUF_SIZE + VLAN_HLEN];

    static const uint8_t broadcast_macaddr[6] =

        { 0xff, 0xff, 0xff, 0xff, 0xff, 0xff };



    DPRINTF(">>> received len=%d\n", size);



    /* test if board clock is stopped */

    if (!s->clock_enabled)

    {

        DPRINTF("stopped ==========================\n");

        return -1;

    }



    /* first check if receiver is enabled */



    if (!rtl8139_receiver_enabled(s))

    {

        DPRINTF("receiver disabled ================\n");

        return -1;

    }



    /* XXX: check this */

    if (s->RxConfig & AcceptAllPhys) {

        /* promiscuous: receive all */

        DPRINTF(">>> packet received in promiscuous mode\n");



    } else {

        if (!memcmp(buf,  broadcast_macaddr, 6)) {

            /* broadcast address */

            if (!(s->RxConfig & AcceptBroadcast))

            {

                DPRINTF(">>> broadcast packet rejected\n");



                /* update tally counter */

                ++s->tally_counters.RxERR;



                return size;

            }



            packet_header |= RxBroadcast;



            DPRINTF(">>> broadcast packet received\n");



            /* update tally counter */

            ++s->tally_counters.RxOkBrd;



        } else if (buf[0] & 0x01) {

            /* multicast */

            if (!(s->RxConfig & AcceptMulticast))

            {

                DPRINTF(">>> multicast packet rejected\n");



                /* update tally counter */

                ++s->tally_counters.RxERR;



                return size;

            }



            int mcast_idx = compute_mcast_idx(buf);



            if (!(s->mult[mcast_idx >> 3] & (1 << (mcast_idx & 7))))

            {

                DPRINTF(">>> multicast address mismatch\n");



                /* update tally counter */

                ++s->tally_counters.RxERR;



                return size;

            }



            packet_header |= RxMulticast;



            DPRINTF(">>> multicast packet received\n");



            /* update tally counter */

            ++s->tally_counters.RxOkMul;



        } else if (s->phys[0] == buf[0] &&

                   s->phys[1] == buf[1] &&

                   s->phys[2] == buf[2] &&

                   s->phys[3] == buf[3] &&

                   s->phys[4] == buf[4] &&

                   s->phys[5] == buf[5]) {

            /* match */

            if (!(s->RxConfig & AcceptMyPhys))

            {

                DPRINTF(">>> rejecting physical address matching packet\n");



                /* update tally counter */

                ++s->tally_counters.RxERR;



                return size;

            }



            packet_header |= RxPhysical;



            DPRINTF(">>> physical address matching packet received\n");



            /* update tally counter */

            ++s->tally_counters.RxOkPhy;



        } else {



            DPRINTF(">>> unknown packet\n");



            /* update tally counter */

            ++s->tally_counters.RxERR;



            return size;

        }

    }



    /* if too small buffer, then expand it

     * Include some tailroom in case a vlan tag is later removed. */

    if (size < MIN_BUF_SIZE + VLAN_HLEN) {

        memcpy(buf1, buf, size);

        memset(buf1 + size, 0, MIN_BUF_SIZE + VLAN_HLEN - size);

        buf = buf1;

        if (size < MIN_BUF_SIZE) {

            size = MIN_BUF_SIZE;

        }

    }



    if (rtl8139_cp_receiver_enabled(s))

    {

        if (!rtl8139_cp_rx_valid(s)) {

            return size;

        }



        DPRINTF("in C+ Rx mode ================\n");



        /* begin C+ receiver mode */



/* w0 ownership flag */

#define CP_RX_OWN (1<<31)

/* w0 end of ring flag */

#define CP_RX_EOR (1<<30)

/* w0 bits 0...12 : buffer size */

#define CP_RX_BUFFER_SIZE_MASK ((1<<13) - 1)

/* w1 tag available flag */

#define CP_RX_TAVA (1<<16)

/* w1 bits 0...15 : VLAN tag */

#define CP_RX_VLAN_TAG_MASK ((1<<16) - 1)

/* w2 low  32bit of Rx buffer ptr */

/* w3 high 32bit of Rx buffer ptr */



        int descriptor = s->currCPlusRxDesc;

        dma_addr_t cplus_rx_ring_desc;



        cplus_rx_ring_desc = rtl8139_addr64(s->RxRingAddrLO, s->RxRingAddrHI);

        cplus_rx_ring_desc += 16 * descriptor;



        DPRINTF("+++ C+ mode reading RX descriptor %d from host memory at "

            "%08x %08x = "DMA_ADDR_FMT"\n", descriptor, s->RxRingAddrHI,

            s->RxRingAddrLO, cplus_rx_ring_desc);



        uint32_t val, rxdw0,rxdw1,rxbufLO,rxbufHI;



        pci_dma_read(d, cplus_rx_ring_desc, &val, 4);

        rxdw0 = le32_to_cpu(val);

        pci_dma_read(d, cplus_rx_ring_desc+4, &val, 4);

        rxdw1 = le32_to_cpu(val);

        pci_dma_read(d, cplus_rx_ring_desc+8, &val, 4);

        rxbufLO = le32_to_cpu(val);

        pci_dma_read(d, cplus_rx_ring_desc+12, &val, 4);

        rxbufHI = le32_to_cpu(val);



        DPRINTF("+++ C+ mode RX descriptor %d %08x %08x %08x %08x\n",

            descriptor, rxdw0, rxdw1, rxbufLO, rxbufHI);



        if (!(rxdw0 & CP_RX_OWN))

        {

            DPRINTF("C+ Rx mode : descriptor %d is owned by host\n",

                descriptor);



            s->IntrStatus |= RxOverflow;

            ++s->RxMissed;



            /* update tally counter */

            ++s->tally_counters.RxERR;

            ++s->tally_counters.MissPkt;



            rtl8139_update_irq(s);

            return size_;

        }



        uint32_t rx_space = rxdw0 & CP_RX_BUFFER_SIZE_MASK;



        /* write VLAN info to descriptor variables. */

        if (s->CpCmd & CPlusRxVLAN && be16_to_cpup((uint16_t *)

                &buf[ETH_ALEN * 2]) == ETH_P_VLAN) {

            dot1q_buf = &buf[ETH_ALEN * 2];

            size -= VLAN_HLEN;

            /* if too small buffer, use the tailroom added duing expansion */

            if (size < MIN_BUF_SIZE) {

                size = MIN_BUF_SIZE;

            }



            rxdw1 &= ~CP_RX_VLAN_TAG_MASK;

            /* BE + ~le_to_cpu()~ + cpu_to_le() = BE */

            rxdw1 |= CP_RX_TAVA | le16_to_cpup((uint16_t *)

                &dot1q_buf[ETHER_TYPE_LEN]);



            DPRINTF("C+ Rx mode : extracted vlan tag with tci: ""%u\n",

                be16_to_cpup((uint16_t *)&dot1q_buf[ETHER_TYPE_LEN]));

        } else {

            /* reset VLAN tag flag */

            rxdw1 &= ~CP_RX_TAVA;

        }



        /* TODO: scatter the packet over available receive ring descriptors space */



        if (size+4 > rx_space)

        {

            DPRINTF("C+ Rx mode : descriptor %d size %d received %d + 4\n",

                descriptor, rx_space, size);



            s->IntrStatus |= RxOverflow;

            ++s->RxMissed;



            /* update tally counter */

            ++s->tally_counters.RxERR;

            ++s->tally_counters.MissPkt;



            rtl8139_update_irq(s);

            return size_;

        }



        dma_addr_t rx_addr = rtl8139_addr64(rxbufLO, rxbufHI);



        /* receive/copy to target memory */

        if (dot1q_buf) {

            pci_dma_write(d, rx_addr, buf, 2 * ETH_ALEN);

            pci_dma_write(d, rx_addr + 2 * ETH_ALEN,

                          buf + 2 * ETH_ALEN + VLAN_HLEN,

                          size - 2 * ETH_ALEN);

        } else {

            pci_dma_write(d, rx_addr, buf, size);

        }



        if (s->CpCmd & CPlusRxChkSum)

        {

            /* do some packet checksumming */

        }



        /* write checksum */

        val = cpu_to_le32(crc32(0, buf, size_));

        pci_dma_write(d, rx_addr+size, (uint8_t *)&val, 4);



/* first segment of received packet flag */

#define CP_RX_STATUS_FS (1<<29)

/* last segment of received packet flag */

#define CP_RX_STATUS_LS (1<<28)

/* multicast packet flag */

#define CP_RX_STATUS_MAR (1<<26)

/* physical-matching packet flag */

#define CP_RX_STATUS_PAM (1<<25)

/* broadcast packet flag */

#define CP_RX_STATUS_BAR (1<<24)

/* runt packet flag */

#define CP_RX_STATUS_RUNT (1<<19)

/* crc error flag */

#define CP_RX_STATUS_CRC (1<<18)

/* IP checksum error flag */

#define CP_RX_STATUS_IPF (1<<15)

/* UDP checksum error flag */

#define CP_RX_STATUS_UDPF (1<<14)

/* TCP checksum error flag */

#define CP_RX_STATUS_TCPF (1<<13)



        /* transfer ownership to target */

        rxdw0 &= ~CP_RX_OWN;



        /* set first segment bit */

        rxdw0 |= CP_RX_STATUS_FS;



        /* set last segment bit */

        rxdw0 |= CP_RX_STATUS_LS;



        /* set received packet type flags */

        if (packet_header & RxBroadcast)

            rxdw0 |= CP_RX_STATUS_BAR;

        if (packet_header & RxMulticast)

            rxdw0 |= CP_RX_STATUS_MAR;

        if (packet_header & RxPhysical)

            rxdw0 |= CP_RX_STATUS_PAM;



        /* set received size */

        rxdw0 &= ~CP_RX_BUFFER_SIZE_MASK;

        rxdw0 |= (size+4);



        /* update ring data */

        val = cpu_to_le32(rxdw0);

        pci_dma_write(d, cplus_rx_ring_desc, (uint8_t *)&val, 4);

        val = cpu_to_le32(rxdw1);

        pci_dma_write(d, cplus_rx_ring_desc+4, (uint8_t *)&val, 4);



        /* update tally counter */

        ++s->tally_counters.RxOk;



        /* seek to next Rx descriptor */

        if (rxdw0 & CP_RX_EOR)

        {

            s->currCPlusRxDesc = 0;

        }

        else

        {

            ++s->currCPlusRxDesc;

        }



        DPRINTF("done C+ Rx mode ----------------\n");



    }

    else

    {

        DPRINTF("in ring Rx mode ================\n");



        /* begin ring receiver mode */

        int avail = MOD2(s->RxBufferSize + s->RxBufPtr - s->RxBufAddr, s->RxBufferSize);



        /* if receiver buffer is empty then avail == 0 */



#define RX_ALIGN(x) (((x) + 3) & ~0x3)



        if (avail != 0 && RX_ALIGN(size + 8) >= avail)

        {

            DPRINTF("rx overflow: rx buffer length %d head 0x%04x "

                "read 0x%04x === available 0x%04x need 0x%04x\n",

                s->RxBufferSize, s->RxBufAddr, s->RxBufPtr, avail, size + 8);



            s->IntrStatus |= RxOverflow;

            ++s->RxMissed;

            rtl8139_update_irq(s);

            return size_;

        }



        packet_header |= RxStatusOK;



        packet_header |= (((size+4) << 16) & 0xffff0000);



        /* write header */

        uint32_t val = cpu_to_le32(packet_header);



        rtl8139_write_buffer(s, (uint8_t *)&val, 4);



        rtl8139_write_buffer(s, buf, size);



        /* write checksum */

        val = cpu_to_le32(crc32(0, buf, size));

        rtl8139_write_buffer(s, (uint8_t *)&val, 4);



        /* correct buffer write pointer */

        s->RxBufAddr = MOD2(RX_ALIGN(s->RxBufAddr), s->RxBufferSize);



        /* now we can signal we have received something */



        DPRINTF("received: rx buffer length %d head 0x%04x read 0x%04x\n",

            s->RxBufferSize, s->RxBufAddr, s->RxBufPtr);

    }



    s->IntrStatus |= RxOK;



    if (do_interrupt)

    {

        rtl8139_update_irq(s);

    }



    return size_;

}

void start_auth_sasl(VncState *vs)

{

    const char *mechlist = NULL;

    sasl_security_properties_t secprops;

    int err;

    char *localAddr, *remoteAddr;

    int mechlistlen;



    VNC_DEBUG("Initialize SASL auth %d\n", vs->csock);



    /* Get local & remote client addresses in form  IPADDR;PORT */

    if (!(localAddr = vnc_socket_local_addr("%s;%s", vs->csock)))

        goto authabort;



    if (!(remoteAddr = vnc_socket_remote_addr("%s;%s", vs->csock))) {

        g_free(localAddr);

        goto authabort;

    }



    err = sasl_server_new("vnc",

                          NULL, /* FQDN - just delegates to gethostname */

                          NULL, /* User realm */

                          localAddr,

                          remoteAddr,

                          NULL, /* Callbacks, not needed */

                          SASL_SUCCESS_DATA,

                          &vs->sasl.conn);

    g_free(localAddr);

    g_free(remoteAddr);

    localAddr = remoteAddr = NULL;



    if (err != SASL_OK) {

        VNC_DEBUG("sasl context setup failed %d (%s)",

                  err, sasl_errstring(err, NULL, NULL));

        vs->sasl.conn = NULL;

        goto authabort;

    }



#ifdef CONFIG_VNC_TLS

    /* Inform SASL that we've got an external SSF layer from TLS/x509 */

    if (vs->auth == VNC_AUTH_VENCRYPT &&

        vs->subauth == VNC_AUTH_VENCRYPT_X509SASL) {

        gnutls_cipher_algorithm_t cipher;

        sasl_ssf_t ssf;



        cipher = gnutls_cipher_get(vs->tls.session);

        if (!(ssf = (sasl_ssf_t)gnutls_cipher_get_key_size(cipher))) {

            VNC_DEBUG("%s", "cannot TLS get cipher size\n");

            sasl_dispose(&vs->sasl.conn);

            vs->sasl.conn = NULL;

            goto authabort;

        }

        ssf *= 8; /* tls key size is bytes, sasl wants bits */



        err = sasl_setprop(vs->sasl.conn, SASL_SSF_EXTERNAL, &ssf);

        if (err != SASL_OK) {

            VNC_DEBUG("cannot set SASL external SSF %d (%s)\n",

                      err, sasl_errstring(err, NULL, NULL));

            sasl_dispose(&vs->sasl.conn);

            vs->sasl.conn = NULL;

            goto authabort;

        }

    } else

#endif /* CONFIG_VNC_TLS */

        vs->sasl.wantSSF = 1;



    memset (&secprops, 0, sizeof secprops);

    /* Inform SASL that we've got an external SSF layer from TLS */

    if (vs->vd->is_unix

#ifdef CONFIG_VNC_TLS

        /* Disable SSF, if using TLS+x509+SASL only. TLS without x509

           is not sufficiently strong */

        || (vs->auth == VNC_AUTH_VENCRYPT &&

            vs->subauth == VNC_AUTH_VENCRYPT_X509SASL)

#endif /* CONFIG_VNC_TLS */

        ) {

        /* If we've got TLS or UNIX domain sock, we don't care about SSF */

        secprops.min_ssf = 0;

        secprops.max_ssf = 0;

        secprops.maxbufsize = 8192;

        secprops.security_flags = 0;

    } else {

        /* Plain TCP, better get an SSF layer */

        secprops.min_ssf = 56; /* Good enough to require kerberos */

        secprops.max_ssf = 100000; /* Arbitrary big number */

        secprops.maxbufsize = 8192;

        /* Forbid any anonymous or trivially crackable auth */

        secprops.security_flags =

            SASL_SEC_NOANONYMOUS | SASL_SEC_NOPLAINTEXT;

    }



    err = sasl_setprop(vs->sasl.conn, SASL_SEC_PROPS, &secprops);

    if (err != SASL_OK) {

        VNC_DEBUG("cannot set SASL security props %d (%s)\n",

                  err, sasl_errstring(err, NULL, NULL));

        sasl_dispose(&vs->sasl.conn);

        vs->sasl.conn = NULL;

        goto authabort;

    }



    err = sasl_listmech(vs->sasl.conn,

                        NULL, /* Don't need to set user */

                        "", /* Prefix */

                        ",", /* Separator */

                        "", /* Suffix */

                        &mechlist,

                        NULL,

                        NULL);

    if (err != SASL_OK) {

        VNC_DEBUG("cannot list SASL mechanisms %d (%s)\n",

                  err, sasl_errdetail(vs->sasl.conn));

        sasl_dispose(&vs->sasl.conn);

        vs->sasl.conn = NULL;

        goto authabort;

    }

    VNC_DEBUG("Available mechanisms for client: '%s'\n", mechlist);



    vs->sasl.mechlist = g_strdup(mechlist);

    mechlistlen = strlen(mechlist);

    vnc_write_u32(vs, mechlistlen);

    vnc_write(vs, mechlist, mechlistlen);

    vnc_flush(vs);



    VNC_DEBUG("Wait for client mechname length\n");

    vnc_read_when(vs, protocol_client_auth_sasl_mechname_len, 4);



    return;



 authabort:

    vnc_client_error(vs);

}

fork_exec(struct socket *so, const char *ex, int do_pty)

{

	int s;

	struct sockaddr_in addr;

	socklen_t addrlen = sizeof(addr);

	int opt;

	const char *argv[256];

	/* don't want to clobber the original */

	char *bptr;

	const char *curarg;

	int c, i, ret;

	pid_t pid;



	DEBUG_CALL("fork_exec");

	DEBUG_ARG("so = %p", so);

	DEBUG_ARG("ex = %p", ex);

	DEBUG_ARG("do_pty = %x", do_pty);



	if (do_pty == 2) {

                return 0;

	} else {

		addr.sin_family = AF_INET;

		addr.sin_port = 0;

		addr.sin_addr.s_addr = INADDR_ANY;



		if ((s = qemu_socket(AF_INET, SOCK_STREAM, 0)) < 0 ||

		    bind(s, (struct sockaddr *)&addr, addrlen) < 0 ||

		    listen(s, 1) < 0) {

			error_report("Error: inet socket: %s", strerror(errno));

			closesocket(s);



			return 0;

		}

	}



	pid = fork();

	switch(pid) {

	 case -1:

		error_report("Error: fork failed: %s", strerror(errno));

		close(s);

		return 0;



	 case 0:

                setsid();



		/* Set the DISPLAY */

                getsockname(s, (struct sockaddr *)&addr, &addrlen);

                close(s);

                /*

                 * Connect to the socket

                 * XXX If any of these fail, we're in trouble!

                 */

                s = qemu_socket(AF_INET, SOCK_STREAM, 0);

                addr.sin_addr = loopback_addr;

                do {

                    ret = connect(s, (struct sockaddr *)&addr, addrlen);

                } while (ret < 0 && errno == EINTR);



		dup2(s, 0);

		dup2(s, 1);

		dup2(s, 2);

		for (s = getdtablesize() - 1; s >= 3; s--)

		   close(s);



		i = 0;

		bptr = g_strdup(ex); /* No need to free() this */

		if (do_pty == 1) {

			/* Setup "slirp.telnetd -x" */

			argv[i++] = "slirp.telnetd";

			argv[i++] = "-x";

			argv[i++] = bptr;

		} else

		   do {

			/* Change the string into argv[] */

			curarg = bptr;

			while (*bptr != ' ' && *bptr != (char)0)

			   bptr++;

			c = *bptr;

			*bptr++ = (char)0;

			argv[i++] = g_strdup(curarg);

		   } while (c);



                argv[i] = NULL;

		execvp(argv[0], (char **)argv);



		/* Ooops, failed, let's tell the user why */

        fprintf(stderr, "Error: execvp of %s failed: %s\n",

                argv[0], strerror(errno));

		close(0); close(1); close(2); /* XXX */

		exit(1);



	 default:

		qemu_add_child_watch(pid);

                /*

                 * XXX this could block us...

                 * XXX Should set a timer here, and if accept() doesn't

                 * return after X seconds, declare it a failure

                 * The only reason this will block forever is if socket()

                 * of connect() fail in the child process

                 */

                do {

                    so->s = accept(s, (struct sockaddr *)&addr, &addrlen);

                } while (so->s < 0 && errno == EINTR);

                closesocket(s);

                socket_set_fast_reuse(so->s);

                opt = 1;

                qemu_setsockopt(so->s, SOL_SOCKET, SO_OOBINLINE, &opt, sizeof(int));

		qemu_set_nonblock(so->s);



		/* Append the telnet options now */

                if (so->so_m != NULL && do_pty == 1)  {

			sbappend(so, so->so_m);

                        so->so_m = NULL;

		}



		return 1;

	}

}

static int vnc_set_x509_credential(VncDisplay *vd,

                                   const char *certdir,

                                   const char *filename,

                                   char **cred,

                                   int ignoreMissing)

{

    struct stat sb;



    g_free(*cred);

    *cred = g_malloc(strlen(certdir) + strlen(filename) + 2);



    strcpy(*cred, certdir);

    strcat(*cred, "/");

    strcat(*cred, filename);



    VNC_DEBUG("Check %s\n", *cred);

    if (stat(*cred, &sb) < 0) {

        g_free(*cred);

        *cred = NULL;

        if (ignoreMissing && errno == ENOENT)

            return 0;

        return -1;

    }



    return 0;

}

