void coroutine_fn qemu_co_mutex_unlock(CoMutex *mutex)

{

    Coroutine *self = qemu_coroutine_self();



    trace_qemu_co_mutex_unlock_entry(mutex, self);



    assert(mutex->locked);

    assert(mutex->holder == self);

    assert(qemu_in_coroutine());



    mutex->holder = NULL;

    self->locks_held--;

    if (atomic_fetch_dec(&mutex->locked) == 1) {

        /* No waiting qemu_co_mutex_lock().  Pfew, that was easy!  */

        return;

    }



    for (;;) {

        CoWaitRecord *to_wake = pop_waiter(mutex);

        unsigned our_handoff;



        if (to_wake) {

            Coroutine *co = to_wake->co;

            aio_co_wake(co);

            break;

        }



        /* Some concurrent lock() is in progress (we know this because

         * mutex->locked was >1) but it hasn't yet put itself on the wait

         * queue.  Pick a sequence number for the handoff protocol (not 0).

         */

        if (++mutex->sequence == 0) {

            mutex->sequence = 1;

        }



        our_handoff = mutex->sequence;

        atomic_mb_set(&mutex->handoff, our_handoff);

        if (!has_waiters(mutex)) {

            /* The concurrent lock has not added itself yet, so it

             * will be able to pick our handoff.

             */

            break;

        }



        /* Try to do the handoff protocol ourselves; if somebody else has

         * already taken it, however, we're done and they're responsible.

         */

        if (atomic_cmpxchg(&mutex->handoff, our_handoff, 0) != our_handoff) {

            break;

        }

    }



    trace_qemu_co_mutex_unlock_return(mutex, self);

}

static uint32_t nvram_readb (void *opaque, target_phys_addr_t addr)

{

    ds1225y_t *NVRAM = opaque;

    int64_t pos;



    pos = addr - NVRAM->mem_base;

    if (addr >= NVRAM->capacity)

        addr -= NVRAM->capacity;



    if (!ds1225y_set_to_mode(NVRAM, readmode, "rb"))

        return 0;

    qemu_fseek(NVRAM->file, pos, SEEK_SET);

    return (uint32_t)qemu_get_byte(NVRAM->file);

}

static void test_dma_fragmented(void)

{

    AHCIQState *ahci;

    AHCICommand *cmd;

    uint8_t px;

    size_t bufsize = 4096;

    unsigned char *tx = g_malloc(bufsize);

    unsigned char *rx = g_malloc0(bufsize);

    uint64_t ptr;



    ahci = ahci_boot_and_enable();

    px = ahci_port_select(ahci);

    ahci_port_clear(ahci, px);



    /* create pattern */

    generate_pattern(tx, bufsize, AHCI_SECTOR_SIZE);



    /* Create a DMA buffer in guest memory, and write our pattern to it. */

    ptr = guest_alloc(ahci->parent->alloc, bufsize);

    g_assert(ptr);

    memwrite(ptr, tx, bufsize);



    cmd = ahci_command_create(CMD_WRITE_DMA);

    ahci_command_adjust(cmd, 0, ptr, bufsize, 32);

    ahci_command_commit(ahci, cmd, px);

    ahci_command_issue(ahci, cmd);

    ahci_command_verify(ahci, cmd);

    g_free(cmd);



    cmd = ahci_command_create(CMD_READ_DMA);

    ahci_command_adjust(cmd, 0, ptr, bufsize, 32);

    ahci_command_commit(ahci, cmd, px);

    ahci_command_issue(ahci, cmd);

    ahci_command_verify(ahci, cmd);

    g_free(cmd);



    /* Read back the guest's receive buffer into local memory */

    memread(ptr, rx, bufsize);

    guest_free(ahci->parent->alloc, ptr);



    g_assert_cmphex(memcmp(tx, rx, bufsize), ==, 0);



    ahci_shutdown(ahci);



    g_free(rx);

    g_free(tx);

}

static long do_rt_sigreturn_v1(CPUARMState *env)

{

        abi_ulong frame_addr;

        struct rt_sigframe_v1 *frame = NULL;

        sigset_t host_set;



	/*

	 * Since we stacked the signal on a 64-bit boundary,

	 * then 'sp' should be word aligned here.  If it's

	 * not, then the user is trying to mess with us.

	 */

        frame_addr = env->regs[13];

        if (frame_addr & 7) {

            goto badframe;

        }



	if (!lock_user_struct(VERIFY_READ, frame, frame_addr, 1))

                goto badframe;



        target_to_host_sigset(&host_set, &frame->uc.tuc_sigmask);

        sigprocmask(SIG_SETMASK, &host_set, NULL);



	if (restore_sigcontext(env, &frame->uc.tuc_mcontext))

		goto badframe;



	if (do_sigaltstack(frame_addr + offsetof(struct rt_sigframe_v1, uc.tuc_stack), 0, get_sp_from_cpustate(env)) == -EFAULT)

		goto badframe;



#if 0

	/* Send SIGTRAP if we're single-stepping */

	if (ptrace_cancel_bpt(current))

		send_sig(SIGTRAP, current, 1);

#endif

	unlock_user_struct(frame, frame_addr, 0);

	return env->regs[0];



badframe:

	unlock_user_struct(frame, frame_addr, 0);

        force_sig(TARGET_SIGSEGV /* , current */);

	return 0;

}

int qcow2_cache_flush(BlockDriverState *bs, Qcow2Cache *c)

{

    BDRVQcow2State *s = bs->opaque;

    int result = 0;

    int ret;

    int i;



    trace_qcow2_cache_flush(qemu_coroutine_self(), c == s->l2_table_cache);



    for (i = 0; i < c->size; i++) {

        ret = qcow2_cache_entry_flush(bs, c, i);

        if (ret < 0 && result != -ENOSPC) {

            result = ret;

        }

    }



    if (result == 0) {

        ret = bdrv_flush(bs->file->bs);

        if (ret < 0) {

            result = ret;

        }

    }



    return result;

}

