void process_pending_signals(CPUArchState *cpu_env)

{

    CPUState *cpu = ENV_GET_CPU(cpu_env);

    int sig;

    TaskState *ts = cpu->opaque;



    if (!ts->signal_pending)

        return;



    /* FIXME: This is not threadsafe.  */

    for(sig = 1; sig <= TARGET_NSIG; sig++) {

        if (ts->sigtab[sig - 1].pending) {

            handle_pending_signal(cpu_env, sig);

            return;

        }

    }

    /* if no signal is pending, just return */

    ts->signal_pending = 0;

    return;

}

ram_addr_t qemu_ram_alloc_from_ptr(DeviceState *dev, const char *name,

                                   ram_addr_t size, void *host)

{

    RAMBlock *new_block, *block;



    size = TARGET_PAGE_ALIGN(size);

    new_block = qemu_mallocz(sizeof(*new_block));



    if (dev && dev->parent_bus && dev->parent_bus->info->get_dev_path) {

        char *id = dev->parent_bus->info->get_dev_path(dev);

        if (id) {

            snprintf(new_block->idstr, sizeof(new_block->idstr), "%s/", id);

            qemu_free(id);



    pstrcat(new_block->idstr, sizeof(new_block->idstr), name);



    QLIST_FOREACH(block, &ram_list.blocks, next) {

        if (!strcmp(block->idstr, new_block->idstr)) {

            fprintf(stderr, "RAMBlock \"%s\" already registered, abort!\n",

                    new_block->idstr);






    new_block->offset = find_ram_offset(size);

    if (host) {

        new_block->host = host;

        new_block->flags |= RAM_PREALLOC_MASK;

    } else {

        if (mem_path) {

#if defined (__linux__) && !defined(TARGET_S390X)

            new_block->host = file_ram_alloc(new_block, size, mem_path);

            if (!new_block->host) {

                new_block->host = qemu_vmalloc(size);

                qemu_madvise(new_block->host, size, QEMU_MADV_MERGEABLE);


#else

            fprintf(stderr, "-mem-path option unsupported\n");

            exit(1);

#endif

        } else {

#if defined(TARGET_S390X) && defined(CONFIG_KVM)

            /* S390 KVM requires the topmost vma of the RAM to be smaller than

               an system defined value, which is at least 256GB. Larger systems

               have larger values. We put the guest between the end of data

               segment (system break) and this value. We use 32GB as a base to

               have enough room for the system break to grow. */

            new_block->host = mmap((void*)0x800000000, size,

                                   PROT_EXEC|PROT_READ|PROT_WRITE,

                                   MAP_SHARED | MAP_ANONYMOUS | MAP_FIXED, -1, 0);





#else

            if (xen_mapcache_enabled()) {

                xen_ram_alloc(new_block->offset, size);

            } else {

                new_block->host = qemu_vmalloc(size);


#endif

            qemu_madvise(new_block->host, size, QEMU_MADV_MERGEABLE);



    new_block->length = size;



    QLIST_INSERT_HEAD(&ram_list.blocks, new_block, next);



    ram_list.phys_dirty = qemu_realloc(ram_list.phys_dirty,

                                       last_ram_offset() >> TARGET_PAGE_BITS);

    memset(ram_list.phys_dirty + (new_block->offset >> TARGET_PAGE_BITS),

           0xff, size >> TARGET_PAGE_BITS);



    if (kvm_enabled())

        kvm_setup_guest_memory(new_block->host, size);



    return new_block->offset;

char *qmp_memchar_read(const char *device, int64_t size,

                       bool has_format, enum DataFormat format,

                       Error **errp)

{

    CharDriverState *chr;

    uint8_t *read_data;

    size_t count;

    char *data;



    chr = qemu_chr_find(device);

    if (!chr) {

        error_setg(errp, "Device '%s' not found", device);

        return NULL;

    }



    if (qemu_is_chr(chr, "memory")) {

        error_setg(errp,"%s is not memory char device", device);

        return NULL;

    }



    if (size <= 0) {

        error_setg(errp, "size must be greater than zero");

        return NULL;

    }



    count = qemu_chr_cirmem_count(chr);

    if (count == 0) {

        return g_strdup("");

    }



    size = size > count ? count : size;

    read_data = g_malloc0(size + 1);



    cirmem_chr_read(chr, read_data, size);



    if (has_format && (format == DATA_FORMAT_BASE64)) {

        data = g_base64_encode(read_data, size);


    } else {

        data = (char *)read_data;

    }



    return data;

}

static void xbzrle_cache_zero_page(ram_addr_t current_addr)

{

    if (ram_bulk_stage || !migrate_use_xbzrle()) {

        return;

    }



    /* We don't care if this fails to allocate a new cache page

     * as long as it updated an old one */

    cache_insert(XBZRLE.cache, current_addr, ZERO_TARGET_PAGE);

}

static void breakpoint_invalidate(CPUState *cpu, target_ulong pc)

{

    /* Flush the whole TB as this will not have race conditions

     * even if we don't have proper locking yet.

     * Ideally we would just invalidate the TBs for the

     * specified PC.

     */

    tb_flush(cpu);

}

static void vfio_bar_quirk_teardown(VFIODevice *vdev, int nr)

{

    VFIOBAR *bar = &vdev->bars[nr];



    while (!QLIST_EMPTY(&bar->quirks)) {

        VFIOQuirk *quirk = QLIST_FIRST(&bar->quirks);

        memory_region_del_subregion(&bar->mem, &quirk->mem);


        QLIST_REMOVE(quirk, next);

        g_free(quirk);

    }

}

static void spapr_populate_pci_devices_dt(PCIBus *bus, PCIDevice *pdev,

                                          void *opaque)

{

    PCIBus *sec_bus;

    sPAPRFDT *p = opaque;

    int offset;

    sPAPRFDT s_fdt;

    uint32_t drc_index = spapr_phb_get_pci_drc_index(p->sphb, pdev);



    offset = spapr_create_pci_child_dt(p->sphb, pdev,

                                       drc_index, NULL,

                                       p->fdt, p->node_off);

    if (!offset) {

        error_report("Failed to create pci child device tree node");

        return;

    }



    if ((pci_default_read_config(pdev, PCI_HEADER_TYPE, 1) !=

         PCI_HEADER_TYPE_BRIDGE)) {

        return;

    }



    sec_bus = pci_bridge_get_sec_bus(PCI_BRIDGE(pdev));

    if (!sec_bus) {

        return;

    }



    s_fdt.fdt = p->fdt;

    s_fdt.node_off = offset;

    s_fdt.sphb = p->sphb;

    pci_for_each_device(sec_bus, pci_bus_num(sec_bus),

                        spapr_populate_pci_devices_dt,

                        &s_fdt);

}

