    const size_t zero_skip = offsetof(VirtIOSCSIReq, vring);



    req = g_malloc(sizeof(*req) + vs->cdb_size);

    req->vq = vq;

    req->dev = s;

    qemu_sglist_init(&req->qsgl, DEVICE(s), 8, &address_space_memory);

