static PCIDevice *nic_init(PCIBus * bus, NICInfo * nd, uint32_t device)

{

    PCIEEPRO100State *d;

    EEPRO100State *s;



    logout("\n");



    d = (PCIEEPRO100State *) pci_register_device(bus, nd->model,

                                                 sizeof(PCIEEPRO100State), -1,

                                                 NULL, NULL);



    s = &d->eepro100;

    s->device = device;

    s->pci_dev = &d->dev;



    pci_reset(s);



    /* Add 64 * 2 EEPROM. i82557 and i82558 support a 64 word EEPROM,

     * i82559 and later support 64 or 256 word EEPROM. */

    s->eeprom = eeprom93xx_new(EEPROM_SIZE);



    /* Handler for memory-mapped I/O */

    d->eepro100.mmio_index =

        cpu_register_io_memory(0, pci_mmio_read, pci_mmio_write, s);



    pci_register_io_region(&d->dev, 0, PCI_MEM_SIZE,

                           PCI_ADDRESS_SPACE_MEM |

                           PCI_ADDRESS_SPACE_MEM_PREFETCH, pci_mmio_map);

    pci_register_io_region(&d->dev, 1, PCI_IO_SIZE, PCI_ADDRESS_SPACE_IO,

                           pci_map);

    pci_register_io_region(&d->dev, 2, PCI_FLASH_SIZE, PCI_ADDRESS_SPACE_MEM,

                           pci_mmio_map);



    memcpy(s->macaddr, nd->macaddr, 6);

    logout("macaddr: %s\n", nic_dump(&s->macaddr[0], 6));

    assert(s->region[1] == 0);



    nic_reset(s);



    s->vc = qemu_new_vlan_client(nd->vlan, nd->model, nd->name,

                                 nic_receive, nic_can_receive, s);



    qemu_format_nic_info_str(s->vc, s->macaddr);



    qemu_register_reset(nic_reset, s);



    register_savevm(s->vc->model, -1, 3, nic_save, nic_load, s);

    return (PCIDevice *)d;

}

void coroutine_fn co_aio_sleep_ns(AioContext *ctx, QEMUClockType type,
                                  int64_t ns)
{
    CoSleepCB sleep_cb = {
        .co = qemu_coroutine_self(),
    };
    sleep_cb.ts = aio_timer_new(ctx, type, SCALE_NS, co_sleep_cb, &sleep_cb);
    timer_mod(sleep_cb.ts, qemu_clock_get_ns(type) + ns);
    qemu_coroutine_yield();
    timer_del(sleep_cb.ts);
    timer_free(sleep_cb.ts);

void cpu_set_log(int log_flags)

{

    loglevel = log_flags;

    if (loglevel && !logfile) {

        logfile = fopen(logfilename, log_append ? "a" : "w");

        if (!logfile) {

            perror(logfilename);

            _exit(1);

        }

#if !defined(CONFIG_SOFTMMU)

        /* must avoid mmap() usage of glibc by setting a buffer "by hand" */

        {

            static char logfile_buf[4096];

            setvbuf(logfile, logfile_buf, _IOLBF, sizeof(logfile_buf));

        }

#elif !defined(_WIN32)

        /* Win32 doesn't support line-buffering and requires size >= 2 */

        setvbuf(logfile, NULL, _IOLBF, 0);

#endif

        log_append = 1;

    }

    if (!loglevel && logfile) {

        fclose(logfile);

        logfile = NULL;

    }

}

void helper_ocbi(CPUSH4State *env, uint32_t address)

{

    memory_content **current = &(env->movcal_backup);

    while (*current)

    {

	uint32_t a = (*current)->address;

	if ((a & ~0x1F) == (address & ~0x1F))

	{

	    memory_content *next = (*current)->next;

            cpu_stl_data(env, a, (*current)->value);



	    if (next == NULL)

	    {

		env->movcal_backup_tail = current;

	    }



	    free (*current);

	    *current = next;

	    break;

	}

    }

}

static void render_memory_region(FlatView *view,

                                 MemoryRegion *mr,

                                 target_phys_addr_t base,

                                 AddrRange clip)

{

    MemoryRegion *subregion;

    unsigned i;

    target_phys_addr_t offset_in_region;

    uint64_t remain;

    uint64_t now;

    FlatRange fr;

    AddrRange tmp;



    base += mr->addr;



    tmp = addrrange_make(base, mr->size);



    if (!addrrange_intersects(tmp, clip)) {

        return;

    }



    clip = addrrange_intersection(tmp, clip);



    if (mr->alias) {

        base -= mr->alias->addr;

        base -= mr->alias_offset;

        render_memory_region(view, mr->alias, base, clip);

        return;

    }



    /* Render subregions in priority order. */

    QTAILQ_FOREACH(subregion, &mr->subregions, subregions_link) {

        render_memory_region(view, subregion, base, clip);

    }



    if (!mr->terminates) {

        return;

    }



    offset_in_region = clip.start - base;

    base = clip.start;

    remain = clip.size;



    /* Render the region itself into any gaps left by the current view. */

    for (i = 0; i < view->nr && remain; ++i) {

        if (base >= addrrange_end(view->ranges[i].addr)) {

            continue;

        }

        if (base < view->ranges[i].addr.start) {

            now = MIN(remain, view->ranges[i].addr.start - base);

            fr.mr = mr;

            fr.offset_in_region = offset_in_region;

            fr.addr = addrrange_make(base, now);

            fr.dirty_log_mask = mr->dirty_log_mask;

            flatview_insert(view, i, &fr);

            ++i;

            base += now;

            offset_in_region += now;

            remain -= now;

        }

        if (base == view->ranges[i].addr.start) {

            now = MIN(remain, view->ranges[i].addr.size);

            base += now;

            offset_in_region += now;

            remain -= now;

        }

    }

    if (remain) {

        fr.mr = mr;

        fr.offset_in_region = offset_in_region;

        fr.addr = addrrange_make(base, remain);

        fr.dirty_log_mask = mr->dirty_log_mask;

        flatview_insert(view, i, &fr);

    }

}

