static int usb_host_handle_iso_data(USBHostDevice *s, USBPacket *p, int in)

{

    AsyncURB *aurb;

    int i, j, ret, max_packet_size, offset, len = 0;



    max_packet_size = get_max_packet_size(s, p->devep);

    if (max_packet_size == 0)

        return USB_RET_NAK;



    aurb = get_iso_urb(s, p->devep);

    if (!aurb) {

        aurb = usb_host_alloc_iso(s, p->devep, in);

    }



    i = get_iso_urb_idx(s, p->devep);

    j = aurb[i].iso_frame_idx;

    if (j >= 0 && j < ISO_FRAME_DESC_PER_URB) {

        if (in) {

            /* Check urb status  */

            if (aurb[i].urb.status) {

                len = urb_status_to_usb_ret(aurb[i].urb.status);

                /* Move to the next urb */

                aurb[i].iso_frame_idx = ISO_FRAME_DESC_PER_URB - 1;

            /* Check frame status */

            } else if (aurb[i].urb.iso_frame_desc[j].status) {

                len = urb_status_to_usb_ret(

                                        aurb[i].urb.iso_frame_desc[j].status);

            /* Check the frame fits */

            } else if (aurb[i].urb.iso_frame_desc[j].actual_length > p->len) {

                printf("husb: received iso data is larger then packet\n");

                len = USB_RET_NAK;

            /* All good copy data over */

            } else {

                len = aurb[i].urb.iso_frame_desc[j].actual_length;

                memcpy(p->data,

                       aurb[i].urb.buffer +

                           j * aurb[i].urb.iso_frame_desc[0].length,

                       len);

            }

        } else {

            len = p->len;

            offset = (j == 0) ? 0 : get_iso_buffer_used(s, p->devep);



            /* Check the frame fits */

            if (len > max_packet_size) {

                printf("husb: send iso data is larger then max packet size\n");

                return USB_RET_NAK;

            }



            /* All good copy data over */

            memcpy(aurb[i].urb.buffer + offset, p->data, len);

            aurb[i].urb.iso_frame_desc[j].length = len;

            offset += len;

            set_iso_buffer_used(s, p->devep, offset);



            /* Start the stream once we have buffered enough data */

            if (!is_iso_started(s, p->devep) && i == 1 && j == 8) {

                set_iso_started(s, p->devep);

            }

        }

        aurb[i].iso_frame_idx++;

        if (aurb[i].iso_frame_idx == ISO_FRAME_DESC_PER_URB) {

            i = (i + 1) % s->iso_urb_count;

            set_iso_urb_idx(s, p->devep, i);

        }

    } else {

        if (in) {

            set_iso_started(s, p->devep);

        } else {

            DPRINTF("hubs: iso out error no free buffer, dropping packet\n");

        }

    }



    if (is_iso_started(s, p->devep)) {

        /* (Re)-submit all fully consumed / filled urbs */

        for (i = 0; i < s->iso_urb_count; i++) {

            if (aurb[i].iso_frame_idx == ISO_FRAME_DESC_PER_URB) {

                ret = ioctl(s->fd, USBDEVFS_SUBMITURB, &aurb[i]);

                if (ret < 0) {

                    printf("husb error submitting iso urb %d: %d\n", i, errno);

                    if (!in || len == 0) {

                        switch(errno) {

                        case ETIMEDOUT:

                            len = USB_RET_NAK;

                            break;

                        case EPIPE:

                        default:

                            len = USB_RET_STALL;

                        }

                    }

                    break;

                }

                aurb[i].iso_frame_idx = -1;

                change_iso_inflight(s, p->devep, +1);

            }

        }

    }



    return len;

}

static void pcie_pci_bridge_realize(PCIDevice *d, Error **errp)

{

    PCIBridge *br = PCI_BRIDGE(d);

    PCIEPCIBridge *pcie_br = PCIE_PCI_BRIDGE_DEV(d);

    int rc, pos;



    pci_bridge_initfn(d, TYPE_PCI_BUS);



    d->config[PCI_INTERRUPT_PIN] = 0x1;

    memory_region_init(&pcie_br->shpc_bar, OBJECT(d), "shpc-bar",

                       shpc_bar_size(d));

    rc = shpc_init(d, &br->sec_bus, &pcie_br->shpc_bar, 0, errp);

    if (rc) {

        goto error;

    }



    rc = pcie_cap_init(d, 0, PCI_EXP_TYPE_PCI_BRIDGE, 0, errp);

    if (rc < 0) {

        goto cap_error;

    }



    pos = pci_add_capability(d, PCI_CAP_ID_PM, 0, PCI_PM_SIZEOF, errp);

    if (pos < 0) {

        goto pm_error;

    }

    d->exp.pm_cap = pos;

    pci_set_word(d->config + pos + PCI_PM_PMC, 0x3);



    pcie_cap_arifwd_init(d);

    pcie_cap_deverr_init(d);



    rc = pcie_aer_init(d, PCI_ERR_VER, 0x100, PCI_ERR_SIZEOF, errp);

    if (rc < 0) {

        goto aer_error;

    }



    if (pcie_br->msi != ON_OFF_AUTO_OFF) {

        rc = msi_init(d, 0, 1, true, true, errp);

        if (rc < 0) {

            goto msi_error;

        }

    }

    pci_register_bar(d, 0, PCI_BASE_ADDRESS_SPACE_MEMORY |

                     PCI_BASE_ADDRESS_MEM_TYPE_64, &pcie_br->shpc_bar);

    return;



msi_error:

    pcie_aer_exit(d);

aer_error:

pm_error:

    pcie_cap_exit(d);

cap_error:

    shpc_free(d);

error:

    pci_bridge_exitfn(d);

}

static int qcrypto_cipher_init_aes(QCryptoCipher *cipher,

                                   const uint8_t *key, size_t nkey,

                                   Error **errp)

{

    QCryptoCipherBuiltin *ctxt;



    if (cipher->mode != QCRYPTO_CIPHER_MODE_CBC &&

        cipher->mode != QCRYPTO_CIPHER_MODE_ECB) {

        error_setg(errp, "Unsupported cipher mode %d", cipher->mode);

        return -1;

    }



    ctxt = g_new0(QCryptoCipherBuiltin, 1);



    if (AES_set_encrypt_key(key, nkey * 8, &ctxt->state.aes.encrypt_key) != 0) {

        error_setg(errp, "Failed to set encryption key");

        goto error;

    }



    if (AES_set_decrypt_key(key, nkey * 8, &ctxt->state.aes.decrypt_key) != 0) {

        error_setg(errp, "Failed to set decryption key");

        goto error;

    }




    ctxt->free = qcrypto_cipher_free_aes;

    ctxt->setiv = qcrypto_cipher_setiv_aes;

    ctxt->encrypt = qcrypto_cipher_encrypt_aes;

    ctxt->decrypt = qcrypto_cipher_decrypt_aes;



    cipher->opaque = ctxt;



    return 0;



 error:

    g_free(ctxt);

    return -1;

}

