static void qemu_laio_process_completion(struct qemu_laiocb *laiocb)

{

    int ret;



    ret = laiocb->ret;

    if (ret != -ECANCELED) {

        if (ret == laiocb->nbytes) {

            ret = 0;

        } else if (ret >= 0) {

            /* Short reads mean EOF, pad with zeros. */

            if (laiocb->is_read) {

                qemu_iovec_memset(laiocb->qiov, ret, 0,

                    laiocb->qiov->size - ret);

            } else {

                ret = -ENOSPC;

            }

        }

    }



    laiocb->ret = ret;

    if (laiocb->co) {

        /* Jump and continue completion for foreign requests, don't do

         * anything for current request, it will be completed shortly. */

        if (laiocb->co != qemu_coroutine_self()) {

            qemu_coroutine_enter(laiocb->co);

        }

    } else {

        laiocb->common.cb(laiocb->common.opaque, ret);

        qemu_aio_unref(laiocb);

    }

}

static uint32_t msix_mmio_readl(void *opaque, target_phys_addr_t addr)

{

    PCIDevice *dev = opaque;

    unsigned int offset = addr & (MSIX_PAGE_SIZE - 1);

    void *page = dev->msix_table_page;

    uint32_t val = 0;



    memcpy(&val, (void *)((char *)page + offset), 4);



    return val;

}

static ssize_t gunzip(void *dst, size_t dstlen, uint8_t *src,

                      size_t srclen)

{

    z_stream s;

    ssize_t dstbytes;

    int r, i, flags;



    /* skip header */

    i = 10;

    flags = src[3];

    if (src[2] != DEFLATED || (flags & RESERVED) != 0) {

        puts ("Error: Bad gzipped data\n");

        return -1;

    }

    if ((flags & EXTRA_FIELD) != 0)

        i = 12 + src[10] + (src[11] << 8);

    if ((flags & ORIG_NAME) != 0)

        while (src[i++] != 0)

            ;

    if ((flags & COMMENT) != 0)

        while (src[i++] != 0)

            ;

    if ((flags & HEAD_CRC) != 0)

        i += 2;

    if (i >= srclen) {

        puts ("Error: gunzip out of data in header\n");

        return -1;

    }



    s.zalloc = zalloc;

    s.zfree = zfree;



    r = inflateInit2(&s, -MAX_WBITS);

    if (r != Z_OK) {

        printf ("Error: inflateInit2() returned %d\n", r);

        return (-1);

    }

    s.next_in = src + i;

    s.avail_in = srclen - i;

    s.next_out = dst;

    s.avail_out = dstlen;

    r = inflate(&s, Z_FINISH);

    if (r != Z_OK && r != Z_STREAM_END) {

        printf ("Error: inflate() returned %d\n", r);

        return -1;

    }

    dstbytes = s.next_out - (unsigned char *) dst;

    inflateEnd(&s);



    return dstbytes;

}

static void omap_i2c_recv(I2CAdapter *i2c, uint8_t addr,

                          uint8_t *buf, uint16_t len)

{

    OMAPI2C *s = (OMAPI2C *)i2c;

    uint16_t data, stat;



    omap_i2c_set_slave_addr(s, addr);



    data = len;

    memwrite(s->addr + OMAP_I2C_CNT, &data, 2);



    data = OMAP_I2C_CON_I2C_EN |

           OMAP_I2C_CON_MST |

           OMAP_I2C_CON_STT |

           OMAP_I2C_CON_STP;

    memwrite(s->addr + OMAP_I2C_CON, &data, 2);

    memread(s->addr + OMAP_I2C_CON, &data, 2);

    g_assert((data & OMAP_I2C_CON_STP) == 0);



    memread(s->addr + OMAP_I2C_STAT, &data, 2);

    g_assert((data & OMAP_I2C_STAT_NACK) == 0);



    memread(s->addr + OMAP_I2C_CNT, &data, 2);

    g_assert_cmpuint(data, ==, len);



    while (len > 0) {

        memread(s->addr + OMAP_I2C_STAT, &data, 2);

        g_assert((data & OMAP_I2C_STAT_RRDY) != 0);

        g_assert((data & OMAP_I2C_STAT_ROVR) == 0);



        memread(s->addr + OMAP_I2C_DATA, &data, 2);



        memread(s->addr + OMAP_I2C_STAT, &stat, 2);

        if (unlikely(len == 1)) {

            *buf = data & 0xf;

            buf++;

            len--;

        } else {

            memcpy(buf, &data, 2);

            buf += 2;

            len -= 2;

        }

    }



    memread(s->addr + OMAP_I2C_CON, &data, 2);

    g_assert((data & OMAP_I2C_CON_STP) == 0);

}

static void gen_ld(DisasContext *ctx, uint32_t opc,

                   int rt, int base, int16_t offset)

{

    TCGv t0, t1, t2;

    int mem_idx = ctx->mem_idx;



    if (rt == 0 && ctx->insn_flags & (INSN_LOONGSON2E | INSN_LOONGSON2F)) {

        /* Loongson CPU uses a load to zero register for prefetch.

           We emulate it as a NOP. On other CPU we must perform the

           actual memory access. */

        return;

    }



    t0 = tcg_temp_new();

    gen_base_offset_addr(ctx, t0, base, offset);



    switch (opc) {

#if defined(TARGET_MIPS64)

    case OPC_LWU:

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_TEUL |

                           ctx->default_tcg_memop_mask);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LD:

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_TEQ |

                           ctx->default_tcg_memop_mask);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LLD:

    case R6_OPC_LLD:

        op_ld_lld(t0, t0, mem_idx, ctx);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LDL:

        t1 = tcg_temp_new();

        /* Do a byte access to possibly trigger a page

           fault with the unaligned address.  */

        tcg_gen_qemu_ld_tl(t1, t0, mem_idx, MO_UB);

        tcg_gen_andi_tl(t1, t0, 7);

#ifndef TARGET_WORDS_BIGENDIAN

        tcg_gen_xori_tl(t1, t1, 7);

#endif

        tcg_gen_shli_tl(t1, t1, 3);

        tcg_gen_andi_tl(t0, t0, ~7);

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_TEQ);

        tcg_gen_shl_tl(t0, t0, t1);

        t2 = tcg_const_tl(-1);

        tcg_gen_shl_tl(t2, t2, t1);

        gen_load_gpr(t1, rt);

        tcg_gen_andc_tl(t1, t1, t2);

        tcg_temp_free(t2);

        tcg_gen_or_tl(t0, t0, t1);

        tcg_temp_free(t1);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LDR:

        t1 = tcg_temp_new();

        /* Do a byte access to possibly trigger a page

           fault with the unaligned address.  */

        tcg_gen_qemu_ld_tl(t1, t0, mem_idx, MO_UB);

        tcg_gen_andi_tl(t1, t0, 7);

#ifdef TARGET_WORDS_BIGENDIAN

        tcg_gen_xori_tl(t1, t1, 7);

#endif

        tcg_gen_shli_tl(t1, t1, 3);

        tcg_gen_andi_tl(t0, t0, ~7);

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_TEQ);

        tcg_gen_shr_tl(t0, t0, t1);

        tcg_gen_xori_tl(t1, t1, 63);

        t2 = tcg_const_tl(0xfffffffffffffffeull);

        tcg_gen_shl_tl(t2, t2, t1);

        gen_load_gpr(t1, rt);

        tcg_gen_and_tl(t1, t1, t2);

        tcg_temp_free(t2);

        tcg_gen_or_tl(t0, t0, t1);

        tcg_temp_free(t1);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LDPC:

        t1 = tcg_const_tl(pc_relative_pc(ctx));

        gen_op_addr_add(ctx, t0, t0, t1);

        tcg_temp_free(t1);

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_TEQ);

        gen_store_gpr(t0, rt);

        break;

#endif

    case OPC_LWPC:

        t1 = tcg_const_tl(pc_relative_pc(ctx));

        gen_op_addr_add(ctx, t0, t0, t1);

        tcg_temp_free(t1);

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_TESL);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LWE:



    case OPC_LW:

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_TESL |

                           ctx->default_tcg_memop_mask);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LHE:



    case OPC_LH:

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_TESW |

                           ctx->default_tcg_memop_mask);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LHUE:



    case OPC_LHU:

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_TEUW |

                           ctx->default_tcg_memop_mask);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LBE:



    case OPC_LB:

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_SB);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LBUE:



    case OPC_LBU:

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_UB);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LWLE:



    case OPC_LWL:

        t1 = tcg_temp_new();

        /* Do a byte access to possibly trigger a page

           fault with the unaligned address.  */

        tcg_gen_qemu_ld_tl(t1, t0, mem_idx, MO_UB);

        tcg_gen_andi_tl(t1, t0, 3);

#ifndef TARGET_WORDS_BIGENDIAN

        tcg_gen_xori_tl(t1, t1, 3);

#endif

        tcg_gen_shli_tl(t1, t1, 3);

        tcg_gen_andi_tl(t0, t0, ~3);

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_TEUL);

        tcg_gen_shl_tl(t0, t0, t1);

        t2 = tcg_const_tl(-1);

        tcg_gen_shl_tl(t2, t2, t1);

        gen_load_gpr(t1, rt);

        tcg_gen_andc_tl(t1, t1, t2);

        tcg_temp_free(t2);

        tcg_gen_or_tl(t0, t0, t1);

        tcg_temp_free(t1);

        tcg_gen_ext32s_tl(t0, t0);

        gen_store_gpr(t0, rt);

        break;




    case OPC_LWR:

        t1 = tcg_temp_new();

        /* Do a byte access to possibly trigger a page

           fault with the unaligned address.  */

        tcg_gen_qemu_ld_tl(t1, t0, mem_idx, MO_UB);

        tcg_gen_andi_tl(t1, t0, 3);

#ifdef TARGET_WORDS_BIGENDIAN

        tcg_gen_xori_tl(t1, t1, 3);

#endif

        tcg_gen_shli_tl(t1, t1, 3);

        tcg_gen_andi_tl(t0, t0, ~3);

        tcg_gen_qemu_ld_tl(t0, t0, mem_idx, MO_TEUL);

        tcg_gen_shr_tl(t0, t0, t1);

        tcg_gen_xori_tl(t1, t1, 31);

        t2 = tcg_const_tl(0xfffffffeull);

        tcg_gen_shl_tl(t2, t2, t1);

        gen_load_gpr(t1, rt);

        tcg_gen_and_tl(t1, t1, t2);

        tcg_temp_free(t2);

        tcg_gen_or_tl(t0, t0, t1);

        tcg_temp_free(t1);

        tcg_gen_ext32s_tl(t0, t0);

        gen_store_gpr(t0, rt);

        break;

    case OPC_LLE:



    case OPC_LL:

    case R6_OPC_LL:

        op_ld_ll(t0, t0, mem_idx, ctx);

        gen_store_gpr(t0, rt);

        break;

    }

    tcg_temp_free(t0);

}

