    int max_fd = -1;

    int ret;

    bool busy;



    /*

     * If there are callbacks left that have been queued, we need to call then.

     * Do not call select in this case, because it is possible that the caller

     * does not need a complete flush (as is the case for qemu_aio_wait loops).

     */

    if (qemu_bh_poll()) {

        return true;

    }



    walking_handlers++;



    FD_ZERO(&rdfds);

    FD_ZERO(&wrfds);



    /* fill fd sets */

    busy = false;

    QLIST_FOREACH(node, &aio_handlers, node) {

        /* If there aren't pending AIO operations, don't invoke callbacks.

         * Otherwise, if there are no AIO requests, qemu_aio_wait() would

         * wait indefinitely.

         */

        if (node->io_flush) {

            if (node->io_flush(node->opaque) == 0) {

                continue;

            }

            busy = true;

        }

        if (!node->deleted && node->io_read) {

            FD_SET(node->fd, &rdfds);

            max_fd = MAX(max_fd, node->fd + 1);

        }

        if (!node->deleted && node->io_write) {

            FD_SET(node->fd, &wrfds);

            max_fd = MAX(max_fd, node->fd + 1);

        }

    }



    walking_handlers--;



    /* No AIO operations?  Get us out of here */

    if (!busy) {

        return false;

    }



    /* wait until next event */

    ret = select(max_fd, &rdfds, &wrfds, NULL, NULL);



    /* if we have any readable fds, dispatch event */

    if (ret > 0) {

        walking_handlers++;



        /* we have to walk very carefully in case

         * qemu_aio_set_fd_handler is called while we're walking */

        node = QLIST_FIRST(&aio_handlers);

        while (node) {

            AioHandler *tmp;



            if (!node->deleted &&

                FD_ISSET(node->fd, &rdfds) &&

                node->io_read) {

                node->io_read(node->opaque);

            }

            if (!node->deleted &&

                FD_ISSET(node->fd, &wrfds) &&

                node->io_write) {

                node->io_write(node->opaque);

            }



            tmp = node;

            node = QLIST_NEXT(node, node);



            if (tmp->deleted) {

                QLIST_REMOVE(tmp, node);

                g_free(tmp);

            }

        }



        walking_handlers--;

    }



    return true;

}

static uint64_t lsi_io_read(void *opaque, target_phys_addr_t addr,

                            unsigned size)

{

    LSIState *s = opaque;

    return lsi_reg_readb(s, addr & 0xff);

}

static int ccid_handle_data(USBDevice *dev, USBPacket *p)

{

    USBCCIDState *s = DO_UPCAST(USBCCIDState, dev, dev);

    int ret = 0;

    uint8_t *data = p->data;

    int len = p->len;



    switch (p->pid) {

    case USB_TOKEN_OUT:

        ret = ccid_handle_bulk_out(s, p);

        break;



    case USB_TOKEN_IN:

        switch (p->devep & 0xf) {

        case CCID_BULK_IN_EP:

            if (!len) {

                ret = USB_RET_NAK;

            } else {

                ret = ccid_bulk_in_copy_to_guest(s, data, len);

            }

            break;

        case CCID_INT_IN_EP:

            if (s->notify_slot_change) {

                /* page 56, RDR_to_PC_NotifySlotChange */

                data[0] = CCID_MESSAGE_TYPE_RDR_to_PC_NotifySlotChange;

                data[1] = s->bmSlotICCState;

                ret = 2;

                s->notify_slot_change = false;

                s->bmSlotICCState &= ~SLOT_0_CHANGED_MASK;

                DPRINTF(s, D_INFO,

                        "handle_data: int_in: notify_slot_change %X, "

                        "requested len %d\n",

                        s->bmSlotICCState, len);

            }

            break;

        default:

            DPRINTF(s, 1, "Bad endpoint\n");

            break;

        }

        break;

    default:

        DPRINTF(s, 1, "Bad token\n");

        ret = USB_RET_STALL;

        break;

    }



    return ret;

}

