static void rtas_ibm_write_pci_config(sPAPREnvironment *spapr,

                                      uint32_t token, uint32_t nargs,

                                      target_ulong args,

                                      uint32_t nret, target_ulong rets)

{

    uint32_t val, size, addr;

    uint64_t buid = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 2);

    PCIDevice *dev = find_dev(spapr, buid, rtas_ld(args, 0));



    if (!dev) {

        rtas_st(rets, 0, -1);

        return;

    }

    val = rtas_ld(args, 4);

    size = rtas_ld(args, 3);

    addr = rtas_pci_cfgaddr(rtas_ld(args, 0));

    pci_default_write_config(dev, addr, val, size);

    rtas_st(rets, 0, 0);

}

static int vhdx_create(const char *filename, QEMUOptionParameter *options,

                       Error **errp)

{

    int ret = 0;

    uint64_t image_size = (uint64_t) 2 * GiB;

    uint32_t log_size   = 1 * MiB;

    uint32_t block_size = 0;

    uint64_t signature;

    uint64_t metadata_offset;

    bool use_zero_blocks = false;



    gunichar2 *creator = NULL;

    glong creator_items;

    BlockDriverState *bs;

    const char *type = NULL;

    VHDXImageType image_type;

    Error *local_err = NULL;



    while (options && options->name) {

        if (!strcmp(options->name, BLOCK_OPT_SIZE)) {

            image_size = options->value.n;

        } else if (!strcmp(options->name, VHDX_BLOCK_OPT_LOG_SIZE)) {

            log_size = options->value.n;

        } else if (!strcmp(options->name, VHDX_BLOCK_OPT_BLOCK_SIZE)) {

            block_size = options->value.n;

        } else if (!strcmp(options->name, BLOCK_OPT_SUBFMT)) {

            type = options->value.s;

        } else if (!strcmp(options->name, VHDX_BLOCK_OPT_ZERO)) {

            use_zero_blocks = options->value.n != 0;

        }

        options++;

    }



    if (image_size > VHDX_MAX_IMAGE_SIZE) {

        error_setg_errno(errp, EINVAL, "Image size too large; max of 64TB");

        ret = -EINVAL;

        goto exit;

    }



    if (type == NULL) {

        type = "dynamic";

    }



    if (!strcmp(type, "dynamic")) {

        image_type = VHDX_TYPE_DYNAMIC;

    } else if (!strcmp(type, "fixed")) {

        image_type = VHDX_TYPE_FIXED;

    } else if (!strcmp(type, "differencing")) {

        error_setg_errno(errp, ENOTSUP,

                         "Differencing files not yet supported");

        ret = -ENOTSUP;

        goto exit;

    } else {

        ret = -EINVAL;

        goto exit;

    }



    /* These are pretty arbitrary, and mainly designed to keep the BAT

     * size reasonable to load into RAM */

    if (block_size == 0) {

        if (image_size > 32 * TiB) {

            block_size = 64 * MiB;

        } else if (image_size > (uint64_t) 100 * GiB) {

            block_size = 32 * MiB;

        } else if (image_size > 1 * GiB) {

            block_size = 16 * MiB;

        } else {

            block_size = 8 * MiB;

        }

    }





    /* make the log size close to what was specified, but must be

     * min 1MB, and multiple of 1MB */

    log_size = ROUND_UP(log_size, MiB);



    block_size = ROUND_UP(block_size, MiB);

    block_size = block_size > VHDX_BLOCK_SIZE_MAX ? VHDX_BLOCK_SIZE_MAX :

                                                    block_size;



    ret = bdrv_create_file(filename, options, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto exit;

    }



    ret = bdrv_file_open(&bs, filename, NULL, NULL, BDRV_O_RDWR, &local_err);

    if (ret < 0) {

        error_propagate(errp, local_err);

        goto exit;

    }



    /* Create (A) */



    /* The creator field is optional, but may be useful for

     * debugging / diagnostics */

    creator = g_utf8_to_utf16("QEMU v" QEMU_VERSION, -1, NULL,

                              &creator_items, NULL);

    signature = cpu_to_le64(VHDX_FILE_SIGNATURE);

    bdrv_pwrite(bs, VHDX_FILE_ID_OFFSET, &signature, sizeof(signature));

    if (ret < 0) {

        goto delete_and_exit;

    }

    if (creator) {

        bdrv_pwrite(bs, VHDX_FILE_ID_OFFSET + sizeof(signature), creator,

                    creator_items * sizeof(gunichar2));

        if (ret < 0) {

            goto delete_and_exit;

        }

    }





    /* Creates (B),(C) */

    ret = vhdx_create_new_headers(bs, image_size, log_size);

    if (ret < 0) {

        goto delete_and_exit;

    }



    /* Creates (D),(E),(G) explicitly. (F) created as by-product */

    ret = vhdx_create_new_region_table(bs, image_size, block_size, 512,

                                       log_size, use_zero_blocks, image_type,

                                       &metadata_offset);

    if (ret < 0) {

        goto delete_and_exit;

    }



    /* Creates (H) */

    ret = vhdx_create_new_metadata(bs, image_size, block_size, 512,

                                   metadata_offset, image_type);

    if (ret < 0) {

        goto delete_and_exit;

    }







delete_and_exit:

    bdrv_unref(bs);

exit:

    g_free(creator);

    return ret;

}

static int zero_single_l2(BlockDriverState *bs, uint64_t offset,

                          uint64_t nb_clusters, int flags)

{

    BDRVQcow2State *s = bs->opaque;

    uint64_t *l2_table;

    int l2_index;

    int ret;

    int i;



    ret = get_cluster_table(bs, offset, &l2_table, &l2_index);

    if (ret < 0) {

        return ret;

    }



    /* Limit nb_clusters to one L2 table */

    nb_clusters = MIN(nb_clusters, s->l2_size - l2_index);

    assert(nb_clusters <= INT_MAX);



    for (i = 0; i < nb_clusters; i++) {

        uint64_t old_offset;



        old_offset = be64_to_cpu(l2_table[l2_index + i]);



        /* Update L2 entries */

        qcow2_cache_entry_mark_dirty(bs, s->l2_table_cache, l2_table);

        if (old_offset & QCOW_OFLAG_COMPRESSED || flags & BDRV_REQ_MAY_UNMAP) {

            l2_table[l2_index + i] = cpu_to_be64(QCOW_OFLAG_ZERO);

            qcow2_free_any_clusters(bs, old_offset, 1, QCOW2_DISCARD_REQUEST);

        } else {

            l2_table[l2_index + i] |= cpu_to_be64(QCOW_OFLAG_ZERO);

        }

    }



    qcow2_cache_put(bs, s->l2_table_cache, (void **) &l2_table);



    return nb_clusters;

}

static int megasas_dcmd_set_properties(MegasasState *s, MegasasCmd *cmd)

{

    struct mfi_ctrl_props info;

    size_t dcmd_size = sizeof(info);



    if (cmd->iov_size < dcmd_size) {

        trace_megasas_dcmd_invalid_xfer_len(cmd->index, cmd->iov_size,

                                            dcmd_size);

        return MFI_STAT_INVALID_PARAMETER;

    }

    dma_buf_write((uint8_t *)&info, cmd->iov_size, &cmd->qsg);

    trace_megasas_dcmd_unsupported(cmd->index, cmd->iov_size);

    return MFI_STAT_OK;

}

static int fd_open(BlockDriverState *bs)

{

    BDRVRawState *s = bs->opaque;

    int last_media_present;



    if (s->type != FTYPE_FD)

        return 0;

    last_media_present = (s->fd >= 0);

    if (s->fd >= 0 &&

        (qemu_get_clock(rt_clock) - s->fd_open_time) >= FD_OPEN_TIMEOUT) {

        close(s->fd);

        s->fd = -1;

        raw_close_fd_pool(s);

#ifdef DEBUG_FLOPPY

        printf("Floppy closed\n");

#endif

    }

    if (s->fd < 0) {

        if (s->fd_got_error &&

            (qemu_get_clock(rt_clock) - s->fd_error_time) < FD_OPEN_TIMEOUT) {

#ifdef DEBUG_FLOPPY

            printf("No floppy (open delayed)\n");

#endif

            return -EIO;

        }

        s->fd = open(bs->filename, s->fd_open_flags);

        if (s->fd < 0) {

            s->fd_error_time = qemu_get_clock(rt_clock);

            s->fd_got_error = 1;

            if (last_media_present)

                s->fd_media_changed = 1;

#ifdef DEBUG_FLOPPY

            printf("No floppy\n");

#endif

            return -EIO;

        }

#ifdef DEBUG_FLOPPY

        printf("Floppy opened\n");

#endif

    }

    if (!last_media_present)

        s->fd_media_changed = 1;

    s->fd_open_time = qemu_get_clock(rt_clock);

    s->fd_got_error = 0;

    return 0;

}

static void qdev_print(Monitor *mon, DeviceState *dev, int indent)

{

    BusState *child;

    qdev_printf("dev: %s, id \"%s\"\n", dev->info->name,

                dev->id ? dev->id : "");

    indent += 2;

    if (dev->num_gpio_in) {

        qdev_printf("gpio-in %d\n", dev->num_gpio_in);

    }

    if (dev->num_gpio_out) {

        qdev_printf("gpio-out %d\n", dev->num_gpio_out);

    }

    qdev_print_props(mon, dev, dev->info->props, "dev", indent);

    qdev_print_props(mon, dev, dev->parent_bus->info->props, "bus", indent);

    if (dev->parent_bus->info->print_dev)

        dev->parent_bus->info->print_dev(mon, dev, indent);

    LIST_FOREACH(child, &dev->child_bus, sibling) {

        qbus_print(mon, child, indent);

    }

}

static int qcow2_load_vmstate(BlockDriverState *bs, QEMUIOVector *qiov,

                              int64_t pos)

{

    BDRVQcow2State *s = bs->opaque;

    bool zero_beyond_eof = bs->zero_beyond_eof;

    int ret;



    BLKDBG_EVENT(bs->file, BLKDBG_VMSTATE_LOAD);

    bs->zero_beyond_eof = false;

    ret = bdrv_preadv(bs, qcow2_vm_state_offset(s) + pos, qiov);

    bs->zero_beyond_eof = zero_beyond_eof;



    return ret;

}

int qemu_acl_insert(qemu_acl *acl,

                    int deny,

                    const char *match,

                    int index)

{

    qemu_acl_entry *entry;

    qemu_acl_entry *tmp;

    int i = 0;



    if (index <= 0)

        return -1;

    if (index >= acl->nentries)

        return qemu_acl_append(acl, deny, match);





    entry = qemu_malloc(sizeof(*entry));

    entry->match = qemu_strdup(match);

    entry->deny = deny;



    TAILQ_FOREACH(tmp, &acl->entries, next) {

        i++;

        if (i == index) {

            TAILQ_INSERT_BEFORE(tmp, entry, next);

            acl->nentries++;

            break;

        }

    }



    return i;

}

