RTCState *rtc_mm_init(target_phys_addr_t base, int it_shift, qemu_irq irq,

                      int base_year)

{

    RTCState *s;

    int io_memory;



    s = qemu_mallocz(sizeof(RTCState));



    s->irq = irq;

    s->cmos_data[RTC_REG_A] = 0x26;

    s->cmos_data[RTC_REG_B] = 0x02;

    s->cmos_data[RTC_REG_C] = 0x00;

    s->cmos_data[RTC_REG_D] = 0x80;



    s->base_year = base_year;

    rtc_set_date_from_host(s);



    s->periodic_timer = qemu_new_timer(rtc_clock, rtc_periodic_timer, s);

    s->second_timer = qemu_new_timer(rtc_clock, rtc_update_second, s);

    s->second_timer2 = qemu_new_timer(rtc_clock, rtc_update_second2, s);



    s->next_second_time =

        qemu_get_clock(rtc_clock) + (get_ticks_per_sec() * 99) / 100;

    qemu_mod_timer(s->second_timer2, s->next_second_time);



    io_memory = cpu_register_io_memory(rtc_mm_read, rtc_mm_write, s);

    cpu_register_physical_memory(base, 2 << it_shift, io_memory);



    register_savevm("mc146818rtc", base, 1, rtc_save, rtc_load, s);

#ifdef TARGET_I386

    if (rtc_td_hack)

        register_savevm("mc146818rtc-td", base, 1, rtc_save_td, rtc_load_td, s);

#endif

    qemu_register_reset(rtc_reset, s);

    return s;

}

INLINE float64 packFloat64( flag zSign, int16 zExp, bits64 zSig )

{



    return ( ( (bits64) zSign )<<63 ) + ( ( (bits64) zExp )<<52 ) + zSig;



}

static int qcow_create2(const char *filename, int64_t total_size,

                        const char *backing_file, const char *backing_format,

                        int flags, size_t cluster_size, int prealloc)

{



    int fd, header_size, backing_filename_len, l1_size, i, shift, l2_bits;

    int ref_clusters, backing_format_len = 0;

    QCowHeader header;

    uint64_t tmp, offset;

    QCowCreateState s1, *s = &s1;

    QCowExtension ext_bf = {0, 0};





    memset(s, 0, sizeof(*s));



    fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC | O_BINARY, 0644);

    if (fd < 0)

        return -1;

    memset(&header, 0, sizeof(header));

    header.magic = cpu_to_be32(QCOW_MAGIC);

    header.version = cpu_to_be32(QCOW_VERSION);

    header.size = cpu_to_be64(total_size * 512);

    header_size = sizeof(header);

    backing_filename_len = 0;

    if (backing_file) {

        if (backing_format) {

            ext_bf.magic = QCOW_EXT_MAGIC_BACKING_FORMAT;

            backing_format_len = strlen(backing_format);

            ext_bf.len = (backing_format_len + 7) & ~7;

            header_size += ((sizeof(ext_bf) + ext_bf.len + 7) & ~7);

        }

        header.backing_file_offset = cpu_to_be64(header_size);

        backing_filename_len = strlen(backing_file);

        header.backing_file_size = cpu_to_be32(backing_filename_len);

        header_size += backing_filename_len;

    }



    /* Cluster size */

    s->cluster_bits = get_bits_from_size(cluster_size);

    if (s->cluster_bits < MIN_CLUSTER_BITS ||

        s->cluster_bits > MAX_CLUSTER_BITS)

    {

        fprintf(stderr, "Cluster size must be a power of two between "

            "%d and %dk\n",

            1 << MIN_CLUSTER_BITS,

            1 << (MAX_CLUSTER_BITS - 10));

        return -EINVAL;

    }

    s->cluster_size = 1 << s->cluster_bits;



    header.cluster_bits = cpu_to_be32(s->cluster_bits);

    header_size = (header_size + 7) & ~7;

    if (flags & BLOCK_FLAG_ENCRYPT) {

        header.crypt_method = cpu_to_be32(QCOW_CRYPT_AES);

    } else {

        header.crypt_method = cpu_to_be32(QCOW_CRYPT_NONE);

    }

    l2_bits = s->cluster_bits - 3;

    shift = s->cluster_bits + l2_bits;

    l1_size = (((total_size * 512) + (1LL << shift) - 1) >> shift);

    offset = align_offset(header_size, s->cluster_size);

    s->l1_table_offset = offset;

    header.l1_table_offset = cpu_to_be64(s->l1_table_offset);

    header.l1_size = cpu_to_be32(l1_size);

    offset += align_offset(l1_size * sizeof(uint64_t), s->cluster_size);



    s->refcount_table = qemu_mallocz(s->cluster_size);



    s->refcount_table_offset = offset;

    header.refcount_table_offset = cpu_to_be64(offset);

    header.refcount_table_clusters = cpu_to_be32(1);

    offset += s->cluster_size;

    s->refcount_block_offset = offset;



    /* count how many refcount blocks needed */

    tmp = offset >> s->cluster_bits;

    ref_clusters = (tmp >> (s->cluster_bits - REFCOUNT_SHIFT)) + 1;

    for (i=0; i < ref_clusters; i++) {

        s->refcount_table[i] = cpu_to_be64(offset);

        offset += s->cluster_size;

    }



    s->refcount_block = qemu_mallocz(ref_clusters * s->cluster_size);



    /* update refcounts */

    qcow2_create_refcount_update(s, 0, header_size);

    qcow2_create_refcount_update(s, s->l1_table_offset,

        l1_size * sizeof(uint64_t));

    qcow2_create_refcount_update(s, s->refcount_table_offset, s->cluster_size);

    qcow2_create_refcount_update(s, s->refcount_block_offset,

        ref_clusters * s->cluster_size);



    /* write all the data */

    write(fd, &header, sizeof(header));

    if (backing_file) {

        if (backing_format_len) {

            char zero[16];

            int d = ext_bf.len - backing_format_len;



            memset(zero, 0, sizeof(zero));

            cpu_to_be32s(&ext_bf.magic);

            cpu_to_be32s(&ext_bf.len);

            write(fd, &ext_bf, sizeof(ext_bf));

            write(fd, backing_format, backing_format_len);

            if (d>0) {

                write(fd, zero, d);

            }

        }

        write(fd, backing_file, backing_filename_len);

    }

    lseek(fd, s->l1_table_offset, SEEK_SET);

    tmp = 0;

    for(i = 0;i < l1_size; i++) {

        write(fd, &tmp, sizeof(tmp));

    }

    lseek(fd, s->refcount_table_offset, SEEK_SET);

    write(fd, s->refcount_table, s->cluster_size);



    lseek(fd, s->refcount_block_offset, SEEK_SET);

    write(fd, s->refcount_block, ref_clusters * s->cluster_size);



    qemu_free(s->refcount_table);

    qemu_free(s->refcount_block);

    close(fd);



    /* Preallocate metadata */

    if (prealloc) {

        BlockDriverState *bs;

        bs = bdrv_new("");

        bdrv_open(bs, filename, BDRV_O_CACHE_WB);

        preallocate(bs);

        bdrv_close(bs);

    }



    return 0;

}

static void scsi_cd_change_media_cb(void *opaque, bool load)

{

    SCSIDiskState *s = opaque;



    /*

     * When a CD gets changed, we have to report an ejected state and

     * then a loaded state to guests so that they detect tray

     * open/close and media change events.  Guests that do not use

     * GET_EVENT_STATUS_NOTIFICATION to detect such tray open/close

     * states rely on this behavior.

     *

     * media_changed governs the state machine used for unit attention

     * report.  media_event is used by GET EVENT STATUS NOTIFICATION.

     */

    s->media_changed = load;

    s->tray_open = !load;

    s->qdev.unit_attention = SENSE_CODE(UNIT_ATTENTION_NO_MEDIUM);

    s->media_event = true;

    s->eject_request = false;

}

static int check_directory_consistency(BDRVVVFATState *s,

	int cluster_num, const char* path)

{

    int ret = 0;

    unsigned char* cluster = g_malloc(s->cluster_size);

    direntry_t* direntries = (direntry_t*)cluster;

    mapping_t* mapping = find_mapping_for_cluster(s, cluster_num);



    long_file_name lfn;

    int path_len = strlen(path);

    char path2[PATH_MAX];



    assert(path_len < PATH_MAX); /* len was tested before! */

    pstrcpy(path2, sizeof(path2), path);

    path2[path_len] = '/';

    path2[path_len + 1] = '\0';



    if (mapping) {

	const char* basename = get_basename(mapping->path);

	const char* basename2 = get_basename(path);



	assert(mapping->mode & MODE_DIRECTORY);



	assert(mapping->mode & MODE_DELETED);

	mapping->mode &= ~MODE_DELETED;



	if (strcmp(basename, basename2))

	    schedule_rename(s, cluster_num, g_strdup(path));

    } else

	/* new directory */

	schedule_mkdir(s, cluster_num, g_strdup(path));



    lfn_init(&lfn);

    do {

	int i;

	int subret = 0;



	ret++;



	if (s->used_clusters[cluster_num] & USED_ANY) {

	    fprintf(stderr, "cluster %d used more than once\n", (int)cluster_num);

	    return 0;

	}

	s->used_clusters[cluster_num] = USED_DIRECTORY;



DLOG(fprintf(stderr, "read cluster %d (sector %d)\n", (int)cluster_num, (int)cluster2sector(s, cluster_num)));

	subret = vvfat_read(s->bs, cluster2sector(s, cluster_num), cluster,

		s->sectors_per_cluster);

	if (subret) {

	    fprintf(stderr, "Error fetching direntries\n");

	fail:

	    free(cluster);

	    return 0;

	}



	for (i = 0; i < 0x10 * s->sectors_per_cluster; i++) {

	    int cluster_count = 0;



DLOG(fprintf(stderr, "check direntry %d: \n", i); print_direntry(direntries + i));

	    if (is_volume_label(direntries + i) || is_dot(direntries + i) ||

		    is_free(direntries + i))

		continue;



	    subret = parse_long_name(&lfn, direntries + i);

	    if (subret < 0) {

		fprintf(stderr, "Error in long name\n");

		goto fail;

	    }

	    if (subret == 0 || is_free(direntries + i))

		continue;



	    if (fat_chksum(direntries+i) != lfn.checksum) {

		subret = parse_short_name(s, &lfn, direntries + i);

		if (subret < 0) {

		    fprintf(stderr, "Error in short name (%d)\n", subret);

		    goto fail;

		}

		if (subret > 0 || !strcmp((char*)lfn.name, ".")

			|| !strcmp((char*)lfn.name, ".."))

		    continue;

	    }

	    lfn.checksum = 0x100; /* cannot use long name twice */



	    if (path_len + 1 + lfn.len >= PATH_MAX) {

		fprintf(stderr, "Name too long: %s/%s\n", path, lfn.name);

		goto fail;

	    }

            pstrcpy(path2 + path_len + 1, sizeof(path2) - path_len - 1,

                    (char*)lfn.name);



	    if (is_directory(direntries + i)) {

		if (begin_of_direntry(direntries + i) == 0) {

		    DLOG(fprintf(stderr, "invalid begin for directory: %s\n", path2); print_direntry(direntries + i));

		    goto fail;

		}

		cluster_count = check_directory_consistency(s,

			begin_of_direntry(direntries + i), path2);

		if (cluster_count == 0) {

		    DLOG(fprintf(stderr, "problem in directory %s:\n", path2); print_direntry(direntries + i));

		    goto fail;

		}

	    } else if (is_file(direntries + i)) {

		/* check file size with FAT */

		cluster_count = get_cluster_count_for_direntry(s, direntries + i, path2);

		if (cluster_count !=

			(le32_to_cpu(direntries[i].size) + s->cluster_size

			 - 1) / s->cluster_size) {

		    DLOG(fprintf(stderr, "Cluster count mismatch\n"));

		    goto fail;

		}

	    } else

                abort(); /* cluster_count = 0; */



	    ret += cluster_count;

	}



	cluster_num = modified_fat_get(s, cluster_num);

    } while(!fat_eof(s, cluster_num));



    free(cluster);

    return ret;

}

static void scsi_disk_emulate_write_data(SCSIRequest *req)

{

    SCSIDiskReq *r = DO_UPCAST(SCSIDiskReq, req, req);



    if (r->iov.iov_len) {

        int buflen = r->iov.iov_len;

        DPRINTF("Write buf_len=%zd\n", buflen);

        r->iov.iov_len = 0;

        scsi_req_data(&r->req, buflen);

        return;

    }



    switch (req->cmd.buf[0]) {

    case MODE_SELECT:

    case MODE_SELECT_10:

        /* This also clears the sense buffer for REQUEST SENSE.  */

        scsi_req_complete(&r->req, GOOD);

        break;



    default:

        abort();

    }

}

bool tcg_cpu_exec(void)

{

    int ret = 0;



    if (next_cpu == NULL)

        next_cpu = first_cpu;

    for (; next_cpu != NULL; next_cpu = next_cpu->next_cpu) {

        CPUState *env = cur_cpu = next_cpu;



        qemu_clock_enable(vm_clock,

                          (cur_cpu->singlestep_enabled & SSTEP_NOTIMER) == 0);



        if (qemu_alarm_pending())

            break;

        if (cpu_can_run(env))

            ret = qemu_cpu_exec(env);

        else if (env->stop)

            break;



        if (ret == EXCP_DEBUG) {

            gdb_set_stop_cpu(env);

            debug_requested = EXCP_DEBUG;

            break;

        }

    }

    return tcg_has_work();

}

static void memory_region_dispatch_write(MemoryRegion *mr,

                                         hwaddr addr,

                                         uint64_t data,

                                         unsigned size)

{

    if (!memory_region_access_valid(mr, addr, size, true)) {

        return; /* FIXME: better signalling */

    }



    adjust_endianness(mr, &data, size);



    if (!mr->ops->write) {

        mr->ops->old_mmio.write[bitops_ctzl(size)](mr->opaque, addr, data);

        return;

    }



    /* FIXME: support unaligned access */

    access_with_adjusted_size(addr, &data, size,

                              mr->ops->impl.min_access_size,

                              mr->ops->impl.max_access_size,

                              memory_region_write_accessor, mr);

}

int bdrv_eject(BlockDriverState *bs, int eject_flag)

{

    BlockDriver *drv = bs->drv;



    if (bs->locked) {

        return -EBUSY;

    }



    if (drv && drv->bdrv_eject) {

        drv->bdrv_eject(bs, eject_flag);

    }

    bs->tray_open = eject_flag;

    return 0;

}

static struct XenDevice *xen_be_del_xendev(int dom, int dev)

{

    struct XenDevice *xendev, *xnext;



    /*

     * This is pretty much like QTAILQ_FOREACH(xendev, &xendevs, next) but

     * we save the next pointer in xnext because we might free xendev.

     */

    xnext = xendevs.tqh_first;

    while (xnext) {

        xendev = xnext;

        xnext = xendev->next.tqe_next;



        if (xendev->dom != dom) {

            continue;

        }

        if (xendev->dev != dev && dev != -1) {

            continue;

        }



        if (xendev->ops->free) {

            xendev->ops->free(xendev);

        }



        if (xendev->fe) {

            char token[XEN_BUFSIZE];

            snprintf(token, sizeof(token), "fe:%p", xendev);

            xs_unwatch(xenstore, xendev->fe, token);

            g_free(xendev->fe);

        }



        if (xendev->evtchndev != XC_HANDLER_INITIAL_VALUE) {

            xc_evtchn_close(xendev->evtchndev);

        }

        if (xendev->gnttabdev != XC_HANDLER_INITIAL_VALUE) {

            xc_gnttab_close(xendev->gnttabdev);

        }



        QTAILQ_REMOVE(&xendevs, xendev, next);

        g_free(xendev);

    }

    return NULL;

}

static void kvm_init_irq_routing(KVMState *s)

{

    int gsi_count;



    gsi_count = kvm_check_extension(s, KVM_CAP_IRQ_ROUTING);

    if (gsi_count > 0) {

        unsigned int gsi_bits, i;



        /* Round up so we can search ints using ffs */

        gsi_bits = ALIGN(gsi_count, 32);

        s->used_gsi_bitmap = g_malloc0(gsi_bits / 8);

        s->max_gsi = gsi_bits;



        /* Mark any over-allocated bits as already in use */

        for (i = gsi_count; i < gsi_bits; i++) {

            set_gsi(s, i);

        }

    }



    s->irq_routes = g_malloc0(sizeof(*s->irq_routes));

    s->nr_allocated_irq_routes = 0;



    kvm_arch_init_irq_routing(s);

}

static void uart_read_rx_fifo(UartState *s, uint32_t *c)

{

    if ((s->r[R_CR] & UART_CR_RX_DIS) || !(s->r[R_CR] & UART_CR_RX_EN)) {

        return;

    }



    if (s->rx_count) {

        uint32_t rx_rpos =

                (RX_FIFO_SIZE + s->rx_wpos - s->rx_count) % RX_FIFO_SIZE;

        *c = s->rx_fifo[rx_rpos];

        s->rx_count--;



        qemu_chr_accept_input(s->chr);

    } else {

        *c = 0;

    }



    uart_update_status(s);

}

static void setup_frame(int sig, struct target_sigaction *ka,

                        target_sigset_t *set, CPUAlphaState *env)

{

    abi_ulong frame_addr, r26;

    struct target_sigframe *frame;

    int err = 0;



    frame_addr = get_sigframe(ka, env, sizeof(*frame));

    if (!lock_user_struct(VERIFY_WRITE, frame, frame_addr, 0)) {

        goto give_sigsegv;

    }



    err |= setup_sigcontext(&frame->sc, env, frame_addr, set);



    if (ka->sa_restorer) {

        r26 = ka->sa_restorer;

    } else {

        __put_user(INSN_MOV_R30_R16, &frame->retcode[0]);

        __put_user(INSN_LDI_R0 + TARGET_NR_sigreturn,

                   &frame->retcode[1]);

        __put_user(INSN_CALLSYS, &frame->retcode[2]);

        /* imb() */

        r26 = frame_addr;

    }



    unlock_user_struct(frame, frame_addr, 1);



    if (err) {

    give_sigsegv:

        if (sig == TARGET_SIGSEGV) {

            ka->_sa_handler = TARGET_SIG_DFL;

        }

        force_sig(TARGET_SIGSEGV);

    }



    env->ir[IR_RA] = r26;

    env->ir[IR_PV] = env->pc = ka->_sa_handler;

    env->ir[IR_A0] = sig;

    env->ir[IR_A1] = 0;

    env->ir[IR_A2] = frame_addr + offsetof(struct target_sigframe, sc);

    env->ir[IR_SP] = frame_addr;

}

static void spin_kick(void *data)

{

    SpinKick *kick = data;

    CPUState *cpu = CPU(kick->cpu);

    CPUPPCState *env = &kick->cpu->env;

    SpinInfo *curspin = kick->spin;

    hwaddr map_size = 64 * 1024 * 1024;

    hwaddr map_start;



    cpu_synchronize_state(cpu);

    stl_p(&curspin->pir, env->spr[SPR_PIR]);

    env->nip = ldq_p(&curspin->addr) & (map_size - 1);

    env->gpr[3] = ldq_p(&curspin->r3);

    env->gpr[4] = 0;

    env->gpr[5] = 0;

    env->gpr[6] = 0;

    env->gpr[7] = map_size;

    env->gpr[8] = 0;

    env->gpr[9] = 0;



    map_start = ldq_p(&curspin->addr) & ~(map_size - 1);

    mmubooke_create_initial_mapping(env, 0, map_start, map_size);



    cpu->halted = 0;

    cpu->exception_index = -1;

    cpu->stopped = false;

    qemu_cpu_kick(cpu);

}

static void sd_blk_write(SDState *sd, uint64_t addr, uint32_t len)

{

    uint64_t end = addr + len;



    if ((addr & 511) || len < 512)

        if (!sd->bdrv || bdrv_read(sd->bdrv, addr >> 9, sd->buf, 1) < 0) {

            fprintf(stderr, "sd_blk_write: read error on host side\n");

            return;

        }



    if (end > (addr & ~511) + 512) {

        memcpy(sd->buf + (addr & 511), sd->data, 512 - (addr & 511));

        if (bdrv_write(sd->bdrv, addr >> 9, sd->buf, 1) < 0) {

            fprintf(stderr, "sd_blk_write: write error on host side\n");

            return;

        }



        if (bdrv_read(sd->bdrv, end >> 9, sd->buf, 1) < 0) {

            fprintf(stderr, "sd_blk_write: read error on host side\n");

            return;

        }

        memcpy(sd->buf, sd->data + 512 - (addr & 511), end & 511);

        if (bdrv_write(sd->bdrv, end >> 9, sd->buf, 1) < 0) {

            fprintf(stderr, "sd_blk_write: write error on host side\n");

        }

    } else {

        memcpy(sd->buf + (addr & 511), sd->data, len);

        if (!sd->bdrv || bdrv_write(sd->bdrv, addr >> 9, sd->buf, 1) < 0) {

            fprintf(stderr, "sd_blk_write: write error on host side\n");

        }

    }

}

