static int ehci_process_itd(EHCIState *ehci,

                            EHCIitd *itd)

{

    USBDevice *dev;

    USBEndpoint *ep;

    int ret;

    uint32_t i, len, pid, dir, devaddr, endp;

    uint32_t pg, off, ptr1, ptr2, max, mult;



    dir =(itd->bufptr[1] & ITD_BUFPTR_DIRECTION);

    devaddr = get_field(itd->bufptr[0], ITD_BUFPTR_DEVADDR);

    endp = get_field(itd->bufptr[0], ITD_BUFPTR_EP);

    max = get_field(itd->bufptr[1], ITD_BUFPTR_MAXPKT);

    mult = get_field(itd->bufptr[2], ITD_BUFPTR_MULT);



    for(i = 0; i < 8; i++) {

        if (itd->transact[i] & ITD_XACT_ACTIVE) {

            pg   = get_field(itd->transact[i], ITD_XACT_PGSEL);

            off  = itd->transact[i] & ITD_XACT_OFFSET_MASK;

            ptr1 = (itd->bufptr[pg] & ITD_BUFPTR_MASK);

            ptr2 = (itd->bufptr[pg+1] & ITD_BUFPTR_MASK);

            len  = get_field(itd->transact[i], ITD_XACT_LENGTH);



            if (len > max * mult) {

                len = max * mult;

            }



            if (len > BUFF_SIZE) {

                return USB_RET_PROCERR;

            }



            pci_dma_sglist_init(&ehci->isgl, &ehci->dev, 2);

            if (off + len > 4096) {

                /* transfer crosses page border */

                uint32_t len2 = off + len - 4096;

                uint32_t len1 = len - len2;

                qemu_sglist_add(&ehci->isgl, ptr1 + off, len1);

                qemu_sglist_add(&ehci->isgl, ptr2, len2);

            } else {

                qemu_sglist_add(&ehci->isgl, ptr1 + off, len);

            }



            pid = dir ? USB_TOKEN_IN : USB_TOKEN_OUT;



            dev = ehci_find_device(ehci, devaddr);

            ep = usb_ep_get(dev, pid, endp);

            usb_packet_setup(&ehci->ipacket, pid, ep);

            usb_packet_map(&ehci->ipacket, &ehci->isgl);



            ret = usb_handle_packet(dev, &ehci->ipacket);



            usb_packet_unmap(&ehci->ipacket);

            qemu_sglist_destroy(&ehci->isgl);



#if 0

            /*  In isoch, there is no facility to indicate a NAK so let's

             *  instead just complete a zero-byte transaction.  Setting

             *  DBERR seems too draconian.

             */



            if (ret == USB_RET_NAK) {

                if (ehci->isoch_pause > 0) {

                    DPRINTF("ISOCH: received a NAK but paused so returning\n");

                    ehci->isoch_pause--;

                    return 0;

                } else if (ehci->isoch_pause == -1) {

                    DPRINTF("ISOCH: recv NAK & isoch pause inactive, setting\n");

                    // Pause frindex for up to 50 msec waiting for data from

                    // remote

                    ehci->isoch_pause = 50;

                    return 0;

                } else {

                    DPRINTF("ISOCH: isoch pause timeout! return 0\n");

                    ret = 0;

                }

            } else {

                DPRINTF("ISOCH: received ACK, clearing pause\n");

                ehci->isoch_pause = -1;

            }

#else

            if (ret == USB_RET_NAK) {

                ret = 0;

            }

#endif



            if (ret >= 0) {

                if (!dir) {

                    /* OUT */

                    set_field(&itd->transact[i], len - ret, ITD_XACT_LENGTH);

                } else {

                    /* IN */

                    set_field(&itd->transact[i], ret, ITD_XACT_LENGTH);

                }



                if (itd->transact[i] & ITD_XACT_IOC) {

                    ehci_record_interrupt(ehci, USBSTS_INT);

                }

            }

            itd->transact[i] &= ~ITD_XACT_ACTIVE;

        }

    }

    return 0;

}

static int vdi_check(BlockDriverState *bs, BdrvCheckResult *res,

                     BdrvCheckMode fix)

{

    /* TODO: additional checks possible. */

    BDRVVdiState *s = (BDRVVdiState *)bs->opaque;

    uint32_t blocks_allocated = 0;

    uint32_t block;

    uint32_t *bmap;

    logout("\n");



    if (fix) {

        return -ENOTSUP;

    }



    bmap = g_try_malloc(s->header.blocks_in_image * sizeof(uint32_t));

    if (s->header.blocks_in_image && bmap == NULL) {

        res->check_errors++;

        return -ENOMEM;

    }



    memset(bmap, 0xff, s->header.blocks_in_image * sizeof(uint32_t));



    /* Check block map and value of blocks_allocated. */

    for (block = 0; block < s->header.blocks_in_image; block++) {

        uint32_t bmap_entry = le32_to_cpu(s->bmap[block]);

        if (VDI_IS_ALLOCATED(bmap_entry)) {

            if (bmap_entry < s->header.blocks_in_image) {

                blocks_allocated++;

                if (!VDI_IS_ALLOCATED(bmap[bmap_entry])) {

                    bmap[bmap_entry] = bmap_entry;

                } else {

                    fprintf(stderr, "ERROR: block index %" PRIu32

                            " also used by %" PRIu32 "\n", bmap[bmap_entry], bmap_entry);

                    res->corruptions++;

                }

            } else {

                fprintf(stderr, "ERROR: block index %" PRIu32

                        " too large, is %" PRIu32 "\n", block, bmap_entry);

                res->corruptions++;

            }

        }

    }

    if (blocks_allocated != s->header.blocks_allocated) {

        fprintf(stderr, "ERROR: allocated blocks mismatch, is %" PRIu32

               ", should be %" PRIu32 "\n",

               blocks_allocated, s->header.blocks_allocated);

        res->corruptions++;

    }



    g_free(bmap);



    return 0;

}

static void uart_write(void *opaque, hwaddr addr,

                       uint64_t value, unsigned size)

{

    LM32UartState *s = opaque;

    unsigned char ch = value;



    trace_lm32_uart_memory_write(addr, value);



    addr >>= 2;

    switch (addr) {

    case R_RXTX:

        if (s->chr) {



            qemu_chr_fe_write_all(s->chr, &ch, 1);

        }

        break;

    case R_IER:

    case R_LCR:

    case R_MCR:

    case R_DIV:

        s->regs[addr] = value;

        break;

    case R_IIR:

    case R_LSR:

    case R_MSR:

        error_report("lm32_uart: write access to read only register 0x"

                TARGET_FMT_plx, addr << 2);

        break;

    default:

        error_report("lm32_uart: write access to unknown register 0x"

                TARGET_FMT_plx, addr << 2);

        break;

    }

    uart_update_irq(s);

}

static void test_opts_parse_size(void)

{

    Error *err = NULL;

    QemuOpts *opts;



    /* Lower limit zero */

    opts = qemu_opts_parse(&opts_list_02, "size1=0", false, &error_abort);

    g_assert_cmpuint(opts_count(opts), ==, 1);

    g_assert_cmpuint(qemu_opt_get_size(opts, "size1", 1), ==, 0);



    /* Note: precision is 53 bits since we're parsing with strtod() */



    /* Around limit of precision: 2^53-1, 2^53, 2^54 */

    opts = qemu_opts_parse(&opts_list_02,

                           "size1=9007199254740991,"

                           "size2=9007199254740992,"

                           "size3=9007199254740993",

                           false, &error_abort);

    g_assert_cmpuint(opts_count(opts), ==, 3);

    g_assert_cmphex(qemu_opt_get_size(opts, "size1", 1),

                     ==, 0x1fffffffffffff);

    g_assert_cmphex(qemu_opt_get_size(opts, "size2", 1),

                     ==, 0x20000000000000);

    g_assert_cmphex(qemu_opt_get_size(opts, "size3", 1),

                     ==, 0x20000000000000);



    /* Close to signed upper limit 0x7ffffffffffffc00 (53 msbs set) */

    opts = qemu_opts_parse(&opts_list_02,

                           "size1=9223372036854774784," /* 7ffffffffffffc00 */

                           "size2=9223372036854775295", /* 7ffffffffffffdff */

                           false, &error_abort);

    g_assert_cmpuint(opts_count(opts), ==, 2);

    g_assert_cmphex(qemu_opt_get_size(opts, "size1", 1),

                     ==, 0x7ffffffffffffc00);

    g_assert_cmphex(qemu_opt_get_size(opts, "size2", 1),

                     ==, 0x7ffffffffffffc00);



    /* Close to actual upper limit 0xfffffffffffff800 (53 msbs set) */

    opts = qemu_opts_parse(&opts_list_02,

                           "size1=18446744073709549568," /* fffffffffffff800 */

                           "size2=18446744073709550591", /* fffffffffffffbff */

                           false, &error_abort);

    g_assert_cmpuint(opts_count(opts), ==, 2);

    g_assert_cmphex(qemu_opt_get_size(opts, "size1", 1),

                     ==, 0xfffffffffffff800);

    g_assert_cmphex(qemu_opt_get_size(opts, "size2", 1),

                     ==, 0xfffffffffffff800);



    /* Beyond limits */

    opts = qemu_opts_parse(&opts_list_02, "size1=-1", false, &err);

    error_free_or_abort(&err);

    g_assert(!opts);

    opts = qemu_opts_parse(&opts_list_02,

                           "size1=18446744073709550592", /* fffffffffffffc00 */

                           false, &error_abort);

    /* BUG: should reject */

    g_assert_cmpuint(opts_count(opts), ==, 1);

    g_assert_cmpuint(qemu_opt_get_size(opts, "size1", 1), ==, 0);



    /* Suffixes */

    opts = qemu_opts_parse(&opts_list_02, "size1=8b,size2=1.5k,size3=2M",

                           false, &error_abort);

    g_assert_cmpuint(opts_count(opts), ==, 3);

    g_assert_cmphex(qemu_opt_get_size(opts, "size1", 0), ==, 8);

    g_assert_cmphex(qemu_opt_get_size(opts, "size2", 0), ==, 1536);

    g_assert_cmphex(qemu_opt_get_size(opts, "size3", 0), ==, 2 * M_BYTE);

    opts = qemu_opts_parse(&opts_list_02, "size1=0.1G,size2=16777215T",

                           false, &error_abort);

    g_assert_cmpuint(opts_count(opts), ==, 2);

    g_assert_cmphex(qemu_opt_get_size(opts, "size1", 0), ==, G_BYTE / 10);

    g_assert_cmphex(qemu_opt_get_size(opts, "size2", 0),

                     ==, 16777215 * T_BYTE);



    /* Beyond limit with suffix */

    opts = qemu_opts_parse(&opts_list_02, "size1=16777216T",

                           false, &error_abort);

    /* BUG: should reject */

    g_assert_cmpuint(opts_count(opts), ==, 1);

    g_assert_cmpuint(qemu_opt_get_size(opts, "size1", 1), ==, 0);



    /* Trailing crap */

    opts = qemu_opts_parse(&opts_list_02, "size1=16E", false, &err);

    error_free_or_abort(&err);

    g_assert(!opts);

    opts = qemu_opts_parse(&opts_list_02, "size1=16Gi", false, &error_abort);

    /* BUG: should reject */

    g_assert_cmpuint(opts_count(opts), ==, 1);

    g_assert_cmpuint(qemu_opt_get_size(opts, "size1", 1), ==, 16 * G_BYTE);



    qemu_opts_reset(&opts_list_02);

}

