{

    unsigned int i;



    for (i = 0; i < ARRAY_SIZE(sparc_defs); i++) {

        (*cpu_fprintf)(f, "Sparc %16s IU " TARGET_FMT_lx " FPU %08x MMU %08x NWINS %d ",

