static void disas_simd_3same_logic(DisasContext *s, uint32_t insn)

{

    int rd = extract32(insn, 0, 5);

    int rn = extract32(insn, 5, 5);

    int rm = extract32(insn, 16, 5);

    int size = extract32(insn, 22, 2);

    bool is_u = extract32(insn, 29, 1);

    bool is_q = extract32(insn, 30, 1);

    TCGv_i64 tcg_op1 = tcg_temp_new_i64();

    TCGv_i64 tcg_op2 = tcg_temp_new_i64();

    TCGv_i64 tcg_res[2];

    int pass;



    tcg_res[0] = tcg_temp_new_i64();

    tcg_res[1] = tcg_temp_new_i64();



    for (pass = 0; pass < (is_q ? 2 : 1); pass++) {

        read_vec_element(s, tcg_op1, rn, pass, MO_64);

        read_vec_element(s, tcg_op2, rm, pass, MO_64);



        if (!is_u) {

            switch (size) {

            case 0: /* AND */

                tcg_gen_and_i64(tcg_res[pass], tcg_op1, tcg_op2);

                break;

            case 1: /* BIC */

                tcg_gen_andc_i64(tcg_res[pass], tcg_op1, tcg_op2);

                break;

            case 2: /* ORR */

                tcg_gen_or_i64(tcg_res[pass], tcg_op1, tcg_op2);

                break;

            case 3: /* ORN */

                tcg_gen_orc_i64(tcg_res[pass], tcg_op1, tcg_op2);

                break;

            }

        } else {

            if (size != 0) {

                /* B* ops need res loaded to operate on */

                read_vec_element(s, tcg_res[pass], rd, pass, MO_64);

            }



            switch (size) {

            case 0: /* EOR */

                tcg_gen_xor_i64(tcg_res[pass], tcg_op1, tcg_op2);

                break;

            case 1: /* BSL bitwise select */

                tcg_gen_xor_i64(tcg_op1, tcg_op1, tcg_op2);

                tcg_gen_and_i64(tcg_op1, tcg_op1, tcg_res[pass]);

                tcg_gen_xor_i64(tcg_res[pass], tcg_op2, tcg_op1);

                break;

            case 2: /* BIT, bitwise insert if true */

                tcg_gen_xor_i64(tcg_op1, tcg_op1, tcg_res[pass]);

                tcg_gen_and_i64(tcg_op1, tcg_op1, tcg_op2);

                tcg_gen_xor_i64(tcg_res[pass], tcg_res[pass], tcg_op1);

                break;

            case 3: /* BIF, bitwise insert if false */

                tcg_gen_xor_i64(tcg_op1, tcg_op1, tcg_res[pass]);

                tcg_gen_andc_i64(tcg_op1, tcg_op1, tcg_op2);

                tcg_gen_xor_i64(tcg_res[pass], tcg_res[pass], tcg_op1);

                break;

            }

        }

    }



    write_vec_element(s, tcg_res[0], rd, 0, MO_64);

    if (!is_q) {

        tcg_gen_movi_i64(tcg_res[1], 0);

    }

    write_vec_element(s, tcg_res[1], rd, 1, MO_64);



    tcg_temp_free_i64(tcg_op1);

    tcg_temp_free_i64(tcg_op2);

    tcg_temp_free_i64(tcg_res[0]);

    tcg_temp_free_i64(tcg_res[1]);

}

void net_check_clients(void)

{

    VLANState *vlan;

    VLANClientState *vc;

    int i;



    /* Don't warn about the default network setup that you get if

     * no command line -net or -netdev options are specified. There

     * are two cases that we would otherwise complain about:

     * (1) board doesn't support a NIC but the implicit "-net nic"

     * requested one

     * (2) CONFIG_SLIRP not set, in which case the implicit "-net nic"

     * sets up a nic that isn't connected to anything.

     */

    if (default_net) {

        return;

    }



    QTAILQ_FOREACH(vlan, &vlans, next) {

        int has_nic = 0, has_host_dev = 0;



        QTAILQ_FOREACH(vc, &vlan->clients, next) {

            switch (vc->info->type) {

            case NET_CLIENT_OPTIONS_KIND_NIC:

                has_nic = 1;

                break;

            case NET_CLIENT_OPTIONS_KIND_USER:

            case NET_CLIENT_OPTIONS_KIND_TAP:

            case NET_CLIENT_OPTIONS_KIND_SOCKET:

            case NET_CLIENT_OPTIONS_KIND_VDE:

                has_host_dev = 1;

                break;

            default: ;

            }

        }

        if (has_host_dev && !has_nic)

            fprintf(stderr, "Warning: vlan %d with no nics\n", vlan->id);

        if (has_nic && !has_host_dev)

            fprintf(stderr,

                    "Warning: vlan %d is not connected to host network\n",

                    vlan->id);

    }

    QTAILQ_FOREACH(vc, &non_vlan_clients, next) {

        if (!vc->peer) {

            fprintf(stderr, "Warning: %s %s has no peer\n",

                    vc->info->type == NET_CLIENT_OPTIONS_KIND_NIC ? "nic" : "netdev",

                    vc->name);

        }

    }



    /* Check that all NICs requested via -net nic actually got created.

     * NICs created via -device don't need to be checked here because

     * they are always instantiated.

     */

    for (i = 0; i < MAX_NICS; i++) {

        NICInfo *nd = &nd_table[i];

        if (nd->used && !nd->instantiated) {

            fprintf(stderr, "Warning: requested NIC (%s, model %s) "

                    "was not created (not supported by this machine?)\n",

                    nd->name ? nd->name : "anonymous",

                    nd->model ? nd->model : "unspecified");

        }

    }

}

static uint16_t read_u16(uint8_t *data, size_t offset)

{

    return ((data[offset] & 0xFF) << 8) | (data[offset + 1] & 0xFF);

}

static void parse_str(StringInputVisitor *siv, Error **errp)

{

    char *str = (char *) siv->string;

    long long start, end;

    Range *cur;

    char *endptr;



    if (siv->ranges) {

        return;

    }



    do {

        errno = 0;

        start = strtoll(str, &endptr, 0);

        if (errno == 0 && endptr > str) {

            if (*endptr == '\0') {

                cur = g_malloc0(sizeof(*cur));

                cur->begin = start;

                cur->end = start + 1;

                siv->ranges = g_list_insert_sorted_merged(siv->ranges, cur,

                                                          range_compare);

                cur = NULL;

                str = NULL;

            } else if (*endptr == '-') {

                str = endptr + 1;

                errno = 0;

                end = strtoll(str, &endptr, 0);

                if (errno == 0 && endptr > str && start <= end &&

                    (start > INT64_MAX - 65536 ||

                     end < start + 65536)) {

                    if (*endptr == '\0') {

                        cur = g_malloc0(sizeof(*cur));

                        cur->begin = start;

                        cur->end = end + 1;

                        siv->ranges =

                            g_list_insert_sorted_merged(siv->ranges,

                                                        cur,

                                                        range_compare);

                        cur = NULL;

                        str = NULL;

                    } else if (*endptr == ',') {

                        str = endptr + 1;

                        cur = g_malloc0(sizeof(*cur));

                        cur->begin = start;

                        cur->end = end + 1;

                        siv->ranges =

                            g_list_insert_sorted_merged(siv->ranges,

                                                        cur,

                                                        range_compare);

                        cur = NULL;

                    } else {

                        goto error;

                    }

                } else {

                    goto error;

                }

            } else if (*endptr == ',') {

                str = endptr + 1;

                cur = g_malloc0(sizeof(*cur));

                cur->begin = start;

                cur->end = start + 1;

                siv->ranges = g_list_insert_sorted_merged(siv->ranges,

                                                          cur,

                                                          range_compare);

                cur = NULL;

            } else {

                goto error;

            }

        } else {

            goto error;

        }

    } while (str);



    return;

error:

    g_list_foreach(siv->ranges, free_range, NULL);

    g_list_free(siv->ranges);

    siv->ranges = NULL;

}

