int pcilg_service_call(S390CPU *cpu, uint8_t r1, uint8_t r2)

{

    CPUS390XState *env = &cpu->env;

    S390PCIBusDevice *pbdev;

    uint64_t offset;

    uint64_t data;

    uint8_t len;

    uint32_t fh;

    uint8_t pcias;



    cpu_synchronize_state(CPU(cpu));



    if (env->psw.mask & PSW_MASK_PSTATE) {

        program_interrupt(env, PGM_PRIVILEGED, 4);

        return 0;

    }



    if (r2 & 0x1) {

        program_interrupt(env, PGM_SPECIFICATION, 4);

        return 0;

    }



    fh = env->regs[r2] >> 32;

    pcias = (env->regs[r2] >> 16) & 0xf;

    len = env->regs[r2] & 0xf;

    offset = env->regs[r2 + 1];



    pbdev = s390_pci_find_dev_by_fh(fh);

    if (!pbdev || !(pbdev->fh & FH_MASK_ENABLE)) {

        DPRINTF("pcilg no pci dev\n");

        setcc(cpu, ZPCI_PCI_LS_INVAL_HANDLE);

        return 0;

    }



    if (pbdev->lgstg_blocked) {

        setcc(cpu, ZPCI_PCI_LS_ERR);

        s390_set_status_code(env, r2, ZPCI_PCI_ST_BLOCKED);

        return 0;

    }



    if (pcias < 6) {

        if ((8 - (offset & 0x7)) < len) {

            program_interrupt(env, PGM_OPERAND, 4);

            return 0;

        }

        MemoryRegion *mr = pbdev->pdev->io_regions[pcias].memory;

        memory_region_dispatch_read(mr, offset, &data, len,

                                    MEMTXATTRS_UNSPECIFIED);

    } else if (pcias == 15) {

        if ((4 - (offset & 0x3)) < len) {

            program_interrupt(env, PGM_OPERAND, 4);

            return 0;

        }

        data =  pci_host_config_read_common(

                   pbdev->pdev, offset, pci_config_size(pbdev->pdev), len);



        switch (len) {

        case 1:

            break;

        case 2:

            data = bswap16(data);

            break;

        case 4:

            data = bswap32(data);

            break;

        case 8:

            data = bswap64(data);

            break;

        default:

            program_interrupt(env, PGM_OPERAND, 4);

            return 0;

        }

    } else {

        DPRINTF("invalid space\n");

        setcc(cpu, ZPCI_PCI_LS_ERR);

        s390_set_status_code(env, r2, ZPCI_PCI_ST_INVAL_AS);

        return 0;

    }



    env->regs[r1] = data;

    setcc(cpu, ZPCI_PCI_LS_OK);

    return 0;

}

int kvm_arch_put_registers(CPUState *cs, int level)

{

    struct kvm_one_reg reg;

    uint32_t fpr;

    uint64_t val;

    int i;

    int ret;



    ARMCPU *cpu = ARM_CPU(cs);

    CPUARMState *env = &cpu->env;



    /* If we are in AArch32 mode then we need to copy the AArch32 regs to the

     * AArch64 registers before pushing them out to 64-bit KVM.

     */

    if (!is_a64(env)) {

        aarch64_sync_32_to_64(env);

    }



    for (i = 0; i < 31; i++) {

        reg.id = AARCH64_CORE_REG(regs.regs[i]);

        reg.addr = (uintptr_t) &env->xregs[i];

        ret = kvm_vcpu_ioctl(cs, KVM_SET_ONE_REG, &reg);

        if (ret) {

            return ret;

        }

    }



    /* KVM puts SP_EL0 in regs.sp and SP_EL1 in regs.sp_el1. On the

     * QEMU side we keep the current SP in xregs[31] as well.

     */

    aarch64_save_sp(env, 1);



    reg.id = AARCH64_CORE_REG(regs.sp);

    reg.addr = (uintptr_t) &env->sp_el[0];

    ret = kvm_vcpu_ioctl(cs, KVM_SET_ONE_REG, &reg);

    if (ret) {

        return ret;

    }



    reg.id = AARCH64_CORE_REG(sp_el1);

    reg.addr = (uintptr_t) &env->sp_el[1];

    ret = kvm_vcpu_ioctl(cs, KVM_SET_ONE_REG, &reg);

    if (ret) {

        return ret;

    }



    /* Note that KVM thinks pstate is 64 bit but we use a uint32_t */

    if (is_a64(env)) {

        val = pstate_read(env);

    } else {

        val = cpsr_read(env);

    }

    reg.id = AARCH64_CORE_REG(regs.pstate);

    reg.addr = (uintptr_t) &val;

    ret = kvm_vcpu_ioctl(cs, KVM_SET_ONE_REG, &reg);

    if (ret) {

        return ret;

    }



    reg.id = AARCH64_CORE_REG(regs.pc);

    reg.addr = (uintptr_t) &env->pc;

    ret = kvm_vcpu_ioctl(cs, KVM_SET_ONE_REG, &reg);

    if (ret) {

        return ret;

    }



    reg.id = AARCH64_CORE_REG(elr_el1);

    reg.addr = (uintptr_t) &env->elr_el[1];

    ret = kvm_vcpu_ioctl(cs, KVM_SET_ONE_REG, &reg);

    if (ret) {

        return ret;

    }



    for (i = 0; i < KVM_NR_SPSR; i++) {

        reg.id = AARCH64_CORE_REG(spsr[i]);

        reg.addr = (uintptr_t) &env->banked_spsr[i - 1];

        ret = kvm_vcpu_ioctl(cs, KVM_SET_ONE_REG, &reg);

        if (ret) {

            return ret;

        }

    }



    /* Advanced SIMD and FP registers

     * We map Qn = regs[2n+1]:regs[2n]

     */

    for (i = 0; i < 32; i++) {

        int rd = i << 1;

        uint64_t fp_val[2];

#ifdef HOST_WORDS_BIGENDIAN

        fp_val[0] = env->vfp.regs[rd + 1];

        fp_val[1] = env->vfp.regs[rd];

#else

        fp_val[1] = env->vfp.regs[rd + 1];

        fp_val[0] = env->vfp.regs[rd];

#endif

        reg.id = AARCH64_SIMD_CORE_REG(fp_regs.vregs[i]);

        reg.addr = (uintptr_t)(&fp_val);

        ret = kvm_vcpu_ioctl(cs, KVM_SET_ONE_REG, &reg);

        if (ret) {

            return ret;

        }

    }



    reg.addr = (uintptr_t)(&fpr);

    fpr = vfp_get_fpsr(env);

    reg.id = AARCH64_SIMD_CTRL_REG(fp_regs.fpsr);

    ret = kvm_vcpu_ioctl(cs, KVM_SET_ONE_REG, &reg);

    if (ret) {

        return ret;

    }



    fpr = vfp_get_fpcr(env);

    reg.id = AARCH64_SIMD_CTRL_REG(fp_regs.fpcr);

    ret = kvm_vcpu_ioctl(cs, KVM_SET_ONE_REG, &reg);

    if (ret) {

        return ret;

    }



    if (!write_list_to_kvmstate(cpu)) {

        return EINVAL;

    }



    kvm_arm_sync_mpstate_to_kvm(cpu);



    return ret;

}

static void sdl_refresh(DisplayState *ds)

{

    SDL_Event ev1, *ev = &ev1;

    int mod_state;

    int buttonstate = SDL_GetMouseState(NULL, NULL);



    if (last_vm_running != vm_running) {

        last_vm_running = vm_running;

        sdl_update_caption();

    }



    vga_hw_update();

    SDL_EnableUNICODE(!is_graphic_console());



    while (SDL_PollEvent(ev)) {

        switch (ev->type) {

        case SDL_VIDEOEXPOSE:

            sdl_update(ds, 0, 0, screen->w, screen->h);

            break;

        case SDL_KEYDOWN:

        case SDL_KEYUP:

            if (ev->type == SDL_KEYDOWN) {

                if (!alt_grab) {

                    mod_state = (SDL_GetModState() & gui_grab_code) ==

                                gui_grab_code;

                } else {

                    mod_state = (SDL_GetModState() & (gui_grab_code | KMOD_LSHIFT)) ==

                                (gui_grab_code | KMOD_LSHIFT);

                }

                gui_key_modifier_pressed = mod_state;

                if (gui_key_modifier_pressed) {

                    int keycode;

                    keycode = sdl_keyevent_to_keycode(&ev->key);

                    switch(keycode) {

                    case 0x21: /* 'f' key on US keyboard */

                        toggle_full_screen(ds);

                        gui_keysym = 1;

                        break;

                    case 0x02 ... 0x0a: /* '1' to '9' keys */

                        /* Reset the modifiers sent to the current console */

                        reset_keys();

                        console_select(keycode - 0x02);

                        if (!is_graphic_console()) {

                            /* display grab if going to a text console */

                            if (gui_grab)

                                sdl_grab_end();

                        }

                        gui_keysym = 1;

                        break;

                    default:

                        break;

                    }

                } else if (!is_graphic_console()) {

                    int keysym;

                    keysym = 0;

                    if (ev->key.keysym.mod & (KMOD_LCTRL | KMOD_RCTRL)) {

                        switch(ev->key.keysym.sym) {

                        case SDLK_UP: keysym = QEMU_KEY_CTRL_UP; break;

                        case SDLK_DOWN: keysym = QEMU_KEY_CTRL_DOWN; break;

                        case SDLK_LEFT: keysym = QEMU_KEY_CTRL_LEFT; break;

                        case SDLK_RIGHT: keysym = QEMU_KEY_CTRL_RIGHT; break;

                        case SDLK_HOME: keysym = QEMU_KEY_CTRL_HOME; break;

                        case SDLK_END: keysym = QEMU_KEY_CTRL_END; break;

                        case SDLK_PAGEUP: keysym = QEMU_KEY_CTRL_PAGEUP; break;

                        case SDLK_PAGEDOWN: keysym = QEMU_KEY_CTRL_PAGEDOWN; break;

                        default: break;

                        }

                    } else {

                        switch(ev->key.keysym.sym) {

                        case SDLK_UP: keysym = QEMU_KEY_UP; break;

                        case SDLK_DOWN: keysym = QEMU_KEY_DOWN; break;

                        case SDLK_LEFT: keysym = QEMU_KEY_LEFT; break;

                        case SDLK_RIGHT: keysym = QEMU_KEY_RIGHT; break;

                        case SDLK_HOME: keysym = QEMU_KEY_HOME; break;

                        case SDLK_END: keysym = QEMU_KEY_END; break;

                        case SDLK_PAGEUP: keysym = QEMU_KEY_PAGEUP; break;

                        case SDLK_PAGEDOWN: keysym = QEMU_KEY_PAGEDOWN; break;

                        case SDLK_BACKSPACE: keysym = QEMU_KEY_BACKSPACE; break;

                        case SDLK_DELETE: keysym = QEMU_KEY_DELETE; break;

                        default: break;

                        }

                    }

                    if (keysym) {

                        kbd_put_keysym(keysym);

                    } else if (ev->key.keysym.unicode != 0) {

                        kbd_put_keysym(ev->key.keysym.unicode);

                    }

                }

            } else if (ev->type == SDL_KEYUP) {

                if (!alt_grab) {

                    mod_state = (ev->key.keysym.mod & gui_grab_code);

                } else {

                    mod_state = (ev->key.keysym.mod &

                                 (gui_grab_code | KMOD_LSHIFT));

                }

                if (!mod_state) {

                    if (gui_key_modifier_pressed) {

                        gui_key_modifier_pressed = 0;

                        if (gui_keysym == 0) {

                            /* exit/enter grab if pressing Ctrl-Alt */

                            if (!gui_grab) {

                                /* if the application is not active,

                                   do not try to enter grab state. It

                                   prevents

                                   'SDL_WM_GrabInput(SDL_GRAB_ON)'

                                   from blocking all the application

                                   (SDL bug). */

                                if (SDL_GetAppState() & SDL_APPACTIVE)

                                    sdl_grab_start();

                            } else {

                                sdl_grab_end();

                            }

                            /* SDL does not send back all the

                               modifiers key, so we must correct it */

                            reset_keys();

                            break;

                        }

                        gui_keysym = 0;

                    }

                }

            }

            if (is_graphic_console() && !gui_keysym)

                sdl_process_key(&ev->key);

            break;

        case SDL_QUIT:

            if (!no_quit) {

                qemu_system_shutdown_request();

                vm_start();	/* In case we're paused */

            }

            break;

        case SDL_MOUSEMOTION:

            if (gui_grab || kbd_mouse_is_absolute() ||

                absolute_enabled) {

                sdl_send_mouse_event(ev->motion.xrel, ev->motion.yrel, 0,

                       ev->motion.x, ev->motion.y, ev->motion.state);

            }

            break;

        case SDL_MOUSEBUTTONDOWN:

        case SDL_MOUSEBUTTONUP:

            {

                SDL_MouseButtonEvent *bev = &ev->button;

                if (!gui_grab && !kbd_mouse_is_absolute()) {

                    if (ev->type == SDL_MOUSEBUTTONDOWN &&

                        (bev->button == SDL_BUTTON_LEFT)) {

                        /* start grabbing all events */

                        sdl_grab_start();

                    }

                } else {

                    int dz;

                    dz = 0;

                    if (ev->type == SDL_MOUSEBUTTONDOWN) {

                        buttonstate |= SDL_BUTTON(bev->button);

                    } else {

                        buttonstate &= ~SDL_BUTTON(bev->button);

                    }

#ifdef SDL_BUTTON_WHEELUP

                    if (bev->button == SDL_BUTTON_WHEELUP && ev->type == SDL_MOUSEBUTTONDOWN) {

                        dz = -1;

                    } else if (bev->button == SDL_BUTTON_WHEELDOWN && ev->type == SDL_MOUSEBUTTONDOWN) {

                        dz = 1;

                    }

#endif

                    sdl_send_mouse_event(0, 0, dz, bev->x, bev->y, buttonstate);

                }

            }

            break;

        case SDL_ACTIVEEVENT:

            if (gui_grab && ev->active.state == SDL_APPINPUTFOCUS &&

                !ev->active.gain && !gui_fullscreen_initial_grab) {

                sdl_grab_end();

            }

            if (ev->active.state & SDL_APPACTIVE) {

                if (ev->active.gain) {

                    /* Back to default interval */

                    ds->gui_timer_interval = 0;

                } else {

                    /* Sleeping interval */

                    ds->gui_timer_interval = 500;

                }

            }

            break;

        default:

            break;

        }

    }

}

static int bdrv_check_byte_request(BlockDriverState *bs, int64_t offset,

                                   size_t size)

{

    int64_t len;



    if (size > INT_MAX) {

        return -EIO;

    }



    if (!bdrv_is_inserted(bs))

        return -ENOMEDIUM;



    if (bs->growable)

        return 0;



    len = bdrv_getlength(bs);



    if (offset < 0)

        return -EIO;



    if ((offset > len) || (len - offset < size))

        return -EIO;



    return 0;

}

static ssize_t vnc_tls_pull(gnutls_transport_ptr_t transport,

                            void *data,

                            size_t len) {

    struct VncState *vs = (struct VncState *)transport;

    int ret;



 retry:

    ret = recv(vs->csock, data, len, 0);

    if (ret < 0) {

	if (errno == EINTR)

	    goto retry;

	return -1;

    }

    return ret;

}

static bool pcie_aer_msg_root_port(PCIDevice *dev, const PCIEAERMsg *msg)

{

    bool msg_sent;

    uint16_t cmd;

    uint8_t *aer_cap;

    uint32_t root_cmd;

    uint32_t root_status;

    bool msi_trigger;



    msg_sent = false;

    cmd = pci_get_word(dev->config + PCI_COMMAND);

    aer_cap = dev->config + dev->exp.aer_cap;

    root_cmd = pci_get_long(aer_cap + PCI_ERR_ROOT_COMMAND);

    root_status = pci_get_long(aer_cap + PCI_ERR_ROOT_STATUS);

    msi_trigger = false;



    if (cmd & PCI_COMMAND_SERR) {

        /* System Error.

         *

         * The way to report System Error is platform specific and

         * it isn't implemented in qemu right now.

         * So just discard the error for now.

         * OS which cares of aer would receive errors via

         * native aer mechanims, so this wouldn't matter.

         */

    }



    /* Errro Message Received: Root Error Status register */

    switch (msg->severity) {

    case PCI_ERR_ROOT_CMD_COR_EN:

        if (root_status & PCI_ERR_ROOT_COR_RCV) {

            root_status |= PCI_ERR_ROOT_MULTI_COR_RCV;

        } else {

            if (root_cmd & PCI_ERR_ROOT_CMD_COR_EN) {

                msi_trigger = true;

            }

            pci_set_word(aer_cap + PCI_ERR_ROOT_COR_SRC, msg->source_id);

        }

        root_status |= PCI_ERR_ROOT_COR_RCV;

        break;

    case PCI_ERR_ROOT_CMD_NONFATAL_EN:

        if (!(root_status & PCI_ERR_ROOT_NONFATAL_RCV) &&

            root_cmd & PCI_ERR_ROOT_CMD_NONFATAL_EN) {

            msi_trigger = true;

        }

        root_status |= PCI_ERR_ROOT_NONFATAL_RCV;

        break;

    case PCI_ERR_ROOT_CMD_FATAL_EN:

        if (!(root_status & PCI_ERR_ROOT_FATAL_RCV) &&

            root_cmd & PCI_ERR_ROOT_CMD_FATAL_EN) {

            msi_trigger = true;

        }

        if (!(root_status & PCI_ERR_ROOT_UNCOR_RCV)) {

            root_status |= PCI_ERR_ROOT_FIRST_FATAL;

        }

        root_status |= PCI_ERR_ROOT_FATAL_RCV;

        break;

    default:

        abort();

        break;

    }

    if (pcie_aer_msg_is_uncor(msg)) {

        if (root_status & PCI_ERR_ROOT_UNCOR_RCV) {

            root_status |= PCI_ERR_ROOT_MULTI_UNCOR_RCV;

        } else {

            pci_set_word(aer_cap + PCI_ERR_ROOT_SRC, msg->source_id);

        }

        root_status |= PCI_ERR_ROOT_UNCOR_RCV;

    }

    pci_set_long(aer_cap + PCI_ERR_ROOT_STATUS, root_status);



    if (root_cmd & msg->severity) {

        /* 6.2.4.1.2 Interrupt Generation */

        if (msix_enabled(dev)) {

            if (msi_trigger) {

                msix_notify(dev, pcie_aer_root_get_vector(dev));

            }

        } else if (msi_enabled(dev)) {

            if (msi_trigger) {

                msi_notify(dev, pcie_aer_root_get_vector(dev));

            }

        } else {

            qemu_set_irq(dev->irq[dev->exp.aer_intx], 1);

        }

        msg_sent = true;

    }

    return msg_sent;

}

