static void kvm_handle_internal_error(CPUState *env, struct kvm_run *run)

{



    if (kvm_check_extension(kvm_state, KVM_CAP_INTERNAL_ERROR_DATA)) {

        int i;



        fprintf(stderr, "KVM internal error. Suberror: %d\n",

                run->internal.suberror);



        for (i = 0; i < run->internal.ndata; ++i) {

            fprintf(stderr, "extra data[%d]: %"PRIx64"\n",

                    i, (uint64_t)run->internal.data[i]);

        }

    }

    cpu_dump_state(env, stderr, fprintf, 0);

    if (run->internal.suberror == KVM_INTERNAL_ERROR_EMULATION) {

        fprintf(stderr, "emulation failure\n");

        if (!kvm_arch_stop_on_emulation_error(env)) {

            return;

        }

    }

    /* FIXME: Should trigger a qmp message to let management know

     * something went wrong.

     */

    vm_stop(0);

}

static void xenfb_mouse_event(DeviceState *dev, QemuConsole *src,

                              InputEvent *evt)

{

    struct XenInput *xenfb = (struct XenInput *)dev;

    InputBtnEvent *btn;

    InputMoveEvent *move;

    QemuConsole *con;

    DisplaySurface *surface;

    int scale;



    switch (evt->type) {

    case INPUT_EVENT_KIND_BTN:

        btn = evt->u.btn.data;

        switch (btn->button) {

        case INPUT_BUTTON_LEFT:

            xenfb_send_key(xenfb, btn->down, BTN_LEFT);

            break;

        case INPUT_BUTTON_RIGHT:

            xenfb_send_key(xenfb, btn->down, BTN_LEFT + 1);

            break;

        case INPUT_BUTTON_MIDDLE:

            xenfb_send_key(xenfb, btn->down, BTN_LEFT + 2);

            break;

        case INPUT_BUTTON_WHEEL_UP:

            if (btn->down) {

                xenfb->wheel--;

            }

            break;

        case INPUT_BUTTON_WHEEL_DOWN:

            if (btn->down) {

                xenfb->wheel++;

            }

            break;

        default:

            break;

        }

        break;



    case INPUT_EVENT_KIND_ABS:

        move = evt->u.abs.data;

        con = qemu_console_lookup_by_index(0);

        if (!con) {

            xen_pv_printf(&xenfb->c.xendev, 0, "No QEMU console available");

            return;

        }

        surface = qemu_console_surface(con);

        switch (move->axis) {

        case INPUT_AXIS_X:

            scale = surface_width(surface) - 1;

            break;

        case INPUT_AXIS_Y:

            scale = surface_height(surface) - 1;

            break;

        default:

            scale = 0x8000;

            break;

        }

        xenfb->axis[move->axis] = move->value * scale / 0x7fff;

        break;



    case INPUT_EVENT_KIND_REL:

        move = evt->u.rel.data;

        xenfb->axis[move->axis] += move->value;

        break;



    default:

        break;

    }

}

static CharDriverState *qemu_chr_open_socket_fd(int fd, bool do_nodelay,

                                                bool is_listen, bool is_telnet,

                                                bool is_waitconnect,

                                                Error **errp)

{

    CharDriverState *chr = NULL;

    TCPCharDriver *s = NULL;

    char host[NI_MAXHOST], serv[NI_MAXSERV];

    const char *left = "", *right = "";

    struct sockaddr_storage ss;

    socklen_t ss_len = sizeof(ss);



    memset(&ss, 0, ss_len);

    if (getsockname(fd, (struct sockaddr *) &ss, &ss_len) != 0) {

        error_setg_errno(errp, errno, "getsockname");

        return NULL;

    }



    chr = g_malloc0(sizeof(CharDriverState));

    s = g_malloc0(sizeof(TCPCharDriver));



    s->connected = 0;

    s->fd = -1;

    s->listen_fd = -1;

    s->read_msgfds = 0;

    s->read_msgfds_num = 0;

    s->write_msgfds = 0;

    s->write_msgfds_num = 0;



    chr->filename = g_malloc(256);

    switch (ss.ss_family) {

#ifndef _WIN32

    case AF_UNIX:

        s->is_unix = 1;

        snprintf(chr->filename, 256, "unix:%s%s",

                 ((struct sockaddr_un *)(&ss))->sun_path,

                 is_listen ? ",server" : "");

        break;

#endif

    case AF_INET6:

        left  = "[";

        right = "]";

        /* fall through */

    case AF_INET:

        s->do_nodelay = do_nodelay;

        getnameinfo((struct sockaddr *) &ss, ss_len, host, sizeof(host),

                    serv, sizeof(serv), NI_NUMERICHOST | NI_NUMERICSERV);

        snprintf(chr->filename, 256, "%s:%s%s%s:%s%s",

                 is_telnet ? "telnet" : "tcp",

                 left, host, right, serv,

                 is_listen ? ",server" : "");

        break;

    }



    chr->opaque = s;

    chr->chr_write = tcp_chr_write;

    chr->chr_sync_read = tcp_chr_sync_read;

    chr->chr_close = tcp_chr_close;

    chr->get_msgfds = tcp_get_msgfds;

    chr->set_msgfds = tcp_set_msgfds;

    chr->chr_add_client = tcp_chr_add_client;

    chr->chr_add_watch = tcp_chr_add_watch;

    chr->chr_update_read_handler = tcp_chr_update_read_handler;

    /* be isn't opened until we get a connection */

    chr->explicit_be_open = true;



    if (is_listen) {

        s->listen_fd = fd;

        s->listen_chan = io_channel_from_socket(s->listen_fd);

        s->listen_tag = g_io_add_watch(s->listen_chan, G_IO_IN, tcp_chr_accept, chr);

        if (is_telnet) {

            s->do_telnetopt = 1;

        }

    } else {

        s->connected = 1;

        s->fd = fd;

        socket_set_nodelay(fd);

        s->chan = io_channel_from_socket(s->fd);

        tcp_chr_connect(chr);

    }



    if (is_listen && is_waitconnect) {

        fprintf(stderr, "QEMU waiting for connection on: %s\n",

                chr->filename);

        tcp_chr_accept(s->listen_chan, G_IO_IN, chr);

        qemu_set_nonblock(s->listen_fd);

    }

    return chr;

}

static void dhcp_decode(const struct bootp_t *bp, int *pmsg_type,

                        const struct in_addr **preq_addr)

{

    const uint8_t *p, *p_end;

    int len, tag;



    *pmsg_type = 0;

    *preq_addr = NULL;



    p = bp->bp_vend;

    p_end = p + DHCP_OPT_LEN;

    if (memcmp(p, rfc1533_cookie, 4) != 0)

        return;

    p += 4;

    while (p < p_end) {

        tag = p[0];

        if (tag == RFC1533_PAD) {

            p++;

        } else if (tag == RFC1533_END) {

            break;

        } else {

            p++;

            if (p >= p_end)

                break;

            len = *p++;

            DPRINTF("dhcp: tag=%d len=%d\n", tag, len);



            switch(tag) {

            case RFC2132_MSG_TYPE:

                if (len >= 1)

                    *pmsg_type = p[0];

                break;

            case RFC2132_REQ_ADDR:

                if (len >= 4)

                    *preq_addr = (struct in_addr *)p;

                break;

            default:

                break;

            }

            p += len;

        }

    }

    if (*pmsg_type == DHCPREQUEST && !*preq_addr && bp->bp_ciaddr.s_addr) {

        *preq_addr = &bp->bp_ciaddr;

    }

}

static void virtio_setup(uint64_t dev_info)

{

    struct schib schib;

    int i;

    int r;

    bool found = false;

    bool check_devno = false;

    uint16_t dev_no = -1;

    blk_schid.one = 1;



    if (dev_info != -1) {

        check_devno = true;

        dev_no = dev_info & 0xffff;

        debug_print_int("device no. ", dev_no);

        blk_schid.ssid = (dev_info >> 16) & 0x3;

        if (blk_schid.ssid != 0) {

            debug_print_int("ssid ", blk_schid.ssid);

            if (enable_mss_facility() != 0) {

                virtio_panic("Failed to enable mss facility\n");

            }

        }

    }



    for (i = 0; i < 0x10000; i++) {

        blk_schid.sch_no = i;

        r = stsch_err(blk_schid, &schib);

        if (r == 3) {

            break;

        }

        if (schib.pmcw.dnv) {

            if (!check_devno || (schib.pmcw.dev == dev_no)) {

                if (virtio_is_blk(blk_schid)) {

                    found = true;

                    break;

                }

            }

        }

    }



    if (!found) {

        virtio_panic("No virtio-blk device found!\n");

    }



    virtio_setup_block(blk_schid);

}

