static int cirrus_bitblt_common_patterncopy(CirrusVGAState *s, bool videosrc)

{

    uint32_t patternsize;

    uint8_t *dst;

    uint8_t *src;



    dst = s->vga.vram_ptr + s->cirrus_blt_dstaddr;



    if (videosrc) {

        switch (s->vga.get_bpp(&s->vga)) {

        case 8:

            patternsize = 64;

            break;

        case 15:

        case 16:

            patternsize = 128;

            break;

        case 24:

        case 32:

        default:

            patternsize = 256;

            break;

        }

        s->cirrus_blt_srcaddr &= ~(patternsize - 1);

        if (s->cirrus_blt_srcaddr + patternsize > s->vga.vram_size) {

            return 0;

        }

        src = s->vga.vram_ptr + s->cirrus_blt_srcaddr;

    } else {

        src = s->cirrus_bltbuf;

    }



    if (blit_is_unsafe(s, true)) {

        return 0;

    }



    (*s->cirrus_rop) (s, dst, src,

                      s->cirrus_blt_dstpitch, 0,

                      s->cirrus_blt_width, s->cirrus_blt_height);

    cirrus_invalidate_region(s, s->cirrus_blt_dstaddr,

                             s->cirrus_blt_dstpitch, s->cirrus_blt_width,

                             s->cirrus_blt_height);

    return 1;

}

static int nbd_handle_export_name(NBDClient *client, uint32_t length)

{

    int rc = -EINVAL, csock = client->sock;

    char name[256];



    /* Client sends:

        [20 ..  xx]   export name (length bytes)

     */

    TRACE("Checking length");

    if (length > 255) {

        LOG("Bad length received");

        goto fail;

    }

    if (read_sync(csock, name, length) != length) {

        LOG("read failed");

        goto fail;

    }

    name[length] = '\0';



    client->exp = nbd_export_find(name);

    if (!client->exp) {

        LOG("export not found");

        goto fail;

    }



    QTAILQ_INSERT_TAIL(&client->exp->clients, client, next);

    nbd_export_get(client->exp);

    rc = 0;

fail:

    return rc;

}

static void tcg_out_insn_3401(TCGContext *s, AArch64Insn insn, TCGType ext,

                              TCGReg rd, TCGReg rn, uint64_t aimm)

{

    if (aimm > 0xfff) {

        assert((aimm & 0xfff) == 0);

        aimm >>= 12;

        assert(aimm <= 0xfff);

        aimm |= 1 << 12;  /* apply LSL 12 */

    }

    tcg_out32(s, insn | ext << 31 | aimm << 10 | rn << 5 | rd);

}

