static gboolean serial_xmit(GIOChannel *chan, GIOCondition cond, void *opaque)

{

    SerialState *s = opaque;



    do {

        if (s->tsr_retry <= 0) {

            if (s->fcr & UART_FCR_FE) {

                if (fifo8_is_empty(&s->xmit_fifo)) {

                    return FALSE;

                }

                s->tsr = fifo8_pop(&s->xmit_fifo);

                if (!s->xmit_fifo.num) {

                    s->lsr |= UART_LSR_THRE;

                }

            } else if ((s->lsr & UART_LSR_THRE)) {

                return FALSE;

            } else {

                s->tsr = s->thr;

                s->lsr |= UART_LSR_THRE;

                s->lsr &= ~UART_LSR_TEMT;

            }

        }



        if (s->mcr & UART_MCR_LOOP) {

            /* in loopback mode, say that we just received a char */

            serial_receive1(s, &s->tsr, 1);

        } else if (qemu_chr_fe_write(s->chr, &s->tsr, 1) != 1) {

            if (s->tsr_retry >= 0 && s->tsr_retry < MAX_XMIT_RETRY &&

                qemu_chr_fe_add_watch(s->chr, G_IO_OUT|G_IO_HUP,

                                      serial_xmit, s) > 0) {

                s->tsr_retry++;

                return FALSE;

            }

            s->tsr_retry = 0;

        } else {

            s->tsr_retry = 0;

        }

        /* Transmit another byte if it is already available. It is only

           possible when FIFO is enabled and not empty. */

    } while ((s->fcr & UART_FCR_FE) && !fifo8_is_empty(&s->xmit_fifo));



    s->last_xmit_ts = qemu_clock_get_ns(QEMU_CLOCK_VIRTUAL);



    if (s->lsr & UART_LSR_THRE) {

        s->lsr |= UART_LSR_TEMT;

        s->thr_ipending = 1;

        serial_update_irq(s);

    }



    return FALSE;

}

static int qemu_gluster_parse_json(BlockdevOptionsGluster *gconf,

                                  QDict *options, Error **errp)

{

    QemuOpts *opts;

    SocketAddress *gsconf = NULL;

    SocketAddressList *curr = NULL;

    QDict *backing_options = NULL;

    Error *local_err = NULL;

    char *str = NULL;

    const char *ptr;

    size_t num_servers;

    int i, type;



    /* create opts info from runtime_json_opts list */

    opts = qemu_opts_create(&runtime_json_opts, NULL, 0, &error_abort);

    qemu_opts_absorb_qdict(opts, options, &local_err);

    if (local_err) {

        goto out;

    }



    num_servers = qdict_array_entries(options, GLUSTER_OPT_SERVER_PATTERN);

    if (num_servers < 1) {

        error_setg(&local_err, QERR_MISSING_PARAMETER, "server");

        goto out;

    }



    ptr = qemu_opt_get(opts, GLUSTER_OPT_VOLUME);

    if (!ptr) {

        error_setg(&local_err, QERR_MISSING_PARAMETER, GLUSTER_OPT_VOLUME);

        goto out;

    }

    gconf->volume = g_strdup(ptr);



    ptr = qemu_opt_get(opts, GLUSTER_OPT_PATH);

    if (!ptr) {

        error_setg(&local_err, QERR_MISSING_PARAMETER, GLUSTER_OPT_PATH);

        goto out;

    }

    gconf->path = g_strdup(ptr);

    qemu_opts_del(opts);



    for (i = 0; i < num_servers; i++) {

        str = g_strdup_printf(GLUSTER_OPT_SERVER_PATTERN"%d.", i);

        qdict_extract_subqdict(options, &backing_options, str);



        /* create opts info from runtime_type_opts list */

        opts = qemu_opts_create(&runtime_type_opts, NULL, 0, &error_abort);

        qemu_opts_absorb_qdict(opts, backing_options, &local_err);

        if (local_err) {

            goto out;

        }



        ptr = qemu_opt_get(opts, GLUSTER_OPT_TYPE);

        if (!ptr) {

            error_setg(&local_err, QERR_MISSING_PARAMETER, GLUSTER_OPT_TYPE);

            error_append_hint(&local_err, GERR_INDEX_HINT, i);

            goto out;



        }

        gsconf = g_new0(SocketAddress, 1);

        if (!strcmp(ptr, "tcp")) {

            ptr = "inet";       /* accept legacy "tcp" */

        }

        type = qapi_enum_parse(SocketAddressType_lookup, ptr,

                               SOCKET_ADDRESS_TYPE__MAX, -1, NULL);

        if (type != SOCKET_ADDRESS_TYPE_INET

            && type != SOCKET_ADDRESS_TYPE_UNIX) {

            error_setg(&local_err,

                       "Parameter '%s' may be 'inet' or 'unix'",

                       GLUSTER_OPT_TYPE);

            error_append_hint(&local_err, GERR_INDEX_HINT, i);

            goto out;

        }

        gsconf->type = type;

        qemu_opts_del(opts);



        if (gsconf->type == SOCKET_ADDRESS_TYPE_INET) {

            /* create opts info from runtime_inet_opts list */

            opts = qemu_opts_create(&runtime_inet_opts, NULL, 0, &error_abort);

            qemu_opts_absorb_qdict(opts, backing_options, &local_err);

            if (local_err) {

                goto out;

            }



            ptr = qemu_opt_get(opts, GLUSTER_OPT_HOST);

            if (!ptr) {

                error_setg(&local_err, QERR_MISSING_PARAMETER,

                           GLUSTER_OPT_HOST);

                error_append_hint(&local_err, GERR_INDEX_HINT, i);

                goto out;

            }

            gsconf->u.inet.host = g_strdup(ptr);

            ptr = qemu_opt_get(opts, GLUSTER_OPT_PORT);

            if (!ptr) {

                error_setg(&local_err, QERR_MISSING_PARAMETER,

                           GLUSTER_OPT_PORT);

                error_append_hint(&local_err, GERR_INDEX_HINT, i);

                goto out;

            }

            gsconf->u.inet.port = g_strdup(ptr);



            /* defend for unsupported fields in InetSocketAddress,

             * i.e. @ipv4, @ipv6  and @to

             */

            ptr = qemu_opt_get(opts, GLUSTER_OPT_TO);

            if (ptr) {

                gsconf->u.inet.has_to = true;

            }

            ptr = qemu_opt_get(opts, GLUSTER_OPT_IPV4);

            if (ptr) {

                gsconf->u.inet.has_ipv4 = true;

            }

            ptr = qemu_opt_get(opts, GLUSTER_OPT_IPV6);

            if (ptr) {

                gsconf->u.inet.has_ipv6 = true;

            }

            if (gsconf->u.inet.has_to) {

                error_setg(&local_err, "Parameter 'to' not supported");

                goto out;

            }

            if (gsconf->u.inet.has_ipv4 || gsconf->u.inet.has_ipv6) {

                error_setg(&local_err, "Parameters 'ipv4/ipv6' not supported");

                goto out;

            }

            qemu_opts_del(opts);

        } else {

            /* create opts info from runtime_unix_opts list */

            opts = qemu_opts_create(&runtime_unix_opts, NULL, 0, &error_abort);

            qemu_opts_absorb_qdict(opts, backing_options, &local_err);

            if (local_err) {

                goto out;

            }



            ptr = qemu_opt_get(opts, GLUSTER_OPT_SOCKET);

            if (!ptr) {

                error_setg(&local_err, QERR_MISSING_PARAMETER,

                           GLUSTER_OPT_SOCKET);

                error_append_hint(&local_err, GERR_INDEX_HINT, i);

                goto out;

            }

            gsconf->u.q_unix.path = g_strdup(ptr);

            qemu_opts_del(opts);

        }



        if (gconf->server == NULL) {

            gconf->server = g_new0(SocketAddressList, 1);

            gconf->server->value = gsconf;

            curr = gconf->server;

        } else {

            curr->next = g_new0(SocketAddressList, 1);

            curr->next->value = gsconf;

            curr = curr->next;

        }

        gsconf = NULL;



        QDECREF(backing_options);

        backing_options = NULL;

        g_free(str);

        str = NULL;

    }



    return 0;



out:

    error_propagate(errp, local_err);

    qapi_free_SocketAddress(gsconf);

    qemu_opts_del(opts);

    g_free(str);

    QDECREF(backing_options);

    errno = EINVAL;

    return -errno;

}

static int try_seek_hole(BlockDriverState *bs, off_t start, off_t *data,

                         off_t *hole)

{

#if defined SEEK_HOLE && defined SEEK_DATA

    BDRVRawState *s = bs->opaque;



    *hole = lseek(s->fd, start, SEEK_HOLE);

    if (*hole == -1) {

        return -errno;

    }



    if (*hole > start) {

        *data = start;

    } else {

        /* On a hole.  We need another syscall to find its end.  */

        *data = lseek(s->fd, start, SEEK_DATA);

        if (*data == -1) {

            *data = lseek(s->fd, 0, SEEK_END);

        }

    }



    return 0;

#else

    return -ENOTSUP;

#endif

}

static int net_client_init(const char *str)

{

    const char *p;

    char *q;

    char device[64];

    char buf[1024];

    int vlan_id, ret;

    VLANState *vlan;



    p = str;

    q = device;

    while (*p != '\0' && *p != ',') {

        if ((q - device) < sizeof(device) - 1)

            *q++ = *p;

        p++;

    }

    *q = '\0';

    if (*p == ',')

        p++;

    vlan_id = 0;

    if (get_param_value(buf, sizeof(buf), "vlan", p)) {

        vlan_id = strtol(buf, NULL, 0);

    }

    vlan = qemu_find_vlan(vlan_id);

    if (!vlan) {

        fprintf(stderr, "Could not create vlan %d\n", vlan_id);

        return -1;

    }

    if (!strcmp(device, "nic")) {

        NICInfo *nd;

        uint8_t *macaddr;



        if (nb_nics >= MAX_NICS) {

            fprintf(stderr, "Too Many NICs\n");

            return -1;

        }

        nd = &nd_table[nb_nics];

        macaddr = nd->macaddr;

        macaddr[0] = 0x52;

        macaddr[1] = 0x54;

        macaddr[2] = 0x00;

        macaddr[3] = 0x12;

        macaddr[4] = 0x34;

        macaddr[5] = 0x56 + nb_nics;



        if (get_param_value(buf, sizeof(buf), "macaddr", p)) {

            if (parse_macaddr(macaddr, buf) < 0) {

                fprintf(stderr, "invalid syntax for ethernet address\n");

                return -1;

            }

        }

        if (get_param_value(buf, sizeof(buf), "model", p)) {

            nd->model = strdup(buf);

        }

        nd->vlan = vlan;

        nb_nics++;

        vlan->nb_guest_devs++;

        ret = 0;

    } else

    if (!strcmp(device, "none")) {

        /* does nothing. It is needed to signal that no network cards

           are wanted */

        ret = 0;

    } else

#ifdef CONFIG_SLIRP

    if (!strcmp(device, "user")) {

        if (get_param_value(buf, sizeof(buf), "hostname", p)) {

            pstrcpy(slirp_hostname, sizeof(slirp_hostname), buf);

        }


        ret = net_slirp_init(vlan);

    } else

#endif

#ifdef _WIN32

    if (!strcmp(device, "tap")) {

        char ifname[64];

        if (get_param_value(ifname, sizeof(ifname), "ifname", p) <= 0) {

            fprintf(stderr, "tap: no interface name\n");

            return -1;

        }


        ret = tap_win32_init(vlan, ifname);

    } else

#else

    if (!strcmp(device, "tap")) {

        char ifname[64];

        char setup_script[1024];

        int fd;

        if (get_param_value(buf, sizeof(buf), "fd", p) > 0) {

            fd = strtol(buf, NULL, 0);

            ret = -1;

            if (net_tap_fd_init(vlan, fd))

                ret = 0;

        } else {

            if (get_param_value(ifname, sizeof(ifname), "ifname", p) <= 0) {

                ifname[0] = '\0';

            }

            if (get_param_value(setup_script, sizeof(setup_script), "script", p) == 0) {

                pstrcpy(setup_script, sizeof(setup_script), DEFAULT_NETWORK_SCRIPT);

            }


            ret = net_tap_init(vlan, ifname, setup_script);

        }

    } else

#endif

    if (!strcmp(device, "socket")) {

        if (get_param_value(buf, sizeof(buf), "fd", p) > 0) {

            int fd;

            fd = strtol(buf, NULL, 0);

            ret = -1;

            if (net_socket_fd_init(vlan, fd, 1))

                ret = 0;

        } else if (get_param_value(buf, sizeof(buf), "listen", p) > 0) {

            ret = net_socket_listen_init(vlan, buf);

        } else if (get_param_value(buf, sizeof(buf), "connect", p) > 0) {

            ret = net_socket_connect_init(vlan, buf);

        } else if (get_param_value(buf, sizeof(buf), "mcast", p) > 0) {

            ret = net_socket_mcast_init(vlan, buf);

        } else {

            fprintf(stderr, "Unknown socket options: %s\n", p);

            return -1;

        }


    } else

    {

        fprintf(stderr, "Unknown network device: %s\n", device);

        return -1;

    }

    if (ret < 0) {

        fprintf(stderr, "Could not initialize device '%s'\n", device);

    }



    return ret;

}

