static gboolean tcp_chr_chan_close(GIOChannel *channel, GIOCondition cond,

                                   void *opaque)

{

    CharDriverState *chr = opaque;



    if (cond != G_IO_HUP) {

        return FALSE;

    }



    /* connection closed */

    tcp_chr_disconnect(chr);

