static bool serial_isa_init(ISABus *bus, int index, CharDriverState *chr)

{

    DeviceState *dev;

    ISADevice *isadev;



    isadev = isa_try_create(bus, TYPE_ISA_SERIAL);

    if (!isadev) {

        return false;

    }

    dev = DEVICE(isadev);

    qdev_prop_set_uint32(dev, "index", index);

    qdev_prop_set_chr(dev, "chardev", chr);

    if (qdev_init(dev) < 0) {

        return false;

    }

    return true;

}

static uint32_t acpi_find_vgia(void)

{

    uint32_t rsdp_offset;

    uint32_t guid_offset = 0;

    AcpiRsdpDescriptor rsdp_table;

    uint32_t rsdt;

    AcpiRsdtDescriptorRev1 rsdt_table;

    int tables_nr;

    uint32_t *tables;

    AcpiTableHeader ssdt_table;

    VgidTable vgid_table;

    int i;



    /* Tables may take a short time to be set up by the guest */

    for (i = 0; i < RSDP_TRIES_MAX; i++) {

        rsdp_offset = acpi_find_rsdp_address();

        if (rsdp_offset < RSDP_ADDR_INVALID) {

            break;

        }

        g_usleep(RSDP_SLEEP_US);

    }

    g_assert_cmphex(rsdp_offset, <, RSDP_ADDR_INVALID);



    acpi_parse_rsdp_table(rsdp_offset, &rsdp_table);



    rsdt = rsdp_table.rsdt_physical_address;

    /* read the header */

    ACPI_READ_TABLE_HEADER(&rsdt_table, rsdt);

    ACPI_ASSERT_CMP(rsdt_table.signature, "RSDT");



    /* compute the table entries in rsdt */

    tables_nr = (rsdt_table.length - sizeof(AcpiRsdtDescriptorRev1)) /

                sizeof(uint32_t);

    g_assert_cmpint(tables_nr, >, 0);



    /* get the addresses of the tables pointed by rsdt */

    tables = g_new0(uint32_t, tables_nr);

    ACPI_READ_ARRAY_PTR(tables, tables_nr, rsdt);



    for (i = 0; i < tables_nr; i++) {

        ACPI_READ_TABLE_HEADER(&ssdt_table, tables[i]);

        if (!strncmp((char *)ssdt_table.oem_table_id, "VMGENID", 7)) {

            /* the first entry in the table should be VGIA

             * That's all we need

             */

            ACPI_READ_FIELD(vgid_table.name_op, tables[i]);

            g_assert(vgid_table.name_op == 0x08);  /* name */

            ACPI_READ_ARRAY(vgid_table.vgia, tables[i]);

            g_assert(memcmp(vgid_table.vgia, "VGIA", 4) == 0);

            ACPI_READ_FIELD(vgid_table.val_op, tables[i]);

            g_assert(vgid_table.val_op == 0x0C);  /* dword */

            ACPI_READ_FIELD(vgid_table.vgia_val, tables[i]);

            /* The GUID is written at a fixed offset into the fw_cfg file

             * in order to implement the "OVMF SDT Header probe suppressor"

             * see docs/specs/vmgenid.txt for more details

             */

            guid_offset = vgid_table.vgia_val + VMGENID_GUID_OFFSET;

            break;

        }

    }

    g_free(tables);

    return guid_offset;

}

int cpu_load(QEMUFile *f, void *opaque, int version_id)

{

    CPUState *env = opaque;

    int i;

    uint32_t tmp;



    if (version_id != 5)

        return -EINVAL;

    for(i = 0; i < 8; i++)

        qemu_get_betls(f, &env->gregs[i]);

    qemu_get_be32s(f, &env->nwindows);

    for(i = 0; i < env->nwindows * 16; i++)

        qemu_get_betls(f, &env->regbase[i]);



    /* FPU */

    for(i = 0; i < TARGET_FPREGS; i++) {

        union {

            float32 f;

            uint32_t i;

        } u;

        u.i = qemu_get_be32(f);

        env->fpr[i] = u.f;

    }



    qemu_get_betls(f, &env->pc);

    qemu_get_betls(f, &env->npc);

    qemu_get_betls(f, &env->y);

    tmp = qemu_get_be32(f);

    env->cwp = 0; /* needed to ensure that the wrapping registers are

                     correctly updated */

    PUT_PSR(env, tmp);

    qemu_get_betls(f, &env->fsr);

    qemu_get_betls(f, &env->tbr);

    tmp = qemu_get_be32(f);

    env->interrupt_index = tmp;

    qemu_get_be32s(f, &env->pil_in);

#ifndef TARGET_SPARC64

    qemu_get_be32s(f, &env->wim);

    /* MMU */

    for (i = 0; i < 32; i++)

        qemu_get_be32s(f, &env->mmuregs[i]);

#else

    qemu_get_be64s(f, &env->lsu);

    for (i = 0; i < 16; i++) {

        qemu_get_be64s(f, &env->immuregs[i]);

        qemu_get_be64s(f, &env->dmmuregs[i]);

    }

    for (i = 0; i < 64; i++) {

        qemu_get_be64s(f, &env->itlb[i].tag);

        qemu_get_be64s(f, &env->itlb[i].tte);

        qemu_get_be64s(f, &env->dtlb[i].tag);

        qemu_get_be64s(f, &env->dtlb[i].tte);

    }

    qemu_get_be32s(f, &env->mmu_version);

    for (i = 0; i < MAXTL_MAX; i++) {

        qemu_get_be64s(f, &env->ts[i].tpc);

        qemu_get_be64s(f, &env->ts[i].tnpc);

        qemu_get_be64s(f, &env->ts[i].tstate);

        qemu_get_be32s(f, &env->ts[i].tt);

    }

    qemu_get_be32s(f, &env->xcc);

    qemu_get_be32s(f, &env->asi);

    qemu_get_be32s(f, &env->pstate);

    qemu_get_be32s(f, &env->tl);

    env->tsptr = &env->ts[env->tl & MAXTL_MASK];

    qemu_get_be32s(f, &env->cansave);

    qemu_get_be32s(f, &env->canrestore);

    qemu_get_be32s(f, &env->otherwin);

    qemu_get_be32s(f, &env->wstate);

    qemu_get_be32s(f, &env->cleanwin);

    for (i = 0; i < 8; i++)

        qemu_get_be64s(f, &env->agregs[i]);

    for (i = 0; i < 8; i++)

        qemu_get_be64s(f, &env->bgregs[i]);

    for (i = 0; i < 8; i++)

        qemu_get_be64s(f, &env->igregs[i]);

    for (i = 0; i < 8; i++)

        qemu_get_be64s(f, &env->mgregs[i]);

    qemu_get_be64s(f, &env->fprs);

    qemu_get_be64s(f, &env->tick_cmpr);

    qemu_get_be64s(f, &env->stick_cmpr);

    qemu_get_ptimer(f, env->tick);

    qemu_get_ptimer(f, env->stick);

    qemu_get_be64s(f, &env->gsr);

    qemu_get_be32s(f, &env->gl);

    qemu_get_be64s(f, &env->hpstate);

    for (i = 0; i < MAXTL_MAX; i++)

        qemu_get_be64s(f, &env->htstate[i]);

    qemu_get_be64s(f, &env->hintp);

    qemu_get_be64s(f, &env->htba);

    qemu_get_be64s(f, &env->hver);

    qemu_get_be64s(f, &env->hstick_cmpr);

    qemu_get_be64s(f, &env->ssr);

    qemu_get_ptimer(f, env->hstick);

#endif

    tlb_flush(env, 1);

    return 0;

}

static void mtree_print_mr(fprintf_function mon_printf, void *f,

                           const MemoryRegion *mr, unsigned int level,

                           target_phys_addr_t base,

                           MemoryRegionListHead *alias_print_queue)

{

    MemoryRegionList *new_ml, *ml, *next_ml;

    MemoryRegionListHead submr_print_queue;

    const MemoryRegion *submr;

    unsigned int i;



    if (!mr) {

        return;

    }



    for (i = 0; i < level; i++) {

        mon_printf(f, "  ");

    }



    if (mr->alias) {

        MemoryRegionList *ml;

        bool found = false;



        /* check if the alias is already in the queue */

        QTAILQ_FOREACH(ml, alias_print_queue, queue) {

            if (ml->mr == mr->alias && !ml->printed) {

                found = true;

            }

        }



        if (!found) {

            ml = g_new(MemoryRegionList, 1);

            ml->mr = mr->alias;

            ml->printed = false;

            QTAILQ_INSERT_TAIL(alias_print_queue, ml, queue);

        }

        mon_printf(f, TARGET_FMT_plx "-" TARGET_FMT_plx " (prio %d): alias %s @%s "

                   TARGET_FMT_plx "-" TARGET_FMT_plx "\n",

                   base + mr->addr,

                   base + mr->addr

                   + (target_phys_addr_t)int128_get64(mr->size) - 1,

                   mr->priority,

                   mr->name,

                   mr->alias->name,

                   mr->alias_offset,

                   mr->alias_offset

                   + (target_phys_addr_t)int128_get64(mr->size) - 1);

    } else {

        mon_printf(f, TARGET_FMT_plx "-" TARGET_FMT_plx " (prio %d): %s\n",

                   base + mr->addr,

                   base + mr->addr

                   + (target_phys_addr_t)int128_get64(mr->size) - 1,

                   mr->priority,

                   mr->name);

    }



    QTAILQ_INIT(&submr_print_queue);



    QTAILQ_FOREACH(submr, &mr->subregions, subregions_link) {

        new_ml = g_new(MemoryRegionList, 1);

        new_ml->mr = submr;

        QTAILQ_FOREACH(ml, &submr_print_queue, queue) {

            if (new_ml->mr->addr < ml->mr->addr ||

                (new_ml->mr->addr == ml->mr->addr &&

                 new_ml->mr->priority > ml->mr->priority)) {

                QTAILQ_INSERT_BEFORE(ml, new_ml, queue);

                new_ml = NULL;

                break;

            }

        }

        if (new_ml) {

            QTAILQ_INSERT_TAIL(&submr_print_queue, new_ml, queue);

        }

    }



    QTAILQ_FOREACH(ml, &submr_print_queue, queue) {

        mtree_print_mr(mon_printf, f, ml->mr, level + 1, base + mr->addr,

                       alias_print_queue);

    }



    QTAILQ_FOREACH_SAFE(next_ml, &submr_print_queue, queue, ml) {

        g_free(ml);

    }

}

int spapr_vio_check_tces(VIOsPAPRDevice *dev, target_ulong ioba,

                         target_ulong len, enum VIOsPAPR_TCEAccess access)

{

    int start, end, i;



    start = ioba >> SPAPR_VIO_TCE_PAGE_SHIFT;

    end = (ioba + len - 1) >> SPAPR_VIO_TCE_PAGE_SHIFT;



    for (i = start; i <= end; i++) {

        if ((dev->rtce_table[i].tce & access) != access) {

#ifdef DEBUG_TCE

            fprintf(stderr, "FAIL on %d\n", i);

#endif

            return -1;

        }

    }



    return 0;

}

void qmp_guest_fstrim(bool has_minimum, int64_t minimum, Error **errp)

{

    int ret = 0;

    FsMountList mounts;

    struct FsMount *mount;

    int fd;

    Error *local_err = NULL;

    struct fstrim_range r = {

        .start = 0,

        .len = -1,

        .minlen = has_minimum ? minimum : 0,

    };



    slog("guest-fstrim called");



    QTAILQ_INIT(&mounts);

    build_fs_mount_list(&mounts, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

        return;

    }



    QTAILQ_FOREACH(mount, &mounts, next) {

        fd = qemu_open(mount->dirname, O_RDONLY);

        if (fd == -1) {

            error_setg_errno(errp, errno, "failed to open %s", mount->dirname);

            goto error;

        }



        /* We try to cull filesytems we know won't work in advance, but other

         * filesytems may not implement fstrim for less obvious reasons.  These

         * will report EOPNOTSUPP; we simply ignore these errors.  Any other

         * error means an unexpected error, so return it in those cases.  In

         * some other cases ENOTTY will be reported (e.g. CD-ROMs).

         */

        ret = ioctl(fd, FITRIM, &r);

        if (ret == -1) {

            if (errno != ENOTTY && errno != EOPNOTSUPP) {

                error_setg_errno(errp, errno, "failed to trim %s",

                                 mount->dirname);

                close(fd);

                goto error;

            }

        }

        close(fd);

    }



error:

    free_fs_mount_list(&mounts);

}

vpc_co_pwritev(BlockDriverState *bs, uint64_t offset, uint64_t bytes,

               QEMUIOVector *qiov, int flags)

{

    BDRVVPCState *s = bs->opaque;

    int64_t image_offset;

    int64_t n_bytes;

    int64_t bytes_done = 0;

    int ret;

    VHDFooter *footer =  (VHDFooter *) s->footer_buf;

    QEMUIOVector local_qiov;



    if (be32_to_cpu(footer->type) == VHD_FIXED) {

        return bdrv_co_pwritev(bs->file, offset, bytes, qiov, 0);

    }



    qemu_co_mutex_lock(&s->lock);

    qemu_iovec_init(&local_qiov, qiov->niov);



    while (bytes > 0) {

        image_offset = get_image_offset(bs, offset, true);

        n_bytes = MIN(bytes, s->block_size - (offset % s->block_size));



        if (image_offset == -1) {

            image_offset = alloc_block(bs, offset);

            if (image_offset < 0) {

                ret = image_offset;

                goto fail;

            }

        }



        qemu_iovec_reset(&local_qiov);

        qemu_iovec_concat(&local_qiov, qiov, bytes_done, n_bytes);



        ret = bdrv_co_pwritev(bs->file, image_offset, n_bytes,

                              &local_qiov, 0);

        if (ret < 0) {

            goto fail;

        }



        bytes -= n_bytes;

        offset += n_bytes;

        bytes_done += n_bytes;

    }



    ret = 0;

fail:

    qemu_iovec_destroy(&local_qiov);

    qemu_co_mutex_unlock(&s->lock);



    return ret;

}

bool memory_region_present(MemoryRegion *container, hwaddr addr)

{

    MemoryRegion *mr = memory_region_find(container, addr, 1).mr;

    if (!mr || (mr == container)) {

        return false;

    }

    memory_region_unref(mr);

    return true;

}

static void tcg_out_qemu_ld_slow_path(TCGContext *s, TCGLabelQemuLdst *l)

{

    TCGMemOp opc = l->opc;

    TCGReg data_reg;

    uint8_t **label_ptr = &l->label_ptr[0];



    /* resolve label address */

    *(uint32_t *)label_ptr[0] = (uint32_t)(s->code_ptr - label_ptr[0] - 4);

    if (TARGET_LONG_BITS > TCG_TARGET_REG_BITS) {

        *(uint32_t *)label_ptr[1] = (uint32_t)(s->code_ptr - label_ptr[1] - 4);

    }



    if (TCG_TARGET_REG_BITS == 32) {

        int ofs = 0;



        tcg_out_st(s, TCG_TYPE_PTR, TCG_AREG0, TCG_REG_ESP, ofs);

        ofs += 4;



        tcg_out_st(s, TCG_TYPE_I32, l->addrlo_reg, TCG_REG_ESP, ofs);

        ofs += 4;



        if (TARGET_LONG_BITS == 64) {

            tcg_out_st(s, TCG_TYPE_I32, l->addrhi_reg, TCG_REG_ESP, ofs);

            ofs += 4;

        }



        tcg_out_sti(s, TCG_TYPE_I32, TCG_REG_ESP, ofs, l->mem_index);

        ofs += 4;



        tcg_out_sti(s, TCG_TYPE_I32, TCG_REG_ESP, ofs, (uintptr_t)l->raddr);

    } else {

        tcg_out_mov(s, TCG_TYPE_PTR, tcg_target_call_iarg_regs[0], TCG_AREG0);

        /* The second argument is already loaded with addrlo.  */

        tcg_out_movi(s, TCG_TYPE_I32, tcg_target_call_iarg_regs[2],

                     l->mem_index);

        tcg_out_movi(s, TCG_TYPE_PTR, tcg_target_call_iarg_regs[3],

                     (uintptr_t)l->raddr);

    }



    tcg_out_calli(s, (uintptr_t)qemu_ld_helpers[opc & ~MO_SIGN]);



    data_reg = l->datalo_reg;

    switch (opc & MO_SSIZE) {

    case MO_SB:

        tcg_out_ext8s(s, data_reg, TCG_REG_EAX, P_REXW);

        break;

    case MO_SW:

        tcg_out_ext16s(s, data_reg, TCG_REG_EAX, P_REXW);

        break;

#if TCG_TARGET_REG_BITS == 64

    case MO_SL:

        tcg_out_ext32s(s, data_reg, TCG_REG_EAX);

        break;

#endif

    case MO_UB:

    case MO_UW:

        /* Note that the helpers have zero-extended to tcg_target_long.  */

    case MO_UL:

        tcg_out_mov(s, TCG_TYPE_I32, data_reg, TCG_REG_EAX);

        break;

    case MO_Q:

        if (TCG_TARGET_REG_BITS == 64) {

            tcg_out_mov(s, TCG_TYPE_I64, data_reg, TCG_REG_RAX);

        } else if (data_reg == TCG_REG_EDX) {

            /* xchg %edx, %eax */

            tcg_out_opc(s, OPC_XCHG_ax_r32 + TCG_REG_EDX, 0, 0, 0);

            tcg_out_mov(s, TCG_TYPE_I32, l->datahi_reg, TCG_REG_EAX);

        } else {

            tcg_out_mov(s, TCG_TYPE_I32, data_reg, TCG_REG_EAX);

            tcg_out_mov(s, TCG_TYPE_I32, l->datahi_reg, TCG_REG_EDX);

        }

        break;

    default:

        tcg_abort();

    }



    /* Jump to the code corresponding to next IR of qemu_st */

    tcg_out_jmp(s, (uintptr_t)l->raddr);

}

static long do_sigreturn_v1(CPUARMState *env)

{

        abi_ulong frame_addr;

	struct sigframe_v1 *frame;

	target_sigset_t set;

        sigset_t host_set;

        int i;



	/*

	 * Since we stacked the signal on a 64-bit boundary,

	 * then 'sp' should be word aligned here.  If it's

	 * not, then the user is trying to mess with us.

	 */

	if (env->regs[13] & 7)

		goto badframe;



        frame_addr = env->regs[13];

	if (!lock_user_struct(VERIFY_READ, frame, frame_addr, 1))

                goto badframe;



	if (__get_user(set.sig[0], &frame->sc.oldmask))

            goto badframe;

        for(i = 1; i < TARGET_NSIG_WORDS; i++) {

            if (__get_user(set.sig[i], &frame->extramask[i - 1]))

                goto badframe;

        }



        target_to_host_sigset_internal(&host_set, &set);

        sigprocmask(SIG_SETMASK, &host_set, NULL);



	if (restore_sigcontext(env, &frame->sc))

		goto badframe;



#if 0

	/* Send SIGTRAP if we're single-stepping */

	if (ptrace_cancel_bpt(current))

		send_sig(SIGTRAP, current, 1);

#endif

	unlock_user_struct(frame, frame_addr, 0);

        return env->regs[0];



badframe:

	unlock_user_struct(frame, frame_addr, 0);

        force_sig(TARGET_SIGSEGV /* , current */);

	return 0;

}

static void tcp_chr_connect(void *opaque)

{

    CharDriverState *chr = opaque;

    TCPCharDriver *s = chr->opaque;

    QIOChannelSocket *sioc = QIO_CHANNEL_SOCKET(s->ioc);



    g_free(chr->filename);

    chr->filename = sockaddr_to_str(&sioc->localAddr, sioc->localAddrLen,

                                    &sioc->remoteAddr, sioc->remoteAddrLen,

                                    s->is_listen, s->is_telnet);



    s->connected = 1;

    if (s->ioc) {

        chr->fd_in_tag = io_add_watch_poll(s->ioc,

                                           tcp_chr_read_poll,

                                           tcp_chr_read, chr);

    }

    qemu_chr_be_generic_open(chr);

}

static void gen_muldiv (DisasContext *ctx, uint32_t opc,

                        int rs, int rt)

{

    const char *opn = "mul/div";

    TCGv t0, t1;

    unsigned int acc;



    switch (opc) {

    case OPC_DIV:

    case OPC_DIVU:

#if defined(TARGET_MIPS64)

    case OPC_DDIV:

    case OPC_DDIVU:

#endif

        t0 = tcg_temp_local_new();

        t1 = tcg_temp_local_new();

        break;

    default:

        t0 = tcg_temp_new();

        t1 = tcg_temp_new();

        break;

    }



    gen_load_gpr(t0, rs);

    gen_load_gpr(t1, rt);

    switch (opc) {

    case OPC_DIV:

        {

            int l1 = gen_new_label();

            int l2 = gen_new_label();



            tcg_gen_ext32s_tl(t0, t0);

            tcg_gen_ext32s_tl(t1, t1);

            tcg_gen_brcondi_tl(TCG_COND_EQ, t1, 0, l1);

            tcg_gen_brcondi_tl(TCG_COND_NE, t0, INT_MIN, l2);

            tcg_gen_brcondi_tl(TCG_COND_NE, t1, -1, l2);



            tcg_gen_mov_tl(cpu_LO[0], t0);

            tcg_gen_movi_tl(cpu_HI[0], 0);

            tcg_gen_br(l1);

            gen_set_label(l2);

            tcg_gen_div_tl(cpu_LO[0], t0, t1);

            tcg_gen_rem_tl(cpu_HI[0], t0, t1);

            tcg_gen_ext32s_tl(cpu_LO[0], cpu_LO[0]);

            tcg_gen_ext32s_tl(cpu_HI[0], cpu_HI[0]);

            gen_set_label(l1);

        }

        opn = "div";

        break;

    case OPC_DIVU:

        {

            int l1 = gen_new_label();



            tcg_gen_ext32u_tl(t0, t0);

            tcg_gen_ext32u_tl(t1, t1);

            tcg_gen_brcondi_tl(TCG_COND_EQ, t1, 0, l1);

            tcg_gen_divu_tl(cpu_LO[0], t0, t1);

            tcg_gen_remu_tl(cpu_HI[0], t0, t1);

            tcg_gen_ext32s_tl(cpu_LO[0], cpu_LO[0]);

            tcg_gen_ext32s_tl(cpu_HI[0], cpu_HI[0]);

            gen_set_label(l1);

        }

        opn = "divu";

        break;

    case OPC_MULT:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext_tl_i64(t2, t0);

            tcg_gen_ext_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "mult";

        break;

    case OPC_MULTU:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext32u_tl(t0, t0);

            tcg_gen_ext32u_tl(t1, t1);

            tcg_gen_extu_tl_i64(t2, t0);

            tcg_gen_extu_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "multu";

        break;

#if defined(TARGET_MIPS64)

    case OPC_DDIV:

        {

            int l1 = gen_new_label();

            int l2 = gen_new_label();



            tcg_gen_brcondi_tl(TCG_COND_EQ, t1, 0, l1);

            tcg_gen_brcondi_tl(TCG_COND_NE, t0, -1LL << 63, l2);

            tcg_gen_brcondi_tl(TCG_COND_NE, t1, -1LL, l2);

            tcg_gen_mov_tl(cpu_LO[0], t0);

            tcg_gen_movi_tl(cpu_HI[0], 0);

            tcg_gen_br(l1);

            gen_set_label(l2);

            tcg_gen_div_i64(cpu_LO[0], t0, t1);

            tcg_gen_rem_i64(cpu_HI[0], t0, t1);

            gen_set_label(l1);

        }

        opn = "ddiv";

        break;

    case OPC_DDIVU:

        {

            int l1 = gen_new_label();



            tcg_gen_brcondi_tl(TCG_COND_EQ, t1, 0, l1);

            tcg_gen_divu_i64(cpu_LO[0], t0, t1);

            tcg_gen_remu_i64(cpu_HI[0], t0, t1);

            gen_set_label(l1);

        }

        opn = "ddivu";

        break;

    case OPC_DMULT:

        gen_helper_dmult(cpu_env, t0, t1);

        opn = "dmult";

        break;

    case OPC_DMULTU:

        gen_helper_dmultu(cpu_env, t0, t1);

        opn = "dmultu";

        break;

#endif

    case OPC_MADD:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext_tl_i64(t2, t0);

            tcg_gen_ext_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_gen_concat_tl_i64(t3, cpu_LO[acc], cpu_HI[acc]);

            tcg_gen_add_i64(t2, t2, t3);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "madd";

        break;

    case OPC_MADDU:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext32u_tl(t0, t0);

            tcg_gen_ext32u_tl(t1, t1);

            tcg_gen_extu_tl_i64(t2, t0);

            tcg_gen_extu_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_gen_concat_tl_i64(t3, cpu_LO[acc], cpu_HI[acc]);

            tcg_gen_add_i64(t2, t2, t3);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "maddu";

        break;

    case OPC_MSUB:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext_tl_i64(t2, t0);

            tcg_gen_ext_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_gen_concat_tl_i64(t3, cpu_LO[acc], cpu_HI[acc]);

            tcg_gen_sub_i64(t2, t3, t2);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "msub";

        break;

    case OPC_MSUBU:

        {

            TCGv_i64 t2 = tcg_temp_new_i64();

            TCGv_i64 t3 = tcg_temp_new_i64();

            acc = ((ctx->opcode) >> 11) & 0x03;

            if (acc != 0) {

                check_dsp(ctx);

            }



            tcg_gen_ext32u_tl(t0, t0);

            tcg_gen_ext32u_tl(t1, t1);

            tcg_gen_extu_tl_i64(t2, t0);

            tcg_gen_extu_tl_i64(t3, t1);

            tcg_gen_mul_i64(t2, t2, t3);

            tcg_gen_concat_tl_i64(t3, cpu_LO[acc], cpu_HI[acc]);

            tcg_gen_sub_i64(t2, t3, t2);

            tcg_temp_free_i64(t3);

            tcg_gen_trunc_i64_tl(t0, t2);

            tcg_gen_shri_i64(t2, t2, 32);

            tcg_gen_trunc_i64_tl(t1, t2);

            tcg_temp_free_i64(t2);

            tcg_gen_ext32s_tl(cpu_LO[acc], t0);

            tcg_gen_ext32s_tl(cpu_HI[acc], t1);

        }

        opn = "msubu";

        break;

    default:

        MIPS_INVAL(opn);

        generate_exception(ctx, EXCP_RI);

        goto out;

    }

    (void)opn; /* avoid a compiler warning */

    MIPS_DEBUG("%s %s %s", opn, regnames[rs], regnames[rt]);

 out:

    tcg_temp_free(t0);

    tcg_temp_free(t1);

}

static void usb_msd_copy_data(MSDState *s)

{

    uint32_t len;

    len = s->usb_len;

    if (len > s->scsi_len)

        len = s->scsi_len;

    if (s->mode == USB_MSDM_DATAIN) {

        memcpy(s->usb_buf, s->scsi_buf, len);

    } else {

        memcpy(s->scsi_buf, s->usb_buf, len);

    }

    s->usb_len -= len;

    s->scsi_len -= len;

    s->usb_buf += len;

    s->scsi_buf += len;

    s->data_len -= len;

    if (s->scsi_len == 0 || s->data_len == 0) {

        if (s->mode == USB_MSDM_DATAIN) {

            s->scsi_dev->info->read_data(s->scsi_dev, s->tag);

        } else if (s->mode == USB_MSDM_DATAOUT) {

            s->scsi_dev->info->write_data(s->scsi_dev, s->tag);

        }

    }

}

