static void select_vgahw (const char *p)

{

    const char *opts;



    assert(vga_interface_type == VGA_NONE);

    if (strstart(p, "std", &opts)) {

        if (vga_available()) {

            vga_interface_type = VGA_STD;

        } else {

            error_report("standard VGA not available");

            exit(1);

        }

    } else if (strstart(p, "cirrus", &opts)) {

        if (cirrus_vga_available()) {

            vga_interface_type = VGA_CIRRUS;

        } else {

            error_report("Cirrus VGA not available");

            exit(1);

        }

    } else if (strstart(p, "vmware", &opts)) {

        if (vmware_vga_available()) {

            vga_interface_type = VGA_VMWARE;

        } else {

            error_report("VMWare SVGA not available");

            exit(1);

        }

    } else if (strstart(p, "virtio", &opts)) {

        if (virtio_vga_available()) {

            vga_interface_type = VGA_VIRTIO;

        } else {

            error_report("Virtio VGA not available");

            exit(1);

        }

    } else if (strstart(p, "xenfb", &opts)) {

        vga_interface_type = VGA_XENFB;

    } else if (strstart(p, "qxl", &opts)) {

        if (qxl_vga_available()) {

            vga_interface_type = VGA_QXL;

        } else {

            error_report("QXL VGA not available");

            exit(1);

        }

    } else if (strstart(p, "tcx", &opts)) {

        if (tcx_vga_available()) {

            vga_interface_type = VGA_TCX;

        } else {

            error_report("TCX framebuffer not available");

            exit(1);

        }

    } else if (strstart(p, "cg3", &opts)) {

        if (cg3_vga_available()) {

            vga_interface_type = VGA_CG3;

        } else {

            error_report("CG3 framebuffer not available");

            exit(1);

        }

    } else if (!strstart(p, "none", &opts)) {

    invalid_vga:

        error_report("unknown vga type: %s", p);

        exit(1);

    }

    while (*opts) {

        const char *nextopt;



        if (strstart(opts, ",retrace=", &nextopt)) {

            opts = nextopt;

            if (strstart(opts, "dumb", &nextopt))

                vga_retrace_method = VGA_RETRACE_DUMB;

            else if (strstart(opts, "precise", &nextopt))

                vga_retrace_method = VGA_RETRACE_PRECISE;

            else goto invalid_vga;

        } else goto invalid_vga;

        opts = nextopt;

    }

}

static target_ulong h_resize_hpt_commit(PowerPCCPU *cpu,

                                        sPAPRMachineState *spapr,

                                        target_ulong opcode,

                                        target_ulong *args)

{

    target_ulong flags = args[0];

    target_ulong shift = args[1];

    sPAPRPendingHPT *pending = spapr->pending_hpt;

    int rc;

    size_t newsize;



    if (spapr->resize_hpt == SPAPR_RESIZE_HPT_DISABLED) {

        return H_AUTHORITY;

    }



    trace_spapr_h_resize_hpt_commit(flags, shift);



    rc = kvmppc_resize_hpt_commit(cpu, flags, shift);

    if (rc != -ENOSYS) {

        return resize_hpt_convert_rc(rc);

    }



    if (flags != 0) {

        return H_PARAMETER;

    }



    if (!pending || (pending->shift != shift)) {

        /* no matching prepare */

        return H_CLOSED;

    }



    if (!pending->complete) {

        /* prepare has not completed */

        return H_BUSY;

    }



    /* Shouldn't have got past PREPARE without an HPT */

    g_assert(spapr->htab_shift);



    newsize = 1ULL << pending->shift;

    rc = rehash_hpt(cpu, spapr->htab, HTAB_SIZE(spapr),

                    pending->hpt, newsize);

    if (rc == H_SUCCESS) {

        qemu_vfree(spapr->htab);

        spapr->htab = pending->hpt;

        spapr->htab_shift = pending->shift;



        if (kvm_enabled()) {

            /* For KVM PR, update the HPT pointer */

            target_ulong sdr1 = (target_ulong)(uintptr_t)spapr->htab

                | (spapr->htab_shift - 18);

            kvmppc_update_sdr1(sdr1);

        }



        pending->hpt = NULL; /* so it's not free()d */

    }



    /* Clean up */

    spapr->pending_hpt = NULL;

    free_pending_hpt(pending);



    return rc;

}

