void hbitmap_set(HBitmap *hb, uint64_t start, uint64_t count)

{

    /* Compute range in the last layer.  */

    uint64_t last = start + count - 1;



    trace_hbitmap_set(hb, start, count,

                      start >> hb->granularity, last >> hb->granularity);



    start >>= hb->granularity;

    last >>= hb->granularity;

    count = last - start + 1;




    hb->count += count - hb_count_between(hb, start, last);

    hb_set_between(hb, HBITMAP_LEVELS - 1, start, last);

}

long do_sigreturn(CPUAlphaState *env)

{

    struct target_sigcontext *sc;

    abi_ulong sc_addr = env->ir[IR_A0];

    target_sigset_t target_set;

    sigset_t set;



    if (!lock_user_struct(VERIFY_READ, sc, sc_addr, 1)) {

        goto badframe;

    }



    target_sigemptyset(&target_set);

    if (__get_user(target_set.sig[0], &sc->sc_mask)) {

        goto badframe;

    }



    target_to_host_sigset_internal(&set, &target_set);

    do_sigprocmask(SIG_SETMASK, &set, NULL);



    if (restore_sigcontext(env, sc)) {

        goto badframe;

    }

    unlock_user_struct(sc, sc_addr, 0);

    return env->ir[IR_V0];



 badframe:

    unlock_user_struct(sc, sc_addr, 0);

    force_sig(TARGET_SIGSEGV);

}

static void coroutine_fn wait_serialising_requests(BdrvTrackedRequest *self)

{

    BlockDriverState *bs = self->bs;

    BdrvTrackedRequest *req;

    bool retry;



    if (!bs->serialising_in_flight) {

        return;

    }



    do {

        retry = false;

        QLIST_FOREACH(req, &bs->tracked_requests, list) {

            if (req == self || (!req->serialising && !self->serialising)) {

                continue;

            }

            if (tracked_request_overlaps(req, self->overlap_offset,

                                         self->overlap_bytes))

            {

                /* Hitting this means there was a reentrant request, for

                 * example, a block driver issuing nested requests.  This must

                 * never happen since it means deadlock.

                 */

                assert(qemu_coroutine_self() != req->co);



                qemu_co_queue_wait(&req->wait_queue);

                retry = true;

                break;

            }

        }

    } while (retry);

}

void qemu_spice_init(void)

{

    QemuOpts *opts = QTAILQ_FIRST(&qemu_spice_opts.head);

    const char *password, *str, *x509_dir, *addr,

        *x509_key_password = NULL,

        *x509_dh_file = NULL,

        *tls_ciphers = NULL;

    char *x509_key_file = NULL,

        *x509_cert_file = NULL,

        *x509_cacert_file = NULL;

    int port, tls_port, len, addr_flags;

    spice_image_compression_t compression;

    spice_wan_compression_t wan_compr;



    if (!opts) {

        return;


    port = qemu_opt_get_number(opts, "port", 0);

    tls_port = qemu_opt_get_number(opts, "tls-port", 0);

    if (!port && !tls_port) {

        return;


    password = qemu_opt_get(opts, "password");



    if (tls_port) {

        x509_dir = qemu_opt_get(opts, "x509-dir");

        if (NULL == x509_dir) {

            x509_dir = ".";


        len = strlen(x509_dir) + 32;



        str = qemu_opt_get(opts, "x509-key-file");

        if (str) {

            x509_key_file = qemu_strdup(str);

        } else {

            x509_key_file = qemu_malloc(len);

            snprintf(x509_key_file, len, "%s/%s", x509_dir, X509_SERVER_KEY_FILE);




        str = qemu_opt_get(opts, "x509-cert-file");

        if (str) {

            x509_cert_file = qemu_strdup(str);

        } else {

            x509_cert_file = qemu_malloc(len);

            snprintf(x509_cert_file, len, "%s/%s", x509_dir, X509_SERVER_CERT_FILE);




        str = qemu_opt_get(opts, "x509-cacert-file");

        if (str) {

            x509_cacert_file = qemu_strdup(str);

        } else {

            x509_cacert_file = qemu_malloc(len);

            snprintf(x509_cacert_file, len, "%s/%s", x509_dir, X509_CA_CERT_FILE);




        x509_key_password = qemu_opt_get(opts, "x509-key-password");

        x509_dh_file = qemu_opt_get(opts, "x509-dh-file");

        tls_ciphers = qemu_opt_get(opts, "tls-ciphers");




    addr = qemu_opt_get(opts, "addr");

    addr_flags = 0;

    if (qemu_opt_get_bool(opts, "ipv4", 0)) {

        addr_flags |= SPICE_ADDR_FLAG_IPV4_ONLY;

    } else if (qemu_opt_get_bool(opts, "ipv6", 0)) {

        addr_flags |= SPICE_ADDR_FLAG_IPV6_ONLY;




    spice_server = spice_server_new();

    spice_server_set_addr(spice_server, addr ? addr : "", addr_flags);

    if (port) {

