void virtio_notify(VirtIODevice *vdev, VirtQueue *vq)

{

    /* Always notify when queue is empty */

    if ((vq->inuse || vring_avail_idx(vq) != vq->last_avail_idx) &&

        (vring_avail_flags(vq) & VRING_AVAIL_F_NO_INTERRUPT))

        return;



    vdev->isr |= 0x01;

    virtio_update_irq(vdev);

}

static int64_t allocate_cluster(BlockDriverState *bs, int64_t sector_num)

{

    BDRVParallelsState *s = bs->opaque;

    uint32_t idx, offset, tmp;

    int64_t pos;

    int ret;



    idx = sector_num / s->tracks;

    offset = sector_num % s->tracks;



    if (idx >= s->catalog_size) {

        return -EINVAL;

    }

    if (s->catalog_bitmap[idx] != 0) {

        return (uint64_t)s->catalog_bitmap[idx] * s->off_multiplier + offset;

    }



    pos = bdrv_getlength(bs->file) >> BDRV_SECTOR_BITS;

    if (s->has_truncate) {

        ret = bdrv_truncate(bs->file, (pos + s->tracks) << BDRV_SECTOR_BITS);

    } else {

        ret = bdrv_write_zeroes(bs->file, pos, s->tracks, 0);

    }

    if (ret < 0) {

        return ret;

    }



    s->catalog_bitmap[idx] = pos / s->off_multiplier;



    tmp = cpu_to_le32(s->catalog_bitmap[idx]);



    ret = bdrv_pwrite(bs->file,

            sizeof(ParallelsHeader) + idx * sizeof(tmp), &tmp, sizeof(tmp));

    if (ret < 0) {

        s->catalog_bitmap[idx] = 0;

        return ret;

    }

    return (uint64_t)s->catalog_bitmap[idx] * s->off_multiplier + offset;

}

static int vdi_open(BlockDriverState *bs, QDict *options, int flags,

                    Error **errp)

{

    BDRVVdiState *s = bs->opaque;

    VdiHeader header;

    size_t bmap_size;

    int ret;



    logout("\n");



    ret = bdrv_read(bs->file, 0, (uint8_t *)&header, 1);

    if (ret < 0) {

        goto fail;

    }



    vdi_header_to_cpu(&header);

#if defined(CONFIG_VDI_DEBUG)

    vdi_header_print(&header);

#endif



    if (header.disk_size % SECTOR_SIZE != 0) {

        /* 'VBoxManage convertfromraw' can create images with odd disk sizes.

           We accept them but round the disk size to the next multiple of

           SECTOR_SIZE. */

        logout("odd disk size %" PRIu64 " B, round up\n", header.disk_size);

        header.disk_size += SECTOR_SIZE - 1;

        header.disk_size &= ~(SECTOR_SIZE - 1);

    }



    if (header.signature != VDI_SIGNATURE) {

        logout("bad vdi signature %08x\n", header.signature);

        ret = -EMEDIUMTYPE;

        goto fail;

    } else if (header.version != VDI_VERSION_1_1) {

        logout("unsupported version %u.%u\n",

               header.version >> 16, header.version & 0xffff);

        ret = -ENOTSUP;

        goto fail;

    } else if (header.offset_bmap % SECTOR_SIZE != 0) {

        /* We only support block maps which start on a sector boundary. */

        logout("unsupported block map offset 0x%x B\n", header.offset_bmap);

        ret = -ENOTSUP;

        goto fail;

    } else if (header.offset_data % SECTOR_SIZE != 0) {

        /* We only support data blocks which start on a sector boundary. */

        logout("unsupported data offset 0x%x B\n", header.offset_data);

        ret = -ENOTSUP;

        goto fail;

    } else if (header.sector_size != SECTOR_SIZE) {

        logout("unsupported sector size %u B\n", header.sector_size);

        ret = -ENOTSUP;

        goto fail;

    } else if (header.block_size != 1 * MiB) {

        logout("unsupported block size %u B\n", header.block_size);

        ret = -ENOTSUP;

        goto fail;

    } else if (header.disk_size >

               (uint64_t)header.blocks_in_image * header.block_size) {

        logout("unsupported disk size %" PRIu64 " B\n", header.disk_size);

        ret = -ENOTSUP;

        goto fail;

    } else if (!uuid_is_null(header.uuid_link)) {

        logout("link uuid != 0, unsupported\n");

        ret = -ENOTSUP;

        goto fail;

    } else if (!uuid_is_null(header.uuid_parent)) {

        logout("parent uuid != 0, unsupported\n");

        ret = -ENOTSUP;

        goto fail;

    }



    bs->total_sectors = header.disk_size / SECTOR_SIZE;



    s->block_size = header.block_size;

    s->block_sectors = header.block_size / SECTOR_SIZE;

    s->bmap_sector = header.offset_bmap / SECTOR_SIZE;

    s->header = header;



    bmap_size = header.blocks_in_image * sizeof(uint32_t);

    bmap_size = (bmap_size + SECTOR_SIZE - 1) / SECTOR_SIZE;

    s->bmap = g_malloc(bmap_size * SECTOR_SIZE);

    ret = bdrv_read(bs->file, s->bmap_sector, (uint8_t *)s->bmap, bmap_size);

    if (ret < 0) {

        goto fail_free_bmap;

    }



    /* Disable migration when vdi images are used */

    error_set(&s->migration_blocker,

              QERR_BLOCK_FORMAT_FEATURE_NOT_SUPPORTED,

              "vdi", bs->device_name, "live migration");

    migrate_add_blocker(s->migration_blocker);



    return 0;



 fail_free_bmap:

    g_free(s->bmap);



 fail:

    return ret;

}

