int qcrypto_cipher_decrypt(QCryptoCipher *cipher,

                           const void *in,

                           void *out,

                           size_t len,

                           Error **errp)

{

    QCryptoCipherNettle *ctx = cipher->opaque;



    switch (cipher->mode) {

    case QCRYPTO_CIPHER_MODE_ECB:

        ctx->alg_decrypt(ctx->ctx_decrypt ? ctx->ctx_decrypt : ctx->ctx_encrypt,

                         len, out, in);

        break;



    case QCRYPTO_CIPHER_MODE_CBC:

        cbc_decrypt(ctx->ctx_decrypt ? ctx->ctx_decrypt : ctx->ctx_encrypt,

                    ctx->alg_decrypt, ctx->niv, ctx->iv,

                    len, out, in);

        break;

    default:

        error_setg(errp, "Unsupported cipher algorithm %d",

                   cipher->alg);

        return -1;

    }

    return 0;

}

static void ahci_migrate(AHCIQState *from, AHCIQState *to, const char *uri)

{

    QOSState *tmp = to->parent;

    QPCIDevice *dev = to->dev;

    char *uri_local = NULL;



    if (uri == NULL) {

        uri_local = g_strdup_printf("%s%s", "unix:", mig_socket);

        uri = uri_local;

    }



    /* context will be 'to' after completion. */

    migrate(from->parent, to->parent, uri);



    /* We'd like for the AHCIState objects to still point

     * to information specific to its specific parent

     * instance, but otherwise just inherit the new data. */

    memcpy(to, from, sizeof(AHCIQState));

    to->parent = tmp;

    to->dev = dev;



    tmp = from->parent;

    dev = from->dev;

    memset(from, 0x00, sizeof(AHCIQState));

    from->parent = tmp;

    from->dev = dev;



    verify_state(to);

    g_free(uri_local);

}

static int kvm_virtio_pci_vq_vector_unmask(VirtIOPCIProxy *proxy,

                                        unsigned int queue_no,

                                        unsigned int vector,

                                        MSIMessage msg)

{

    VirtQueue *vq = virtio_get_queue(proxy->vdev, queue_no);

    EventNotifier *n = virtio_queue_get_guest_notifier(vq);

    VirtIOIRQFD *irqfd = &proxy->vector_irqfd[vector];

    int ret;



    if (irqfd->msg.data != msg.data || irqfd->msg.address != msg.address) {

        ret = kvm_irqchip_update_msi_route(kvm_state, irqfd->virq, msg);

        if (ret < 0) {

            return ret;

        }

    }



    /* If guest supports masking, irqfd is already setup, unmask it.

     * Otherwise, set it up now.

     */

    if (proxy->vdev->guest_notifier_mask) {

        proxy->vdev->guest_notifier_mask(proxy->vdev, queue_no, false);

        /* Test after unmasking to avoid losing events. */

        if (proxy->vdev->guest_notifier_pending &&

            proxy->vdev->guest_notifier_pending(proxy->vdev, queue_no)) {

            event_notifier_set(n);

        }

    } else {

        ret = kvm_virtio_pci_irqfd_use(proxy, queue_no, vector);

    }

    return ret;

}

static int vvfat_open(BlockDriverState *bs, const char* dirname, int flags)

{

    BDRVVVFATState *s = bs->opaque;

    int floppy = 0;

    int i;



#ifdef DEBUG

    vvv = s;

#endif



DLOG(if (stderr == NULL) {

    stderr = fopen("vvfat.log", "a");

    setbuf(stderr, NULL);

})



    s->bs = bs;



    s->fat_type=16;

    /* LATER TODO: if FAT32, adjust */

    s->sectors_per_cluster=0x10;

    /* 504MB disk*/

    bs->cyls=1024; bs->heads=16; bs->secs=63;



    s->current_cluster=0xffffffff;



    s->first_sectors_number=0x40;

    /* read only is the default for safety */

    bs->read_only = 1;

    s->qcow = s->write_target = NULL;

    s->qcow_filename = NULL;

    s->fat2 = NULL;

    s->downcase_short_names = 1;



    if (!strstart(dirname, "fat:", NULL))

	return -1;



    if (strstr(dirname, ":floppy:")) {

	floppy = 1;

	s->fat_type = 12;

	s->first_sectors_number = 1;

	s->sectors_per_cluster=2;

	bs->cyls = 80; bs->heads = 2; bs->secs = 36;

    }



    if (strstr(dirname, ":32:")) {

	fprintf(stderr, "Big fat greek warning: FAT32 has not been tested. You are welcome to do so!\n");

	s->fat_type = 32;

    } else if (strstr(dirname, ":16:")) {

	s->fat_type = 16;

    } else if (strstr(dirname, ":12:")) {

	s->fat_type = 12;

	bs->secs = 18;

    }



    s->sector_count=bs->cyls*bs->heads*bs->secs-(s->first_sectors_number-1);



    if (strstr(dirname, ":rw:")) {

	if (enable_write_target(s))

	    return -1;

	bs->read_only = 0;

    }



    i = strrchr(dirname, ':') - dirname;

    assert(i >= 3);

    if (dirname[i-2] == ':' && qemu_isalpha(dirname[i-1]))

	/* workaround for DOS drive names */

	dirname += i-1;

    else

	dirname += i+1;



    bs->total_sectors=bs->cyls*bs->heads*bs->secs;



    if(init_directories(s, dirname))

	return -1;



    s->sector_count = s->faked_sectors + s->sectors_per_cluster*s->cluster_count;



    if(s->first_sectors_number==0x40)

	init_mbr(s);



    /* for some reason or other, MS-DOS does not like to know about CHS... */

    if (floppy)

	bs->heads = bs->cyls = bs->secs = 0;



    //    assert(is_consistent(s));

    qemu_co_mutex_init(&s->lock);

    return 0;

}

VirtIODevice *virtio_scsi_init(DeviceState *dev, VirtIOSCSIConf *proxyconf)

{

    VirtIOSCSI *s;

    static int virtio_scsi_id;

    size_t sz;

    int i;



    sz = sizeof(VirtIOSCSI) + proxyconf->num_queues * sizeof(VirtQueue *);

    s = (VirtIOSCSI *)virtio_common_init("virtio-scsi", VIRTIO_ID_SCSI,

                                         sizeof(VirtIOSCSIConfig), sz);



    s->qdev = dev;

    s->conf = proxyconf;



    /* TODO set up vdev function pointers */

    s->vdev.get_config = virtio_scsi_get_config;

    s->vdev.set_config = virtio_scsi_set_config;

    s->vdev.get_features = virtio_scsi_get_features;

    s->vdev.reset = virtio_scsi_reset;



    s->ctrl_vq = virtio_add_queue(&s->vdev, VIRTIO_SCSI_VQ_SIZE,

                                   virtio_scsi_handle_ctrl);

    s->event_vq = virtio_add_queue(&s->vdev, VIRTIO_SCSI_VQ_SIZE,

                                   NULL);

    for (i = 0; i < s->conf->num_queues; i++) {

        s->cmd_vqs[i] = virtio_add_queue(&s->vdev, VIRTIO_SCSI_VQ_SIZE,

                                         virtio_scsi_handle_cmd);

    }



    scsi_bus_new(&s->bus, dev, &virtio_scsi_scsi_info);

    if (!dev->hotplugged) {

        scsi_bus_legacy_handle_cmdline(&s->bus);

    }



    register_savevm(dev, "virtio-scsi", virtio_scsi_id++, 1,

                    virtio_scsi_save, virtio_scsi_load, s);



    return &s->vdev;

}

static void test_properties(const char *path)

{

    char *child_path;

    QDict *response, *tuple;

    QList *list;

    QListEntry *entry;



    g_test_message("Obtaining properties of %s", path);

    response = qmp("{ 'execute': 'qom-list',"

                   "  'arguments': { 'path': '%s' } }", path);

    g_assert(response);



    g_assert(qdict_haskey(response, "return"));

    list = qobject_to_qlist(qdict_get(response, "return"));

    QLIST_FOREACH_ENTRY(list, entry) {

        tuple = qobject_to_qdict(qlist_entry_obj(entry));

        if (strstart(qdict_get_str(tuple, "type"), "child<", NULL)) {

            child_path = g_strdup_printf("%s/%s",

                                         path, qdict_get_str(tuple, "name"));

            test_properties(child_path);

            g_free(child_path);

        } else {

            const char *prop = qdict_get_str(tuple, "name");

            g_test_message("Testing property %s.%s", path, prop);

            response = qmp("{ 'execute': 'qom-get',"

                           "  'arguments': { 'path': '%s',"

                           "                 'property': '%s' } }",

                           path, prop);

            /* qom-get may fail but should not, e.g., segfault. */

            g_assert(response);

        }

    }

}

int coroutine_fn blk_co_pwritev(BlockBackend *blk, int64_t offset,

                                unsigned int bytes, QEMUIOVector *qiov,

                                BdrvRequestFlags flags)

{

