sosendto(struct socket *so, struct mbuf *m)

{

	Slirp *slirp = so->slirp;

	int ret;

	struct sockaddr_in addr;



	DEBUG_CALL("sosendto");

	DEBUG_ARG("so = %p", so);

	DEBUG_ARG("m = %p", m);



        addr.sin_family = AF_INET;

	if ((so->so_faddr.s_addr & slirp->vnetwork_mask.s_addr) ==

	    slirp->vnetwork_addr.s_addr) {

	  /* It's an alias */

	  if (so->so_faddr.s_addr == slirp->vnameserver_addr.s_addr) {

	    if (get_dns_addr(&addr.sin_addr) < 0)

	      addr.sin_addr = loopback_addr;

	  } else {

	    addr.sin_addr = loopback_addr;

	  }

	} else

	  addr.sin_addr = so->so_faddr;

	addr.sin_port = so->so_fport;



	DEBUG_MISC((dfd, " sendto()ing, addr.sin_port=%d, addr.sin_addr.s_addr=%.16s\n", ntohs(addr.sin_port), inet_ntoa(addr.sin_addr)));



	/* Don't care what port we get */

	ret = sendto(so->s, m->m_data, m->m_len, 0,

		     (struct sockaddr *)&addr, sizeof (struct sockaddr));

	if (ret < 0)

		return -1;



	/*

	 * Kill the socket if there's no reply in 4 minutes,

	 * but only if it's an expirable socket

	 */

	if (so->so_expire)

		so->so_expire = curtime + SO_EXPIRE;

	so->so_state &= SS_PERSISTENT_MASK;

	so->so_state |= SS_ISFCONNECTED; /* So that it gets select()ed */

	return 0;

}

long do_rt_sigreturn(CPUSH4State *regs)

{

    struct target_rt_sigframe *frame;

    abi_ulong frame_addr;

    sigset_t blocked;

    target_ulong r0;



    frame_addr = regs->gregs[15];

    trace_user_do_rt_sigreturn(regs, frame_addr);

    if (!lock_user_struct(VERIFY_READ, frame, frame_addr, 1)) {

        goto badframe;

    }



    target_to_host_sigset(&blocked, &frame->uc.tuc_sigmask);

    do_sigprocmask(SIG_SETMASK, &blocked, NULL);



    restore_sigcontext(regs, &frame->uc.tuc_mcontext, &r0);



    if (do_sigaltstack(frame_addr +

                       offsetof(struct target_rt_sigframe, uc.tuc_stack),

                       0, get_sp_from_cpustate(regs)) == -EFAULT) {

        goto badframe;

    }



    unlock_user_struct(frame, frame_addr, 0);

    return r0;



badframe:

    unlock_user_struct(frame, frame_addr, 0);

    force_sig(TARGET_SIGSEGV);

    return 0;

}

static void patch_reloc(uint8_t *code_ptr, int type,

                        intptr_t value, intptr_t addend)

{

    uint32_t insn;

    value += addend;

    switch (type) {

    case R_SPARC_32:

        if (value != (uint32_t)value) {

            tcg_abort();

        }

        *(uint32_t *)code_ptr = value;

        break;

    case R_SPARC_WDISP16:

        value -= (intptr_t)code_ptr;

        if (!check_fit_tl(value >> 2, 16)) {

            tcg_abort();

        }

        insn = *(uint32_t *)code_ptr;

        insn &= ~INSN_OFF16(-1);

        insn |= INSN_OFF16(value);

        *(uint32_t *)code_ptr = insn;

        break;

    case R_SPARC_WDISP19:

        value -= (intptr_t)code_ptr;

        if (!check_fit_tl(value >> 2, 19)) {

            tcg_abort();

        }

        insn = *(uint32_t *)code_ptr;

        insn &= ~INSN_OFF19(-1);

        insn |= INSN_OFF19(value);

        *(uint32_t *)code_ptr = insn;

        break;

    default:

        tcg_abort();

    }

}

