static void fill_note(struct memelfnote *note, const char *name, int type,

                      unsigned int sz, void *data)

{

    unsigned int namesz;



    namesz = strlen(name) + 1;

    note->name = name;

    note->namesz = namesz;

    note->namesz_rounded = roundup(namesz, sizeof (int32_t));

    note->type = type;

    note->datasz = roundup(sz, sizeof (int32_t));;

    note->data = data;



    /*

     * We calculate rounded up note size here as specified by

     * ELF document.

     */

    note->notesz = sizeof (struct elf_note) +

        note->namesz_rounded + note->datasz;

}

int bdrv_snapshot_goto(BlockDriverState *bs,

                       const char *snapshot_id)

{

    BlockDriver *drv = bs->drv;

    int ret, open_ret;



    if (!drv)

        return -ENOMEDIUM;

    if (drv->bdrv_snapshot_goto)

        return drv->bdrv_snapshot_goto(bs, snapshot_id);



    if (bs->file) {

        drv->bdrv_close(bs);

        ret = bdrv_snapshot_goto(bs->file, snapshot_id);

        open_ret = drv->bdrv_open(bs, NULL, bs->open_flags);

        if (open_ret < 0) {

            bdrv_delete(bs->file);

            bs->drv = NULL;

            return open_ret;

        }

        return ret;

    }



    return -ENOTSUP;

}

static void lsi_execute_script(LSIState *s)

{

    uint32_t insn;

    uint32_t addr, addr_high;

    int opcode;

    int insn_processed = 0;



    s->istat1 |= LSI_ISTAT1_SRUN;

again:

    insn_processed++;

    insn = read_dword(s, s->dsp);

    addr = read_dword(s, s->dsp + 4);

    addr_high = 0;

    DPRINTF("SCRIPTS dsp=%08x opcode %08x arg %08x\n", s->dsp, insn, addr);

    s->dsps = addr;

    s->dcmd = insn >> 24;

    s->dsp += 8;

    switch (insn >> 30) {

    case 0: /* Block move.  */

        if (s->sist1 & LSI_SIST1_STO) {

            DPRINTF("Delayed select timeout\n");

            lsi_stop_script(s);

            break;

        }

        s->dbc = insn & 0xffffff;

        s->rbc = s->dbc;

        if (insn & (1 << 29)) {

            /* Indirect addressing.  */

            addr = read_dword(s, addr);

        } else if (insn & (1 << 28)) {

            uint32_t buf[2];

            int32_t offset;

            /* Table indirect addressing.  */

            offset = sxt24(addr);

            cpu_physical_memory_read(s->dsa + offset, (uint8_t *)buf, 8);

            /* byte count is stored in bits 0:23 only */

            s->dbc = cpu_to_le32(buf[0]) & 0xffffff;

            s->rbc = s->dbc;

            addr = cpu_to_le32(buf[1]);



            /* 40-bit DMA, upper addr bits [39:32] stored in first DWORD of

             * table, bits [31:24] */

            if (lsi_dma_40bit(s))

                addr_high = cpu_to_le32(buf[0]) >> 24;

        }

        if ((s->sstat1 & PHASE_MASK) != ((insn >> 24) & 7)) {

            DPRINTF("Wrong phase got %d expected %d\n",

                    s->sstat1 & PHASE_MASK, (insn >> 24) & 7);

            lsi_script_scsi_interrupt(s, LSI_SIST0_MA, 0);

            break;

        }

        s->dnad = addr;

        s->dnad64 = addr_high;

        /* ??? Set ESA.  */

        s->ia = s->dsp - 8;

        switch (s->sstat1 & 0x7) {

        case PHASE_DO:

            s->waiting = 2;

            lsi_do_dma(s, 1);

            if (s->waiting)

                s->waiting = 3;

            break;

        case PHASE_DI:

            s->waiting = 2;

            s->current_dma_len = s->dbc;

            lsi_do_dma(s, 0);

            if (s->waiting)

                s->waiting = 3;

            break;

        case PHASE_CMD:

            lsi_do_command(s);

            break;

        case PHASE_ST:

            lsi_do_status(s);

            break;

        case PHASE_MO:

            lsi_do_msgout(s);

            break;

        case PHASE_MI:

            lsi_do_msgin(s);

            break;

        default:

            BADF("Unimplemented phase %d\n", s->sstat1 & PHASE_MASK);

            exit(1);

        }

        s->dfifo = s->dbc & 0xff;

        s->ctest5 = (s->ctest5 & 0xfc) | ((s->dbc >> 8) & 3);

        s->sbc = s->dbc;

        s->rbc -= s->dbc;

        s->ua = addr + s->dbc;

        break;



    case 1: /* IO or Read/Write instruction.  */

        opcode = (insn >> 27) & 7;

        if (opcode < 5) {

            uint32_t id;



            if (insn & (1 << 25)) {

                id = read_dword(s, s->dsa + sxt24(insn));

            } else {

                id = addr;

            }

            id = (id >> 16) & 0xf;

            if (insn & (1 << 26)) {

                addr = s->dsp + sxt24(addr);

            }

            s->dnad = addr;

            switch (opcode) {

            case 0: /* Select */

                s->sdid = id;

                if (s->current_dma_len && (s->ssid & 0xf) == id) {

                    DPRINTF("Already reselected by target %d\n", id);

                    break;

                }

                s->sstat0 |= LSI_SSTAT0_WOA;

                s->scntl1 &= ~LSI_SCNTL1_IARB;

                if (id >= LSI_MAX_DEVS || !s->scsi_dev[id]) {

                    DPRINTF("Selected absent target %d\n", id);

                    lsi_script_scsi_interrupt(s, 0, LSI_SIST1_STO);

                    lsi_disconnect(s);

                    break;

                }

                DPRINTF("Selected target %d%s\n",

                        id, insn & (1 << 3) ? " ATN" : "");

                /* ??? Linux drivers compain when this is set.  Maybe

                   it only applies in low-level mode (unimplemented).

                lsi_script_scsi_interrupt(s, LSI_SIST0_CMP, 0); */

                s->current_dev = s->scsi_dev[id];

                s->current_tag = id << 8;

                s->scntl1 |= LSI_SCNTL1_CON;

                if (insn & (1 << 3)) {

                    s->socl |= LSI_SOCL_ATN;

                }

                lsi_set_phase(s, PHASE_MO);

                break;

            case 1: /* Disconnect */

                DPRINTF("Wait Disconect\n");

                s->scntl1 &= ~LSI_SCNTL1_CON;

                break;

            case 2: /* Wait Reselect */

                lsi_wait_reselect(s);

                break;

            case 3: /* Set */

                DPRINTF("Set%s%s%s%s\n",

                        insn & (1 << 3) ? " ATN" : "",

                        insn & (1 << 6) ? " ACK" : "",

                        insn & (1 << 9) ? " TM" : "",

                        insn & (1 << 10) ? " CC" : "");

                if (insn & (1 << 3)) {

                    s->socl |= LSI_SOCL_ATN;

                    lsi_set_phase(s, PHASE_MO);

                }

                if (insn & (1 << 9)) {

                    BADF("Target mode not implemented\n");

                    exit(1);

                }

                if (insn & (1 << 10))

                    s->carry = 1;

                break;

            case 4: /* Clear */

                DPRINTF("Clear%s%s%s%s\n",

                        insn & (1 << 3) ? " ATN" : "",

                        insn & (1 << 6) ? " ACK" : "",

                        insn & (1 << 9) ? " TM" : "",

                        insn & (1 << 10) ? " CC" : "");

                if (insn & (1 << 3)) {

                    s->socl &= ~LSI_SOCL_ATN;

                }

                if (insn & (1 << 10))

                    s->carry = 0;

                break;

            }

        } else {

            uint8_t op0;

            uint8_t op1;

            uint8_t data8;

            int reg;

            int operator;

#ifdef DEBUG_LSI

            static const char *opcode_names[3] =

                {"Write", "Read", "Read-Modify-Write"};

            static const char *operator_names[8] =

                {"MOV", "SHL", "OR", "XOR", "AND", "SHR", "ADD", "ADC"};

#endif



            reg = ((insn >> 16) & 0x7f) | (insn & 0x80);

            data8 = (insn >> 8) & 0xff;

            opcode = (insn >> 27) & 7;

            operator = (insn >> 24) & 7;

            DPRINTF("%s reg 0x%x %s data8=0x%02x sfbr=0x%02x%s\n",

                    opcode_names[opcode - 5], reg,

                    operator_names[operator], data8, s->sfbr,

                    (insn & (1 << 23)) ? " SFBR" : "");

            op0 = op1 = 0;

            switch (opcode) {

            case 5: /* From SFBR */

                op0 = s->sfbr;

                op1 = data8;

                break;

            case 6: /* To SFBR */

                if (operator)

                    op0 = lsi_reg_readb(s, reg);

                op1 = data8;

                break;

            case 7: /* Read-modify-write */

                if (operator)

                    op0 = lsi_reg_readb(s, reg);

                if (insn & (1 << 23)) {

                    op1 = s->sfbr;

                } else {

                    op1 = data8;

                }

                break;

            }



            switch (operator) {

            case 0: /* move */

                op0 = op1;

                break;

            case 1: /* Shift left */

                op1 = op0 >> 7;

                op0 = (op0 << 1) | s->carry;

                s->carry = op1;

                break;

            case 2: /* OR */

                op0 |= op1;

                break;

            case 3: /* XOR */

                op0 ^= op1;

                break;

            case 4: /* AND */

                op0 &= op1;

                break;

            case 5: /* SHR */

                op1 = op0 & 1;

                op0 = (op0 >> 1) | (s->carry << 7);

                s->carry = op1;

                break;

            case 6: /* ADD */

                op0 += op1;

                s->carry = op0 < op1;

                break;

            case 7: /* ADC */

                op0 += op1 + s->carry;

                if (s->carry)

                    s->carry = op0 <= op1;

                else

                    s->carry = op0 < op1;

                break;

            }



            switch (opcode) {

            case 5: /* From SFBR */

            case 7: /* Read-modify-write */

                lsi_reg_writeb(s, reg, op0);

                break;

            case 6: /* To SFBR */

                s->sfbr = op0;

                break;

            }

        }

        break;



    case 2: /* Transfer Control.  */

        {

            int cond;

            int jmp;



            if ((insn & 0x002e0000) == 0) {

                DPRINTF("NOP\n");

                break;

            }

            if (s->sist1 & LSI_SIST1_STO) {

                DPRINTF("Delayed select timeout\n");

                lsi_stop_script(s);

                break;

            }

            cond = jmp = (insn & (1 << 19)) != 0;

            if (cond == jmp && (insn & (1 << 21))) {

                DPRINTF("Compare carry %d\n", s->carry == jmp);

                cond = s->carry != 0;

            }

            if (cond == jmp && (insn & (1 << 17))) {

                DPRINTF("Compare phase %d %c= %d\n",

                        (s->sstat1 & PHASE_MASK),

                        jmp ? '=' : '!',

                        ((insn >> 24) & 7));

                cond = (s->sstat1 & PHASE_MASK) == ((insn >> 24) & 7);

            }

            if (cond == jmp && (insn & (1 << 18))) {

                uint8_t mask;



                mask = (~insn >> 8) & 0xff;

                DPRINTF("Compare data 0x%x & 0x%x %c= 0x%x\n",

                        s->sfbr, mask, jmp ? '=' : '!', insn & mask);

                cond = (s->sfbr & mask) == (insn & mask);

            }

            if (cond == jmp) {

                if (insn & (1 << 23)) {

                    /* Relative address.  */

                    addr = s->dsp + sxt24(addr);

                }

                switch ((insn >> 27) & 7) {

                case 0: /* Jump */

                    DPRINTF("Jump to 0x%08x\n", addr);

                    s->dsp = addr;

                    break;

                case 1: /* Call */

                    DPRINTF("Call 0x%08x\n", addr);

                    s->temp = s->dsp;

                    s->dsp = addr;

                    break;

                case 2: /* Return */

                    DPRINTF("Return to 0x%08x\n", s->temp);

                    s->dsp = s->temp;

                    break;

                case 3: /* Interrupt */

                    DPRINTF("Interrupt 0x%08x\n", s->dsps);

                    if ((insn & (1 << 20)) != 0) {

                        s->istat0 |= LSI_ISTAT0_INTF;

                        lsi_update_irq(s);

                    } else {

                        lsi_script_dma_interrupt(s, LSI_DSTAT_SIR);

                    }

                    break;

                default:

                    DPRINTF("Illegal transfer control\n");

                    lsi_script_dma_interrupt(s, LSI_DSTAT_IID);

                    break;

                }

            } else {

                DPRINTF("Control condition failed\n");

            }

        }

        break;



    case 3:

        if ((insn & (1 << 29)) == 0) {

            /* Memory move.  */

            uint32_t dest;

            /* ??? The docs imply the destination address is loaded into

               the TEMP register.  However the Linux drivers rely on

               the value being presrved.  */

            dest = read_dword(s, s->dsp);

            s->dsp += 4;

            lsi_memcpy(s, dest, addr, insn & 0xffffff);

        } else {

            uint8_t data[7];

            int reg;

            int n;

            int i;



            if (insn & (1 << 28)) {

                addr = s->dsa + sxt24(addr);

            }

            n = (insn & 7);

            reg = (insn >> 16) & 0xff;

            if (insn & (1 << 24)) {

                cpu_physical_memory_read(addr, data, n);

                DPRINTF("Load reg 0x%x size %d addr 0x%08x = %08x\n", reg, n,

                        addr, *(int *)data);

                for (i = 0; i < n; i++) {

                    lsi_reg_writeb(s, reg + i, data[i]);

                }

            } else {

                DPRINTF("Store reg 0x%x size %d addr 0x%08x\n", reg, n, addr);

                for (i = 0; i < n; i++) {

                    data[i] = lsi_reg_readb(s, reg + i);

                }

                cpu_physical_memory_write(addr, data, n);

            }

        }

    }

    if (insn_processed > 10000 && !s->waiting) {

        /* Some windows drivers make the device spin waiting for a memory

           location to change.  If we have been executed a lot of code then

           assume this is the case and force an unexpected device disconnect.

           This is apparently sufficient to beat the drivers into submission.

         */

        if (!(s->sien0 & LSI_SIST0_UDC))

            fprintf(stderr, "inf. loop with UDC masked\n");

        lsi_script_scsi_interrupt(s, LSI_SIST0_UDC, 0);

        lsi_disconnect(s);

    } else if (s->istat1 & LSI_ISTAT1_SRUN && !s->waiting) {

        if (s->dcntl & LSI_DCNTL_SSM) {

            lsi_script_dma_interrupt(s, LSI_DSTAT_SSI);

        } else {

            goto again;

        }

    }

    DPRINTF("SCRIPTS execution stopped\n");

}

static void kqemu_update_cpuid(CPUState *env)

{

    int critical_features_mask, features, ext_features, ext_features_mask;

    uint32_t eax, ebx, ecx, edx;



    /* the following features are kept identical on the host and

       target cpus because they are important for user code. Strictly

       speaking, only SSE really matters because the OS must support

       it if the user code uses it. */

    critical_features_mask =

        CPUID_CMOV | CPUID_CX8 |

        CPUID_FXSR | CPUID_MMX | CPUID_SSE |

        CPUID_SSE2 | CPUID_SEP;

    ext_features_mask = CPUID_EXT_SSE3 | CPUID_EXT_MONITOR;

    if (!is_cpuid_supported()) {

        features = 0;

        ext_features = 0;

    } else {

        cpuid(1, eax, ebx, ecx, edx);

        features = edx;

        ext_features = ecx;

    }

#ifdef __x86_64__

    /* NOTE: on x86_64 CPUs, SYSENTER is not supported in

       compatibility mode, so in order to have the best performances

       it is better not to use it */

    features &= ~CPUID_SEP;

#endif

    env->cpuid_features = (env->cpuid_features & ~critical_features_mask) |

        (features & critical_features_mask);

    env->cpuid_ext_features = (env->cpuid_ext_features & ~ext_features_mask) |

        (ext_features & ext_features_mask);

    /* XXX: we could update more of the target CPUID state so that the

       non accelerated code sees exactly the same CPU features as the

       accelerated code */

}

static GenericList *qapi_dealloc_next_list(Visitor *v, GenericList **listp,

                                           size_t size)

{

    GenericList *list = *listp;

    QapiDeallocVisitor *qov = to_qov(v);

    StackEntry *e = QTAILQ_FIRST(&qov->stack);



    if (e && e->is_list_head) {

        e->is_list_head = false;

        return list;

    }



    if (list) {

        list = list->next;

        g_free(*listp);

        return list;

    }



    return NULL;

}

static void qbool_destroy_obj(QObject *obj)

{

    assert(obj != NULL);

    g_free(qobject_to_qbool(obj));

}

static QemuOpt *qemu_opt_find(QemuOpts *opts, const char *name)

{

    QemuOpt *opt;



    TAILQ_FOREACH(opt, &opts->head, next) {

        if (strcmp(opt->name, name) != 0)

            continue;

        return opt;

    }

    return NULL;

}

uint64_t helper_cmptun (uint64_t a, uint64_t b)

{

    float64 fa, fb;



    fa = t_to_float64(a);

    fb = t_to_float64(b);



    if (float64_is_quiet_nan(fa) || float64_is_quiet_nan(fb))

        return 0x4000000000000000ULL;

    else

        return 0;

}

Aml *aml_arg(int pos)

{

    Aml *var;

    uint8_t op = 0x68 /* ARG0 op */ + pos;



    assert(pos <= 6);

    var = aml_opcode(op);

    return var;

}

static int vnc_display_listen_addr(VncDisplay *vd,

                                   SocketAddressLegacy *addr,

                                   const char *name,

                                   QIOChannelSocket ***lsock,

                                   guint **lsock_tag,

                                   size_t *nlsock,

                                   Error **errp)

{

    QIODNSResolver *resolver = qio_dns_resolver_get_instance();

    SocketAddressLegacy **rawaddrs = NULL;

    size_t nrawaddrs = 0;

    Error *listenerr = NULL;

    bool listening = false;

    size_t i;



    if (qio_dns_resolver_lookup_sync(resolver, addr, &nrawaddrs,

                                     &rawaddrs, errp) < 0) {

        return -1;

    }



    for (i = 0; i < nrawaddrs; i++) {

        QIOChannelSocket *sioc = qio_channel_socket_new();



        qio_channel_set_name(QIO_CHANNEL(sioc), name);

        if (qio_channel_socket_listen_sync(

                sioc, rawaddrs[i], listenerr == NULL ? &listenerr : NULL) < 0) {

            object_unref(OBJECT(sioc));

            continue;

        }

        listening = true;

        (*nlsock)++;

        *lsock = g_renew(QIOChannelSocket *, *lsock, *nlsock);

        *lsock_tag = g_renew(guint, *lsock_tag, *nlsock);



        (*lsock)[*nlsock - 1] = sioc;

        (*lsock_tag)[*nlsock - 1] = 0;

    }



    for (i = 0; i < nrawaddrs; i++) {

        qapi_free_SocketAddressLegacy(rawaddrs[i]);

    }

    g_free(rawaddrs);



    if (listenerr) {

        if (!listening) {

            error_propagate(errp, listenerr);

            return -1;

        } else {

            error_free(listenerr);

        }

    }



    for (i = 0; i < *nlsock; i++) {

        (*lsock_tag)[i] = qio_channel_add_watch(

            QIO_CHANNEL((*lsock)[i]),

            G_IO_IN, vnc_listen_io, vd, NULL);

    }



    return 0;

}

static void OPLWriteReg(FM_OPL *OPL, int r, int v)

{

	OPL_CH *CH;

	int slot;

	int block_fnum;



	switch(r&0xe0)

	{

	case 0x00: /* 00-1f:control */

		switch(r&0x1f)

		{

		case 0x01:

			/* wave selector enable */

			if(OPL->type&OPL_TYPE_WAVESEL)

			{

				OPL->wavesel = v&0x20;

				if(!OPL->wavesel)

				{

					/* preset compatible mode */

					int c;

					for(c=0;c<OPL->max_ch;c++)

					{

						OPL->P_CH[c].SLOT[SLOT1].wavetable = &SIN_TABLE[0];

						OPL->P_CH[c].SLOT[SLOT2].wavetable = &SIN_TABLE[0];

					}

				}

			}

			return;

		case 0x02:	/* Timer 1 */

			OPL->T[0] = (256-v)*4;

			break;

		case 0x03:	/* Timer 2 */

			OPL->T[1] = (256-v)*16;

			return;

		case 0x04:	/* IRQ clear / mask and Timer enable */

			if(v&0x80)

			{	/* IRQ flag clear */

				OPL_STATUS_RESET(OPL,0x7f);

			}

			else

			{	/* set IRQ mask ,timer enable*/

				UINT8 st1 = v&1;

				UINT8 st2 = (v>>1)&1;

				/* IRQRST,T1MSK,t2MSK,EOSMSK,BRMSK,x,ST2,ST1 */

				OPL_STATUS_RESET(OPL,v&0x78);

				OPL_STATUSMASK_SET(OPL,((~v)&0x78)|0x01);

				/* timer 2 */

				if(OPL->st[1] != st2)

				{

					double interval = st2 ? (double)OPL->T[1]*OPL->TimerBase : 0.0;

					OPL->st[1] = st2;

					if (OPL->TimerHandler) (OPL->TimerHandler)(OPL->TimerParam+1,interval);

				}

				/* timer 1 */

				if(OPL->st[0] != st1)

				{

					double interval = st1 ? (double)OPL->T[0]*OPL->TimerBase : 0.0;

					OPL->st[0] = st1;

					if (OPL->TimerHandler) (OPL->TimerHandler)(OPL->TimerParam+0,interval);

				}

			}

			return;

#if BUILD_Y8950

		case 0x06:		/* Key Board OUT */

			if(OPL->type&OPL_TYPE_KEYBOARD)

			{

				if(OPL->keyboardhandler_w)

					OPL->keyboardhandler_w(OPL->keyboard_param,v);

				else

					LOG(LOG_WAR,("OPL:write unmapped KEYBOARD port\n"));

			}

			return;

		case 0x07:	/* DELTA-T control : START,REC,MEMDATA,REPT,SPOFF,x,x,RST */

			if(OPL->type&OPL_TYPE_ADPCM)

				YM_DELTAT_ADPCM_Write(OPL->deltat,r-0x07,v);

			return;

		case 0x08:	/* MODE,DELTA-T : CSM,NOTESEL,x,x,smpl,da/ad,64k,rom */

			OPL->mode = v;

			v&=0x1f;	/* for DELTA-T unit */

		case 0x09:		/* START ADD */

		case 0x0a:

		case 0x0b:		/* STOP ADD  */

		case 0x0c:

		case 0x0d:		/* PRESCALE   */

		case 0x0e:

		case 0x0f:		/* ADPCM data */

		case 0x10: 		/* DELTA-N    */

		case 0x11: 		/* DELTA-N    */

		case 0x12: 		/* EG-CTRL    */

			if(OPL->type&OPL_TYPE_ADPCM)

				YM_DELTAT_ADPCM_Write(OPL->deltat,r-0x07,v);

			return;

#if 0

		case 0x15:		/* DAC data    */

		case 0x16:

		case 0x17:		/* SHIFT    */

			return;

		case 0x18:		/* I/O CTRL (Direction) */

			if(OPL->type&OPL_TYPE_IO)

				OPL->portDirection = v&0x0f;

			return;

		case 0x19:		/* I/O DATA */

			if(OPL->type&OPL_TYPE_IO)

			{

				OPL->portLatch = v;

				if(OPL->porthandler_w)

					OPL->porthandler_w(OPL->port_param,v&OPL->portDirection);

			}

			return;

		case 0x1a:		/* PCM data */

			return;

#endif

#endif

		}

		break;

	case 0x20:	/* am,vib,ksr,eg type,mul */

		slot = slot_array[r&0x1f];

		if(slot == -1) return;

		set_mul(OPL,slot,v);

		return;

	case 0x40:

		slot = slot_array[r&0x1f];

		if(slot == -1) return;

		set_ksl_tl(OPL,slot,v);

		return;

	case 0x60:

		slot = slot_array[r&0x1f];

		if(slot == -1) return;

		set_ar_dr(OPL,slot,v);

		return;

	case 0x80:

		slot = slot_array[r&0x1f];

		if(slot == -1) return;

		set_sl_rr(OPL,slot,v);

		return;

	case 0xa0:

		switch(r)

		{

		case 0xbd:

			/* amsep,vibdep,r,bd,sd,tom,tc,hh */

			{

			UINT8 rkey = OPL->rythm^v;

			OPL->ams_table = &AMS_TABLE[v&0x80 ? AMS_ENT : 0];

			OPL->vib_table = &VIB_TABLE[v&0x40 ? VIB_ENT : 0];

			OPL->rythm  = v&0x3f;

			if(OPL->rythm&0x20)

			{

#if 0

				usrintf_showmessage("OPL Rythm mode select");

#endif

				/* BD key on/off */

				if(rkey&0x10)

				{

					if(v&0x10)

					{

						OPL->P_CH[6].op1_out[0] = OPL->P_CH[6].op1_out[1] = 0;

						OPL_KEYON(&OPL->P_CH[6].SLOT[SLOT1]);

						OPL_KEYON(&OPL->P_CH[6].SLOT[SLOT2]);

					}

					else

					{

						OPL_KEYOFF(&OPL->P_CH[6].SLOT[SLOT1]);

						OPL_KEYOFF(&OPL->P_CH[6].SLOT[SLOT2]);

					}

				}

				/* SD key on/off */

				if(rkey&0x08)

				{

					if(v&0x08) OPL_KEYON(&OPL->P_CH[7].SLOT[SLOT2]);

					else       OPL_KEYOFF(&OPL->P_CH[7].SLOT[SLOT2]);

				}/* TAM key on/off */

				if(rkey&0x04)

				{

					if(v&0x04) OPL_KEYON(&OPL->P_CH[8].SLOT[SLOT1]);

					else       OPL_KEYOFF(&OPL->P_CH[8].SLOT[SLOT1]);

				}

				/* TOP-CY key on/off */

				if(rkey&0x02)

				{

					if(v&0x02) OPL_KEYON(&OPL->P_CH[8].SLOT[SLOT2]);

					else       OPL_KEYOFF(&OPL->P_CH[8].SLOT[SLOT2]);

				}

				/* HH key on/off */

				if(rkey&0x01)

				{

					if(v&0x01) OPL_KEYON(&OPL->P_CH[7].SLOT[SLOT1]);

					else       OPL_KEYOFF(&OPL->P_CH[7].SLOT[SLOT1]);

				}

			}

			}

			return;

		}

		/* keyon,block,fnum */

		if( (r&0x0f) > 8) return;

		CH = &OPL->P_CH[r&0x0f];

		if(!(r&0x10))

		{	/* a0-a8 */

			block_fnum  = (CH->block_fnum&0x1f00) | v;

		}

		else

		{	/* b0-b8 */

			int keyon = (v>>5)&1;

			block_fnum = ((v&0x1f)<<8) | (CH->block_fnum&0xff);

			if(CH->keyon != keyon)

			{

				if( (CH->keyon=keyon) )

				{

					CH->op1_out[0] = CH->op1_out[1] = 0;

					OPL_KEYON(&CH->SLOT[SLOT1]);

					OPL_KEYON(&CH->SLOT[SLOT2]);

				}

				else

				{

					OPL_KEYOFF(&CH->SLOT[SLOT1]);

					OPL_KEYOFF(&CH->SLOT[SLOT2]);

				}

			}

		}

		/* update */

		if(CH->block_fnum != block_fnum)

		{

			int blockRv = 7-(block_fnum>>10);

			int fnum   = block_fnum&0x3ff;

			CH->block_fnum = block_fnum;



			CH->ksl_base = KSL_TABLE[block_fnum>>6];

			CH->fc = OPL->FN_TABLE[fnum]>>blockRv;

			CH->kcode = CH->block_fnum>>9;

			if( (OPL->mode&0x40) && CH->block_fnum&0x100) CH->kcode |=1;

			CALC_FCSLOT(CH,&CH->SLOT[SLOT1]);

			CALC_FCSLOT(CH,&CH->SLOT[SLOT2]);

		}

		return;

	case 0xc0:

		/* FB,C */

		if( (r&0x0f) > 8) return;

		CH = &OPL->P_CH[r&0x0f];

		{

		int feedback = (v>>1)&7;

		CH->FB   = feedback ? (8+1) - feedback : 0;

		CH->CON = v&1;

		set_algorythm(CH);

		}

		return;

	case 0xe0: /* wave type */

		slot = slot_array[r&0x1f];

		if(slot == -1) return;

		CH = &OPL->P_CH[slot/2];

		if(OPL->wavesel)

		{

			/* LOG(LOG_INF,("OPL SLOT %d wave select %d\n",slot,v&3)); */

			CH->SLOT[slot&1].wavetable = &SIN_TABLE[(v&0x03)*SIN_ENT];

		}

		return;

	}

}

static int qemu_rbd_set_conf(rados_t cluster, const char *conf,

                             bool only_read_conf_file,

                             Error **errp)

{

    char *p, *buf;

    char *name;

    char *value;

    Error *local_err = NULL;

    int ret = 0;



    buf = g_strdup(conf);

    p = buf;



    while (p) {

        name = qemu_rbd_next_tok(RBD_MAX_CONF_NAME_SIZE, p,

                                 '=', "conf option name", &p, &local_err);

        if (local_err) {

            break;

        }

        qemu_rbd_unescape(name);



        if (!p) {

            error_setg(errp, "conf option %s has no value", name);

            ret = -EINVAL;

            break;

        }



        value = qemu_rbd_next_tok(RBD_MAX_CONF_VAL_SIZE, p,

                                  ':', "conf option value", &p, &local_err);

        if (local_err) {

            break;

        }

        qemu_rbd_unescape(value);



        if (strcmp(name, "conf") == 0) {

            /* read the conf file alone, so it doesn't override more

               specific settings for a particular device */

            if (only_read_conf_file) {

                ret = rados_conf_read_file(cluster, value);

                if (ret < 0) {

                    error_setg_errno(errp, -ret, "error reading conf file %s",

                                     value);

                    break;

                }

            }

        } else if (strcmp(name, "id") == 0) {

            /* ignore, this is parsed by qemu_rbd_parse_clientname() */

        } else if (!only_read_conf_file) {

            ret = rados_conf_set(cluster, name, value);

            if (ret < 0) {

                error_setg_errno(errp, -ret, "invalid conf option %s", name);

                ret = -EINVAL;

                break;

            }

        }

    }



    if (local_err) {

        error_propagate(errp, local_err);

        ret = -EINVAL;

    }

    g_free(buf);

    return ret;

}

