int ioinst_handle_tsch(S390CPU *cpu, uint64_t reg1, uint32_t ipb)

{

    CPUS390XState *env = &cpu->env;

    int cssid, ssid, schid, m;

    SubchDev *sch;

    IRB irb;

    uint64_t addr;

    int cc, irb_len;

    uint8_t ar;



    if (ioinst_disassemble_sch_ident(reg1, &m, &cssid, &ssid, &schid)) {

        program_interrupt(env, PGM_OPERAND, 2);

        return -EIO;

    }

    trace_ioinst_sch_id("tsch", cssid, ssid, schid);

    addr = decode_basedisp_s(env, ipb, &ar);

    if (addr & 3) {

        program_interrupt(env, PGM_SPECIFICATION, 2);

        return -EIO;

    }



    sch = css_find_subch(m, cssid, ssid, schid);

    if (sch && css_subch_visible(sch)) {

        cc = css_do_tsch_get_irb(sch, &irb, &irb_len);

    } else {

        cc = 3;

    }

    /* 0 - status pending, 1 - not status pending, 3 - not operational */

    if (cc != 3) {

        if (s390_cpu_virt_mem_write(cpu, addr, ar, &irb, irb_len) != 0) {

            return -EFAULT;

        }

        css_do_tsch_update_subch(sch);

    } else {

        irb_len = sizeof(irb) - sizeof(irb.emw);

        /* Access exceptions have a higher priority than cc3 */

        if (s390_cpu_virt_mem_check_write(cpu, addr, ar, irb_len) != 0) {

            return -EFAULT;

        }

    }



    setcc(cpu, cc);

    return 0;

}

static ssize_t v9fs_synth_pwritev(FsContext *ctx, V9fsFidOpenState *fs,

                                  const struct iovec *iov,

                                  int iovcnt, off_t offset)

{

    int i, count = 0, wcount;

    V9fsSynthOpenState *synth_open = fs->private;

    V9fsSynthNode *node = synth_open->node;

    if (!node->attr->write) {

        errno = EPERM;

        return -1;

    }

    for (i = 0; i < iovcnt; i++) {

        wcount = node->attr->write(iov[i].iov_base, iov[i].iov_len,

                                   offset, node->private);

        offset += wcount;

        count  += wcount;

        /* If we wrote less than requested. we are done */

        if (wcount < iov[i].iov_len) {

            break;

        }

    }

    return count;

}

static void piix4_device_unplug_request_cb(HotplugHandler *hotplug_dev,

                                           DeviceState *dev, Error **errp)

{

    PIIX4PMState *s = PIIX4_PM(hotplug_dev);



    if (s->acpi_memory_hotplug.is_enabled &&

        object_dynamic_cast(OBJECT(dev), TYPE_PC_DIMM)) {

        acpi_memory_unplug_request_cb(hotplug_dev, &s->acpi_memory_hotplug,

                                      dev, errp);

    } else if (object_dynamic_cast(OBJECT(dev), TYPE_PCI_DEVICE)) {

        acpi_pcihp_device_unplug_cb(hotplug_dev, &s->acpi_pci_hotplug, dev,

                                    errp);

    } else if (object_dynamic_cast(OBJECT(dev), TYPE_CPU) &&

               !s->cpu_hotplug_legacy) {

        acpi_cpu_unplug_request_cb(hotplug_dev, &s->cpuhp_state, dev, errp);

    } else {

        error_setg(errp, "acpi: device unplug request for not supported device"

                   " type: %s", object_get_typename(OBJECT(dev)));

    }

}

static void ohci_td_pkt(const char *msg, const uint8_t *buf, size_t len)

{

    bool print16 = !!trace_event_get_state(TRACE_USB_OHCI_TD_PKT_SHORT);

    bool printall = !!trace_event_get_state(TRACE_USB_OHCI_TD_PKT_FULL);

    const int width = 16;

    int i;

    char tmp[3 * width + 1];

    char *p = tmp;



    if (!printall && !print16) {

        return;

    }



    for (i = 0; ; i++) {

        if (i && (!(i % width) || (i == len))) {

            if (!printall) {

                trace_usb_ohci_td_pkt_short(msg, tmp);

                break;

            }

            trace_usb_ohci_td_pkt_full(msg, tmp);

            p = tmp;

            *p = 0;

        }

        if (i == len) {

            break;

        }



        p += sprintf(p, " %.2x", buf[i]);

    }

}

int do_subchannel_work_virtual(SubchDev *sch)

{



    SCSW *s = &sch->curr_status.scsw;



    if (s->ctrl & SCSW_FCTL_CLEAR_FUNC) {

        sch_handle_clear_func(sch);

    } else if (s->ctrl & SCSW_FCTL_HALT_FUNC) {

        sch_handle_halt_func(sch);

    } else if (s->ctrl & SCSW_FCTL_START_FUNC) {

        /* Triggered by both ssch and rsch. */

        sch_handle_start_func_virtual(sch);

    } else {

        /* Cannot happen. */

        return 0;

    }

    css_inject_io_interrupt(sch);

    return 0;

}

static inline uint64_t ldq_phys_internal(target_phys_addr_t addr,

                                         enum device_endian endian)

{

    uint8_t *ptr;

    uint64_t val;

    MemoryRegionSection *section;



    section = phys_page_find(address_space_memory.dispatch, addr >> TARGET_PAGE_BITS);



    if (!(memory_region_is_ram(section->mr) ||

          memory_region_is_romd(section->mr))) {

        /* I/O case */

        addr = memory_region_section_addr(section, addr);



        /* XXX This is broken when device endian != cpu endian.

               Fix and add "endian" variable check */

#ifdef TARGET_WORDS_BIGENDIAN

        val = io_mem_read(section->mr, addr, 4) << 32;

        val |= io_mem_read(section->mr, addr + 4, 4);

#else

        val = io_mem_read(section->mr, addr, 4);

        val |= io_mem_read(section->mr, addr + 4, 4) << 32;

#endif

    } else {

        /* RAM case */

        ptr = qemu_get_ram_ptr((memory_region_get_ram_addr(section->mr)

                                & TARGET_PAGE_MASK)

                               + memory_region_section_addr(section, addr));

        switch (endian) {

        case DEVICE_LITTLE_ENDIAN:

            val = ldq_le_p(ptr);

            break;

        case DEVICE_BIG_ENDIAN:

            val = ldq_be_p(ptr);

            break;

        default:

            val = ldq_p(ptr);

            break;

        }

    }

    return val;

}

